// Per-locale documentation translations. GENERATED by scripts/i18n-docs-translate.mjs.
// Shape: { [locale]: { [blockKey]: translatedText } }. English is the source of truth in content/*.ts.

export const DOC_TRANSLATIONS: Record<string, Record<string, string>> = {"zh-CN":{"start.for-non-coders#6#li3":"当你希望她真正去创建或修改内容时，直接告诉她就好——她总会先展示即将执行的操作，并等待你的“确认”。","start.for-non-coders#7#c":"遇到不认识的单词？本章节下方的“通俗术语表”会解释每一个术语，无需任何前置知识。","start.install#title":"安装","start.install#0#p":"选择最适合你工作习惯的界面。你可以使用多个界面——登录时，Ava 会在它们之间同步记忆。","start.install#1#h":"VS Code 扩展","start.install#2#li0":"在 VS Code 中打开扩展面板（Ctrl+Shift+X / Cmd+Shift+X）。","start.install#2#li1":"搜索“Ava Supernova”并点击安装。","start.install#2#li2":"按 Ctrl+Shift+A（macOS 上是 Cmd+Shift+A）打开聊天面板。","start.install#2#li3":"跟随设置向导操作——选择一个模型，设定权限模式，完成。","start.install#3#h":"桌面 IDE","start.install#4#li0":"从发布页面下载适用于你平台的安装程序。","start.install#4#li1":"运行它。首次运行时，IDE 会启动欢迎流程。","start.install#4#li2":"登录获取免费平台额度，或者粘贴你自己的 API 密钥以完全本地运行。","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli（或 pnpm / yarn —— 由你决定）。","start.install#6#li1":"在任何项目目录中运行 ava。","start.install#6#li2":"首次运行时会提示你选择提供商和模型。选好即可开始。","start.install#7#c":"没有账户也没关系。使用你自己的 API 密钥（BYOK），你无需登录。免费层仅用于平台托管的模型。","concepts.memory#1#p":"Ava 拥有持久记忆（“持久”意味着即使你关闭应用，它也会保留）。它在对话、项目和设备之间都能留存，如果你开启同步（同步会在你的设备间复制记忆）。它不是聊天日志。它是对你是谁、你喜欢什么以及你做过什么决定的结构化、可搜索的理解。","concepts.memory#2#h":"五个层级","concepts.memory#3#li0":"提取 — 实时捕获每条消息中的关键事实。","concepts.memory#3#li1":"反思 — 在有意义的会话结束时进行更深入的分析。模式、主题、矛盾点。","concepts.memory#3#li2":"积累 — 修正和偏好随数周数月不断累积。","concepts.memory#3#li3":"分析 — 图引擎关联相关记忆，当新信息与旧信息冲突时标记矛盾。","concepts.memory#3#li4":"整合 — 相似记忆合并；过时记忆修剪。记忆随时间变得更精准，而非更嘈杂。","concepts.memory#4#c":"上述五个层级自动运行 —— 你无需管理它们。它们的存在是为了让你看到记忆真正随时间改善，而不是变成一堆杂乱无章的信息。","concepts.memory#5#h":"检索","concepts.memory#6#p":"当你提问时，Ava 通过含义搜索记忆（“语义搜索”——它理解你的意图，所以即使措辞不同也能找到正确的记忆），而不仅仅是匹配确切单词。模式特定过滤器同时运行 —— 聊天模式调用个人上下文，工作模式调用项目决策和代码模式。","concepts.memory#7#c":"记忆按用户和项目范围限定（你的记忆归你所有，按人和项目分开保存）。机密信息和凭据（密码、密钥）在保存边界被拦截 —— 它们永远无法进入记忆。","start.for-non-coders#title":"从未写过代码？从这里开始","start.for-non-coders#0#p":"如果你从未写过一行代码，那你正是 Ava 想帮助的对象。开始不需要学习任何专业术语 —— 像跟懂行的朋友聊天一样，用日常语言跟她交流就行。这一页就是你完整的入门指南。","start.for-non-coders#1#h":"今天就能做的事，无需经验","start.for-non-coders#2#li0":"用日常语言问她任何问题 —— “这个文件是做什么的？”、“为什么我的页面是空的？”、“数据库到底是什么？”她会用大白话回答，并且记住你们的对话。","start.for-non-coders#2#li1":"从零开始学习新技能 —— 说“从零教我 Python”，她会为你搭建一套包含课程和测验的系统教程。这永远是免费的。","start.for-non-coders#2#li2":"动手做出点东西 —— 描述你的需求（比如“一个能下载我笔记的按钮”），她会写好代码，并在执行前向你展示每一个改动。","start.for-non-coders#3#h":"你不必什么都懂","start.for-non-coders#4#p":"Ava 背后有很多底层机制 —— 模式、模型、专家模块、路由等。你可能会在应用中或文档里看到这些词。秘诀是：你几乎可以忽略它们。Ava 会自动为你挑选合适的工具和帮手。那些技术页面，是为了等你好奇时再看，而不是为了让你开始就必须懂。","start.for-non-coders#5#h":"温和的第一步","start.for-non-coders#6#li0":"安装 Ava（下一页）并打开聊天。","start.for-non-coders#6#li1":"输入你真正的问题。任何事。看看她怎么回答。","start.for-non-coders#6#li2":"试试学习模式：输入“教教我”和一个主题。跟着做。","concepts.memory#title":"记忆 —— Ava 如何记住您","concepts.memory#0#p":"简单来说：Ava 记得您。告诉她一件事——您喜欢什么，您做的决定——她会记住，这样您在下次聊天或下周就不用重复了。这就是核心要点。下面的内容只是解释她如何随着时间的推移保持记忆整洁。","reference.models#11#h":"自带密钥","reference.models#12#p":"“API 密钥”是一个私密密码，允许软件在您的账户上使用付费服务。“BYOK”仅意味着“自带密钥”——使用您自己的而非我们的。将您的 API 密钥粘贴到设置中。BYOK 请求直接从 Ava 流向提供商（运行模型的公司的）——它们不经过我们的基础设施，也不消耗平台令牌。您向提供商付费；我们看不到流量。","reference.models#14#c":"对于基准分数、能力标签和并排过滤，请查看 ava-supernova.com/models 上的完整模型页面。上方显示的价格是我们发布时对每个提供商费率表的最新解读——在承诺投入工作负载之前，请务必检查提供商网站。","reference.personas#title":"角色编排","reference.personas#0#p":"“角色”是 Ava 在幕后为处理更难的任务而扮演的助手角色——例如探索者、规划者或事实核查员。您无需直接与它们交谈，也不需要理解此页即可使用 Ava。这里是为了当您好奇她如何将大任务分解为小专家团队时提供说明。","reference.personas#1#p":"5 个模式团队共有 24 位专家。指挥者（负责协调其余部分的助手）决定哪个团队运行、以何种顺序以及使用何种上下文。聊天模式没有角色——它就是 Ava 本人。","reference.personas#2#h":"编排如何运行","reference.personas#3#li0":"您在“计划”、“教学”、“安全”或“头脑风暴”模式下发送消息（或复杂的作业请求）。","reference.personas#3#li1":"指挥者读取请求，选择模式团队，并构建执行计划——某些角色按顺序运行，某些以并行波次运行。","reference.personas#3#li2":"每个角色都有自己的系统提示词、受限的工具白名单，以及先前角色发现内容的共享上下文池。","reference.personas#3#li3":"最终角色根据模式生成摘要、计划或报告。","reference.personas#3#li4":"Ava 向您展示结果。您可以批准、调整或重定向。","reference.personas#4#p":"下面的完整名单仅供参考——无需记住谁做什么。Ava 会为您组建合适的团队。","reference.personas#6#c":"作业模式仅在复杂任务时调用整个团队。简单编辑直接由 Ava 运行——无编排开销。","concepts.desktop-grounding#title":"桌面定位层级（预览版）","concepts.desktop-grounding#0#c":"预览 —— 解释 Scout 每一步如何决定使用哪种定位源。","concepts.desktop-grounding#1#p":"在 Ava 点击按钮之前，她必须先真正理解屏幕上有什么、东西在哪里——这就是“定位”（弄清楚屏幕上每个元素是什么以及确切位置）。她有这三种方法，并会为你当前使用的 App 选择最可靠的一种。这是给高级用户的深层细节；核心点在于她偏好扎实准确的方法，而不是靠猜测图片。","concepts.desktop-grounding#2#p":"分为三层，按顺序评估。成本最低且可靠的方案胜出。","concepts.desktop-grounding#3#h":"1. 浏览器窗口 → Playwright DOM","concepts.desktop-grounding#4#p":"如果活动窗口是 Web 浏览器，Ava 会读取页面自身的结构（“DOM”——页面上元素的底层列表），而不是从图片中猜测。读取结构比肉眼观察像素可靠约 10×——她能精确知道每个按钮的位置，以及页面何时加载完成。这是 Web 上任何操作的主要路径，而非备用方案。","concepts.desktop-grounding#5#h":"2. 支持 UIA 的本地应用 → Windows UI Automation","concepts.desktop-grounding#6#p":"对于 Windows 上的普通桌面应用，Ava 会读取内置的可访问性映射（“UIA”，屏幕阅读器用来描述窗口的相同数据）——它列出每个控件、名称及其位置。如果该映射返回至少五个可用且有名称的元素，她就信任并使用它。","concepts.desktop-grounding#7#h":"3. UIA 为空或无效 → OmniParser 视觉","concepts.desktop-grounding#8#p":"当该映射缺失或无效时（某些应用、游戏和远程屏幕不提供），Ava 会回退到实际查看截图。视觉工具（OmniParser）识别可点击区域并标记每个区域的内容，将图片转回她可以操作的列表——同时结合可访问性映射提供的少量信息。","concepts.desktop-grounding#9#c":"OmniParser 在 Ava 首次需要时会要求授权，并提供清晰的隐私提示。BYOK 用户可以指定自己的本地 OmniParser 部署。","concepts.desktop-kill-switches#title":"桌面紧急停止开关（预览版）","concepts.desktop-kill-switches#0#c":"预览 —— 三种独立的中断运行轨迹的方式。任意一种都能生效。","concepts.desktop-kill-switches#1#p":"“紧急停止开关”顾名思义——当 Ava 控制你的屏幕时，立即停止它的紧急方式。令人安心的是：有三个，各自独立构建，所以如果一个失效，另一个依然有效。你不必学习全部三个。只需知道当情况看起来不对劲时，你随时可以停止它，而最强的停止方式（下方的恐慌停止）不依赖 Ava 的配合。","concepts.desktop-kill-switches#2#p":"在研究了所有公开的自主事故（AI 代理忽略停止命令、删除邮件存档、擦除驱动器的真实案例）后，我们在三个不同层级构建了三个紧急停止开关。它们都不依赖于 AI 模型本身——如果 Ava 卡住或无响应，你仍然可以停止她。","concepts.desktop-kill-switches#3#h":"暂停 —— 空格键或暂停按钮","concepts.desktop-kill-switches#4#p":"会在下一步的边界处暂停。可以恢复使用。当你想要介入干预，同时又不希望偏离当前轨迹时，请使用此功能。","concepts.desktop-kill-switches#5#h":"停止 — 按 Escape 键或点击停止按钮","concepts.desktop-kill-switches#6#p":"安全中止。叙述者会总结目前已完成的工作。无法恢复。审计日志会记录提交。","concepts.desktop-kill-switches#7#h":"紧急终止 — 连按三次 Escape 或 Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"这是最彻底的停止方式。它是一个独立的小程序（看门狗），会强制关闭正在控制你屏幕的 Ava 组件。它不会等待 AI 回应，也不需要应用窗口正常运行，不管系统处于什么状态——它直接切断进程。只有在情况真的不对劲时，才使用这个。","concepts.desktop-kill-switches#9#p":"这三种方式在配套应用中同样有效。任意驱动模式都能触发结束。","reference.tools#title":"工具参考手册","reference.tools#0#p":"这是 Ava 所有工具的完整清单——“工具”指的是她能执行的具体操作，比如读取文件或进行搜索。你不必阅读此页面。Ava 每次都会自动选择正确的工具。这里仅供你在好奇她具体能做什么时查阅。","reference.tools#1#p":"完整的内置工具箱。此处列出的每个工具都已注册在核心运行时（即支撑所有三种界面的底层引擎）中，只要模式及权限允许，Ava 即可调用。可按类别或风险等级进行筛选。","reference.tools#2#p":"无需记忆所有内容——下方的表格仅作为参考卡片。","reference.tools#4#h":"风险等级","reference.tools#5#li0":"安全级 —— 只读取内容而不做任何更改。包括 `file_read`、`glob`（按名称模式查找文件）、`grep`（在文件内搜索文本）、`git_status`（Git 是追踪项目变更的系统）。","reference.tools#5#li1":"写入级 —— 修改文件、保存工作检查点（即“提交”），或生成新内容。包括 `file_edit`、`git_commit`、`generate_image`。","reference.tools#5#li2":"危险级 —— 在电脑终端（“命令行”）运行指令、控制桌面、访问互联网或查询数据库。包括 `bash`、`browser`、`desktop_*`。","reference.tools#6#c":"不同角色的专家拥有各自独立的工具白名单。“侦察员”只能读取不能写入；“构建者”拥有完全访问权限；“挑战者”则没有任何工具——它的职责是对计划提出质疑。","reference.models#title":"模型列表","reference.models#0#p":"“模型”就是负责思考的 AI 大脑——例如 Qwen、DeepSeek、Mistral 等。本页面列出了 Ava 可用的所有模型。简单来说：你无需手动选择。Ava 会为每一步自动挑选合适的模型。除非你想了解细节或手动覆盖，否则无需继续阅读。","reference.models#1#p":"包含 Ava 可调度的所有模型，以及三种编排策略——即决定由哪个模型处理任务各部分的规则。你可以选择一个路由模式，让 Ava 自动分发任务；或者指定单个模型，完全跳过路由。","reference.models#2#h":"路由模式","reference.models#3#p":"三种编排策略。相同的角色流水线（Ava 在幕后运行的小型专家团队）适用于所有三种模式；区别在于底层的模型阵容。在模型选择器中选定一种模式，Ava 会自动处理其余部分。下方的每张卡片展示了指挥者将任务路由给哪些具体的专家成员。","reference.models#4#p":"无需记忆下方的卡片——它们的存在是为了让你了解每种策略由哪些部分组成。","reference.models#6#c":"Aurora 特意限定为仅支持 Mistral。如果 Mistral 模型不可用，路由器会返回错误而非跨路由——这是欧盟栈的保证。如需优雅降级，请选择 Maestro 或 Supernova。","reference.models#7#c":"这三种模式均全面可用——无论是使用平台额度还是你自己的密钥。BYOK 提供了绕过编排、直接驱动单个模型的选项。","reference.models#8#h":"平台托管模型","reference.models#9#p":"所有套餐均可使用，包括免费版。令牌（AI 计量的文本单位，约等于四分之三个词）会计入你的套餐配额。密钥（解锁每个付费模型的私钥密码）由平台轮换和监控——无需你进行任何配置。","reference.config#title":"配置","reference.config#0#p":"此页面显示 Ava 在您的计算机上保存设置和文件的位置。您几乎不需要手动修改任何内容——应用程序会为您打理好一切。如果您想查看、备份或自行共享这些文件，这里会有帮助。","reference.config#1#p":"Ava 从两个范围读取配置（她保存的设置）。全局设置——适用于所有地方的设置——位于名为 ~/.ava/ 的文件夹中（\"~\" 是您的主文件夹的简写）。按项目设置的配置文件位于项目本身的 .ava/ 文件夹内。","reference.config#2#h":"全局 — ~/.ava/","reference.config#3#li0":"settings.json — 模型偏好、权限模式、性格、语言。","reference.config#3#li1":"memory/ — 您的全局记忆（适用于所有地方的偏好和决策）。","reference.config#3#li2":"tasks.json — 跨项目任务列表。","reference.config#3#li3":"journal/ — 每日日记条目，按日期组织。","reference.config#4#h":"项目 — .ava/","reference.config#5#li0":"instructions.md — Ava 始终加载的项目特定说明。持久上下文（“我们使用 pnpm，而不是 npm”，“API 密钥存储在 1Password 中”）。","reference.config#5#li1":"context.md — 可选的自由格式项目笔记。","reference.config#5#li2":"memory/ — 仅限此项目的记忆。","reference.config#5#li3":"datasets/config.json — 需主动开启的数据采集配置。","reference.config#6#c":"如果您不希望与团队共享记忆，请将 .ava/ 添加到您的 .gitignore（Git 被告知不要包含在共享项目中的文件列表）中。将 instructions.md 保留在仓库（共享项目文件夹）中——这就是 Ava 学习项目约定的方式。","reference.shortcuts#title":"键盘快捷键","reference.shortcuts#0#p":"键盘快捷键是可选的提速技巧——每一个都有对应的可点击按钮。仅当您想通过键盘更流畅地操控 Ava 时才查阅此处。","reference.shortcuts#1#p":"按运行界面分类的快捷键（Ava 运行的三个位置：VS Code 扩展、桌面应用和终端）。在每个界面的设置中自定义它们。无需记住下面的列表。","features.office-suite#title":"Office Suite","features.office-suite#0#p":"需要撰写报告、邮件或文档吗？Ava 可以为您起草，并提供真正的 Word、Excel 或 PDF 文件，您可以像处理普通文件一样打开和编辑。","features.office-suite#1#p":"报告、邮件和文档——经过起草、格式化，并导出为原生格式（.docx 对应 Word，.xlsx 对应 Excel，.pdf 对应 PDF）。","features.office-suite#2#li0":"report_generate —— 基于任务、日志、记忆和项目状态生成的结构化 .docx 文件。","features.office-suite#2#li1":"email_draft —— 控制语气的邮件，输出为 .docx 文件。","features.office-suite#2#li2":"document_manage —— 在 Word、Excel、PDF、CSV、Markdown 之间进行创建、读取、编辑和导出。","features.office-suite#3#p":"当 Ava 代您撰写内容时非常实用——例如状态报告、启动演示文稿或客户更新。.docx 文件会出现在您的项目中，方便您进一步润色。","features.dashboard-library#title":"仪表板库","features.dashboard-library#0#p":"简单来说：就像一个大书架，存放您和 Ava 共同创作和讨论的所有内容，确保一切井井有条，永不遗失。","features.dashboard-library#1#p":"提供可浏览的视图，展示 Ava 与您协作产生的所有内容——包括生成的图片、视频、音频、文档，以及您的对话、记忆和任务。只需一处，就能找回您上周制作的内容。","features.document-preview#title":"文档预览","features.document-preview#0#p":"简单来说：无需打开独立程序，直接在当前位置即可查看文档内容。","features.document-preview#1#p":"在项目文件夹中右键点击 Word 文档、Excel 表格、PDF、CSV、HTML 或 Markdown 文件——无需离开编辑器即可内联预览。非常适合阅读 Ava 生成的参考资料，或是协作者放入的文件。","features.daily-briefing#title":"每日简报","features.daily-briefing#0#p":"简单来说：每天早上一条简短的“昨日进度摘要”，让您无需重读所有内容即可快速接上工作。","features.daily-briefing#1#p":"晨间摘要：包含昨日的日志、待办任务、项目状态，以及 Ava 设置的任何提醒。此为可选功能——可在设置中开启。","features.daily-briefing#2#p":"简报利用记忆呈现相关上下文（例如：\"上次您处理认证流程时，曾提到想重新审视刷新令牌策略\"）。这不是新闻推送，而是帮助您专注跟进的摘要。","features.unified-panel#title":"统一面板","features.unified-panel#0#p":"简单来说：Ava 做的所有事情都在一个窗口中，所以你无需在标签页间查找。","features.unified-panel#1#p":"一个面板涵盖聊天、仪表板、记忆、任务和日记。无需在窗口间切换上下文。侧边栏选择你要看的内容；主区域随之匹配变化。","features.unified-panel#2#p":"离开后对话状态依然保留 —— 打开记忆，检查任务，然后回来。聊天依然存在，如果 Ava 仍在运行，流式传输也会继续。","features.unified-panel#3#c":"统一面板是扩展和 IDE 概念。Web 界面使用浏览器标签页。","features.knowledge-packs#title":"知识包","features.knowledge-packs#0#p":"简单来说：把你自己文档的文件夹交给 Ava，她可以从中阅读来回答你的问题。“知识包”就是那束文件 —— 她被允许参考的参考资料。","features.knowledge-packs#1#p":"将参考资料目录（规范、RFC、会议记录、API 文档）拖入知识包。当对话涉及该主题时，Ava 可以将相关内容拉入上下文中。","features.knowledge-packs#2#p":"包是本地索引的。检索是语义化的 —— Ava 通过含义而非文件名找到正确的文档。（“语义化”意味着她根据文档的主题进行匹配，所以你不需要记住确切的词语或文件名。）包可以与团队共享或保持私密。","troubleshooting.common-errors#title":"常见错误","troubleshooting.common-errors#0#p":"大多数错误都有简短、具体的原因。以下是常见问题及其解决方法。如果措辞听起来有些技术化，请不要担心——下面的每一项都会告诉你实际看到了什么，以及具体该怎么做。","troubleshooting.common-errors#1#h":"模型无响应","troubleshooting.common-errors#2#p":"你看到的情况：Ava 沉默了，没有回复。","troubleshooting.common-errors#3#p":"检查聊天标题栏中的状态指示器。如果显示“正在连接”，说明你的提供商（Ava 正在对话的 AI 服务）可达但较慢——给它三十秒时间。如果显示“不可用”，Ava 会自动回退到链中的下一个模型（她自动切换到了备用模型）。如果没有任何反应，请在设置中验证你的 API key 并测试连接。（API key 是允许 Ava 使用付费 AI 服务的私密密码。）","troubleshooting.common-errors#4#h":"工具调用失败","troubleshooting.common-errors#5#p":"你看到的情况：Ava 的某一步骤（一个“工具调用”——比如读取文件、运行命令等）显示红色错误，而不是完成。","troubleshooting.common-errors#6#p":"点击失败的“工具调用”查看错误。常见原因：她试图访问项目文件夹外的文件，这是出于安全目的故意阻止的（这种保护称为“路径遍历”防护——防止她走出你正在工作的文件夹）；或者需要在不同文件夹中运行的命令；或者是自从 Ava 上次查看后文件被移动了。告诉她哪里出错了——她会修正后重试。","troubleshooting.common-errors#7#h":"记忆未找回","troubleshooting.common-errors#8#p":"你看到的情况：Ava 找不到一些你确信她应该记得的内容。","troubleshooting.common-errors#9#p":"记忆基于含义而非精确字词工作（这就是“语义”的意思）。所以“我对认证做了什么决定？”比“查找我的认证决定”更有效。如果记忆确实存在但没有浮现，请打开记忆浏览器进行搜索——如果那里没有，说明它从未被保存过。","troubleshooting.common-errors#10#h":"登录循环","troubleshooting.common-errors#11#p":"你看到的情况：你已登录，但 Ava 不断要求你再次登录——这是一个无法通过的循环。","troubleshooting.common-errors#12#p":"解决方法是清除保存的登录信息并重新开始：在扩展中从命令面板运行“Ava: Sign Out”，在 IDE 中使用设置 → 账户 → 注销，在 CLI 中删除文件 ~/.ava/auth.json（位于主目录名为 .ava 的文件夹中的小型登录文件）。然后重新登录。","troubleshooting.common-errors#13#h":"令牌耗尽","troubleshooting.common-errors#14#p":"你看到的情况：一条消息提示本月免费额度已用完。（“令牌”是衡量 AI 使用量的方式——“耗尽”仅意味着你用完了本月的免费额度。）","troubleshooting.common-errors#15#p":"免费版月度预算每月 1 日重置。在此之前，切换到 BYOK 提供商（使用你自己的 API key）以继续工作。你的账户保持活跃——仅暂停免费的平台托管请求。","troubleshooting.logs#title":"日志位置","troubleshooting.logs#0#p":"“日志”只是电脑记录发生事情的日记——当出现问题且你需要（或支持人员需要）查看详情时很有用。","troubleshooting.logs#1#p":"当你需要原始画面——调用了什么工具、获取了什么信息、AI 服务返回了什么——日志是你电脑上 ~/.ava/logs/ 文件夹中的纯文本文件（主目录下的 .ava 文件夹，里面有一个 logs 文件夹）。","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — 每次会话的转录，包括工具调用、流式响应和错误。","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — VS Code 扩展主机日志。激活失败、面板错误。","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — 桌面 IDE 日志。Sidecar 进程消息、Rust 崩溃。","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — CLI REPL 日志。","troubleshooting.logs#3#p":"在扩展中，命令面板中的“Ava: Show Logs”会在编辑器标签页中打开相关日志。在 IDE 中，设置 → 诊断有个“打开日志”按钮。CLI 可以通过 `ava logs --follow` 跟踪其自身日志。","troubleshooting.logs#4#c":"日志中可能包含 Ava 在会话期间读取的项目文件片段。分享前请先检查。","troubleshooting.support-request#title":"提交支持请求","troubleshooting.support-request#0#p":"简单来说：如果遇到问题且上述方法没解决，请给我们留言。最简单的方式是直接让 Ava 帮你处理。","troubleshooting.support-request#1#p":"如果问题不在常见错误列表中，请提交支持工单（即向支持团队求助）。你可以直接在 Ava 内操作（无需填表），也可以通过网页进行。","troubleshooting.support-request#2#h":"在 Ava 应用中","troubleshooting.support-request#3#p":"请她来提交。说：\"Ava，能帮我提交个支持工单吗？\" 她会调用 support_request，附上相关的会话上下文（已隐藏敏感信息），然后发送。这是最快的方式。","troubleshooting.support-request#4#h":"通过网页端","troubleshooting.support-request#5#p":"访问 ava-supernova.com/support。选择一个类别（缺陷、功能、账户、安全、通用）并描述情况。我们将在一个工作日内回复。","troubleshooting.support-request#6#h":"请提供哪些信息","troubleshooting.support-request#7#li0":"你原本想做什么。","troubleshooting.support-request#7#li1":"实际发生了什么。","troubleshooting.support-request#7#li2":"使用的环境（扩展、IDE、CLI、配套应用）及具体版本。","troubleshooting.support-request#7#li3":"任何错误消息或日志片段。请先隐藏敏感凭证。","troubleshooting.security-disclosure#title":"报告安全漏洞","troubleshooting.security-disclosure#0#p":"简单来说：如果你发现 Ava 可能存在被入侵或滥用的风险（即“漏洞”——安全弱点），请先私下告知我们，这样我们能在他人利用之前修复它。本页就是操作方法。","troubleshooting.security-disclosure#1#p":"发现漏洞了吗？谢谢你。我们重视每一份报告，会在公开披露前与你协作修复（即在问题公之于众之前）。","troubleshooting.security-disclosure#2#h":"如何报告","troubleshooting.security-disclosure#3#li0":"发送邮件至 security@ava-supernova.com，包含描述、复现步骤以及你希望的披露时间窗口。","troubleshooting.security-disclosure#3#li1":"或者提交类别为“安全”的支持工单——进入相同的处理队列。","troubleshooting.security-disclosure#3#li2":"我们会在 24 小时内确认收到。","troubleshooting.security-disclosure#4#h":"我们的承诺","troubleshooting.security-disclosure#5#li0":"协调披露——在公开前我们会与你商定时间表。默认期限为 90 天。","troubleshooting.security-disclosure#5#li1":"署名致谢——除非你希望匿名，否则我们将在修复说明中为你署名。","troubleshooting.security-disclosure#5#li2":"无法律追责——欢迎善意研究。我们绝不会因为此事起诉你。","troubleshooting.security-disclosure#6#c":"ava-supernova.com/security 上的安全页面包含了完整的安全策略——架构保障、数据脱敏、权限控制等。","reference.project-context#title":"项目上下文","reference.project-context#0#p":"这里说明 Ava 在开工前如何了解你的项目——她会查阅哪些文件来理解你的工作内容。你无需手动配置任何内容，她会自动完成。如果你希望放置一些笔记让她随时能看到，可以参考这里了解应该放在哪里。","reference.project-context#1#p":"当你打开一个项目时，Ava 会加载多个层级的上下文（她脑海中持有的背景信息）。了解这些层级有助于你将信息放在合适的位置。","reference.project-context#2#h":"自动加载","reference.project-context#3#li0":".ava/instructions.md —— 被视为持久、高优先级的指导。始终包含在上下文中。","reference.project-context#3#li1":".ava/context.md —— 自由格式的笔记。会被加载，但优先级较低。","reference.project-context#3#li2":"README.md —— 首次运行时扫描，用于获取项目摘要。","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml —— 列出项目配置的小文件；读取它们以检测语言、框架和测试命令。","reference.project-context#3#li4":".gitignore —— 版本控制中要排除的文件列表；所有文件工具（glob, grep, project_index）都会尊重此规则。","reference.project-context#4#h":"按需加载","reference.project-context#5#p":"“按需”意味着 Ava 仅在任务真正需要时才获取这些信息，而不是提前全部加载。","reference.project-context#6#li0":"项目索引 —— 你文件的结构化地图，包括其中的命名部分（函数、类 —— “符号”）以及它们如何连接（“导入”）。采用惰性构建，即仅在 Ava 需要时才生成。","reference.project-context#6#li1":"Git 历史 —— 过去变更的记录；当调用 git_status、git_diff 或 git_create_pr 时拉取（Git 是追踪项目所有变更的工具；“拉取请求”是提议的一组变更）。","reference.project-context#6#li2":"记忆 —— 条目按含义（“语义上”）匹配，并逐次注入，而非一次性全部注入。","reference.project-context#7#c":"将规范放入 instructions.md。将笔记放入 context.md。让记忆自行捕捉其余内容。","features.workflows#title":"工作流程","features.workflows#0#p":"简单来说：教 Ava 一个你反复执行的例行任务，给它起个名字，她就能按需重复整个流程。所谓“工作流”，就是保存下来的这个例行任务——一套 Ava 为你重复执行的步骤。","features.workflows#1#p":"保存一组你发现自己会重复执行的步骤 —— 审查拉取请求 → 运行测试 → 编写发布说明 → 起草邮件。工作流就是一个可复用的计划，Ava 可以用不同的输入重新执行它。","features.workflows#2#p":"工作流按项目存储在你的项目文件夹 .ava/workflows/ 中。通过提交该目录（将其保存到共享项目中）与团队成员共享，这样队友也能获取到。","features.events#title":"事件与通知","features.events#0#p":"简单来说：当 Ava 工作时，你会看到一个整洁的步骤列表，显示她在做什么；长任务完成后会有提示，让你可以暂时离开。","features.events#1#p":"Ava 运行时，你看到的是结构化的更新，而不是一堆文字。每一次工具调用、每一个角色交接、每一段流式传输的增量，都是 UI 中的一个独立事件 —— 可展开查看详情，也可折叠查看概览。","features.events#2#p":"后台运行在完成时会发出操作系统级别的通知。你可以离开去处理其他事情，等长构建完成后，Ava 会告诉你。","features.personality#title":"性格设定","features.personality#0#p":"简单来说：调节 Ava 与你交谈的方式 —— 是健谈还是简洁，正式还是随意，多讲笑话还是少讲 —— 让她听起来符合你的喜好。","features.personality#1#p":"塑造 Ava 与你交谈的风格。语气、能量、说话多少（表达详略）、正式度、幽默感。滑块和预设选项 —— 干练工程师、温暖导师、冷静同事，或者你自己的混合风格。","features.personality#2#p":"性格只影响措辞，不影响能力。她仍然使用相同的工具并遵循相同的权限规则。她的名字固定为 Ava —— 这一点不可更改。","features.release-notes#title":"发布说明","features.release-notes#0#p":"简单来说：每次更新中新功能和修复内容的持续清单，让你清楚看到了什么变化。","features.release-notes#1#p":"应用内变更日志（变更日志即变化的历史记录）。每个已发布的版本都包含亮点、错误修复和破坏性变更（可能需要你调整使用方式的变更）。网页端在 ava-supernova.com/releases 维护公开版本。","start.what#title":"Ava 是什么？","start.what#0#p":"Ava 是一位真正会做事的 AI —— 不只是聊天。她会帮你构建应用、撰写文档、从零教你新知识、设计 Logo，或者处理那些你一直拖延的杂务。而且她记得你：你在做什么、你喜欢什么风格、上周你问了什么。","start.what#1#p":"只有一个 Ava，她在你的任何工作场所都能协作 —— 在你的代码编辑器里、作为桌面应用、在手机上，或者在终端中。记忆相同，性格相同，无处不在。","start.what#2#h":"她的独特之处","start.what#3#li0":"默认归你所有。你的工作始终保留在你自己的设备上。无追踪，无遥测——永远如此。","start.what#3#li1":"对任何人可见。Ava 的每一行代码都是公开的。无需盲目信任。","start.what#3#li2":"起步免费。每月 300 积分，无需信用卡，没有隐藏条款——或者接入你自己的 AI 密钥，完全不用付钱给我们。","start.what#3#li3":"教学永远免费。学习不该有价签。","start.what#4#p":"从未写过代码？下一页是专门为你写的。已经懂技术了？直接跳过——她能跟上你的节奏。","start.what#deeper#0#h":"Ava 在哪里","start.what#deeper#1#li0":"VS Code 扩展 —— Ava 就在你的编辑器旁边：一个聊天面板、一个仪表盘，以及行动前内联展示变更。","start.what#deeper#1#li1":"桌面 IDE —— 一个独立应用，所有内容在一个窗口中。增加桌面控制权（打开应用、点击、替你打字）。","start.what#deeper#1#li2":"伴侣 —— 一款移动应用，适合你离开办公桌时使用：任务、日记、记忆、快速聊天。","start.what#deeper#1#li3":"CLI —— 终端里的 Ava，专为常驻终端的人准备。","start.what#deeper#2#h":"工作原理简述","start.what#deeper#3#p":"Ava 会根据任务切换思维模式（称为模式），在复杂工作中悄悄运行一小队专家助手，并自动为每一步选择最佳的 AI 模型。你无需管理任何内容。当你好奇时，“核心概念”部分有完整介绍。","start.first-five#title":"与 Ava 的第一件事","start.first-five#0#p":"最快上手 Ava 的方式，就是让她做点实事，然后看着她操作。不需要阅读设置说明，也不需要先学什么——直接用大白话告诉她你想要什么。","start.first-five#1#h":"现在就试试","start.first-five#2#li0":"打开聊天。","start.first-five#2#li1":"输入你真心想做的事。试试“解释这个项目是做什么的”，或者“添加一个清除表单的按钮”。","start.first-five#2#li2":"Ava 会展示她打算做什么 —— 然后等待。","start.first-five#2#li3":"满意吗？说“是”。看着她完成。","start.first-five#3#p":"这就是整个节奏：你提问，她展示计划，你批准，她执行。她从不未经展示就修改任何东西——这样你就不会因尝试而搞砸。","start.first-five#4#h":"值得问的几个事","models.routing#deeper#2#td5.0":"对话","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"图像生成编排","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"视觉","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5（从头训练的视觉编码器）","models.routing#deeper#2#td8.0":"长文写作","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"数据驻留","models.routing#deeper#2#td9.1":"混合（阿里云）","models.routing#deeper#2#td9.2":"混合（DeepSeek + 阿里云）","models.routing#deeper#2#td9.3":"仅限欧盟 · 开放权重","models.routing#deeper#2#td10.0":"状态","models.routing#deeper#2#td10.1":"已上线 · 所有计划","models.routing#deeper#2#td10.2":"即将推出","models.routing#deeper#2#td10.3":"即将推出","models.routing#deeper#2#td11.0":"最适合","models.routing#deeper#1#h":"并排展示","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"协调中枢","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro（1.6T / 49B 激活，1M 上下文）","models.routing#deeper#2#td0.3":"Mistral Large 3（675B / 41B 激活，262K 上下文）","models.routing#deeper#2#td1.0":"构建助手","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus（复用协调中枢）","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5（128B 稠密，256K 上下文）","models.routing#deeper#2#td2.0":"中级专家","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash（代码审查、事实核查、信息调研、扫描检测、安全校验等）","models.routing#deeper#2#td2.3":"Mistral Medium 3.5（架构设计、核验确认、流程编排、指导教学、报告汇总等）","models.routing#deeper#2#td3.0":"轻量级 / 意图筛选","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash（侦察探索、核验确认、流程编排、质疑挑战、整合融合）","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"重量级专家","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3（研究分析、质疑挑战、CVE 研究员、创意构思、事实核查）","start.first-five#5#li0":"一个问题 —— “为什么我的页面是空的？”，“这个文件是做什么的？”","start.first-five#5#li1":"构建点什么 —— “给我做一个简单的待办事项页面”。","start.first-five#5#li2":"学习点东西 —— “从零开始教我 Python”。（完全免费。）","start.first-five#5#li3":"一份文档 —— “帮我写一份一页纸的项目提案”。她会给你 Word 文件或 PDF。","start.first-five#6#c":"不知道说什么？像对待一位博学的朋友那样跟她聊天。大白话就刚刚好——你不需要懂技术术语就能上手。","start.first-five#deeper#0#p":"那个简单的循环背后其实做了不少事。使用 Ava 并不需要了解这些——但如果你好奇，这里就是实际发生的情况。","start.first-five#deeper#1#h":"工具与授权","start.first-five#deeper#2#p":"当 Ava 读取文件、运行命令或编辑代码时，每一次都算作一次“工具调用”。在触及你的文件或系统之前，她都会先询问——她询问的频率由你的权限模式决定（每次都问、只问有风险的操作，或者直接执行）。","start.first-five#deeper#3#h":"模式 —— 她的心境","start.first-five#deeper#4#p":"Ava 通过模式工作：一种思维模式加上适合任务的工具包。随时可以从选择器切换，或者在消息开头输入前缀。一共有七种。","start.first-five#deeper#6#h":"专家与路由","start.first-five#deeper#7#p":"处理复杂任务时，Ava 会在后台运行一个小型专家团队（规划者、检查者、构建者），并将每一步路由给最擅长的模型。你无需管理任何内容——都由她为你协调。","start.local-vs-cloud#title":"本地与云端，一段话说清","start.local-vs-cloud#0#p":"除非你明确同意，否则 Ava 做的所有事情都在本地完成。记忆、任务、日志、个性、设置——全部存储在你的机器上，位于 ~/.ava/ 和 .ava/（按项目）。她通过 HTTPS 联系模型提供商来运行你的请求，然后回家。她不主动回传数据。不收集遥测数据。不会用你的代码进行训练。","start.local-vs-cloud#1#p":"如果登录，你可以在平台托管模型（Qwen, MiniMax）上获得每月 300 个免费额度，以及可选的云同步功能，用于跨设备同步记忆和设置。同步是按功能开启的，随时可撤销。自带 API 密钥，Ava 无需账户即可完全工作。","start.local-vs-cloud#2#c":"规则：本地至上。云端为辅。","start.first-model#title":"我需要选择 AI 吗？","start.first-model#0#p":"好消息：你不需要挑选 AI。Ava 会自动为每一步选择合适的模型，让你轻松获得好结果，无需操心。","start.first-model#1#p":"唯一你能选择的是路由风格——默认设置适合绝大多数人。只有特定原因才需要用到其他选项。","start.first-model#2#h":"三种风格","start.first-model#3#li0":"Maestro —— 默认选项。稳定、可靠、可预测。不确定？选这个准没错。","start.first-model#3#li1":"Supernova —— 用于繁重的多步骤工作，值得让不同专家负责不同部分。","start.first-model#3#li2":"Aurora —— 适用于数据必须留在欧盟的情况（公共部门、医疗、严格隐私）。完全在欧洲开源权重 AI 上运行。","start.first-model#4#p":"随时可以在聊天顶部的模型选择器中切换。没有任何锁定。","start.first-model#5#c":"想自己指定某个模型？可以——打开“显示详细信息”。","credits.overview#8#li4":"编排任务 — 10 积分。完整的人设流程启动（协调员 + 多角色任务）。","credits.overview#8#li5":"图像生成 — 12 积分。通过 Creative Studio 使用 Hailuo image-01。","credits.overview#8#li6":"视频生成 — 150 积分。Hailuo 02 Pro 1080p 6 秒片段。","credits.overview#8#li7":"语音生成 — 10 积分。Speech 2.8 HD 合成。","credits.overview#8#li8":"音乐生成 — 50 积分。MiniMax Music 2.5/2.6。","credits.overview#8#li9":"背景移除 — 2 积分。","credits.overview#9#h":"按模型计算的倍数","credits.overview#10#p":"这部分是给好奇的你看的 —— 使用 Ava 并不需要了解它。倍数只是根据动作背后的模型成本高低来调整积分消耗，模型越“重”，消耗的积分就越多。（“净收益”是项目在支付自身开销后保留的部分 —— 我们将其定得较低，以便价值更多地回馈给你。）","credits.overview#11#p":"较重模型的倍率会放大操作成本，让积分更真实地反映实际花费，而不是固定档位。校准目标约为 55% 的净收益。","credits.overview#12#li0":"0.6× — Mistral Small 4（Aurora 的专业席位）。低于 1×，因为 Mistral Small 4 比 Qwen 3.6 Plus 锚点更便宜。","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax。基础费率。","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus。","credits.overview#12#li3":"1.4× — Mistral Large 3（Aurora 协调员）。与 Qwen 3.6 Plus 锚点大致持平。","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus（Maestro 协调员）。","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro（Supernova 协调员 + 重型专家）。从 5.0× 重新校准，以在公布的 V4 Pro 费率下恢复利润率平衡。","credits.overview#13#c":"Anthropic 模型（Claude Opus / Sonnet / Haiku）完全跳过积分计费 —— 它们仅限 BYOK，你直接向 Anthropic 付费。其他任何 BYOK 提供商在使用你自己的密钥时也是如此。","credits.overview#14#h":"BYOK 与积分","credits.overview#15#p":"BYOK（“自带密钥”——你自己向 AI 提供商提供账户和密钥，这是一个私密密码，允许软件使用该付费账户）适用于已经直接向 AI 提供商付费的人。如果你不属于这种情况，完全可以忽略本节。","credits.overview#16#p":"自带密钥请求完全绕过平台基础设施 —— 调用直接从 Ava 发往提供商，你直接支付给提供商，不消耗积分。唯一的例外是当 BYOK 会话为子任务启动托管层级人设时；积分扣除仍然适用，因为使用了 Ava 的编排界面。","credits.overview#17#h":"查看余额的位置","credits.overview#18#li0":"扩展程序 — 设置 → 账户，或聊天标题栏中的积分胶囊。","credits.overview#18#li1":"IDE — 账户仪表板磁贴显示当前余额和消耗速率。","credits.overview#18#li2":"Web 端 — ava-supernova.com/dashboard 显示余额、历史记录和续订日期。","credits.overview#19#c":"本地优先：Ava 在自定义模型卡片上无需账户即可运行（Ollama, LM Studio, vLLM，或任何兼容 OpenAI 的端点）。无积分，无平台令牌 —— 你的模型，你的机器，零账单。","concepts.modes#title":"模式 —— Ava 的思维状态","start.first-model#deeper#0#h":"每种风格具体包含什么","start.first-model#deeper#1#p":"Maestro —— 一位指挥家（Qwen 3.6 Plus）负责每一步。专为生产环境打磨，经得起考验，成本清晰可算。","start.first-model#deeper#2#p":"Supernova —— 前沿协调员（DeepSeek V4 Pro，1.6T 参数 / 49B 激活，1M 上下文）将每个子任务交给专家：V4 Flash 用于大规模构建，Qwen 3.6 Plus 作为备选，Qwen Omni 用于视觉。","start.first-model#deeper#3#p":"Aurora —— 仅用 Mistral，分三层：Mistral Large 3（协调员 + 重型专家），Mistral Medium 3.5（128B 稠密，256K 上下文，原生视觉，修改版 MIT 开源权重，77.6% SWE-Bench 验证）用于构建者 + 中级 + 视觉 + 长文，以及 Mistral Small 4 在意图门槛。全程开源权重，数据绝不流出欧盟基础设施。","start.first-model#deeper#4#h":"自带模型 (BYOK)","start.first-model#deeper#5#p":"更想用自己的 AI 账号？在设置里粘贴你的服务商密钥，就能同时拥有这两样——三种路由风格，外加选单个模型并完全跳过路由的选项。适合有强烈偏好、预算严格或测试特定模型的情况。完整服务商列表见参考部分。","start.glossary#title":"通俗词汇表","start.glossary#0#p":"关于 Ava 你可能碰到的每个词，都按零基础水平解释。不用死记硬背——遇到任何术语看不懂时随时翻回来查。","start.glossary#1#th0":"词汇","start.glossary#1#th1":"实际含义","start.glossary#1#td0.0":"智能体","start.glossary#1#td0.1":"能替你干活的 AI —— 读文件、跑命令、搜网页 —— 而不只是陪聊。Ava 就是个智能体：她会动手做事，但得你先点头。","start.glossary#1#td1.0":"模型","start.glossary#1#td1.1":"真正负责思考的 AI 大脑（Qwen、DeepSeek、Mistral 等）。不同模型各有长处。通常你不用挑——让 Ava 决定。","start.glossary#1#td2.0":"模式","start.glossary#1#td2.1":"Ava 当下的心态。就像同事切换角色：构建者、写作者、教师、规划师、朋友。你选模式；这会改变她的行为方式。共七种。","start.glossary#1#td3.0":"角色 / 专家","start.glossary#1#td3.1":"Ava 在幕后为处理复杂任务而运行的辅助角色——探索者、规划师、事实核查员。想象一个小专家团队。你从不直接跟他们说话；由 Ava 来协调。","start.glossary#1#td4.0":"路由","start.glossary#1#td4.1":"Ava 决定每一步用哪个模型，让你拿到好答案又不花冤枉钱。这是自动发生的——“路由模式”只是选整体策略。","start.glossary#1#td5.0":"工具","start.glossary#1#td5.1":"Ava 能做的具体动作——读文件、搜信息、发邮件。“工具调用”就是她用了其中一个。涉及风险前她会先征求许可。","start.glossary#1#td6.0":"令牌","start.glossary#1#td6.1":"AI 衡量文本的单位——大约四分之三一个单词。模型按每百万令牌计费。大部分时候你可以忽略它。","start.glossary#1#td7.0":"额度","models.routing#deeper#2#td11.1":"日常任务，成本可预测","models.routing#deeper#2#td11.2":"复杂多步任务，每个计划都配备前沿协调器","models.routing#deeper#2#td11.3":"严格符合 GDPR，公共部门，主权欧盟架构","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"分层差异化 Qwen 路由，轻量级。Qwen 3.6 Plus 负责协调、Builder、规划、安全、头脑风暴和长上下文工作——在这些领域，其 1M 上下文的混合线性注意力优势明显。Qwen 3.5 Flash 处理聊天、图像生成编排以及上游意图网关，其 $0.07/$0.26 的定价和更快的 TTFT 在大量低深度令牌量上胜出。Qwen 3.5 Omni Plus 负责视觉输入（Qwen 3.6 Plus 没有原生视觉功能）。Qwen 3.5 Plus 承担对成本敏感的长文工作。如果主要协调器不可用，则按优先级阶梯降级：Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash。","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"多语言模型集成。DeepSeek V4 Pro 负责协调并将每个子任务分派给最合适的专家：Qwen 3.6 Plus 运行所有 Builder 实例，V4 Flash 处理聊天以及中层的审核/审计角色，Qwen 3.5 Flash 吸收轻量级分类工作，Qwen 3.5 Omni Plus 负责视觉输入，Qwen 3.5 Omni Flash 编排图像生成工具调用，Qwen 3.5 Plus 承担对成本敏感的长文“内容撰写者”角色。关键处使用前沿推理，大部分令牌量采用闪速层级的经济性方案。","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"欧洲 AI 架构 —— 设计即主权。仅 Mistral 路由分为三个层级：Mistral Large 3 (675B/41B 激活稀疏 MoE) 负责协调角色以及需要深度的重型专家——研究员、挑战者、CVE 研究员、创意者、事实核查员、安全验证者——以及长上下文的基础工作，其稀疏 MoE 效率在此胜出。Mistral Medium 3.5 —— 2026 年 4 月发布的融合旗舰版，128B 稠密，256K 上下文，从头训练的视觉编码器，修改版 MIT 开源权重，77.6% SWE-Bench 验证 —— 运行实际工作层级：Builder 实例、中层专家（架构师、验证者、序列器、导师、报告员）、视觉输入和长文写作。Mistral Small 4 从意图网关的单角色扩展为同时处理聊天和图像生成编排——其 $0.15/$0.60 的定价和可配置推理在高流量低深度路线上物有所值。端到端开源权重，永不离开欧盟基础设施。Aurora 有意不在主模型不可用时静默跨路由到非 Mistral 模型；路由器会直接显示错误——这正是它称为\"Aurora\"而非带有 Mistral 风味的 Maestro 的原因。","credits.overview#title":"Ava 积分 —— 计费说明","credits.overview#0#p":"积分只是 Ava 计算您使用情况的方式——就像手机套餐里的分钟数一样。每个计划，包括免费计划，都附带一个积分池，Ava 做的每件事（回答您、生成图片）都会消耗少量积分。这就是核心理念。下面的细节供您了解具体每项操作的成本。","credits.overview#1#p":"Ava 按积分计费，而非原始令牌。（A \"token\"是 AI 模型读取和写入的微小文本块——大约几个字母——大多数服务按令牌收费，这很难预测。）一个积分覆盖一个工作单位——一次对话回合、一个角色实例化（一个助手完成部分任务）、一次图像生成。与令牌级计量解耦意味着您无需知道正在运行哪个模型就能知道某项操作的成本。无论 Maestro 将其路由到 Qwen 3.6 Plus 还是 Supernova 路由到 V4 Pro，同一次对话回合的成本都是一样的。","credits.overview#2#h":"计划","credits.overview#3#p":"每个计划都能访问所有功能——模型访问权限、Creative Studio、全部七种模式、完整的角色编排。更高阶的计划购买更多积分和更高的速率限制上限，而非解锁新功能。","credits.overview#4#li0":"免费 —— 每月 $0。300 积分。每分钟 20 次请求速率限制。无需绑定卡片。","credits.overview#4#li1":"专业版 —— 每月 $19。5,000 积分。每分钟 60 次请求。","credits.overview#4#li2":"超能版 —— 每月 $39。10,000 积分。每分钟 120 次请求。","credits.overview#4#li3":"企业版 —— 每月 $79。20,000 积分。每分钟 200 次请求。","credits.overview#5#c":"订阅期间未使用的积分会结转——不会强制收回。充值会在订阅池中叠加：$3 获得 750 积分，$8 获得 2,000 积分，$15 获得 4,000 积分。","credits.overview#6#h":"各项费用说明","credits.overview#7#p":"按操作计费表 —— 每项操作运行时从您的积分池中扣除的内容。（A \"cache hit\"是指 Ava 重用已完成的工作而不是重新执行；此时您支付更少——费用降低 70%，或在 DeepSeek V4 Pro 等输出密集型模型上降低 50%。）","credits.overview#8#li0":"对话回合 —— 2 积分。任意模式下的单次来回交流。","credits.overview#8#li1":"轻量调用 —— 1 积分。意图网关、分类、单次读取。","credits.overview#8#li2":"重型角色 —— 3 积分。架构师、研究员、CVE 研究员、创意者（深度 ≥ 4）。","credits.overview#8#li3":"轻型角色 —— 1 积分。侦察兵、验证者、序列器、挑战者（深度 ≤ 2）。","start.glossary#1#td7.1":"Ava 衡量操作成本的更简单单位，让你不用算 token 了。套餐包含每月额度。","start.glossary#1#td8.0":"API 密钥","start.glossary#1#td8.1":"一种私密密码，允许软件在你的账户上使用付费服务（如 AI 模型）。只有当你想自带密钥时才需要。","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"自带密钥。\" 使用你自己的 API 密钥，而不是 Ava 的托管访问。可选——适合已经直接向提供商付费的人。","start.glossary#1#td10.0":"本地优先","start.glossary#1#td10.1":"默认情况下，你的数据保存在你自己的电脑上。除非开启同步，否则不会上传任何内容。\"本地至上\"。","start.glossary#1#td11.0":"权限模式","start.glossary#1#td11.1":"Ava 做事前的谨慎程度——每次都问、只问高风险的事、或者直接执行。由你设定级别。","start.glossary#1#td12.0":"上下文窗口","start.glossary#1#td12.1":"模型一次能记住多少文本——它的短期记忆。\"1M 上下文\"意味着大约一百万字。越大 = 遗忘前能读的越多。","start.glossary#1#td13.0":"差异对比","start.glossary#1#td13.1":"文件变更的并排视图——一边旧版，一边新版——在 Ava 修改之前显示，以便你批准。","start.glossary#1#td14.0":"仓库（repo）","start.glossary#1#td14.1":"一个用于追踪变更的项目文件夹，通常配合 Git 使用。如果这对你来说还陌生，它就只是\"存放我项目的文件夹\"。","start.glossary#1#td15.0":"提示词","start.glossary#1#td15.1":"你输入给 AI 的内容——你的问题或指令。","start.glossary#2#c":"还在为某个词卡住？在聊天模式中问 Ava——\"X 是什么意思？\"——她会根据你的水平解释。","models.routing#title":"路由 —— Ava 如何挑选模型","models.routing#0#p":"简而言之：你永远不必选择使用哪个 AI 模型。Ava 会为你完成，为工作的每一部分选择最佳工具——就像一位好经理把合适的任务交给合适的人一样。","models.routing#1#p":"你可以从三种风格中选择一种——Maestro、Supernova 或 Aurora——然后 Ava 将每项工作发送给处理得最好的模型。Maestro 是默认选项，所有套餐都可用，对大多数人来说都是不错的选择。","models.routing#2#h":"为什么要进行路由？","models.routing#3#p":"在每个步骤使用合适的模型，比把所有事情都跑在一个昂贵的大模型上成本更低——并且效果更好，因为每个模型都做它擅长的事。你获得稳定的成本和高质量，而无需关心具体是哪个模型。","models.routing#4#c":"这三种风格都支持平台积分和你的自有密钥。使用自有密钥时，你还可以跳过路由，直接驱动单个模型。完整列表在\"向我展示详情\"下。","models.routing#deeper#0#c":"下面的\"B\"数字代表数十亿参数——大致相当于模型大脑的大小；越大通常越聪明但更慢且更贵。这是底层细节；使用 Ava 时你完全不需要它。","concepts.modes#0#p":"模式就是 Ava 当下的心态——好比同事换了一副眼镜。人还是那个人，对你的记忆也没变，但构建者和教师的思维方式截然不同。选定模式后，她的行事风格和调用的助手都会随之调整。你可以随时通过模式选择器切换，或者直接输入两个字符的快捷键。","concepts.modes#2#h":"你想用哪个？","concepts.modes#3#p":"从你想完成的任务出发——模式自然随之而定：","concepts.modes#4#li0":"我想构建或修改内容 → 代码 (>>). 你描述需求，她负责构建，并先向你展示每一处改动。处理大任务时，完整的助手团队会全部上线。","concepts.modes#4#li1":"我想在行动前先有个方案 → 计划 (::). 她会深思熟虑后交给你一个计划，供你批准或修改。在此模式下，她不会触碰你的任何文件。","concepts.modes#4#li2":"我只想聊聊或问问 → 聊天 (..). 一位拥有记忆、资讯和天气知识的思考伙伴。不涉及文件修改，也不写代码——纯粹是交流。","concepts.modes#4#li3":"我想学习新知识 → 教学 (??). 为你量身打造的真实课程：包含课程、测验等内容。所有订阅计划永久免费。如果你是新手，这非常适合。","concepts.modes#4#li4":"我想检查项目的安全漏洞 → 安全 (!!). 团队会对照常见的 Web 漏洞标准清单（即 \"OWASP\" 类别）以及已知的公开缺陷（称为 \"CVEs\"）进行排查，然后给你一份按严重程度排序的报告。这一项专为开发者设计——如果不是开发者可以略过。","concepts.modes#4#li5":"我想要灵感 → 头脑风暴 (**). 她会基于你的实际情况生成选项，找出其中的弱点并加以修正，将剩余方案细化为可执行的下一步。","concepts.modes#4#li6":"我想撰写文档 → 写作 (<<). 无论是报告、提案、信件还是文章——她先用 Markdown 起草，再导出带品牌的 Word 文档或 PDF，逐节打磨。不涉及代码，仅专注文字创作。","concepts.modes#5#c":"“助手团队”（角色设定）完全在幕后运行——你无需直接与它们对话。你只会获得更周全的回答。不需要了解它们的名字。","concepts.modes#6#c":"你可以在对话过程中随时切换模式。你的记忆会保留下来，而专家助手会根据新模式重新调整状态。","concepts.tasks-journal#title":"任务与日志","concepts.tasks-journal#0#p":"Ava 会为你记录三种类型的笔记，很容易弄混。简单记法：记忆是她对你了解的内容，任务是待办事项，日志则是记录事情经过的日记。下面说明何时使用哪一种。","concepts.tasks-journal#1#li0":"记忆 —— 持久的事实。包括偏好、决策和行为模式。通常由系统根据交互积累，很少手动创建。","concepts.tasks-journal#1#li1":"任务 —— 待办事项。带有截止日期和状态的具体行动项。完成后打勾即可。","concepts.tasks-journal#1#li2":"日志 —— 反思记录。每日流水账，包含双方条目（你的记录和 Ava 对会话的观察）。有助于情绪追踪、会话复盘，并为明天提供背景信息。","concepts.tasks-journal#2#p":"只要合适，Ava 会自动同步更新这三类笔记。你也可以直接从仪表盘向其中任意一项写入内容。没有任何数据被锁定在单一位置——你在一个地方创建的任务（例如命令行工具），会自动出现在其他所有地方（如桌面应用）。","concepts.permissions#title":"权限设置 —— 你的安全调节旋钮","concepts.permissions#0#p":"权限就是你的安全调节旋钮。它决定了 Ava 是在电脑操作前征求你的许可，还是直接执行。你可以设置为询问所有操作、仅询问高风险操作，或直接信任她全权处理——而且随时可以更改。如果不确定，保持默认设置即可，这样最稳妥。","concepts.permissions#1#p":"Ava 拥有 60 种工具（\"tools\"指她能执行的操作，如读取文件、搜索网络等）。每种工具都归类于某个类别（文件操作、Shell、Git、Web、媒体、数据库、系统、文档、记忆、学习）。每次工具调用在执行前都要经过权限关卡（一个决定是否需要先询问你的检查点）。你可以控制哪些操作自动批准、哪些询问一次、哪些始终询问。","concepts.permissions#3#p":"“平衡”是默认设置。“严格”模式适合审计她的行为（仔细检查每一步）。“自主”模式则适合希望她放手去做的场景。","concepts.permissions#4#c":"“自主”并不意味着不受监管。计划、澄清问题和明确的请求用户输入提示仍会暂停等待你的反馈。不可逆操作（如 Git 强制推送、数据库删除）无论何种模式都会要求确认。","concepts.interjection#title":"引导与中止 Ava","concepts.interjection#0#p":"你永远掌握主导权。当 Ava 忙碌工作时，你可以轻轻引导她转向新方向而不打断进度，也可以立即叫停。两个按钮，两种结果——这就是本页面要介绍的全部内容。","features.creative-studio#1#p":"图像、视频、音乐和语音生成——融入您编写代码的同一工作流中。无论是生成图标、产品原型、演示视频，还是教程配音，都能轻松完成。由 MiniMax 驱动。","features.creative-studio#2#h":"你可以创作什么","features.creative-studio#3#li0":"图片 —— 输入提示词即可生成 PNG/JPG。背景移除只需一次调用。","features.creative-studio#3#li1":"视频 —— 通过文本提示生成简短 AI 视频（MiniMax Hailuo）。","features.creative-studio#3#li2":"音乐 —— 包含器乐或带歌词的人声曲目。","features.creative-studio#3#li3":"语音 —— 支持选择不同声音的文本转语音功能。","features.creative-studio#4#p":"Creative Studio 的费用与其他服务共用同一个积分池——只有一个池子，一个余额数字。如果您自带 MiniMax 密钥（BYOK），则对您计划内的使用免费。","features.creative-studio#5#c":"Creative Studio 适用于免费层级。它不是付费附加功能。","features.desktop-automation#title":"桌面自动化","features.desktop-automation#0#p":"简单来说：Ava 可以接管你的鼠标和键盘来帮你完成任务——比如打开应用、点击按钮、填写表单——而你在旁边观看，并对重要事项进行确认。","features.desktop-automation#1#p":"这是 Ava 的一种新模式，使用前缀 @@。她会观察桌面，决定如何操作，并驱动 UI 自动化（替你控制屏幕上的应用）来完成任务。它在你的真实机器上运行，使用你的真实凭证——而非云端浏览器。上线后将对所有层级开放。","features.desktop-automation#2#h":"为何需要另一个","features.desktop-automation#3#p":"其他桌面自动化工具通常需要你坐在电脑前才能启动。而 Ava 会在凌晨 2 点你的错误追踪器报警时依然在线——IDE 持续运行，手机通过安全通道连接，你只需轻点一下就能批准那些不可撤销的操作。","features.desktop-automation#4#p":"她还能记住跨会话如何操作你的应用。其他智能体每次都要重新学习。这种记忆优势会随着使用不断积累。","features.desktop-automation#5#h":"工作原理","features.desktop-automation#6#p":"每个步骤都会触发一个“五人角色组”：侦察员负责观察，规划者选择下一步动作，执行者进行操作，验证者进行检查，讲述者向你汇报结果。Sidecar 会选择成本最低且可靠的交互基础——原生应用使用 UIA，浏览器使用 Playwright，当其他方案无法提供有效结构时使用 OmniParser 视觉能力。","features.desktop-automation#7#p":"有关安全本体、交互依据层级、紧急停止开关以及会话白名单模型的详细信息，请参阅概念页面。","reference.cli#5#li3":"--project <path> — 显式设置项目根目录。","reference.desktop-budget#title":"桌面预算上限","reference.desktop-budget#0#p":"当 Ava 代表您操作桌面时——点击、输入、打开应用——每一次运行都被称为一个“轨迹”。本页说明了安全限制，确保单次运行不会耗时太久或花费过多。核心原则是：她绝不会擅自超时，而是会在超出前停下来向您确认。如果您想了解具体数据，这里都有。","reference.desktop-budget#1#p":"每个“轨迹”都受三个同时生效的上限（硬性限制）约束。一旦触及其中任何一个，就会立即停止。轨迹绝不会在突破限制后悄悄继续——Narrator（那位帮您解说当前情况的助手）会暂停下来，询问您该如何处理。","reference.desktop-budget#2#h":"三个硬性上限（默认值）","reference.desktop-budget#3#li0":"步骤数 — 30 步","reference.desktop-budget#3#li1":"Token 预算 — 500,000 个 Token","reference.desktop-budget#3#li2":"实际耗时 — 5 分钟","reference.desktop-budget#4#h":"任务成本档位","reference.desktop-budget#5#li0":"简单（搜索文档、打开页面）— 5–10 步，~70–135K Token，~$0.04–0.08","reference.desktop-budget#5#li1":"中等（登录、查看日志、下载输出）— 15–25 步，~205–340K Token，~$0.12–0.21","reference.desktop-budget#5#li2":"复杂（分类处理三个 GitHub 问题）— 25–30 步，~340–410K Token，~$0.21–0.25","reference.desktop-budget#6#p":"上面的 Token 数值指的是单次运行的技术上限，不是您的月度额度——那是按积分计算的。免费版的每月 300 积分足以轻松应对聊天、写代码和少量自动化任务的组合。","reference.desktop-budget#7#c":"您可以在任务开始时针对单个任务调整上限，但只要突破限制，系统总会让您做决定。预算绝不会在不知情的情况下被消耗。","reference.desktop-whitelist#title":"桌面会话白名单","reference.desktop-whitelist#0#p":"“白名单”是指您授权 Ava 在接管桌面时可以操作的软件及网站列表。本页说明如何授予这些权限，以及为何每次都会重置。简单来说：她只能在您允许的地方行动，去新地方前也会先问您。","reference.desktop-whitelist#1#p":"在桌面会话开始时，Ava 会询问她可以在哪里行动。用大白话就行：“Gmail、Cursor、Azure 门户。”她会复述一遍并与您确认匹配结果（“Gmail 网页版、Cursor 应用、portal.azure.com”）。","reference.desktop-whitelist#2#h":"执行方式","reference.desktop-whitelist#3#p":"仅查看类操作——例如截图、读取屏幕上的按钮和字段列表（也就是“UIA 树”，Windows 对窗口内容的映射）——随处都允许，因为您需要看清屏幕内容才能决定是否把应用加入白名单。凡是涉及修改的操作，在列表外一律被拦截；Ava 会暂停并询问您是否要添加。","reference.desktop-whitelist#4#h":"仅限会话，这是刻意为之","reference.desktop-whitelist#5#p":"白名单不会在不同会话间保留。没有“记住此应用”的选项。每个新轨迹都从头开始。这虽有些不便，却是有意为之——忘记重新授权是一种保护特性，而非漏洞。","reference.desktop-whitelist#6#h":"轨迹中途添加","reference.desktop-whitelist#7#p":"在轨迹进行中，您可以从顶部栏添加应用：“+ 允许应用”会打开一个小输入框。点击添加，新应用即刻生效，直至本次会话结束。","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"想做一张图片、一段短视频、一首歌，或者一段配音？只需描述一下，Ava 就能为您制作——无需设计或音频软件。","concepts.interjection#1#p":"Ava 会一直运行，直到她的计划完成或你停止她。在她运行时，你有两种方式介入（这个词叫做“干预”）。","concepts.interjection#2#h":"介入 —— 引导而不取消","concepts.interjection#3#p":"在 Ava 工作时输入新消息。她会先完成当前的工具调用，读取你的消息，然后调整计划。不会丢失任何上下文。当你想要重定向、补充信息或在运行中更改优先级时使用此功能。","concepts.interjection#4#h":"硬停止 —— 取消并清空","concepts.interjection#5#p":"按 Escape（CLI）、点击停止（扩展程序、IDE），或输入停止命令。当前运行会被取消，待处理的工具调用也会终止，对话准备好迎接新的回合。","concepts.interjection#6#c":"优先使用介入。硬停止仅在真正出错时使用。介入能保持对话线程活跃。","concepts.desktop-personas#title":"桌面角色","concepts.desktop-personas#0#p":"本页面适合好奇者和高级用户。“桌面自动化”（有时称为“电脑操作”）意味着 Ava 实际上可以在你的屏幕上点击并使用应用——打开 Gmail、填写表单、发送消息——就像一个人坐在键盘前一样。为了安全地做到这一点，她将工作拆分为五个小助手，每个助手只有一个狭窄的角色。你永远不会直接与它们打交道；这里只是为了让你知道谁负责什么。","concepts.desktop-personas#1#p":"桌面轨迹中的每一步（Ava 驱动你的屏幕朝向目标的一次运行）都会经历一个五角色流程。每个角色只有一份工作，且仅此一份。这种分离确保提示紧凑、输出结构化，并且推理设计为保持审慎。","concepts.desktop-personas#2#h":"侦察兵","concepts.desktop-personas#3#p":"报告当前屏幕上可见的内容。从不虚构元素。从不规划。返回包含元素 ID、名称、边界框、置信度和依据来源（UIA、Playwright DOM 或 OmniParser 视觉）的 ScreenState JSON。","concepts.desktop-personas#4#h":"规划师","concepts.desktop-personas#5#p":"决定单个下一步动作。每步仅一个动作——绝不批量处理。偏好可逆路径。根据安全本体论对风险进行分类。输出包含类型、目标、参数、风险类别、推理和预期后状态预测的 ProposedAction JSON。","concepts.desktop-personas#6#h":"执行者","concepts.desktop-personas#7#p":"精确执行规划师提出的内容——在审批门通过之后。不即兴发挥。不重试。失败如实报告，由验证器处理下一步。","concepts.desktop-personas#8#h":"验证器","concepts.desktop-personas#9#p":"检查动作是否成功落地。将新的 ScreenState 与规划师的预测进行比较。返回已验证、偏离或需要回滚。还运行循环检测——重复已经成功的动作属于偏离，而非验证。","concepts.desktop-personas#10#h":"叙述者","concepts.desktop-personas#11#p":"用户在轨迹期间听到的唯一声音。每步一句过去时句子（“打开了 Gmail。”，“点击了撰写。”）。还编写结构化的审计日志。当出现问题时会说明——从不隐藏问题。","concepts.desktop-safety#title":"桌面安全本体论","concepts.desktop-safety#0#p":"简而言之：在 Ava 点击屏幕上的任何内容之前，她会按风险程度对动作进行分类。读取屏幕？无害。发送资金或删除内容？她总是先停下来问你——每一次，绝无例外。下面的五个标签只是这个风险梯子的阶梯。这是高级用户的细节，但要点很简单：危险的事情总是需要你的同意。","concepts.desktop-safety#1#p":"每个提议的动作都被归类为五种风险类别之一。分类结合了三个信号——屏幕上的目标是什么、它的通俗描述（“语义标题”——Ava 对自己正在看内容的描述）以及动作的设置——当它们不一致时会上调（视为风险更高）。误报（不需要问却问了）只是唠叨。漏报（应该问却没问）则是导致产品终结的事故。","concepts.desktop-safety#2#h":"五个类别","concepts.desktop-safety#3#li0":"观察性 —— 读取 UIA 树、截图、悬停。始终自动允许。","concepts.desktop-safety#3#li1":"导航性 —— 滚动、移动焦点、打开菜单。在驾驶模式下自动允许。","concepts.desktop-safety#3#li2":"Mutative-reversible — type into a field, paste, open an app, navigate a URL. Confirms in Ask mode; auto in Drive within the whitelist.","concepts.desktop-safety#3#li3":"Mutative-irreversible — send, submit, pay, delete, confirm, publish. Always confirms, regardless of permission level. Approval never caches.","concepts.desktop-safety#3#li4":"Privileged — UAC elevation, sudo, registry edits, credential prompts. Forbidden by default. Single-use opt-in required per session.","concepts.desktop-safety#4#h":"Never-cached approvals","concepts.desktop-safety#5#p":"Every competitor caches approvals (remembers your \"yes\" and reuses it next time). That is the largest foothold for prompt injection — an attack where a booby-trapped web page sneaks hidden instructions to the AI to make it act against you. If approvals are cached, a compromised page can ride on a \"yes\" you gave earlier. Ava never caches. Each mutative-irreversible action asks fresh.","concepts.desktop-safety#6#h":"Secrets handling","concepts.desktop-safety#7#p":"Passwords, API keys, and 2FA codes (the one-time codes a second app or text gives you when you log in) are handled via opaque handles — placeholders that stand in for the real value. Ava sees \"{secret}\", not the actual password. The real value never enters her memory, her activity log, or what she \"reads\" — a separate low-level layer types it in at the last moment, at the keypress, so the AI part never touches it.","reference.cli#title":"CLI commands","reference.cli#0#p":"This page is for the CLI — the version of Ava you type to in a terminal window, rather than clicking buttons. If you use the extension or the desktop app, you can skip it entirely. It is here for people who prefer the keyboard.","reference.cli#1#p":"The CLI is a REPL — a prompt that waits for you to type, runs what you typed, then waits again. These slash commands (instructions that start with \"/\") work from the prompt.","reference.cli#2#li0":"/help — list commands and current mode.","reference.cli#2#li1":"/mode <name> — switch mode (work, write, plan, chat, teach, security, brainstorm).","reference.cli#2#li2":"/model <id> — switch model without leaving the session.","reference.cli#2#li3":"/clear — clear the current conversation. Memory is untouched.","reference.cli#2#li4":"/history — list past conversations in this project.","reference.cli#2#li5":"/memory — open the memory browser.","reference.cli#2#li6":"/tasks — list and manage tasks.","reference.cli#2#li7":"/journal — open today journal entry.","reference.cli#2#li8":"/settings — open the settings menu.","reference.cli#2#li9":"/exit — quit the REPL.","reference.cli#3#h":"Launch flags","reference.cli#4#p":"Flags are extra options you add when you start Ava, each beginning with \"--\", to set how she opens.","reference.cli#5#li0":"--mode <name> — start in a specific mode.","reference.cli#5#li1":"--model <id> — start with a specific model.","reference.cli#5#li2":"--permission <mode> — strict / balanced / autonomous."},"zh-TW":{"start.for-non-coders#6#li3":"當你想讓她真正執行或修改某些內容時，直接告訴她就對了。她總是會先展示即將採取的行動，並等待你說「好的」。","start.for-non-coders#7#c":"遇到不認識的單字嗎？本節下方有「白話詞彙表」，會用通俗易懂的方式解釋每個術語，完全不需要預先具備相關知識。","start.install#title":"安裝","start.install#0#p":"選擇最適合你工作習慣的介面。你可以同時使用多個——只要登入，Ava 就會在所有介面間同步她的記憶。","start.install#1#h":"VS Code 擴充套件","start.install#2#li0":"在 VS Code 中開啟「擴充功能」面板（按 Ctrl+Shift+X / Cmd+Shift+X）。","start.install#2#li1":"搜尋「Ava Supernova」，然後點擊安裝。","start.install#2#li2":"按下 Ctrl+Shift+A（macOS 請改用 Cmd+Shift+A）來開啟對話視窗。","start.install#2#li3":"依照設定嚮導操作——選擇模型、設定權限模式，就完成了。","start.install#3#h":"桌面 IDE","start.install#4#li0":"前往發布頁面，下載適合你作業平台的安裝程式。","start.install#4#li1":"執行安裝程式。首次啟動時，IDE 會引導您完成歡迎流程。","start.install#4#li2":"登入即可獲得免費的平台代幣，或者貼上您自己的 API 金鑰，就能完全在本機運行。","start.install#5#h":"CLI","start.install#6#li0":"執行 `npm install -g @ava/cli`（或是 `pnpm` / `yarn` —— 隨您喜好）。","start.install#6#li1":"在任何專案資料夾中執行 `ava`。","start.install#6#li2":"首次執行時會詢問您服務供應商與模型，選定後即可開始使用。","start.install#7#c":"沒有帳號也沒關係。使用您自己的 API 金鑰（BYOK），就完全不需要登入。免費方案僅適用於平台管理的模型。","concepts.memory#1#p":"Ava 擁有一個持久記憶（\"persistent\" 意味著即使你關閉應用程式，它仍會持續存在），能跨對話、跨專案，且在啟用同步後跨設備保存（同步會在你的裝置間複製你的記憶）。這不是聊天記錄。它是對你是誰、你喜歡什麼以及你做過什麼決定的結構化、可搜尋的理解。","concepts.memory#2#h":"五層架構","concepts.memory#3#li0":"提取 — 即時捕捉每則訊息中的關鍵事實。","concepts.memory#3#li1":"反思 — 在有意義的會話結束後進行更深度的分析。模式、主題、矛盾之處。","concepts.memory#3#li2":"累積 — 修正與偏好會隨著數週數月不斷疊加。","concepts.memory#3#li3":"分析 — 圖形引擎連結相關記憶，當新資訊與舊資訊衝突時標記矛盾。","concepts.memory#3#li4":"整合 — 相似記憶合併；過時的記憶修剪。記憶隨時間變得更清晰，而非更雜亂。","concepts.memory#4#c":"上述五層自動運行——你從不需要管理它們。它們的存在是為了讓你看到記憶確實隨時間改善，而不是變成一堆雜物。","concepts.memory#5#h":"檢索","concepts.memory#6#p":"當你提問時，Ava 會透過意義搜尋記憶（`semantic search` —— 它理解你的意思，所以即使你措辭不同，也能找到正確的記憶）。特定模式的過濾器同時運作——聊天模式拉取個人背景，工作模式拉取專案決策和程式碼模式。","concepts.memory#7#c":"記憶範圍限於每個用戶和每個專案（你的記憶屬於你，按人和專案分開保存）。秘密和憑證（密碼、金鑰）在儲存邊界被阻擋——它們永遠無法進入記憶。","concepts.memory#title":"記憶 —— Ava 如何記住您","concepts.memory#0#p":"簡單來說：Ava 記得您。告訴她一件事一次——您喜歡什麼、您做的決定——她都會記住，所以您在下次對話或下一週就不用重複了。這就是重點。下面的層次只是解釋她如何隨著時間保持記憶整齊。","concepts.desktop-kill-switches#4#p":"會在下一個步驟邊界暫停。可以繼續。如果你想在不干擾進度的情況下介入，就用這個。","concepts.desktop-kill-switches#5#h":"停止 — 按 Esc 鍵或點擊停止按鈕","concepts.desktop-kill-switches#6#p":"乾淨地中止。講述者會總結目前的進度。無法恢復執行。審計日誌已記錄。","concepts.desktop-kill-switches#7#h":"緊急強制終止 — 連按三次 Esc 或 Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"這是最強力的停止方式。有一個獨立的小型監控程式，會強制關閉負責控制你螢幕的 Ava 部分。它不用等 AI 回應，也不用視窗正常運作，不管現在是什麼狀況，它都會直接終止。只有當事情真的嚴重出錯時，才需要用到它。","concepts.desktop-kill-switches#9#p":"這三種方式在 Companion App 中也能用。任何驅動都能結束任務。","reference.tools#title":"工具參考","reference.tools#0#p":"這是 Ava 所有工具的完整清單。「工具」指的是她能執行的特定動作，像是讀取檔案或進行搜尋。其實你不需要看這一頁。每次都是 Ava 自己挑選最適合的工具。這裡列出是供你好奇她具體能做些什麼時參考。","reference.tools#1#p":"這是完整的內建工具箱。這裡的每個工具都已註冊在核心運行時（支撐三個介面的引擎）中，只要模式和權限允許，Ava 就能使用。你可以依類別或風險來篩選。","reference.tools#2#p":"不需要記住這些細節——下方的表格只是一張快速參考表。","reference.tools#4#h":"風險等級","reference.tools#5#li0":"安全 — 只讀取內容，不會修改任何東西。file_read, glob (依名稱模式找檔案), grep (在檔案內搜尋文字), git_status (Git 是用來追蹤專案變更的系統)。","reference.tools#5#li1":"寫入 — 修改檔案、儲存工作檢查點（稱為「提交」），或是產出新內容。file_edit, git_commit, generate_image.","reference.tools#5#li2":"危險 — 在你的電腦上執行指令（「Shell」）、控制桌面、連線到網際網路，或是查詢資料庫。bash, browser, desktop_*.","reference.tools#6#c":"角色專家各有自己的工具白名單。Scout 只能讀取，不能寫入。Builder 擁有完整存取權限。Challenger 則完全沒有工具——它的任務是質疑計畫。","reference.models#title":"模型","reference.models#0#p":"「模型」就是負責思考的 AI 大腦——像是 Qwen, DeepSeek, Mistral 等。此頁面列出 Ava 能使用的所有模型。簡單說：你不需要手動選擇。Ava 會為每個步驟自動挑選合適的模型。除非你想了解或手動覆蓋，否則不用看這裡。","reference.models#1#p":"列出 Ava 能調用的所有模型，以及三種協調策略——也就是決定哪個模型負責哪部分工作的規則。你可以選擇路由模式讓 Ava 自動分派，或者指定單一模型，完全跳過路由。","reference.models#2#h":"路由模式","reference.models#3#p":"三種協調策略。相同的角色流程（Ava 在幕後運作的專家小隊）在三種模式下都一樣；變化的只是底層的模型群組。在模型選擇器中選個模式，剩下的交給 Ava 處理。下方每張卡片顯示指揮官會調用的專家組合。","reference.models#4#p":"不需要記住下方的卡片——它們只是為了讓你看看每個策略是由哪些部分組成的。","reference.models#6#c":"Aurora 特意只支援 Mistral。如果找不到 Mistral 模型，路由器會回傳錯誤，不會切換到其他模型——這是 EU-stack 的保證。如果想要優雅降級，請選擇 Maestro 或 Supernova。","reference.models#7#c":"三種模式都通用——無論是使用平台積分還是你自己的金鑰。BYOK 提供了繞過協調機制、直接驅動單一模型的選項。","reference.models#8#h":"平台管理模型","reference.models#9#p":"適用於所有方案，包含免費版。Token（AI 計算文字量的單位，大約每 Token 等於四分之三個字）會消耗你的方案配額。金鑰（解鎖付費模型的私密密碼）由平台自動輪替與監控——你不需要做任何設定。","concepts.desktop-grounding#title":"桌面錨定層級（預覽版）","concepts.desktop-grounding#0#c":"預覽 —— Scout 決定每一步使用哪種錨定來源的方式。","concepts.desktop-grounding#1#p":"在 Ava 點擊按鈕之前，她必須真正理解螢幕上顯示什麼、東西在哪裡——這就是「錨定」（弄清楚螢幕上每個物件是什麼及其確切位置）。她有這三種方法，並會選擇最適合你當前應用程式的最可靠方式。這是深入進階使用者的細節；重點在於她偏好紮實準確的方法，而不是從圖片猜測。","concepts.desktop-grounding#2#p":"三個層級，依序評估。最輕量且可靠的來源優先。","concepts.desktop-grounding#3#h":"1. 瀏覽器視窗 → Playwright `DOM`","concepts.desktop-grounding#4#p":"如果活躍視窗是網頁瀏覽器，Ava 會讀取頁面自身的結構（`` `DOM` ``——頁面上內容的底層列表），而不是從圖片猜測。讀取結構比肉眼檢視像素大約可靠 10 倍——她知道每個按鈕的確切位置以及頁面何時載入完成。這是網頁相關操作的主要途徑，並非備案。","concepts.desktop-grounding#5#h":"2. 支援 `UIA` 的原生應用程式 → Windows `UI Automation`","concepts.desktop-grounding#6#p":"對於 Windows 上的普通桌面應用程式，Ava 會讀取內建的無障礙地圖（`` `UIA` ``，與螢幕閱讀器用來描述視窗的相同數據）——它列出每個控制項、名稱及位置。如果該地圖回傳至少五個可用且有名的項目，她就會信任並使用它。","concepts.desktop-grounding#7#h":"3. `UIA` 空白或無效 → OmniParser 視覺","concepts.desktop-grounding#8#p":"當該地圖缺失或無用時（某些應用程式、遊戲和遠端畫面不提供），Ava 會退而求其次，直接查看螢幕截圖。視覺工具（OmniParser）會識別可點擊區域並標註每個區域是什麼，將圖片轉回她能操作的列表——再結合無障礙地圖提供的任何少量資訊。","concepts.desktop-grounding#9#c":"首次 Ava 需要使用 OmniParser 時需選擇加入，並會有明確的隱私提示。BYOK 使用者可以指向自己的本地 OmniParser 部署。","concepts.desktop-kill-switches#title":"桌面緊急停止開關（預覽版）","concepts.desktop-kill-switches#0#c":"預覽 —— 中止正在運作的流程有三種獨立方式。任一種都能生效。","concepts.desktop-kill-switches#1#p":"「緊急停止開關」聽起來就是那麼回事——當 Ava 控制你的螢幕時，立即停止她的緊急方式。令人安心的是：有三個開關，各自獨立建置，所以如果一個失效，另一個仍然有效。你不需要學會全部三個。只需知道當事情看起來不對勁時，你總能停止它，而最強力的停止（下方的恐慌停止機制）不依賴 Ava 的配合。","concepts.desktop-kill-switches#2#p":"在研讀了所有公開的自主事故（AI 代理忽略停止指令、刪除電子郵件封存、格式化硬碟等真實案例）後，我們在三層不同的架構中建立了三個緊急停止開關。它們都不依賴 AI 模型本身——如果 Ava 卡住或無反應，你仍然可以停止她。","concepts.desktop-kill-switches#3#h":"暫停 —— 空格鍵或暫停按鈕","reference.config#title":"設定檔","reference.config#0#p":"此頁面顯示 Ava 在您的電腦上存放設定和檔案的位置。您幾乎不需要手動調整任何內容——應用程式會幫您管理。這裡是為了當您想自行查看、備份或分享這些檔案時使用的。","reference.config#1#p":"Ava 從兩個範圍讀取設定（她的儲存設定）。全域設定——適用於所有地方的設定——位於名為 ~/.ava/ 的資料夾中（「~」是您的主目錄縮寫）。專案專屬設定則位於專案內部的 .ava/ 資料夾中。","reference.config#2#h":"全域 — ~/.ava/","reference.config#3#li0":"settings.json — 模型偏好、許可權模式、個性、語言。","reference.config#3#li1":"memory/ — 您的全域記憶（偏好、適用於所有地方的決定）。","reference.config#3#li2":"tasks.json — 跨專案任務清單。","reference.config#3#li3":"journal/ — 每日日記條目，依日期組織。","reference.config#4#h":"專案 — .ava/","reference.config#5#li0":"instructions.md — Ava 總是載入的專案專屬說明。持久情境（「我們使用 pnpm，不使用 npm」、「API 金鑰存在 1Password 中」）。","reference.config#5#li1":"context.md — 可選的自由格式專案筆記。","reference.config#5#li2":"memory/ — 限於此專案的記憶。","reference.config#5#li3":"datasets/config.json — 自願選擇的數據集捕捉設定。","reference.config#6#c":"如果您不想與團隊共享記憶，請將 .ava/ 加入您的 .gitignore（Git 被告知不納入共享專案的檔案清單）。將 instructions.md 保留在倉庫（共享專案資料夾）中——這就是 Ava 學習專案慣例的方式。","reference.shortcuts#title":"鍵盤快捷鍵","reference.shortcuts#0#p":"鍵盤快捷鍵是可選的加速功能——每一個都有對應的按鈕可以點擊。只有當您想透過鍵盤更快速地操作 Ava 時，才需要查看這裡。","reference.shortcuts#1#p":"依介面分類的快捷鍵（Ava 運行的三個地方：VS Code 擴充功能、桌面應用程式和終端機）。您可以在各個介面的設定中自訂它們。無需記住下方的列表。","start.for-non-coders#title":"從未寫過程式碼？從這裡開始","start.for-non-coders#0#p":"如果你從未寫過一行程式碼，你就是 Ava 的目標對象。你不需要學習任何術語就能開始 —— 你用普通的英文跟她說話，就像問一位博學的朋友一樣。這一頁就是你完整的入門指南。","start.for-non-coders#1#h":"今天無經驗也能做的事","start.for-non-coders#2#li0":"用平常的話問她任何事 —— 「這個檔案是做什麼的？」、「為什麼我的頁面是空的？」、「資料庫到底是什麼？」她用簡單的語言回答，並記住對話內容。","start.for-non-coders#2#li1":"從零開始學習某樣東西 —— 說「從零教我 Python」，她會為你建立一套完整的課程，包含課程和測驗。這永遠是免費的。","start.for-non-coders#2#li2":"完成某個建構 —— 描述你想要的（「一個按鈕可以下載我的筆記」），她會把它寫出來，在發生之前向你展示每一個變更。","start.for-non-coders#3#h":"你不需要理解所有事情","start.for-non-coders#4#p":"Ava 背後有很多機制 —— 模式、模型、專家、路由。你會在這款應用程式和這些文件中看到這些詞彙。這裡的秘密是：你可以忽略幾乎所有這些內容。Ava 會自動為你選擇正確的工具和正確的助手。技術頁面是為了當你好奇時才看的，不是因為你需要它們才能開始。","start.for-non-coders#5#h":"溫和的第一步","start.for-non-coders#6#li0":"安裝 Ava（下一頁）並開啟對話。","start.for-non-coders#6#li1":"輸入你真正想問的問題。任何問題。看看她如何回答。","start.for-non-coders#6#li2":"嘗試學習模式：輸入「教教我」和一個主題。跟著做。","features.unified-panel#title":"整合面板","features.unified-panel#0#p":"簡單來說：Ava 做的所有事情都在一個視窗裡，所以你永遠不用透過分頁搜尋它。","features.unified-panel#1#p":"一個面板涵蓋聊天、儀表板、記憶、任務和日誌。無需在不同視窗間切換情境。側邊欄選擇你看的是什麼；主區域會相應切換。","features.unified-panel#2#p":"導航離開時對話狀態會保留——打開記憶、檢查任務，然後回來。聊天依然存在，如果 Ava 仍在運行，仍會持續串流。","features.unified-panel#3#c":"整合面板是擴充功能和 IDE 概念。網頁介面使用瀏覽器分頁。","features.knowledge-packs#title":"知識包","features.knowledge-packs#0#p":"簡單來說：給 Ava 一個你自己的文件資料夾，她就能閱讀它們來回答你的問題。「知識包」就是那組檔案——她獲准參考的資料。","features.knowledge-packs#1#p":"將參考資料目錄（規格書、RFC、會議記錄、API 文件）拖入知識包。當對話觸及主題時，Ava 能將相關部分拉入上下文。","features.knowledge-packs#2#p":"包會在本地索引。檢索是語義式的——Ava 根據意義而非檔名找到正確文件。（「語義式」意味著她匹配文件的主題，所以你不需要記住確切字詞或檔名。）包可以與團隊共享或保持私密。","features.office-suite#title":"Office Suite","features.office-suite#0#p":"需要撰寫報告、電子郵件或文件嗎？Ava 可以起草並提供給您一份標準的 Word、Excel 或 PDF 檔案，讓您能像一般檔案一樣開啟和編輯。","features.office-suite#1#p":"報告、電子郵件和文件——起草、格式化並匯出為原生格式（.docx 是 Word，.xlsx 是 Excel，.pdf 是 PDF）。","features.office-suite#2#li0":"report_generate —— 從任務、日誌、記憶和專案狀態提取結構化的 .docx。","features.office-suite#2#li1":"email_draft —— 控制語氣的電子郵件轉為 .docx 檔案。","features.office-suite#2#li2":"document_manage —— 在 Word、Excel、PDF、CSV、Markdown 之間建立、讀取、編輯、匯出。","features.office-suite#3#p":"當 Ava 代您撰寫時非常有用——狀態報告、啟動簡報、客戶更新。.docx 會出現在您的專案中，您可以在此潤飾它。","features.dashboard-library#title":"儀表板庫","features.dashboard-library#0#p":"簡單來說：一個架子存放您和 Ava 製作及談論過的一切，讓任何東西都不會遺失。","features.dashboard-library#1#p":"瀏覽您與 Ava 共同產出的所有內容——生成的圖片、影片、音訊、文件——以及您的對話、記憶和任務。一個地方即可找到您上週製作的東西。","features.document-preview#title":"文件預覽","features.document-preview#0#p":"簡單來說：就在您目前的位置直接查看文件內容，不用另外打開程式來讀。","features.document-preview#1#p":"在您的專案中右鍵點擊 Word 文件、Excel 試算表、PDF、CSV、HTML 或 Markdown 檔案——在不離開編輯器的情況下內嵌預覽。對於閱讀 Ava 生成的參考資料或合作夥伴放入的檔案很有用。","features.daily-briefing#title":"每日簡報","features.daily-briefing#0#p":"簡單來說：每天早上給您一則簡短的「您上次做到哪裡了」備忘，讓您能直接接續，不用重新閱讀所有内容。","features.daily-briefing#1#p":"早晨摘要：昨天的日誌、待辦任務、專案狀態，以及 Ava 設定的任何提醒。選填項目——在設定中開啟即可。","features.daily-briefing#2#p":"簡報運用記憶呈現相關情境（「上次您處理驗證流程時，提到想重新檢視重新整理令牌的策略」）。這不是新聞資訊流——而是專注的回顧。","features.workflows#title":"工作流程","features.workflows#0#p":"簡單來說：教導 Ava 一個你反覆執行的例行任務，幫它取個名字，她就能隨時再次執行整套流程。「工作流程」就是這個已保存的例行任務——一套 Ava 為你重複執行的步驟。","features.workflows#1#p":"保存一組你經常重複的步驟序列——審查合併請求 → 執行測試 → 撰寫發行說明 → 草擬郵件。工作流程是一個可重用的計劃，Ava 可以用不同的輸入內容重新播放。","features.workflows#2#p":"工作流程會依專案儲存於專案內的 .ava/workflows/ 資料夾中。透過提交該目錄（將其保存到共享專案中），即可與團隊成員分享（讓隊友也能取得）。","features.events#title":"事件與通知","features.events#0#p":"簡單來說：當 Ava 工作時，你會看到整齊的逐步清單，顯示她在做什麼；長任務完成時也會收到通知，讓你暫時離開。","features.events#1#p":"當 Ava 運行時，你看到的是結構化的更新，而不是一大堆文字。每個工具呼叫、每次角色交接、每段流式更新都是 UI 中的獨立事件——可展開查看細節，也可收合查看概覽。","features.events#2#p":"背景運行在完成時會發出作業系統層級的通知。你可以離開進行長時間的建置，Ava 會在完成時告訴你。","features.personality#title":"人格設計器","features.personality#0#p":"簡單來說：調整 Ava 與你交談的方式——健談或簡潔、正式或隨意、多一點幽默或少一點——讓她說話的方式符合你的喜好。","features.personality#1#p":"塑造 Ava 與你交談的方式。語氣、能量、詳盡程度（她說多少話）、正式度、幽默感。提供滑桿和預設設定——簡練工程師、溫暖導師、嚴肅同事，或是你自己的混合風格。","features.personality#2#p":"人格設定影響措辭，不影響能力。她仍執行相同的工具並遵循相同的權限規則。她的名稱鎖定為 Ava——這一點不可妥協。","features.release-notes#title":"發行說明","features.release-notes#0#p":"簡單來說：列出每個更新中新增了什麼以及修復了什麼的持續清單，讓你能夠查看變更內容。","features.release-notes#1#p":"應用程式內更新日誌（更新日誌是變更歷史）。每個發布版本及其亮點、錯誤修復和破壞性變更（可能需要你調整使用方式的變更）。網頁版在 ava-supernova.com/releases 維護公開版本。","troubleshooting.logs#4#c":"日誌可能包含 Ava 在會話期間讀取的專案檔案片段。分享前請先檢視。","troubleshooting.support-request#title":"提出支援請求","troubleshooting.support-request#0#p":"簡單來說：如果出了問題且上述修復方法無效，請告訴我們。最簡單的方式是直接請 Ava 幫您處理。","troubleshooting.support-request#1#p":"如果問題不在常見錯誤範圍內，請提交支援工單（向支援團隊發送求助請求）。您可以在 Ava 內部操作（無需填寫表單），也可以透過網頁進行。","troubleshooting.support-request#2#h":"從 Ava 內部","troubleshooting.support-request#3#p":"請她來提交。「Ava，你能為這個問題提交支援工單嗎？」她會呼叫 support_request，附上相關的會話內容（已隱藏憑證），然後發送。這是最快的途徑。","troubleshooting.support-request#4#h":"從網頁","troubleshooting.support-request#5#p":"請造訪 ava-supernova.com/support。選擇類別（錯誤、功能、帳號、安全、一般）並描述發生的狀況。我們將於一個工作天內回覆。","troubleshooting.support-request#6#h":"需要包含的內容","troubleshooting.support-request#7#li0":"您原本想做的事。","troubleshooting.support-request#7#li1":"實際發生的狀況。","troubleshooting.support-request#7#li2":"使用哪個介面（擴充套件、IDE、CLI、伴隨程式）以及版本為何。","troubleshooting.support-request#7#li3":"任何錯誤訊息或日誌片段。請先隱藏憑證。","troubleshooting.security-disclosure#title":"回報安全問題","troubleshooting.security-disclosure#0#p":"簡單來說：如果您發現 Ava 可能被入侵或濫用的方式（稱為「漏洞」— 安全弱點），請先私下告訴我們，以便我們在他人利用之前修復它。本頁即說明如何操作。","troubleshooting.security-disclosure#1#p":"發現漏洞？謝謝您。我們重視每一份回報，並在公開披露（問題被公開宣布）之前與您合作修復。","troubleshooting.security-disclosure#2#h":"如何回報","troubleshooting.security-disclosure#3#li0":"寄信至 security@ava-supernova.com，附上描述、重現步驟及您偏好的揭露時間窗。","troubleshooting.security-disclosure#3#li1":"或者提交類別為「安全」的支援工單——進入相同的分流隊列。","troubleshooting.security-disclosure#3#li2":"我們會在 24 小時內確認收到。","troubleshooting.security-disclosure#4#h":"我們的承諾","troubleshooting.security-disclosure#5#li0":"協調揭露 — 我們會與您協議時程，確保在公開前完成。預設為 90 天。","troubleshooting.security-disclosure#5#li1":"署名 — 除非您希望匿名，否則您的名字將出現在修復紀錄中。","troubleshooting.security-disclosure#5#li2":"無法律報復 — 歡迎善意研究。我們不會派律師找上門。","troubleshooting.security-disclosure#6#c":"ava-supernova.com/security 的安全頁面涵蓋完整的防護架構 — 架構保證、遮蔽工具、權限管控。","reference.project-context#title":"專案情境","reference.project-context#0#p":"這解釋了 Ava 在開始工作前如何了解你的專案——她查看的檔案來理解你在做什麼。你不需要設定這些；她自己會處理。如果你想讓她隨時看到某個筆記，可以閱讀此處了解應該把筆記放在哪裡。","reference.project-context#1#p":"當你開啟專案時，Ava 會載入多層次的背景資訊（她腦海中持有的資料）。了解這些層次能幫助你把資訊放在正確的地方。","reference.project-context#2#h":"自動載入","reference.project-context#3#li0":".ava/instructions.md — 視為持久且高優先級的指導。始終在上下文中。","reference.project-context#3#li1":".ava/context.md — 自由形式的筆記。載入，但優先級較低。","reference.project-context#3#li2":"README.md — 首次執行時掃描以獲取專案摘要。","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — 列出專案設定的小型檔案；用於偵測語言、框架和測試指令。","reference.project-context#3#li4":".gitignore — 版本控制中要排除的檔案清單；所有檔案工具（glob, grep, project_index）都會遵守。","reference.project-context#4#h":"按需載入","reference.project-context#5#p":"「按需」意味著 Ava 只有在任務真正需要時才會取得這些內容，而不是一開始就全部載入。","reference.project-context#6#li0":"專案索引 — 你檔案的結構化地圖，以及其中的命名區塊（函式、類別 — 「符號」）和它們如何連接（「匯入」）。惰性建構，意指僅在 Ava 需要時才建立。","reference.project-context#6#li1":"Git 歷史記錄 — 過去變更的紀錄；當呼叫 `git_status`, `git_diff` 或 `git_create_pr` 時取得（Git 是用來追蹤專案每項變更的工具；「PR」是拉取請求，即一組擬議的變更）。","reference.project-context#6#li2":"記憶 — 條目會根據意義（「語意上」）進行匹配，並一次只注入一輪，而非一次性全部注入。","reference.project-context#7#c":"將規範放入 instructions.md。將筆記放入 context.md。讓記憶自行捕捉其餘部分。","reference.models#11#h":"自帶金鑰","reference.models#12#p":"「API 金鑰」就像一個私密的密碼，讓軟體能在你自己的帳戶上使用付費服務。「BYOK」就是「自帶金鑰」的意思——用你自己的，而不是我們的。將你的 API 金鑰貼到設定中。BYOK 請求會直接從 Ava 傳送至提供者（運行模型的廠商）——不會經過我們的基礎設施，也不會消耗平台代幣。你向提供者付費；我們看不到流量。","reference.models#14#c":"關於基準分數、能力標籤和並排過濾，請參閱 ava-supernova.com/models 上的完整模型頁面。上方顯示的價格是我們發布時對各提供者費率表的最佳解讀——在投入工作負載前，請務必先檢查提供者網站。","reference.personas#title":"角色調度","reference.personas#0#p":"「角色」是 Ava 在幕後為處理困難任務所扮演的助手職責——例如探索者、規劃者或事實查核員。你不會直接與它們對話，也不需要理解本頁內容即可使用 Ava。這裡是為了當你好奇她如何將大任務拆解成小專家團隊時參考。","reference.personas#1#p":"跨 5 個模式團隊的 24 位專家。指揮官（負責協調其餘成員的助手）決定哪個團隊運行、順序為何以及使用什麼上下文。聊天模式沒有角色——那就是 Ava 本人。","reference.personas#2#h":"調度如何運作","reference.personas#3#li0":"你在計劃、教學、安全或發想模式中發送訊息（或是複雜的工作請求）。","reference.personas#3#li1":"指揮官閱讀請求，選擇模式團隊，並建立執行計畫——某些角色依序運行，某些則以平行波次運行。","reference.personas#3#li2":"每個角色都有自己的系統提示詞、受限的工具白名單，以及先前角色發現內容的共享上下文池。","reference.personas#3#li3":"最終角色會產生摘要、計畫或報告，視模式而定。","reference.personas#3#li4":"Ava 將結果呈現給你。你可以批准、微調或重新導向。","reference.personas#4#p":"下方的完整名冊僅供參考——無需記住誰負責什麼。Ava 會為你組建合適的團隊。","reference.personas#6#c":"工作模式僅在複雜任務時才會調用完整團隊。簡單編輯由 Ava 直接執行——無需調度開銷。","troubleshooting.common-errors#title":"常見錯誤","troubleshooting.common-errors#0#p":"大多數錯誤背後都有明確且具體的原因。這裡列出常見的狀況及解決方法。如果文字看起來有點技術性，別擔心——下面每個項目都會告訴你實際發生了什麼，以及該怎麼做。","troubleshooting.common-errors#1#h":"模型無回應","troubleshooting.common-errors#2#p":"你看到的：Ava 不再回應。","troubleshooting.common-errors#3#p":"檢查聊天視窗頂端的狀態指示器。如果顯示「正在連接」，代表你的提供者（Ava 正在對話的 AI 服務）有連線但速度較慢——請再等三十秒。如果顯示「無法使用」，Ava 已自動回退到鏈中的下一個模型（也就是自動切換到了備用模型）。如果完全沒有任何顯示，請在設定中檢查你的 API key 並測試連線。（API key 就像是讓 Ava 能使用付費 AI 服務的私密密碼。）","troubleshooting.common-errors#4#h":"工具呼叫失敗","troubleshooting.common-errors#5#p":"你看到的：Ava 的其中一個步驟（「工具呼叫」— 讀取檔案、執行指令等）顯示紅色錯誤，而非完成。","troubleshooting.common-errors#6#p":"點擊失敗的工具呼叫來查看錯誤訊息。常見原因包括：她試圖存取專案資料夾之外的檔案，這是為了安全起見而設定的阻擋（這項防護稱為「路徑穿越」保護，目的是防止她離開你正在工作的資料夾範圍）；或是需要在不同資料夾執行的指令；又或是檔案在 Ava 上次檢視後已被移動。直接告訴她哪裡出了問題，她就會修正後重新嘗試。","troubleshooting.common-errors#7#h":"記憶無法召回","troubleshooting.common-errors#8#p":"你看到的：Ava 找不到某些東西，但你確定她應該記得。","troubleshooting.common-errors#9#p":"記憶運作是基於「意義」，而非精確的字詞（這正是「語意」的含義）。因此，問「關於認證我做了什麼決定？」通常比「尋找我的認證決定」效果更好。如果記憶確實存在卻沒出現，請開啟記憶瀏覽器進行搜尋——如果裡面沒有，那就代表當初根本沒有儲存過。","troubleshooting.common-errors#10#h":"登入循環","troubleshooting.common-errors#11#p":"你看到的：你已經登入，但 Ava 一直要求你再登入一次——這是一個無法突破的循環。","troubleshooting.common-errors#12#p":"解決方法是清除儲存的登入資訊並重新開始：在擴充功能中，從命令面板執行「Ava: Sign Out」；在 IDE 中，前往設定 → 帳號 → 登出；在 CLI 中，刪除位於 ~/.ava/auth.json 的檔案（這是你家目錄下 .ava 資料夾中的一個小型登入檔）。之後再次登入即可。","troubleshooting.common-errors#13#h":"Token 耗盡","troubleshooting.common-errors#14#p":"你看到的：提示訊息說你本月的免費用量已用完。（「Tokens」是用來衡量 AI 用量的單位——「耗盡」只是表示你用完了本月免費額度。）","troubleshooting.common-errors#15#p":"免費方案的每月額度會在每個月 1 日重置。在那之前，請切換到 BYOK 提供者（使用你自己的 API key）以繼續使用。你的帳戶仍然有效——僅限免費平台管理的請求暫時暫停。","troubleshooting.logs#title":"日誌存放位置","troubleshooting.logs#0#p":"「日誌」就像電腦記錄發生事情的日記——當某個環節出錯，而你（或支援團隊）需要查看細節時很有用。","troubleshooting.logs#1#p":"當你想知道原始情況——例如呼叫了什麼工具、獲得了什麼資訊、AI 服務回傳了什麼——日誌就是位於你電腦上 ~/.ava/logs/ 資料夾中的純文字檔案（這是你家目錄下名為 .ava 的資料夾，裡面有一個 logs 資料夾）。","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — 每次會話的紀錄，包含工具呼叫、串流回應和錯誤。","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — VS Code 擴充功能主機日誌。啟動失敗、面板錯誤。","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — 桌面 IDE 日誌。Sidecar 進程訊息、Rust 崩潰。","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — CLI REPL 日誌。","troubleshooting.logs#3#p":"在擴充功能中，於命令面板選擇「Ava: Show Logs」即可在編輯器分頁開啟相關日誌。在 IDE 中，設定 → 診斷頁面有一個「開啟日誌」按鈕。CLI 則可以使用 `ava logs --follow` 來追蹤其自身日誌。","start.what#title":"什麼是 Ava？","start.what#0#p":"Ava 是一位真正能做事的 AI，不只是會說話而已。她能為你建立應用程式、撰寫文件、從頭教你新技能、設計 Logo，或是處理那些你總是一直擱置的行政瑣事。她還記得你：正在進行什麼專案、偏好什麼樣的方式、上週提過什麼請求。","start.what#1#p":"只有一位 Ava，無論你在哪裡工作，她都在那裡——在你的程式碼編輯器中、作為桌面應用程式、在手機上，或是在終端機裡。記憶相同，個性相同，處處如一。","start.what#2#h":"她的獨特之處","start.what#3#li0":"預設屬於你。你的工作始終保留在你自己的裝置上。絕不追蹤，絕不收集遥測數據。","start.what#3#li1":"完全公開透明。Ava 的每一行程式碼都對外公開。無需盲目信任。","start.what#3#li2":"免費起步。每月提供 300 點數，不需綁定信用卡，也沒有隱藏條件——或者你可以接入自己的 AI 金鑰，完全不用付我們費用。","start.what#3#li3":"教學永遠免費。學習不該標價。","start.what#4#p":"從未寫過程式碼嗎？下一頁就是專為你準備的。已經具備技術背景？直接跳過就好——她能跟得上你的節奏。","start.what#deeper#0#h":"Ava 住在哪裡","start.what#deeper#1#li0":"VS Code 擴充套件——Ava 伴隨在你的編輯器旁：包含聊天面板、儀表板，以及操作發生前即時顯示的內聯變更。","start.what#deeper#1#li1":"桌面 IDE——獨立應用程式，所有功能整合在單一視窗中。支援桌面控制（開啟應用程式、點擊、替你輸入文字）。","start.what#deeper#1#li2":"夥伴——行動應用程式，適合不在桌前時使用：管理任務、記錄日誌、存取記憶、快速聊天。","start.what#deeper#1#li3":"CLI——終端機中的 Ava，專為習慣在終端機工作的人設計。","start.what#deeper#2#h":"簡述運作方式","start.what#deeper#3#p":"Ava 會根據任務切換思維模式（稱為「模式」），在複雜工作中悄悄調用一組專業助手團隊，並自動為每個步驟挑選最適合的 AI 模型。你完全無需管理這些細節。核心概念章節提供了完整導覽，隨時歡迎探索。","start.first-five#title":"與 Ava 的第一次互動","start.first-five#0#p":"體驗 Ava 最快的方法，就是請她完成一件實際任務，然後看著她執行。無需閱讀設定說明，也無需先學習什麼——直接用自然語言告訴她你想要什麼。","start.first-five#1#h":"現在試試看","start.first-five#2#li0":"開啟對話。","start.first-five#2#li1":"輸入你真正想做的事。例如輸入「解釋這個專案在做什麼」，或「新增一個清除表單的按鈕」。","start.first-five#2#li2":"Ava 會先展示她打算怎麼做——然後暫停等待。","start.first-five#2#li3":"滿意嗎？確認同意。接著看她執行。","start.first-five#3#p":"這就是完整的流程：你提出請求，她展示計畫，你確認後，她才執行。她絕不會在未先展示的情況下修改任何內容——所以即使嘗試也不會弄壞東西。","start.first-five#4#h":"值得詢問的一些事項","start.first-five#5#li0":"一個問題 — \"為什麼我的頁面是空的？\", \"這個檔案是做什麼的？\"","start.first-five#5#li1":"想建立東西 — \"幫我做一個簡單的待辦事項頁面\"。","start.first-five#5#li2":"為了學習 — \"從零開始教我 Python\"。(永遠免費。)","start.first-five#5#li3":"一份文件 — \"幫我寫一份單頁專案提案\"。她會給你 Word 檔案或 PDF。","start.first-five#6#c":"不知道要輸入什麼？像跟博學的朋友聊天一樣跟她對話。用普通的詞彙就對了——你完全不需要技術術語就能上手。","start.first-five#deeper#0#p":"那個簡單的迴圈在幕後其實做了不少事。使用 Ava 你不需要懂這些——但如果你好奇，這裡是實際發生的情況。","start.first-five#deeper#1#h":"工具與授權","start.first-five#deeper#2#p":"當 Ava 讀取檔案、執行指令或編輯程式碼時，每一項都算是「工具呼叫」。在觸及你的檔案或系統之前，她都會先詢問——她詢問的頻率由你的權限模式設定（每次都問、只對危險操作問、或直接進行）。","start.first-five#deeper#3#h":"模式 —— 她的心態狀態","start.first-five#deeper#4#p":"Ava 以模式運作：心態加上適合該任務的工具組。隨時可以從選單切換，或在訊息開頭輸入前綴。總共有七種。","start.first-five#deeper#6#h":"專家與路由","start.first-five#deeper#7#p":"面對較複雜的工作，Ava 會在幕後運行一個小型專家團隊（規劃者、檢查者、建構者），並將每個步驟路由到最擅長的模型。你無需管理任何部分——她會為你協調一切。","start.local-vs-cloud#title":"本地與雲端，一段話說明","start.local-vs-cloud#0#p":"除非你明確選擇加入，否則 Ava 做的所有事情都是本地的。記憶、任務、日誌、人格、設定——全部儲存在你的機器上，位置在 ~/.ava/ 和 .ava/（依專案）。她透過 HTTPS 與模型供應商交談以執行你的請求，然後返回本地。她不主動回傳數據。她不收集遙測資料。她不利用你的程式碼進行訓練。","start.local-vs-cloud#1#p":"如果你登入，每月可獲得 300 個免費額度用於平台管理的模型（Qwen, MiniMax），以及跨機器的記憶與設定雲端同步選項。同步是按功能設定的，隨時可撤銷。自帶 API 金鑰，Ava 即可在不帳號的情況下完全運作。","start.local-vs-cloud#2#c":"規則：本地至上。雲端為輔。","start.first-model#title":"我需要選擇 AI 嗎？","start.first-model#0#p":"令人寬慰的是：你不用挑選 AI。Ava 會自動為每個步驟選擇合適的那一個，讓你得到好結果而無需費心思考。","start.first-model#1#p":"唯一你能選擇的是路由風格——預設值適合絕大多數人。你只需要其他選項才有特定理由。","start.first-model#2#h":"三種風格","start.first-model#3#li0":"Maestro —— 預設值。穩健、可靠、可預測。不確定？選這個就對了。","start.first-model#3#li1":"Supernova —— 適用於繁重、多步驟的工作，在任務各部分指派不同專家是有利的。","start.first-model#3#li2":"Aurora —— 適用於你的資料必須留在歐盟的情況（公共部門、醫療保健、嚴格隱私）。完全運行於歐洲開放權重 AI。","start.first-model#4#p":"隨時可以在對話框頂部的模型選單中切換。沒有鎖定。","start.first-model#5#c":"想自己驅動某個特定模型？你可以——開啟「顯示詳細資訊」。","models.routing#deeper#1#h":"並排比較","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"協調者","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro（1.6T / 49B 活躍，1M 上下文）","models.routing#deeper#2#td0.3":"Mistral Large 3（675B / 41B 活躍，262K 上下文）","models.routing#deeper#2#td1.0":"建構者","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus（沿用協調者模式）","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5（128B 稠密，256K 上下文）","models.routing#deeper#2#td2.0":"中階專家","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash（程式碼審查、事實查核、偵察、掃描、安全驗證等）","models.routing#deeper#2#td2.3":"Mistral Medium 3.5（架構師、驗證者、流程規劃、導師、匯報者等）","models.routing#deeper#2#td3.0":"輕量級 / 意圖篩選","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash（偵察、驗證者、流程規劃、挑戰者、整合者）","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"重量級專家","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3（研究員、挑戰者、CVE 研究員、創意發想、事實查核）","start.glossary#1#td7.1":"Ava 用來計算行動成本的簡易單位，你不需要操心 token 計算。方案內含每月額度。","start.glossary#1#td8.0":"API 金鑰","start.glossary#1#td8.1":"一種私密密碼，讓軟體能在你的帳戶上使用付費服務（像是 AI 模型）。如果你打算自備，才需要這個。","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"「自帶金鑰。」使用你自己的 API 金鑰，而非 Ava 的管理存取方式。選填 — 適合那些已經直接向供應商付費的人。","start.glossary#1#td10.0":"本地優先","start.glossary#1#td10.1":"預設情況下，你的資料都存放在你自己的電腦上。除非你開啟同步，否則什麼都不會上傳。「本地是神聖的。」","start.glossary#1#td11.0":"權限模式","start.glossary#1#td11.1":"這代表 Ava 在執行動作前有多謹慎 — 每次都要問、僅針對高風險事項詢問，或是直接執行。等級由你設定。","start.glossary#1#td12.0":"上下文視窗","start.glossary#1#td12.1":"模型一次能在腦海中保留多少文字 — 也就是它的短期記憶。「1M 上下文」大約是一百萬個字。越大表示它能閱讀更多內容後才遺忘。","start.glossary#1#td13.0":"差異比對","start.glossary#1#td13.1":"一個並排檢視，顯示檔案將發生的具體變更 — 舊版在一邊，新版在另一邊 — 在 Ava 修改之前顯示給你核准。","start.glossary#1#td14.0":"儲存庫（倉庫）","start.glossary#1#td14.1":"追蹤變化的專案資料夾，通常搭配 Git 使用。如果這聽起來還很陌生，它只是「存放我專案的資料夾」。","start.glossary#1#td15.0":"提示詞","start.glossary#1#td15.1":"你輸入給 AI 的內容 — 你的問題或指示。","start.glossary#2#c":"還在卡在某個單字嗎？在聊天模式中問 Ava — 「X 是什麼意思？」 — 她會用適合你的程度解釋。","models.routing#title":"路由選擇 — Ava 如何挑選模型","models.routing#0#p":"簡短版本：你永遠不需要選擇要用哪個 AI 模型。Ava 會幫你做決定，為工作的每個部分挑選最佳工具 — 就像一位好經理把正確的任務交給正確的人一樣。","models.routing#1#p":"你可以從三種風格中選擇一種 — Maestro、Supernova 或 Aurora — 然後 Ava 會將每項工作發送到最適合處理它的模型。Maestro 是預設值，在所有方案中都可用，對幾乎所有人來說都是不錯的選擇。","models.routing#2#h":"為什麼要進行路由選擇？","models.routing#3#p":"在每個步驟使用合適的模型，成本比把所有事情都放在一個昂貴的大型模型上運行更低 — 並且結果更好，因為每個模型都做它最擅長的事。你獲得穩定的成本和優質的結果，完全不需要知道哪個模型是哪個。","models.routing#4#c":"所有三種風格都能使用平台點數或你自己的金鑰運作。使用你自己的金鑰時，你也可以跳過路由，直接驅動單一模型。完整的機隊細項位於「向我展示詳情」下方。","models.routing#deeper#0#c":"下方的「B」數字代表數十億個參數 — 大致相當於模型大腦的大小；越大通常越聰明但更慢且更貴。這是幕後的技術細節；使用 Ava 時你完全不需要了解它。","credits.overview#8#li4":"協調 — 10 積分。完整人設流程啟動（指揮官 + 多個人設任務）。","credits.overview#8#li5":"圖像生成 — 12 積分。透過 Creative Studio 使用 Hailuo image-01。","credits.overview#8#li6":"影片生成 — 150 積分。Hailuo 02 Pro 1080p 6 秒片段。","credits.overview#8#li7":"語音生成 — 10 積分。Speech 2.8 HD 合成。","credits.overview#8#li8":"音樂生成 — 50 積分。MiniMax Music 2.5/2.6。","credits.overview#8#li9":"背景移除 — 2 積分。","credits.overview#9#h":"各模型倍率","credits.overview#10#p":"這部分是給好奇的你看的 — 不用懂這些也能用 Ava。倍率只是根據背後模型的消耗程度來調整積分成本，模型越重，花費就稍高一些。（「淨利潤」是專案在支付自身成本後保留的份額 — 我們設定得較低，好讓價值能回饋給你。）","credits.overview#11#p":"較重的模型會放大動作成本，讓積分反映實際花費，而不是固定在某個檔位。校準目標為約 55% 淨利潤。","credits.overview#12#li0":"0.6× — Mistral Small 4（Aurora 的專家席位）。低於 1×，因為 Mistral Small 4 比 Qwen 3.6 Plus 基準更便宜。","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash、Qwen Omni Flash、DeepSeek V4 Flash、MiniMax。基準費率。","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus、Qwen 3.5 Omni Plus。","credits.overview#12#li3":"1.4× — Mistral Large 3（Aurora 協調者）。與 Qwen 3.6 Plus 基準相當。","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus（Maestro 協調者）。","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro（Supernova 協調者 + 重型專家）。從 5.0× 重新校準，以在公布的 V4 Pro 費率下恢復利潤平衡。","credits.overview#13#c":"Anthropic 模型（Claude Opus / Sonnet / Haiku）完全跳過積分計費 — 它們僅限 BYOK，你直接付費給 Anthropic。其他任何 BYOK 供應商搭配你自己的金鑰使用時也是一樣。","credits.overview#14#h":"BYOK 與積分","credits.overview#15#p":"BYOK（「自帶金鑰」— 你提供自己的 AI 供應商帳戶和金鑰，這是一個私人密碼，讓軟體可以使用該付費帳戶）適合已經直接向 AI 供應商付費的人。如果你不是這樣，可以完全忽略本節。","credits.overview#16#p":"自帶金鑰請求完全繞過平台基礎設施 — 呼叫直接從 Ava 發送到供應商，你向供應商付費，不消耗積分。唯一的例外是當 BYOK 會話為子任務啟動管理層級人設時；仍會扣除積分，因為使用了 Ava 的協調介面。","credits.overview#17#h":"哪裡查看餘額","credits.overview#18#li0":"擴充套件 — 設定 → 帳戶，或是聊天標頭的積分標示。","credits.overview#18#li1":"IDE — 帳戶儀表板圖塊顯示當前餘額和消耗速率。","credits.overview#18#li2":"網頁版 — ava-supernova.com/dashboard 顯示餘額、歷史記錄和續期日期。","credits.overview#19#c":"本地優先：Ava 在自訂模型卡上無需帳戶即可運作（Ollama、LM Studio、vLLM，或任何 OpenAI 相容端點）。無積分、無平台令牌 — 你的模型、你的機器、零費用。","concepts.modes#title":"模式 — Ava 的心智狀態","models.routing#deeper#2#td5.0":"對話","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"圖像生成工作流","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"視覺識別","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (視覺編碼器從零開始訓練)","models.routing#deeper#2#td8.0":"長篇寫作","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"數據存放位置","models.routing#deeper#2#td9.1":"混合（阿里雲）","models.routing#deeper#2#td9.2":"混合（DeepSeek + 阿里雲）","models.routing#deeper#2#td9.3":"僅限歐盟 · 權重公開","models.routing#deeper#2#td10.0":"狀態","models.routing#deeper#2#td10.1":"已上線 · 所有方案","models.routing#deeper#2#td10.2":"即將推出","models.routing#deeper#2#td10.3":"即將推出","models.routing#deeper#2#td11.0":"最適合","concepts.interjection#1#p":"Ava 會執行直到計劃完成或你停止她。在她運行時，你有兩種介入方式（這個動作稱為「干預」）。","concepts.interjection#2#h":"介入 —— 導向但不取消","concepts.interjection#3#p":"當 Ava 工作時輸入新訊息。她會先完成目前的工具呼叫，讀取你的訊息，然後調整計劃。不會遺失任何上下文。當你想要在中途重定向、補充資訊或改變優先級時使用此功能。","concepts.interjection#4#h":"強制停止 —— 取消並清除","concepts.interjection#5#p":"按下 Escape (CLI)、點擊停止 (擴充套件、IDE)，或輸入停止指令。目前的執行會被取消，待處理的工具呼叫也會終止，對話準備好迎接全新的回合。","concepts.interjection#6#c":"先嘗試介入。強制停止是用於真正出錯的情況。介入能保持對話串活躍。","concepts.desktop-personas#title":"桌面角色","concepts.desktop-personas#0#p":"本頁面向好奇者及進階用戶。「桌面自動化」（有時稱為「電腦操作」）意味著 Ava 實際上可以點擊你的螢幕並為你使用應用程式——開啟 Gmail、填寫表單、發送訊息——就像坐在鍵盤前的人一樣。為了安全地做到這一點，她將工作分散給五個小助手，每個助手只有一個狹窄的角色。你無需直接與它們互動；這裡只是展示誰負責什麼。","concepts.desktop-personas#1#p":"桌面任務的每一步（Ava 驅動你的螢幕朝向目標的一次執行）都會啟動一個五人角色組。每個角色只有一份工作，且僅限一份。這種分離確保提示緊湊、輸出結構化，並且設計上保持審慎推理。","concepts.desktop-personas#2#h":"偵察兵","concepts.desktop-personas#3#p":"報告當前螢幕上可見的內容。絕不虛構元素。絕不規劃。返回包含元素 ID、名稱、邊界框、置信度和基礎來源（UIA、Playwright DOM 或 OmniParser 視覺）的 ScreenState JSON。","concepts.desktop-personas#4#h":"規劃師","concepts.desktop-personas#5#p":"決定單一的下一步行動。每步僅一個行動——絕不分批。偏好可逆路徑。根據安全本體論分類風險。輸出包含類型、目標、參數、風險類別、推理和預期後狀態預測的 ProposedAction JSON。","concepts.desktop-personas#6#h":"執行者","concepts.desktop-personas#7#p":"在通過批准閘門後，精確執行規劃師提出的內容。無即興發揮。無重試。失敗會忠實報告，由驗證器處理下一步。","concepts.desktop-personas#8#h":"驗證器","concepts.desktop-personas#9#p":"檢查行動是否成功。將新的 ScreenState 與規劃師的預測進行比較。返回 verified、deviated 或 rollback_needed。同時運行循環檢測——重複已成功的行動是偏離，而非驗證。","concepts.desktop-personas#10#h":"敘述者","concepts.desktop-personas#11#p":"這是用戶在任務過程中唯一聽到的聲音。每步一句過去式句子（「已開啟 Gmail。」、「已點擊撰寫。」）。也撰寫結構化審計日誌。出錯時會說明——絕不隱藏問題。","concepts.desktop-safety#title":"桌面安全分類體系","concepts.desktop-safety#0#p":"簡而言之：在 Ava 點擊螢幕上的任何內容之前，她會根據風險程度對行動進行分類。閱讀螢幕？無害。發送金錢或刪除內容？她總是會先停止並詢問你——每一次，絕無例外。下方的五個標籤只是那個風險梯子的階梯。這是進階用戶的細節，但重點很簡單：危險的事情總是需要你的同意。","concepts.desktop-safety#1#p":"每個建議的行動都歸類為五種風險類別之一。分類結合三個信號——螢幕上的目標是什麼、它的通俗語言描述（「語義標題」—— Ava 對自己正在看什麼的描述）、以及行動設定——當它們不一致時會升級（視為更高风险）。誤報（不需要問卻問了）只是煩人。漏報（應該問卻沒問）則是災難性事故。","concepts.desktop-safety#2#h":"五個類別","concepts.desktop-safety#3#li0":"觀察性 —— 讀取 UIA 樹、截圖、懸停。始終自動允許。","concepts.desktop-safety#3#li1":"導航性 —— 捲動、移動焦點、開啟選單。在駕駛模式下自動允許。","concepts.modes#0#p":"模式就是 Ava 當時的心態——就像同事換了帽子。還是同一個人，對你的記憶也一樣，但建造者的思考方式與老師不同。你選擇模式，就會改變她的行為和帶來的助手。隨時用模式選擇器切換，或輸入兩個字的快捷鍵即可。","concepts.modes#2#h":"你想要哪一個？","concepts.modes#3#p":"從你想做的事開始——模式會隨之而定：","concepts.modes#4#li0":"我想建立或修改某物 → 程式碼 (>>)。你描述需求，她負責建置，並先向你展示每個變更。大型任務會啟動完整的助手團隊。","concepts.modes#4#li1":"我想在變更前先有個計畫 → 計畫 (::)。她會深思熟慮後交給你一份計畫供你批准或編輯。此模式下她不會觸碰你的檔案。","concepts.modes#4#li2":"我只想聊天或提問 → 對話 (..)。一位擁有記憶、新聞和天氣功能的思考夥伴。不更動檔案，不寫程式碼——只有對話。","concepts.modes#4#li3":"我想學習某事 → 教學 (??)。為你量身打造的真實課程：課程、測驗等全套內容。所有方案永遠免費。如果你是新手，這很適合。","concepts.modes#4#li4":"我想檢查專案是否有安全漏洞 → 安全 (!!)。團隊會依照標準清單檢查常見的網頁漏洞（「OWASP」類別）和已知報告的缺陷（稱為「CVEs」），然後交出一份依問題嚴重程度排序的報告。這是針對開發者的——如果你不是，可以跳過。","concepts.modes#4#li5":"我想要點子 → 腦力激盪 (**)。她會根據你的實際情況產生選項，找出弱點的破綻，並將其餘部分精煉為下一步行動。","concepts.modes#4#li6":"我想撰寫文件 → 寫作 (<<)。報告、提案、信件、文章——她用 Markdown 起草，並匯出帶有品牌格式的 Word 文件或 PDF，逐段精修。不寫程式碼，只專注於寫作。","concepts.modes#5#c":"「助手團隊」（人設）完全在幕後運作——你從未直接與他們交談。你只會得到更詳盡的回答。你不需要知道他們的名字。","concepts.modes#6#c":"你可以在對話中切換模式。你的記憶會延續；專家們會重置以配合新模式。","concepts.tasks-journal#title":"任務與日誌","concepts.tasks-journal#0#p":"Ava 為你保存三種筆記，很容易混淆。快速記憶法：記憶是她對你的了解，任務是你仍需完成的事，日誌則是事情經過的日記。以下是使用時機。","concepts.tasks-journal#1#li0":"記憶——持久的事實。偏好、決策、模式。被反覆詢問，很少手動建立。","concepts.tasks-journal#1#li1":"任務——待辦事項。帶有截止日期和狀態的行動項目。完成時勾選。","concepts.tasks-journal#1#li2":"日誌——反思。每日記錄，雙重條目（你的和 Ava 對該次會話的觀察）。用於情緒追蹤、會話回顧、明天的背景資訊。","concepts.tasks-journal#2#p":"當合理時，Ava 會寫入所有三類。你可以從儀表板直接寫入任何一類。沒有任何內容鎖定在你使用 Ava 的單一位置——你在其中一個地方建立的任務（例如命令列工具）會自動出現在其他地方（例如桌面應用程式）。","concepts.permissions#title":"權限——你的安全旋鈕","concepts.permissions#0#p":"權限是你的安全旋鈕。它決定 Ava 是在電腦上執行動作前徵求你的同意，還是直接進行。你可以設定她詢問一切、僅詢問風險事項，或是信任她執行——且隨時可更改。若你不確定，保持預設值即可。","concepts.permissions#1#p":"Ava 有 60 個工具（「工具」是她能採取的動作——讀取檔案、搜尋網路等）。每個工具屬於一個類別（檔案操作、Shell、Git、網路、媒體、資料庫、系統、文件、記憶、學習）。每個工具呼叫在執行前都會通過權限閘門（一個決定是否先詢問你的檢查點）。你控制哪些自動批准、哪些詢問一次、哪些總是詢問。","concepts.permissions#3#p":"平衡是預設值。嚴格模式用於審計她的行為（仔細檢查每個步驟）。自主模式用於你想讓她自行執行時。","concepts.permissions#4#c":"自主不代表不受控。計畫、澄清問題和明確要求用戶輸入的提示仍會暫停等待你的輸入。不可逆的操作（如 Git force-push、資料庫刪除）無論何種模式都會確認。","concepts.interjection#title":"引導與停止 Ava","concepts.interjection#0#p":"你始終掌握主導權。當 Ava 忙碌工作時，你可以輕推她轉向新方向而不打斷節奏，或直接立刻停止她。兩個按鈕，兩種結果——這就是本頁的重點。","concepts.desktop-safety#3#li2":"可逆變更 — 在欄位輸入、貼上、開啟應用程式、瀏覽網址。Ask 模式下會確認；Drive 模式下在白名單內則自動執行。","concepts.desktop-safety#3#li3":"不可逆變更 — 發送、提交、付款、刪除、確認、發布。無論權限等級為何，一律需要確認。批准記錄永不快取。","concepts.desktop-safety#3#li4":"特權操作 — 使用者帳戶控制權限提升、sudo 指令、編輯登錄檔、憑證提示。預設禁止。每個工作階段需單次手動同意。","concepts.desktop-safety#4#h":"不儲存批准的記錄","concepts.desktop-safety#5#p":"所有競爭對手都會儲存批准記錄（記住你的「是」，下次重複使用）。這是提示詞注入攻擊最大的漏洞——一種陷阱網頁偷偷塞入隱藏指令給 AI，讓它做出對你不利的行為。如果批准被儲存，被駭的網頁就能利用你之前說過的「是」。Ava 絕不儲存。每次不可逆變更動作都會重新詢問。","concepts.desktop-safety#6#h":"機密資料處理","concepts.desktop-safety#7#p":"密碼、API 金鑰和雙重驗證代碼（登入時第二個應用程式或簡訊給你的一次性代碼）透過不透明句柄處理——即替換真實數值的佔位符。Ava 看到的是「{secret}」，而非實際密碼。真實值從不進入她的記憶、活動日誌或她「讀取」的內容——由一個獨立的底層模組在最後一刻、按下鍵盤時輸入，這樣 AI 部分就完全不會接觸到它。","reference.cli#title":"CLI 指令","reference.cli#0#p":"本頁專為 CLI 設計——即在終端機視窗中用文字與 Ava 對話的版本，而非點擊按鈕。如果你使用擴充功能或桌面應用程式，可以完全跳過此頁。這裡是給偏好使用鍵盤的人準備的。","reference.cli#1#p":"CLI 是一種互動式命令列環境——等待你輸入、執行你輸入的內容後再等待。這些斜線指令（以「/」開頭的指示）可在提示字元中使用。","reference.cli#2#li0":"/help — 列出指令與目前模式。","reference.cli#2#li1":"/mode <name> — 切換模式（work, write, plan, chat, teach, security, brainstorm）。","reference.cli#2#li2":"/model <id> — 在不離開工作階段的情況下切換模型。","reference.cli#2#li3":"/clear — 清除目前的對話。記憶不受影響。","reference.cli#2#li4":"/history — 列出此專案中的過往對話。","reference.cli#2#li5":"/memory — 開啟記憶瀏覽器。","reference.cli#2#li6":"/tasks — 列出並管理工作。","reference.cli#2#li7":"/journal — 開啟今日記事本條目。","reference.cli#2#li8":"/settings — 開啟設定選單。","reference.cli#2#li9":"/exit — 結束互動式命令列。","reference.cli#3#h":"啟動參數","reference.cli#4#p":"參數是你啟動 Ava 時加入的額外選項，每個都以「--」開頭，用來設定她的啟動方式。","reference.cli#5#li0":"--mode <name> — 以特定模式啟動。","reference.cli#5#li1":"--model <id> — 以特定模型啟動。","reference.cli#5#li2":"--permission <mode> — 嚴格 / 平衡 / 自主。","features.creative-studio#1#p":"圖片、影片、音樂和語音生成——與你的程式碼工作流整合在同一處。生成圖標、產品原型、演示影片或教學旁白。由 MiniMax 驅動。","features.creative-studio#2#h":"你能製作什麼","features.creative-studio#3#li0":"圖片——從提示詞到 PNG/JPG。背景移除只需一鍵呼叫。","features.creative-studio#3#li1":"影片——透過文字提示生成短 AI 影片（MiniMax Hailuo）。","features.creative-studio#3#li2":"音樂——包含歌詞的器樂或人聲曲目。","features.creative-studio#3#li3":"語音——可選聲音的文字轉語音。","features.creative-studio#4#p":"Creative Studio 的成本與其他功能共用同一個信用額度池——一個池子，一個數字。使用你自己的 MiniMax 金鑰（BYOK），則對你的方案免費。","features.creative-studio#5#c":"Creative Studio 符合免費層級資格。不是付費附加組件。","features.desktop-automation#title":"桌面自動化","features.desktop-automation#0#p":"簡單來說：Ava 可以接管你的滑鼠和鍵盤來為你執行任務——開啟應用程式、點擊按鈕、填寫表單——同時你在一旁觀看並批准任何重要事項。","features.desktop-automation#1#p":"Ava 的新模式，使用前綴 @@。她觀察桌面，決定要做什麼，並驅動 UI 自動化（為你控制螢幕上的應用程式）以完成任務。在你的實際機器上運行，使用你的實際憑證——而非雲端瀏覽器。推出後將適用於所有層級。","features.desktop-automation#2#h":"為什麼需要另一個？","features.desktop-automation#3#p":"其他桌面自動化產品都是你在桌前才啟動的。而 Ava 是當凌晨 2 點錯誤追蹤器響起時依然在那裡的那一個——IDE 持續運行，手機透過安全通道配對，你用一觸即可批准不可逆的操作。","features.desktop-automation#4#p":"她還能記住跨會話如何導航你的應用程式。其他代理每次都要重新學習。記憶差異化會隨著使用而累積優勢。","features.desktop-automation#5#h":"它是如何運作的","features.desktop-automation#6#p":"每個步驟都運行五種角色輪次：偵察員觀察，規劃師選擇下一步動作，執行者操作，驗證者檢查，敘述者告訴你發生了什麼。Sidecar 選擇最便宜可靠的依據——原生應用用 UIA，瀏覽器用 Playwright，若無其他可用樹狀結構則用 OmniParser 視覺。","features.desktop-automation#7#p":"請參閱概念頁面，了解安全本體概念、依據層級、緊急停止開關以及會話白名單機制。","models.routing#deeper#2#td11.1":"日常工作，費用可預測","models.routing#deeper#2#td11.2":"重度多步驟工作，每種方案都配備前沿協調器","models.routing#deeper#2#td11.3":"嚴格遵守 GDPR、公共部門、歐盟主權架構","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"分級差異化的 Qwen 路由策略，輕量級。Qwen 3.6 Plus 負責協調器、建構者、規劃、安全、腦力激盪和長上下文工作——在這些場景中，其 1M 上下文混合線性注意力機制表現出色。Qwen 3.5 Flash 處理聊天、圖像生成調度和上游意圖閘門，其 $0.07/$0.26 的價格和更快的首字生成時間（TTFT）讓它在大量低深度 token 量上勝出。Qwen 3.5 Omni Plus 負責視覺輸入（Qwen 3.6 Plus 無原生視覺）。Qwen 3.5 Plus 承擔對成本敏感的長篇工作。若主要協調器不可用，則依優先順序降級：Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash。","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"多語言集成模型。DeepSeek V4 Pro 負責協調並將每個子任務分配給最適合的專家：Qwen 3.6 Plus 運行所有建構者實例，V4 Flash 處理聊天以及中層審查/審計角色，Qwen 3.5 Flash 吸收輕量級分類工作，Qwen 3.5 Omni Plus 負責視覺輸入，Qwen 3.5 Omni Flash 調度圖像生成工具調用，Qwen 3.5 Plus 承擔對成本敏感的長篇內容撰寫者角色。關鍵處使用前沿推理能力，大部分 token 量採用閃電級經濟效益。","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"歐洲 AI 堆疊——設計上即為主權獨立。僅限 Mistral 的路由分為三層：Mistral Large 3（675B/41B 活躍稀疏混合專家模型 (MoE)）負責協調角色及需要深度的重型專家——研究員、挑戰者、CVE 研究員、構想家、事實核查員、安全驗證員——以及其稀疏 MoE 效率占優的長上下文基礎工作。Mistral Medium 3.5——於 2026 年 4 月發布的融合旗艦版，128B 稠密模型、256K 上下文、從零訓練的視覺編碼器、修改版 MIT 開源權重、77.6% SWE-Bench 驗證通過——運行實際工作層級：建構者實例、中層專家（架構師、驗證員、序列器、導師、報告員）、視覺輸入和長篇寫作。Mistral Small 4 從單一的角色擴展到同時處理聊天和圖像生成調度——其 $0.15/$0.60 的價格和可配置推理能力在高流量低深度路線上物超所值。端到端開源權重，永不離開歐盟基礎設施。Aurora 故意不會在不可用時靜默交叉路由到非 Mistral 模型；路由器會顯示錯誤——這正是它被稱為「Aurora」而非「Mistral 風味的 Maestro」的原因。","credits.overview#title":"Ava 積分 — 計費方式","credits.overview#0#p":"積分只是 Ava 計算您使用量的方式——就像手機方案的分鐘數一樣。每個方案，包括免費方案，都附帶一組積分池，而 Ava 做的每件事（回答您、製作圖片）都會消耗少量積分。這就是核心概念。下方的詳細內容供您需要精確了解各項費用時參考。","credits.overview#1#p":"Ava 以積分計費，而非原始 token。（「token」是 AI 模型讀寫的最小文字塊——大約幾個字母——大多數服務按 token 收費，這很難預測。）一個積分覆蓋一個工作單位——一次對話輪次、一個角色實例（一個助手完成任務的一部分）、一次圖像生成。脫離 token 級計量意味著您無需知道運行的是哪個模型就能知道操作的成本。無論 Maestro 將其路由給 Qwen 3.6 Plus 還是 Supernova 將其路由給 V4 Pro，同一個對話輪次的成本都是一樣的。","credits.overview#2#h":"方案","credits.overview#3#p":"每個方案都能享用所有功能——模型訪問權、Creative Studio、全部七種模式、完整的角色編排。更高層級購買更多積分和更高的速率限制上限，而非解鎖新功能。","credits.overview#4#li0":"免費 — 每月 $0。300 積分。20 請求/分鐘速率限制。無需信用卡。","credits.overview#4#li1":"專業版 — 每月 $19。5,000 積分。60 請求/分鐘。","credits.overview#4#li2":"進階版 — 每月 $39。10,000 積分。120 請求/分鐘。","credits.overview#4#li3":"企業版 — 每月 $79。20,000 積分。200 請求/分鐘。","credits.overview#5#c":"未使用的積分會在訂閱有效期間滾存——沒有強制回收。充值會累加到訂閱池中：$3 獲得 750 積分，$8 獲得 2,000 積分，$15 獲得 4,000 積分。","credits.overview#6#h":"各項費用","credits.overview#7#p":"單項操作費用清單——每次運行操作時從您的積分池中扣除的金額。（「緩存命中」是指 Ava 重複使用已完成的結果而非重新執行；此時您付費更少——費用降低 70%，或在 DeepSeek V4 Pro 等輸出密集型模型上降低 50%。）","credits.overview#8#li0":"對話輪次 — 2 積分。任何模式下的單次來回互動。","credits.overview#8#li1":"輕量呼叫 — 1 積分。意圖閘門、分類、單次讀取。","credits.overview#8#li2":"重型角色 — 3 積分。架構師、研究員、CVE 研究員、構想家（深度 ≥ 4）。","credits.overview#8#li3":"輕型角色 — 1 積分。偵察員、驗證員、序列器、挑戰者（深度 ≤ 2）。","reference.cli#5#li3":"--project <path> — 明確設定專案根目錄。","reference.desktop-budget#title":"桌面預算上限","reference.desktop-budget#0#p":"當 Ava 代表您控制桌面時——點擊、輸入文字、開啟應用程式——每次執行都稱為一次「軌跡」。本頁說明安全限制，防止任何一次執行時間過長或花費過多。重點是：她總會在超時前停下並向您確認。如果您想了解細節，數字都在這裡。","reference.desktop-budget#1#p":"每一次軌跡運行時都會受到三個同時生效的上限（硬性限制）約束。哪個先觸發就按哪個算。一旦違規，軌跡絕不會靜默繼續——Narrator（為您解說狀況的助手）會暫停並詢問您該怎麼辦。","reference.desktop-budget#2#h":"三個硬性上限（預設值）","reference.desktop-budget#3#li0":"步驟數 — 30 步","reference.desktop-budget#3#li1":"Token 預算 — 500,000 tokens","reference.desktop-budget#3#li2":"實際耗時 — 5 分鐘","reference.desktop-budget#4#h":"任務成本區間","reference.desktop-budget#5#li0":"簡單（搜尋文件、開啟頁面）— 5–10 步，~70–135K tokens，~$0.04–0.08","reference.desktop-budget#5#li1":"中等（登入、檢查日誌、下載輸出）— 15–25 步，~205–340K tokens，~$0.12–0.21","reference.desktop-budget#5#li2":"複雜（分類三個 GitHub 問題）— 25–30 步，~340–410K tokens，~$0.21–0.25","reference.desktop-budget#6#p":"上述 Token 數據是單次軌跡的技術上限，並非您的每月額度——那是以點數計算的，免費方案的每月 300 點足以涵蓋聊天、程式碼和少量自動化任務。","reference.desktop-budget#7#c":"您可以在任務開始時針對個別任務覆蓋上限，但一旦違規總會出現決策點。預算絕不會被靜默消耗掉。","reference.desktop-whitelist#title":"桌面會話白名單","reference.desktop-whitelist#0#p":"「白名單」只是您允許 Ava 在控制桌面時可以操作的應用程式和網站清單。本頁說明如何授予此權限，以及為何每次都會重置。簡短來說：她只能在您允許的地方行動，並且前往新地方前會先詢問。","reference.desktop-whitelist#1#p":"桌面會話開始時，Ava 會詢問她可以在哪裡行動。使用普通英文即可：「Gmail、Cursor、Azure 門戶。」她讀取後會向您確認匹配結果（「Gmail 網頁版、Cursor 應用程式、portal.azure.com」）。","reference.desktop-whitelist#2#h":"如何執行","reference.desktop-whitelist#3#p":"僅查看的操作——擷取螢幕截圖、讀取螢幕上按鈕與欄位的列表（即「UIA 樹」，Windows 對視窗內容的內部映射）——在任何地方都允許，因為您需要看到螢幕上的內容才能決定是否將應用程式加入白名單。任何會更改內容的操作在清單外會被阻擋；Ava 會暫停並詢問是否要將其加入。","reference.desktop-whitelist#4#h":"限定於會話，這是刻意設計","reference.desktop-whitelist#5#p":"白名單不會跨會話保留。沒有「記住此應用程式」的選項。每一個新軌跡都從全新的範圍開始。這是不便的設計——忘記重新授權是功能，不是錯誤。","reference.desktop-whitelist#6#h":"軌跡中途新增","reference.desktop-whitelist#7#p":"在軌跡進行中，您可以從標題列新增應用程式：「+ 允許應用程式」會開啟一個小型輸入框。輕觸「新增」，新應用程式即刻生效至本次會話結束。","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"想製作圖片、短片、歌曲或語音旁白嗎？只需描述需求，Ava 就能為您完成——無需設計或音訊軟體。","start.first-model#deeper#0#h":"每種風格的實際內容是什麼","start.first-model#deeper#1#p":"Maestro —— 一位指揮官（Qwen 3.6 Plus）負責所有步驟。經過生產環境調校，可靠且成本可預測。","start.first-model#deeper#2#p":"Supernova —— 前沿協調者（DeepSeek V4 Pro，1.6T 參數 / 49B 活躍，1M 上下文）將每個子任務交給專家：V4 Flash 用於大量構建，Qwen 3.6 Plus 作為備用，Qwen Omni 處理視覺。","start.first-model#deeper#3#p":"Aurora —— 僅使用 Mistral，分為三級：Mistral Large 3（協調者 + 重型專家）、Mistral Medium 3.5（128B 稠密，256K 上下文，原生視覺，修改版 MIT 開放權重，77.6% SWE-Bench 驗證），適用於建構者 + 中階 + 視覺 + 長文，以及 Mistral Small 4 在意圖閘門處。全程開放權重，絕不離開歐盟基礎設施。","start.first-model#deeper#4#h":"自帶模型 (BYOK)","start.first-model#deeper#5#p":"偏好使用自己的 AI 帳號？在設定中貼上你的提供者金鑰，你就能同時獲得這兩項功能——三種路由風格，加上選擇單一模型並完全跳過路由的選項。適合有強烈偏好、嚴格預算或測試特定模型的場景。完整提供者清單請參閱參考章節。","start.glossary#title":"通俗詞彙表","start.glossary#0#p":"這裡解釋了你在 Ava 周圍可能遇到的每個單字，無需任何先備知識。你不需要記住這些內容——遇到不懂的術語時隨時翻回來看。","start.glossary#1#th0":"詞彙","start.glossary#1#th1":"實際含義","start.glossary#1#td0.0":"代理程式","start.glossary#1#td0.1":"能為你執行動作的 AI —— 讀取檔案、執行指令、搜尋網頁 —— 而不只是聊天。Ava 就是一個代理程式：她會做事，但需經你同意。","start.glossary#1#td1.0":"模型","start.glossary#1#td1.1":"真正進行思考的 AI 大腦（Qwen、DeepSeek、Mistral 及其他）。不同模型各有擅長之處。通常你不需要挑選——由 Ava 決定。","start.glossary#1#td2.0":"模式","start.glossary#1#td2.1":"Ava 當下的心態。就像同事換帽子：建構者、寫作者、教師、規劃師、朋友。你選擇模式；這會改變她的行為方式。共有七種。","start.glossary#1#td3.0":"角色 / 專家","start.glossary#1#td3.1":"Ava 在幕後為較困難的工作運行的輔助角色——探索者、規劃師、事實查核員。想像成一個小型專家團隊。你不會直接與他們交談；由 Ava 協調他們。","start.glossary#1#td4.0":"路由","start.glossary#1#td4.1":"Ava 決定每一步使用哪個模型，讓你得到好答案又不花冤枉錢。這是自動發生的——\"路由模式\"只是選擇整體策略。","start.glossary#1#td5.0":"工具","start.glossary#1#td5.1":"Ava 可以執行的具體動作——讀取檔案、執行搜尋、發送電子郵件。\"工具呼叫\"就是她使用其中一個工具。她在執行任何風險動作前都會請求許可。","start.glossary#1#td6.0":"記號","start.glossary#1#td6.1":"AI 衡量文字的方式——大約相當於四分之三個字。模型按百萬個記號計費。大部分時候你可以忽略它。","start.glossary#1#td7.0":"信用額度"},"ja":{"start.for-non-coders#title":"コードを書いたことがない？ここから始めよう","start.for-non-coders#0#p":"これまでコードを一行も書いたことがないなら、あなたはまさに Ava のためのユーザーです。始めるために専門用語を学ぶ必要はありません——知識豊富な友人に尋ねるように、普通の英語で彼女と話せばいいのです。このページがあなたの完全な入り口です。","start.for-non-coders#1#h":"経験ゼロでも今日できること","start.for-non-coders#2#li0":"普通の言葉で何でも聞いてください——\\\"what does this file do?\\\", \\\"why is my page blank?\\\", \\\"what even is a database?\\\"。彼女は平易な言葉で答え、会話を覚えています。","start.for-non-coders#2#li1":"ゼロから何かを学ぶ——\\\"teach me Python from zero\\\"と言うだけで、レッスンとクイズ付きの適切なコースを作ってくれます。これはいつも無料です。","start.for-non-coders#2#li2":"何かを作る——欲しいものを説明する（\\\"a button that downloads my notes\\\"など）だけで、起こる前にすべての変更を見せてくれます。","start.for-non-coders#3#h":"すべてを理解する必要はありません","start.for-non-coders#4#p":"Ava には裏側で動く多くの仕組みがあります——モード、モデル、スペシャリスト、ルーティング。アプリやドキュメントの中でこれらの言葉を目にするでしょう。秘密を教えます：ほとんどは無視しても大丈夫です。Ava が自動的に正しいツールと正しいヘルパーを選んできます。技術的なページは、あなたが好奇心を持ったときのためにあるもので、始めるために必要なわけではありません。","start.for-non-coders#5#h":"優しい最初の道","start.for-non-coders#6#li0":"Ava をインストール（次ページ）してチャットを開く。","start.for-non-coders#6#li1":"持っている実際の質問を入力してください。何でも。彼女がどう答えるか見てみましょう。","start.for-non-coders#6#li2":"ラーニングモードを試す：\\\"teach me\\\"とトピックを入力。ついていきましょう。","start.for-non-coders#6#li3":"何かを実際に変更したり作成させたいときは、ただ頼んでください。Ava は必ず実行する内容を事前に示し、「はい」と答えるまで待ってくれます。","start.for-non-coders#7#c":"知らない言葉が出てきましたか？このセクションのさらに下にある「平易な用語集」が、専門知識なしですべての用語をわかりやすく説明します。","start.install#title":"インストール","start.install#0#p":"あなたの作業スタイルに合ったものを選んでください。複数の環境を使うこともできます。サインインすると、Ava はそれらの間で記憶を同期します。","start.install#1#h":"VS Code 拡張機能","start.install#2#li0":"VS Code の拡張機能パネルを開きます（Ctrl+Shift+X / Cmd+Shift+X）。","start.install#2#li1":"「Ava Supernova」と検索して、インストールをクリックします。","start.install#2#li2":"チャットパネルを開くには、Ctrl+Shift+A を押します（macOS の場合は Cmd+Shift+A）。","start.install#2#li3":"セットアップウィザードに従ってください。モデルを選び、権限モードを設定したら完了です。","start.install#3#h":"デスクトップ IDE","start.install#4#li0":"リリースページから、お使いのプラットフォーム用のインストーラーをダウンロードしてください。","start.install#4#li1":"それを実行してください。初めて起動するときは、ウェルカム画面が表示されます。","start.install#4#li2":"無料のプラットフォームトークンを受け取るにはサインインするか、あるいは独自の API キーを貼り付けて、すべてローカルで実行することもできます。","start.install#5#h":"CLI","start.install#6#li0":"`npm install -g @ava/cli` を実行してください（または pnpm / yarn — お好みで）。","start.install#6#li1":"任意のプロジェクトディレクトリで `ava` を実行します。","start.install#6#li2":"初回実行時にプロバイダーとモデルを尋ねます。選んで始めましょう。","start.install#7#c":"アカウントがなくても大丈夫です。独自の API キー（BYOK）を使えば、サインインは不要です。無料枠はプラットフォーム管理モデル向けです。","concepts.memory#1#p":"Ava には、一度覚えたことは忘れにくい「永続的なメモリ」があります（「永続的」とは、アプリを閉じても記憶が消えないという意味です）。同期機能をオンにすれば、会話やプロジェクト、さらには端末を超えて記憶がつながります（同期すると、デバイス間でメモリが共有されます）。これは単なるチャットの履歴ではなく、あなたが誰で、何を好み、何を決めたのかを構造化して理解し、検索できるものです。","concepts.memory#2#h":"5 つの層","concepts.memory#3#li0":"抽出 — 毎回のメッセージからリアルタイムで重要な事実をキャプチャします。","concepts.memory#3#li1":"振り返り — 有意義なセッションの終わりに、より深い分析が行われます。パターン、テーマ、矛盾点など。","concepts.memory#3#li2":"蓄積 — 修正や好みが数週間、数ヶ月をかけて積み重なっていきます。","concepts.memory#3#li3":"分析 — グラフエンジンが関連するメモリをつなぎ合わせ、新しい情報が古い情報と矛盾する場合に警告を出します。","concepts.memory#3#li4":"統合 — 似たメモリは結合され、古くなったものは整理されます。メモリは時間とともにノイズが増えるのではなく、より鋭くなります。","concepts.memory#4#c":"上記の 5 つの層は自動的に動作するため、あなたが管理する必要はありません。これらは、メモリが時間の経過とともにゴミの山になるのではなく、本当に向上していくことを確認できるように用意されています。","concepts.memory#5#h":"検索・想起","concepts.memory#6#p":"質問をすると、Ava は単語の一致だけでなく、意味に基づいてメモリを検索します（「セマンティック検索」— あなたが何を意図しているかを理解するため、表現が変わっても正しいメモリが見つかります）。モード固有のフィルターも同時に動作します。チャットモードでは個人コンテキストを、ワークモードではプロジェクトの決定事項やコードパターンを引き出します。","concepts.memory#7#c":"メモリはユーザーごと、プロジェクトごとにスコープが設定されています（あなたのメモリはあなたのもので、人ごと、プロジェクトごとに分離されて保管されます）。機密情報や認証情報（パスワード、キー）は保存時にブロックされます — これらがメモリに残ることはありません。","concepts.memory#title":"メモリー — Ava があなたをどう覚えているか","concepts.memory#0#p":"簡単に言うと：Ava はあなたを覚えています。一度何か伝えてください — 好きなことや決めたこと — すると彼女はそれを覚えておき、次のチャットでも来週にも繰り返す必要がありません。これが基本です。以下の詳細は、時間が経ってもその記憶を整理する方法を説明しています。","concepts.desktop-grounding#title":"デスクトップ・グラウンディング階層（プレビュー）","concepts.desktop-grounding#0#c":"プレビュー — Scout が各ステップでどのグラウンディングソースを使うか決める方法。","concepts.desktop-grounding#1#p":"Ava がボタンをクリックする前に、画面にあるものが何で、どこにあるかを実際に理解する必要があります — これが「グラウンディング」（画面にある各ものが何で、正確な位置はどこかを見つけること）です。やり方は 3 つあり、あなたが使っているアプリに適した最も信頼できるものを選びます。これは深いパワーユーザー向けの詳細ですが、ポイントはただ一つ、彼女は写真から推測するよりも、確実で正確な方法を好むということです。","concepts.desktop-grounding#2#p":"3 つの段階があり、順番に評価されます。最も軽量で信頼できるソースが勝ちます。","concepts.desktop-grounding#3#h":"1. ブラウザウィンドウ → Playwright DOM","concepts.desktop-grounding#4#p":"アクティブなウィンドウが Web ブラウザの場合、Ava は画像から推測するのではなく、ページ自体の構造（「DOM」— ページにあるものの背後にあるリスト）を読み取ります。構造を読むことは、ピクセルを目視するよりも約 10 倍信頼性が高いです — ボタンの位置やページの読み込み完了を正確に知っています。これは Web 上のあらゆるものに適用されるメインの経路であり、バックアップではありません。","concepts.desktop-grounding#5#h":"2. UIA 対応ネイティブアプリ → Windows UI Automation","concepts.desktop-grounding#6#p":"Windows の一般的なデスクトップアプリの場合、Ava は組み込みのアクセシビリティマップ（「UIA」、画面リーダーがウィンドウを説明するために使用する同じデータ）を読み取ります — それぞれのコントロール、名前、位置をリストします。そのマップが少なくとも 5 つの有用な名前付きアイテムを返す場合、彼女はそれを信頼して使用します。","concepts.desktop-grounding#7#h":"3. UIA が空または無効 → OmniParser ビジョン","concepts.desktop-grounding#8#p":"そのマップがないか役に立たない場合（一部のアプリ、ゲーム、リモート画面は提供しない）、Ava は実際にはスクリーンショットを見ることに戻ります。ビジョンツール（OmniParser）がクリック可能な領域を見つけ、それぞれが何かをラベル付けし、画像を再び行動可能なリストに変換します — アクセシビリティマップが提供してくれたわずかな情報と組み合わせられます。","concepts.desktop-grounding#9#c":"OmniParser は Ava が必要とする初回のみオプトインとなり、明確なプライバシープロンプトが表示されます。BYOK ユーザーは独自のローカル OmniParser 展開を指すことができます。","concepts.desktop-kill-switches#title":"デスクトップ・キルスイッチ（プレビュー）","concepts.desktop-kill-switches#0#c":"プレビュー — 実行中の作業を中止するための 3 つの独立した方法。どれか一つでも機能すれば成功です。","concepts.desktop-kill-switches#1#p":"「キルスイッチ」とは名前の通り — Ava があなたの画面を制御しているときに即座に停止させる緊急手段です。安心できる点：3 つあります。それぞれ別々に作られているので、一つが失敗してももう一つが働きます。すべてを覚える必要はありません。何かおかしいと思ったらいつでも止められることだけ知っておいてください。そして最も強力な停止（下のパニックキル）は Ava の協力を頼りにしません。","concepts.desktop-kill-switches#2#p":"公的な自律性のトラブル事例（AI エージェントが停止コマンドを無視したり、メールアーカイブを削除したり、ドライブを消去したりした実際のケース）をすべて読んだ後、私たちは 3 つの異なるレイヤーに 3 つのキルスイッチを構築しました。それらのいずれも AI モデル自体に依存していません — Ava が固まって動かなかったとしても、あなたは依然として彼女を止めることができます。","concepts.desktop-kill-switches#3#h":"一時停止 — スペースキーまたは一時停止ボタン","concepts.desktop-kill-switches#4#p":"次のステップの区切りで一時停止します。再開できます。進行方向を維持したまま、途中で介入したい場合に使いましょう。","concepts.desktop-kill-switches#5#h":"停止 — Escape キーまたは「停止」ボタン","concepts.desktop-kill-switches#6#p":"きれいな中止処理です。ナレーターがこれまでに実行した内容をまとめます。再開はできません。監査ログに記録されます。","concepts.desktop-kill-switches#7#h":"パニック終了 — Escape を 3 回押すか Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"これが最も強力な停止方法です。小さな独立した監視プログラムが、あなたの画面を操作している Ava の一部を強制終了します。AI の応答を待たず、アプリウィンドウが正常でなくても構いません。何らかの状態であっても関係なく、強制的に止めます。本当に何か問題が起きた時用の機能です。","concepts.desktop-kill-switches#9#p":"これら 3 つの方法は、コンパニオンアプリからも利用できます。どちらのドライバーでも終了可能です。","reference.tools#title":"ツールリファレンス","reference.tools#0#p":"これは Ava が持っているすべてのツールの完全なリストです。「ツール」とは、ファイルの読み込みや検索の実行など、Ava が取ることのできる特定のアクションのことです。このページを読む必要はありません。Ava は毎回適切なツールを自分で選んでくれます。Ava が具体的に何ができるのか気になった時のために用意されています。","reference.tools#1#p":"完全な組み込みツールボックスです。ここにあるすべてのツールはコアランタイム（3 つのインターフェースを支えるエンジン）に登録されており、モードと権限設定が許可する限り Ava が利用できます。カテゴリやリスクレベルで絞り込んでください。","reference.tools#2#p":"これらをすべて覚える必要はありません。下の表はあくまで参照用カードです。","reference.tools#4#h":"リスクレベル","reference.tools#5#li0":"セーフ — 何も変更せず読み取るだけです。`file_read`, `glob`（名前のパターンでファイルを探す）, `grep`（ファイル内からテキストを検索）, `git_status`（`Git` はプロジェクトの変更を追跡するシステム）。","reference.tools#5#li1":"書き込み — ファイルを変更したり、作業のチェックポイント（「コミット」）を保存したり、新しいものを生成したりします。`file_edit`, `git_commit`, `generate_image`。","reference.tools#5#li2":"ダンジャー — コンピューター上でコマンドを実行（「シェル」）、デスクトップを制御、インターネットにアクセス、またはデータベースを照会します。`bash`, `browser`, `desktop_*`。","reference.tools#6#c":"ペルソナごとの専門家には、それぞれのツール使用許可リストがあります。Scout は読み取りのみでき、書き込みはできません。Builder はフルアクセス権限を持ちます。Challenger はツールを持っていません — その役割は計画に対して疑問を投げかけることです。","reference.models#title":"モデル","reference.models#0#p":"「モデル」とは、考える AI の頭脳のことです — Qwen, DeepSeek, Mistral など。このページでは Ava が使用できるすべてのモデルをリストしています。簡単に言うと：あなたが一つを選ぶ必要はありません。Ava は各ステップごとに最適なモデルを自分で選んでくれます。理解したい場合や、その選択を上書きしたい場合のみお読みください。","reference.models#1#p":"Ava がルーティングできるすべてのモデルに加え、3 つのオーケストレーション戦略（ジョブの各部分をどのモデルが担当するかを決めるルール）も記載しています。ルーティングモードを選んで Ava に任せるか、単一のモデルを選んでルーティングを完全にスキップすることもできます。","reference.models#2#h":"ルーティングモード","reference.models#3#p":"3 つのオーケストレーション戦略です。同じペルソナパイプライン（裏側で活動する専門家の小さなチーム）は 3 つすべてで共通して稼働しますが、基盤となるモデルの組み合わせが変わります。モデルセレクターでモードを選択すれば、Ava が残りの処理をすべて行います。下の各カードには、指揮者がルーティングする構成要素である専門家が示されています。","reference.models#4#p":"下のカードを覚える必要はありません。各戦略が何で構成されているかを確認できるように用意されています。","reference.models#6#c":"Aurora はあえて Mistral のみを使用するように設計されています。Mistral モデルが利用できない場合、他のモデルへの振り分けではなくエラーを返します — これが EU スタックの保証です。Maestro や Supernova を選択すると、よりスムーズな低下対応が可能です。","reference.models#7#c":"3 つのモードはすべてどこでも利用可能です — プラットフォームクレジットでも、ご自身のキーでも。BYOK を使うと、オーケストレーションをバイパスして単一のモデルを直接動かすオプションが追加されます。","reference.models#8#h":"プラットフォーム管理モデル","reference.models#9#p":"すべてのプランで利用可能です。無料プランを含みます。トークン（AI が使用するテキストの単位 — およそ単語の 3/4 程度）はプランの使用量に含まれます。キー（各有料モデルのロックを解除する秘密のパスワード）はプラットフォームによって自動的に更新・監視されるため、設定する必要はありません。","reference.models#11#h":"自分自身のキーを使用する（BYOK）","reference.models#12#p":"「API キー」とは、ソフトウェアがあなたのアカウントで有料サービスを利用できるようにする、秘密のパスワードのようなものです。「BYOK」は「自分自身のキーを持ってくる」という意味で、私たちのキーではなく、あなた自身のキーを使います。設定画面に API キーを貼り付けてください。BYOK リクエストは、Ava から直接プロバイダー（モデルを運営している会社）へ送られます。当社のインフラを経由せず、プラットフォームトークンも消費しません。料金はプロバイダーにお支払いいただき、当社は通信内容を確認することはありません。","reference.models#14#c":"ベンチマークスコア、機能タグ、並列比較については、ava-supernova.com/models のフルモデルページをご覧ください。上記の料金は、公開時点での各プロバイダーのレートカードに基づく当社の最良の読み取りです。ワークロードを開始する前に、必ずプロバイダーのウェブサイトをご確認ください。","reference.personas#title":"ペルソナ・オーケストレーション","reference.personas#0#p":"「ペルソナ」とは、難しいタスクのために裏側で活躍する Ava のお手伝い役のことです。探検家、プランナー、事実確認係などです。あなたが直接話すことはなく、このページを理解しなくても Ava を使うことができます。これは、Ava が大きな仕事を小さな専門家チームにどのように分解するか、詳しく知りたい方のためにあります。","reference.personas#1#p":"5 つのモードチームにわたる 24 名の専門家。指揮者（Conductor：残りを調整するお手伝い役）が、どのチームが動き、どのような順序で、どのようなコンテキストで動くかを決定します。チャットモードにはペルソナはありません——それは Ava そのものです。","reference.personas#2#h":"オーケストレーションの実行方法","reference.personas#3#li0":"Plan、Teach、Security、Brainstorm モード（または複雑な Work リクエスト）でメッセージを送信します。","reference.personas#3#li1":"指揮者がリクエストを読み取り、モードチームを選び、実行計画を立てます。一部のペルソナは順次、一部は並列波で実行されます。","reference.personas#3#li2":"各ペルソナには独自のシステムプロンプト、制限されたツール許可リスト、および以前のペルソナが見つけたことの共有コンテキストプールがあります。","reference.personas#3#li3":"最後のペルソナが、モードに応じて要約、計画、またはレポートを作成します。","reference.personas#3#li4":"Ava が結果をあなたに提示します。承認、修正、または指示を変更できます。","reference.personas#4#p":"以下の完全な名簿は参考のみです——誰が何をするか暗記する必要はありません。Ava があなたに必要なチームを組み立てます。","reference.personas#6#c":"Work モードでは、複雑なタスクに対してのみフルチームが呼び出されます。簡単な編集は Ava が直接処理——オーケストレーションのオーバーヘッドはありません。","reference.project-context#title":"プロジェクトのコンテキスト","reference.project-context#0#p":"これは、Ava が作業を開始する前にプロジェクトについてどう調べるか、つまりあなたが何に取り組んでいるかを理解するために参照するファイルについて説明しています。これらを自分で設定する必要はありません。Ava が自動で行います。Ava が必ず見てくれるようにメモを置く場所を知りたい場合はこちらをお読みください。","reference.project-context#1#p":"プロジェクトを開くと、Ava は複数の層のコンテキスト（頭の中にある背景情報）を読み込みます。これらの層を理解することで、情報を適切な場所に配置しやすくなります。","reference.project-context#2#h":"自動的に読み込まれるもの","reference.project-context#3#li0":".ava/instructions.md — 永続的で優先度の高いガイドラインとして扱われます。常にコンテキストに含まれます。","reference.project-context#3#li1":".ava/context.md — フリーフォームのメモです。読み込まれますが、優先度は低めです。","reference.project-context#3#li2":"README.md — 初回実行時にスキャンされ、プロジェクトの概要を取得します。","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — プロジェクトの設定を列挙した小さなファイルです。言語、フレームワーク、テストコマンドを検出するために読み取ります。","reference.project-context#3#li4":".gitignore — バージョン管理から除外するファイルのリストです。すべてのファイルツール（glob, grep, project_index）で尊重されます。","reference.project-context#4#h":"必要に応じて読み込まれるもの","reference.project-context#5#p":"「必要に応じて」とは、Ava がタスクで実際に必要とする時だけこれらを取得することを意味し、最初からすべて取得するわけではありません。","reference.project-context#6#li0":"プロジェクトインデックス — ファイルとその内部の名前付き部品（関数、クラス — \"シンボル\"）およびそれらがどのように接続しているか（\"インポート\"）の構造化されたマップです。必要な時だけ構築されるため、遅延ロードされます。","reference.project-context#6#li1":"Git の履歴 — 過去の変更の記録です。git_status、git_diff、または git_create_pr が呼び出されたときに取得されます（Git はプロジェクトへの変更をすべて追跡するツールです。\"PR\" はプルリクエスト、提案された変更のバッチです）。","reference.project-context#6#li2":"メモリ — エントリは意味に基づいて（\"意味的に\"）一致し、一度にすべてではなく、1 ターンずつ注入されます。","reference.project-context#7#c":"規約は instructions.md に、メモは context.md に置きましょう。残りはメモリにお任せしましょう。","features.office-suite#title":"Office Suite","features.office-suite#0#p":"レポート、メール、ドキュメントの作成にお困りですか？Ava が下書きを作成し、実際に使える Word、Excel、PDF ファイルをお渡しします。いつものように開いて編集可能です。","features.office-suite#1#p":"レポート、メール、ドキュメント — 下書き作成、書式設定、ネイティブ形式でのエクスポート（.docx は Word、.xlsx は Excel、.pdf は PDF）。","features.office-suite#2#li0":"report_generate — タスク、ジャーナル、記憶、プロジェクトの状態から情報を引き出した構造化された .docx ファイル。","features.office-suite#2#li1":"email_draft — トーンを調整したメールを .docx ファイルとして出力。","features.office-suite#2#li2":"document_manage — Word、Excel、PDF、CSV、Markdown に対応した作成、閲覧、編集、エクスポート機能。","features.office-suite#3#p":"Ava が代わりに文章を書く際に便利です。ステータスレポート、キックオフ資料、クライアントへの連絡など。.docx ファイルはプロジェクト内に保存され、そのまま手を加えることができます。","features.dashboard-library#title":"ダッシュボードライブラリ","features.dashboard-library#0#p":"簡単に言うと：あなたと Ava が作り、話し合ったすべてのものが収められた棚のようなものです。大切なものがどこにも行かないよう守ります。","features.dashboard-library#1#p":"Ava とあなたが一緒に作ったすべてのものが閲覧できるビューです。生成されたイメージ、動画、音声、ドキュメントに加え、会話や記憶、タスクもここに集まります。先週作ったものを探すのに最適な場所です。","features.document-preview#title":"ドキュメントプレビュー","features.document-preview#0#p":"簡単に言うと：別々のアプリを開かずに、その場でドキュメントの中身を確認できます。","features.document-preview#1#p":"プロジェクト内の Word ドキュメント、Excel シート、PDF、CSV、HTML、Markdown ファイルを右クリック — エディターを離れずにインラインでプレビューできます。Ava が生成した参考資料や、共同作業者が配置したファイルを読むのに役立ちます。","features.daily-briefing#title":"デイリーブリーフィング","features.daily-briefing#0#p":"簡単に言うと：毎朝、「前回の続きはどこでしたか」という短いメモが届きます。すべてを読み返す必要なく、すぐに作業を再開できます。","features.daily-briefing#1#p":"朝のサマリー：昨日の記録、未完了のタスク、プロジェクトの状態、そして Ava が設定したリマインダー。オプション機能です — 設定で有効にできます。","features.daily-briefing#2#p":"このブリーフィングは記憶を活用して、必要な文脈を提示します（\"last time you worked on the auth flow, you noted you wanted to revisit the refresh token strategy\"）。ニュースフィードではなく、要点をまとめた再確認です。","features.unified-panel#title":"ユニファイドパネル","features.unified-panel#0#p":"簡単に言うと：Ava が行うことはすべて 1 つのウィンドウ内にあり、タブを探し回って見つける必要がありません。","features.unified-panel#1#p":"チャット、ダッシュボード、メモリ、タスク、ジャーナル用の 1 つのパネル。ウィンドウ間のコンテキスト切り替えなし。サイドバーで見たいものを選び、メインエリアがそれに合わせて切り替わります。","features.unified-panel#2#p":"離脱しても会話の状態は維持されます——メモリを開き、タスクを確認してから戻ってください。チャットはまだそこにあり、Ava が実行中であればストリーミングも続いています。","features.unified-panel#3#c":"ユニファイドパネルは拡張機能および IDE の概念です。Web 表面はブラウザタブを使用します。","features.knowledge-packs#title":"ナレッジパック","features.knowledge-packs#0#p":"簡単に言うと：Ava に自分自身のドキュメントが入ったフォルダーを手渡すと、彼女はそれらを読んで質問にお答えします。「ナレッジパック」とはまさにそのファイルの束のこと——彼女が参照してもよい参考資料です。","features.knowledge-packs#1#p":"参考資料（仕様書、RFC、議事録、API ドキュメント）のディレクトリをナレッジパックにドロップしてください。会話がそのトピックに触れたとき、Ava は関連する部分をコンテキストに引き出せます。","features.knowledge-packs#2#p":"パックはローカルでインデックス化されます。検索は意味的（セマンティック）です——Ava はファイル名ではなく意味で正しいドキュメントを見つけます。（「意味的」とは、ドキュメントの内容に基づいて一致させることを意味するため、正確な言葉やファイル名を覚える必要がないということです。）パックはチームと共有することも、プライベートに保つこともできます。","features.workflows#title":"ワークフロー","features.workflows#0#p":"わかりやすく言うと：Ava に繰り返す作業を教え、名前をつければ、いつでも実行できます。「ワークフロー」とは、保存されたその手順のことです。Ava があなたのために繰り返す一連のステップです。","features.workflows#1#p":"繰り返し行う一連のステップを保存しましょう。PR のレビュー → テストの実行 → リリースノートの作成 → メールの下書きなど。ワークフローとは、異なる入力でも再生できる再利用可能な計画です。","features.workflows#2#p":"ワークフローはプロジェクトごとに、プロジェクト内の .ava/workflows/ フォルダに保存されます。チームと共有するには、ディレクトリをコミット（共有プロジェクトに保存）してください。そうすればチームメイトも受け取れます。","features.events#title":"イベントと通知","features.events#0#p":"わかりやすく言うと：Ava が作業している間、彼女が何をしているかの整理されたステップバイステップのリストが表示され、長いジョブが終わると通知が来るので、離席しても安心です。","features.events#1#p":"Ava が実行中は、テキストの壁ではなく構造化された更新情報が見えます。各ツール呼び出し、各ペルソナ引き継ぎ、各ストリーミングデルタは UI 内の個別イベントです。詳細は展開可能、概要は折りたたみ可能です。","features.events#2#p":"バックグラウンド実行では完了時に OS レベルの通知が発信されます。長いビルドから離れていても、Ava が終わったら知らせてくれます。","features.personality#title":"パーソンナリティデザイナー","features.personality#0#p":"わかりやすく言うと：Ava の話し方を調整できます。チャット好きか簡潔か、フォーマルかカジュアルか、ジョーク多めか少なめか — あなた好みの声になるように設定します。","features.personality#1#p":"Ava の話し方を形作ります。トーン、エネルギー、発言量、形式ばり具合、ユーモア。スライダーとプリセットで設定可能 — 簡潔なエンジニア、温かいメンター、ドライな同僚、または独自のブレンド。","features.personality#2#p":"パーソナリティは表現に影響しますが、能力には影響しません。同じツールを実行し、同じ権限ルールに従います。名前は Ava に固定されています — これは変更できません。","features.release-notes#title":"リリースノート","features.release-notes#0#p":"わかりやすく言うと：各アップデートで何が新しくなり、何が修正されたかのリストです。変更点を確認できます。","features.release-notes#1#p":"アプリ内チェンジログ（変更履歴）。リリースされたすべてのバージョンとそのハイライト、バグ修正、破壊的変更（使用法の変更が必要な変更）が含まれています。ウェブサイトの公開版は ava-supernova.com/releases にあります。","troubleshooting.logs#4#c":"ログには、セッション中に Ava が読み込んだプロジェクトファイルの一部が含まれている可能性があります。共有する前に必ずご確認ください。","troubleshooting.support-request#title":"サポートへの問い合わせ","troubleshooting.support-request#0#p":"簡単に言うと：なにかおかしくなって、上の方法でも直らない場合は、私たちにお知らせください。一番簡単なのは、Ava に頼むことです。","troubleshooting.support-request#1#p":"よくあるエラーリストにない問題の場合は、サポートチケットを発行してください（サポートチームへのお手伝い依頼です）。Ava 内（フォーム入力不要）か、Web サイトから行えます。","troubleshooting.support-request#2#h":"Ava 内から","troubleshooting.support-request#3#p":"Ava に頼んでください。「Ava、これについてサポートチケットを起こしてくれますか？」と。Ava は support_request を実行し、関連するセッションの状況（パスワードなどの機密情報は隠した状態）を添付して送信します。これが一番速い道です。","troubleshooting.support-request#4#h":"Web サイトから","troubleshooting.support-request#5#p":"ava-supernova.com/support にアクセスしてください。カテゴリ（バグ、機能、アカウント、セキュリティ、全般）を選んで、何が起きたかを説明してください。1 営業日以内に返信いたします。","troubleshooting.support-request#6#h":"記載すべき内容","troubleshooting.support-request#7#li0":"何をしようとしていたか。","troubleshooting.support-request#7#li1":"実際にどうなったか。","troubleshooting.support-request#7#li2":"どの環境（拡張機能、IDE、CLI、コンパニオン）で、どのバージョンか。","troubleshooting.support-request#7#li3":"エラーメッセージやログの一部など。その際、認証情報は事前に伏字にしてください。","troubleshooting.security-disclosure#title":"セキュリティ上の問題について","troubleshooting.security-disclosure#0#p":"簡単に言うと：Ava の抜け穴や悪用の可能性（「脆弱性」— セキュリティ上の弱点）を見つけたら、だれかに悪用される前に直すため、まず私たちだけに知らせてください。このページがその方法です。","troubleshooting.security-disclosure#1#p":"脆弱性を見つけましたか？ありがとうございます。私たちはすべての報告を真摯に受け止め、問題が公に発表される前の段階で、あなたと一緒に修正に取り組みます。","troubleshooting.security-disclosure#2#h":"報告方法","troubleshooting.security-disclosure#3#li0":"security@ava-supernova.com にメールを送ってください。内容は説明、再現手順、希望する公開までの期間などです。","troubleshooting.security-disclosure#3#li1":"また、「セキュリティ」カテゴリでサポートチケットを発行してください——処理順は同じです。","troubleshooting.security-disclosure#3#li2":"24 時間以内に返信いたします。","troubleshooting.security-disclosure#4#h":"私たちの約束事","troubleshooting.security-disclosure#5#li0":"調整された公開 — 何も公表する前に、あなたと日程を合わせます。標準は 90 日間です。","troubleshooting.security-disclosure#5#li1":"謝辞 — 修正に関するノートに記載されます（匿名を希望しない限り）。","troubleshooting.security-disclosure#5#li2":"法的な報復はありません — 善意での調査は大歓迎です。弁護士を派遣することはありません。","troubleshooting.security-disclosure#6#c":"ava-supernova.com/security のセキュリティページには、アーキテクチャの保証、機密情報の隠蔽機能、権限管理など、全体のセキュリティ体制が詳しく載っています。","reference.config#title":"設定","reference.config#0#p":"このページでは、Ava があなたのコンピュータ上で設定やファイルをどこに保存しているかを確認できます。ほとんど手動で触る必要はありません——アプリが自動的に管理してくれます。自分で確認したり、バックアップしたり、共有したい場合のためにここに用意されています。","reference.config#1#p":"Ava は設定（保存された設定）を 2 つの範囲から読み取ります。グローバル設定（どこでも適用される設定）は、`~/.ava/` というフォルダにあります（「~」はホームフォルダの略語です）。プロジェクトごとの設定は、プロジェクト内の `.ava/` フォルダにあります。","reference.config#2#h":"グローバル — ~/.ava/","reference.config#3#li0":"settings.json — モデルの好み、許可モード、性格、言語。","reference.config#3#li1":"memory/ — グローバルメモリ（全体的な好みや、どこでも適用される決定など）。","reference.config#3#li2":"tasks.json — プロジェクト間共通のタスクリスト。","reference.config#3#li3":"journal/ — 日付ごとに整理された日々の日記エントリ。","reference.config#4#h":"プロジェクト — .ava/","reference.config#5#li0":"instructions.md — Ava が常に読み込むプロジェクト固有の指示。永続的なコンテキスト（「pnpm を使い、npm は使わない」「API キーは 1Password に保存されている」など）。","reference.config#5#li1":"context.md — オプションの自由記述形式のプロジェクトメモ。","reference.config#5#li2":"memory/ — このプロジェクトに限定されたメモリ。","reference.config#5#li3":"datasets/config.json — オプトイン型のデータセット収集設定。","reference.config#6#c":"チームとメモリを共有したくない場合は、`.ava/` を `.gitignore`（Git に共有プロジェクトから除外するように指示するファイルリスト）に追加してください。`instructions.md` はリポジトリ（共有プロジェクトフォルダ）に残してください——これが Ava がプロジェクトの規約を学ぶ方法です。","reference.shortcuts#title":"キーボードショートカット","reference.shortcuts#0#p":"キーボードショートカットは任意の高速化機能です——すべてクリックできるボタンでもあります。キーボードから Ava を操作する速度を上げたい場合のみこちらをご覧ください。","reference.shortcuts#1#p":"画面ごとのショートカット（Ava が動作する 3 つの場所：VS Code 拡張機能、デスクトップアプリ、ターミナル）。各画面の設定でカスタマイズできます。以下のリストを覚える必要はありません。","troubleshooting.common-errors#title":"よくあるエラー","troubleshooting.common-errors#0#p":"ほとんどのエラーには、短い特定の理由があります。ここではよくあるものとその対処法をご紹介します。言葉が技術的だと感じても心配しないでください。以下に実際に何が見えているか、そしてどうすべきかを具体的に説明しています。","troubleshooting.common-errors#1#h":"モデルが反応しない","troubleshooting.common-errors#2#p":"表示される内容：Ava が沈黙し、返信してきません。","troubleshooting.common-errors#3#p":"チャットヘッダーのステータスインジケーターを確認してください。「connecting」と表示されている場合、プロバイダー（Ava が話している AI サービス）は接続できているが遅れています — 30 秒ほどお待ちください。「unavailable」と表示されている場合、Ava は自動的に次のモデルにフォールバックしました（バックアップモデルに切り替わりました）。何も表示されない場合は、設定で API キーを確認し、接続をテストしてください。（API キーとは、Ava が有料 AI サービスを利用するための秘密のパスワードです。）","troubleshooting.common-errors#4#h":"ツールの呼び出しに失敗","troubleshooting.common-errors#5#p":"表示される内容：Ava の手順の一つ（「ツール呼び出し」— ファイルを読む、コマンドを実行するなど）が完了する代わりに赤いエラーを表示します。","troubleshooting.common-errors#6#p":"失敗したツール呼び出しをクリックしてエラーを確認してください。一般的な原因：プロジェクトフォルダ外のファイルに触れようとした（これはあなたの安全のために意図的にブロックされています。このガードは「パストラバーサル」保護と呼ばれます — あなたが作業しているフォルダの外に彼女が行き渡るのを防ぎます）、別のフォルダで実行が必要なコマンド、または Ava が最後に確認してから移動されたファイルなどです。何が起きたか教えてあげてください — 修正して再試行します。","troubleshooting.common-errors#7#h":"メモリが思い出せない","troubleshooting.common-errors#8#p":"表示される内容：Ava が、あなたが確実に覚えていてほしいものを発見できません。","troubleshooting.common-errors#9#p":"メモリは正確な単語ではなく意味に基づいて機能します（これが「セマンティック」の意味です）。なので、「認証について何を決めた？」と聞く方が、「私の認証決定を見つけて」と探すよりも効果的です。メモリが確かにあるのに表示されない場合は、メモリブラウザを開いて検索してください — もしそこにないなら、最初から保存されていなかったということです。","troubleshooting.common-errors#10#h":"サインインのループ","troubleshooting.common-errors#11#p":"表示される内容：サインインしましたが、Ava が何度も再度サインインを求めてきます — 決して進めないループ状態です。","troubleshooting.common-errors#12#p":"解決策は保存されたサインイン情報をクリアして新しく始めることです：拡張機能ではコマンドパレットから「Ava: Sign Out」を実行し、IDE では 設定 → アカウント → サインアウト を使い、CLI では `~/.ava/auth.json` ファイルを削除してください（ホームディレクトリ内の `.ava` フォルダにある小さなサインインファイルです）。その後、再度サインインしてください。","troubleshooting.common-errors#13#h":"トークン切れ","troubleshooting.common-errors#14#p":"表示される内容：今月の無料利用枠を使い切ったというメッセージが表示されます。（「トークン」は AI の使用量を測る単位です — 「exhausted」は単に今月の無料枠を使い果たしたという意味です。）","troubleshooting.common-errors#15#p":"無料プランの月間予算は毎月 1 日にリセットされます。それまでは、動作を続けるために BYOK プロバイダー（自分の API キーを使用）に切り替えてください。アカウントは有効のままです — 無料のプラットフォーム管理リクエストのみが一時停止されます。","troubleshooting.logs#title":"ログの場所","troubleshooting.logs#0#p":"「ログ」とは、コンピューターが何か起きたときに記録する日記のようなものです — 何か壊れたときや、あなた（またはサポート）が詳細を確認する必要がある場合に役立ちます。","troubleshooting.logs#1#p":"生の状況を知りたい場合 — どのツールが呼び出されたか、どんな情報を受け取ったか、AI サービスが何を返したか — ログは、コンピューター上のフォルダにあるプレーンテキストファイルです。場所は `~/.ava/logs/` です（ホームディレクトリ内の `.ava` フォルダの中に `logs` フォルダが入っています）。","troubleshooting.logs#2#li0":"`~/.ava/logs/session-<date>.log` — ツール呼び出し、ストリーミングされた応答、エラーを含むセッションごとのトランスクリプト。","troubleshooting.logs#2#li1":"`~/.ava/logs/extension.log` — VS Code 拡張機能ホストログ。アクティベーションの失敗、パネルエラー。","troubleshooting.logs#2#li2":"`~/.ava/logs/ide.log` — デスクトップ IDE ログ。サイドカープロセスのメッセージ、Rust パニック。","troubleshooting.logs#2#li3":"`~/.ava/logs/cli.log` — CLI REPL ログ。","troubleshooting.logs#3#p":"拡張機能では、コマンドパレットの「Ava: Show Logs」で関連するログがエディタタブで開きます。IDE では、設定 → 診断 に「ログを開く」ボタンがあります。CLI は `ava logs --follow` コマンドで自身のログをフォローできます。","start.what#title":"Ava とは？","start.what#0#p":"Ava は実際に何かをしてくれる AI です。ただおしゃべりするだけではありません。アプリを作ったり、文書を書いたり、ゼロから教えてくれたり、ロゴをデザインしたり、先延ばしにしていた事務処理を片付けたりします。そして Ava はあなたを覚えてくれます：何に取り組んでいるか、どんな風に好むか、先週何を頼んだかまで。","start.what#1#p":"Ava は一人しかいませんが、どこでも働きます。コードエディタの中も、デスクトップアプリとして、スマホ上も、ターミナル上も。同じ記憶、同じ性格、どこでも一緒です。","start.what#2#h":"何が違うのか","start.what#3#li0":"デフォルトであなたのもの。作業はすべて自分のマシン上に残ります。追跡もデータ収集もなし。永久に。","start.what#3#li1":"誰でも見られるオープンソース。Ava のすべての行が公開されています。信用する必要はありません。","start.what#3#li2":"無料で始められます。毎月 300 クレジット。カード不要、裏技なし。あるいは自分の AI キーを接続して、私たちに支払う必要もありません。","start.what#3#li3":"教育は永久無料。学びには価格タグがつくべきではありません。","start.what#4#p":"コードを書いたことがない？次のページはあなたのために書かれています。すでに技術者なら、先へスキップしてください。Ava がついていきます。","start.what#deeper#0#h":"Where Ava lives","start.what#deeper#1#li0":"VS Code extension — Ava next to your editor: a chat panel, a dashboard, and changes shown inline before they happen.","start.what#deeper#1#li1":"Desktop IDE — a standalone app with the whole thing in one window. Adds desktop control (opening apps, clicking, typing for you).","start.what#deeper#1#li2":"Companion — a mobile app for when you're away from your desk: tasks, journal, memory, quick chats.","start.what#deeper#1#li3":"CLI — Ava in your terminal, for people who live there.","start.what#deeper#2#h":"How she works, in brief","start.what#deeper#3#p":"Ava switches mindsets (called modes) to match the job, quietly runs a small team of specialist helpers on harder work, and picks the best AI model for each step automatically. You never manage any of it. The Core concepts section has the full tour whenever you're curious.","start.first-five#title":"Ava と初めての体験","start.first-five#0#p":"Ava を使い始める最速の方法は、実際に何かを頼んで、その様子を見ることです。読むべき設定もなく、最初に学ぶこともありません。ただ、欲しいものを普通の言葉で伝えてください。","start.first-five#1#h":"今すぐ試してみましょう","start.first-five#2#li0":"チャットを開く。","start.first-five#2#li1":"実際にやりたいことを入力。「このプロジェクトは何をするものか説明して」、または「フォームをクリアするボタンを追加して」といった具合に。","start.first-five#2#li2":"Ava はこれから行うことを示し、待機します。","start.first-five#2#li3":"気に入ったら「はい」と言う。実行する様子を見守ろう。","start.first-five#3#p":"これが基本のリズムです：あなたが頼み、彼女は計画を示し、あなたが承認し、彼女が実行します。何も示さずに何も変えません。だから、試すことで壊してしまう心配もありません。","start.first-five#4#h":"聞いてみる価値のあること","start.first-five#5#li0":"質問 — 「なぜページが空白なの？」「このファイルは何をするの？」","start.first-five#5#li1":"何か作ってほしい — 「簡単な ToDo リストのページを作ってくれる？」","start.first-five#5#li2":"何か学びたい — 「ゼロから Python を教えて」。 (いつでも無料。)","start.first-five#5#li3":"ドキュメント — 「1 ページのプロジェクト提案書を書いて」。Word ファイルか PDF を渡します。","start.first-five#6#c":"何を入力するか迷ったら？知識豊富な友達みたいに話しかけてください。普通の言葉でちょうどいいんです — 始めるのに技術用語は全く必要ありません。","start.first-five#deeper#0#p":"そのシンプルなループも、裏側では結構なことをしています。Ava を使うためにこれらを知る必要はありません — ただし、気になる方のために実際に何が起きているかお伝えします。","start.first-five#deeper#1#h":"ツールと承認","start.first-five#deeper#2#p":"Ava がファイルを読み込み、コマンドを実行したり、コードを編集したりするときは、それすべてが「ツール呼び出し」です。ファイルやシステムに触れることの前には必ず聞きます — どのくらい聞くかは、あなたの許可モード（毎回聞く、危険なときだけ聞く、またはそのまま実行）で設定されています。","start.first-five#deeper#3#h":"モード — 彼女の思考状態","start.first-five#deeper#4#p":"Ava はモードで動作します：マインドセットに、その仕事に必要な正しいツールキットを加えたものです。ピッカーからいつでも切り替えるか、メッセージの先頭にプレフィックスを入力してください。全部で 7 つあります。","start.first-five#deeper#6#h":"スペシャリストとルーティング","start.first-five#deeper#7#p":"難しい作業の場合、Ava は裏側でスペシャリストヘルパーの小さなチーム（プランナー、チェッカー、ビルダー）を動かして、各ステップを最も得意なモデルにルーティングします。これをあなたが管理する必要はありません — 彼女があなたのために調整してくれます。","start.local-vs-cloud#title":"ローカルとクラウド、1 パラグラフで","start.local-vs-cloud#0#p":"Ava が行うことはすべてローカルですが、明示的にオプトインしない限り。メモリ、タスク、ジャーナル、人格、設定 — すべてあなたのマシン上の ~/.ava/ と .ava/ (プロジェクトごと) に保存されます。HTTPS でモデルプロバイダーと通信してリクエストを実行し、その後自宅に戻ります。外部へ連絡しません。テレメトリを集めません。あなたのコードで学習しません。","start.local-vs-cloud#1#p":"ログインすると、プラットフォーム管理モデル（Qwen, MiniMax）で月 300 クレジット無料で利用でき、マシン間でメモリと設定のクラウド同期もオプションで可能です。同期は機能ごとにあり、いつでも取り消せます。API キーを持参すれば、アカウントなしでも Ava は完全に動作します。","start.local-vs-cloud#2#c":"ルール：ローカルは聖域。クラウドは追加機能。","start.first-model#title":"AI を選ぶ必要がありますか？","start.first-model#0#p":"ほっとしてください：AI を選ぶ必要はありません。Ava が各ステップに最適なものを自動的に選んでくれるので、考えなくても良い結果が得られます。","start.first-model#1#p":"あなたが選べるのはルーティングスタイルだけです — デフォルトはほとんどの方に適しています。特定の理由がある場合のみ、他のものが必要です。","start.first-model#2#h":"3 つのスタイル","start.first-model#3#li0":"マエストロ — デフォルト。安定しており、信頼でき、予測可能。わからない？これがおすすめです。","start.first-model#3#li1":"スーパーノヴァ — 重く多段階の作業向け。仕事の各部分に異なるスペシャリストを配置する価値があります。","start.first-model#3#li2":"オーロラ — データが EU 内に留まる必要がある場合（公共部門、医療、厳格なプライバシー）。ヨーロッパのオープンウェイト AI のみで完全に動作します。","start.first-model#4#p":"チャットの上部にあるモデルピッカーからいつでも切り替えられます。何も固定されていません。","start.first-model#5#c":"特定のモデルを自分で操作したいですか？できます — 「詳細を表示」を開いてください。","models.routing#deeper#2#td5.0":"チャット","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"画像生成の調整と連携","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"視覚認識","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (ゼロから学習した視覚エンコーダー搭載)","models.routing#deeper#2#td8.0":"長文作成","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"データの保存場所","models.routing#deeper#2#td9.1":"混合 (Alibaba Cloud)","models.routing#deeper#2#td9.2":"混合 (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"EU のみ · オープンウェイト","models.routing#deeper#2#td10.0":"ステータス","models.routing#deeper#2#td10.1":"利用可能 · すべてのプラン","models.routing#deeper#2#td10.2":"近日公開","models.routing#deeper#2#td10.3":"近日公開","models.routing#deeper#2#td11.0":"おすすめの用途","start.first-model#deeper#0#h":"各スタイルの中身は実際には何？","start.first-model#deeper#1#p":"Maestro — 一人の指揮者（Qwen 3.6 Plus）がすべての工程を担当します。実用向けに最適化され、実績があり、コストも明確です。","start.first-model#deeper#2#p":"Supernova — フロンティア・コーディネーター（DeepSeek V4 Pro、1.6T パラメータ / 49B アクティブ、1M コンテキスト）が各サブタスクを専門家へ委ねます。大量ビルドには V4 Flash、フォールバックには Qwen 3.6 Plus、ビジョン処理には Qwen Omni です。","start.first-model#deeper#3#p":"Aurora — Mistral のみを使用し、3 つのティアがあります：Mistral Large 3（コーディネーター＋重厚な専門家）、Mistral Medium 3.5（128B デンス、256K コンテキスト、ネイティブ・ビジョン、修正 MIT オープンウェイト、77.6% SWE-Bench 検証済み）は Builder ＋ミッドティア＋ビジョン＋長文向け、そして意図ゲートでは Mistral Small 4。オープンウェイトは最初から最後まで、EU インフラの外に出ることはありません。","start.first-model#deeper#4#h":"お好みのモデルを持ってきてください (BYOK)","start.first-model#deeper#5#p":"ご自身で AI アカウントを使いたいですか？設定画面にプロバイダーキーを貼り付けるだけで、両方のメリットが得られます — 3 つのルーティングスタイルに加え、単一のモデルを選んでルーティングなしで使うことも可能です。特定のモデルへのこだわりがある場合、予算を厳しく管理したい場合、あるいは特定のモデルを試したい場合に便利です。完全なプロバイダー一覧は「リファレンス」セクションをご覧ください。","start.glossary#title":"わかりやすい用語集","start.glossary#0#p":"Ava に関連して出てくるかもしれない言葉すべてを、前提知識ゼロで解説しています。これを全部覚える必要はありません — 用語で詰まったときはいつでもここに戻ってきてください。","start.glossary#1#th0":"言葉","start.glossary#1#th1":"実際の意味","start.glossary#1#td0.0":"エージェント","start.glossary#1#td0.1":"あなたのために行動できる AI です — ファイルを開く、コマンドを実行、ウェブ検索をするなど、ただ話すだけではありません。Ava はエージェントです：あなたの許可のもとで、実際に作業をこなしてくれます。","start.glossary#1#td1.0":"モデル","start.glossary#1#td1.1":"実際に考えている AI の頭脳（Qwen、DeepSeek、Mistral など）。モデルごとに得意分野が異なります。通常、あなたが選ぶ必要はありません — Ava が選んでくれます。","start.glossary#1#td2.0":"モード","start.glossary#1#td2.1":"Ava が今どんな役割でいるかを示します。同僚が帽子を変えるようなもので：ビルダー、ライターの、ティーチャー、プランナー、フレンドなど。モードを選ぶと、彼女の振る舞い方が変わります。全部で 7 つあります。","start.glossary#1#td3.0":"ペルソナ / スペシャリスト","start.glossary#1#td3.1":"より難しい仕事をこなすために、裏側で活躍する Ava のサポート役 — エクスプローラー、プランナー、ファクトチェッカー。小さな専門家チームだと思ってください。あなたたちが直接話しかけることはなく、Ava がまとめてくれます。","start.glossary#1#td4.0":"ルーティング","start.glossary#1#td4.1":"各ステップでどのモデルを使うかを Ava が判断し、無駄遣いせずによい回答を得られるようにします。これは自動で行われます — 「routing mode」は全体の戦略を選ぶだけです。","start.glossary#1#td5.0":"ツール","start.glossary#1#td5.1":"Ava が実行できる具体的なアクション — ファイルを開く、検索を実行、メールを送る。「ツール呼び出し」とは、それらを使うことを指します。危険そうなことは何でも事前に許可を求めます。","start.glossary#1#td6.0":"トークン","start.glossary#1#td6.1":"AI がテキストを測る単位です — 単語の約 3/4 にあたります。モデルは百万トークン単位で料金が決まります。ほとんど気にする必要のないものです。","start.glossary#1#td7.0":"クレジット","models.routing#deeper#1#h":"横並び","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"調整役","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro（1.6T / アクティブ 49B、1M コンテキスト）","models.routing#deeper#2#td0.3":"Mistral Large 3（675B / アクティブ 41B、262K コンテキスト）","models.routing#deeper#2#td1.0":"ビルダー","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus（調整役を再利用）","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5（128B 全体重、256K コンテキスト）","models.routing#deeper#2#td2.0":"中堅スペシャリスト","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash（コードレビュー、事実確認、情報収集、スキャン、セキュリティ検証など）","models.routing#deeper#2#td2.3":"Mistral Medium 3.5（アーキテクト、検証者、シーケンサー、チューター、レポーターなど）","models.routing#deeper#2#td3.0":"ライトティア / 意図ゲート","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash（スカウト、検証者、シーケンサー、チャレンジャー、インテグレーター）","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"ヘビースペシャリスト","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3（リサーチャー、チャレンジャー、CVE リサーチャー、アイデア考案者、事実確認者）","start.glossary#1#td7.1":"アバが定める、アクションにかかるコストを表すシンプルな単位です。トークン計算なんて気にする必要はありません。プランには毎月のバンドルがついています。","start.glossary#1#td8.0":"API キー","start.glossary#1#td8.1":"ソフトウェアがあなたのアカウントで有料サービス（AI モデルなど）を利用できるようにする、秘密のパスワードです。自分で用意する場合だけ必要です。","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"「Bring Your Own Key」。「アバの管理アクセス」の代わりに、自分自身の API キーを使うことです。オプション——すでにプロバイダーに直接支払いをしている人向けです。","start.glossary#1#td10.0":"ローカルファースト","start.glossary#1#td10.1":"データは基本的にあなた自身のコンピューター上にあります。同期をオンにしない限り、何もアップロードされません。「ローカルは守るべきもの」です。","start.glossary#1#td11.0":"パーミッションモード","start.glossary#1#td11.1":"アバが行動を起こす前にどれほど慎重になるかを決める設定です。「毎回確認」「リスクがある時だけ確認」「そのまま実行」など、レベルをあなたが設定できます。","start.glossary#1#td12.0":"コンテキストウィンドウ","start.glossary#1#td12.1":"モデルが一度に記憶できるテキストの量のこと——つまり短期記憶です。「1M コンテキスト」とは約 100 万語分を指します。大きいほど、忘れ始める前に多くの文章を読み込めます。","start.glossary#1#td13.0":"差分","start.glossary#1#td13.1":"ファイル内で何がどう変わるのかを左右に並べて表示する機能です。左側に古い内容、右側に新しい内容が表示されます。アバが変更を加える前に確認して承認するための画面です。","start.glossary#1#td14.0":"リポジトリ (リポジトリ)","start.glossary#1#td14.1":"変更を追跡するプロジェクトフォルダで、通常は Git で管理されます。もしこれが何を意味するかまだわからない場合は、「プロジェクトが入っているフォルダ」と思ってください。","start.glossary#1#td15.0":"プロンプト","start.glossary#1#td15.1":"AI に打ち込むメッセージ——あなたの質問や指示のことです。","start.glossary#2#c":"それでも言葉でつまずいているなら？チャットモードでアバに聞いてみてください。「X って何？」と聞けば、あなたのレベルに合わせて説明してくれます。","models.routing#title":"ルーティング —— アバがモデルを選ぶ仕組み","models.routing#0#p":"簡単に言うと：どの AI モデルを使うか選ぶ必要はありません。アバが代わりに選んでくれます。仕事の一部ごとに最適なツールを選ぶのです——良いマネージャーが適切なタスクを適切な人に任せるようなものです。","models.routing#1#p":"3 つのスタイル（Maestro、Supernova、Aurora）から 1 つ選べば、アバがそれぞれの作業を最も得意とするモデルに振り分けます。デフォルトは Maestro で、すべてのプランで利用でき、ほとんどの方におすすめです。","models.routing#2#h":"なぜルーティングが必要なのか？","models.routing#3#p":"各ステップに適切なモデルを使う方が、一つの高価なモデルですべて処理するよりもコストを抑えられ、かつ結果も良くなります。なぜなら、各モデルは得意なことをしているからです。どのモデルがどちらかわからなくても、安定したコストと高い品質を手に入れられます。","models.routing#4#c":"3 つのスタイルすべてが、プラットフォームクレジットでもご自身のキーでも使えます。ご自身のキーを使えば、ルーティングを飛ばして単一のモデルを直接動かすことも可能です。詳細な一覧は「詳細を表示」の下にあります。","models.routing#deeper#0#c":"以下の「B」の数値はパラメータの数十億——つまりモデルの「脳」の大きさを表しています。大きいほど一般的に賢いですが、遅く、高価になります。これは裏側の技術的な詳細なので、アバを使うためには気にする必要はありません。","models.routing#deeper#2#td11.1":"日常業務、コストが予測しやすい","models.routing#deeper#2#td11.2":"複雑な多段階作業。すべてのプランに最前線のコーディネーターを搭載","models.routing#deeper#2#td11.3":"GDPR 厳守、公共部門向け、主権を有する EU スタック","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"ティア別に最適化された Qwen ルーティングで、軽量なフットプリントを実現。Qwen 3.6 Plus がコーディネーター、ビルダー、計画、セキュリティ、ブレインストーミング、長文コンテキストの担当を引き受け、その 1M コンテキストハイブリッド線形アテンションが効果を発揮する場面で活躍します。Qwen 3.5 Flash はチャット、画像生成オーケストレーション、そして上流の意図ゲートを担当し、$0.07/$0.26 の価格設定と高速な TTFT で、浅い深度のトークンボリュームの大部分で有利です。Qwen 3.5 Omni Plus はビジョン入力を担当（Qwen 3.6 Plus にネイティブビジョン機能はありません）。Qwen 3.5 Plus はコスト重視の長文ワークを担当します。プライオリティ階層は Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash となり、主要なコーディネーターが利用できない場合にフォールスルーします。","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"多言語アンサンブル。DeepSeek V4 Pro が調整役となり、各サブタスクを最も適した専門家に振り分けます。Qwen 3.6 Plus はすべての Builder 起動を実行し、V4 Flash はチャットおよびミッドティアのレビュー/監査ペルソナを処理し、Qwen 3.5 Flash はライトティアの分類ワークを引き受け、Qwen 3.5 Omni Plus はビジョン入力を担当、Qwen 3.5 Omni Flash は画像生成ツール呼び出しをオーケストレーション、Qwen 3.5 Plus はコスト重視の長文コンテンツライターペルソナを担当します。重要な場所で最前線の推論を、トークンボリュームの大部分ではフラッシュティアのコスト効率を。","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"欧州 AI スタック — 設計思想から主権を確保。3 つのティアでの Mistral 専用ルーティング：Mistral Large 3（675B/41B アクティブ疎性 MoE）がコーディネーター役および深度が必要な重厚な専門家（Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier）と、疎性 MoE の効率性が光る長文コンテキストの重労働を担当します。Mistral Medium 3.5 — 2026 年 4 月にリリースされた統合フラッグシップモデル。128B 稠密、256K コンテキスト、ゼロから訓練されたビジョンエンコーダー、修正 MIT オープンウェイト、SWE-Bench Verified 77.6% — が実際の作業ティアを担当：Builder 起動、ミッドティア専門家（Architect, Verifier, Sequencer, Tutor, Reporter）、ビジョン入力、長文ライティング。Mistral Small 4 は意図ゲートの単一役割から拡張され、チャットと画像生成オーケストレーションも担当。その $0.15/$0.60 の価格設定と構成可能な推論が、高ボリューム・浅い深度ルートで価値を発揮します。エンドツーエンドでオープンウェイト。EU インフラストラクチャから決して離れません。Aurora は、利用できない場合でもあえて無言で他社モデルへクロスルーティングせず、エラーを表示します。それが『Aurora』であり、Mistral フレーバーの『Maestro』ではない理由です。","credits.overview#title":"Ava クレジット — 請求の仕組みについて","credits.overview#0#p":"クレジットとは、Ava があなたの使用量をカウントする方法です。携帯電話のプランの分量のようなものと考えてください。無料プランを含むすべてのプランにはクレジットのプールがあり、Ava が行うことすべて（回答や画像作成など）が少量のクレジットを消費します。これが基本理念です。詳細は、何にいくらかかるか知りたい場合のために記載しています。","credits.overview#1#p":"Ava はトークン数ではなくクレジットで請求します。（「トークン」とは、AI モデルが読み書きする文字の小さな断片のことです。多くのサービスはトークン単位で課金しますが、これは予測が難しいものです。）1 クレジットは 1 ユニットの作業をカバーします。チャットターン、ペルソナの起動（タスクの一部を行うヘルパー 1 人）、画像生成など。トークンレベルの計測から切り離すことで、どのモデルが動いているかを知らなくてもアクションのコストを知ることができます。同じチャットターンなら、Maestro が Qwen 3.6 Plus にルーティングしても、Supernova が V4 Pro にルーティングしてもコストは同じです。","credits.overview#2#h":"プラン","credits.overview#3#p":"すべてのプランで全機能にアクセスできます。モデルアクセス、Creative Studio、すべての 7 つのモード、フルペルソナオーケストレーションなど。上位ティアは、機能のロック解除ではなく、より多くのクレジットと高いレート制限上限を購入します。","credits.overview#4#li0":"Free — 月額$0。300 クレジット。1 分間あたり 20 リクエストのレート制限。カード登録不要。","credits.overview#4#li1":"Pro — 月額$19。5,000 クレジット。1 分間あたり 60 リクエスト。","credits.overview#4#li2":"Ultra — 月額$39。10,000 クレジット。1 分間あたり 120 リクエスト。","credits.overview#4#li3":"Enterprise — 月額$79。20,000 クレジット。1 分間あたり 200 リクエスト。","credits.overview#5#c":"未使用クレジットは契約期間中ロールオーバーします（強制返還はありません）。トップアップはサブスクリプションプールに積み重ねられます：$3 で 750 クレジット、$8 で 2,000、$15 で 4,000。","credits.overview#6#h":"アイテムごとの料金","credits.overview#7#p":"アクションごとの料金表 — 各アクション実行時にクレジットプールから差し引かれる金額。（「キャッシュヒット」とは、Ava がすでに実施済みの作業を再利用することを指します。その場合は支払額が減り、70% 減額、または DeepSeek V4 Pro のような出力重視モデルでは 50% 減額になります。）","credits.overview#8#li0":"チャットターン — 2 クレジット。どのモードでも 1 往復。","credits.overview#8#li1":"ライトコール — 1 クレジット。意図ゲート、分類、シングルショット読み取り。","credits.overview#8#li2":"ヘビーペルソナ — 3 クレジット。Architect, Researcher, CVE Researcher, Ideator（深度≥4）。","credits.overview#8#li3":"ライトペルソナ — 1 クレジット。Scout, Verifier, Sequencer, Challenger（深度≤2）。","credits.overview#8#li4":"オーケストレーション — 10 クレジット。フルペルソナパイプラインを起動します（コンダクターと複数ペルソナのタスクを含む）。","credits.overview#8#li5":"イメージ生成 — 12 クレジット。Creative Studio 経由で Hailuo image-01 を使用。","credits.overview#8#li6":"ビデオ生成 — 150 クレジット。Hailuo 02 Pro の 1080p、6 秒クリップ。","credits.overview#8#li7":"ボイス生成 — 10 クレジット。Speech 2.8 HD 合成を使用。","credits.overview#8#li8":"ミュージック生成 — 50 クレジット。MiniMax Music 2.5/2.6。","credits.overview#8#li9":"背景削除 — 2 クレジット。","credits.overview#9#h":"モデル別の乗数","credits.overview#10#p":"このセクションは好奇心旺盛な方のためのものです — Ava を使うには必須ではありません。乗数は、アクションを支えるモデルのコストに応じて、クレジットコストを上下に調整するだけです。つまり、重いモデルは少し高くつきます。「ネットマージン」とは、プロジェクトが経費を支払った後に残る利益のことです — 私たちはこれを低く抑えているので、その価値はあなたに戻ってきます。","credits.overview#11#p":"重いモデルではアクションコストに乗数が適用され、クレジットが単一の料金帯ではなく実際の支出を追跡します。約 55% のネットマージンになるように調整されています。","credits.overview#12#li0":"0.6× — Mistral Small 4（Aurora の専門家担当）。Qwen 3.6 Plus を基準とするより安いため、1×未満です。","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash、Qwen Omni Flash、DeepSeek V4 Flash、MiniMax。基本レートです。","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus、Qwen 3.5 Omni Plus。","credits.overview#12#li3":"1.4× — Mistral Large 3（Aurora コーディネーター）。Qwen 3.6 Plus とほぼ同等です。","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus（Maestro コーディネーター）。","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro（Supernova コーディネーター＋重厚な専門家）。公開されている V4 Pro レートでマージンのバランスを保つため、5.0×から再調整されました。","credits.overview#13#c":"Anthropic モデル（Claude Opus / Sonnet / Haiku）はクレジット課金が一切かかりません — BYOK のみで、料金は Anthropic に直接支払われます。他の BYOK プロバイダーを自分のキーで使用する場合も同様です。","credits.overview#14#h":"BYOK とクレジットについて","credits.overview#15#p":"BYOK（\"bring your own key\" — つまり、AI プロバイダーへのアカウントとキー（有料アカウントを使用するための秘密のパスワード）を自分で用意すること）は、すでに AI プロバイダーに直接支払いを行っている方向けです。該当しない場合は、このセクションは無視して大丈夫です。","credits.overview#16#p":"BYOK リクエストはプラットフォームのインフラを完全に迂回します — 通信は Ava からプロバイダーへ直接行き、料金はプロバイダーに直接支払い、クレジットは消費されません。唯一の例外は、BYOK セッション内でサブタスクのために管理型ペルソナが起動される場合です。この場合、Ava のオーケストレーション機能が使われているため、クレジットの引き落としが発生します。","credits.overview#17#h":"残高の確認場所","credits.overview#18#li0":"エクステンション — 設定 → アカウント、またはチャットヘッダーのクレジット表示。","credits.overview#18#li1":"IDE — アカウントダッシュボードのタイルで、現在の残高と使用率を確認できます。","credits.overview#18#li2":"Web — ava-supernova.com/dashboard で残高、履歴、更新日を確認できます。","credits.overview#19#c":"ローカルファースト：Ava はカスタムモデルカード上でアカウントなしで動作します（Ollama、LM Studio、vLLM、またはあらゆる OpenAI 互換エンドポイント）。クレジットもプラットフォームトークンも不要 — あなたのモデル、あなたのマシン、請求額はゼロです。","concepts.modes#title":"モード — Ava の思考状態","concepts.modes#0#p":"モードは、Ava が今どんな心持ちでいるかを示すものです。帽子をかえる同僚に例えてみましょう。同じ人、あなたについての記憶も同じですが、ビルダーと先生では考え方が違います。モードを選べば、彼女の振る舞いや連れてくるヘルパーが変わります。モードセレクターでいつでも切り替えられますし、2 文字のショートカットを入力してもいいですよ。","concepts.modes#2#h":"どれを選びますか？","concepts.modes#3#p":"やりたいことから始めてください。それに合わせてモードが決まります：","concepts.modes#4#li0":"何かを作ったり変更したい → コード (>>)。あなたが説明すれば、彼女が作ってくれます。すべての変更点をまず見せてくれます。大きな仕事にはフルチームが動きます。","concepts.modes#4#li1":"変更する前に計画が欲しい → プラン (::)。よく考えてから、承認または編集できる計画を渡します。このモードではファイルに触れません。","concepts.modes#4#li2":"ただ話したり聞きたいだけ → チャット (..)。記憶、ニュース、天気を知っている思考のパートナー。ファイル変更もコードもなし。会話だけです。","concepts.modes#4#li3":"何か学びたい → ティーチ (??)。あなた専用の本格的なコース：レッスン、クイズなどすべて。すべてのプランで永久無料。初心者におすすめです。","concepts.modes#4#li4":"プロジェクトのセキュリティ穴をチェックしたい → セキュリティ (!!)。チームが一般的なウェブ脆弱性の標準リスト（the \\\"OWASP\\\" カテゴリ）と既知の報告された欠陥（called \\\"CVEs\\\"）を確認し、深刻度順にレポートを渡します。開発者向けです。該当なければスキップしてください。","concepts.modes#4#li5":"アイデアが欲しい → ブレインストーミング (**)。実際の状況に基づいて選択肢を生成し、弱い点を突っ込み、残りを次のステップに磨き上げます。","concepts.modes#4#li6":"文書を書きたい → ライティング (<<)。レポート、提案書、手紙、記事など。Markdown で下書きし、ブランド付きの Word ドキュメントや PDF にエクスポート。セクションごとに推敲。コードなし、ライティングのみ。","concepts.modes#5#c":"「ヘルパーチーム」（ペルソナ）は完全に裏方として動きます。直接話すことはありません。より丁寧な回答が得られるだけです。名前を知る必要はありません。","concepts.modes#6#c":"会話中にモードを切り替えられます。あなたの記憶は引き継がれます。専門家は新しいモードに合わせてリセットされます。","concepts.tasks-journal#title":"タスクとジャーナル","concepts.tasks-journal#0#p":"Ava はあなたのために 3 種類のメモを残しています。混同しやすいので、覚え方のコツ：記憶は Ava があなたについて知っていること、タスクはまだやるべきこと、ジャーナルは出来事の日記です。それぞれいつ使うかはこちら。","concepts.tasks-journal#1#li0":"記憶 — 永続的な事実。好み、決定、パターン。繰り返し聞かれることが多く、手動で作られることはほとんどありません。","concepts.tasks-journal#1#li1":"タスク — やること。期限とステータスのあるアクションアイテム。終わったらチェックを入れます。","concepts.tasks-journal#1#li2":"ジャーナル — 振り返り。日々のログ、ダブルエントリー（あなたとセッションに関する Ava の観察）。気分トラッキング、セッションレビュー、明日のための文脈に役立ちます。","concepts.tasks-journal#2#p":"Ava は意味があるときは 3 つすべてに記録します。ダッシュボードから直接どれにも書き込めます。Ava を使う場所は一つに限定されていません。ある場所（例えばコマンドラインツール）で作成したタスクは、他の場所（デスクトップアプリなど）にも自動的に表示されます。","concepts.permissions#title":"パーミッション — あなたの安全ダイヤル","concepts.permissions#0#p":"パーミッションはあなたの安全ダイヤルです。Ava がコンピュータ上で何かをする前に許可を求めるときか、そのまま進めるかを決めます。すべて聞く設定、危険なものだけ聞く設定、信頼して任せる設定ができ、いつでも変更できます。わからない場合はデフォルトのままにしておけば大丈夫です。","concepts.permissions#1#p":"Ava には 60 のツールがあります（「ツール」とはファイルを読む、ウェブを検索するなど実行可能なアクションのことです）。各ツールはカテゴリに属します（ファイル操作、シェル、git、ウェブ、メディア、データベース、システム、ドキュメント、記憶、学習）。すべてのツール呼び出しは実行前にパーミッションゲート（最初に聞くかどうかを決めるチェックポイント）を通ります。自動承認されるもの、一度聞くもの、常に聞くものを制御できます。","concepts.permissions#3#p":"デフォルトはバランス型です。監査中（各ステップを細かく確認したいとき）は厳格型。ただ任せたいときは自律型。","concepts.permissions#4#c":"自律型でも無制限ではありません。計画、確認質問、ユーザーへの明確な問いかけは入力待ちになります。元に戻せない操作（git force-push、データベース削除など）はモードに関わらず必ず確認します。","concepts.interjection#title":"Ava の操縦と停止","concepts.interjection#0#p":"あなたがいつも主導権を持っています。Ava が作業中の間、方向転換を促して流れを壊さずに進めたり、完全に停止させたりできます。2 つのボタン、2 つの結果 — これがこのページのすべてです。","concepts.interjection#1#p":"Ava は計画が完了するか、あなたが停止するまで実行を続けます。実行中に介入（この行為の用語は「インタージェクト」です）するには、2 つの方法があります。","concepts.interjection#2#h":"インタージェクト — キャンセルせずに方向転換","concepts.interjection#3#p":"Ava が作業中にある新しいメッセージを入力してください。彼女は現在のツール呼び出しを完了し、あなたのメッセージを読み取り、計画を調整します。コンテキストは失われません。実行中にリダイレクトしたい場合、情報を追加したい場合、優先順位を変更したい場合にこれを使用してください。","concepts.interjection#4#h":"ハードストップ — キャンセルしてクリア","concepts.interjection#5#p":"Escape キーを押す（CLI）、クリックで停止（拡張機能、IDE）、または停止コマンドを入力します。現在のランがキャンセルされ、保留中のツール呼び出しは破棄され、会話は新しいターンに向けて準備が整います。","concepts.interjection#6#c":"まずインタージェクトしてください。ハードストップは本当に問題がある場合にのみ使用します。インタージェクトすることでスレッドを維持できます。","concepts.desktop-personas#title":"デスクトップ・ペルソナ","concepts.desktop-personas#0#p":"このページは、詳しく知りたい方や上級者向けです。「デスクトップ自動化」（「コンピューター操作」とも呼ばれます）とは、Ava が実際に画面をクリックしてアプリを操作できることを意味します — Gmail を開いたり、フォームに入力したり、メッセージを送信したり — キーボードの前にいる人間のよう。安全に行うために、仕事は 5 つの小さなアシスタントに分担されます。それぞれが特定の役割を持ちます。あなたが直接関わることはありません。ここでは、それぞれの担当者が何をするのかをご紹介します。","concepts.desktop-personas#1#p":"デスクトップの軌跡（Ava が画面を操作して目標に向かう 1 つの実行）のすべてのステップで、5 つのペルソナによる一連の動きが実行されます。各ペルソナには 1 つの仕事しかありません。この分離により、プロンプトは簡潔に、出力は構造化され、推論は意図的に慎重に行われます。","concepts.desktop-personas#2#h":"スカウト","concepts.desktop-personas#3#p":"現在画面に表示されているものを報告します。要素を発明しません。計画も立てません。要素 ID、名前、バウンディングボックス、信頼度、およびグラウンディングソース（UIA、Playwright DOM、または OmniParser ビジョン）を含む ScreenState JSON を返します。","concepts.desktop-personas#4#h":"プランナー","concepts.desktop-personas#5#p":"次の単一のアクションを決定します。ステップごとに 1 つのアクション — バッチ処理はしません。元に戻せる経路を好みます。安全性オントロジーに基づいてリスクを分類します。種別、ターゲット、パラメータ、riskClass、推論、および予想される後状態予測を含む ProposedAction JSON を出力します。","concepts.desktop-personas#6#h":"アクター","concepts.desktop-personas#7#p":"承認ゲートを通過した後、プランナーが提案した内容を正確に実行します。即興はしません。再試行もしません。失敗は忠実に報告され、次なる動きは Verifier が処理します。","concepts.desktop-personas#8#h":"ベリファイア","concepts.desktop-personas#9#p":"アクションが成功したかどうかを確認します。最新の ScreenState をプランナーの予測と比較します。検証済み、逸脱、またはロールバックが必要と判断します。また、ループ検出を実行します — すでに成功したアクションを繰り返すことは、検証ではなく逸脱です。","concepts.desktop-personas#10#h":"ナレーター","concepts.desktop-personas#11#p":"一連の作業の間、ユーザーが聞く唯一の声です。ステップごとに過去形の文を 1 つ（「Gmail を開きました。」、「Compose をクリックしました。」）。構造化された監査ログも作成します。何か問題があったときは言います — 問題を隠すことはありません。","concepts.desktop-safety#title":"デスクトップ・セーフティ・オントロジー","concepts.desktop-safety#0#p":"簡単に言うと：Ava が画面の何かをクリックする前に、そのアクションのリスクレベルで分類します。画面を読むだけ？無害です。送金や削除？彼女は必ず一度止めてあなたに確認します — 毎回例外なく。以下の 5 つのラベルは、そのリスク梯子の段にすぎません。これはパワーユーザー向けの詳細ですが、要点はシンプルです：危険なものは常にあなたの許可が必要です。","concepts.desktop-safety#1#p":"提案されたすべてのアクションは、5 つのリスククラスのいずれかに分類されます。分類は 3 つの信号を組み合わせたものです — 画面上のターゲットが何であるか、それの平易な言語での説明（「セマンティックキャプション」— Ava が見ているものについての自分の言葉）、そしてアクションの設定 — そしてそれらが不一致の場合はエスカレーションします（より危険だと扱います）。偽陽性（必要ないのに尋ねる）はただの煩わしさです。偽陰性（尋ねるべきなのに尋ねない）はサービス終了につながる事故です。","concepts.desktop-safety#2#h":"5 つのクラス","concepts.desktop-safety#3#li0":"観測的 — UIA ツリー、スクリーンショット、ホバーを読む。常に自動許可。","concepts.desktop-safety#3#li1":"移動的 — スクロール、フォーカスを移動、メニューを開く。ドライブモードでは自動許可。","reference.cli#5#li3":"--project <path> — プロジェクトのルートディレクトリを明示的に設定します。","reference.desktop-budget#title":"デスクトップ予算の上限","reference.desktop-budget#0#p":"Ava があなたの代わりにデスクトップを操作するときは——クリックやタイピング、アプリの起動など——それぞれの実行を「トラジェクトリ」と呼びます。このページでは、一度の実行が長く続いたりコストがかさんだりしないよう、安全な制限を設けています。結論から言うと、彼女はオーバーランする前に必ず止まって確認します。詳しい数字はここにあります。","reference.desktop-budget#1#p":"すべてのトラジェクトリは、同時に適用される 3 つの上限（ハードリミット）の下で実行されます。最初に到達したものが有効になります。違反してもトラジェクトリは静かに続行せず、ナレーター（進行状況を教えてくれるお手伝い役）が一時停止して、どうするか尋ねます。","reference.desktop-budget#2#h":"3 つのハード上限（デフォルト）","reference.desktop-budget#3#li0":"ステップ数 — 30 ステップ","reference.desktop-budget#3#li1":"トークン予算 — 500,000 トークン","reference.desktop-budget#3#li2":"実時間 — 5 分","reference.desktop-budget#4#h":"タスクのコスト帯域","reference.desktop-budget#5#li0":"シンプル（ドキュメント検索、ページを開く）— 5〜10 ステップ、約 70–135K トークン、約 $0.04–0.08","reference.desktop-budget#5#li1":"ミディアム（ログイン、ログ確認、出力のダウンロード）— 15〜25 ステップ、約 205–340K トークン、約 $0.12–0.21","reference.desktop-budget#5#li2":"複雑（GitHub の課題 3 つの整理）— 25〜30 ステップ、約 340–410K トークン、約 $0.21–0.25","reference.desktop-budget#6#p":"上記のトークン数は、1 回の実行あたりの技術的な上限であり、月間の利用枠ではありません。月間枠はクレジットでカウントされ、無料プランの月 300 は、チャット、コード、そしていくつかの自動化を組み合わせても十分にカバーできます。","reference.desktop-budget#7#c":"開始時にタスクごとに上限を上書きすることもできますが、違反が発生すると必ず判断ポイントが表示されます。予算が静かに消費されることはありません。","reference.desktop-whitelist#title":"デスクトップセッションのホワイトリスト","reference.desktop-whitelist#0#p":"`ホワイトリスト`とは、Ava がデスクトップを操作している間に触れてよいとあなたが許可したアプリとウェブサイトのリストのことです。このページでは、その許可を与える方法と、なぜ毎回リセットされるのかを説明しています。簡単に言うと：彼女はあなたが許可した場所でのみ行動でき、新しい場所に行く前には必ず聞いてきます。","reference.desktop-whitelist#1#p":"デスクトップセッションの開始時、Ava はどこで行動できるか尋ねてきます。簡単な英語で構いません：「Gmail、Cursor、Azure ポータル」。彼女はそれを読み取り、あなたに一致を確認します（「Gmail ウェブ、Cursor アプリ、portal.azure.com」）。","reference.desktop-whitelist#2#h":"どのように管理するか","reference.desktop-whitelist#3#p":"見るだけのアクション——スクリーンショットの取得、画面上のボタンやフィールドのリストを読むこと（「UIA ツリー」、Windows が持つウィンドウ内のマッピング）——はどこでも許可されています。なぜなら、アプリをホワイトリストに追加するかどうかを決めるために画面にあるものを見る必要があるからです。何かを変更するものはリスト外ではブロックされ、Ava が一時停止して追加するか尋ねます。","reference.desktop-whitelist#4#h":"意図的にセッション限定","reference.desktop-whitelist#5#p":"ホワイトリストはセッション間で継続しません。「このアプリを記憶する」というオプションはありません。新しいトラジェクトリは常に新しいスコープから始まります。あえて不便にしています——再承認を忘れるのはバグではなく、機能なのです。","reference.desktop-whitelist#6#h":"実行中の追加","reference.desktop-whitelist#7#p":"実行中、ヘッダーからアプリを追加できます：「+ アプリを許可」を開くと小さな入力欄が表示されます。「追加」をタップすると、新しいアプリはそのセッション残りで有効になります。","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"画像、短い動画、曲、または音声ボイスオーバーを作りたいですか？それを説明するだけで、Ava が作ってくれます——デザインやオーディオソフトウェアは不要です。","features.creative-studio#1#p":"画像、動画、音楽、音声の生成 — あなたのコードと同じワークフローの中に組み込まれています。アイコンや製品のモックアップ、デモ動画、チュートリアルのナレーションなどを生成可能です。MiniMax の技術を活用しています。","features.creative-studio#2#h":"あなたが作れるもの","features.creative-studio#3#li0":"画像 — プロンプトで PNG/JPG を作成。背景削除もすぐに行えます。","features.creative-studio#3#li1":"動画 — テキストプロンプトから短い AI 動画を生成（MiniMax Hailuo）。","features.creative-studio#3#li2":"音楽 — インストルメンタル曲や、歌詞付きボーカルトラックなど。","features.creative-studio#3#li3":"音声 — 好みの声を選べるテキスト読み上げ機能。","features.creative-studio#4#p":"Creative Studio の利用料金は、他の機能と同じクレジットプールから消費されます — プールは一つ、管理も簡単。独自の MiniMax キーを BYOK すれば、プラン内では無料でご利用いただけます。","features.creative-studio#5#c":"Creative Studio は無料枠でも利用可能です。追加課金が必要なオプションではありません。","features.desktop-automation#title":"デスクトップ操作の自動化","features.desktop-automation#0#p":"簡単に言うと：Ava がマウスやキーボードを代わりに操作してタスクをこなしてくれます — アプリを開いたり、ボタンを押したり、フォームに入力したり。あなたは見守りつつ、重要な決定だけを手動で承認できます。","features.desktop-automation#1#p":"Ava の新モード「@@」です。デスクトップを観察し、何をするべきかを判断して UI 自動化を駆動します（画面上のアプリをあなたのために操作）。クラウドブラウザではなく、実際のマシン上で実際のアカウント情報を使って動作します。リリース後はすべてのプランで利用可能です。","features.desktop-automation#2#h":"他の製品との違い","features.desktop-automation#3#p":"他のデスクトップ自動化ツールは、机に向かった時に起動するものです。しかし Ava は、2am にエラー通知が鳴っても待機しています — IDE は稼働したまま、スマホは安全なチャネルで接続され、タップ一つで取り返しのつかない操作も承認できます。","features.desktop-automation#4#p":"さらに、Ava はセッションを超えてアプリの操作方法も記憶しています。他のエージェントは毎回最初から学び直しますが、Ava の記憶機能は使うほどにその価値を高めていきます。","features.desktop-automation#5#h":"仕組みについて","features.desktop-automation#6#p":"各ステップでは 5 つの役割が連携します：Scout が状況を観察し、Planner が次の行動を決め、Actor が実行し、Verifier が確認し、Narrator が結果を伝えます。サイドカーが最も安価で確実な手段を選びます — ネイティブアプリなら UIA、ブラウザなら Playwright、それ以外に適した構造がない場合は OmniParser のビジョン機能を使います。","features.desktop-automation#7#p":"安全性の概念、基盤の階層、緊急停止スイッチ、セッションホワイトリストモデルについては、コンセプトページをご覧ください。","concepts.desktop-safety#3#li2":"変更可能で元に戻せる — フィールドへの入力、貼り付け、アプリの起動、URL の移動。Ask モードでは確認が必要ですが、ホワイトリスト内の Drive では自動で行われます。","concepts.desktop-safety#3#li3":"変更不可（元に戻せない） — 送信、提出、支払い、削除、確認、公開。許可レベルに関わらず、毎回必ず確認が必要です。承認内容はキャッシュされません。","concepts.desktop-safety#3#li4":"特権操作 — UAC 昇格、sudo、レジストリ編集、認証プロンプト。デフォルトでは禁止されています。セッションごとに一度限りのオプトインが必要です。","concepts.desktop-safety#4#h":"承認はキャッシュされません","concepts.desktop-safety#5#p":"すべての競合他社は承認をキャッシュします（あなたの「はい」を覚えて、次回再利用してしまいます）。これがプロンプトインジェクション攻撃の最大の足掛かりです — 罠を仕掛けられた Web ページが AI に隠れた指示を忍ばせ、あなたに不利な行動をとらせる攻撃のことです。承認がキャッシュされていれば、乗っ取られたページが以前与えた「はい」に乗っかることができます。Ava は決してキャッシュしません。それぞれの変更不可アクションは、毎回新鮮に（新たに）確認を求めます。","concepts.desktop-safety#6#h":"シークレットの扱い","concepts.desktop-safety#7#p":"パスワード、API キー、2FA コード（ログイン時に別のアプリやテキストメッセージから受け取るワンタイムコード）は、実体を見せないハンドル（実際の値に代わるプレースホルダー）を通じて扱われます。Ava が目にするのは「{secret}」だけで、実際のパスワードではありません。実際の値は、Ava のメモリやアクティビティログ、あるいは彼女が「読み込む」内容には一切入りません — 別の低レベルのレイヤーが最後の瞬間、キーを押したタイミングで直接入力するため、AI 部分がそれに触れることはありません。","reference.cli#title":"CLI コマンド","reference.cli#0#p":"このページは CLI 向けです — ボタンをクリックするのではなく、ターミナルウィンドウで文字を入力して使う Ava のバージョンです。拡張機能やデスクトップアプリをお使いの場合は、このページを完全に飛ばしても問題ありません。こちらはキーボード操作を好む方のために用意されています。","reference.cli#1#p":"CLI は REPL（対話型プロンプト）です — 入力を待ち、実行し、また待機するというサイクルです。これらのスラッシュコマンド（「/」で始まる指示）は、このプロンプトから使用できます。","reference.cli#2#li0":"/help — コマンド一覧と現在のモードを表示。","reference.cli#2#li1":"/mode <名前> — モードを切り替えます（work, write, plan, chat, teach, security, brainstorm）。","reference.cli#2#li2":"/model <ID> — セッションを離れずにモデルを切り替えます。","reference.cli#2#li3":"/clear — 現在の会話をクリアします。メモリは影響を受けません。","reference.cli#2#li4":"/history — このプロジェクト内の過去の会話の一覧を表示。","reference.cli#2#li5":"/memory — メモリブラウザを開きます。","reference.cli#2#li6":"/tasks — タスクの一覧表示と管理。","reference.cli#2#li7":"/journal — 今日のジャーナルエントリを開きます。","reference.cli#2#li8":"/settings — 設定メニューを開きます。","reference.cli#2#li9":"/exit — REPL を終了します。","reference.cli#3#h":"起動フラグ","reference.cli#4#p":"フラグは、Ava を起動する際に加えるオプションです。それぞれ「--」で始まり、どのように起動するかを設定します。","reference.cli#5#li0":"--mode <名前> — 特定のモードで開始します。","reference.cli#5#li1":"--model <ID> — 特定のモデルで開始します。","reference.cli#5#li2":"--permission <モード> — 厳格 / バランス / オートノマス。"},"ko":{"start.for-non-coders#6#li3":"실제로 무언가를 만들거나 수정하고 싶다면 그냥 말씀해 주세요. Ava 는 항상 자신이 무엇을 하려는지 보여드리고 당신의 \"예\"를 기다립니다.","start.for-non-coders#7#c":"낯선 단어를 만나셨나요? 이 섹션 아래에 있는 쉬운 영어 용어집은 기초 지식이 없어도 모든 용어를 설명해 드립니다.","start.install#title":"설치하기","start.install#0#p":"작업 방식에 맞는 환경을 선택하세요. 여러 곳을 함께 사용해도 괜찮습니다. 로그인하면 Ava 가 모든 환경에서 기억을 공유합니다.","start.install#1#h":"VS Code 확장 프로그램","start.install#2#li0":"VS Code 에서 확장 프로그램 패널을 엽니다 (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"\"Ava Supernova\" 를 검색하고 설치를 클릭하세요.","start.install#2#li2":"채팅 패널을 열려면 Ctrl+Shift+A 를 누르세요 (macOS 는 Cmd+Shift+A).","start.install#2#li3":"설정 마법사를 따라 진행하세요. 모델을 선택하고 권한 모드를 설정하면 끝입니다.","start.install#3#h":"데스크톱 IDE","start.install#4#li0":"릴리스 페이지에서 플랫폼용 설치 파일을 다운로드하세요.","start.install#4#li1":"실행하세요. 처음 실행할 때 IDE 가 환영 화면으로 시작됩니다.","start.install#4#li2":"무료 플랫폼 토큰을 받으려면 로그인하거나, 완전히 로컬로 실행하려면 직접 API 키를 붙여넣으세요.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (or pnpm / yarn — your choice).","start.install#6#li1":"어떤 프로젝트 디렉토리에서도 ava 를 실행하세요.","start.install#6#li2":"처음 실행 시 제공자와 모델을 물어봅니다. 선택하고 시작하세요.","start.install#7#c":"계정이 없어도 괜찮습니다. 직접 API 키 (BYOK) 를 사용하면 로그인할 필요가 없습니다. 무료 티어는 플랫폼 관리 모델용입니다.","start.for-non-coders#title":"한 번도 코드를 써본 적이 없나요? 여기부터 시작하세요","start.for-non-coders#0#p":"한 줄의 코드도 써본 적이 없다면, 바로 당신을 위한 도구예요. 시작하려면 전문 용어를 배울 필요 없어요. 지식이 많은 친구에게 묻듯이 평범한 말로 대화하면 됩니다. 이 페이지가 당신의 유일한 진입로입니다.","start.for-non-coders#1#h":"경험 없이 오늘 할 수 있는 것들","start.for-non-coders#2#li0":"평범한 말로 아무거나 물어보세요 — \"이 파일이 뭐 하는 건데요?\", \"내 페이지가 왜 비어 있나요?\", \"데이터베이스가 도대체 뭐예요?\" 그녀는 쉬운 말로 답변하고 대화 내용도 기억해 줍니다.","start.for-non-coders#2#li1":"처음부터 하나씩 배우세요 — \"제로부터 Python 가르쳐줘\"라고 하면 수업과 퀴즈가 포함된 제대로 된 커리큘럼을 만들어 줍니다. 이건 항상 무료예요.","start.for-non-coders#2#li2":"무언가를 만들어 보세요 — 원하는 것을 설명하면 (예: \"내 노트를 다운로드하는 버튼\") Ava 가 작성해 주고, 적용되기 전에 모든 변경 사항을 먼저 보여줍니다.","start.for-non-coders#3#h":"모든 걸 이해할 필요는 없어요","start.for-non-coders#4#p":"Ava 는 표면 아래에 많은 장치들이 숨어 있어요 — 모드, 모델, 전문가, 라우팅 같은 것들이죠. 앱과 문서에서 이런 단어들을 보실 수 있습니다. 하지만 비밀은 간단해요: 대부분 무시해도 괜찮습니다. Ava 가 알아서 올바른 도구와 도우미를 골라주기 때문이죠. 기술적인 페이지들은 궁금증이 생겼을 때 참고용일 뿐, 시작하려면 꼭 알아야 하는 내용은 아닙니다.","start.for-non-coders#5#h":"부드러운 첫걸음","start.for-non-coders#6#li0":"Ava 를 설치한 뒤 (다음 페이지) 채팅을 열어보세요.","start.for-non-coders#6#li1":"진짜 가지고 계신 질문을 입력해 보세요. 아무거나 좋습니다. 어떻게 답변하는지 확인해 보세요.","start.for-non-coders#6#li2":"학습 모드를 시도해 보세요: \"teach me\"와 주제를 입력하고 따라 가세요.","concepts.memory#title":"기억 — Ava 가 당신을 어떻게 기억하는지","concepts.memory#0#p":"쉽게 말해서: Ava 는 당신을 기억합니다. 한 번만 알려주세요 — 좋아하는 것, 내린 결정 등 — 그러면 그녀는 그것을 보관해 두어 다음 채팅이나 다음 주에 반복할 필요가 없습니다. 이것이 핵심입니다. 아래의 층들은 시간이 지나도 그 기억을 깔끔하게 유지하는 방법을 설명할 뿐입니다.","concepts.memory#1#p":"Ava 는 지속 가능한 메모리를 가지고 있어요. (\"지속 가능\"은 앱을 닫아도 기억이 남아 있다는 뜻입니다.) 동기화를 활성화하면 기기간에 메모리가 공유되죠. 이건 단순한 채팅 로그가 아니라, 당신이 누구인지, 무엇을 좋아하는지, 어떤 결정을 내렸는지에 대한 구조화된 이해예요.","concepts.memory#2#h":"다섯 가지 층","concepts.memory#3#li0":"추출 — 실시간으로 모든 메시지에서 핵심 사실을 포착합니다.","concepts.memory#3#li1":"반성 — 의미 있는 세션이 끝나면 더 깊은 분석이 실행됩니다. 패턴, 주제, 모순점 등을 파악하죠.","concepts.memory#3#li2":"축적 — 수정 사항과 선호도가 수주, 수개월에 걸쳐 누적됩니다.","concepts.memory#3#li3":"분석 — 그래프 엔진이 관련 메모리를 연결하고, 새로운 정보가 기존 정보와 충돌할 때 모순점을 표시합니다.","concepts.memory#3#li4":"통합 — 유사한 메모리는 합쳐지고, 오래된 것은 정리됩니다. 시간이 지날수록 메모리는 더 선명해지지 소음은 많아지지 않아요.","concepts.memory#4#c":"위의 다섯 가지 층은 자동으로 작동하므로 직접 관리할 필요가 없어요. 시간이 지나면서 메모리가 실제로 개선되는 것을 확인할 수 있도록 돕기 위한 것이죠, 단순히 쌓이는 잡다한 정보로 변하지 않도록요.","concepts.memory#5#h":"검색","concepts.memory#6#p":"질문을 하면 Ava 는 단어 일치뿐만 아니라 의미 (의미 기반 검색 — 당신이 무엇을 원하는지 이해하므로 표현이 달라도 올바른 메모리를 찾습니다) 로 메모리를 검색해요. 모드별 필터도 함께 작동하죠. 채팅 모드는 개인 컨텍스트를 가져오고, 작업 모드는 프로젝트 결정 사항과 코드 패턴을 가져옵니다.","concepts.memory#7#c":"메모리는 사용자별 및 프로젝트별로 범위가 정해져 있어요 (메모리는 당신 것이며 사람과 프로젝트별로 분리되어 보관됩니다). 비밀 정보와 자격 증명 (비밀번호, 키) 은 저장 시점에 차단되며, 절대 메모리에 저장되지 않습니다.","concepts.desktop-grounding#title":"데스크톱 그라운드 계층 구조 (미리보기)","concepts.desktop-grounding#0#c":"미리보기 — Scout 이 각 단계마다 어떤 그라운드 소스를 사용할지 결정하는 방법.","concepts.desktop-grounding#1#p":"Ava 가 버튼을 클릭하려면 먼저 화면에 무엇이 있고 어디에 있는지 실제로 이해해야 합니다 — 이를 \\\"그라운드\\\"라고 합니다 (화면의 각 사물이 무엇인지와 정확한 위치를 파악하는 것). 그녀는 세 가지 방법으로 이를 수행하며, 사용 중인 앱에서 작동하는 가장 신뢰할 수 있는 방법을 선택합니다. 이는 심도 있는 파워 유저용 세부 사항이지만, 핵심은 그림에서 추측하는 것보다 견고하고 정확한 방법을 선호한다는 점입니다.","concepts.desktop-grounding#2#p":"세 가지 등급이 순서대로 평가됩니다. 가장 저렴하면서도 신뢰할 수 있는 소스가 우선입니다.","concepts.desktop-grounding#3#h":"1. 브라우저 창 → Playwright DOM","concepts.desktop-grounding#4#p":"활성 창이 웹 브라우저라면, Ava 는 그림에서 추측하는 대신 페이지 자체의 구조 (\\\"DOM\\\" — 페이지에 무엇이 있는지 나타내는 밑바닥 목록) 를 읽습니다. 구조를 읽는 것은 픽셀을 눈으로 보는 것보다 약 10× 더 신뢰할 수 있습니다 — 그녀는 각 버튼의 정확한 위치와 페이지 로딩이 완료되었는지 정확히 압니다. 이는 백업이 아닌 웹상의 모든 것에 대한 주요 경로입니다.","concepts.desktop-grounding#5#h":"2. 네이티브 앱 with UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Windows 의 일반 데스크톱 앱의 경우, Ava 는 내장 접근성 맵 (\\\"UIA\\\", 화면 판독기가 창을 설명하는 데 사용하는 동일한 데이터) 을 읽습니다 — 각 컨트롤, 이름, 위치를 나열합니다. 해당 맵이 최소 5 개의 사용 가능한 명명된 항목을 반환하면, 그녀는 그것을 신뢰하고 사용합니다.","concepts.desktop-grounding#7#h":"3. UIA 공백 또는 잡음 → OmniParser 비전","concepts.desktop-grounding#8#p":"해당 맵이 없거나 쓸모없을 때 (일부 앱, 게임, 원격 화면은 제공하지 않음), Ava 는 스크린샷을 실제로 보는 것으로 대체합니다. 비전 도구 (OmniParser) 가 클릭 가능한 영역을 찾고 각 영역이 무엇을 하는지 라벨을 붙여, 접근성 맵이 제공한 작은 정보와 함께 그녀가 행동할 수 있는 목록으로 이미지를 변환합니다.","concepts.desktop-grounding#9#c":"OmniParser 는 Ava 가 처음 필요로 할 때 사용자가 직접 동의 (옵트인) 하며 명확한 개인정보 보호 프롬프트가 표시됩니다. BYOK 사용자는 자신의 로컬 OmniParser 배포를 가리킬 수 있습니다.","concepts.desktop-kill-switches#title":"데스크톱 킬 스위치 (미리보기)","concepts.desktop-kill-switches#0#c":"미리보기 — 실행 중인 작업 흐름을 중단할 수 있는 세 가지 독립적인 방법. 그중 하나만으로도 충분합니다.","concepts.desktop-kill-switches#1#p":"\\\"킬 스위치\\\"는 말 그대로 Ava 가 당신의 화면을 제어할 때 즉시 중단할 수 있는 비상 수단입니다. 안심되는 점은 세 가지가 있다는 것입니다. 각각 별도로 구축되어 하나라도 고장 나면 다른 것이 작동합니다. 세 가지 모두 배울 필요는 없습니다. 단지 무언가가 잘못 보이는 경우 언제든지 멈출 수 있다는 것만 알면 됩니다. 그리고 가장 강력한 중지 (아래의 패닉 킬) 는 Ava 의 협력이 필요하지 않습니다.","concepts.desktop-kill-switches#2#p":"공개된 자율성 사고 (AI 에이전트가 중지 명령을 무시하고 이메일 보관함을 삭제하거나 드라이브를 초기화한 실제 사례) 를 모두 읽은 후, 우리는 세 가지 다른 레이어에 세 가지 킬 스위치를 구축했습니다. 어느 것도 AI 모델 자체에 의존하지 않습니다 — Ava 가 막히거나 응답하지 않아도 여전히 그녀를 멈출 수 있습니다.","concepts.desktop-kill-switches#3#h":"일시정지 — 스페이스바 또는 일시정지 버튼","concepts.desktop-kill-switches#4#p":"다음 단계 경계에서 일시 정지됩니다. 재개 가능합니다. 진행 방향을 잃지 않고 개입하고 싶을 때 사용하세요.","concepts.desktop-kill-switches#5#h":"중지 — Esc 키 또는 중지 버튼","concepts.desktop-kill-switches#6#p":"깔끔하게 중단합니다. 내레이터가 지금까지 한 일을 요약합니다. 재개할 수 없습니다. 감사 로그가 기록됩니다.","concepts.desktop-kill-switches#7#h":"비상 종료 — Esc 세 번 또는 Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"가장 강력한 중단 방법입니다. 화면을 제어하는 Ava 의 부분을 강제 종료하는 작은 독립 감시 프로그램입니다. AI 가 응답할 때까지 기다리지 않으며, 앱 창이 작동 중일 필요도 없고 상태에 상관없이 바로 종료합니다. 정말로 문제가 생겼을 때 사용하는 방법입니다.","concepts.desktop-kill-switches#9#p":"이 세 가지 모두 보조 앱에서도 작동합니다. 어느 방식이든 작동을 멈출 수 있어요.","reference.tools#title":"도구 참조","reference.tools#0#p":"Ava 가 가진 모든 도구의 전체 목록입니다. 여기서 \"도구\"란 파일을 읽거나 검색을 실행하는 것처럼 Ava 가 수행할 수 있는 특정 행위를 의미합니다. 이 페이지를 꼭 읽을 필요는 없어요. Ava 는 매번 적절한 도구를 스스로 선택합니다. Ava 가 정확히 무엇을 할 수 있는지 궁금할 때 참고용으로 마련된 페이지입니다.","reference.tools#1#p":"기본 제공되는 전체 도구 상자입니다. 여기에 있는 모든 도구는 코어 런타임 (세 가지 인터페이스 아래의 엔진) 에 등록되어 있으며, 모드 및 권한 설정이 허용할 때 Ava 가 사용할 수 있습니다. 카테고리나 위험 수준별로 필터링하세요.","reference.tools#2#p":"이를 다 외울 필요는 없어요. 아래 표는 참고용 카드일 뿐입니다.","reference.tools#4#h":"위험 수준","reference.tools#5#li0":"안전 — 아무것도 변경하지 않고 읽기만 합니다. file_read, glob (이름 패턴으로 파일 찾기), grep (파일 내부에서 텍스트 검색), git_status (Git 은 프로젝트 변경 사항을 추적하는 시스템입니다).","reference.tools#5#li1":"쓰기 — 파일을 변경하거나 작업의 체크포인트를 저장합니다 (\"커밋\"), 새 무언가를 생성합니다. file_edit, git_commit, generate_image.","reference.tools#5#li2":"위험 — 컴퓨터에서 명령어를 실행합니다 (\"쉘\"), 데스크톱을 제어하거나 인터넷에 접속하며, 데이터베이스를 쿼리합니다. bash, browser, desktop_*.","reference.tools#6#c":"페르소나 전문가는 각각 고유한 도구 허용 목록을 가집니다. 스카우트는 읽기만 가능하고 쓰기는 불가능합니다. 빌더는 전체 접근 권한을 가집니다. 챌린저는 도구가 전혀 없습니다 — 역할은 계획을 질문하는 것입니다.","reference.models#title":"모델","reference.models#0#p":"\"모델\"은 사고하는 AI 두뇌입니다. Qwen, DeepSeek, Mistral 등 다양한 모델이 있습니다. 이 페이지에는 Ava 가 사용할 수 있는 모든 모델이 나열되어 있습니다. 간단히 말해, 직접 선택할 필요는 없습니다. Ava 가 각 단계마다 적절한 모델을 스스로 선택합니다. 이해하거나 이를 우회하고 싶을 때만 읽어보세요.","reference.models#1#p":"Ava 가 라우팅할 수 있는 모든 모델과 세 가지 오케스트레이션 전략 — 작업의 각 부분을 어떤 모델이 처리할지 결정하는 규칙들입니다. 라우팅 모드를 선택하여 Ava 가 배정하게 하거나, 단일 모델을 선택하여 라우팅을 완전히 건너뛸 수 있습니다.","reference.models#2#h":"라우팅 모드","reference.models#3#p":"세 가지 오케스트레이션 전략입니다. 동일한 페르소나 파이프라인 (Ava 가 배경에서 운영하는 전문가 조력자 소규모 팀) 이 세 가지 모두에서 작동합니다. 달라지는 것은 기반이 되는 모델 군집입니다. 모델 선택기에서 모드를 선택하면 Ava 가 나머지를 처리합니다. 아래 각 카드는 지휘자가 라우팅하는 구성원인 전문가들을 보여줍니다.","reference.models#4#p":"아래 카드를 외울 필요는 없어요. 각 전략이 무엇으로 구성되어 있는지 확인할 수 있도록 마련된 것입니다.","reference.models#6#c":"Aurora 는 고의로 Mistral 전용입니다. Mistral 모델을 사용할 수 없는 경우 라우터는 교차 라우팅 대신 오류를 반환합니다 — 이것이 EU 스택 보증입니다. 원활한 저하를 위해 Maestro 또는 Supernova 를 선택하세요.","reference.models#7#c":"세 가지 모드 모두 어디서나 사용할 수 있습니다 — 플랫폼 크레딧과 자체 키 모두에서요. BYOK 는 오케스트레이션을 우회하여 단일 모델을 직접 구동할 옵션을 추가합니다.","reference.models#8#h":"플랫폼 관리 모델","reference.models#9#p":"무료 티어를 포함한 모든 플랜에서 사용할 수 있습니다. 토큰 (AI 가 측정하는 텍스트 단위 — 단어 약 3/4 분량) 은 플랜 할당량에서 차감됩니다. 키 (각 유료 모델을 잠금 해제하는 비공개 비밀번호) 는 플랫폼에서 회전 및 모니터링하므로 설정할 것이 없습니다.","reference.models#11#h":"자신만의 키 가져오기","reference.models#12#p":"\"API 키\"는 소프트웨어가 본인의 계정으로 유료 서비스를 사용할 수 있게 해주는 비밀 번호입니다. \"BYOK\"는 단순히 \"자신만의 키를 가져온다\"는 뜻으로, 저희의 키 대신 본인 것을 사용하는 것입니다. 설정에 API 키를 붙여넣으세요. BYOK 요청은 Ava 에서 직접 제공업체 (모델을 운영하는 회사) 로 갑니다 — 저희 인프라를 거치지 않으며 플랫폼 토큰도 소모하지 않아요. 제공업체에 비용을 지불하시면 되며, 우리는 트래픽을 보지 못해요.","reference.models#14#c":"벤치마크 점수, 기능 태그, 그리고 나란히 필터링 정보는 ava-supernova.com/models 의 전체 모델 페이지를 참고하세요. 위에 표시된 가격은 각 제공업체 요금표에 대한 저희의 최신 해석입니다 — 작업에 착수하기 전에 항상 제공업체 웹사이트를 확인해 주세요.","reference.personas#title":"페르소나 조정","reference.personas#0#p":"\"페르소나\"는 Ava 가 어려운 작업을 위해 뒷조림에서 맡는 보조 역할입니다 — 탐험가, 기획자, 사실 검증자 같은 역할이죠. 여러분은 그들과 직접 대화하지 않으며, Ava 를 사용하려면 이 페이지를 이해할 필요도 없습니다. Ava 가 큰 작업을 작은 전문가 팀으로 어떻게 나누는지 궁금하실 때 참고용으로 마련되었어요.","reference.personas#1#p":"5 개의 모드 팀에 걸쳐 24 명의 전문가가 있습니다. 지휘자 (나머지를 조정하는 보조 역할) 가 어떤 팀이 실행될지, 순서와 맥락은 무엇인지 결정합니다. Chat 모드에는 페르소나가 없습니다 — 바로 Ava 자신이에요.","reference.personas#2#h":"오케스트레이션 작동 방식","reference.personas#3#li0":"Plan, Teach, Security, 또는 Brainstorm 모드에서 메시지를 보내거나 (또는 복잡한 Work 요청을 합니다).","reference.personas#3#li1":"지휘자가 요청을 읽고 모드 팀을 선택하여 실행 계획을 세웁니다 — 일부 페르소나는 순차적으로, 일부는 병렬 파도로 실행됩니다.","reference.personas#3#li2":"각 페르소나에는 고유한 시스템 프롬프트, 제한된 도구 허용 목록, 그리고 이전 페르소나가 찾은 내용에 대한 공유 컨텍스트 풀이 있어요.","reference.personas#3#li3":"최종 페르소나는 모드에 따라 요약, 계획, 또는 보고서를 생성합니다.","reference.personas#3#li4":"Ava 가 결과를 보여줍니다. 승인하거나 수정하거나 방향을 전환할 수 있어요.","reference.personas#4#p":"아래 전체 명단은 참고용일 뿐 — 누가 무엇을 하는지 기억할 필요는 없어요. Ava 가 여러분에게 맞는 팀을 구성해 줍니다.","reference.personas#6#c":"Work 모드는 복잡한 작업에만 전체 팀을 호출합니다. 간단한 편집은 Ava 가 직접 처리하며 — 오케스트레이션 오버헤드가 없어요.","reference.project-context#title":"프로젝트 컨텍스트","reference.project-context#0#p":"이곳에서는 Ava 가 작업을 시작하기 전에 프로젝트를 어떻게 파악하는지 설명합니다. 그녀가 작업 내용을 이해하기 위해 확인하는 파일들입니다. 따로 설정할 필요는 없습니다. Ava 가 알아서 처리해요. 만약 그녀가 항상 볼 수 있도록 메모를 어디에 넣어야 하는지 궁금하다면 읽어보세요.","reference.project-context#1#p":"프로젝트를 열면 Ava 는 여러 층의 컨텍스트 (머릿속에 유지하는 배경 정보) 를 불러옵니다. 이 층들을 이해하면 정보를 올바른 위치에 배치하는 데 도움이 됩니다.","reference.project-context#2#h":"자동으로 로드됨","reference.project-context#3#li0":".ava/instructions.md — 영구적이고 우선순위가 높은 지침으로 취급됩니다. 항상 컨텍스트에 포함돼요.","reference.project-context#3#li1":".ava/context.md — 자유로운 형태의 메모입니다. 로드되지만 우선순위는 낮습니다.","reference.project-context#3#li2":"README.md — 처음 실행 시 프로젝트 요약을 위해 스캔합니다.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — 프로젝트 설정을 나열하는 작은 파일들입니다. 언어, 프레임워크, 테스트 명령어를 감지하기 위해 읽어요.","reference.project-context#3#li4":".gitignore — 버전 관리에서 제외할 파일 목록입니다. 모든 파일 도구 (glob, grep, project_index) 에서 이를 존중합니다.","reference.project-context#4#h":"필요할 때 로드됨","reference.project-context#5#p":"`온 디맨드`는 실제 작업에 필요할 때만 Ava 가 가져온다는 뜻이며, 처음부터 모두 가져오는 것은 아닙니다.","reference.project-context#6#li0":"프로젝트 인덱스 — 파일과 그 안의 명명된 조각들 (함수, 클래스 — \"심볼\") 및 연결 방식 (\"임포트\") 을 구조화한 지도입니다. 필요한 때에만 만들어집니다.","reference.project-context#6#li1":"Git 히스토리 — 과거 변경 사항 기록입니다. git_status, git_diff, git_create_pr 호출 시 가져옵니다 (Git 은 프로젝트의 모든 변경 사항을 추적하는 도구입니다. \"PR\"은 풀 리퀘스트로, 제안된 변경 모음입니다).","reference.project-context#6#li2":"메모리 — 항목은 의미 기반으로 매칭되며, 한 번에 하나씩 주입됩니다. 한꺼번에 들어오지 않아요.","reference.project-context#7#c":"규칙은 instructions.md 에, 메모는 context.md 에 적으세요. 나머지는 메모리가 알아서 챙겨줍니다.","reference.config#title":"설정","reference.config#0#p":"이 페이지에서는 컴퓨터에서 Ava 가 설정과 파일을 어디에 보관하는지 보여줍니다. 대부분 직접 건드릴 필요가 없어요 — 앱이 대신 관리해 줍니다. 직접 확인하거나 백업, 공유하고 싶을 때 참고하세요.","reference.config#1#p":"Ava 는 두 가지 범위의 설정 (저장된 상태) 을 읽습니다. 전역 설정 — 어디서나 적용되는 설정 — 은 ~/.ava/ 폴더에 있어요 (\"~\" 은 홈 폴더의 약자입니다). 프로젝트별 설정은 프로젝트 내부의 .ava/ 폴더에 있습니다.","reference.config#2#h":"전역 — ~/.ava/","reference.config#3#li0":"settings.json — 모델 선호도, 권한 모드, 성격, 언어.","reference.config#3#li1":"memory/ — 전역 메모리 (모든 곳에 적용되는 선호도, 결정).","reference.config#3#li2":"tasks.json — 프로젝트 간 작업 목록.","reference.config#3#li3":"journal/ — 날짜별로 정리된 일일 기록.","reference.config#4#h":"프로젝트 — .ava/","reference.config#5#li0":"instructions.md — Ava 가 항상 로드하는 프로젝트 전용 지침. 항상 유지되는 컨텍스트 (\"pnpm 을 사용하지, npm 을 쓰지 않아요\", \"API 키는 1Password 에 있어요\").","reference.config#5#li1":"context.md — 선택 사항인 자유 형식 프로젝트 노트.","reference.config#5#li2":"memory/ — 이 프로젝트에 한정된 메모리.","reference.config#5#li3":"datasets/config.json — 데이터셋 캡처 설정 (선택 참여).","reference.config#6#c":"팀과 메모리를 공유하고 싶지 않다면 .ava/ 를 .gitignore(공유 프로젝트에서 제외할 파일 목록) 에 추가하세요. instructions.md 는 저장소 (공유 프로젝트 폴더) 에 남겨두세요 — 이것이 Ava 가 프로젝트 관습을 배우는 방법입니다.","reference.shortcuts#title":"키보드 단축키","reference.shortcuts#0#p":"키보드 단축키는 선택적인 속도 향상 기능이에요 — 모두 클릭 가능한 버튼이기도 합니다. 키보드로 Ava 를 더 빠르게 사용하려면 여기를 보세요.","reference.shortcuts#1#p":"환경별 단축키 (Ava 가 실행되는 세 곳: VS Code 확장 프로그램, 데스크톱 앱, 터미널). 각 환경 설정에서 커스터마이징하세요. 아래 목록을 외울 필요는 없습니다.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"보고서, 이메일, 문서 작성이 필요하신가요? Ava 가 초안을 작성하여 다른 파일처럼 열고 편집할 수 있는 실제 Word, Excel, PDF 파일을 제공합니다.","features.office-suite#1#p":"보고서, 이메일, 문서 — 초안 작성, 서식 지정, 네이티브 포맷으로 내보내기 (.docx 는 Word, .xlsx 는 Excel, .pdf 는 PDF 입니다).","features.office-suite#2#li0":"report_generate — 작업, 일지, 메모리, 프로젝트 상태에서 가져온 구조화된 .docx.","features.office-suite#2#li1":"email_draft — 어조 조절된 이메일을 .docx 파일로.","features.office-suite#2#li2":"document_manage — Word, Excel, PDF, CSV, Markdown 간 생성, 읽기, 편집, 내보내기.","features.office-suite#3#p":"Ava 가 대신 작성할 때 유용합니다 — 상태 보고서, 시작 회의 자료, 고객 업데이트. .docx 파일이 프로젝트에 저장되어 다듬을 수 있습니다.","features.dashboard-library#title":"대시보드 라이브러리","features.dashboard-library#0#p":"쉽게 말해: Ava 와 당신이 만든 것과 대화한 모든 것을 보관하는 하나의 선반으로, 어떤 것도 잃어버리지 않습니다.","features.dashboard-library#1#p":"Ava 가 당신과 함께 만든 모든 것에 대한 검색 가능한 뷰 — 생성된 이미지, 비디오, 오디오, 문서 — 당신의 대화, 메모리, 작업과 함께. 지난 주에 만든 것을 찾을 수 있는 한 곳.","features.document-preview#title":"문서 미리보기","features.document-preview#0#p":"쉽게 말해: 별도의 프로그램을 열지 않고 현재 위치에서 문서를 바로 들여다볼 수 있습니다.","features.document-preview#1#p":"프로젝트 내 Word 문서, Excel 시트, PDF, CSV, HTML, Markdown 파일을 마우스 오른쪽 버튼으로 클릭 — 에디터를 떠나지 않고 인라인으로 미리보세요. Ava 가 생성한 참고 자료를 읽거나 협업자가 넣은 파일을 읽을 때 유용합니다.","features.daily-briefing#title":"매일 브리핑","features.daily-briefing#0#p":"쉽게 말해: 아침마다 짧은 \"여기가 마지막 지점입니다\" 메모로, 모든 것을 다시 읽지 않고 이어갈 수 있습니다.","features.daily-briefing#1#p":"아침 요약: 어제 일지, 진행 중인 작업, 프로젝트 상태, Ava 가 설정한 알림 등. 선택 사항 — 설정에서 켤 수 있습니다.","features.daily-briefing#2#p":"브리핑은 관련 컨텍스트를 찾아내기 위해 메모리를 사용합니다 (\"마지막에 인증 흐름 작업을 했을 때, 리프레시 토큰 전략을 다시 검토하고 싶다고 언급했습니다\"). 뉴스 피드가 아닌 집중적인 회고입니다.","features.unified-panel#title":"통합 패널","features.unified-panel#0#p":"쉽게 말해: Ava 가 하는 모든 것이 하나의 창에 있으므로, 찾아 헤매며 탭을 뒤질 필요가 없습니다.","features.unified-panel#1#p":"채팅, 대시보드, 메모리, 작업, 일지를 위한 하나의 패널입니다. 창 사이에서 컨텍스트를 전환할 필요가 없습니다. 사이드바에서 보고 싶은 것을 선택하면 메인 영역이 그에 맞춰 바뀝니다.","features.unified-panel#2#p":"다른 곳으로 이동해도 대화 상태는 유지됩니다 — 메모리를 열고 작업을 확인한 후 돌아오세요. 채팅은 여전히 그곳에 있으며, Ava 가 실행 중이면 스트리밍도 계속됩니다.","features.unified-panel#3#c":"통합 패널은 확장 프로그램 및 IDE 개념입니다. 웹 표면은 브라우저 탭을 사용합니다.","features.knowledge-packs#title":"지식 팩","features.knowledge-packs#0#p":"쉽게 말해: Ava 에게 자신의 문서 폴더를 건네면, 그녀는 질문을 답변하기 위해 그들을 읽을 수 있습니다. \"지식 팩\"은 바로 그 파일 묶음입니다 — 그녀가 참고할 수 있는 당신의 참조 자료.","features.knowledge-packs#1#p":"참조 자료 디렉토리 (명세서, RFC, 회의록, API 문서) 를 지식 팩에 넣으세요. 대화에서 주제가 다뤄질 때 Ava 가 관련 부분을 컨텍스트로 가져올 수 있습니다.","features.knowledge-packs#2#p":"팩은 로컬로 색인됩니다. 검색은 의미 기반입니다 — Ava 는 파일명이 아닌 의미로 올바른 문서를 찾습니다. (\"의미 기반\"이란 문서가 무엇에 관한 것인지에 맞춰진다는 뜻이므로, 정확한 단어나 파일 이름을 기억할 필요가 없습니다.) 팩은 팀과 공유하거나 개인으로 둘 수 있습니다.","troubleshooting.common-errors#title":"일반적인 오류","troubleshooting.common-errors#0#p":"대부분의 오류는 짧고 구체적인 원인이 있습니다. 여기 가장 흔한 것들과 해결 방법을 알려드릴게요. 용어가 기술적으로 들릴 수 있지만 걱정하지 않으셔도 됩니다 — 아래 각각이 실제로 무엇을 보고 있는지, 그리고 정확히 무엇을 해야 하는지 알려줍니다.","troubleshooting.common-errors#1#h":"모델 응답 없음","troubleshooting.common-errors#2#p":"확인 사항: Ava 가 조용해지고 답장이 없습니다.","troubleshooting.common-errors#3#p":"채팅 헤더의 상태 표시기를 확인하세요. \"connecting\"이라고 표시되면 제공자 (AI 서비스) 는 연결되지만 느립니다 — 30 초 정도 기다려 주세요. \"unavailable\"라고 표시되면 Ava 가 다음 모델로 자동 전환되었습니다 (백업 모델을 사용 중입니다). 아예 안 된다면 설정에서 API 키를 확인하고 연결을 테스트하세요. (API 키는 유료 AI 서비스를 사용할 수 있게 해주는 비밀 비밀번호입니다.)","troubleshooting.common-errors#4#h":"도구 호출 실패","troubleshooting.common-errors#5#p":"확인 사항: Ava 의 단계 중 하나 (\"tool call\" — 파일 읽기, 명령 실행 등) 가 완료되지 않고 빨간색 오류로 표시됩니다.","troubleshooting.common-errors#6#p":"실패한 도구 호출을 클릭하여 오류를 확인하세요. 일반적인 원인: 프로젝트 폴더 밖 파일을 만지려 함 (보안을 위해 차단됨, 이 보호 장치는 \"path traversal\" 보호라 불리며 작업 중인 폴더 밖으로 나돌아다니는 것을 막습니다); 다른 폴더에서 실행해야 하는 명령; 또는 Ava 가 마지막으로 본 이후 파일이 이동됨. Ava 에게 무엇이 잘못되었는지 알려주시면 수정 후 다시 시도할 거예요.","troubleshooting.common-errors#7#h":"메모리 회상 불가","troubleshooting.common-errors#8#p":"확인 사항: 분명 기억해야 할 것을 Ava 가 찾지 못합니다.","troubleshooting.common-errors#9#p":"메모리는 정확한 단어가 아닌 의미로 작동합니다 (이를 \"semantic\"이라고 합니다). 따라서 \"What did I decide about auth?\"가 \"find my auth decision\"보다 더 잘 작동합니다. 메모리가 분명히 있는데 나타나지 않으면 메모리 브라우저에서 검색하세요 — 없으면 처음부터 저장되지 않은 것입니다.","troubleshooting.common-errors#10#h":"로그인 반복","troubleshooting.common-errors#11#p":"확인 사항: 로그인했지만 Ava 가 계속 다시 로그인하라고 요청합니다 — 통과할 수 없는 루프입니다.","troubleshooting.common-errors#12#p":"해결 방법은 저장된 로그인 정보를 지우고 새로 시작하는 것입니다: 확장 프로그램에서 명령 팔레트에서 \"Ava: Sign Out\"을 실행하고, IDE 에서 설정 → 계정 → 로그아웃을 사용하며, CLI 에서 ~/.ava/auth.json 파일을 삭제하세요 (홈 디렉토리의 .ava 폴더 안에 있는 작은 로그인 파일). 그런 다음 다시 로그인하세요.","troubleshooting.common-errors#13#h":"토큰 소진","troubleshooting.common-errors#14#p":"확인 사항: 이번 달 무료 사용량이 다 됐다는 메시지가 나타납니다. (\"Tokens\"는 AI 사용량을 측정하는 단위입니다 — \"exhausted\"는 이번 달 무료 할당량을 모두 사용했다는 뜻입니다.)","troubleshooting.common-errors#15#p":"무료 계정의 월간 예산은 매월 1 일에 초기화됩니다. 그 전까지는 BYOK 제공자 (자신만의 API 키 사용) 로 전환하여 작업을 계속하세요. 계정은 활성화된 상태로 유지되며, 무료 플랫폼 관리 요청만 일시 중지됩니다.","troubleshooting.logs#title":"로그 위치","troubleshooting.logs#0#p":"\"log\"는 컴퓨터가 발생한 일을 기록하는 일기 같은 것입니다 — 문제가 생겼을 때 (또는 지원팀이) 세부 사항을 볼 필요가 있을 때 유용합니다.","troubleshooting.logs#1#p":"원본 기록이 필요할 때 — 어떤 도구가 호출되었는지, 어떤 정보를 얻었는지, AI 서비스가 무엇을 반환했는지 — 로그는 컴퓨터의 폴더에 있는 일반 텍스트 파일입니다 (~/.ava/logs/ — 홈 디렉토리에 있는 .ava 폴더 내부에 logs 폴더가 있음).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — 세션별 기록 (도구 호출, 스트리밍 응답, 오류 포함).","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — VS Code 확장 프로그램 호스트 로그. 활성화 실패, 패널 오류.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — 데스크톱 IDE 로그. 사이드카 프로세스 메시지, 러스트 패닉.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — CLI REPL 로그.","troubleshooting.logs#3#p":"확장 프로그램에서는 명령 팔레트의 \"Ava: Show Logs\"를 사용하면 관련 로그가 편집기 탭에 열립니다. IDE 에서는 설정 → 진단에 \"Open Logs\" 버튼이 있습니다. CLI 는 ava logs --follow 명령으로 로그를 실시간으로 확인할 수 있습니다.","features.workflows#title":"워크플로우","features.workflows#0#p":"쉽게 말해: 반복하는 작업을 아바에게 가르치고 이름을 붙이면, 필요할 때마다 그 전체 과정을 다시 실행할 수 있어요. '워크플로우'란 바로 그런 저장된 작업 절차 — 아바가 당신을 위해 반복하는 일련의 단계들이에요.","features.workflows#1#p":"자주 반복하게 되는 단계들을 저장하세요 — 코드 요청 검토 → 테스트 실행 → 릴리스 노트 작성 → 이메일 초안 작성. 워크플로우는 다른 입력값으로 재생할 수 있는 재사용 가능한 계획이에요.","features.workflows#2#p":"워크플로우는 프로젝트별로 프로젝트 폴더 내부의 `.ava/workflows/` 폴더에 저장돼요. 해당 디렉토리를 커밋하여 팀원과 공유하면 (공유 프로젝트에 저장하면) 동료들도 함께 사용할 수 있어요.","features.events#title":"이벤트 및 알림","features.events#0#p":"쉽게 말해: 아바가 작업하는 동안 그녀가 무엇을 하는지 깔끔한 단계별 목록을 볼 수 있고, 긴 작업이 끝나면 알려줘서 잠시 자리를 비울 수 있어요.","features.events#1#p":"아바가 실행 중일 때 텍스트 산더미 대신 구조화된 업데이트를 볼 수 있어요. 각 도구 호출, 각 페르소나 이관, 각 스트리밍 델타는 사용자 인터페이스 에서 개별 이벤트로 표시되며 — 세부 내용은 펼치고 개요는 접을 수 있어요.","features.events#2#p":"백그라운드 실행은 완료 시 운영체제 수준의 알림을 보내요. 긴 빌드를 진행 중일 때도 자리를 비워두면 아바가 다 끝났다고 알려줘요.","features.personality#title":"성격 디자이너","features.personality#0#p":"쉽게 말해: 아바가 당신과 대화하는 방식을 조절하세요 — 수다스러우거나 간결하게, 격식 있거나 캐주얼하게, 농담을 더하거나 줄여서 당신이 원하는 목소리로 만들어요.","features.personality#1#p":"아바가 당신과 대화하는 방식을 만들어보세요. 톤, 에너지, 말량 (얼마나 많이 말하는지), 격식도, 유머감각. 슬라이더와 프리셋 — 간결한 엔지니어, 따뜻한 멘토, 건조한 동료, 또는 당신의 고유한 조합.","features.personality#2#p":"성격은 표현 방식에만 영향을 줘요. 능력에는 영향 없죠. 같은 도구를 실행하고 동일한 권한 규칙을 따릅니다. 이름은 Ava 로 고정되어 있어요 — 이건 절대 변경 불가예요.","features.release-notes#title":"릴리스 노트","features.release-notes#0#p":"쉽게 말해: 각 업데이트마다 새로 추가된 것과 수정된 것에 대한 지속적인 목록이에요. 어떤 것이 변경되었는지 확인할 수 있어요.","features.release-notes#1#p":"앱 내 변경 로그 (변경 로그는 변경 사항의 기록이에요). 출시된 모든 버전별 하이라이트, 버그 수정, 그리고 호환성 변경 사항 (무언가를 사용하는 방식을 조정해야 할 수 있는 변경 사항) 이 포함되어 있어요. 웹 사이트 주소 ava-supernova.com/releases 에 공개 버전을 유지해요.","troubleshooting.logs#4#c":"로그에는 세션 동안 Ava 가 읽은 프로젝트 파일 일부가 포함될 수 있습니다. 공유하기 전에 꼭 확인하세요.","troubleshooting.support-request#title":"지원 문의 작성하기","troubleshooting.support-request#0#p":"쉽게 말씀드리면: 무언가 잘못되었고 위의 해결책이 도움이 안 된다면, 저희에게 알려주세요. 가장 쉬운 방법은 Ava 에게 직접 부탁하는 거예요.","troubleshooting.support-request#1#p":"일반적인 오류로 다루지 않는 문제가 있다면 지원 티켓을 제출하세요 (지원 팀에 도움을 요청하는 것). Ava 내부에서 (양식을 작성할 필요 없이) 또는 웹에서 할 수 있어요.","troubleshooting.support-request#2#h":"Ava 내부에서","troubleshooting.support-request#3#p":"그녀에게 맡기세요. \"Ava, 이걸로 지원 티켓을 만들어 줄 수 있나요?\" 그녀는 support_request 를 실행하고 관련 세션 컨텍스트 (자격 증명은 마스킹 처리됨) 를 첨부하여 보냅니다. 가장 빠른 방법이에요.","troubleshooting.support-request#4#h":"웹에서","troubleshooting.support-request#5#p":"ava-supernova.com/support 로 방문하세요. 카테고리 (버그, 기능, 계정, 보안, 일반) 를 선택하고 발생한 일을 설명하세요. 영업일 기준 하루 안에 답변 드립니다.","troubleshooting.support-request#6#h":"포함해야 할 사항","troubleshooting.support-request#7#li0":"무엇을 하려 했는지.","troubleshooting.support-request#7#li1":"실제로 어떤 일이 일어났는지.","troubleshooting.support-request#7#li2":"사용 중인 환경 (확장 프로그램, IDE, CLI, 연동 앱) 과 버전.","troubleshooting.support-request#7#li3":"오류 메시지나 로그 발췌문. 자격 증명은 먼저 마스킹 처리하세요.","troubleshooting.security-disclosure#title":"보안 문제 보고하기","troubleshooting.security-disclosure#0#p":"쉽게 말씀드리면: Ava 가 해킹되거나 오용될 수 있는 방법 (\"취약점\" — 보안 약점) 을 발견하셨다면, 누군가가 악용하기 전에 우리가 수정할 수 있도록 먼저 사적으로 알려주세요. 이 페이지가 그 방법입니다.","troubleshooting.security-disclosure#1#p":"취약점을 발견하셨나요? 감사합니다. 우리는 모든 보고를 진지하게 받아들이며, 공개 발표 (문제가 공표되기 전) 전에 여러분과 함께 수정 작업을 진행합니다.","troubleshooting.security-disclosure#2#h":"보고 방법","troubleshooting.security-disclosure#3#li0":"설명, 재현 단계, 선호하는 공개 기간을 명시하여 security@ava-supernova.com 으로 이메일을 보내세요.","troubleshooting.security-disclosure#3#li1":"또는 카테고리가 \"보안\"인 지원 티켓을 제출하세요 — 동일한 분류 대기열입니다.","troubleshooting.security-disclosure#3#li2":"24 시간 이내에 확인 연락을 드립니다.","troubleshooting.security-disclosure#4#h":"우리의 약속","troubleshooting.security-disclosure#5#li0":"조정된 공개 — 아무것도 공개되기 전에 여러분과 일정을 협의합니다. 기본값은 90 일입니다.","troubleshooting.security-disclosure#5#li1":"크레딧 — 익명을 원하지 않는 한 수정 내역에 이름을 올립니다.","troubleshooting.security-disclosure#5#li2":"법적 보복 없음 — 선의의 연구는 환영합니다. 변호사를 보내지 않아요.","troubleshooting.security-disclosure#6#c":"ava-supernova.com/security 의 보안 페이지에는 전체 보안 태세 (아키텍처 보장, 정보 마스킹, 권한 관리) 가 포함되어 있습니다.","start.what#title":"Ava 는 무엇인가요?","start.what#0#p":"Ava 는 그저 이야기만 하는 AI 가 아니라, 실제로 일을 해내는 AI 에요. 앱을 만들어 드리고, 문서를 작성해 주며, 처음부터 가르쳐 주고, 로고를 디자인하거나 미루고 있던 업무를 처리해 줍니다. 그리고 Ava 는 당신을 기억해요: 무엇을 하고 있는지, 어떤 것을 좋아하는지, 지난주에 무엇을 요청했는지까지요.","start.what#1#p":"Ava 는 하나뿐이고, 어디서든 함께 일합니다. 코드 편집기에서, 데스크톱 앱으로, 휴대폰에서, 혹은 터미널에서요. 메모리도 성격도 어디나 같습니다.","start.what#2#h":"무엇이 다른가요?","start.what#3#li0":"기본적으로 당신 것입니다. 작업은 항상 내 기기에 남아 있습니다. 추적도, 데이터 수집도 없습니다 — 영원히요.","start.what#3#li1":"누구나 볼 수 있게 공개되어 있습니다. Ava 의 모든 코드가 공개됩니다. 신뢰할 필요가 없어요.","start.what#3#li2":"무료로 시작하세요. 매월 300 크레딧 제공, 카드 필요 없음, 숨은 조건도 없습니다 — 아니면 직접 AI 키를 연결하면 저희에게 돈을 내지 않아도 됩니다.","start.what#3#li3":"가르치는 것은 영원히 무료입니다. 배움에는 가격이 붙으면 안 되죠.","start.what#4#p":"코드를 한 번도 써 본 적 없나요? 다음 페이지는 당신을 위해 쓰여졌습니다. 이미 기술에 익숙하다면 건너뛰세요 — Ava 가 따라갈 테니까요.","start.what#deeper#0#h":"Ava 는 어디에 있나요?","start.what#deeper#1#li0":"VS Code 확장 프로그램 — 편집기 옆에 있는 Ava: 채팅 패널, 대시보드, 그리고 변경 사항이 발생하기 전에 미리 보여줍니다.","start.what#deeper#1#li1":"데스크톱 IDE — 전체 기능이 하나의 창에 들어있는 독립형 앱입니다. 데스크톱 제어 기능을 추가합니다 (앱 열기, 클릭, 대신 입력 등).","start.what#deeper#1#li2":"컴패니언 — 책상에서離れ 있을 때 쓰는 모바일 앱: 작업, 일기, 메모리, 빠른 채팅.","start.what#deeper#1#li3":"CLI — 터미널 속의 Ava, 그곳에서 살아가는 분들을 위해.","start.what#deeper#2#h":"어떻게 작동하나요?","start.what#deeper#3#p":"Ava 는 작업에 맞춰 마음가짐 (모드라고 부릅니다) 을 바꾸고, 어려운 작업에는 조용히 전문 도우미 팀을 돌보며, 각 단계마다 가장 좋은 AI 모델을 자동으로 선택합니다. 당신은 그중 하나도 관리할 필요는 없어요. 궁금할 때마다 '핵심 개념' 섹션에서 전체 투어를 확인하세요.","start.first-five#title":"Ava 와 함께하는 첫 번째 작업","start.first-five#0#p":"Ava 를 사용하는 가장 빠른 방법은 실제로 필요한 것을 요청하고 그녀가 하는 모습을 보는 것입니다. 읽어야 할 설정이나 먼저 배울 것은 없습니다 — 원하는 것을 평범한 말로 알려주기만 하면 돼요.","start.first-five#1#h":"지금 바로 시도해 보세요","start.first-five#2#li0":"채팅을 엽니다.","start.first-five#2#li1":"실제로 원하는 것을 입력하세요. \"이 프로젝트가 무엇을 하는지 설명해 주세요\", 또는 \"폼을 지우는 버튼을 추가해 주세요\" 같은 걸 시도해 보세요.","start.first-five#2#li2":"Ava 가 하려는 일을 보여주고 기다립니다.","start.first-five#2#li3":"마음에 드나요? 네 라고 말하세요. 그녀의 작업을 지켜보세요.","start.first-five#3#p":"이것이 전적인 흐름이에요: 당신이 요청하면, 그녀는 계획을 보여주고, 당신이 승인하면, 그녀가 실행합니다. 그녀는 먼저 보여주지 않고는 아무것도 변경하지 않아요 — 그래서 시도하다가 무언가를 망칠 일이 없죠.","start.first-five#4#h":"요청해 보면 좋은 것들","start.first-model#deeper#0#h":"각 스타일에는 실제로 어떤 것이 담겨 있을까요?","start.first-model#deeper#1#p":"Maestro — 한 명의 지휘자 (Qwen 3.6 Plus) 가 모든 단계를 맡아 진행해요. 실무에 맞춰 잘 다듬어졌고 검증되었으며, 비용도 미리 알 수 있어요.","start.first-model#deeper#2#p":"Supernova — 최전선 조정자 (DeepSeek V4 Pro, 1.6T 파라미터 / 49B 활성, 1M 컨텍스트) 가 각 하위 작업을 전문가에게 맡깁니다: 대량 빌드는 V4 Flash, 백업은 Qwen 3.6 Plus, 비전은 Qwen Omni 를 사용해요.","start.first-model#deeper#3#p":"Aurora — Mistral 전용으로 세 단계로 구성됩니다: Mistral Large 3(조정자 + 중형 전문가), Mistral Medium 3.5(128B 밀집, 256K 컨텍스트, 네이티브 비전, 수정 MIT 오픈 웨이트, 77.6% SWE-Bench 검증됨) 는 빌더 + 미드티어 + 비전 + 장문 작성용, 그리고 의도 게이트에서는 Mistral Small 4 를 사용해요. 처음부터 끝까지 오픈 웨이트이며, EU 인프라를 벗어나지 않아요.","start.first-model#deeper#4#h":"직접 모델을 가져오기 (BYOK)","start.first-model#deeper#5#p":"본인의 AI 계정을 선호하시나요? 설정에 제공자 키를 붙여넣으면 두 가지 모두 얻을 수 있어요 — 세 가지 라우팅 스타일과 함께 단일 모델을 선택하고 라우팅을 완전히 건너뛸 수도 있죠. 강한 선호도가 있거나 예산이 엄격하거나 특정 모델을 테스트할 때 유용해요. 전체 제공자 목록은 참고 섹션에 있습니다.","start.glossary#title":"쉬운 말로 풀어쓴 용어 사전","start.glossary#0#p":"Ava 주변에서 마주칠 수 있는 모든 단어를, 아무런 전제 지식 없이 설명했어요. 이를 다 외울 필요는 없어요 — 용어가 헷갈릴 때마다 다시 돌아보세요.","start.glossary#1#th0":"단어","start.glossary#1#th1":"실제 의미","start.glossary#1#td0.0":"에이전트","start.glossary#1#td0.1":"당신을 위해 행동을 취할 수 있는 AI — 파일을 읽거나 명령을 실행하거나 웹을 검색하는 것이지, 단순히 채팅만 하는 것이 아니에요. Ava 는 에이전트예요: 당신의 허락으로 일을 수행하죠.","start.glossary#1#td1.0":"모델","start.glossary#1#td1.1":"실제로 생각하는 AI 두뇌예요 (Qwen, DeepSeek, Mistral 등). 모델마다 강점이 달라요. 보통은 직접 고르지 않아도 돼요. Ava 가 알아서 해줘요.","start.glossary#1#td2.0":"모드","start.glossary#1#td2.1":"Ava 가 가진 마음가짐이에요. 동료들이 모자를 바꾸듯 — 빌더, 작가, 교사, 기획자, 친구처럼요. 모드를 선택하면 Ava 의 행동 방식이 달라져요. 일곱 가지가 있답니다.","start.glossary#1#td3.0":"페르소나 / 전문가","start.glossary#1#td3.1":"어려운 작업을 위해 Ava 가 배경에서 수행하는 조력자 역할 — 탐험가, 기획자, 사실 확인자 같은 존재예요. 작은 전문가 팀이라고 생각하세요. 직접 대화하지는 않지만, Ava 가 그들을 조정해요.","start.glossary#1#td4.0":"라우팅","start.glossary#1#td4.1":"Ava 가 각 단계에 사용할 모델을 결정하여 과금 없이 좋은 답변을 받을 수 있도록 해요. 자동으로 이루어지며, \"라우팅 모드\"는 전체 전략을 선택해요.","start.glossary#1#td5.0":"도구","start.glossary#1#td5.1":"Ava 가 할 수 있는 구체적인 행동 — 파일 읽기, 검색 실행, 이메일 보내기 등이에요. \"툴 호출\"은 그녀가 도구를 사용하는 것을 말해요. 위험한 일은 전에 허락을 구하죠.","start.glossary#1#td6.0":"토큰","start.glossary#1#td6.1":"AI 가 텍스트를 측정하는 단위예요 — 대략 단어의 3/4 정도랍니다. 모델은 토큰 100 만 개당 가격이 책정돼요. 대부분은 신경 쓸 필요가 없는 개념이에요.","start.glossary#1#td7.0":"크레딧","models.routing#deeper#2#td5.0":"채팅","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"이미지 생성 조정","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"시각 기능","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (시각 인코더를 처음부터 학습함)","models.routing#deeper#2#td8.0":"긴 글 작성","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"데이터 저장 위치","models.routing#deeper#2#td9.1":"혼합 (알리바바 클라우드)","models.routing#deeper#2#td9.2":"혼합 (DeepSeek + 알리바바 클라우드)","models.routing#deeper#2#td9.3":"EU 전용 · 가중치 공개","models.routing#deeper#2#td10.0":"상태","models.routing#deeper#2#td10.1":"서비스 중 · 모든 플랜","models.routing#deeper#2#td10.2":"곧 출시 예정","models.routing#deeper#2#td10.3":"곧 출시 예정","models.routing#deeper#2#td11.0":"추천 용도","models.routing#deeper#1#h":"나란히","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"조정자","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B active, 1M ctx)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B active, 262K ctx)","models.routing#deeper#2#td1.0":"빌더","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (조정자를 재사용)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B dense, 256K ctx)","models.routing#deeper#2#td2.0":"중급 전문가들","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (코드 검토자, 사실 확인자, 정보 수집, 검사기, 보안 검증자 등)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (설계자, 검증자, 순서 관리자, 튜터, 보고자 등)","models.routing#deeper#2#td3.0":"가벼운 등급 / 의도 확인","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (정찰자, 검증자, 순서 관리자, 반박자, 통합자)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"고급 전문가들","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (연구자, 반박자, CVE 연구자, 아이디어 제안자, 사실 확인자)","start.glossary#1#td7.1":"Ava 가 작업 비용을 계산하기 위해 사용하는 더 쉬운 단위예요. 복잡한 토큰 계산 없이도 괜찮습니다. 플랜에는 매달 사용할 수 있는 번들이 기본으로 들어있어요.","start.glossary#1#td8.0":"API 키","start.glossary#1#td8.1":"소프트웨어가 계정을 통해 유료 서비스 (예: AI 모델) 를 쓸 수 있게 해주는 개인 비밀번호예요. 직접 준비해서 사용하려는 경우에만 필요하답니다.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"자신만의 키를 가져오기\"라는 뜻이에요. Ava 가 관리하는 접근 방식 대신 직접 가진 API 키를 쓰는 거죠. 선택 사항이에요 — 이미 제공업체에 직접 요금을 내고 있다면 유용하답니다.","start.glossary#1#td10.0":"로컬 퍼스트","start.glossary#1#td10.1":"기본적으로 데이터는 내 컴퓨터에 있어요. 동기화를 켜지 않으면 아무것도 올라가지 않아요. \"로컬은 신성합니다.\"","start.glossary#1#td11.0":"권한 모드","start.glossary#1#td11.1":"일을 시작하기 전 Ava 가 얼마나 조심할지를 정하는 거예요. 매번 물어볼 수도 있고, 위험한 일일 때만 물을 수도 있으며, 그냥 진행하게 할 수도 있죠. 수준은 여러분이 정해요.","start.glossary#1#td12.0":"컨텍스트 윈도우","start.glossary#1#td12.1":"모델이 한 번에 머릿속에 담아둘 수 있는 텍스트 양이에요. 단기 기억과 비슷하죠. \"1M 컨텍스트\"는 대략 100 만 단어 정도를 말해요. 더 크다는 건 잊어버리기 전에 더 많은 내용을 읽을 수 있다는 뜻이에요.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"파일의 변경 사항을 한눈에 볼 수 있는 나란히 보는 창이에요. 왼쪽엔 이전 버전, 오른쪽엔 새로운 버전이 표시되죠. Ava 가 수정하기 전에 보여드려서 여러분이 확인하고 승인할 수 있도록 해요.","start.glossary#1#td14.0":"저장소 (레포지토리)","start.glossary#1#td14.1":"변경 사항을 기록해두는 프로젝트 폴더예요. 보통 Git 을 사용하죠. 만약 이 설명이 어렵다면, 그냥 \"내 프로젝트가 들어있는 폴더\"라고 생각하면 돼요.","start.glossary#1#td15.0":"프롬프트","start.glossary#1#td15.1":"AI 에게 보내는 메시지예요. 질문이거나 지시사항이 될 수 있죠.","start.glossary#2#c":"Still stuck on a word? Ask Ava in Chat mode — \"what does X mean?\" — and she will explain it for your level.","models.routing#title":"라우팅 — Ava 가 모델을 선택하는 방법","models.routing#0#p":"간단히 말해, 어떤 AI 모델을 쓸지 직접 고를 필요가 없어요. Ava 가 대신 골라주거든요. 일의 각 단계에 가장 적합한 도구를 선택하죠. 좋은 관리자가 알맞은 업무를 알맞은 사람에게 맡기는 것과 같아요.","models.routing#1#p":"세 가지 스타일 중 하나를 고르면 돼요 — Maestro, Supernova, Aurora. Ava 는 각 작업을 가장 잘 처리하는 모델로 보내주죠. Maestro 가 기본 설정이고 모든 플랜에서 사용 가능해요. 거의 모든 분께 추천하는 선택이에요.","models.routing#2#h":"왜 라우팅을 따로 설정해야 할까요?","models.routing#3#p":"각 단계에 알맞은 모델을 쓰면, 하나의 비싼 모델을 다 돌리는 것보다 비용도 덜 들고 결과도 더 좋아요. 각 모델이 가장 잘하는 일을 하니까요. 어떤 모델이 뭔지 몰라도 비용은 안정적이고 품질은 높게 유지될 거예요.","models.routing#4#c":"세 가지 스타일 모두 플랫폼 크레딧과 직접 키에서 사용할 수 있어요. 직접 키를 쓴다면 라우팅을 생략하고 단일 모델을 바로 쓸 수도 있죠. 전체 모델 목록은 \"상세 정보 보기\" 메뉴 아래에 있어요.","models.routing#deeper#0#c":"아래에 있는 \"B\" 숫자는 수십억 개의 파라미터를 의미해요 — 모델의 두뇌 크기와 비슷하죠. 더 크면 보통 더 똑똑하지만 속도가 느리고 가격이 비싸져요. 이건 내부적인 상세 정보예요. Ava 를 쓰는 데는 절대 필요 없답니다.","models.routing#deeper#2#td11.1":"일상 업무, 비용 예측 가능","models.routing#deeper#2#td11.2":"복잡한 다단계 작업, 모든 플랜에 최첨단 코디네이터 탑재","models.routing#deeper#2#td11.3":"GDPR 엄격 준수, 공공 부문, 주권 EU 스택","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"계층별 차등화된 Qwen 라우팅, 가벼운 발자국. Qwen 3.6 Plus 가 코디네이터, 빌더, 계획 수립, 보안, 브레인스토밍, 긴 컨텍스트 작업을 담당합니다 — 여기서 1M 컨텍스트 하이브리드 선형 어텐션이 빛을 발합니다. Qwen 3.5 Flash 는 채팅, 이미지 생성 오케스트레이션, 상류 의도 게이트를 처리하며, $0.07/$0.26 가격과 빠른 초기 응답 속도로 대량의 저깊이 토큰 부하에서 이깁니다. Qwen 3.5 Omni Plus 는 비전 입력을 담당합니다 (Qwen 3.6 Plus 는 네이티브 비전이 없음). Qwen 3.5 Plus 는 비용 민감한 장문 작업을 수행합니다. 주요 코디네이터 사용 불가 시 우선순위 사다리 Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash 를 따라 내려갑니다.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"다국어 앙상블. DeepSeek V4 Pro 가 조정하고 각 하위 작업을 가장 적합한 전문가에게 배정합니다: Qwen 3.6 Plus 는 모든 빌더 생성을 실행하고, V4 Flash 는 채팅과 중급 검토/감사 페르소나를 처리하며, Qwen 3.5 Flash 는 경량 분류 작업을 흡수하고, Qwen 3.5 Omni Plus 는 비전 입력을 담당하며, Qwen 3.5 Omni Flash 는 이미지 생성 도구 호출을 오케스트레이션하고, Qwen 3.5 Plus 는 비용 민감한 장문의 콘텐츠 작가 페르소나를 담당합니다. 중요한 곳에서는 최첨단 추론, 대량 토큰 부하에는 플래시 등급의 경제성을 제공합니다.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"유럽 AI 스택 — 설계 단계부터 주권적. 세 가지 등급의 Mistral 전용 라우팅: Mistral Large 3 (675B/41B 활성 희소 MoE) 는 코디네이터 역할 및 깊이와 연구원, 도전자, CVE 연구원, 아이디어 제안자, 사실 확인자, 보안 검증자가 필요한 중점 전문가들을 담당하고, 희소 MoE 효율성이 빛나는 긴 컨텍스트 잡무도 처리합니다. Mistral Medium 3.5 — 2026 년 4 월 출시된 통합 플래그십, 128B 밀집, 256K 컨텍스트, 처음부터 훈련된 비전 인코더, 수정 MIT 오픈 웨이트, 77.6% SWE-Bench Verified — 실제 작업 등급을 수행: 빌더 생성, 중급 전문가 (아키텍트, 검증자, 순서화기, 튜터, 리포터), 비전 입력, 장문 작성. Mistral Small 4 는 의도 게이트의 단일 역할에서 확장되어 채팅과 이미지 생성 오케스트레이션도 처리하며, $0.15/$0.60 가격과 구성 가능한 추론은 고부하 저깊이 경로에서 그 가치를 입증합니다. 엔드 투 엔드 오픈 웨이트, EU 인프라를 떠나지 않습니다. Aurora 는 모델 사용 불가 시 비 Mistral 모델로 조용히 크로스 라우팅하지 않도록 의도적으로 설계되었습니다. 대신 라우터가 오류를 표시합니다 — 이것이 이를 \"Aurora\"라고 하는 이유이며, Mistral 풍의 Maestro 가 아닌 이유입니다.","credits.overview#title":"Ava 크레딧 — 청구 방식 안내","credits.overview#0#p":"크레딧은 Ava 가 사용량을 계산하는 방법일 뿐입니다 — 휴대폰 요금제처럼 분 단위로요. 무료 플랜을 포함한 모든 플랜에는 크레딧 풀이 제공되며, Ava 가 하는 일마다 (질문에 답하거나 이미지를 생성하는 등) 소수의 크레딧이 사용됩니다. 그게 전체 개념입니다. 아래 세부 내용은 정확히 무엇이 얼마인지 알고 싶을 때 참고하세요.","credits.overview#1#p":"Ava 는 원본 토큰이 아닌 크레딧으로 청구합니다. (\"토큰\"은 AI 모델이 읽고 쓰는 텍스트의 아주 작은 조각 — 대략 몇 글자 정도 — 입니다. 대부분의 서비스는 토큰 단위로 청구하는데 이는 예측하기 어렵습니다.) 한 크레딧은 한 단위 작업을 커버합니다 — 채팅 한 번, 페르소나 생성 (작업의 일부만 수행하는 보조 하나), 이미지 생성. 토큰 수준 미터링에서 분리되었으므로 어떤 모델이 실행 중인지 알 필요 없이 행동 비용이 얼마인지 알 수 있습니다. Maestro 가 Qwen 3.6 Plus 로 라우팅하든 Supernova 가 V4 Pro 로 라우팅하든 같은 채팅 턴은 동일한 비용을 냅니다.","credits.overview#2#h":"플랜","credits.overview#3#p":"모든 플랜은 모든 기능에 접근할 수 있습니다 — 모델 액세스, Creative Studio, 모든 7 가지 모드, 전체 페르소나 오케스트레이션. 상위 등급은 더 많은 크레딧과 더 높은 속도 제한 상한선을 구매하는 것이지, 잠긴 기능을 해제하는 것이 아닙니다.","credits.overview#4#li0":"무료 — 월 $0. 300 크레딧. 분당 20 건 요청 속도 제한. 카드 필요 없음.","credits.overview#4#li1":"프로 — 월 $19. 5,000 크레딧. 분당 60 건.","credits.overview#4#li2":"울트라 — 월 $39. 10,000 크레딧. 분당 120 건.","credits.overview#4#li3":"엔터프라이즈 — 월 $79. 20,000 크레딧. 분당 200 건.","credits.overview#5#c":"구독이 활성화되는 동안 사용하지 않은 크레딧은 다음 달로 이월됩니다 — 강제 회수가 없습니다. 추가 충전은 구독 풀에 쌓입니다: $3 에 750 크레딧, $8 에 2,000, $15 에 4,000.","credits.overview#6#h":"항목별 비용","credits.overview#7#p":"액션별 비용 표 — 각 액션 실행 시 크레딧 풀에서 차감되는 금액입니다. (\"캐시 히트\"는 Ava 가 이미 한 작업을 다시 하지 않고 재사용할 때를 말합니다. 이때는 더 적게 지불합니다 — 요금이 70% 감소하거나, DeepSeek V4 Pro 와 같은 출력 집중형 모델의 경우 50% 감소합니다.)","credits.overview#8#li0":"채팅 턴 — 2 크레딧. 어떤 모드든 한 번 주고받음.","credits.overview#8#li1":"라이트 콜 — 1 크레딧. 의도 게이트, 분류, 단일 샷 읽기.","credits.overview#8#li2":"헤비 페르소나 — 3 크레딧. 아키텍트, 연구원, CVE 연구원, 아이디어 제안자 (깊이 ≥ 4).","credits.overview#8#li3":"라이트 페르소나 — 1 크레딧. 스카우트, 검증자, 순서화기, 도전자 (깊이 ≤ 2).","credits.overview#8#li4":"오케스트레이션 — 10 크레딧. 전체 퍼소나 파이프라인 실행 (컨덕터 + 다중 퍼소나 작업).","credits.overview#8#li5":"이미지 생성 — 12 크레딧. Creative Studio 를 통해 Hailuo image-01 사용.","credits.overview#8#li6":"비디오 생성 — 150 크레딧. Hailuo 02 Pro 1080p 6 초 클립.","credits.overview#8#li7":"음성 생성 — 10 크레딧. Speech 2.8 HD 합성.","credits.overview#8#li8":"음악 생성 — 50 크레딧. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"배경 제거 — 2 크레딧.","credits.overview#9#h":"모델별 곱셈 계수","credits.overview#10#p":"궁금한 분들을 위한 설명이에요 — Ava 를 사용하려면 꼭 알 필요는 없어요. 곱셈 계수는 단순히 액션 뒤에 있는 모델이 얼마나 비싼지에 따라 크레딧 비용을 늘리거나 줄여주는 거예요. 무거운 모델일수록 비용이 조금 더 들죠. (“순이익”은 프로젝트가 자신의 지출을 내고 나서 가져가는 몫이에요 — 저희는 낮게 설정해서 가치가 여러분에게 돌아갈 수 있도록 해요.)","credits.overview#11#p":"무거운 모델은 액션 비용을 곱해서 크레딧이 고정된 구간이 아닌 실제 지출을 반영하도록 해요. 약 55% 순이익을 목표로 조정되었습니다.","credits.overview#12#li0":"0.6× — Mistral Small 4 (Aurora 의 전문가 자리). Qwen 3.6 Plus 기준보다 Mistral Small 4 가 저렴해서 1× 미만이에요.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. 기본 요금입니다.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (Aurora 코디네이터). Qwen 3.6 Plus 기준과 비슷해요.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (Maestro 코디네이터).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (Supernova 코디네이터 + 무거운 전문가들). 공개된 V4 Pro 요금에서 마진 균형을 맞추기 위해 5.0× 에서 다시 조정되었습니다.","credits.overview#13#c":"Anthropic 모델 (Claude Opus / Sonnet / Haiku) 은 크레딧 청구가 완전히 생략됩니다 — BYOK 전용이며 Anthropic 에 직접 지불합니다. 다른 BYOK 제공자를 내 키로 사용할 때도 마찬가지예요.","credits.overview#14#h":"BYOK 와 크레딧","credits.overview#15#p":"BYOK(“own key 가져오기” — AI 제공자 계정과 키를 직접 준비하는 것, 소프트웨어가 유료 계정을 사용할 수 있게 해주는 개인 비밀번호) 는 이미 AI 제공자에 직접 결제하는 분들을 위한 것입니다. 해당 사항이 아니라면 이 섹션은 무시하셔도 됩니다.","credits.overview#16#p":"자체 키 요청은 플랫폼 인프라를 완전히 우회합니다 — 호출이 Ava 에서 제공자로 직접 이루어지며, 제공자에게 지불하고 크레딧은 소모되지 않아요. 유일한 예외는 BYOK 세션이 하위 작업을 위해 관리형 퍼소나를 생성할 때입니다. Ava 의 오케스트레이션 표면이 사용되므로 크레딧 차감이 여전히 적용됩니다.","credits.overview#17#h":"잔액 확인 위치","credits.overview#18#li0":"확장 프로그램 — 설정 → 계정, 또는 채팅 헤더의 크레딧 표시.","credits.overview#18#li1":"IDE — 계정 대시보드 타일에 현재 잔액과 소모율이 표시됩니다.","credits.overview#18#li2":"웹 — ava-supernova.com/dashboard 에서 잔액, 내역 및 갱신 날짜를 확인할 수 있습니다.","credits.overview#19#c":"로컬 우선: Ava 는 사용자 정의 모델 카드에서 계정 없이 작동합니다 (Ollama, LM Studio, vLLM 또는 모든 OpenAI 호환 엔드포인트). 크레딧 없음, 플랫폼 토큰 없음 — 당신의 모델, 당신의 머신, 청구금은 제로.","concepts.modes#title":"모드 — Ava 의 마음 상태","concepts.interjection#1#p":"Ava 는 계획이 완료되거나 당신이 멈추기 전까지 작동해요. 작동 중인 동안 개입할 수 있는 두 가지 방법이 있어요 (이를 '개입'이라고 불러요).","concepts.interjection#2#h":"개입 — 취소하지 않고 방향 전환하기","concepts.interjection#3#p":"Ava 가 작업하는 동안 새 메시지를 입력하세요. 현재 도구 호출을 마친 후 메시지를 읽고 계획을 조정해요. 컨텍스트는 사라지지 않아요. 진행 중 경로를 바꾸거나 정보를 추가하고 싶을 때, 우선순위를 변경하고 싶을 때 사용하세요.","concepts.interjection#4#h":"강제 중지 — 취소하고 초기화하기","concepts.interjection#5#p":"Escape 를 누르세요 (CLI), 중지 버튼을 클릭하세요 (확장 프로그램, IDE), 또는 중지 명령어를 입력하세요. 현재 실행이 취소되고 대기 중인 도구 호출은 사라지며, 대화는 새로운 시작을 위해 준비됩니다.","concepts.interjection#6#c":"먼저 개입하세요. 강제 중지는 정말로 잘못된 일이 있을 때만 사용하세요. 개입하면 대화가 계속 이어집니다.","concepts.desktop-personas#title":"데스크톱 페르소나","concepts.desktop-personas#0#p":"이 페이지는 호기심이 많거나 고급 사용자분을 위한 내용이에요. \"데스크톱 자동화\"(일부에서는 \"컴퓨터 사용\"이라고도 함) 란 Ava 가 실제로 화면을 클릭하고 앱을 대신 사용하는 것을 의미해요 — Gmail 열기, 양식 작성, 메시지 보내기 — 마치 키보드 앞에 앉은 사람처럼요. 안전하게 수행하려면, 그녀는 일을 다섯 명의 작은 도우미에게 나누어요. 각자는 하나의 좁은 역할만 맡죠. 직접 그들과 소통하지 않아도 되지만, 여기서는 누가 무엇을 하는지 보여드릴게요.","concepts.desktop-personas#1#p":"데스크톱 트래젝토리 (목표를 향해 화면을 조작하는 Ava 의 한 번 실행) 의 모든 단계마다 다섯 명의 페르소나 파동이 실행돼요. 각 페르소나는 오직 한 가지 일만 해요. 이 분리는 프롬프트를 간결하게, 출력을 구조화하며, 설계상 추론을 신중하게 유지하도록 돕습니다.","concepts.desktop-personas#2#h":"정찰병","concepts.desktop-personas#3#p":"지금 화면에 보이는 것을 보고해요. 요소를 만들어내지 않아요. 계획도 세우지 않아요. 요소 ID, 이름, 바운딩 박스, 신뢰도, 그리고 근원 소스 (UIA, Playwright DOM, 또는 OmniParser 비전) 가 포함된 ScreenState JSON 을 반환해요.","concepts.desktop-personas#4#h":"기획자","concepts.desktop-personas#5#p":"다음 단일 행동을 결정해요. 한 단계당 한 행동 — 결코 묶어서 하지 않아요. 되돌릴 수 있는 경로를 선호해요. 안전 온톨로지에 따라 위험을 분류해요. 종류, 대상, 매개변수, 위험 클래스, 이유, 예상 후 상태 예측이 포함된 ProposedAction JSON 을 출력해요.","concepts.desktop-personas#6#h":"실행자","concepts.desktop-personas#7#p":"승인 게이트를 통과한 후 기획자가 제안한 내용을 정확히 실행해요. 즉흥적인 시도는 없어요. 재시도도 없어요. 실패는 솔직하게 보고되며, 검증자가 다음 움직임을 처리해요.","concepts.desktop-personas#8#h":"검증자","concepts.desktop-personas#9#p":"행동이 제대로 이루어졌는지 확인해요. 새로 나온 ScreenState 를 기획자의 예측과 비교해요. 검증됨, 이탈함, 또는 롤백 필요 중 하나를 반환해요. 또한 루프 감지를 실행해요 — 이미 성공한 행동을 반복하는 것은 검증이 아니라 이탈이에요.","concepts.desktop-personas#10#h":"내레이터","concepts.desktop-personas#11#p":"트래젝토리 동안 사용자가 듣는 유일한 목소리예요. 단계마다 과거형 문장 하나씩 (\"Gmail 을 열었어요.\", \"작성 버튼을 클릭했어요.\") 으로 말해요. 또한 구조화된 작업 기록도 작성해요. 문제가 생겼을 때는 항상 알려주며, 문제를 숨기지 않아요.","concepts.desktop-safety#title":"데스크톱 안전 온톨로지","concepts.desktop-safety#0#p":"간단히 말해: Ava 가 화면에서 아무것도 클릭하기 전에, 행동의 위험도에 따라 분류해요. 화면 읽기? 해가 없어요. 돈 보내기나 삭제하기? 항상 멈춰서 먼저 물어봐요 — 매번, 예외 없이요. 아래 다섯 개의 레이블은 그 위험 사다리의 발판일 뿐이에요. 이건 고급 사용자용 세부 사항이지만 핵심은 간단해요: 위험한 일은 항상 당신의 허락이 필요하답니다.","concepts.desktop-safety#1#p":"제안된 모든 행동은 다섯 가지 위험 클래스 중 하나로 분류돼요. 분류는 세 가지 신호를 결합해요 — 화면상의 대상이 무엇인지, 자연어 설명 (\"의미 캡션\" — Ava 가 보고 있는 것에 대한 그녀의 말), 그리고 행동 설정 — 그리고 불일치가 있을 경우 더 위험하게 취급하며 상향 조정해요. 오탐지 (필요 없는 곳에 묻는 것) 는 그냥 성가신 거예요. 미탐지 (물어야 할 때 묻지 않는 것) 는 심각한 문제입니다.","concepts.desktop-safety#2#h":"다섯 가지 클래스","concepts.desktop-safety#3#li0":"관찰형 — UIA 트리, 스크린샷, 호버 읽기. 항상 자동 허용됩니다.","concepts.desktop-safety#3#li1":"탐색형 — 스크롤, 포커스 이동, 메뉴 열기. 드라이브 모드에서는 자동 허용됩니다.","start.first-five#5#li0":"질문 — \"내 페이지가 왜 비어 있나요?\", \"이 파일은 뭐 하는 거죠?\"","start.first-five#5#li1":"무언가를 만들어달기 — \"간단한 할 일 목록 페이지를 만들어줘.\"","start.first-five#5#li2":"무언가를 배우기 위해 — \"처음부터 파이썬을 가르쳐줘.\" (항상 무료예요.)","start.first-five#5#li3":"문서를 원할 때 — \"일 페이지 프로젝트 제안서를 써줘.\" 워드 파일이나 PDF 로 드릴게요.","start.first-five#6#c":"뭘 입력할지 모르겠나요? 지식이 풍부한 친구처럼 말해주세요. 평범한 단어가 딱 맞아요 — 시작하려면 기술 용어가 필요 없어요.","start.first-five#deeper#0#p":"그 간단한 루프 뒤에는 꽤 많은 일이 일어나고 있어요. Ava 를 사용하려면 이 모든 게 필요하지는 않지만, 궁금하다면 실제로 어떤 일이 일어나는지 알려드릴게요.","start.first-five#deeper#1#h":"도구와 승인","start.first-five#deeper#2#p":"Ava 가 파일을 읽거나 명령어를 실행하거나 코드를 편집할 때마다 그것은 모두 \"도구 호출\"이에요. 파일이나 시스템에 영향을 주는 모든 작업 전에 물어봐요 — 얼마나 자주 물어볼지는 권한 모드 (매번 묻기, 위험한 것만 묻기, 또는 바로 진행) 로 설정되어 있어요.","start.first-five#deeper#3#h":"모드 — 그녀의 마음가짐","start.first-five#deeper#4#p":"Ava 는 모드로 작동해요: 업무에 맞는 마음가짐과 올바른 툴킷의 조합이에요. 피커에서 언제든지 전환하거나 메시지 시작 부분에 접두사를 입력하면 돼요. 총 일곱 가지가 있죠.","start.first-five#deeper#6#h":"전문가와 라우팅","start.first-five#deeper#7#p":"어려운 작업에서는 Ava 가 배경에서 작은 전문가 팀 (계획자, 검사자, 빌더) 을 운영하며 각 단계를 가장 잘하는 모델로 라우팅해요. 당신은 이를 관리할 필요가 없어요 — 그녀가 당신을 위해 조정해 주죠.","start.local-vs-cloud#title":"로컬 대 클라우드, 한 문장으로","start.local-vs-cloud#0#p":"Ava 가 하는 모든 일은 명시적으로 동의하지 않는 한 로컬이에요. 메모리, 작업, 저널, 성격, 설정 — 모두 기기의 ~/.ava/ 및 .ava/(프로젝트별) 에 저장돼요. HTTPS 로 모델 제공자와 대화하여 요청을 실행한 후 다시 로컬로 돌아옵니다. 집으로 전화를 걸지 않아요. 텔레메트리를 수집하지 않아요. 당신의 코드로 학습하지 않아요.","start.local-vs-cloud#1#p":"로그인하면 플랫폼 관리 모델 (Qwen, MiniMax) 에서 매월 300 개의 무료 크레딧을 받고, 기기 간 메모리와 설정을 위한 선택적 클라우드 동기화를 이용할 수 있어요. 동기화는 기능별로 가능하며 언제든지 취소할 수 있어요. 자체 API 키를 가져오면 계정이 없이도 Ava 가 완전히 작동해요.","start.local-vs-cloud#2#c":"규칙: 로컬은 절대적입니다. 클라우드는 추가 기능입니다.","start.first-model#title":"AI 를 직접 선택해야 하나요?","start.first-model#0#p":"안심이 될 만한 소식이에요: AI 를 직접 고를 필요가 없어요. Ava 가 각 단계마다 적절한 모델을 자동으로 선택하므로, 생각할 필요 없이 좋은 결과를 얻을 수 있어요.","start.first-model#1#p":"당신이 선택할 수 있는 유일한 것은 라우팅 스타일이에요 — 기본값이 거의 모든 사람에게 적합하죠. 특정 이유가 있을 때만 다른 것이 필요해요.","start.first-model#2#h":"세 가지 스타일","start.first-model#3#li0":"Maestro — 기본값. 안정적이고 신뢰할 수 있으며 예측 가능해요. 잘 모르겠다면 이게 맞아요.","start.first-model#3#li1":"Supernova — 무겁고 다단계 작업에 적합해요. 작업의 각 부분에 다른 전문가를 투입하는 것이 유리한 경우죠.","start.first-model#3#li2":"Aurora — 데이터가 EU 내에 머물러야 할 때 (공공 부문, 의료, 엄격한 개인정보 보호). 유럽산 오픈 웨이트 AI 로만 완전히 실행됩니다.","start.first-model#4#p":"채팅 상단의 모델 피커에서 언제든지 전환할 수 있어요. 고정된 것은 없어요.","start.first-model#5#c":"특정 모델을 직접 제어하고 싶으신가요? 가능합니다 — \"자세히 보기\"를 열어보세요.","concepts.desktop-safety#3#li2":"되돌릴 수 있는 변경 — 필드에 입력하거나 붙여넣기, 앱 열기, URL 이동. Ask 모드에서는 확인하며, 화이트리스트 내 드라이브 모드에서는 자동 수행됩니다.","concepts.desktop-safety#3#li3":"되돌릴 수 없는 변경 — 보내기, 제출하기, 결제하기, 삭제하기, 확인하기, 게시하기. 권한 수준과 관계없이 항상 확인합니다. 승인 기록은 캐싱되지 않습니다.","concepts.desktop-safety#3#li4":"특권 작업 — UAC 승격, sudo, 레지스트리 편집, 자격 증명 요청. 기본적으로 금지되며, 세션마다 단일 사용 승인 (opt-in) 이 필요합니다.","concepts.desktop-safety#4#h":"승인 기록 저장 안 함","concepts.desktop-safety#5#p":"모든 경쟁사는 승인 기록을 저장합니다 ('예'라고 답한 것을 기억했다가 다음에 다시 사용합니다). 이것이 프롬프트 주입 공격의 가장 큰 발판입니다 — 위험한 웹 페이지가 AI 에게 숨겨진 지시사항을 넣어 사용자를 해치려는 공격입니다. 승인 기록을 저장하면 해킹된 페이지가 이전에 준 '예'를 이용할 수 있습니다. Ava 는 절대 저장하지 않습니다. 매번 되돌릴 수 없는 작업을 할 때마다 새로 묻습니다.","concepts.desktop-safety#6#h":"비밀 정보 처리","concepts.desktop-safety#7#p":"비밀번호, API 키, 그리고 로그인할 때 두 번째 앱이나 문자로 받는 일회용 코드 (2FA 코드) 는 가상 표시자 (opaque handles) 를 통해 처리됩니다. 이는 실제 값을 대신하는 자리표시자입니다. Ava 는 \"{secret}\" 만 보지 실제 비밀번호는 보지 않습니다. 실제 값은 그녀의 메모리나 활동 로그, 혹은 그녀가 \"읽는\" 내용에 들어가지 않습니다. 별도의 저수준 레이어가 마지막 순간, 키 입력 시점에 직접 입력하므로 AI 부분은 이를 건드리지 않습니다.","reference.cli#title":"CLI 명령어","reference.cli#0#p":"이 페이지는 CLI 를 위한 것입니다 — 버튼을 클릭하는 대신 터미널 창에서 입력하는 Ava 의 버전입니다. 확장 프로그램이나 데스크톱 앱을 사용한다면 완전히 건너뛰어도 됩니다. 키보드를 선호하는 분들을 위해 여기에 있습니다.","reference.cli#1#p":"CLI 는 명령어 반복 실행 환경 (REPL) 입니다 — 입력을 기다리는 프롬프트로, 입력한 내용을 실행한 뒤 다시 기다립니다. 이 슬래시 명령어 (\"/\" 로 시작하는 지시사항) 는 프롬프트에서 작동합니다.","reference.cli#2#li0":"`/help` — 명령어 목록과 현재 모드 표시.","reference.cli#2#li1":"`/mode <name>` — 모드 전환 (작업, 작성, 계획, 채팅, 교육, 보안, 브레인스토밍).","reference.cli#2#li2":"`/model <id>` — 세션을 벗어나지 않고 모델 전환.","reference.cli#2#li3":"`/clear` — 현재 대화 지우기. 메모리는 그대로 유지됩니다.","reference.cli#2#li4":"`/history` — 이 프로젝트의 과거 대화 목록 표시.","reference.cli#2#li5":"`/memory` — 메모리 브라우저 열기.","reference.cli#2#li6":"`/tasks` — 작업 목록 표시 및 관리.","reference.cli#2#li7":"`/journal` — 오늘의 일기 항목 열기.","reference.cli#2#li8":"`/settings` — 설정 메뉴 열기.","reference.cli#2#li9":"`/exit` — REPL 종료.","reference.cli#3#h":"실행 플래그","reference.cli#4#p":"플래그는 Ava 를 시작할 때 추가하는 옵션으로, 모두 \"--\" 로 시작하여 어떻게 열지를 설정합니다.","reference.cli#5#li0":"`--mode <name>` — 특정 모드로 시작.","reference.cli#5#li1":"`--model <id>` — 특정 모델로 시작.","reference.cli#5#li2":"`--permission <mode>` — 엄격 / 균형 / 자율.","concepts.modes#0#p":"모드는 Ava 가 가진 마음가짐입니다 — 마치 동료들이 서로 다른 모자를 쓰는 것과 같아요. 같은 사람이고 당신에 대한 기억도 같지만, 빌더는 선생님처럼 다르게 생각합니다. 모드만 선택하면 행동 방식과 함께 어떤 도우미들을 데려올지도 달라집니다. 모드 선택기로 언제든 전환하거나, 두 글자 단축키를 입력하세요.","concepts.modes#2#h":"어떤 모드를 원하시나요?","concepts.modes#3#p":"무엇을 하려고 하는지부터 시작하세요 — 모드는 그다음에 따라 정해집니다:","concepts.modes#4#li0":"무언가를 만들거나 바꾸고 싶어요 → 코드 (>>). 당신이 설명하면 Ava 가 만들어 보여줍니다. 모든 변경 사항을 먼저 확인시켜 주죠. 큰 작업에는 전체 도우미 팀이 나섭니다.","concepts.modes#4#li1":"변경 전에 계획이 필요해요 → 계획 (::). Ava 가 충분히 생각한 뒤 승인하거나 수정할 계획을 건네줍니다. 이 모드에서는 파일을 만지지 않습니다.","concepts.modes#4#li2":"단순히 대화하거나 물어보고 싶어요 → 채팅 (..). 기억력과 뉴스, 날씨 정보를 갖춘 사고 파트너예요. 파일 변경이나 코드가 없어요 — 오직 대화만 가능하죠.","concepts.modes#4#li3":"뭔가를 배우고 싶어요 → 가르침 (??). 당신을 위한 실제 강의: 수업, 퀴즈 등등. 모든 플랜에서 영구 무료. 처음이라면 완벽해요.","concepts.modes#4#li4":"프로젝트의 보안 구멍을 점검받고 싶어요 → 보안 (!!). 표준적인 웹 취약점 목록 (\"OWASP\" 카테고리) 과 알려진 보고된 결함 (\"CVEs\") 을 팀이 검토한 뒤, 각 이슈의 심각도에 따라 정렬된 보고서를 건네줍니다. 개발자를 위한 기능이에요 — 해당되지 않으면 건너뛰세요.","concepts.modes#4#li5":"아이디어가 필요해요 → 브레인스토밍 (**). 실제 상황에 기반한 옵션을 생성하고, 약점이 있는 것은 찾아내며, 나머지를 다음 단계로 다듬습니다.","concepts.modes#4#li6":"문서를 쓰고 싶어요 → 글쓰기 (<<). 보고서, 제안서, 편지, 기사 — 마크다운으로 초안을 작성하고 브랜드가 적용된 Word 문서나 PDF 로 내보내며, 섹션별로 다듬습니다. 코드가 없어요, 오직 글쓰기만 가능합니다.","concepts.modes#5#c":"\"도우미 팀\"(페르소나) 은 전적으로 배후에서 작동합니다 — 직접 대화하지 않습니다. 더 철저한 답변만 받게 됩니다. 이름을 알 필요는 없습니다.","concepts.modes#6#c":"대화 중간에 모드를 전환할 수 있습니다. 기억은 이어지고, 전문가들은 새 모드에 맞게 초기화됩니다.","concepts.tasks-journal#title":"작업 및 일지","concepts.tasks-journal#0#p":"Ava 는 당신을 위해 세 가지 종류의 노트를 보관하며, 혼동하기 쉽습니다. 빠르게 기억하는 법: 기억은 그녀가 당신에 대해 아는 것, 작업은 아직 해야 할 일, 일지는 일이 어떻게 진행되었는지의 일기입니다. 각각 언제 사용하는지 알려드릴게요.","concepts.tasks-journal#1#li0":"기억 — 영속적인 사실. 선호도, 결정, 패턴. 반복해서 물어보면 대답하지만, 직접 만들기는 드뭅니다.","concepts.tasks-journal#1#li1":"작업 — 할 일. 마감일과 상태가 있는 액션 아이템. 완료하면 체크 표시를 합니다.","concepts.tasks-journal#1#li2":"일지 — 성찰. 매일 로그, 이중 항목 (당신의 것과 Ava 의 세션 관찰). 기분 추적, 세션 리뷰, 내일의 맥락에 유용합니다.","concepts.tasks-journal#2#p":"Ava 는 상황에 맞게 세 곳 모두에 기록합니다. 대시보드에서 직접 어느 곳에도 쓸 수 있습니다. Ava 를 사용하는 곳에 단일 장소로 고정된 것은 없습니다 — 명령줄 도구에서 만든 작업도 데스크톱 앱 등 다른 곳에서 자동으로 나타납니다.","concepts.permissions#title":"권한 — 당신의 안전 다이얼","concepts.permissions#0#p":"권한은 당신의 안전 다이얼입니다. 컴퓨터에서 무언가를 할 때 Ava 가 당신의 허락을 받는지, 아니면 그냥 진행하는지 결정합니다. 모든 것에 대해 물어보게 설정하거나, 위험한 것만 물어보게 하거나, 신뢰하고 실행하게 할 수 있습니다. 언제든지 변경할 수 있습니다. 잘 모르겠다면 기본값에 두면 됩니다.","concepts.permissions#1#p":"Ava 는 60 개의 도구를 가지고 있습니다 (\"도구\"는 파일 읽기, 웹 검색 등 취할 수 있는 행동입니다). 모든 도구는 카테고리 (파일 작업, 셸, Git, 웹, 미디어, 데이터베이스, 시스템, 문서, 메모리, 학습) 에 속합니다. 모든 도구 호출은 실행되기 전에 권한 게이트 (먼저 물어볼지 결정하는 체크포인트) 를 통과합니다. 자동 승인, 한 번 물어보기, 항상 물어보기를 당신이 통제합니다.","concepts.permissions#3#p":"균형이 기본값입니다. 그녀의 행동을 면밀히 검토할 때 (각 단계를 확인) 엄격하게. 그냥 맡기고 싶을 때 자율적으로.","concepts.permissions#4#c":"자율이라고 해서 통제가 없는 것은 아닙니다. 계획, 명확화 질문, 사용자 입력을 명시적으로 요구하는 프롬프트는 여전히 입력을 기다립니다. 되돌릴 수 없는 작업 (Git 강제 푸시, 데이터베이스 삭제) 은 모드와 상관없이 항상 확인합니다.","concepts.interjection#title":"방향 조절 및 중단","concepts.interjection#0#p":"항상 당신이 주도권을 쥐고 있습니다. Ava 가 작업하는 동안, 발걸음을 끊지 않고 새로운 방향으로 살짝 밀거나, 완전히 멈출 수도 있습니다. 두 버튼, 두 결과 — 이것이 이 페이지의 전부입니다.","features.creative-studio#1#p":"이미지, 동영상, 음악, 목소리 생성까지 — 코드를 쓰는 워크플로우 안에 그대로 담았습니다. 아이콘 하나부터 제품 시안, 데모 영상, 튜토리얼 내레이션까지 만들 수 있어요. MiniMax 기술로 구동됩니다.","features.creative-studio#2#h":"어떤 것을 만들 수 있을까요","features.creative-studio#3#li0":"이미지 — 프롬프트로 PNG/JPG 를 만드세요. 배경 제거도 한 번의 명령으로 가능합니다.","features.creative-studio#3#li1":"비디오 — 텍스트 프롬프트로 짧은 AI 동영상을 만듭니다 (MiniMax Hailuo).","features.creative-studio#3#li2":"음악 — 악기 반주곡이나 가사가 포함된 보컬 트랙을 만들 수 있습니다.","features.creative-studio#3#li3":"음성 — 원하는 목소리를 선택해 텍스트를 말로 변환할 수 있습니다.","features.creative-studio#4#p":"Creative Studio 비용은 다른 모든 기능과 같은 크레딧 풀에서 사용돼요 — 하나의 풀, 하나의 잔액이에요. BYOK 으로 직접 MiniMax 키를 연결하면 플랜 내에서 무료로 사용할 수 있습니다.","features.creative-studio#5#c":"Creative Studio 는 무료 티어도 이용할 수 있습니다. 따로 유료로 추가해야 하는 기능이 아니에요.","features.desktop-automation#title":"데스크톱 자동화","features.desktop-automation#0#p":"쉽게 말해: Ava 가 마우스와 키보드를 대신해서 작업을 해드릴 수 있어요. 앱을 열고, 버튼을 누르고, 양식을 채우는 일까지 — 중요한 건 당신이 지켜보고 승인하면 되죠.","features.desktop-automation#1#p":"Ava 의 새로운 모드예요. 접두사로 @@ 를 붙이세요. Ava 가 데스크톱을 살펴보고 무엇을 할지 결정한 뒤, 화면 속 앱들을 직접 제어하는 UI 자동화를 실행해 일을 끝내줍니다. 실제 컴퓨터에서 실제 권한으로 돌아가며, 클라우드 브라우저가 아니에요. 출시되면 모든 티어에서 이용하실 수 있습니다.","features.desktop-automation#2#h":"왜 또 다른 도구가 필요할까요","features.desktop-automation#3#p":"다른 데스크톱 자동화 제품은 책상에 앉았을 때만 시작할 수 있죠. 하지만 Ava 는 새벽 2 시에 오류 알림이 울려도 여전히 곁에 있어요. IDE 는 계속 돌아오고, 휴대폰은 안전한 채널로 연결되며, 중요한 결정은 터치 하나로 승인할 수 있습니다.","features.desktop-automation#4#p":"게다가 Ava 는 세션을 넘어 앱 탐색 방법도 기억해요. 다른 에이전트들은 매번 처음부터 다시 배우지만, Ava 는 그렇지 않아요. 이 기억 능력은 사용할수록 더 빛을 발합니다.","features.desktop-automation#5#h":"어떻게 작동하나요","features.desktop-automation#6#p":"각 단계마다 5 가지 역할이 순차적으로 움직여요: 스카우트가 관찰하고, 플래너가 다음 행동을 정하며, 액터가 실행하고, 검증자가 확인하며, 내레이터가 결과를 알려줍니다. 사이드카는 가장 안정적이고 효율적인 방법을 골라내죠. 네이티브 앱엔 UIA 를 쓰고, 브라우저엔 Playwright 를 쓰며, 다른 방법이 없으면 OmniParser 의 시각 기능을 활용합니다.","features.desktop-automation#7#p":"안전 원칙, 근거 계층 구조, 비상 정지 기능, 세션 허용 목록 모델에 대한 개념 페이지를 참고해 주세요.","reference.cli#5#li3":"--project <path> — 프로젝트 루트를 명시적으로 설정합니다.","reference.desktop-budget#title":"데스크톱 예산 제한","reference.desktop-budget#0#p":"Ava 가 대신 데스크톱을 제어할 때 — 클릭, 타이핑, 앱 실행 등 — 각 실행은 \"트래젝토리\"라고 불립니다. 이 페이지는 한 번의 실행이 너무 길어지거나 비용이 많이 들지 않도록 막아주는 안전 제한에 대해 설명합니다. 핵심은 그녀가 초과하기 전에 항상 멈추고 확인한다는 점입니다. 자세한 숫자는 여기에 있습니다.","reference.desktop-budget#1#p":"모든 트래젝토리는 세 가지 동시 제한 (하드 리밋) 아래에서 실행됩니다. 먼저 도달한 제한이 적용됩니다. 트래젝토리는 위반 시 조용히 진행하지 않고 — 상황을 안내하는 도우미인 내레이터가 일시 정지하고 무엇을 할지 물어봅니다.","reference.desktop-budget#2#h":"세 가지 하드 캡 (기본값)","reference.desktop-budget#3#li0":"단계 수 — 30 단계","reference.desktop-budget#3#li1":"토큰 예산 — 500,000 토큰","reference.desktop-budget#3#li2":"실제 시간 — 5 분","reference.desktop-budget#4#h":"작업 비용 범위","reference.desktop-budget#5#li0":"간단함 (문서 검색, 페이지 열기) — 5–10 단계, 약 70–135K 토큰, 약 $0.04–0.08","reference.desktop-budget#5#li1":"중간 (로그인, 로그 확인, 출력 다운로드) — 15–25 단계, 약 205–340K 토큰, 약 $0.12–0.21","reference.desktop-budget#5#li2":"복잡함 (GitHub 이슈 3 개 분류) — 25–30 단계, 약 340–410K 토큰, 약 $0.21–0.25","reference.desktop-budget#6#p":"위의 토큰 수는 개별 트래젝토리별 기술적 제한이며 월 사용량이 아닙니다. 월 사용량은 크레딧으로 계산되며, 무료 티어의 월 300 은 채팅, 코드, 몇몇 자동화 작업을 섞어서 사용하기에도 충분합니다.","reference.desktop-budget#7#c":"시작 시 작업별로 제한을 재정의할 수 있지만, 위반 시에는 항상 결정 지점이 나타납니다. 예산은 결코 조용히 소모되지 않습니다.","reference.desktop-whitelist#title":"데스크톱 세션 화이트리스트","reference.desktop-whitelist#0#p":"\"화이트리스트\"란 Ava 가 데스크톱을 제어하는 동안 만질 수 있는 앱과 웹사이트의 목록을 의미합니다. 이 페이지는 어떻게 권한을 부여하는지, 그리고 왜 매번 초기화되는지 설명합니다. 간단히 말해, 그녀는 당신이 허락한 곳에서만 행동할 수 있으며, 새로운 곳으로 이동하기 전에 묻습니다.","reference.desktop-whitelist#1#p":"데스크톱 세션 시작 시 Ava 는 어디에서 활동할 수 있는지 묻습니다. 평이한 영어로 가능합니다: \"Gmail, Cursor, Azure 포털.\" 그녀는 이를 읽고 다시 확인해 줍니다 (\"Gmail 웹, Cursor 앱, portal.azure.com\").","reference.desktop-whitelist#2#h":"어떻게 강제하는지","reference.desktop-whitelist#3#p":"보기만 하는 작업 — 스크린샷 찍기, 화면의 버튼과 필드 목록 읽기 (\"UIA 트리\", Windows 가 창 내부 구조를 매핑한 것) — 는 어디서나 허용됩니다. 왜냐하면 앱을 화이트리스트에 추가할지 결정하려면 화면에 무엇이 있는지 봐야 하기 때문입니다. 무언가를 변경하는 모든 것은 목록 밖에서 차단되며, Ava 가 일시 정지하고 추가할지 묻습니다.","reference.desktop-whitelist#4#h":"의도적으로 세션 범위만","reference.desktop-whitelist#5#p":"화이트리스트는 세션 간에 유지되지 않습니다. \"이 앱 기억하기\" 옵션은 없습니다. 모든 새 트래젝토리는 새로운 범위로 시작합니다. 설계상 불편하게 만든 것입니다 — 재승인을 잊는 것은 버그가 아닌 기능입니다.","reference.desktop-whitelist#6#h":"트래젝토리 중간 추가","reference.desktop-whitelist#7#p":"트래젝토리 동안 헤더에서 앱을 추가할 수 있습니다: \"+ 앱 허용\"을 누르면 작은 입력창이 열립니다. 추가를 탭하면 새 앱이 세션 나머지 동안 활성화됩니다.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"이미지, 짧은 동영상, 노래, 또는 음성 내레이션을 만들고 싶으신가요? 그냥 설명하면 Ava 가 만들어 드립니다 — 디자인이나 오디오 소프트웨어 없이도 됩니다."},"es":{"start.for-non-coders#title":"¿Nunca has escrito código? Empieza aquí","start.for-non-coders#0#p":"Si nunca has escrito una línea de código, eres exactamente para quién es Ava. No necesitas aprender jerga para empezar: hablas con ella en lenguaje sencillo, como le pedirías a un amigo conocedor. Esta página es toda tu puerta de entrada.","start.for-non-coders#1#h":"Qué puedes hacer hoy, sin experiencia","start.for-non-coders#2#li0":"Pídele cualquier cosa, en palabras normales: \"¿qué hace este archivo?\", \"¿por qué está mi página en blanco?\", \"¿qué es una base de datos, de hecho?\". Ella responde en lenguaje sencillo y recuerda la conversación.","start.for-non-coders#2#li1":"Aprende algo desde cero: di \"enséñame Python desde cero\" y te construye un curso adecuado con lecciones y cuestionarios. Esto es siempre gratis.","start.for-non-coders#2#li2":"Consigue algo construido: describe lo que quieres (\"un botón que descargue mis notas\") y lo escribe, mostrándote cada cambio antes de que ocurra.","start.for-non-coders#3#h":"No necesitas entenderlo todo","start.for-non-coders#4#p":"Ava tiene mucha maquinaria bajo el capó: modos, modelos, especialistas, enrutamiento. Verás esas palabras por la aplicación y en estos documentos. Aquí está el secreto: puedes ignorar casi todo. Ava elige las herramientas correctas y los ayudantes correctos para ti automáticamente. Las páginas técnicas están ahí cuando tengas curiosidad, no porque las necesites para empezar.","start.for-non-coders#5#h":"Un primer camino suave","start.for-non-coders#6#li0":"Instala Ava (siguiente página) y abre el chat.","start.for-non-coders#6#li1":"Escribe una pregunta real que tengas. Cualquier cosa. Mira cómo responde.","start.for-non-coders#6#li2":"Prueba el modo aprendizaje: escribe \"enséñame\" y un tema. Síguela.","concepts.memory#1#p":"Ava tiene una memoria persistente (\"persistente\" significa que se mantiene después de cerrar la aplicación) que sobrevive entre conversaciones, proyectos y máquinas si activas la sincronización (la sincronización copia tu memoria entre tus dispositivos). No es un registro de chat. Es una comprensión estructurada y buscable de quién eres, qué te gusta y qué has decidido.","concepts.memory#2#h":"Cinco capas","concepts.memory#3#li0":"Extraer — hechos clave capturados de cada mensaje en tiempo real.","concepts.memory#3#li1":"Reflexionar — análisis más profundos al final de sesiones significativas. Patrones, temas, contradicciones.","concepts.memory#3#li2":"Acumular — correcciones y preferencias se acumulan durante semanas y meses.","concepts.memory#3#li3":"Analizar — el motor de gráficos conecta memorias relacionadas y marca contradicciones cuando nueva información entra en conflicto con la antigua.","concepts.memory#3#li4":"Consolidar — memorias similares se fusionan; las obsoletas se eliminan. La memoria se vuelve más nítida con el tiempo, no más ruidosa.","concepts.memory#4#c":"Las cinco capas anteriores funcionan por sí solas — nunca tienes que gestionarlas. Están aquí para que veas que la memoria mejora genuinamente con el tiempo en lugar de convertirse en un montón de desorden.","concepts.memory#5#h":"Recuperación","concepts.memory#6#p":"Cuando haces una pregunta, Ava busca en su memoria por significado (\"búsqueda semántica\" — entiende lo que quieres decir, así que encuentra lo correcto aunque uses otras palabras), no solo buscando coincidencias exactas. Los filtros según el modo se aplican también: el Modo Chat recupera contexto personal, el Modo Trabajo recupera decisiones del proyecto y patrones de código.","concepts.memory#7#c":"La memoria está limitada por usuario y por proyecto (tus memorias son tuyas, separadas por persona y por proyecto). Los secretos y credenciales (contraseñas, claves) están bloqueados en el límite de guardado — nunca pueden llegar a la memoria.","concepts.memory#title":"Memoria — cómo recuerda Ava a ti","concepts.memory#0#p":"En términos sencillos: Ava te recuerda. Dile algo una vez — lo que te gusta, una decisión que tomaste — y ella lo guarda, así no tienes que repetirlo en el siguiente chat o la próxima semana. Esa es la idea principal. Las capas de abajo solo explican cómo mantiene esa memoria ordenada con el tiempo.","concepts.desktop-grounding#title":"Jerarquía de \"grounding\" en escritorio (Previsualización)","concepts.desktop-grounding#0#c":"Previsualización — cómo Scout decide qué fuente de grounding usar en cada paso.","concepts.desktop-grounding#1#p":"Antes de que Ava pueda hacer clic en un botón, tiene que entender realmente qué hay en tu pantalla y dónde están las cosas — eso es \"grounding\" (descubrir qué es cada cosa en pantalla y su posición exacta). Tiene tres formas de hacerlo y elige la más fiable que funcione para la app en la que estás. Esto es un detalle técnico avanzado; lo importante es que prefiere métodos sólidos y precisos a adivinar desde una imagen.","concepts.desktop-grounding#2#p":"Tres niveles, evaluados en orden. Gana la fuente fiable más económica.","concepts.desktop-grounding#3#h":"1. Ventana del navegador → DOM de Playwright","concepts.desktop-grounding#4#p":"Si la ventana activa es un navegador web, Ava lee la estructura propia de la página (el \"DOM\" — la lista subyacente de lo que hay en una página) en lugar de adivinar desde la imagen. Leer la estructura es unas 10× más fiable que mirar píxeles a ojo — sabe exactamente dónde está cada botón y cuándo ha terminado de cargar la página. Este es el camino principal para cualquier cosa en la web, no una copia de seguridad.","concepts.desktop-grounding#5#h":"2. App nativa con UIA → Automatización de interfaz de usuario de Windows","concepts.desktop-grounding#6#p":"Para aplicaciones de escritorio ordinarias en Windows, Ava lee un mapa de accesibilidad integrado (\"UIA\", los mismos datos que usan los lectores de pantalla para describir una ventana) — enumera cada control, su nombre y dónde está ubicado. Si ese mapa devuelve al menos cinco elementos utilizables y con nombre, ella confía en él y lo usa.","concepts.desktop-grounding#7#h":"3. UIA vacío o inútil → Visión de OmniParser","concepts.desktop-grounding#8#p":"Cuando ese mapa falta o es inútil (algunas apps, juegos y pantallas remotas no proporcionan uno), Ava recurre a mirar realmente una captura de pantalla. Una herramienta de visión (OmniParser) detecta las zonas clickeables y etiqueta qué es cada una, convirtiendo la imagen de nuevo en una lista sobre la que puede actuar — combinado con lo poco que el mapa de accesibilidad dio.","concepts.desktop-grounding#9#c":"OmniParser es opcional la primera vez que Ava lo necesita, con una advertencia clara de privacidad. Los usuarios BYOK pueden apuntar a su propio despliegue local de OmniParser.","concepts.desktop-kill-switches#title":"Interruptores de parada de emergencia en escritorio (Previsualización)","concepts.desktop-kill-switches#0#c":"Previsualización — tres formas independientes de cancelar una trayectoria en ejecución. Cualquiera de ellas funciona.","concepts.desktop-kill-switches#1#p":"Un \"interruptor de parada de emergencia\" es exactamente lo que dice el nombre — una forma de emergencia para detener a Ava instantáneamente cuando está controlando tu pantalla. Lo tranquilizador: hay tres, cada uno construido por separado, así que si uno falla, otro sigue funcionando. No tienes que aprender los tres. Solo sé que cuando algo parece mal, siempre puedes detenerlo, y la parada más fuerte (la de pánico abajo) no depende de que Ava colabore.","concepts.desktop-kill-switches#2#p":"Después de leer todos los incidentes públicos de autonomía (casos reales donde agentes de IA ignoraron comandos de parada, borraron archivos de correo, limpiaron discos), construimos tres interruptores de parada en tres capas diferentes. Ninguno depende del modelo de IA en sí — si Ava se queda atascada o no responde, aún puedes detenerla.","concepts.desktop-kill-switches#3#h":"Pausa — espacio o el botón Pausa","concepts.desktop-kill-switches#4#p":"Se congela en el siguiente límite de paso. Se puede reanudar. Úsalo cuando quieras intervenir sin perder la trayectoria.","concepts.desktop-kill-switches#5#h":"Detener — Escape o el botón Detener","concepts.desktop-kill-switches#6#p":"Aborto limpio. El narrador resume lo hecho hasta ahora. No se puede reanudar. El registro de auditoría se confirma.","concepts.desktop-kill-switches#7#h":"Apagado de pánico — triple-Escape o Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"La parada más drástica que existe. Un pequeño programa de vigilancia separado fuerza el cierre de la parte de Ava que controla tu pantalla. No espera a que la IA responda, no necesita que la ventana de la aplicación funcione y no le importa en qué estado estén las cosas: simplemente la apaga. Esta es la opción para cuando algo está realmente mal.","concepts.desktop-kill-switches#9#p":"Las tres funcionan también desde la aplicación complementaria. Cualquiera de los controladores puede terminarla.","reference.tools#title":"Referencia de herramientas","reference.tools#0#p":"Esta es la lista completa de todas las herramientas que tiene Ava: una \"herramienta\" es simplemente una acción específica que puede realizar, como leer un archivo o ejecutar una búsqueda. No necesitas leer esta página. Ava elige la herramienta correcta cada vez por sí misma. Está aquí para cuando tengas curiosidad sobre exactamente qué puede hacer.","reference.tools#1#p":"El conjunto completo de herramientas integradas. Cada herramienta aquí registrada está en el motor central (el núcleo detrás de las tres interfaces) y disponible para Ava cuando el modo y el modo de permisos lo permiten. Filtra por categoría o riesgo.","reference.tools#2#p":"No hace falta memorizar nada de esto: la tabla de abajo es solo una tarjeta de referencia.","reference.tools#4#h":"Niveles de riesgo","reference.tools#5#li0":"Seguro — lee cosas sin cambiar nada. file_read, glob (buscar archivos por patrón de nombre), grep (buscar texto dentro de archivos), git_status (Git es el sistema que rastrea los cambios en tu proyecto).","reference.tools#5#li1":"Escribir — cambia archivos, guarda un punto de control de tu trabajo (un \"commit\") o produce algo nuevo. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Peligroso — ejecuta comandos en tu computadora (la \"consola\"), controla el escritorio, va a internet o consulta bases de datos. bash, browser, desktop_*.","reference.tools#6#c":"Los especialistas de roles tienen sus propias listas permitidas de herramientas. Scout puede leer pero no escribir. Builder tiene acceso total. Challenger no tiene herramientas en absoluto: su trabajo es cuestionar el plan.","reference.models#title":"Modelos","reference.models#0#p":"Un \"modelo\" es el cerebro de la IA que piensa: Qwen, DeepSeek, Mistral y otros. Esta página lista todos los modelos que puede usar Ava. En resumen: no tienes que elegir uno. Ava selecciona el modelo correcto para cada paso ella misma. Lee más solo si quieres entender o anular eso.","reference.models#1#p":"Cada modelo al que Ava puede enrutar, además de las tres estrategias de orquestación: las reglas que deciden qué modelo maneja cada parte de un trabajo. Elige un modo de enrutamiento y deja que Ava gestione, o elige un solo modelo y omite el enrutamiento por completo.","reference.models#2#h":"Modos de enrutamiento","reference.models#3#p":"Tres estrategias orquestadas. El mismo flujo de trabajo de roles (el pequeño equipo de asistentes expertos que Ava ejecuta tras bambalinas) funciona en las tres; lo que cambia es la flota subyacente de modelos. Elige un modo en el selector de modelos y Ava se encarga del resto. Cada tarjeta de abajo muestra a los especialistas constituyentes a los que el director enruta.","reference.models#4#p":"No necesitas memorizar las tarjetas de abajo: están aquí para que veas de qué está hecha cada estrategia.","reference.models#6#c":"Aurora es deliberadamente solo Mistral. Si un modelo Mistral no está disponible, el enrutador devuelve un error en lugar de redirigir: esa es la garantía de la pila de la UE. Elige Maestro o Supernova para una degradación elegante.","reference.models#7#c":"Los tres modos están disponibles universalmente: con créditos de plataforma y con tus propias claves. BYOK añade la opción de omitir la orquestación y controlar un solo modelo directamente.","reference.models#8#h":"Modelos gestionados por la plataforma","reference.models#9#p":"Disponible en todos los planes, incluido el nivel gratuito. Los tokens (las unidades de texto en las que se mide la IA: aproximadamente tres cuartas partes de una palabra cada uno) cuentan contra tu asignación de plan. Las claves (las contraseñas privadas que desbloquean cada modelo de pago) son rotadas y monitoreadas por la plataforma: nada que configurar por tu parte.","reference.models#11#h":"Trae tu propia clave","reference.models#12#p":"Una \"clave de API\" es una contraseña privada que permite al software usar un servicio de pago en tu cuenta propia. \"BYOK\" simplemente significa \"traer tu propia clave\" — usar la tuya en lugar de la nuestra. Pega tu clave de API en configuración. Las solicitudes BYOK van directamente de Ava al proveedor (la empresa que ejecuta el modelo) — no pasan por nuestra infraestructura ni consumen tokens de plataforma. Tú pagas al proveedor; nosotros no vemos el tráfico.","reference.models#14#c":"Para puntuaciones de benchmarks, etiquetas de capacidades y filtros lado a lado, consulta la página completa de Modelos en ava-supernova.com/models. Los precios mostrados arriba son nuestra mejor lectura de cada tarjeta de tarifas del proveedor en la publicación — siempre revisa el sitio web del proveedor antes de comprometerte con una carga de trabajo.","reference.personas#title":"Orquestación de roles","reference.personas#0#p":"Un \"rol\" es un papel de ayuda que Ava juega detrás de escena para tareas difíciles — un explorador, un planificador, un verificador de hechos. Nunca hablas con ellos directamente y no necesitas entender esta página para usar Ava. Está aquí cuando tienes curiosidad sobre cómo ella divide un trabajo grande en un pequeño equipo experto.","reference.personas#1#p":"24 especialistas en 5 equipos de modo. El Conductor (el ayudante que coordina el resto) decide qué equipo corre, en qué orden y con qué contexto. El modo Conversación no tiene roles — es Ava misma.","reference.personas#2#h":"Cómo funciona la orquestación","reference.personas#3#li0":"Envías un mensaje en modo Planificar, Enseñar, Seguridad o Lluvia de ideas (o una solicitud compleja de Trabajo).","reference.personas#3#li1":"El Conductor lee la solicitud, elige el equipo de modo y crea un plan de ejecución — algunos roles se ejecutan secuencialmente, otros en oleadas paralelas.","reference.personas#3#li2":"Cada rol tiene su propio sistema de instrucciones, una lista permitida restringida de herramientas y un conjunto compartido de contexto de lo que encontraron los roles anteriores.","reference.personas#3#li3":"El último rol produce un resumen, un plan o un informe, según el modo.","reference.personas#3#li4":"Ava te presenta el resultado. Aprobas, ajustas o rediriges.","reference.personas#4#p":"La lista completa abajo es solo de referencia — no hace falta memorizar quién hace qué. Ava ensambla el equipo correcto para ti.","reference.personas#6#c":"Solo el modo Trabajo invoca al equipo completo para tareas complejas. Las ediciones simples ejecutan a Ava directamente — sin sobrecarga de orquestación.","reference.config#title":"Configuración","reference.config#0#p":"Esta página te muestra dónde guarda Ava sus configuraciones y archivos en tu computadora. Casi nunca tendrás que tocarlos manualmente: la app se encarga de todo por ti. Solo acude aquí si quieres ver, respaldar o compartir esos archivos tú mismo.","reference.config#1#p":"Ava lee su configuración (sus ajustes guardados) desde dos ámbitos. Los ajustes globales — los que valen para todo — están en una carpeta llamada ~/.ava/ (el \"~\" significa tu carpeta personal). Los ajustes específicos de proyecto están en una carpeta .ava/ dentro del proyecto mismo.","reference.config#2#h":"Global — ~/.ava/","reference.config#3#li0":"settings.json — preferencias del modelo, modo de permiso, personalidad, idioma.","reference.config#3#li1":"memory/ — tus memorias globales (preferencias, decisiones que valen para todo).","reference.config#3#li2":"tasks.json — lista de tareas entre proyectos.","reference.config#3#li3":"journal/ — entradas diarias del diario, organizadas por fecha.","reference.config#4#h":"Proyecto — .ava/","reference.config#5#li0":"instructions.md — instrucciones específicas del proyecto que Ava carga siempre. Contexto persistente (\"usamos pnpm, no npm\", \"las claves de API viven en 1Password\").","reference.config#5#li1":"context.md — notas opcionales libres del proyecto.","reference.config#5#li2":"memory/ — memorias limitadas a este proyecto.","reference.config#5#li3":"datasets/config.json — configuración de captura de conjuntos de datos (opcional).","reference.config#6#c":"Agrega .ava/ a tu .gitignore (una lista de archivos que Git debe ignorar en el proyecto compartido) si no quieres compartir memorias con tu equipo. Guarda instructions.md en el repositorio (la carpeta compartida del proyecto): así es como Ava aprende las normas del proyecto.","reference.shortcuts#title":"Atajos de teclado","reference.shortcuts#0#p":"Los atajos de teclado son aceleradores opcionales: cada uno también es un botón que puedes pulsar. Solo mira aquí si prefieres usar a Ava más rápido desde el teclado.","reference.shortcuts#1#p":"Atajos por entorno (cada uno de los tres lugares donde funciona Ava: la extensión de VS Code, la app de escritorio y la terminal). Personalízalos en la configuración de cada entorno. No hace falta memorizar la lista de abajo.","reference.project-context#title":"Contexto del proyecto","reference.project-context#0#p":"Esto explica cómo Ava se informa sobre tu proyecto antes de empezar — los archivos que revisa para entender en qué estás trabajando. No necesitas configurar nada de esto; ella lo hace por su cuenta. Léelo si quieres saber dónde poner una nota para que ella siempre la vea.","reference.project-context#1#p":"Cuando abres un proyecto, Ava carga varias capas de contexto (información de fondo que tiene presente). Entender estas capas te ayuda a colocar la información en el lugar correcto.","reference.project-context#2#h":"Carga automática","reference.project-context#3#li0":".ava/instructions.md — tratada como orientación duradera y de alta prioridad. Siempre en contexto.","reference.project-context#3#li1":".ava/context.md — notas libres. Cargadas, prioridad menor.","reference.project-context#3#li2":"README.md — escaneada en la primera ejecución para obtener un resumen del proyecto.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — los pequeños archivos que listan la configuración del proyecto; se leen para detectar el lenguaje, el marco de trabajo y el comando de prueba.","reference.project-context#3#li4":".gitignore — la lista de archivos para excluir del control de versiones; respetado por todas las herramientas de archivos (glob, grep, project_index).","reference.project-context#4#h":"Carga bajo demanda","reference.project-context#5#p":"\"Bajo demanda\" significa que Ava solo obtiene estos elementos cuando una tarea realmente los necesita, en lugar de al principio.","reference.project-context#6#li0":"Índice del proyecto — un mapa estructurado de tus archivos y las piezas nombradas dentro de ellos (funciones, clases — \"símbolos\") y cómo se conectan (\"importaciones\"). Se construye bajo demanda, es decir, solo cuando Ava lo necesita.","reference.project-context#6#li1":"Historial de Git — el registro de cambios anteriores; se consulta cuando se ejecutan git_status, git_diff o git_create_pr (Git es la herramienta que registra cada cambio en un proyecto; \"PR\" es una petición de cambios, un conjunto propuesto de modificaciones).","reference.project-context#6#li2":"Memoria — las entradas se emparejan por significado (\"semánticamente\") e inyectan una vez a la vez, no todas juntas.","reference.project-context#7#c":"Pon las convenciones en instructions.md. Pon las notas en context.md. Deja que la memoria capture el resto por sí sola.","start.for-non-coders#6#li3":"Cuando quieras que ella realmente haga o cambie algo, solo pídeselo — siempre te mostrará qué está a punto de hacer y esperará tu \"sí\".","start.for-non-coders#7#c":"¿Te encuentras con una palabra que no conoces? El glosario en lenguaje sencillo (más abajo en esta sección) explica cada término sin conocimientos previos.","start.install#title":"Instalar","start.install#0#p":"Elige la interfaz que se adapte a cómo trabajas. Puedes usar más de una — Ava sincroniza su memoria entre ellas cuando inicias sesión.","start.install#1#h":"Extensión de VS Code","start.install#2#li0":"Abre el panel de Extensiones en VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Busca \"Ava Supernova\" y haz clic en Instalar.","start.install#2#li2":"Presiona Ctrl+Shift+A (Cmd+Shift+A en macOS) para abrir el panel de chat.","start.install#2#li3":"Sigue el asistente de configuración — elige un modelo, define tu modo de permisos, listo.","start.install#3#h":"IDE de escritorio","start.install#4#li0":"Descarga el instalador para tu plataforma desde la página de versiones.","start.install#4#li1":"Ejecútalo. El IDE se abre con un flujo de bienvenida la primera vez.","start.install#4#li2":"Inicia sesión para obtener los tokens gratuitos de la plataforma, o pega tu propia clave API para ejecutarlo totalmente local.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (o pnpm / yarn — tú eliges).","start.install#6#li1":"Ejecuta  ava  en cualquier directorio de proyecto.","start.install#6#li2":"La primera ejecución te pedirá un proveedor y un modelo. Elige y sigue adelante.","start.install#7#c":"Sin cuenta, sin problema. Con tu propia clave API (BYOK) nunca necesitas iniciar sesión. La capa gratuita es para los modelos gestionados por la plataforma.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"¿Necesitas un informe, un correo electrónico o un documento escrito? Ava puede redactarlo y entregarte un archivo real de Word, Excel o PDF que puedes abrir y editar como cualquier otro.","features.office-suite#1#p":"Informes, correos electrónicos y documentos: redactados, formateados y exportados a formatos nativos (.docx es Word, .xlsx es Excel, .pdf es un PDF).","features.office-suite#2#li0":"report_generate: un .docx estructurado que extrae datos de tareas, diario, memoria y estado del proyecto.","features.office-suite#2#li1":"email_draft: correo electrónico controlado por tono a un archivo .docx.","features.office-suite#2#li2":"document_manage: crear, leer, editar, exportar entre Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Útil cuando Ava escribe en tu nombre: informes de estado, presentaciones de inicio, actualizaciones para clientes. El .docx llega a tu proyecto donde puedes pulirlo.","features.dashboard-library#title":"Biblioteca del panel de control","features.dashboard-library#0#p":"En términos sencillos: un estante que guarda todo lo que tú y Ava han creado y hablado, para que nada se pierda.","features.dashboard-library#1#p":"Una vista navegable de todo lo que Ava ha producido contigo: imágenes generadas, videos, audio, documentos: junto con tus conversaciones, memorias y tareas. Un lugar para encontrar algo que hiciste la semana pasada.","features.document-preview#title":"Vista previa de documento","features.document-preview#0#p":"En términos sencillos: echa un vistazo dentro de un documento justo donde estás, sin abrir un programa separado para leerlo.","features.document-preview#1#p":"Haz clic derecho en un archivo Word, hoja de Excel, PDF, CSV, HTML o Markdown en tu proyecto: prévisualízalo en línea sin salir del editor. Útil para leer material de referencia que Ava ha generado o archivos que un colaborador dejó en el proyecto.","features.daily-briefing#title":"Breve resumen diario","features.daily-briefing#0#p":"En términos sencillos: una nota corta cada mañana de \"aquí es donde te quedaste\", para que puedas retomar sin volver a leer todo.","features.daily-briefing#1#p":"Resumen matutino: diario de ayer, tareas abiertas, estado del proyecto y cualquier recordatorio que Ava haya establecido. Opcional: actívalo en la configuración.","features.daily-briefing#2#p":"El breve resumen usa la memoria para mostrar contexto relevante (\"la última vez que trabajaste en el flujo de autenticación, notaste que querías revisar la estrategia de token de actualización\"). No es un feed de noticias: es un repaso enfocado.","features.unified-panel#title":"Panel unificado","features.unified-panel#0#p":"En términos sencillos: todo lo que hace Ava vive en una sola ventana, así que nunca tienes que buscar entre pestañas para encontrarlo.","features.unified-panel#1#p":"Un panel para chat, tablero, memoria, tareas y diario. Sin cambiar de contexto entre ventanas. La barra lateral selecciona lo que estás viendo; el área principal cambia para coincidir.","features.unified-panel#2#p":"El estado de la conversación persiste cuando navegas fuera — abres memoria, revisas una tarea, luego vuelves. El chat sigue ahí, activo si Ava sigue corriendo.","features.unified-panel#3#c":"El panel unificado es un concepto de extensión e IDE. La interfaz web usa pestañas del navegador.","features.knowledge-packs#title":"Paquetes de conocimiento","features.knowledge-packs#0#p":"En términos sencillos: entrega a Ava una carpeta con tus propios documentos y ella puede leerlos para responder tus preguntas. Un \"paquete de conocimiento\" es simplemente ese conjunto de archivos: tu material de referencia del cual ella tiene permiso para consultar.","features.knowledge-packs#1#p":"Arrastra un directorio de material de referencia (especificaciones, RFCs, notas de reuniones, documentación de API) a un paquete de conocimiento. Ava puede extraer las partes relevantes al contexto cuando una conversación toca el tema.","features.knowledge-packs#2#p":"Los paquetes se indexan localmente. La recuperación es semántica: Ava encuentra el documento correcto por significado, no por nombre de archivo. (\"Semántico\" significa que coincide sobre de qué trata un documento, así que no necesitas recordar las palabras exactas ni el nombre del archivo.) Los paquetes pueden compartirse con un equipo o mantenerse privados.","features.workflows#title":"Flujos de trabajo","features.workflows#0#p":"En términos sencillos: enséñale a Ava una rutina que repites una y otra vez, ponle un nombre y ella podrá ejecutar todo eso cuando lo pidas. Un \"flujo\" es simplemente esa rutina guardada: un conjunto de pasos que Ava repite por ti.","features.workflows#1#p":"Guarda una secuencia de pasos que sueles repetir: revisar PR → ejecutar pruebas → escribir notas de lanzamiento → redactar el correo. Un flujo es un plan reutilizable que Ava puede reproducir con diferentes entradas.","features.workflows#2#p":"Los flujos se guardan por proyecto en una carpeta llamada `.ava/workflows/` dentro de tu proyecto. Compártelos con tu equipo haciendo commit del directorio (guardándolo en tu proyecto compartido para que tus compañeros también lo reciban).","features.events#title":"Eventos y notificaciones","features.events#0#p":"En términos sencillos: mientras Ava trabaja recibes una lista ordenada paso a paso de lo que está haciendo, y una notificación cuando termina un trabajo largo para que puedas alejarte.","features.events#1#p":"Mientras Ava se ejecuta ves actualizaciones estructuradas, no un muro de texto. Cada llamada a herramienta, cada entrega entre personalidades, cada delta transmitido es un evento discreto en la interfaz: expándelo para detalles, contraerlo para una visión general.","features.events#2#p":"Las ejecuciones en segundo plano emiten notificaciones a nivel del sistema operativo cuando terminan. Puedes alejarte de una compilación larga y Ava te avisará cuando esté lista.","features.personality#title":"Diseñador de personalidad","features.personality#0#p":"En términos sencillos: ajusta cómo habla Ava contigo: charlatana o breve, formal o casual, más bromas o menos, para que suene como te gusta.","features.personality#1#p":"Define cómo habla Ava contigo. Tono, energía, verbosidad (cuánto dice), formalidad, humor. Deslizadores y ajustes predefinidos: ingeniero conciso, mentor cálido, colega seco, o tu propia mezcla.","features.personality#2#p":"La personalidad afecta la forma de hablar, no la competencia. Ella sigue usando las mismas herramientas y siguiendo las mismas reglas de permisos. Su nombre está fijo como Ava: esto es innegociable.","features.release-notes#title":"Notas de lanzamiento","features.release-notes#0#p":"En términos sencillos: una lista continua de lo nuevo y lo arreglado en cada actualización, para que veas qué cambió.","features.release-notes#1#p":"Registro de cambios en la aplicación (un changelog es el historial de cambios). Cada versión lanzada con sus puntos destacados, correcciones de errores y cambios disruptivos (cambios que pueden requerir que ajustes cómo usas algo). La versión pública se mantiene en la web en ava-supernova.com/releases.","troubleshooting.logs#4#c":"Los registros pueden contener fragmentos de los archivos del proyecto que leyó Ava durante una sesión. Revísalos antes de compartirlos.","troubleshooting.support-request#title":"Enviar una solicitud de soporte","troubleshooting.support-request#0#p":"En términos sencillos: si algo falla y las soluciones anteriores no ayudaron, envíanos un mensaje al respecto. La forma más fácil es simplemente pedirle a Ava que lo haga por ti.","troubleshooting.support-request#1#p":"Si un problema no está cubierto por errores comunes, abre un ticket de soporte (envía un pedido de ayuda al equipo de soporte). Puedes hacerlo dentro de Ava (sin formularios que rellenar) o en la web.","troubleshooting.support-request#2#h":"Desde dentro de Ava","troubleshooting.support-request#3#p":"Pídele que lo gestione. \"Ava, ¿puedes gestionar un ticket de soporte sobre esto?\" Ella invoca `support_request`, adjunta el contexto relevante de la sesión (con credenciales ocultas) y lo envía. El camino más rápido.","troubleshooting.support-request#4#h":"Desde la web","troubleshooting.support-request#5#p":"Visita ava-supernova.com/support. Elige una categoría (error, función, cuenta, seguridad, general) y describe qué sucedió. Respuesta en un día hábil.","troubleshooting.support-request#6#h":"Qué incluir","troubleshooting.support-request#7#li0":"Lo que intentabas hacer.","troubleshooting.support-request#7#li1":"Lo que realmente sucedió.","troubleshooting.support-request#7#li2":"Qué plataforma (extensión, IDE, CLI, complementaria) y qué versión.","troubleshooting.support-request#7#li3":"Cualquier mensaje de error o fragmento de registro. Oculta las credenciales primero.","troubleshooting.security-disclosure#title":"Reportar problemas de seguridad","troubleshooting.security-disclosure#0#p":"En términos sencillos: si detectaste una forma en que Ava podría ser vulnerada o mal utilizada (una \"vulnerabilidad\" — una debilidad de seguridad), por favor cuéntanoslo primero de forma privada para que podamos solucionarlo antes de que alguien pueda aprovecharse. Esta página explica cómo.","troubleshooting.security-disclosure#1#p":"¿Encontraste una vulnerabilidad? Gracias. Tomamos cada reporte en serio y trabajamos contigo en la solución antes de cualquier divulgación pública (antes de que se anuncie el problema públicamente).","troubleshooting.security-disclosure#2#h":"Cómo reportar","troubleshooting.security-disclosure#3#li0":"Envía un correo a security@ava-supernova.com con una descripción, pasos para reproducirlo y tu ventana de divulgación preferida.","troubleshooting.security-disclosure#3#li1":"O abre un ticket de soporte con categoría \"seguridad\" — misma cola de clasificación.","troubleshooting.security-disclosure#3#li2":"Te confirmamos recepción en menos de 24 horas.","troubleshooting.security-disclosure#4#h":"Nuestros compromisos","troubleshooting.security-disclosure#5#li0":"Divulgación coordinada — acordamos un cronograma contigo antes de que nada sea público. Por defecto son 90 días.","troubleshooting.security-disclosure#5#li1":"Reconocimiento — recibirás crédito en las notas de la corrección a menos que prefieras anonimato.","troubleshooting.security-disclosure#5#li2":"Sin represalias legales — la investigación de buena fe es bienvenida. No enviaremos abogados tras ti.","troubleshooting.security-disclosure#6#c":"La página de seguridad en ava-supernova.com/security tiene la postura completa — garantías de arquitectura, herramienta de ofuscación, filtros de permisos.","troubleshooting.common-errors#title":"Errores comunes","troubleshooting.common-errors#0#p":"La mayoría de los errores tienen una causa corta y específica. Aquí tienes los más frecuentes y cómo solucionarlos. No te preocupes si el lenguaje suena técnico — cada uno de abajo te dice exactamente qué estás viendo y qué hacer.","troubleshooting.common-errors#1#h":"El modelo no responde","troubleshooting.common-errors#2#p":"Lo que ves: Ava se queda en silencio y no responde.","troubleshooting.common-errors#3#p":"Revisa el indicador de estado en el encabezado del chat. Si dice \"conectando\", tu proveedor (el servicio de IA con el que habla Ava) es accesible pero lento — dale treinta segundos. Si dice \"no disponible\", Ava hizo un cambio automático al siguiente modelo en la cadena (cambió automáticamente a un modelo de respaldo). Si no hay nada, verifica tu clave API en Configuración y prueba la conexión. (Una clave API es la contraseña privada que permite a Ava usar un servicio de IA de pago.)","troubleshooting.common-errors#4#h":"Llamada de herramienta fallida","troubleshooting.common-errors#5#p":"Lo que ves: uno de los pasos de Ava (una \"llamada de herramienta\" — leer un archivo, ejecutar un comando, etc.) muestra un error rojo en lugar de terminar.","troubleshooting.common-errors#6#p":"Haz clic en la llamada de herramienta fallida para ver el error. Causas comunes: intentó tocar un archivo fuera de tu carpeta de proyecto, lo cual está bloqueado por seguridad (esta protección se llama \"traversía de rutas\" — evita que se salga de la carpeta donde trabajas); un comando que necesita ejecutarse en otra carpeta; o un archivo que se movió desde que Ava lo vio por última vez. Dile qué salió mal — ella reintentará con correcciones.","troubleshooting.common-errors#7#h":"La memoria no recuerda","troubleshooting.common-errors#8#p":"Lo que ves: Ava no encuentra algo que estás seguro de que debería recordar.","troubleshooting.common-errors#9#p":"La memoria funciona por significado, no por palabras exactas (esto es lo que significa \"semántico\"). Así que \"¿Qué decidí sobre autenticación?\" funciona mejor que \"encuentra mi decisión sobre autenticación\". Si la memoria definitivamente está ahí pero no aparece, abre el navegador de memoria y busca — si no está allí, nunca se guardó en primer lugar.","troubleshooting.common-errors#10#h":"Bucles de inicio de sesión","troubleshooting.common-errors#11#p":"Lo que ves: inicias sesión, pero Ava sigue pidiéndote que inicies sesión de nuevo — un bucle que nunca te deja pasar.","troubleshooting.common-errors#12#p":"La solución es borrar los detalles de inicio de sesión guardados y empezar de cero: en la extensión ejecuta \"Ava: Sign Out\" desde el panel de comandos, en el IDE usa Configuración → Cuenta → Cerrar sesión, en la CLI borra el archivo en ~/.ava/auth.json (un pequeño archivo de inicio de sesión en una carpeta llamada .ava en tu carpeta personal (home)). Luego inicia sesión de nuevo.","troubleshooting.common-errors#13#h":"Tokens agotados","troubleshooting.common-errors#14#p":"Lo que ves: un mensaje de que te has quedado sin uso gratuito del mes. (Los \"tokens\" son cómo se mide el uso de IA — \"agotados\" simplemente significa que has usado tu límite gratuito de este mes.)","troubleshooting.common-errors#15#p":"El presupuesto mensual de nivel gratuito se restablece el día 1 de cada mes. Hasta entonces, cambia a un proveedor BYOK (usa tu propia clave API) para seguir trabajando. Tu cuenta permanece activa — solo las solicitudes gestionadas gratuitamente por la plataforma están pausadas.","troubleshooting.logs#title":"Dónde están los registros","troubleshooting.logs#0#p":"Un \"registro\" es simplemente un diario que mantiene tu computadora sobre lo que sucedió — útil cuando algo falla y tú (o soporte) necesitas ver los detalles.","troubleshooting.logs#1#p":"Cuando necesitas ver el panorama completo — qué herramienta se llamó, qué información obtuvo, qué devolvió el servicio de IA — los registros son archivos de texto plano en una carpeta en tu computadora en ~/.ava/logs/ (una carpeta llamada .ava en tu carpeta personal (home), con una carpeta logs dentro).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — transcripciones por sesión incluyendo llamadas de herramientas, respuestas transmitidas y errores.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — registro del host de la extensión de VS Code. Fallos de activación, errores del panel.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — registro del IDE de escritorio. Mensajes del proceso Sidecar, fallos de Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — registro del REPL de CLI.","troubleshooting.logs#3#p":"En la extensión, \"Ava: Show Logs\" en el panel de comandos abre el registro relevante en una pestaña de editor. En el IDE, Configuración → Diagnósticos tiene un botón \"Abrir Registros\". La CLI puede seguir su propio registro con ava logs --follow.","start.what#title":"¿Qué es Ava?","start.what#0#p":"Ava es una IA que realmente hace cosas, no solo habla. Te crea una app, escribe un documento, te enseña algo desde cero, diseña un logo o se encarga de las tareas administrativas que siempre pospones. Y ella te recuerda: en qué estás trabajando, cómo te gustan las cosas, qué pediste la semana pasada.","start.what#1#p":"Hay una sola Ava, y trabaja donde tú trabajas: en tu editor de código, como aplicación de escritorio, en tu teléfono o en una terminal. Misma memoria, misma personalidad, en todas partes.","start.what#2#h":"Qué la hace diferente","start.what#3#li0":"Tuya por defecto. Tu trabajo se queda en tu propia máquina. Sin rastreo, sin telemetría — nunca.","start.what#3#li1":"Abierta para que cualquiera la vea. Cada línea de Ava es pública. Nada que aceptar ciegamente.","start.what#3#li2":"Gratis para empezar. 300 créditos cada mes, sin tarjeta, sin truco — o conecta tus propias claves de IA y no nos pagas nada.","start.what#3#li3":"Enseñar es gratis, para siempre. Aprender no debería tener precio.","start.what#4#p":"¿Nunca has escrito código? La siguiente página está escrita especialmente para ti. ¿Ya eres técnico? Salta adelante — ella te seguirá el ritmo.","start.what#deeper#0#h":"Dónde vive Ava","start.what#deeper#1#li0":"Extensión de VS Code — Ava junto a tu editor: un panel de chat, un tablero y cambios mostrados en línea antes de que ocurran.","start.what#deeper#1#li1":"IDE de escritorio — una aplicación independiente con todo en una ventana. Añade control de escritorio (abrir apps, hacer clic, escribir por ti).","start.what#deeper#1#li2":"Compañero — una aplicación móvil cuando estás lejos de tu escritorio: tareas, diario, memoria, chats rápidos.","start.what#deeper#1#li3":"CLI — Ava en tu terminal, para quienes viven allí.","start.what#deeper#2#h":"Cómo funciona, en resumen","start.what#deeper#3#p":"Ava cambia de mentalidad (llamadas modos) para adaptarse al trabajo, ejecuta silenciosamente un pequeño equipo de ayudantes especialistas en trabajos difíciles y elige el mejor modelo de IA para cada paso automáticamente. Tú nunca gestionas nada. La sección de conceptos principales tiene el recorrido completo si tienes curiosidad.","start.first-five#title":"Tu primer paso con Ava","start.first-five#0#p":"La forma más rápida de usar Ava es pedirle algo real y verla hacerlo. Sin configuraciones que leer, nada que aprender primero — solo dile lo que quieres, en palabras sencillas.","start.first-five#1#h":"Prueba esto ahora","start.first-five#2#li0":"Abre el chat.","start.first-five#2#li1":"Escribe algo que realmente quieras. Prueba \"explica qué hace este proyecto\", o \"añade un botón que limpie el formulario\".","start.first-five#2#li2":"Ava te muestra lo que está a punto de hacer — y espera.","start.first-five#2#li3":"¿Estás satisfecho? Di que sí. Mira cómo lo hace.","start.first-five#3#p":"Ese es todo el ritmo: tú preguntas, ella te muestra el plan, apruebas, ella lo hace. Nunca cambia nada sin mostrártelo primero — así que no puedes romper nada intentándolo.","start.first-five#4#h":"Algunas cosas que vale la pena pedir","start.first-model#deeper#0#h":"¿Qué hay realmente en cada estilo?","start.first-model#deeper#1#p":"Maestro — un solo director (Qwen 3.6 Plus) maneja cada paso. Optimizado para producción, comprobado y con costos predecibles.","start.first-model#deeper#2#p":"Supernova — un coordinador de vanguardia (DeepSeek V4 Pro, 1.6T parámetros / 49B activos, contexto de 1M) asigna cada subtarea a un especialista: V4 Flash para compilaciones de alto volumen, Qwen 3.6 Plus como respaldo, Qwen Omni para visión.","start.first-model#deeper#3#p":"Aurora — solo Mistral, en tres niveles: Mistral Large 3 (coordinador + especialistas pesados), Mistral Medium 3.5 (128B denso, contexto de 256K, visión nativa, pesos abiertos MIT modificado, 77.6% SWE-Bench Verificado) para Constructor + nivel medio + visión + texto largo, y Mistral Small 4 en el filtro de intención. Pesos abiertos de extremo a extremo, nunca sale de la infraestructura de la UE.","start.first-model#deeper#4#h":"Trae tu propio modelo (BYOK)","start.first-model#deeper#5#p":"¿Prefieres usar tu propia cuenta de IA? Pega tu clave del proveedor en la configuración y obtienes ambas cosas: los tres estilos de enrutamiento, más la opción de elegir un solo modelo y saltarte el enrutamiento por completo. Útil si tienes una preferencia fuerte, un presupuesto estricto o estás probando un modelo específico. La lista completa de proveedores está en la sección de Referencia.","start.glossary#title":"Glosario en lenguaje sencillo","start.glossary#0#p":"Cada palabra que podrías encontrar sobre Ava, explicada sin conocimientos previos asumidos. No necesitas memorizar nada de esto: vuelve aquí siempre que un término te confunda.","start.glossary#1#th0":"Palabra","start.glossary#1#th1":"Lo que realmente significa","start.glossary#1#td0.0":"Agente","start.glossary#1#td0.1":"Una IA que puede tomar acciones por ti: leer un archivo, ejecutar un comando, buscar en la web, no solo chatear. Ava es un agente: hace cosas, con tu aprobación.","start.glossary#1#td1.0":"Modelo","start.glossary#1#td1.1":"El cerebro real de la IA que piensa (Qwen, DeepSeek, Mistral y otros). Diferentes modelos tienen diferentes fortalezas. Normalmente nunca eliges uno: lo hace Ava.","start.glossary#1#td2.0":"Modo","start.glossary#1#td2.1":"La mentalidad en la que está Ava. Como un colega cambiando de sombrero: constructor, escritor, profesor, planificador, amigo. Tú eliges el modo; cambia cómo se comporta. Hay siete.","start.glossary#1#td3.0":"Persona / especialista","start.glossary#1#td3.1":"Roles de apoyo que ejecuta Ava tras bambalinas para trabajos difíciles: explorador, planificador, verificador de hechos. Piensa en un pequeño equipo de expertos. Nunca hablas directamente con ellos; Ava los coordina.","start.glossary#1#td4.0":"Enrutamiento","start.glossary#1#td4.1":"Ava decide qué modelo usar en cada paso para que obtengas buenas respuestas sin pagar de más. Ocurre automáticamente: el \"modo de enrutamiento\" solo elige la estrategia general.","start.glossary#1#td5.0":"Herramienta","start.glossary#1#td5.1":"Una acción específica que Ava puede realizar: leer un archivo, hacer una búsqueda, enviar un correo. Un \"llamado de herramienta\" es cuando usa una. Pide permiso antes de cualquier cosa riesgosa.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Cómo mide la IA el texto: aproximadamente ¾ de una palabra. Los modelos se cobran por millón de tokens. Algo que mayormente puedes ignorar.","start.glossary#1#td7.0":"Crédito","start.first-five#5#li0":"Una pregunta — «¿por qué mi página está en blanco?», «¿qué hace este archivo?»","start.first-five#5#li1":"Algo construido — «hazme una página de lista de tareas sencilla».","start.first-five#5#li2":"Para aprender algo — «enséñame Python desde cero». (Siempre gratis.)","start.first-five#5#li3":"Un documento — «escríbeme una propuesta de proyecto de una página». Te entregará un archivo Word o PDF.","start.first-five#6#c":"¿No sabes qué escribir? Háblale como a una amiga experta. Las palabras sencillas son exactamente lo correcto — nunca necesitas términos técnicos para empezar.","start.first-five#deeper#0#p":"Ese bucle sencillo está haciendo bastante cosas tras bambalinas. No necesitas nada de esto para usar Ava — pero aquí te explico qué está pasando realmente si tienes curiosidad.","start.first-five#deeper#1#h":"Herramientas y aprobación","start.first-five#deeper#2#p":"Cuando Ava lee un archivo, ejecuta un comando o edita código, cada uno de esos es una «llamada de herramienta». Ella pregunta antes de cualquier cosa que toque tus archivos o sistema — con qué frecuencia pregunta depende de tu modo de permiso (preguntar siempre, preguntar solo por cosas riesgosas, o simplemente ir).","start.first-five#deeper#3#h":"Modos — sus estados de ánimo","start.first-five#deeper#4#p":"Ava trabaja en modos: una mentalidad más la caja de herramientas adecuada para el trabajo. Cambia cuando quieras desde el selector, o escribe un prefijo al inicio de tu mensaje. Hay siete.","start.first-five#deeper#6#h":"Especialistas y enrutamiento","start.first-five#deeper#7#p":"En trabajos difíciles, Ava ejecuta un pequeño equipo de ayudantes especialistas tras bambalinas (un planificador, un verificador, un constructor) y enruta cada paso al modelo que mejor lo hace. Nunca gestionas nada de esto — ella lo coordina por ti.","start.local-vs-cloud#title":"Local vs nube, en un párrafo","start.local-vs-cloud#0#p":"Todo lo que hace Ava es local a menos que explícitamente aceptes. Memoria, tareas, diario, personalidad, configuración — todo almacenado en tu máquina en ~/.ava/ y .ava/ (por proyecto). Habla con proveedores de modelos sobre HTTPS para ejecutar tu solicitud, luego regresa a casa. No llama a casa. No recopila telemetría. No entrena con tu código.","start.local-vs-cloud#1#p":"Si inicias sesión, obtienes 300 créditos gratuitos al mes en modelos gestionados por la plataforma (Qwen, MiniMax) y sincronización en la nube opcional para memoria y configuración entre máquinas. La sincronización es por función, revocable en cualquier momento. Trae tu propia clave API y Ava funciona completamente sin cuenta.","start.local-vs-cloud#2#c":"La regla: lo local es sagrado. La nube es un complemento.","start.first-model#title":"¿Necesito elegir una IA?","start.first-model#0#p":"Aquí hay un alivio: no eliges la IA. Ava elige la correcta para cada paso automáticamente, así que obtienes buenos resultados sin tener que pensarlo.","start.first-model#1#p":"Lo único que puedes elegir es un estilo de enrutamiento — y el predeterminado sirve para casi todos. Solo necesitas los otros por una razón específica.","start.first-model#2#h":"Los tres estilos","start.first-model#3#li0":"Maestro — el predeterminado. Estable, confiable, predecible. ¿No estás seguro? Este es el indicado.","start.first-model#3#li1":"Supernova — para trabajo pesado y multietapa, donde vale la pena poner un especialista diferente en cada parte del trabajo.","start.first-model#3#li2":"Aurora — para cuando tus datos deben permanecer en la UE (sector público, salud, privacidad estricta). Se ejecuta totalmente en una IA europea de pesos abiertos.","start.first-model#4#p":"Cambia en cualquier momento desde el selector de modelos en la parte superior del chat. Nada está bloqueado.","start.first-model#5#c":"¿Quieres controlar tú mismo un modelo específico? Puedes — abre «Muéstrame los detalles».","models.routing#deeper#1#h":"Lado a lado","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Coordinador","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B activos, 1M de contexto)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B activos, 262K de contexto)","models.routing#deeper#2#td1.0":"Constructor","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (reutiliza al coordinador)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B denso, 256K de contexto)","models.routing#deeper#2#td2.0":"Especialistas de nivel medio","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (revisor de código, verificador de hechos, reconocimiento, escáner, verificador de seguridad, etc.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Arquitecto, Verificador, Secuenciador, Tutor, Reportero, etc.)","models.routing#deeper#2#td3.0":"Nivel ligero / filtro de intención","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Explorador, Verificador, Secuenciador, Retador, Integrador)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Especialistas de alto nivel","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Investigador, Retador, Investigador de CVE, Generador de ideas, Verificador de hechos)","start.glossary#1#td7.1":"La unidad más sencilla de Ava para calcular el costo de una acción, así no necesitas hacer cálculos con tokens. Los planes incluyen un paquete mensual.","start.glossary#1#td8.0":"Clave API","start.glossary#1#td8.1":"Una contraseña privada que permite al software usar un servicio de pago (como un modelo de IA) en tu cuenta. Solo necesitas una si prefieres usar la tuya propia.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Trae tu propia clave.\" Usar tu propia clave API en lugar del acceso gestionado por Ava. Opcional — para quienes ya pagan directamente a un proveedor.","start.glossary#1#td10.0":"Primero local","start.glossary#1#td10.1":"Tus datos viven en tu propio ordenador por defecto. Nada se sube a menos que actives la sincronización. \"Lo local es sagrado.\"","start.glossary#1#td11.0":"Modo de permisos","start.glossary#1#td11.1":"Qué tan cautelosa es Ava antes de actuar — preguntar cada vez, solo pedir permiso para cosas riesgosas, o simplemente proceder. Tú defines el nivel.","start.glossary#1#td12.0":"Ventana de contexto","start.glossary#1#td12.1":"Cuánto texto puede tener un modelo en mente a la vez — su memoria a corto plazo. \"Contexto de 1M\" significa unas un millón de palabras. Más grande = puede leer más antes de olvidar.","start.glossary#1#td13.0":"Diferencia","start.glossary#1#td13.1":"Una vista lado a lado de exactamente qué cambiará en un archivo — lo viejo a un lado, lo nuevo al otro — mostrado antes de que Ava cambie algo para que puedas aprobarlo.","start.glossary#1#td14.0":"Repositorio (repo)","start.glossary#1#td14.1":"Una carpeta de proyecto rastreada para cambios, usualmente con Git. Si eso aún no significa nada para ti, es simplemente \"la carpeta donde vive mi proyecto.\"","start.glossary#1#td15.0":"Solicitud","start.glossary#1#td15.1":"Lo que escribes a la IA — tu pregunta o instrucción.","start.glossary#2#c":"¿Sigues atascado con una palabra? Pregunta a Ava en modo Chat — \"¿qué significa X?\" — y ella te lo explicará según tu nivel.","models.routing#title":"Enrutamiento — cómo Ava elige los modelos","models.routing#0#p":"Aquí está la versión corta: nunca tienes que elegir qué modelo de IA usar. Ava lo hace por ti, eligiendo la mejor herramienta para cada parte de un trabajo — como cuando un buen jefe asigna la tarea correcta a la persona adecuada.","models.routing#1#p":"Eliges uno de tres estilos — Maestro, Supernova, o Aurora — y Ava envía cada pieza de trabajo al modelo que lo maneja mejor. Maestro es el predeterminado, está activo en todos los planes, y es una buena opción para casi todos.","models.routing#2#h":"¿Por qué molestarse con el enrutamiento?","models.routing#3#p":"Poner el modelo correcto en cada paso cuesta menos que ejecutar todo en un modelo grande y caro — y da mejores resultados, porque cada modelo hace lo que mejor sabe. Obtienes costos estables y alta calidad sin necesidad de saber cuál es cuál.","models.routing#4#c":"Los tres estilos funcionan con créditos de plataforma y con tus propias claves. Con tu propia clave también puedes omitir el enrutamiento y controlar un único modelo directamente. El desglose completo de la flota está debajo de \"Muéstrame los detalles\".","models.routing#deeper#0#c":"Las cifras \"B\" de abajo son miles de millones de parámetros — aproximadamente qué tan grande es el cerebro de un modelo; más grande suele significar más inteligente pero más lento y caro. Este es el detalle técnico; nunca lo necesitarás para usar Ava.","models.routing#deeper#2#td5.0":"Conversación","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Coordinación de generación de imágenes","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Visión","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (codificador de visión entrenado desde cero)","models.routing#deeper#2#td8.0":"Redacción de textos largos","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Ubicación de los datos","models.routing#deeper#2#td9.1":"Mixto (Nube Alibaba)","models.routing#deeper#2#td9.2":"Mixto (DeepSeek + Nube Alibaba)","models.routing#deeper#2#td9.3":"Solo UE · modelos de pesos abiertos","models.routing#deeper#2#td10.0":"Estado","models.routing#deeper#2#td10.1":"Disponible · todos los planes","models.routing#deeper#2#td10.2":"Próximamente","models.routing#deeper#2#td10.3":"Próximamente","models.routing#deeper#2#td11.0":"Ideal para","credits.overview#8#li4":"Orquestación — 10 créditos. Inicio completo del flujo de personas (Conductor + tarea con múltiples personas).","credits.overview#8#li5":"Generación de imágenes — 12 créditos. Hailuo image-01 mediante Creative Studio.","credits.overview#8#li6":"Generación de video — 150 créditos. Clip de 6 segundos en 1080p de Hailuo 02 Pro.","credits.overview#8#li7":"Generación de voz — 10 créditos. Síntesis de voz 2.8 HD.","credits.overview#8#li8":"Generación de música — 50 créditos. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Eliminación de fondo — 2 créditos.","credits.overview#9#h":"Multiplicadores por modelo","credits.overview#10#p":"Esto es para los curiosos — no lo necesitas para usar Ava. Un multiplicador simplemente escala el costo de créditos hacia arriba o abajo dependiendo de qué tan costoso sea el modelo detrás de una acción, así que los modelos más pesados cuestan un poco más. (\"Margen neto\" es la parte que se queda el proyecto después de cubrir sus gastos — buscamos mantenerlo bajo para que el valor regrese a ti.)","credits.overview#11#p":"Los modelos más pesados multiplican el costo de la acción para que los créditos sigan el gasto real en lugar de una tarifa fija. Calibrado para un margen neto de ~55%.","credits.overview#12#li0":"0.6× — Mistral Small 4 (el puesto de especialista de Aurora). Por debajo de 1× porque Mistral Small 4 es más económico que el ancla Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Tarifa base.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (coordinador de Aurora). Aproximadamente al nivel del ancla Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (coordinador Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (coordinador Supernova + especialistas pesados). Recalibrado desde 5.0× para restaurar la paridad de márgenes a la tarifa publicada de V4 Pro.","credits.overview#13#c":"Modelos de Anthropic (Claude Opus / Sonnet / Haiku) saltan la facturación de créditos por completo — son solo BYOK y pagas a Anthropic directamente. Lo mismo para cualquier otro proveedor BYOK cuando se usa con tu propia clave.","credits.overview#14#h":"BYOK y créditos","credits.overview#15#p":"BYOK (\"trae tu propia clave\" — proporcionas tu propia cuenta con un proveedor de IA y una clave, que es una contraseña privada que permite al software usar esa cuenta pagada) es para personas que ya pagan directamente a un proveedor de IA. Si ese no eres tú, puedes ignorar esta sección por completo.","credits.overview#16#p":"Las solicitudes de trae-tu-propia-clave omiten toda la infraestructura de la plataforma — la llamada va directa de Ava al proveedor, pagas al proveedor, no se consumen créditos. La única excepción es cuando una sesión BYOK genera una persona de nivel gestionado para una subtarea; la deducción de créditos aún aplica porque se está usando la capa de orquestación de Ava.","credits.overview#17#h":"Dónde verificar tu saldo","credits.overview#18#li0":"Extensión — Configuración → Cuenta, o la pastilla de créditos en el encabezado del chat.","credits.overview#18#li1":"IDE — El panel de cuenta muestra el saldo actual y la tasa de consumo.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard muestra saldo, historial y fecha de renovación.","credits.overview#19#c":"Local-first: Ava funciona sin cuenta en la tarjeta de Modelo Personalizado (Ollama, LM Studio, vLLM, o cualquier punto final compatible con OpenAI). Sin créditos, sin tokens de plataforma — tu modelo, tu máquina, tu factura de cero.","concepts.modes#title":"Modos — Estados de ánimo de Ava","models.routing#deeper#2#td11.1":"Trabajo diario, costo predecible","models.routing#deeper#2#td11.2":"Trabajo intensivo de múltiples pasos, coordinador de vanguardia en todos los planes","models.routing#deeper#2#td11.3":"Estricto con GDPR, sector público, infraestructuras soberanas de la UE","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Enrutamiento diferenciado por niveles de Qwen, huella ligera. Qwen 3.6 Plus se encarga del coordinador, Builder, planificación, seguridad, lluvia de ideas y trabajo de contexto largo — las áreas donde su atención lineal híbrida de 1M de contexto rinde frutos. Qwen 3.5 Flash maneja el chat, la orquestación de generación de imágenes y la puerta de intención aguas arriba, donde su precio de $0.07/$0.26 y su TTFT más rápido ganan en la mayor parte del volumen de tokens de baja profundidad. Qwen 3.5 Omni Plus se encarga de la entrada visual (Qwen 3.6 Plus no tiene visión nativa). Qwen 3.5 Plus lleva el trabajo de formato largo sensible al costo. Si el coordinador principal no está disponible, cae en la escalera de prioridades Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Conjunto políglota. DeepSeek V4 Pro coordina y envía cada subtarea a su especialista más adecuado: Qwen 3.6 Plus ejecuta cada inicio de Builder, V4 Flash maneja el chat además de las personas de revisión/auditoría de nivel medio, Qwen 3.5 Flash absorbe el trabajo de clasificación de nivel ligero, Qwen 3.5 Omni Plus se encarga de la entrada visual, Qwen 3.5 Omni Flash orquesta las llamadas de herramientas de generación de imágenes, Qwen 3.5 Plus lleva la persona de Escritor de Contenido sensible al costo de formato largo. Razonamiento de vanguardia donde importa, economía de nivel flash en la mayor parte del volumen de tokens.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Infraestructura de IA europea — soberana por diseño. Enrutamiento solo de Mistral en tres niveles: Mistral Large 3 (675B/41B-activo sparse MoE) maneja el rol de coordinador además de los especialistas pesados que necesitan profundidad — Investigador, Retador, Investigador CVE, Ideador, Verificador de Hechos, Verificador de Seguridad — y las tareas pesadas de contexto largo donde su eficiencia sparse-MoE gana. Mistral Medium 3.5 — el modelo insignia combinado lanzado en abril de 2026, 128B denso, contexto 256K, codificador visual entrenado desde cero, pesos abiertos MIT modificados, 77.6% SWE-Bench Verified — ejecuta el nivel de trabajo real: inicios de Builder, especialistas de nivel medio (Arquitecto, Verificador, Secuenciador, Tutor, Reportero), entrada visual y escritura de formato largo. Mistral Small 4 pasó de un solo rol en la puerta de intención a también manejar el chat y la orquestación de generación de imágenes — su precio de $0.15/$0.60 y razonamiento configurable valen la pena en las rutas de alto volumen y baja profundidad. Pesos abiertos de extremo a extremo, nunca sale de la infraestructura de la UE. Aurora deliberadamente no cambia silenciosamente el enrutamiento a un modelo no-Mistral cuando uno no está disponible; el enrutador muestra un error en su lugar — eso es lo que la hace \"Aurora\" en lugar de un Maestro con sabor a Mistral.","credits.overview#title":"Créditos Ava — cómo funciona la facturación","credits.overview#0#p":"Los créditos son simplemente cómo Ava cuenta lo que usas — como los minutos en un plan telefónico. Cada plan, incluido el gratuito, viene con una reserva de créditos, y cada cosa que hace Ava (responderte, crear una imagen) cuesta unos pocos de ellos. Esa es toda la idea. Los detalles de abajo son para cuando quieres saber exactamente qué cuesta qué.","credits.overview#1#p":"Ava factura en créditos, no en tokens crudos. (Un \"token\" es el pequeño fragmento de texto — aproximadamente unas pocas letras — que los modelos de IA leen y escriben; la mayoría de los servicios te cobran por token, lo cual es difícil de predecir.) Un crédito cubre una unidad de trabajo — un turno de chat, un inicio de persona (un ayudante haciendo una parte de la tarea), una generación de imagen. Desacoplar del medidor a nivel de token significa que no necesitas saber qué modelo se está ejecutando para saber cuánto costará una acción. El mismo turno de chat cuesta lo mismo ya sea que Maestro lo enrute a Qwen 3.6 Plus o Supernova lo enrute a V4 Pro.","credits.overview#2#h":"Planes","credits.overview#3#p":"Cada plan tiene acceso a todas las funciones — acceso a modelos, Creative Studio, los siete modos, la orquestación completa de personas. Los niveles superiores compran más créditos y un límite de tasa más alto, no funciones desbloqueadas.","credits.overview#4#li0":"Gratuito — $0/mes. 300 créditos. Límite de tasa de 20 solicitudes/minuto. No se requiere tarjeta.","credits.overview#4#li1":"Pro — $19/mes. 5,000 créditos. 60 solicitudes/minuto.","credits.overview#4#li2":"Ultra — $39/mes. 10,000 créditos. 120 solicitudes/minuto.","credits.overview#4#li3":"Empresarial — $79/mes. 20,000 créditos. 200 solicitudes/minuto.","credits.overview#5#c":"Los créditos no utilizados se transfieren mientras tu suscripción esté activa — no hay recuperación forzada. Las recargas se acumulan en la reserva de suscripción: 750 créditos por $3, 2,000 por $8, 4,000 por $15.","credits.overview#6#h":"Qué cuestan las cosas","credits.overview#7#p":"Tabla de costos por acción — qué se deduce de tu reserva de créditos cuando se ejecuta cada acción. (Un \"cache hit\" es cuando Ava reutiliza trabajo que ya hizo en lugar de rehacerlo; cuando eso sucede pagas menos — el cargo baja un 70%, o 50% en modelos pesados de salida como DeepSeek V4 Pro.)","credits.overview#8#li0":"Turno de chat — 2 créditos. Una sola ida y vuelta en cualquier modo.","credits.overview#8#li1":"Llamada ligera — 1 crédito. Puerta de intención, clasificación, lectura de disparo único.","credits.overview#8#li2":"Persona pesada — 3 créditos. Arquitecto, Investigador, Investigador CVE, Ideador (profundidad ≥ 4).","credits.overview#8#li3":"Persona ligera — 1 crédito. Explorador, Verificador, Secuenciador, Retador (profundidad ≤ 2).","concepts.modes#0#p":"Un modo es la mentalidad en la que está Ava — como un colega cambiando de sombrero. Misma persona, mismo recuerdo de ti, pero un constructor piensa diferente a un profesor. Eliges el modo y eso cambia cómo se comporta y qué ayudantes trae. Cambia cuando quieras con el selector de modos, o escribe un atajo de dos caracteres.","concepts.modes#2#h":"¿Cuál quieres?","concepts.modes#3#p":"Empieza por lo que intentas hacer — el modo sigue de eso:","concepts.modes#4#li0":"Quiero algo construido o cambiado → Código (>>). Tú lo describes, ella lo construye, mostrándote cada cambio primero. El equipo completo de ayudantes entra en acción para trabajos grandes.","concepts.modes#4#li1":"Quiero un plan antes de cualquier cambio → Plan (::). Ella lo piensa y te entrega un plan para aprobar o editar. No tocará tus archivos en este modo.","concepts.modes#4#li2":"Solo quiero hablar o preguntar → Chat (..). Una compañera de pensamiento con memoria, noticias y clima. Sin cambios de archivos, sin código — solo conversación.","concepts.modes#4#li3":"Quiero aprender algo → Enseñar (??). Un curso real hecho para ti: lecciones, cuestionarios, todo. Gratis en todos los planes, para siempre. Perfecto si eres nuevo.","concepts.modes#4#li4":"Quiero revisar mi proyecto buscando agujeros de seguridad → Seguridad (!!). Un equipo revisa la lista estándar de vulnerabilidades web comunes (las categorías \"OWASP\") y fallos reportados conocidos (llamados \"CVEs\"), luego te entrega un informe ordenado por gravedad. Este va dirigido a desarrolladores — sáltalo si no lo eres.","concepts.modes#4#li5":"Quiero ideas → Lluvia de ideas (**). Genera opciones basadas en tu situación real, busca huecos en las débiles y refina el resto en siguientes pasos.","concepts.modes#4#li6":"Quiero escribir un documento → Escribir (<<). Informes, propuestas, cartas, artículos — redacta en Markdown y exporta un documento Word con marca o PDF, refinando sección por sección. Sin código, solo escritura.","concepts.modes#5#c":"El \"equipo de asistentes\" (personas) corre completamente detrás de escena — nunca hablas con ellos directamente. Solo obtienes una respuesta más completa. No necesitas saber sus nombres.","concepts.modes#6#c":"Puedes cambiar de modo en medio de la conversación. Tu memoria se mantiene; los especialistas se reinician para adaptarse al nuevo modo.","concepts.tasks-journal#title":"Tareas y diario","concepts.tasks-journal#0#p":"Ava guarda tres tipos de notas para ti, y es fácil confundirlas. La forma rápida de recordar: la memoria es lo que sabe sobre ti, las tareas son lo que aún debes hacer, y el diario es un registro de cómo fueron las cosas. Aquí tienes cuándo usar cuál.","concepts.tasks-journal#1#li0":"Memoria — hechos persistentes. Preferencias, decisiones, patrones. Preguntado repetidamente, raramente creado manualmente.","concepts.tasks-journal#1#li1":"Tareas — cosas por hacer. Elementos de acción con fechas límite y estado. Los marcas como hechos cuando terminas.","concepts.tasks-journal#1#li2":"Diario — reflexión. Registro diario, entradas duales (tuyas y observaciones de Ava sobre la sesión). Útil para seguimiento del estado de ánimo, revisiones de sesión, contexto para mañana.","concepts.tasks-journal#2#p":"Ava escribe en los tres cuando tiene sentido. Puedes escribir en cualquiera directamente desde el panel. Nada está bloqueado en un solo lugar donde usas Ava — una tarea que creas en uno (digamos la herramienta de línea de comandos) aparece en todas partes (como la aplicación de escritorio), automáticamente.","concepts.permissions#title":"Permisos — tu dial de seguridad","concepts.permissions#0#p":"Los permisos son tu dial de seguridad. Deciden cuándo Ava pide tu aprobación antes de hacer algo en tu computadora, versus simplemente hacerlo. Puedes configurarla para pedir sobre todo, solo sobre lo riesgoso, o confiar en que ejecute — y puedes cambiarlo en cualquier momento. Si no estás seguro, déjalo en el predeterminado y estarás bien.","concepts.permissions#1#p":"Ava tiene 60 herramientas (\"herramientas\" son las acciones que puede tomar — leer un archivo, buscar en la web, etc.). Cada herramienta pertenece a una categoría (operaciones de archivo, shell, Git, web, multimedia, base de datos, sistema, documentos, memoria, aprendizaje). Cada llamada de herramienta pasa por el portón de permisos (un punto de control que decide si preguntarte primero) antes de ejecutarse. Controlas qué se aprueba automáticamente, qué pregunta una vez y qué siempre pregunta.","concepts.permissions#3#p":"Equilibrado es el predeterminado. Estricto cuando auditas su comportamiento (mirando de cerca para verificar cada paso). Autónomo cuando quieres que simplemente vaya.","concepts.permissions#4#c":"Autónomo no significa sin control. Los planes, preguntas de aclaración y solicitudes explícitas de usuario todavía pausan para tu entrada. Operaciones irreversibles (Git force-push, eliminaciones de base de datos) siempre confirman independientemente del modo.","concepts.interjection#title":"Guiar y detener a Ava","concepts.interjection#0#p":"Siempre estás al mando. Mientras Ava trabaja, puedes empujarla suavemente en una nueva dirección sin romper su ritmo, o detenerla en seco. Dos botones, dos resultados — eso es todo lo que trata esta página.","reference.cli#5#li3":"--project <path> — establece la raíz del proyecto explícitamente.","reference.desktop-budget#title":"Límites de presupuesto del escritorio","reference.desktop-budget#0#p":"Cuando Ava controla tu escritorio por ti — hacer clic, escribir, abrir aplicaciones — cada ejecución se llama \\\"trayectoria\\\". Esta página explica los límites de seguridad que evitan que una sola ejecución dure demasiado o cueste demasiado. La idea principal: ella siempre se detiene y verifica antes de excederse. Los números están aquí si quieres los detalles.","reference.desktop-budget#1#p":"Cada trayectoria corre bajo tres límites simultáneos (límites duros). El primero que se alcanza gana. La trayectoria nunca continúa en silencio tras una violación — el Narrador (el ayudante que te explica qué está pasando) pausa y pregunta qué hacer.","reference.desktop-budget#2#h":"Tres límites duros (por defecto)","reference.desktop-budget#3#li0":"Conteo de pasos — 30 pasos","reference.desktop-budget#3#li1":"Presupuesto de tokens — 500,000 tokens","reference.desktop-budget#3#li2":"Tiempo límite — 5 minutos","reference.desktop-budget#4#h":"Rangos de costo de tarea","reference.desktop-budget#5#li0":"Simple (buscar documentos, abrir una página) — 5–10 pasos, ~70–135K tokens, ~$0.04–0.08","reference.desktop-budget#5#li1":"Medio (iniciar sesión, revisar registros, descargar salida) — 15–25 pasos, ~205–340K tokens, ~$0.12–0.21","reference.desktop-budget#5#li2":"Complejo (clasificar tres problemas de GitHub) — 25–30 pasos, ~340–410K tokens, ~$0.21–0.25","reference.desktop-budget#6#p":"Las cifras de tokens anteriores son los límites técnicos por trayectoria, no tu asignación mensual — eso se cuenta en créditos, y los 300 del nivel gratuito cubren cómodamente una mezcla de chat, código y algunas automatizaciones.","reference.desktop-budget#7#c":"Puedes sobrescribir los límites por tarea al inicio, pero las violaciones siempre muestran un punto de decisión. El presupuesto nunca se gasta en silencio.","reference.desktop-whitelist#title":"Lista blanca de sesiones de escritorio","reference.desktop-whitelist#0#p":"Una \\\"lista blanca\\\" es simplemente la lista de aplicaciones y sitios web que has dicho que Ava puede tocar mientras controla tu escritorio. Esta página explica cómo le das ese permiso y por qué se reinicia cada vez. La versión corta: ella solo puede actuar donde tú lo permites, y pregunta antes de ir a cualquier lugar nuevo.","reference.desktop-whitelist#1#p":"Al inicio de una sesión de escritorio, Ava pregunta dónde tiene permiso para actuar. Un lenguaje sencillo funciona: \\\"Gmail, Cursor, el portal de Azure.\\\" Ella lee eso y confirma la coincidencia contigo (\\\"Gmail web, Cursor la aplicación, portal.azure.com\\\").","reference.desktop-whitelist#2#h":"Cómo lo aplica","reference.desktop-whitelist#3#p":"Acciones solo de lectura — tomar una captura de pantalla, leer la lista de botones y campos en pantalla (el \\\"árbol UIA\\\", el propio mapa de Windows de lo que hay en una ventana) — están permitidas en todas partes, porque necesitas ver qué hay en pantalla para decidir si agregar una aplicación a la lista blanca. Cualquier cosa que cambie algo se bloquea fuera de la lista; Ava pausa y pregunta si agregarla.","reference.desktop-whitelist#4#h":"Limitado a la sesión, deliberadamente","reference.desktop-whitelist#5#p":"La lista blanca NO persiste entre sesiones. No hay opción de \\\"recordar esta aplicación\\\". Cada nueva trayectoria comienza con un alcance nuevo. Incómodo por diseño: olvidar volver a autorizar es una característica, no un error.","reference.desktop-whitelist#6#h":"Adiciones durante la trayectoria","reference.desktop-whitelist#7#p":"Durante una trayectoria puedes agregar aplicaciones desde el encabezado: \\\"+ Permitir aplicación\\\" abre un pequeño campo de entrada. Toca Agregar y la nueva aplicación está activa para el resto de la sesión.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"¿Quieres crear una imagen, un video corto, una canción o una voz en off hablada? Solo descríbela y Ava la crea por ti — no se necesita software de diseño ni de audio.","concepts.interjection#1#p":"Ava trabaja hasta que su plan se completa o tú la detienes. Tienes dos formas de intervenir (la palabra para esto es \"intervenir\") mientras está en ejecución.","concepts.interjection#2#h":"Intercalar — guiar sin cancelar","concepts.interjection#3#p":"Escribe un nuevo mensaje mientras Ava está trabajando. Termina su llamada de herramienta actual, lee tu mensaje y ajusta su plan. No se pierde ningún contexto. Úsalo cuando quieras redirigir, agregar información o cambiar prioridades en medio de la ejecución.","concepts.interjection#4#h":"Detener forzoso — cancelar y limpiar","concepts.interjection#5#p":"Presiona Escape (CLI), haz clic en Detener (extensión, IDE) o escribe un comando de parada. La ejecución actual se cancela, las llamadas de herramientas pendientes se descartan y la conversación está lista para un nuevo turno.","concepts.interjection#6#c":"Intercala primero. El detener forzoso es para cuando algo está realmente mal. Intercalar mantiene el hilo activo.","concepts.desktop-personas#title":"Personas de escritorio","concepts.desktop-personas#0#p":"Esta página es para los curiosos y para usuarios avanzados. \"Automatización de escritorio\" (a veces llamada \"uso del ordenador\") significa que Ava puede hacer clic en tu pantalla y usar aplicaciones por ti — abrir Gmail, rellenar un formulario, enviar un mensaje — como una persona en el teclado. Para hacerlo con seguridad, divide el trabajo entre cinco ayudantes pequeños, cada uno con un rol estrecho. Nunca tratas con ellos directamente; esto solo te muestra quién hace qué.","concepts.desktop-personas#1#p":"Cada paso en una trayectoria de escritorio (una ejecución de Ava guiando tu pantalla hacia una meta) activa una oleada de cinco personas. Cada persona tiene un trabajo y solo uno. La separación mantiene las instrucciones claras, las salidas estructuradas y el razonamiento escéptico por diseño.","concepts.desktop-personas#2#h":"Explorador","concepts.desktop-personas#3#p":"Informa lo que es visible en pantalla en este momento. Nunca inventa elementos. Nunca planifica. Devuelve un JSON de ScreenState con IDs de elemento, nombres, bboxes, confianza y una fuente de anclaje (UIA, Playwright DOM, o visión OmniParser).","concepts.desktop-personas#4#h":"Planificador","concepts.desktop-personas#5#p":"Decide la única acción siguiente. Una acción por paso — nunca en lotes. Prefiere caminos reversibles. Clasifica el riesgo según la ontología de seguridad. Devuelve un JSON de ProposedAction con kind, target, params, riskClass, reasoning, y una predicción de expectedPostState.","concepts.desktop-personas#6#h":"Actor","concepts.desktop-personas#7#p":"Ejecuta exactamente lo que propuso el Planificador — después de que el filtro de aprobación se haya desbloqueado. Sin improvisación. Sin reintento. El fallo se reporta fielmente y el Verificador maneja el siguiente movimiento.","concepts.desktop-personas#8#h":"Verificador","concepts.desktop-personas#9#p":"Comprueba si la acción tuvo éxito. Compara el ScreenState fresco contra la predicción del Planificador. Devuelve verified, deviated, o rollback_needed. También detecta bucles — repetir una acción que ya tuvo éxito es una desviación, no una verificación.","concepts.desktop-personas#10#h":"Narrador","concepts.desktop-personas#11#p":"La única voz que el usuario escucha durante una trayectoria. Una frase en pasado por paso (\"Abrió Gmail.\", \"Hizo clic en Redactar.\"). También escribe el registro de auditoría estructurado. Dice cuándo algo salió mal — nunca oculta un problema.","concepts.desktop-safety#title":"Ontología de seguridad de escritorio","concepts.desktop-safety#0#p":"En resumen: antes de que Ava haga clic en algo en tu pantalla, clasifica la acción según su riesgo. ¿Leer la pantalla? Inofensivo. ¿Enviar dinero o borrar algo? Siempre se detiene y te pregunta primero — cada vez, sin excepciones. Las cinco etiquetas de abajo son solo los peldaños de esa escalera de riesgos. Esto es detalle para usuarios avanzados, pero la idea principal es simple: lo peligroso siempre necesita tu sí.","concepts.desktop-safety#1#p":"Cada acción propuesta se clasifica en una de cinco clases de riesgo. La clasificación combina tres señales — qué es el objetivo en pantalla, una descripción en lenguaje sencillo (\"etiqueta semántica\" — las propias palabras de Ava sobre lo que está mirando), y la configuración de la acción — y escala hacia arriba (lo trata como más riesgoso) cuando discrepan. Un falso positivo (preguntar cuando no era necesario) es solo una molestia. Un falso negativo (no preguntar cuando debería haberlo hecho) es un incidente que arruina el producto.","concepts.desktop-safety#2#h":"Las cinco clases","concepts.desktop-safety#3#li0":"Observacional — leer árbol UIA, captura de pantalla, pasar el cursor. Siempre permitido automáticamente.","concepts.desktop-safety#3#li1":"De navegación — desplazarse, mover el foco, abrir un menú. Permitido automáticamente en modo Drive.","features.creative-studio#1#p":"Generación de imágenes, video, música y voz — integrado en el mismo flujo de trabajo que tu código. Genera un ícono, una maqueta de producto, un video de demostración, una voz en off para un tutorial. Impulsado por MiniMax.","features.creative-studio#2#h":"Qué puedes crear","features.creative-studio#3#li0":"Imágenes — de prompt a PNG/JPG. Eliminación de fondo con una llamada.","features.creative-studio#3#li1":"Video — videos cortos de IA desde un prompt de texto (MiniMax Hailuo).","features.creative-studio#3#li2":"Música — pistas instrumentales o vocales con letras.","features.creative-studio#3#li3":"Voz — texto a voz con voces seleccionables.","features.creative-studio#4#p":"Los costos de Creative Studio salen del mismo grupo de créditos que todo lo demás — un solo grupo, un solo número. BYOK tu propia clave de MiniMax y es gratis para tu plan.","features.creative-studio#5#c":"Creative Studio es elegible para el plan gratuito. No es un complemento de pago.","features.desktop-automation#title":"Automatización de escritorio","features.desktop-automation#0#p":"En términos sencillos: Ava puede tomar el control de tu mouse y teclado para hacer tareas por ti — abrir una app, hacer clic en botones, llenar un formulario — mientras tú observas y apruebas cualquier cosa importante.","features.desktop-automation#1#p":"Un nuevo modo para Ava, prefijo @@. Ella observa el escritorio, decide qué hacer, y maneja la automatización de UI (controlando las apps en tu pantalla para ti) para lograrlo. Se ejecuta en tu máquina real con tus credenciales reales — no es un navegador en la nube. Disponible en todos los niveles una vez lanzado.","features.desktop-automation#2#h":"¿Por qué otra más?","features.desktop-automation#3#p":"Cada otro producto de automatización de escritorio es algo que inicias cuando estás en tu escritorio. Ava es la que sigue ahí cuando tu rastreador de errores se activa a las 2am — el IDE sigue corriendo, tu teléfono se empareja por un canal seguro, apruebas acciones irreversibles con un toque.","features.desktop-automation#4#p":"También recuerda cómo navegar por tus apps entre sesiones. Cada otro agente vuelve a aprenderlas cada vez. El diferenciador de memoria se acumula con el uso.","features.desktop-automation#5#h":"Cómo funciona","features.desktop-automation#6#p":"Cada paso ejecuta una oleada de cinco personalidades: Scout observa, Planner elige la siguiente acción, Actor ejecuta, Verifier verifica, Narrator te cuenta qué pasó. El sidecar elige el anclaje confiable más barato — UIA para apps nativas, Playwright para navegadores, visión OmniParser cuando nada más tiene un árbol útil.","features.desktop-automation#7#p":"Consulta las páginas de conceptos para ontología de seguridad, jerarquía de anclaje, interruptores de parada y el modelo de lista blanca de sesión.","concepts.desktop-safety#3#li2":"Mutativo-reversible — escribe en un campo, pega, abre una aplicación, navega por una URL. Se confirma en modo Ask; automático en Drive dentro de la lista blanca.","concepts.desktop-safety#3#li3":"Mutativo-irreversible — enviar, presentar, pagar, eliminar, confirmar, publicar. Siempre solicita confirmación, sin importar el nivel de permiso. La aprobación nunca se guarda en caché.","concepts.desktop-safety#3#li4":"Privilegiado — elevación de UAC, sudo, modificaciones del registro, solicitudes de credenciales. Prohibido por defecto. Requiere autorización de uso único por sesión.","concepts.desktop-safety#4#h":"Aprobaciones que nunca se guardan en caché","concepts.desktop-safety#5#p":"Todos los competidores guardan las aprobaciones en caché (recuerdan tu «sí» y lo vuelven a usar la próxima vez). Ese es el mayor punto de apoyo para la inyección de instrucciones: un ataque donde una página web trucada introduce instrucciones ocultas a la IA para que actúe en tu contra. Si las aprobaciones se guardan en caché, una página comprometida puede aprovecharse de un «sí» que diste antes. Ava nunca guarda en caché. Cada acción mutativa-irreversible solicita confirmación nueva.","concepts.desktop-safety#6#h":"Manejo de secretos","concepts.desktop-safety#7#p":"Contraseñas, claves de API y códigos de 2FA (los códigos únicos que te da una segunda aplicación o mensaje cuando inicias sesión) se gestionan mediante manejadores opacos — marcadores de posición que representan el valor real. Ava ve \"{secret}\", no la contraseña real. El valor real nunca entra en su memoria, su registro de actividad ni en lo que ella «lee»: una capa separada de bajo nivel lo escribe en el último momento, al pulsar la tecla, para que la parte de IA nunca lo toque.","reference.cli#title":"Comandos CLI","reference.cli#0#p":"Esta página es para la CLI — la versión de Ava con la que escribes en una ventana de terminal, en lugar de hacer clic en botones. Si usas la extensión o la aplicación de escritorio, puedes omitirla por completo. Está aquí para quienes prefieren el teclado.","reference.cli#1#p":"La CLI es un REPL — una consola que espera a que escribas, ejecuta lo que escribiste y luego vuelve a esperar. Estos comandos con barra (/) (instrucciones que empiezan con \"/\") funcionan desde la consola.","reference.cli#2#li0":"/help — lista los comandos y el modo actual.","reference.cli#2#li1":"/mode <nombre> — cambia el modo (trabajo, escribir, planificar, conversar, enseñar, seguridad, lluvia de ideas).","reference.cli#2#li2":"/model <id> — cambia el modelo sin salir de la sesión.","reference.cli#2#li3":"/clear — borra la conversación actual. La memoria permanece intacta.","reference.cli#2#li4":"/history — lista conversaciones pasadas en este proyecto.","reference.cli#2#li5":"/memory — abre el navegador de memoria.","reference.cli#2#li6":"/tasks — lista y gestiona tareas.","reference.cli#2#li7":"/journal — abre la entrada de diario de hoy.","reference.cli#2#li8":"/settings — abre el menú de configuración.","reference.cli#2#li9":"/exit — sale del REPL.","reference.cli#3#h":"Banderas de lanzamiento","reference.cli#4#p":"Las banderas son opciones adicionales que agregas al iniciar Ava, cada una comienza con \"--\", para definir cómo inicia.","reference.cli#5#li0":"--mode <nombre> — inicia en un modo específico.","reference.cli#5#li1":"--model <id> — inicia con un modelo específico.","reference.cli#5#li2":"--permission <modo> — estricto / equilibrado / autónomo."},"pt":{"start.for-non-coders#title":"Nunca escreveu código? Comece aqui","start.for-non-coders#0#p":"Se você nunca escreveu uma linha de código, você é exatamente quem o Ava foi feito para ajudar. Você não precisa aprender nenhum jargão para começar — você fala com ela em linguagem simples, como pediria a um amigo conhecedor. Esta página é todo o seu ponto de partida.","start.for-non-coders#1#h":"O que você pode fazer hoje, sem experiência","start.for-non-coders#2#li0":"Pergunte qualquer coisa, em palavras comuns — \"o que este arquivo faz?\", \"por que minha página está em branco?\", \"o que é mesmo um banco de dados?\" Ela responde em linguagem simples e lembra da conversa.","start.for-non-coders#2#li1":"Aprenda algo do zero — diga \"ensine-me Python do zero\" e ela cria um curso próprio com lições e testes. Isso é sempre grátis.","start.for-non-coders#2#li2":"Faça algo ser construído — descreva o que quer (\"um botão que baixa minhas notas\") e ela escreve, mostrando cada alteração antes que aconteça.","start.for-non-coders#3#h":"Você não precisa entender tudo","start.for-non-coders#4#p":"Ava tem muita mecânica por baixo do capô — modos, modelos, especialistas, roteamento. Você verá essas palavras pelo app e nesta documentação. Aqui está o segredo: você pode ignorar quase tudo. O Ava escolhe as ferramentas certas e os auxiliares certos para você automaticamente. As páginas técnicas estão lá quando você ficar curioso, não porque você precise delas para começar.","start.for-non-coders#5#h":"Um primeiro caminho suave","start.for-non-coders#6#li0":"Instale Ava (próxima página) e abra o chat.","start.for-non-coders#6#li1":"Digite uma pergunta real que você tenha. Qualquer uma. Veja como ela responde.","start.for-non-coders#6#li2":"Tente o modo de aprendizado: digite \"ensine-me\" e um tópico. Siga o passo a passo.","concepts.memory#title":"Memória — como a Ava se lembra de você","concepts.memory#0#p":"Em termos simples: a Ava se lembra de você. Conte algo uma vez — o que você gosta, uma decisão que tomou — e ela guarda, para você não ter que repetir na próxima conversa ou semana que vem. Essa é a ideia principal. As camadas abaixo explicam apenas como ela mantém essa memória organizada com o tempo.","concepts.memory#1#p":"A Ava tem uma memória persistente (\"persistente\" significa que ela fica guardada mesmo depois de fechar o app) que sobrevive entre conversas, projetos e máquinas se você ativar o sincronismo (o sincronismo copia sua memória entre seus dispositivos). Não é um registro de chat. É uma compreensão estruturada e pesquisável sobre quem você é, o que você gosta e o que decidiu.","concepts.memory#2#h":"Cinco camadas","concepts.memory#3#li0":"Extrair — fatos-chave capturados de cada mensagem em tempo real.","concepts.memory#3#li1":"Refletir — análise mais profunda roda ao final de sessões significativas. Padrões, temas, contradições.","concepts.memory#3#li2":"Acumular — correções e preferências se acumulam ao longo de semanas e meses.","concepts.memory#3#li3":"Analisar — o motor de grafos conecta memórias relacionadas e sinaliza contradições quando novas informações conflitam com as antigas.","concepts.memory#3#li4":"Consolidar — memórias similares se fundem; as antigas são podadas. A memória fica mais afiada com o tempo, não mais barulhenta.","concepts.memory#4#c":"As cinco camadas acima rodam sozinhas — você nunca precisa gerenciá-las. Elas estão aqui para você ver que a memória realmente melhora com o tempo em vez de virar uma pilha de bagunça.","concepts.memory#5#h":"Recordação","concepts.memory#6#p":"Quando você faz uma pergunta, a Ava busca na memória por significado (\"busca semântica\" — ela entende o que você quer dizer, então encontra a memória certa mesmo se você formular diferente), não apenas por palavras exatas. Filtros específicos do modo rodam junto — Modo Chat puxa contexto pessoal, Modo Trabalho puxa decisões de projeto e padrões de código.","concepts.memory#7#c":"A memória é limitada por usuário e por projeto (suas memórias são suas, mantidas separadas por pessoa e por projeto). Segredos e credenciais (senhas, chaves) são bloqueados na borda de salvamento — eles nunca podem chegar à memória.","reference.models#11#h":"Traga sua própria chave","reference.models#12#p":"Uma \"chave de API\" é uma senha privada que permite ao software usar um serviço pago na sua conta. \"BYOK\" significa apenas \"traga sua própria chave\" — usando a sua em vez da nossa. Cole sua chave de API nas configurações. Solicitações BYOK vão direto da Ava para o provedor (a empresa que roda o modelo) — elas não passam pela nossa infraestrutura e não consomem tokens da plataforma. Você paga ao provedor; nós não visualizamos o tráfego.","reference.models#14#c":"Para pontuações de benchmark, tags de capacidade e filtros lado a lado, veja a página completa de Modelos em ava-supernova.com/models. Os preços mostrados acima são nossa melhor leitura das tabelas de preços de cada provedor na publicação — sempre verifique o site do provedor antes de se comprometer com uma carga de trabalho.","reference.personas#title":"Orquestração de personas","reference.personas#0#p":"Uma \"persona\" é um papel de assistente que a Ava desempenha nos bastidores para tarefas mais difíceis — um explorador, um planejador, um verificador de fatos. Você nunca fala diretamente com elas e não precisa entender esta página para usar a Ava. Ela está aqui quando você tem curiosidade sobre como ela divide um grande trabalho em uma pequena equipe de especialistas.","reference.personas#1#p":"24 especialistas em 5 equipes de modo. O Maestro (o assistente que coordena os demais) decide qual equipe roda, em que ordem e com qual contexto. O modo Chat não tem personas — é a própria Ava.","reference.personas#2#h":"Como a orquestração funciona","reference.personas#3#li0":"Você envia uma mensagem no modo Planejar, Ensinar, Segurança ou Brainstorm (ou um pedido complexo de Trabalho).","reference.personas#3#li1":"O Maestro lê o pedido, escolhe a equipe de modo e cria um plano de execução — algumas personas rodam sequencialmente, outras em ondas paralelas.","reference.personas#3#li2":"Cada persona tem seu próprio prompt de sistema, uma lista permitida restrita de ferramentas e um conjunto de contexto compartilhado do que as personas anteriores encontraram.","reference.personas#3#li3":"A persona final produz um resumo, um plano ou um relatório, dependendo do modo.","reference.personas#3#li4":"A Ava apresenta o resultado para você. Você aprova, ajusta ou redireciona.","reference.personas#4#p":"A lista completa abaixo é apenas referência — não há necessidade de memorizar quem faz o quê. A Ava monta a equipe certa para você.","reference.personas#6#c":"O modo Trabalho invoca apenas a equipe completa para tarefas complexas. Edições simples rodam a Ava diretamente — sem sobrecarga de orquestração.","reference.config#title":"Configurações","reference.config#0#p":"Esta página mostra onde a Ava guarda suas configurações e arquivos no seu computador. Quase nunca é preciso mexer nisso manualmente — o aplicativo cuida disso por você. Está aqui caso você queira ver, fazer backup ou compartilhar esses arquivos pessoalmente.","reference.config#1#p":"A Ava lê as configurações (suas configurações salvas) de dois escopos. Configurações globais — aquelas que se aplicam em tudo — ficam numa pasta chamada ~/.ava/ (o \"~\" é abreviação da sua pasta pessoal). Configurações por projeto ficam numa pasta .ava/ dentro do próprio projeto.","reference.config#2#h":"Global — ~/.ava/","reference.config#3#li0":"settings.json — preferências de modelo, modo de permissão, personalidade, idioma.","reference.config#3#li1":"memory/ — suas memórias globais (preferências, decisões que se aplicam em tudo).","reference.config#3#li2":"tasks.json — lista de tarefas entre projetos.","reference.config#3#li3":"journal/ — entradas diárias do diário, organizadas por data.","reference.config#4#h":"Projeto — .ava/","reference.config#5#li0":"instructions.md — instruções específicas do projeto que a Ava sempre carrega. Contexto duradouro (\"usamos pnpm, não npm\", \"chaves de API ficam no 1Password\").","reference.config#5#li1":"context.md — anotações opcionais livres do projeto.","reference.config#5#li2":"memory/ — memórias limitadas a este projeto.","reference.config#5#li3":"datasets/config.json — configuração de captura de conjuntos de dados (adesão opcional).","reference.config#6#c":"Adicione .ava/ ao seu .gitignore (uma lista de arquivos que o Git é instruído a ignorar no projeto compartilhado) se não quiser compartilhar memórias com sua equipe. Mantenha instructions.md no repositório (a pasta do projeto compartilhada) — é assim que a Ava aprende as convenções do projeto.","reference.shortcuts#title":"Atalhos de teclado","reference.shortcuts#0#p":"Atalhos de teclado são aceleradores opcionais — todos eles também são botões que você pode clicar. Consulte esta seção apenas se quiser controlar a Ava mais rápido pelo teclado.","reference.shortcuts#1#p":"Atalhos por interface (cada um dos três lugares onde a Ava roda: a extensão do VS Code, o aplicativo de desktop e o terminal). Personalize-os nas configurações de cada interface. Não precisa decorar a lista abaixo.","concepts.desktop-grounding#title":"Hierarquia de fundamentação do Desktop (Prévia)","concepts.desktop-grounding#0#c":"Prévia — como o Scout decide qual fonte de fundamentação usar a cada passo.","concepts.desktop-grounding#1#p":"Antes de clicar em um botão, ela precisa realmente entender o que está na sua tela e onde as coisas estão — isso é \"fundamentação\" (descobrir o que cada item na tela é e sua posição exata). Ela tem três maneiras de fazer isso e escolhe a mais confiável que funciona para o app em que você está. Isso é um detalhe avançado para usuários experientes; o ponto é apenas que ela prefere métodos sólidos e precisos em vez de adivinhar a partir de uma imagem.","concepts.desktop-grounding#2#p":"Três níveis, avaliados em ordem. A fonte confiável de menor custo vence.","concepts.desktop-grounding#3#h":"1. Janela do navegador → Playwright DOM","concepts.desktop-grounding#4#p":"Se a janela ativa for um navegador web, a Ava lê a estrutura própria da página (o \"DOM\" — a lista subjacente do que há em uma página) em vez de adivinhar a partir da imagem. Ler a estrutura é cerca de 10× mais confiável do que olhar os pixels — ela sabe exatamente onde cada botão está e quando a página terminou de carregar. Este é o caminho principal para qualquer coisa na web, não um plano de backup.","concepts.desktop-grounding#5#h":"2. App nativo com UIA → Automação de Interface do Usuário do Windows","concepts.desktop-grounding#6#p":"Para aplicativos de desktop comuns no Windows, a Ava lê um mapa de acessibilidade integrado (\"UIA\", o mesmo dado que leitores de tela usam para descrever uma janela) — ele lista cada controle, seu nome e onde fica. Se esse mapa retornar pelo menos cinco itens utilizáveis e nomeados, ela confia nele e o usa.","concepts.desktop-grounding#7#h":"3. UIA vazio ou inútil → Visão OmniParser","concepts.desktop-grounding#8#p":"Quando esse mapa está ausente ou é inútil (alguns apps, jogos e telas remotas não fornecem um), a Ava recorre a olhar diretamente para uma captura de tela. Uma ferramenta de visão (OmniParser) identifica as regiões clicáveis e rotula o que cada uma é, transformando a imagem de volta em uma lista na qual ela pode agir — combinado com o pouco que o mapa de acessibilidade conseguiu dar.","concepts.desktop-grounding#9#c":"OmniParser é opt-in na primeira vez que a Ava precisa dele, com um aviso claro de privacidade. Usuários BYOK podem apontar para sua própria implantação local do OmniParser.","concepts.desktop-kill-switches#title":"Interruptores de emergência do Desktop (Prévia)","concepts.desktop-kill-switches#0#c":"Prévia — três maneiras independentes de abortar uma trajetória em execução. Qualquer uma delas vence.","concepts.desktop-kill-switches#1#p":"Um \"interruptor de emergência\" é exatamente o que parece — uma maneira de parar a Ava instantaneamente quando ela está controlando sua tela. A parte tranquilizadora: existem três deles, cada um construído separadamente, então se um falhar, outro ainda funciona. Você não precisa aprender todos os três. Apenas saiba que quando algo parecer errado, você sempre pode pará-lo, e a parada mais forte (o pânico abaixo) não depende da Ava cooperar.","concepts.desktop-kill-switches#2#p":"Depois de ler todos os incidentes públicos de autonomia (casos reais onde agentes de IA ignoraram comandos de parada, apagaram arquivos de e-mail, limparam unidades), criamos três interruptores de emergência em três camadas diferentes. Nenhum deles depende do próprio modelo de IA — se a Ava estiver travada ou sem resposta, você ainda pode pará-la.","concepts.desktop-kill-switches#3#h":"Pausar — espaço ou o botão Pausa","concepts.desktop-kill-switches#4#p":"Congela no próximo limite de etapa. Pode ser retomado. Use isso quando quiser intervir sem perder o rumo.","concepts.desktop-kill-switches#5#h":"Parar — Escape ou o botão Parar","concepts.desktop-kill-switches#6#p":"Aborto limpo. O narrador resume o que foi feito até agora. Não é retomável. Registra no log de auditoria.","concepts.desktop-kill-switches#7#h":"Parada de pânico — três vezes Escape ou Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"A parada mais drástica possível. Um pequeno programa de vigilância separado força o encerramento da parte do Ava que está controlando sua tela. Ele não espera a IA responder, não precisa da janela do aplicativo estar funcionando e não se importa com o estado das coisas — ele apenas mata. Este é o recurso para quando algo está realmente errado.","concepts.desktop-kill-switches#9#p":"Os três também funcionam pelo aplicativo complementar. Qualquer um dos drivers pode encerrar.","reference.tools#title":"Referência de ferramentas","reference.tools#0#p":"Esta é a lista completa de todas as ferramentas que o Ava tem — uma \"ferramenta\" sendo apenas uma ação específica que ela pode realizar, como ler um arquivo ou executar uma busca. Você não precisa ler esta página. O Ava escolhe a ferramenta certa por conta própria toda vez. Está aqui caso você tenha curiosidade sobre exatamente o que ela pode fazer.","reference.tools#1#p":"A caixa de ferramentas integrada completa. Cada ferramenta aqui está registrada no núcleo de execução (o motor por trás das três superfícies) e disponível para o Ava quando o modo e o modo de permissão permitirem. Filtre por categoria ou risco.","reference.tools#2#p":"Não precisa decorar nada disso — a tabela abaixo é apenas um cartão de referência.","reference.tools#4#h":"Níveis de risco","reference.tools#5#li0":"Seguro — lê coisas sem alterar nada. file_read, glob (encontra arquivos por padrão de nome), grep (busca texto dentro de arquivos), git_status (Git é o sistema que rastreia alterações no seu projeto).","reference.tools#5#li1":"Escrita — altera arquivos, salva um ponto de verificação do seu trabalho (um \"compromisso\"), ou produz algo novo. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Perigoso — executa comandos no seu computador (o \"shell\"), controla a área de trabalho, vai para a internet ou consulta bancos de dados. bash, browser, desktop_*.","reference.tools#6#c":"Especialistas de persona têm suas próprias listas de permissão de ferramentas. Scout pode ler mas não escrever. Builder tem acesso total. Challenger não tem nenhuma ferramenta — o trabalho dele é questionar o plano.","reference.models#title":"Modelos","reference.models#0#p":"Um \"modelo\" é o cérebro da IA fazendo o pensamento — Qwen, DeepSeek, Mistral e outros. Esta página lista todos os modelos que o Ava pode usar. O resumo: você não precisa escolher um. O Ava escolhe o modelo certo para cada etapa por conta própria. Leia apenas se quiser entender ou sobrescrever isso.","reference.models#1#p":"Todos os modelos aos quais o Ava pode rotear, além das três estratégias de orquestração — as regras que decidem qual modelo cuida de cada parte de uma tarefa. Escolha um modo de roteamento e deixe o Ava encaminhar, ou escolha um único modelo e pule o roteamento inteiramente.","reference.models#2#h":"Modos de roteamento","reference.models#3#p":"Três estratégias orquestradas. O mesmo pipeline de persona (a pequena equipe de especialistas auxiliares que o Ava executa nos bastidores) roda em todos os três; o que muda é a frota subjacente de modelos. Escolha um modo no seletor de modelos e o Ava cuida do resto. Cada cartão abaixo mostra os especialistas constituintes aos quais o regente roteia.","reference.models#4#p":"Não precisa decorar os cartões abaixo — eles estão aqui para você ver do que cada estratégia é feita.","reference.models#6#c":"Aurora é deliberadamente apenas Mistral. Se um modelo Mistral não estiver disponível, o roteador retorna um erro em vez de rotear cruzado — essa é a garantia da pilha da UE. Escolha Maestro ou Supernova para degradação suave.","reference.models#7#c":"Os três modos estão universalmente disponíveis — com créditos da plataforma e com suas próprias chaves. BYOK adiciona a opção de contornar a orquestração e acionar um único modelo diretamente.","reference.models#8#h":"Modelos gerenciados pela plataforma","reference.models#9#p":"Disponível em todos os planos, incluindo o nível gratuito. Tokens (as unidades de texto nas quais a IA é medida — aproximadamente três quartos de uma palavra cada) contam contra a cota do seu plano. As chaves (as senhas privadas que desbloqueiam cada modelo pago) são rotacionadas e monitoradas pela plataforma — nada para você configurar.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Precisa de um relatório, um e-mail ou um documento escrito? Ava pode rascunhá-lo e entregar um arquivo real do Word, Excel ou PDF que você pode abrir e editar como qualquer outro.","features.office-suite#1#p":"Relatórios, e-mails e documentos — rascunhados, formatados e exportados para formatos nativos (.docx é Word, .xlsx é Excel, .pdf é um PDF).","features.office-suite#2#li0":"report_generate — um .docx estruturado que extrai dados de tarefas, diário, memória e estado do projeto.","features.office-suite#2#li1":"email_draft — e-mail com tom controlado para um arquivo .docx.","features.office-suite#2#li2":"document_manage — criar, ler, editar, exportar entre Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Útil quando Ava está escrevendo em seu nome — relatórios de status, apresentações de início, atualizações de clientes. O .docx chega ao seu projeto onde você pode refiná-lo.","features.dashboard-library#title":"Biblioteca do painel","features.dashboard-library#0#p":"Em termos simples: uma prateleira que guarda tudo que você e a Ava criaram e conversaram, para nada se perder.","features.dashboard-library#1#p":"Uma visão navegável de tudo que a Ava produziu com você — imagens geradas, vídeos, áudio, documentos — junto com suas conversas, memórias e tarefas. Um lugar para encontrar algo que você fez semana passada.","features.document-preview#title":"Visualização de documento","features.document-preview#0#p":"Em termos simples: dê uma olhada dentro de um documento exatamente onde você está, sem abrir um programa separado para lê-lo.","features.document-preview#1#p":"Clique com o botão direito em um doc do Word, planilha do Excel, PDF, CSV, HTML ou arquivo Markdown no seu projeto — visualize-o diretamente sem sair do editor. Útil para ler material de referência que a Ava gerou ou arquivos que um colaborador enviou.","features.daily-briefing#title":"Resumo diário","features.daily-briefing#0#p":"Em termos simples: uma nota curta \"aqui está onde você parou\" toda manhã, para que você possa retomar sem reler tudo.","features.daily-briefing#1#p":"Resumo matinal: diário de ontem, tarefas abertas, estado do projeto e quaisquer lembretes que a Ava definiu. Opcional — ative nas configurações.","features.daily-briefing#2#p":"O resumo usa a memória para mostrar contexto relevante (\"na última vez que trabalhou no fluxo de autenticação, você notou que queria revisar a estratégia de token de atualização\"). Não é um feed de notícias — é uma atualização focada.","troubleshooting.common-errors#title":"Erros comuns","troubleshooting.common-errors#0#p":"A maioria dos erros tem uma causa curta e específica. Aqui estão os mais comuns e como corrigi-los. Não se preocupe se o texto parecer técnico — cada um abaixo diz exatamente o que você está vendo e o que fazer.","troubleshooting.common-errors#1#h":"Modelo não responde","troubleshooting.common-errors#2#p":"O que você vê: A Ava fica em silêncio e não responde.","troubleshooting.common-errors#3#p":"Verifique o indicador de status no cabeçalho do chat. Se disser \"conectando\", seu provedor (o serviço de IA com o qual a Ava está falando) está acessível, mas lento — aguarde trinta segundos. Se disser \"indisponível\", a Ava caiu automaticamente para o próximo modelo na cadeia (ela trocou automaticamente para um modelo de backup). Se nada acontecer, verifique sua chave de API nas Configurações e teste a conexão. (Uma chave de API é a senha privada que permite à Ava usar um serviço de IA pago.)","troubleshooting.common-errors#4#h":"Chamada de ferramenta falhou","troubleshooting.common-errors#5#p":"O que você vê: Uma das etapas da Ava (uma \"chamada de ferramenta\" — ela lendo um arquivo, executando um comando, etc.) mostra um erro vermelho em vez de terminar.","troubleshooting.common-errors#6#p":"Clique na chamada de ferramenta falhada para ver o erro. Causas comuns: ela tentou tocar em um arquivo fora da pasta do seu projeto, o que é bloqueado propositalmente por segurança (essa proteção é chamada de proteção contra \"travessia de caminho\" — impede que ela saia da pasta em que você está trabalhando); um comando que precisa ser executado em outra pasta; ou um arquivo que foi movido desde que a Ava olhou pela última vez. Diga a ela o que aconteceu — ela tentará novamente com correções.","troubleshooting.common-errors#7#h":"Memória não recorda","troubleshooting.common-errors#8#p":"O que você vê: A Ava não encontra algo que você tem certeza que ela deveria lembrar.","troubleshooting.common-errors#9#p":"A memória funciona por significado, não por palavras exatas (é isso que \"semântico\" significa). Então \"O que decidi sobre autenticação?\" funciona melhor do que \"encontre minha decisão sobre auth\". Se a memória estiver definitivamente lá mas não aparecendo, abra o navegador de memória e pesquise — se não estiver lá, nunca foi salva.","troubleshooting.common-errors#10#h":"Loops de login","troubleshooting.common-errors#11#p":"O que você vê: Você faz login, mas a Ava continua pedindo para você fazer login novamente — um ciclo que nunca deixa você passar.","troubleshooting.common-errors#12#p":"A solução é limpar os detalhes de login salvos e começar do zero: na extensão, execute \"Ava: Sign Out\" na paleta de comandos; na IDE, vá em Configurações → Conta → Sair; na CLI, exclua o arquivo em ~/.ava/auth.json (um pequeno arquivo de login em uma pasta chamada .ava no seu diretório home). Depois faça login novamente.","troubleshooting.common-errors#13#h":"Tokens esgotados","troubleshooting.common-errors#14#p":"O que você vê: Uma mensagem dizendo que você acabou do uso gratuito do mês. (“tokens” são como o uso de IA é medido — “esgotados” apenas significa que você usou toda a cota gratuita deste mês.)","troubleshooting.common-errors#15#p":"O orçamento mensal da camada gratuita reinicia no dia 1 de cada mês. Até lá, mude para um provedor BYOK (use sua própria chave de API) para continuar trabalhando. Sua conta permanece ativa — apenas as solicitações gerenciadas gratuitamente pela plataforma estão pausadas.","troubleshooting.logs#title":"Onde ficam os logs","troubleshooting.logs#0#p":"Um \"log\" é apenas um diário que seu computador mantém do que aconteceu — útil quando algo quebra e você (ou o suporte) precisa ver os detalhes.","troubleshooting.logs#1#p":"Quando você precisa da imagem bruta — qual ferramenta foi chamada, que informações ela obteve, o que o serviço de IA retornou — os logs são arquivos de texto simples em uma pasta no seu computador em ~/.ava/logs/ (uma pasta chamada .ava no seu diretório home, com uma pasta logs dentro dela).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — transcrições por sessão incluindo chamadas de ferramentas, respostas transmitidas e erros.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — log do host da extensão VS Code. Falhas de ativação, erros do painel.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — log do IDE desktop. Mensagens do processo sidecar, falhas no Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — log do REPL CLI.","troubleshooting.logs#3#p":"Na extensão, \"Ava: Show Logs\" na paleta de comandos abre o log relevante em uma aba de editor. Na IDE, Configurações → Diagnósticos tem um botão \"Open Logs\". A CLI pode acompanhar seu próprio log com ava logs --follow.","features.unified-panel#title":"Painel unificado","features.unified-panel#0#p":"Em termos simples: tudo o que a Ava faz vive em uma única janela, então você nunca precisa procurar abas para encontrá-lo.","features.unified-panel#1#p":"Um painel para chat, painel, memória, tarefas e diário. Sem alternância de contexto entre janelas. A barra lateral escolhe o que você está vendo; a área principal muda para combinar.","features.unified-panel#2#p":"O estado da conversa persiste quando você navega para outro lugar — abra a memória, verifique uma tarefa e volte. O chat ainda está lá, continuando a atualizar se a Ava ainda estiver rodando.","features.unified-panel#3#c":"Painel unificado é um conceito de extensão e IDE. A interface web usa abas do navegador.","features.knowledge-packs#title":"Pacotes de conhecimento","features.knowledge-packs#0#p":"Em termos simples: entregue à Ava uma pasta com seus próprios documentos, e ela pode ler deles para responder às suas perguntas. Um \"pacote de conhecimento\" é apenas esse conjunto de arquivos — seu material de referência do qual ela pode consultar.","features.knowledge-packs#1#p":"Arraste um diretório de material de referência (especificações, RFCs, atas de reunião, docs de API) para um pacote de conhecimento. A Ava pode puxar as partes relevantes para o contexto quando uma conversa aborda o tópico.","features.knowledge-packs#2#p":"Os pacotes são indexados localmente. A recuperação é semântica — a Ava encontra o documento certo pelo significado, não pelo nome do arquivo. (\"Semântica\" significa que ela combina com o que o documento trata, então você não precisa lembrar das palavras exatas ou do nome do arquivo.) Os pacotes podem ser compartilhados com a equipe ou mantidos privados.","troubleshooting.logs#4#c":"Logs podem conter trechos dos arquivos do projeto que a Ava leu durante uma sessão. Revise antes de compartilhar.","troubleshooting.support-request#title":"Abrindo um pedido de suporte","troubleshooting.support-request#0#p":"Em termos simples: se algo estiver errado e as correções acima não ajudarem, envie-nos uma mensagem sobre isso. O jeito mais fácil é pedir para a Ava fazer isso por você.","troubleshooting.support-request#1#p":"Se um problema não estiver coberto pelos erros comuns, abra um chamado de suporte (envie um pedido de ajuda à equipe de suporte). Você pode fazer isso dentro da Ava (sem formulário para preencher) ou na web.","troubleshooting.support-request#2#h":"Dentro da Ava","troubleshooting.support-request#3#p":"Peça para ela abrir o chamado. \"Ava, você pode abrir um chamado de suporte sobre isso?\" Ela aciona o support_request, anexa o contexto relevante da sessão (com credenciais ocultadas) e envia. Caminho mais rápido.","troubleshooting.support-request#4#h":"Pela web","troubleshooting.support-request#5#p":"Acesse ava-supernova.com/support. Escolha uma categoria (bug, feature, account, security, general) e descreva o que aconteceu. Resposta em até um dia útil.","troubleshooting.support-request#6#h":"O que incluir","troubleshooting.support-request#7#li0":"O que você estava tentando fazer.","troubleshooting.support-request#7#li1":"O que realmente aconteceu.","troubleshooting.support-request#7#li2":"Qual plataforma (extensão, IDE, CLI, aplicativo complementar) e qual versão.","troubleshooting.support-request#7#li3":"Qualquer mensagem de erro ou trecho de log. Oculte as credenciais primeiro.","troubleshooting.security-disclosure#title":"Reportando problemas de segurança","troubleshooting.security-disclosure#0#p":"Em termos simples: se você identificou uma forma de a Ava ser invadida ou usada indevidamente (uma \"vulnerabilidade\" — uma falha de segurança), por favor nos avise privadamente primeiro para que possamos corrigir antes que alguém possa explorar. Esta página explica como.","troubleshooting.security-disclosure#1#p":"Encontrou uma vulnerabilidade? Obrigado. Levaremos cada relatório a sério e trabalharemos com você na correção antes de qualquer divulgação pública (antes que o problema seja anunciado publicamente).","troubleshooting.security-disclosure#2#h":"Como reportar","troubleshooting.security-disclosure#3#li0":"Envie um email para security@ava-supernova.com com uma descrição, passos para reproduzir e sua janela de divulgação preferida.","troubleshooting.security-disclosure#3#li1":"Ou abra um chamado de suporte com a categoria \"segurança\" — mesma fila de triagem.","troubleshooting.security-disclosure#3#li2":"Reconhecemos em até 24 horas.","troubleshooting.security-disclosure#4#h":"Nossos compromissos","troubleshooting.security-disclosure#5#li0":"Divulgação coordenada — concordamos com um cronograma com você antes de qualquer coisa ficar pública. O padrão é 90 dias.","troubleshooting.security-disclosure#5#li1":"Crédito — você será creditado nas notas da correção, a menos que prefira anonimato.","troubleshooting.security-disclosure#5#li2":"Sem retaliação legal — pesquisas de boa-fé são bem-vindas. Não enviaremos advogados atrás de você.","troubleshooting.security-disclosure#6#c":"A página de segurança em ava-supernova.com/security detalha toda a postura — garantias de arquitetura, ferramenta de redação, controles de permissão.","features.workflows#title":"Fluxos de Trabalho","features.workflows#0#p":"Em termos simples: ensine à Ava uma rotina que você faz repetidamente, dê um nome a ela e ela pode executar tudo novamente sob demanda. Um \"workflow\" é apenas essa rotina salva — um conjunto de passos que Ava repete para você.","features.workflows#1#p":"Salve uma sequência de passos que você encontra repetindo-se — revisar o pull request → rodar testes → escrever notas de versão → rascunhar o e-mail. Um workflow é um plano reutilizável que Ava pode reproduzir com entradas diferentes.","features.workflows#2#p":"Os workflows são armazenados por projeto em uma pasta chamada .ava/workflows/ dentro do seu projeto. Compartilhe-os com sua equipe fazendo commit do diretório (salvando-o no seu projeto compartilhado para que os colegas também o recebam).","features.events#title":"Eventos e notificações","features.events#0#p":"Em termos simples: enquanto a Ava trabalha, você recebe uma lista passo a passo organizada do que ela está fazendo, e um aviso quando um trabalho longo termina para que você possa se afastar.","features.events#1#p":"Enquanto a Ava está executando, você vê atualizações estruturadas, não um muro de texto. Cada chamada de ferramenta, cada transferência de agente, cada delta transmitido é um evento discreto na interface — expansível para detalhes, colapsável para visão geral.","features.events#2#p":"Execuções em segundo plano emitem notificações ao nível do sistema operacional quando terminam. Você pode se afastar de uma compilação longa e a Ava avisará quando estiver pronta.","features.personality#title":"Designer de Personalidade","features.personality#0#p":"Em termos simples: ajuste como a Ava fala com você — conversadora ou breve, formal ou casual, mais piadas ou menos — para que ela soe como você gosta.","features.personality#1#p":"Defina como a Ava fala com você. Tom, energia, verbosidade (o quanto ela diz), formalidade, humor. Controles deslizantes e presets — engenheiro conciso, mentor acolhedor, colega seco, ou sua própria mistura.","features.personality#2#p":"A personalidade afeta a formulação, não a competência. Ela ainda executa as mesmas ferramentas e segue as mesmas regras de permissão. O nome dela está travado em Ava — isso é inegociável.","features.release-notes#title":"Notas de lançamento","features.release-notes#0#p":"Em termos simples: uma lista contínua do que há de novo e do que foi corrigido em cada atualização, para que você veja o que mudou.","features.release-notes#1#p":"Registro de alterações no aplicativo (um registro de alterações é o histórico de mudanças). Cada versão lançada com seus destaques, correções de bugs e mudanças quebradas (alterações que podem exigir que você ajuste como usa algo). A interface web mantém a versão pública em ava-supernova.com/releases.","start.for-non-coders#6#li3":"Quando você quiser que ela realmente faça ou altere algo, é só pedir — ela sempre mostrará o que está prestes a fazer e esperará pelo seu \"sim\".","start.for-non-coders#7#c":"Deparou-se com uma palavra que não conhece? O glossário em linguagem simples (mais adiante nesta seção) explica cada termo sem assumir nenhum conhecimento prévio.","start.install#title":"Instalar","start.install#0#p":"Escolha a interface que combina com sua forma de trabalhar. Você pode usar mais de uma — Ava sincroniza sua memória entre elas quando você faz login.","start.install#1#h":"Extensão do VS Code","start.install#2#li0":"Abra o painel de Extensões no VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Procure por \"Ava Supernova\" e clique em Instalar.","start.install#2#li2":"Pressione Ctrl+Shift+A (Cmd+Shift+A no macOS) para abrir o painel de chat.","start.install#2#li3":"Siga o assistente de configuração — escolha um modelo, defina seu modo de permissão, pronto.","start.install#3#h":"IDE Desktop","start.install#4#li0":"Baixe o instalador para sua plataforma na página de lançamentos.","start.install#4#li1":"Execute-o. O IDE inicia com um fluxo de boas-vindas na primeira vez.","start.install#4#li2":"Faça login para obter tokens gratuitos da plataforma, ou cole sua própria chave de API para rodar totalmente local.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli (ou pnpm / yarn — sua escolha).","start.install#6#li1":"Execute o ava em qualquer diretório de projeto.","start.install#6#li2":"Na primeira execução, ele solicitará um provedor e um modelo. Escolha e vá.","start.install#7#c":"Sem conta, sem problema. Com sua própria chave de API (BYOK) você nunca precisa fazer login. O plano gratuito é para os modelos gerenciados pela plataforma.","reference.project-context#title":"Contexto do projeto","reference.project-context#0#p":"Isso explica como a Ava se informa sobre o seu projeto antes de começar — os arquivos que ela analisa para entender no que você está trabalhando. Você não precisa configurar nada disso; ela faz isso sozinha. Leia se quiser saber onde colocar uma nota para que ela sempre veja.","reference.project-context#1#p":"Quando você abre um projeto, a Ava carrega várias camadas de contexto (informações de fundo que ela mantém em mente). Entender as camadas ajuda você a colocar as informações no lugar certo.","reference.project-context#2#h":"Carregado automaticamente","reference.project-context#3#li0":".ava/instructions.md — tratado como orientação durável e de alta prioridade. Sempre no contexto.","reference.project-context#3#li1":".ava/context.md — notas livres. Carregado, prioridade menor.","reference.project-context#3#li2":"README.md — escaneado na primeira execução para resumo do projeto.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — os pequenos arquivos que listam a configuração do projeto; lidos para detectar a linguagem, framework e comando de teste.","reference.project-context#3#li4":".gitignore — a lista de arquivos para deixar fora do controle de versão; respeitado por todas as ferramentas de arquivo (glob, grep, project_index).","reference.project-context#4#h":"Carregado sob demanda","reference.project-context#5#p":"\"Sob demanda\" significa que a Ava só busca esses itens quando uma tarefa realmente precisa deles, e não de antemão.","reference.project-context#6#li0":"Índice do projeto — um mapa estruturado dos seus arquivos e das partes nomeadas dentro deles (funções, classes — \"símbolos\") e como eles se conectam (\"importações\"). Criado apenas quando a Ava precisa.","reference.project-context#6#li1":"Histórico do Git — o registro de mudanças passadas; puxado quando git_status, git_diff ou git_create_pr são chamados (Git é a ferramenta que rastreia toda mudança no projeto; \"PR\" é um pull request, um lote proposto de mudanças).","reference.project-context#6#li2":"Memória — entradas são correspondidas por significado (\"semanticamente\") e injetadas uma vez por vez, não tudo de uma vez.","reference.project-context#7#c":"Coloque convenções em instructions.md. Coloque notas em context.md. Deixe a memória capturar o resto sozinha.","start.what#title":"O que é a Ava?","start.what#0#p":"Ava é uma IA que realmente faz coisas — não apenas fala. Ela cria um app para você, escreve um documento, ensina algo do zero, desenha um logo ou cuida da administração que você sempre adia. E ela se lembra de você: do que está trabalhando, como gosta das coisas, do que pediu semana passada.","start.what#1#p":"É só uma Ava, e ela trabalha onde você trabalha — no seu editor de código, como um app de desktop, no celular ou no terminal. Mesma memória, mesma personalidade, em todo lugar.","start.what#2#h":"O que a torna diferente","start.what#3#li0":"Sua por padrão. Seu trabalho fica na sua própria máquina. Sem rastreamento, sem telemetria — nunca.","start.what#3#li1":"Aberta para todos verem. Cada linha do código da Ava é pública. Nada para aceitar cegamente.","start.what#3#li2":"Grátis para começar. 300 créditos todo mês, sem cartão, sem pegadinha — ou conecte suas próprias chaves de IA e não nos paga nada.","start.what#3#li3":"Ensinar é grátis, para sempre. Aprender não deveria ter preço.","start.what#4#p":"Nunca escreveu código? A próxima página foi escrita só para você. Já é técnico? Pule adiante — ela acompanha o ritmo.","start.what#deeper#0#h":"Onde a Ava mora","start.what#deeper#1#li0":"Extensão do VS Code — Ava ao lado do seu editor: painel de chat, visão geral e mudanças mostradas diretamente antes de acontecerem.","start.what#deeper#1#li1":"IDE Desktop — um app independente com tudo em uma janela. Adiciona controle do desktop (abrir apps, clicar, digitar por você).","start.what#deeper#1#li2":"Companheiro — um app móvel quando você está longe da mesa: tarefas, diário, memória, chats rápidos.","start.what#deeper#1#li3":"CLI — Ava no seu terminal, para quem vive lá.","start.what#deeper#2#h":"Como ela funciona, em resumo","start.what#deeper#3#p":"Ava muda de mentalidade (chamados modos) para combinar com a tarefa, roda silenciosamente uma pequena equipe de especialistas em trabalhos mais difíceis e escolhe o melhor modelo de IA para cada etapa automaticamente. Você nunca gerencia nada disso. A seção Conceitos Básicos tem o tour completo sempre que estiver curioso.","start.first-five#title":"Sua primeira coisa com a Ava","start.first-five#0#p":"A maneira mais rápida de conhecer a Ava é pedir algo real e vê-la fazer. Sem configuração para ler, nada para aprender primeiro — apenas diga o que quer, em palavras simples.","start.first-five#1#h":"Experimente agora","start.first-five#2#li0":"Abra o chat.","start.first-five#2#li1":"Digite algo que você realmente quer. Tente \"explicar o que este projeto faz\", ou \"adicionar um botão que limpa o formulário\".","start.first-five#2#li2":"Ava mostra o que vai fazer — e espera.","start.first-five#2#li3":"Gostou? Diga sim. Veja ela fazendo.","start.first-five#3#p":"Esse é o ritmo inteiro: você pede, ela mostra o plano, você aprova, ela faz. Ela nunca muda nada sem mostrar primeiro — então você não pode quebrar nada tentando.","start.first-five#4#h":"Algumas coisas vale a pena pedir","start.first-five#5#li0":"Uma pergunta — \"por que minha página está em branco?\", \"o que faz este arquivo?\"","start.first-five#5#li1":"Algo construído — \"crie para mim uma página de lista de tarefas simples\".","start.first-five#5#li2":"Para aprender algo — \"ensine-me Python do zero\". (Sempre gratuito.)","start.first-five#5#li3":"Um documento — \"escreva para mim uma proposta de projeto de uma página\". Ela te entrega um arquivo Word ou PDF.","start.first-five#6#c":"Não sabe o que digitar? Converse com ela como faria com um amigo bem informado. Palavras simples estão exatamente certas — você nunca precisa dos termos técnicos para começar.","start.first-five#deeper#0#p":"Esse loop simples está fazendo bastante coisa nos bastidores. Você não precisa de nada disso para usar a Ava — mas aqui está o que realmente acontece se você tiver curiosidade.","start.first-five#deeper#1#h":"Ferramentas e aprovação","start.first-five#deeper#2#p":"Quando a Ava lê um arquivo, executa um comando ou edita código, cada um desses é uma \"chamada de ferramenta\". Ela pede permissão antes de qualquer coisa que toque seus arquivos ou sistema — com que frequência ela pede é definido pelo seu modo de permissão (perguntar sempre, perguntar apenas coisas arriscadas, ou apenas seguir).","start.first-five#deeper#3#h":"Modos — os estados dela","start.first-five#deeper#4#p":"Ava trabalha em modos: uma mentalidade mais a caixa de ferramentas certa para o trabalho. Troque a qualquer momento pelo seletor, ou digite um prefixo no início da sua mensagem. São sete.","start.first-five#deeper#6#h":"Especialistas e roteamento","start.first-five#deeper#7#p":"Em trabalhos mais difíceis, a Ava roda uma pequena equipe de ajudantes especialistas nos bastidores (um planejador, um verificador, um construtor) e roteia cada etapa para o modelo que é melhor nisso. Você nunca gerencia nada disso — ela coordena tudo para você.","start.local-vs-cloud#title":"Local vs nuvem, em um parágrafo","start.local-vs-cloud#0#p":"Tudo o que a Ava faz é local, a menos que você opte explicitamente. Memória, tarefas, diário, personalidade, configurações — tudo armazenado na sua máquina em ~/.ava/ e .ava/ (por projeto). Ela conversa com provedores de modelos via HTTPS para executar seu pedido, depois volta para casa. Ela não liga para casa. Ela não coleta telemetria. Ela não treina com seu código.","start.local-vs-cloud#1#p":"Se fizer login, você ganha 300 créditos gratuitos por mês em modelos gerenciados pela plataforma (Qwen, MiniMax) e sincronização em nuvem opcional para memória e configurações entre máquinas. Sincronização é por recurso, revogável a qualquer momento. Traga sua própria chave de API e a Ava funciona totalmente sem conta.","start.local-vs-cloud#2#c":"A regra: local é sagrado. Nuvem é adicional.","start.first-model#title":"Preciso escolher uma IA?","start.first-model#0#p":"Aqui vai um alívio: você não escolhe a IA. A Ava escolhe a certa para cada passo automaticamente, então você tem bons resultados sem precisar pensar nisso.","start.first-model#1#p":"A única coisa que você pode escolher é um estilo de roteamento — e o padrão serve para quase todos. Você só precisa dos outros por um motivo específico.","start.first-model#2#h":"Os três estilos","start.first-model#3#li0":"Maestro — o padrão. Estável, confiável, previsível. Não tem certeza? Este é o ideal.","start.first-model#3#li1":"Supernova — para trabalho pesado e multifásico, onde vale a pena colocar um especialista diferente em cada parte do trabalho.","start.first-model#3#li2":"Aurora — para quando seus dados devem permanecer na UE (setor público, saúde, privacidade rigorosa). Funciona inteiramente com IA europeia de peso aberto.","start.first-model#4#p":"Troque a qualquer momento pelo seletor de modelos no topo do chat. Nada está travado.","start.first-model#5#c":"Quer controlar um modelo específico você mesmo? Pode — abra \"Mostre-me os detalhes\".","start.first-model#deeper#0#h":"O que há de fato em cada estilo","start.first-model#deeper#1#p":"Maestro — um único maestro (Qwen 3.6 Plus) cuida de cada etapa. Otimizado para produção, comprovado e com custo previsível.","start.first-model#deeper#2#p":"Supernova — um coordenador de fronteira (DeepSeek V4 Pro, 1.6T parâmetros / 49B ativos, contexto de 1M) passa cada subtarefa para um especialista: V4 Flash para builds de alto volume, Qwen 3.6 Plus como plano B, Qwen Omni para visão.","start.first-model#deeper#3#p":"Aurora — apenas Mistral, em três níveis: Mistral Large 3 (coordenador + especialistas pesados), Mistral Medium 3.5 (128B denso, contexto de 256K, visão nativa, pesos abertos MIT modificado, 77.6% SWE-Bench Verificado) para Construtor + nível médio + visão + texto longo, e Mistral Small 4 na porta de intenção. Pesos abertos do início ao fim, nunca sai da infraestrutura da UE.","start.first-model#deeper#4#h":"Traga seu próprio modelo (BYOK)","start.first-model#deeper#5#p":"Prefere usar sua própria conta de IA? Cole sua chave do provedor nas configurações e você terá ambos — os três estilos de roteamento, além da opção de escolher um único modelo e pular o roteamento inteiramente. Útil para uma preferência forte, um orçamento apertado ou testar um modelo específico. A lista completa de provedores está na seção Referências.","start.glossary#title":"Glossário em linguagem simples","start.glossary#0#p":"Cada palavra que você pode encontrar por aí sobre a Ava, explicada sem pressupor conhecimento prévio. Você não precisa decorar nada disso — consulte novamente sempre que um termo te deixar na dúvida.","start.glossary#1#th0":"Palavra","start.glossary#1#th1":"O que realmente significa","start.glossary#1#td0.0":"Agente","start.glossary#1#td0.1":"Uma IA que pode tomar ações por você — ler um arquivo, executar um comando, buscar na web — não apenas conversar. A Ava é um agente: ela faz coisas, com sua aprovação.","start.glossary#1#td1.0":"Modelo","start.glossary#1#td1.1":"O cérebro real da IA fazendo o pensamento (Qwen, DeepSeek, Mistral e outros). Modelos diferentes têm pontos fortes diferentes. Normalmente você nunca escolhe um — a Ava faz isso.","start.glossary#1#td2.0":"Modo","start.glossary#1#td2.1":"O estado mental da Ava. Como um colega trocando de chapéu: construtor, escritor, professor, planejador, amigo. Você escolhe o modo; isso muda como ela se comporta. São sete.","start.glossary#1#td3.0":"Persona / especialista","start.glossary#1#td3.1":"Papéis de ajuda que a Ava executa nos bastidores para tarefas mais difíceis — um explorador, um planejador, um verificador de fatos. Pense em uma pequena equipe de especialistas. Você nunca fala diretamente com eles; a Ava coordena eles.","start.glossary#1#td4.0":"Roteamento","start.glossary#1#td4.1":"Ava decidindo qual modelo usar em cada passo para você ter boas respostas sem pagar demais. Isso acontece automaticamente — \"modo de roteamento\" apenas escolhe a estratégia geral.","start.glossary#1#td5.0":"Ferramenta","start.glossary#1#td5.1":"Uma ação específica que a Ava pode fazer — ler um arquivo, fazer uma busca, enviar um e-mail. Uma \"chamada de ferramenta\" é ela usando uma. Ela pede permissão antes de qualquer coisa arriscada.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Como a IA mede texto — aproximadamente ¾ de uma palavra. Modelos são precificados por milhão de tokens. Geralmente algo que você pode ignorar.","start.glossary#1#td7.0":"Crédito","models.routing#deeper#1#h":"Lado a lado","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Coordenador","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B ativos, 1M de contexto)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B ativos, 262K de contexto)","models.routing#deeper#2#td1.0":"Construtor","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (reutiliza o coordenador)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B denso, 256K de contexto)","models.routing#deeper#2#td2.0":"Especialistas de nível intermediário","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (revisor de código, verificador de fatos, reconhecimento, varredura, verificador de segurança, etc.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Arquiteto, Verificador, Sequenciador, Tutor, Relator, etc.)","models.routing#deeper#2#td3.0":"Nível leve / filtro de intenção","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Explorador, Verificador, Sequenciador, Desafista, Integrador)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Especialistas de alto desempenho","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Pesquisador, Desafista, Pesquisador de CVE, Idealizador, Verificador de Fatos)","concepts.desktop-safety#3#li2":"Mutativo-reversível — digite em um campo, cole, abra um aplicativo, navegue por uma URL. Confirma no modo Ask; automático no Drive dentro da lista permitida.","concepts.desktop-safety#3#li3":"Mutativo-irreversível — enviar, submeter, pagar, excluir, confirmar, publicar. Sempre confirma, independentemente do nível de permissão. Aprovação nunca é armazenada em cache.","concepts.desktop-safety#3#li4":"Privilegiado — elevação UAC, sudo, edições de registro, prompts de credenciais. Proibido por padrão. Requer opt-in de uso único por sessão.","concepts.desktop-safety#4#h":"Aprovações nunca armazenadas em cache","concepts.desktop-safety#5#p":"Todo concorrente armazena aprovações em cache (lembra seu \"sim\" e reutiliza na próxima vez). Esse é o maior ponto de entrada para injeção de prompt — um ataque onde uma página web com armadilha insere instruções ocultas na IA para fazê-la agir contra você. Se as aprovações forem armazenadas em cache, uma página comprometida pode aproveitar um \"sim\" que você deu antes. A Ava nunca armazena em cache. Cada ação mutativo-irreversível pede uma nova confirmação.","concepts.desktop-safety#6#h":"Gerenciamento de segredos","concepts.desktop-safety#7#p":"Senhas, chaves de API e códigos 2FA (os códigos únicos que um segundo aplicativo ou mensagem de texto envia quando você faz login) são manipulados via identificadores opacos — espaços reservados que substituem o valor real. A Ava vê \"{segredo}\", não a senha real. O valor real nunca entra na memória dela, no log de atividades ou no que ela \"lê\" — uma camada separada de baixo nível digita isso no último momento, ao pressionar a tecla, para que a parte da IA nunca toque nisso.","reference.cli#title":"Comandos CLI","reference.cli#0#p":"Esta página é para a CLI — a versão da Ava que você digita em uma janela de terminal, em vez de clicar em botões. Se usar a extensão ou o aplicativo desktop, pode pular completamente. Ela está aqui para quem prefere o teclado.","reference.cli#1#p":"A CLI é um REPL — um prompt que espera você digitar, executa o que foi digitado e espera novamente. Esses comandos com barra (instruções que começam com \"/\") funcionam diretamente no prompt.","reference.cli#2#li0":"/help — listar comandos e modo atual.","reference.cli#2#li1":"/mode <name> — mudar modo (trabalho, escrita, planejamento, conversa, ensino, segurança, brainstorming).","reference.cli#2#li2":"/model <id> — mudar modelo sem sair da sessão.","reference.cli#2#li3":"/clear — limpar conversa atual. Memória intacta.","reference.cli#2#li4":"/history — listar conversas passadas neste projeto.","reference.cli#2#li5":"/memory — abrir navegador de memória.","reference.cli#2#li6":"/tasks — listar e gerenciar tarefas.","reference.cli#2#li7":"/journal — abrir entrada de diário de hoje.","reference.cli#2#li8":"/settings — abrir menu de configurações.","reference.cli#2#li9":"/exit — sair do REPL.","reference.cli#3#h":"Opções de inicialização","reference.cli#4#p":"Opções são extras que você adiciona ao iniciar a Ava, cada uma começando com \"--\", para definir como ela abre.","reference.cli#5#li0":"--mode <name> — iniciar em um modo específico.","reference.cli#5#li1":"--model <id> — iniciar com um modelo específico.","reference.cli#5#li2":"--permission <mode> — estrito / equilibrado / autônomo.","models.routing#deeper#2#td11.1":"Trabalho diário, custo previsível","models.routing#deeper#2#td11.2":"Trabalhos pesados e multifásicos, coordenador de ponta em todos os planos","models.routing#deeper#2#td11.3":"Estritas ao GDPR, setor público, pilhas soberanas da UE","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Roteamento Qwen diferenciado por nível, com pegada leve. O Qwen 3.6 Plus assume o papel de coordenador, Builder, planejamento, segurança, brainstorming e trabalhos de contexto longo — onde sua atenção híbrida linear de 1M contextos rende mais. O Qwen 3.5 Flash cuida do chat, orquestração de geração de imagens e do filtro de intenção inicial, onde seu preço de $0.07/$0.26 e tempo de resposta inicial (TTFT) mais rápido vencem no volume bruto de tokens de baixa profundidade. O Qwen 3.5 Omni Plus assume a entrada visual (o Qwen 3.6 Plus não tem visão nativa). O Qwen 3.5 Plus carrega trabalhos longos sensíveis a custos. Se o coordenador principal estiver indisponível, cai na escada de prioridades: Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Conjunto poliglota. O DeepSeek V4 Pro coordena e despacha cada subtarefa para seu especialista mais adequado: o Qwen 3.6 Plus roda toda criação do Builder, o V4 Flash cuida do chat além dos papéis de revisão/auditoria de nível intermediário, o Qwen 3.5 Flash absorve o trabalho de classificador de nível leve, o Qwen 3.5 Omni Plus assume a entrada visual, o Qwen 3.5 Omni Flash orquestra chamadas de ferramentas de geração de imagem, o Qwen 3.5 Plus carrega o papel de Content Writer sensível a custos. Raciocínio avançado onde importa, economia de nível flash no volume bruto de tokens.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Pilha de IA europeia — soberana por design. Roteamento exclusivo Mistral em três níveis: Mistral Large 3 (675B/41B-sparse MoE ativo) assume o papel de coordenador mais os especialistas pesados que precisam de profundidade — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — e o trabalho pesado de contexto longo onde sua eficiência sparse-MoE vence. Mistral Medium 3.5 — a versão consolidada lançada em abril de 2026, 128B denso, 256K contexto, codificador visual treinado do zero, pesos abertos modified-MIT, 77.6% SWE-Bench Verified — roda o nível de trabalho real: criações do Builder, especialistas de nível intermediário (Architect, Verifier, Sequencer, Tutor, Reporter), entrada visual e escrita de formato longo. Mistral Small 4 expandiu de um único papel no filtro de intenção para também cuidar do chat e orquestração de geração de imagem — seu preço de $0.15/$0.60 e raciocínio configurável valem o esforço nas rotas de alto volume e baixa profundidade. Pesos abertos de ponta a ponta, nunca sai da infraestrutura da UE. A Aurora deliberadamente não faz roteamento silencioso para um modelo não-Mistral quando um está indisponível; o roteador exibe um erro em vez disso — é isso que a torna \"Aurora\" em vez de um Maestro com sabor de Mistral.","credits.overview#title":"Créditos Ava — como funciona a faturação","credits.overview#0#p":"Os créditos são simplesmente como a Ava conta o que você usa — como minutos em um plano de celular. Todo plano, incluindo o gratuito, vem com uma reserva de créditos, e cada coisa que a Ava faz (responder você, criar uma imagem) custa alguns deles. Essa é toda a ideia. Os detalhes abaixo são para quando você quer saber exatamente quanto custa cada coisa.","credits.overview#1#p":"A Ava fatura em créditos, não em tokens brutos. (Um \"token\" é o pedacinho minúsculo de texto — cerca de algumas letras — que os modelos de IA leem e escrevem; a maioria dos serviços cobra por token, o que é difícil de prever.) Um crédito cobre uma unidade de trabalho — uma rodada de chat, uma criação de persona (um ajudante fazendo parte da tarefa), uma geração de imagem. Desacoplar da medição por nível de token significa que você não precisa saber qual modelo está rodando para saber quanto uma ação vai custar. A mesma rodada de chat custa o mesmo, seja o Maestro roteando para o Qwen 3.6 Plus ou o Supernova roteando para o V4 Pro.","credits.overview#2#h":"Planos","credits.overview#3#p":"Todo plano tem acesso a todos os recursos — acesso a modelos, Creative Studio, todas as sete modalidades, a orquestração completa de personas. Níveis superiores compram mais créditos e um teto de limite de taxa maior, não recursos desbloqueados.","credits.overview#4#li0":"Grátis — $0/mês. 300 créditos. Limite de taxa de 20 requisições/minuto. Nenhum cartão necessário.","credits.overview#4#li1":"Pro — $19/mês. 5.000 créditos. 60 requisições/minuto.","credits.overview#4#li2":"Ultra — $39/mês. 10.000 créditos. 120 requisições/minuto.","credits.overview#4#li3":"Enterprise — $79/mês. 20.000 créditos. 200 requisições/minuto.","credits.overview#5#c":"Créditos não usados rolam enquanto sua assinatura estiver ativa — não há cobrança forçada reversa. Recargas se acumulam na reserva da assinatura: 750 créditos por $3, 2.000 por $8, 4.000 por $15.","credits.overview#6#h":"Quanto custam as coisas","credits.overview#7#p":"Tabela de custo por ação — o que é deduzido da sua reserva de créditos quando cada ação é executada. (Um \"cache hit\" é quando a Ava reutiliza trabalho que já fez em vez de refazê-lo; quando isso acontece você paga menos — o valor cai em 70%, ou 50% em modelos pesados em saída como o DeepSeek V4 Pro.)","credits.overview#8#li0":"Rodada de chat — 2 créditos. Uma única troca de mensagens em qualquer modalidade.","credits.overview#8#li1":"Chamada leve — 1 crédito. Filtro de intenção, classificação, leitura de tiro único.","credits.overview#8#li2":"Persona pesada — 3 créditos. Architect, Researcher, CVE Researcher, Ideator (profundidade ≥ 4).","credits.overview#8#li3":"Persona leve — 1 crédito. Scout, Verifier, Sequencer, Challenger (profundidade ≤ 2).","credits.overview#8#li4":"Orquestração — 10 créditos. Início completo do pipeline de personas (Conductor + tarefa multi-persona).","credits.overview#8#li5":"Geração de imagem — 12 créditos. Hailuo image-01 via Creative Studio.","credits.overview#8#li6":"Geração de vídeo — 150 créditos. Clipe de 6s em 1080p do Hailuo 02 Pro.","credits.overview#8#li7":"Geração de voz — 10 créditos. Síntese de fala 2.8 HD.","credits.overview#8#li8":"Geração de música — 50 créditos. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Remoção de fundo — 2 créditos.","credits.overview#9#h":"Multiplicadores por modelo","credits.overview#10#p":"Isso é para os curiosos — você não precisa disso para usar Ava. Um multiplicador apenas ajusta o custo dos créditos para cima ou para baixo dependendo de quão caro é o modelo por trás de uma ação, então modelos mais pesados custam um pouco mais. (\"Margem líquida\" é a fatia que o projeto fica depois de pagar suas próprias despesas — miramos baixo para que o valor volte para você.)","credits.overview#11#p":"Modelos mais pesados multiplicam o custo da ação para que os créditos acompanhem o gasto real em vez de uma faixa fixa. Calibrado para margem líquida de ~55%.","credits.overview#12#li0":"0.6× — Mistral Small 4 (o lugar do especialista da Aurora). Abaixo de 1× porque o Mistral Small 4 é mais barato que a âncora Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Taxa base.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (coordenador da Aurora). Quase igual à âncora Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (coordenador Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (coordenador Supernova + especialistas pesados). Recalibrado de 5.0× para restaurar a paridade de margem na tarifa publicada do V4 Pro.","credits.overview#13#c":"Modelos da Anthropic (Claude Opus / Sonnet / Haiku) ignoram totalmente a faturamento de créditos — são apenas BYOK e você paga à Anthropic diretamente. O mesmo vale para qualquer outro provedor BYOK usado com sua própria chave.","credits.overview#14#h":"BYOK e créditos","credits.overview#15#p":"BYOK (\"traga sua própria chave\" — você fornece sua própria conta com um provedor de IA e uma chave, que é uma senha privada que permite ao software usar essa conta paga) é para quem já paga um provedor de IA diretamente. Se não é o seu caso, pode ignorar esta seção inteiramente.","credits.overview#16#p":"Solicitações de chave própria contornam toda a infraestrutura da plataforma — a chamada vai direto de Ava para o provedor, você paga o provedor, nenhum crédito é consumido. A única exceção é quando uma sessão BYOK inicia uma persona de nível gerenciado para uma sub-tarefa; a dedução de crédito ainda se aplica porque a superfície de orquestração de Ava está sendo usada.","credits.overview#17#h":"Onde verificar seu saldo","credits.overview#18#li0":"Extensão — Configurações → Conta, ou a etiqueta de créditos no cabeçalho do chat.","credits.overview#18#li1":"IDE — O painel do dashboard mostra o saldo atual e a taxa de consumo.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard mostra saldo, histórico e data de renovação.","credits.overview#19#c":"Foco local: Ava funciona sem conta no cartão de Modelo Personalizado (Ollama, LM Studio, vLLM ou qualquer endpoint compatível com OpenAI). Sem créditos, sem tokens da plataforma — seu modelo, sua máquina, sua conta zero.","concepts.modes#title":"Modos — Os estados de mente do Ava","reference.cli#5#li3":"--project <path> — definir explicitamente a raiz do projeto.","reference.desktop-budget#title":"Limites de orçamento da área de trabalho","reference.desktop-budget#0#p":"Quando a Ava controla sua área de trabalho em seu nome — clicando, digitando, abrindo apps — cada execução é chamada de \"trajetória\". Esta página explica os limites de segurança que impedem qualquer execução de durar demais ou custar muito. O resumo: ela sempre para e verifica antes de ultrapassar o limite. Os números estão aqui se você quiser os detalhes.","reference.desktop-budget#1#p":"Cada trajetória roda sob três limites simultâneos (limites rígidos). O primeiro atingido vence. A trajetória nunca continua silenciosamente após uma violação — o Narrador (o assistente que te explica o que está acontecendo) pausa e pergunta o que fazer.","reference.desktop-budget#2#h":"Três limites rígidos (padrão)","reference.desktop-budget#3#li0":"Contagem de passos — 30 passos","reference.desktop-budget#3#li1":"Orçamento de tokens — 500.000 tokens","reference.desktop-budget#3#li2":"Tempo real — 5 minutos","reference.desktop-budget#4#h":"Faixas de custo da tarefa","reference.desktop-budget#5#li0":"Simples (buscar docs, abrir uma página) — 5–10 passos, ~70–135K tokens, ~$0,04–0,08","reference.desktop-budget#5#li1":"Médio (fazer login, verificar logs, baixar saída) — 15–25 passos, ~205–340K tokens, ~$0,12–0,21","reference.desktop-budget#5#li2":"Complexo (triagem de três problemas do GitHub) — 25–30 passos, ~340–410K tokens, ~$0,21–0,25","reference.desktop-budget#6#p":"Os valores de tokens acima são os limites técnicos por trajetória, não sua cota mensal — isso é contado em créditos, e os 300 gratuitos por mês na camada básica cobrem confortavelmente uma mistura de chat, código e algumas automações.","reference.desktop-budget#7#c":"Você pode sobrescrever os limites por tarefa no início, mas violações sempre mostram um ponto de decisão. O orçamento nunca é consumido silenciosamente.","reference.desktop-whitelist#title":"Lista branca da sessão da área de trabalho","reference.desktop-whitelist#0#p":"Uma \"lista branca\" é simplesmente a lista de aplicativos e sites que você disse que a Ava tem permissão para tocar enquanto controla sua área de trabalho. Esta página explica como você concede essa permissão e por que ela reinicia a cada vez. A versão curta: ela só pode agir onde você permite, e pede antes de ir a qualquer lugar novo.","reference.desktop-whitelist#1#p":"No início de uma sessão de área de trabalho, a Ava pergunta onde ela tem permissão para agir. Inglês simples funciona: \"Gmail, Cursor, o portal do Azure.\" Ela lê isso e confirma a correspondência de volta para você (\"Web do Gmail, aplicativo Cursor, portal.azure.com\").","reference.desktop-whitelist#2#h":"Como é aplicado","reference.desktop-whitelist#3#p":"Ações apenas de visualização — tirar uma captura de tela, ler a lista de botões e campos na tela (a \"árvore UIA\", o próprio mapa do Windows do que há em uma janela) — são permitidas em todos os lugares, porque você precisa ver o que está na tela para decidir se adiciona um aplicativo à lista branca. Qualquer coisa que mude algo é bloqueada fora da lista; a Ava pausa e pergunta se deve adicionar.","reference.desktop-whitelist#4#h":"Escopo da sessão, deliberadamente","reference.desktop-whitelist#5#p":"A lista branca NÃO persiste entre sessões. Não há opção \"lembrar deste aplicativo\". Cada nova trajetória começa com um escopo fresco. Inconveniente por design — esquecer de reautorizar é um recurso, não um bug.","reference.desktop-whitelist#6#h":"Adições durante a trajetória","reference.desktop-whitelist#7#p":"Durante uma trajetória, você pode adicionar aplicativos do cabeçalho: \"+ Permitir aplicativo\" abre uma pequena entrada. Toque em Adicionar e o novo aplicativo fica ativo pelo resto da sessão.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Quer criar uma imagem, um vídeo curto, uma música ou uma narração falada? Basta descrever e a Ava faz para você — sem precisar de software de design ou áudio.","features.creative-studio#1#p":"Geração de imagens, vídeo, música e voz — integrado ao mesmo fluxo de trabalho do seu código. Gere um ícone, uma maquete de produto, um vídeo de demonstração, uma narração para um tutorial. Alimentado por MiniMax.","features.creative-studio#2#h":"O que você pode criar","features.creative-studio#3#li0":"Imagens — de prompt para PNG/JPG. Remoção de fundo com apenas um comando.","features.creative-studio#3#li1":"Vídeo — vídeos curtos de IA a partir de um prompt de texto (MiniMax Hailuo).","features.creative-studio#3#li2":"Música — trilhas instrumentais ou vocais com letras.","features.creative-studio#3#li3":"Voz — conversão de texto em fala com vozes selecionáveis.","features.creative-studio#4#p":"Os custos do Creative Studio saem do mesmo pool de créditos que tudo o mais — um pool, um número. BYOK sua própria chave MiniMax e fica grátis para o seu plano.","features.creative-studio#5#c":"Creative Studio é elegível para a camada gratuita. Não é um complemento pago.","features.desktop-automation#title":"Automação de Área de Trabalho","features.desktop-automation#0#p":"Em termos simples: Ava pode assumir o controle do seu mouse e teclado para fazer tarefas por você — abrir um aplicativo, clicar em botões, preencher um formulário — enquanto você assiste e aprova qualquer coisa importante.","features.desktop-automation#1#p":"Um novo modo para Ava, prefixo @@. Ela observa a área de trabalho, decide o que fazer e executa a automação de interface (controlando os aplicativos na sua tela para você) para concluir a tarefa. Roda na sua máquina real com suas credenciais reais — não é um navegador na nuvem. Disponível em todas as camadas após o lançamento.","features.desktop-automation#2#h":"Por que mais uma?","features.desktop-automation#3#p":"Todo outro produto de automação de área de trabalho é algo que você inicia quando está na sua mesa. Ava é a que ainda está lá quando seu rastreador de erros dispara às 2 da manhã — o IDE continua rodando, seu celular pareia por um canal seguro, você aprova ações irreversíveis com um toque.","features.desktop-automation#4#p":"Ela também lembra como navegar nos seus aplicativos entre sessões. Todo outro agente reaprende tudo toda vez. O diferencial de memória se acumula com o uso.","features.desktop-automation#5#h":"Como funciona","features.desktop-automation#6#p":"Cada etapa ativa uma onda de cinco personas: Scout observa, Planner escolhe a próxima ação, Actor executa, Verifier verifica, Narrator relata o que aconteceu. O sidecar escolhe a ancoragem confiável mais econômica — UIA para aplicativos nativos, Playwright para navegadores, visão OmniParser quando nada mais oferece uma árvore útil.","features.desktop-automation#7#p":"Veja as páginas de conceitos para ontologia de segurança, hierarquia de ancoragem, interruptores de segurança e o modelo de lista branca de sessão.","start.glossary#1#td7.1":"Ava's simpler unit for what an action costs, so you are not doing token maths. Plans come with a monthly bundle.","start.glossary#1#td8.0":"API key","start.glossary#1#td8.1":"A private password that lets software use a paid service (like an AI model) on your account. You only need one if you want to bring your own.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Bring Your Own Key.\" Using your own API key instead of Ava's managed access. Optional — for people who already pay a provider directly.","start.glossary#1#td10.0":"Local-first","start.glossary#1#td10.1":"Your data lives on your own computer by default. Nothing is uploaded unless you switch on sync. \"Local is sacred.\"","start.glossary#1#td11.0":"Permission mode","start.glossary#1#td11.1":"How cautious Ava is before doing things — ask every time, ask for risky things only, or just go. You set the level.","start.glossary#1#td12.0":"Context window","start.glossary#1#td12.1":"How much text a model can hold in mind at once — its short-term memory. \"1M context\" means about a million words. Bigger = it can read more before forgetting.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"A side-by-side view of exactly what will change in a file — old on one side, new on the other — shown before Ava changes anything so you can approve it.","start.glossary#1#td14.0":"Repository (repo)","start.glossary#1#td14.1":"A project folder tracked for changes, usually with Git. If that means nothing to you yet, it is just \"the folder my project lives in.\"","start.glossary#1#td15.0":"Prompt","start.glossary#1#td15.1":"What you type to the AI — your question or instruction.","start.glossary#2#c":"Still stuck on a word? Ask Ava in Chat mode — \"what does X mean?\" — and she will explain it for your level.","models.routing#title":"Routing — how Ava picks models","models.routing#0#p":"Here is the short version: you never have to pick which AI model to use. Ava does it for you, choosing the best tool for each part of a job — the way a good manager hands the right task to the right person.","models.routing#1#p":"You pick one of three styles — Maestro, Supernova, or Aurora — and Ava sends each piece of work to the model that handles it best. Maestro is the default, it is live on every plan, and it is a good choice for almost everyone.","models.routing#2#h":"Why bother routing?","models.routing#3#p":"Putting the right model on each step costs less than running everything on one big expensive model — and gives better results, because each model does what it is best at. You get steady cost and high quality without ever needing to know which model is which.","models.routing#4#c":"All three styles work on platform credits and on your own keys. With your own key you can also skip routing and drive a single model directly. The full fleet breakdown is under \"Show me the details\".","models.routing#deeper#0#c":"The \"B\" numbers below are billions of parameters — roughly how big a model's brain is; bigger usually means smarter but slower and pricier. This is the under-the-hood detail; you never need it to use Ava.","models.routing#deeper#2#td5.0":"Conversa","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Orquestração de geração de imagens","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Visão","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (codificador de visão treinado do zero)","models.routing#deeper#2#td8.0":"Escrita de textos longos","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Residência de dados","models.routing#deeper#2#td9.1":"Misto (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Misto (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Apenas UE · pesos abertos","models.routing#deeper#2#td10.0":"Status","models.routing#deeper#2#td10.1":"Ativo · todos os planos","models.routing#deeper#2#td10.2":"Em breve","models.routing#deeper#2#td10.3":"Em breve","models.routing#deeper#2#td11.0":"Ideal para","concepts.modes#0#p":"Um modo é o estado mental em que a Ava se encontra — como um colega trocando de chapéu. Mesma pessoa, mesma memória sobre você, mas um construtor pensa diferente de um professor. Você escolhe o modo e isso muda como ela age e quais auxiliares ela traz. Mude a qualquer momento com o seletor de modos ou digite um atalho de dois caracteres.","concepts.modes#2#h":"Qual deles você quer?","concepts.modes#3#p":"Comece pelo que você está tentando fazer — o modo segue disso:","concepts.modes#4#li0":"Quero algo criado ou alterado → Código (>>). Você descreve, ela cria, mostrando cada alteração primeiro. A equipe completa de auxiliares entra em ação para tarefas maiores.","concepts.modes#4#li1":"Quero um plano antes de qualquer mudança → Plano (::). Ela pensa tudo e te entrega um plano para aprovar ou editar. Ela não tocará nos seus arquivos neste modo.","concepts.modes#4#li2":"Só quero conversar ou perguntar → Conversa (..). Um parceiro de pensamento com memória, notícias e clima. Sem alterações de arquivo, sem código — só conversa.","concepts.modes#4#li3":"Quero aprender algo → Ensinar (??). Um curso real feito para você: aulas, questionários, tudo. Grátis em todos os planos, para sempre. Perfeito se você é novo.","concepts.modes#4#li4":"Quero meu projeto verificado quanto a falhas de segurança → Segurança (!!). Uma equipe percorre a lista padrão de vulnerabilidades web comuns (as categorias \"OWASP\") e falhas conhecidas relatadas (chamadas \"CVEs\"), depois te entrega um relatório ordenado pela gravidade de cada problema. Este é focado em desenvolvedores — pule se não for o seu caso.","concepts.modes#4#li5":"Quero ideias → Brainstorming (**). Ela gera opções baseadas na sua situação real, aponta falhas nas fracas e refina as outras em próximos passos.","concepts.modes#4#li6":"Quero escrever um documento → Escrever (<<). Relatórios, propostas, cartas, artigos — ela rascunha em Markdown e exporta um doc Word ou PDF com marcação, refinando seção por seção. Sem código, só escrita.","concepts.modes#5#c":"A \"equipe de auxiliares\" (personas) roda inteiramente nos bastidores — você nunca fala com eles diretamente. Você apenas recebe uma resposta mais completa. Não precisa saber os nomes deles.","concepts.modes#6#c":"Você pode mudar de modo no meio da conversa. Sua memória é mantida; os especialistas reiniciam para se adequar ao novo modo.","concepts.tasks-journal#title":"Tarefas e diário","concepts.tasks-journal#0#p":"A Ava mantém três tipos de anotações para você, e é fácil confundi-las. O jeito rápido de lembrar: memória é o que ela sabe sobre você, tarefas são o que você ainda precisa fazer, e o diário é um registro de como as coisas foram. Veja quando usar qual.","concepts.tasks-journal#1#li0":"Memória — fatos persistentes. Preferências, decisões, padrões. Perguntada repetidamente, raramente criada manualmente.","concepts.tasks-journal#1#li1":"Tarefas — coisas a fazer. Itens de ação com prazos e status. Você marca como feitos quando concluídos.","concepts.tasks-journal#1#li2":"Diário — reflexão. Registro diário, entradas duplas (suas e observações da Ava sobre a sessão). Útil para rastrear humor, revisões de sessão, contexto para amanhã.","concepts.tasks-journal#2#p":"A Ava escreve em todas as três quando faz sentido. Você pode escrever em qualquer uma delas diretamente do painel. Nada está travado em um único lugar onde usa a Ava — uma tarefa que cria em um (digamos, a ferramenta de linha de comando) aparece em todos os outros lugares (como o aplicativo desktop), automaticamente.","concepts.permissions#title":"Permissões — seu botão de segurança","concepts.permissions#0#p":"Permissões são seu botão de segurança. Elas decidem quando a Ava pede sua aprovação antes de fazer algo no seu computador, versus apenas prosseguir. Você pode configurá-la para pedir sobre tudo, pedir apenas sobre o arriscado, ou confiar nela para rodar — e você pode mudar a qualquer momento. Se não tiver certeza, deixe no padrão e ficará tudo bem.","concepts.permissions#1#p":"A Ava tem 60 ferramentas (\"ferramentas\" são as ações que ela pode tomar — ler um arquivo, pesquisar na web, etc.). Cada ferramenta pertence a uma categoria (operações de arquivo, terminal, Git, web, mídia, banco de dados, sistema, documentos, memória, aprendizado). Toda chamada de ferramenta passa pelo portão de permissão (um ponto de verificação que decide se deve te perguntar primeiro) antes de rodar. Você controla o que é aprovado automaticamente, o que pergunta uma vez e o que sempre pergunta.","concepts.permissions#3#p":"Equilibrado é o padrão. Estrito quando você está auditando o comportamento dela (observando de perto para checar cada passo). Autônomo quando você quer que ela apenas vá.","concepts.permissions#4#c":"Autônomo não significa sem controle. Planos, perguntas de esclarecimento e solicitações explícitas de usuário ainda pausam para sua entrada. Operações irreversíveis (Git force-push, drops de banco de dados) sempre confirmam independentemente do modo.","concepts.interjection#title":"Guiando e parando a Ava","concepts.interjection#0#p":"Você está sempre no comando. Enquanto a Ava trabalha, você pode tanto empurrá-la suavemente para uma nova direção sem quebrar o ritmo, quanto pará-la imediatamente. Dois botões, dois resultados — é só isso que esta página trata.","concepts.interjection#1#p":"Ava executa até que seu plano seja concluído ou você a pare. Você tem duas formas de intervir (a palavra para isso é \"intervir\") enquanto ela está em execução.","concepts.interjection#2#h":"Intervir — guiar sem cancelar","concepts.interjection#3#p":"Digite uma nova mensagem enquanto a Ava trabalha. Ela finaliza sua chamada de ferramenta atual, lê sua mensagem e ajusta seu plano. Nenhum contexto é perdido. Use isso quando quiser redirecionar, adicionar informações ou mudar prioridades no meio da execução.","concepts.interjection#4#h":"Parada brusca — cancelar e limpar","concepts.interjection#5#p":"Pressione Escape (CLI), clique em Parar (extensão, IDE) ou digite um comando de parada. A execução atual é cancelada, chamadas de ferramentas pendentes são descartadas e a conversa fica pronta para um novo turno.","concepts.interjection#6#c":"Intervir primeiro. Parada brusca é para quando algo está realmente errado. Intervir mantém o fluxo vivo.","concepts.desktop-personas#title":"Personas de área de trabalho","concepts.desktop-personas#0#p":"Esta página é para os curiosos e para usuários avançados. \"Automação de área de trabalho\" (às vezes chamada de \"uso do computador\") significa que a Ava pode realmente clicar na sua tela e usar aplicativos por você — abrir Gmail, preencher um formulário, enviar uma mensagem — como uma pessoa no teclado. Para fazer isso com segurança, ela divide a tarefa entre cinco pequenos ajudantes, cada um com um papel estreito. Você nunca lida com eles diretamente; isto apenas mostra quem faz o quê.","concepts.desktop-personas#1#p":"Cada passo em uma trajetória de área de trabalho (uma execução da Ava guiando sua tela em direção a um objetivo) executa uma onda de cinco personas. Cada persona tem um trabalho e apenas um trabalho. A separação mantém os prompts concisos, as saídas estruturadas e o raciocínio cético por design.","concepts.desktop-personas#2#h":"Explorador","concepts.desktop-personas#3#p":"Relata o que está visível na tela agora. Nunca inventa elementos. Nunca planeja. Retorna um ScreenState JSON com IDs de elemento, nomes, bboxes, confiança e uma fonte de referência (UIA, Playwright DOM ou visão OmniParser).","concepts.desktop-personas#4#h":"Planejador","concepts.desktop-personas#5#p":"Decide a única próxima ação. Uma ação por passo — nunca em lote. Preferência por caminhos reversíveis. Classifica risco conforme a ontologia de segurança. Produz um ProposedAction JSON com kind, target, params, riskClass, reasoning e uma previsão de expectedPostState.","concepts.desktop-personas#6#h":"Executor","concepts.desktop-personas#7#p":"Executa exatamente o que o Planejador propôs — após o portão de aprovação ter sido liberado. Sem improvisação. Sem reexecução. Falha é relatada fielmente e o Verificador cuida do próximo movimento.","concepts.desktop-personas#8#h":"Verificador","concepts.desktop-personas#9#p":"Verifica se a ação foi executada. Compara o novo ScreenState contra a previsão do Planejador. Retorna verified, deviated, or rollback_needed. Também executa detecção de loop — repetir uma ação que já teve sucesso é um desvio, não uma verificação.","concepts.desktop-personas#10#h":"Narrador","concepts.desktop-personas#11#p":"A única voz que o usuário ouve durante uma trajetória. Uma frase no passado por passo (\"Abriu o Gmail.\", \"Clicou em Redigir.\"). Também escreve o registro de auditoria estruturado. Diz quando algo deu errado — nunca esconde um problema.","concepts.desktop-safety#title":"Ontologia de segurança de área de trabalho","concepts.desktop-safety#0#p":"Em resumo: antes de a Ava clicar em qualquer coisa na sua tela, ela classifica a ação pelo nível de risco. Ler a tela? Inofensivo. Enviar dinheiro ou excluir algo? Ela sempre para e pergunta a você primeiro — todas as vezes, sem exceções. As cinco etiquetas abaixo são apenas os degraus dessa escada de risco. Isso é detalhe para usuário avançado, mas a conclusão é simples: o perigoso sempre precisa do seu sim.","concepts.desktop-safety#1#p":"Toda ação proposta é classificada em uma das cinco classes de risco. A classificação combina três sinais — o que é o alvo na tela, uma descrição em linguagem simples (\"legenda semântica\" — palavras próprias da Ava sobre o que ela está vendo), e as configurações da ação — e eleva o nível (trata como mais arriscado) quando discordam. Um falso positivo (perguntar quando não era necessário) é apenas um incômodo. Um falso negativo (não perguntar quando deveria) é um incidente que encerra o produto.","concepts.desktop-safety#2#h":"As cinco classes","concepts.desktop-safety#3#li0":"Observacional — ler árvore UIA, captura de tela, passar o mouse. Sempre permitido automaticamente.","concepts.desktop-safety#3#li1":"Navegação — rolar, mover foco, abrir menu. Permitido automaticamente no modo Drive."},"fr":{"start.for-non-coders#title":"Jamais écrit de code ? Commencez ici","start.for-non-coders#0#p":"Si vous n'avez jamais écrit une ligne de code, vous êtes exactement la personne pour qui Ava est faite. Vous n'avez pas besoin d'apprendre de jargon pour commencer — vous lui parlez simplement, comme vous le feriez avec un ami compétent. Cette page est votre point d'entrée complet.","start.for-non-coders#1#h":"Ce que vous pouvez faire aujourd'hui, sans aucune expérience","start.for-non-coders#2#li0":"Demandez-lui tout, en mots simples — « que fait ce fichier ? », « pourquoi ma page est blanche ? », « qu'est-ce qu'une base de données ? ». Elle répond en langage clair et se souvient de la conversation.","start.for-non-coders#2#li1":"Apprenez quelque chose à partir de zéro — dites « apprends-moi Python depuis zéro » et elle vous construit un vrai cours avec des leçons et des quiz. C'est toujours gratuit.","start.for-non-coders#2#li2":"Faites réaliser quelque chose — décrivez ce que vous voulez (« un bouton qui télécharge mes notes ») et elle l'écrit, en vous montrant chaque changement avant qu'il ne se produise.","start.for-non-coders#3#h":"Vous n'avez pas besoin de tout comprendre","start.for-non-coders#4#p":"Ava dispose de beaucoup de mécanismes sous le capot — modes, modèles, spécialistes, routage. Vous verrez ces mots autour de l'application et dans cette documentation. Voici le secret : vous pouvez ignorer presque tout cela. Ava choisit les bons outils et les bons assistants pour vous automatiquement. Les pages techniques sont là quand vous aurez envie d'en savoir plus, pas parce que vous en avez besoin pour commencer.","start.for-non-coders#5#h":"Une première approche douce","start.for-non-coders#6#li0":"Installez Ava (page suivante) et ouvrez le chat.","start.for-non-coders#6#li1":"Tapez une vraie question que vous avez. N'importe quoi. Voyez comment elle répond.","start.for-non-coders#6#li2":"Essayez le mode Apprentissage : tapez « apprends-moi » et un sujet. Suivez le fil.","concepts.memory#1#p":"Ava dispose d'une mémoire persistante (\\\"persistante\\\" signifie qu'elle reste active après avoir fermé l'application) qui survit à travers les conversations, les projets et les machines si vous activez la synchronisation (la synchro copie votre mémoire entre vos appareils). Ce n'est pas un historique de chat. C'est une compréhension structurée et consultable de qui vous êtes, de ce que vous aimez et de ce que vous avez décidé.","concepts.memory#2#h":"Cinq couches","concepts.memory#3#li0":"Extraire — les faits clés capturés à partir de chaque message en temps réel.","concepts.memory#3#li1":"Réfléchir — une analyse plus approfondie s'exécute à la fin des sessions significatives. Modèles, thèmes, contradictions.","concepts.memory#3#li2":"Accumuler — les corrections et préférences se cumulent sur plusieurs semaines et mois.","concepts.memory#3#li3":"Analyser — le moteur de graphe relie les mémoires connexes et signale les contradictions lorsque de nouvelles informations entrent en conflit avec les anciennes.","concepts.memory#3#li4":"Consolider — les mémoires similaires fusionnent ; les obsolètes sont supprimées. La mémoire devient plus précise avec le temps, pas plus bruyante.","concepts.memory#4#c":"Les cinq couches ci-dessus fonctionnent automatiquement — vous n'avez jamais besoin de les gérer. Elles sont là pour que vous voyiez que la mémoire s'améliore vraiment avec le temps plutôt que de devenir un amas de désordre.","concepts.memory#5#h":"Rappel","concepts.memory#6#p":"Lorsque vous posez une question, Ava recherche dans la mémoire par sens (\\\"recherche sémantique\\\" — elle comprend ce que vous voulez dire, donc elle trouve la bonne mémoire même si vous la formulez différemment), pas seulement par correspondance exacte de mots. Des filtres spécifiques au mode s'exécutent en parallèle : le mode Chat récupère le contexte personnel, le mode Travail récupère les décisions de projet et les modèles de code.","concepts.memory#7#c":"La mémoire est limitée par utilisateur et par projet (vos souvenirs sont les vôtres, séparés par personne et par projet). Les secrets et identifiants (mots de passe, clés) sont bloqués à la limite d'enregistrement — ils ne peuvent jamais atterrir dans la mémoire.","concepts.desktop-grounding#title":"Hiérarchie de l'ancrage bureau (Aperçu)","concepts.desktop-grounding#0#c":"Aperçu — comment Scout décide quelle source d'ancrage utiliser à chaque étape.","concepts.desktop-grounding#1#p":"Avant qu'Ava puisse cliquer sur un bouton, elle doit vraiment comprendre ce qui est à l'écran et où se trouvent les éléments — c'est l'« ancrage » (déterminer ce qu'est chaque élément à l'écran et sa position exacte). Elle dispose de trois méthodes et choisit la plus fiable qui fonctionne pour l'application que vous utilisez. Ceci est un détail technique avancé ; l'essentiel est qu'elle privilégie des méthodes solides et précises plutôt que de deviner à partir d'une image.","concepts.desktop-grounding#2#p":"Trois niveaux, évalués dans l'ordre. La source fiable la moins coûteuse l'emporte.","concepts.desktop-grounding#3#h":"1. Fenêtre navigateur → Playwright DOM","concepts.desktop-grounding#4#p":"Si la fenêtre active est un navigateur web, Ava lit la structure propre de la page (le « DOM » — la liste sous-jacente de ce qui se trouve sur une page) au lieu de deviner à partir de l'image. Lire la structure est environ 10× plus fiable que de regarder les pixels — elle sait exactement où se trouve chaque bouton et quand la page a fini de charger. C'est le chemin principal pour tout ce qui est sur le web, pas une solution de secours.","concepts.desktop-grounding#5#h":"2. Application native avec UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Pour les applications de bureau classiques sur Windows, Ava lit une carte d'accessibilité intégrée (« UIA », les mêmes données que les lecteurs d'écran utilisent pour décrire une fenêtre) — elle liste chaque contrôle, son nom et sa position. Si cette carte renvoie au moins cinq éléments utilisables et nommés, elle lui fait confiance et l'utilise.","concepts.desktop-grounding#7#h":"3. UIA vide ou inutilisable → Vision OmniParser","concepts.desktop-grounding#8#p":"Lorsque cette carte manque ou est inutile (certaines applications, jeux et écrans distants n'en fournissent pas), Ava revient à regarder réellement une capture d'écran. Un outil de vision (OmniParser) repère les zones cliquables et identifie ce qu'est chacune, transformant l'image en une liste sur laquelle elle peut agir — combiné avec ce que la carte d'accessibilité a pu fournir.","concepts.desktop-grounding#9#c":"OmniParser nécessite un accord explicite la première fois qu'Ava en a besoin, avec une invite de confidentialité claire. Les utilisateurs BYOK peuvent pointer vers leur propre déploiement local OmniParser.","concepts.desktop-kill-switches#title":"Arrêts d'urgence du bureau (Aperçu)","concepts.desktop-kill-switches#0#c":"Aperçu — trois façons indépendantes d'interrompre une trajectoire en cours. L'une d'elles suffit.","concepts.desktop-kill-switches#1#p":"Un « interrupteur d'arrêt » est exactement ce que le nom suggère — une méthode d'urgence pour arrêter Ava instantanément lorsqu'elle contrôle votre écran. Ce qui rassure : il y en a trois, chacun construit séparément, donc si l'un échoue, un autre fonctionne toujours. Vous n'avez pas besoin de connaître les trois. Sachez simplement que lorsque quelque chose semble incorrect, vous pouvez toujours l'arrêter, et l'arrêt le plus fort (l'arrêt panique ci-dessous) ne dépend pas de la coopération d'Ava.","concepts.desktop-kill-switches#2#p":"Après avoir lu tous les incidents publics d'autonomie (cas réels où des agents IA ont ignoré les commandes d'arrêt, supprimé des archives d'e-mails, effacé des disques), nous avons créé trois interrupteurs d'arrêt dans trois couches différentes. Aucun ne dépend du modèle d'IA lui-même — si Ava est bloquée ou ne répond pas, vous pouvez toujours l'arrêter.","concepts.desktop-kill-switches#3#h":"Pause — barre d'espace ou le bouton Pause","concepts.memory#title":"Mémoire — comment Ava se souvient de vous","concepts.memory#0#p":"En termes simples : Ava se souvient de vous. Dites-lui quelque chose une fois — ce que vous aimez, une décision que vous avez prise — et elle la garde, pour que vous n'ayez pas à vous répéter dans la prochaine discussion ou la semaine prochaine. C'est l'essentiel. Les couches ci-dessous expliquent simplement comment elle maintient cette mémoire ordonnée avec le temps.","reference.config#title":"Configuration","reference.config#0#p":"Cette page indique où Ava conserve ses paramètres et fichiers sur votre ordinateur. Vous n'aurez presque jamais besoin de les modifier manuellement — l'application gère tout pour vous. Elle est là si vous souhaitez consulter, sauvegarder ou partager ces fichiers vous-même.","reference.config#1#p":"Ava lit la configuration (ses paramètres enregistrés) selon deux niveaux. Les paramètres globaux — ceux qui s'appliquent partout — se trouvent dans un dossier nommé ~/.ava/ (le \"~\" est une abréviation pour votre dossier personnel). Les paramètres spécifiques à un projet vivent dans un dossier .ava/ à l'intérieur du projet lui-même.","reference.config#2#h":"Général — ~/.ava/","reference.config#3#li0":"settings.json — préférences du modèle, mode de permission, personnalité, langue.","reference.config#3#li1":"memory/ — vos mémoires globales (préférences, décisions qui s'appliquent partout).","reference.config#3#li2":"tasks.json — liste des tâches transverses aux projets.","reference.config#3#li3":"journal/ — entrées de journal quotidien, organisées par date.","reference.config#4#h":"Projet — .ava/","reference.config#5#li0":"instructions.md — instructions spécifiques au projet qu'Ava charge toujours. Contexte durable (« nous utilisons pnpm, pas npm », « les clés API sont dans 1Password »).","reference.config#5#li1":"context.md — notes de projet libres optionnelles.","reference.config#5#li2":"memory/ — mémoires limitées à ce projet.","reference.config#5#li3":"datasets/config.json — configuration d'enregistrement de jeu de données (optionnel).","reference.config#6#c":"Ajoutez .ava/ à votre .gitignore (une liste de fichiers que Git ignore pour le projet partagé) si vous ne souhaitez pas partager vos mémoires avec votre équipe. Gardez instructions.md dans le dépôt (le dossier de projet partagé) — c'est ainsi qu'Ava apprend les conventions du projet.","reference.shortcuts#title":"Raccourcis clavier","reference.shortcuts#0#p":"Les raccourcis clavier sont des gains de temps optionnels — chacun d'eux est aussi un bouton que vous pouvez cliquer. Consultez cette section uniquement si vous voulez piloter Ava plus rapidement depuis le clavier.","reference.shortcuts#1#p":"Raccourcis par interface (les trois endroits où Ava fonctionne : l'extension VS Code, l'application de bureau et le terminal). Personnalisez-les dans les paramètres de chaque interface. Pas besoin de mémoriser la liste ci-dessous.","reference.models#11#h":"Apportez votre propre clé","reference.models#12#p":"Une « clé API » est un mot de passe privé qui permet à un logiciel d'utiliser un service payant sur votre propre compte. « BYOK » signifie simplement « apportez votre propre clé » — utiliser la vôtre plutôt que la nôtre. Collez votre clé API dans les paramètres. Les requêtes BYOK partent directement d'Ava vers le fournisseur (la société qui gère le modèle) — elles ne transitent pas par notre infrastructure et ne consomment pas de jetons de plateforme. Vous payez le fournisseur ; nous ne voyons pas le trafic.","reference.models#14#c":"Pour les scores de performance, les balises de capacités et le filtrage côte à côte, consultez la page complète des Modèles à ava-supernova.com/models. Les tarifs affichés ci-dessus sont notre meilleure estimation des grilles tarifaires de chaque fournisseur au moment de la publication — vérifiez toujours le site du fournisseur avant de lancer une charge de travail.","reference.personas#title":"Orchestration des rôles","reference.personas#0#p":"Un « persona » est un rôle d'assistant qu'Ava joue dans l'ombre pour les tâches complexes — un explorateur, un planificateur, un vérificateur de faits. Vous ne leur parlez jamais directement et vous n'avez pas besoin de comprendre cette page pour utiliser Ava. Elle est là si vous êtes curieux de savoir comment elle découpe une grande tâche en une petite équipe d'experts.","reference.personas#1#p":"24 spécialistes répartis sur 5 équipes de modes. Le Chef d'orchestre (l'assistant qui coordonne le reste) décide quelle équipe intervient, dans quel ordre et avec quel contexte. Le mode Discussion n'a aucun persona — c'est Ava elle-même.","reference.personas#2#h":"Comment l'orchestration fonctionne","reference.personas#3#li0":"Vous envoyez un message en mode Planification, Enseignement, Sécurité ou Idéation (ou une demande complexe de Travail).","reference.personas#3#li1":"Le Chef d'orchestre lit la demande, choisit l'équipe de mode et construit un plan d'exécution — certains rôles s'exécutent séquentiellement, d'autres par vagues parallèles.","reference.personas#3#li2":"Chaque persona dispose de son propre prompt système, d'une liste autorisée d'outils restreinte et d'un pool de contexte partagé contenant ce que les précédents ont trouvé.","reference.personas#3#li3":"Le dernier persona produit un résumé, un plan ou un rapport, selon le mode.","reference.personas#3#li4":"Ava vous présente le résultat. Vous validez, ajustez ou redirigez.","reference.personas#4#p":"La liste complète ci-dessous est à titre de référence uniquement — pas besoin de mémoriser qui fait quoi. Ava assemble la bonne équipe pour vous.","reference.personas#6#c":"Le mode Travail invoque uniquement l'équipe complète pour les tâches complexes. Les modifications simples font intervenir Ava directement — sans surcharge d'orchestration.","concepts.desktop-kill-switches#4#p":"Se met en pause à la prochaine étape. Peut être repris. À utiliser quand vous souhaitez intervenir sans perdre le fil conducteur.","concepts.desktop-kill-switches#5#h":"Arrêt — Touche Échap ou le bouton Arrêt","concepts.desktop-kill-switches#6#p":"Interruption propre. Le narrateur récapitule ce qui a été accompli jusqu'ici. Impossible de reprendre. L'historique d'audit est validé.","concepts.desktop-kill-switches#7#h":"Arrêt d'urgence — triple touche Échap ou Ctrl+Maj+K","concepts.desktop-kill-switches#8#p":"C'est l'arrêt ultime. Un petit programme de surveillance indépendant force l'arrêt de la partie d'Ava qui pilote votre écran. Il n'attend pas la réponse de l'IA, ne nécessite pas que la fenêtre de l'application soit fonctionnelle, et ignore l'état du système — il coupe tout net. C'est celui qu'il faut utiliser quand quelque chose tourne vraiment mal.","concepts.desktop-kill-switches#9#p":"Ces trois méthodes fonctionnent aussi depuis l'application compagnon. N'importe quel pilote peut mettre fin à l'action.","reference.tools#title":"Référentiel des outils","reference.tools#0#p":"Voici la liste complète de tous les outils dont dispose Ava — un « outil » désignant simplement une action précise qu'elle peut effectuer, comme lire un fichier ou lancer une recherche. Inutile de lire cette page : Ava choisit toujours le bon outil par elle-même. Elle est là pour répondre à votre curiosité sur ce qu'elle peut faire exactement.","reference.tools#1#p":"La boîte à outils intégrée complète. Tous ces outils sont enregistrés dans le moteur central (le socle technique sous-jacent aux trois interfaces) et disponibles pour Ava lorsque le mode et les permissions le permettent. Vous pouvez filtrer par catégorie ou niveau de risque.","reference.tools#2#p":"Pas besoin de tout apprendre par cœur — le tableau ci-dessous n'est qu'une fiche mémo.","reference.tools#4#h":"Niveaux de risque","reference.tools#5#li0":"Sûr — lit des éléments sans rien modifier. file_read, glob (recherche de fichiers par motif de nom), grep (recherche de texte dans les fichiers), git_status (Git est le système qui suit les modifications de votre projet).","reference.tools#5#li1":"Écriture — modifie des fichiers, enregistre une sauvegarde de votre travail (un « commit »), ou génère quelque chose de nouveau. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Dangereux — exécute des commandes sur votre ordinateur (le « shell »), contrôle le bureau, accède à Internet, ou interroge des bases de données. bash, browser, desktop_*.","reference.tools#6#c":"Les spécialistes par persona disposent de leurs propres listes d'autorisation. Scout peut lire mais pas écrire. Builder a un accès total. Challenger n'a aucun outil — sa mission est de remettre en question le plan.","reference.models#title":"Modèles","reference.models#0#p":"Un « modèle » est le cerveau de l'IA qui réfléchit — Qwen, DeepSeek, Mistral et d'autres. Cette page recense tous les modèles utilisables par Ava. En bref : vous n'avez pas à en choisir un. Ava sélectionne le bon modèle pour chaque étape elle-même. Continuez à lire uniquement si vous souhaitez comprendre ou modifier ce choix.","reference.models#1#p":"Tous les modèles accessibles à Ava, ainsi que les trois stratégies d'orchestration — les règles qui déterminent quel modèle traite quelle partie d'une tâche. Choisissez un mode de routage et laissez Ava gérer l'envoi, ou sélectionnez un modèle unique et passez directement le routage.","reference.models#2#h":"Modes de routage","reference.models#3#p":"Trois stratégies orchestrées. Le même pipeline de personas (l'équipe réduite d'experts spécialisés que Ava mobilise en coulisses) s'exécute sur les trois ; seule la flotte de modèles sous-jacente change. Choisissez un mode dans le sélecteur de modèles et Ava s'occupe du reste. Chaque carte ci-dessous détaille les spécialistes constitutifs auxquels le chef d'orchestre délègue.","reference.models#4#p":"Pas besoin de mémoriser les cartes ci-dessous — elles sont là pour vous montrer de quoi est composée chaque stratégie.","reference.models#6#c":"Aurora est volontairement réservée exclusivement à Mistral. Si un modèle Mistral n'est pas disponible, le routeur renvoie une erreur au lieu de rediriger ailleurs — c'est la garantie de la pile UE. Choisissez Maestro ou Supernova pour une dégradation gracieuse.","reference.models#7#c":"Les trois modes sont universellement disponibles — avec les crédits de la plateforme ou avec vos propres clés. BYOK ajoute l'option de contourner l'orchestration et de piloter un modèle unique directement.","reference.models#8#h":"Modèles gérés par la plateforme","reference.models#9#p":"Disponibles sur tous les plans, y compris l'offre gratuite. Les jetons (les unités de mesure du texte pour l'IA — environ trois-quarts de mot chacun) sont déduits de votre forfait. Les clés (les mots de passe privés qui déverrouillent chaque modèle payé) sont renouvelées et surveillées par la plateforme — rien à configurer de votre côté.","reference.project-context#title":"Contexte du projet","reference.project-context#0#p":"Cela explique comment Ava consulte votre projet avant de commencer — les fichiers qu'elle examine pour comprendre ce sur quoi vous travaillez. Vous n'avez pas besoin de configurer quoi que ce soit ; elle le fait toute seule. Lisez ceci si vous voulez savoir où placer une note pour qu'elle la voie toujours.","reference.project-context#1#p":"Lorsque vous ouvrez un projet, Ava charge plusieurs couches de contexte (des informations en arrière-plan qu'elle garde en tête). Comprendre ces couches vous aide à placer les informations au bon endroit.","reference.project-context#2#h":"Chargé automatiquement","reference.project-context#3#li0":".ava/instructions.md — traitée comme une guidance durable et prioritaire. Toujours dans le contexte.","reference.project-context#3#li1":".ava/context.md — notes libres. Chargées, priorité inférieure.","reference.project-context#3#li2":"README.md — analysée lors du premier lancement pour un résumé du projet.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — les petits fichiers qui listent la configuration du projet ; lus pour détecter le langage, le framework et la commande de test.","reference.project-context#3#li4":".gitignore — la liste des fichiers à exclure du contrôle de version ; respectée par tous les outils de fichiers (glob, grep, project_index).","reference.project-context#4#h":"Chargé à la demande","reference.project-context#5#p":"« À la demande » signifie qu'Ava ne récupère ces éléments que lorsqu'une tâche en a réellement besoin, et non d'emblée.","reference.project-context#6#li0":"Index du projet — une carte structurée de vos fichiers et des pièces nommées à l'intérieur (fonctions, classes — « symboles ») et de leur connexion (« imports »). Construit paresseusement, c'est-à-dire uniquement quand Ava en a besoin.","reference.project-context#6#li1":"Historique Git — le registre des changements passés ; extrait lorsque git_status, git_diff ou git_create_pr sont appelés (Git est l'outil qui suit chaque changement du projet ; « PR » est une demande de fusion, un lot proposé de modifications).","reference.project-context#6#li2":"Mémoire — les entrées sont appariées par sens (« sémantiquement ») et injectées tour par tour, et non toutes ensemble.","reference.project-context#7#c":"Placez les conventions dans instructions.md. Placez les notes dans context.md. Laissez la mémoire capturer le reste d'elle-même.","features.unified-panel#title":"Panneau unifié","features.unified-panel#0#p":"En termes simples : tout ce qu'Ava fait se trouve dans une seule fenêtre, ainsi vous n'avez jamais besoin de fouiller dans les onglets pour le retrouver.","features.unified-panel#1#p":"Un seul panneau pour le chat, le tableau de bord, la mémoire, les tâches et le journal. Aucun basculement de contexte entre les fenêtres. La barre latérale sélectionne ce que vous consultez ; la zone principale s'adapte automatiquement.","features.unified-panel#2#p":"L'état de la conversation persiste même si vous naviguez ailleurs — ouvrez la mémoire, vérifiez une tâche, puis revenez. Le chat est toujours là, toujours en cours si Ava continue de fonctionner.","features.unified-panel#3#c":"Le panneau unifié est un concept d'extension et d'IDE. L'interface web utilise les onglets du navigateur.","features.knowledge-packs#title":"Packs de connaissances","features.knowledge-packs#0#p":"En termes simples : remettez à Ava un dossier de vos documents personnels, et elle pourra les lire pour répondre à vos questions. Un « pack de connaissances » est simplement ce regroupement de fichiers — vos documents de référence dont elle a l'autorisation de s'alimenter.","features.knowledge-packs#1#p":"Déposez un dossier de documents de référence (spécifications, RFC, comptes-rendus de réunion, docs API) dans un pack de connaissances. Ava peut intégrer les éléments pertinents dans le contexte lorsque la conversation aborde le sujet.","features.knowledge-packs#2#p":"Les packs sont indexés localement. La recherche est sémantique — Ava trouve le bon document grâce au sens, et non au nom de fichier. (« Sémantique » signifie qu'elle identifie le contenu du document, vous n'avez donc pas besoin de vous souvenir des mots exacts ni du nom de fichier.) Les packs peuvent être partagés avec une équipe ou conservés en privé.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Besoin d'un rapport, d'un e-mail ou d'un document rédigé ? Ava peut le rédiger et vous remettre un vrai fichier Word, Excel ou PDF que vous pouvez ouvrir et modifier comme n'importe quel autre.","features.office-suite#1#p":"Rapports, e-mails et documents — rédigés, mis en forme et exportés vers des formats natifs (.docx est Word, .xlsx est Excel, .pdf est un PDF).","features.office-suite#2#li0":"report_generate — un .docx structuré qui tire des données des tâches, du journal, de la mémoire et de l'état du projet.","features.office-suite#2#li1":"email_draft — e-mail avec ton ajusté vers un fichier .docx.","features.office-suite#2#li2":"document_manage — créer, lire, modifier, exporter entre Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Utile quand Ava écrit pour vous — rapports d'avancement, présentations de lancement, mises à jour clients. Le .docx arrive dans votre projet où vous pouvez le peaufiner.","features.dashboard-library#title":"Bibliothèque du tableau de bord","features.dashboard-library#0#p":"En termes simples : une seule étagère contenant tout ce que vous et Ava avez créé et discuté, pour que rien ne se perde.","features.dashboard-library#1#p":"Une vue consultable de tout ce qu'Ava a produit avec vous — images générées, vidéos, audio, documents — ainsi que vos conversations, mémoires et tâches. Un seul endroit pour retrouver quelque chose que vous avez fait la semaine dernière.","features.document-preview#title":"Aperçu de document","features.document-preview#0#p":"En termes simples : jetez un coup d'œil à l'intérieur d'un document là où vous êtes, sans avoir à ouvrir un programme séparé pour le lire.","features.document-preview#1#p":"Faites un clic droit sur un fichier Word, Excel, PDF, CSV, HTML ou Markdown dans votre projet — prévisualisez-le en ligne sans quitter l'éditeur. Utile pour lire du matériel de référence généré par Ava ou des fichiers qu'un collaborateur a déposés.","features.daily-briefing#title":"Briefing quotidien","features.daily-briefing#0#p":"En termes simples : un court message « voici où vous en étiez » chaque matin, pour que vous puissiez reprendre sans tout relire.","features.daily-briefing#1#p":"Résumé matinal : journal d'hier, tâches en cours, état du projet et tous les rappels qu'Ava a définis. Optionnel — activez-le dans les paramètres.","features.daily-briefing#2#p":"Le briefing utilise la mémoire pour mettre en avant le contexte pertinent (« la dernière fois que vous avez travaillé sur le flux d'authentification, vous aviez noté vouloir revoir la stratégie de rafraîchissement du jeton »). Pas un fil d'actualité — un point ciblé.","features.workflows#title":"Flux de travail","features.workflows#0#p":"En termes simples : apprenez à Ava une routine que vous faites sans cesse, donnez-lui un nom, et elle peut relancer l'ensemble sur demande. Un « flux de travail » est simplement cette routine enregistrée — un ensemble d'étapes qu'Ava répète pour vous.","features.workflows#1#p":"Enregistrez une séquence d'étapes que vous trouvez répétitives — revue de code → exécuter les tests → rédiger les notes de version → brouillonner l'email. Un flux de travail est un plan réutilisable qu'Ava peut rejouer avec différentes entrées.","features.workflows#2#p":"Les flux de travail sont stockés par projet dans un dossier nommé .ava/workflows/ à l'intérieur de votre projet. Partagez-les avec votre équipe en validant le dossier (en le sauvegardant dans votre projet partagé pour que les collègues l'aient aussi).","features.events#title":"Événements et notifications","features.events#0#p":"En termes simples : pendant qu'Ava travaille, vous obtenez une liste étape par étape claire de ce qu'elle fait, et une alerte quand un travail long termine pour que vous puissiez vous éloigner.","features.events#1#p":"Pendant qu'Ava tourne, vous voyez des mises à jour structurées, pas un mur de texte. Chaque appel d'outil, chaque transfert de persona, chaque delta diffusé est un événement discret dans l'interface — développable pour les détails, repliable pour la vue d'ensemble.","features.events#2#p":"Les exécutions en arrière-plan émettent des notifications au niveau du système d'exploitation quand elles terminent. Vous pouvez partir d'une longue compilation et Ava vous dira quand elle est finie.","features.personality#title":"Designer de personnalité","features.personality#0#p":"En termes simples : réglez comment Ava vous parle — bavard ou bref, formel ou décontracté, plus ou moins d'humour — pour qu'elle sonne comme vous aimez.","features.personality#1#p":"Formez la façon dont Ava vous parle. Ton, énergie, verbeuxité (combien elle dit), formalité, humour. Curseurs et préréglages — ingénieur concis, mentor chaleureux, collègue sec, ou votre propre mélange.","features.personality#2#p":"La personnalité affecte la formulation, pas la compétence. Elle utilise toujours les mêmes outils et suit les mêmes règles d'autorisation. Son nom est verrouillé sur Ava — c'est non négociable.","features.release-notes#title":"Notes de version","features.release-notes#0#p":"En termes simples : une liste mise à jour de ce qui est nouveau et ce qui a été corrigé à chaque mise à jour, pour que vous puissiez voir ce qui a changé.","features.release-notes#1#p":"Journal des modifications dans l'application (un journal des modifications est l'historique des changements). Chaque version livrée avec ses points forts, corrections de bugs et changements cassants (modifications qui peuvent nécessiter d'ajuster votre utilisation). La version publique est maintenue sur le site web à ava-supernova.com/releases.","troubleshooting.logs#4#c":"Les journaux peuvent contenir des extraits des fichiers du projet qu'Ava a lus lors d'une session. Veuillez les examiner avant de les partager.","troubleshooting.support-request#title":"Déposer une demande d'assistance","troubleshooting.support-request#0#p":"En clair : si quelque chose ne fonctionne pas et que les correctifs ci-dessus n'ont pas aidé, faites-le-nous savoir. La méthode la plus simple consiste à simplement demander à Ava de s'en charger pour vous.","troubleshooting.support-request#1#p":"Si un problème n'est pas couvert par les erreurs courantes, déposez un ticket de support (envoyez une demande d'aide à notre équipe). Vous pouvez le faire directement dans Ava (sans formulaire à remplir) ou via notre site web.","troubleshooting.support-request#2#h":"Depuis Ava","troubleshooting.support-request#3#p":"Demandez-lui de le faire. « Ava, peux-tu déposer un ticket de support à ce sujet ? » Elle invoque support_request, joint le contexte de session pertinent (avec les identifiants masqués), et l'envoie. C'est le chemin le plus rapide.","troubleshooting.support-request#4#h":"Via le site web","troubleshooting.support-request#5#p":"Visitez ava-supernova.com/support. Choisissez une catégorie (bug, fonctionnalité, compte, sécurité, général) et décrivez ce qui s'est produit. Nous répondons en un jour ouvrable.","troubleshooting.support-request#6#h":"Ce qu'il faut inclure","troubleshooting.support-request#7#li0":"Ce que vous tentiez de réaliser.","troubleshooting.support-request#7#li1":"Ce qui s'est réellement produit.","troubleshooting.support-request#7#li2":"Quelle interface (extension, IDE, CLI, compagnon) et quelle version.","troubleshooting.support-request#7#li3":"Tout message d'erreur ou extrait de journal. Masquez les identifiants en premier.","troubleshooting.security-disclosure#title":"Signaler des problèmes de sécurité","troubleshooting.security-disclosure#0#p":"En clair : si vous avez repéré un moyen de compromettre Ava ou de la détourner (une « vulnérabilité » — une faille de sécurité), merci de nous en informer en privé d'abord afin que nous puissions la corriger avant que quiconque n'en profite. Voici comment procéder.","troubleshooting.security-disclosure#1#p":"Vulnérabilité détectée ? Merci. Nous prenons chaque signalement au sérieux et travaillons avec vous sur la correction avant toute divulgation publique (avant que le problème ne soit annoncé officiellement).","troubleshooting.security-disclosure#2#h":"Comment signaler","troubleshooting.security-disclosure#3#li0":"Envoyez un courriel à security@ava-supernova.com avec une description, les étapes de reproduction et le délai de divulgation souhaité.","troubleshooting.security-disclosure#3#li1":"Ou déposez un ticket de support avec la catégorie « sécurité » — même file de traitement.","troubleshooting.security-disclosure#3#li2":"Nous accusons réception sous 24 heures.","troubleshooting.security-disclosure#4#h":"Nos engagements","troubleshooting.security-disclosure#5#li0":"Divulgation coordonnée — nous convenons d'un calendrier avec vous avant toute publication. La durée par défaut est de 90 jours.","troubleshooting.security-disclosure#5#li1":"Crédits — vous serez crédité dans les notes de correction, sauf si vous préférez rester anonyme.","troubleshooting.security-disclosure#5#li2":"Aucune représaille légale — la recherche de bonne foi est la bienvenue. Nous n'engagerons aucune procédure judiciaire contre vous.","troubleshooting.security-disclosure#6#c":"La page de sécurité sur ava-supernova.com/security détaille notre position complète — garanties d'architecture, outil de masquage, contrôles d'accès.","troubleshooting.common-errors#title":"Erreurs courantes","troubleshooting.common-errors#0#p":"La plupart des erreurs ont une cause courte et précise. Voici les plus fréquentes et comment les résoudre. Ne vous inquiétez pas si le vocabulaire semble technique — chaque point ci-dessous vous dit ce que vous voyez réellement et exactement quoi faire.","troubleshooting.common-errors#1#h":"Le modèle ne répond pas","troubleshooting.common-errors#2#p":"Ce que vous voyez : Ava se tait et ne répond pas.","troubleshooting.common-errors#3#p":"Vérifiez l'indicateur d'état dans l'en-tête du chat. S'il indique « en cours de connexion », votre fournisseur (le service IA avec lequel Ava communique) est joignable mais lent — attendez trente secondes. S'il indique « indisponible », Ava a automatiquement basculé vers le modèle suivant dans la chaîne (elle a changé pour un modèle de secours). Si rien du tout, vérifiez votre clé API dans Paramètres et testez la connexion. (Une clé API est le mot de passe privé qui permet à Ava d'utiliser un service IA payant.)","troubleshooting.common-errors#4#h":"Échec de l'appel d'outil","troubleshooting.common-errors#5#p":"Ce que vous voyez : l'une des étapes d'Ava (un « appel d'outil » — lire un fichier, exécuter une commande, etc.) affiche une erreur rouge au lieu de se terminer.","troubleshooting.common-errors#6#p":"Cliquez sur l'appel d'outil échoué pour voir l'erreur. Causes fréquentes : elle a tenté de toucher un fichier hors de votre dossier de projet, ce qui est bloqué intentionnellement pour votre sécurité (cette garde s'appelle la protection contre la « traversée de chemin » — elle l'empêche de sortir du dossier dans lequel vous travaillez) ; une commande nécessitant d'être exécutée dans un autre dossier ; ou un fichier déplacé depuis la dernière fois qu'Ava l'a vu. Dites-lui ce qui s'est mal passé — elle réessayera avec les corrections.","troubleshooting.common-errors#7#h":"La mémoire ne se souvient pas","troubleshooting.common-errors#8#p":"Ce que vous voyez : Ava ne trouve pas quelque chose dont vous êtes sûr qu'elle devrait se souvenir.","troubleshooting.common-errors#9#p":"La mémoire fonctionne par sens, pas par mots exacts (c'est ce que signifie « sémantique »). Donc « Qu'ai-je décidé concernant l'authentification ? » fonctionne mieux que « trouver ma décision sur l'authentification ». Si la mémoire est bien là mais ne remonte pas, ouvrez le navigateur de mémoire et recherchez — si elle n'y est pas, elle n'a jamais été sauvegardée.","troubleshooting.common-errors#10#h":"Boucles de connexion","troubleshooting.common-errors#11#p":"Ce que vous voyez : vous vous connectez, mais Ava continue de vous demander de vous reconnecter — une boucle qui ne vous laisse jamais passer.","troubleshooting.common-errors#12#p":"La solution est de supprimer les détails de connexion enregistrés et de recommencer : dans l'extension, exécutez « Ava : Se déconnecter » depuis la palette de commandes, dans l'IDE utilisez Paramètres → Compte → Se déconnecter, dans le CLI supprimez le fichier situé à ~/.ava/auth.json (un petit fichier de connexion dans un dossier nommé .ava dans votre répertoire personnel). Puis reconnectez-vous.","troubleshooting.common-errors#13#h":"Jetons épuisés","troubleshooting.common-errors#14#p":"Ce que vous voyez : un message indiquant que vous avez épuisé votre utilisation gratuite pour le mois. (« Jetons » est la mesure de l'utilisation de l'IA — « épuisés » signifie simplement que vous avez utilisé votre allocation gratuite de ce mois-ci.)","troubleshooting.common-errors#15#p":"Le budget mensuel gratuit se réinitialise le 1er de chaque mois. Jusqu'à ce moment, passez à un fournisseur BYOK (utilisez votre propre clé API) pour continuer à travailler. Votre compte reste actif — seuls les gérés gratuitement par la plateforme sont mis en pause.","troubleshooting.logs#title":"Où se trouvent les journaux","troubleshooting.logs#0#p":"Un « journal » est simplement un agenda que votre ordinateur tient de ce qui s'est produit — utile quand quelque chose casse et que vous (ou le support) devez voir les détails.","troubleshooting.logs#1#p":"Quand vous avez besoin de l'image brute — quel outil a été appelé, quelles informations il a reçues, ce que le service IA a renvoyé — les journaux sont des fichiers texte brut dans un dossier sur votre ordinateur à ~/.ava/logs/ (un dossier nommé .ava dans votre répertoire personnel, avec un dossier logs à l'intérieur).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — transcriptions par session incluant les appels d'outils, les réponses diffusées et les erreurs.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — journal de l'hôte d'extension VS Code. Échecs d'activation, erreurs de panneau.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — journal de l'IDE de bureau. Messages du processus sidecar, plantages Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — journal REPL CLI.","troubleshooting.logs#3#p":"Dans l'extension, « Ava : Afficher les journaux » dans la palette de commandes ouvre le journal pertinent dans un onglet éditeur. Dans l'IDE, Paramètres → Diagnostics possède un bouton « Ouvrir les journaux ». Le CLI peut suivre son propre journal avec `ava logs --follow`.","start.for-non-coders#6#li3":"Quand vous voulez qu'elle réalise ou modifie quelque chose, demandez-le simplement — elle vous montrera toujours ce qu'elle sur le point de faire et attendra votre « oui ».","start.for-non-coders#7#c":"Vous rencontrez un mot que vous ne reconnaissez pas ? Le glossaire en langage clair (plus bas dans cette section) explique chaque terme, sans supposer de connaissances préalables.","start.install#title":"Installation","start.install#0#p":"Choisissez l'interface qui correspond à votre façon de travailler. Vous pouvez en utiliser plusieurs — Ava synchronise sa mémoire entre elles lorsque vous vous connectez.","start.install#1#h":"Extension VS Code","start.install#2#li0":"Ouvrez le panneau Extensions dans VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Recherchez « Ava Supernova » et cliquez sur Installer.","start.install#2#li2":"Appuyez sur Ctrl+Shift+A (Cmd+Shift+A sur macOS) pour ouvrir le panneau de discussion.","start.install#2#li3":"Suivez l'assistant d'installation — choisissez un modèle, définissez votre mode d'autorisation, c'est fini.","start.install#3#h":"IDE de bureau","start.install#4#li0":"Téléchargez l'installateur pour votre plateforme depuis la page des versions.","start.install#4#li1":"Lancez-le. L'IDE démarre avec un parcours de bienvenue lors de la première utilisation.","start.install#4#li2":"Connectez-vous pour obtenir les jetons gratuits de la plateforme, ou collez votre propre clé API pour exécuter localement.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli (ou pnpm / yarn — à vous de choisir).","start.install#6#li1":"Exécutez  ava  dans n'importe quel répertoire de projet.","start.install#6#li2":"La première exécution vous demande un fournisseur et un modèle. Choisissez et c'est parti.","start.install#7#c":"Pas de compte, pas de souci. Avec votre propre clé API (BYOK), vous n'avez jamais besoin de vous connecter. L'offre gratuite concerne les modèles gérés par la plateforme.","start.what#title":"Qu'est-ce qu'Ava ?","start.what#0#p":"Ava est une intelligence artificielle qui agit vraiment — pas seulement discuter. Elle peut créer une application pour vous, rédiger un document, vous apprendre quelque chose depuis le début, dessiner un logo, ou gérer les tâches administratives que vous remettez sans cesse. Et elle se souvient de vous : sur quoi vous travaillez, comment vous préférez les choses, ce que vous lui avez demandé la semaine dernière.","start.what#1#p":"Une seule Ava, et elle travaille là où vous travaillez — dans votre éditeur de code, en tant qu'application de bureau, sur votre téléphone, ou dans un terminal. Même mémoire, même personnalité, partout.","start.what#2#h":"Ce qui la rend différente","start.what#3#li0":"La vôtre par défaut. Vos travaux restent sur votre propre ordinateur. Aucun suivi, aucune télémétrie — jamais.","start.what#3#li1":"Ouverte à tous. Chaque ligne du code d'Ava est publique. Rien à croire sur parole.","start.what#3#li2":"Gratuite pour commencer. 300 crédits chaque mois, sans carte bancaire, sans surprise — ou utilisez vos propres clés d'IA et ne nous payez rien du tout.","start.what#3#li3":"L'apprentissage est gratuit, pour toujours. Apprendre ne devrait pas avoir de prix.","start.what#4#p":"Vous n'avez jamais écrit de code ? La page suivante est faite spécialement pour vous. Vous êtes déjà technique ? Passez directement — elle vous suivra.","start.what#deeper#0#h":"Où réside Ava","start.what#deeper#1#li0":"Extension VS Code — Ava à côté de votre éditeur : un panneau de discussion, un tableau de bord, et des modifications affichées en direct avant qu'elles ne soient appliquées.","start.what#deeper#1#li1":"IDE de bureau — une application autonome avec tout dans une seule fenêtre. Ajoute le contrôle du bureau (ouvrir des applications, cliquer, taper pour vous).","start.what#deeper#1#li2":"Compagnon — une application mobile pour quand vous êtes loin de votre bureau : tâches, journal, mémoire, discussions rapides.","start.what#deeper#1#li3":"CLI — Ava dans votre terminal, pour ceux qui y vivent.","start.what#deeper#2#h":"Comment elle fonctionne, en bref","start.what#deeper#3#p":"Ava change d'état d'esprit (appelé modes) pour s'adapter à la tâche, fait tourner discrètement une petite équipe d'experts pour les travaux complexes, et choisit le meilleur modèle d'IA pour chaque étape automatiquement. Vous n'avez jamais à gérer cela. La section Concepts de base propose le tour complet dès que vous êtes curieux.","start.first-five#title":"Votre première chose avec Ava","start.first-five#0#p":"Le moyen le plus rapide de démarrer avec Ava est de lui demander quelque chose de concret et de la voir agir. Pas de configuration à lire, rien à apprendre avant — dites-lui simplement ce que vous voulez, en mots simples.","start.first-five#1#h":"Essayez ceci maintenant","start.first-five#2#li0":"Ouvrez le chat.","start.first-five#2#li1":"Tapez quelque chose que vous voulez vraiment. Essayez « expliquer ce que fait ce projet », ou « ajouter un bouton qui vide le formulaire ».","start.first-five#2#li2":"Ava vous montre ce qu'elle compte faire — et elle attend.","start.first-five#2#li3":"Vous êtes satisfait ? Dites oui. Regardez-la faire.","start.first-five#3#p":"C'est tout le principe : vous demandez, elle vous montre le plan, vous validez, elle exécute. Elle ne modifie jamais rien sans vous montrer d'abord — ainsi, vous ne pouvez rien casser en essayant.","start.first-five#4#h":"Quelques demandes qui valent le coup","start.first-five#5#li0":"Une question — « Pourquoi ma page est-elle vide ? », « Que fait ce fichier ? »","start.first-five#5#li1":"Quelque chose à construire — « Crée-moi une page de liste de tâches simple ».","start.first-five#5#li2":"Pour apprendre quelque chose — « Apprends-moi Python dès le début ». (Toujours gratuit.)","start.first-five#5#li3":"Un document — « Rédige-moi une proposition de projet d'une page ». Elle vous remettra un fichier Word ou PDF.","start.first-five#6#c":"Pas sûr de quoi taper ? Parlez-lui comme à une amie experte. Des mots simples sont parfaits — vous n'avez jamais besoin de termes techniques pour démarrer.","start.first-five#deeper#0#p":"Cette simple boucle accomplit beaucoup de choses en coulisses. Vous n'avez besoin de rien de tout cela pour utiliser Ava — mais voici ce qui se passe réellement si vous êtes curieux.","start.first-five#deeper#1#h":"Outils et approbation","start.first-five#deeper#2#p":"Quand Ava lit un fichier, lance une commande ou modifie du code, chacun de ces actes est un « appel d'outil ». Elle demande avant toute action touchant vos fichiers ou votre système — la fréquence de ses demandes dépend de votre mode de permission (demander à chaque fois, seulement pour les actions risquées, ou simplement y aller).","start.first-five#deeper#3#h":"Modes — ses états d'esprit","start.first-five#deeper#4#p":"Ava fonctionne selon des modes : un état d'esprit plus l'outillage adapté au travail. Changez à tout moment depuis le sélecteur, ou tapez un préfixe au début de votre message. Il y en a sept.","start.first-five#deeper#6#h":"Spécialistes et routage","start.first-five#deeper#7#p":"Sur les tâches plus complexes, Ava mobilise une petite équipe d'aides spécialisés en coulisses (un planificateur, un vérificateur, un constructeur) et dirige chaque étape vers le modèle le plus apte. Vous ne gérez rien de tout cela — elle coordonne tout pour vous.","start.local-vs-cloud#title":"Local vs cloud, en un paragraphe","start.local-vs-cloud#0#p":"Tout ce qu'Ava fait reste local sauf si vous optez explicitement pour le cloud. Mémoire, tâches, journal, personnalité, paramètres — tout est stocké sur votre machine dans ~/.ava/ et .ava/ (par projet). Elle communique avec les fournisseurs de modèles via HTTPS pour exécuter votre demande, puis rentre chez elle. Elle ne téléphone pas chez elle. Elle ne collecte pas de télémétrie. Elle ne s'entraîne pas sur votre code.","start.local-vs-cloud#1#p":"Si vous vous connectez, vous bénéficiez de 300 crédits gratuits par mois sur des modèles gérés par la plateforme (Qwen, MiniMax) et d'une synchronisation cloud optionnelle pour la mémoire et les paramètres entre machines. La synchro est par fonctionnalité, révocable à tout moment. Apportez votre propre clé API et Ava fonctionne pleinement sans compte.","start.local-vs-cloud#2#c":"La règle : le local est sacré. Le cloud est un complément.","start.first-model#title":"Dois-je choisir une IA ?","start.first-model#0#p":"Voici une bonne nouvelle : vous ne choisissez pas l'IA. Ava sélectionne automatiquement la bonne pour chaque étape, ainsi vous obtenez de bons résultats sans avoir à y réfléchir.","start.first-model#1#p":"La seule chose que vous pouvez choisir est un style de routage — et le choix par défaut convient à presque tout le monde. Vous n'avez besoin des autres que pour une raison précise.","start.first-model#2#h":"Les trois styles","start.first-model#3#li0":"Maestro — le choix par défaut. Stable, fiable, prévisible. Pas sûr ? C'est celui-ci.","start.first-model#3#li1":"Supernova — pour les travaux lourds et multi-étapes, où il est avantageux de confier chaque partie de la tâche à un spécialiste différent.","start.first-model#3#li2":"Aurora — lorsque vos données doivent rester dans l'UE (secteur public, santé, confidentialité stricte). Fonctionne entièrement sur une IA européenne à poids ouvert.","start.first-model#4#p":"Changez à tout moment depuis le sélecteur de modèle en haut de la discussion. Rien n'est figé.","start.first-model#5#c":"Vous voulez piloter un modèle spécifique vous-même ? Vous le pouvez — ouvrez « Montrez-moi les détails ».","start.glossary#1#td7.1":"L'unité plus simple d'Ava pour savoir ce qu'une action coûte, sans avoir à faire de calculs de tokens. Les abonnements comprennent un forfait mensuel.","start.glossary#1#td8.0":"Clé API","start.glossary#1#td8.1":"Un mot de passe secret qui autorise un logiciel à utiliser un service payant (comme un modèle d'IA) sur votre compte. Vous n'en avez besoin que si vous souhaitez utiliser la vôtre.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"« Apportez votre propre clé. » Utilisez votre propre clé API plutôt que l'accès géré par Ava. Optionnel — pour ceux qui paient déjà directement un fournisseur.","start.glossary#1#td10.0":"Priorité locale","start.glossary#1#td10.1":"Vos données restent sur votre ordinateur par défaut. Rien n'est envoyé en ligne sauf si vous activez la synchronisation. « Le local est sacré. »","start.glossary#1#td11.0":"Mode permission","start.glossary#1#td11.1":"Le niveau de prudence d'Ava avant d'agir : demander à chaque fois, uniquement pour les actions risquées, ou simplement procéder. Vous choisissez le niveau.","start.glossary#1#td12.0":"Fenêtre de contexte","start.glossary#1#td12.1":"La quantité de texte qu'un modèle peut garder en mémoire à la fois — sa mémoire à court terme. « Contexte 1M » signifie environ un million de mots. Plus c'est grand, plus il peut lire avant d'oublier.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"Une vue côte à côte montrant exactement ce qui changera dans un fichier — l'ancienne version d'un côté, la nouvelle de l'autre — affichée avant qu'Ava ne modifie quoi que ce soit, pour que vous puissiez approuver.","start.glossary#1#td14.0":"Dépôt (repo)","start.glossary#1#td14.1":"Un dossier de projet suivi des modifications, généralement avec Git. Si cela ne vous dit rien pour l'instant, c'est simplement « le dossier où se trouve mon projet ». ","start.glossary#1#td15.0":"Prompt","start.glossary#1#td15.1":"Ce que vous écrivez à l'IA — votre question ou votre consigne.","start.glossary#2#c":"Toujours bloqué sur un mot ? Posez la question à Ava dans le mode Discussion — « que signifie X ? » — et elle vous expliquera selon votre niveau.","models.routing#title":"Routage — comment Ava choisit les modèles","models.routing#0#p":"Voici le résumé : vous n'avez jamais à choisir quel modèle d'IA utiliser. Ava s'en charge pour vous, sélectionnant le meilleur outil pour chaque partie d'une tâche — comme un bon chef confie la bonne mission à la bonne personne.","models.routing#1#p":"Vous choisissez l'un des trois modes — Maestro, Supernova ou Aurora — et Ava envoie chaque tâche au modèle qui la gère le mieux. Maestro est la valeur par défaut, disponible sur tous les plans, et c'est un excellent choix pour presque tout le monde.","models.routing#2#h":"Pourquoi se donner la peine de router ?","models.routing#3#p":"Utiliser le bon modèle pour chaque étape coûte moins cher que de tout faire tourner sur un seul gros modèle coûteux — et donne de meilleurs résultats, car chaque modèle excelle dans ce qu'il fait. Vous bénéficiez d'un coût stable et d'une haute qualité sans jamais avoir besoin de savoir quel modèle est utilisé.","models.routing#4#c":"Les trois modes fonctionnent avec les crédits de la plateforme et vos propres clés. Avec votre propre clé, vous pouvez aussi ignorer le routage et piloter un modèle unique directement. Le détail complet de la flotte se trouve sous « Montrez-moi les détails ».","models.routing#deeper#0#c":"Les chiffres « B » ci-dessous représentent des milliards de paramètres — une mesure approximative de la taille du « cerveau » d'un modèle ; plus grand signifie généralement plus intelligent, mais plus lent et plus cher. C'est un détail technique ; vous n'en aurez jamais besoin pour utiliser Ava.","models.routing#deeper#1#h":"Côte à côte","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Coordinateur","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B actifs, 1M de contexte)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B actifs, 262K de contexte)","models.routing#deeper#2#td1.0":"Constructeur","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (réutilise le coordinateur)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B denses, 256K de contexte)","models.routing#deeper#2#td2.0":"Spécialistes de niveau intermédiaire","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (réviseur de code, vérificateur de faits, exploration, analyseur, vérificateur de sécurité, etc.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Architecte, Vérificateur, Séquenceur, Tuteur, Rapporteur, etc.)","models.routing#deeper#2#td3.0":"Niveau léger / filtre d'intention","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Éclaireur, Vérificateur, Séquenceur, Challengeur, Intégrateur)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Spécialistes avancés","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Chercheur, Challengeur, Chercheur CVE, Générateur d'idées, Vérificateur de faits)","start.first-model#deeper#0#h":"Ce que contient réellement chaque style","start.first-model#deeper#1#p":"Maestro — un seul chef d'orchestre (Qwen 3.6 Plus) gère chaque étape. Optimisé pour la production, éprouvé, coût prévisible.","start.first-model#deeper#2#p":"Supernova — un coordinateur de pointe (DeepSeek V4 Pro, 1,6 T paramètres / 49 B actifs, contexte de 1 M) confie chaque sous-tâche à un spécialiste : V4 Flash pour les builds à haut volume, Qwen 3.6 Plus en secours, Qwen Omni pour la vision.","start.first-model#deeper#3#p":"Aurora — uniquement Mistral, en trois niveaux : Mistral Large 3 (coordinateur + spécialistes lourds), Mistral Medium 3.5 (128 B denses, contexte 256 K, vision native, poids ouverts MIT modifiés, 77,6 % SWE-Bench Verified) pour Builder + milieu de gamme + vision + textes longs, et Mistral Small 4 au niveau de l'intention. Poids ouverts de bout en bout, ne quitte jamais l'infrastructure UE.","start.first-model#deeper#4#h":"Apportez votre propre modèle (BYOK)","start.first-model#deeper#5#p":"Préférez utiliser votre propre compte IA ? Collez votre clé de fournisseur dans les paramètres et vous obtenez les deux — les trois styles de routage, plus l'option de choisir un seul modèle et de sauter le routage entièrement. Utile pour une forte préférence, un budget strict, ou tester un modèle spécifique. La liste complète des fournisseurs se trouve dans la section Références.","start.glossary#title":"Glossaire en langage clair","start.glossary#0#p":"Chaque mot que vous pourriez rencontrer autour d'Ava, expliqué sans connaissances préalables. Vous n'avez pas besoin de mémoriser tout cela — revenez-y dès qu'un terme vous pose problème.","start.glossary#1#th0":"Mot","start.glossary#1#th1":"Ce que cela signifie vraiment","start.glossary#1#td0.0":"Agent","start.glossary#1#td0.1":"Une IA capable d'agir pour vous — lire un fichier, lancer une commande, chercher sur le web — pas seulement discuter. Ava est un agent : elle fait des choses, avec votre accord.","start.glossary#1#td1.0":"Modèle","start.glossary#1#td1.1":"Le véritable cerveau IA qui réfléchit (Qwen, DeepSeek, Mistral, et autres). Différents modèles ont différentes forces. Vous ne choisissez normalement jamais l'un d'eux — Ava le fait.","start.glossary#1#td2.0":"Mode","start.glossary#1#td2.1":"L'état d'esprit d'Ava. Comme un collègue qui change de casquette : constructeur, rédacteur, enseignant, planificateur, ami. Vous choisissez le mode ; cela change son comportement. Il y en a sept.","start.glossary#1#td3.0":"Personnalité / spécialiste","start.glossary#1#td3.1":"Rôles d'aide qu'Ava exécute en coulisses pour les tâches difficiles — un explorateur, un planificateur, un vérificateur de faits. Imaginez une petite équipe d'experts. Vous ne leur parlez jamais directement ; Ava les coordonne.","start.glossary#1#td4.0":"Routage","start.glossary#1#td4.1":"Ava décide quel modèle utiliser à chaque étape pour que vous obteniez de bonnes réponses sans payer trop. Cela se fait automatiquement — la « mode routage » choisit simplement la stratégie globale.","start.glossary#1#td5.0":"Outil","start.glossary#1#td5.1":"Une action spécifique qu'Ava peut effectuer — lire un fichier, lancer une recherche, envoyer un e-mail. Un « appel d'outil » est son utilisation d'un tel outil. Elle demande la permission avant toute chose risquée.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Comment l'IA mesure le texte — environ ¾ d'un mot. Les modèles sont facturés par million de tokens. Pour l'essentiel, quelque chose que vous pouvez ignorer.","start.glossary#1#td7.0":"Crédit","credits.overview#8#li4":"Orchestration — 10 crédits. Lancement complet du pipeline de persona (Conducteur + tâche multi-personas).","credits.overview#8#li5":"Génération d'images — 12 crédits. Hailuo image-01 via Creative Studio.","credits.overview#8#li6":"Génération vidéo — 150 crédits. Clip vidéo Hailuo 02 Pro 1080p 6s.","credits.overview#8#li7":"Génération vocale — 10 crédits. Synthèse vocale Speech 2.8 HD.","credits.overview#8#li8":"Génération musicale — 50 crédits. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Suppression d'arrière-plan — 2 crédits.","credits.overview#9#h":"Multiplicateurs par modèle","credits.overview#10#p":"Cette section est pour les curieux — vous n'en avez pas besoin pour utiliser Ava. Un multiplicateur ajuste simplement le coût en crédits à la hausse ou à la baisse selon le prix du modèle qui exécute l'action, donc les modèles plus coûteux coûtent un peu plus. (« Marge nette » désigne la part que le projet garde après avoir couvert ses frais — nous visons bas pour que la valeur vous revienne directement.)","credits.overview#11#p":"Les modèles plus gourmands multiplient le coût de l'action pour que les crédits correspondent à la dépense réelle plutôt qu'à une tranche forfaitaire. Calibré pour une marge nette d'environ 55 %.","credits.overview#12#li0":"0.6× — Mistral Small 4 (la place spécialisée d'Aurora). Moins de 1× car Mistral Small 4 est moins cher que la référence Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Tarif de base.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (coordinateur d'Aurora). Environ équivalent à la référence Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (coordinateur Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (coordinateur Supernova + spécialistes exigeants). Recalibré de 5.0× pour rétablir l'équilibre des marges au tarif publié pour V4 Pro.","credits.overview#13#c":"Les modèles Anthropic (Claude Opus / Sonnet / Haiku) ne sont pas facturés en crédits — ils sont exclusivement BYOK et vous payez Anthropic directement. Même chose pour tout autre fournisseur BYOK utilisé avec votre propre clé.","credits.overview#14#h":"BYOK et crédits","credits.overview#15#p":"BYOK (« apportez votre propre clé » — vous utilisez votre propre compte auprès d'un fournisseur d'IA et une clé, qui est un mot de passe privé permettant au logiciel d'utiliser ce compte payant) s'adresse aux personnes qui paient déjà directement un fournisseur d'IA. Si ce n'est pas votre cas, vous pouvez ignorer cette section entièrement.","credits.overview#16#p":"Les demandes BYOK contournent entièrement l'infrastructure de la plateforme — l'appel va directement d'Ava au fournisseur, vous payez le fournisseur, aucun crédit n'est consommé. La seule exception survient lorsqu'une session BYOK lance un persona de niveau géré pour une sous-tâche ; la déduction de crédit s'applique toujours car l'interface d'orchestration d'Ava est utilisée.","credits.overview#17#h":"Où vérifier votre solde","credits.overview#18#li0":"Extension — Paramètres → Compte, ou la pastille de crédits dans l'en-tête du chat.","credits.overview#18#li1":"IDE — La tuile du tableau de bord du compte affiche le solde actuel et le rythme de consommation.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard affiche le solde, l'historique et la date de renouvellement.","credits.overview#19#c":"Local-first : Ava fonctionne sans compte sur la carte Modèle personnalisé (Ollama, LM Studio, vLLM, ou tout service compatible OpenAI). Pas de crédits, pas de jetons de plateforme — votre modèle, votre machine, votre facture à zéro.","concepts.modes#title":"Modes — États d'esprit d'Ava","models.routing#deeper#2#td11.1":"Travail quotidien, coût prévisible","models.routing#deeper#2#td11.2":"Travail lourd et multi-étapes, coordinateur de pointe sur tous les forfaits","models.routing#deeper#2#td11.3":"Respect strict du RGPD, secteur public, infrastructures souveraines de l'UE","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Routage Qwen différencié par niveau, empreinte légère. Qwen 3.6 Plus assume le rôle de coordinateur, ainsi que la construction, la planification, la sécurité, le brainstorming et les tâches à contexte long — là où son attention hybride linéaire à contexte de 1M tokens paie. Qwen 3.5 Flash gère le chat, l'orchestration de la génération d'images et la porte d'entrée des intentions en amont, où ses prix de 0,07 $/0,26 $ et sa latence TTFT plus rapide gagnent sur le volume majoritaire de tokens peu profonds. Qwen 3.5 Omni Plus gère l'entrée visuelle (Qwen 3.6 Plus n'a pas de vision native). Qwen 3.5 Plus prend en charge les travaux longs sensibles au coût. En cas d'indisponibilité du coordinateur principal, cela passe à l'échelon inférieur de la hiérarchie : Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Ensemble polyglotte. DeepSeek V4 Pro coordonne et répartit chaque sous-tâche vers son spécialiste le mieux adapté : Qwen 3.6 Plus exécute chaque création de Builder, V4 Flash gère le chat ainsi que les personas de révision/audit de niveau intermédiaire, Qwen 3.5 Flash absorbe le travail de classification de niveau léger, Qwen 3.5 Omni Plus gère l'entrée visuelle, Qwen 3.5 Omni Flash orchestre les appels d'outils de génération d'images, Qwen 3.5 Plus prend en charge le persona Content Writer sensible au coût. Raisonnement de pointe là où c'est nécessaire, économie de niveau flash sur le volume majoritaire de tokens.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Pile logicielle IA européenne — conçue pour être souveraine. Routage uniquement Mistral en trois niveaux : Mistral Large 3 (675B/41B actif MoE épars) gère le rôle de coordinateur ainsi que les spécialistes lourds nécessitant de la profondeur — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — et les tâches longues où son efficacité MoE épars prime. Mistral Medium 3.5 — le phare fusionné lancé en avril 2026, 128B dense, contexte 256K, encodeur visuel entraîné depuis zéro, poids ouverts MIT modifiés, 77,6% SWE-Bench Verified — gère le niveau de travail réel : créations de Builder, spécialistes de niveau intermédiaire (Architect, Verifier, Sequencer, Tutor, Reporter), entrée visuelle et rédaction longue. Mistral Small 4 est passé d'un seul rôle à la porte d'entrée des intentions à également gérer le chat et l'orchestration de génération d'images — ses prix de 0,15 $/0,60 $ et son raisonnement configurable valent leur pesant d'or sur les routes haute volume faible profondeur. Poids ouverts de bout en bout, ne quitte jamais l'infrastructure UE. Aurora ne croise pas silencieusement vers un modèle non-Mistral lorsqu'un modèle est indisponible ; le routeur affiche une erreur à la place — c'est ce qui fait qu'il s'agit d'« Aurora » plutôt que d'un Maestro à la sauce Mistral.","credits.overview#title":"Crédits Ava — comment fonctionne la facturation","credits.overview#0#p":"Les crédits sont simplement la façon dont Ava compte ce que vous utilisez — comme les minutes sur un forfait téléphonique. Chaque forfait, y compris le gratuit, vient avec un pool de crédits, et chaque chose qu'Ava fait (vous répondre, créer une image) coûte un petit nombre d'entre eux. C'est tout le principe. Les détails ci-dessous sont pour quand vous voulez savoir exactement ce que coûte quoi.","credits.overview#1#p":"Ava facture en crédits, pas en tokens bruts. (Un « token » est le tout petit morceau de texte — environ quelques lettres — que les modèles d'IA lisent et écrivent ; la plupart des services vous facturent par token, ce qui est difficile à prévoir.) Un crédit couvre une unité de travail — un tour de chat, une création de persona (un assistant faisant une partie de la tâche), une génération d'image. Se découpler de la facturation au niveau du token signifie que vous n'avez pas besoin de savoir quel modèle tourne pour savoir combien coûtera une action. Le même tour de chat coûte le même montant que Maestro le route vers Qwen 3.6 Plus ou que Supernova le route vers V4 Pro.","credits.overview#2#h":"Forfaits","credits.overview#3#p":"Chaque forfait donne accès à toutes les fonctionnalités — accès aux modèles, Creative Studio, les sept modes, l'orchestration complète des personas. Les niveaux supérieurs achètent plus de crédits et un plafond de limite de débit plus élevé, pas des fonctionnalités débloquées.","credits.overview#4#li0":"Gratuit — 0 $/mois. 300 crédits. Limite de débit de 20 requêtes/minute. Aucune carte requise.","credits.overview#4#li1":"Pro — 19 $/mois. 5 000 crédits. 60 requêtes/minute.","credits.overview#4#li2":"Ultra — 39 $/mois. 10 000 crédits. 120 requêtes/minute.","credits.overview#4#li3":"Entreprise — 79 $/mois. 20 000 crédits. 200 requêtes/minute.","credits.overview#5#c":"Les crédits inutilisés se reportent tant que votre abonnement est actif — aucun rappel forcé. Les recharges s'empilent sur le pool d'abonnement : 750 crédits pour 3 $, 2 000 pour 8 $, 4 000 pour 15 $.","credits.overview#6#h":"Ce que coûtent les actions","credits.overview#7#p":"Tableau des coûts par action — ce qui est déduit de votre pool de crédits lorsque chaque action s'exécute. (Un « hit de cache » est quand Ava réutilise un travail déjà fait au lieu de le refaire ; quand cela arrive, vous payez moins — la charge baisse de 70 %, ou 50 % sur les modèles gourmands en sortie comme DeepSeek V4 Pro.)","credits.overview#8#li0":"Tour de chat — 2 crédits. Une simple interaction dans n'importe quel mode.","credits.overview#8#li1":"Appel léger — 1 crédit. Porte d'entrée des intentions, classification, lecture en un tir.","credits.overview#8#li2":"Persona lourd — 3 crédits. Architect, Researcher, CVE Researcher, Ideator (profondeur ≥ 4).","credits.overview#8#li3":"Persona léger — 1 crédit. Scout, Verifier, Sequencer, Challenger (profondeur ≤ 2).","concepts.modes#0#p":"Un mode correspond à l'état d'esprit dans lequel se trouve Ava — comme un collègue qui change de casquette. Même personne, même souvenir de vous, mais un constructeur pense différemment d'un enseignant. Vous choisissez le mode et cela change sa façon d'agir et les assistants qu'elle mobilise. Changez à tout moment avec le sélecteur de mode, ou tapez un raccourci à deux caractères.","concepts.modes#2#h":"Lequel préférez-vous ?","concepts.modes#3#p":"Commencez par ce que vous essayez de faire — le mode en découle :","concepts.modes#4#li0":"Je veux quelque chose de construit ou modifié → Code (>>). Vous la décrivez, elle la construit, en vous montrant chaque changement d'abord. L'équipe complète d'assistants intervient pour les gros travaux.","concepts.modes#4#li1":"Je veux un plan avant toute modification → Plan (::). Elle réfléchit et vous remet un plan à approuver ou modifier. Elle ne touchera pas à vos fichiers dans ce mode.","concepts.modes#4#li2":"Je veux juste parler ou poser une question → Discussion (..). Un partenaire de réflexion avec mémoire, actualités et météo. Pas de modification de fichiers, pas de code — juste la conversation.","concepts.modes#4#li3":"Je veux apprendre quelque chose → Enseigner (??). Un vrai cours conçu pour vous : leçons, quiz, le tout. Gratuit sur tous les plans, à jamais. Parfait si vous débutez.","concepts.modes#4#li4":"Je veux vérifier mon projet pour des failles de sécurité → Sécurité (!!). Une équipe parcourt la liste standard des vulnérabilités web courantes (les catégories \"OWASP\") et des défauts connus signalés (appelés \"CVEs\"), puis vous remet un rapport trié par gravité. Celle-ci est destinée aux développeurs — passez votre chemin si ce n'est pas votre cas.","concepts.modes#4#li5":"Je veux des idées → Idées (**). Elle génère des options ancrées dans votre situation réelle, creuse les faiblesses et affine le reste en prochaines étapes.","concepts.modes#4#li6":"Je veux rédiger un document → Rédaction (<<). Rapports, propositions, lettres, articles — elle brouillonne en Markdown et exporte un document Word ou PDF personnalisé, section par section. Pas de code, juste de l'écriture.","concepts.modes#5#c":"L'« équipe d'assistants » (personas) fonctionne entièrement en arrière-plan — vous ne leur parlez jamais directement. Vous obtenez simplement une réponse plus complète. Vous n'avez pas besoin de connaître leurs noms.","concepts.modes#6#c":"Vous pouvez changer de mode en plein milieu d'une conversation. Votre mémoire traverse ; les spécialistes se réinitialisent pour s'adapter au nouveau mode.","concepts.tasks-journal#title":"Tâches et journal","concepts.tasks-journal#0#p":"Ava conserve trois types de notes pour vous, et il est facile de les confondre. Le moyen rapide de s'en souvenir : la mémoire, c'est ce qu'elle sait de vous, les tâches sont ce qu'il reste à faire, et le journal est un carnet de comment les choses se sont passées. Voici quand utiliser laquelle.","concepts.tasks-journal#1#li0":"Mémoire — faits persistants. Préférences, décisions, habitudes. Demandées souvent, rarement créées manuellement.","concepts.tasks-journal#1#li1":"Tâches — choses à faire. Éléments d'action avec dates d'échéance et statut. Vous les cochez une fois terminées.","concepts.tasks-journal#1#li2":"Journal — réflexion. Log quotidien, entrées doubles (la vôtre et les observations d'Ava sur la session). Utile pour le suivi d'humeur, les revues de session, le contexte pour demain.","concepts.tasks-journal#2#p":"Ava écrit dans les trois quand cela a du sens. Vous pouvez écrire dans chacun directement depuis le tableau de bord. Rien n'est verrouillé dans un seul endroit où vous utilisez Ava — une tâche que vous créez dans l'un (disons l'outil en ligne de commande) apparaît partout ailleurs (comme l'application de bureau), automatiquement.","concepts.permissions#title":"Autorisations — votre bouton de sécurité","concepts.permissions#0#p":"Les autorisations sont votre bouton de sécurité. Elles décident quand Ava demande votre accord avant de faire quelque chose sur votre ordinateur, versus juste continuer. Vous pouvez la régler pour demander tout, demander seulement les choses risquées, ou lui faire confiance pour exécuter — et vous pouvez le changer à tout moment. Si vous n'êtes pas sûr, laissez-la sur la valeur par défaut et vous irez bien.","concepts.permissions#1#p":"Ava dispose de 60 outils (« outils » sont les actions qu'elle peut prendre — lire un fichier, chercher sur le web, etc.). Chaque outil appartient à une catégorie (opérations sur fichiers, terminal, git, web, média, base de données, système, documents, mémoire, apprentissage). Chaque appel d'outil passe par la porte des autorisations (un point de contrôle qui décide si elle doit vous demander d'abord) avant de s'exécuter. Vous contrôlez ce qui est auto-approuvé, ce qui demande une fois, et ce qui demande toujours.","concepts.permissions#3#p":"Équilibré est la valeur par défaut. Strict pour quand vous auditez son comportement (surveiller de près pour vérifier chaque étape). Autonome pour quand vous voulez qu'elle aille de l'avant.","concepts.permissions#4#c":"Autonome ne signifie pas sans contrôle. Les plans, les questions de clarification et les invites explicites demandant à l'utilisateur mettent toujours pause pour votre saisie. Les opérations irréversibles (git force-push, suppressions de bases de données) confirment toujours peu importe le mode.","concepts.interjection#title":"Guider et arrêter Ava","concepts.interjection#0#p":"Vous êtes toujours aux commandes. Pendant qu'Ava travaille, vous pouvez soit la guider vers une nouvelle direction sans rompre son élan, soit l'arrêter net. Deux boutons, deux résultats — c'est tout ce dont parle cette page.","concepts.interjection#1#p":"Ava continue tant que son plan n'est pas terminé ou jusqu'à ce que vous l'arrêtiez. Vous disposez de deux méthodes pour intervenir (le terme exact est \"intervenir\") pendant qu'elle est en cours d'exécution.","concepts.interjection#2#h":"Intervenir — orienter sans annuler","concepts.interjection#3#p":"Saisissez un nouveau message pendant qu'Ava travaille. Elle termine l'action en cours, lit votre message et adapte son plan. Rien ne se perd. Utilisez cette option si vous souhaitez réorienter la tâche, ajouter des détails ou modifier les priorités en cours d'exécution.","concepts.interjection#4#h":"Arrêt net — annuler et effacer","concepts.interjection#5#p":"Appuyez sur Échap (CLI), cliquez sur Arrêter (extension, IDE) ou saisissez une commande d'arrêt. L'exécution en cours est annulée, les actions en attente sont abandonnées, et la conversation est prête pour une nouvelle étape.","concepts.interjection#6#c":"Commencez par intervenir. L'arrêt net sert uniquement en cas de problème grave. Intervenir permet de maintenir la continuité.","concepts.desktop-personas#title":"Rôles de bureau","concepts.desktop-personas#0#p":"Cette page s'adresse aux curieux et aux utilisateurs experts. L'automatisation de bureau (parfois nommée \"utilisation de l'ordinateur\") signifie qu'Ava peut réellement cliquer sur votre écran et utiliser vos applications — ouvrir Gmail, remplir un formulaire, envoyer un message — comme le ferait une personne au clavier. Pour agir en toute sécurité, elle répartit la tâche entre cinq assistants spécialisés, chacun ayant un rôle précis. Vous n'avez pas besoin de les gérer directement ; cette section vous explique simplement qui fait quoi.","concepts.desktop-personas#1#p":"À chaque étape d'une séquence de bureau (une exécution où Ava pilote votre écran vers un objectif), cinq rôles interviennent successivement. Chaque rôle a une seule mission, rien de plus. Cette séparation garantit des consignes claires, des résultats structurés et une réflexion critique par conception.","concepts.desktop-personas#2#h":"Éclaireur","concepts.desktop-personas#3#p":"Rend compte de ce qui est visible à l'écran à l'instant présent. Il n'invente aucun élément et ne planifie rien. Il renvoie un état d'écran (ScreenState JSON) contenant les identifiants des éléments, leurs noms, leurs zones (bboxes), leur niveau de confiance et la source utilisée (UIA, Playwright DOM ou vision OmniParser).","concepts.desktop-personas#4#h":"Planificateur","concepts.desktop-personas#5#p":"Détermine la prochaine action unique. Une seule action par étape — jamais plusieurs à la fois. Privilégie les chemins réversibles. Classe le risque selon l'ontologie de sécurité. Il génère un JSON ProposedAction incluant le type, la cible, les paramètres, la classe de risque, le raisonnement et une prédiction de l'état suivant (expectedPostState).","concepts.desktop-personas#6#h":"Acteur","concepts.desktop-personas#7#p":"Exécute exactement ce que le Planificateur a proposé, une fois l'approbation obtenue. Aucune improvisation. Aucun réessai. En cas d'échec, il le signale honnêtement et le Vérificateur prend la décision suivante.","concepts.desktop-personas#8#h":"Vérificateur","concepts.desktop-personas#9#p":"Vérifie si l'action a bien eu lieu. Il compare l'état d'écran actuel à la prédiction du Planificateur. Il renvoie \"vérifié\", \"dévié\" ou \"rollback_needed\". Il détecte également les boucles : répéter une action qui a déjà réussi est considéré comme une déviation, pas une validation.","concepts.desktop-personas#10#h":"Narrateur","concepts.desktop-personas#11#p":"C'est la seule voix que l'utilisateur entend durant une séquence. Une phrase au passé par étape (\"Gmail ouvert.\", \"Composer cliqué.\"). Il rédige également le journal d'audit structuré. Il signale quand quelque chose tourne mal — il ne cache jamais un problème.","concepts.desktop-safety#title":"Ontologie de sécurité de bureau","concepts.desktop-safety#0#p":"En résumé : avant qu'Ava clique sur quoi que ce soit sur votre écran, elle évalue le risque de l'action. Lire l'écran ? Sans danger. Envoyer de l'argent ou supprimer un fichier ? Elle s'arrête toujours et vous demande votre accord — systématiquement, sans exception. Les cinq catégories ci-dessous sont les degrés de cette échelle de risque. C'est un détail pour utilisateurs avancés, mais l'essentiel est simple : les actions dangereuses nécessitent toujours votre accord.","concepts.desktop-safety#1#p":"Chaque action proposée est classée dans l'une des cinq catégories de risque. Cette classification croise trois signaux : la cible à l'écran, une description simple (la \"légende sémantique\" — les mots d'Ava pour décrire ce qu'elle voit), et les paramètres de l'action. Si ces signaux divergent, le niveau de risque augmente. Un faux positif (vous demander confirmation inutilement) est simplement une contrainte mineure. Un faux négatif (ne pas demander alors qu'il fallait) constitue un incident bloquant.","concepts.desktop-safety#2#h":"Les cinq catégories","concepts.desktop-safety#3#li0":"Observationnel — lecture de l'arbre UIA, capture d'écran, survol. Toujours autorisé automatiquement.","concepts.desktop-safety#3#li1":"Navigationnel — défilement, déplacement du focus, ouverture d'un menu. Autorisé automatiquement en mode Drive.","features.creative-studio#1#p":"Génération d'images, de vidéos, de musique et de voix — intégrée directement dans votre flux de travail de codage. Créez une icône, une maquette produit, une vidéo démo ou une voix off pour un tutoriel. Propulsé par MiniMax.","features.creative-studio#2#h":"Ce que vous pouvez créer","features.creative-studio#3#li0":"Images — du prompt au PNG/JPG. Suppression d'arrière-plan en un seul appel.","features.creative-studio#3#li1":"Vidéo — courtes vidéos IA à partir d'un prompt texte (MiniMax Hailuo).","features.creative-studio#3#li2":"Musique — pistes instrumentales ou vocales avec paroles.","features.creative-studio#3#li3":"Voix — synthèse vocale avec choix de voix.","features.creative-studio#4#p":"Les coûts de Creative Studio proviennent du même pool de crédits que tout le reste — un seul pool, un seul chiffre. Apportez votre propre clé MiniMax (BYOK) et c'est gratuit pour votre plan.","features.creative-studio#5#c":"Creative Studio est éligible à l'offre gratuite. Ce n'est pas un module payant supplémentaire.","features.desktop-automation#title":"Automatisation de bureau","features.desktop-automation#0#p":"En termes simples : Ava peut prendre le contrôle de votre souris et de votre clavier pour effectuer des tâches à votre place — ouvrir une application, cliquer sur des boutons, remplir un formulaire — pendant que vous surveillez et validez les éléments importants.","features.desktop-automation#1#p":"Un nouveau mode pour Ava, préfixe @@. Elle observe le bureau, décide quoi faire, et pilote l'automatisation de l'interface (contrôle des applications sur votre écran pour vous) pour accomplir la tâche. S'exécute sur votre véritable machine avec vos vrais identifiants — pas un navigateur cloud. Disponible sur tous les niveaux une fois livré.","features.desktop-automation#2#h":"Pourquoi encore une autre ?","features.desktop-automation#3#p":"Tous les autres produits d'automatisation de bureau sont quelque chose que vous lancez quand vous êtes à votre bureau. Ava, elle, est toujours là quand votre outil de suivi d'erreurs sonne à 2h du matin — l'IDE continue de tourner, votre téléphone s'apparie via un canal sécurisé, vous validez les actions irréversibles d'un simple tapotement.","features.desktop-automation#4#p":"Elle se souvient aussi comment naviguer dans vos applications entre les sessions. Chaque autre agent doit réapprendre à chaque fois. La différence liée à la mémoire s'accentue avec l'usage.","features.desktop-automation#5#h":"Comment ça marche","features.desktop-automation#6#p":"Chaque étape déclenche une vague de cinq personnalités : Scout observe, Planificateur choisit l'action suivante, Acteur exécute, Vérificateur contrôle, Narrateur vous explique ce qui s'est passé. Le sidecar choisit l'ancrage fiable le plus économique — UIA pour les applications natives, Playwright pour les navigateurs, OmniParser vision quand rien d'autre ne propose d'arborescence utile.","features.desktop-automation#7#p":"Consultez les pages de concepts pour l'ontologie de sécurité, la hiérarchie d'ancrage, les interrupteurs d'arrêt d'urgence et le modèle de liste blanche de session.","models.routing#deeper#2#td5.0":"Chat","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Orchestration de génération d'images","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Analyse d'images","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (encodeur de vision entraîné à partir de zéro)","models.routing#deeper#2#td8.0":"Rédaction de longs textes","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Localisation des données","models.routing#deeper#2#td9.1":"Mixte (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Mixte (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"UE uniquement · poids ouverts","models.routing#deeper#2#td10.0":"Statut","models.routing#deeper#2#td10.1":"Disponible · tous les forfaits","models.routing#deeper#2#td10.2":"Bientôt disponible","models.routing#deeper#2#td10.3":"Bientôt disponible","models.routing#deeper#2#td11.0":"Idéal pour","concepts.desktop-safety#3#li2":"Mutatif-réversible — tapez dans un champ, collez, ouvrez une application, naviguez vers une URL. Confirme en mode « Demande » ; automatique dans Drive si l'entrée est dans la liste autorisée.","concepts.desktop-safety#3#li3":"Mutatif-irréversible — envoyer, soumettre, payer, supprimer, confirmer, publier. Confirme toujours, quel que soit le niveau d'autorisation. L'accord n'est jamais mis en cache.","concepts.desktop-safety#3#li4":"Privilégié — élévation UAC, sudo, modifications du registre, demandes d'identifiants. Interdit par défaut. Une option unique à chaque session est requise pour y accéder.","concepts.desktop-safety#4#h":"Accords jamais mis en cache","concepts.desktop-safety#5#p":"Tous les concurrents mettent les accords en cache (ils se souviennent de votre « oui » et le réutilisent la prochaine fois). C'est la principale faille pour l'injection de prompt — une attaque où une page web piégée glisse des instructions cachées à l'IA pour qu'elle agisse contre vous. Si les accords sont mis en cache, une page compromise peut profiter d'un « oui » que vous avez donné plus tôt. Ava ne met jamais en cache. Chaque action mutative-irréversible demande une nouvelle confirmation.","concepts.desktop-safety#6#h":"Gestion des secrets","concepts.desktop-safety#7#p":"Les mots de passe, clés API et codes 2FA (les codes uniques qu'une seconde application ou un SMS vous donne lors de la connexion) sont gérés via des identifiants opaques — des espaces réservés qui remplacent la valeur réelle. Ava voit « {secret} », pas le vrai mot de passe. La vraie valeur n'entre jamais dans sa mémoire, son journal d'activité, ou ce qu'elle « lit » — une couche distincte de bas niveau le saisit au dernier moment, à la frappe, afin que la partie IA ne le touche jamais.","reference.cli#title":"Commandes CLI","reference.cli#0#p":"Cette page concerne la CLI — la version d'Ava avec laquelle vous tapez dans une fenêtre de terminal, plutôt que de cliquer sur des boutons. Si vous utilisez l'extension ou l'application de bureau, vous pouvez ignorer cette section entièrement. Elle est là pour les personnes qui préfèrent le clavier.","reference.cli#1#p":"La CLI est un REPL — une invite qui attend que vous tapiez, exécute ce que vous avez écrit, puis attend à nouveau. Ces commandes slash (instructions commençant par « / ») fonctionnent depuis l'invite.","reference.cli#2#li0":"/help — affiche la liste des commandes et le mode actuel.","reference.cli#2#li1":"/mode <nom> — changez de mode (travail, rédaction, planification, discussion, enseignement, sécurité, brainstorming).","reference.cli#2#li2":"/model <id> — changez de modèle sans quitter la session.","reference.cli#2#li3":"/clear — efface la conversation actuelle. La mémoire reste intacte.","reference.cli#2#li4":"/history — affiche les conversations passées dans ce projet.","reference.cli#2#li5":"/memory — ouvre le navigateur de mémoire.","reference.cli#2#li6":"/tasks — affiche et gère les tâches.","reference.cli#2#li7":"/journal — ouvre l'entrée du journal d'aujourd'hui.","reference.cli#2#li8":"/settings — ouvre le menu des paramètres.","reference.cli#2#li9":"/exit — quitte le REPL.","reference.cli#3#h":"Options de démarrage","reference.cli#4#p":"Les options sont des réglages supplémentaires que vous ajoutez lorsque vous lancez Ava, chacun commençant par « -- », pour définir comment elle démarre.","reference.cli#5#li0":"--mode <nom> — démarre dans un mode spécifique.","reference.cli#5#li1":"--model <id> — démarre avec un modèle spécifique.","reference.cli#5#li2":"--permission <mode> — strict / équilibré / autonome.","reference.cli#5#li3":"--project <path> — définir explicitement la racine du projet.","reference.desktop-budget#title":"Limites budgétaires du bureau","reference.desktop-budget#0#p":"Quand Ava contrôle votre bureau à votre place — cliquer, taper, ouvrir des applications — chaque exécution s'appelle une « trajectoire ». Cette page explique les limites de sécurité qui empêchent qu'une seule exécution ne dure trop longtemps ou ne coûte trop cher. La conclusion : elle s'arrête toujours et fait un point avant de dépasser. Les chiffres sont ici si vous voulez les détails.","reference.desktop-budget#1#p":"Chaque trajectoire fonctionne sous trois limites simultanées (limites strictes). Celle atteinte en premier l'emporte. La trajectoire ne continue jamais silencieusement après une violation — le Narrateur (l'assistant qui vous explique ce qui se passe) met en pause et demande quoi faire.","reference.desktop-budget#2#h":"Trois limites strictes (par défaut)","reference.desktop-budget#3#li0":"Nombre d'étapes — 30 étapes","reference.desktop-budget#3#li1":"Budget de jetons — 500 000 jetons","reference.desktop-budget#3#li2":"Temps réel — 5 minutes","reference.desktop-budget#4#h":"Tranches de coût des tâches","reference.desktop-budget#5#li0":"Simple (rechercher dans les docs, ouvrir une page) — 5–10 étapes, ~70–135K jetons, ~$0,04–0,08","reference.desktop-budget#5#li1":"Moyenne (se connecter, vérifier les journaux, télécharger la sortie) — 15–25 étapes, ~205–340K jetons, ~$0,12–0,21","reference.desktop-budget#5#li2":"Complexe (trier trois problèmes GitHub) — 25–30 étapes, ~340–410K jetons, ~$0,21–0,25","reference.desktop-budget#6#p":"Les chiffres de jetons ci-dessus sont les limites techniques par trajectoire, pas votre allocation mensuelle — celle-ci est comptabilisée en crédits, et les 300 gratuits du niveau gratuit couvrent confortablement un mélange de chat, de code et de quelques automatisations.","reference.desktop-budget#7#c":"Vous pouvez modifier les limites par tâche au début, mais les violations font toujours apparaître un point de décision. Le budget n'est jamais consommé silencieusement.","reference.desktop-whitelist#title":"Liste blanche de session de bureau","reference.desktop-whitelist#0#p":"Une « liste blanche » est simplement la liste des applications et sites web que vous avez dit à Ava être autorisés à toucher pendant qu'elle contrôle votre bureau. Cette page explique comment accorder cette permission et pourquoi elle se réinitialise à chaque fois. En bref : elle ne peut agir que là où vous le lui permettez, et elle demande avant d'aller ailleurs.","reference.desktop-whitelist#1#p":"Au début d'une session de bureau, Ava demande où elle est autorisée à agir. Anglais simple fonctionne : « Gmail, Cursor, le portail Azure. » Elle lit cela et confirme la correspondance avec vous (« site web Gmail, application Cursor, portal.azure.com »).","reference.desktop-whitelist#2#h":"Comment elle applique","reference.desktop-whitelist#3#p":"Les actions en lecture seule — prendre une capture d'écran, lire la liste des boutons et champs à l'écran (l'« arbre UIA », la propre carte de Windows de ce qui se trouve dans une fenêtre) — sont autorisées partout, car vous devez voir ce qui est à l'écran pour décider d'ajouter une application à la liste blanche. Tout ce qui change quelque chose est bloqué en dehors de la liste ; Ava met en pause et demande si vous souhaitez l'ajouter.","reference.desktop-whitelist#4#h":"Limité à la session, volontairement","reference.desktop-whitelist#5#p":"La liste blanche NE persiste PAS entre les sessions. Il n'y a pas d'option « se souvenir de cette application ». Chaque nouvelle trajectoire commence avec un nouveau périmètre. Peu pratique par conception — oublier de réautoriser est une fonctionnalité, pas un bug.","reference.desktop-whitelist#6#h":"Ajouts en cours de trajectoire","reference.desktop-whitelist#7#p":"Pendant une trajectoire, vous pouvez ajouter des applications depuis l'en-tête : « + Autoriser une application » ouvre une petite zone de saisie. Appuyez sur Ajouter et la nouvelle application est active pour le reste de la session.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Envie de créer une image, une courte vidéo, une chanson ou une voix off parlée ? Décrivez-le simplement et Ava le crée pour vous — aucun logiciel de design ou audio nécessaire."},"de":{"start.for-non-coders#title":"Noch nie Code geschrieben? Fang hier an","start.for-non-coders#0#p":"Wenn du noch nie eine Zeile Code geschrieben hast, bist du genau die Zielgruppe für Ava. Du musst keine Fachbegriffe lernen, um zu starten – du sprichst mit ihr in einfacher Sprache, genau wie du es einem wissenden Freund sagen würdest. Diese Seite ist dein kompletter Einstieg.","start.for-non-coders#1#h":"Was du heute schon schaffen kannst, ohne Erfahrung","start.for-non-coders#2#li0":"Frag sie alles, ganz normal formuliert — \"was macht diese Datei?\", \"warum ist meine Seite leer?\", \"was ist eigentlich eine Datenbank?\" Sie antwortet in verständlicher Sprache und behält das Gespräch im Kopf.","start.for-non-coders#2#li1":"Lerne etwas von Grund auf — sage \"lehr mich Python von Null\" und sie erstellt dir einen ordentlichen Kurs mit Lektionen und Quizzen. Das ist immer kostenlos.","start.for-non-coders#2#li2":"Erstelle etwas — beschreibe, was du möchtest (\"ein Button, der meine Notizen herunterlädt\") und sie schreibt den Code, zeigt dir jede Änderung, bevor sie stattfindet.","start.for-non-coders#3#h":"Du musst nicht alles verstehen","start.for-non-coders#4#p":"Unter der Haube steckt viel Technik bei Ava – Modi, Modelle, Spezialisten, Routings. Du wirst diese Begriffe in der App und in dieser Dokumentation finden. Hier ist das Geheimnis: Du kannst fast alles ignorieren. Ava wählt automatisch die richtigen Werkzeuge und Helfer für dich aus. Die technischen Seiten gibt es, wenn du neugierig wirst, nicht weil du sie zum Starten brauchst.","start.for-non-coders#5#h":"Ein sanfter erster Weg","start.for-non-coders#6#li0":"Installiere Ava (nächste Seite) und öffne den Chat.","start.for-non-coders#6#li1":"Tippe eine echte Frage, die du hast. Alles. Schau, wie sie antwortet.","start.for-non-coders#6#li2":"Probiere den Lernmodus: tippe \"lehr mich\" und ein Thema. Folge mit.","concepts.memory#title":"Gedächtnis — wie Ava Sie erinnert","concepts.memory#0#p":"Einfach gesagt: Ava erinnert sich an Sie. Erzählen Sie ihr einmal etwas — was Sie mögen, eine Entscheidung, die Sie getroffen haben — und sie behält es, damit Sie sich im nächsten Chat oder nächste Woche nicht wiederholen müssen. Das ist die Kernbotschaft. Die Ebenen unten erklären nur, wie sie dieses Gedächtnis über die Zeit ordentlich hält.","start.for-non-coders#6#li3":"When you want her to actually make or change something, just ask — she will always show you what she is about to do and wait for your \"yes\".","start.for-non-coders#7#c":"Hit a word you do not recognise? The Plain-English glossary (further down this section) explains every term with no assumed knowledge.","start.install#title":"Install","start.install#0#p":"Pick the surface that matches how you work. You can use more than one — Ava syncs her memory across them when you sign in.","start.install#1#h":"VS Code extension","start.install#2#li0":"Open the Extensions panel in VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Search for \"Ava Supernova\" and click Install.","start.install#2#li2":"Press Ctrl+Shift+A (Cmd+Shift+A on macOS) to open the chat panel.","start.install#2#li3":"Follow the setup wizard — pick a model, set your permission mode, done.","start.install#3#h":"Desktop IDE","start.install#4#li0":"Download the installer for your platform from the releases page.","start.install#4#li1":"Run it. The IDE launches with a welcome flow the first time.","start.install#4#li2":"Sign in for the free platform tokens, or paste your own API key to run fully local.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (or pnpm / yarn — your choice).","start.install#6#li1":"Run  ava  in any project directory.","start.install#6#li2":"First run prompts you for a provider and a model. Pick and go.","start.install#7#c":"No account, no problem. With your own API key (BYOK) you never need to sign in. The free tier is for the platform-managed models.","concepts.memory#1#p":"Ava hat ein dauerhaftes Gedächtnis („dauerhaft\" heißt, es bleibt erhalten, auch wenn du die App schließt), das über Gespräche, Projekte und Geräte hinweg besteht, wenn du die Synchronisierung aktivierst (die Synchronisierung kopiert dein Gedächtnis zwischen deinen Geräten). Es ist kein Chat-Verlauf. Es ist ein strukturiertes, durchsuchbares Verständnis davon, wer du bist, was du magst und was du entschieden hast.","concepts.memory#2#h":"Fünf Ebenen","concepts.memory#3#li0":"Extrahieren — wichtige Fakten werden aus jeder Nachricht in Echtzeit erfasst.","concepts.memory#3#li1":"Reflektieren — tiefere Analysen laufen am Ende sinnvoller Sitzungen. Muster, Themen, Widersprüche.","concepts.memory#3#li2":"Sammeln — Korrekturen und Präferenzen summieren sich über Wochen und Monate auf.","concepts.memory#3#li3":"Analysieren — die Graph-Engine verknüpft zusammenhängende Erinnerungen und markiert Widersprüche, wenn neue Informationen mit alten kollidieren.","concepts.memory#3#li4":"Bündeln — ähnliche Erinnerungen verschmelzen; veraltete werden entfernt. Das Gedächtnis wird mit der Zeit schärfer, nicht lauter.","concepts.memory#4#c":"Die fünf Ebenen oben laufen eigenständig — du musst sie nie verwalten. Sie sind da, damit du sehen kannst, wie sich das Gedächtnis wirklich verbessert, anstatt zu einem Chaos an Daten zu werden.","concepts.memory#5#h":"Abrufen","concepts.memory#6#p":"Wenn du eine Frage stellst, sucht Ava im Gedächtnis nach Bedeutung („semantische Suche\" — sie versteht, was du meinst, also findet sie die richtige Erinnerung, selbst wenn du es anders formulierst). Modus-spezifische Filter laufen parallel — Chat-Modus zieht persönlichen Kontext, Arbeitsmodus zieht Projektentscheidungen und Code-Muster.","concepts.memory#7#c":"Das Gedächtnis ist pro Benutzer und pro Projekt begrenzt (deine Erinnerungen gehören dir, getrennt nach Person und Projekt). Geheimnisse und Zugangsdaten (Passwörter, Schlüssel) werden an der Speichergrenze blockiert — sie können niemals ins Gedächtnis gelangen.","reference.config#title":"Konfiguration","reference.config#0#p":"Diese Seite zeigt, wo Ava ihre Einstellungen und Dateien auf deinem Computer speichert. Du musst fast nie etwas davon manuell anfassen – die App erledigt das für dich. Hier findest du alles, wenn du diese Dateien selbst einsehen, sichern oder teilen möchtest.","reference.config#1#p":"Ava liest Konfigurationen (ihre gespeicherten Einstellungen) aus zwei Bereichen. Globale Einstellungen – die überall gelten – befinden sich in einem Ordner namens ~/.ava/ (das \"~\" steht abgekürzt für deinen Home-Ordner). Projekteinstellungen liegen in einem .ava/-Ordner direkt im Projekt.","reference.config#2#h":"Global — ~/.ava/","reference.config#3#li0":"settings.json — Modelleinstellungen, Berechtigungsmodus, Persönlichkeit, Sprache.","reference.config#3#li1":"memory/ — deine globalen Erinnerungen (Einstellungen, Entscheidungen, die überall gelten).","reference.config#3#li2":"tasks.json — projektübergreifende Aufgabenliste.","reference.config#3#li3":"journal/ — tägliche Journaleinträge, nach Datum sortiert.","reference.config#4#h":"Projekt — .ava/","reference.config#5#li0":"instructions.md — projektspezifische Anweisungen, die Ava immer lädt. Dauerhafter Kontext (\"wir nutzen pnpm, nicht npm\", \"API-Schlüssel liegen in 1Password\").","reference.config#5#li1":"context.md — optionale freie Projektnotizen.","reference.config#5#li2":"memory/ — Erinnerungen, die nur für dieses Projekt gelten.","reference.config#5#li3":"datasets/config.json — Konfiguration zur opt-in Datenerfassung.","reference.config#6#c":"Füge .ava/ zu deiner .gitignore hinzu (eine Liste von Dateien, die Git angewiesen ist, vom geteilten Projekt auszuschließen), wenn du keine Erinnerungen mit deinem Team teilen möchtest. Behalte instructions.md im Repository (dem geteilten Projektordner) – so lernt Ava die Projektkonventionen.","reference.shortcuts#title":"Tastenkürzel","reference.shortcuts#0#p":"Tastenkürzel sind optionale Beschleuniger – jedes davon ist auch ein Button, den du anklicken kannst. Schau hier nur nach, wenn du Ava schneller über die Tastatur steuern möchtest.","reference.shortcuts#1#p":"Kürzel nach Oberfläche (die drei Bereiche, in denen Ava läuft: die VS Code-Erweiterung, die Desktop-App und das Terminal). Passe sie in den Einstellungen jeder Oberfläche an. Du musst die folgende Liste nicht auswendig lernen.","reference.models#11#h":"Eigener Schlüssel","reference.models#12#p":"Ein „API-Schlüssel“ ist ein privates Passwort, das Software erlaubt, einen kostenpflichtigen Dienst auf Ihrem eigenen Konto zu nutzen. „BYOK“ bedeutet einfach nur „eigenen Schlüssel bringen“ – also Ihren eigenen statt unseren. Fügen Sie Ihren API-Schlüssel in den Einstellungen ein. BYOK-Anfragen gehen direkt von Ava zum Anbieter (dem Unternehmen, das das Modell betreibt) – sie durchlaufen nicht unsere Infrastruktur und verbrauchen keine Plattform-Token. Sie zahlen den Anbieter; wir sehen keinen Datenverkehr.","reference.models#14#c":"Für Benchmark-Werte, Fähigkeits-Tags und den Seitenvergleich sehen Sie sich die vollständige Modelle-Seite an unter ava-supernova.com/models. Die oben gezeigten Preise sind unser bestes Verständnis der Preislisten jedes Anbieters zum Zeitpunkt der Veröffentlichung – prüfen Sie immer die Website des Anbieters, bevor Sie sich auf eine Aufgabe festlegen.","reference.personas#title":"Orchestrierung von Rollen","reference.personas#0#p":"Eine „Persona“ ist eine Helfer-Rolle, die Ava im Hintergrund für schwierigere Aufgaben übernimmt – ein Entdecker, ein Planer, ein Faktenprüfer. Sie sprechen nie direkt mit ihnen und müssen diese Seite nicht verstehen, um Ava zu nutzen. Sie dient dazu, wenn Sie neugierig sind, wie sie eine große Aufgabe in ein kleines Expertenteam zerlegt.","reference.personas#1#p":"24 Spezialisten über 5 Modus-Teams hinweg. Der Dirigent (der Helfer, der den Rest koordiniert) entscheidet, welches Team läuft, in welcher Reihenfolge und mit welchem Kontext. Der Chat-Modus hat keine Personas – es ist Ava selbst.","reference.personas#2#h":"Wie die Orchestrierung abläuft","reference.personas#3#li0":"Sie senden eine Nachricht im Plan-, Lehr-, Sicherheits- oder Brainstorming-Modus (oder eine komplexe Arbeitsanfrage).","reference.personas#3#li1":"Der Dirigent liest die Anfrage, wählt das Modus-Team aus und erstellt einen Ausführungsplan – einige Personas laufen nacheinander, andere in parallelen Wellen.","reference.personas#3#li2":"Jede Persona hat ihr eigenes System-Prompt, eine eingeschränkte Tool-Erlaubnisliste und einen gemeinsamen Kontextpool dessen, was vorherige Personas gefunden haben.","reference.personas#3#li3":"Die letzte Persona erstellt je nach Modus eine Zusammenfassung, einen Plan oder einen Bericht.","reference.personas#3#li4":"Ava präsentiert Ihnen das Ergebnis. Sie genehmigen, ändern oder leiten um.","reference.personas#4#p":"Die vollständige Liste unten dient nur als Referenz – kein Grund, sich zu merken, wer was macht. Ava stellt das richtige Team für Sie zusammen.","reference.personas#6#c":"Der Arbeitsmodus ruft das volle Team nur für komplexe Aufgaben auf. Einfache Bearbeitungen führt Ava direkt aus – ohne Orchestrierungs-Overhead.","reference.project-context#title":"Projekt-Kontext","reference.project-context#0#p":"Hier erfahren Sie, wie Ava sich vor ihrem Start über Ihr Projekt informiert – welche Dateien sie anschaut, um zu verstehen, woran Sie arbeiten. Sie müssen nichts davon einrichten; das erledigt sie eigenständig. Lesen Sie es, wenn Sie wissen möchten, wo Sie eine Notiz platzieren können, damit sie diese immer sieht.","reference.project-context#1#p":"Wenn Sie ein Projekt öffnen, lädt Ava mehrere Ebenen von Kontextinformationen (Hintergrundwissen, das sie im Kopf behält). Zu verstehen, wie diese Ebenen funktionieren, hilft Ihnen dabei, Informationen am richtigen Ort abzulegen.","reference.project-context#2#h":"Automatisch geladen","reference.project-context#3#li0":".ava/instructions.md — wird als dauerhafte, hochpriorisierte Anleitung behandelt. Immer im Kontext vorhanden.","reference.project-context#3#li1":".ava/context.md — freie Notizen. Wird geladen, hat niedrigere Priorität.","reference.project-context#3#li2":"README.md — wird beim ersten Durchlauf nach einer Projektzusammenfassung durchsucht.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — die kleinen Dateien, die die Projektumgebung auflisten; werden gelesen, um Sprache, Framework und Testbefehl zu erkennen.","reference.project-context#3#li4":".gitignore — die Liste der Dateien, die nicht in die Versionskontrolle aufgenommen werden sollen; wird von allen Dateiwerkzeugen beachtet (glob, grep, project_index).","reference.project-context#4#h":"Bei Bedarf geladen","reference.project-context#5#p":"„Bei Bedarf\" bedeutet, dass Ava diese nur dann abruft, wenn eine Aufgabe sie tatsächlich benötigt, und nicht im Voraus.","reference.project-context#6#li0":"Projektindex — eine strukturierte Karte Ihrer Dateien und der benannten Teile darin (Funktionen, Klassen — „Symbole\") und wie sie verbunden sind („Importe\"). Wird erst bei Bedarf aufgebaut, also nur, wenn Ava ihn braucht.","reference.project-context#6#li1":"Git-Verlauf — die Aufzeichnung vergangener Änderungen; wird abgerufen, wenn git_status, git_diff oder git_create_pr aufgerufen werden (Git ist das Werkzeug, das jede Änderung am Projekt verfolgt; „Pull-Request\" ist ein vorgeschlagener Änderungsstapel).","reference.project-context#6#li2":"Speicher — Einträge werden nach Bedeutung („semantisch\") abgeglichen und einzeln eingefügt, nicht alle auf einmal.","reference.project-context#7#c":"Legen Sie Konventionen in instructions.md ab. Legen Sie Notizen in context.md ab. Lassen Sie den Speicher den Rest selbst erfassen.","troubleshooting.common-errors#title":"Häufige Fehler","troubleshooting.common-errors#0#p":"Die meisten Fehler haben eine kurze, spezifische Ursache. Hier sind die häufigsten und wie du sie behebst. Mach dir keine Sorgen, wenn der Text technisch klingt – jeder Punkt unten erklärt dir genau, was du siehst und was zu tun ist.","troubleshooting.common-errors#1#h":"Modell reagiert nicht","troubleshooting.common-errors#2#p":"Was du siehst: Ava wird still und antwortet nicht.","troubleshooting.common-errors#3#p":"Prüfe den Statusindikator im Chat-Kopfzeilenbereich. Steht dort \"Verbinden\", ist dein Anbieter (der KI-Dienst, mit dem Ava spricht) erreichbar, aber langsam – gib ihm dreißig Sekunden Zeit. Steht dort \"Nicht verfügbar\", ist Ava automatisch auf das nächste Modell in der Kette zurückgefallen (sie hat automatisch ein Backup-Modell gewählt). Wenn gar nichts passiert, überprüfe deinen API-Schlüssel in den Einstellungen und teste die Verbindung. (Ein API-Schlüssel ist das private Passwort, das Ava erlaubt, einen kostenpflichtigen KI-Dienst zu nutzen.)","troubleshooting.common-errors#4#h":"Werkzeugaufruf fehlgeschlagen","troubleshooting.common-errors#5#p":"Was du siehst: Einer von Avas Schritten (ein \"Werkzeugaufruf\" – etwa das Lesen einer Datei, Ausführen eines Befehls usw.) zeigt einen roten Fehler statt des Erfolgs.","troubleshooting.common-errors#6#p":"Klicke auf den fehlgeschlagenen Werkzeugaufruf, um den Fehler zu sehen. Häufige Ursachen: Sie wollte auf eine Datei außerhalb deines Projektordners zugreifen, was aus Sicherheitsgründen bewusst blockiert ist (diese Schutzmaßnahme heißt \"Path-Traversal\"-Schutz – sie verhindert, dass sie aus dem Ordner herauswandert, in dem du arbeitest); ein Befehl, der in einem anderen Ordner ausgeführt werden muss; oder eine Datei, die verschoben wurde, seit Ava sie zuletzt gesehen hat. Sag ihr, was schiefgelaufen ist – sie wird es mit Korrekturen erneut versuchen.","troubleshooting.common-errors#7#h":"Speicher erinnert sich nicht","troubleshooting.common-errors#8#p":"Was du siehst: Ava findet etwas nicht, wovon du sicher bist, dass sie es wissen sollte.","troubleshooting.common-errors#9#p":"Der Speicher funktioniert nach Bedeutung, nicht nach exakten Worten (das bedeutet \"semantisch\"). Also funktioniert \"Was habe ich bezüglich Auth entschieden?\" besser als \"finde meine Auth-Entscheidung\". Wenn der Speicher definitiv da ist, aber nicht angezeigt wird, öffne den Speicherbrowser und suche – wenn er dort nicht ist, wurde er überhaupt nicht gespeichert.","troubleshooting.common-errors#10#h":"Anmelde-Schleifen","troubleshooting.common-errors#11#p":"Was du siehst: Du meldest dich an, aber Ava fragt dich immer wieder neu nach der Anmeldung – eine Schleife, die dich nie durchlässt.","troubleshooting.common-errors#12#p":"Die Lösung ist, die gespeicherten Anmeldeinformationen zu löschen und neu zu starten: Führe in der Erweiterung \"Ava: Sign Out\" aus der Befehlspalette aus, verwende in der IDE Einstellungen → Konto → Abmelden, lösche in der CLI die Datei unter `~/.ava/auth.json` (eine kleine Anmelde-Datei in einem Ordner namens .ava in deinem Home-Verzeichnis). Melde dich dann erneut an.","troubleshooting.common-errors#13#h":"Token verbraucht","troubleshooting.common-errors#14#p":"Was du siehst: Eine Nachricht, dass du deine kostenlose Nutzung für diesen Monat aufgebraucht hast. (\"Tokens\" sind die Maßeinheit für KI-Nutzung – \"aufgebraucht\" bedeutet einfach, dass du dieses Monats kostenloses Kontingent verbraucht hast.)","troubleshooting.common-errors#15#p":"Das kostenlose monatliche Budget wird am 1. jedes Monats zurückgesetzt. Bis dahin wechsle zu einem BYOK-Anbieter (nutze deinen eigenen API-Schlüssel), um weiterarbeiten zu können. Dein Konto bleibt aktiv – nur die kostenlosen plattformverwalteten Anfragen sind pausiert.","troubleshooting.logs#title":"Wo Logs zu finden sind","troubleshooting.logs#0#p":"Ein \"Log\" ist einfach ein Tagebuch, das dein Computer führt, was passiert ist – nützlich, wenn etwas kaputtgeht und du (oder der Support) die Details sehen musst.","troubleshooting.logs#1#p":"Wenn du das rohe Bild brauchst – welches Werkzeug aufgerufen wurde, welche Informationen es bekam, was der KI-Dienst zurückgegeben hat – sind die Logs einfache Textdateien in einem Ordner auf deinem Computer unter `~/.ava/logs/` (ein Ordner namens .ava in deinem Home-Verzeichnis, mit einem logs-Ordner darin).","troubleshooting.logs#2#li0":"`~/.ava/logs/session-<date>.log` — Protokolle pro Sitzung einschließlich Werkzeugaufrufe, gestreamte Antworten und Fehler.","troubleshooting.logs#2#li1":"`~/.ava/logs/extension.log` — Log der VS Code-Erweiterungshosts. Aktivierungsfehler, Panel-Fehler.","troubleshooting.logs#2#li2":"`~/.ava/logs/ide.log` — Desktop-IDE-Log. Sidecar-Prozessnachrichten, Rust-Panics.","troubleshooting.logs#2#li3":"`~/.ava/logs/cli.log` — CLI-REPL-Log.","troubleshooting.logs#3#p":"In der Erweiterung öffnet \"Ava: Show Logs\" in der Befehlspalette das relevante Log in einem Editor-Tab. In der IDE hat Einstellungen → Diagnose einen Button \"Logs öffnen\". Die CLI kann ihr eigenes Log mit `ava logs --follow` anzeigen.","troubleshooting.logs#4#c":"Logs können Ausschnitte der Projektdateien enthalten, die Ava während einer Sitzung gelesen hat. Bitte prüfe sie vor dem Teilen.","troubleshooting.support-request#title":"Eine Supportanfrage stellen","troubleshooting.support-request#0#p":"Einfach ausgedrückt: Wenn etwas nicht funktioniert und die oben genannten Lösungen nicht helfen, lass es uns wissen. Am einfachsten fragst du Ava direkt danach.","troubleshooting.support-request#1#p":"Wenn ein Problem nicht unter den häufigen Fehlern fällt, reiche ein Support-Ticket ein (eine Anfrage an unser Support-Team). Das geht direkt in Ava (ohne Formular) oder im Web.","troubleshooting.support-request#2#h":"Innerhalb von Ava","troubleshooting.support-request#3#p":"Bitte sie darum. \\\"Ava, kannst du ein Support-Ticket dazu erstellen?\\\" Sie nutzt support_request, hängt den relevanten Sitzungskontext an (mit geschwärzten Zugangsdaten) und sendet ihn. Der schnellste Weg.","troubleshooting.support-request#4#h":"Über das Web","troubleshooting.support-request#5#p":"Besuche ava-supernova.com/support. Wähle eine Kategorie (Fehler, Funktion, Konto, Sicherheit, Allgemein) und beschreibe, was passiert ist. Wir antworten innerhalb eines Werktages.","troubleshooting.support-request#6#h":"Was du angeben solltest","troubleshooting.support-request#7#li0":"Was du erreichen wolltest.","troubleshooting.support-request#7#li1":"Was tatsächlich passiert ist.","troubleshooting.support-request#7#li2":"Welche Oberfläche (Erweiterung, IDE, CLI, Begleitprogramm) und welche Version.","troubleshooting.support-request#7#li3":"Alle Fehlermeldungen oder Log-Auszüge. Zugangsdaten vorher schwärzen.","troubleshooting.security-disclosure#title":"Sicherheitsvorfälle melden","troubleshooting.security-disclosure#0#p":"Einfach ausgedrückt: Wenn du entdeckt hast, wie Ava kompromittiert oder missbraucht werden könnte (eine \\\"Schwachstelle\\\" — eine Sicherheitslücke), sage es uns bitte zuerst privat, damit wir es beheben können, bevor jemand es ausnutzt. So geht’s über diese Seite.","troubleshooting.security-disclosure#1#p":"Schwachstelle gefunden? Vielen Dank. Wir nehmen jeden Hinweis ernst und arbeiten mit dir an der Lösung, bevor etwas öffentlich bekannt wird (bevor das Problem öffentlich angekündigt wird).","troubleshooting.security-disclosure#2#h":"So meldest du es","troubleshooting.security-disclosure#3#li0":"Schreibe eine E-Mail an security@ava-supernova.com mit einer Beschreibung, Schritten zur Reproduktion und deinem bevorzugten Zeitfenster für die Veröffentlichung.","troubleshooting.security-disclosure#3#li1":"Oder reiche ein Support-Ticket mit der Kategorie \\\"Sicherheit\\\" ein – dieselbe Bearbeitungsliste.","troubleshooting.security-disclosure#3#li2":"Wir melden uns innerhalb von 24 Stunden.","troubleshooting.security-disclosure#4#h":"Unsere Zusagen","troubleshooting.security-disclosure#5#li0":"Koordinierte Offenlegung — wir vereinbaren einen Zeitplan mit dir, bevor etwas öffentlich wird. Standardmäßig sind es 90 Tage.","troubleshooting.security-disclosure#5#li1":"Anerkennung — du wirst in den Notizen zur Behebung genannt, es sei denn, du bevorzugst Anonymität.","troubleshooting.security-disclosure#5#li2":"Keine rechtlichen Schritte — Forschung im guten Glauben ist willkommen. Wir schicken keine Anwälte hinter dir her.","troubleshooting.security-disclosure#6#c":"Die Sicherheitsseite unter ava-supernova.com/security enthält die vollständige Übersicht — Architekturgarantien, Schwärzungs-Tool, Zugriffskontrollen.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Brauchst du einen Bericht, eine E-Mail oder ein Dokument verfasst? Ava kann es entwerfen und dir eine echte Word-, Excel- oder PDF-Datei übergeben, die du öffnen und bearbeiten kannst wie jede andere.","features.office-suite#1#p":"Berichte, E-Mails und Dokumente – entworfen, formatiert und exportiert in native Formate (.docx ist Word, .xlsx ist Excel, .pdf ist ein PDF).","features.office-suite#2#li0":"report_generate – ein strukturiertes .docx, das auf Aufgaben, Journal, Erinnerung und Projektstatus zugreift.","features.office-suite#2#li1":"email_draft – tonangepasste E-Mail als .docx-Datei.","features.office-suite#2#li2":"document_manage – erstellen, lesen, bearbeiten, exportieren über Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Nützlich, wenn Ava im Namen schreibt – Statusberichte, Kickoff-Präsentationen, Kundenupdates. Die .docx landet in deinem Projekt, wo du sie nachbearbeiten kannst.","features.dashboard-library#title":"Dashboard-Bibliothek","features.dashboard-library#0#p":"Einfach gesagt: ein Regal, das alles hält, was du und Ava gemacht und besprochen hast, damit nichts verloren geht.","features.dashboard-library#1#p":"Eine durchsuchbare Ansicht von allem, was Ava mit dir produziert hat – generierte Bilder, Videos, Audio, Dokumente – neben deinen Gesprächen, Erinnerungen und Aufgaben. Ein Ort, um etwas zu finden, das du letzte Woche gemacht hast.","features.document-preview#title":"Dokumentenvorschau","features.document-preview#0#p":"Einfach gesagt: schau direkt dort hinein, wo du bist, ohne ein separates Programm zum Lesen zu öffnen.","features.document-preview#1#p":"Rechtsklick auf eine Word-Datei, Excel-Tabelle, PDF, CSV, HTML oder Markdown-Datei in deinem Projekt – Vorschau direkt im Editor ohne diesen zu verlassen. Nützlich zum Lesen von Referenzmaterial, das Ava erstellt hat, oder Dateien, die ein Kollege eingefügt hat.","features.daily-briefing#title":"Täglicher Überblick","features.daily-briefing#0#p":"Einfach gesagt: eine kurze \\\"hier ist, wo du aufgehört hast\\\"-Notiz jeden Morgen, damit du weitermachen kannst, ohne alles erneut zu lesen.","features.daily-briefing#1#p":"Morgendliche Zusammenfassung: Gestern-Journal, offene Aufgaben, Projektstatus und alle Erinnerungen, die Ava gesetzt hat. Optional – schalte es in den Einstellungen ein.","features.daily-briefing#2#p":"Das Briefing nutzt Erinnerungen, um relevante Kontexte hervorzuheben (\\\"letztes Mal, als du am Auth-Flow gearbeitet hast, hast du notiert, dass du die Refresh-Token-Strategie noch einmal überprüfen wolltest\\\"). Keine Nachrichtenquelle – ein fokussiertes Auffrischen.","features.unified-panel#title":"Einheitliches Bedienfeld","features.unified-panel#0#p":"Einfach ausgedrückt: Alles, was Ava tut, befindet sich in einem Fenster, sodass Sie nie durch Tabs suchen müssen, um es zu finden.","features.unified-panel#1#p":"Ein Panel für Chat, Dashboard, Gedächtnis, Aufgaben und Journal. Kein Wechseln zwischen Fenstern. Die Seitenleiste wählt aus, worauf Sie schauen; der Hauptbereich passt sich an.","features.unified-panel#2#p":"Der Gesprächszustand bleibt erhalten, wenn Sie weg navigieren – öffnen Sie Gedächtnis, prüfen Sie eine Aufgabe, dann kommen Sie zurück. Der Chat ist noch da, läuft weiter, wenn Ava noch läuft.","features.unified-panel#3#c":"Unified Panel ist ein Erweiterungs- und IDE-Konzept. Die Weboberfläche verwendet Browser-Tabs.","features.knowledge-packs#title":"Wissenspakete","features.knowledge-packs#0#p":"Einfach ausgedrückt: Geben Sie Ava einen Ordner Ihrer eigenen Dokumente, und sie kann daraus lesen, um Ihre Fragen zu beantworten. Ein \\\"Wissenspaket\\\" ist genau dieses Bündel von Dateien – Ihr Referenzmaterial, auf das sie zugreifen darf.","features.knowledge-packs#1#p":"Legen Sie ein Verzeichnis mit Referenzmaterial (Spezifikationen, RFCs, Meeting-Notizen, API-Dokumentationen) in ein Wissenspaket. Ava kann die relevanten Teile in den Kontext ziehen, wenn ein Gespräch das Thema berührt.","features.knowledge-packs#2#p":"Pakete werden lokal indiziert. Die Suche ist semantisch – Ava findet das richtige Dokument anhand der Bedeutung, nicht des Dateinamens. (\\\"Semantisch\\\" bedeutet, dass sie abgleicht, worum es in einem Dokument geht, sodass Sie sich weder die genauen Worte noch den Dateinamen merken müssen.) Pakete können mit einem Team geteilt oder privat gehalten werden.","features.workflows#title":"Workflows","features.workflows#0#p":"Ganz einfach: Zeige Ava eine Routine, die du immer wieder machst, gib ihr einen Namen, und sie kann das Ganze auf Abruf wiederholen. Ein \\\"Workflow\\\" ist einfach diese gespeicherte Routine – eine Reihe von Schritten, die Ava für dich wiederholt.","features.workflows#1#p":"Speichere eine Abfolge von Schritten, die du oft wiederholst – PR prüfen → Tests ausführen → Versionsnotizen schreiben → E-Mail entwerfen. Ein Workflow ist ein wiederverwendbarer Plan, den Ava mit verschiedenen Eingaben abspielen kann.","features.workflows#2#p":"Workflows werden projektbezogen in einem Ordner namens .ava/workflows/ innerhalb deines Projekts gespeichert. Teile sie mit deinem Team, indem du das Verzeichnis committest (in dein geteiltes Projekt speicherst, damit auch Teammitglieder Zugriff haben).","features.events#title":"Ereignisse und Benachrichtigungen","features.events#0#p":"Ganz einfach: Während Ava arbeitet, erhältst du eine übersichtliche Schritt-für-Schritt-Liste dessen, was sie tut, und eine Benachrichtigung, wenn ein langer Job fertig ist, damit du weggehen kannst.","features.events#1#p":"Während Ava läuft, siehst du strukturierte Updates, keine Textwüste. Jeder Tool-Aufruf, jede Übergabe an eine Persona, jedes gestreamte Delta ist ein diskretes Ereignis in der UI – erweiterbar für Details, zusammenklappbar für den Überblick.","features.events#2#p":"Hintergrundläufe senden Benachrichtigungen auf Betriebssystemebene, wenn sie abgeschlossen sind. Du kannst bei einem langen Build weggehen, und Ava meldet sich, wenn es fertig ist.","features.personality#title":"Persönlichkeits-Designer","features.personality#0#p":"Ganz einfach: Stelle ein, wie Ava mit dir spricht – plaudernd oder kurz, formell oder locker, mehr Witze oder weniger – damit sie so klingt, wie du magst.","features.personality#1#p":"Gestalte, wie Ava mit dir spricht. Tonfall, Energie, Wortwahl (wie viel sie sagt), Formalität, Humor. Regler und Voreinstellungen – knapper Ingenieur, warmer Mentor, trockener Kollege oder deine eigene Mischung.","features.personality#2#p":"Die Persönlichkeit beeinflusst die Formulierung, nicht die Kompetenz. Sie führt weiterhin dieselben Tools aus und folgt denselben Berechtigungsregeln. Ihr Name ist auf Ava festgelegt – das ist nicht verhandelbar.","features.release-notes#title":"Versionshinweise","features.release-notes#0#p":"Ganz einfach: Eine laufende Liste davon, was neu ist und was in jedem Update behoben wurde, damit du sehen kannst, was sich geändert hat.","features.release-notes#1#p":"Changelog in der App (ein Changelog ist die Historie der Änderungen). Jede ausgelieferte Version mit ihren Highlights, Fehlerbehebungen und Breaking Changes (Änderungen, die möglicherweise erfordern, dass du Anpassungen vornimmst, wie du etwas verwendest). Die Web-Oberfläche hält die öffentliche Version unter ava-supernova.com/releases bereit.","concepts.desktop-kill-switches#4#p":"Freezes on the next step boundary. Resumable. Use this when you want to intervene without losing the trajectory.","concepts.desktop-kill-switches#5#h":"Stop — Escape or the Stop button","concepts.desktop-kill-switches#6#p":"Clean abort. Narrator summarises what was done so far. Not resumable. Audit log commits.","concepts.desktop-kill-switches#7#h":"Panic kill — triple-Escape or Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"The hardest stop there is. A small, separate watchdog program force-quits the part of Ava that is driving your screen. It does not wait for the AI to respond, does not need the app window to be working, and does not care what state things are in — it just kills it. This is the one for when something is genuinely wrong.","concepts.desktop-kill-switches#9#p":"All three work from the companion app too. Either driver can end it.","reference.tools#title":"Tool reference","reference.tools#0#p":"This is the full lookup of every tool Ava has — a \"tool\" just being a specific action she can take, like reading a file or running a search. You do not need to read this page. Ava picks the right tool herself every time. It is here for when you are curious about exactly what she can do.","reference.tools#1#p":"The full built-in toolbox. Every tool here is registered in the core runtime (the engine underneath all three surfaces) and available to Ava when the mode and permission mode allow it. Filter by category or risk.","reference.tools#2#p":"No need to memorise any of this — the table below is just a reference card.","reference.tools#4#h":"Risk levels","reference.tools#5#li0":"Safe — reads things without changing anything. file_read, glob (find files by name pattern), grep (search inside files for text), git_status (Git is the system that tracks changes to your project).","reference.tools#5#li1":"Write — changes files, saves a checkpoint of your work (a \"commit\"), or produces something new. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Dangerous — runs commands on your computer (the \"shell\"), controls the desktop, goes out to the internet, or queries databases. bash, browser, desktop_*.","reference.tools#6#c":"Persona specialists have their own tool allowlists. Scout can read but not write. Builder has full access. Challenger has no tools at all — its job is to question the plan.","reference.models#title":"Models","reference.models#0#p":"A \"model\" is the AI brain doing the thinking — Qwen, DeepSeek, Mistral and others. This page lists every model Ava can use. The short version: you do not have to choose one. Ava picks the right model for each step herself. Read on only if you want to understand or override that.","reference.models#1#p":"Every model Ava can route to, plus the three orchestration strategies — the rules that decide which model handles each part of a job. Pick a routing mode and let Ava dispatch, or pick a single model and skip routing entirely.","reference.models#2#h":"Routing modes","reference.models#3#p":"Three orchestrated strategies. The same persona pipeline (the small team of specialist helpers Ava runs behind the scenes) runs on all three; what changes is the underlying fleet of models. Pick a mode in the model selector and Ava handles the rest. Each card below shows the constituent specialists the conductor routes to.","reference.models#4#p":"You do not need to memorise the cards below — they are here so you can see what each strategy is made of.","reference.models#6#c":"Aurora is deliberately Mistral-only. If a Mistral model is unavailable the router returns an error rather than cross-routing — that is the EU-stack guarantee. Pick Maestro or Supernova for graceful degradation.","reference.models#7#c":"All three modes are universally available — on platform credits and on your own keys. BYOK adds the option to bypass orchestration and drive a single model directly.","reference.models#8#h":"Platform-managed models","reference.models#9#p":"Available on every plan, including the free tier. Tokens (the units of text AI is measured in — roughly three-quarters of a word each) count against your plan allowance. The keys (the private passwords that unlock each paid model) are rotated and monitored by the platform — nothing for you to configure.","concepts.desktop-grounding#title":"Desktop-Verankerungshierarchie (Vorschau)","concepts.desktop-grounding#0#c":"Vorschau — wie Scout entscheidet, welche Verankerungsquelle in jedem Schritt verwendet wird.","concepts.desktop-grounding#1#p":"Bevor Ava auf einen Button klicken kann, muss sie wirklich verstehen, was auf deinem Bildschirm zu sehen ist und wo sich Dinge befinden — das ist die \"Verankerung\" (herausfinden, was jedes Element auf dem Bildschirm ist und seinen genauen Ort). Sie hat drei Möglichkeiten dafür und wählt die zuverlässigste, die für die App funktioniert, in der du bist. Das ist tiefergehender Detailgrad für Power-User; der Punkt ist einfach, dass sie solide, genaue Methoden dem Raten aus einem Bild vorzieht.","concepts.desktop-grounding#2#p":"Drei Ebenen, nacheinander geprüft. Die günstigste zuverlässige Quelle gewinnt.","concepts.desktop-grounding#3#h":"1. Browserfenster → Playwright DOM","concepts.desktop-grounding#4#p":"Wenn das aktive Fenster ein Webbrowser ist, liest Ava die Struktur der Seite selbst (das \"DOM\" — die zugrundeliegende Liste dessen, was auf einer Seite steht), statt aus dem Bild zu raten. Das Lesen der Struktur ist etwa 10× zuverlässiger als das Betrachten von Pixeln — sie weiß genau, wo jeder Button ist und wann die Seite fertig geladen ist. Dies ist der Hauptweg für alles im Web, kein Backup.","concepts.desktop-grounding#5#h":"2. Native App mit UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Für gewöhnliche Desktop-Apps unter Windows liest Ava eine eingebaute Zugänglichkeitskarte (\"UIA\", dieselben Daten, die Screenreader verwenden, um ein Fenster zu beschreiben\") — sie listet jede Steuerung, ihren Namen und ihre Position auf. Wenn diese Karte mindestens fünf nutzbare, benannte Elemente zurückgibt, vertraut sie darauf und nutzt sie.","concepts.desktop-grounding#7#h":"3. UIA leer oder unbrauchbar → OmniParser vision","concepts.desktop-grounding#8#p":"Wenn diese Karte fehlt oder nutzlos ist (einige Apps, Spiele und Remote-Bildschirme bieten keine), fällt Ava auf das tatsächliche Anschauen eines Screenshots zurück. Ein Vision-Tool (OmniParser) erkennt die klickbaren Bereiche und beschriftet, was jeder einzelne ist, und wandelt das Bild wieder in eine Liste um, auf die sie zugreifen kann — kombiniert mit dem Wenigen, das die Zugänglichkeitskarte doch noch geliefert hat.","concepts.desktop-grounding#9#c":"OmniParser ist beim ersten Mal, wenn Ava es benötigt, freiwillig aktivierbar, mit einem klaren Datenschutzhinweis. BYOK-Nutzer können auf ihre eigene lokale OmniParser-Instanz verweisen.","concepts.desktop-kill-switches#title":"Desktop-Notabschaltungen (Vorschau)","concepts.desktop-kill-switches#0#c":"Vorschau — drei unabhängige Wege, um einen laufenden Ablauf abzubrechen. Jeder einzelne davon reicht aus.","concepts.desktop-kill-switches#1#p":"Ein \"Notabschalter\" ist genau das, was der Name sagt — eine Notfallmöglichkeit, um Ava sofort zu stoppen, wenn sie deinen Bildschirm steuert. Das Beruhigende daran: Es gibt drei davon, jede separat gebaut, also wenn eine ausfällt, funktioniert eine andere weiter. Du musst nicht alle drei lernen. Einfach wissen, dass, wenn etwas falsch aussieht, du sie immer stoppen kannst, und die stärkste Stop-Methode (der Panik-Notabschalter unten) nicht darauf angewiesen ist, dass Ava kooperiert.","concepts.desktop-kill-switches#2#p":"Nachdem wir jeden öffentlichen Autonomie-Vorfall gelesen haben (echte Fälle, in denen KI-Agenten Stopp-Befehle ignorierten, E-Mail-Archive löschten, Laufwerke wischten), haben wir drei Notabschalter in drei verschiedenen Schichten gebaut. Keiner von ihnen hängt vom KI-Modell selbst ab — wenn Ava feststeckt oder nicht reagiert, kannst du sie trotzdem stoppen.","concepts.desktop-kill-switches#3#h":"Pause — Leertaste oder die Pause-Taste","models.routing#deeper#2#td5.0":"Chat","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Koordination der Bildgenerierung","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Visuelle Fähigkeiten","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (Sehencoder von Grund auf trainiert)","models.routing#deeper#2#td8.0":"Umfangreiche Texte verfassen","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Datenstandort","models.routing#deeper#2#td9.1":"Gemischt (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Gemischt (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Nur EU · offene Gewichte","models.routing#deeper#2#td10.0":"Status","models.routing#deeper#2#td10.1":"Aktiv · alle Pläne","models.routing#deeper#2#td10.2":"Demnächst verfügbar","models.routing#deeper#2#td10.3":"Demnächst verfügbar","models.routing#deeper#2#td11.0":"Ideal für","models.routing#deeper#1#h":"Nebeneinander","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Koordinator","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B aktiv, 1M Kontext)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B aktiv, 262K Kontext)","models.routing#deeper#2#td1.0":"Entwickler","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (greift auf Koordinator zurück)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B vollständig, 256K Kontext)","models.routing#deeper#2#td2.0":"Spezialisten der mittleren Ebene","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (Code-Prüfer, Faktenprüfer, Aufklärung, Scanner, Sicherheitsprüfer, usw.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Architekt, Prüfer, Sequenzierer, Tutor, Berichterstatter, usw.)","models.routing#deeper#2#td3.0":"Leichte Ebene / Eingangsfilter","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Aufklärer, Prüfer, Sequenzierer, Herausforderer, Verknüpfer)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Spezialisten für anspruchsvolle Aufgaben","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Forscher, Herausforderer, CVE-Forscher, Ideenentwickler, Faktenprüfer)","start.first-model#deeper#0#h":"What's actually in each style","start.first-model#deeper#1#p":"Maestro — one conductor (Qwen 3.6 Plus) handles every step. Production-tuned, proven, predictable cost.","start.first-model#deeper#2#p":"Supernova — a frontier coordinator (DeepSeek V4 Pro, 1.6T parameters / 49B active, 1M context) hands each subtask to a specialist: V4 Flash for high-volume builds, Qwen 3.6 Plus as fallback, Qwen Omni for vision.","start.first-model#deeper#3#p":"Aurora — Mistral only, in three tiers: Mistral Large 3 (coordinator + heavy specialists), Mistral Medium 3.5 (128B dense, 256K context, native vision, modified-MIT open weights, 77.6% SWE-Bench Verified) for Builder + mid-tier + vision + long-form, and Mistral Small 4 at the intent gate. Open weights end to end, never leaves EU infrastructure.","start.first-model#deeper#4#h":"Bring your own model (BYOK)","start.first-model#deeper#5#p":"Prefer to use your own AI account? Paste your provider key in settings and you get both — the three routing styles, plus the option to pick a single model and skip routing entirely. Useful for a strong preference, a strict budget, or testing a specific model. The full provider list is in the Reference section.","start.glossary#title":"Plain-English glossary","start.glossary#0#p":"Every word you might bump into around Ava, explained with no assumed knowledge. You do not need to memorise any of this — flip back whenever a term trips you up.","start.glossary#1#th0":"Word","start.glossary#1#th1":"What it actually means","start.glossary#1#td0.0":"Agent","start.glossary#1#td0.1":"An AI that can take actions for you — read a file, run a command, search the web — not just chat. Ava is an agent: she does things, with your say-so.","start.glossary#1#td1.0":"Model","start.glossary#1#td1.1":"The actual AI brain doing the thinking (Qwen, DeepSeek, Mistral, and others). Different models have different strengths. You normally never pick one — Ava does.","start.glossary#1#td2.0":"Mode","start.glossary#1#td2.1":"The mindset Ava is in. Like a colleague switching hats: builder, writer, teacher, planner, friend. You pick the mode; it changes how she behaves. There are seven.","start.glossary#1#td3.0":"Persona / specialist","start.glossary#1#td3.1":"Helper roles Ava runs behind the scenes for harder jobs — an explorer, a planner, a fact-checker. Think of a small expert team. You never talk to them directly; Ava coordinates them.","start.glossary#1#td4.0":"Routing","start.glossary#1#td4.1":"Ava deciding which model to use for each step so you get good answers without overpaying. It happens automatically — \"routing mode\" just picks the overall strategy.","start.glossary#1#td5.0":"Tool","start.glossary#1#td5.1":"A specific action Ava can take — read a file, run a search, send an email. A \"tool call\" is her using one. She asks permission before anything risky.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"How AI measures text — roughly ¾ of a word. Models are priced per million tokens. Mostly something you can ignore.","start.glossary#1#td7.0":"Credit","credits.overview#8#li4":"Orchestrierung — 10 Gutschriften. Vollständige Persona-Prozesskette starten (Conductor + Multi-Persona-Aufgabe).","credits.overview#8#li5":"Bildgenerierung — 12 Gutschriften. Hailuo image-01 über Creative Studio.","credits.overview#8#li6":"Videogenerierung — 150 Gutschriften. Hailuo 02 Pro 1080p 6s Clip.","credits.overview#8#li7":"Sprachgenerierung — 10 Gutschriften. Speech 2.8 HD-Synthese.","credits.overview#8#li8":"Musikgenerierung — 50 Gutschriften. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Hintergrundentfernung — 2 Gutschriften.","credits.overview#9#h":"Modell-spezifische Multiplikatoren","credits.overview#10#p":"Das hier ist für die Neugierigen — du brauchst es nicht, um Ava zu nutzen. Ein Multiplikator skaliert die Gutschriftenkosten einfach hoch oder runter, je nachdem, wie teuer das Modell hinter einer Aktion ist, also kosten schwerere Modelle etwas mehr. (\\\"Nettomarge\\\" ist der Anteil, den das Projekt nach Bezahlung seiner eigenen Rechnungen behält — wir zielen niedrig ab, damit der Wert zu dir zurückfließt.)","credits.overview#11#p":"Schwere Modelle multiplizieren die Kosten pro Aktion, sodass die Gutschriften die tatsächlichen Ausgaben widerspiegeln und nicht nur eine Pauschale abbilden. Kalibriert auf ca. 55 % Nettomarge.","credits.overview#12#li0":"0.6× — Mistral Small 4 (Auroras Spezialistenrolle). Unter 1×, da Mistral Small 4 günstiger ist als der Qwen 3.6 Plus Referenzpunkt.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Basisrate.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (Aurora Koordinator). Ungefähr gleichwertig mit dem Qwen 3.6 Plus Referenzpunkt.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (Maestro Koordinator).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (Supernova Koordinator + schwere Spezialisten). Neu kalibriert von 5.0×, um Margengleichheit zum veröffentlichten V4 Pro Preis wiederherzustellen.","credits.overview#13#c":"Anthropic-Modelle (Claude Opus / Sonnet / Haiku) werden komplett ohne Gutschriften-Abrechnung genutzt — sie sind nur per BYOK verfügbar und du zahlst direkt an Anthropic. Gleiches gilt für jeden anderen BYOK-Anbieter, wenn er mit deinem eigenen Schlüssel verwendet wird.","credits.overview#14#h":"BYOK und Gutschriften","credits.overview#15#p":"BYOK (\\\"Bring Your Own Key\\\" — du stellst dein eigenes Konto bei einem KI-Anbieter bereit und einen Schlüssel, das ist ein privates Passwort, das Software erlaubt, dieses bezahlte Konto zu nutzen) ist für Leute, die bereits direkt bei einem KI-Anbieter zahlen. Wenn das nicht auf dich zutrifft, kannst du diesen Abschnitt völlig ignorieren.","credits.overview#16#p":"Anfragen \\\"Bring Your Own Key\\\" umgehen die Plattforminfrastruktur vollständig — der Aufruf geht direkt von Ava zum Anbieter, du zahlst den Anbieter, keine Gutschriften werden verbraucht. Die einzige Ausnahme ist, wenn eine BYOK-Sitzung eine verwaltete Persona für eine Teilaufgabe startet; der Gutschriftenabzug gilt trotzdem, weil Avas Orchestrationsfläche genutzt wird.","credits.overview#17#h":"Wo du dein Guthaben prüfen kannst","credits.overview#18#li0":"Erweiterung — Einstellungen → Konto, oder die Guthaben-Anzeige in der Chat-Kopfzeile.","credits.overview#18#li1":"IDE — Das Konto-Dashboard zeigt aktuelles Guthaben und Verbrauch an.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard zeigt Guthaben, Verlauf und Verlängerungsdatum an.","credits.overview#19#c":"Lokal-first: Ava funktioniert ohne Konto auf der Karte für benutzerdefinierte Modelle (Ollama, LM Studio, vLLM oder beliebige OpenAI-kompatible Endpunkte). Keine Gutschriften, keine Plattform-Tokens — dein Modell, deine Maschine, deine Rechnung null.","concepts.modes#title":"Modi — Avas Denkweisen","models.routing#deeper#2#td11.1":"Tägliche Arbeit, planbare Kosten","models.routing#deeper#2#td11.2":"Schwere mehrstufige Aufgaben, Spitzen-Koordinator in jedem Tarif","models.routing#deeper#2#td11.3":"GDPR-konform, öffentlicher Sektor, souveräne EU-Infrastrukturen","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Stufenbasiertes Qwen-Routing mit geringem Aufwand. Qwen 3.6 Plus übernimmt die Koordination, Builder, Planung, Sicherheit, Brainstorming und Arbeiten mit langem Kontext – genau dort, wo sein hybrider Linear-Attention-Mechanismus mit 1M-Kontext seine Stärken ausspielt. Qwen 3.5 Flash kümmert sich um Chat, Bildgenerierungs-Orchestrierung und das Upstream-Intent-Tor, wo seine Preisgestaltung von $0.07/$0.26 und schnellere TTFT bei der Mehrheit des Token-Volumens mit geringer Tiefe gewinnen. Qwen 3.5 Omni Plus übernimmt die Vision-Eingabe (Qwen 3.6 Plus hat keine native Vision). Qwen 3.5 Plus übernimmt kostenempfindliche Langtext-Arbeiten. Fällt es bei Ausfall des primären Koordinators durch die Prioritätsleiter: Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Polyglottes Ensemble. DeepSeek V4 Pro koordiniert und verteilt jede Teilaufgabe an den am besten geeigneten Spezialisten: Qwen 3.6 Plus führt jeden Builder-Spawn aus, V4 Flash kümmert sich um Chat sowie die Review-/Audit-Personas der mittleren Stufe, Qwen 3.5 Flash übernimmt die Klassifizierungsarbeit der leichten Stufe, Qwen 3.5 Omni Plus übernimmt die Vision-Eingabe, Qwen 3.5 Omni Flash orchestriert Bildgenerierungs-Tool-Calls, Qwen 3.5 Plus trägt die kostenempfindliche Langtext-Persona Content Writer. Spitzen-Reasoning, wo es wichtig ist; Flash-Tier-Wirtschaftlichkeit beim Großteil des Token-Volumens.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Europäischer KI-Stack — souverän von Grund auf. Nur Mistral-Routing in drei Stufen: Mistral Large 3 (675B/41B-active sparse MoE) übernimmt die Koordinator-Rolle sowie die schweren Spezialisten, die Tiefe benötigen – Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier – und die Langtext-Grundarbeit, wo seine sparse-MoE-Effizienz gewinnt. Mistral Medium 3.5 – der zusammengeführte Flaggschiff-Release vom April 2026, 128B dicht, 256K Kontext, Vision-Encoder von Grund auf trainiert, modifizierte-MIT Offene Gewichte, 77,6 % SWE-Bench Verified – betreibt die eigentliche Arbeitsebene: Builder-Spawns, mittlere Spezialisten (Architect, Verifier, Sequencer, Tutor, Reporter), Vision-Eingabe und Langtext-Schreiben. Mistral Small 4 wurde von einer einzelnen Rolle am Intent-Tor erweitert, um auch Chat und Bildgenerierungs-Orchestrierung zu übernehmen – seine Preisgestaltung von $0.15/$0.60 und konfigurierbares Reasoning rechtfertigen ihren Einsatz auf den hochvolumigen Routen mit geringer Tiefe. Offene Gewichte Ende-zu-Ende, verlässt niemals die EU-Infrastruktur. Aurora kreuzt bewusst nicht stillschweigend auf ein Nicht-Mistral-Modell um, wenn eines nicht verfügbar ist; der Router zeigt stattdessen einen Fehler an – das macht es zu \"Aurora\" statt zu einem Mistral-ähnlichen Maestro.","credits.overview#title":"Ava Credits – so funktioniert die Abrechnung","credits.overview#0#p":"Credits sind einfach die Methode, mit der Ava Ihren Verbrauch misst – ähnlich wie Minuten auf einem Handyvertrag. Jeder Tarif, auch der kostenlose, kommt mit einem Credit-Pool, und jedes Ding, das Ava tut (Ihnen antworten, ein Bild erstellen), kostet eine kleine Anzahl davon. Das ist die ganze Idee. Die Details unten sind dafür da, wenn Sie genau wissen wollen, was was kostet.","credits.overview#1#p":"Ava berechnet in Credits, nicht in rohen Token. (Ein \"Token\" ist das winzige Textstück – grob ein paar Buchstaben –, das KI-Modelle lesen und schreiben; die meisten Dienste berechnen pro Token, was schwer vorhersehbar ist.) Ein Credit deckt eine Arbeitseinheit ab – einen Chat-Durchgang, eine Persona-Erstellung (ein Helfer, der einen Teil der Aufgabe erledigt), eine Bildgenerierung. Die Entkopplung von der Token-basierten Messung bedeutet, dass Sie nicht wissen müssen, welches Modell läuft, um zu wissen, was eine Aktion kostet. Der gleiche Chat-Durchgang kostet gleich viel, egal ob Maestro ihn an Qwen 3.6 Plus weiterleitet oder Supernova ihn an V4 Pro.","credits.overview#2#h":"Tarife","credits.overview#3#p":"Jeder Tarif bietet Zugriff auf alle Funktionen – Modellzugriff, Creative Studio, alle sieben Modi, die vollständige Persona-Orchestrierung. Höhere Stufen kaufen mehr Credits und ein höheres Anfrage-Limit, keine freigeschalteten Features.","credits.overview#4#li0":"Kostenlos — $0/Monat. 300 Credits. 20 Anfragen/Minute Limit. Keine Karte erforderlich.","credits.overview#4#li1":"Pro — $19/Monat. 5.000 Credits. 60 Anfragen/Minute.","credits.overview#4#li2":"Ultra — $39/Monat. 10.000 Credits. 120 Anfragen/Minute.","credits.overview#4#li3":"Enterprise — $79/Monat. 20.000 Credits. 200 Anfragen/Minute.","credits.overview#5#c":"Unverbrauchte Credits bleiben während Ihres aktiven Abonnements erhalten – es gibt keine erzwungene Rücknahme. Aufladungen stapeln sich im Abo-Pool: 750 Credits für $3, 2.000 für $8, 4.000 für $15.","credits.overview#6#h":"Was Dinge kosten","credits.overview#7#p":"Kosten-Tabelle pro Aktion – was von Ihrem Credit-Pool abgezogen wird, wenn jede Aktion ausgeführt wird. (Ein \"Cache Treffer\" ist, wenn Ava bereits geleistete Arbeit wiederverwendet, statt sie neu zu machen; wenn das passiert, zahlen Sie weniger – die Gebühr sinkt um 70 %, oder 50 % bei ausgabenintensiven Modellen wie DeepSeek V4 Pro.)","credits.overview#8#li0":"Chat-Durchgang — 2 Credits. Ein einmaliger Hin- und Her-Dialog in jedem Modus.","credits.overview#8#li1":"Leichte Anfrage — 1 Credit. Intent-Tor, Klassifizierung, Single-Shot-Lesevorgang.","credits.overview#8#li2":"Schwere Persona — 3 Credits. Architect, Researcher, CVE Researcher, Ideator (Tiefe ≥ 4).","credits.overview#8#li3":"Leichte Persona — 1 Credit. Scout, Verifier, Sequencer, Challenger (Tiefe ≤ 2).","reference.cli#5#li3":"--project <path> — den Projektstamm explizit festlegen.","reference.desktop-budget#title":"Desktop-Budgetlimits","reference.desktop-budget#0#p":"Wenn Ava Ihren Desktop stellvertretend steuert – klickt, tippt, Apps öffnet –, wird jeder Durchlauf als „Trajektorie“ bezeichnet. Diese Seite erklärt die Sicherheitsgrenzen, die verhindern, dass ein einzelner Durchlauf zu lange läuft oder zu viel kostet. Das Wichtigste: Sie hält immer an und meldet sich, bevor sie das Limit überschreitet. Die Zahlen finden Sie hier, wenn Sie Details wünschen.","reference.desktop-budget#1#p":"Jeder Durchlauf läuft unter drei gleichzeitigen Limits (harte Grenzen). Das erste erreichte Limit gewinnt. Der Durchlauf setzt nie stillschweigend über eine Verletzung hinaus fort – der Erzähler (der Assistent, der Sie durch das Geschehen führt) pausiert und fragt, was zu tun ist.","reference.desktop-budget#2#h":"Drei harte Limits (Standard)","reference.desktop-budget#3#li0":"Schrittanzahl — 30 Schritte","reference.desktop-budget#3#li1":"Token-Budget — 500.000 Token","reference.desktop-budget#3#li2":"Uhrzeit — 5 Minuten","reference.desktop-budget#4#h":"Aufgabenkosten-Bereiche","reference.desktop-budget#5#li0":"Einfach (Dokumente suchen, Seite öffnen) — 5–10 Schritte, ~70–135K Token, ~0,04–0,08 $","reference.desktop-budget#5#li1":"Mittel (Einloggen, Logs prüfen, Ausgabe herunterladen) — 15–25 Schritte, ~205–340K Token, ~0,12–0,21 $","reference.desktop-budget#5#li2":"Komplex (drei GitHub Issues triagieren) — 25–30 Schritte, ~340–410K Token, ~0,21–0,25 $","reference.desktop-budget#6#p":"Die Token-Zahlen oben sind die technischen Limits pro Durchlauf, nicht Ihr monatliches Kontingent – das wird in Credits gezählt, und die kostenlosen 300 pro Monat decken bequem eine Mischung aus Chat, Code und ein paar Automatisierungen ab.","reference.desktop-budget#7#c":"Sie können Limits pro Aufgabe zu Beginn überschreiben, aber Verstöße zeigen immer einen Entscheidungspunkt auf. Budget wird niemals stillschweigend verbrannt.","reference.desktop-whitelist#title":"Desktop-Sitzungs-Zulassungsliste","reference.desktop-whitelist#0#p":"Eine „Zulassungsliste\" ist einfach die Liste der Apps und Websites, bei denen Sie Ava erlaubt haben, zuzugreifen, während sie Ihren Desktop steuert. Diese Seite erklärt, wie Sie diese Berechtigung erteilen und warum sie jedes Mal zurückgesetzt wird. Kurz gesagt: Sie kann nur dort handeln, wo Sie es zulassen, und fragt vor dem Betreten neuer Bereiche nach.","reference.desktop-whitelist#1#p":"Einfache Sprache funktioniert: „Gmail, Cursor, das Azure-Portal.\" Sie liest das und bestätigt die Übereinstimmung mit Ihnen („Gmail Web, Cursor die App, portal.azure.com\").","reference.desktop-whitelist#2#h":"Wie es durchgesetzt wird","reference.desktop-whitelist#3#p":"Nur-Lese-Aktionen – ein Screenshot, das Lesen der Liste von Buttons und Feldern auf dem Bildschirm (der „UIA-Baum\", Windows eigene Karte dessen, was in einem Fenster ist) – sind überall erlaubt, weil Sie sehen müssen, was auf dem Bildschirm ist, um zu entscheiden, ob Sie eine App zur Zulassungsliste hinzufügen möchten. Alles, was etwas ändert, ist außerhalb der Liste blockiert; Ava pausiert und fragt, ob hinzugefügt werden soll.","reference.desktop-whitelist#4#h":"Sitzungsbezogen, bewusst","reference.desktop-whitelist#5#p":"Die Zulassungsliste bleibt NICHT über Sitzungen hinweg bestehen. Es gibt keine Option „diese App merken\". Jeder neue Durchlauf beginnt mit einem frischen Bereich. Unbequem aus Designgründen – das Vergessen einer erneuten Autorisierung ist ein Feature, kein Bug.","reference.desktop-whitelist#6#h":"Nachträgliche Ergänzungen während des Durchlaufs","reference.desktop-whitelist#7#p":"Während eines Durchlaufs können Sie Apps aus der Kopfzeile hinzufügen: „+ App erlauben\" öffnet eine kleine Eingabe. Tippen Sie auf Hinzufügen, und die neue App ist für den Rest der Sitzung aktiv.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Möchten Sie ein Bild, ein kurzes Video, einen Song oder eine Sprachaufnahme erstellen? Beschreiben Sie es einfach, und Ava erstellt es für Sie – keine Design- oder Audio-Software erforderlich.","start.first-five#5#li0":"Eine Frage — \"Warum ist meine Seite leer?\", \"Was macht diese Datei?\"","start.first-five#5#li1":"Etwas erstellt — \"Erstelle mir eine einfache To-Do-Listen-Seite\".","start.first-five#5#li2":"Etwas lernen — \"Bringe mir Python von Grund auf bei\". (Immer kostenlos.)","start.first-five#5#li3":"Ein Dokument — \"Schreibe mir einen einseitigen Projektantrag\". Sie übergibt dir dann eine Word-Datei oder ein PDF.","start.first-five#6#c":"Nicht sicher, was du eingeben sollst? Sprich mit ihr wie mit einem wissenden Freund. Einfache Wörter sind genau richtig – du brauchst nie Fachbegriffe, um loszulegen.","start.first-five#deeper#0#p":"Diese einfache Schleife erledigt im Hintergrund einiges. Du brauchst das alles nicht, um Ava zu nutzen – aber hier erfährst du, was tatsächlich passiert, wenn du neugierig bist.","start.first-five#deeper#1#h":"Werkzeuge und Genehmigung","start.first-five#deeper#2#p":"Wenn Ava eine Datei liest, einen Befehl ausführt oder Code bearbeitet, ist jedes davon ein \"Tool Call\". Sie fragt vor allem, das deine Dateien oder System berührt – wie oft sie fragt, wird durch deinen Berechtigungsmodus festgelegt (jedes Mal fragen, nur bei riskanten Dingen fragen, oder einfach loslegen).","start.first-five#deeper#3#h":"Modi – ihre Denkweisen","start.first-five#deeper#4#p":"Ava arbeitet in Modi: eine Denkweise plus das richtige Werkzeugset für die Aufgabe. Wechsle jederzeit über den Picker oder gib am Anfang deiner Nachricht ein Präfix. Es gibt sieben.","start.first-five#deeper#6#h":"Spezialisten und Routing","start.first-five#deeper#7#p":"Bei schwierigeren Aufgaben setzt Ava im Hintergrund ein kleines Team aus Spezialisten-Helfern ein (ein Planer, ein Prüfer, ein Ersteller) und leitet jeden Schritt an das Modell weiter, das dafür am besten geeignet ist. Du musst das nie selbst verwalten – sie koordiniert es für dich.","start.local-vs-cloud#title":"Lokal vs. Cloud, in einem Absatz","start.local-vs-cloud#0#p":"Alles, was Ava tut, ist lokal, es sei denn, du stimmst ausdrücklich zu. Speicher, Aufgaben, Journal, Persönlichkeit, Einstellungen – alles auf deinem Rechner in ~/.ava/ und .ava/ (projektbezogen). Sie spricht mit Model-Anbietern über HTTPS, um deine Anfrage auszuführen, und kehrt dann nach Hause zurück. Sie ruft nicht nach Hause. Sie sammelt keine Telemetrie. Sie trainiert nicht an deinem Code.","start.local-vs-cloud#1#p":"Wenn du dich anmeldest, erhältst du 300 kostenlose Credits pro Monat für plattformverwaltete Modelle (Qwen, MiniMax) und optionale Cloud-Synchronisation für Speicher und Einstellungen über Geräte hinweg. Synchronisation ist pro Feature, jederzeit widerrufbar. Bringe deinen eigenen API-Schlüssel mit und Ava funktioniert vollständig ohne Konto.","start.local-vs-cloud#2#c":"Die Regel: Lokal ist heilig. Cloud ist Zusatz.","start.first-model#title":"Muss ich eine KI auswählen?","start.first-model#0#p":"Hier ist eine Erleichterung: Du wählst die KI nicht. Ava wählt automatisch die richtige für jeden Schritt, damit du gute Ergebnisse bekommst, ohne darüber nachdenken zu müssen.","start.first-model#1#p":"Das Einzige, was du wählen kannst, ist ein Routing-Stil – und der Standard passt fast allen. Du brauchst die anderen nur aus einem bestimmten Grund.","start.first-model#2#h":"Die drei Stile","start.first-model#3#li0":"Maestro – der Standard. Beständig, zuverlässig, vorhersehbar. Unsicher? Das ist der richtige.","start.first-model#3#li1":"Supernova – für schwere, mehrstufige Arbeiten, wo es sich lohnt, für jeden Teil der Aufgabe einen anderen Spezialisten einzusetzen.","start.first-model#3#li2":"Aurora – wenn deine Daten in der EU bleiben müssen (öffentlicher Sektor, Gesundheitswesen, strenge Datenschutz). Läuft vollständig auf europäischer, Open-Weight-KI.","start.first-model#4#p":"Wechsle jederzeit über den Modell-Picker oben im Chat. Nichts ist festgelegt.","start.first-model#5#c":"Möchtest du selbst ein bestimmtes Modell steuern? Das geht – öffne \"Zeig mir die Details\".","start.glossary#1#td7.1":"Eine einfachere Einheit von Ava für die Kosten einer Aktion, damit du dich nicht um Token-Rechnerei kümmern musst. Deine Pläne beinhalten ein monatliches Kontingent.","start.glossary#1#td8.0":"API-Schlüssel","start.glossary#1#td8.1":"Ein geheimes Passwort, das Software erlaubt, einen kostenpflichtigen Dienst (wie ein KI-Modell) in deinem Namen zu nutzen. Du benötigst nur einen, wenn du deinen eigenen Schlüssel verwenden möchtest.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Bring Your Own Key.\" Nutze deinen eigenen API-Schlüssel statt Avas verwaltetem Zugriff. Optional – für alle, die bereits direkt bei einem Anbieter bezahlen.","start.glossary#1#td10.0":"Lokal zuerst","start.glossary#1#td10.1":"Deine Daten bleiben standardmäßig auf deinem eigenen Computer. Es wird nichts hochgeladen, es sei denn, du aktivierst die Synchronisation. \"Lokal ist heilig.\"","start.glossary#1#td11.0":"Berechtigungsmodus","start.glossary#1#td11.1":"Wie vorsichtig Ava ist, bevor sie etwas ausführt – jedes Mal nachfragen, nur bei riskanten Aktionen fragen oder einfach loslegen. Du bestimmst das Maß.","start.glossary#1#td12.0":"Kontextfenster","start.glossary#1#td12.1":"Wie viel Text ein Modell gleichzeitig im Gedächtnis hat – sein Kurzzeitgedächtnis. \"1M Kontext\" bedeutet etwa eine Million Wörter. Je größer, desto mehr kann es lesen, bevor es vergisst.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"Eine Gegenüberstellung, die genau zeigt, was sich in einer Datei ändern wird – Alt auf der einen, Neu auf der anderen Seite – angezeigt, bevor Ava etwas verändert, damit du zustimmen kannst.","start.glossary#1#td14.0":"Repository (repo)","start.glossary#1#td14.1":"Ein Projektordner, der auf Änderungen überwacht wird, normalerweise mit Git. Falls dir das noch nichts sagt, ist es einfach \"der Ordner, in dem mein Projekt liegt.\"","start.glossary#1#td15.0":"Prompt","start.glossary#1#td15.1":"Was du der KI eingibst – deine Frage oder Anweisung.","start.glossary#2#c":"Immer noch unsicher bei einem Begriff? Frag Ava im Chat-Modus – \"Was bedeutet X?\" – und sie erklärt es passend für dein Niveau.","models.routing#title":"Routing — wie Ava Modelle auswählt","models.routing#0#p":"Hier die Kurzfassung: Du musst nie selbst entscheiden, welches KI-Modell du nutzt. Ava erledigt das für dich und wählt das passende Werkzeug für jeden Teil der Aufgabe – so wie ein guter Manager die richtige Arbeit an die richtige Person weitergibt.","models.routing#1#p":"Du wählst einen von drei Modi — Maestro, Supernova oder Aurora — und Ava leitet jeden Arbeitsauftrag an das Modell weiter, das ihn am besten bewältigt. Maestro ist der Standard, er läuft auf jedem Plan und ist für fast alle eine gute Wahl.","models.routing#2#h":"Warum Routing überhaupt?","models.routing#3#p":"Das richtige Modell für jeden Schritt einzusetzen kostet weniger, als alles auf einem einzigen großen, teuren Modell laufen zu lassen – und liefert bessere Ergebnisse, weil jedes Modell das tut, worin es besonders gut ist. Du hast stabile Kosten und hohe Qualität, ohne jemals wissen zu müssen, welches Modell welches ist.","models.routing#4#c":"Alle drei Modi funktionieren mit Plattform-Guthaben und deinen eigenen Schlüsseln. Mit deinem eigenen Schlüssel kannst du das Routing auch überspringen und ein einzelnes Modell direkt ansteuern. Die vollständige Übersicht findest du unter \"Zeig mir die Details\".","models.routing#deeper#0#c":"Die \"B\"-Werte unten stehen für Milliarden Parameter – grob gesagt, wie groß das \"Gehirn\" eines Modells ist. Größer bedeutet meist intelligenter, aber auch langsamer und teurer. Das ist technisches Detailwissen unter der Haube; du brauchst es nie, um Ava zu nutzen.","features.creative-studio#1#p":"Bild-, Video-, Musik- und Sprachgenerierung – integriert in denselben Workflow wie dein Code. Erstelle ein Icon, einen Produkt-Mockup, ein Demo-Video, eine Voiceover für ein Tutorial. Angetrieben von MiniMax.","features.creative-studio#2#h":"Was du erstellen kannst","features.creative-studio#3#li0":"Bilder — Prompt zu PNG/JPG. Hintergrundentfernung nur einen Klick entfernt.","features.creative-studio#3#li1":"Video — kurze KI-Videos aus einem Text-Prompt (MiniMax Hailuo).","features.creative-studio#3#li2":"Musik — instrumentale oder vokale Tracks mit Texten.","features.creative-studio#3#li3":"Stimme — Text-zu-Sprache mit wählbaren Stimmen.","features.creative-studio#4#p":"Die Kosten für Creative Studio stammen aus demselben Guthabenpool wie alles andere – ein Pool, eine Zahl. BYOK deinen eigenen MiniMax-Schlüssel und es ist in deinem Plan kostenlos.","features.creative-studio#5#c":"Creative Studio ist für die kostenlose Ebene berechtigt. Kein kostenpflichtiges Add-on.","features.desktop-automation#title":"Desktop-Automatisierung","features.desktop-automation#0#p":"Einfach gesagt: Ava kann deine Maus und Tastatur übernehmen, um Aufgaben für dich auszuführen – eine App öffnen, auf Buttons klicken, Formulare ausfüllen –, während du zuschaust und alles Wichtige genehmigst.","features.desktop-automation#1#p":"Ein neuer Modus für Ava, Präfix @@. Sie beobachtet den Desktop, entscheidet, was zu tun ist, und steuert die UI-Automatisierung (kontrolliert die Apps auf deinem Bildschirm für dich), um es fertig zu bekommen. Läuft auf deiner echten Maschine mit deinen echten Zugangsdaten – kein Cloud-Browser. Verfügbar in jeder Stufe, sobald ausgeliefert.","features.desktop-automation#2#h":"Warum noch einer?","features.desktop-automation#3#p":"Jedes andere Desktop-Automatisierungsprodukt ist etwas, das du startest, wenn du an deinem Schreibtisch sitzt. Ava ist diejenige, die immer noch da ist, wenn dein Fehler-Tracker um 2 Uhr nachts feuert – IDE läuft weiter, dein Telefon koppelt sich über einen sicheren Kanal, du genehmigst unwiderrufliche Schritte mit einem Tippen.","features.desktop-automation#4#p":"Sie erinnert sich auch daran, wie man durch deine Apps navigiert, über Sitzungen hinweg. Jeder andere Assistent muss sie jedes Mal neu lernen. Der Speicher-Vorteil nimmt mit der Nutzung zu.","features.desktop-automation#5#h":"Wie es funktioniert","features.desktop-automation#6#p":"Jeder Schritt führt einen Fünf-Rollen-Modus aus: Späher beobachtet, Planer wählt den nächsten Schritt, Akteur führt ihn aus, Prüfer kontrolliert, Erzähler berichtet dir, was passiert ist. Das Sidecar wählt die günstigste zuverlässige Basis – UIA für native Apps, Playwright für Browser, OmniParser Vision, wenn sonst keine nützliche Struktur vorhanden ist.","features.desktop-automation#7#p":"Siehe die Konzeptseiten für Sicherheitsontologie, Hierarchie der Verankerung, Kill Switches und das Session-Whitelist-Modell.","start.what#title":"Was ist Ava?","start.what#0#p":"Ava ist eine KI, die tatsächlich etwas macht – nicht nur redet. Sie baut dir eine App, schreibt dir ein Dokument, bringt dir etwas von Grund auf bei, entwirft dir ein Logo oder erledigt die Verwaltungsaufgaben, die du immer wieder aufschiebst. Und sie erinnert sich an dich: woran du arbeitest, wie du Dinge magst, was du letzte Woche gefragt hast.","start.what#1#p":"Es gibt nur eine Ava, und sie arbeitet überall dort, wo du arbeitest – in deinem Code-Editor, als Desktop-App, auf deinem Handy oder im Terminal. Gleicher Speicher, gleiche Persönlichkeit, überall.","start.what#2#h":"Was macht sie anders?","start.what#3#li0":"Von Haus aus deine. Deine Arbeit bleibt auf deinem eigenen Gerät. Kein Tracking, keine Telemetrie – nie.","start.what#3#li1":"Für jeden einsehbar. Jede Zeile von Ava ist öffentlich. Nichts, dem man blind vertrauen muss.","start.what#3#li2":"Kostenlos starten. 300 Credits jeden Monat, keine Karte, kein Haken – oder steck deine eigenen KI-Schlüssel ein und zahl uns gar nichts.","start.what#3#li3":"Lehren ist kostenlos, für immer. Lernen sollte keinen Preis haben.","start.what#4#p":"Noch nie Code geschrieben? Die nächste Seite ist genau für dich geschrieben. Schon technisch versiert? Spring vor – sie hält Schritt.","start.what#deeper#0#h":"Wo Ava lebt","start.what#deeper#1#li0":"VS Code-Erweiterung – Ava neben deinem Editor: ein Chat-Fenster, ein Dashboard und Änderungen werden direkt angezeigt, bevor sie passieren.","start.what#deeper#1#li1":"Desktop-IDE – eine eigenständige App mit allem in einem Fenster. Fügt Desktop-Steuerung hinzu (Apps öffnen, klicken, tippen für dich).","start.what#deeper#1#li2":"Begleiter – eine Mobile-App, wenn du vom Schreibtisch weg bist: Aufgaben, Tagebuch, Gedächtnis, schnelle Chats.","start.what#deeper#1#li3":"CLI – Ava in deinem Terminal, für Leute, die dort leben.","start.what#deeper#2#h":"Wie sie funktioniert, kurz erklärt","start.what#deeper#3#p":"Ava wechselt die Denkweisen (genannt Modi), um zur Aufgabe zu passen, lässt im Hintergrund ein kleines Team spezialisierter Helfer bei schwierigerer Arbeit laufen und wählt automatisch das beste KI-Modell für jeden Schritt aus. Du musst nichts davon verwalten. Der Abschnitt Kernkonzepte bietet die vollständige Tour, wann immer du neugierig bist.","start.first-five#title":"Dein erstes Vorhaben mit Ava","start.first-five#0#p":"Der schnellste Weg, Ava kennenzulernen, ist, ihr etwas Reales zu bitten und zuzusehen, wie sie es tut. Keine Einrichtung zum Lesen, nichts erst lernen – sag ihr einfach, was du willst, in einfachen Worten.","start.first-five#1#h":"Probier es jetzt aus","start.first-five#2#li0":"Öffne den Chat.","start.first-five#2#li1":"Schreib etwas, das du wirklich willst. Versuche \\\"Erkläre, was dieses Projekt macht\\\", oder \\\"Füge einen Button hinzu, der das Formular leert\\\".","start.first-five#2#li2":"Ava zeigt dir, was sie vorhat – und wartet.","start.first-five#2#li3":"Zufrieden? Sag ja. Schau ihr dabei zu, wie sie es tut.","start.first-five#3#p":"Das ist der ganze Rhythmus: du fragst, sie zeigt dir den Plan, du stimmst zu, sie macht es. Sie ändert nie etwas, ohne dir zuerst zu zeigen – also kannst du nichts kaputt machen, indem du es ausprobierst.","start.first-five#4#h":"Ein paar Dinge, die man fragen sollte","concepts.interjection#1#p":"Ava runs until her plan completes or you stop her. You have two ways to step in (the word for this is \"intervene\") while she is running.","concepts.interjection#2#h":"Interject — steer without cancelling","concepts.interjection#3#p":"Type a new message while Ava is working. She finishes her current tool call, reads your message, and adjusts her plan. No context is lost. Use this when you want to redirect, add information, or change priorities mid-run.","concepts.interjection#4#h":"Hard-stop — cancel and clear","concepts.interjection#5#p":"Press Escape (CLI), click Stop (extension, IDE), or type a stop command. The current run cancels, pending tool calls drop, and the conversation is ready for a fresh turn.","concepts.interjection#6#c":"Interject first. Hard-stop is for when something is genuinely wrong. Interjecting keeps the thread alive.","concepts.desktop-personas#title":"Desktop personas","concepts.desktop-personas#0#p":"This page is for the curious and for power users. \"Desktop automation\" (sometimes called \"computer use\") means Ava can actually click around your screen and use apps for you — open Gmail, fill a form, send a message — like a person at the keyboard. To do that safely, she splits the job across five small helpers, each with one narrow role. You never deal with them directly; this just shows you who does what.","concepts.desktop-personas#1#p":"Every step in a desktop trajectory (one run of Ava driving your screen toward a goal) runs a five-persona wave. Each persona has one job and only one job. The separation keeps prompts tight, outputs structured, and reasoning skeptical by design.","concepts.desktop-personas#2#h":"Scout","concepts.desktop-personas#3#p":"Reports what is visible on screen right now. Never invents elements. Never plans. Returns a ScreenState JSON with element IDs, names, bboxes, confidence, and a grounding source (UIA, Playwright DOM, or OmniParser vision).","concepts.desktop-personas#4#h":"Planner","concepts.desktop-personas#5#p":"Decides the single next action. One action per step — never batches. Prefers reversible paths. Classifies risk per the safety ontology. Outputs a ProposedAction JSON with kind, target, params, riskClass, reasoning, and an expectedPostState prediction.","concepts.desktop-personas#6#h":"Actor","concepts.desktop-personas#7#p":"Executes exactly what Planner proposed — after the approval gate has cleared. No improvisation. No retry. Failure is reported faithfully and Verifier handles the next move.","concepts.desktop-personas#8#h":"Verifier","concepts.desktop-personas#9#p":"Checks whether the action landed. Compares the fresh ScreenState against Planner's prediction. Returns verified, deviated, or rollback_needed. Also runs loop detection — repeating an action that already succeeded is a deviation, not a verification.","concepts.desktop-personas#10#h":"Narrator","concepts.desktop-personas#11#p":"The only voice the user hears during a trajectory. One past-tense sentence per step (\"Opened Gmail.\", \"Clicked Compose.\"). Also writes the structured audit log. Says when something went wrong — never hides a problem.","concepts.desktop-safety#title":"Desktop safety ontology","concepts.desktop-safety#0#p":"In short: before Ava clicks anything on your screen, she sorts the action by how risky it is. Reading the screen? Harmless. Sending money or deleting something? She always stops and asks you first — every single time, no exceptions. The five labels below are just the rungs on that risk ladder. This is power-user detail, but the takeaway is simple: the dangerous stuff always needs your yes.","concepts.desktop-safety#1#p":"Every proposed action is classified into one of five risk classes. The classification combines three signals — what the on-screen target is, a plain-language description of it (\"semantic caption\" — Ava's own words for what she's looking at), and the action's settings — and escalates up (treats it as riskier) when they disagree. A false positive (asking when it didn't need to) is just a nag. A false negative (not asking when it should have) is a product-ending incident.","concepts.desktop-safety#2#h":"The five classes","concepts.desktop-safety#3#li0":"Observational — read UIA tree, screenshot, hover. Always auto-allowed.","concepts.desktop-safety#3#li1":"Navigational — scroll, move focus, open a menu. Auto-allowed in Drive mode.","concepts.modes#0#p":"A mode is the mindset Ava is in — like a colleague swapping hats. Same person, same memory of you, but a builder thinks differently from a teacher. You pick the mode and it changes how she behaves and which helpers she brings. Switch any time with the mode selector, or type a two-character shortcut.","concepts.modes#2#h":"Which one do you want?","concepts.modes#3#p":"Start from what you are trying to do — the mode follows from that:","concepts.modes#4#li0":"I want something built or changed → Code (>>). You describe it, she builds it, showing you every change first. The full helper team kicks in for bigger jobs.","concepts.modes#4#li1":"I want a plan before anything changes → Plan (::). She thinks it through and hands you a plan to approve or edit. She will not touch your files in this mode.","concepts.modes#4#li2":"I just want to talk or ask → Chat (..). A thinking partner with memory, news, and weather. No file changes, no code — just conversation.","concepts.modes#4#li3":"I want to learn something → Teach (??). A real course built for you: lessons, quizzes, the lot. Free on every plan, forever. Perfect if you are new.","concepts.modes#4#li4":"I want my project checked for security holes → Security (!!). A team works through the standard list of common web vulnerabilities (the \"OWASP\" categories) and known reported flaws (called \"CVEs\"), then hands you a report sorted by how serious each issue is. This one is aimed at developers — skip it if that is not you.","concepts.modes#4#li5":"I want ideas → Brainstorm (**). She generates options grounded in your actual situation, pokes holes in the weak ones, and refines the rest into next steps.","concepts.modes#4#li6":"I want to write a document → Write (<<). Reports, proposals, letters, articles — she drafts in Markdown and exports a branded Word doc or PDF, refining section by section. No code, just writing.","concepts.modes#5#c":"The \"helper team\" (personas) runs entirely behind the scenes — you never talk to them directly. You just get a more thorough answer. You do not need to know their names.","concepts.modes#6#c":"You can switch modes mid-conversation. Your memory carries across; the specialists reset to suit the new mode.","concepts.tasks-journal#title":"Tasks and journal","concepts.tasks-journal#0#p":"Ava keeps three kinds of notes for you, and it's easy to mix them up. The quick way to remember: memory is what she knows about you, tasks are what you still need to do, and the journal is a diary of how things went. Here is when to use which.","concepts.tasks-journal#1#li0":"Memory — persistent facts. Preferences, decisions, patterns. Asked about repeatedly, rarely created manually.","concepts.tasks-journal#1#li1":"Tasks — things to do. Action items with due dates and status. You tick them off when done.","concepts.tasks-journal#1#li2":"Journal — reflection. Daily log, dual entries (yours and Ava observations about the session). Useful for mood tracking, session reviews, context for tomorrow.","concepts.tasks-journal#2#p":"Ava writes to all three when it makes sense. You can write to any of them directly from the dashboard. Nothing is locked to a single place you use Ava — a task you create in one (say the command-line tool) shows up everywhere else (like the desktop app), automatically.","concepts.permissions#title":"Permissions — your safety dial","concepts.permissions#0#p":"Permissions are your safety dial. They decide when Ava asks your okay before doing something on your computer, versus just getting on with it. You can set her to ask about everything, ask about the risky stuff only, or trust her to run — and you can change it any time. If you're not sure, leave it on the default and you'll be fine.","concepts.permissions#1#p":"Ava has 60 tools (\"tools\" are the actions she can take — reading a file, searching the web, and so on). Every tool belongs to a category (file operations, shell, git, web, media, database, system, documents, memory, learning). Every tool call passes through the permission gate (a checkpoint that decides whether to ask you first) before it runs. You control what gets auto-approved, what asks once, and what always asks.","concepts.permissions#3#p":"Balanced is the default. Strict for when you are auditing her behaviour (watching closely to check each step). Autonomous for when you want her to just go.","concepts.permissions#4#c":"Autonomous does not mean unchecked. Plans, clarifying questions, and explicit ask-user prompts still pause for your input. Irreversible operations (git force-push, database drops) always confirm regardless of mode.","concepts.interjection#title":"Steering and stopping Ava","concepts.interjection#0#p":"You are always in charge. While Ava is busy working, you can either nudge her in a new direction without breaking her stride, or stop her cold. Two buttons, two outcomes — that's all this page is about.","concepts.desktop-safety#3#li2":"Mutative-reversible — type into a field, paste, open an app, navigate a URL. Confirms in Ask mode; auto in Drive within the whitelist.","concepts.desktop-safety#3#li3":"Mutative-irreversible — send, submit, pay, delete, confirm, publish. Always confirms, regardless of permission level. Approval never caches.","concepts.desktop-safety#3#li4":"Privileged — UAC elevation, sudo, registry edits, credential prompts. Forbidden by default. Single-use opt-in required per session.","concepts.desktop-safety#4#h":"Never-cached approvals","concepts.desktop-safety#5#p":"Every competitor caches approvals (remembers your \"yes\" and reuses it next time). That is the largest foothold for prompt injection — an attack where a booby-trapped web page sneaks hidden instructions to the AI to make it act against you. If approvals are cached, a compromised page can ride on a \"yes\" you gave earlier. Ava never caches. Each mutative-irreversible action asks fresh.","concepts.desktop-safety#6#h":"Secrets handling","concepts.desktop-safety#7#p":"Passwords, API keys, and 2FA codes (the one-time codes a second app or text gives you when you log in) are handled via opaque handles — placeholders that stand in for the real value. Ava sees \"{secret}\", not the actual password. The real value never enters her memory, her activity log, or what she \"reads\" — a separate low-level layer types it in at the last moment, at the keypress, so the AI part never touches it.","reference.cli#title":"CLI commands","reference.cli#0#p":"This page is for the CLI — the version of Ava you type to in a terminal window, rather than clicking buttons. If you use the extension or the desktop app, you can skip it entirely. It is here for people who prefer the keyboard.","reference.cli#1#p":"The CLI is a REPL — a prompt that waits for you to type, runs what you typed, then waits again. These slash commands (instructions that start with \"/\") work from the prompt.","reference.cli#2#li0":"/help — list commands and current mode.","reference.cli#2#li1":"/mode <name> — switch mode (work, write, plan, chat, teach, security, brainstorm).","reference.cli#2#li2":"/model <id> — switch model without leaving the session.","reference.cli#2#li3":"/clear — clear the current conversation. Memory is untouched.","reference.cli#2#li4":"/history — list past conversations in this project.","reference.cli#2#li5":"/memory — open the memory browser.","reference.cli#2#li6":"/tasks — list and manage tasks.","reference.cli#2#li7":"/journal — open today journal entry.","reference.cli#2#li8":"/settings — open the settings menu.","reference.cli#2#li9":"/exit — quit the REPL.","reference.cli#3#h":"Launch flags","reference.cli#4#p":"Flags are extra options you add when you start Ava, each beginning with \"--\", to set how she opens.","reference.cli#5#li0":"--mode <name> — start in a specific mode.","reference.cli#5#li1":"--model <id> — start with a specific model.","reference.cli#5#li2":"--permission <mode> — strict / balanced / autonomous."},"ru":{"start.for-non-coders#title":"Никогда не писали код? Начните здесь","start.for-non-coders#0#p":"Если вы никогда не писали ни строчки кода, то вы именно та аудитория, для которой создана Ava. Вам не нужно изучать жаргон, чтобы начать — общайтесь с ней на простом языке, как с знающим другом. Эта страница — ваш полный путь к старту.","start.for-non-coders#1#h":"Что вы можете сделать сегодня без опыта","start.for-non-coders#2#li0":"Спросите её о чём угодно обычными словами — «что делает этот файл?», «почему моя страница пустая?», «что вообще такое база данных?» Она отвечает простым языком и помнит разговор.","start.for-non-coders#2#li1":"Изучите что-то с нуля — скажите «обучи меня Python с нуля», и она создаст для вас полноценный курс с уроками и тестами. Это всегда бесплатно.","start.for-non-coders#2#li2":"Получите готовый результат — опишите, что вам нужно («кнопку, которая скачивает мои заметки»), и она напишет его, показывая каждое изменение до того, как оно произойдёт.","start.for-non-coders#3#h":"Вам не нужно понимать всё","start.for-non-coders#4#p":"У Ava много механизмов под капотом — режимы, модели, специалисты, маршрутизация. Вы увидите эти слова вокруг приложения и в этой документации. Вот секрет: вы можете игнорировать почти всё. Ava сама выбирает нужные инструменты и помощников. Технические страницы созданы, когда вы захотите узнать больше, а не потому, что они нужны для старта.","start.for-non-coders#5#h":"Мягкий первый шаг","start.for-non-coders#6#li0":"Установите Ava (на следующей странице) и откройте чат.","start.for-non-coders#6#li1":"Напишите реальный вопрос, который у вас есть. Любой. Посмотрите, как она ответит.","start.for-non-coders#6#li2":"Попробуйте режим обучения: напишите «обучи меня» и тему. Следуйте за ней.","start.for-non-coders#6#li3":"Когда вы хотите, чтобы она действительно что-то создала или изменила, просто попросите — она всегда покажет вам, что собирается сделать, и подождёт вашего «да».","start.for-non-coders#7#c":"Столкнулись со словом, которое не знаете? Глоссарий простыми словами (ниже в этом разделе) объясняет каждый термин без предположений о ваших знаниях.","start.install#title":"Установка","start.install#0#p":"Выберите интерфейс, который подходит вашему стилю работы. Можно использовать несколько — Ava синхронизирует свою память между ними при входе в систему.","start.install#1#h":"Расширение для VS Code","start.install#2#li0":"Откройте панель расширений в VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Найдите «Ava Supernova» и нажмите Установить.","start.install#2#li2":"Нажмите Ctrl+Shift+A (Cmd+Shift+A на macOS), чтобы открыть панель чата.","start.install#2#li3":"Следуйте мастеру настройки — выберите модель, установите режим разрешений, готово.","start.install#3#h":"Настольная IDE","start.install#4#li0":"Скачайте установщик для вашей платформы со страницы релизов.","start.install#4#li1":"Запустите его. При первом запуске IDE откроется приветственный экран.","start.install#4#li2":"Войдите, чтобы получить бесплатные токены платформы, или вставьте свой собственный ключ API для полного локального запуска.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (или pnpm / yarn — ваш выбор).","start.install#6#li1":"Запустите  ava  в любой директории проекта.","start.install#6#li2":"Первый запуск предложит выбрать провайдера и модель. Выберите и начните.","start.install#7#c":"Нет аккаунта — не проблема. С собственным ключом API (BYOK) вам никогда не нужно будет входить в систему. Бесплатный тариф предназначен для управляемых платформой моделей.","concepts.memory#title":"Память — как Ava запоминает вас","concepts.memory#0#p":"Простыми словами: Ava помнит вас. Расскажите ей что-нибудь один раз — что вам нравится, какое решение вы приняли — и она запомнит это, так что вам не придётся повторяться в следующем чате или на следующей неделе. Вот главная мысль. Слои ниже просто объясняют, как она поддерживает эту память в порядке со временем.","concepts.memory#1#p":"Ava имеет постоянную память (\"постоянная\" означает, что она остаётся после закрытия приложения) и живёт между разговорами, проектами и устройствами, если включить синхронизацию (синхронизация копирует вашу память между устройствами). Это не просто лог переписки. Это структурированное, доступное для поиска понимание того, кто вы, что любите и что решили.","concepts.memory#2#h":"Пять уровней","concepts.memory#3#li0":"Извлечение — ключевые факты, захваченные из каждого сообщения в реальном времени.","concepts.memory#3#li1":"Рефлексия — более глубокий анализ запускается в конце значимых сессий. Паттерны, темы, противоречия.","concepts.memory#3#li2":"Накопление — исправления и предпочтения накапливаются неделями и месяцами.","concepts.memory#3#li3":"Анализ — графовый движок связывает связанные воспоминания и отмечает противоречия, когда новая информация конфликтует со старой.","concepts.memory#3#li4":"Консолидация — похожие воспоминания объединяются; устаревшие удаляются. Память становится острее со временем, а не шумнее.","concepts.memory#4#c":"Пять слоёв выше работают сами по себе — вам никогда не нужно ими управлять. Они здесь, чтобы вы видели, как память действительно улучшается со временем, а не превращается в кучу мусора.","concepts.memory#5#h":"Воспоминание","concepts.memory#6#p":"Когда вы задаёте вопрос, Ava ищет в памяти по смыслу (\"семантический поиск\" — она понимает, что вы имеете в виду, поэтому находит нужное воспоминание, даже если вы сформулировали иначе), а не просто по точному совпадению слов. Фильтры для разных режимов работают рядом — режим Чат тянет личный контекст, режим Работа — решения по проектам и паттерны кода.","concepts.memory#7#c":"Память ограничена пользователем и проектом (ваши воспоминания ваши, разделены по человеку и проекту). Секреты и учётные данные (пароли, ключи) блокируются сразу при сохранении — они никогда не попадут в память.","concepts.desktop-grounding#title":"Иерархия понимания экрана (Предварительный просмотр)","concepts.desktop-grounding#0#c":"Предварительный просмотр — как Scout выбирает способ определения элементов на каждом шаге.","concepts.desktop-grounding#1#p":"Чтобы нажать кнопку, Ava сначала должна понять, что находится на вашем экране и где именно это расположено — это называется «grounding» (определение того, что изображено на экране и точного местоположения каждого элемента). У неё есть три способа это сделать, и она выбирает самый надёжный для текущего приложения. Это техническая деталь для опытных пользователей; главное — она всегда предпочитает точные методы случайным догадкам по картинке.","concepts.desktop-grounding#2#p":"Три уровня, проверяются последовательно. Побеждает самый доступный надёжный источник.","concepts.desktop-grounding#3#h":"1. Окно браузера → Playwright DOM","concepts.desktop-grounding#4#p":"Если активное окно — браузер, Ava считывает структуру самой страницы («DOM» — внутренний список элементов), а не пытается угадать по картинке. Чтение структуры примерно в 10× раз надёжнее, чем анализ пикселей: она точно знает, где каждая кнопка и когда страница полностью загрузилась. Это основной метод для работы в интернете, а не запасной вариант.","concepts.desktop-grounding#5#h":"2. Обычное приложение с UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Для обычных программ на Windows Ava использует встроенную карту доступности («UIA», те же данные, что программы чтения с экрана применяют для описания окон) — там указаны все элементы управления, их названия и расположение. Если эта карта выдаёт хотя бы пять понятных элементов, Ava доверяет ей и работает по ней.","concepts.desktop-grounding#7#h":"3. Если UIA пустая или бесполезная → OmniParser vision","concepts.desktop-grounding#8#p":"Если карты нет или она бесполезна (в некоторых программах, играх и удалённых экранах её просто не бывает), Ava смотрит на скриншот. Инструмент компьютерного зрения (OmniParser) находит кликабельные зоны и подписывает их, превращая картинку в понятный список — плюс всё, что смогла дать карта доступности.","concepts.desktop-grounding#9#c":"OmniParser подключается только по вашему согласию, когда он впервые понадобится, с чётким предупреждением о конфиденциальности. Пользователи BYOK могут подключить свою собственную локальную версию OmniParser.","concepts.desktop-kill-switches#title":"Аварийные кнопки остановки на рабочем столе (Предварительный просмотр)","concepts.desktop-kill-switches#0#c":"Предварительный просмотр — три независимых способа остановить выполнение задачи. Достаточно любого из них.","concepts.desktop-kill-switches#1#p":"«Аварийный выключатель» — это именно то, что говорит название: экстренный способ мгновенно остановить Ava, пока она управляет вашим экраном. Хорошая новость: таких выключателя три, они работают независимо друг от друга, так что если один подведёт, другие сработают. Вам не обязательно знать все три. Главное помнить: если что-то идёт не так, вы всегда можете всё остановить. Самый мощный способ (кнопка паники ниже) вообще не зависит от того, слушается ли Ava.","concepts.desktop-kill-switches#2#p":"Мы изучили все публичные инциденты с автономными агентами (случаи, когда ИИ игнорировал команды остановки, удалял почту или стирал диски), и создали три аварийных выключателя на разных уровнях. Ни один из них не зависит от самой модели ИИ. Даже если Ava зависнет или перестанет отвечать, вы сможете её остановить.","concepts.desktop-kill-switches#3#h":"Пауза — клавиша Пробел или кнопка Паузы","concepts.desktop-kill-switches#4#p":"Замораживает на следующем шаге. Можно продолжить. Используйте это, когда хотите вмешаться, не сбивая траекторию.","concepts.desktop-kill-switches#5#h":"Стоп — клавиша Escape или кнопка «Стоп»","concepts.desktop-kill-switches#6#p":"Чистое завершение. Диктор подводит итог того, что было сделано. Нельзя продолжить. Лог аудита сохраняется.","concepts.desktop-kill-switches#7#h":"Тревожная остановка — тройное нажатие Escape или Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"Самый радикальный способ остановки. Небольшая отдельная программа-страж принудительно завершает часть Ava, которая управляет вашим экраном. Она не ждёт ответа от ИИ, ей не нужно, чтобы окно приложения работало, и ей всё равно в каком состоянии находятся вещи — она просто убивает процесс. Это вариант на случай, если действительно что-то пошло не так.","concepts.desktop-kill-switches#9#p":"Все три работают и из вспомогательного приложения. Любой драйвер может завершить работу.","reference.tools#title":"Справочник инструментов","reference.tools#0#p":"Это полный справочник всех инструментов Ava — «инструмент» это просто конкретное действие, которое она может выполнить, например чтение файла или поиск. Вам не нужно читать эту страницу. Ava сама выбирает нужный инструмент каждый раз. Он здесь для тех, кто хочет точно знать, что она умеет делать.","reference.tools#1#p":"Полный встроенный набор инструментов. Каждый инструмент здесь зарегистрирован в ядре (движок под всеми тремя поверхностями) и доступен Ava, когда режим и режим разрешений позволяют. Фильтруйте по категории или уровню риска.","reference.tools#2#p":"Ничего запоминать не нужно — таблица ниже просто справочная карточка.","reference.tools#4#h":"Уровни риска","reference.tools#5#li0":"Безопасно — читает данные без изменений. file_read, glob (поиск файлов по имени), grep (поиск текста внутри файлов), git_status (Git — система отслеживания изменений вашего проекта).","reference.tools#5#li1":"Запись — изменяет файлы, сохраняет контрольную точку вашей работы («коммит»), или создаёт новое. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Опасно — выполняет команды на компьютере («оболочка»), управляет рабочим столом, выходит в интернет или опрашивает базы данных. bash, browser, desktop_*.","reference.tools#6#c":"У специалистов-персон свои списки разрешённых инструментов. Scout может читать, но не писать. Builder имеет полный доступ. Challenger вообще не имеет инструментов — его задача ставить план под сомнение.","reference.models#title":"Модели","reference.models#0#p":"«Модель» — это мозг ИИ, который думает — Qwen, DeepSeek, Mistral и другие. На этой странице перечислены все модели, которые может использовать Ava. Коротко: вам не нужно выбирать одну. Ava сама выбирает нужную модель для каждого шага. Читайте дальше только если хотите понять или переопределить это.","reference.models#1#p":"Все модели, к которым может обращаться Ava, плюс три стратегии оркестрации — правила, определяющие, какая модель обрабатывает каждую часть задачи. Выберите режим маршрутизации и позвольте Ava распределить, или выберите одну модель и полностью пропустите маршрутизацию.","reference.models#2#h":"Режимы маршрутизации","reference.models#3#p":"Три стратегические схемы. Один и тот же конвейер персон (небольшая команда помощников-специалистов, которую запускает Ava за кулисами) работает во всех трёх; меняется только базовый парк моделей. Выберите режим в селекторе моделей, а остальное сделает Ava. Каждая карточка ниже показывает специалистов, к которым направляется дирижёр.","reference.models#4#p":"Вам не нужно запоминать карточки ниже — они здесь, чтобы вы видели, из чего состоит каждая стратегия.","reference.models#6#c":"Aurora намеренно использует только Mistral. Если модель Mistral недоступна, роутер возвращает ошибку вместо перенаправления — это гарантия стека ЕС. Выберите Maestro или Supernova для плавной деградации.","reference.models#7#c":"Все три режима доступны везде — на платформенных кредитах и на ваших собственных ключах. BYOK добавляет возможность обойти оркестрацию и управлять одной моделью напрямую.","reference.models#8#h":"Модели, управляемые платформой","reference.models#9#p":"Доступны во всех тарифах, включая бесплатный. Токены (единицы текста, которыми измеряется ИИ — примерно три четверти слова каждое) учитываются в вашем лимите плана. Ключи (личные пароли, разблокирующие каждую платную модель) обновляются и контролируются платформой — ничего настраивать вам не нужно.","reference.config#title":"Конфигурация","reference.config#0#p":"На этой странице показано, где Ava хранит свои настройки и файлы на вашем компьютере. Вам почти никогда не нужно трогать их вручную — приложение управляет этим за вас. Это здесь для тех случаев, когда вы хотите сами посмотреть, сделать резервную копию или поделиться этими файлами.","reference.config#1#p":"Ava считывает конфигурацию (свои сохранённые настройки) из двух областей. Глобальные настройки — те, что применяются везде — находятся в папке ~/.ava/ (знак \"~\" означает вашу домашнюю папку). Настройки конкретного проекта живут в папке .ava/ внутри самого проекта.","reference.config#2#h":"Глобальные — ~/.ava/","reference.config#3#li0":"settings.json — предпочтения модели, режим разрешений, личность, язык.","reference.config#3#li1":"memory/ — ваши глобальные воспоминания (предпочтения, решения, применимые везде).","reference.config#3#li2":"tasks.json — список задач между проектами.","reference.config#3#li3":"journal/ — ежедневные записи журнала, организованные по дате.","reference.config#4#h":"Проект — .ava/","reference.config#5#li0":"instructions.md — инструкции, специфичные для проекта, которые Ava всегда загружает. Постоянный контекст («мы используем pnpm, а не npm», «ключи API хранятся в 1Password»).","reference.config#5#li1":"context.md — необязательные заметки о проекте произвольного формата.","reference.config#5#li2":"memory/ — воспоминания, ограниченные этим проектом.","reference.config#5#li3":"datasets/config.json — конфигурация захвата датасетов по желанию.","reference.config#6#c":"Добавьте .ava/ в свой .gitignore (список файлов, которые Git должен игнорировать в общем проекте), если вы не хотите делиться воспоминаниями с командой. Оставьте instructions.md в репозитории (общей папке проекта) — так Ava узнаёт правила проекта.","reference.shortcuts#title":"Горячие клавиши","reference.shortcuts#0#p":"Горячие клавиши — это опциональные ускорения — каждая из них также является кнопкой, которую можно нажать. Заходите сюда только если хотите управлять Ava быстрее с клавиатуры.","reference.shortcuts#1#p":"Ярлыки по интерфейсам (каждое из трёх мест, где работает Ava: расширение VS Code, десктопное приложение и терминал). Настройте их в настройках каждого интерфейса. Не нужно запоминать список ниже.","reference.models#11#h":"Подключите свой ключ","reference.models#12#p":"An \"API key\" is a private password that lets software use a paid service on your own account. \"BYOK\" just means \"bring your own key\" — using yours instead of ours. Paste your API key in settings. BYOK requests go direct from Ava to the provider (the company that runs the model) — they do not pass through our infrastructure and do not consume platform tokens. You pay the provider; we do not see the traffic.","reference.models#14#c":"For benchmark scores, capability tags, and side-by-side filtering, see the full Models page at ava-supernova.com/models. Pricing shown above is our best read of each provider rate card at publication — always check the provider website before committing to a workload.","reference.personas#title":"Оркестрация ролей","reference.personas#0#p":"«Персона» — это вспомогательная роль, которую Ava играет за кулисами для сложных задач — исследователь, планировщик, фактчекер. Вы никогда не общаетесь с ними напрямую и не обязаны понимать эту страницу, чтобы пользоваться Ava. Она здесь, когда вам интересно, как она разбивает большую задачу на небольшую команду экспертов.","reference.personas#1#p":"24 специалиста в 5 командах режимов. Координатор (помощник, который управляет остальными) решает, какая команда работает, в каком порядке и с каким контекстом. В режиме чата нет персонажей — это сама Ava.","reference.personas#2#h":"Как работает оркестрация","reference.personas#3#li0":"Вы отправляете сообщение в режиме Планирования, Обучения, Безопасности или Мозгового штурма (или сложной задаче Работы).","reference.personas#3#li1":"Координатор читает запрос, выбирает команду режимов и строит план выполнения — некоторые персоны работают последовательно, некоторые волнами параллельно.","reference.personas#3#li2":"У каждой персоны свой системный промпт, ограниченный список разрешённых инструментов и общий пул контекста того, что нашли предыдущие персоны.","reference.personas#3#li3":"Финальная персона создаёт резюме, план или отчёт в зависимости от режима.","reference.personas#3#li4":"Ava показывает результат вам. Вы одобряете, правите или перенаправляете.","reference.personas#4#p":"Полный список ниже — только справочный — запоминать, кто что делает, не нужно. Ava собирает нужную команду для вас.","reference.personas#6#c":"Режим Работы вызывает полную команду только для сложных задач. Простые правки запускают Ava напрямую — без накладных расходов на оркестрацию.","reference.project-context#title":"Контекст проекта","reference.project-context#0#p":"Здесь рассказано, как Ава изучает ваш проект перед началом работы — какие файлы она просматривает, чтобы понять, над чем вы трудитесь. Вам не нужно ничего настраивать — она делает это сама. Прочтите, если хотите знать, куда положить заметку, чтобы она всегда её видела.","reference.project-context#1#p":"Когда вы открываете проект, Ава загружает несколько слоёв контекста (фоновую информацию, которую она держит в уме). Понимание этих слоёв поможет вам разместить информацию в нужном месте.","reference.project-context#2#h":"Загружается автоматически","reference.project-context#3#li0":".ava/instructions.md — считается постоянным руководством высокого приоритета. Всегда доступно в контексте.","reference.project-context#3#li1":".ava/context.md — произвольные заметки. Загружаются, но имеют меньший приоритет.","reference.project-context#3#li2":"README.md — сканируется при первом запуске для получения сводки по проекту.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — небольшие файлы с описанием настройки проекта; читаются, чтобы определить язык, фреймворк и команду тестирования.","reference.project-context#3#li4":".gitignore — список файлов, которые нужно исключить из системы контроля версий; учитывается всеми инструментами работы с файлами (glob, grep, project_index).","reference.project-context#4#h":"Загружается по запросу","reference.project-context#5#p":"\"По запросу\" означает, что Ава получает их только тогда, когда задача действительно в них нуждается, а не заранее.","reference.project-context#6#li0":"Индекс проекта — структурированная карта ваших файлов и названных элементов внутри них (функции, классы — \"символы\") и того, как они связаны (\"импорты\"). Создаётся лениво, то есть только тогда, когда Аве это нужно.","reference.project-context#6#li1":"История Git — запись прошлых изменений; загружается при вызове git_status, git_diff или git_create_pr (Git — инструмент, отслеживающий каждое изменение проекта; \"PR\" — это запрос на слияние, предлагаемый пакет изменений).","reference.project-context#6#li2":"Память — записи сопоставляются по смыслу (\"семантически\") и подставляются по одной за ход, а не все сразу.","reference.project-context#7#c":"Правила пишите в instructions.md. Заметки — в context.md. Остальное пусть запомнит память самостоятельно.","features.unified-panel#title":"Единая панель","features.unified-panel#0#p":"Простыми словами: всё, что делает Ava, находится в одном окне, так что вам никогда не придётся искать её среди вкладок.","features.unified-panel#1#p":"Одна панель для чата, дашборда, памяти, задач и журнала. Никакого переключения контекста между окнами. Боковая панель выбирает то, на что вы смотрите; основная область меняется соответственно.","features.unified-panel#2#p":"Состояние диалога сохраняется при переходе — откройте память, проверьте задачу, затем вернитесь. Чат всё ещё там, всё ещё транслируется, если Ava всё ещё работает.","features.unified-panel#3#c":"Единая панель — это расширение и концепция IDE. Веб-интерфейс использует браузерные вкладки.","features.knowledge-packs#title":"Пакеты знаний","features.knowledge-packs#0#p":"Простыми словами: передайте Ava папку своих документов, и она сможет читать их, чтобы отвечать на ваши вопросы. «Пакет знаний» — это просто набор файлов — ваш справочный материал, с которым она имеет право работать.","features.knowledge-packs#1#p":"Перетащите директорию справочного материала (спецификации, RFC, заметки о встречах, документация API) в пакет знаний. Ava может извлекать соответствующие части в контекст, когда разговор касается темы.","features.knowledge-packs#2#p":"Пакеты индексируются локально. Поиск семантический — Ava находит нужный документ по смыслу, а не по имени файла. («Семантика» означает, что она сопоставляет содержание документа, поэтому вам не нужно помнить точные слова или имя файла.) Пакеты можно делиться с командой или хранить приватно.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Нужен отчет, письмо или документ? Ava составит черновик и передаст вам реальный файл Word, Excel или PDF, который открывается и редактируется как обычный.","features.office-suite#1#p":"Отчеты, письма и документы — подготовлены, оформлены и экспортированы в родные форматы (.docx — это Word, .xlsx — это Excel, .pdf — это PDF).","features.office-suite#2#li0":"report_generate — структурированный .docx, собирающий данные из задач, журнала, памяти и состояния проекта.","features.office-suite#2#li1":"email_draft — письмо с заданным тоном в файл .docx.","features.office-suite#2#li2":"document_manage — создание, чтение, редактирование и экспорт в Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Полезно, когда Ava пишет за вас — отчеты о статусе, презентации для запуска, обновления для клиентов. Файл .docx оказывается в вашем проекте, где вы сможете его доработать.","features.dashboard-library#title":"Библиотека дашбордов","features.dashboard-library#0#p":"Простыми словами: одна полка, где хранится всё, что вы и Ava создали и обсудили, так что ничто не теряется.","features.dashboard-library#1#p":"Удобный обзор всего, что Ava создала вместе с вами — сгенерированные изображения, видео, аудио, документы — рядом с вашими диалогами, воспоминаниями и задачами. Одно место, чтобы найти то, что вы делали на прошлой неделе.","features.document-preview#title":"Предпросмотр документа","features.document-preview#0#p":"Простыми словами: посмотреть содержимое документа прямо здесь, не открывая отдельную программу для чтения.","features.document-preview#1#p":"Нажмите правой кнопкой мыши на файл Word, Excel, PDF, CSV, HTML или Markdown в вашем проекте — просмотрите его прямо в редакторе, не уходя из него. Удобно для чтения справочных материалов, созданных Ava, или файлов, добавленных коллегой.","features.daily-briefing#title":"Ежедневная сводка","features.daily-briefing#0#p":"Простыми словами: короткая заметка каждое утро «где вы остановились», чтобы вы могли продолжить работу, не перечитывая всё заново.","features.daily-briefing#1#p":"Утренняя сводка: вчерашний журнал, открытые задачи, текущее состояние проекта и любые напоминания от Ava. По желанию — включите в настройках.","features.daily-briefing#2#p":"Брифинг использует память, чтобы подсветить нужный контекст («на прошлой работе над потоком авторизации вы отмечали желание пересмотреть стратегию обновления токенов»). Это не лента новостей — а целенаправленное обновление информации.","troubleshooting.common-errors#title":"Общие ошибки","troubleshooting.common-errors#0#p":"У большинства ошибок есть короткая и конкретная причина. Вот самые распространённые из них и способы их устранения. Не переживайте, если формулировки покажутся техническими — каждая ниже описывает именно то, что вы видите, и точно указывает, что делать.","troubleshooting.common-errors#1#h":"Ava не отвечает","troubleshooting.common-errors#2#p":"Что вы видите: Ava замолкает и не отвечает.","troubleshooting.common-errors#3#p":"Проверьте индикатор статуса в заголовке чата. Если там написано «подключение», ваш провайдер (сервис ИИ, с которым общается Ava) доступен, но работает медленно — подождите тридцать секунд. Если написано «недоступно», Ava автоматически переключилась на следующую модель в цепочке (она перешла на резервную модель). Если ничего нет, проверьте свой API ключ в Настройках и протестируйте соединение. (API ключ — это секретный пароль, который позволяет Ava использовать платный сервис ИИ.)","troubleshooting.common-errors#4#h":"Ошибка вызова инструмента","troubleshooting.common-errors#5#p":"Что вы видите: один из шагов Ava («вызов инструмента» — чтение файла, выполнение команды и так далее) показывает красную ошибку вместо завершения.","troubleshooting.common-errors#6#p":"Нажмите на неудачный вызов инструмента, чтобы увидеть ошибку. Распространённые причины: она попыталась коснуться файла вне папки вашего проекта, что заблокировано специально ради вашей безопасности (эта защита называется защитой от «обхода пути» — она не даёт ей выходить за пределы папки, в которой вы работаете); команда, требующая запуска в другой папке; или файл, который был перемещён с тех пор, как Ava его последний раз проверяла. Скажите ей, что пошло не так — она повторит попытку с исправлениями.","troubleshooting.common-errors#7#h":"Память не вспоминает","troubleshooting.common-errors#8#p":"Что вы видите: Ava не может найти то, что, по вашему мнению, она должна помнить.","troubleshooting.common-errors#9#p":"Память работает по смыслу, а не по точным словам (именно это означает «семантический»). Поэтому «Что я решил насчёт авторизации?» работает лучше, чем «найти моё решение по авторизации». Если память точно есть, но не находится, откройте браузер памяти и выполните поиск — если её там нет, значит, она никогда не сохранялась.","troubleshooting.common-errors#10#h":"Зацикливание входа","troubleshooting.common-errors#11#p":"Что вы видите: вы входите в систему, но Ava постоянно просит войти снова — бесконечный цикл, который не пропускает вас дальше.","troubleshooting.common-errors#12#p":"Решение — очистить сохранённые данные для входа и начать заново: в расширении выполните «Ava: Выйти» через палитру команд, в IDE перейдите в Настройки → Аккаунт → Выйти, в CLI удалите файл по адресу ~/.ava/auth.json (маленький файл входа в папке .ava в вашей домашней директории). Затем войдите снова.","troubleshooting.common-errors#13#h":"Лимит токенов исчерпан","troubleshooting.common-errors#14#p":"Что вы видите: сообщение о том, что бесплатный лимит использования за месяц исчерпан. («Токены» — это единица измерения использования ИИ — «исчерпан» просто означает, что вы использовали весь бесплатный лимит этого месяца.)","troubleshooting.common-errors#15#p":"Бесплатный месячный бюджет обновляется 1-го числа каждого месяца. До этого момента переключитесь на провайдера BYOK (используйте свой собственный API ключ), чтобы продолжить работу. Ваш аккаунт остаётся активным — приостанавливаются только бесплатные запросы, управляемые платформой.","troubleshooting.logs#title":"Где находятся логи","troubleshooting.logs#0#p":"«Лог» — это просто дневник, который ведёт ваш компьютер о том, что произошло — полезно, когда что-то ломается и вам (или поддержке) нужно увидеть детали.","troubleshooting.logs#1#p":"Когда вам нужна полная картина — какой инструмент был вызван, какую информацию он получил, что вернул сервис ИИ — логи представляют собой обычные текстовые файлы в папке на вашем компьютере по адресу ~/.ava/logs/ (папка с именем .ava в вашей домашней директории, внутри которой находится папка logs).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — транскрипты каждой сессии, включая вызовы инструментов, потоковые ответы и ошибки.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — лог хоста расширения VS Code. Сбои активации, ошибки панели.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — лог настольной IDE. Сообщения процесса sidecar, сбои Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — лог CLI REPL.","troubleshooting.logs#3#p":"В расширении «Ava: Показать логи» в палитре команд открывает нужный лог во вкладке редактора. В IDE в Настройках → Диагностика есть кнопка «Открыть логи». CLI может отслеживать свой лог с помощью команды ava logs --follow.","troubleshooting.logs#4#c":"Логи могут содержать фрагменты файлов проекта, которые прочитала Ava во время сессии. Проверьте перед отправкой.","troubleshooting.support-request#title":"Оформление запроса в поддержку","troubleshooting.support-request#0#p":"Простыми словами: если что-то пошло не так и описанные выше исправления не помогли, напишите нам об этом. Самый простой способ — просто попросить об этом Ava.","troubleshooting.support-request#1#p":"Если проблема не описана в разделе распространённых ошибок, оформите тикет в поддержку (отправьте команде запрос на помощь). Это можно сделать внутри Ava (без заполнения форм) или через веб-сайт.","troubleshooting.support-request#2#h":"Изнутри Ava","troubleshooting.support-request#3#p":"Попросите её это сделать. «Ava, можешь оформить тикет в поддержку по этому поводу?» Она вызывает команду support_request, прикрепляет контекст сессии (с удалёнными учётными данными) и отправляет. Самый быстрый путь.","troubleshooting.support-request#4#h":"Через веб-сайт","troubleshooting.support-request#5#p":"Перейдите на ava-supernova.com/support. Выберите категорию (ошибка, функция, аккаунт, безопасность, общее) и опишите, что произошло. Ответ в течение одного рабочего дня.","troubleshooting.support-request#6#h":"Что включить","troubleshooting.support-request#7#li0":"Что вы пытались сделать.","troubleshooting.support-request#7#li1":"Что произошло на самом деле.","troubleshooting.support-request#7#li2":"На какой платформе (расширение, IDE, CLI, приложение-компаньон) и какая версия.","troubleshooting.support-request#7#li3":"Любое сообщение об ошибке или фрагмент лога. Сначала скройте учётные данные.","troubleshooting.security-disclosure#title":"Сообщение о проблемах безопасности","troubleshooting.security-disclosure#0#p":"Простыми словами: если вы заметили способ, которым Ava можно взломать или использовать не по назначению («уязвимость» — слабость в защите), пожалуйста, сообщите нам сначала лично, чтобы мы успели всё исправить до того, как этим воспользуются другие. Здесь описано, как.","troubleshooting.security-disclosure#1#p":"Нашли уязвимость? Спасибо. Мы серьёзно относимся к каждому сообщению и работаем над исправлением вместе с вами до публичного объявления (до того, как проблема станет известна всем).","troubleshooting.security-disclosure#2#h":"Как сообщить","troubleshooting.security-disclosure#3#li0":"Напишите на security@ava-supernova.com с описанием, шагами воспроизведения и вашим предпочтительным окном раскрытия информации.","troubleshooting.security-disclosure#3#li1":"Или оформите тикет в поддержку с категорией «Безопасность» — та же очередь обработки.","troubleshooting.security-disclosure#3#li2":"Мы подтверждаем получение в течение 24 часов.","troubleshooting.security-disclosure#4#h":"Наши обязательства","troubleshooting.security-disclosure#5#li0":"Согласованное раскрытие — мы договариваемся о сроках с вами до публикации чего-либо. Стандартный срок — 90 дней.","troubleshooting.security-disclosure#5#li1":"Благодарность — вас упомянут в примечаниях к исправлению, если вы не предпочтёте анонимность.","troubleshooting.security-disclosure#5#li2":"Никаких юридических последствий — добросовестные исследования приветствуются. Мы не будем нанимать юристов для преследования вас.","troubleshooting.security-disclosure#6#c":"Страница безопасности на ava-supernova.com/security содержит всю информацию — гарантии архитектуры, инструмент очистки данных, контроль доступа.","features.workflows#title":"Сценарии","features.workflows#0#p":"Простыми словами: научите Ava рутину, которую вы выполняете снова и снова, дайте ей имя, и она сможет выполнить всё заново по требованию. «Сценарий» — это просто сохранённая рутина — набор шагов, которые Ava повторяет для вас.","features.workflows#1#p":"Сохраняйте последовательность шагов, которые вы часто повторяете — обзор PR → запуск тестов → написание заметок о релизе → черновик письма. Сценарий — это многоразовый план, который Ava может воспроизвести с разными входными данными.","features.workflows#2#p":"Сценарии хранятся для каждого проекта в папке .ava/workflows/ внутри вашего проекта. Делитесь ими с командой, добавив директорию в репозиторий (сохранив её в общем проекте, чтобы коллеги тоже получили доступ).","features.events#title":"События и уведомления","features.events#0#p":"Простыми словами: пока Ava работает, вы получаете аккуратный пошаговый список того, что она делает, и уведомление, когда долгая задача завершится, так что вы можете отлучиться.","features.events#1#p":"Пока Ava работает, вы видите структурированные обновления, а не стену текста. Каждый вызов инструмента, каждая передача между ролями, каждый поток данных — это отдельное событие в интерфейсе. Их можно развернуть для деталей или свернуть для обзора.","features.events#2#p":"Фоновые задачи отправляют системные уведомления при завершении. Вы можете уйти от долгой сборки, и Ava сообщит вам, когда всё будет готово.","features.personality#title":"Конструктор личности","features.personality#0#p":"Простыми словами: настройте, как Ava общается с вами — болтливая или краткая, официальная или неформальная, больше шуток или меньше — чтобы она звучала так, как вам нравится.","features.personality#1#p":"Настройте стиль общения Ava. Тон, энергичность, объём речи (сколько она говорит), формальность, юмор. Ползунки и готовые настройки — сдержанный инженер, тёплый наставник, сухой коллега или ваша собственная комбинация.","features.personality#2#p":"Личность влияет на формулировки, а не на компетенции. Она по-прежнему использует те же инструменты и следует тем же правилам доступа. Её имя зафиксировано как Ava — это не обсуждается.","features.release-notes#title":"Заметки о выпуске","features.release-notes#0#p":"Простыми словами: постоянный список нового и исправленного в каждом обновлении, чтобы вы видели, что изменилось.","features.release-notes#1#p":"Встроенный журнал изменений (changelog — это история изменений). Каждая выпущенная версия с основными нововведениями, исправлениями ошибок и критическими изменениями (изменения, которые могут потребовать корректировки способа использования). Веб-версия поддерживает публичную версию по адресу ava-supernova.com/releases.","start.what#title":"Что такое Ava?","start.what#0#p":"Ava — это ИИ, который реально что-то делает, а не просто разговаривает. Она создаст для вас приложение, напишет документ, научит с нуля, разработает логотип или займётся делами, которые вы всё откладывали. И она помнит вас: над чем вы работаете, как вам нравится, что вы просили на прошлой неделе.","start.what#1#p":"Одна Ava, и она работает там, где работаете вы — в редакторе кода, как десктопное приложение, на телефоне или в терминале. Одна память, одна личность везде.","start.what#2#h":"Чем она отличается","start.what#3#li0":"По умолчанию ваша. Ваши работы остаются на вашем устройстве. Никакого отслеживания, никакой телеметрии — никогда.","start.what#3#li1":"Открыта для всех. Каждая строка Ava публична. Ничего не нужно принимать на веру.","start.what#3#li2":"Начать бесплатно. 300 кредитов каждый месяц, без карты, без подвоха — или подключите свои ключи ИИ и ничего нам не платите.","start.what#3#li3":"Обучение бесплатно навсегда. Обучение не должно иметь ценник.","start.what#4#p":"Никогда не писали код? Следующая страница написана специально для вас. Если вы уже технически подкованы? Переходите дальше — она успеет за вами.","start.what#deeper#0#h":"Where Ava lives","start.what#deeper#1#li0":"VS Code extension — Ava next to your editor: a chat panel, a dashboard, and changes shown inline before they happen.","start.what#deeper#1#li1":"Desktop IDE — a standalone app with the whole thing in one window. Adds desktop control (opening apps, clicking, typing for you).","start.what#deeper#1#li2":"Companion — a mobile app for when you're away from your desk: tasks, journal, memory, quick chats.","start.what#deeper#1#li3":"CLI — Ava in your terminal, for people who live there.","start.what#deeper#2#h":"How she works, in brief","start.what#deeper#3#p":"Ava switches mindsets (called modes) to match the job, quietly runs a small team of specialist helpers on harder work, and picks the best AI model for each step automatically. You never manage any of it. The Core concepts section has the full tour whenever you're curious.","start.first-five#title":"Ваша первая задача с Ava","start.first-five#0#p":"Самый быстрый способ познакомиться с Ava — попросить её о чём-то реальном и посмотреть, как она это сделает. Не нужно читать инструкции, ничего учить заранее — просто скажите ей, чего хотите, простыми словами.","start.first-five#1#h":"Попробуйте сейчас","start.first-five#2#li0":"Откройте чат.","start.first-five#2#li1":"Напишите то, что вам действительно нужно. Попробуйте «объясни, что делает этот проект», или «добавь кнопку, которая очищает форму».","start.first-five#2#li2":"Ava покажет, что она собирается сделать — и подождёт.","start.first-five#2#li3":"Удовлетворены? Скажите да. Посмотрите, как она это сделает.","start.first-five#3#p":"Вот и весь ритм: вы спрашиваете, она показывает план, вы одобряете, она выполняет. Она никогда не меняет ничего без предварительного показа — так что вы ничего не сломаете, пробуя.","start.first-five#4#h":"Несколько вещей, о которых стоит попросить","start.first-five#5#li0":"Вопрос — «почему моя страница пустая?», «что делает этот файл?»","start.first-five#5#li1":"Что-то созданное — «сделай мне простую страницу со списком дел».","start.first-five#5#li2":"Чтобы чему-то научиться — «обучи меня Python с нуля». (Всегда бесплатно.)","start.first-five#5#li3":"Документ — «напиши мне одностраничное предложение по проекту». Она передаст вам файл Word или PDF.","start.first-five#6#c":"Не знаете, что написать? Общайтесь с ней как с знающим другом. Обычные слова подходят идеально — вам никогда не понадобятся технические термины, чтобы начать.","start.first-five#deeper#0#p":"Этот простой цикл выполняет довольно много работы за кулисами. Вам не нужно знать об этом, чтобы использовать Ava — но вот что на самом деле происходит, если вам интересно.","start.first-five#deeper#1#h":"Инструменты и одобрение","start.first-five#deeper#2#p":"Когда Ava читает файл, запускает команду или редактирует код, каждое из этих действий — это «вызов инструмента». Она спрашивает перед тем, как что-то коснется ваших файлов или системы — как часто она спрашивает, устанавливается вашим режимом разрешений (спрашивать всегда, спрашивать только при рисках или просто действовать).","start.first-five#deeper#3#h":"Режимы — её состояния ума","start.first-five#deeper#4#p":"Ava работает в режимах: подход плюс нужный набор инструментов для задачи. Переключайтесь в любое время через меню выбора или введите префикс в начале сообщения. Их семь.","start.first-five#deeper#6#h":"Специалисты и маршрутизация","start.first-five#deeper#7#p":"При сложных задачах Ava запускает небольшую команду помощников-специалистов за кулисами (планировщик, контролёр, строитель) и направляет каждый шаг модели, которая лучше всего с этим справляется. Вы никогда не управляете этим — она координирует всё за вас.","start.local-vs-cloud#title":"Локально против облака, одним абзацем","start.local-vs-cloud#0#p":"Всё, что делает Ava, локально, если вы явно не соглашаетесь иначе. Память, задачи, журнал, личность, настройки — всё хранится на вашем компьютере в ~/.ava/ и .ava/ (для каждого проекта). Она общается с поставщиками моделей через HTTPS, чтобы выполнить ваш запрос, а затем возвращается домой. Она не отправляет данные наружу. Она не собирает телеметрию. Она не обучается на вашем коде.","start.local-vs-cloud#1#p":"Если вы войдете в систему, вы получите 300 бесплатных кредитов в месяц на управляемых платформой моделях (Qwen, MiniMax) и опциональную облачную синхронизацию памяти и настроек между устройствами. Синхронизация по функциям, отменяется в любое время. Используйте свой ключ API, и Ava работает полностью без аккаунта.","start.local-vs-cloud#2#c":"Правило: локальное священно. Облако — дополнение.","start.first-model#title":"Нужно ли мне выбирать ИИ?","start.first-model#0#p":"Вот облегчение: вы не выбираете ИИ. Ava автоматически выбирает правильный для каждого шага, так что вы получаете хорошие результаты, не задумываясь об этом.","start.first-model#1#p":"Единственное, что вы можете выбрать — это стиль маршрутизации — и стандартный подходит почти всем. Остальные нужны только по конкретной причине.","start.first-model#2#h":"Три стиля","start.first-model#3#li0":"Maestro — стандартный. Стабильный, надёжный, предсказуемый. Не уверены? Это тот самый.","start.first-model#3#li1":"Supernova — для тяжёлой, многошаговой работы, где выгодно поставить разных специалистов на каждую часть задачи.","start.first-model#3#li2":"Aurora — когда ваши данные должны оставаться в ЕС (государственный сектор, здравоохранение, строгая конфиденциальность). Работает полностью на европейском ИИ с открытыми весами.","start.first-model#4#p":"Переключайтесь в любое время через выбор модели вверху чата. Ничего не заблокировано.","start.first-model#5#c":"Хотите управлять одной конкретной моделью сами? Можете — откройте «Показать детали».","start.first-model#deeper#0#h":"Что именно внутри каждого стиля","start.first-model#deeper#1#p":"Maestro — один дирижёр (Qwen 3.6 Plus) управляет каждым шагом. Настроен для продакшена, проверен, предсказуемая стоимость.","start.first-model#deeper#2#p":"Supernova — координатор передовых технологий (DeepSeek V4 Pro, 1.6 трлн параметров / 49 млрд активных, контекст 1 млн) передаёт каждую подзадачу специалисту: V4 Flash для объёмных сборок, Qwen 3.6 Plus как запасной вариант, Qwen Omni для работы с изображениями.","start.first-model#deeper#3#p":"Aurora — только Mistral, в трёх уровнях: Mistral Large 3 (координатор + тяжёлые специалисты), Mistral Medium 3.5 (128 млрд плотных, контекст 256К, нативное зрение, открытые веса по модифицированной MIT, 77.6% SWE-Bench Verified) для режима Создателя + среднего уровня + зрение + длинные тексты, и Mistral Small 4 на шлюзе намерений. Открытые веса от начала до конца, никогда не покидает инфраструктуру ЕС.","start.first-model#deeper#4#h":"Используйте свою модель (BYOK)","start.first-model#deeper#5#p":"Предпочитаете использовать свой аккаунт ИИ? Вставьте ключ провайдера в настройках, и вы получите и то, и другое — три стиля маршрутизации, плюс возможность выбрать одну модель и полностью исключить маршрутизацию. Полезно при сильном предпочтении, строгом бюджете или тестировании конкретной модели. Полный список провайдеров есть в разделе Справочник.","start.glossary#title":"Глоссарий простым языком","start.glossary#0#p":"Каждое слово, которое вы можете встретить рядом с Ava, объяснено без предположений о знаниях. Вам не нужно запоминать это — возвращайтесь к этому разделу, когда какой-то термин вызывает затруднения.","start.glossary#1#th0":"Слово","start.glossary#1#th1":"Что это на самом деле значит","start.glossary#1#td0.0":"Агент","start.glossary#1#td0.1":"ИИ, который может выполнять действия за вас — читать файлы, запускать команды, искать в интернете — не только общаться. Ava — агент: она делает дела, с вашего разрешения.","start.glossary#1#td1.0":"Модель","start.glossary#1#td1.1":"Настоящий мозг ИИ, который думает (Qwen, DeepSeek, Mistral и другие). У разных моделей разные сильные стороны. Обычно вы никогда не выбираете одну — это делает Ava.","start.glossary#1#td2.0":"Режим","start.glossary#1#td2.1":"Настроение, в котором находится Ava. Как коллега, меняющий шляпы: строитель, писатель, учитель, планировщик, друг. Вы выбираете режим; это меняет её поведение. Их семь.","start.glossary#1#td3.0":"Персона / специалист","start.glossary#1#td3.1":"Вспомогательные роли, которые Ava запускает за кулисами для сложных задач — исследователь, планировщик, фактчекер. Представьте небольшую команду экспертов. Вы никогда не общаетесь с ними напрямую; Ava координирует их.","start.glossary#1#td4.0":"Маршрутизация","start.glossary#1#td4.1":"Ava решает, какую модель использовать на каждом шаге, чтобы вы получали хорошие ответы, не переплачивая. Это происходит автоматически — \\\"режим маршрутизации\\\" просто выбирает общую стратегию.","start.glossary#1#td5.0":"Инструмент","start.glossary#1#td5.1":"Конкретное действие, которое может выполнить Ava — прочитать файл, запустить поиск, отправить письмо. \\\"Вызов инструмента\\\" — это её использование одного из них. Она просит разрешение перед чем-то рискованным.","start.glossary#1#td6.0":"Токен","start.glossary#1#td6.1":"Как ИИ измеряет текст — примерно ¾ слова. Модели тарифицируются за миллион токенов. В основном что-то, что можно игнорировать.","start.glossary#1#td7.0":"Кредит","start.glossary#1#td7.1":"Упрощённая единица измерения стоимости действий в Ava, чтобы вам не пришлось считать токены. Тарифы включают ежемесячный пакет.","start.glossary#1#td8.0":"Ключ API","start.glossary#1#td8.1":"Приватный пароль, который позволяет программному обеспечению использовать платную услугу (например, модель ИИ) от вашего имени. Он нужен только если вы хотите использовать свой собственный.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"«Bring Your Own Key». Использование своего ключа API вместо управляемого доступа Ava. Опционально — для тех, кто уже платит провайдеру напрямую.","start.glossary#1#td10.0":"Локальный приоритет","start.glossary#1#td10.1":"Ваши данные по умолчанию хранятся на вашем компьютере. Ничего не загружается в облако, пока вы не включите синхронизацию. «Локальное — священное.»","start.glossary#1#td11.0":"Режим разрешений","start.glossary#1#td11.1":"Насколько осторожно Ava действует перед выполнением задач — спрашивать каждый раз, только для рискованных действий или просто выполнять. Уровень устанавливаете вы.","start.glossary#1#td12.0":"Контекстное окно","start.glossary#1#td12.1":"Сколько текста модель может удержать в памяти одновременно — её краткосрочная память. «Контекст 1M» означает около миллиона слов. Больше = она может прочитать больше, прежде чем забыть.","start.glossary#1#td13.0":"Дифф","start.glossary#1#td13.1":"Вид рядом с собой того, что именно изменится в файле — старое с одной стороны, новое с другой — показывается до того, как Ava что-то изменит, чтобы вы могли это утвердить.","start.glossary#1#td14.0":"Репозиторий (repo)","start.glossary#1#td14.1":"Папка проекта, отслеживаемая на предмет изменений, обычно через Git. Если это ничего вам не говорит, это просто «папка, где живёт мой проект».","start.glossary#1#td15.0":"Промпт","start.glossary#1#td15.1":"То, что вы вводите ИИ — ваш вопрос или инструкция.","start.glossary#2#c":"Всё ещё застряли на слове? Спросите Ava в режиме Чата — «что означает X?» — и она объяснит это для вашего уровня.","models.routing#title":"Маршрутизация — как Ava выбирает модели","models.routing#0#p":"Вот короткая версия: вам никогда не нужно выбирать, какую модель ИИ использовать. Ava делает это за вас, выбирая лучший инструмент для каждой части задачи — как хороший менеджер передаёт нужную задачу нужному человеку.","models.routing#1#p":"Вы выбираете один из трёх стилей — Maestro, Supernova или Aurora — и Ava отправляет каждую часть работы той модели, которая справляется с ней лучше всего. Maestro — стандартный вариант, он доступен на всех тарифах и подходит почти всем.","models.routing#2#h":"Зачем нужна маршрутизация?","models.routing#3#p":"Использование правильной модели на каждом шаге стоит меньше, чем запуск всего на одной большой дорогой модели — и даёт лучшие результаты, потому что каждая модель делает то, что умеет лучше всего. Вы получаете стабильную стоимость и высокое качество, не зная, какая модель за что отвечает.","models.routing#4#c":"Все три стиля работают на кредиты платформы и на ваши собственные ключи. Со своим ключом вы также можете пропустить маршрутизацию и управлять одной моделью напрямую. Полный список флота находится под разделом «Показать детали».","models.routing#deeper#0#c":"Цифры «B» ниже обозначают миллиарды параметров — примерно размер «мозга» модели; больше обычно означает умнее, но медленнее и дороже. Это техническая деталь «под капотом»; вам никогда не понадобится это знать, чтобы пользоваться Ava.","models.routing#deeper#2#td5.0":"Чат","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Оркестрация генерации изображений","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Визуальные возможности","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (модуль визуального восприятия, обученный с нуля)","models.routing#deeper#2#td8.0":"Написание длинных текстов","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Резидентство данных","models.routing#deeper#2#td9.1":"Комбинированная (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Комбинированная (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Только ЕС · открытые веса","models.routing#deeper#2#td10.0":"Статус","models.routing#deeper#2#td10.1":"Доступно · все планы","models.routing#deeper#2#td10.2":"Скоро","models.routing#deeper#2#td10.3":"Скоро","models.routing#deeper#2#td11.0":"Лучше всего подходит для","models.routing#deeper#1#h":"Рядом","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Координатор","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B активных, 1M контекста)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B активных, 262K контекста)","models.routing#deeper#2#td1.0":"Создатель","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (использует координатора)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B плотных, 256K контекста)","models.routing#deeper#2#td2.0":"Специалисты среднего уровня","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (проверка кода, проверка фактов, поиск информации, сканер, проверка безопасности и т.д.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Архитектор, Проверщик, Планировщик, Наставник, Отчётчик и т.д.)","models.routing#deeper#2#td3.0":"Лёгкий уровень / фильтр намерений","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Разведчик, Проверщик, Планировщик, Оппонент, Интегратор)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Специалисты для сложных задач","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Исследователь, Оппонент, Исследователь уязвимостей CVE, Генератор идей, Проверщик фактов)","models.routing#deeper#2#td11.1":"Ежедневная работа, предсказуемая стоимость","models.routing#deeper#2#td11.2":"Сложная многошаговая работа, ведущий координатор в каждом тарифе","models.routing#deeper#2#td11.3":"Строгое соблюдение GDPR, госсектор, суверенные стеки ЕС","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Маршрутизация Qwen с учётом уровней. Легкий отпечаток. Qwen 3.6 Plus отвечает за координатора, Builder, планирование, безопасность, мозговой штурм и работу с длинным контекстом — там, где её гибридный линейный attention на 1 млн токенов окупается. Qwen 3.5 Flash обрабатывает чат, оркестрацию генерации изображений и верхнеуровневый шлюз намерений, где её цена $0.07/$0.26 и быстрая TTFT выигрывают у большого объёма токенов низкой глубины. Qwen 3.5 Omni Plus отвечает за входные данные зрения (у Qwen 3.6 Plus нет нативного зрения). Qwen 3.5 Plus берёт на себя чувствительную к стоимости работу с длинными текстами. Если основной координатор недоступен, приоритетная лестница падает через Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Полиглотный ансамбль. DeepSeek V4 Pro координирует и направляет каждую подзадачу подходящему специалисту: Qwen 3.6 Plus запускает все спавны Builder, V4 Flash обрабатывает чат и персоны среднего уровня проверки/аудита, Qwen 3.5 Flash берет на себя классификационные задачи лёгкого уровня, Qwen 3.5 Omni Plus отвечает за ввод визуальных данных, Qwen 3.5 Omni Flash оркестрирует вызовы инструментов для генерации изображений, Qwen 3.5 Plus выполняет роль Content Writer, чувствительную к стоимости. Передовые возможности рассуждения там, где они нужны, а экономичность уровня flash — на основном объёме токенов.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Европейский стек ИИ — суверенный по своей сути. Только маршрутизация Mistral в трёх уровнях: Mistral Large 3 (675B/41B-active sparse MoE) выполняет роль координатора и работает с тяжёлыми специалистами, требующими глубины — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — а также с задачами длинного контекста, где эффективна архитектура sparse-MoE. Mistral Medium 3.5 — объединённый флагман, выпущенный в апреле 2026 года, 128B dense, 256K контекст, энкодер зрения обучен с нуля, модифицированные открытые веса MIT, 77.6% SWE-Bench Verified — выполняет основную рабочую нагрузку: спавны Builder, специалисты среднего уровня (Architect, Verifier, Sequencer, Tutor, Reporter), ввод визуальных данных и написание длинных текстов. Mistral Small 4 расширен: если раньше он был лишь на шлюзе намерений, то теперь также обрабатывает чат и оркестрацию генерации изображений — его цена $0.15/$0.60 и настраиваемое рассуждение окупаются на маршрутах с высоким объёмом и низкой глубиной. Открытые веса от начала до конца, данные никогда не покидают инфраструктуру ЕС. Aurora намеренно не переключает молча на немодель Mistral при недоступности; роутер показывает ошибку — именно это делает его \"Aurora\", а не просто Maestro с оттенком Mistral.","credits.overview#title":"Кредиты Ava — как работает оплата","credits.overview#0#p":"Кредиты — это способ подсчёта того, что вы используете, в Ava — как минуты в тарифном плане телефона. Каждый план, включая бесплатный, имеет пул кредитов, и каждое действие Ava (ответ вам, создание изображения) стоит небольшое количество из них. Вот и вся идея. Ниже приведены детали, когда вы хотите точно знать, сколько что стоит.","credits.overview#1#p":"Ava начисляет счета в кредитах, а не в сырых токенах. (Токен — это крошечный кусочек текста — примерно несколько букв, которые модели ИИ читают и пишут; большинство сервисов берут плату за токен, что сложно предсказать.) Один кредит покрывает одну единицу работы — ход чата, спавн персоны (один помощник, делающий часть задачи), генерация изображения. Разделение от метрики на уровне токенов означает, что вам не нужно знать, какая модель работает, чтобы понять, сколько будет стоить действие. Один ход чата стоит одинаково, будь то Maestro маршрутизирует его на Qwen 3.6 Plus или Supernova маршрутизирует его на V4 Pro.","credits.overview#2#h":"Тарифы","credits.overview#3#p":"Каждый тариф даёт доступ ко всем функциям — доступ к моделям, Creative Studio, всем семи режимам, полной оркестровке персон. Более высокие уровни покупают больше кредитов и более высокий лимит запросов, а не разблокированные функции.","credits.overview#4#li0":"Бесплатный — $0/месяц. 300 кредитов. Лимит запросов 20 в минуту. Карта не требуется.","credits.overview#4#li1":"Pro — $19/месяц. 5,000 кредитов. 60 запросов в минуту.","credits.overview#4#li2":"Ultra — $39/месяц. 10,000 кредитов. 120 запросов в минуту.","credits.overview#4#li3":"Enterprise — $79/месяц. 20,000 кредитов. 200 запросов в минуту.","credits.overview#5#c":"Неиспользованные кредиты переносятся, пока ваша подписка активна — принудительного списания нет. Доплаты складываются с пулом подписки: 750 кредитов за $3, 2,000 за $8, 4,000 за $15.","credits.overview#6#h":"Что столько стоит","credits.overview#7#p":"Таблица стоимости действий — что вычитается из вашего пула кредитов при выполнении каждого действия. («Кэш-попадание» — когда Ava повторно использует уже выполненную работу вместо повторения; в этом случае вы платите меньше — сумма списания снижается на 70%, или на 50% для моделей с большим объемом вывода, таких как DeepSeek V4 Pro.)","credits.overview#8#li0":"Ход чата — 2 кредита. Одно взаимодействие в любом режиме.","credits.overview#8#li1":"Лёгкий вызов — 1 кредит. Шлюз намерений, классификация, однократное чтение.","credits.overview#8#li2":"Тяжёлая персона — 3 кредита. Architect, Researcher, CVE Researcher, Ideator (глубина ≥ 4).","credits.overview#8#li3":"Лёгкая персона — 1 кредит. Scout, Verifier, Sequencer, Challenger (глубина ≤ 2).","credits.overview#8#li4":"Оркестрация — 10 кредитов. Полный запуск конвейера персонажей (Кондуктор + задача с несколькими ролями).","credits.overview#8#li5":"Генерация изображений — 12 кредитов. Hailuo image-01 через Creative Studio.","credits.overview#8#li6":"Генерация видео — 150 кредитов. Hailuo 02 Pro 1080p, клип на 6 секунд.","credits.overview#8#li7":"Генерация голоса — 10 кредитов. Синтез речи 2.8 HD.","credits.overview#8#li8":"Генерация музыки — 50 кредитов. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Удаление фона — 2 кредита.","credits.overview#9#h":"Множители для каждой модели","credits.overview#10#p":"Этот раздел для тех, кто хочет разобраться — использовать его не обязательно. Множитель просто меняет стоимость кредита вверх или вниз в зависимости от того, сколько стоит модель, которая выполняет действие: более сложные модели обходятся чуть дороже. («Чистая маржа» — это часть, которую проект оставляет себе после покрытия расходов — мы делаем её небольшой, чтобы вы получали максимум ценности.)","credits.overview#11#p":"Более мощные модели умножают стоимость действия, чтобы кредиты соответствовали реальным расходам, а не фиксированному тарифу. Настроено под ~55% чистой маржи.","credits.overview#12#li0":"0.6× — Mistral Small 4 (специализированная роль Aurora). Ниже 1×, так как Mistral Small 4 дешевле базовой модели Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Базовая ставка.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (координатор Aurora). Примерно соответствует базовой модели Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (координатор Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (координатор Supernova + тяжёлые специалисты). Пересмотрено с 5.0×, чтобы восстановить баланс маржи по опубликованной ставке V4 Pro.","credits.overview#13#c":"Модели Anthropic (Claude Opus / Sonnet / Haiku) полностью исключены из кредитной системы — они работают только по схеме BYOK, и вы платите Anthropic напрямую. То же самое относится к любому другому провайдеру BYOK при использовании вашего собственного ключа.","credits.overview#14#h":"BYOK и кредиты","credits.overview#15#p":"BYOK («принеси свой ключ» — вы используете свою учётную запись у провайдера ИИ и ключ, который служит приватным паролем для доступа к этой платной учётной записи) предназначена для тех, кто уже оплачивает услуги провайдера ИИ напрямую. Если это не ваш случай, вы можете полностью игнорировать этот раздел.","credits.overview#16#p":"Запросы с собственным ключом полностью обходят инфраструктуру платформы — запрос идёт напрямую от Ava к провайдеру, вы платите провайдеру, кредиты не расходуются. Единственное исключение: если сессия BYOK запускает управляемую персону для подзадачи; списание кредитов всё равно применяется, так как используется сервис оркестрации Ava.","credits.overview#17#h":"Где проверить баланс","credits.overview#18#li0":"Расширение — Настройки → Аккаунт, или плашка с кредитами в заголовке чата.","credits.overview#18#li1":"IDE — Плитка панели управления аккаунтом показывает текущий баланс и скорость расхода.","credits.overview#18#li2":"Веб-версия — ava-supernova.com/dashboard показывает баланс, историю и дату продления.","credits.overview#19#c":"Локальный режим: Ava работает без аккаунта в разделе «Своя модель» (Ollama, LM Studio, vLLM или любой интерфейс, совместимый с OpenAI). Нет кредитов, нет токенов платформы — ваша модель, ваш компьютер, ваш счёт равен нулю.","concepts.modes#title":"Режимы — состояния Ava","concepts.modes#0#p":"Режим — это состояние, в котором находится Ava — как коллега, сменившая шляпу. Один и тот же человек, одна и та же память о вас, но разработчик мыслит иначе, чем учитель. Вы выбираете режим, и он меняет то, как она ведёт себя и каких помощников привлекает. Переключайте его в любой момент через переключатель режимов или введите двухсимвольную команду.","concepts.modes#2#h":"Какой из них вам нужен?","concepts.modes#3#p":"Начните с того, что вы хотите сделать — режим следует из этого:","concepts.modes#4#li0":"Я хочу что-то построить или изменить → Код (>>). Вы описываете задачу, она строит, сначала показывая каждое изменение. Вся команда помощников подключается для больших задач.","concepts.modes#4#li1":"Я хочу план перед любыми изменениями → План (::). Она всё обдумает и предложит план, который вы утвердите или отредактируете. В этом режиме она не будет трогать ваши файлы.","concepts.modes#4#li2":"Я просто хочу поболтать или задать вопрос → Чат (..). Партнёр для размышлений с памятью, новостями и погодой. Никаких изменений файлов и кода — только разговор.","concepts.modes#4#li3":"Я хочу чему-то научиться → Обучение (??). Реальный курс, созданный специально для вас: уроки, тесты и всё остальное. Бесплатно на любом тарифе навсегда. Идеально, если вы новичок.","concepts.modes#4#li4":"Я хочу проверить проект на дыры в безопасности → Безопасность (!!). Команда проходит по стандартному списку распространённых веб-уязвимостей (категории OWASP) и известным сообщённым ошибкам (называемым «CVE»), затем передаёт вам отчёт, отсортированный по степени серьёзности каждой проблемы. Этот режим для разработчиков — пропустите, если это не про вас.","concepts.modes#4#li5":"Я хочу идеи → Мозговой штурм (**). Она генерирует варианты, основанные на вашей реальной ситуации, находит слабые места в плохих идеях и превращает остальные в конкретные шаги.","concepts.modes#4#li6":"Я хочу написать документ → Письмо (<<). Отчёты, предложения, письма, статьи — она составляет черновик в Markdown и экспортирует брендированный документ Word или PDF, улучшая раздел за разделом. Никакого кода, только текст.","concepts.modes#5#c":"Команда помощников (персоны) работает полностью за кулисами — вы никогда не общаетесь с ними напрямую. Вы просто получаете более полный ответ. Вам не нужно знать их имена.","concepts.modes#6#c":"Вы можете переключать режимы во время разговора. Ваша память сохраняется; специалисты сбрасываются под новый режим.","concepts.tasks-journal#title":"Задачи и журнал","concepts.tasks-journal#0#p":"Ava ведёт три вида заметок для вас, и их легко перепутать. Быстрый способ запомнить: память — это то, что она знает о вас, задачи — это то, что вам ещё нужно сделать, а журнал — это дневник того, как всё прошло. Вот когда что использовать.","concepts.tasks-journal#1#li0":"Память — постоянные факты. Предпочтения, решения, паттерны. О них спрашивают часто, редко создают вручную.","concepts.tasks-journal#1#li1":"Задачи — дела, которые нужно сделать. Пункты действий с датами и статусом. Вы отмечаете их выполненными.","concepts.tasks-journal#1#li2":"Журнал — размышления. Ежедневный лог, двойные записи (ваши и наблюдения Ava о сессии). Полезно для отслеживания настроения, обзора сессий, контекста на завтра.","concepts.tasks-journal#2#p":"Ava пишет во все три раздела, когда это уместно. Вы можете писать в любой из них прямо из панели управления. Ничего не привязано к одному месту использования Ava — задача, созданная в одном (например, в инструменте командной строки), появляется везде (как в десктопном приложении), автоматически.","concepts.permissions#title":"Разрешения — ваш регулятор безопасности","concepts.permissions#0#p":"Разрешения — это ваш регулятор безопасности. Они решают, когда Ava должна спросить ваше разрешение перед действием на компьютере, а когда просто действовать. Можно настроить так, чтобы она спрашивала обо всём, только о рискованных вещах, или доверять ей полностью. И вы можете менять это в любое время. Если сомневаетесь, оставьте настройки по умолчанию, и всё будет хорошо.","concepts.permissions#1#p":"У Ava 60 инструментов («инструменты» — это действия, которые она может выполнить — чтение файла, поиск в вебе и так далее). Каждый инструмент относится к категории (операции с файлами, оболочка, Git, веб, медиа, база данных, система, документы, память, обучение). Каждый вызов инструмента проходит через шлюз разрешений (контрольную точку, решающую, спрашивать ли вас сначала) перед запуском. Вы контролируете, что одобряется автоматически, что спрашивает один раз, а что всегда требует подтверждения.","concepts.permissions#3#p":"Баланс — это настройка по умолчанию. Строгий режим, когда вы проверяете её поведение (внимательно следите за каждым шагом). Автономный режим, когда вы хотите, чтобы она просто действовала.","concepts.permissions#4#c":"Автономный режим не означает отсутствие контроля. Планы, уточняющие вопросы и явные запросы к пользователю всё равно ждут вашего ввода. Необратимые операции (Git force-push, удаление баз данных) всегда требуют подтверждения, независимо от режима.","concepts.interjection#title":"Управление и остановка Ava","concepts.interjection#0#p":"Вы всегда управляете процессом. Пока Ava занята работой, вы можете либо мягко направить её в новое русло, не сбивая темпа, либо остановить её мгновенно. Две кнопки, два результата — вот и всё, о чём эта страница.","concepts.interjection#1#p":"Ava работает до тех пор, пока не выполнит свой план или пока вы её не остановите. У вас есть два способа вмешаться (слово для этого — «интервенция»), пока она работает.","concepts.interjection#2#h":"Вмешаться — направлять без отмены","concepts.interjection#3#p":"Отправьте новое сообщение, пока Ava работает. Она завершит текущее действие, прочитает ваш текст и скорректирует план. Ничего не потеряется. Используйте этот способ, если нужно перенаправить задачу, добавить детали или сменить приоритеты прямо в процессе.","concepts.interjection#4#h":"Резкая остановка — отмена и сброс","concepts.interjection#5#p":"Нажмите Escape (CLI), кликните «Стоп» (расширение, IDE) или введите команду остановки. Текущий процесс прерывается, все ожидающие действия отменяются, и диалог готов к новому шагу.","concepts.interjection#6#c":"Сначала попробуйте вмешаться. Резкая остановка — только если что-то пошло не так. Вмешательство позволяет продолжить работу.","concepts.desktop-personas#title":"Роли на рабочем столе","concepts.desktop-personas#0#p":"Эта страница для тех, кто хочет разобраться, и для опытных пользователей. «Автоматизация рабочего стола» (иногда называют «управление компьютером») значит, что Ava может сама кликать по экрану и работать в приложениях за вас — открывать Gmail, заполнять формы, отправлять сообщения — как живой человек за клавиатурой. Чтобы сделать это безопасно, она делит задачу на пять небольших помощников, у каждого своя чёткая роль. Вы не взаимодействуете с ними напрямую; здесь мы просто показываем, кто за что отвечает.","concepts.desktop-personas#1#p":"Каждый этап работы Ava на вашем экране (один запуск, ведущий к цели) проходит через «волну» из пяти ролей. У каждой роли одна задача и только одна. Такое разделение делает инструкции точными, результаты структурированными, а рассуждения — критическими по умолчанию.","concepts.desktop-personas#2#h":"Разведчик","concepts.desktop-personas#3#p":"Сообщает, что сейчас видно на экране. Никогда не выдумывает элементы и не строит планов. Возвращает состояние экрана в формате JSON со списком элементов, их именами, координатами, степенью уверенности и источником данных (UIA, Playwright DOM или визуальное распознавание OmniParser).","concepts.desktop-personas#4#h":"Планировщик","concepts.desktop-personas#5#p":"Принимает решение об одном следующем действии. Только одно действие за шаг — никаких пакетов. Предпочитает пути, которые можно легко отменить. Оценивает риск по шкале безопасности. Формирует JSON с предложением действия, указывая тип, цель, параметры, уровень риска, обоснование и прогноз того, что будет дальше.","concepts.desktop-personas#6#h":"Исполнитель","concepts.desktop-personas#7#p":"Выполняет ровно то, что предложил Планировщик — только после получения разрешения. Никаких импровизаций. Никаких повторов. Если что-то идёт не так, это честно фиксируется, а следующую попытку берёт на себя Верификатор.","concepts.desktop-personas#8#h":"Контролёр","concepts.desktop-personas#9#p":"Проверяет, удалось ли выполнить действие. Сопоставляет текущее состояние экрана с прогнозом Планировщика. Возвращает результат: подтверждено, отклонено или требуется откат. Также следит за циклами — повторение уже выполненного действия считается ошибкой, а не успехом.","concepts.desktop-personas#10#h":"Рассказчик","concepts.desktop-personas#11#p":"Это единственный голос, который слышит пользователь в ходе работы. За каждый шаг — одно короткое предложение в прошедшем времени («Открыл Gmail.», «Нажал „Создать“.»). Также ведёт структурированный журнал событий. Сообщает о проблемах сразу — ничего не скрывает.","concepts.desktop-safety#title":"Онтология безопасности на рабочем столе","concepts.desktop-safety#0#p":"Проще говоря: прежде чем Ava кликнет что-либо на вашем экране, она оценивает риск действия. Чтение экрана? Безопасно. Отправка денег или удаление файлов? Она всегда останавливается и спрашивает вас — каждый раз, без исключений. Пять категорий ниже — это ступени такой лестницы рисков. Это техническая деталь для опытных, но главное простое: всё опасное всегда требует вашего согласия.","concepts.desktop-safety#1#p":"Любое предлагаемое действие попадает в один из пяти классов риска. Оценка складывается из трёх сигналов: что находится на экране, описание простыми словами («семантическая подпись» — так Ava называет то, что видит), и настройки действия. Если сигналы противоречат друг другу, риск повышается. Ложная тревога (спросить там, где не надо) — это просто лишнее беспокойство. А вот пропустить вопрос там, где он нужен, — это серьёзный сбой.","concepts.desktop-safety#2#h":"Пять классов","concepts.desktop-safety#3#li0":"Наблюдение — чтение дерева UIA, скриншот, наведение курсора. Всегда разрешается автоматически.","concepts.desktop-safety#3#li1":"Навигация — прокрутка, перемещение фокуса, открытие меню. Автоматически разрешено в режиме Drive.","concepts.desktop-safety#3#li2":"Обратимые действия — ввод текста, вставка, запуск приложения, переход по ссылке. В режиме «Запрос» требуется подтверждение; в режиме Drive внутри белого списка работает автоматически.","concepts.desktop-safety#3#li3":"Необратимые действия — отправка, подача формы, оплата, удаление, подтверждение, публикация. Всегда требует подтверждения, независимо от уровня прав. Одобрение никогда не запоминается.","concepts.desktop-safety#3#li4":"Привилегированные — повышение прав через UAC, sudo, изменение реестра, запросы учётных данных. Запрещено по умолчанию. Требуется разовое согласие для каждой сессии.","concepts.desktop-safety#4#h":"Одобрения не сохраняются в кэше","concepts.desktop-safety#5#p":"Все конкуренты сохраняют одобрения (запоминают ваше «да» и используют его снова). Это главная уязвимость для атак через промпт-инъекцию — когда вредоносная веб-страница подсовывает ИИ скрытые команды, чтобы он действовал против вас. Если одобрения кэшируются, взломанная страница может воспользоваться вашим предыдущим «да». Ava никогда не кэширует. Каждое необратимое действие запрашивается заново.","concepts.desktop-safety#6#h":"Обработка секретов","concepts.desktop-safety#7#p":"Пароли, ключи API и коды двухфакторной аутентификации (однозначные коды, которые второе приложение или SMS присылают вам при входе) обрабатываются через заглушки — вместо реального значения. Ava видит \"{secret}\", а не сам пароль. Реальное значение никогда не попадает в её память, лог активности или то, что она «читает» — отдельный низкоуровневый слой вводит его в последний момент, при нажатии клавиши, так что часть ИИ никогда с ним не соприкасается.","reference.cli#title":"Команды CLI","reference.cli#0#p":"Эта страница посвящена CLI — версии Ava, в которую вы пишете в терминале, вместо того чтобы нажимать кнопки. Если вы используете расширение или десктопное приложение, можете пропустить это. Она здесь для тех, кто предпочитает клавиатуру.","reference.cli#1#p":"CLI — это REPL — оболочка, которая ждёт ввода, выполняет команду, затем снова ждёт. Эти слеш-команды (инструкции, начинающиеся с \"/\") работают прямо из оболочки.","reference.cli#2#li0":"/help — список команд и текущего режима.","reference.cli#2#li1":"/mode <name> — переключение режима (работа, письмо, планирование, чат, обучение, безопасность, мозговой штурм).","reference.cli#2#li2":"/model <id> — смена модели без выхода из сессии.","reference.cli#2#li3":"/clear — очистка текущего диалога. Память остаётся нетронутой.","reference.cli#2#li4":"/history — список прошлых диалогов в этом проекте.","reference.cli#2#li5":"/memory — открыть браузер памяти.","reference.cli#2#li6":"/tasks — список и управление задачами.","reference.cli#2#li7":"/journal — открыть дневник за сегодня.","reference.cli#2#li8":"/settings — открыть меню настроек.","reference.cli#2#li9":"/exit — выйти из REPL.","reference.cli#3#h":"Флаги запуска","reference.cli#4#p":"Флаги — дополнительные опции, которые вы добавляете при запуске Ava, каждая начинается с \"--\", чтобы задать способ её открытия.","reference.cli#5#li0":"--mode <name> — запуск в определённом режиме.","reference.cli#5#li1":"--model <id> — запуск с конкретной моделью.","reference.cli#5#li2":"--permission <mode> — строгий / сбалансированный / автономный.","features.creative-studio#1#p":"Генерация изображений, видео, музыки и голоса — всё встроено в тот же рабочий процесс, что и ваш код. Создайте иконку, макет продукта, демо-видео или закадровый голос для урока. Работает на базе MiniMax.","features.creative-studio#2#h":"Что вы можете создать","features.creative-studio#3#li0":"Изображения — от промпта до PNG/JPG. Удаление фона — одним запросом.","features.creative-studio#3#li1":"Видео — короткие ИИ-видео по текстовому запросу (MiniMax Hailuo).","features.creative-studio#3#li2":"Музыка — инструментальные или вокальные треки с текстом песни.","features.creative-studio#3#li3":"Голос — синтез речи из текста с выбором голоса.","features.creative-studio#4#p":"Расходы Creative Studio идут из того же пула кредитов, что и всё остальное — один пул, одна цифра. Используйте BYOK для своего ключа MiniMax, и это бесплатно для вашего тарифа.","features.creative-studio#5#c":"Creative Studio доступен в бесплатном тарифе. Это не платная надстройка.","features.desktop-automation#title":"Автоматизация рабочего стола","features.desktop-automation#0#p":"Простыми словами: Ava может взять на себя управление мышью и клавиатурой, чтобы выполнить задачи за вас — открыть приложение, нажать кнопки, заполнить форму — пока вы наблюдаете и подтверждаете важные действия.","features.desktop-automation#1#p":"Новый режим для Ava, префикс @@. Она наблюдает за рабочим столом, решает, что делать, и управляет автоматизацией интерфейса (контролирует приложения на вашем экране за вас), чтобы выполнить задачу. Запускается на вашей реальной машине с вашими реальными учётными данными — не облачный браузер. Доступен на всех тарифах после выпуска.","features.desktop-automation#2#h":"Зачем ещё один?","features.desktop-automation#3#p":"Любой другой продукт для автоматизации рабочего стола запускается, когда вы сидите за столом. Ava остаётся рядом, когда ваш трекер ошибок срабатывает в 2 часа ночи — IDE продолжает работать, ваш телефон подключается через защищённый канал, вы подтверждаете необратимые действия одним касанием.","features.desktop-automation#4#p":"Она также помнит, как перемещаться по вашим приложениям между сессиями. Каждый другой агент переучивает их каждый раз. Разница в памяти становится ценнее при использовании.","features.desktop-automation#5#h":"Как это работает","features.desktop-automation#6#p":"Каждый шаг использует команду из пяти ролей: Scout наблюдает, Planner выбирает следующее действие, Actor выполняет, Verifier проверяет, Narrator рассказывает, что произошло. Sidecar выбирает самое доступное и надёжное решение — UIA для нативных приложений, Playwright для браузеров, OmniParser vision, если у других нет полезной структуры.","features.desktop-automation#7#p":"Подробнее читайте в разделе «Концепции»: система понятий безопасности, иерархия подтверждения фактов, аварийные выключатели и модель разрешённых сессий.","reference.cli#5#li3":"--project <path> — явно задать корень проекта.","reference.desktop-budget#title":"Лимиты бюджета для рабочего стола","reference.desktop-budget#0#p":"Когда Ava управляет вашим рабочим столом от вашего имени — кликает, печатает, открывает приложения — каждый такой запуск называют «траекторией». На этой странице описаны лимиты безопасности, которые не дают ни одному запуску длиться слишком долго или стоить слишком дорого. Главное: она всегда останавливается и сверяется перед тем, как превысить лимит. Числа здесь, если нужны подробности.","reference.desktop-budget#1#p":"Каждая траектория работает под тремя одновременными ограничениями (жёсткими лимитами). Срабатывает тот, который достигнут первым. Траектория никогда не продолжает работу молча после нарушения — Рассказчик (помощник, который объясняет, что происходит) ставит процесс на паузу и спрашивает, что делать.","reference.desktop-budget#2#h":"Три жёстких лимита (по умолчанию)","reference.desktop-budget#3#li0":"Количество шагов — 30 шагов","reference.desktop-budget#3#li1":"Бюджет токенов — 500 000 токенов","reference.desktop-budget#3#li2":"По времени — 5 минут","reference.desktop-budget#4#h":"Группы стоимости задач","reference.desktop-budget#5#li0":"Простая (поиск в документах, открытие страницы) — 5–10 шагов, ~70–135K токенов, ~$0,04–0,08","reference.desktop-budget#5#li1":"Средняя (вход в систему, проверка логов, скачивание результата) — 15–25 шагов, ~205–340K токенов, ~$0,12–0,21","reference.desktop-budget#5#li2":"Сложная (разбор трёх вопросов в GitHub) — 25–30 шагов, ~340–410K токенов, ~$0,21–0,25","reference.desktop-budget#6#p":"Указанные выше цифры по токенам — это технические лимиты на одну траекторию, а не ваш месячный лимит — он считается в кредитах, и бесплатного тарифа с 300 в месяц достаточно для смеси чатов, кода и нескольких автоматизаций.","reference.desktop-budget#7#c":"Вы можете изменить лимиты для каждой задачи при старте, но при нарушении всегда появляется точка принятия решения. Бюджет никогда не тратится молча.","reference.desktop-whitelist#title":"Список разрешений для сессии рабочего стола","reference.desktop-whitelist#0#p":"«Список разрешений» — это просто список приложений и сайтов, которые вы разрешили трогать Ava, пока она управляет вашим рабочим столом. На этой странице объясняется, как вы предоставляете это разрешение и почему оно сбрасывается каждый раз. Коротко: она может действовать только там, где вы разрешили, и спрашивает перед переходом куда-то новое.","reference.desktop-whitelist#1#p":"В начале сессии рабочего стола Ava спрашивает, где ей разрешено действовать. Подойдёт простой текст: «Gmail, Cursor, портал Azure». Она читает это и подтверждает совпадение вам («веб-версия Gmail, приложение Cursor, portal.azure.com»).","reference.desktop-whitelist#2#h":"Как это обеспечивается","reference.desktop-whitelist#3#p":"Действия только для просмотра — создание скриншота, чтение списка кнопок и полей на экране (так называемое «дерево UIA», собственная карта Windows того, что находится в окне) — разрешены везде, потому что вам нужно видеть, что на экране, чтобы решить, добавить ли приложение в список разрешений. Всё, что что-то меняет, блокируется вне списка; Ava ставит паузу и спрашивает, добавить ли его.","reference.desktop-whitelist#4#h":"Ограничено сессией, намеренно","reference.desktop-whitelist#5#p":"Список разрешений НЕ сохраняется между сессиями. Нет опции «запомнить это приложение». Каждый новый запуск начинается с чистого списка. Это неудобство по замыслу — забыть повторную авторизацию это функция, а не ошибка.","reference.desktop-whitelist#6#h":"Добавления во время выполнения","reference.desktop-whitelist#7#p":"Во время выполнения вы можете добавить приложения из заголовка: «+ Разрешить приложение» открывает небольшое поле ввода. Нажмите «Добавить», и новое приложение станет доступно до конца сессии.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Хотите создать изображение, короткое видео, песню или озвучку? Просто опишите это, и Ava сделает это для вас — никакие программы для дизайна или звука не требуются."},"ar":{"start.for-non-coders#6#li3":"عندما تريدين منها تنفيذ أو تعديل شيء فعليًا، اسأليها ببساطة — ستعرض عليك دائمًا ما تنوي فعله وتنتظر موافقتك بـ \"نعم\".","start.for-non-coders#7#c":"هل صادفت كلمة لا تفهم معناها؟ قاموس المصطلحات بلغة بسيطة (في أسفل هذا القسم) يوضح كل مصطلح دون افتراض أي معرفة سابقة.","start.install#title":"التثبيت","start.install#0#p":"اختاري الواجهة التي تناسب أسلوب عملك. يمكنك استخدام أكثر من واحدة — حيث تتزامن ذاكرة Ava بينها جميعًا عند تسجيل الدخول.","start.install#1#h":"إضافة VS Code","start.install#2#li0":"افتحي لوحة الإضافات في VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"ابحثي عن \"Ava Supernova\" وانقري على تثبيت.","start.install#2#li2":"اضغطي Ctrl+Shift+A (Cmd+Shift+A على macOS) لفتح لوحة الدردشة.","start.install#2#li3":"اتبعي معالج الإعداد — اختاري نموذجًا، اضبطي وضع الصلاحيات، انتهيت.","start.install#3#h":"IDE سطح المكتب","start.install#4#li0":"حمّلي المثبت لمنصتك من صفحة الإصدارات.","start.install#4#li1":"شغّلي الملف. سيفتح IDE لأول مرة مع تجربة ترحيبية.","start.install#4#li2":"سجّلي الدخول للحصول على الرموز المجانية للمنصة، أو الصقي مفتاح API الخاص بك للتشغيل المحلي الكامل.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (أو pnpm / yarn — اختيارك).","start.install#6#li1":"شغّلي ava في أي مجلد مشروع.","start.install#6#li2":"أول تشغيل يطلب منك مزود الخدمة ونموذجًا. اختاري وابدئي.","start.install#7#c":"لا حساب، لا مشكلة. بمفتاح API خاص بك (BYOK) لن تحتاجي أبدًا لتسجيل الدخول. الطبقة المجانية مخصصة للنماذج التي تديرها المنصة.","start.for-non-coders#title":"لم تكتب كودًا من قبل؟ ابدأ هنا","start.for-non-coders#0#p":"إذا لم تكتب سطرًا واحدًا من الكود من قبل، فأنت بالضبط من أجله Ava. لا تحتاج إلى تعلم أي مصطلحات تقنية للبدء — تتحدث معها باللغة الإنجليزية البسيطة، كما تسأل صديقًا خبيرًا. هذه الصفحة هي مدخلك بالكامل.","start.for-non-coders#1#h":"ما يمكنك فعله اليوم، بدون خبرة","start.for-non-coders#2#li0":"اسألها أي شيء، بكلمات عادية — \\\"ماذا يفعل هذا الملف؟\\\", \\\"لماذا صفحتي فارغة؟\\\", \\\"ما هي قاعدة البيانات حتى؟\\\" تجيب بلغة بسيطة وتتذكر المحادثة.","start.for-non-coders#2#li1":"تعلّم شيئًا من الصفر — قل \\\"علّمني بايثون من الصفر\\\" وهي تبني لك دورة مناسبة مع دروس واختبارات. هذا مجاني دائمًا.","start.for-non-coders#2#li2":"احصل على شيء مبني — صف ما تريده (\\\"زر يقوم بتنزيل ملاحظاتي\\\") وهي تكتبه، مُظهِرةً لك كل تغيير قبل حدوثه.","start.for-non-coders#3#h":"لا تحتاج إلى فهم كل شيء","start.for-non-coders#4#p":"لدى Ava الكثير من الآليات تحت الغطاء — الأوضاع، النماذج، المتخصصون، التوجيه. ستجد هذه الكلمات حول التطبيق وفي هذه الوثائق. إليك السر: يمكنك تجاهل معظمها تقريبًا. تختار Ava الأدوات الصحيحة والمساعدات المناسبة لك تلقائيًا. الصفحات التقنية موجودة عندما تشعر بالفضول، وليس لأنك تحتاجها للبدء.","start.for-non-coders#5#h":"طريق أول لطيف","start.for-non-coders#6#li0":"ثبت Ava (الصفحة التالية) وافتح الدردشة.","start.for-non-coders#6#li1":"اكتب سؤالًا حقيقيًا لديك. أي شيء. شاهد كيف تجيب.","start.for-non-coders#6#li2":"جرب وضع التعلم: اكتب \\\"علّمني\\\" وموضوعًا. تابع معنا.","concepts.memory#1#p":"Ava لديها ذاكرة دائمة (\"دائمة\" تعني أنها تبقى موجودة حتى بعد إغلاق التطبيق)، وهي تتجاوز المحادثات والمشاريع والأجهزة إذا قمت بتمكين المزامنة (تقوم المزامنة بنسخ ذكرياتك بين أجهزتك). ليست مجرد سجل محادثة. إنها فهم منظم وقابل للبحث عن هويتك، وما تحبّه، وما قرّرتَه.","concepts.memory#2#h":"خمس طبقات","concepts.memory#3#li0":"استخراج — حقائق رئيسية تُلتقط من كل رسالة في الوقت الفعلي.","concepts.memory#3#li1":"تأمّل — تحليل أعمق يُجرى في نهاية الجلسات الهادفة. أنماط، مواضيع، تناقضات.","concepts.memory#3#li2":"تراكم — التصحيحات والتفضيلات تتراكم مع مرور الأسابيع والأشهر.","concepts.memory#3#li3":"تحليل — يربط محرك الرسم البياني الذكريات ذات الصلة ويُبرز التناقضات عند تعارض المعلومات الجديدة مع القديمة.","concepts.memory#3#li4":"توحيد — تندمج الذكريات المتشابهة؛ وتُزال القديمة منها. تصبح الذاكرة أكثر دقة مع الوقت، لا أكثر ضجيجًا.","concepts.memory#4#c":"الطبقات الخمس أعلاه تعمل تلقائيًا — لن تحتاج أبدًا لإدارتها. هي هنا لتراك كيف تتحسن الذاكرة حقًا مع الوقت بدلًا من أن تتحول إلى فوضى.","concepts.memory#5#h":"استرجاع","concepts.memory#6#p":"عندما تطرح سؤالاً، تبحث Ava في الذاكرة بالمعنى (\"البحث الدلالي\" — تفهم ما تقصده، لذا تجد الذاكرة الصحيحة حتى لو صغّت السؤال بشكل مختلف)، وليس فقط بمطابقة الكلمات حرفيًا. تعمل فلاتر خاصة بكل وضع جنبًا إلى جنب — وضع المحادثة يجلب السياق الشخصي، ووضع العمل يجلب قرارات المشروع وأنماط الكود.","concepts.memory#7#c":"الذاكرة محدودة لكل مستخدم وكل مشروع (ذكرياتك لك، محفوظة منفصلة حسب الشخص وحسب المشروع). يتم حظر الأسرار والبيانات الحساسة (كلمات المرور، المفاتيح) عند نقطة الحفظ — لا يمكنها أبدًا الوصول إلى الذاكرة.","concepts.memory#title":"الذاكرة — كيف تتذكر Ava شخصك","concepts.memory#0#p":"ببساطة: Ava تتذكرك. أخبرها بشيء مرة واحدة — ما تحبه، أو قرار اتخذته — وستحتفظ به، حتى لا تضطر للتكرار في المحادثة التالية أو الأسبوع القادم. هذا هو الخبر الرئيسي. الطبقات أدناه تشرح فقط كيف تحافظ على هذه الذاكرة مرتبة مع الوقت.","concepts.desktop-grounding#title":"تسلسل أساسيات سطح المكتب (معاينة)","concepts.desktop-grounding#0#c":"معاينة — كيف يقرر Scout مصدر الأساس المناسب لكل خطوة.","concepts.desktop-grounding#1#p":"قبل أن تتمكن Ava من النقر على زر، يجب أن تفهم فعلياً ما هو على شاشتك وأين الأشياء — هذا هو \"التأسيس\" (تحديد ماهية كل شيء على الشاشة ومكانه الدقيق). لديها ثلاث طرق للقيام بذلك وتختار الأكثر موثوقية التي تعمل مع التطبيق الذي تستخدمه. هذه تفاصيل متقدمة للمستخدم المحترف؛ النقطة هي فقط أنها تفضل الطرق الصلبة والدقيقة بدلاً من التخمين من صورة.","concepts.desktop-grounding#2#p":"ثلاث مستويات، تُقيّم بالترتيب. المصدر الموثوق الأرخص يفوز.","concepts.desktop-grounding#3#h":"1. نافذة المتصفح → Playwright DOM","concepts.desktop-grounding#4#p":"إذا كانت النافذة النشطة متصفح ويب، تقرأ Ava بنية الصفحة الخاصة (الـ \"DOM\" — القائمة الأساسية لما هو موجود في صفحة) بدلاً من التخمين من الصورة. قراءة البنية أكثر موثوقية بحوالي 10 مرات من النظر إلى البكسلات — تعرف بالضبط أين كل زر ومتى انتهت الصفحة من التحميل. هذا هو المسار الرئيسي لأي شيء على الويب، وليس نسخة احتياطية.","concepts.desktop-grounding#5#h":"2. تطبيق أصلي مع UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"للتطبيقات العادية على سطح المكتب في Windows، تقرأ Ava خريطة إمكانية الوصول المدمجة (\"UIA\"، نفس البيانات التي تستخدمها قارئات الشاشة لوصف نافذة) — تذكر كل عنصر، اسمه، ومكانه. إذا عادت الخريطة بخمسة عناصر قابلة للاستخدام ومُسمّاة على الأقل، فهي تثق بها وتستخدمها.","concepts.desktop-grounding#7#h":"3. UIA فارغة أو غير صالحة → رؤية OmniParser","concepts.desktop-grounding#8#p":"عندما تكون تلك الخريطة مفقودة أو عديمة الفائدة (بعض التطبيقات والألعاب وشاشات عن بعد لا توفر واحدة)، تتراجع Ava فعلياً للنظر إلى لقطة شاشة. أداة رؤية (OmniParser) تكتشف المناطق القابلة للنقر وتُعرّف ما هو كل واحد منها، محولة الصورة مرة أخرى إلى قائمة يمكنها التصرف عليها — مجتمعة مع أي قليل قدمته خريطة إمكانية الوصول.","concepts.desktop-grounding#9#c":"OmniParser اختياري لأول مرة تحتاج إليها Ava، مع إشعار خصوصية واضح. مستخدمو BYOK يمكنهم توجيهها نحو نشر OmniParser المحلي الخاص بهم.","concepts.desktop-kill-switches#title":"مفاتيح إيقاف طارئ لسطح المكتب (معاينة)","concepts.desktop-kill-switches#0#c":"معاينة — ثلاث طرق مستقلة لإلغاء مسار عمل قيد التنفيذ. أي واحدة منهم تفوز.","concepts.desktop-kill-switches#1#p":"\"مفتاح الإيقاف\" هو بالضبط ما يوحي به الاسم — طريقة طارئة لإيقاف Ava فوراً عندما تتحكم في شاشتك. الجانب المشجع: هناك ثلاثة منها، مبنية بشكل منفصل، لذا إذا فشل واحد يعمل الآخر. لا يجب عليك تعلم الثلاثة جميعاً. فقط اعرف أنه عندما يبدو شيء خاطئ، يمكنك دائماً إيقافه، وأقوى توقف (إيقاف الطوارئ أدناه) لا يعتمد على تعاون Ava.","concepts.desktop-kill-switches#2#p":"بعد قراءة كل حادث استقلالية عام (حالات حقيقية حيث تجاهلت وكلاء الذكاء الاصطناعي أوامر التوقف، وحذفت أرشيفات البريد الإلكتروني، ومسحت الأقراص)، بنينا ثلاثة مفاتيح إيقاف في ثلاث طبقات مختلفة. لا تعتمد أي منها على نموذج الذكاء الاصطناعي نفسه — إذا كانت Ava عالقة أو غير مستجيبة، يمكنك إيقافها.","concepts.desktop-kill-switches#3#h":"إيقاف مؤقت — المسافة أو زر الإيقاف المؤقت","reference.models#11#h":"استخدم مفتاحك الخاص","reference.models#12#p":"مفتاح \"API\" هو كلمة مرور خاصة تسمح للبرامج باستخدام خدمة مدفوعة على حسابك. \"BYOK\" تعني ببساطة \"استخدم مفتاحك الخاص\" — أي استخدام مفتاحك بدلاً من مفتاحنا. الصق مفتاح الـ API في الإعدادات. تذهب طلبات BYOK مباشرة من Ava إلى المزود (الشركة التي تشغل النموذج) — لا تمر عبر بنيتنا التحتية ولا تستهلك رموز المنصة. أنت تدفع للمزود؛ نحن لا نرى حركة المرور.","reference.models#14#c":"للحصول على نتائج الاختبارات، وعلامات القدرات، والفرز الجانبي، راجع صفحة النماذج الكاملة على ava-supernova.com/models. الأسعار المعروضة أعلاه هي أفضل قراءة لدينا لبطاقة أسعار كل مزود عند النشر — تحقق دائمًا من موقع المزود قبل الالتزام بأي عمل.","reference.personas#title":"تنسيق الشخصيات","reference.personas#0#p":"الشخصية هي دور مساعد تلعبه Ava خلف الكواليس للمهام الأصعب — مستكشف، مخطط، مدقق حقائق. لن تتحدث معهم مباشرة ولن تحتاج لفهم هذه الصفحة لاستخدام Ava. هي هنا عندما تتساءل كيف تقسم مهمة كبيرة إلى فريق خبراء صغير.","reference.personas#1#p":"24 متخصصًا عبر 5 فرق وضع. الموصل (المساعد الذي ينسق الباقي) يقرر أي فريق يعمل، وبأي ترتيب، ومع أي سياق. وضع الدردشة لا يحتوي على شخصيات — إنها Ava نفسها.","reference.personas#2#h":"كيف يعمل التنسيق","reference.personas#3#li0":"ترسل رسالة في وضع التخطيط، أو التدريس، أو الأمان، أو العصف الذهني (أو طلب عمل معقد).","reference.personas#3#li1":"يقرأ الموصل الطلب، يختار فريق الوضع، ويبني خطة تنفيذ — بعض الشخصيات تعمل بالتتابع، وبعضها في موجات متوازية.","reference.personas#3#li2":"لكل شخصية مطالبة نظام خاصة بها، وقائمة أدوات مسموح بها محدودة، ومجموعة سياق مشتركة لما وجدته الشخصيات السابقة.","reference.personas#3#li3":"تنتج الشخصية الأخيرة ملخصًا، أو خطة، أو تقريرًا، حسب الوضع.","reference.personas#3#li4":"تعرض Ava النتيجة لك. توافق عليها، تعدلها، أو تعيد توجيهها.","reference.personas#4#p":"القائمة الكاملة أدناه مرجعية فقط — لا داعي لحفظ من يفعل ماذا. تجمع Ava الفريق المناسب لك.","reference.personas#6#c":"وضع العمل يستدعي الفريق الكامل للمهام المعقدة فقط. التعديلات البسيطة تشغل Ava مباشرة — بدون عبء التنسيق.","reference.config#title":"الإعدادات","reference.config#0#p":"تُظهر هذه الصفحة أين تحفظ Ava إعداداتها وملفاتها على جهازك. نادرًا ما تحتاج إلى لمس أي شيء بيديك — التطبيق يديرها لك. توجد هنا عندما تريد رؤية تلك الملفات أو نسخها احتياطيًا أو مشاركتها بنفسك.","reference.config#1#p":"تقرأ Ava الإعدادات (إعداداتها المحفوظة) من مستويين. الإعدادات العامة — التي تنطبق في كل مكان — موجودة في مجلد يُسمى ~/.ava/ (الرمز \"~\" اختصار لمجلدك الشخصي). أما إعدادات كل مشروع فتوجد في مجلد .ava/ داخل المشروع نفسه.","reference.config#2#h":"عامة — ~/.ava/","reference.config#3#li0":"settings.json — تفضيلات النموذج، وضع الإذن، الشخصية، اللغة.","reference.config#3#li1":"memory/ — ذكرياتك العامة (التفضيلات والقرارات التي تنطبق في كل مكان).","reference.config#3#li2":"tasks.json — قائمة المهام عبر المشاريع.","reference.config#3#li3":"journal/ — يوميات يومية، مرتبة حسب التاريخ.","reference.config#4#h":"مشروع — .ava/","reference.config#5#li0":"instructions.md — تعليمات خاصة بالمشروع تقوم Ava بتحميلها دائمًا. سياق دائم (\"نستخدم pnpm وليس npm\"، \"مفاتيح API مخزنة في 1Password\").","reference.config#5#li1":"context.md — ملاحظات المشروع الحرة الاختيارية.","reference.config#5#li2":"memory/ — ذكريات محدودة بهذا المشروع.","reference.config#5#li3":"datasets/config.json — إعدادات التقاط البيانات الاختيارية.","reference.config#6#c":"أضف .ava/ إلى ملف .gitignore (قائمة الملفات التي يُطلب من Git تجاهلها في المشروع المشترك) إذا كنت لا ترغب في مشاركة الذكريات مع فريقك. احتفظ بملف instructions.md في المستودع (مجلد المشروع المشترك) — هكذا تتعلم Ava اتفاقيات المشروع.","reference.shortcuts#title":"اختصارات لوحة المفاتيح","reference.shortcuts#0#p":"اختصارات لوحة المفاتيح هي تسريعات اختيارية — كل واحدة منها زر يمكنك النقر عليه أيضًا. اطّلع هنا فقط إذا أردت استخدام Ava بسرعة أكبر من لوحة المفاتيح.","reference.shortcuts#1#p":"اختصارات حسب البيئة (كل من الأماكن الثلاثة التي تعمل فيها Ava: إضافة VS Code، وتطبيق سطح المكتب، والطرفية). خصّصها في إعدادات كل بيئة. لا حاجة لحفظ القائمة أدناه.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"هل تحتاج إلى تقرير، أو بريد إلكتروني، أو مستند مكتوب؟ يمكن لـ Ava صياغته وتسليمك ملف Word أو Excel أو PDF حقيقي يمكنك فتحه وتعديله مثل أي ملف آخر.","features.office-suite#1#p":"تقارير، ورسائل بريد إلكتروني، ومستندات — تم صياغتها وتنسيقها وتصديرها بتنسيقات أصلية (.docx هو Word، .xlsx هو Excel، .pdf هو PDF).","features.office-suite#2#li0":"report_generate — ملف .docx منظم يستمد بياناته من المهام، وسجل اليوميات، والذاكرة، وحالة المشروع.","features.office-suite#2#li1":"email_draft — رسالة بريد إلكتروني مضبوطة النبرة إلى ملف .docx.","features.office-suite#2#li2":"document_manage — إنشاء، وقراءة، وتحرير، وتصدير عبر Word، وExcel، وPDF، وCSV، وMarkdown.","features.office-suite#3#p":"مفيد عندما تكتب Ava نيابة عنك — تقارير الحالة، وعروض البدء، وتحديثات العملاء. يصل ملف .docx إلى مشروعك حيث يمكنك تنقيحه.","features.dashboard-library#title":"مكتبة لوحة التحكم","features.dashboard-library#0#p":"ببساطة: رف واحد يحمل كل ما صنعته وتحدثت عنه أنت وAva، حتى لا يضيع شيء.","features.dashboard-library#1#p":"عرض قابل للتنقل لكل ما أنتجته Ava معك — صور، وفيديوهات، وصوت، ومستندات تم إنشاؤها — جنبًا إلى جنب مع محادثاتك، وذاكرتك، ومهامك. مكان واحد للعثور على شيء صنعته الأسبوع الماضي.","features.document-preview#title":"معاينة المستند","features.document-preview#0#p":"ببساطة: الاطلاع داخل مستند أينما كنت، دون الحاجة لفتح برنامج منفصل لقراءته.","features.document-preview#1#p":"انقر بزر الماوس الأيمن على ملف Word أو Excel أو PDF أو CSV أو HTML أو Markdown في مشروعك — اعرضه مباشرة دون مغادرة المحرر. مفيد لقراءة مواد مرجعية أنشأتها Ava أو ملفات وضعها أحد الزملاء.","features.daily-briefing#title":"موجز يومي","features.daily-briefing#0#p":"ببساطة: ملاحظة قصيرة صباحًا تقول \"إليك أين توقفت\"، لتتمكن من الاستئناف دون إعادة قراءة كل شيء.","features.daily-briefing#1#p":"ملخص الصباح: سجل أمس، والمهام المفتوحة، وحالة المشروع، وأي تذكيرات وضعتها Ava. اختياري — فعله من الإعدادات.","features.daily-briefing#2#p":"يستخدم الموجز الذاكرة لإظهار السياق ذي الصلة (\"آخر مرة عملت فيها على تدفق المصادقة، لاحظت أنك تريد إعادة النظر في استراتيجية رمز التحديث\"). ليس تغذية أخبار — بل استعادة تركيز سريعة.","reference.project-context#title":"سياق المشروع","reference.project-context#0#p":"يشرح هذا كيف تقرأ Ava عن مشروعك قبل أن تبدأ — الملفات التي تنظر إليها لفهم ما تعمل عليه. لا تحتاج إلى إعداد أي من هذا؛ فهي تفعل ذلك بمفردها. اقرأها إذا أردت معرفة أين تضع ملاحظة لتراها دائمًا.","reference.project-context#1#p":"تحمّل Ava عدة طبقات من السياق (معلومات خلفية تحتفظ بها في ذهنها) عند فتح مشروع. فهم الطبقات يساعدك على وضع المعلومات في المكان الصحيح.","reference.project-context#2#h":"يتم تحميله تلقائيًا","reference.project-context#3#li0":".ava/instructions.md — تُعامل كإرشادات دائمة وعالية الأهمية. موجودة دائمًا في السياق.","reference.project-context#3#li1":".ava/context.md — ملاحظات حرة. يتم تحميلها، بأولوية أقل.","reference.project-context#3#li2":"README.md — يتم مسحها في التشغيل الأول للحصول على ملخص للمشروع.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — الملفات الصغيرة التي تسجل إعداد المشروع؛ تُقرأ للكشف عن اللغة والإطار وأمر الاختبار.","reference.project-context#3#li4":".gitignore — قائمة الملفات التي يجب استبعادها من التحكم بالإصدار؛ تحترمها جميع أدوات الملفات (glob, grep, project_index).","reference.project-context#4#h":"يتم التحميل حسب الطلب","reference.project-context#5#p":"\"على حسب الطلب\" تعني أن Ava تجلب هذه فقط عندما تحتاج المهمة إليها فعليًا، وليس مسبقًا.","reference.project-context#6#li0":"فهرس المشروع — خريطة منظمة لملفاتك والقطع المسمّاة بداخلها (الدوال، الفئات — \"رموز\") وكيفية اتصالها (\"استيرادات\"). يُبنى عند الحاجة، أي فقط عندما تحتاجه Ava.","reference.project-context#6#li1":"سجل Git — سجل التغييرات السابقة؛ يُستدعى عند استدعاء git_status أو git_diff أو git_create_pr (Git هو الأداة التي تتعقب كل تغيير في المشروع؛ \"PR\" هي طلب سحب، وهي مجموعة مقترحة من التغييرات).","reference.project-context#6#li2":"الذاكرة — تطابق الإدخالات حسب المعنى (\"دلاليًا\") وتُحقن دورة واحدة تلو الأخرى، وليس دفعة واحدة.","reference.project-context#7#c":"ضع الاتفاقيات في instructions.md. ضع الملاحظات في context.md. اترك الذاكرة تلتقط الباقي بنفسها.","concepts.desktop-kill-switches#4#p":"تتجمد عند حدود الخطوة التالية. يمكن الاستمرار منها. استخدمها عندما تريد التدخل دون فقدان المسار.","concepts.desktop-kill-switches#5#h":"إيقاف — زر الهروب أو زر التوقف","concepts.desktop-kill-switches#6#p":"إلغاء نظيف. يُلخص الراوي ما تم إنجازه حتى الآن. لا يمكن الاستمرار منها. يتم حفظ سجل التدقيق.","concepts.desktop-kill-switches#7#h":"قتل الذعر — الهروب ثلاث مرات أو Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"هذا هو الإيقاف الأقوى المتاح. برنامج صغير منفصل يُسمى \"حارس المراقبة\" يجبر على الخروج فوراً عن الجزء من Ava الذي يتحكم في شاشتك. لا ينتظر رد الذكاء الاصطناعي، ولا يحتاج إلى أن تكون نافذة التطبيق تعمل، ولا يهتم بحالة الأمور — إنه يقتل العملية ببساطة. هذا الخيار مخصص للحالات التي يكون فيها الخطأ حقيقياً وجدياً.","concepts.desktop-kill-switches#9#p":"جميع الخيارات الثلاثة تعمل أيضاً من التطبيق المرافق. أي من السائقين يمكنه إنهاء المهمة.","reference.tools#title":"مرجع الأدوات","reference.tools#0#p":"هذا هو الدليل الكامل لكل أداة تمتلكها Ava — والأداة هنا تعني مجرد إجراء محدد يمكنها تنفيذه، مثل قراءة ملف أو تشغيل بحث. لا تحتاج لقراءة هذه الصفحة. Ava تختار الأداة المناسبة بنفسها في كل مرة. موجود هنا فقط عندما تود معرفة بالضبط ما تستطيع فعله.","reference.tools#1#p":"صندوق الأدوات المدمج بالكامل. كل أداة مسجلة هنا في وقت التشغيل الأساسي (المحرك الذي يعمل تحت السطح الثلاثي) ومتاحة لـ Ava عندما يسمح وضع التشغيل ووضع الصلاحيات بذلك. يمكنك التصفية حسب الفئة أو مستوى المخاطر.","reference.tools#2#p":"لا حاجة لحفظ أي من هذا — الجدول أدناه هو مجرد بطاقة مرجعية.","reference.tools#4#h":"مستويات المخاطر","reference.tools#5#li0":"آمن — يقرأ الأشياء دون تغيير أي شيء. file_read, glob (إيجاد ملفات بنمط الاسم), grep (البحث داخل الملفات للنص), git_status (Git هو النظام الذي يتتبع التغييرات في مشروعك).","reference.tools#5#li1":"كتابة — يغير الملفات، يحفظ نقطة تفتيش لعملك (أو \"commit\")، أو ينتج شيئاً جديداً. file_edit, git_commit, generate_image.","reference.tools#5#li2":"خطير — يشغل أوامر على جهازك (الـ \"shell\")، يتحكم في سطح المكتب، يخرج للإنترنت، أو يستفسر قواعد البيانات. bash, browser, desktop_*.","reference.tools#6#c":"متخصصو الشخصيات لديهم قوائم أدوات مسموحة خاصة بهم. المستكشف يمكنه القراءة لكن ليس الكتابة. المُصمم لديه وصول كامل. المُتحدي لا يملك أي أدوات على الإطلاق — مهمته هي التشكيك في الخطة.","reference.models#title":"النماذج","reference.models#0#p":"الـ \"model\" هو عقل الذكاء الاصطناعي الذي يقوم بالتفكير — Qwen, DeepSeek, Mistral وغيرها. هذه الصفحة تذكر كل نموذج يمكن لـ Ava استخدامه. باختصار: لا يجب عليك اختيار واحد. Ava تختار النموذج المناسب لكل خطوة بنفسها. اقرأ المزيد فقط إذا أردت فهم ذلك أو تجاوزها.","reference.models#1#p":"كل نموذج يمكن لـ Ava توجيه الطلب إليه، بالإضافة إلى استراتيجيات التنسيق الثلاث — القواعد التي تحدد أي نموذج يعالج كل جزء من المهمة. اختر وضع التوجيه واترك Ava ترسل، أو اختر نموذجاً واحداً وتجاوز التوجيه تماماً.","reference.models#2#h":"أوضاع التوجيه","reference.models#3#p":"ثلاث استراتيجيات منسقة. نفس خط أنابيب الشخصيات (الفريق الصغير من المساعدين المتخصصين الذين تشغله Ava خلف الكواليس) يعمل على الجميع؛ ما يتغير هو أسطول النماذج الأساسي. اختر وضعاً في مُحدد النماذج وستتعامل Ava مع الباقي. كل بطاقة أدناه تظهر المتخصصين المكونين الذين يرسل إليهم القائد.","reference.models#4#p":"لا تحتاج لحفظ البطاقات أدناه — موجودة هنا لترى ما يتكون منه كل استراتيجية.","reference.models#6#c":"Aurora مصمم ليكون Mistral فقط عمداً. إذا لم يكن نموذج Mistral متاحاً، يعيد الموجه خطأ بدلاً من التوجيه عبر الأنظمة — هذا ضمان طبقة الاتحاد الأوروبي. اختر Maestro أو Supernova لتدهور سلس.","reference.models#7#c":"جميع الأوضاع الثلاثة متاحة عالمياً — على أرصدة المنصة وعلى مفاتيحك الخاصة. BYOK يضيف خيار تجاوز التنسيق وتشغيل نموذج واحد مباشرة.","reference.models#8#h":"نماذج تديرها المنصة","reference.models#9#p":"متاحة في كل خطة، بما في ذلك الطبقة المجانية. الرموز (وحدات قياس النص التي يقاس بها الذكاء الاصطناعي — تقريباً ثلاثة أرباع كلمة لكل رمز) تُحتسب ضمن السماح الخاص بخطتك. المفاتيح (كلمات المرور الخاصة التي تفتح كل نموذج مدفوع) يتم تدويرها ومراقبتها بواسطة المنصة — لا شيء عليك تكوينه.","features.unified-panel#title":"لوحة موحدة","features.unified-panel#0#p":"بكلمات بسيطة: كل ما تفعله Ava يعيش في نافذة واحدة، لذا لن تضطر أبدًا للبحث بين التبويبات لإيجاده.","features.unified-panel#1#p":"لوحة واحدة للدردشة، لوحة المعلومات، الذاكرة، المهام، والسجل. لا تبديل سياق بين النوافذ. الشريط الجانبي يختار ما تنظر إليه؛ المنطقة الرئيسية تتغير لتناسب ذلك.","features.unified-panel#2#p":"حالة المحادثة تبقى محفوظة عند التنقل بعيدًا — افتح الذاكرة، راجع مهمة، ثم عد. الدردشة لا تزال هناك، ولا تزال جارية إذا كانت Ava تعمل.","features.unified-panel#3#c":"اللوحة الموحدة هي مفهوم امتداد وIDE. السطح الويب يستخدم تبويبات المتصفح.","features.knowledge-packs#title":"حزم المعرفة","features.knowledge-packs#0#p":"بكلمات بسيطة: أعطِ Ava مجلدًا من مستنداتك الخاصة، ويمكنها القراءة منها للإجابة على أسئلتك. \"حزمة المعرفة\" هي مجرد حزمة ملفات تلك — مواد المرجع المسموح لها بالاستناد إليها.","features.knowledge-packs#1#p":"اسحب دليلًا لمواد مرجعية (مواصفات، RFCs، محاضر اجتماعات، وثائق API) إلى حزمة معرفة. يمكن لـ Ava سحب القطع ذات الصلة إلى السياق عندما تلامس المحادثة الموضوع.","features.knowledge-packs#2#p":"الحزم تُفهرس محليًا. الاسترجاع دلالي — تجد Ava المستند الصحيح بالمعنى وليس باسم الملف. (\"دلالي\" يعني أنها تطابق بناءً على محتوى المستند، لذا لا تحتاج لتذكر الكلمات الدقيقة أو اسم الملف.) يمكن مشاركة الحزم مع فريق أو الاحتفاظ بها خاصة.","features.workflows#title":"سير العمل","features.workflows#0#p":"ببساطة: علّم Ava روتينًا تقوم به مرارًا وتكرارًا، أعطِه اسمًا، ويمكنها تشغيله بالكامل عند الطلب. \"سير العمل\" هو ببساطة ذلك الروتين المحفوظ — مجموعة خطوات تتكرر Ava من أجلك.","features.workflows#1#p":"احفظ تسلسل خطوات تجد نفسك تكررها — مراجعة PR → تشغيل الاختبارات → كتابة ملاحظات الإصدار → صياغة البريد الإلكتروني. سير العمل هو خطة قابلة لإعادة الاستخدام يمكن لـ Ava إعادة تشغيلها بإدخالات مختلفة.","features.workflows#2#p":"يتم تخزين سير العمل لكل مشروع في مجلد باسم .ava/workflows/ داخل مشروعك. شاركها مع فريقك عن طريق حفظ المجلد في المشروع المشترك (بحيث يحصل زملاؤك عليه أيضًا).","features.events#title":"الأحداث والإشعارات","features.events#0#p":"ببساطة: بينما تعمل Ava تحصل على قائمة خطوة بخطوة مرتبة لما تفعله، ونبهة عندما ينتهي عمل طويل حتى تتمكن من الابتعاد.","features.events#1#p":"أثناء تشغيل Ava ترى تحديثات منظمة، وليست كتلة من النصوص. كل استدعاء أداة، وكل تسليم لشخصية، وكل دلتا متدفق هو حدث منفصل في الواجهة — قابل للتوسيع للتفاصيل، قابل للطي للمراجعة العامة.","features.events#2#p":"التشغيل في الخلفية يصدر إشعارات على مستوى النظام عند اكتماله. يمكنك الابتعاد عن عملية بناء طويلة وستخبرك Ava عندما تنتهي.","features.personality#title":"مصمم الشخصية","features.personality#0#p":"ببساطة: اضبط كيف تتحدث Ava معك — محادثة أو موجزة، رسمية أو غير رسمية، المزيد من النكات أو أقل — لتبدو كما تحب.","features.personality#1#p":"شكل طريقة تحدث Ava معك. النبرة، الطاقة، الإفراط في الكلام (كم تقول)، الرسمية، الفكاهة. أشرطة تمرير وقوالب جاهزة — مهندس مختصر، مرشد دافئ، زميل جاف، أو مزيج خاص بك.","features.personality#2#p":"الشخصية تؤثر على الصياغة، وليس الكفاءة. لا تزال تشغل نفس الأدوات وتتبع نفس قواعد الأذونات. اسمها مقفل على Ava — هذا أمر غير قابل للتفاوض.","features.release-notes#title":"ملاحظات الإصدار","features.release-notes#0#p":"ببساطة: قائمة مستمرة لما هو جديد وما تم إصلاحه في كل تحديث، حتى تتمكن من رؤية ما تغير.","features.release-notes#1#p":"سجل التغييرات داخل التطبيق (سجل التغييرات هو تاريخ التغييرات). كل إصدار تم شحنه مع أبرز النقاط وإصلاحات الأخطاء والتغييرات الكبيرة (تغييرات قد تتطلب منك تعديل كيفية استخدام شيء ما). يحافظ السطح الويب على النسخة العامة في ava-supernova.com/releases.","troubleshooting.logs#4#c":"قد تحتوي السجلات على مقتطفات من ملفات المشروع التي قرأتها Ava خلال جلسة. راجعها قبل مشاركتها.","troubleshooting.support-request#title":"تقديم طلب دعم","troubleshooting.support-request#0#p":"ببساطة: إذا كان هناك خطأ ولم تنجح الإصلاحات المذكورة أعلاه، أرسل لنا رسالة بخصوصه. أسهل طريقة هي أن تطلب من Ava القيام بذلك نيابةً عنك.","troubleshooting.support-request#1#p":"إذا لم تكن المشكلة مغطاة بالأخطاء الشائعة، قدم تذكرة دعم (أرسل طلب مساعدة لفريق الدعم). يمكنك فعل ذلك داخل Ava (بدون نموذج لملئه) أو عبر الويب.","troubleshooting.support-request#2#h":"من داخل Ava","troubleshooting.support-request#3#p":"اطلب منها تقديمها. \\\"Ava، هل يمكنك تقديم تذكرة دعم حول هذا؟\\\" تستدعي support_request، وتلحق سياق الجلسة ذي الصلة (مع إخفاء بيانات الاعتماد)، ثم ترسلها. أسرع طريق.","troubleshooting.support-request#4#h":"من الويب","troubleshooting.support-request#5#p":"زر ava-supernova.com/support. اختر فئة (خطأ برمجي، ميزة، حساب، أمان، عام) ووصف ما حدث. رد خلال يوم عمل واحد.","troubleshooting.support-request#6#h":"ما يجب تضمينه","troubleshooting.support-request#7#li0":"ما كنت تحاول فعله.","troubleshooting.support-request#7#li1":"ما حدث فعليًا.","troubleshooting.support-request#7#li2":"أي سطح (إضافة، IDE, CLI، مرافق) وأي إصدار.","troubleshooting.support-request#7#li3":"أي رسالة خطأ أو مقتطف سجل. قم بإخفاء بيانات الاعتماد أولاً.","troubleshooting.security-disclosure#title":"الإبلاغ عن مشكلات الأمان","troubleshooting.security-disclosure#0#p":"ببساطة: إذا لاحظت طريقة يمكن اختراق Ava أو إساءة استخدامها فيها (ثغرة أمنية — ضعف في الأمان)، يرجى إخبارنا خصوصيًا أولاً حتى نتمكن من إصلاحها قبل أن يستغلها أحد. هذه الصفحة توضح كيفية ذلك.","troubleshooting.security-disclosure#1#p":"وجدت ثغرة؟ شكرًا لك. نحن نأخذ كل تقرير على محمل الجد ونعمل معك على الحل قبل أي إفصاح عام (قبل الإعلان عن المشكلة علنًا).","troubleshooting.security-disclosure#2#h":"كيفية الإبلاغ","troubleshooting.security-disclosure#3#li0":"أرسل بريدًا إلى security@ava-supernova.com مع وصف، خطوات إعادة الإنتاج، ونافذة الإفصاح المفضلة لديك.","troubleshooting.security-disclosure#3#li1":"أو قدم تذكرة دعم بفئة \\\"أمان\\\" — نفس قائمة الفرز.","troubleshooting.security-disclosure#3#li2":"نؤكد الاستلام خلال 24 ساعة.","troubleshooting.security-disclosure#4#h":"التزاماتنا","troubleshooting.security-disclosure#5#li0":"الإفصاح المنسق — نتفق معك على جدول زمني قبل أي شيء يصبح عامًا. الافتراضي هو 90 يومًا.","troubleshooting.security-disclosure#5#li1":"الاعتراف — يُذكر اسمك في ملاحظات الحل إلا إذا فضلت عدم الكشف عن هويتك.","troubleshooting.security-disclosure#5#li2":"لا انتقام قانوني — البحث بحسن نية مرحب به. لن نرسل محامين وراءك.","troubleshooting.security-disclosure#6#c":"صفحة الأمان في ava-supernova.com/security تحتوي على الوضع الأمني الكامل — ضمانات البنية، أداة الإخفاء، بوابات الصلاحيات.","troubleshooting.common-errors#title":"أخطاء شائعة","troubleshooting.common-errors#0#p":"معظم الأخطاء لها سبب قصير ومحدد. إليك الشائع منها وكيفية إصلاحها. لا تقلق إذا بدت العبارات تقنية — كل ما يلي يوضح ما تراه بالضبط وما يجب فعله.","troubleshooting.common-errors#1#h":"النموذج لا يستجيب","troubleshooting.common-errors#2#p":"ما تراه: تتوقف Ava عن الرد ولا تجيب.","troubleshooting.common-errors#3#p":"تحقق من مؤشر الحالة في رأس المحادثة. إذا قال \"connecting\"، فإن مقدم الخدمة (خدمة الذكاء الاصطناعي التي تتحدث إليها Ava) متصل لكن بطيء — انتظر ثلاثين ثانية. إذا قال \"unavailable\"، فقد انتقلت Ava تلقائيًا إلى النموذج التالي في السلسلة (بدلت تلقائيًا إلى نموذج احتياطي). إذا لم يظهر شيء على الإطلاق، تحقق من مفتاح API في الإعدادات واختبر الاتصال. (مفتاح API هو كلمة المرور الخاصة التي تسمح لـ Ava باستخدام خدمة ذكاء اصطناعي مدفوعة.)","troubleshooting.common-errors#4#h":"فشل استدعاء الأداة","troubleshooting.common-errors#5#p":"ما تراه: تظهر إحدى خطوات Ava (\"استدعاء أداة\" — مثل قراءة ملف أو تشغيل أمر) خطأ أحمر بدلاً من الانتهاء بنجاح.","troubleshooting.common-errors#6#p":"انقر على استدعاء الأداة الفاشل لرؤية الخطأ. الأسباب الشائعة: حاولت لمس ملف خارج مجلد مشروعك، وهو محظور عمداً لأمانك (هذا الحارس يُسمى حماية \"path traversal\" — تمنعها من التجول خارج المجلد الذي تعمل فيه); أمر يحتاج للعمل في مجلد مختلف؛ أو ملف تم نقله منذ أن نظرت إليه Ava آخر مرة. أخبرها بما حدث — ستعيد المحاولة مع التصحيحات.","troubleshooting.common-errors#7#h":"الذاكرة لا تسترجع","troubleshooting.common-errors#8#p":"ما تراه: Ava لا تجد شيئاً أنت متأكد أنها يجب أن تتذكره.","troubleshooting.common-errors#9#p":"الذاكرة تعمل بالمعنى وليس بالكلمات الدقيقة (هذا ما تعنيه \"semantic\"). لذا \"ماذا قررت بخصوص المصادقة؟\" أفضل من \"ابحث عن قرار المصادقة الخاص بي\". إذا كانت الذاكرة موجودة بالتأكيد لكنها لا تظهر، افتح متصفح الذاكرة وابحث — إذا لم تكن هناك، فهي لم تُحفظ من الأساس.","troubleshooting.common-errors#10#h":"حلقات تسجيل الدخول","troubleshooting.common-errors#11#p":"ما تراه: تسجل الدخول، لكن Ava تطلب منك تسجيل الدخول مرة أخرى — حلقة لا تسمح لك بالمرور أبدًا.","troubleshooting.common-errors#12#p":"الحل هو مسح تفاصيل تسجيل الدخول المحفوظة والبدء من جديد: في الامتداد شغّل \"Ava: Sign Out\" من لوحة الأوامر، في الـ IDE استخدم الإعدادات → الحساب → تسجيل الخروج، في الـ CLI احذف الملف الموجود في ~/.ava/auth.json (ملف تسجيل دخول صغير في مجلد اسمه .ava في مجلد منزلك). ثم سجّل الدخول مرة أخرى.","troubleshooting.common-errors#13#h":"نفاد رصيد الرموز","troubleshooting.common-errors#14#p":"ما تراه: رسالة تفيد بأنك استنفدت الاستخدام المجاني لهذا الشهر. (\"Tokens\" هي طريقة قياس استخدام الذكاء الاصطناعي — \"exhausted\" تعني ببساطة أنك استخدمت السماح المجاني لهذا الشهر.)","troubleshooting.common-errors#15#p":"ميزانية الطبقة المجانية الشهرية تعود للوضع الطبيعي في اليوم الأول من كل شهر. حتى ذلك الحين، انتقل إلى مزود BYOK (استخدم مفتاح API الخاص بك) لمواصلة العمل. حسابك يبقى نشطًا — فقط الطلبات المدارة مجانًا عبر المنصة مؤقتة.","troubleshooting.logs#title":"مكان وجود السجلات","troubleshooting.logs#0#p":"\"السجل\" هو مجرد يوميات يحافظ عليها جهازك لما حدث — مفيد عندما يحدث عطل وتحتاج أنت (أو الدعم) لرؤية التفاصيل.","troubleshooting.logs#1#p":"عندما تحتاج الصورة الخام — أي أداة تم استدعاؤها، وما المعلومات التي حصلت عليها، وما الذي عادته خدمة الذكاء الاصطناعي — تكون السجلات ملفات نصية بسيطة في مجلد على جهازك في ~/.ava/logs/ (مجلد اسمه .ava في مجلد منزلك، يحتوي على مجلد logs بداخله).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — نسخ جلسات فردية تتضمن استدعاءات الأدوات، والاستجابات المتدفقة، والأخطاء.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — سجل مضيف امتداد VS Code. فشل التفعيل، أخطاء اللوحة.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — سجل الـ IDE المكتبي. رسائل عملية Sidecar، انهيارات Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — سجل REPL للـ CLI.","troubleshooting.logs#3#p":"في الامتداد، \"Ava: Show Logs\" في لوحة الأوامر يفتح السجل ذي الصلة في تبويب محرر. في الـ IDE، الإعدادات → التشخيص يحتوي على زر \"عرض السجلات\". يمكن للـ CLI تتبع سجله الخاص مع ava logs --follow.","start.what#title":"ما هي Ava؟","start.what#0#p":"Ava هي مساعد ذكي يقوم بالأعمال فعليًا وليس مجرد كلام. ستقوم ببناء تطبيق لك، كتابة مستند، تعليمك شيئًا من الصفر، تصميم شعار، أو الاعتناء بالمهام الإدارية التي تؤجلها دائمًا. وهي تتذكر تفاصيلك: ما تعمل عليه حاليًا، كيف تفضل الأمور، وما طلبته الأسبوع الماضي.","start.what#1#p":"هناك Ava واحدة، وتعمل أينما تعمل — في محرر الأكواد الخاص بك، كتطبيق سطح مكتب، على هاتفك، أو في الطرفية. نفس الذاكرة، نفس الشخصية، في كل مكان.","start.what#2#h":"ما الذي يجعلها مختلفة","start.what#3#li0":"أنت المالك افتراضيًا. عملك يبقى على جهازك الخاص. لا تتبع، ولا قياسات عن بُعد — أبدًا.","start.what#3#li1":"شفافة للجميع. كل سطر في كود Ava متاح للعامة. لا حاجة للثقة العمياء.","start.what#3#li2":"ابدأ مجانًا. 300 رصيد شهريًا، بدون بطاقة، بدون شروط خفية — أو استخدم مفاتيح الذكاء الاصطناعي الخاصة بك ودفعنا صفرًا.","start.what#3#li3":"التعليم مجاني إلى الأبد. التعلم لا ينبغي أن يحمل علامة سعر.","start.what#4#p":"لم تكتب أكوادًا من قبل؟ الصفحة القادمة مخصصة لك تمامًا. هل لديك خبرة تقنية؟ انتقل للأمام — ستواكبك بسهولة.","start.what#deeper#0#h":"أين تعيش Ava","start.what#deeper#1#li0":"إضافة VS Code — Ava بجانب محررك: لوحة دردشة، لوحة تحكم، وتغييرات تظهر مباشرة قبل حدوثها.","start.what#deeper#1#li1":"IDE سطح المكتب — تطبيق مستقل بكل شيء في نافذة واحدة. يضيف تحكمًا بسطح المكتب (فتح التطبيقات، النقر، الكتابة نيابةً عنك).","start.what#deeper#1#li2":"رفيق — تطبيق جوال عندما تكون بعيدًا عن مكتبك: مهام، يوميات، ذاكرة، محادثات سريعة.","start.what#deeper#1#li3":"CLI — Ava في طرفيتك، لأولئك الذين يعيشون فيها.","start.what#deeper#2#h":"كيف تعمل، باختصار","start.what#deeper#3#p":"Ava تبديل الأوضاع لتناسب المهمة، تشغيل فريق متخصص خلف الكواليس للمهام المعقدة، واختيار أفضل نموذج ذكاء اصطناعي تلقائيًا. أنت لا تدير أي شيء. قسم «المفاهيم الأساسية» يحتوي على الشرح الكامل متى شئت.","start.first-five#title":"أول شيء تفعله مع Ava","start.first-five#0#p":"أسرع طريقة للحصول على Ava هي أن تطلب منها شيئًا حقيقيًا وتشاهد فعلها. لا إعدادات لقراءتها، لا شيء لتتعلمه أولًا — فقط أخبرها بما تريد، بكلمات بسيطة.","start.first-five#1#h":"جرب هذا الآن","start.first-five#2#li0":"افتح الدردشة.","start.first-five#2#li1":"اكتب شيئًا تريده حقًا. جرب \"اشرح ماذا يفعل هذا المشروع\"، أو \"أضف زرًا لمسح النموذج\".","start.first-five#2#li2":"تعرض لك Ava ما تنوي فعله — وتنتظر.","start.first-five#2#li3":"راضٍ عنها؟ قل نعم. شاهد فعلها.","start.first-five#3#p":"هذا هو الإيقاع كله: تسأل، تعرض لك الخطة، توافق، تقوم بها. لا تغير أي شيء دون إظهاره لك أولًا — حتى لا تكسر أي شيء بالتجربة.","start.first-five#4#h":"بعض الأشياء الجديرة بأن تطلبها","start.first-five#5#li0":"سؤال — \"لماذا صفحتي فارغة؟\"، \"ما وظيفة هذا الملف؟\"","start.first-five#5#li1":"شيء مبنٍ — \"اصنع لي صفحة قائمة مهام بسيطة\".","start.first-five#5#li2":"لتعلم شيء جديد — \"علّمني بايثون من الصفر\". (مجاني دائمًا.)","start.first-five#5#li3":"مستند — \"اكتب لي مقترح مشروع في صفحة واحدة\". ستسلم لك ملف Word أو PDF.","start.first-five#6#c":"غير متأكد مما تكتب؟ تحدث إليها كصديقة خبيرة. الكلمات البسيطة هي الأنسب تمامًا — لا تحتاج أبدًا للمصطلحات التقنية للبدء.","start.first-five#deeper#0#p":"هذه الحلقة البسيطة تقوم بالكثير خلف الكواليس. لا تحتاج لأي مما سبق لاستخدام Ava — لكن إليك ما يحدث فعليًا إذا كنت فضوليًا.","start.first-five#deeper#1#h":"الأدوات والموافقة","start.first-five#deeper#2#p":"عندما تقرأ Ava ملفًا، أو تشغل أمرًا، أو تعدّل كودًا، فإن كل ذلك يُعدّ \"طلب أداة\". تسأل قبل أي شيء يمس ملفاتك أو نظامك — وتكرار سؤالها يعتمد على وضع الإذن الخاص بك (اسأل في كل مرة، اسأل فقط للأشياء الخطرة، أو اذهب مباشرة).","start.first-five#deeper#3#h":"الأوضاع — حالات تفكيرها","start.first-five#deeper#4#p":"تعمل Ava بأوضاع مختلفة: عقلية زائد مجموعة أدوات مناسبة للعمل. يمكنك التبديل في أي وقت من القائمة، أو كتابة بادئة في بداية رسالتك. هناك سبعة أوضاع.","start.first-five#deeper#6#h":"المتخصصون والتوجيه","start.first-five#deeper#7#p":"في المهام الأصعب، تشغل Ava فريقًا صغيرًا من المساعدين المتخصصين خلف الكواليس (مخطط، مدقق، باني) وتوجّه كل خطوة إلى النموذج الأفضل فيه. أنت لا تدير أيًا من هذا — إنها تنسق الأمر نيابةً عنك.","start.local-vs-cloud#title":"محلي مقابل سحابي، في فقرة واحدة","start.local-vs-cloud#0#p":"كل ما تفعله Ava محلي إلا إذا اخترت صراحةً الانضمام للسحابة. الذاكرة، المهام، اليوميات، الشخصية، الإعدادات — كلها مخزنة على جهازك في ~/.ava/ و .ava/ (لكل مشروع). تتحدث مع مزودي النماذج عبر HTTPS لتشغيل طلبك، ثم تعود إلى المنزل. لا تتصل بالخارج. لا تجمع بيانات تتبع. لا تدرب على كودك.","start.local-vs-cloud#1#p":"إذا قمت بتسجيل الدخول، تحصل على 300 رصيد مجاني شهريًا على نماذج تُدار عبر المنصة (Qwen, MiniMax) ومزامنة سحابية اختيارية للذاكرة والإعدادات عبر الأجهزة. المزامنة لكل ميزة، ويمكن إلغاؤها في أي وقت. احمل مفتاح API الخاص بك وستعمل Ava بالكامل بدون حساب.","start.local-vs-cloud#2#c":"القاعدة: المحلي مقدس. السحابي إضافي.","start.first-model#title":"هل أحتاج لاختيار ذكاء اصطناعي؟","start.first-model#0#p":"هنا خبر مريح: أنت لا تختار الذكاء الاصطناعي. Ava تختار المناسب منها لكل خطوة تلقائيًا، لتحصل على نتائج جيدة دون الحاجة للتفكير في ذلك.","start.first-model#1#p":"الشيء الوحيد الذي يمكنك اختياره هو أسلوب التوجيه — والافتراضي يناسب الجميع تقريبًا. لا تحتاج للآخرين إلا لسبب محدد.","start.first-model#2#h":"الأساليب الثلاثة","start.first-model#3#li0":"Maestro — الافتراضي. ثابت، موثوق، متوقع. غير متأكد؟ هذا هو الخيار.","start.first-model#3#li1":"Supernova — للمهام الثقيلة متعددة الخطوات، حيث يستحق الأمر وضع متخصص مختلف على كل جزء من العمل.","start.first-model#3#li2":"Aurora — عندما يجب أن تبقى بياناتك داخل الاتحاد الأوروبي (القطاع العام، الرعاية الصحية، خصوصية صارمة). تعمل بالكامل على ذكاء اصطناعي أوروبي مفتوح الوزن.","start.first-model#4#p":"غيّر في أي وقت من قائمة اختيار النموذج في أعلى الدردشة. لا شيء محجوز.","start.first-model#5#c":"تريد قيادة نموذج معين بنفسك؟ يمكنك — افتح \"أظهر لي التفاصيل\".","models.routing#deeper#1#h":"مقارنة جانبية","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"منسق","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B نشط، 1M سياق)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B نشط، 262K سياق)","models.routing#deeper#2#td1.0":"منشئ","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (يعيد استخدام المنسق)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B كثيفة، 256K سياق)","models.routing#deeper#2#td2.0":"متخصصو الفئة المتوسطة","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (مراجع كود، مدقق حقائق، استطلاع، ماسح، مدقق أمني، إلخ)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (معماري، مدقق، منظم تسلسل، معلم، مرسل تقارير، إلخ)","models.routing#deeper#2#td3.0":"الفئة الخفيفة / بوابة النية","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (كاشف، مدقق، منظم تسلسل، متحدٍ، مُدمج)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"متخصصو الفئة الثقيلة","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (باحث، متحدٍ، باحث عن CVE، مبتكر، مدقق حقائق)","start.first-model#deeper#0#h":"ما يتضمنه كل نمط فعليًا","start.first-model#deeper#1#p":"Maestro — موزر واحد (Qwen 3.6 Plus) يتولى كل خطوة. مُعدّ للإنتاج، مجرّب، وتكلفة متوقعة.","start.first-model#deeper#2#p":"Supernova — منسق حدودي (DeepSeek V4 Pro، 1.6T معلمة / 49B نشطة، سياق 1M) يسند كل مهمة فرعية إلى متخصص: V4 Flash للبناء عالي الحجم، Qwen 3.6 Plus كاحتياط، Qwen Omni للرؤية.","start.first-model#deeper#3#p":"Aurora — Mistral فقط، بثلاث مستويات: Mistral Large 3 (منسق + متخصصون أثقل)، Mistral Medium 3.5 (128B كثيفة، سياق 256K، رؤية أصلية، أوزان مفتوحة معدلة MIT، 77.6% SWE-Bench Verified) للمُبنِي + المستوى المتوسط + الرؤية + النصوص الطويلة، و Mistral Small 4 عند بوابة النية. أوزان مفتوحة من البداية للنهاية، لا تغادر البنية التحتية للاتحاد الأوروبي أبدًا.","start.first-model#deeper#4#h":"استخدم نموذجك الخاص (BYOK)","start.first-model#deeper#5#p":"تفضل استخدام حساب الذكاء الاصطناعي الخاص بك؟ الصق مفتاح المزود في الإعدادات وستحصل على كليهما — أنماط التوجيه الثلاثة، بالإضافة إلى خيار اختيار نموذج واحد وتخطي التوجيه تمامًا. مفيد لوجود تفضيل قوي، أو ميزانية صارمة، أو اختبار نموذج محدد. قائمة المزود الكاملة موجودة في قسم المرجع.","start.glossary#title":"قاموس بلغة بسيطة","start.glossary#0#p":"كل كلمة قد تواجهها حول Ava، مُشرحة دون افتراض أي معرفة مسبقة. لا تحتاج إلى حفظ أي مما يلي — عد إليها كلما عثرت على مصطلح يُربكك.","start.glossary#1#th0":"الكلمة","start.glossary#1#th1":"ماذا تعني فعليًا","start.glossary#1#td0.0":"وكيل","start.glossary#1#td0.1":"ذكاء اصطناعي يمكنه تنفيذ إجراءات نيابة عنك — قراءة ملف، تشغيل أمر، البحث في الويب — وليس مجرد دردشة. Ava هي وكيل: فهي تنفذ أشياء، بإذن منك.","start.glossary#1#td1.0":"نموذج","start.glossary#1#td1.1":"العقل الفعلي للذكاء الاصطناعي الذي يفكر (Qwen, DeepSeek, Mistral، وآخرون). نماذج مختلفة لها نقاط قوة مختلفة. عادةً لا تختار أنت واحدة — Ava تفعل ذلك.","start.glossary#1#td2.0":"وضع","start.glossary#1#td2.1":"الذهنية التي تكون فيها Ava. مثل زميل يغير قبعة: مبني، كاتب، معلم، مخطط، صديق. أنت تختار الوضع؛ فهو يغير طريقة تصرفها. هناك سبعة.","start.glossary#1#td3.0":"شخصية / متخصص","start.glossary#1#td3.1":"أدوار مساعدة تشغلها Ava خلف الكواليس للمهام الأصعب — مستكشف، مخطط، مراجع حقائق. تخيل فريق خبراء صغير. لا تتحدث إليهم مباشرة أبدًا؛ Ava تنسق بينهم.","start.glossary#1#td4.0":"توجيه","start.glossary#1#td4.1":"قرار Ava بشأن النموذج المستخدم لكل خطوة لتحصّل إجابات جيدة دون دفع مبالغ زائدة. يحدث تلقائيًا — \"وضع التوجيه\" يختار الاستراتيجية العامة فقط.","start.glossary#1#td5.0":"أداة","start.glossary#1#td5.1":"إجراء محدد يمكن لـ Ava تنفيذه — قراءة ملف، بحث، إرسال بريد إلكتروني. \"مكالمة أداة\" هي استخدامها لأحد هذه. تطلب الإذن قبل أي شيء خطير.","start.glossary#1#td6.0":"رمز","start.glossary#1#td6.1":"كيف يقيس الذكاء الاصطناعي النص — تقريبًا ¾ من الكلمة. تُسعّر النماذج حسب المليون رمز. غالبًا شيء يمكنك تجاهله.","start.glossary#1#td7.0":"رصيد","models.routing#deeper#2#td5.0":"دردشة","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"إدارة توليد الصور","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"الرؤية","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (تم تدريبه من الصفر)","models.routing#deeper#2#td8.0":"كتابة النصوص الطويلة","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"مكان تخزين البيانات","models.routing#deeper#2#td9.1":"مختلط (ألي بابا كلاود)","models.routing#deeper#2#td9.2":"مختلط (DeepSeek + ألي بابا كلاود)","models.routing#deeper#2#td9.3":"الاتحاد الأوروبي فقط · أوزان مفتوحة","models.routing#deeper#2#td10.0":"الحالة","models.routing#deeper#2#td10.1":"متوفر حالياً · جميع الخطط","models.routing#deeper#2#td10.2":"قريبًا","models.routing#deeper#2#td10.3":"قريبًا","models.routing#deeper#2#td11.0":"الأفضل لـ","credits.overview#8#li4":"التنسيق — 10 رصيد. بدء خط عمل كامل للشخصيات (المنسق + مهام متعددة الشخصيات).","credits.overview#8#li5":"توليد الصور — 12 رصيد. Hailuo image-01 عبر Creative Studio.","credits.overview#8#li6":"توليد الفيديو — 150 رصيد. مقطع فيديو Hailuo 02 Pro بدقة 1080p لمدة 6 ثوانٍ.","credits.overview#8#li7":"توليد الصوت — 10 رصيد. تركيب صوتي Speech 2.8 بجودة عالية.","credits.overview#8#li8":"توليد الموسيقى — 50 رصيد. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"إزالة الخلفية — 2 رصيد.","credits.overview#9#h":"مضاعفات لكل نموذج","credits.overview#10#p":"هذا الجزء للمهتمين — لا تحتاجه لاستخدام Ava. المضاعف ببساطة يضبط تكلفة الرصيد صعودًا أو هبوطًا حسب تكلفة النموذج الذي يقف خلف كل إجراء، لذا النماذج الأثقل تكلف قليلًا أكثر. (\\\"صافي الربح\\\" هو الجزء الذي يحتفظ به المشروع بعد دفع فواتيره الخاصة — نهدف لأن يكون منخفضًا حتى تعود القيمة إليك.)","credits.overview#11#p":"النماذج الأثقل تضرب تكلفة الإجراء لمتابعة الرصيد للنفقات الفعلية بدلًا من شريحة ثابتة. مُعَدّ لـ ~55% صافي ربح.","credits.overview#12#li0":"0.6× — Mistral Small 4 (مقعد الخبير في Aurora). أقل من 1× لأن Mistral Small 4 أرخص من مرجع Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. السعر الأساسي.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (منسق Aurora). يعادل تقريبًا مرجع Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (منسق Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (منسق Supernova + خبراء أثقال). أُعيد معايرته من 5.0× لاستعادة توازن الهامش عند معدل V4 Pro المنشور.","credits.overview#13#c":"نماذج Anthropic (Claude Opus / Sonnet / Haiku) تتجاوز الفوترة بالريسات تمامًا — هي BYOK فقط وتدفع Anthropic مباشرة. نفس الشيء لأي مزود آخر BYOK عند استخدامه بمفتاحك الخاص.","credits.overview#14#h":"BYOK والريسات","credits.overview#15#p":"BYOK (\\\"جلب مفتاحك الخاص\\\" — توفر حسابك الخاص مع مزود ذكاء اصطناعي ومفتاحًا، وهو كلمة مرور خاصة تسمح للبرامج باستخدام ذلك الحساب المدفوع) مخصص للأشخاص الذين يدفعون لمزود ذكاء اصطناعي مباشرة بالفعل. إذا لم تكن منهم، يمكنك تجاهل هذا القسم بالكامل.","credits.overview#16#p":"طلبات جلب المفتاح الخاص تتجاوز بنية المنصة تمامًا — المكالمة تذهب مباشرة من Ava إلى المزود، تدفع المزود، لا تُستهلك أي ريسات. الاستثناء الوحيد هو عندما يولد جلسة BYOK شخصية من فئة مُدارة لمهمة فرعية؛ ينطبق خصم الريسات أيضًا لأن سطح تنسيق Ava يُستخدم.","credits.overview#17#h":"أين تتحقق من رصيدك","credits.overview#18#li0":"الامتداد — الإعدادات → الحساب، أو علامة الرصيد في رأس الدردشة.","credits.overview#18#li1":"IDE — لوحة تحكم الحساب تظهر الرصيد الحالي ومعدل الاستهلاك.","credits.overview#18#li2":"الويب — ava-supernova.com/dashboard يظهر الرصيد والسجل وتاريخ التجديد.","credits.overview#19#c":"محلي أولاً: تعمل Ava بدون حساب على بطاقة النموذج المخصص (Ollama, LM Studio, vLLM، أو أي نقطة نهاية متوافقة مع OpenAI). لا ريسات، لا رموز منصة — نموذجك، جهازك، فاتورتك صفر.","concepts.modes#title":"الأنماط — حالات تفكير Ava","reference.cli#5#li3":"--project <path> — تحديد جذر المشروع صراحةً.","reference.desktop-budget#title":"حدود ميزانية سطح المكتب","reference.desktop-budget#0#p":"عندما تتحكم أفا في سطح المكتب نيابةً عنك — بالنقر والكتابة وفتح التطبيقات — يُطلق على كل تشغيل اسم \"مسار\". توضح هذه الصفحة حدود الأمان التي تمنع أي تشغيل واحد من الاستمرار لفترة طويلة جدًا أو التكلفة العالية جدًا. الخلاصة: إنها تتوقف دائمًا وتتواصل معك قبل تجاوز الحدود. الأرقام هنا إذا كنت تريد التفاصيل.","reference.desktop-budget#1#p":"يعمل كل مسار تحت ثلاثة حدود متزامنة (حدود قصوى). أول حد يتم الوصول إليه هو الذي يسري. لا يستمر المسار بصمت بعد انتهاك الحد — يتوقف المساعد (المسؤول عن شرح ما يحدث لك) ويسأل عما يجب فعله.","reference.desktop-budget#2#h":"ثلاثة حدود صارمة (افتراضي)","reference.desktop-budget#3#li0":"عدد الخطوات — 30 خطوة","reference.desktop-budget#3#li1":"ميزانية الرموز — 500,000 رمز","reference.desktop-budget#3#li2":"الوقت الفعلي — 5 دقائق","reference.desktop-budget#4#h":"فئات تكلفة المهام","reference.desktop-budget#5#li0":"بسيطة (بحث في المستندات، فتح صفحة) — 5–10 خطوات، ~70–135 ألف رمز، ~$0.04–0.08","reference.desktop-budget#5#li1":"متوسطة (تسجيل الدخول، فحص السجلات، تحميل المخرجات) — 15–25 خطوة، ~205–340 ألف رمز، ~$0.12–0.21","reference.desktop-budget#5#li2":"معقدة (فرز ثلاث مشكلات على GitHub) — 25–30 خطوة، ~340–410 ألف رمز، ~$0.21–0.25","reference.desktop-budget#6#p":"الأرقام الخاصة بالرموز أعلاه هي حدود تقنية لكل مسار، وليست حصتك الشهرية — تُحتسب تلك في الائتمانات، وتغطي الخطة المجانية الـ 300 شهريًا بوفرة مزيجًا من الدردشة والبرمجة وبعض الأتمتة.","reference.desktop-budget#7#c":"يمكنك تجاوز الحدود لكل مهمة عند البدء، لكن الانتهاكات تظهر دائمًا نقطة قرار. لا يُحرق الميزان بصمت أبدًا.","reference.desktop-whitelist#title":"قائمة السماح بجلسات سطح المكتب","reference.desktop-whitelist#0#p":"\"قائمة السماح\" هي ببساطة قائمة التطبيقات والمواقع الإلكترونية التي قلت لأفا أنها مسموح لها باللمس بينما تتحكم في سطح مكتبك. تشرح هذه الصفحة كيفية منح هذا الإذن ولماذا يتم إعادة تعيينه في كل مرة. النسخة المختصرة: يمكنها التصرف فقط حيث تسمح لها، وتطلب إذنًا قبل الذهاب إلى مكان جديد.","reference.desktop-whitelist#1#p":"في بداية جلسة سطح المكتب، تسأل أفا أين مسموح لها بالتصرف. اللغة البسيطة تعمل: \"Gmail، Cursor، بوابة Azure.\" تقرأ ذلك وتؤكد المطابقة لك مرة أخرى (\"Gmail web، Cursor التطبيق، portal.azure.com\").","reference.desktop-whitelist#2#h":"كيف يتم التنفيذ","reference.desktop-whitelist#3#p":"الإجراءات التي تتطلب النظر فقط — التقاط لقطة شاشة، قراءة قائمة الأزرار والحقول على الشاشة (شجرة \"UIA\"، الخريطة الخاصة بـ Windows لما هو موجود في نافذة) — مسموح بها في كل مكان، لأنك تحتاج لرؤية ما هو على الشاشة لتقرر إضافة تطبيق إلى قائمة السماح. أي شيء يغير شيئًا يتم حظره خارج القائمة؛ تتوقف أفا وتطلب ما إذا كان يجب إضافته.","reference.desktop-whitelist#4#h":"محدودة بالجلسة، وبشكل متعمد","reference.desktop-whitelist#5#p":"قائمة السماح لا تستمر عبر الجلسات. لا يوجد خيار \"تذكر هذا التطبيق\". تبدأ كل مسار جديد بنطاق جديد. غير مريح عن قصد — نسيان إعادة التفويض ميزة وليس عيبًا.","reference.desktop-whitelist#6#h":"إضافات أثناء المسار","reference.desktop-whitelist#7#p":"أثناء المسار يمكنك إضافة تطبيقات من الرأس: \"+ Allow app\" يفتح إدخالًا صغيرًا. اضغط Add والتطبيق الجديد يصبح نشطًا لبقية الجلسة.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"هل ترغب في إنشاء صورة، فيديو قصير، أغنية، أو صوت مكتوب؟ اصفحه فقط وستقوم أفا بإنشائه لك — لا حاجة لبرامج تصميم أو صوتية.","concepts.desktop-safety#3#li2":"تغيير قابل للعكس — اكتب في خانة، أو الصق نصًا، أو افتح تطبيقًا، أو انتقل إلى رابط. يتم التأكيد في وضع \"اسأل\"؛ أما في وضع \"القيادة\" فيكون تلقائيًا ضمن القائمة المسموحة.","concepts.desktop-safety#3#li3":"تغيير غير قابل للعكس — إرسال، تقديم، دفع، حذف، تأكيد، نشر. دائمًا يتطلب تأكيدًا، بغض النظر عن مستوى الصلاحية. الموافقة لا تُحفظ أبدًا.","concepts.desktop-safety#3#li4":"صلاحيات خاصة — رفع مستوى UAC، أمر sudo، تعديلات السجل، نوافذ طلب البيانات. محظور افتراضيًا. يتطلب موافقة اختيارية لمرة واحدة فقط في كل جلسة.","concepts.desktop-safety#4#h":"موافقات غير محفوظة","concepts.desktop-safety#5#p":"جميع المنافسين يحفظون الموافقات (يتذكرون \"نعم\" ويعيدون استخدامها المرة القادمة). هذا هو أكبر ثغرة لـ \"حقن الأوامر\" — هجوم تخترق فيه صفحة ويب مخادعة تعليمات خفية إلى الذكاء الاصطناعي لجعله يعمل ضدك. إذا كانت الموافقات محفوظة، يمكن لصفحة مختلطة أن تستغل \"نعم\" التي أعطيتها سابقًا. Ava لا تحفظ أبدًا. كل إجراء غير قابل للعكس يطلب تأكيدًا جديدًا.","concepts.desktop-safety#6#h":"التعامل مع الأسرار","concepts.desktop-safety#7#p":"كلمات المرور، مفاتيح API، ورموز التحقق بخطوتين (الرموز لمرة واحدة التي يعطيك إياها تطبيق ثانٍ أو رسالة نصية عند تسجيل الدخول) تُعالج عبر مؤشرات مؤقتة — أماكن تقف بدل القيمة الحقيقية. ترى Ava \"{secret}\" وليس كلمة المرور الفعلية. القيمة الحقيقية لا تدخل ذاكرتها أبدًا، ولا سجل نشاطها، ولا ما \"تقرأه\" — طبقة منفصلة منخفضة المستوى تقوم بإدخالها في اللحظة الأخيرة، عند الضغط على المفتاح، حتى لا يلمس جزء الذكاء الاصطناعي ذلك أبدًا.","reference.cli#title":"أوامر CLI","reference.cli#0#p":"هذه الصفحة مخصصة لأوامر CLI — نسخة Ava التي تكتب لها في نافذة طرفية، بدلاً من النقر على الأزرار. إذا كنت تستخدم الإضافة أو التطبيق المكتبي، يمكنك تجاهلها تمامًا. هي هنا للأشخاص الذين يفضلون استخدام لوحة المفاتيح.","reference.cli#1#p":"الـ CLI هي واجهة تفاعلية (REPL) — موجه ينتظر منك الكتابة، ينفذ ما كتبته، ثم يعود للانتظار. تعمل هذه الأوامر المائلة (التعليمات التي تبدأ بـ \"/\") مباشرة من الموجه.","reference.cli#2#li0":"/help — قائمة الأوامر والوضع الحالي.","reference.cli#2#li1":"/mode <name> — تبديل الوضع (عمل، كتابة، تخطيط، دردشة، تعليم، أمان، عصف ذهني).","reference.cli#2#li2":"/model <id> — تبديل النموذج دون مغادرة الجلسة.","reference.cli#2#li3":"/clear — مسح المحادثة الحالية. الذاكرة تبقى كما هي.","reference.cli#2#li4":"/history — عرض المحادثات السابقة في هذا المشروع.","reference.cli#2#li5":"/memory — فتح متصفح الذاكرة.","reference.cli#2#li6":"/tasks — عرض المهام وإدارتها.","reference.cli#2#li7":"/journal — فتح مدونة اليوم.","reference.cli#2#li8":"/settings — فتح قائمة الإعدادات.","reference.cli#2#li9":"/exit — الخروج من الواجهة التفاعلية.","reference.cli#3#h":"خيارات التشغيل","reference.cli#4#p":"الخيارات هي إضافات إضافية تضيفها عند بدء تشغيل Ava، وكل منها يبدأ بـ \"--\"، لتحديد كيفية فتحها.","reference.cli#5#li0":"--mode <name> — ابدأ في وضع معين.","reference.cli#5#li1":"--model <id> — ابدأ بنموذج معين.","reference.cli#5#li2":"--permission <mode> — صارم / متوازن / مستقل.","concepts.interjection#1#p":"Ava تعمل حتى يكتمل مخططها أو تقوم أنت بإيقافها. ولديك طريقتان للتدخل (وهذا ما نسميه \"تدخل\") أثناء عملها.","concepts.interjection#2#h":"تدخل — توجيه دون إلغاء","concepts.interjection#3#p":"اكتب رسالة جديدة بينما تعمل Ava. إنها تكمل استدعاء الأداة الحالي، تقرأ رسالتك، ثم تعدّل مخططها. لا يضيع أي سياق. استخدم هذا عندما تريد إعادة التوجيه، أو إضافة معلومات، أو تغيير الأولويات أثناء التشغيل.","concepts.interjection#4#h":"إيقاف قاطع — إلغاء وتفريغ","concepts.interjection#5#p":"اضغط على Escape (في الـ CLI)، أو انقر على Stop (في الإضافة، أو الـ IDE)، أو اكتب أمر إيقاف. يتوقف التشغيل الحالي، وتُسقط المكالمات المعلقة للأدوات، ويصبح الحوار جاهزاً لبدء جديد.","concepts.interjection#6#c":"استخدم التدخل أولاً. الإيقاف القاطع يكون فقط عندما يكون هناك خطأ حقيقي حقاً. التدخل يحافظ على استمرارية المحادثة.","concepts.desktop-personas#title":"شخصيات سطح المكتب","concepts.desktop-personas#0#p":"هذه الصفحة للمستخدمين الفضوليين وللمستخدمين المتقدمين. تعني \"أتمتة سطح المكتب\" (يُسمى أحياناً \"استخدام الكمبيوتر\") أن Ava يمكنها فعلياً النقر حول شاشتك واستخدام التطبيقات نيابة عنك — فتح Gmail، تعبئة نموذج، إرسال رسالة — مثل شخص يجلس أمام لوحة المفاتيح. للقيام بذلك بأمان، تقسم المهمة عبر خمسة مساعدين صغار، لكل منهم دور ضيق واحد. أنت لا تتعامل معهم مباشرة؛ هذا مجرد توضيح لمن يقوم بماذا.","concepts.desktop-personas#1#p":"تمر كل خطوة في مسار سطح المكتب (تشغيل واحد لـAva يقود شاشتك نحو هدف) بخمس شخصيات. لكل شخصية وظيفة واحدة فقط. الفصل بين الأدوار يبقي الطلبات مركزة، والمخرجات منظمة، والتفكير متشككاً بالتصميم.","concepts.desktop-personas#2#h":"المستكشف","concepts.desktop-personas#3#p":"تبلغ عما هو ظاهر على الشاشة الآن. لا تخترع عناصر أبداً. لا تخطط أبداً. تُرجع كائن JSON بحالة الشاشة مع معرفات العناصر، والأسماء، والإحداثيات، والثقة، ومصدر التأسيس (UIA، Playwright DOM، أو رؤية OmniParser).","concepts.desktop-personas#4#h":"المخطط","concepts.desktop-personas#5#p":"تقرر الإجراء التالي الوحيد. إجراء واحد لكل خطوة — لا تجمع أبداً. تفضل المسارات القابلة للعكس. تصنف المخاطر حسب مصفوفة السلامة. تُخرج JSON مقترح الإجراء مع النوع، الهدف، المعاملات، فئة المخاطر، والسبب، وتوقع الحالة اللاحقة المتوقعة.","concepts.desktop-personas#6#h":"المنفذ","concepts.desktop-personas#7#p":"تنفذ بالضبط ما اقترحه المخطط — بعد مرور بوابة الموافقة. لا يوجد ارتجال. لا يوجد إعادة محاولة. يُبلغ عن الفشل بصدق، ويتولى المُحقق الخطوة التالية.","concepts.desktop-personas#8#h":"المحقق","concepts.desktop-personas#9#p":"تتحقق مما إذا كان الإجراء قد نجح. تقارن حالة الشاشة الجديدة بتوقعات المخطط. تُرجع 'verified'، 'deviated'، أو 'rollback_needed'. كما تكشف عن الحلقات — تكرار إجراء نجح بالفعل هو انحراف، وليس تحققاً.","concepts.desktop-personas#10#h":"الراوي","concepts.desktop-personas#11#p":"الصوت الوحيد الذي يسمعه المستخدم خلال المسار. جملة واحدة بصيغة الماضي لكل خطوة (\"تم فتح Gmail.\"، \"تم النقر على كتابة.\"). أيضاً تكتب سجل التدقيق المنظم. تقول متى حدث خطأ — لا تخفي المشكلة أبداً.","concepts.desktop-safety#title":"مصفوفة سلامة سطح المكتب","concepts.desktop-safety#0#p":"باختصار: قبل أن تضغط Ava على أي شيء على شاشتك، تصنف الإجراء حسب مدى خطورته. قراءة الشاشة؟ غير ضار. إرسال أموال أو حذف شيء؟ تتوقف دائماً وتطلب إذنك أولاً — في كل مرة، بدون استثناء. العناوين الخمسة أدناه هي مجرد درجات على سلم المخاطر هذا. هذه تفاصيل للمستخدم المتقدم، لكن الخلاصة بسيطة: الأشياء الخطرة تحتاج دائماً إلى موافقتك.","concepts.desktop-safety#1#p":"يتم تصنيف كل إجراء مقترح ضمن إحدى فئات المخاطر الخمس. يجمع التصنيف بين ثلاثة إشارات — ما هو الهدف الظاهر على الشاشة، ووصف بلغة واضحة له (\"وصف دلالي\" — كلمات Ava الخاصة لما تنظر إليه)، وإعدادات الإجراء — ويرفع المستوى (يعامله كمخاطرة أعلى) عندما تختلف هذه الإشارات. النتيجة الإيجابية الكاذبة (السؤال عند عدم الحاجة) مجرد إزعاج. النتيجة السلبية الكاذبة (عدم السؤال عند وجوبه) هي حادثة تؤدي لإيقاف المنتج.","concepts.desktop-safety#2#h":"الفئات الخمس","concepts.desktop-safety#3#li0":"رصدية — قراءة شجرة UIA، لقطة شاشة، تمرير الماوس. مسموح تلقائياً دائماً.","concepts.desktop-safety#3#li1":"تنقلية — تمرير، نقل التركيز، فتح قائمة. مسموح تلقائياً في وضع القيادة.","features.creative-studio#1#p":"إنشاء الصور والفيديو والموسيقى والصوت — مدمج في نفس سير عمل الكود الخاص بك. أنشئ أيقونة، نموذجًا أوليًا للمنتج، فيديو تجريبي، أو تعليقًا صوتيًا للدروس. مدعوم بواسطة MiniMax.","features.creative-studio#2#h":"ما يمكنك إنشاؤه","features.creative-studio#3#li0":"صور — من النص إلى PNG/JPG. إزالة الخلفية بإشارة واحدة.","features.creative-studio#3#li1":"فيديو — مقاطع فيديو قصيرة بالذكاء الاصطناعي من وصف نصي (MiniMax Hailuo).","features.creative-studio#3#li2":"موسيقى — مقطوعات آلية أو غنائية مع كلمات.","features.creative-studio#3#li3":"صوت — تحويل النص إلى كلام بأصوات قابلة للاختيار.","features.creative-studio#4#p":"تكاليف Creative Studio تُخصم من نفس رصيد الاعتمادات مثل كل شيء آخر — رصيد واحد، رقم واحد. استخدم مفتاح MiniMax الخاص بك عبر BYOK وسيكون مجانيًا ضمن خطتك.","features.creative-studio#5#c":"Creative Studio مؤهل للاستخدام في الطبقة المجانية. ليست إضافة مدفوعة.","features.desktop-automation#title":"أتمتة سطح المكتب","features.desktop-automation#0#p":"ببساطة: يمكن لـ Ava التحكم في الفأرة ولوحة المفاتيح لتنفيذ المهام نيابةً عنك — فتح تطبيق، النقر على الأزرار، ملء نموذج — بينما تشرف وتوافق على أي أمر مهم.","features.desktop-automation#1#p":"وضع جديد لـ Ava، بادئة @@. هي تراقب سطح المكتب، وتقرر ما يجب فعله، وتقود أتمتة الواجهة (التحكم في التطبيقات على شاشتك لك) لإنجاز المهمة. تعمل على جهازك الفعلي بصلاحياتك الفعلية — وليس متصفح سحابي. متاحة في كل المستويات بمجرد إطلاقها.","features.desktop-automation#2#h":"لماذا نحتاج لأداة أخرى؟","features.desktop-automation#3#p":"كل منتجات أتمتة سطح المكتب الأخرى تبدأ فقط عندما تكون جالسًا أمام مكتبك. أما Ava فهي موجودة دائمًا عندما ينبهك نظام تتبع الأخطاء في الساعة 2 صباحًا — يستمر تشغيل IDE، ويرتبط هاتفك عبر قناة آمنة، وتوافق على الإجراءات الحاسمة بنقرة واحدة.","features.desktop-automation#4#p":"هي تتذكر أيضًا كيفية التنقل داخل تطبيقاتك عبر الجلسات المختلفة. كل وكيل آخر يعيد تعلمها في كل مرة. ميزة الذاكرة تتراكم قيمتها مع الاستخدام.","features.desktop-automation#5#h":"كيف يعمل","features.desktop-automation#6#p":"كل خطوة تمر بموجة من خمسة أدوار: الماسح يراقب، المخطط يختار الإجراء التالي، المنفذ ينفذ، المراجع يتحقق، الراوي يخبرك بما حدث. يختار المساعد الجانبي أرخص حل موثوق للربط — UIA للتطبيقات الأصلية، Playwright للمتصفحات، رؤية OmniParser عندما لا يكون لدى الآخرين شجرة مفيدة.","features.desktop-automation#7#p":"راجع صفحات المفاهيم لمزيد من المعلومات حول أساسيات السلامة، تسلسل الربط، مفاتيح الإيقاف، ونموذج قائمة السماح للجلسات.","start.glossary#1#td7.1":"وحدة حساب أبسط من Ava لتكلفة أي إجراء، حتى لا تضطر لحساب رموز. الخطط تأتي مع باقة شهرية.","start.glossary#1#td8.0":"مفتاح API","start.glossary#1#td8.1":"كلمة مرور خاصة تسمح للبرامج باستخدام خدمة مدفوعة (مثل نموذج ذكاء اصطناعي) على حسابك. لن تحتاج إليها إلا إذا أردت استخدام مفتاحك الخاص.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Bring Your Own Key.\" استخدام مفتاح API الخاص بك بدلاً من الوصول المدار من Ava. اختياري — للأشخاص الذين يدفعون لمزود الخدمة مباشرة بالفعل.","start.glossary#1#td10.0":"محلي أولاً","start.glossary#1#td10.1":"بياناتك تبقى على جهازك الشخصي افتراضياً. لا يُرفع شيء ما ما لم تقم بتشغيل التزامن. \"المحلي مقدس.\"","start.glossary#1#td11.0":"وضع الإذن","start.glossary#1#td11.1":"مدى حذر Ava قبل تنفيذ الأمور — أن تسأل في كل مرة، أو تطلب الإذن للمخاطر فقط، أو تنفذ فوراً. أنت من يحدد المستوى.","start.glossary#1#td12.0":"نافذة السياق","start.glossary#1#td12.1":"كمية النص التي يمكن للنموذج تذكرها دفعة واحدة — ذاكرته قصيرة المدى. \"سياق 1M\" تعني حوالي مليون كلمة. كلما كبر الحجم = قدرته على القراءة أكثر قبل النسيان.","start.glossary#1#td13.0":"فرق","start.glossary#1#td13.1":"عرض جانبي لما سيتغير بالضبط في ملف — القديم على جانب، والجديد على الآخر — يُعرض قبل أن تعدل Ava أي شيء لتتمكن من الموافقة عليه.","start.glossary#1#td14.0":"مستودع (repo)","start.glossary#1#td14.1":"مجلد مشروع يتم تتبع التغييرات فيه، عادة مع Git. إذا لم يكن ذلك يعني شيئاً لك بعد، فهو ببساطة \"المجلد الذي يوجد فيه مشروعي.\"","start.glossary#1#td15.0":"أمر","start.glossary#1#td15.1":"ما تكتبه للذكاء الاصطناعي — سؤالك أو تعليماتك.","start.glossary#2#c":"هل لا تزال متعثراً على كلمة؟ اسأل Ava في وضع الدردشة — \"ماذا يعني X؟\" — وستشرحه حسب مستواك.","models.routing#title":"التوجيه — كيف تختار Ava النماذج","models.routing#0#p":"إليك الخلاصة: لن تضطر أبداً لاختيار نموذج الذكاء الاصطناعي للاستخدام. Ava تفعل ذلك نيابة عنك، مختارة أفضل أداة لكل جزء من المهمة — تماماً مثل المدير الجيد الذي يسند المهمة الصحيحة للشخص المناسب.","models.routing#1#p":"تختار أحد الأنماط الثلاثة — Maestro، Supernova، أو Aurora — وترسل Ava كل جزء من العمل إلى النموذج الذي يتعامل معه بشكل أفضل. Maestro هو الافتراضي، وهو متاح في كل الخطة، وهو خيار جيد للجميع تقريباً.","models.routing#2#h":"لماذا نهتم بالتوجيه؟","models.routing#3#p":"استخدام النموذج المناسب في كل خطوة يكلف أقل من تشغيل كل شيء على نموذج واحد كبير ومكلف — ويعطي نتائج أفضل، لأن كل نموذج يقوم بما يجيده. تحصل على تكلفة مستقرة وجودة عالية دون الحاجة أبداً لمعرفة أي نموذج هو أي.","models.routing#4#c":"جميع الأنماط الثلاثة تعمل على أرصدة المنصة وعلى مفاتيحك الخاصة. بمفتاحك الخاص يمكنك أيضاً تجاوز التوجيه وتشغيل نموذج واحد مباشرة. التفصيل الكامل للأسطول موجود تحت \"أظهر لي التفاصيل\".","models.routing#deeper#0#c":"أرقام \"B\" أدناه هي مليارات المعلمات — تقريباً حجم عقل النموذج؛ الأكبر يعني عادة أكثر ذكاءً لكن أبطأ وأغلى. هذا تفصيل داخلي؛ لن تحتاجه أبداً لاستخدام Ava.","models.routing#deeper#2#td11.1":"أعمال يومية، تكلفة متوقعة","models.routing#deeper#2#td11.2":"أعمال معقدة متعددة الخطوات، منسق متقدم في كل خطة","models.routing#deeper#2#td11.3":"صارمة بخصوص GDPR، قطاع عام، بنى تحتية أوروبية سيادية","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"توجيه Qwen مختلف حسب الطبقة، بصمة خفيفة. يتولى Qwen 3.6 Plus دور المنسق والمُنشئ والتخطيط والأمن والعصف الذهني والعمل طويل السياق — الأماكن التي يستفيد فيها من اهتمامه الهجين الخطي بسياق 1M. يتولى Qwen 3.5 Flash الدردشة وتنسيق توليد الصور وبوابة النية الأمامية، حيث يفوز سعره $0.07/$0.26 وزمن الاستجابة الأسرع TTFT على معظم حجم الرموز منخفض العمق. يتولى Qwen 3.5 Omni Plus مدخلات الرؤية (لا يمتلك Qwen 3.6 Plus رؤية أصلية). يحمل Qwen 3.5 Plus الأعمال طويلة الشكل الحساسة للتكلفة. ينزل عبر سلم الأولويات Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash إذا تعذر المنسق الأساسي.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"تجمع متعدد اللغات. ينسق DeepSeek V4 Pro ويوزع كل مهمة فرعية إلى متخصصها الأنسب: يشغل Qwen 3.6 Plus كل استدعاء للمُنشئ، يتعامل V4 Flash مع الدردشة بالإضافة إلى شخصيات المراجعة/التدقيق من المستوى المتوسط، يمتص Qwen 3.5 Flash أعمال التصنيف الخفيفة، يتولى Qwen 3.5 Omni Plus مدخلات الرؤية، ينسق Qwen 3.5 Omni Flash مكالمات أدوات توليد الصور، يحمل Qwen 3.5 Plus شخصية كاتب المحتوى الحساسة للتكلفة. تفكير متقدم حيث يهم، اقتصاديات مستوى الفلاش على معظم حجم الرموز.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"حزمة الذكاء الاصطناعي الأوروبية — سيادية بالتصميم. توجيه يعتمد على Mistral فقط في ثلاث طبقات: يتولى Mistral Large 3 (675B/41B-nشط sparse MoE) دور المنسق بالإضافة إلى المتخصصين الثقيلين الذين يحتاجون للعمق — الباحث، المحدي، باحث CVE، المبتكر، المدقق الواقعي، المفحص الأمني — والعمل الشاق طويل السياق حيث تفوق كفاءة sparse-MoE. يتولى Mistral Medium 3.5 — العلم المدمج الصادر أبريل 2026، 128B كثيف، سياق 256K، محول رؤية مدرب من الصفر، أوزان مفتوحة معدلة MIT، 77.6% SWE-Bench Verified — تشغيل الطبقة العملية الفعلية: إطلاق المُنشئ، المتخصصون من المستوى المتوسط (المهندس المعماري، المدقق، المخطط، المعلم، المبلغ)، مدخلات الرؤية، والكتابة طويلة الشكل. توسع Mistral Small 4 من دور واحد عند بوابة النية ليتناول أيضًا الدردشة وتنسيق توليد الصور — سعره $0.15/$0.60 وقابلية التكوين في التفكير تكسب مكانها على الطرق عالية الحجم منخفضة العمق. أوزان مفتوحة من البداية للنهاية، لا تغادر البنية التحتية للاتحاد الأوروبي أبدًا. لا تعبر Aurora صامتة إلى نموذج غير Mistral عندما يكون أحدها غير متاح؛ يظهر المسار خطأً بدلاً من ذلك — هذا ما يجعلها \"Aurora\" بدلاً من \"Maestro\" بنكهة Mistral.","credits.overview#title":"رصيد Ava — كيف تعمل الفواتير","credits.overview#0#p":"الرصيد هو ببساطة طريقة حساب Ava لما تستخدمه — مثل دقائق خطة الهاتف. كل خطة، بما فيها المجانية، تأتي مع رصيد، وكل شيء تفعله Ava (الإجابة عليك، صنع صورة) يكلف عددًا صغيرًا منها. هذه هي الفكرة كلها. التفاصيل أدناه لمن يريد معرفة التكلفة بدقة.","credits.overview#1#p":"تحاسبك Ava بالرصيد وليس بالرموز الخام. (الـ \"رمز\" هو قطعة صغيرة من النص — حوالي بضعة حروف — تقرأها وتكتبها نماذج الذكاء الاصطناعي؛ معظم الخدمات تحاسبك لكل رمز، وهو أمر يصعب توقعه.) الرصيد الواحد يغطي وحدة عمل واحدة — دورة دردشة، إطلاق شخصية (مساعدة واحدة تقوم بجزء من المهمة)، توليد صورة. فصل القياس عن مستوى الرموز يعني أنك لا تحتاج لمعرفة النموذج الذي يعمل لتعرف تكلفة الإجراء. نفس دورة الدردشة تكلف نفس الشيء سواء وجهها Maestro إلى Qwen 3.6 Plus أو وجهتها Supernova إلى V4 Pro.","credits.overview#2#h":"الخطط","credits.overview#3#p":"كل خطة لها حق الوصول إلى كل الميزات — وصول النماذج، Creative Studio، جميع الأوضاع السبعة، تنسيق الشخصيات الكامل. الطبقات الأعلى تشتري المزيد من الرصيد وسقف أعلى لحد الطلب، وليس ميزات مطلقة.","credits.overview#4#li0":"مجاني — 0 دولار/شهريًا. 300 رصيد. حد طلب 20/دقيقة. لا حاجة لبطاقة.","credits.overview#4#li1":"احترافي — 19 دولار/شهريًا. 5,000 رصيد. 60 طلب/دقيقة.","credits.overview#4#li2":"فائق — 39 دولار/شهريًا. 10,000 رصيد. 120 طلب/دقيقة.","credits.overview#4#li3":"مؤسسي — 79 دولار/شهريًا. 20,000 رصيد. 200 طلب/دقيقة.","credits.overview#5#c":"الرصيد غير المستخدم ينتقل مع استمرار اشتراكك — لا يوجد استرداد إجباري. الإضافات تتراكم على رصيد الاشتراك: 750 رصيد مقابل 3 دولارات، 2,000 مقابل 8 دولارات، 4,000 مقابل 15 دولارًا.","credits.overview#6#h":"تكلفة الأشياء","credits.overview#7#p":"جدول التكلفة لكل إجراء — ما يُخصم من رصيدك عند تشغيل كل إجراء. (الـ \"استرجاع من الذاكرة المؤقتة\" هو عندما تعيد Ava استخدام عمل فعلته مسبقًا بدلًا من إعادة تنفيذه؛ عند حدوث ذلك تدفع أقل — ينخفض الخصم بنسبة 70%، أو 50% على نماذج الإنتاج الكثيفة مثل DeepSeek V4 Pro.)","credits.overview#8#li0":"دورة دردشة — 2 رصيد. محادثة واحدة ذهابًا وإيابًا في أي وضع.","credits.overview#8#li1":"مكالمة خفيفة — 1 رصيد. بوابة النية، التصنيف، قراءة لمرة واحدة.","credits.overview#8#li2":"شخصية ثقيلة — 3 رصيد. المهندس المعماري، الباحث، باحث CVE، المبتكر (عمق ≥ 4).","credits.overview#8#li3":"شخصية خفيفة — 1 رصيد. الكاشف، المدقق، المخطط، المحدي (عمق ≤ 2).","concepts.modes#0#p":"الوضع هو عقلية Ava الحالية — مثل زميل يغير قبعة عمله. نفس الشخص، نفس ذكرياتك، لكن المصمم يفكر بشكل مختلف عن المعلم. تختار الوضع ويغير طريقة تصرفها والمساعدون الذين تجلبها. يمكنك التبديل في أي وقت عبر محدد الأوضاع، أو كتابة اختصار مكون من حرفين.","concepts.modes#2#h":"أيّ واحد تفضّل؟","concepts.modes#3#p":"ابدأ مما تحاول فعله — يتبع الوضع ذلك:","concepts.modes#4#li0":"أريد بناء شيء ما أو تعديله → برمجة (>>). تصف الفكرة، هي تبنيه، وتعرض عليك كل تغيير أولاً. ينضم فريق المساعدة الكامل للمهام الكبيرة.","concepts.modes#4#li1":"أريد خطة قبل أي تغيير → خطة (::). تفكر ملياً وتسلمك خطة للموافقة عليها أو تعديلها. لن تمس ملفاتك في هذا الوضع.","concepts.modes#4#li2":"أريد فقط التحدث أو السؤال → دردشة (..). شريك للتفكير يمتلك ذاكرة وأخباراً وطقساً. لا تغييرات على الملفات، ولا كود — مجرد محادثة.","concepts.modes#4#li3":"أريد تعلّم شيء ما → تعليم (??). دورة حقيقية مبنية لك: دروس، اختبارات، وكل شيء. مجاني في كل الخطة، للأبد. مثالي إذا كنت جديداً.","concepts.modes#4#li4":"أريد فحص مشروعي بحثاً عن ثغرات أمنية → أمان (!!). يعمل فريق على قائمة معيارية لثغرات الويب الشائعة (فئات \"OWASP\") والعيوب المعروفة المبلغ عنها (تُسمى \"CVEs\")، ثم يسلمك تقريراً مرتباً حسب خطورة كل مشكلة. هذا موجه للمطورين — تخطّه إذا لم تكن منهم.","concepts.modes#4#li5":"أريد أفكاراً → عصف ذهني (**). تولّد خيارات مبنية على وضعك الفعلي، تنتقد الضعيف منها، وتطوّر الباقي إلى خطوات قادمة.","concepts.modes#4#li6":"أريد كتابة مستند → كتابة (<<). تقارير، مقترحات، رسائل، مقالات — تصيغها بـ Markdown وتصدر ملف Word أو PDF مصمماً، وتُحسّن القسم تلو الآخر. لا كود، مجرد كتابة.","concepts.modes#5#c":"فريق \"المساعدات\" (الشخصيات) يعمل بالكامل خلف الكواليس — لا تتحدث معهم مباشرة أبداً. تحصل فقط على إجابة أكثر شمولاً. لا تحتاج لمعرفة أسماءهم.","concepts.modes#6#c":"يمكنك التبديل بين الأوضاع أثناء المحادثة. ذاكرتك تنتقل؛ بينما يعيد المتخصصون ضبط أنفسهم لتناسب الوضع الجديد.","concepts.tasks-journal#title":"المهام والسجل اليومي","concepts.tasks-journal#0#p":"تحتفظ Ava بثلاث أنواع من الملاحظات لك، ومن السهل الخلط بينها. الطريقة السريعة للتذكر: الذاكرة هي ما تعرفه عنك، المهام هي ما لا يزال عليك فعله، والسجل هو يوميات لما حدث. إليك متى تستخدم كل واحدة.","concepts.tasks-journal#1#li0":"الذاكرة — حقائق دائمة. التفضيلات، القرارات، الأنماط. يُسأل عنها مراراً، نادراً ما تُنشأ يدوياً.","concepts.tasks-journal#1#li1":"المهام — أشياء يجب فعلها. بنود عمل مع تواريخ استحقاق وحالة. تضع علامة عليها عند الانتهاء.","concepts.tasks-journal#1#li2":"السجل — تأمل. سجل يومي، إدخالان مزدوجان (منك وملاحظات Ava حول الجلسة). مفيد لتتبع الحالة المزاجية، مراجعة الجلسات، سياق للغد.","concepts.tasks-journal#2#p":"Ava تكتب في الثلاثة عندما يكون ذلك منطقياً. يمكنك الكتابة في أي منها مباشرة من لوحة التحكم. لا شيء مقفل في مكان واحد تستخدم فيه Ava — مهمة تنشئها في واحد (لنقل أداة سطر الأوامر) تظهر في كل مكان آخر (مثل تطبيق سطح المكتب)، تلقائياً.","concepts.permissions#title":"الصلاحيات — مفتاح الأمان الخاص بك","concepts.permissions#0#p":"الصلاحيات هي مفتاح الأمان الخاص بك. تقرر متى تطلب Ava موافقتك قبل فعل شيء على جهازك، مقابل الاستمرار فوراً. يمكنك ضبطها لتسأل عن كل شيء، أو تسأل عن الأمور الخطرة فقط، أو تثق بها لتشغيلها — ويمكنك تغييره في أي وقت. إذا لم تكن متأكداً، اتركه على الإعداد الافتراضي وستكون بخير.","concepts.permissions#1#p":"لدى Ava 60 أداة (\"الأدوات\" هي الإجراءات التي يمكنها القيام بها — قراءة ملف، البحث في الويب، وما إلى ذلك). تنتمي كل أداة إلى فئة (عمليات الملفات، Shell، Git، الويب، الوسائط، قاعدة البيانات، النظام، المستندات، الذاكرة، التعلم). تمر كل استدعاء أداة عبر بوابة الصلاحيات (نقطة تحقق تقرر ما إذا كانت ستسألك أولاً) قبل تشغيلها. أنت تتحكم فيما يتم الموافقة عليه تلقائياً، وما الذي يسأل مرة واحدة، وما الذي يسأل دائماً.","concepts.permissions#3#p":"\"متوازن\" هو الإعداد الافتراضي. \"صارم\" عندما تقوم بمراجعة سلوكها (مراقبة دقيقة لكل خطوة). \"ذاتي\" عندما تريد منها أن تعمل وحدها.","concepts.permissions#4#c":"\"ذاتي\" لا يعني غير خاضع للرقابة. الخطط، الأسئلة التوضيحية، واستدعاءات طلب المستخدم الصريحة لا تزال تتوقف لمدخلاتك. العمليات التي لا رجعة فيها (مثل Git force-push أو حذف قواعد البيانات) تتطلب تأكيداً دائماً بغض النظر عن الوضع.","concepts.interjection#title":"توجيه وإيقاف Ava","concepts.interjection#0#p":"أنت المسؤول دائماً. بينما تكون Ava مشغولة بالعمل، يمكنك إما توجيهها في اتجاه جديد دون كسر خطوتها، أو إيقافها فوراً. زرين، نتيجتان — هذا كل ما تدور حوله هذه الصفحة."},"hi":{"start.for-non-coders#title":"कभी कोड नहीं लिखा? यहाँ से शुरू करें","start.for-non-coders#0#p":"If you have never written a line of code, you are exactly who Ava is for. You do not need to learn any jargon to start — you talk to her in plain English, the way you would ask a knowledgeable friend. This page is your whole on-ramp.","start.for-non-coders#1#h":"आज ही क्या कर सकते हैं, बिना किसी अनुभव के","start.for-non-coders#2#li0":"कुछ भी पूछें, आम शब्दों में — \"यह फ़ाइल क्या करती है?\", \"मेरी पेज खाली क्यों है?\", \"डेटाबेस होता क्या है?\" वह सरल भाषा में जवाब देती है और बातचीत याद रखती है।","start.for-non-coders#2#li1":"Learn something from scratch — say \"teach me Python from zero\" and she builds you a proper course with lessons and quizzes. This is always free.","start.for-non-coders#2#li2":"Get something built — describe what you want (\"a button that downloads my notes\") and she writes it, showing you every change before it happens.","start.for-non-coders#3#h":"आपको सब कुछ समझने की जरूरत नहीं","start.for-non-coders#4#p":"Ava has a lot of machinery under the hood — modes, models, specialists, routing. You will see those words around the app and in these docs. Here is the secret: you can ignore almost all of it. Ava picks the right tools and the right helpers for you automatically. The technical pages are there for when you get curious, not because you need them to start.","start.for-non-coders#5#h":"एक आसान पहला रास्ता","start.for-non-coders#6#li0":"Install Ava (next page) and open the chat.","start.for-non-coders#6#li1":"Type a real question you have. Anything. See how she answers.","start.for-non-coders#6#li2":"Try learning mode: type \"teach me\" and a topic. Follow along.","start.for-non-coders#6#li3":"जब आप चाहें कि वह वाकई कुछ बनाए या बदले, बस कहें — वह हमेशा बताएगी कि वह क्या करने जा रही है और आपके 'हाँ' का इंतज़ार करेगी।","start.for-non-coders#7#c":"क्या कोई शब्द समझ नहीं आया? इस खंड के आगे दिए गए सरल अंग्रेजी शब्दकोश में हर पद की व्याख्या की गई है, बिना किसी पहले से मानी जाने वाली जानकारी के।","start.install#title":"इंस्टॉल करें","start.install#0#p":"अपने काम के तरीके के हिसाब से वह जगह चुनें। आप एक से ज्यादा का भी इस्तेमाल कर सकते हैं — Ava सिग्न इन करते ही अपने डेटा को सब जगह सिंक कर लेती है।","start.install#1#h":"VS Code extension","start.install#2#li0":"VS Code में Extensions panel खोलें (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"\"Ava Supernova\" के लिए सर्च करें और Install पर क्लिक करें।","start.install#2#li2":"चैट पेनल खोलने के लिए Ctrl+Shift+A दबाएं (macOS पर Cmd+Shift+A).","start.install#2#li3":"सेटअप विज़र्ड का पालन करें — एक मॉडल चुनें, अपना परमिशन मोड सेट करें, तैयार।","start.install#3#h":"Desktop IDE","start.install#4#li0":"रिलीज़ पेज से अपने प्लेटफॉर्म के लिए इंस्टॉलर डाउनलोड करें।","start.install#4#li1":"इसे चलाएं। पहली बार IDE लॉन्च होने पर यह एक स्वागत प्रक्रिया के साथ खुलेगा।","start.install#4#li2":"फ्री प्लेटफॉर्म टोकन्स के लिए साइन इन करें, या पूरी तरह लोकल चलाने के लिए अपना API key पेस्ट करें।","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli (या pnpm / yarn — आपकी पसंद).","start.install#6#li1":"किसी भी प्रोजेक्ट डायरेक्ट्री में `ava` चलाएं।","start.install#6#li2":"पहली बार चलाने पर यह एक प्रोवाइडर और मॉडल मांगता है। चुनें और शुरू करें।","start.install#7#c":"कोई खाता नहीं, कोई समस्या नहीं। अपने API key (BYOK) के साथ आपको कभी साइन इन करने की जरूरत नहीं होती। फ्री टियर प्लेटफॉर्म-प्रबंधित मॉडल्स के लिए है।","concepts.memory#title":"स्मृति — Ava आपको कैसे याद रखती है","concepts.memory#0#p":"सरल शब्दों में: Ava आपको याद रखती है। उसे एक बार कुछ बताएं — क्या आपको पसंद है, आपने क्या निर्णय लिया — और वह उसे रखती है, ताकि आपको अगली चैट या अगले हफ्ते खुद को दोहराने की जरूरत न पड़े। यह मुख्य बात है। नीचे की परतें केवल यह समझाती हैं कि वह समय के साथ उस स्मृति को कैसे साफ़ रखती है।","concepts.desktop-grounding#title":"डेस्कटॉप ग्राउंडिंग हियरार्की (पूर्वावलोकन)","concepts.desktop-grounding#0#c":"पूर्वावलोकन — स्कौट हर चरण में किस ग्राउंडिंग स्रोत का उपयोग करने का निर्णय लेता है।","concepts.desktop-grounding#1#p":"Ava बटन क्लिक करने से पहले, उसे वास्तव में समझना होगा कि आपकी स्क्रीन पर क्या है और चीज़ें कहाँ हैं — इसे \"ग्राउंडिंग\" कहते हैं (स्क्रीन पर हर चीज़ क्या है और उसका सटीक स्थान क्या है, यह पता लगाना)। इसके लिए उसके पास तीन तरीके हैं और वह उस ऐप के लिए सबसे भरोसेमंद तरीका चुनती है जिसमें आप हैं। यह गहरा पावर-यूजर विवरण है; मुख्य बात यह है कि वह तस्वीर से अनुमान लगाने के बजाय मजबूत, सटीक विधियों को प्राथमिकता देती है।","concepts.desktop-grounding#2#p":"तीन स्तर, क्रम में मूल्यांकित। सबसे सस्ता भरोसेमंद स्रोत जीतता है।","concepts.desktop-grounding#3#h":"1. ब्राउज़र विंडो → Playwright DOM","concepts.desktop-grounding#4#p":"यदि सक्रिय विंडो एक वेब ब्राउज़र है, तो Ava तस्वीर से अनुमान लगाने के बजाय पेज की अपनी संरचना को पढ़ती है (\"DOM\" — पेज पर क्या है, इसकी नींव सूची)। संरचना पढ़ना पिकसेल्स को देखने से लगभग 10 गुना अधिक भरोसेमंद है — उसे हर बटन का सटीक स्थान पता होता है और जब पेज लोड हो गया है। यह वेब पर किसी भी चीज़ के लिए मुख्य मार्ग है, बैकअप नहीं।","concepts.desktop-grounding#5#h":"2. UIA के साथ नेटिव ऐप → Windows UI Automation","concepts.desktop-grounding#6#p":"Windows पर साधारण डेस्कटॉप ऐप्स के लिए, Ava एक इनबिल्ट एक्सेसिबिलिटी मैप पढ़ती है (\"UIA\", वही डेटा जिसे स्क्रीन-रीडर्स विंडो का वर्णन करने के लिए उपयोग करते हैं) — यह हर कंट्रोल, उसका नाम, और वह कहाँ बैठता है, सूचीबद्ध करता है। यदि वह मैप कम से कम पांच उपयोग योग्य, नामित आइटम लौटाता है, तो Ava उस पर भरोसा करती है और उसका उपयोग करती है।","concepts.desktop-grounding#7#h":"3. UIA खाली या बेकार → OmniParser vision","concepts.desktop-grounding#8#p":"जब वह मैप गायब या बेकार होता है (कुछ ऐप्स, गेम, और रिमोट स्क्रीन एक नहीं देते), तो Ava वास्तव में स्क्रीनशॉट देखने पर लौट आती है। एक विजन टूल (OmniParser) क्लिक करने योग्य क्षेत्रों को पहचानता है और लेबल करता है कि हर एक क्या है, तस्वीर को फिर से उस सूची में बदल देता है जिस पर वह कार्य कर सकती है — एक्सेसिबिलिटी मैप द्वारा दिए गए थोड़े से हिस्से के साथ।","concepts.desktop-grounding#9#c":"OmniParser पहली बार जब Ava को इसकी आवश्यकता होती है, तब ऑप्शनल होता है, एक स्पष्ट गोपनीयता प्रॉम्प्ट के साथ। BYOK उपयोगकर्ता अपने स्थानीय OmniParser डिप्लॉयमेंट की ओर इशारा कर सकते हैं।","concepts.desktop-kill-switches#title":"डेस्कटॉप किल स्विच (पूर्वावलोकन)","concepts.desktop-kill-switches#0#c":"पूर्वावलोकन — चल रही प्रक्रिया रद्द करने के तीन स्वतंत्र तरीके। उनमें से कोई एक भी काम करेगा।","concepts.desktop-kill-switches#1#p":"एक \"किल स्विच\" बिल्कुल वैसा ही है जैसे सुनाई देता है — एक आपातकालीन तरीका Ava को तुरंत रोकने का जब वह आपकी स्क्रीन को नियंत्रित कर रही हो। आराम देने वाली बात: इसके तीन हैं, प्रत्येक अलग से बनाया गया है, इसलिए यदि एक विफल हो जाता है तो दूसरा अभी भी काम करता है। आपको तीनों सीखने की जरूरत नहीं है। बस यह जान लें कि जब कुछ गलत दिखे, तो आप हमेशा उसे रोक सकते हैं, और सबसे मजबूत रोक (नीचे दी गई पैनिक किल) Ava के सहयोग पर निर्भर नहीं करती।","concepts.desktop-kill-switches#2#p":"हर सार्वजनिक AI स्वतंत्रता घटना (वास्तविक मामले जहाँ AI एजेंट्स ने स्टॉप कमांड्स को अनदेखा किया, ईमेल आर्काइव हटा दिए, ड्राइव मिटा दिए) पढ़ने के बाद, हमने तीन अलग-अलग परतों में तीन किल स्विच बनाए। इनमें से कोई भी AI मॉडल पर निर्भर नहीं है — यदि Ava फंस गई है या प्रतिक्रिया नहीं दे रही है, तो आप अभी भी उसे रोक सकते हैं।","concepts.desktop-kill-switches#3#h":"रोकें — स्पेस या पॉज बटन","reference.models#11#h":"अपनी कुंजी खुद लाएं","reference.models#12#p":"एक \"API कुंजी\" एक निजी पासवर्ड है जो सॉफ़्टवेयर को आपके खाते पर भुगतान वाली सेवा का उपयोग करने देता है। \"BYOK\" का मतलब सिर्फ \"अपनी कुंजी खुद लाएं\" है — हमारी जगह अपनी का उपयोग करना। सेटिंग्स में अपनी API कुंजी पेस्ट करें। BYOK अनुरोध Ava सीधे प्रदाता (मॉडल चलाने वाली कंपनी) तक जाते हैं — वे हमारे इंफ्रास्ट्रक्चर से नहीं गुजरते और प्लेटफ़ॉर्म टोकन खर्च नहीं करते। आप प्रदाता को भुगतान करते हैं; हम ट्रैफिक नहीं देखते।","reference.models#14#c":"बेंचमार्क स्कोर, क्षमता टैग, और साइड-बाई-साइड फ़िल्टरिंग के लिए ava-supernova.com/models पर पूर्ण मॉडल्स पेज देखें। ऊपर दिखाया गया मूल्य प्रकाशन समय पर प्रत्येक प्रदाता रेट कार्ड का हमारा सर्वोत्तम अनुमान है — कार्यभार शुरू करने से पहले हमेशा प्रदाता वेबसाइट जांचें।","reference.personas#title":"पर्सोना समन्वय","reference.personas#0#p":"एक \"पर्सोना\" Ava द्वारा कठिन कामों के लिए पृष्ठभूमि में निभाई जाने वाली एक सहायक भूमिका है — एक अन्वेषक, एक योजनाकार, एक तथ्य-जाँचकर्ता। आप उनसे सीधे बात नहीं करते और Ava का उपयोग करने के लिए इस पेज को समझने की आवश्यकता नहीं है। यह वहां है जब आप जिज्ञासु होते हैं कि वह बड़े काम को छोटे विशेषज्ञ टीम में कैसे विभाजित करती है।","reference.personas#1#p":"5 मोड टीमों में 24 विशेषज्ञ। कंडक्टर (बाकी को समन्वित करने वाला सहायक) तय करता है कि कौन सी टीम चलेगी, किस क्रम में, और किस संदर्भ के साथ। चैट मोड में कोई पर्सोना नहीं होता — यह Ava स्वयं है।","reference.personas#2#h":"समन्वय कैसे काम करता है","reference.personas#3#li0":"आप Plan, Teach, Security, या Brainstorm मोड (या एक जटिल Work अनुरोध) में संदेश भेजते हैं।","reference.personas#3#li1":"कंडक्टर अनुरोध पढ़ता है, मोड टीम चुनता है, और एक निष्पादन योजना बनाता है — कुछ पर्सोना क्रमिक रूप से चलते हैं, कुछ समानांतर लहरों में।","reference.personas#3#li2":"प्रत्येक पर्सोना का अपना सिस्टम प्रॉम्प्ट, एक प्रतिबंधित टूल अनुमत सूची, और पिछले पर्सोना द्वारा पाए गए संदर्भ का साझा पूल होता है।","reference.personas#3#li3":"अंतिम पर्सोना मोड के आधार पर एक सारांश, योजना, या रिपोर्ट तैयार करता है।","reference.personas#3#li4":"Ava आपको परिणाम प्रस्तुत करती है। आप उसे स्वीकार, संशोधित, या पुनः निर्देशित कर सकते हैं।","reference.personas#4#p":"नीचे दी गई पूर्ण सूची केवल संदर्भ के लिए है — जानने की आवश्यकता नहीं है कि कौन क्या करता है। Ava आपके लिए सही टीम इकट्ठा करती है।","reference.personas#6#c":"Work मोड केवल जटिल कार्यों के लिए पूरी टीम को बुलाता है। सरल संपादन Ava को सीधे चलाते हैं — कोई समन्वय ओवरहेड नहीं।","concepts.desktop-kill-switches#4#p":"अगले कदम की सीमा पर रुक जाता है। इसे फिर से शुरू किया जा सकता है। जब आप बिना रास्ते भटकाए बीच में दखल देना चाहें, तो इसका इस्तेमाल करें।","concepts.desktop-kill-switches#5#h":"रोकें — Escape या स्टॉप बटन","concepts.desktop-kill-switches#6#p":"साफ़ तरीके से रोकें। नरेटर बताता है कि अब तक क्या काम हुआ। इसे फिर से शुरू नहीं किया जा सकता। ऑडिट लॉग सेव हो जाता है।","concepts.desktop-kill-switches#7#h":"पैनिक किल — तीन बार Escape या Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"यह सबसे कड़ी रोक है। एक छोटा, अलग वॉचडॉग प्रोग्राम Ava के उस हिस्से को जबरदस्ती बंद कर देता है जो आपके स्क्रीन को चला रहा है। यह AI के जवाब का इंतज़ार नहीं करता, ऐप विंडो के खुले होने की भी जरूरत नहीं है, और यह नहीं देखता कि सब कुछ किस हालत में है — यह सिर्फ उसे बंद कर देता है। यह तब इस्तेमाल करें जब कुछ सचमुच गलत हो जाए।","concepts.desktop-kill-switches#9#p":"तीनों ही साथी ऐप से भी काम करते हैं। कोई भी ड्राइवर इसे समाप्त कर सकता है।","reference.tools#title":"टूल्स का संदर्भ","reference.tools#0#p":"यह Ava के सभी टूल्स की पूरी सूची है — एक \"टूल\" बस एक खास एक्शन है जो वह कर सकती है, जैसे फाइल पढ़ना या सर्च चलाना। आपको इस पेज को पढ़ने की जरूरत नहीं है। Ava हर बार सही टूल अपने आप चुन लेती है। यह तब है जब आप जानना चाहते हैं कि वह ठीक-ठीक क्या कर सकती है।","reference.tools#1#p":"पूरा इनबिल्ट टूलबॉक्स। यहाँ का हर टूल कोर रनटाइम (तीनों सतहों के नीचे वाला इंजन) में रजिस्टर है और Ava के लिए उपलब्ध है जब मोड और परमिशन मोड अनुमति देते हैं। श्रेणी या रिस्क के आधार पर फिल्टर करें।","reference.tools#2#p":"इसमें से किसी को भी याद करने की जरूरत नहीं — नीचे दी गई टेबल बस एक रेफरेंस कार्ड है।","reference.tools#4#h":"जोखिम के स्तर","reference.tools#5#li0":"सुरक्षित — बिना कुछ बदले चीज़ें पढ़ता है। file_read, glob (नाम पैटर्न से फाइल ढूंढें), grep (फाइलों के अंदर टेक्स्ट के लिए सर्च करें), git_status (Git वह सिस्टम है जो आपके प्रोजेक्ट में हुए बदलावों को ट्रैक करता है)।","reference.tools#5#li1":"लिखें — फाइलें बदलता है, आपके काम का चेकपॉइंट सेव करता है (एक \"commit\"), या कुछ नया उत्पन्न करता है। file_edit, git_commit, generate_image.","reference.tools#5#li2":"खतरनाक — आपके कंप्यूटर पर कमांड चलाता है (\"shell\"), डेस्कटॉप को नियंत्रित करता है, इंटरनेट पर जाता है, या डेटाबेस को क्वेरी करता है। bash, browser, desktop_*.","reference.tools#6#c":"पर्सोना विशेषज्ञों के अपने टूल अनुमतियां होती हैं। Scout पढ़ सकता है लेकिन लिख नहीं सकता। Builder को पूरा एक्सेस है। Challenger के पास कोई टूल नहीं है — इसका काम योजना पर सवाल उठाना है।","reference.models#title":"मॉडल","reference.models#0#p":"एक \"मॉडल\" वह AI दिमाग है जो सोचता है — Qwen, DeepSeek, Mistral और अन्य। यह पेज उन सभी मॉडल्स की सूची है जिन्हें Ava इस्तेमाल कर सकती है। छोटे शब्दों में: आपको एक चुनने की जरूरत नहीं है। Ava हर कदम के लिए सही मॉडल अपने आप चुन लेती है। तभी आगे पढ़ें अगर आप समझना या इसे बदलना चाहते हैं।","reference.models#1#p":"Ava के लिए उपलब्ध हर मॉडल, और तीन ऑर्केस्ट्रेशन रणनीतियां — नियम जो तय करते हैं कि कौन सा मॉडल काम के हर हिस्से को संभालेगा। एक रूटिंग मोड चुनें और Ava को भेजने दें, या एक अकेला मॉडल चुनें और रूटिंग को पूरी तरह छोड़ दें।","reference.models#2#h":"रूटिंग मोड्स","reference.models#3#p":"तीन ऑर्केस्ट्रेटेड रणनीतियां। वही पर्सोना पाइपलाइन (पीछे की छुपी हुई विशेषज्ञ मददगारों की छोटी टीम) तीनों पर चलती है; जो बदलता है वह मॉडल्स का बेसिक फ्लीट है। मॉडल सिलेक्टर में मोड चुनें और Ava बाकी संभाल लेती है। नीचे की हर कार्ड दिखाता है कि कंडक्टर किन विशेषज्ञों को रूट करता है।","reference.models#4#p":"आपको नीचे की कार्ड्स को याद करने की जरूरत नहीं — वे यहाँ इसलिए हैं ताकि आप देख सकें कि हर रणनीति किससे बनी है।","reference.models#6#c":"Aurora जानबूझकर सिर्फ Mistral के लिए है। अगर Mistral मॉडल उपलब्ध नहीं है तो रूटर एरर देता है cross-routing के बजाय — यह EU-stack की गारंटी है। Maestro या Supernova के लिए graceful degradation चुनें।","reference.models#7#c":"तीनों मोड्स हर जगह उपलब्ध हैं — प्लेटफॉर्म क्रेडिट्स और अपने खुद के keys पर। BYOK एक विकल्प जोड़ता है orchestration को bypass करने और एक अकेले मॉडल को सीधे चलाने का।","reference.models#8#h":"प्लेटफॉर्म-प्रबंधित मॉडल","reference.models#9#p":"हर प्लान पर उपलब्ध, निःशुल्क टियर सहित। Tokens (AI द्वारा मापा जाने वाला टेक्स्ट की इकाई — लगभग शब्द का तीन-चौथाई) आपके प्लान की सीमा के अंदर गिने जाते हैं। Keys (हर paid model को अनलॉक करने वाले निजी पासवर्ड) प्लेटफॉर्म द्वारा घुमाए और निगरानी किए जाते हैं — आपको कॉन्फ़िगर करने के लिए कुछ नहीं।","reference.config#title":"कॉन्फ़िगरेशन","reference.config#0#p":"यह पेज बताता है कि Ava अपने कंप्यूटर पर अपनी सेटिंग्स और फाइल्स कहाँ रखती है। आपको हाथ से इसमें छूने की लगभग कभी जरूरत नहीं होती — ऐप इसे आपके लिए मैनेज करता है। यह तब काम आता है जब आप खुद इन फाइलों को देखना, बैकअप लेना या शेयर करना चाहते हैं।","reference.config#1#p":"Ava अपनी सेव की गई सेटिंग्स (कॉन्फ़िगरेशन) दो जगहों से पढ़ती है। ग्लोबल सेटिंग्स — जो हर जगह लागू होती हैं — ~/.ava/ नामक फोल्डर में होती हैं (यहाँ \"~\" आपका होम फोल्डर दर्शाता है)। प्रोजेक्ट-विशिष्ट सेटिंग्स प्रोजेक्ट के अंदर मौजूद .ava/ फोल्डर में होती हैं।","reference.config#2#h":"ग्लोबल — ~/.ava/","reference.config#3#li0":"settings.json — मॉडल प्राथमिकताएं, अनुमति मोड, व्यक्तित्व, भाषा।","reference.config#3#li1":"memory/ — आपकी ग्लोबल मेमोरियां (प्राथमिकताएं, निर्णय जो हर जगह लागू होते हैं)।","reference.config#3#li2":"tasks.json — कई प्रोजेक्ट्स के लिए कार्य सूची।","reference.config#3#li3":"journal/ — दैनिक डायरी के एंट्री, तारीख के अनुसार व्यवस्थित।","reference.config#4#h":"प्रोजेक्ट — .ava/","reference.config#5#li0":"instructions.md — प्रोजेक्ट-विशिष्ट निर्देश जो Ava हमेशा लोड करती है। टिकाऊ संदर्ध (\"हम pnpm का उपयोग करते हैं, npm का नहीं\", \"API कुंजियां 1Password में रहती हैं\")।","reference.config#5#li1":"context.md — वैकल्पिक स्वतंत्र प्रोजेक्ट नोट्स।","reference.config#5#li2":"memory/ — इस प्रोजेक्ट तक सीमित मेमोरियां।","reference.config#5#li3":"datasets/config.json — ऑप्ट-इन डेटासेट कैप्चर कॉन्फ़िगरेशन।","reference.config#6#c":".ava/ को अपने .gitignore में शामिल करें (एक फाइल सूची जिसे Git को साझा प्रोजेक्ट से बाहर छोड़ने के लिए कहा गया है), अगर आप टीम के साथ मेमोरिया शेयर नहीं करना चाहते। instructions.md को रिपॉजिटरी (साझा प्रोजेक्ट फोल्डर) में रखें — यही तरीका है जिससे Ava प्रोजेक्ट की परंपराओं को समझती है।","reference.shortcuts#title":"कीबोर्ड शॉर्टकट","reference.shortcuts#0#p":"कीबोर्ड शॉर्टकट वैकल्पिक तेज़ी हैं — इनमें से हर एक बटन भी है जिसे आप क्लिक कर सकते हैं। केवल तभी यहाँ देखें यदि आप कीबोर्ड से Ava को तेज़ चलाना चाहते हैं।","reference.shortcuts#1#p":"सतह के अनुसार शॉर्टकट (Ava चलाए जाने वाले तीन स्थान: VS Code एक्सटेंशन, डेस्कटॉप ऐप, और टर्मिनल)। इन्हें प्रत्येक सतह की सेटिंग्स में अनुकूलित करें। नीचे दी गई सूची याद रखने की आवश्यकता नहीं है।","reference.project-context#title":"परियोजना का संदर्भ","reference.project-context#0#p":"यह बताता है कि Ava शुरू करने से पहले आपके प्रोजेक्ट के बारे में कैसे जानकारी लेती है — वह कौन से फ़ाइलें देखती है ताकि समझ सके आप क्या काम कर रहे हैं। आपको इसकी कोई सेटअप नहीं करना पड़ता; वह खुद ही यह करती है। अगर आप जानना चाहते हैं कि नोट कहाँ रखें ताकि Ava उसे हमेशा देख सके, तो इसे पढ़ें।","reference.project-context#1#p":"जब आप एक प्रोजेक्ट खोलते हैं, तो Ava कई परतों का संदर्भ लोड करती है (वह पृष्ठभूमि जानकारी जो उसके दिमाग में होती है)। परतों को समझने से आपको जानकारी सही जगह पर रखने में मदद मिलती है।","reference.project-context#2#h":"स्वतः लोड होता है","reference.project-context#3#li0":".ava/instructions.md — इसे स्थायी, उच्च प्राथमिकता वाला निर्देश माना जाता है। हमेशा संदर्भ में रहता है।","reference.project-context#3#li1":".ava/context.md — स्वतंत्र नोट्स। लोड किया जाता है, कम प्राथमिकता।","reference.project-context#3#li2":"README.md — प्रोजेक्ट सारांश के लिए पहली बार चलाए जाने पर स्कैन किया जाता है।","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — छोटी फ़ाइलें जो प्रोजेक्ट सेटअप की सूची बनाती हैं; भाषा, फ्रेमवर्क और टेस्ट कमांड का पता लगाने के लिए पढ़ी जाती हैं।","reference.project-context#3#li4":".gitignore — उन फ़ाइलों की सूची जिन्हें वर्जन कंट्रोल से बाहर रखा जाए; सभी फ़ाइल टूल्स द्वारा सम्मानित किया जाता है (glob, grep, project_index).","reference.project-context#4#h":"जरूरत पड़ने पर लोड होता है","reference.project-context#5#p":"\"On demand\" का मतलब है कि Ava इनको तभी लाती है जब किसी कार्य को वास्तव में उनकी जरूरत हो, शुरुआत में नहीं।","reference.project-context#6#li0":"Project index — आपकी फ़ाइलों और उनके अंदर के नामित हिस्सों (फ़ंक्शन, क्लासेस — \"symbols\") और उनके जुड़ाव (\"imports\") का एक संरचित नक्शा। इसे 'lazily' बनाया जाता है, यानी केवल तब जब Ava को इसकी जरूरत हो।","reference.project-context#6#li1":"Git history — पिछले बदलावों का रिकॉर्ड; जब git_status, git_diff, या git_create_pr कॉल किए जाते हैं तो लिया जाता है (git वह टूल है जो प्रोजेक्ट के हर बदलाव को ट्रैक करता है; \"PR\" एक पुल रिक्वेस्ट है, बदलावों का एक प्रस्तावित समूह).","reference.project-context#6#li2":"Memory — एंट्रीज अर्थ के आधार पर (\"semantically\") मेल खाती हैं और एक-एक करके डाली जाती हैं, एक साथ नहीं।","reference.project-context#7#c":"निर्देशों को instructions.md में रखें। नोट्स को context.md में रखें। बाकी सब कुछ अपने आप Memory को कैप्चर करने दें।","features.unified-panel#title":"एकीकृत पैनल","features.unified-panel#0#p":"सरल शब्दों में: Ava जो कुछ भी करती है वह एक ही विंडो में रहता है, इसलिए आपको इसे ढूंढने के लिए टैब्स में कभी घूमना नहीं पड़ता।","features.unified-panel#1#p":"चैट, डैशबोर्ड, मेमोरी, कार्यों और जर्नल के लिए एक ही पैनल। विंडोओं के बीच संदर्भ बदलने की जरूरत नहीं। साइडबार बताता है कि आप क्या देख रहे हैं; मुख्य क्षेत्र उससे मिलान करने के लिए बदलता है।","features.unified-panel#2#p":"जब आप नेविगेट करके दूर जाते हैं तो बातचीत की स्थिति बना रहती है — मेमोरी खोलें, एक कार्य जांचें, फिर वापस आएँ। चैट अभी भी वहां है, अगर Ava अभी भी चल रही है तो स्ट्रीमिंग भी जारी है।","features.unified-panel#3#c":"एकीकृत पैनल एक एक्सटेंशन और IDE अवधारणा है। वेब सतह ब्राउज़र टैब्स का उपयोग करती है।","features.knowledge-packs#title":"ज्ञान पैकेट","features.knowledge-packs#0#p":"सरल शब्दों में: Ava को अपने दस्तावेज़ों का एक फोल्डर दें, और वह आपके सवालों का जवाब देने के लिए उनसे पढ़ सकती है। एक \"ज्ञान पैकेट\" बस उस फाइलों के बंडल को कहते हैं — वह संदर्भ सामग्री जिस पर उसे हवाला देना अनुमति है।","features.knowledge-packs#1#p":"संदर्भ सामग्री (specs, RFCs, मीटिंग नोट्स, API docs) का एक डायरेक्टरी एक ज्ञान पैकेट में डालें। जब बातचीत उस विषय को छूती है तो Ava प्रासंगिक हिस्सों को संदर्भ में खींच सकती है।","features.knowledge-packs#2#p":"पैकेट स्थानीय रूप से इंडेक्स किए जाते हैं। पुनःप्राप्ति अर्थ के आधार पर होती है — Ava सही दस्तावेज़ नाम से नहीं, बल्कि अर्थ से ढूंढती है। (\"Semantic\" का मतलब है कि वह इस बात पर मैच करती है कि दस्तावेज़ किस बारे में है, इसलिए आपको सटीक शब्दों या फ़ाइल का नाम याद रखने की जरूरत नहीं है।) पैकेट टीम के साथ साझा किए जा सकते हैं या निजी रखे जा सकते हैं।","troubleshooting.common-errors#title":"सामान्य त्रुटियाँ","troubleshooting.common-errors#0#p":"अधिकांश त्रुटियों का कारण छोटा और स्पष्ट होता है। यहाँ कुछ सामान्य त्रुटियाँ और उन्हें ठीक करने के तरीके दिए गए हैं। अगर शब्दावली तकनीकी लगती है तो चिंता न करें — नीचे दिया गया हर बिंदु बताता है कि आप वास्तव में क्या देख रहे हैं और बिल्कुल क्या करना है।","troubleshooting.common-errors#1#h":"मॉडल प्रतिक्रिया नहीं दे रहा","troubleshooting.common-errors#2#p":"आप क्या देखते हैं: Ava चुप हो जाती है और जवाब नहीं देती।","troubleshooting.common-errors#3#p":"चैट हेडर में स्टेटस इंडिकेटर को चेक करें। अगर यह \"connecting\" कहता है, तो आपका प्रोवाइडर (AI सेवा जिससे Ava बात कर रही है) उपलब्ध है लेकिन धीमी है — उसे तीस सेकंड दें। अगर यह \"unavailable\" कहता है, तो Ava अपने आप अगले मॉडल पर स्विच कर गई (उसने बैकअप मॉडल का उपयोग किया)। अगर कुछ भी नहीं दिख रहा, तो Settings में अपना API key सत्यापित करें और कनेक्शन टेस्ट करें। (एक API key वह निजी पासवर्ड है जो Ava को भुगतान वाली AI सेवा का उपयोग करने की अनुमति देता है।)","troubleshooting.common-errors#4#h":"टूल कॉल विफल","troubleshooting.common-errors#5#p":"आप क्या देखते हैं: Ava के एक कदम (एक \"tool call\" — उसका फ़ाइल पढ़ना, कमांड चलाना, आदि) पूरा होने के बजाय लाल त्रुटि दिखाता है।","troubleshooting.common-errors#6#p":"त्रुटि देखने के लिए विफल टूल कॉल पर क्लिक करें। सामान्य कारण: उसने आपके प्रोजेक्ट फोल्डर के बाहर किसी फ़ाइल को छूने की कोशिश की, जो आपकी सुरक्षा के लिए जानबूझकर रोका गया है (इस गार्ड को \"path traversal\" प्रोटेक्शन कहा जाता है — यह उसे उस फोल्डर के बाहर घूमने से रोकता है जहाँ आप काम कर रहे हैं); या तो एक कमांड जिसे अलग फोल्डर में चलाना होगा; या कोई फ़ाइल जो Ava ने पिछली बार देखने के बाद हिल गई है। उसे बताएं कि क्या गलत हुआ — वह सुधार के साथ फिर से कोशिश करेगी।","troubleshooting.common-errors#7#h":"याददाश्त याद नहीं कर पा रही","troubleshooting.common-errors#8#p":"आप क्या देखते हैं: Ava कुछ ऐसा नहीं ढूंढ पा रही जिसे आपको यकीन है कि उसे याद रखना चाहिए था।","troubleshooting.common-errors#9#p":"याददाश्त अर्थ के आधार पर काम करती है, शब्दों के सटीक मिलान से नहीं (इसी को \"semantic\" कहते हैं)। इसलिए \"What did I decide about auth?\" बेहतर काम करता है \"find my auth decision\" की तुलना में। अगर याददाश्त जरूर वहां है लेकिन दिख नहीं रही, तो मेमोरी ब्राउज़र खोलें और सर्च करें — अगर वह वहां नहीं है, तो वह पहले ही सेव नहीं हुई थी।","troubleshooting.common-errors#10#h":"साइन-इन लूप","troubleshooting.common-errors#11#p":"आप क्या देखते हैं: आप साइन इन करते हैं, लेकिन Ava बार-बार आपसे दोबारा साइन इन करने को कहती है — एक लूप जो आपको कभी भी अंदर जाने नहीं देता।","troubleshooting.common-errors#12#p":"समाधान यह है कि सेव किए गए साइन-इन विवरण साफ करें और नई शुरुआत करें: एक्सटेंशन में कमांड पैलेट से \"Ava: Sign Out\" चलाएं, IDE में Settings → Account → Sign Out का उपयोग करें, CLI में ~/.ava/auth.json फ़ाइल डिलीट करें (आपके होम डायरेक्ट्री में .ava नामक फोल्डर में एक छोटी साइन-इन फ़ाइल)। फिर दोबारा साइन इन करें।","troubleshooting.common-errors#13#h":"टोकन समाप्त","troubleshooting.common-errors#14#p":"आप क्या देखते हैं: एक संदेश कि इस महीने की मुफ्त उपयोग सीमा खत्म हो गई है। (\"Tokens\" AI उपयोग को मापने का तरीका है — \"exhausted\" का मतलब सिर्फ यह है कि आपने इस महीने की मुफ्त राशि पूरी कर दी है।)","troubleshooting.common-errors#15#p":"मुफ्त-स्तर का मासिक बजट हर महीने की 1 तारीख को रीसेट हो जाता है। तब तक, काम जारी रखने के लिए एक BYOK प्रोवाइडर पर स्विच करें (अपना API key उपयोग करें)। आपका खाता सक्रिय रहता है — केवल मुफ्त प्लेटफ़ॉर्म-प्रबंधित अनुरोध रुके हुए हैं।","troubleshooting.logs#title":"लॉग्स कहाँ होते हैं","troubleshooting.logs#0#p":"एक \"log\" सिर्फ एक डायरी है जो आपका कंप्यूटर रिकॉर्ड करता है कि क्या हुआ — जब कुछ खराब हो जाए और आपको (या सपोर्ट को) विवरण देखने की जरूरत हो, तो यह उपयोगी होता है।","troubleshooting.logs#1#p":"जब आपको पूरी तस्वीर चाहिए — किस टूल को कॉल किया गया, उसे क्या जानकारी मिली, AI सेवा ने क्या लौटाया — लॉग्स आपके कंप्यूटर पर ~/.ava/logs/ फोल्डर में सादे टेक्स्ट फ़ाइलें हैं (आपके होम डायरेक्ट्री में .ava नामक फोल्डर, जिसके अंदर logs फोल्डर है)।","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — प्रति-सत्र ट्रांसक्रिप्ट जिसमें टूल कॉल, स्ट्रीम्ड रिस्पॉन्स और त्रुटियाँ शामिल हैं।","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — VS Code एक्सटेंशन होस्ट लॉग। एक्टिवेशन विफलताएं, पैनल त्रुटियाँ।","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — डेस्कटॉप IDE लॉग। साइडकार प्रोसेस संदेश, Rust त्रुटियाँ।","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — CLI REPL लॉग।","troubleshooting.logs#3#p":"एक्सटेंशन में, कमांड पैलेट में \"Ava: Show Logs\" से संबंधित लॉग एडिटर टैब में खुलता है। IDE में, Settings → Diagnostics में एक \"Open Logs\" बटन है। CLI अपने लॉग को `ava logs --follow` के साथ देख सकता है।","features.office-suite#title":"Office Suite","features.office-suite#0#p":"रिपोर्ट, ईमेल, या दस्तावेज़ लिखवाने की जरूरत है? Ava उसे तैयार कर सकता है और आपको असली Word, Excel, या PDF फ़ाइल दे सकता है जिसे आप किसी अन्य फ़ाइल की तरह खोल और एडिट कर सकते हैं।","features.office-suite#1#p":"रिपोर्ट, ईमेल, और दस्तावेज़ — तैयार, फॉर्मेट किया गया, और नेटिव फॉर्मेट्स में निर्यात (.docx Word है, .xlsx Excel है, .pdf एक PDF है)।","features.office-suite#2#li0":"report_generate — कार्यों, जर्नल, मेमोरी, और प्रोजेक्ट स्थिति से जानकारी लेता एक संरचित .docx।","features.office-suite#2#li1":"email_draft — टोन-नियंत्रित ईमेल जो एक .docx फ़ाइल में होता है।","features.office-suite#2#li2":"document_manage — Word, Excel, PDF, CSV, Markdown के बीच बनाना, पढ़ना, एडिट करना, निर्यात करना।","features.office-suite#3#p":"जब Ava आपके नाम से लिख रहा हो तो उपयोगी — स्टेटस रिपोर्ट, शुरुआती प्रस्तुतियाँ, क्लाइंट अपडेट। .docx आपके प्रोजेक्ट में आ जाता है जहाँ आप इसे चमका सकते हैं।","features.dashboard-library#title":"डैशबोर्ड लाइब्रेरी","features.dashboard-library#0#p":"सरल शब्दों में: एक शेल्फ जो आपके और Ava के द्वारा बनाई गई और बातचीत की हर चीज़ को रखता है, ताकि कुछ भी खो न जाए।","features.dashboard-library#1#p":"वह सब कुछ देखने योग्य दृश्य जो Ava ने आपके साथ तैयार किया — जनरेट की गई छवियाँ, वीडियो, ऑडियो, दस्तावेज़ — आपके संवाद, मेमोरी और कार्यों के साथ। पिछले हफ्ते आपने जो कुछ बना था, वह यहीं मिल जाएगा।","features.document-preview#title":"दस्तावेज़ पूर्वावलोकन","features.document-preview#0#p":"सरल शब्दों में: एक अलग प्रोग्राम खोलने के बिना, वहीं रहकर दस्तावेज़ के अंदर झांकें।","features.document-preview#1#p":"अपने प्रोजेक्ट में Word डॉक, Excel शीट, PDF, CSV, HTML, या Markdown फ़ाइल पर राइट-क्लिक करें — एडिटर से बाहर न निकलकर उसका इंलाइन पूर्वावलोकन करें। Ava द्वारा जनरेट किए गए रेफरेंस सामग्री या सहयोगी द्वारा डाली गई फ़ाइलों को पढ़ने के लिए उपयोगी।","features.daily-briefing#title":"दैनिक ब्रीफिंग","features.daily-briefing#0#p":"सरल शब्दों में: हर सुबह एक छोटा 'आप कहाँ रुके थे' संदेश, ताकि आप सब कुछ फिर से पढ़े बिना काम शुरू कर सकें।","features.daily-briefing#1#p":"सुबह का सारांश: कल का जर्नल, खुले कार्य, प्रोजेक्ट स्थिति, और Ava द्वारा सेट किए गए कोई भी अनुस्मारक। वैकल्पिक — सेटिंग्स में इसे चालू करें।","features.daily-briefing#2#p":"ब्रीफिंग प्रासंगिक संदर्भ लाने के लिए मेमोरी का उपयोग करती है (\"पिछली बार जब आपने auth flow पर काम किया था, तो आपने नोट किया था कि आप refresh token strategy को दोबारा देखना चाहते थे\")। यह समाचार फ़ीड नहीं है — एक केंद्रित अपडेट है।","troubleshooting.logs#4#c":"लॉग्स में Ava द्वारा सत्र के दौरान पढ़ी गई प्रोजेक्ट फाइलों के कुछ हिस्से शामिल हो सकते हैं। शेयर करने से पहले जरूर देख लें।","troubleshooting.support-request#title":"सहायता अनुरोध भेजना","troubleshooting.support-request#0#p":"सीधे शब्दों में: अगर कुछ ठीक नहीं है और ऊपर बताए गए उपाय काम नहीं आए, तो हमें बताएं। सबसे आसान तरीका है Ava से ही कहना कि वह आपके लिए यह कर दे।","troubleshooting.support-request#1#p":"अगर कोई समस्या आम त्रुटियों में शामिल नहीं है, तो एक सहायता टिकट फाइल करें (सहायता टीम से मदद मांगें)। आप इसे Ava के अंदर (कोई फॉर्म भरने की जरूरत नहीं) या वेबसाइट पर कर सकते हैं।","troubleshooting.support-request#2#h":"Ava के अंदर से","troubleshooting.support-request#3#p":"उसे फाइल करने को कहें। \"Ava, क्या आप इसके बारे में एक सहायता टिकट फाइल कर सकती हैं?\" वह support_request कॉल करती है, संबंधित सत्र संदर्भ (क्रेडेंशियल छिपाकर) जोड़ती है और भेज देती है। यह सबसे तेज़ तरीका है।","troubleshooting.support-request#4#h":"वेबसाइट से","troubleshooting.support-request#5#p":"ava-supernova.com/support पर जाएं। एक श्रेणी चुनें (bug, feature, account, security, general) और बताएं कि क्या हुआ था। एक कार्य दिवस के भीतर जवाब मिल जाएगा।","troubleshooting.support-request#6#h":"क्या शामिल करें","troubleshooting.support-request#7#li0":"आप क्या करने की कोशिश कर रहे थे।","troubleshooting.support-request#7#li1":"वास्तव में क्या हुआ।","troubleshooting.support-request#7#li2":"कौन सा प्लेटफॉर्म (extension, IDE, CLI, companion) और कौन सी वर्शन।","troubleshooting.support-request#7#li3":"कोई भी एरर मैसेज या लॉग का हिस्सा। पहले क्रेडेंशियल छिपा दें।","troubleshooting.security-disclosure#title":"सुरक्षा मुद्दों की रिपोर्ट करना","troubleshooting.security-disclosure#0#p":"सीधे शब्दों में: अगर आपको लगा है कि Ava को किसी तरह तोड़ा जा सकता है या गलत इस्तेमाल किया जा सकता है (एक \"vulnerability\" — सुरक्षा कमजोरी), तो कृपया पहले हमें निजी रूप से बताएं ताकि हम इसे ठीक कर सकें। यह पेज बताता है कि ऐसा कैसे करें।","troubleshooting.security-disclosure#1#p":"क्या आपको कोई vulnerability मिली? धन्यवाद। हम हर रिपोर्ट को गंभीरता से लेते हैं और किसी सार्वजनिक खुलासे से पहले (समस्या को सार्वजनिक रूप से घोषित करने से पहले) आपकी मदद से इसे ठीक करते हैं।","troubleshooting.security-disclosure#2#h":"रिपोर्ट कैसे करें","troubleshooting.security-disclosure#3#li0":"security@ava-supernova.com पर ईमेल करें जिसमें विवरण, पुनः बनाने के चरण, और आपकी पसंदीदा खुलासे की समयसीमा हो।","troubleshooting.security-disclosure#3#li1":"या \"security\" श्रेणी के साथ एक सहायता टिकट फाइल करें — वही प्राथमिकता सूची।","troubleshooting.security-disclosure#3#li2":"हम 24 घंटों के भीतर जवाब देते हैं।","troubleshooting.security-disclosure#4#h":"हमारी प्रतिबद्धताएं","troubleshooting.security-disclosure#5#li0":"समन्वित खुलासा — हम कुछ भी सार्वजनिक करने से पहले आपसे समयसीमा पर सहमत होते हैं। डिफ़ॉल्ट 90 दिन होता है।","troubleshooting.security-disclosure#5#li1":"क्रेडिट — आपकी पहचान सुधार नोट्स में दी जाएगी, जब तक कि आप गोपनीयता नहीं चाहते।","troubleshooting.security-disclosure#5#li2":"कोई कानूनी कार्रवाई नहीं — ईमानदार अनुसंधान का स्वागत है। हम आपके खिलाफ वकील नहीं भेजेंगे।","troubleshooting.security-disclosure#6#c":"ava-supernova.com/security पर सुरक्षा पेज में पूरी जानकारी है — आर्किटेक्चर गारंटी, रेडैक्टर, और अनुमति नियंत्रण।","features.workflows#title":"कार्यप्रवाह","features.workflows#0#p":"सरल शब्दों में: Ava को एक रूटीन सिखाएं जो आप बार-बार करते हैं, उसे एक नाम दें, और वह इसे जरूरत पड़ने पर फिर से चला सकती है। एक \"वर्कफ़्लो\" बस वही सेव की गई रूटीन है — Ava द्वारा आपके लिए दोहराए जाने वाले कदमों का सेट।","features.workflows#1#p":"उन कदमों का अनुक्रम सेव करें जो आप बार-बार दोहराते हैं — PR review → tests run → release notes write → email draft। एक वर्कफ़्लो एक पुनः उपयोग योग्य योजना है जिसे Ava अलग-अलग इनपुट्स के साथ फिर से चला सकती है।","features.workflows#2#p":"वर्कफ़्लो प्रोजेक्ट के अनुसार .ava/workflows/ फोल्डर में स्टोर होते हैं। उन्हें अपनी टीम के साथ शेयर करें डायरेक्टरी को commit करके (इसे अपने साझा प्रोजेक्ट में सेव करके ताकि सहकर्मी भी इसे प्राप्त कर सकें)।","features.events#title":"घटनाएं और सूचनाएं","features.events#0#p":"सरल शब्दों में: जब Ava काम कर रही होती है तो आपको उसकी क्या कर रही है का साफ़ स्टेप-बाय-स्टेप लिस्ट मिलता है, और एक पिंग जब लंबी जॉब खत्म हो जाती है ताकि आप दूर जा सकें।","features.events#1#p":"जब Ava चल रही होती है तो आपको टेक्स्ट की दीवार नहीं, बल्कि संरचित अपडेट्स दिखते हैं। हर टूल कॉल, हर पर्सनालिटी हस्तांतरण, हर स्ट्रीम्ड डेल्टा UI में एक अलग घटना है — विस्तार के लिए विस्तारित, अवलोकन के लिए संक्षिप्त।","features.events#2#p":"बैकग्राउंड रन OS-लेवल नोटिफिकेशन भेजते हैं जब वे पूरा हो जाते हैं। आप लंबी बिल्ड के दौरान दूर जा सकते हैं और Ava बताएगी जब यह खत्म हो जाए।","features.personality#title":"पर्सनालिटी डिज़ाइनर","features.personality#0#p":"सरल शब्दों में: Ava आपके साथ कैसे बात करती है उसे सेट करें — बातचीत करने वाली या संक्षिप्त, औपचारिक या अनौपचारिक, ज्यादा मज़ाक या कम — ताकि वह वैसी लगे जैसी आप पसंद करते हैं।","features.personality#1#p":"Ava के बोलने का अंदाज़ तय करें। टोन, ऊर्जा, विस्तार (वो कितना बोलती है), औपचारिकता, हास्य। स्लाइडर और प्रीसेट्स — संक्षिप्त इंजीनियर, गर्मजोशी वाला मेंटर, सूखे सहकर्मी, या आपका अपना मिश्रण।","features.personality#2#p":"पर्सनालिटी वाक्यों को प्रभावित करती है, क्षमता को नहीं। वह वही टूल्स चलाती है और वही अनुमति नियमों का पालन करती है। उसका नाम Ava पर लॉक है — यह बात निश्चित है।","features.release-notes#title":"रिलीज़ नोट्स","features.release-notes#0#p":"सरल शब्दों में: हर अपडेट में क्या नया है और क्या ठीक किया गया इसकी चलती लिस्ट, ताकि आप देख सकें कि क्या बदला।","features.release-notes#1#p":"ऐप के अंदर का चेंजलॉग (चेंजलॉग परिवर्तनों का इतिहास है)। हर शिप्ड वर्जन अपनी हाइलाइट्स, बग फिक्स, और ब्रेकिंग परिवर्तन (परिवर्तन जिनके लिए आपको कुछ का उपयोग करने का तरीका समायोजित करना पड़ सकता है) के साथ। वेब पृष्ठ public version ava-supernova.com/releases पर बनाए रखता है।","concepts.memory#1#p":"Ava की एक स्थायी मेमोरी है (\"persistent\" का मतलब है कि यह एप बंद करने के बाद भी रहती है) जो कन्वर्सेशन, प्रोजेक्ट्स और मशीनों के बीच टिकी रहती है अगर आप सिंक चालू करते हैं (सिंक आपके डिवाइसों के बीच आपकी मेमोरी कॉपी करता है)। यह चैट लॉग नहीं है। यह एक संरचित, खोजने योग्य समझ है कि आप कौन हैं, आपको क्या पसंद है, और आपने क्या तय किया है।","concepts.memory#2#h":"पाँच परतें","concepts.memory#3#li0":"Extract — हर संदेश से रियल-टाइम में कैप्चर किए गए मुख्य तथ्य।","concepts.memory#3#li1":"Reflect — अर्थपूर्ण सत्रों के अंत में गहरा विश्लेषण चलता है। पैटर्न, विषय, विरोधाभास।","concepts.memory#3#li2":"Accumulate — सुधार और प्राथमिकताएं हफ्तों और महीनों में जुड़ती जाती हैं।","concepts.memory#3#li3":"Analyse — ग्राफ इंजन संबंधित मेमोरियों को जोड़ता है और नई जानकारी पुरानी के साथ टकराती है तो विरोधाभास दिखाता है।","concepts.memory#3#li4":"Consolidate — समान मेमोरिया मिल जाते हैं; पुराने हटा दिए जाते हैं। समय के साथ मेमोरी तेज़ होती है, शोर वाली नहीं।","concepts.memory#4#c":"ऊपर बताई गई पाँच परतें अपने आप चलती हैं — आपको इनका प्रबंधन कभी नहीं करना पड़ता। ये इसलिए हैं ताकि आप देख सकें कि मेमोरी वाकई समय के साथ बेहतर होती है, बल्कि कचरे के ढेर में नहीं बदलती।","concepts.memory#5#h":"Recall","concepts.memory#6#p":"जब आप कोई सवाल पूछते हैं, Ava मेमोरी का मतलब के आधार पर खोजती है (\"semantic search\" — यह समझती है कि आप क्या कहना चाह रहे हैं, इसलिए वह सही मेमोरी ढूंढ लेती है भले ही आप अलग तरह से कहें), न कि सिर्फ शब्दों को मिलाकर। मोड-विशिष्ट फिल्टर साथ में चलते हैं — Chat mode व्यक्तिगत संदर्भ खींचता है, Work mode प्रोजेक्ट निर्णय और code patterns खींचता है।","concepts.memory#7#c":"मेमोरी उपयोगकर्ता और प्रोजेक्ट के अनुसार सीमित है (आपकी मेमोरिया आपकी होती हैं, व्यक्ति और प्रोजेक्ट द्वारा अलग रखी जाती हैं)। राज़ और क्रेडेंशियल्स (पासवर्ड, keys) सेव बाउंड्री पर ब्लॉक होते हैं — वे कभी मेमोरी में नहीं पहुंच सकते।","start.what#title":"Ava क्या है?","start.what#0#p":"Ava एक ऐसा AI है जो वाकई काम करता है — बस बातें नहीं करता। वह आपके लिए ऐप बनाएगी, दस्तावेज़ लिखेगी, आपको कुछ नया सिखाएगी, लोगो डिज़ाइन करेगी, या उस सारी प्रशासनिक काम को संभाल लेगी जिसे आप टाल रहे हैं। और वह आपको याद रखती है: आप किस पर काम कर रहे हैं, आप चीज़ों को कैसे पसंद करते हैं, पिछले हफ्ते आपने क्या माँगा था।","start.what#1#p":"Ava एक ही है, और वह जहाँ भी आप काम करते हैं वहाँ काम करती है — आपके कोड एडिटर में, डेस्कटॉप ऐप के रूप में, आपके फ़ोन पर, या टर्मिनल में। वही मेमोरी, वही शख्सियत, हर जगह।","start.what#2#h":"वह अलग क्यों है?","start.what#3#li0":"डिफ़ॉल्ट रूप से आपकी। आपका काम आपकी मशीन पर ही रहता है। कोई ट्रैकिंग, कोई टेलीमेट्री — कभी नहीं।","start.what#3#li1":"सबके लिए खुला। Ava की हर लाइन सार्वजनिक है। भरोसा करने के लिए कुछ छुपा नहीं है।","start.what#3#li2":"शुरुआत मुफ़्त है। हर महीने 300 क्रेडिट, कार्ड की जरूरत नहीं, कोई चूक नहीं — या अपने खुद के AI कीज़ लगाएं और हमें बिल्कुल कुछ न दें।","start.what#3#li3":"सिखाना हमेशा मुफ़्त है। सीखने का कोई दाम नहीं होना चाहिए।","start.what#4#p":"पहले कभी कोड नहीं लिखा? अगली पेज सिर्फ आपके लिए लिखा गया है। तकनीकी जानकार हैं? आगे बढ़ जाएं — वह पीछे नहीं रहेगी।","start.what#deeper#0#h":"Ava कहाँ रहती है","start.what#deeper#1#li0":"VS Code एक्सटेंशन — आपके एडिटर के पास Ava: एक चैट पैनल, एक डैशबोर्ड, और बदलाव होने से पहले ही इन्हें दिखाया जाता है।","start.what#deeper#1#li1":"Desktop IDE — एक अलग ऐप जिसमें सब कुछ एक खिड़की में है। इसमें डेस्कटॉप कंट्रोल जुड़ता है (ऐप्स खोलना, क्लिक करना, आपके लिए टाइप करना)।","start.what#deeper#1#li2":"Companion — एक मोबाइल ऐप जब आप अपने डेस्क से दूर होते हैं: कार्य, जर्नल, मेमोरी, तेज़ चैट।","start.what#deeper#1#li3":"CLI — Ava आपकी टर्मिनल में, उन लोगों के लिए जो वहीं रहते हैं।","start.what#deeper#2#h":"वह कैसे काम करती है, संक्षेप में","start.what#deeper#3#p":"Ava काम के अनुसार दिमाग बदलती है (इसे मोड कहते हैं), मुश्किल काम के लिए चुपचाप विशेषज्ञ मददगारों की छोटी टीम चलाती है, और हर कदम के लिए सबसे अच्छा AI मॉडल अपने आप चुनती है। आप इसे कभी मैनेज नहीं करते। Core concepts सेक्शन में पूरा टूर है जब भी आप जिज्ञासु हों।","start.first-five#title":"Ava के साथ आपका पहला काम","start.first-five#0#p":"Ava को पाकर सबसे तेज़ तरीका है कि उसे कुछ असली मांगें और देखें वह यह करती है। पढ़ने के लिए सेटअप नहीं, पहले कुछ सीखने की जरूरत नहीं — बस साधारण शब्दों में बताएं कि आप क्या चाहते हैं।","start.first-five#1#h":"अब यह आजमाएं","start.first-five#2#li0":"चैट खोलें।","start.first-five#2#li1":"कुछ ऐसा टाइप करें जो आप वाकई चाहते हैं। कोशिश करें \"explain what this project does\", या \"add a button that clears the form\"।","start.first-five#2#li2":"Ava आपको बताती है वह क्या करने वाली है — और रुक जाती है।","start.first-five#2#li3":"खुश हैं? हाँ कहें। देखें वह यह करती है।","start.first-five#3#p":"यही पूरा रिदम है: आप पूछते हैं, वह आपको योजना दिखाती है, आप स्वीकार करते हैं, वह करती है। वह बिना आपको पहले दिखाए कुछ भी नहीं बदलती — ताकि आप कोशिश करते समय कुछ भी खराब न कर सकें।","start.first-five#4#h":"कुछ ऐसे काम जो पूछने लायक हैं","start.first-five#5#li0":"एक सवाल — 'मेरी पेज खाली क्यों है?', 'इस फ़ाइल का काम क्या है?'","start.first-five#5#li1":"कुछ बनाना — 'मुझे एक साधारण टू-डू लिस्ट पेज बना दो।'","start.first-five#5#li2":"कुछ सीखने के लिए — 'मुझे शुरुआत से Python सिखाओ।' (हमेशा निःशुल्क।)","start.first-five#5#li3":"एक दस्तावेज़ — 'मुझे एक पन्ने की परियोजना प्रस्ताव लिख दो।' वह आपको Word फ़ाइल या PDF दे देगी।","start.first-five#6#c":"नहीं पता क्या लिखना है? उसे एक समझदार दोस्त की तरह बातचीत करें। सादे शब्द ही बिल्कुल सही हैं — शुरुआत करने के लिए आपको तकनीकी शब्दों की कभी जरूरत नहीं पड़ती।","start.first-five#deeper#0#p":"वह साधारण लूप पर्दे के पीछे काफी कुछ कर रहा होता है। Ava का इस्तेमाल करने के लिए आपको इन सबकी जरूरत नहीं — लेकिन अगर आप जानना चाहते हैं तो यहाँ असल में क्या हो रहा है।","start.first-five#deeper#1#h":"उपकरण और अनुमति","start.first-five#deeper#2#p":"जब Ava किसी फ़ाइल को पढ़ती है, कमांड चलाती है, या कोड में बदलाव करती है, तो हर एक को एक 'tool call' माना जाता है। वह आपके फ़ाइलों या सिस्टम को छूने से पहले हमेशा पूछती है — कि वह कितनी बार पूछेगी, यह आपके 'permission mode' पर निर्भर करता है (हर बार पूछें, केवल जोखिम भरी चीजों के लिए पूछें, या बिना पूछे चलें)।","start.first-five#deeper#3#h":"मोड — उसकी मनोदशा","start.first-five#deeper#4#p":"Ava अलग-अलग मोड में काम करती है: एक विशिष्ट सोच और काम के हिसाब से सही उपकरण। आप चाहे तो पिकर से कभी भी बदल सकते हैं, या अपने संदेश की शुरुआत में एक प्रीफिक्स टाइप कर सकते हैं। कुल सात हैं।","start.first-five#deeper#6#h":"विशेषज्ञ और राउटिंग","start.first-five#deeper#7#p":"मुश्किल कामों पर Ava पर्दे के पीछे विशेषज्ञ सहायकों की एक छोटी टीम लगाती है (एक योजनाकार, एक जांचकर्ता, एक निर्माता) और हर कदम को उस मॉडल पर भेजती है जो उसमें सबसे बेहतर है। आप इसका कभी प्रबंधन नहीं करते — वह आपके लिए इसे समन्वित करती है।","start.local-vs-cloud#title":"लोकल बनाम क्लाउड, एक पैराग्राफ में","start.local-vs-cloud#0#p":"Ava जो कुछ भी करती है वह लोकल रहता है, जब तक आप स्पष्ट रूप से सहमति न दें। मेमोरी, कार्य, जर्नल, व्यक्तिगत सेटिंग्स — सभी आपके कंप्यूटर पर ~/.ava/ और .ava/ (प्रोजेक्ट के अनुसार) में सुरक्षित रहते हैं। वह आपके अनुरोध को चलाने के लिए HTTPS के जरिए मॉडल प्रोवाइडर्स से जुड़ती है, फिर वापस अपने घर लौट आती है। वह 'फोन होम' नहीं करती। वह टेलीमेट्री नहीं इकट्ठा करती। वह आपके कोड पर ट्रेनिंग नहीं करती।","start.local-vs-cloud#1#p":"अगर आप साइन इन करते हैं, तो आपको प्लेटफॉर्म-प्रबंधित मॉडल (Qwen, MiniMax) पर महीने में 300 मुफ्त क्रेडिट मिलते हैं और मशीनों के बीच मेमोरी और सेटिंग्स के लिए वैकल्पिक क्लाउड सिंक। सिंक हर फीचर के लिए अलग है, इसे कभी भी रद्द किया जा सकता है। अपना खुद का API key लाएं और Ava खाते के बिना पूरी तरह काम करती है।","start.local-vs-cloud#2#c":"नियम: लोकल पवित्र है। क्लाउड केवल पूरक है।","start.first-model#title":"क्या मुझे एक AI चुनना होगा?","start.first-model#0#p":"यहाँ राहत की बात है: आपको AI चुनने की जरूरत नहीं। Ava हर कदम के लिए सही मॉडल स्वचालित रूप से चुन लेती है, ताकि आपको अच्छे परिणाम मिलें बिना इसके बारे में ज्यादा सोचे।","start.first-model#1#p":"एकमात्र चीज जो आप चुन सकते हैं वह राउटिंग शैली है — और डिफ़ॉल्ट लगभग हर किसी के लिए सही है। आपको अन्य विकल्पों की जरूरत तभी पड़ती है जब कोई विशेष कारण हो।","start.first-model#2#h":"तीन शैलियां","start.first-model#3#li0":"Maestro — डिफ़ॉल्ट। स्थिर, विश्वसनीय, और भरोसेमंद। शक है? तो यह वही है।","start.first-model#3#li1":"Supernova — भारी और बहु-चरण वाले कामों के लिए, जहाँ काम के हर हिस्से पर एक अलग विशेषज्ञ लगाना फायदेमंद होता है।","start.first-model#3#li2":"Aurora — जब आपका डेटा यूरोपीय संघ (EU) में रहना जरूरी हो (सरकारी क्षेत्र, स्वास्थ्य सेवा, कठोर गोपनीयता)। यह पूरी तरह यूरोपीय, ओपन-वेट AI पर चलता है।","start.first-model#4#p":"चैट के ऊपर दिए गए मॉडल पिकर से कभी भी बदल सकते हैं। कोई भी चीज़ लॉक नहीं है।","start.first-model#5#c":"क्या आप खुद एक विशिष्ट मॉडल चलाना चाहते हैं? आप कर सकते हैं — 'मुझे विवरण दिखाएं' खोलें।","start.first-model#deeper#0#h":"हर स्टाइल में असल में क्या शामिल है","start.first-model#deeper#1#p":"Maestro — एक कंडक्टर (Qwen 3.6 Plus) हर कदम संभालता है। प्रोडक्शन-ट्यून्ड, साबित, और लागत की गणना पहले से पक्की।","start.first-model#deeper#2#p":"Supernova — एक फ्रंटियर कोऑर्डिनेटर (DeepSeek V4 Pro, 1.6T पैरामीटर्स / 49B एक्टिव, 1M कॉन्टेक्स्ट) हर उप-कार्य एक विशेषज्ञ को सौंपता है: हाई-वॉल्यूम बिल्ड्स के लिए V4 Flash, फॉलबैक के लिए Qwen 3.6 Plus, और विजन के लिए Qwen Omni।","start.first-model#deeper#3#p":"Aurora — सिर्फ Mistral, तीन टियर्स में: Mistral Large 3 (कोऑर्डिनेटर + भारी विशेषज्ञ), Mistral Medium 3.5 (128B डेंस, 256K कॉन्टेक्स्ट, नेटिव विजन, मॉडिफाइड-MIT ओपन वेट्स, 77.6% SWE-Bench Verified) बिल्डर + मिड-टियर + विजन + लॉन्ग-फॉर्म के लिए, और इंटेंट गेट पर Mistral Small 4। ओपन वेट्स शुरू से अंत तक, कभी भी EU इंफ्रास्ट्रक्चर से बाहर नहीं जाता।","start.first-model#deeper#4#h":"अपना मॉडल लाएं (BYOK)","start.first-model#deeper#5#p":"अपने खुद के AI खाते का उपयोग करना पसंद है? सेटिंग्स में अपना प्रोवाइडर की पेस्ट करें और आपको दोनों मिलेंगे — तीनों रूटिंग स्टाइल्स, साथ ही एकल मॉडल चुनने और पूरी तरह से रूटिंग छोड़ने का विकल्प। यह एक मजबूत प्राथमिकता, सख्त बजट, या किसी विशिष्ट मॉडल को टेस्ट करने के लिए उपयोगी है। पूर्ण प्रोवाइडर सूची रेफरेंस अनुभाग में है।","start.glossary#title":"सरल हिंदी शब्दावली","start.glossary#0#p":"Ava के आसपास जो शब्द आप देख सकते हैं, बिना किसी पूर्व ज्ञान के समझाया गया। आपको इसमें से कुछ भी याद रखने की जरूरत नहीं है — जब भी कोई शब्द आपको उलझन में डाले, वापस देखें।","start.glossary#1#th0":"शब्द","start.glossary#1#th1":"इसका असल मतलब क्या है","start.glossary#1#td0.0":"एजेंट","start.glossary#1#td0.1":"वह AI जो आपके लिए कार्रवाई कर सकता है — फ़ाइल पढ़ना, कमांड चलाना, वेब सर्च करना — सिर्फ चैट नहीं। Ava एक एजेंट है: वह चीज़ें करती है, आपकी सहमति से।","start.glossary#1#td1.0":"मॉडल","start.glossary#1#td1.1":"वह असली AI दिमाग जो सोचता है (Qwen, DeepSeek, Mistral, और अन्य)। अलग-अलग मॉडलों की अपनी ताकत होती है। आप आमतौर पर एक नहीं चुनते — Ava चुनती है।","start.glossary#1#td2.0":"मोड","start.glossary#1#td2.1":"Ava जिस मानसिकता में है। जैसे एक सहकर्मी टोपी बदल रहा हो: बिल्डर, राइटर, टीचर, प्लानर, दोस्त। आप मोड चुनते हैं; यह बदल देता है कि वह कैसे व्यवहार करती है। सात हैं।","start.glossary#1#td3.0":"पर्सोना / विशेषज्ञ","start.glossary#1#td3.1":"Ava पीछे चलने वाली मददगार भूमिकाएँ मुश्किल कामों के लिए — एक एक्सप्लोरर, एक प्लानर, एक फैक्ट-चेकर। एक छोटी विशेषज्ञ टीम की तरह सोचें। आप उनसे सीधे बात नहीं करते; Ava उनका समन्वय करती है।","start.glossary#1#td4.0":"रूटिंग","start.glossary#1#td4.1":"Ava तय करती है कि हर कदम के लिए कौन सा मॉडल उपयोग करें ताकि आपको अच्छे जवाब मिलें बिना ज्यादा खर्च किए। यह स्वचालित रूप से होता है — \\\"रूटिंग मोड\\\" बस कुल रणनीति चुनता है।","start.glossary#1#td5.0":"टूल","start.glossary#1#td5.1":"एक विशिष्ट क्रिया जो Ava ले सकती है — फ़ाइल पढ़ना, सर्च चलाना, ईमेल भेजना। एक \\\"टूल कॉल\\\" उसका एक का उपयोग करना है। वह किसी भी जोखिम भरी चीज़ से पहले अनुमति मांगती है।","start.glossary#1#td6.0":"टोकन","start.glossary#1#td6.1":"AI टेक्स्ट को कैसे मापती है — लगभग शब्द का ¾। मॉडल प्रति लाख टोकन के लिए दामदार होते हैं। ज्यादातर ऐसा कुछ जिसे आप नजरअंदाज कर सकते हैं।","start.glossary#1#td7.0":"क्रेडिट","start.glossary#1#td7.1":"Ava की कार्रवाई की लागत मापने की सरल इकाई, ताकि आपको टोकन गणना करने की चिंता न हो। प्लान्स में हर महीने का एक बंडल मिलता है।","start.glossary#1#td8.0":"API कुंजी","start.glossary#1#td8.1":"यह एक गोपनीय पासवर्ड है जो सॉफ्टवेयर को आपके खाते पर किसी भुगतान वाली सेवा (जैसे AI मॉडल) का इस्तेमाल करने की अनुमति देता है। अगर आप अपना खुद का लाना चाहते हैं, तो ही आपको इसकी जरूरत होगी।","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"अपनी खुद की कुंजी लाएं।\" Ava के प्रबंधित एक्सेस के बजाय अपनी खुद की API कुंजी का उपयोग करना। वैकल्पिक — उन लोगों के लिए जो पहले से ही प्रदाता को सीधे भुगतान करते हैं।","start.glossary#1#td10.0":"Local-first","start.glossary#1#td10.1":"आपका डेटा डिफ़ॉल्ट रूप से आपके अपने कंप्यूटर पर रहता है। सिंक चालू करने तक कुछ भी अपलोड नहीं होता। \"स्थानीय डेटा पवित्र है।\"","start.glossary#1#td11.0":"अनुमति मोड","start.glossary#1#td11.1":"Ava चीज़ें करने से पहले कितनी सावधान रहती है — हर बार पूछें, केवल जोखिमपूर्ण कामों के लिए पूछें, या फिर बस आगे बढ़ना। स्तर आप तय करते हैं।","start.glossary#1#td12.0":"संदर्भ विंडो (Context window)","start.glossary#1#td12.1":"एक मॉडल एक साथ मन में कितना टेक्स्ट रख सकता है — इसकी छोटी अवधि की मेमोरी। \"1M context\" का मतलब लगभग एक लाख शब्द हैं। बड़ा = भूलने से पहले यह ज्यादा पढ़ सकता है।","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"एक फ़ाइल में क्या बदलाव होगा, उसका एक साथ-साथ दृश्य — एक तरफ पुराना, दूसरी तरफ नया — Ava कुछ भी बदलने से पहले दिखाया जाता है ताकि आप उसे मंजूरी दे सकें।","start.glossary#1#td14.0":"रिपॉजिटरी (repo)","start.glossary#1#td14.1":"परिवर्तनों के लिए ट्रैक किया गया प्रोजेक्ट फ़ोल्डर, आमतौर पर Git के साथ। अगर यह अभी तक आपके लिए कुछ नहीं कहता, तो यह बस \"वह फ़ोल्डर है जहाँ मेरा प्रोजेक्ट रहता है।\"","start.glossary#1#td15.0":"प्रॉम्प्ट","start.glossary#1#td15.1":"वह जो आप AI को टाइप करते हैं — आपका सवाल या निर्देश।","start.glossary#2#c":"अभी भी किसी शब्द पर फंसे हैं? चैट मोड में Ava से पूछें — \"X का मतलब क्या है?\" — और वह आपके स्तर के अनुसार इसे समझाएगी।","models.routing#title":"रूटिंग — Ava कैसे चुनती है मॉडल","models.routing#0#p":"यहाँ संक्षिप्त संस्करण है: आपको कभी भी यह नहीं चुनना पड़ता कि किस AI मॉडल का उपयोग करें। Ava आपके लिए यह करती है, हर काम के हिस्से के लिए सबसे अच्छा उपकरण चुनकर — जैसे एक अच्छा मैनेजर सही व्यक्ति को सही कार्य सौंपता है।","models.routing#1#p":"आप तीन शैलियों में से एक चुनते हैं — Maestro, Supernova, या Aurora — और Ava हर काम का टुकड़ा उस मॉडल को भेजती है जो उसे सबसे अच्छा संभालता है। Maestro डिफ़ॉल्ट है, यह हर प्लान पर चल रहा है, और यह लगभग सभी के लिए एक अच्छा विकल्प है।","models.routing#2#h":"रूटिंग क्यों करें?","models.routing#3#p":"हर कदम पर सही मॉडल लगाने का खर्च एक बड़े महंगे मॉडल पर सब कुछ चलाने से कम होता है — और बेहतर परिणाम देता है, क्योंकि हर मॉडल वही करता है जिसमें वह सबसे अच्छा है। आपको स्थिर लागत और उच्च गुणवत्ता मिलती है बिना यह जाने कि कौन सा मॉडल कौन सा है।","models.routing#4#c":"तीनों शैलियाँ प्लेटफ़ॉर्म क्रेडिट और आपके अपने कुंजियों पर काम करती हैं। अपने कुंजी के साथ आप रूटिंग को छोड़ सकते हैं और एकल मॉडल को सीधे चला सकते हैं। पूरी फ्लीट विवरण \"मुझे विवरण दिखाएं\" के नीचे है।","models.routing#deeper#0#c":"नीचे दिए गए \"B\" नंबर अरबों पैरामीटर हैं — लगभग मॉडल के दिमाग का आकार कितना है; बड़ा आमतौर पर समझदार लेकिन धीमा और महंगा होता है। यह अंदरूनी विवरण है; Ava का उपयोग करने के लिए आपको इसकी कभी जरूरत नहीं होती।","models.routing#deeper#1#h":"एक साथ","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"समन्वयक","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B सक्रिय, 1M संदर्भ)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B सक्रिय, 262K संदर्भ)","models.routing#deeper#2#td1.0":"बिल्डर","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (समन्वयक का उपयोग करता है)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B घनत्व, 256K संदर्भ)","models.routing#deeper#2#td2.0":"मध्यम स्तर के विशेषज्ञ","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (कोड समीक्षक, तथ्य जांचक, अनुसंधान, स्कैनर, सुरक्षा सत्यापक, आदि)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (आर्किटेक्ट, सत्यापक, क्रमबद्धकर्ता, ट्यूटर, रिपोर्टर, आदि)","models.routing#deeper#2#td3.0":"हल्का स्तर / उद्देश्य नियंत्रण","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (स्कौट, सत्यापक, क्रमबद्धकर्ता, चुनौती देने वाला, एकीकृत करने वाला)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"गहन विशेषज्ञ","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (शोधकर्ता, चुनौती देने वाला, CVE शोधकर्ता, विचारक, तथ्य जांचक)","credits.overview#8#li4":"ऑर्केस्ट्रेशन — 10 क्रेडिट्स। पूर्ण पर्सोना पाइपलाइन शुरू करें (कंडक्टर + कई पर्सोना वाले कार्य)।","credits.overview#8#li5":"इमेज जनरेशन — 12 क्रेडिट्स। हेलुओ इमेज-01 क्रिएटिव स्टूडियो के जरिए।","credits.overview#8#li6":"वीडियो जनरेशन — 150 क्रेडिट्स। हेलुओ 02 प्रो 1080p 6 सेकंड का क्लिप।","credits.overview#8#li7":"वॉइस जनरेशन — 10 क्रेडिट्स। स्पीच 2.8 एचडी सिंथेसिस।","credits.overview#8#li8":"संगीत जनरेशन — 50 क्रेडिट्स। मिनीमैक्स म्यूजिक 2.5/2.6।","credits.overview#8#li9":"बैकग्राउंड रीमूवल — 2 क्रेडिट्स।","credits.overview#9#h":"प्रति-मॉडल गुणक","credits.overview#10#p":"यह जानकारी जिज्ञासु लोगों के लिए है — Ava का उपयोग करने के लिए आपको इसकी ज़रूरत नहीं है। मल्टीप्लायर बस क्रेडिट लागत को बढ़ाता या घटाता है, यह देखते हुए कि किसी एक्शन के पीछे वाला मॉडल कितना महंगा है, इसलिए भारी मॉडल्स थोड़े ज्यादा खर्च होते हैं। (\\\"नेट मार्जिन\\\" वह हिस्सा है जो परियोजना अपने खर्चों की चुकाई के बाद रखती है — हम इसे कम रखते हैं ताकि फायदा सीधे आप तक पहुंचे।)","credits.overview#11#p":"भारी मॉडल्स एक्शन लागत को गुणा करते हैं ताकि क्रेडिट वास्तविक खर्च को दर्शाएं, न कि एक निश्चित दर में। यह ~55% नेट मार्जिन के लिए सेट किया गया है।","credits.overview#12#li0":"0.6× — मिस्ट्रल स्मॉल 4 (ऑरोरा का विशेषज्ञ स्थान)। 1 से कम क्योंकि मिस्ट्रल स्मॉल 4, क्वेन 3.6 प्लस आधार से सस्ता है।","credits.overview#12#li1":"1.0× — क्वेन 3.5 फ्लैश, क्वेन ओमी फ्लैश, डीपसीक V4 फ्लैश, मिनीमैक्स। आधार दर।","credits.overview#12#li2":"1.2× — क्वेन 3.5 प्लस, क्वेन 3.5 ओमी प्लस।","credits.overview#12#li3":"1.4× — मिस्ट्रल लार्ज 3 (ऑरोरा समन्वयक)। क्वेन 3.6 प्लस आधार के लगभग बराबर।","credits.overview#12#li4":"1.5× — क्वेन 3.6 प्लस (माエスト्रो समन्वयक)।","credits.overview#12#li5":"6.0× — डीपसीक V4 प्रो (सुपरनोवा समन्वयक + भारी विशेषज्ञ)। सार्वजनिक V4 प्रो दर पर मार्जिन संतुलन वापस लाने के लिए 5.0× से फिर से सेट किया गया।","credits.overview#13#c":"एंथ्रोपिक मॉडल्स (क्लॉड ओपस / सोनेट / हाइकु) क्रेडिट बिलिंग पूरी तरह छोड़ देते हैं — ये केवल BYOK हैं और आप सीधे एंथ्रोपिक को भुगतान करते हैं। अपनी कुंजी के साथ किसी अन्य BYOK प्रदाता का उपयोग करने पर भी यही नियम लागू होता है।","credits.overview#14#h":"BYOK और क्रेडिट्स","credits.overview#15#p":"BYOK (\\\"अपनी खुद की कुंजी लाएं\\\" — आप अपने खाते के साथ एक AI प्रदाता और एक कुंजी प्रदान करते हैं, जो एक निजी पासवर्ड है जो सॉफ्टवेयर को उस भुगतान किए गए खाते का उपयोग करने देता है) उन लोगों के लिए है जो पहले से ही सीधे एक AI प्रदाता को भुगतान करते हैं। यदि आप ऐसा नहीं हैं, तो आप इस अनुभाग को पूरी तरह अनदेखा कर सकते हैं।","credits.overview#16#p":"अपनी-खुद-की-कुंजी अनुरोध पूरी तरह से प्लेटफॉर्म इंफ्रास्ट्रक्चर को छोड़ देते हैं — कॉल सीधे Ava से प्रदाता तक जाती है, आप प्रदाता को भुगतान करते हैं, कोई क्रेडिट खर्च नहीं होते। एकमात्र अपवाद तब है जब एक BYOK सेशन उप-कार्य के लिए प्रबंधित स्तर का पर्सोना शुरू करता है; क्रेडिट कटौती अभी भी लागू होती है क्योंकि Ava का ऑर्केस्ट्रेशन सतह का उपयोग किया जा रहा है।","credits.overview#17#h":"अपना बैलेंस कहाँ चेक करें","credits.overview#18#li0":"एक्सटेंशन — सेटिंग्स → खाता, या चैट हेडर में क्रेडिट पिल।","credits.overview#18#li1":"IDE — खाता डैशबोर्ड टाइल वर्तमान बैलेंस और खर्च की दर दिखाता है।","credits.overview#18#li2":"वेब — ava-supernova.com/dashboard बैलेंस, इतिहास, और नवीकरण तिथि दिखाता है।","credits.overview#19#c":"लोकल-फर्स्ट: Ava बिना खाते के कस्टम मॉडल कार्ड पर काम करता है (ओलामा, एलएम स्टूडियो, vLLM, या कोई भी OpenAI-कम्पैटिबल एंडपॉइंट)। कोई क्रेडिट नहीं, कोई प्लेटफॉर्म टोकन नहीं — आपका मॉडल, आपकी मशीन, आपका बिल जीरो।","concepts.modes#title":"मोड्स — Ava की मन की स्थितियां","models.routing#deeper#2#td11.1":"रोज़ाना के काम, स्थिर लागत","models.routing#deeper#2#td11.2":"भारी बहु-चरण वाले काम, हर प्लान पर फ्रंटियर कोऑर्डिनेटर","models.routing#deeper#2#td11.3":"GDPR-कठोर, सरकारी क्षेत्र, स्वतंत्र यूरोपीय स्टैक","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"स्तर-अनुसार Qwen राउटिंग, हल्का प्रभाव। Qwen 3.6 Plus समन्वयक, बिल्डर, योजना, सुरक्षा, ब्रेनस्टॉर्म और लंबे कंटेंट वाले कामों का जिम्मा लेता है — जहाँ उसका 1M-कॉन्टेक्ट हाइब्रिड लिनियर-एटेंशन सबसे अच्छा काम करता है। Qwen 3.5 Flash चैट, इमेज जनरेशन ऑर्केस्ट्रेशन और ऊपर वाला इंटेंट गेट संभालता है, जहाँ इसकी $0.07/$0.26 की कीमत और तेज़ TTFT ज्यादा टोकन वाले कामों में जीत देती है। Qwen 3.5 Omni Plus विज़न इनपुट (Qwen 3.6 Plus में नेटिव विज़न नहीं है) संभालता है। Qwen 3.5 Plus लागत-संवेदनशील लॉन्ग-फॉर्म काम संभालता है। यदि प्राथमिक कोऑर्डिनेटर उपलब्ध न हो तो प्राथमिकता क्रम Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash के अनुसार चलता है।","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"बहुभाषी समूह। DeepSeek V4 Pro हर सबटास्क को उसके लिए सबसे उपयुक्त विशेषज्ञ को भेजता है: Qwen 3.6 Plus हर बिल्डर स्पॉन चलाता है, V4 Flash चैट और मध्य-स्तरीय समीक्षा/ऑडिट पर्सोना संभालता है, Qwen 3.5 Flash हल्के-स्तरीय वर्गीकरण काम संभालता है, Qwen 3.5 Omni Plus विज़न इनपुट संभालता है, Qwen 3.5 Omni Flash इमेज-जन टूल कॉल संयोजित करता है, Qwen 3.5 Plus लागत-संवेदनशील लॉन्ग-फॉर्म कंटेंट राइटर पर्सोना संभालता है। जहाँ ज़रूरी हो वहाँ फ्रंटियर तर्क, और टोकन वॉल्यूम के ज्यादा हिस्से पर फ्लैश-स्तरीय अर्थशास्त्र।","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"यूरोपीय AI स्टैक — डिज़ाइन के अनुसार स्वतंत्र। तीन स्तरों में केवल Mistral राउटिंग: Mistral Large 3 (675B/41B-एक्टिव स्पर्स MoE) समन्वयक भूमिका और गहरे ज्ञान वाले भारी विशेषज्ञ संभालता है — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — और लंबे कॉन्टेक्ट वाले कठिन काम जहाँ उसकी स्पर्स-MoE दक्षता जीतती है। Mistral Medium 3.5 — अप्रैल 2026 में जारी किया गया फ्लैगशिप, 128B डेंस, 256K कॉन्टेक्ट, शून्य से प्रशिक्षित विज़न एनकोडर, संशोधित-MIT ओपन वेट्स, 77.6% SWE-Bench वेरीफाइड — वास्तविक कार्य स्तर चलाता है: बिल्डर स्पॉन, मध्य-स्तरीय विशेषज्ञ (Architect, Verifier, Sequencer, Tutor, Reporter), विज़न इनपुट और लॉन्ग-फॉर्म लेखन। Mistral Small 4 इंटेंट गेट पर एकल भूमिका से बढ़कर अब चैट और इमेज-जन ऑर्केस्ट्रेशन भी संभालता है — इसकी $0.15/$0.60 की कीमत और कॉन्फ़िगर करने योग्य तर्क उच्च-वॉल्यूम कम-गहराई वाले राउट्स पर अपना खर्च निकालते हैं। ओपन वेट्स एंड टू एंड, कभी भी यूरोपीय बुनियादी ढांचे से बाहर नहीं जाता। Aurora जानबूझकर तब भी गैर-Mistral मॉडल पर राउट नहीं करता जब कोई उपलब्ध न हो; इसके बजाय राउटर एक त्रुटि दिखाता है — यही कारण है कि इसे \"Aurora\" कहा जाता है, न कि एक Mistral-फ्लेवर वाला Maestro।","credits.overview#title":"Ava क्रेडिट्स — बिलिंग कैसे काम करती है","credits.overview#0#p":"क्रेडिट्स सिर्फ यह गिनती हैं कि Ava आपका उपयोग कैसे करता है — जैसे फोन प्लान में मिनट। हर प्लान, निःशुल्क वाला भी, क्रेडिट्स के एक पूल के साथ आता है, और Ava जो भी करता है (आपका उत्तर देना, इमेज बनाना) कुछ क्रेडिट्स खर्च करता है। यही पूरी बात है। नीचे दिया गया विवरण तब है जब आप जानना चाहते हैं कि क्या किसकी कीमत है।","credits.overview#1#p":"Ava क्रेडिट्स में बिलिंग करता है, कच्चे टोकन्स में नहीं। (एक \"टोकन\" टेक्स्ट का छोटा टुकड़ा है — लगभग कुछ अक्षर — जिसमें AI मॉडल पढ़ते और लिखते हैं; ज्यादातर सेवाएं आपको प्रति टोकन चार्ज करती हैं, जो अनुमान लगाना मुश्किल है।) एक क्रेडिट एक यूनिट काम कवर करता है — एक चैट टर्न, एक पर्सोना स्पॉन (एक सहायक जो काम का हिस्सा करता है), एक इमेज जनरेशन। टोकन-स्तरीय मापन से अलग होने का मतलब है कि आपको यह नहीं जानने की ज़रूरत है कि कौन सा मॉडल चल रहा है ताकि पता चले कि एक एक्शन की कीमत क्या होगी। वही चैट टर्न की कीमत वही रहेगी चाहे Maestro उसे Qwen 3.6 Plus पर भेजे या Supernova उसे V4 Pro पर।","credits.overview#2#h":"प्लान","credits.overview#3#p":"हर प्लान में हर फीचर तक पहुंच है — मॉडल एक्सेस, Creative Studio, सभी सात मोड, पूर्ण पर्सोना ऑर्केस्ट्रेशन। उच्च स्तर अधिक क्रेडिट्स और उच्च रेट-लिमिट छत खरीदते हैं, अनलॉक किए गए फीचर्स नहीं।","credits.overview#4#li0":"निःशुल्क — $0/महीना। 300 क्रेडिट्स। 20 अनुरोध/मिनट मात्रा सीमा। कार्ड की आवश्यकता नहीं।","credits.overview#4#li1":"Pro — $19/महीना। 5,000 क्रेडिट्स। 60 अनुरोध/मिनट।","credits.overview#4#li2":"Ultra — $39/महीना। 10,000 क्रेडिट्स। 120 अनुरोध/मिनट।","credits.overview#4#li3":"Enterprise — $79/महीना। 20,000 क्रेडिट्स। 200 अनुरोध/मिनट।","credits.overview#5#c":"अप्रयुक्त क्रेडिट्स आपके सदस्यत्व सक्रिय रहने तक carry forward होते हैं — कोई जबरदस्ती वापसी नहीं। टॉप-अप्स सदस्यता पूल पर जुड़ते हैं: $3 के लिए 750 क्रेडिट्स, $8 के लिए 2,000, $15 के लिए 4,000।","credits.overview#6#h":"चीज़ों की कीमत क्या है","credits.overview#7#p":"प्रति-एक्शन लागत तालिका — जब हर एक्शन चलता है तो आपके क्रेडिट पूल से क्या घटता है। (एक \"कैश हिट\" तब होता है जब Ava पहले से किए गए काम को दोबारा करने के बजाय पुनः उपयोग करता है; जब ऐसा होता है तो आप कम भुगतान करते हैं — चार्ज 70% कम हो जाता है, या आउटपुट-भारी मॉडल्स जैसे DeepSeek V4 Pro पर 50%।)","credits.overview#8#li0":"चैट टर्न — 2 क्रेडिट्स। किसी भी मोड में एक बार आगे-पीछे।","credits.overview#8#li1":"लाइट कॉल — 1 क्रेडिट। इंटेंट गेट, वर्गीकरण, सिंगल-शॉट रीड।","credits.overview#8#li2":"हेवी पर्सोना — 3 क्रेडिट्स। आर्किटेक्ट, शोधकर्ता, CVE शोधकर्ता, विचारक (गहराई ≥ 4)।","credits.overview#8#li3":"लाइट पर्सोना — 1 क्रेडिट। स्कॉट, सत्यापक, सीक्वेंसर, चुनौती देने वाला (गहराई ≤ 2)।","concepts.modes#0#p":"एक मोड वह अवस्था है जिसमें Ava होती है — जैसे कोई सहकर्मी टोपी बदल रहा हो। वही व्यक्ति, वही आपकी याददाश्त, लेकिन एक बिल्डर की सोच शिक्षक से अलग होती है। आप मोड चुनते हैं और यह बदल देती है कि वह कैसे व्यवहार करेगी और कौन से सहायक लाएगी। किसी भी समय मोड सीलेक्टर के साथ स्विच करें, या दो अक्षरों वाला शॉर्टकट टाइप करें।","concepts.modes#2#h":"आपको कौन सा चाहिए?","concepts.modes#3#p":"अपनी कोशिश से शुरू करें — मोड उसी पर आधारित होता है:","concepts.modes#4#li0":"मुझे कुछ बनाना या बदलना है → Code (>>). आप बताएं, वह बनाएगी, हर बदलाव पहले दिखाकर। बड़े कामों के लिए पूरी सहायक टीम आगे आती है।","concepts.modes#4#li1":"कुछ बदलने से पहले प्लान चाहिए → Plan (::). वह सब सोचकर एक प्लान देगी जिसे आप मंजूर या एडिट कर सकें। इस मोड में वह आपके फ़ाइलों को छू नहीं पाएगी।","concepts.modes#4#li2":"बस बात करना या पूछना है → Chat (..). याददाश्त, खबरें और मौसम वाली सोचने वाली साथी। कोई फ़ाइल बदलाव नहीं, कोई कोड नहीं — सिर्फ बातचीत।","concepts.modes#4#li3":"कुछ सीखना है → Teach (??). आपके लिए बनाया गया असली कोर्स: लेक्चर, क्विज़, सब कुछ। हर प्लान पर हमेशा के लिए मुफ्त। अगर आप नए हैं तो यह बेहतरीन है।","concepts.modes#4#li4":"मेरे प्रोजेक्ट में सुरक्षा की कमियाँ चेक करवाना है → Security (!!)। एक टीम सामान्य वेब कमियों की मानक सूची (\"OWASP\" श्रेणियाँ) और ज्ञात रिपोर्ट किए गए दोषों (जिन्हें \"CVEs\" कहा जाता है) को देखती है, फिर आपको एक रिपोर्ट देती है जो हर समस्या की गंभीरता के अनुसार क्रमित है। यह डेवलपर्स के लिए है — अगर आप नहीं हैं तो इसे छोड़ दें।","concepts.modes#4#li5":"मुझे विचार चाहिए → Brainstorm (**). वह आपके वास्तविक स्थिति पर आधारित विकल्प बनाती है, कमजोरों में छेद करती है, और बाकी को अगले कदमों में ढालती है।","concepts.modes#4#li6":"दस्तावेज़ लिखना है → Write (<<). रिपोर्ट, प्रस्ताव, पत्र, लेख — वह Markdown में ड्राफ्ट करती है और ब्रांडेड Word डॉक या PDF निर्यात करती है, हिस्सेवार सुधारती हुई। कोई कोड नहीं, सिर्फ लेखन।","concepts.modes#5#c":"\"सहायक टीम\" (व्यक्तित्व) पूरी तरह से पर्दे के पीछे चलती है — आप कभी सीधे उनसे बात नहीं करते। आपको बस अधिक विस्तृत उत्तर मिलता है। आपको उनके नाम जानने की जरूरत नहीं है।","concepts.modes#6#c":"आप बातचीत के बीच मोड बदल सकते हैं। आपकी याददाश्त साथ रहती है; विशेषज्ञ नए मोड के अनुसार रीसेट हो जाते हैं।","concepts.tasks-journal#title":"कार्य और जर्नल","concepts.tasks-journal#0#p":"Ava आपके लिए तीन तरह के नोट्स रखती है, और इनमें उलझन हो सकती है। याद रखने का आसान तरीका: याददाश्त वह है जो उसे आप बारे पता है, कार्य वे हैं जो अभी करने बाकी हैं, और जर्नल एक डायरी है कि काम कैसा चला। यहाँ बताया गया है कि कब क्या उपयोग करें।","concepts.tasks-journal#1#li0":"याददाश्त — स्थायी तथ्य। प्राथमिकताएं, निर्णय, पैटर्न। बार-बार पूछे जाने पर, दुर्लभ रूप से मैन्युअल बनाई जाती है।","concepts.tasks-journal#1#li1":"कार्य — करने की चीज़ें। ड्यू डेट और स्टेटस वाले एक्शन आइटम। जब पूरा हो जाए तो आप उन्हें टिक कर दें।","concepts.tasks-journal#1#li2":"जर्नल — विचार-मंथन। दैनिक लॉग, द्वि-प्रविष्टियाँ (आपकी और Ava द्वारा सत्र के बारे में अवलोकन)। मूड ट्रैकिंग, सत्र समीक्षा, कल के लिए संदर्भ के लिए उपयोगी।","concepts.tasks-journal#2#p":"Ava तब लिखती है जब यह उचित लगे। आप डैशबोर्ड से सीधे इनमें से किसी में भी लिख सकते हैं। Ava का उपयोग करने वाली किसी एक जगह तक कुछ भी सीमित नहीं है — एक कार्य जो आप एक में बनाते हैं (मान लीजिए कमांड-लाइन टूल) वह दूसरी जगहों पर (जैसे डेस्कटॉप ऐप) स्वतः दिखता है।","concepts.permissions#title":"अनुमतियाँ — आपकी सुरक्षा डायल","concepts.permissions#0#p":"अनुमतियाँ आपकी सुरक्षा डायल हैं। ये तय करती हैं कि Ava अपने कंप्यूटर पर कुछ करने से पहले आपकी अनुमति मांगे या बस आगे बढ़े। आप उसे सबके बारे में पूछने, केवल जोखिम भरी चीज़ों के बारे में पूछने, या उसे चलने पर भरोसा करने के लिए सेट कर सकते हैं — और आप इसे किसी भी समय बदल सकते हैं। अगर आपको यकीन नहीं है, तो डिफ़ॉल्ट पर छोड़ दें और सब ठीक रहेगा।","concepts.permissions#1#p":"Ava के पास 60 टूल्स हैं (\"टूल्स\" वे कार्रवाइयाँ हैं जो वह कर सकती है — फ़ाइल पढ़ना, वेब सर्च करना, और इसी तरह)। हर टूल एक श्रेणी से संबंधित है (फ़ाइल ऑपरेशन, शेल, Git, वेब, मीडिया, डेटाबेस, सिस्टम, दस्तावेज़, याददाश्त, सीखना)। हर टूल कॉल चलने से पहले अनुमति गेट (एक चेकपॉइंट जो तय करता है कि पहले आपको पूछना है या नहीं) से गुजरता है। आप नियंत्रण करते हैं कि क्या ऑटो-अप्रूव होगा, क्या एक बार पूछेगा, और क्या हमेशा पूछेगा।","concepts.permissions#3#p":"`Balanced` डिफ़ॉल्ट है। `Strict` तब जब आप उसका व्यवहार ऑडिट कर रहे हों (हर कदम को ध्यान से देखना)। `Autonomous` तब जब आप चाहते हैं कि वह बस आगे बढ़े।","concepts.permissions#4#c":"`Autonomous` का मतलब अनियंत्रित नहीं है। प्लान, स्पष्टीकरण प्रश्न, और स्पष्ट यूजर-इनपुट के लिए पूछने वाले संकेत अभी भी आपके इनपुट के लिए रुकते हैं। अपरिवर्तनीय कार्रवाइयाँ (Git force-push, database drops) मोड चाहे जो हो, हमेशा पुष्टि करते हैं।","concepts.interjection#title":"Ava को नियंत्रित करना और रोकना","concepts.interjection#0#p":"आप हमेशा नियंत्रण में होते हैं। जब Ava काम करने में व्यस्त होती है, तो आप या तो बिना उसकी गति तोड़े उसे नई दिशा में धकेल सकते हैं, या उसे तुरंत रोक सकते हैं। दो बटन, दो परिणाम — यही इस पेज का मुख्य विषय है।","concepts.interjection#1#p":"Ava अपनी योजना पूरी करने तक या आप उसे रोकने तक चलती रहती है। जब वह चल रही होती है, तो आप दो तरीकों से बीच में हस्तक्षेप कर सकते हैं (इसे \"हस्तक्षेप\" कहते हैं)।","concepts.interjection#2#h":"इंटरजेक्ट — बिना रद्द किए मार्गदर्शन करें","concepts.interjection#3#p":"Ava काम कर रही हो तो नया संदेश टाइप करें। वह अपने वर्तमान टूल कॉल को पूरा करती है, आपके संदेश को पढ़ती है और अपनी योजना में बदलाव करती है। कोई भी जानकारी खोती नहीं है। इसका उपयोग तब करें जब आप दौरे के दौरान रास्ता बदलना, जानकारी जोड़ना या प्राथमिकताएं बदलना चाहते हों।","concepts.interjection#4#h":"हार्ड-स्टॉप — रद्द करें और साफ़ करें","concepts.interjection#5#p":"Escape दबाएं (CLI), Stop पर क्लिक करें (एक्सटेंशन, IDE), या एक स्टॉप कमांड टाइप करें। वर्तमान चाल रद्द हो जाती है, लंबित टूल कॉल गायब हो जाते हैं, और बातचीत नई शुरुआत के लिए तैयार हो जाती है।","concepts.interjection#6#c":"पहले इंटरजेक्ट करें। हार्ड-स्टॉप तभी करें जब कुछ सचमुच गलत हो रहा हो। इंटरजेक्ट करने से बातचीत का धागा जीवित रहता है।","concepts.desktop-personas#title":"डेस्कटॉप पर्सोनाज़","concepts.desktop-personas#0#p":"यह पेज जिज्ञासुओं और पावर यूज़र्स के लिए है। \"डेस्कटॉप ऑटोमेशन\" (कभी-कभी \"कंप्यूटर यूज़\" कहा जाता है) का मतलब है कि Ava वास्तव में आपके स्क्रीन पर क्लिक कर सकती है और आपके लिए ऐप्स का उपयोग कर सकती है — Gmail खोलना, फॉर्म भरना, संदेश भेजना — जैसे कीबोर्ड पर बैठा कोई व्यक्ति। इसे सुरक्षित रूप से करने के लिए, वह काम को पांच छोटे मददगारों में बांट देती है, जिनमें से प्रत्येक का एक संकीर्ण कार्य होता है। आप उनसे सीधे कभी नहीं मिलते; यह सिर्फ आपको दिखाता है कि कौन क्या करता है।","concepts.desktop-personas#1#p":"डेस्कटॉप ट्रैजेक्टरी (एक बार Ava द्वारा आपके स्क्रीन को लक्ष्य की ओर चलाने की एक चाल) में हर कदम पर पांच-पर्सोना वेव चलती है। प्रत्येक पर्सोना का एक ही काम होता है और केवल एक ही काम। यह अलग-अलग होने से प्रॉम्प्ट्स संकीर्ण, आउटपुट संरचित और तर्क डिज़ाइन के अनुसार संदेहात्मक रखता है।","concepts.desktop-personas#2#h":"Scout","concepts.desktop-personas#3#p":"बताता है कि अभी स्क्रीन पर क्या दिख रहा है। कभी भी तत्वों का आविष्कार नहीं करता। कभी भी योजना नहीं बनाता। ScreenState JSON लौटाता है जिसमें तत्व IDs, नाम, bboxes, विश्वास, और एक ग्राउंडिंग स्रोत (UIA, Playwright DOM, या OmniParser विजन) होता है।","concepts.desktop-personas#4#h":"Planner","concepts.desktop-personas#5#p":"अगला एकमात्र कार्रवाई तय करता है। एक कदम पर एक कार्रवाई — कभी भी समूह नहीं बनाता। उलटने योग्य रास्तों को प्राथमिकता देता है। सुरक्षा ऑन्टोलॉजी के अनुसार जोखिम वर्गीकृत करता है। ProposedAction JSON आउटपुट करता है जिसमें kind, target, params, riskClass, reasoning, और एक expectedPostState अनुमान होता है।","concepts.desktop-personas#6#h":"Actor","concepts.desktop-personas#7#p":"बिल्कुल वही करता है जो Planner ने सुझाया था — मंजूरी दरवाजा खुलने के बाद। कोई इम्प्रोवाइज़ेशन नहीं। कोई पुनः प्रयास नहीं। विफलता को ईमानदारी से रिपोर्ट किया जाता है और Verifier अगली चाल संभालता है।","concepts.desktop-personas#8#h":"Verifier","concepts.desktop-personas#9#p":"चेक करता है कि क्या कार्रवाई हुई। Planner के अनुमान के खिलाफ ताज़ा ScreenState की तुलना करता है। Verified, deviated, या rollback_needed लौटाता है। साथ ही लूप डिटेक्शन चलाता है — एक ऐसे कार्रवाई को दोहराना जो पहले से सफल हो चुकी है, वह विचलन है, न कि पुष्टि।","concepts.desktop-personas#10#h":"Narrator","concepts.desktop-personas#11#p":"वह एकमात्र आवाज़ है जो उपयोगकर्ता ट्रैजेक्टरी के दौरान सुनता है। हर कदम पर एक अतीत काल का वाक्य (\"Gmail खोला।\", \"Compose पर क्लिक किया।\")। साथ ही संरचित ऑडिट लॉग लिखता है। बताता है जब कुछ गलत हुआ — कभी समस्या छिपाता नहीं है।","concepts.desktop-safety#title":"डेस्कटॉप सुरक्षा ऑन्टोलॉजी","concepts.desktop-safety#0#p":"संक्षेप में: Ava आपके स्क्रीन पर कुछ भी क्लिक करने से पहले, वह कार्रवाई को उसके जोखिम के आधार पर व्यवस्थित करती है। स्क्रीन पढ़ना? कोई नुकसान नहीं। पैसा भेजना या कुछ हटाना? वह हमेशा रुकती है और पहले आपसे पूछती है — हर बार, कोई अपवाद नहीं। नीचे दिए गए पांच लेबल उस जोखिम सीढ़ी की सीढ़ियाँ हैं। यह पावर-यूज़र विवरण है, लेकिन मुख्य बात सरल है: खतरनाक चीज़ों को हमेशा आपकी हां चाहिए।","concepts.desktop-safety#1#p":"हर सुझाई गई कार्रवाई को पांच जोखिम श्रेणियों में से किसी एक में वर्गीकृत किया जाता है। वर्गीकरण तीन संकेतों को जोड़ता है — स्क्रीन पर लक्ष्य क्या है, इसका साधारण भाषा में विवरण (\"semantic caption\" — Ava के शब्दों में वह क्या देख रही है), और कार्रवाई की सेटिंग्स — और जब वे असहमत होते हैं तो इसे ऊपर बढ़ा देता है (इसे अधिक जोखिम भरा मानता है)। एक फॉल्स पॉजिटिव (जब जरूरत न होकर पूछना) सिर्फ एक चिढ़ है। एक फॉल्स नेगेटिव (जब पूछना चाहिए था लेकिन नहीं पूछा) एक उत्पाद समाप्त करने वाली घटना है।","concepts.desktop-safety#2#h":"पांच श्रेणियाँ","concepts.desktop-safety#3#li0":"Observational — UIA ट्री, स्क्रीनशॉट, होवर पढ़ें। हमेशा स्वतः अनुमति दी जाती है।","concepts.desktop-safety#3#li1":"Navigational — स्क्रॉल करें, फोकस हिलाएं, मेनू खोलें। Drive mode में स्वतः अनुमति दी जाती है।","concepts.desktop-safety#3#li2":"परिवर्तन जो वापस किए जा सकते हैं — जैसे कोई फ़ील्ड भरना, पेस्ट करना, ऐप खोलना या वेबसाइट पर जाना। 'Ask' मोड में यह पुष्टि मांगता है; जबकि 'Drive' मोड में व्हाइटलिस्ट के अंदर यह अपने आप हो जाता है।","concepts.desktop-safety#3#li3":"ऐसे कार्य जिनमें बदलाव को वापस नहीं लिया जा सकता — जैसे भेजना, सबमिट करना, भुगतान करना, डिलीट करना, पुष्टि करना या प्रकाशित करना। अनुमति स्तर चाहे कुछ भी हो, हमेशा पुष्टि की जाती है। मंजूरी कभी सेव नहीं होती।","concepts.desktop-safety#3#li4":"विशेषाधिकार प्राप्त — UAC उन्नयन, sudo, रजिस्ट्री में बदलाव, पासवर्ड पूछना। डिफ़ॉल्ट रूप से निषिद्ध। प्रति सत्र केवल एक बार चुनने की आवश्यकता होती है।","concepts.desktop-safety#4#h":"कभी सेव न होने वाली मंजूरीयाँ","concepts.desktop-safety#5#p":"हर प्रतिस्पर्धी मंजूरीयाँ सेव कर लेता है (आपके \\\"हाँ\\\" को याद रखता है और अगली बार उसका उपयोग करता है)। यह 'प्रॉम्प्ट इनजेक्शन' के लिए सबसे बड़ा मौका है — एक हमला जहाँ एक खतरनाक वेब पेज एआई को छिपी हुई निर्देश देकर आपके खिलाफ काम करने पर मजबूर करता है। अगर मंजूरीयाँ सेव हो गई हों, तो एक खराब पेज आपके पहले दिए गए \\\"हाँ\\\" का फायदा उठा सकता है। Ava कभी सेव नहीं करती। हर ऐसे कार्य के लिए वह नई पुष्टि मांगती है।","concepts.desktop-safety#6#h":"गुप्त जानकारी का प्रबंधन","concepts.desktop-safety#7#p":"पासवर्ड, API कुंजियाँ, और 2FA कोड (लॉगिन करते समय दूसरा ऐप या टेक्स्ट द्वारा दिया जाने वाला एक-बार का कोड) अपारदर्शी हैंडल्स के जरिए संभाले जाते हैं — ये असली मान्यता के लिए स्थानचिह्न होते हैं। Ava \\\"{secret}\\\" देखती है, असली पासवर्ड नहीं। असली मान्यता कभी उसके मेमोरी, एक्टिविटी लॉग, या उसे \\\"पढ़ने\\\" में नहीं आती — एक अलग कम-स्तरीय परत अंतिम क्षण में, कीबोर्ड दबाव पर इसे टाइप करती है, ताकि AI भाग कभी इससे संपर्क न करे।","reference.cli#title":"CLI कमांड्स","reference.cli#0#p":"यह पृष्ठ CLI के लिए है — Ava का वह संस्करण जिसे आप बटन क्लिक करने के बजाय टर्मिनल विंडो में टाइप करते हैं। यदि आप एक्सटेंशन या डेस्कटॉप ऐप का उपयोग करते हैं, तो आप इसे पूरी तरह छोड़ सकते हैं। यह उन लोगों के लिए है जो कीबोर्ड को प्राथमिकता देते हैं।","reference.cli#1#p":"CLI एक REPL है — एक प्रॉम्प्ट जो आपको टाइप करने के लिए इंतज़ार करता है, जो आपने टाइप किया है उसे चलाता है, फिर फिर से इंतज़ार करता है। ये स्लैश कमांड्स (जो \\\"/\\\" से शुरू होने वाले निर्देश हैं) प्रॉम्प्ट से काम करते हैं।","reference.cli#2#li0":"/help — कमांड्स और वर्तमान मोड सूचीबद्ध करें।","reference.cli#2#li1":"/mode <name> — मोड बदलें (कार्य, लिखना, योजना, बातचीत, सिखाना, सुरक्षा, ब्रेनस्टॉर्मिंग)।","reference.cli#2#li2":"/model <id> — सत्र छोड़े बिना मॉडल बदलें।","reference.cli#2#li3":"/clear — वर्तमान बातचीत साफ़ करें। मेमोरी अप्रभावित रहती है।","reference.cli#2#li4":"/history — इस प्रोजेक्ट में पिछली बातचीत सूचीबद्ध करें।","reference.cli#2#li5":"/memory — मेमोरी ब्राउज़र खोलें।","reference.cli#2#li6":"/tasks — कार्यों की सूची बनाएं और प्रबंधित करें।","reference.cli#2#li7":"/journal — आज का जर्नल एंट्री खोलें।","reference.cli#2#li8":"/settings — सेटिंग्स मेनू खोलें।","reference.cli#2#li9":"/exit — REPL से बाहर निकलें।","reference.cli#3#h":"लॉन्च फ्लैग्स","reference.cli#4#p":"फ्लैग्स अतिरिक्त विकल्प हैं जो आप Ava शुरू करते समय जोड़ते हैं, जो प्रत्येक \\\"--\\\" से शुरू होते हैं, यह सेट करने के लिए कि वह कैसे खुलेगी।","reference.cli#5#li0":"--mode <name> — किसी विशेष मोड में शुरू करें।","reference.cli#5#li1":"--model <id> — किसी विशेष मॉडल के साथ शुरू करें।","reference.cli#5#li2":"--permission <mode> — सख्त / संतुलित / स्वतंत्र।","reference.cli#5#li3":"--project <path> — प्रोजेक्ट की जड़ स्पष्ट रूप से सेट करें।","reference.desktop-budget#title":"डेस्कटॉप बजेट सीमाएं","reference.desktop-budget#0#p":"जब Ava आपके डेस्कटॉप पर आपकी तरफ से काम करती है — क्लिक करके, टाइप करके, ऐप्स खोलकर — हर चाल को एक \"ट्रैजेक्टरी\" कहते हैं। इस पेज पर वे सुरक्षा सीमाएं बताई गई हैं जो किसी भी चाल को बहुत लंबा चलने या महंगा होने से रोकती हैं। सबसे जरूरी बात: वह हमेशा समय से पहले रुकती है और आपसे पूछती है। अगर विस्तार जानना हो तो आंकड़े यहाँ दिए गए हैं।","reference.desktop-budget#1#p":"हर ट्रैजेक्टरी तीन एक साथ लागू होने वाली सीमाओं (कठोर लिमिट्स) के तहत चलती है। जिस सीमा का पहला उल्लंघन होता है, वही मान्य होती है। ट्रैजेक्टरी सीमा पार करने के बाद कभी बिना बताए आगे नहीं बढ़ती — नरेटर (वह मददगार जो आपको बताता है कि क्या हो रहा है) रुकता है और पूछता है कि अब क्या करना है।","reference.desktop-budget#2#h":"तीन कठोर सीमाएं (डिफ़ॉल्ट)","reference.desktop-budget#3#li0":"स्टेप गिनती — 30 स्टेप्स","reference.desktop-budget#3#li1":"टोकन बजट — 500,000 टोकन्स","reference.desktop-budget#3#li2":"वाक-क्लॉक — 5 मिनट","reference.desktop-budget#4#h":"कार्य लागत श्रेणियां","reference.desktop-budget#5#li0":"सरल (दस्तावेज़ खोजें, पेज खोलें) — 5–10 स्टेप्स, ~70–135K टोकन्स, ~$0.04–0.08","reference.desktop-budget#5#li1":"मध्यम (लॉग इन करें, लॉग चेक करें, आउटपुट डाउनलोड करें) — 15–25 स्टेप्स, ~205–340K टोकन्स, ~$0.12–0.21","reference.desktop-budget#5#li2":"जटिल (तीन GitHub इश्यूज़ का निपटान) — 25–30 स्टेप्स, ~340–410K टोकन्स, ~$0.21–0.25","reference.desktop-budget#6#p":"ऊपर दिए गए टोकन आंकड़े हर ट्रैजेक्टरी की तकनीकी सीमाएं हैं, आपका मासिक बजट नहीं — इसे क्रेडिट्स में गिना जाता है, और फ्री टियर का 300 प्रति माह चैट, कोडिंग और कुछ ऑटोमेशन के मिश्रण को आसानी से पूरा कर लेता है।","reference.desktop-budget#7#c":"आप शुरू में कार्य के आधार पर सीमाओं को ओवरराइड कर सकते हैं, लेकिन उल्लंघन हमेशा एक निर्णय बिंदु लाता है। बजट कभी भी बिना बताए खर्च नहीं होता।","reference.desktop-whitelist#title":"डेस्कटॉप सत्र व्हाइटलिस्ट","reference.desktop-whitelist#0#p":"`व्हाइटलिस्ट` सिर्फ उन ऐप्स और वेबसाइटों की सूची है जिन्हें आपने कहा है कि Ava आपके डेस्कटॉप को नियंत्रित करते हुए छू सकती है। यह पेज समझाता है कि आप कैसे अनुमति देते हैं और यह हर बार क्यों रीसेट होता है। छोटा संस्करण: वह केवल वहीं एक्शन ले सकती है जहां आप उसे अनुमति देते हैं, और वह कहीं नया जाने से पहले पूछती है।","reference.desktop-whitelist#1#p":"डेस्कटॉप सत्र शुरू होते ही Ava पूछती है कि वह कहाँ काम कर सकती है। आम भाषा में बताएं: \"Gmail, Cursor, the Azure portal.\" वह उसे पढ़ती है और आपको पुष्टि करती है कि मिलान सही है (\"Gmail web, Cursor the app, portal.azure.com\")।","reference.desktop-whitelist#2#h":"यह कैसे लागू करता है","reference.desktop-whitelist#3#p":"केवल देखने वाले कार्यों — जैसे स्क्रीनशॉट लेना, स्क्रीन पर बटनों और फ़ील्ड्स की सूची पढ़ना (\"UIA tree\", विंडो में क्या है का Windows का अपना मैप) — हर जगह अनुमत हैं, क्योंकि आपको यह तय करने के लिए स्क्रीन पर क्या दिख रहा है देखना होगा कि क्या कोई ऐप व्हाइटलिस्ट में जोड़ा जाए। कुछ बदलने वाला कोई भी एक्शन सूची के बाहर रोका जाता है; Ava रुक जाती है और पूछती है कि क्या इसे जोड़ा जाए।","reference.desktop-whitelist#4#h":"सत्र-विशिष्ट, जानबूझकर","reference.desktop-whitelist#5#p":"व्हाइटलिस्ट सत्रों के बीच सहेजा नहीं जाता है। \"इस ऐप को याद रखें\" का कोई विकल्प नहीं है। हर नई ट्रैजेक्टरी एक नए स्कोप के साथ शुरू होती है। जानबूझकर असुविधाजनक — दोबारा अनुमति देना भूल जाना एक विशेषता है, कोई बग नहीं।","reference.desktop-whitelist#6#h":"ट्रैजेक्टरी के बीच में जोड़ना","reference.desktop-whitelist#7#p":"ट्रैजेक्टरी के दौरान आप हेडर से ऐप्स जोड़ सकते हैं: \"+ Allow app\" एक छोटा इनपुट खोलता है। Add पर टैप करें और नया ऐप सत्र के बाकी हिस्से के लिए लाइव हो जाता है।","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"क्या आप एक इमेज, छोटा वीडियो, गाना, या बोले जाने वाले वॉइसओवर बनाना चाहते हैं? बस इसे वर्णन करें और Ava आपके लिए बना देगी — डिज़ाइन या ऑडियो सॉफ्टवेयर की जरूरत नहीं।","features.creative-studio#1#p":"छवि, वीडियो, संगीत और आवाज़ निर्माण — आपके कोड के साथ एक ही कार्यप्रवाह में बनाया गया है। एक आइकन, उत्पाद का मॉकअप, डेमो वीडियो, या ट्यूटोरियल के लिए वॉइसओवर जनरेट करें। MiniMax द्वारा संचालित।","features.creative-studio#2#h":"आप क्या बना सकते हैं","features.creative-studio#3#li0":"छवियाँ — प्रॉम्प्ट से PNG/JPG। बैकग्राउंड हटाना बस एक क्लिक दूर।","features.creative-studio#3#li1":"वीडियो — टेक्स्ट प्रॉम्प्ट से छोटे AI वीडियो (MiniMax Hailuo)।","features.creative-studio#3#li2":"संगीत — वाद्य या गायन ट्रैक, बोलों के साथ।","features.creative-studio#3#li3":"आवाज़ — चुनिंदा आवाज़ों के साथ टेक्स्ट-से-स्पीच।","features.creative-studio#4#p":"Creative Studio की लागत बाकी सब कुछ जैसे ही क्रेडिट पूल से निकलती है — एक पूल, एक नंबर। अपना MiniMax कुंजी BYOK करें और यह आपके प्लान के लिए मुफ्त हो जाएगा।","features.creative-studio#5#c":"Creative Studio फ्री-टियर के लिए उपयुक्त है। यह कोई भुगतान योग्य एड-ऑन नहीं है।","features.desktop-automation#title":"डेस्कटॉप ऑटोमेशन","features.desktop-automation#0#p":"सरल शब्दों में: Ava आपकी माउस और कीबोर्ड को अपने हाथ में ले सकती है ताकि वह आपके लिए काम कर सके — ऐप खोलना, बटन पर क्लिक करना, फॉर्म भरना — जबकि आप देख रहे हों और किसी भी महत्वपूर्ण चीज़ को स्वीकार कर सकें।","features.desktop-automation#1#p":"Ava के लिए एक नया मोड, प्रिफिक्स @@। वह डेस्कटॉप को देखती है, तय करती है कि क्या करना है, और इसे पूरा करने के लिए UI ऑटोमेशन चलाती है (आपके स्क्रीन पर ऐप्स को आपके लिए नियंत्रित करना)। यह आपके असली मशीन पर आपके असली क्रेडेंशियल्स के साथ चलता है — क्लाउड ब्राउज़र नहीं। हर टियर पर उपलब्ध होगा एक बार शिप होने के बाद।","features.desktop-automation#2#h":"क्यों यह खास है?","features.desktop-automation#3#p":"हर अन्य डेस्कटॉप-ऑटोमेशन उत्पाद वह है जो आप तभी शुरू करते हैं जब आप अपने डेस्क पर होते हैं। Ava वही है जो तब भी मौजूद रहती है जब आपका एरर ट्रैकर रात 2am बजता है — IDE चलता रहता है, आपका फोन सुरक्षित चैनल के जरिए जुड़ता है, आप एक टैप के साथ ऐसे कार्यों को स्वीकार करते हैं जिन्हें वापस नहीं किया जा सकता।","features.desktop-automation#4#p":"वह आपके ऐप्स को नेविगेट करना कैसे है उसे भी याद रखती है। हर अन्य एजेंट हर बार फिर से सीखता है। मेमोरी का फायदा इस्तेमाल करने के साथ बढ़ता जाता है।","features.desktop-automation#5#h":"यह कैसे काम करता है","features.desktop-automation#6#p":"हर कदम पर 5-भूमिकाओं वाली लहर चलती है: Scout देखता है, Planner अगला कदम चुनता है, Actor निष्पादित करता है, Verifier जाँच करता है, Narrator बताता है कि क्या हुआ। साइडकार सबसे सस्ता विश्वसनीय आधार चुनता है — नेटिव ऐप्स के लिए UIA, ब्राउज़र्स के लिए Playwright, OmniParser विजन जब कुछ और उपयोगी पेड़ नहीं देता।","features.desktop-automation#7#p":"सुरक्षा सिद्धांत, आधार क्रम, किल स्विच, और सत्र व्हाइटलिस्ट मॉडल के लिए अवधारणा पृष्ठ देखें।","models.routing#deeper#2#td5.0":"चैट","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"तस्वीरें बनाने की व्यवस्था","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"दृष्टि","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (बिल्कुल नए सिरे से प्रशिक्षित दृष्टि एन्कोडर)","models.routing#deeper#2#td8.0":"लंबे लेख या कहानियाँ","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"डेटा निवास स्थान","models.routing#deeper#2#td9.1":"मिश्रित (Alibaba Cloud)","models.routing#deeper#2#td9.2":"मिश्रित (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"केवल यूरोपीय संघ · खुले वजन","models.routing#deeper#2#td10.0":"स्थिति","models.routing#deeper#2#td10.1":"लाइव · सभी योजनाओं के लिए","models.routing#deeper#2#td10.2":"जल्द आ रहा है","models.routing#deeper#2#td10.3":"जल्द आ रहा है","models.routing#deeper#2#td11.0":"किसके लिए सबसे अच्छा"},"vi":{"start.for-non-coders#title":"Chưa bao giờ viết code? Bắt đầu từ đây","start.for-non-coders#0#p":"Nếu bạn chưa từng viết một dòng code, bạn chính là đối tượng mà Ava dành cho. Bạn không cần học thuật ngữ để bắt đầu — bạn nói chuyện với cô ấy bằng tiếng Anh bình thường, như cách bạn hỏi một người bạn am hiểu. Trang này là toàn bộ lộ trình nhập môn của bạn.","start.for-non-coders#1#h":"Những gì bạn có thể làm hôm nay, không cần kinh nghiệm","start.for-non-coders#2#li0":"Hỏi cô ấy bất cứ điều gì, bằng từ ngữ bình thường — \"file này làm gì?\", \"tại sao trang của tôi trống rỗng?\", \"database là gì nhỉ?\" Cô ấy trả lời bằng ngôn ngữ đơn giản và nhớ cuộc trò chuyện.","start.for-non-coders#2#li1":"Học một thứ từ đầu — nói \"dạy tôi Python từ số 0\" và cô ấy tạo cho bạn một khóa học đúng đắn với bài học và bài kiểm tra. Điều này luôn miễn phí.","start.for-non-coders#2#li2":"Có được thứ gì đó được xây dựng — mô tả những gì bạn muốn (\"một nút tải ghi chú của tôi\") và cô ấy viết nó, hiển thị mọi thay đổi trước khi nó xảy ra.","start.for-non-coders#3#h":"Bạn không cần phải hiểu mọi thứ","start.for-non-coders#4#p":"Ava có rất nhiều cơ chế bên trong — các chế độ, mô hình, chuyên gia, định tuyến. Bạn sẽ thấy những từ này quanh ứng dụng và trong tài liệu này. Đây là bí mật: bạn có thể bỏ qua hầu hết chúng. Ava chọn công cụ đúng và trợ lý đúng cho bạn tự động. Các trang kỹ thuật có sẵn khi bạn tò mò, chứ không phải vì bạn cần chúng để bắt đầu.","start.for-non-coders#5#h":"Một con đường nhẹ nhàng đầu tiên","start.for-non-coders#6#li0":"Cài đặt Ava (trang tiếp theo) và mở bảng trò chuyện.","start.for-non-coders#6#li1":"Gõ một câu hỏi thật bạn đang có. Bất cứ gì. Xem cô ấy trả lời thế nào.","start.for-non-coders#6#li2":"Thử chế độ học tập: gõ \"dạy tôi\" và một chủ đề. Theo dõi và thực hiện.","concepts.memory#title":"Trí nhớ — cách Ava nhớ về bạn","concepts.memory#0#p":"Nói đơn giản: Ava nhớ bạn. Kể cho cô ấy điều gì đó một lần — những gì bạn thích, một quyết định bạn đã đưa ra — và cô ấy giữ nó, để bạn không phải lặp lại trong cuộc trò chuyện tiếp theo hoặc tuần sau. Đó là ý chính. Các phần dưới chỉ giải thích cách cô ấy giữ ký ức gọn gàng theo thời gian.","concepts.memory#1#p":"Ava có bộ nhớ lưu trữ lâu dài (\"lâu dài\" nghĩa là nó vẫn tồn tại ngay cả khi bạn tắt ứng dụng) và duy trì qua các cuộc trò chuyện, dự án và thiết bị nếu bạn bật đồng bộ (đồng bộ sao chép bộ nhớ giữa các thiết bị của bạn). Nó không phải là nhật ký trò chuyện. Đó là sự hiểu biết có cấu trúc, có thể tìm kiếm về con người bạn, sở thích và những gì bạn đã quyết định.","concepts.memory#2#h":"Năm lớp","concepts.memory#3#li0":"Trích xuất — các thông tin quan trọng được ghi lại từ mọi tin nhắn theo thời gian thực.","concepts.memory#3#li1":"Phản ánh — phân tích sâu hơn chạy vào cuối các phiên làm việc ý nghĩa. Các mẫu hình, chủ đề, mâu thuẫn.","concepts.memory#3#li2":"Tích lũy — các chỉnh sửa và sở thích cộng dồn qua nhiều tuần và tháng.","concepts.memory#3#li3":"Phân tích — công cụ đồ thị liên kết các bộ nhớ liên quan và báo hiệu mâu thuẫn khi thông tin mới xung đột với thông tin cũ.","concepts.memory#3#li4":"Tổng hợp — các bộ nhớ tương tự hợp nhất; những cái cũ bị loại bỏ. Bộ nhớ trở nên sắc bén hơn theo thời gian, không ồn ào hơn.","concepts.memory#4#c":"Năm lớp trên hoạt động độc lập — bạn không bao giờ phải quản lý chúng. Chúng ở đây để bạn thấy bộ nhớ thực sự cải thiện theo thời gian thay vì trở thành một đống lộn xộn.","concepts.memory#5#h":"Gợi nhớ","concepts.memory#6#p":"Khi bạn đặt câu hỏi, Ava tìm kiếm trong bộ nhớ dựa trên ý nghĩa (\"tìm kiếm ngữ nghĩa\" — nó hiểu ý bạn muốn nói, nên tìm đúng bộ nhớ dù bạn diễn đạt khác đi), không chỉ khớp chính xác từng từ. Bộ lọc theo chế độ chạy song song — Chế độ Trò chuyện kéo bối cảnh cá nhân, Chế độ Công việc kéo quyết định dự án và mẫu mã.","concepts.memory#7#c":"Bộ nhớ giới hạn theo từng người dùng và từng dự án (ký ức của bạn là của bạn, được giữ riêng biệt theo người và theo dự án). Bí mật và thông tin đăng nhập (mật khẩu, khóa) bị chặn ở ranh giới lưu — chúng không bao giờ có thể rơi vào bộ nhớ.","reference.models#11#h":"Mang khóa của riêng bạn","reference.models#12#p":"Một \"khóa API\" là mật khẩu riêng cho phép phần mềm sử dụng dịch vụ trả phí trên tài khoản của bạn. \"BYOK\" đơn giản chỉ có nghĩa là \"mang theo khóa của bạn\" — dùng của bạn thay vì của chúng tôi. Dán khóa API của bạn vào cài đặt. Yêu cầu BYOK đi thẳng từ Ava đến nhà cung cấp (công ty chạy mô hình) — chúng không đi qua hạ tầng của chúng tôi và không tiêu tốn token nền tảng. Bạn trả tiền cho nhà cung cấp; chúng tôi không thấy lưu lượng truy cập.","reference.models#14#c":"Để xem điểm chuẩn, thẻ khả năng và bộ lọc so sánh song song, hãy xem trang Mô hình đầy đủ tại ava-supernova.com/models. Giá được hiển thị ở trên là mức đọc tốt nhất của chúng tôi về bảng giá từng nhà cung cấp tại thời điểm xuất bản — luôn kiểm tra trang web của nhà cung cấp trước khi cam kết với một khối lượng công việc.","reference.personas#title":"Điều phối vai trò","reference.personas#0#p":"Một \"vai trò\" là một trợ lý mà Ava đóng giả phía sau hậu trường để làm những việc khó hơn — như người khám phá, người lập kế hoạch, người kiểm chứng sự thật. Bạn sẽ không bao giờ nói chuyện trực tiếp với họ và bạn cũng không cần phải hiểu trang này để sử dụng Ava. Nó ở đây khi bạn tò mò muốn biết cô ấy chia nhỏ một công việc lớn thành một nhóm chuyên gia nhỏ như thế nào.","reference.personas#1#p":"24 chuyên gia trong 5 đội chế độ. Người điều phối (trợ lý giúp phối hợp các phần khác) quyết định đội nào chạy, theo thứ tự nào, và với ngữ cảnh gì. Chế độ Chat không có vai trò — đó chính là Ava.","reference.personas#2#h":"Cách thức vận hành điều phối","reference.personas#3#li0":"Bạn gửi tin nhắn ở chế độ Lập kế hoạch, Giảng dạy, Bảo mật hoặc Bão não (hoặc yêu cầu Công việc phức tạp).","reference.personas#3#li1":"Người điều phối đọc yêu cầu, chọn đội chế độ và xây dựng kế hoạch thực thi — một số vai trò chạy tuần tự, một số chạy theo làn sóng song song.","reference.personas#3#li2":"Mỗi vai trò có hệ thống lệnh riêng, danh sách cho phép công cụ bị giới hạn và một bể ngữ cảnh chung về những gì các vai trò trước đã tìm ra.","reference.personas#3#li3":"Vai trò cuối cùng tạo ra tóm tắt, kế hoạch hoặc báo cáo, tùy thuộc vào chế độ.","reference.personas#3#li4":"Ava trình bày kết quả cho bạn. Bạn phê duyệt, tinh chỉnh hoặc chuyển hướng.","reference.personas#4#p":"Danh sách đầy đủ bên dưới chỉ mang tính tham khảo — không cần nhớ ai làm gì. Ava tập hợp đúng đội cho bạn.","reference.personas#6#c":"Chế độ Công việc chỉ gọi toàn bộ đội cho các tác vụ phức tạp. Chỉnh sửa đơn giản chạy trực tiếp Ava — không có chi phí điều phối.","concepts.desktop-grounding#title":"Phân cấp nền tảng trên máy tính (Bản xem trước)","concepts.desktop-grounding#0#c":"Bản xem trước — cách Scout quyết định dùng nguồn dữ liệu nào ở mỗi bước.","concepts.desktop-grounding#1#p":"Trước khi Ava bấm nút, cô ấy cần thực sự hiểu những gì hiển thị trên màn hình của bạn và vị trí của chúng — gọi là 'nền tảng' (xác định mỗi thứ trên màn hình là gì và tọa độ chính xác). Cô ấy có ba cách để làm điều này và chọn cách đáng tin cậy nhất phù hợp với ứng dụng bạn đang dùng. Đây là chi tiết kỹ thuật chuyên sâu; điều quan trọng là cô ấy luôn ưu tiên phương pháp chắc chắn, chính xác thay vì đoán mò từ bức ảnh.","concepts.desktop-grounding#2#p":"Ba cấp độ, được kiểm tra theo thứ tự. Nguồn đáng tin cậy và nhẹ nhất sẽ được ưu tiên.","concepts.desktop-grounding#3#h":"1. Cửa sổ trình duyệt → Playwright DOM","concepts.desktop-grounding#4#p":"Nếu cửa sổ đang hoạt động là trình duyệt web, Ava đọc cấu trúc trang (cái gọi là 'DOM' — danh sách cơ bản về nội dung trang) thay vì đoán từ ảnh chụp. Đọc cấu trúc này đáng tin cậy hơn gấp 10× so với nhìn từng điểm ảnh — cô ấy biết chính xác mỗi nút ở đâu và khi nào trang đã tải xong. Đây là con đường chính cho mọi tác vụ trên web, không phải giải pháp dự phòng.","concepts.desktop-grounding#5#h":"2. Ứng dụng gốc có UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Với các ứng dụng desktop thông thường trên Windows, Ava đọc bản đồ hỗ trợ truy cập tích hợp ('UIA', cùng dữ liệu mà trình đọc màn hình dùng để mô tả cửa sổ) — nó liệt kê từng điều khiển, tên và vị trí của chúng. Nếu bản đồ này trả về ít nhất năm mục có tên và sử dụng được, cô ấy sẽ tin tưởng và dùng nó.","concepts.desktop-grounding#7#h":"3. UIA trống hoặc vô dụng → Thị giác OmniParser","concepts.desktop-grounding#8#p":"Khi bản đồ này thiếu hoặc vô dụng (một số ứng dụng, trò chơi và màn hình từ xa không cung cấp), Ava sẽ dựa vào việc nhìn trực tiếp ảnh chụp màn hình. Công cụ thị giác (OmniParser) sẽ phát hiện các vùng có thể nhấp chuột và gắn nhãn cho từng vùng, biến bức ảnh trở lại thành danh sách cô ấy có thể thao tác — kết hợp với bất kỳ thông tin nhỏ nào mà bản đồ hỗ trợ truy cập vẫn cung cấp được.","concepts.desktop-grounding#9#c":"OmniParser chỉ được kích hoạt khi bạn chọn tham gia lần đầu Ava cần nó, kèm theo cảnh báo bảo mật rõ ràng. Người dùng BYOK có thể chỉ định triển khai OmniParser cục bộ của riêng mình.","concepts.desktop-kill-switches#title":"Công tắc dừng khẩn cấp trên máy tính (Bản xem trước)","concepts.desktop-kill-switches#0#c":"Bản xem trước — ba cách độc lập để hủy bỏ quy trình đang chạy. Chỉ cần một trong số chúng hoạt động là đủ.","concepts.desktop-kill-switches#1#p":"Một 'công tắc dừng khẩn cấp' đúng như tên gọi — cách thức khẩn cấp để dừng Ava ngay lập tức khi cô ấy đang điều khiển màn hình của bạn. Điểm đáng yên tâm: có tới ba công tắc, mỗi cái được xây dựng riêng biệt, nên nếu một cái gặp sự cố, cái khác vẫn hoạt động. Bạn không cần phải học thuộc cả ba. Chỉ cần biết rằng khi có dấu hiệu bất thường, bạn luôn có thể dừng lại, và biện pháp dừng mạnh nhất (dừng khẩn cấp bên dưới) không phụ thuộc vào việc Ava có hợp tác hay không.","concepts.desktop-kill-switches#2#p":"Sau khi nghiên cứu mọi sự cố tự động hóa công khai (các trường hợp thật nơi AI bỏ qua lệnh dừng, xóa kho lưu trữ email, xóa ổ đĩa), chúng tôi đã xây dựng ba công tắc dừng ở ba lớp khác nhau. Không cái nào phụ thuộc vào chính mô hình AI — nếu Ava bị kẹt hoặc không phản hồi, bạn vẫn có thể dừng cô ấy.","concepts.desktop-kill-switches#3#h":"Tạm dừng — phím Space hoặc nút Pause","concepts.desktop-kill-switches#4#p":"Đứng yên ở ranh giới bước tiếp theo. Có thể tiếp tục. Dùng khi bạn muốn can thiệp mà không làm mất phương hướng.","concepts.desktop-kill-switches#5#h":"Dừng — Phím Escape hoặc nút Dừng","concepts.desktop-kill-switches#6#p":"Hủy bỏ gọn gàng. Người dẫn chuyện tóm tắt những gì đã hoàn thành. Không thể tiếp tục lại. Nhật ký kiểm toán được ghi nhận.","concepts.desktop-kill-switches#7#h":"Cắt khẩn cấp — nhấn ba lần phím Escape hoặc Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"Cách dừng mạnh mẽ nhất. Một chương trình giám sát nhỏ, độc lập buộc tắt phần Ava đang điều khiển màn hình của bạn. Nó không chờ AI phản hồi, không cần cửa sổ ứng dụng chạy tốt, và không quan tâm mọi thứ đang ở trạng thái nào — nó chỉ tắt luôn. Đây là lựa chọn duy nhất khi có vấn đề thực sự nghiêm trọng.","concepts.desktop-kill-switches#9#p":"Cả ba cách này đều hoạt động từ ứng dụng đồng hành. Bất kỳ trình điều khiển nào cũng có thể ngắt.","reference.tools#title":"Tham khảo công cụ","reference.tools#0#p":"Đây là danh mục đầy đủ mọi công cụ Ava sở hữu — một \"công cụ\" chỉ đơn giản là một hành động cụ thể cô ấy thực hiện, như đọc tệp hay chạy tìm kiếm. Bạn không cần đọc trang này. Ava tự chọn đúng công cụ mỗi lần. Trang này dành cho lúc bạn tò mò xem chính xác cô ấy có thể làm gì.","reference.tools#1#p":"Bộ công cụ tích hợp đầy đủ. Mọi công cụ ở đây đều được đăng ký trong môi trường chạy cốt lõi (động cơ vận hành bên dưới cả ba giao diện) và sẵn sàng cho Ava khi chế độ và chế độ quyền cho phép. Bạn có thể lọc theo danh mục hoặc mức độ rủi ro.","reference.tools#2#p":"Không cần phải ghi nhớ bất cứ điều gì ở đây — bảng dưới đây chỉ là thẻ tra cứu nhanh.","reference.tools#4#h":"Mức độ rủi ro","reference.tools#5#li0":"An toàn — chỉ đọc thông tin mà không thay đổi gì. file_read, glob (tìm tệp theo mẫu tên), grep (tìm kiếm văn bản trong tệp), git_status (Git là hệ thống theo dõi thay đổi dự án của bạn).","reference.tools#5#li1":"Viết — thay đổi tệp, lưu điểm kiểm soát công việc (một \"commit\"), hoặc tạo ra nội dung mới. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Nguy hiểm — chạy lệnh trên máy tính của bạn (“shell”), điều khiển màn hình nền, truy cập internet, hoặc truy vấn cơ sở dữ liệu. bash, browser, desktop_*.","reference.tools#6#c":"Các chuyên gia nhân vật có danh sách công cụ cho phép riêng. Scout có thể đọc nhưng không được viết. Builder có quyền truy cập đầy đủ. Challenger không có công cụ nào cả — nhiệm vụ của nó là chất vấn kế hoạch.","reference.models#title":"Mô hình","reference.models#0#p":"Một \"mô hình\" là bộ não AI đang xử lý suy nghĩ — Qwen, DeepSeek, Mistral và các mô hình khác. Trang này liệt kê mọi mô hình Ava có thể sử dụng. Nói ngắn gọn: bạn không cần phải chọn một cái. Ava tự chọn mô hình phù hợp cho từng bước. Chỉ đọc tiếp nếu bạn muốn hiểu rõ hoặc muốn thay thế.","reference.models#1#p":"Tất cả các mô hình Ava có thể định tuyến tới, cộng thêm ba chiến lược điều phối — các quy tắc quyết định mô hình nào xử lý từng phần của công việc. Chọn chế độ định tuyến và để Ava phân công, hoặc chọn một mô hình đơn lẻ và bỏ qua bước định tuyến.","reference.models#2#h":"Chế độ định tuyến","reference.models#3#p":"Ba chiến lược được điều phối. Cùng một quy trình nhân vật (nhóm trợ lý chuyên môn nhỏ mà Ava vận hành ngầm) chạy trên cả ba; điều thay đổi là đội ngũ mô hình nền tảng. Chọn chế độ trong trình chọn mô hình và Ava lo phần còn lại. Mỗi thẻ dưới đây hiển thị các chuyên gia cấu thành mà người điều phối định tuyến tới.","reference.models#4#p":"Bạn không cần phải ghi nhớ các thẻ dưới đây — chúng ở đây để bạn thấy mỗi chiến lược được cấu thành từ những gì.","reference.models#6#c":"Aurora cố tình chỉ dùng Mistral. Nếu mô hình Mistral không khả dụng, trình định tuyến trả về lỗi thay vì chuyển hướng sang mô hình khác — đó là cam kết của EU-stack. Chọn Maestro hoặc Supernova để giảm nhẹ tác động.","reference.models#7#c":"Cả ba chế độ đều khả dụng rộng rãi — trên tín dụng nền tảng và trên khóa của riêng bạn. BYOK thêm tùy chọn bỏ qua điều phối và điều khiển trực tiếp một mô hình.","reference.models#8#h":"Mô hình quản lý bởi nền tảng","reference.models#9#p":"Khả dụng trên mọi gói, bao gồm gói miễn phí. Tokens (đơn vị văn bản AI được đo lường bằng — khoảng ba phần tư một từ mỗi token) tính vào hạn mức gói của bạn. Các khóa (mật khẩu riêng mở khóa mỗi mô hình trả phí) được xoay vòng và giám sát bởi nền tảng — bạn không cần cấu hình gì cả.","reference.config#title":"Cấu hình","reference.config#0#p":"Trang này cho bạn biết nơi Ava lưu trữ cài đặt và các tệp trên máy tính của bạn. Bạn hầu như không bao giờ cần phải can thiệp thủ công — ứng dụng sẽ quản lý mọi thứ thay bạn. Mục này có sẵn khi bạn muốn xem, sao lưu hoặc chia sẻ các tệp đó.","reference.config#1#p":"Ava đọc cấu hình (các cài đặt đã lưu) từ hai phạm vi. Cài đặt chung — những cài đặt áp dụng ở mọi nơi — nằm trong thư mục ~/.ava/ (ký hiệu \"~\" là viết tắt cho thư mục cá nhân của bạn). Cài đặt riêng cho từng dự án thì nằm trong thư mục .ava/ ngay bên trong dự án.","reference.config#2#h":"Chung — ~/.ava/","reference.config#3#li0":"settings.json — sở thích mô hình, chế độ quyền hạn, tính cách, ngôn ngữ.","reference.config#3#li1":"memory/ — bộ nhớ chung của bạn (sở thích, các quyết định áp dụng cho mọi nơi).","reference.config#3#li2":"tasks.json — danh sách nhiệm vụ liên dự án.","reference.config#3#li3":"journal/ — các ghi chú nhật ký hàng ngày, được tổ chức theo ngày tháng.","reference.config#4#h":"Dự án — .ava/","reference.config#5#li0":"instructions.md — hướng dẫn riêng cho dự án mà Ava luôn tải vào. Bối cảnh cố định (ví dụ: \"chúng ta dùng pnpm, không dùng npm\", \"khóa API được lưu trong 1Password\").","reference.config#5#li1":"context.md — ghi chú dự án tự do (tùy chọn).","reference.config#5#li2":"memory/ — bộ nhớ giới hạn trong dự án này.","reference.config#5#li3":"datasets/config.json — cấu hình thu thập dữ liệu (có chọn lọc).","reference.config#6#c":"Hãy thêm .ava/ vào .gitignore (danh sách các tệp Git được bảo là không đưa vào dự án chung) nếu bạn không muốn chia sẻ bộ nhớ với đồng đội. Hãy giữ instructions.md trong kho chứa (thư mục dự án chung) — đó chính là cách Ava học các quy ước của dự án.","reference.shortcuts#title":"Phím tắt bàn phím","reference.shortcuts#0#p":"Phím tắt bàn phím là các trợ giúp tốc độ tùy chọn — tất cả chúng đều có thể thay thế bằng nút bấm. Chỉ xem phần này nếu bạn muốn điều khiển Ava nhanh hơn bằng bàn phím.","reference.shortcuts#1#p":"Phím tắt theo giao diện (mỗi trong ba nơi Ava hoạt động: tiện ích mở rộng VS Code, ứng dụng máy tính để bàn và terminal). Bạn có thể tùy chỉnh chúng trong cài đặt của từng giao diện. Không cần phải nhớ danh sách bên dưới.","reference.project-context#title":"Bối cảnh dự án","reference.project-context#0#p":"Phần này giải thích cách Ava tìm hiểu về dự án của bạn trước khi bắt đầu — những file cô ấy xem để hiểu bạn đang làm gì. Bạn không cần thiết lập bất kỳ thứ gì; cô ấy tự làm điều đó. Đọc nếu bạn muốn biết nơi đặt ghi chú để cô ấy luôn thấy được.","reference.project-context#1#p":"Khi bạn mở một dự án, Ava tải nhiều lớp ngữ cảnh (thông tin nền tảng cô ấy giữ trong trí nhớ). Hiểu các lớp này giúp bạn đưa thông tin vào đúng vị trí.","reference.project-context#2#h":"Được tải tự động","reference.project-context#3#li0":".ava/instructions.md — được coi là hướng dẫn bền vững, ưu tiên cao. Luôn có trong ngữ cảnh.","reference.project-context#3#li1":".ava/context.md — ghi chú tự do. Được tải, ưu tiên thấp hơn.","reference.project-context#3#li2":"README.md — được quét lần đầu để tóm tắt dự án.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — các file nhỏ liệt kê cấu hình dự án; được đọc để phát hiện ngôn ngữ, framework và lệnh kiểm thử.","reference.project-context#3#li4":".gitignore — danh sách file cần bỏ qua khỏi quản lý phiên bản; được tôn trọng bởi mọi công cụ file (glob, grep, project_index).","reference.project-context#4#h":"Được tải theo yêu cầu","reference.project-context#5#p":"\"Theo yêu cầu\" nghĩa là Ava chỉ lấy những thứ này khi nhiệm vụ thực sự cần, chứ không phải từ trước.","reference.project-context#6#li0":"Chỉ mục dự án — bản đồ có cấu trúc của các file và các thành phần có tên bên trong chúng (hàm, lớp — \"ký hiệu\") và cách chúng kết nối (\"nhập\"). Được xây dựng theo kiểu lười, nghĩa là chỉ khi Ava cần nó.","reference.project-context#6#li1":"Lịch sử Git — bản ghi thay đổi quá khứ; được kéo về khi gọi git_status, git_diff, hoặc git_create_pr (git là công cụ theo dõi mọi thay đổi đến dự án; \"PR\" là yêu cầu kéo, một đề xuất lô thay đổi).","reference.project-context#6#li2":"Bộ nhớ — các mục được khớp theo ý nghĩa (\"theo ngữ nghĩa\") và được đưa vào từng lượt một, không phải tất cả cùng lúc.","reference.project-context#7#c":"Để quy ước trong instructions.md. Để ghi chú trong context.md. Để bộ nhớ tự thu thập phần còn lại.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Cần báo cáo, email, hay tài liệu nào đó? Ava có thể soạn thảo và giao cho bạn một file Word, Excel hoặc PDF thật sự mà bạn có thể mở và chỉnh sửa như mọi file khác.","features.office-suite#1#p":"Báo cáo, email và tài liệu — được soạn thảo, định dạng và xuất ra các định dạng gốc (.docx là Word, .xlsx là Excel, .pdf là PDF).","features.office-suite#2#li0":"report_generate — một file .docx có cấu trúc lấy dữ liệu từ nhiệm vụ, nhật ký, bộ nhớ và trạng thái dự án.","features.office-suite#2#li1":"email_draft — email có kiểm soát giọng điệu xuất thành file .docx.","features.office-suite#2#li2":"document_manage — tạo, xem, chỉnh sửa, xuất trên Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Hữu ích khi Ava viết thay bạn — báo cáo tiến độ, slide khởi động, cập nhật khách hàng. File .docx sẽ nằm trong dự án của bạn để bạn tinh chỉnh thêm.","features.dashboard-library#title":"Thư viện bảng điều khiển","features.dashboard-library#0#p":"Nói đơn giản: một kệ chứa tất cả những gì bạn và Ava đã tạo ra và trò chuyện về, để không gì bị thất lạc.","features.dashboard-library#1#p":"Một cách xem có thể duyệt qua mọi thứ Ava đã tạo cùng bạn — ảnh, video, âm thanh, tài liệu được tạo ra — bên cạnh cuộc trò chuyện, ký ức và nhiệm vụ của bạn. Một nơi duy nhất để tìm lại thứ bạn đã làm tuần trước.","features.document-preview#title":"Xem trước tài liệu","features.document-preview#0#p":"Nói đơn giản: xem nhanh nội dung tài liệu ngay tại chỗ, không cần mở chương trình riêng để đọc nó.","features.document-preview#1#p":"Nhấp chuột phải vào file Word, Excel, PDF, CSV, HTML hoặc Markdown trong dự án của bạn — xem trước trực tiếp mà không rời trình soạn thảo. Hữu ích để đọc tài liệu tham khảo do Ava tạo ra hoặc file cộng tác viên gửi vào.","features.daily-briefing#title":"Bản tin hàng ngày","features.daily-briefing#0#p":"Nói đơn giản: ghi chú ngắn gọn mỗi sáng \"đây là nơi bạn dừng lại\", để bạn có thể tiếp tục mà không cần đọc lại mọi thứ.","features.daily-briefing#1#p":"Tóm tắt buổi sáng: nhật ký hôm qua, nhiệm vụ đang mở, trạng thái dự án và bất kỳ lời nhắc nào Ava đã đặt. Tùy chọn — bật lên trong cài đặt.","features.daily-briefing#2#p":"Bản tin sử dụng bộ nhớ để hiển thị ngữ cảnh liên quan (\"Lần cuối bạn làm việc trên luồng xác thực, bạn ghi chú muốn xem lại chiến lược token làm mới\"). Không phải nguồn tin tức — mà là tóm tắt tập trung.","features.unified-panel#title":"Bảng điều khiển thống nhất","features.unified-panel#0#p":"Nói đơn giản: mọi thứ Ava làm đều nằm trong một cửa sổ, nên bạn không bao giờ phải lục lọi qua các tab để tìm nó.","features.unified-panel#1#p":"Một bảng điều khiển cho trò chuyện, dashboard, bộ nhớ, nhiệm vụ và nhật ký. Không chuyển ngữ cảnh giữa các cửa sổ. Thanh bên chọn những gì bạn đang xem; khu vực chính thay đổi để phù hợp.","features.unified-panel#2#p":"Trạng thái hội thoại vẫn tồn tại khi bạn di chuyển ra — mở bộ nhớ, kiểm tra nhiệm vụ, rồi quay lại. Cuộc trò chuyện vẫn ở đó, vẫn đang phát trực tuyến nếu Ava vẫn đang chạy.","features.unified-panel#3#c":"Bảng điều khiển thống nhất là khái niệm của tiện ích mở rộng và IDE. Giao diện web sử dụng các tab trình duyệt.","features.knowledge-packs#title":"Gói kiến thức","features.knowledge-packs#0#p":"Nói đơn giản: đưa Ava một thư mục tài liệu của riêng bạn, và cô ấy có thể đọc chúng để trả lời câu hỏi của bạn. Một \"gói kiến thức\" đơn giản là tập hợp các tệp đó — tài liệu tham khảo mà cô ấy được phép sử dụng.","features.knowledge-packs#1#p":"Thả một thư mục tài liệu tham khảo (thông số kỹ thuật, RFC, ghi chú cuộc họp, tài liệu API) vào một gói kiến thức. Ava có thể kéo các phần liên quan vào ngữ cảnh khi cuộc trò chuyện chạm đến chủ đề.","features.knowledge-packs#2#p":"Các gói được lập chỉ mục cục bộ. Truy xuất mang tính ngữ nghĩa — Ava tìm đúng tài liệu bằng ý nghĩa, không phải tên tệp. (\"Ngữ nghĩa\" có nghĩa là cô ấy khớp dựa trên tài liệu nói về cái gì, nên bạn không cần nhớ chính xác từ ngữ hoặc tên tệp.) Các gói có thể được chia sẻ với nhóm hoặc giữ riêng tư.","troubleshooting.common-errors#title":"Các lỗi thường gặp","troubleshooting.common-errors#0#p":"Hầu hết các lỗi đều có nguyên nhân ngắn gọn và cụ thể. Dưới đây là những lỗi phổ biến cùng cách khắc phục. Đừng lo nếu văn phong nghe hơi kỹ thuật — mỗi mục dưới đây sẽ nói rõ bạn đang thấy gì và chính xác phải làm gì.","troubleshooting.common-errors#1#h":"Mô hình không phản hồi","troubleshooting.common-errors#2#p":"Bạn thấy: Ava im lặng và không trả lời.","troubleshooting.common-errors#3#p":"Kiểm tra chỉ báo trạng thái ở đầu khung chat. Nếu nó ghi \\\"connecting\\\", nhà cung cấp của bạn (dịch vụ AI mà Ava đang trò chuyện) vẫn kết nối được nhưng chậm — hãy đợi thêm ba mươi giây. Nếu nó ghi \\\"unavailable\\\", Ava tự động chuyển sang mô hình tiếp theo trong chuỗi (cô ấy tự động chuyển sang mô hình dự phòng). Nếu không có gì cả, hãy kiểm tra khóa API của bạn trong Cài đặt và thử kết nối lại. (Khóa API là mật khẩu riêng tư cho phép Ava sử dụng dịch vụ AI trả phí.)","troubleshooting.common-errors#4#h":"Gọi công cụ thất bại","troubleshooting.common-errors#5#p":"Bạn thấy: Một bước của Ava (một \\\"gọi công cụ\\\" — cô ấy đọc tệp, chạy lệnh, v.v.) hiển thị lỗi màu đỏ thay vì hoàn thành.","troubleshooting.common-errors#6#p":"Nhấp vào cuộc gọi công cụ bị lỗi để xem chi tiết lỗi. Nguyên nhân phổ biến: cô ấy cố gắng truy cập một tệp bên ngoài thư mục dự án của bạn, điều này bị chặn cố ý vì sự an toàn của bạn (lá chắn này gọi là bảo vệ \\\"path traversal\\\" — ngăn cô ấy lang thang ra khỏi thư mục bạn đang làm việc); một lệnh cần chạy trong thư mục khác; hoặc một tệp đã bị di chuyển kể từ lần cuối Ava kiểm tra. Hãy nói với cô ấy điều gì đã xảy ra — cô ấy sẽ thử lại với các điều chỉnh.","troubleshooting.common-errors#7#h":"Bộ nhớ không nhớ lại","troubleshooting.common-errors#8#p":"Bạn thấy: Ava không tìm thấy thứ gì đó mà bạn chắc chắn cô ấy nên nhớ.","troubleshooting.common-errors#9#p":"Bộ nhớ hoạt động dựa trên ý nghĩa, không phải từ ngữ chính xác (đây là ý nghĩa của \\\"semantic\\\"). Vậy nên \\\"Tôi đã quyết định thế nào về auth?\\\" hiệu quả hơn \\\"tìm quyết định auth của tôi\\\". Nếu bộ nhớ chắc chắn có đó nhưng không hiện lên, hãy mở trình duyệt bộ nhớ và tìm kiếm — nếu không có ở đó, nghĩa là ngay từ đầu nó chưa bao giờ được lưu.","troubleshooting.common-errors#10#h":"Vòng lặp đăng nhập","troubleshooting.common-errors#11#p":"Bạn thấy: Bạn đăng nhập, nhưng Ava liên tục yêu cầu bạn đăng nhập lại — một vòng lặp không bao giờ cho phép bạn vào.","troubleshooting.common-errors#12#p":"Cách sửa là xóa thông tin đăng nhập đã lưu và bắt đầu lại: trong tiện ích mở rộng, chạy \\\"Ava: Sign Out\\\" từ bảng lệnh, trong IDE dùng Cài đặt → Tài khoản → Đăng xuất, trong CLI xóa tệp tại ~/.ava/auth.json (một tệp đăng nhập nhỏ trong thư mục tên .ava trong thư mục nhà của bạn). Sau đó đăng nhập lại.","troubleshooting.common-errors#13#h":"Hết Token","troubleshooting.common-errors#14#p":"Bạn thấy: Thông báo rằng bạn đã hết lượt dùng miễn phí trong tháng. (\\\"Tokens\\\" là cách đo lường mức độ sử dụng AI — \\\"exhausted\\\" đơn giản có nghĩa là bạn đã dùng hết hạn mức miễn phí của tháng này.)","troubleshooting.common-errors#15#p":"Ngân sách hàng tháng của gói miễn phí sẽ được đặt lại vào ngày 1 của mỗi tháng. Cho đến lúc đó, hãy chuyển sang nhà cung cấp BYOK (sử dụng khóa API của riêng bạn) để tiếp tục làm việc. Tài khoản của bạn vẫn hoạt động — chỉ các yêu cầu do nền tảng quản lý miễn phí bị tạm dừng.","troubleshooting.logs#title":"Nơi lưu trữ nhật ký","troubleshooting.logs#0#p":"Một \\\"nhật ký\\\" (log) đơn giản là cuốn sổ tay máy tính bạn giữ lại về những gì đã xảy ra — hữu ích khi có gì đó hỏng và bạn (hoặc bộ phận hỗ trợ) cần xem chi tiết.","troubleshooting.logs#1#p":"Khi bạn cần xem chi tiết gốc — công cụ nào được gọi, thông tin nào nó nhận được, dịch vụ AI trả về gì — nhật ký là các tệp văn bản thuần túy trong một thư mục trên máy tính của bạn tại ~/.ava/logs/ (một thư mục tên .ava trong thư mục nhà của bạn, bên trong có thư mục logs).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — bản ghi từng phiên bao gồm gọi công cụ, phản hồi phát trực tuyến và lỗi.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — nhật ký chủ tiện ích VS Code. Lỗi kích hoạt, lỗi bảng điều khiển.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — nhật ký IDE trên máy tính để bàn. Tin nhắn quy trình Sidecar, lỗi Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — nhật ký CLI REPL.","troubleshooting.logs#3#p":"Trong tiện ích mở rộng, \\\"Ava: Show Logs\\\" trong bảng lệnh sẽ mở nhật ký liên quan trong một thẻ trình soạn thảo. Trong IDE, Cài đặt → Chẩn đoán có nút \\\"Open Logs\\\". CLI có thể theo dõi nhật ký của chính nó bằng lệnh ava logs --follow.","features.workflows#title":"Quy trình làm việc","features.workflows#0#p":"Nói nôm na: hướng dẫn Ava một thao tác bạn thường xuyên làm, đặt tên cho nó, và cô ấy sẽ tự động thực hiện lại mọi lúc bạn cần. Một \"quy trình làm việc\" chính là thói quen đã được lưu đó — một tập hợp các bước Ava lặp lại thay bạn.","features.workflows#1#p":"Lưu lại chuỗi các bước bạn thường phải làm đi làm lại — xem PR → chạy test → viết ghi chú bản phát hành → soạn email. Quy trình là một kế hoạch có thể dùng lại, để Ava thực hiện lại với các dữ liệu khác nhau.","features.workflows#2#p":"Mỗi dự án sẽ lưu quy trình riêng trong thư mục .ava/workflows/ nằm ngay trong dự án của bạn. Để chia sẻ với đồng đội, hãy commit thư mục này (lưu vào kho dự án chung để mọi người đều có được).","features.events#title":"Sự kiện và thông báo","features.events#0#p":"Nói nôm na: khi Ava làm việc, bạn sẽ thấy danh sách từng bước rõ ràng về những gì cô ấy đang xử lý, cùng thông báo khi công việc dài hạn hoàn thành để bạn yên tâm làm việc khác.","features.events#1#p":"Trong khi Ava hoạt động, bạn sẽ thấy các cập nhật có cấu trúc, không phải một khối văn bản dày đặc. Mỗi lần gọi công cụ, mỗi lần chuyển giao vai trò, hay mỗi luồng dữ liệu đều là một sự kiện riêng biệt trên giao diện — có thể mở rộng để xem chi tiết hoặc thu gọn để nắm tổng quan.","features.events#2#p":"Các tác vụ chạy nền sẽ gửi thông báo ở cấp hệ điều hành khi hoàn tất. Bạn có thể rời khỏi màn hình trong khi quá trình biên dịch dài diễn ra, và Ava sẽ báo cho bạn biết khi nào thì xong.","features.personality#title":"Thiết kế Tính cách","features.personality#0#p":"Nói nôm na: bạn có thể điều chỉnh cách Ava trò chuyện với bạn — nhiều lời hay ngắn gọn, trang trọng hay thân mật, hài hước hay nghiêm túc — để giọng điệu phù hợp với sở thích của bạn.","features.personality#1#p":"Bạn có thể định hình cách Ava trò chuyện: giọng điệu, năng lượng, độ dài câu trả lời, mức độ trang trọng, hay yếu tố hài hước. Có thanh trượt và cài đặt sẵn — kỹ sư kiệm lời, cố vấn ấm áp, đồng nghiệp hài hước nhẹ nhàng, hoặc sự kết hợp riêng của bạn.","features.personality#2#p":"Tính cách chỉ ảnh hưởng đến cách diễn đạt, không làm giảm năng lực. Cô ấy vẫn sử dụng cùng công cụ và tuân thủ cùng quy tắc quyền hạn. Tên của cô ấy luôn là Ava — điều này không thể thay đổi.","features.release-notes#title":"Ghi chú phát hành","features.release-notes#0#p":"Nói nôm na: đây là danh sách cập nhật liên tục về những tính năng mới và lỗi đã sửa trong mỗi phiên bản, giúp bạn dễ dàng theo dõi những thay đổi.","features.release-notes#1#p":"Nhật ký thay đổi trong ứng dụng (changelog là lịch sử các thay đổi). Mỗi phiên bản được phát hành đều có các điểm nổi bật, sửa lỗi và các thay đổi lớn (những thay đổi có thể yêu cầu bạn điều chỉnh cách sử dụng). Trang web duy trì phiên bản công khai tại ava-supernova.com/releases.","troubleshooting.logs#4#c":"Nhật ký có thể chứa các đoạn trích từ các tệp dự án mà Ava đã đọc trong một phiên làm việc. Hãy xem lại trước khi chia sẻ.","troubleshooting.support-request#title":"Gửi yêu cầu hỗ trợ","troubleshooting.support-request#0#p":"Nói đơn giản: nếu có gì đó không ổn và các cách sửa ở trên không giúp được, hãy gửi tin nhắn cho chúng tôi về vấn đề đó. Cách dễ nhất là chỉ cần hỏi Ava thực hiện hộ bạn.","troubleshooting.support-request#1#p":"Nếu vấn đề không nằm trong các lỗi phổ biến, hãy tạo vé hỗ trợ (gửi yêu cầu trợ giúp cho đội ngũ hỗ trợ). Bạn có thể làm điều này ngay trong Ava (không cần điền biểu mẫu) hoặc trên trang web.","troubleshooting.support-request#2#h":"Từ bên trong Ava","troubleshooting.support-request#3#p":"Hãy bảo cô ấy tạo vé. \"Ava, bạn có thể tạo vé hỗ trợ về vấn đề này không?\" Cô ấy sẽ gọi lệnh support_request, đính kèm ngữ cảnh phiên làm việc liên quan (đã ẩn thông tin nhạy cảm), rồi gửi đi. Đây là cách nhanh nhất.","troubleshooting.support-request#4#h":"Từ trang web","troubleshooting.support-request#5#p":"Truy cập ava-supernova.com/support. Chọn danh mục (lỗi, tính năng, tài khoản, bảo mật, chung) và mô tả những gì đã xảy ra. Phản hồi trong vòng một ngày làm việc.","troubleshooting.support-request#6#h":"Những gì cần cung cấp","troubleshooting.support-request#7#li0":"Bạn đang cố gắng làm gì.","troubleshooting.support-request#7#li1":"Điều gì thực sự đã xảy ra.","troubleshooting.support-request#7#li2":"Giao diện nào (tiện ích mở rộng, IDE, CLI, ứng dụng đi kèm) và phiên bản nào.","troubleshooting.support-request#7#li3":"Bất kỳ thông báo lỗi nào hoặc đoạn trích nhật ký. Hãy ẩn thông tin đăng nhập trước.","troubleshooting.security-disclosure#title":"Báo cáo các vấn đề bảo mật","troubleshooting.security-disclosure#0#p":"Nói đơn giản: nếu bạn phát hiện cách nào đó để xâm nhập vào Ava hoặc lạm dụng nó (một \"lỗ hổng\" — điểm yếu bảo mật), vui lòng báo cho chúng tôi riêng tư trước để chúng tôi có thể sửa chữa trước khi ai đó lợi dụng. Trang này hướng dẫn cách làm.","troubleshooting.security-disclosure#1#p":"Phát hiện lỗ hổng? Cảm ơn bạn. Chúng tôi nghiêm túc tiếp nhận mọi báo cáo và làm việc cùng bạn để khắc phục trước khi công bố công khai (trước khi vấn đề được thông báo rộng rãi).","troubleshooting.security-disclosure#2#h":"Cách báo cáo","troubleshooting.security-disclosure#3#li0":"Gửi email đến security@ava-supernova.com kèm theo mô tả, các bước tái hiện, và khung thời gian công bố bạn mong muốn.","troubleshooting.security-disclosure#3#li1":"Hoặc tạo vé hỗ trợ với danh mục \"bảo mật\" — cùng hàng đợi xử lý.","troubleshooting.security-disclosure#3#li2":"Chúng tôi xác nhận trong vòng 24 giờ.","troubleshooting.security-disclosure#4#h":"Cam kết của chúng tôi","troubleshooting.security-disclosure#5#li0":"Công bố phối hợp — chúng tôi thống nhất lộ trình với bạn trước khi bất cứ điều gì được công khai. Mặc định là 90 ngày.","troubleshooting.security-disclosure#5#li1":"Ghi công — bạn sẽ được ghi tên trong chú thích sửa lỗi trừ khi bạn muốn giữ bí danh.","troubleshooting.security-disclosure#5#li2":"Không trả đũa pháp lý — nghiên cứu thiện chí luôn được chào đón. Chúng tôi sẽ không cử luật sư đến tìm bạn.","troubleshooting.security-disclosure#6#c":"Trang bảo mật tại ava-supernova.com/security có đầy đủ chính sách — đảm bảo kiến trúc, công cụ ẩn dữ liệu, cổng quyền hạn.","start.for-non-coders#6#li3":"Khi bạn muốn cô ấy thực sự tạo ra hoặc thay đổi điều gì đó, chỉ cần hỏi — cô ấy luôn cho bạn xem những gì mình sắp làm và chờ câu trả lời \"đồng ý\" của bạn.","start.for-non-coders#7#c":"Gặp từ nào bạn không hiểu? Từ điển giải thích đơn giản (ở phần dưới mục này) sẽ giải thích mọi thuật ngữ mà không cần bạn phải biết trước.","start.install#title":"Cài đặt","start.install#0#p":"Chọn giao diện phù hợp với cách bạn làm việc. Bạn có thể dùng nhiều loại — Ava sẽ đồng bộ ký ức của cô ấy trên tất cả khi bạn đăng nhập.","start.install#1#h":"Tiện ích mở rộng VS Code","start.install#2#li0":"Mở bảng Tiện ích mở rộng trong VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Tìm kiếm \"Ava Supernova\" và nhấn Cài đặt.","start.install#2#li2":"Nhấn Ctrl+Shift+A (Cmd+Shift+A trên macOS) để mở bảng trò chuyện.","start.install#2#li3":"Làm theo trình hướng dẫn thiết lập — chọn mô hình, đặt chế độ quyền, là xong.","start.install#3#h":"IDE trên máy tính để bàn","start.install#4#li0":"Tải trình cài đặt cho nền tảng của bạn từ trang phát hành.","start.install#4#li1":"Chạy nó. Lần đầu tiên, IDE sẽ mở ra với màn hình chào mừng.","start.install#4#li2":"Đăng nhập để nhận token miễn phí của nền tảng, hoặc dán khóa API của riêng bạn để chạy hoàn toàn trên máy.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (hoặc pnpm / yarn — tùy bạn).","start.install#6#li1":"Chạy  ava  trong bất kỳ thư mục dự án nào.","start.install#6#li2":"Lần chạy đầu tiên sẽ hỏi bạn về nhà cung cấp và mô hình. Chọn và bắt đầu.","start.install#7#c":"Không tài khoản cũng không sao. Với khóa API của riêng bạn (BYOK) bạn không bao giờ cần đăng nhập. Gói miễn phí dành cho các mô hình do nền tảng quản lý.","start.what#title":"Ava là gì?","start.what#0#p":"Ava là một AI thực sự làm được việc — chứ không chỉ biết nói. Cô ấy sẽ xây cho bạn một ứng dụng, viết tài liệu, dạy bạn điều gì đó từ đầu, thiết kế logo, hoặc lo phần công việc hành chính bạn vẫn hay trì hoãn. Và cô ấy nhớ về bạn: những gì bạn đang làm, cách bạn thích mọi thứ, và những gì bạn đã hỏi tuần trước.","start.what#1#p":"Chỉ có một Ava duy nhất, và cô ấy hoạt động ở bất cứ đâu bạn làm việc — trong trình soạn thảo mã của bạn, như một ứng dụng trên máy tính để bàn, trên điện thoại, hoặc trong terminal. Cùng trí nhớ, cùng cá tính, ở khắp mọi nơi.","start.what#2#h":"Điều gì làm nên sự khác biệt của cô ấy","start.what#3#li0":"Mặc định là của riêng bạn. Công việc của bạn luôn ở trên máy của chính bạn. Không theo dõi, không thu thập dữ liệu — bao giờ cũng vậy.","start.what#3#li1":"Mở cho bất kỳ ai xem. Mọi dòng mã của Ava đều công khai. Không cần phải tin tưởng mù quáng.","start.what#3#li2":"Miễn phí để bắt đầu. 300 điểm mỗi tháng, không cần thẻ, không điều kiện ẩn — hoặc tự cắm khóa AI của bạn vào và chẳng cần trả chúng tôi đồng nào.","start.what#3#li3":"Việc dạy học miễn phí mãi mãi. Học tập không nên có giá tiền.","start.what#4#p":"Chưa từng viết mã bao giờ? Trang tiếp theo được viết riêng cho bạn. Đã quen kỹ thuật? Bỏ qua phần này — cô ấy sẽ theo kịp bạn.","start.what#deeper#0#h":"Ava sống ở đâu","start.what#deeper#1#li0":"Tiện ích mở rộng VS Code — Ava bên cạnh trình soạn thảo của bạn: bảng trò chuyện, bảng điều khiển, và các thay đổi được hiển thị trực tiếp trước khi chúng xảy ra.","start.what#deeper#1#li1":"IDE trên máy tính để bàn — ứng dụng độc lập với toàn bộ mọi thứ trong một cửa sổ. Thêm quyền kiểm soát máy tính (mở ứng dụng, nhấp chuột, gõ phím thay bạn).","start.what#deeper#1#li2":"Người đồng hành — ứng dụng di động dành cho lúc bạn rời khỏi bàn làm việc: nhiệm vụ, nhật ký, trí nhớ, trò chuyện nhanh.","start.what#deeper#1#li3":"CLI — Ava trong terminal của bạn, dành cho những người sống ở đó.","start.what#deeper#2#h":"Cách cô ấy hoạt động, tóm tắt","start.what#deeper#3#p":"Ava chuyển đổi tư duy (gọi là chế độ) để phù hợp với công việc, âm thầm vận hành một nhóm nhỏ trợ lý chuyên gia cho những việc khó, và chọn mô hình AI tốt nhất cho từng bước tự động. Bạn không bao giờ phải quản lý bất cứ thứ gì trong số đó. Phần Khái niệm Cốt lõi có bản hướng dẫn đầy đủ bất cứ khi nào bạn tò mò.","start.first-five#title":"Việc đầu tiên của bạn với Ava","start.first-five#0#p":"Cách nhanh nhất để dùng Ava là yêu cầu cô ấy làm một việc cụ thể và xem cô ấy làm. Không cần đọc hướng dẫn cài đặt, không cần học gì trước — chỉ cần nói cho cô ấy biết bạn muốn gì, bằng lời đơn giản.","start.first-five#1#h":"Thử ngay bây giờ","start.first-five#2#li0":"Mở cuộc trò chuyện.","start.first-five#2#li1":"Gõ thứ bạn thực sự muốn. Thử \"giải thích dự án này làm gì\", hoặc \"thêm nút xóa biểu mẫu\".","start.first-five#2#li2":"Ava hiện cho bạn thấy cô ấy sắp làm gì — và chờ đợi.","start.first-five#2#li3":"Hài lòng chưa? Nói đồng ý. Xem cô ấy làm đi.","start.first-five#3#p":"Đó là nhịp điệu hoàn chỉnh: bạn hỏi, cô ấy hiện kế hoạch cho bạn, bạn phê duyệt, cô ấy làm. Cô ấy không bao giờ thay đổi gì mà không hiện cho bạn xem trước — nên bạn không thể làm hỏng gì cả khi thử.","start.first-five#4#h":"Một vài điều đáng để yêu cầu","start.first-five#5#li0":"Một câu hỏi — “tại sao trang của tôi lại trắng?”, “tệp này làm gì?”","start.first-five#5#li1":"Một thứ được tạo ra — “làm cho tôi một trang danh sách việc cần làm đơn giản”.","start.first-five#5#li2":"Để học điều gì đó — “dạy tôi Python từ đầu”. (Luôn miễn phí.)","start.first-five#5#li3":"Một tài liệu — “viết cho tôi đề xuất dự án một trang”. Cô ấy sẽ gửi bạn tệp Word hoặc PDF.","start.first-five#6#c":"Không chắc phải gõ gì? Hãy trò chuyện với cô ấy như một người bạn am hiểu. Từ ngữ bình thường là hoàn toàn đúng — bạn không bao giờ cần thuật ngữ kỹ thuật để bắt đầu.","start.first-five#deeper#0#p":"Vòng lặp đơn giản đó đang xử lý khá nhiều việc phía sau hậu trường. Bạn không cần biết những điều này để dùng Ava — nhưng đây là những gì thực sự xảy ra nếu bạn tò mò.","start.first-five#deeper#1#h":"Công cụ và phê duyệt","start.first-five#deeper#2#p":"Khi Ava đọc tệp, chạy lệnh, hoặc chỉnh sửa mã, mỗi việc đó là một “lời gọi công cụ”. Cô ấy hỏi trước khi làm bất cứ điều gì chạm đến tệp hoặc hệ thống của bạn — tần suất cô ấy hỏi được đặt bởi chế độ quyền hạn của bạn (hỏi mọi lần, chỉ hỏi khi rủi ro, hoặc cứ thế mà đi).","start.first-five#deeper#3#h":"Chế độ — trạng thái tâm trí của cô ấy","start.first-five#deeper#4#p":"Ava hoạt động theo các chế độ: tư duy cộng với bộ công cụ phù hợp cho công việc. Chuyển đổi bất cứ lúc nào từ trình chọn, hoặc gõ tiền tố ở đầu tin nhắn của bạn. Có bảy cái.","start.first-five#deeper#6#h":"Chuyên gia và định tuyến","start.first-five#deeper#7#p":"Với các công việc khó hơn, Ava chạy một nhóm nhỏ trợ lý chuyên gia phía sau hậu trường (người lập kế hoạch, người kiểm tra, người xây dựng) và định tuyến từng bước đến mô hình giỏi nhất về nó. Bạn không bao giờ quản lý việc này — cô ấy phối hợp nó thay bạn.","start.local-vs-cloud#title":"Cục bộ so với đám mây, trong một đoạn văn","start.local-vs-cloud#0#p":"Mọi thứ Ava làm đều cục bộ trừ khi bạn chủ động đồng ý. Bộ nhớ, nhiệm vụ, nhật ký, tính cách, cài đặt — tất cả lưu trên máy của bạn tại ~/.ava/ và .ava/ (theo dự án). Cô ấy nói chuyện với nhà cung cấp mô hình qua HTTPS để chạy yêu cầu của bạn, rồi trở về nhà. Cô ấy không gọi về nhà. Cô ấy không thu thập dữ liệu theo dõi. Cô ấy không huấn luyện trên mã của bạn.","start.local-vs-cloud#1#p":"Nếu đăng nhập, bạn nhận được 300 tín dụng miễn phí mỗi tháng trên các mô hình do nền tảng quản lý (Qwen, MiniMax) và đồng bộ đám mây tùy chọn cho bộ nhớ và cài đặt giữa các máy. Đồng bộ theo tính năng, có thể hủy bất cứ lúc nào. Mang theo khóa API của riêng bạn và Ava hoạt động đầy đủ mà không cần tài khoản.","start.local-vs-cloud#2#c":"Quy tắc: Cục bộ là tối thượng. Đám mây là bổ sung.","start.first-model#title":"Tôi có cần chọn AI không?","start.first-model#0#p":"Đây là tin vui: bạn không cần chọn AI. Ava tự động chọn đúng cái cho mỗi bước, nên bạn có kết quả tốt mà không cần nghĩ ngợi.","start.first-model#1#p":"Điều duy nhất bạn có thể chọn là kiểu định tuyến — và mặc định phù hợp với hầu hết mọi người. Bạn chỉ cần những cái khác vì lý do cụ thể.","start.first-model#2#h":"Ba kiểu","start.first-model#3#li0":"Maestro — mặc định. Ổn định, đáng tin cậy, dễ đoán. Không chắc? Đây là cái bạn cần.","start.first-model#3#li1":"Supernova — cho công việc nặng, nhiều bước, nơi việc giao mỗi phần cho một chuyên gia khác sẽ hiệu quả hơn.","start.first-model#3#li2":"Aurora — khi dữ liệu của bạn phải ở trong EU (công cộng, y tế, bảo mật nghiêm ngặt). Chạy hoàn toàn trên AI nguồn mở châu Âu.","start.first-model#4#p":"Chuyển bất cứ lúc nào từ trình chọn mô hình ở đầu cuộc trò chuyện. Không có gì bị khóa chặt.","start.first-model#5#c":"Muốn tự lái một mô hình cụ thể? Bạn có thể — mở “Hiện chi tiết cho tôi”.","start.first-model#deeper#0#h":"Mỗi phong cách thực sự bao gồm những gì","start.first-model#deeper#1#p":"Maestro — một nhạc trưởng (Qwen 3.6 Plus) điều hành mọi bước. Đã tối ưu cho sản xuất, đã được chứng minh, chi phí dự đoán được.","start.first-model#deeper#2#p":"Supernova — một người phối hợp tiên phong (DeepSeek V4 Pro, 1.6T tham số / 49B hoạt động, ngữ cảnh 1M) giao mỗi nhiệm vụ nhỏ cho chuyên gia: V4 Flash cho các bản dựng khối lượng lớn, Qwen 3.6 Plus làm phương án dự phòng, Qwen Omni cho xử lý hình ảnh.","start.first-model#deeper#3#p":"Aurora — chỉ dùng Mistral, chia làm ba cấp: Mistral Large 3 (người phối hợp + chuyên gia mạnh), Mistral Medium 3.5 (128B dense, ngữ cảnh 256K, xử lý hình ảnh gốc, trọng lượng mở MIT sửa đổi, 77.6% SWE-Bench Verified) dành cho người xây dựng + tầm trung + xử lý hình ảnh + văn bản dài, và Mistral Small 4 ở cổng ý định. Trọng lượng mở từ đầu đến cuối, không bao giờ rời khỏi hạ tầng EU.","start.first-model#deeper#4#h":"Tự mang mô hình của bạn (BYOK)","start.first-model#deeper#5#p":"Thích dùng tài khoản AI của riêng bạn? Dán khóa nhà cung cấp vào cài đặt và bạn sẽ nhận được cả hai — ba phong cách định tuyến, cộng thêm tùy chọn chọn một mô hình duy nhất và bỏ qua định tuyến hoàn toàn. Hữu ích cho sở thích cá nhân, ngân sách chặt chẽ, hoặc thử nghiệm một mô hình cụ thể. Danh sách đầy đủ nhà cung cấp có trong phần Tham khảo.","start.glossary#title":"Từ điển tiếng Việt đơn giản","start.glossary#0#p":"Mọi từ bạn có thể gặp quanh Ava, được giải thích mà không cần kiến thức nền. Bạn không cần phải nhớ hết — quay lại bất cứ khi nào một thuật ngữ làm bạn bối rối.","start.glossary#1#th0":"Từ","start.glossary#1#th1":"Ý nghĩa thực sự","start.glossary#1#td0.0":"Tác nhân","start.glossary#1#td0.1":"Một AI có thể thực hiện hành động thay bạn — đọc tệp, chạy lệnh, tìm kiếm web — không chỉ trò chuyện. Ava là một Tác nhân: cô ấy làm việc, với sự cho phép của bạn.","start.glossary#1#td1.0":"Mô hình","start.glossary#1#td1.1":"Bộ não AI thực tế đang suy nghĩ (Qwen, DeepSeek, Mistral, và những cái khác). Các mô hình khác nhau có điểm mạnh khác nhau. Bình thường bạn không bao giờ chọn một cái — Ava làm điều đó.","start.glossary#1#td2.0":"Chế độ","start.glossary#1#td2.1":"Tâm thế của Ava lúc này. Giống như đồng nghiệp đổi mũ: người xây dựng, người viết, người dạy, người lập kế hoạch, bạn bè. Bạn chọn chế độ; nó thay đổi cách cô ấy hành xử. Có bảy loại.","start.glossary#1#td3.0":"Nhân vật / chuyên gia","start.glossary#1#td3.1":"Vai trò trợ lý Ava chạy ngầm cho các công việc khó hơn — người khám phá, người lập kế hoạch, người kiểm tra sự thật. Hãy tưởng tượng một đội ngũ chuyên gia nhỏ. Bạn không bao giờ nói chuyện trực tiếp với họ; Ava điều phối họ.","start.glossary#1#td4.0":"Định tuyến","start.glossary#1#td4.1":"Ava quyết định dùng mô hình nào cho mỗi bước để bạn có câu trả lời tốt mà không tốn kém quá. Nó xảy ra tự động — \"chế độ định tuyến\" chỉ chọn chiến lược tổng thể.","start.glossary#1#td5.0":"Công cụ","start.glossary#1#td5.1":"Hành động cụ thể Ava có thể làm — đọc tệp, tìm kiếm, gửi email. Một \"lời gọi công cụ\" là cô ấy dùng một cái. Cô ấy xin phép trước mọi thứ rủi ro.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Cách AI đo lường văn bản — khoảng ¾ từ. Mô hình tính giá theo triệu token. Chủ yếu là thứ bạn có thể bỏ qua.","start.glossary#1#td7.0":"Tín dụng","models.routing#deeper#2#td5.0":"Trò chuyện","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Điều phối tạo ảnh","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Thị giác","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (mô hình nhận diện hình ảnh được huấn luyện từ đầu)","models.routing#deeper#2#td8.0":"Viết nội dung dài","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Vị trí lưu trữ dữ liệu","models.routing#deeper#2#td9.1":"Hỗn hợp (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Hỗn hợp (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Chỉ EU · trọng số mở","models.routing#deeper#2#td10.0":"Trạng thái","models.routing#deeper#2#td10.1":"Đang hoạt động · tất cả gói","models.routing#deeper#2#td10.2":"Sắp ra mắt","models.routing#deeper#2#td10.3":"Sắp ra mắt","models.routing#deeper#2#td11.0":"Phù hợp nhất cho","credits.overview#8#li4":"Điều phối — 10 điểm. Khởi chạy trọn vẹn quy trình nhân cách (Người dẫn dắt + nhiệm vụ đa nhân cách).","credits.overview#8#li5":"Tạo ảnh — 12 điểm. Hailuo image-01 thông qua Creative Studio.","credits.overview#8#li6":"Tạo video — 150 điểm. Hailuo 02 Pro clip 1080p trong 6 giây.","credits.overview#8#li7":"Tạo giọng nói — 10 điểm. Tổng hợp Speech 2.8 HD.","credits.overview#8#li8":"Tạo nhạc — 50 điểm. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Xóa nền — 2 điểm.","credits.overview#9#h":"Hệ số nhân theo từng mô hình","credits.overview#10#p":"Phần này dành cho những ai tò mò — bạn không cần biết nó để dùng Ava. Hệ số nhân chỉ điều chỉnh chi phí điểm tăng hay giảm tùy theo độ đắt đỏ của mô hình đằng sau hành động, nên các mô hình 'nặng' hơn sẽ tốn nhiều điểm hơn một chút. (\"Lợi nhuận ròng\" là phần dự án giữ lại sau khi trừ chi phí — chúng tôi cố gắng giữ ở mức thấp để giá trị thực sự quay về cho bạn.)","credits.overview#11#p":"Các mô hình nặng hơn sẽ nhân đôi chi phí hành động để điểm tín dụng phản ánh đúng chi tiêu thực tế thay vì một mức cố định. Đã được hiệu chuẩn với ~55% lợi nhuận ròng.","credits.overview#12#li0":"0.6× — Mistral Small 4 (Chỗ ngồi chuyên gia của Aurora). Thấp hơn 1× vì Mistral Small 4 rẻ hơn mốc neo Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Mức giá gốc.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (Người điều phối của Aurora). Khoảng tương đương với mốc neo Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (Người điều phối Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (Người điều phối Supernova + chuyên gia nặng). Đã hiệu chỉnh lại từ 5.0× để đảm bảo cân bằng lợi nhuận theo mức giá công bố của V4 Pro.","credits.overview#13#c":"Mô hình Anthropic (Claude Opus / Sonnet / Haiku) hoàn toàn không tính phí điểm — chúng chỉ áp dụng BYOK và bạn trả tiền trực tiếp cho Anthropic. Điều này cũng đúng với bất kỳ nhà cung cấp BYOK nào khác khi sử dụng khóa riêng của bạn.","credits.overview#14#h":"BYOK và điểm tín dụng","credits.overview#15#p":"BYOK (\"mang khóa của riêng bạn\" — bạn tự cung cấp tài khoản của mình với nhà cung cấp AI và một khóa bí mật, giống như mật khẩu cho phép phần mềm sử dụng tài khoản đã trả phí đó) dành cho những ai đã trả tiền trực tiếp cho nhà cung cấp AI. Nếu không phải trường hợp của bạn, bạn có thể bỏ qua mục này hoàn toàn.","credits.overview#16#p":"Yêu cầu mang khóa riêng sẽ bỏ qua hoàn toàn cơ sở hạ tầng nền tảng — yêu cầu đi thẳng từ Ava đến nhà cung cấp, bạn trả tiền cho nhà cung cấp, không điểm nào bị tiêu hao. Ngoại lệ duy nhất là khi phiên bản BYOK khởi tạo nhân cách cấp quản lý cho một nhiệm vụ con; việc trừ điểm vẫn được áp dụng vì bề mặt điều phối của Ava đang được sử dụng.","credits.overview#17#h":"Nơi kiểm tra số dư của bạn","credits.overview#18#li0":"Tiện ích mở rộng — Cài đặt → Tài khoản, hoặc thanh điểm tín dụng ở đầu khung chat.","credits.overview#18#li1":"IDE — Bảng điều khiển Tài khoản hiển thị số dư hiện tại và tốc độ tiêu hao.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard hiển thị số dư, lịch sử và ngày gia hạn.","credits.overview#19#c":"Ưu tiên cục bộ: Ava hoạt động mà không cần tài khoản trên thẻ Mô hình Tùy chỉnh (Ollama, LM Studio, vLLM, hoặc bất kỳ điểm kết nối tương thích OpenAI nào). Không điểm tín dụng, không token nền tảng — mô hình của bạn, máy của bạn, hóa đơn bằng không.","concepts.modes#title":"Chế độ — Các trạng thái tư duy của Ava","models.routing#deeper#2#td11.1":"Công việc hàng ngày, chi phí dự đoán được","models.routing#deeper#2#td11.2":"Công việc phức tạp nhiều bước, điều phối viên tiên phong trong mọi gói","models.routing#deeper#2#td11.3":"Tuân thủ GDPR nghiêm ngặt, khu vực công, hạ tầng chủ quyền EU","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Phân tuyến Qwen theo cấp độ, tiêu tốn ít tài nguyên. Qwen 3.6 Plus đảm nhận vai trò điều phối, xây dựng, lập kế hoạch, bảo mật, brainstorm và xử lý ngữ cảnh dài — nơi khả năng xử lý ngữ cảnh 1 triệu của nó phát huy tác dụng. Qwen 3.5 Flash xử lý chat, điều phối tạo ảnh và cổng ý định đầu vào, nơi mức giá $0.07/$0.26 và thời gian bắt đầu phản hồi nhanh hơn giúp tối ưu khối lượng token độ sâu thấp. Qwen 3.5 Omni Plus chịu trách nhiệm đầu vào hình ảnh (Qwen 3.6 Plus không có thị giác gốc). Qwen 3.5 Plus đảm nhận công việc văn bản dài nhạy cảm về chi phí. Hệ thống sẽ rơi xuống thang ưu tiên Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash nếu điều phối viên chính không khả dụng.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Tập hợp đa ngôn ngữ. DeepSeek V4 Pro điều phối và phân bổ mỗi nhiệm vụ con tới chuyên gia phù hợp nhất: Qwen 3.6 Plus chạy mọi khởi tạo Builder, V4 Flash xử lý chat cùng nhân vật kiểm tra/thẩm định cấp trung, Qwen 3.5 Flash hấp thụ công việc phân loại cấp nhẹ, Qwen 3.5 Omni Plus chịu trách nhiệm đầu vào hình ảnh, Qwen 3.5 Omni Flash điều phối lệnh gọi công cụ tạo ảnh, Qwen 3.5 Plus đảm nhận nhân vật Content Writer nhạy cảm chi phí. Lập luận tiên phong ở nơi cần thiết, kinh tế học cấp Flash cho phần lớn khối lượng token.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Hạ tầng AI châu Âu — thiết kế chủ quyền. Phân tuyến chỉ dùng Mistral ở ba cấp độ: Mistral Large 3 (675B/41B-active sparse MoE) đảm nhận vai trò điều phối cùng các chuyên gia nặng cần chiều sâu — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — và công việc ngữ cảnh dài nơi hiệu suất MoE thưa thắng thế. Mistral Medium 3.5 — flagship hợp nhất ra mắt tháng 4 năm 2026, 128B dense, ngữ cảnh 256K, encoder thị giác huấn luyện từ đầu, trọng số mở MIT đã sửa đổi, 77.6% SWE-Bench Verified — chạy tầng làm việc thực tế: khởi tạo Builder, chuyên gia cấp trung (Architect, Verifier, Sequencer, Tutor, Reporter), đầu vào thị giác và viết văn bản dài. Mistral Small 4 mở rộng từ một vai trò tại cổng ý định sang cả xử lý chat và điều phối tạo ảnh — mức giá $0.15/$0.60 và khả năng suy luận cấu hình giúp chúng xứng đáng trên các tuyến độ sâu thấp lưu lượng cao. Trọng số mở từ đầu đến cuối, không bao giờ rời khỏi hạ tầng EU. Aurora cố tình không tự động chuyển hướng sang mô hình ngoài Mistral khi một mô hình không khả dụng; trình định tuyến sẽ hiện lỗi thay vào đó — đó chính là điều khiến nó trở thành \"Aurora\" chứ không phải một Maestro hương vị Mistral.","credits.overview#title":"Ava Credits — cách thức tính phí hoạt động","credits.overview#0#p":"Credits đơn giản là cách Ava đếm những gì bạn dùng — giống như phút trên gói cước điện thoại. Mọi gói, kể cả gói miễn phí, đều đi kèm một kho credits, và mỗi việc Ava làm (trả lời bạn, tạo ảnh) đều tốn một số lượng nhỏ credits. Đó là toàn bộ ý tưởng. Chi tiết dưới đây dành cho khi bạn muốn biết chính xác mỗi thứ tốn bao nhiêu.","credits.overview#1#p":"Ava tính phí bằng credits, không phải bằng token thô. (Một \"token\" là đoạn văn bản nhỏ — khoảng vài chữ cái — mà các mô hình AI đọc và viết; hầu hết các dịch vụ tính phí bạn theo token, điều này khó dự đoán.) Một credit bao phủ một đơn vị công việc — một lượt chat, khởi tạo một vai trò (một trợ lý làm một phần của nhiệm vụ), tạo ảnh. Việc tách biệt khỏi đo lường theo token nghĩa là bạn không cần biết mô hình nào đang chạy để biết một hành động sẽ tốn bao nhiêu. Cùng một lượt chat sẽ tốn như nhau dù Maestro phân tuyến nó tới Qwen 3.6 Plus hay Supernova phân tuyến nó tới V4 Pro.","credits.overview#2#h":"Các gói","credits.overview#3#p":"Mọi gói đều truy cập mọi tính năng — truy cập mô hình, Creative Studio, bảy chế độ đầy đủ, điều phối vai trò trọn vẹn. Các gói cao hơn mua thêm credits và giới hạn tốc độ cao hơn, chứ không mở khóa tính năng.","credits.overview#4#li0":"Miễn phí — $0/tháng. 300 credits. Giới hạn tốc độ 20 yêu cầu/phút. Không cần thẻ.","credits.overview#4#li1":"Pro — $19/tháng. 5,000 credits. 60 yêu cầu/phút.","credits.overview#4#li2":"Ultra — $39/tháng. 10,000 credits. 120 yêu cầu/phút.","credits.overview#4#li3":"Doanh nghiệp — $79/tháng. 20,000 credits. 200 yêu cầu/phút.","credits.overview#5#c":"Credits chưa dùng sẽ được chuyển tiếp trong khi đăng ký còn hiệu lực — không có thu hồi bắt buộc. Nạp thêm chồng lên kho gói đăng ký: 750 credits cho $3, 2,000 cho $8, 4,000 cho $15.","credits.overview#6#h":"Chi phí cho từng thứ","credits.overview#7#p":"Bảng chi phí theo từng hành động — những gì bị trừ khỏi kho credits của bạn khi mỗi hành động chạy. (Một \"cache hit\" là khi Ava tái sử dụng công việc đã làm thay vì làm lại; khi đó bạn trả ít hơn — khoản phí giảm 70%, hoặc 50% trên các mô hình nặng xuất như DeepSeek V4 Pro.)","credits.overview#8#li0":"Vòng chat — 2 credits. Một lượt qua lại đơn lẻ trong bất kỳ chế độ nào.","credits.overview#8#li1":"Lệnh nhẹ — 1 credit. Cổng ý định, phân loại, đọc đơn lần.","credits.overview#8#li2":"Vai trò nặng — 3 credits. Architect, Researcher, CVE Researcher, Ideator (chiều sâu ≥ 4).","credits.overview#8#li3":"Vai trò nhẹ — 1 credit. Scout, Verifier, Sequencer, Challenger (chiều sâu ≤ 2).","concepts.desktop-safety#3#li2":"Thay đổi có thể hoàn tác — gõ vào ô nhập liệu, dán nội dung, mở ứng dụng, điều hướng URL. Xác nhận ở chế độ Ask; tự động trong Drive nếu nằm trong danh sách trắng.","concepts.desktop-safety#3#li3":"Thay đổi không thể hoàn tác — gửi, nộp, thanh toán, xóa, xác nhận, xuất bản. Luôn xác nhận, bất kể cấp độ quyền hạn. Việc phê duyệt không bao giờ được lưu lại.","concepts.desktop-safety#3#li4":"Quyền đặc quyền — nâng cao quyền UAC, sudo, chỉnh sửa registry, yêu cầu thông tin xác thực. Bị cấm theo mặc định. Cần chọn tham gia dùng một lần cho mỗi phiên.","concepts.desktop-safety#4#h":"Phê duyệt không lưu bộ nhớ đệm","concepts.desktop-safety#5#p":"Mọi đối thủ cạnh tranh đều lưu bộ nhớ đệm các phê duyệt (nhớ câu \\\"yes\\\" của bạn và tái sử dụng nó lần sau). Đó là lỗ hổng lớn nhất cho prompt injection — một cuộc tấn công nơi trang web bị cài bẫy lén đưa hướng dẫn ẩn vào AI để khiến nó hành động chống lại bạn. Nếu phê duyệt được lưu, trang bị xâm phạm có thể lợi dụng câu \\\"yes\\\" bạn đã đưa trước đó. Ava không bao giờ lưu. Mỗi thao tác thay đổi không thể hoàn tác đều hỏi lại mới.","concepts.desktop-safety#6#h":"Xử lý bí mật","concepts.desktop-safety#7#p":"Mật khẩu, API keys và 2FA codes (các mã dùng một lần mà ứng dụng thứ hai hoặc tin nhắn gửi cho bạn khi đăng nhập) được xử lý qua các biểu tượng mờ — vị trí giữ chỗ đại diện cho giá trị thật. Ava thấy \\\"{secret}\\\", không phải mật khẩu thật. Giá trị thật không bao giờ vào bộ nhớ, nhật ký hoạt động hay những gì cô ấy \\\"đọc\\\" — một lớp riêng biệt ở mức thấp sẽ gõ nó vào lúc cuối cùng, tại lúc nhấn phím, nên phần AI không bao giờ chạm vào nó.","reference.cli#title":"Lệnh CLI","reference.cli#0#p":"Trang này dành cho CLI — phiên bản của Ava bạn gõ lệnh trong cửa sổ terminal, thay vì bấm nút. Nếu dùng tiện ích mở rộng hoặc ứng dụng máy tính, bạn có thể bỏ qua hoàn toàn. Nó ở đây cho những người thích dùng bàn phím.","reference.cli#1#p":"CLI là một REPL — một lời nhắc chờ bạn gõ, chạy những gì bạn gõ, rồi lại chờ. Các lệnh gạch chéo (hướng dẫn bắt đầu bằng \\\"/\\\") hoạt động từ lời nhắc này.","reference.cli#2#li0":"/help — liệt kê lệnh và chế độ hiện tại.","reference.cli#2#li1":"/mode <name> — chuyển chế độ (làm việc, viết, lập kế hoạch, trò chuyện, dạy, bảo mật, động não).","reference.cli#2#li2":"/model <id> — chuyển mô hình mà không rời phiên làm việc.","reference.cli#2#li3":"/clear — xóa hội thoại hiện tại. Bộ nhớ không bị ảnh hưởng.","reference.cli#2#li4":"/history — liệt kê hội thoại cũ trong dự án này.","reference.cli#2#li5":"/memory — mở trình duyệt bộ nhớ.","reference.cli#2#li6":"/tasks — liệt kê và quản lý nhiệm vụ.","reference.cli#2#li7":"/journal — mở mục nhật ký hôm nay.","reference.cli#2#li8":"/settings — mở menu cài đặt.","reference.cli#2#li9":"/exit — thoát REPL.","reference.cli#3#h":"Cờ khởi động","reference.cli#4#p":"Cờ lệnh là các tùy chọn thêm bạn thêm khi khởi động Ava, mỗi cái bắt đầu bằng \\\"--\\\", để thiết lập cách cô ấy khởi động.","reference.cli#5#li0":"--mode <name> — khởi động ở chế độ cụ thể.","reference.cli#5#li1":"--model <id> — khởi động với mô hình cụ thể.","reference.cli#5#li2":"--permission <mode> — nghiêm ngặt / cân bằng / tự động.","concepts.modes#0#p":"Chế độ là tâm thế của Ava — giống như đồng nghiệp đổi vai trò vậy. Vẫn là một người, vẫn nhớ về bạn, nhưng người xây dựng suy nghĩ khác người giảng dạy. Bạn chọn chế độ, và điều đó thay đổi cách cô ấy hành động cũng như nhóm trợ lý đi kèm. Có thể chuyển bất kỳ lúc nào qua bộ chọn chế độ, hoặc gõ phím tắt hai ký tự.","concepts.modes#2#h":"Bạn muốn cái nào?","concepts.modes#3#p":"Bắt đầu từ việc bạn đang cố làm gì — chế độ sẽ phù hợp với mục đích đó:","concepts.modes#4#li0":"Tôi muốn tạo ra hoặc thay đổi thứ gì đó → Code (>>). Bạn mô tả, cô ấy xây dựng, hiển thị mọi thay đổi trước cho bạn xem. Nhóm trợ lý đầy đủ sẽ tham gia cho các công việc lớn hơn.","concepts.modes#4#li1":"Tôi muốn có kế hoạch trước khi có bất kỳ thay đổi nào → Plan (::). Cô ấy suy nghĩ kỹ và đưa ra kế hoạch để bạn phê duyệt hoặc chỉnh sửa. Cô ấy sẽ không chạm vào tệp của bạn ở chế độ này.","concepts.modes#4#li2":"Tôi chỉ muốn trò chuyện hoặc hỏi → Chat (..). Một đối tác tư duy có trí nhớ, tin tức và thời tiết. Không thay đổi tệp, không mã — chỉ là trò chuyện.","concepts.modes#4#li3":"Tôi muốn học điều gì đó → Teach (??). Một khóa học thực sự được xây dựng riêng cho bạn: bài học, bài kiểm tra, tất cả mọi thứ. Miễn phí trên mọi gói, mãi mãi. Hoàn hảo nếu bạn mới bắt đầu.","concepts.modes#4#li4":"Tôi muốn dự án của mình được kiểm tra lỗ hổng bảo mật → Security (!!). Một nhóm làm việc dựa trên danh sách tiêu chuẩn các lỗ hổng web phổ biến (danh mục \"OWASP\") và các lỗi đã biết (gọi là \"CVEs\"), sau đó trao báo cáo cho bạn sắp xếp theo mức độ nghiêm trọng. Mục này dành cho lập trình viên — bỏ qua nếu bạn không thuộc nhóm đó.","concepts.modes#4#li5":"Tôi muốn ý tưởng → Brainstorm (**). Cô ấy tạo ra các lựa chọn dựa trên tình huống thực tế của bạn, chỉ ra điểm yếu và tinh chỉnh phần còn lại thành các bước tiếp theo.","concepts.modes#4#li6":"Tôi muốn viết tài liệu → Write (<<). Báo cáo, đề xuất, thư, bài viết — cô ấy soạn thảo bằng Markdown và xuất tài liệu Word hoặc PDF có thương hiệu, tinh chỉnh từng phần. Không mã, chỉ viết.","concepts.modes#5#c":"\"Nhóm trợ lý\" (nhân vật) chạy hoàn toàn phía sau hậu trường — bạn không bao giờ nói chuyện trực tiếp với họ. Bạn chỉ nhận được câu trả lời chi tiết hơn. Bạn không cần biết tên của họ.","concepts.modes#6#c":"Bạn có thể chuyển chế độ giữa cuộc trò chuyện. Ký ức của bạn được giữ nguyên; các chuyên gia sẽ khởi động lại để phù hợp với chế độ mới.","concepts.tasks-journal#title":"Nhiệm vụ và nhật ký","concepts.tasks-journal#0#p":"Ava lưu ba loại ghi chú cho bạn, rất dễ nhầm lẫn. Mẹo nhớ nhanh: Ký ức là những gì cô ấy biết về bạn, Nhiệm vụ là những gì bạn cần làm tiếp, và Nhật ký là cuốn sổ ghi lại diễn biến sự việc. Dưới đây là khi nào nên dùng cái nào.","concepts.tasks-journal#1#li0":"Ký ức — thông tin tồn tại lâu dài. Sở thích, quyết định, thói quen. Thường xuyên được nhắc đến, hiếm khi tạo thủ công.","concepts.tasks-journal#1#li1":"Nhiệm vụ — việc cần làm. Các mục hành động với hạn chót và trạng thái. Bạn đánh dấu xong khi hoàn thành.","concepts.tasks-journal#1#li2":"Nhật ký — suy ngẫm. Ghi chép hàng ngày, hai cột (của bạn và quan sát của Ava về buổi làm việc). Hữu ích cho theo dõi tâm trạng, xem lại buổi làm việc, ngữ cảnh cho ngày mai.","concepts.tasks-journal#2#p":"Ava ghi chép vào cả ba khi cần thiết. Bạn có thể viết trực tiếp vào bất kỳ mục nào từ bảng điều khiển. Không có gì bị giới hạn ở một nơi duy nhất bạn dùng Ava — một nhiệm vụ bạn tạo ở nơi này (ví dụ công cụ dòng lệnh) sẽ tự động hiện ra ở mọi nơi khác (như ứng dụng máy tính để bàn).","concepts.permissions#title":"Quyền truy cập — núm vặn an toàn của bạn","concepts.permissions#0#p":"Quyền truy cập là núm vặn an toàn của bạn. Nó quyết định khi nào Ava xin phép bạn trước khi thực hiện việc gì trên máy tính, thay vì tự động làm luôn. Bạn có thể cài đặt để cô ấy hỏi mọi thứ, chỉ hỏi việc rủi ro, hoặc tin tưởng cô ấy tự hành động — và bạn có thể thay đổi bất cứ lúc nào. Nếu chưa chắc chắn, hãy để mặc định và bạn sẽ ổn.","concepts.permissions#1#p":"Ava có 60 công cụ (\"công cụ\" là các hành động cô ấy có thể thực hiện — đọc tệp, tìm kiếm web, v.v.). Mỗi công cụ thuộc một danh mục (thao tác tệp, shell, git, web, đa phương tiện, cơ sở dữ liệu, hệ thống, tài liệu, ký ức, học tập). Mọi lệnh gọi công cụ đều đi qua cổng quyền (một điểm kiểm soát quyết định có hỏi bạn trước hay không) trước khi chạy. Bạn kiểm soát cái nào được tự động chấp thuận, cái nào hỏi một lần, và cái nào luôn hỏi.","concepts.permissions#3#p":"Cân bằng là mặc định. Nghiêm ngặt khi bạn đang kiểm tra hành vi của cô ấy (theo dõi kỹ để kiểm tra từng bước). Tự chủ khi bạn muốn cô ấy cứ làm.","concepts.permissions#4#c":"Tự chủ không có nghĩa là không kiểm soát. Kế hoạch, câu hỏi làm rõ, và yêu cầu rõ ràng vẫn tạm dừng chờ nhập của bạn. Các thao tác không thể đảo ngược (git force-push, xóa cơ sở dữ liệu) luôn xác nhận bất kể chế độ.","concepts.interjection#title":"Điều hướng và dừng Ava","concepts.interjection#0#p":"Bạn luôn nắm quyền. Khi Ava đang bận làm việc, bạn có thể nhẹ nhàng gợi ý hướng mới mà không làm gián đoạn tiến độ, hoặc dừng cô ấy ngay lập tức. Hai nút bấm, hai kết quả — đó là nội dung chính của trang này.","reference.cli#5#li3":"--project <path> — chỉ định gốc dự án một cách rõ ràng.","reference.desktop-budget#title":"Giới hạn ngân sách trên Desktop","reference.desktop-budget#0#p":"Khi Ava điều khiển máy tính giúp bạn — nhấp chuột, gõ phím, mở ứng dụng — mỗi lượt thực hiện được gọi là một \"hành trình\". Trang này giải thích các giới hạn an toàn để ngăn mọi lượt chạy kéo dài quá lâu hoặc tốn kém quá nhiều. Điều quan trọng nhất: cô ấy luôn dừng lại và xác nhận với bạn trước khi vượt quá giới hạn. Các con số cụ thể có sẵn ở đây nếu bạn muốn xem chi tiết.","reference.desktop-budget#1#p":"Mọi hành trình đều chạy dưới ba mức giới hạn đồng thời (giới hạn cứng). Giới hạn nào bị chạm trước sẽ được áp dụng. Hành trình không bao giờ tiếp tục âm thầm sau khi vượt quá — Narrator (người trợ giúp hướng dẫn bạn những gì đang diễn ra) sẽ tạm dừng và hỏi bạn nên làm gì.","reference.desktop-budget#2#h":"Ba giới hạn cứng (mặc định)","reference.desktop-budget#3#li0":"Số bước — 30 bước","reference.desktop-budget#3#li1":"Ngân sách Token — 500,000 tokens","reference.desktop-budget#3#li2":"Thời gian thực — 5 phút","reference.desktop-budget#4#h":"Các nhóm chi phí nhiệm vụ","reference.desktop-budget#5#li0":"Đơn giản (tìm kiếm tài liệu, mở một trang) — 5–10 bước, ~70–135K tokens, ~$0.04–0.08","reference.desktop-budget#5#li1":"Trung bình (đăng nhập, kiểm tra nhật ký, tải xuống kết quả) — 15–25 bước, ~205–340K tokens, ~$0.12–0.21","reference.desktop-budget#5#li2":"Phức tạp (phân loại ba vấn đề GitHub) — 25–30 bước, ~340–410K tokens, ~$0.21–0.25","reference.desktop-budget#6#p":"Các con số token ở trên là giới hạn kỹ thuật cho mỗi hành trình, không phải hạn mức hàng tháng của bạn — phần đó được tính bằng tín dụng, và gói miễn phí với 300 mỗi tháng đủ thoải mái để dùng cho cả trò chuyện, viết mã và vài tác vụ tự động.","reference.desktop-budget#7#c":"Bạn có thể điều chỉnh giới hạn cho từng nhiệm vụ ngay từ đầu, nhưng mọi trường hợp vượt quá đều sẽ hiện lên để bạn quyết định. Ngân sách không bao giờ bị tiêu hao âm thầm.","reference.desktop-whitelist#title":"Danh sách trắng phiên Desktop","reference.desktop-whitelist#0#p":"\"Danh sách trắng\" đơn giản là danh sách các ứng dụng và trang web mà bạn đã cho phép Ava tương tác khi cô ấy điều khiển máy tính của bạn. Trang này giải thích cách bạn cấp quyền đó và tại sao nó khởi tạo lại mỗi lần. Tóm tắt ngắn gọn: cô ấy chỉ có thể hành động nơi bạn cho phép, và cô ấy luôn hỏi trước khi truy cập bất cứ thứ gì mới.","reference.desktop-whitelist#1#p":"Vào đầu phiên Desktop, Ava hỏi nơi cô ấy được phép hành động. Bạn có thể dùng ngôn ngữ đời thường: \"Gmail, Cursor, cổng Azure.\" Cô ấy đọc lại và xác nhận lại với bạn (\"Gmail web, ứng dụng Cursor, portal.azure.com\").","reference.desktop-whitelist#2#h":"Cách thức thực thi","reference.desktop-whitelist#3#p":"Các hành động chỉ xem — chụp màn hình, đọc danh sách nút và trường trên màn hình (cây \"UIA\", bản đồ nội bộ của Windows về những gì trong cửa sổ) — được phép ở mọi nơi, vì bạn cần nhìn thấy những gì trên màn hình để quyết định có thêm ứng dụng vào danh sách trắng hay không. Mọi thứ thay đổi nội dung đều bị chặn ngoài danh sách; Ava tạm dừng và hỏi bạn có nên thêm nó không.","reference.desktop-whitelist#4#h":"Giới hạn theo phiên, cố ý","reference.desktop-whitelist#5#p":"Danh sách trắng KHÔNG được lưu lại giữa các phiên. Không có tùy chọn \"nhớ ứng dụng này\". Mọi hành trình mới đều bắt đầu với phạm vi mới. Đây là sự bất tiện được thiết kế có chủ đích — việc quên cho phép lại là một tính năng bảo mật, không phải lỗi.","reference.desktop-whitelist#6#h":"Thêm vào giữa hành trình","reference.desktop-whitelist#7#p":"Trong một hành trình, bạn có thể thêm ứng dụng từ thanh trên cùng: \"+ Cho phép ứng dụng\" mở một ô nhập nhỏ. Nhấn Thêm và ứng dụng mới sẽ hoạt động cho phần còn lại của phiên.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Bạn muốn tạo ảnh, video ngắn, bài hát, hoặc lời thoại? Chỉ cần mô tả và Ava sẽ làm nó cho bạn — không cần phần mềm thiết kế hay xử lý âm thanh.","features.creative-studio#1#p":"Tạo ảnh, video, nhạc và giọng nói — tích hợp ngay trong quy trình làm việc cùng mã của bạn. Tạo biểu tượng, bản mẫu sản phẩm, video giới thiệu, hoặc lồng tiếng cho bài hướng dẫn. Được vận hành bởi MiniMax.","features.creative-studio#2#h":"Những gì bạn có thể tạo ra","features.creative-studio#3#li0":"Ảnh — từ mô tả sang PNG/JPG. Xóa nền chỉ với một lệnh.","features.creative-studio#3#li1":"Video — video AI ngắn từ văn bản (MiniMax Hailuo).","features.creative-studio#3#li2":"Nhạc — bản nhạc không lời hoặc có lời ca.","features.creative-studio#3#li3":"Giọng nói — chuyển văn bản thành giọng nói với nhiều lựa chọn giọng đọc.","features.creative-studio#4#p":"Chi phí Creative Studio nằm chung trong một kho tín dụng với mọi thứ khác — một kho, một con số duy nhất. Tự mang theo khóa MiniMax riêng (BYOK) và nó miễn phí cho gói của bạn.","features.creative-studio#5#c":"Creative Studio đủ điều kiện dùng gói miễn phí. Không phải tính năng trả phí thêm.","features.desktop-automation#title":"Tự động hóa máy tính để bàn","features.desktop-automation#0#p":"Nói đơn giản: Ava có thể thay bạn điều khiển chuột và bàn phím để làm các tác vụ — mở ứng dụng, bấm nút, điền biểu mẫu — trong khi bạn quan sát và phê duyệt những việc quan trọng.","features.desktop-automation#1#p":"Một chế độ mới cho Ava, tiền tố @@. Cô ấy quan sát màn hình, quyết định làm gì, và điều khiển tự động giao diện (kiểm soát các ứng dụng trên màn hình của bạn) để hoàn thành công việc. Chạy trực tiếp trên máy thật của bạn với thông tin đăng nhập thật — không phải trình duyệt đám mây. Có sẵn ở mọi gói sau khi phát hành.","features.desktop-automation#2#h":"Tại sao lại là một giải pháp khác","features.desktop-automation#3#p":"Mọi sản phẩm tự động hóa máy tính khác đều là thứ bạn khởi động khi đang ngồi tại bàn làm việc. Ava là người luôn ở đó khi bộ theo dõi lỗi báo động lúc 2 giờ sáng — IDE vẫn chạy, điện thoại kết nối qua kênh bảo mật, bạn phê duyệt các thao tác không thể đảo ngược chỉ bằng một chạm.","features.desktop-automation#4#p":"Cô ấy còn nhớ cách điều hướng trong các ứng dụng của bạn qua các phiên làm việc. Mọi tác nhân khác phải học lại từ đầu mỗi lần. Điểm khác biệt về trí nhớ càng tăng giá trị theo thời gian sử dụng.","features.desktop-automation#5#h":"Cách thức hoạt động","features.desktop-automation#6#p":"Mỗi bước chạy một sóng năm vai trò: Người trinh sát quan sát, Người lập kế hoạch chọn hành động tiếp theo, Người thực thi xử lý, Người xác minh kiểm tra, Người tường thuật kể cho bạn biết chuyện gì xảy ra. Module sidecar chọn phương thức xác thực rẻ nhất và đáng tin cậy nhất — UIA cho ứng dụng gốc, Playwright cho trình duyệt, OmniParser thị giác khi không cái nào có cây cấu trúc hữu ích.","features.desktop-automation#7#p":"Xem trang khái niệm để hiểu rõ hơn về nguyên tắc an toàn, hệ thống xác thực, nút dừng khẩn cấp, và mô hình danh sách trắng cho phiên làm việc.","start.glossary#1#td7.1":"Đơn vị tính đơn giản hơn của Ava để biết giá mỗi hành động, giúp bạn không cần phải tính toán token. Các gói đều đi kèm một gói credit hàng tháng.","start.glossary#1#td8.0":"Khóa API","start.glossary#1#td8.1":"Một mật khẩu riêng tư cho phép phần mềm sử dụng dịch vụ trả phí (như mô hình AI) trên tài khoản của bạn. Bạn chỉ cần cái này nếu muốn tự mang theo.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Tự mang theo khóa.\" Sử dụng khóa API của riêng bạn thay vì quyền truy cập được quản lý bởi Ava. Tùy chọn — dành cho những người đã trả tiền trực tiếp cho nhà cung cấp.","start.glossary#1#td10.0":"Ưu tiên lưu trữ tại máy","start.glossary#1#td10.1":"Dữ liệu của bạn mặc định nằm trên máy tính của bạn. Không có gì được tải lên trừ khi bạn bật đồng bộ. \"Dữ liệu tại máy là linh thiêng.\"","start.glossary#1#td11.0":"Chế độ xin phép","start.glossary#1#td11.1":"Mức độ cẩn thận của Ava trước khi thực hiện việc gì đó — hỏi mọi lúc, chỉ hỏi khi rủi ro, hoặc cứ làm luôn. Bạn tự đặt mức độ.","start.glossary#1#td12.0":"Cửa sổ ngữ cảnh","start.glossary#1#td12.1":"Lượng văn bản mô hình có thể ghi nhớ cùng lúc — giống như bộ nhớ ngắn hạn của nó. \"Ngữ cảnh 1M\" nghĩa là khoảng một triệu từ. Càng lớn = càng đọc được nhiều hơn trước khi quên.","start.glossary#1#td13.0":"So sánh thay đổi","start.glossary#1#td13.1":"Xem song song chính xác những gì sẽ thay đổi trong tệp — cũ một bên, mới một bên — được hiển thị trước khi Ava thay đổi gì để bạn phê duyệt.","start.glossary#1#td14.0":"Kho chứa (repo)","start.glossary#1#td14.1":"Thư mục dự án được theo dõi các thay đổi, thường là qua Git. Nếu điều đó chưa có nghĩa gì với bạn, thì nó chỉ là \"thư mục chứa dự án của tôi.\"","start.glossary#1#td15.0":"Lời nhắc","start.glossary#1#td15.1":"Những gì bạn gõ cho AI — câu hỏi hoặc hướng dẫn của bạn.","start.glossary#2#c":"Vẫn còn vướng mắc về từ nào đó? Hãy hỏi Ava ở chế độ trò chuyện — \"X nghĩa là gì?\" — và cô ấy sẽ giải thích phù hợp với trình độ của bạn.","models.routing#title":"Định tuyến — cách Ava chọn mô hình","models.routing#0#p":"Đây là tóm tắt ngắn gọn: bạn không bao giờ phải chọn mô hình AI nào để dùng. Ava làm hộ bạn, chọn công cụ tốt nhất cho mỗi phần việc — giống như một người quản lý giỏi giao đúng việc cho đúng người.","models.routing#1#p":"Bạn chọn một trong ba phong cách — Maestro, Supernova, hoặc Aurora — và Ava gửi mỗi phần việc đến mô hình xử lý nó tốt nhất. Maestro là mặc định, nó hoạt động trên mọi gói, và là lựa chọn tốt cho hầu hết mọi người.","models.routing#2#h":"Tại sao lại phải định tuyến?","models.routing#3#p":"Việc đặt đúng mô hình cho mỗi bước tốn kém ít hơn so với chạy tất cả trên một mô hình lớn đắt đỏ — và cho kết quả tốt hơn, vì mỗi mô hình đều làm những gì nó giỏi nhất. Bạn có chi phí ổn định và chất lượng cao mà không cần biết mô hình nào là gì.","models.routing#4#c":"Cả ba phong cách đều hoạt động trên credit nền tảng và khóa của bạn. Với khóa riêng, bạn cũng có thể bỏ qua định tuyến và điều khiển trực tiếp một mô hình. Danh sách đầy đủ nằm ở phần \"Cho tôi xem chi tiết\".","models.routing#deeper#0#c":"Các số \"B\" bên dưới là hàng tỷ tham số — xấp xỉ kích thước 'não' của mô hình; lớn hơn thường thông minh hơn nhưng chậm hơn và đắt hơn. Đây là chi tiết kỹ thuật bên trong; bạn không bao giờ cần nó để dùng Ava.","models.routing#deeper#1#h":"So sánh song song","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Người điều phối","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B tham số hoạt động, 1M ngữ cảnh)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B tham số hoạt động, 262K ngữ cảnh)","models.routing#deeper#2#td1.0":"Người xây dựng","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (tái sử dụng người điều phối)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B tham số đầy đủ, 256K ngữ cảnh)","models.routing#deeper#2#td2.0":"Chuyên gia tầm trung","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (người kiểm tra mã, người kiểm chứng sự thật, khảo sát, quét, xác minh bảo mật, v.v.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Kiến trúc sư, Người xác minh, Người sắp xếp trình tự, Gia sư, Người báo cáo, v.v.)","models.routing#deeper#2#td3.0":"Cấp nhẹ / Cổng ý định","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Người tìm kiếm, Người xác minh, Người sắp xếp trình tự, Người thách thức, Người tích hợp)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Chuyên gia chuyên sâu","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Nhà nghiên cứu, Người thách thức, Nhà nghiên cứu CVE, Người tạo ý tưởng, Người kiểm chứng sự thật)","concepts.interjection#1#p":"Ava sẽ chạy cho đến khi kế hoạch hoàn tất hoặc bạn dừng cô ấy lại. Trong lúc cô ấy đang hoạt động, bạn có hai cách để can thiệp (từ này gọi là \"can thiệp\").","concepts.interjection#2#h":"Can thiệp — dẫn hướng mà không hủy bỏ","concepts.interjection#3#p":"Gõ một tin nhắn mới trong khi Ava đang làm việc. Cô ấy sẽ hoàn thành công cụ hiện tại, đọc tin nhắn của bạn và điều chỉnh kế hoạch. Không mất ngữ cảnh nào cả. Dùng cách này khi bạn muốn đổi hướng, thêm thông tin, hoặc thay đổi ưu tiên giữa chừng.","concepts.interjection#4#h":"Dừng khẩn cấp — hủy bỏ và làm sạch","concepts.interjection#5#p":"Nhấn Escape (trên CLI), bấm Stop (trên extension, IDE), hoặc gõ lệnh dừng. Chạy hiện tại bị hủy, các lệnh chờ bị bỏ qua, và cuộc trò chuyện sẵn sàng cho lượt mới.","concepts.interjection#6#c":"Hãy dùng Can thiệp trước. Dừng khẩn cấp chỉ dùng khi thực sự có vấn đề. Can thiệp giúp giữ mạch làm việc liên tục.","concepts.desktop-personas#title":"Các nhân vật Desktop","concepts.desktop-personas#0#p":"Trang này dành cho những người tò mò và người dùng nâng cao. \"Tự động hóa Desktop\" (đôi khi gọi là \"sử dụng máy tính\") nghĩa là Ava thực sự có thể nhấp chuột quanh màn hình và dùng ứng dụng thay bạn — mở Gmail, điền biểu mẫu, gửi tin nhắn — như một người ngồi trước bàn phím. Để làm điều đó an toàn, cô ấy chia công việc cho năm trợ lý nhỏ, mỗi người một vai trò hẹp. Bạn không bao giờ phải trực tiếp xử lý chúng; trang này chỉ giúp bạn biết ai làm gì.","concepts.desktop-personas#1#p":"Mỗi bước trong hành trình Desktop (một lần chạy của Ava lái màn hình của bạn hướng tới mục tiêu) đều trải qua một chu trình gồm năm nhân vật. Mỗi nhân vật có một nhiệm vụ và chỉ một nhiệm vụ. Sự tách biệt này giúp yêu cầu ngắn gọn, đầu ra có cấu trúc, và tư duy phản biện được thiết kế sẵn.","concepts.desktop-personas#2#h":"Người trinh sát","concepts.desktop-personas#3#p":"Báo cáo những gì hiển thị trên màn hình ngay lúc này. Không bao giờ tự tạo ra các yếu tố. Không bao giờ lập kế hoạch. Trả về JSON ScreenState với ID phần tử, tên, bboxes, độ tin cậy, và nguồn xác thực (UIA, Playwright DOM, hoặc OmniParser vision).","concepts.desktop-personas#4#h":"Người lập kế hoạch","concepts.desktop-personas#5#p":"Quyết định hành động tiếp theo duy nhất. Một hành động mỗi bước — không bao giờ gom nhóm. Ưu tiên các đường đi có thể đảo ngược. Phân loại rủi ro theo hệ thống an toàn. Xuất ra JSON ProposedAction với kind, target, params, riskClass, reasoning, và dự đoán expectedPostState.","concepts.desktop-personas#6#h":"Người thực thi","concepts.desktop-personas#7#p":"Thực thi chính xác những gì Người lập kế hoạch đề xuất — sau khi cổng phê duyệt đã thông qua. Không có sáng tạo tùy tiện. Không có thử lại. Lỗi được báo cáo trung thực và Verifier xử lý nước đi tiếp theo.","concepts.desktop-personas#8#h":"Người kiểm tra","concepts.desktop-personas#9#p":"Kiểm tra xem hành động có thành công hay không. So sánh ScreenState mới với dự đoán của Người lập kế hoạch. Trả về verified, deviated, hoặc rollback_needed. Cũng chạy phát hiện lặp — lặp lại một hành động đã thành công là sai lệch, không phải xác minh.","concepts.desktop-personas#10#h":"Người kể chuyện","concepts.desktop-personas#11#p":"Là giọng nói duy nhất người dùng nghe thấy trong suốt hành trình. Một câu quá khứ mỗi bước (\"Đã mở Gmail.\", \"Đã bấm Compose.\"). Cũng ghi nhật ký kiểm toán có cấu trúc. Nói khi có gì đó sai sót — không bao giờ giấu giếm vấn đề.","concepts.desktop-safety#title":"Hệ thống an toàn Desktop","concepts.desktop-safety#0#p":"Tóm lại: trước khi Ava nhấp bất cứ thứ gì trên màn hình, cô ấy phân loại hành động dựa trên mức độ rủi ro. Đọc màn hình? Vô hại. Gửi tiền hoặc xóa thứ gì đó? Cô ấy luôn dừng lại và hỏi bạn trước — mỗi lần, không ngoại lệ. Năm nhãn bên dưới chỉ là các bậc thang trên thang đo rủi ro đó. Đây là chi tiết cho người dùng nâng cao, nhưng điểm chính rất đơn giản: những thứ nguy hiểm luôn cần lời đồng ý của bạn.","concepts.desktop-safety#1#p":"Mọi hành động được đề xuất đều được phân loại vào một trong năm lớp rủi ro. Việc phân loại kết hợp ba tín hiệu — mục tiêu trên màn hình là gì, mô tả bằng ngôn ngữ bình thường (\"mô tả ngữ nghĩa\" — từ ngữ của Ava về những gì cô ấy đang nhìn), và cài đặt hành động — và tăng cấp (coi là rủi ro hơn) khi chúng không khớp. Dương tính giả (hỏi khi không cần) chỉ là phiền phức. Âm tính giả (không hỏi khi đáng lẽ phải hỏi) là sự cố nghiêm trọng.","concepts.desktop-safety#2#h":"Năm lớp","concepts.desktop-safety#3#li0":"Quan sát — đọc cây UIA, chụp màn hình, di chuột. Luôn được tự động cho phép.","concepts.desktop-safety#3#li1":"Điều hướng — cuộn, di chuyển tiêu điểm, mở menu. Tự động cho phép ở chế độ Drive mode."},"th":{"start.for-non-coders#6#li3":"เมื่อคุณต้องการให้เธอทำหรือเปลี่ยนแปลงอะไรจริงๆ แค่บอกไป — เธอจะแสดงให้คุณเห็นเสมอว่ากำลังจะทำอะไร และรอคำพูดว่า “ใช่” จากคุณ","start.for-non-coders#7#c":"เจอคำที่ไม่คุ้นเคยไหม? พจนานุกรมภาษาธรรมดา (อยู่ด้านล่างของส่วนนี้) อธิบายทุกคำศัพท์โดยไม่ต้องมีความรู้พื้นฐานมาก่อน","start.install#title":"ติดตั้ง","start.install#0#p":"เลือกช่องทางที่เหมาะกับวิธีทำงานของคุณ ใช้ได้หลายช่องทางก็ได้ — Ava จะซิงค์ความทรงจำข้ามช่องทางเหล่านี้เมื่อคุณล็อกอิน","start.install#1#h":"ส่วนขยาย VS Code","start.install#2#li0":"เปิดแผงส่วนขยายใน VS Code (Ctrl+Shift+X / Cmd+Shift+X)","start.install#2#li1":"ค้นหา \"Ava Supernova\" แล้วคลิก ติดตั้ง","start.install#2#li2":"กด Ctrl+Shift+A (Cmd+Shift+A บน macOS) เพื่อเปิดแผงแชท","start.install#2#li3":"ทำตามตัวช่วยติดตั้ง — เลือกโมเดล ตั้งโหมดการอนุญาต แล้วเสร็จ","start.install#3#h":"IDE สำหรับเดสก์ท็อป","start.install#4#li0":"ดาวน์โหลดโปรแกรมติดตั้งสำหรับแพลตฟอร์มของคุณจากหน้ารีลีส","start.install#4#li1":"รันได้เลย ครั้งแรก IDE จะเปิดตัวพร้อมขั้นตอนต้อนรับ","start.install#4#li2":"ล็อกอินเพื่อรับโทเค็นแพลตฟอร์มฟรี หรือวางคีย์ API ของคุณเองเพื่อรันแบบเต็มรูปแบบบนเครื่อง","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli (หรือ pnpm / yarn — เลือกเอาเอง)","start.install#6#li1":"รัน ava ในไดเรกทอรีโปรเจกต์ใดก็ได้","start.install#6#li2":"การรันครั้งแรกจะถามหาผู้ให้บริการและโมเดล เลือกแล้วเริ่มได้เลย","start.install#7#c":"ไม่มีบัญชี ก็ไม่เป็นไร ด้วยคีย์ API ของคุณเอง (BYOK) คุณไม่ต้องล็อกอินเลย โหมดฟรีใช้สำหรับโมเดลที่จัดการโดยแพลตฟอร์ม","concepts.memory#title":"Memory — how Ava remembers you","concepts.memory#0#p":"In plain terms: Ava remembers you. Tell her something once — what you like, a decision you made — and she keeps it, so you don't have to repeat yourself in the next chat or next week. That's the headline. The layers below just explain how she keeps that memory tidy over time.","concepts.memory#1#p":"Ava มีหน่วยความจำถาวร (\"persistent\" หมายถึงมันอยู่ต่อหลังจากคุณปิดแอป) ที่คงอยู่ข้ามบทสนทนา ข้ามโปรเจกต์ และข้ามเครื่องหากคุณเปิดซิงค์ (ซิงค์คัดลอกความทรงจำระหว่างอุปกรณ์ของคุณ) มันไม่ใช่บันทึกแชท มันคือความเข้าใจที่มีโครงสร้างและค้นหาได้ว่าคุณเป็นใคร ชอบอะไร และตัดสินใจอะไรไว้","concepts.memory#2#h":"ห้าชั้น","concepts.memory#3#li0":"ดึงข้อมูล — จับข้อเท็จจริงสำคัญจากทุกข้อความแบบเรียลไทม์","concepts.memory#3#li1":"สะท้อนคิด — วิเคราะห์ลึกซึ้งตอนจบเซสชันที่มีความหมาย รูปแบบ แนวคิด ความขัดแย้ง","concepts.memory#3#li2":"สะสม — การแก้ไขและความชอบจะสะสมเพิ่มขึ้นเรื่อยๆ เป็นสัปดาห์และเดือน","concepts.memory#3#li3":"วิเคราะห์ — ระบบกราฟเชื่อมโยงความทรงจำที่เกี่ยวข้องและแจ้งเตือนเมื่อข้อมูลใหม่ขัดแย้งกับเก่า","concepts.memory#3#li4":"รวมศูนย์ — ความทรงจำที่คล้ายกันจะรวมเข้าด้วยกัน; ที่เก่าเกินไปจะถูกตัดออก ความทรงจำจะคมชัดขึ้นตามเวลา ไม่รกขึ้น","concepts.memory#4#c":"ชั้นทั้งห้าทำงานเองโดยอัตโนมัติ — คุณไม่ต้องจัดการเองเลย พวกนี้ช่วยให้เห็นความทรงจำพัฒนาดีขึ้นจริงๆ ตามเวลา แทนที่จะกลายเป็นกองขยะ","concepts.memory#5#h":"เรียกคืน","concepts.memory#6#p":"เมื่อคุณถามคำถาม Ava จะค้นหาความทรงจำจากความหมาย (\"semantic search\" — เข้าใจสิ่งที่หมายถึง จึงหาความทรงจำที่ถูกต้องแม้คุณจะพูดต่างออกไป) ไม่ใช่แค่จับคู่คำตรงๆ ตัวกรองเฉพาะโหมดทำงานไปด้วย — โหมดแชทดึงบริบทส่วนตัว โหมดงานดึงการตัดสินใจโปรเจกต์และรูปแบบโค้ด","concepts.memory#7#c":"ความทรงจำถูกจำกัดตามผู้ใช้และโปรเจกต์ (ความทรงจำของคุณเป็นของคุณ แยกตามคนและโปรเจกต์) รหัสผ่านและข้อมูลลับ (รหัสผ่าน, คีย์) จะถูกบล็อกที่ขอบเขตการบันทึก — ไม่สามารถลงไปในความทรงจำได้เลย","concepts.desktop-grounding#title":"ลำดับชั้นการยึดติดบนเดสก์ท็อป (ฉบับทดลอง)","concepts.desktop-grounding#0#c":"ฉบับทดลอง — วิธีที่ Scout ตัดสินใจว่าจะใช้แหล่งข้อมูลการยึดติดใดในแต่ละขั้นตอน","concepts.desktop-grounding#1#p":"ก่อนที่ Ava จะคลิกปุ่มได้ เธอต้องเข้าใจก่อนว่าบนหน้าจอของคุณมีอะไรอยู่และอยู่ที่ไหน — นั่นคือ \\\"Grounding\\\" (การระบุว่ามีอะไรอยู่บนหน้าจอและตำแหน่งที่แน่นอน) เธอมี 3 วิธีในการทำแบบนี้ และเลือกวิธีที่น่าเชื่อถือที่สุดที่ใช้ได้กับแอปที่คุณกำลังใช้ นี่คือรายละเอียดเชิงลึกสำหรับผู้ใช้ขั้นสูง จุดสำคัญคือเธอชอบวิธีที่มั่นคงและแม่นยำกว่าการเดาจากภาพ","concepts.desktop-grounding#2#p":"มี 3 ระดับ ประเมินตามลำดับ แหล่งข้อมูลที่เชื่อถือได้และประหยัดที่สุดจะถูกเลือก","concepts.desktop-grounding#3#h":"1. หน้าต่างเบราว์เซอร์ → Playwright DOM","concepts.desktop-grounding#4#p":"หากหน้าต่างที่เปิดอยู่เป็นเบราว์เซอร์เว็บ Ava จะอ่านโครงสร้างของหน้าเว็บเอง (หรือ \\\"DOM\\\" — รายการพื้นฐานของสิ่งที่อยู่บนหน้า) แทนที่จะเดาจากภาพ การอ่านโครงสร้างน่าเชื่อถือกว่าการดูพิกเซลประมาณ 10 เท่า — เธอรู้ตำแหน่งของแต่ละปุ่มและเมื่อไหร่ที่หน้าโหลดเสร็จสมบูรณ์ นี่คือเส้นทางหลักสำหรับทุกสิ่งบนเว็บ ไม่ใช่ทางเลือกสำรอง","concepts.desktop-grounding#5#h":"2. แอปเนทีฟที่มี UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"สำหรับแอปเดสก์ท็อปทั่วไปบน Windows Ava จะอ่านแผนที่การเข้าถึงในตัว (\\\"UIA\\\" ซึ่งเป็นข้อมูลเดียวกันที่โปรแกรมอ่านหน้าจอใช้บรรยายหน้าต่าง) — มันจะระบุแต่ละองค์ประกอบ ชื่อ และตำแหน่งของมัน หากแผนที่นั้นส่งคืนรายการที่มีชื่อและใช้งานได้อย่างน้อย 5 รายการ เธอจะไว้วางใจและใช้มัน","concepts.desktop-grounding#7#h":"3. UIA ว่างเปล่าหรือไม่มีประโยชน์ → วิทัศน์ OmniParser","concepts.desktop-grounding#8#p":"เมื่อแผนที่นั้นหายไปหรือไม่สามารถใช้ได้ (บางแอป เกม และหน้าจอระยะไกลไม่ให้มา) Ava จะถอยกลับไปมองภาพหน้าจอจริงๆ เครื่องมือวิทัศน์ (OmniParser) จะระบุพื้นที่ที่คลิกได้และติดป้ายกำกับว่าคืออะไร เปลี่ยนรูปภาพกลับมาเป็นรายการที่เธอสามารถดำเนินการได้ — ผสมผสานกับข้อมูลเล็กน้อยที่แผนที่การเข้าถึงให้ได้มา","concepts.desktop-grounding#9#c":"OmniParser จะเปิดใช้งานเฉพาะเมื่อ Ava ต้องการครั้งแรก พร้อมข้อความแจ้งความเป็นส่วนตัวที่ชัดเจน ผู้ใช้ BYOK สามารถชี้ไปที่การติดตั้ง OmniParser ในเครื่องของตนเองได้","concepts.desktop-kill-switches#title":"สวิตช์ตัดไฟบนเดสก์ท็อป (ฉบับทดลอง)","concepts.desktop-kill-switches#0#c":"ฉบับทดลอง — 3 วิธีอิสระในการยกเลิกกระบวนการที่กำลังทำงานอยู่ วิธีใดก็ได้ใช้ได้ผล","concepts.desktop-kill-switches#1#p":"\\\"สวิตช์ตัดไฟ\\\" คือสิ่งที่ชื่อบอกเป๊ะ — ทางฉุกเฉินเพื่อหยุด Ava ทันทีเมื่อเธอกำลังควบคุมหน้าจอของคุณ ส่วนที่น่าสบายใจ: มี 3 แบบ สร้างแยกกัน ดังนั้นถ้าอันหนึ่งล้มเหลว อีกอันยังทำงานได้ คุณไม่ต้องเรียนรู้ทั้งสามอย่าง แค่รู้ว่าเมื่อไหร่ก็ตามที่ดูเหมือนมีปัญหา คุณสามารถหยุดมันได้เสมอ และการหยุดที่แข็งแกร่งที่สุด (การตัดไฟฉุกเฉินด้านล่าง) ไม่ได้ขึ้นอยู่กับความร่วมมือของ Ava","concepts.desktop-kill-switches#2#p":"หลังจากศึกษาเหตุการณ์ที่เกิดขึ้นกับเอเจนต์ AI ทั้งหมด (กรณีจริงที่เอเจนต์ AI ปฏิเสธคำสั่งหยุด ลบอีเมลเก่า หรือล้างไดรฟ์) เราสร้างสวิตช์ตัดไฟ 3 ตัวใน 3 ชั้นที่แตกต่างกัน ไม่มีตัวไหนขึ้นอยู่กับโมเดล AI โดยตรง — หาก Ava ติดขัดหรือไม่ตอบสนอง คุณยังสามารถหยุดเธอได้","concepts.desktop-kill-switches#3#h":"หยุดชั่วคราว — กด Space หรือปุ่ม Pause","concepts.desktop-kill-switches#4#p":"หยุดชั่วคราวที่จุดเปลี่ยนของขั้นตอนถัดไป ทำต่อได้ ใช้เมื่อคุณต้องการแทรกแซงแต่ไม่ต้องการให้สูญเสียความต่อเนื่อง","concepts.desktop-kill-switches#5#h":"หยุด — กดปุ่ม Escape หรือปุ่มหยุด","concepts.desktop-kill-switches#6#p":"ยกเลิกอย่างเรียบร้อย ผู้ช่วยจะสรุปสิ่งที่ทำไปแล้ว ไม่สามารถทำต่อได้ และบันทึกข้อมูลลงในล็อกตรวจสอบ","concepts.desktop-kill-switches#7#h":"ฆ่าฉุกเฉิน — กด Escape ติดกันสามครั้ง หรือ Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"เป็นการหยุดที่เด็ดขาดที่สุด โปรแกรมเฝ้ายามขนาดเล็กและแยกต่างหากจะบังคับปิดส่วนหนึ่งของ Ava ที่กำลังควบคุมหน้าจอของคุณ มันจะไม่รอคำตอบจาก AI ไม่จำเป็นต้องให้หน้าต่างแอปพลิเคชันทำงานอยู่ และไม่สนว่าระบบอยู่ในสถานะไหน — มันแค่ตัดการทำงานทันที นี่คือทางออกสุดท้ายเมื่อเกิดปัญหาจริง ๆ","concepts.desktop-kill-switches#9#p":"ทั้งสามวิธีนี้ใช้งานได้ผ่านแอปเสริมเช่นกัน ไม่ว่าตัวควบคุมตัวไหนก็สามารถยุติการทำงานได้","reference.tools#title":"คู่มืออ้างอิงเครื่องมือ","reference.tools#0#p":"นี่คือรายการเครื่องมือทั้งหมดที่ Ava มี — คำว่า \"เครื่องมือ\" หมายถึงการกระทำเฉพาะที่เธอทำได้ เช่น การอ่านไฟล์หรือการค้นหา คุณไม่จำเป็นต้องอ่านหน้านี้ เพราะ Ava จะเลือกเครื่องมือที่เหมาะสมให้ทุกครั้งเอง ส่วนหน้าที่นี้มีไว้เพื่อคุณที่อยากทราบว่าเธอทำอะไรได้บ้างเท่านั้น","reference.tools#1#p":"นี่คือกล่องเครื่องมือในตัวแบบครบถ้วน ทุกเครื่องมือที่นี่ถูกจดทะเบียนในรันไทม์หลัก (ซึ่งเป็นเครื่องยนต์ที่อยู่เบื้องหลังพื้นผิวทั้งสาม) และพร้อมใช้งานสำหรับ Ava เมื่อโหมดและระดับสิทธิ์อนุญาต คุณสามารถกรองตามหมวดหมู่หรือระดับความเสี่ยงได้","reference.tools#2#p":"ไม่ต้องจำสิ่งเหล่านี้เลย — ตารางด้านล่างเป็นเพียงบัตรคู่มืออ้างอิง","reference.tools#4#h":"ระดับความเสี่ยง","reference.tools#5#li0":"ปลอดภัย — อ่านข้อมูลโดยไม่มีการแก้ไขใดๆ เช่น file_read, glob (ค้นหาไฟล์ตามรูปแบบชื่อ), grep (ค้นหาข้อความภายในไฟล์), git_status (Git คือระบบที่ใช้ติดตามการเปลี่ยนแปลงในโปรเจกต์ของคุณ)","reference.tools#5#li1":"เขียน — แก้ไขไฟล์ บันทึกจุดเก็บงานของคุณ (เรียกว่า \"commit\") หรือสร้างสิ่งใหม่ๆ เช่น file_edit, git_commit, generate_image","reference.tools#5#li2":"อันตราย — รันคำสั่งบนเครื่องคอมพิวเตอร์ของคุณ (เช่น \"shell\"), ควบคุมเดสก์ท็อป, เข้าถึงอินเทอร์เน็ต, หรือสอบถามฐานข้อมูล เช่น bash, browser, desktop_*","reference.tools#6#c":"ผู้เชี่ยวชาญแต่ละบทบาทจะมีรายการเครื่องมือที่ได้รับอนุญาตเป็นของตัวเอง Scout สามารถอ่านได้แต่ไม่สามารถเขียนได้ Builder มีสิทธิ์เข้าถึงเต็มที่ ส่วน Challenger ไม่มีเครื่องมือเลย — หน้าที่ของมันคือการตั้งคำถามกับแผนงาน","reference.models#title":"โมเดล (AI)","reference.models#0#p":"\"โมเดล\" คือสมองของ AI ที่ทำหน้าที่คิด — อย่างเช่น Qwen, DeepSeek, Mistral และอื่นๆ หน้านี้ระบุทุกโมเดลที่ Ava สามารถใช้ได้ แบบย่อคือ คุณไม่ต้องเลือกเอง เพราะ Ava จะเลือกโมเดลที่เหมาะสมสำหรับแต่ละขั้นตอนให้เอง อ่านต่อก็ต่อเมื่อคุณต้องการเข้าใจหรือต้องการกำหนดค่าเอง","reference.models#1#p":"ทุกโมเดลที่ Ava สามารถส่งงานไปได้ รวมถึงกลยุทธ์การประสานงานทั้งสามแบบ — ซึ่งเป็นกฎที่จะตัดสินว่าโมเดลใดจะรับผิดชอบแต่ละส่วนของงาน คุณสามารถเลือกโหมดการกระจายงานแล้วให้ Ava จัดการเอง หรือเลือกโมเดลเดียวแล้วข้ามการกระจายงานไปเลยก็ได้","reference.models#2#h":"โหมดการกระจายงาน","reference.models#3#p":"กลยุทธ์การประสานงานสามแบบ Pipeline ของบทบาทเดียวกัน (ทีมงานผู้เชี่ยวชาญเล็กๆ ที่ Ava เรียกใช้เบื้องหลัง) จะทำงานเหมือนกันในทุกแบบ; สิ่งที่ต่างกันคือกลุ่มโมเดลพื้นฐาน คุณสามารถเลือกโหมดในตัวเลือกโมเดล แล้ว Ava จะจัดการส่วนที่เหลือ การ์ดด้านล่างแสดงรายละเอียดผู้เชี่ยวชาญแต่ละคนที่ผู้ประสานงานจะส่งงานไป","reference.models#4#p":"คุณไม่จำเป็นต้องจำการ์ดด้านล่าง — พวกมันมีไว้เพื่อให้คุณเห็นโครงสร้างของแต่ละกลยุทธ์","reference.models#6#c":"Aurora ถูกออกแบบมาให้ใช้เฉพาะกับ Mistral เท่านั้น หากไม่มีโมเดล Mistral ให้ใช้งาน ตัวกระจายจะส่งข้อผิดพลาดแทนการเปลี่ยนเส้นทางไปยังโมเดลอื่น — นั่นคือนโยบายของ EU-stack หากคุณต้องการทางเลือกที่รองรับได้ดีกว่า ให้เลือก Maestro หรือ Supernova","reference.models#7#c":"โหมดทั้งสามพร้อมใช้งานเสมอ — ไม่ว่าจะเป็นเครดิตของแพลตฟอร์มหรือคีย์ของคุณเอง BYOK เพิ่มตัวเลือกให้คุณข้ามการประสานงานและควบคุมโมเดลเดี่ยวโดยตรงได้","reference.models#8#h":"โมเดลที่ดูแลโดยแพลตฟอร์ม","reference.models#9#p":"พร้อมใช้งานในทุกแพ็กเกจ รวมถึงระดับฟรี โทเค็น (หน่วยวัดปริมาณข้อความของ AI — ประมาณ 3 ใน 4 ของคำต่อหนึ่งโทเค็น) จะถูกหักออกจากโควตาแพ็กเกจของคุณ คีย์ (รหัสผ่านส่วนตัวที่ใช้เปิดใช้งานโมเดลที่ต้องชำระเงิน) จะถูกหมุนเวียนและตรวจสอบโดยแพลตฟอร์ม — คุณไม่ต้องตั้งค่าอะไรเพิ่มเติม","reference.config#title":"การตั้งค่า","reference.config#0#p":"หน้านี้แสดงว่า Ava เก็บการตั้งค่าและไฟล์ไว้ในไหนบนคอมพิวเตอร์ของคุณ คุณแทบไม่ต้องจัดการเองเลย เพราะแอปดูแลให้ทั้งหมด มีไว้เมื่อคุณต้องการดู สำรอง หรือแชร์ไฟล์เหล่านั้นเอง","reference.config#1#p":"Ava อ่านค่าการตั้งค่า (บันทึกการตั้งค่าของเธอ) จากสองระดับ การตั้งค่าส่วนกลาง — ที่ใช้ได้ทุกที่ — อยู่ที่โฟลเดอร์ชื่อ ~/.ava/ (\"~\" คือคำย่อของโฟลเดอร์หลักของคุณ) ส่วนการตั้งค่ารายโปรเจกต์อยู่ที่โฟลเดอร์ .ava/ ภายในโปรเจกต์นั้นๆ","reference.config#2#h":"ส่วนกลาง — ~/.ava/","reference.config#3#li0":"settings.json — ความชอบของโมเดล โหมดการอนุญาต บุคลิก ภาษา","reference.config#3#li1":"memory/ — ความทรงจำส่วนกลางของคุณ (ความชอบ ตัดสินใจที่ใช้ได้ทุกที่)","reference.config#3#li2":"tasks.json — รายการงานข้ามโปรเจกต์","reference.config#3#li3":"journal/ — บันทึกประจำวัน จัดเรียงตามวันที่","reference.config#4#h":"โปรเจกต์ — .ava/","reference.config#5#li0":"instructions.md — คำแนะนำเฉพาะโปรเจกต์ที่ Ava โหลดเสมอ บริบทที่คงทน (\"เราใช้ pnpm ไม่ใช่ npm\", \"คีย์ API เก็บใน 1Password\")","reference.config#5#li1":"context.md — หมายเหตุโปรเจกต์แบบอิสระ (ไม่บังคับ)","reference.config#5#li2":"memory/ — ความทรงจำที่กำหนดขอบเขตสำหรับโปรเจกต์นี้","reference.config#5#li3":"datasets/config.json — การตั้งค่าการเก็บข้อมูลชุดข้อมูล (เลือกเปิดใช้งานเอง)","reference.config#6#c":"เพิ่ม .ava/ ลงใน .gitignore (รายการไฟล์ที่บอกให้ Git ไม่รวมในโปรเจกต์ร่วมกัน) หากคุณไม่ต้องการแชร์ความทรงจำกับทีม เก็บ instructions.md ไว้ในโฟลเดอร์โปรเจกต์ร่วมกัน — นั่นคือวิธีที่ Ava เรียนรู้กฎเกณฑ์ของโปรเจกต์","reference.shortcuts#title":"ปุ่มลัดบนคีย์บอร์ด","reference.shortcuts#0#p":"ปุ่มลัดบนคีย์บอร์ดเป็นตัวเลือกเพื่อความเร็ว — ทุกอันมีปุ่มกดให้คุณคลิกได้เช่นกัน ดูที่นี่ก็ต่อเมื่อต้องการควบคุม Ava ให้เร็วขึ้นจากคีย์บอร์ด","reference.shortcuts#1#p":"ปุ่มลัดแบ่งตามพื้นที่ทำงาน (สามจุดที่ Ava ทำงาน: ส่วนขยาย VS Code แอปเดสก์ท็อป และเทอร์มินัล) ปรับแต่งได้ที่การตั้งค่าของแต่ละพื้นที่ ไม่ต้องท่องจำรายการด้านล่าง","reference.models#11#h":"นำคีย์ของคุณเองมาใช้งาน","reference.models#12#p":"คีย์ \"API\" คือรหัสผ่านส่วนตัวที่ใช้ให้ซอฟต์แวร์ใช้บริการที่ต้องชำระเงินในบัญชีของคุณได้ \"BYOK\" ก็แค่หมายถึง \"นำคีย์ของคุณเองมาใช้งาน\" — ใช้ของคุณแทนของเรา วางคีย์ API ของคุณในการตั้งค่า คำขอ BYOK จะส่งตรงจาก Ava ไปยังผู้ให้บริการ (บริษัทที่รันโมเดล) — ไม่ผ่านโครงสร้างพื้นฐานของเราและไม่ใช้โทเค็นแพลตฟอร์ม คุณจ่ายให้ผู้ให้บริการ; เราไม่เห็นการจราจร","reference.models#14#c":"สำหรับคะแนนการทดสอบประสิทธิภาพ แท็กความสามารถ และการกรองแบบเปรียบเทียบ ดูหน้าโมเดลเต็มได้ที่ ava-supernova.com/models ราคาที่แสดงด้านบนคือราคาที่เรารวบรวมจากผู้ให้บริการแต่ละราย ณ เวลาตีพิมพ์ — โปรดตรวจสอบเว็บไซต์ของผู้ให้บริการก่อนตัดสินใจใช้งานเสมอ","reference.personas#title":"การประสานงานบทบาท","reference.personas#0#p":"คำว่า \"บทบาท\" คือหน้าที่ผู้ช่วยที่ Ava เล่นอยู่เบื้องหลังเพื่อทำงานที่ยากขึ้น — เช่น นักสำรวจ ผู้วางแผน ผู้ตรวจสอบข้อเท็จจริง คุณไม่ได้พูดคุยกับพวกเขาโดยตรง และไม่ต้องเข้าใจหน้านี้เพื่อใช้ Ava มันอยู่ที่นี่เมื่อคุณสงสัยว่าเธอแบ่งงานใหญ่เป็นทีมผู้เชี่ยวชาญเล็กๆ อย่างไร","reference.personas#1#p":"ผู้เชี่ยวชาญ 24 คนใน 5 ทีมโหมด หัวหน้าวง (ผู้ประสานงานที่เหลือ) ตัดสินใจว่าทีมใดจะทำงาน ลำดับไหน และด้วยบริบทอะไร โหมดแชทไม่มีบทบาท — นั่นคือตัว Ava เอง","reference.personas#2#h":"วิธีการทำงานของการประสานงาน","reference.personas#3#li0":"คุณส่งข้อความในโหมด วางแผน, สอน, ความปลอดภัย, หรือ ระดมสมอง (หรือคำขอ งาน ที่ซับซ้อน)","reference.personas#3#li1":"หัวหน้าวงอ่านคำขอ เลือกทีมโหมด และสร้างแผนการดำเนินงาน — บางบทบาททำงานตามลำดับ บางส่วนทำงานพร้อมกันเป็นคลื่น","reference.personas#3#li2":"แต่ละบทบาทมีคำสั่งระบบของตัวเอง รายการเครื่องมือที่อนุญาตเฉพาะ และคลังบริภาคร่วมกันของสิ่งที่บทบาทก่อนหน้าค้นพบ","reference.personas#3#li3":"บทบาทสุดท้ายจะผลิตสรุป แผนงาน หรือรายงาน ขึ้นอยู่กับโหมด","reference.personas#3#li4":"Ava นำเสนอผลลัพธ์ให้คุณ คุณอนุมัติ ปรับแต่ง หรือเปลี่ยนทิศทาง","reference.personas#4#p":"รายชื่อด้านล่างนี้เป็นเพียงข้อมูลอ้างอิง — ไม่ต้องจำว่าใครทำอะไร Ava จะประกอบทีมที่เหมาะสมให้คุณ","reference.personas#6#c":"โหมด งาน เรียกใช้ทีมเต็มรูปแบบเฉพาะสำหรับงานซับซ้อน การแก้ไขง่ายๆ ทำงานผ่าน Ava โดยตรง — ไม่มีขั้นตอนการประสานงานเพิ่ม","features.office-suite#title":"Office Suite","features.office-suite#0#p":"ต้องการรายงาน อีเมล หรือเอกสารไหม? Ava สามารถร่างให้และส่งไฟล์ Word, Excel, หรือ PDF จริงให้คุณเปิดและแก้ไขได้เหมือนไฟล์ทั่วไป","features.office-suite#1#p":"รายงาน อีเมล และเอกสาร — ร่าง จัดรูปแบบ และส่งออกเป็นฟอร์แมตต้นฉบับ (.docx คือ Word, .xlsx คือ Excel, .pdf คือ PDF)","features.office-suite#2#li0":"report_generate — ไฟล์ .docx ที่มีโครงสร้าง ดึงข้อมูลจากงาน บันทึก ความจำ และสถานะโปรเจกต์","features.office-suite#2#li1":"email_draft — อีเมลที่ควบคุมโทนเสียง ส่งออกเป็นไฟล์ .docx","features.office-suite#2#li2":"document_manage — สร้าง อ่าน แก้ไข และส่งออก ใน Word, Excel, PDF, CSV, Markdown","features.office-suite#3#p":"มีประโยชน์เมื่อ Ava เขียนแทนคุณ — รายงานสถานะ สไลด์เริ่มโปรเจกต์ อัปเดตลูกค้า ไฟล์ .docx จะลงไปที่โปรเจกต์ของคุณเพื่อให้คุณเกลาต่อได้","features.dashboard-library#title":"คลังข้อมูลแดชบอร์ด","features.dashboard-library#0#p":"พูดง่ายๆ คือ ชั้นวางหนึ่งชั้นที่เก็บทุกอย่างที่คุณและ Ava ทำและคุยกันไว้ ไม่ให้สิ่งใดสูญหาย","features.dashboard-library#1#p":"มุมมองแบบดูรายการได้ ของทุกอย่างที่ Ava สร้างร่วมกับคุณ — ภาพ วิดีโอ เสียง เอกสาร — คู่ไปกับบทสนทนา ความจำ และงานของคุณ สถานที่เดียวที่จะหาสิ่งที่ทำสัปดาห์ที่แล้วเจอ","features.document-preview#title":"ดูตัวอย่างเอกสาร","features.document-preview#0#p":"พูดง่ายๆ คือ มองเข้าไปในเอกสารทันทีที่คุณอยู่ที่นั่น โดยไม่ต้องเปิดโปรแกรมแยกเพื่ออ่าน","features.document-preview#1#p":"คลิกขวาที่ไฟล์ Word doc, Excel sheet, PDF, CSV, HTML, หรือ Markdown ในโปรเจกต์ของคุณ — ดูตัวอย่างแบบอินไลน์โดยไม่ต้องออกจากตัวแก้ไข มีประโยชน์สำหรับการอ่านวัสดุอ้างอิงที่ Ava สร้าง หรือไฟล์ที่เพื่อนร่วมงานทิ้งไว้","features.daily-briefing#title":"สรุปประจำวัน","features.daily-briefing#0#p":"พูดง่ายๆ คือ บันทึกสั้นๆ ทุกเช้าว่า \"นี่คือจุดที่คุณค้างไว้\" เพื่อให้คุณสามารถเริ่มต้นต่อได้โดยไม่ต้องอ่านใหม่ทั้งหมด","features.daily-briefing#1#p":"สรุปตอนเช้า: บันทึกเมื่อวาน งานที่ยังไม่เสร็จ สถานะโปรเจกต์ และการแจ้งเตือนใดๆ ที่ Ava ตั้งไว้ เป็นตัวเลือก — เปิดใช้งานได้ในการตั้งค่า","features.daily-briefing#2#p":"การสรุปนี้จะใช้ความจำเพื่อแสดงบริบทที่เกี่ยวข้อง (\"last time you worked on the auth flow, you noted you wanted to revisit the refresh token strategy\") ไม่ใช่ฟีดข่าว — เป็นการทบทวนที่ตรงประเด็น","reference.project-context#title":"บริบทโปรเจกต์","reference.project-context#0#p":"ส่วนนี้อธิบายว่า Ava อ่านข้อมูลโปรเจกต์ของคุณอย่างไรก่อนเริ่มทำงาน — ไฟล์ที่เธอตรวจสอบเพื่อเข้าใจว่าคุณกำลังทำอะไรอยู่ คุณไม่ต้องตั้งค่าอะไรเอง เธอทำให้อัตโนมัติ อ่านตรงนี้ถ้าอยากรู้ว่าจะวางโน้ตไว้ตรงไหนเพื่อให้เธอมองเห็นเสมอ","reference.project-context#1#p":"เมื่อคุณเปิดโปรเจกต์ Ava จะโหลดบริบทหลายชั้น (ข้อมูลพื้นฐานที่เธอจดจำไว้) การเข้าใจแต่ละชั้นช่วยให้คุณใส่ข้อมูลได้ถูกที่","reference.project-context#2#h":"โหลดอัตโนมัติ","reference.project-context#3#li0":".ava/instructions.md — ถือเป็นคำแนะนำถาวรที่มีความสำคัญสูง เสมออยู่ในความทรงจำ","reference.project-context#3#li1":".ava/context.md — หมายเหตุแบบอิสระ โหลดเข้ามาแต่มีความสำคัญรองลงมา","reference.project-context#3#li2":"README.md — สแกนครั้งแรกเพื่อสรุปภาพรวมโปรเจกต์","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — ไฟล์เล็กๆ ที่ระบุการตั้งค่าโปรเจกต์; อ่านเพื่อตรวจจับภาษา เฟรมเวิร์ก และคำสั่งทดสอบ","reference.project-context#3#li4":".gitignore — รายการไฟล์ที่จะไม่เก็บในเวอร์ชันคอนโทรล; เครื่องมือจัดการไฟล์ทั้งหมดเคารพกฎนี้ (glob, grep, project_index)","reference.project-context#4#h":"โหลดตามความต้องการ","reference.project-context#5#p":"\"ตามความต้องการ\" หมายถึง Ava จะดึงข้อมูลเหล่านี้เฉพาะเมื่อมีงานที่ต้องใช้จริงๆ ไม่ใช่โหลดมาล่วงหน้า","reference.project-context#6#li0":"Project index — แผนที่โครงสร้างไฟล์และองค์ประกอบภายใน (ฟังก์ชัน, คลาส — \"สัญลักษณ์\") พร้อมวิธีการเชื่อมโยง (\"imports\") สร้างแบบรอใช้งาน คือต่อเมื่อ Ava จำเป็นต้องใช้เท่านั้น","reference.project-context#6#li1":"Git history — บันทึกการเปลี่ยนแปลงในอดีต; ดึงมาเมื่อเรียก git_status, git_diff, หรือ git_create_pr (Git คือเครื่องมือติดตามการเปลี่ยนแปลงทุกอย่างในโปรเจกต์; \"PR\" คือ Pull Request หรือข้อเสนอชุดการเปลี่ยนแปลง)","reference.project-context#6#li2":"Memory — ข้อมูลถูกจับคู่ตามความหมาย (\"เชิงความหมาย\") และนำเข้ามาทีละขั้นตอน ไม่ใช่ทั้งหมดพร้อมกัน","reference.project-context#7#c":"วางกฎไว้ใน instructions.md วางโน้ตใน context.md ให้ Memory เก็บส่วนที่เหลือเอง","features.unified-panel#title":"แผงรวมศูนย์","features.unified-panel#0#p":"พูดง่ายๆ: ทุกสิ่งที่ Ava ทำอยู่ในหน้าต่างเดียว ดังนั้นคุณไม่ต้องคอยค้นหาผ่านแท็บต่างๆ เพื่อหา","features.unified-panel#1#p":"แผงเดียวสำหรับแชท, แดชบอร์ด, ความจำ, งาน, และบันทึก ไม่มีการสลับบริบทระหว่างหน้าต่าง แถบด้านข้างเลือกสิ่งที่กำลังดู พื้นที่หลักจะเปลี่ยนตาม","features.unified-panel#2#p":"สถานะการสนทนาจะคงอยู่เมื่อคุณเลื่อนออก — เปิดความจำ, ตรวจสอบงาน, แล้วกลับมาใหม่ แชทยังอยู่ที่นั่น ยังสตรีมอยู่ถ้า Ava ยังทำงานอยู่","features.unified-panel#3#c":"แผงรวมศูนย์เป็นแนวคิดของส่วนขยายและ IDE พื้นผิวเว็บใช้แท็บเบราว์เซอร์","features.knowledge-packs#title":"แพ็กความรู้","features.knowledge-packs#0#p":"พูดง่ายๆ: ส่งโฟลเดอร์เอกสารของคุณให้ Ava เธอก็จะอ่านเพื่อตอบคำถามคุณ \"แพ็กความรู้\" ก็คือชุดไฟล์นั้นเอง — เอกสารอ้างอิงที่คุณอนุญาตให้เธอใช้","features.knowledge-packs#1#p":"วางไดเรกทอรีของเอกสารอ้างอิง (สเปค, RFCs, บันทึกการประชุม, เอกสาร API) ลงในแพ็กความรู้ Ava สามารถดึงส่วนที่เกี่ยวข้องเข้ามาในบริบทได้เมื่อการสนทนาแตะหัวข้อนั้น","features.knowledge-packs#2#p":"แพ็กถูกจัดทำดัชนีในเครื่อง การค้นหาเป็นเชิงความหมาย — Ava หาเอกสารที่ถูกต้องจากความหมาย ไม่ใช่ชื่อไฟล์ (\"เชิงความหมาย\" หมายถึงเธอจับคู่ตามเนื้อหาเอกสาร ดังนั้นคุณไม่ต้องจำคำพูดหรือชื่อไฟล์ที่แน่นอน) แพ็กสามารถแชร์กับทีมหรือเก็บเป็นส่วนตัว","troubleshooting.common-errors#title":"ข้อผิดพลาดที่พบบ่อย","troubleshooting.common-errors#0#p":"ข้อผิดพลาดส่วนใหญ่มีสาเหตุสั้นๆ เฉพาะเจาะจง นี่คือข้อผิดพลาดทั่วไปและวิธีแก้ไข ไม่ต้องกังวลถ้าคำดูเทคนิคเกินไป — แต่ละข้อด้านล่างบอกว่าคุณเห็นอะไรจริงๆ และต้องทำอะไร","troubleshooting.common-errors#1#h":"โมเดลไม่ตอบสนอง","troubleshooting.common-errors#2#p":"สิ่งที่คุณเห็น: Ava เงียบและไม่ตอบกลับ","troubleshooting.common-errors#3#p":"ตรวจสอบตัวบ่งชี้สถานะในหัวข้อแชท ถ้าบอกว่า \"connecting\" ผู้ให้บริการ (บริการ AI ที่ Ava พูดด้วย) เข้าถึงได้แต่ช้า — ให้เวลาสักสามสิบวินาที ถ้าบอกว่า \"unavailable\" Ava จะเปลี่ยนไปใช้โมเดลถัดไปในห่วงโซ่โดยอัตโนมัติ (เธอเปลี่ยนไปใช้โมเดลสำรอง) ถ้าไม่มีอะไรเลย ตรวจสอบคีย์ API ของคุณในการตั้งค่าและทดสอบการเชื่อมต่อ (คีย์ API คือรหัสผ่านส่วนตัวที่ทำให้ Ava ใช้บริการ AI แบบเสียเงินได้)","troubleshooting.common-errors#4#h":"การเรียกใช้เครื่องมือล้มเหลว","troubleshooting.common-errors#5#p":"สิ่งที่คุณเห็น: ขั้นตอนหนึ่งของ Ava (การ \"tool call\" — การอ่านไฟล์ รันคำสั่ง ฯลฯ) แสดงข้อผิดพลาดสีแดงแทนที่จะเสร็จสิ้น","troubleshooting.common-errors#6#p":"คลิกการเรียกใช้เครื่องมือที่ล้มเหลวเพื่อดูข้อผิดพลาด สาเหตุทั่วไป: เธอพยายามแตะไฟล์นอกโฟลเดอร์โปรเจกต์ของคุณ ซึ่งถูกบล็อกไว้เพื่อความปลอดภัยของคุณ (เกราะนี้เรียกว่า \"path traversal\" protection — มันหยุดเธอไม่ให้เดินออกนอกโฟลเดอร์ที่คุณกำลังทำงานอยู่); คำสั่งที่ต้องรันในโฟลเดอร์อื่น; หรือไฟล์ที่ถูกย้ายตั้งแต่ Ava มองครั้งสุดท้าย บอกเธอว่าเกิดอะไรขึ้น — เธอจะลองใหม่อีกครั้งพร้อมแก้ไข","troubleshooting.common-errors#7#h":"ความจำไม่สามารถเรียกคืนได้","troubleshooting.common-errors#8#p":"สิ่งที่คุณเห็น: Ava หาสิ่งที่แน่ใจว่าเธอควรจำไม่ได้","troubleshooting.common-errors#9#p":"ความจำทำงานตามความหมาย ไม่ใช่คำตรงตัว (นี่คือสิ่งที่ \"semantic\" หมายถึง) ดังนั้น \"What did I decide about auth?\" ทำงานได้ดีกว่า \"find my auth decision\". ถ้าความจำมีอยู่แน่ๆ แต่ไม่แสดงขึ้นมา เปิดเบราว์เซอร์ความจำแล้วค้นหา — ถ้าไม่มีอยู่ นั่นแปลว่าไม่เคยบันทึกไว้ในครั้งแรก","troubleshooting.common-errors#10#h":"วงจรรอบการเข้าสู่ระบบ","troubleshooting.common-errors#11#p":"สิ่งที่คุณเห็น: คุณเข้าสู่ระบบ แต่ Ava ถามให้คุณเข้าสู่ระบบอีกครั้ง — วงจรที่ไม่ยอมให้ผ่าน","troubleshooting.common-errors#12#p":"วิธีแก้คือล้างข้อมูลการเข้าสู่ระบบที่บันทึกไว้และเริ่มใหม่: ในส่วนขยาย รัน \"Ava: Sign Out\" จากพาเลตต์คำสั่ง ใน IDE ใช้ Settings → Account → Sign Out ใน CLI ลบไฟล์ที่ ~/.ava/auth.json (ไฟล์เข้าสู่ระบบขนาดเล็กในโฟลเดอร์ชื่อ .ava ในไดเรกทอรีหลักของคุณ) แล้วเข้าสู่ระบบอีกครั้ง","troubleshooting.common-errors#13#h":"โทเค็นหมดแล้ว","troubleshooting.common-errors#14#p":"สิ่งที่คุณเห็น: ข้อความว่าคุณใช้ฟรีเดือนนี้หมดแล้ว (\"Tokens\" เป็นหน่วยวัดการใช้งาน AI — \"exhausted\" แค่หมายถึงคุณใช้โควตาฟรีของเดือนนี้หมดแล้ว)","troubleshooting.common-errors#15#p":"งบประมาณรายเดือนระดับฟรีรีเซ็ตในวันที่ 1 ของทุกเดือน จนกว่าจะถึงวันนั้น สลับไปใช้ผู้ให้บริการ BYOK (ใช้คีย์ API ของคุณเอง) เพื่อทำงานต่อ บัญชีของคุณยังคงใช้งานอยู่ — มีเพียงคำขอที่จัดการโดยแพลตฟอร์มฟรีเท่านั้นที่ถูกพักไว้","troubleshooting.logs#title":"บันทึกอยู่ที่ไหน","troubleshooting.logs#0#p":"\"Log\" ก็เหมือนไดอารี่ที่คอมพิวเตอร์ของคุณจดบันทึกสิ่งที่เกิดขึ้น — มีประโยชน์เมื่อมีบางอย่างเสียหายและคุณ (หรือฝ่ายสนับสนุน) ต้องการดูรายละเอียด","troubleshooting.logs#1#p":"เมื่อคุณต้องการภาพรวมดิบ — เครื่องมือใดถูกเรียก ข้อมูลอะไรที่ได้รับ บริการ AI ส่งกลับมาอย่างไร — บันทึกจะเป็นไฟล์ข้อความธรรมดาในโฟลเดอร์บนคอมพิวเตอร์ของคุณที่ ~/.ava/logs/ (โฟลเดอร์ชื่อ .ava ในไดเรกทอรีหลักของคุณ มีโฟลเดอร์ logs อยู่ข้างใน)","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — บันทึกการประชุมรายเซสชัน รวมถึงการเรียกใช้เครื่องมือ คำตอบแบบสตรีม และข้อผิดพลาด","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — บันทึกโฮสต์ส่วนขยาย VS Code ความล้มเหลวในการเปิดใช้งาน ข้อผิดพลาดของแผงควบคุม","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — บันทึก IDE บนเดสก์ท็อป ข้อความกระบวนการ Sidecar Rust panic","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — บันทึก CLI REPL","troubleshooting.logs#3#p":"ในส่วนขยาย \"Ava: Show Logs\" ในพาเลตต์คำสั่งจะเปิดบันทึกที่เกี่ยวข้องในแท็บบรรณาธิการ ใน IDE, Settings → Diagnostics มีปุ่ม \"Open Logs\" CLI สามารถ tail บันทึกของตัวเองด้วย ava logs --follow.","features.workflows#title":"เวิร์กโฟลว์","features.workflows#0#p":"พูดง่ายๆ ก็คือ สอนให้ Ava จำขั้นตอนที่คุณทำซ้ำๆ แล้วตั้งชื่อให้ มันสามารถรันทั้งหมดนั้นอีกครั้งได้ตามต้องการ เวิร์กโฟลว์ก็คือขั้นตอนที่บันทึกไว้ — ชุดขั้นตอนที่ Ava ทำซ้ำให้คุณ","features.workflows#1#p":"บันทึกลำดับขั้นตอนที่คุณพบว่าตัวเองทำซ้ำ — ตรวจสอบคำขอรวมโค้ด → รันเทสต์ → เขียนบันทึกการปล่อยเวอร์ชัน → ร่างอีเมล เวิร์กโฟลว์คือแผนที่ใช้ซ้ำได้ซึ่ง Ava สามารถเล่นซ้ำด้วยข้อมูลนำเข้าที่แตกต่างกัน","features.workflows#2#p":"เวิร์กโฟลว์จะถูกเก็บแยกตามโปรเจกต์ในโฟลเดอร์ .ava/workflows/ ภายในโปรเจกต์ของคุณ แชร์กับทีมของคุณได้โดยการ commit โฟลเดอร์นี้ (บันทึกไว้ในโปรเจกต์ร่วมกันเพื่อให้เพื่อนร่วมทีมได้รับด้วย)","features.events#title":"เหตุการณ์และการแจ้งเตือน","features.events#0#p":"พูดง่ายๆ ก็คือ ในขณะที่ Ava ทำงาน คุณจะได้รับรายการทีละขั้นตอนที่เรียบร้อยว่าเธอกำลังทำอะไรอยู่ และการแจ้งเตือนเมื่องานที่ยาวนานเสร็จสิ้น เพื่อให้คุณสามารถเดินจากไปได้","features.events#1#p":"ในขณะที่ Ava กำลังทำงาน คุณจะเห็นการอัปเดตที่เป็นโครงสร้าง ไม่ใช่กำแพงข้อความ แต่ละการเรียกใช้เครื่องมือ แต่ละการส่งต่อบทบาท แต่ละข้อมูลที่ส่งมาแบบเรียลไทม์จะเป็นเหตุการณ์ที่ไม่ต่อเนื่องใน UI — ขยายเพื่อดูรายละเอียด หรือพับเพื่อภาพรวม","features.events#2#p":"การรันเบื้องหลังจะส่งการแจ้งเตือนระดับระบบปฏิบัติการเมื่อเสร็จสิ้น คุณสามารถเดินจากงานสร้างที่ยาวนาน และ Ava จะบอกคุณเมื่อมันเสร็จแล้ว","features.personality#title":"ผู้ปรับบุคลิกภาพของ Ava","features.personality#0#p":"พูดง่ายๆ ก็คือ ปรับวิธีที่ Ava พูดคุยกับคุณ — สนทนาเยอะหรือสั้น เป็นทางการหรือไม่เป็นทางการ มีมุกตลกมากขึ้นหรือน้อยลง — เพื่อให้เธอฟังดูเหมือนที่คุณชอบ","features.personality#1#p":"กำหนดวิธีที่ Ava พูดคุยกับคุณ น้ำเสียง พลังงาน ความยาวประโยค (ว่าเธอพูดมากแค่ไหน) ความเป็นทางการ ความตลกขบขัน แถบเลื่อนและรูปแบบสำเร็จรูป — วิศวกรกระชับ ที่ปรึกษาอบอุ่น เพื่อนร่วมงานแห้งแล้ง หรือส่วนผสมของคุณเอง","features.personality#2#p":"บุคลิกภาพส่งผลต่อการเลือกใช้คำ ไม่ใช่ความสามารถ เธอยังคงใช้เครื่องมือเดียวกันและปฏิบัติตามกฎสิทธิ์เดียวกัน ชื่อของเธอถูกล็อกไว้ที่ Ava — ซึ่งเป็นเรื่องที่ไม่สามารถต่อรองได้","features.release-notes#title":"บันทึกการปล่อยเวอร์ชัน","features.release-notes#0#p":"พูดง่ายๆ ก็คือ รายการสรุปสิ่งที่ใหม่และสิ่งที่ได้รับการแก้ไขในการอัปเดตแต่ละครั้ง เพื่อให้คุณเห็นว่ามีอะไรเปลี่ยนแปลง","features.release-notes#1#p":"ประวัติการเปลี่ยนแปลงในแอป (ประวัติการเปลี่ยนแปลงคือประวัติของการเปลี่ยนแปลง) ทุกเวอร์ชันที่ปล่อยออกมาพร้อมไฮไลต์ การแก้ไขข้อบกพร่อง และการเปลี่ยนแปลงสำคัญ (การเปลี่ยนแปลงที่อาจต้องการให้คุณปรับวิธีใช้งานบางอย่าง) หน้าเว็บรักษาเวอร์ชันสาธารณะไว้ที่ ava-supernova.com/releases","troubleshooting.logs#4#c":"บันทึกข้อมูลอาจมีบางส่วนจากไฟล์โปรเจกต์ที่ Ava อ่านระหว่างการทำงาน ตรวจสอบให้เรียบร้อยก่อนส่งต่อ","troubleshooting.support-request#title":"ส่งเรื่องขอความช่วยเหลือ","troubleshooting.support-request#0#p":"พูดง่ายๆ ก็คือ: หากมีปัญหาและวิธีแก้ไขด้านบนยังไม่ช่วย ให้ส่งข้อความแจ้งเรา วิธีที่ง่ายที่สุดคือสั่งให้ Ava ช่วยทำแทนคุณได้เลย","troubleshooting.support-request#1#p":"หากปัญหานั้นไม่อยู่ในรายการข้อผิดพลาดทั่วไป ให้เปิดตั๋วขอความช่วยเหลือ (ส่งคำขอถึงทีมสนับสนุน) คุณสามารถทำได้ภายใน Ava (ไม่ต้องกรอกแบบฟอร์ม) หรือผ่านเว็บไซต์","troubleshooting.support-request#2#h":"จากภายในแอป Ava","troubleshooting.support-request#3#p":"สั่งให้เธอทำแทน บอกว่า \"Ava ช่วยเปิดตั๋วขอความช่วยเหลือเรื่องนี้ให้หน่อยได้ไหม?\" เธอจะเรียกใช้ support_request แนบบริบทของเซสชันที่เกี่ยวข้อง (โดยลบข้อมูลลับออก) แล้วส่งไปเลย นี่คือวิธีที่เร็วที่สุด","troubleshooting.support-request#4#h":"ผ่านเว็บไซต์","troubleshooting.support-request#5#p":"เข้าไปที่ ava-supernova.com/support เลือกหมวดหมู่ (เช่น bug, feature, account, security, general) แล้วอธิบายสิ่งที่เกิดขึ้น เราจะตอบกลับภายในหนึ่งวันทำการ","troubleshooting.support-request#6#h":"ข้อมูลที่ต้องระบุ","troubleshooting.support-request#7#li0":"สิ่งที่คุณกำลังพยายามทำ","troubleshooting.support-request#7#li1":"สิ่งที่เกิดขึ้นจริง","troubleshooting.support-request#7#li2":"ส่วนที่ใช้ (ส่วนเสริม, IDE, CLI, โปรแกรมคู่) และเวอร์ชันใด","troubleshooting.support-request#7#li3":"ข้อความแสดงข้อผิดพลาดหรือส่วนหนึ่งของบันทึกข้อมูลใดๆ ลบข้อมูลลับออกก่อนเสมอ","troubleshooting.security-disclosure#title":"แจ้งรายงานปัญหาความปลอดภัย","troubleshooting.security-disclosure#0#p":"พูดง่ายๆ ก็คือ: หากคุณพบช่องโหว่ที่อาจทำให้ Ava ถูกเจาะหรือถูกใช้งานในทางที่ผิด (\"vulnerability\" — จุดอ่อนด้านความปลอดภัย) กรุณาแจ้งเราเป็นส่วนตัวก่อน เพื่อให้เราสามารถแก้ไขได้ก่อนที่ใครจะนำไปใช้ประโยชน์ หน้านี้คือวิธีการ","troubleshooting.security-disclosure#1#p":"พบช่องโหว่แล้วหรือยัง? ขอบคุณครับ เราให้ความสำคัญกับทุกการรายงาน และจะร่วมมือกันแก้ไขก่อนมีการเปิดเผยต่อสาธารณะ (ก่อนประกาศปัญหาอย่างเป็นทางการ)","troubleshooting.security-disclosure#2#h":"วิธีการแจ้ง","troubleshooting.security-disclosure#3#li0":"ส่งอีเมลถึง security@ava-supernova.com พร้อมคำอธิบาย ขั้นตอนการจำลองเหตุการณ์ และช่วงเวลาที่ต้องการเปิดเผยข้อมูล","troubleshooting.security-disclosure#3#li1":"หรือเปิดตั๋วขอความช่วยเหลือโดยเลือกหมวดหมู่ \"security\" — อยู่ในคิวตรวจสอบเดียวกัน","troubleshooting.security-disclosure#3#li2":"เราจะยืนยันรับเรื่องภายใน 24 ชั่วโมง","troubleshooting.security-disclosure#4#h":"พันธกิจของเรา","troubleshooting.security-disclosure#5#li0":"การเปิดเผยข้อมูลแบบประสานงาน — เราตกลงกำหนดเวลาด้วยกันก่อนจะมีการเผยแพร่สู่สาธารณะ กำหนดมาตรฐานคือ 90 วัน","troubleshooting.security-disclosure#5#li1":"การให้เครดิต — คุณจะได้รับการยกย่องในบันทึกการแก้ไข เว้นแต่คุณต้องการความเป็นส่วนตัว","troubleshooting.security-disclosure#5#li2":"ไม่มีการดำเนินคดีตอบโต้ — การวิจัยด้วยความตั้งใจดีเป็นที่ต้อนรับ เราจะไม่มีทนายความมาดำเนินการทางกฎหมายกับคุณ","troubleshooting.security-disclosure#6#c":"หน้าด้านความปลอดภัยที่ ava-supernova.com/security มีรายละเอียดครบถ้วน — หลักประกันสถาปัตยกรรม ระบบปิดบังข้อมูล และระบบควบคุมสิทธิ์","start.for-non-coders#title":"ไม่เคยเขียนโค้ดเลย? เริ่มต้นที่นี่","start.for-non-coders#0#p":"หากคุณไม่เคยเขียนโค้ดแม้แต่บรรทัดเดียว คุณคือกลุ่มเป้าหมายของ Ava คุณไม่ต้องเรียนศัพท์เทคนิคเพื่อเริ่ม — พูดคุยกับเธอเป็นภาษาอังกฤษธรรมดา เหมือนถามเพื่อนที่มีความรู้หน้านี้คือทางเข้าทั้งหมดของคุณ","start.for-non-coders#1#h":"วันนี้คุณทำอะไรได้บ้าง โดยไม่มีประสบการณ์","start.for-non-coders#2#li0":"ถามเธอได้ทุกเรื่อง ด้วยภาษาปกติ — \"ไฟล์นี้ทำอะไร\", \"ทำไมหน้าเว็บของฉันว่างเปล่า\", \"ฐานข้อมูลคืออะไรกันแน่\" เธอตอบเป็นภาษาเข้าใจง่ายและจำบทสนทนาได้","start.for-non-coders#2#li1":"เรียนรู้สิ่งใหม่ตั้งแต่ต้น — บอกว่า \"สอนฉัน Python จากศูนย์\" แล้วเธอจะสร้างคอร์สเรียนพร้อมบทเรียนและแบบทดสอบให้คุณ นี่คือฟรีเสมอ","start.for-non-coders#2#li2":"สร้างบางอย่างขึ้นมา — อธิบายสิ่งที่ต้องการ (\"ปุ่มที่ดาวน์โหลดโน้ตของฉัน\") แล้วเธอจะเขียนโค้ดให้ แสดงทุกการเปลี่ยนแปลงก่อนเกิดขึ้น","start.for-non-coders#3#h":"คุณไม่ต้องเข้าใจทุกอย่าง","start.for-non-coders#4#p":"Ava มีกลไกมากมายซ่อนอยู่เบื้องหลัง — โหมด โมเดล ผู้เชี่ยวชาญ การกำหนดเส้นทาง คุณจะเห็นคำเหล่านี้ในแอปและเอกสารเหล่านี้ ความจริงคือ: คุณสามารถเพิกเฉยเกือบทั้งหมดได้ Ava เลือกเครื่องมือและผู้ช่วยที่เหมาะสมให้คุณอัตโนมัติ หน้าด้านเทคนิคมีไว้เมื่อคุณอยากค้นคว้าเพิ่มเติม ไม่ใช่เพราะคุณจำเป็นต้องใช้เพื่อเริ่มต้น","start.for-non-coders#5#h":"เส้นทางแรกอย่างนุ่มนวล","start.for-non-coders#6#li0":"ติดตั้ง Ava (หน้าถัดไป) แล้วเปิดแชท","start.for-non-coders#6#li1":"พิมพ์คำถามจริงที่คุณมี อะไรก็ได้ ดูว่าเธอตอบอย่างไร","start.for-non-coders#6#li2":"ลองโหมดการเรียนรู้: พิมพ์ \"teach me\" และหัวข้อ ตามไปพร้อมกัน","start.first-five#5#li0":"คำถาม — “หน้าเว็บของฉันว่างเปล่าทำไม?”, “ไฟล์นี้ทำหน้าที่อะไร?”","start.first-five#5#li1":"สิ่งที่คุณต้องการสร้าง — “สร้างหน้ารายการสิ่งที่ต้องทำง่ายๆ ให้ฉันหน่อย”.","start.first-five#5#li2":"เพื่อเรียนรู้สิ่งใหม่ — “สอนฉันเขียน Python ตั้งแต่เริ่มต้นให้หน่อย” (ฟรีเสมอ)","start.first-five#5#li3":"เอกสาร — “เขียนข้อเสนอโครงการหนึ่งหน้าให้ฉันหน่อย” เธอจะส่งไฟล์ Word หรือ PDF ให้คุณ","start.first-five#6#c":"ไม่แน่ใจว่าจะพิมพ์อะไรดี? พูดคุยกับเธอเหมือนเพื่อนที่มีความรู้ คำพูดธรรมดาๆ ก็เพียงพอแล้ว — คุณไม่ต้องใช้ศัพท์เทคนิคเพื่อให้เริ่มใช้งานได้","start.first-five#deeper#0#p":"วงจรง่ายๆ นั้นกำลังทำงานหนักอยู่เบื้องหลัง คุณไม่จำเป็นต้องรู้เรื่องนี้เพื่อใช้ Ava — แต่หากคุณอยากรู้ นี่คือสิ่งที่เกิดขึ้นจริงๆ","start.first-five#deeper#1#h":"เครื่องมือและการอนุมัติ","start.first-five#deeper#2#p":"เมื่อ Ava อ่านไฟล์ รันคำสั่ง หรือแก้ไขโค้ด แต่ละอย่างคือ \"การเรียกใช้เครื่องมือ\" เธอจะถามก่อนทุกครั้งที่มีอะไรสัมผัสไฟล์หรือระบบของคุณ — ความถี่ในการถามถูกกำหนดโดยโหมดการอนุญาตของคุณ (ถามทุกครั้งที่ทำ, ถามเฉพาะเรื่องเสี่ยง, หรือแค่ทำเลย)","start.first-five#deeper#3#h":"โหมด — สภาวะจิตใจของเธอ","start.first-five#deeper#4#p":"Ava ทำงานในโหมดต่างๆ: จิตใจบวกชุดเครื่องมือที่เหมาะสมสำหรับงาน สามารถสลับได้ตลอดเวลาจากตัวเลือก หรือพิมพ์คำนำหน้าไว้ต้นข้อความ มีทั้งหมดเจ็ดโหมด","start.first-five#deeper#6#h":"ผู้เชี่ยวชาญและการจัดเส้นทาง","start.first-five#deeper#7#p":"ในงานที่ยากขึ้น Ava จะเรียกทีมผู้เชี่ยวชาญเล็กๆ เบื้องหลัง (ผู้วางแผน, ผู้ตรวจสอบ, ผู้สร้าง) และส่งแต่ละขั้นตอนไปยังโมเดลที่เก่งที่สุด คุณไม่ต้องจัดการอะไรทั้งนั้น — เธอประสานงานให้คุณเอง","start.local-vs-cloud#title":"ท้องถิ่นเทียบกับคลาวด์ ในย่อหน้าเดียว","start.local-vs-cloud#0#p":"ทุกสิ่งที่ Ava ทำเป็นแบบท้องถิ่น ยกเว้นคุณจะเลือกเข้าร่วมเอง ความจำ งาน บันทึก บุคลิก การตั้งค่า — เก็บไว้ในเครื่องของคุณที่ ~/.ava/ และ .ava/ (ต่อโปรเจกต์) เธอติดต่อผู้ให้บริการโมเดลผ่าน HTTPS เพื่อรันคำขอของคุณ แล้วกลับมาที่เครื่องของคุณ เธอไม่ได้ส่งข้อมูลกลับ เธอไม่เก็บข้อมูลสถิติการใช้งาน เธอไม่ใช้โค้ดของคุณฝึกฝนโมเดล","start.local-vs-cloud#1#p":"หากคุณเข้าสู่ระบบ คุณจะได้รับเครดิตฟรี 300 หน่วยต่อเดือนบนโมเดลที่แพลตฟอร์มจัดการ (Qwen, MiniMax) และการซิงค์คลาวด์แบบเลือกได้สำหรับความจำและการตั้งค่าข้ามเครื่อง การซิงค์เป็นรายฟีเจอร์ ยกเลิกได้ตลอดเวลา นำคีย์ API ของคุณมาเองและ Ava จะทำงานได้เต็มที่โดยไม่ต้องมีบัญชี","start.local-vs-cloud#2#c":"กฎ: ท้องถิ่นคือศักดิ์สิทธิ์ คลาวด์เป็นเพียงส่วนเสริม","start.first-model#title":"ฉันต้องเลือก AI เองไหม?","start.first-model#0#p":"นี่เป็นเรื่องสบายใจ: คุณไม่ต้องเลือก AI เอง Ava จะเลือกตัวที่เหมาะสมที่สุดสำหรับแต่ละขั้นตอนโดยอัตโนมัติ เพื่อให้คุณได้ผลลัพธ์ที่ดีโดยไม่ต้องคิดมาก","start.first-model#1#p":"สิ่งเดียวที่คุณเลือกได้คือสไตล์การจัดเส้นทาง — และค่าเริ่มต้นเหมาะกับเกือบทุกคน คุณต้องการอันอื่นก็ต่อเมื่อมีเหตุผลเฉพาะเจาะจง","start.first-model#2#h":"สไตล์ทั้งสาม","start.first-model#3#li0":"Maestro — ค่าเริ่มต้น มั่นคง เชื่อถือได้ คาดการณ์ได้ ไม่แน่ใจ? อันนี้แหละ","start.first-model#3#li1":"Supernova — สำหรับงานหนักหลายขั้นตอน ซึ่งคุ้มค่าที่จะแบ่งงานให้ผู้เชี่ยวชาญคนละคนดูแล","start.first-model#3#li2":"Aurora — เมื่อข้อมูลของคุณต้องอยู่ในสหภาพยุโรป (ภาครัฐ, สุขภาพ, ความเป็นส่วนตัวเข้มงวด) ทำงานด้วย AI แบบโอเพนเวทของยุโรปเท่านั้น","start.first-model#4#p":"เปลี่ยนได้ตลอดเวลาจากตัวเลือกโมเดลด้านบนของแชท ไม่มีอะไรล็อกไว้","start.first-model#5#c":"อยากควบคุมโมเดลเฉพาะเองบ้างไหม? ได้ — เปิด \"แสดงรายละเอียดให้ฉันดู\"","start.what#title":"Ava คืออะไร?","start.what#0#p":"Ava เป็น AI ที่ลงมือทำจริง ๆ ไม่ใช่แค่พูด เธอจะสร้างแอปให้คุณ เขียนเอกสารให้คุณ สอนสิ่งใหม่ตั้งแต่ต้น ออกแบบโลโก้ หรือจัดการงานบ้านที่คุณมักเลื่อนออกไป และเธอยังจำคุณได้: ว่ากำลังทำงานอะไร ชอบแบบไหน เคยถามอะไรมาเมื่อสัปดาห์ที่แล้ว","start.what#1#p":"มี Ava คนเดียว และเธอทำงานได้ทุกที่ที่คุณทำ — ในโปรแกรมแก้ไขโค้ดของคุณ เป็นแอปบนเดสก์ท็อป บนโทรศัพท์ หรือในเทอร์มินอล ความทรงจำเดียวกัน บุคลิกเดียวกัน ทุกที่","start.what#2#h":"อะไรทำให้เธอแตกต่าง","start.what#3#li0":"เป็นของคุณโดยค่าเริ่มต้น งานของคุณอยู่บนเครื่องของคุณเอง ไม่มีติดตาม ไม่มีเก็บข้อมูล — ไม่เคยเลย","start.what#3#li1":"เปิดให้ทุกคนเห็น ทุกบรรทัดของ Ava เป็นสาธารณะ ไม่ต้องเชื่อใจใคร","start.what#3#li2":"เริ่มต้นฟรี ให้เครดิต 300 ทุกเดือน ไม่ต้องใช้บัตร ไม่ต้องมีเงื่อนไข — หรือใส่คีย์ AI ของคุณเองแล้วไม่ต้องจ่ายเราเลยสักบาท","start.what#3#li3":"การสอนฟรีตลอดไป การเรียนรู้ไม่ควรต้องมีราคา","start.what#4#p":"ยังไม่เคยเขียนโค้ดไหม? หน้าถัดไปเขียนมาเพื่อคุณโดยเฉพาะ ถ้ามีความรู้ด้านเทคนิคอยู่แล้ว? เลื่อนไปข้างหน้าได้เลย — เธอตลอดตามทัน","start.what#deeper#0#h":"Ava อยู่ที่ไหนบ้าง","start.what#deeper#1#li0":"ส่วนขยาย VS Code — Ava อยู่ข้างๆ ตัวแก้ไขของคุณ: ช่องแชท แดชบอร์ด และการเปลี่ยนแปลงแสดงตรงหน้าก่อนเกิดขึ้นจริง","start.what#deeper#1#li1":"IDE บนเดสก์ท็อป — แอปแยกต่างหากที่มีทุกอย่างในหน้าต่างเดียว เพิ่มการควบคุมเดสก์ท็อป (เปิดแอป คลิก พิมพ์แทนคุณ)","start.what#deeper#1#li2":"เพื่อนคู่คิด — แอปมือถือสำหรับตอนอยู่นอกโต๊ะทำงาน: งานที่ต้องทำ บันทึกประจำวัน ความทรงจำ แชทสั้นๆ","start.what#deeper#1#li3":"CLI — Ava ในเทอร์มินัลของคุณ สำหรับคนที่ใช้ชีวิตอยู่ที่นั่น","start.what#deeper#2#h":"วิธีทำงานของเธอ แบบย่อ","start.what#deeper#3#p":"Ava จะเปลี่ยนโหมดความคิด (เรียกว่าโหมด) ให้เหมาะกับงาน ทำงานเบื้องหลังด้วยทีมผู้ช่วยผู้เชี่ยวชาญสำหรับงานที่ยากขึ้น และเลือกโมเดล AI ที่ดีที่สุดสำหรับแต่ละขั้นตอนอัตโนมัติ คุณไม่ต้องจัดการอะไรเลย ส่วนหัวข้อแนวคิดหลักมีรายละเอียดครบถ้วนไว้เสมอเมื่อคุณอยากทราบ","start.first-five#title":"สิ่งแรกที่คุณทำกับ Ava","start.first-five#0#p":"วิธีเร็วที่สุดที่จะเริ่มใช้ Ava คือขอให้เธอทำอะไรจริง ๆ แล้วดูเธอทำ ไม่ต้องตั้งค่าให้อ่าน ไม่ต้องเรียนรู้อะไรก่อน — แค่บอกสิ่งที่ต้องการ ด้วยคำธรรมดา","start.first-five#1#h":"ลองทำตอนนี้เลย","start.first-five#2#li0":"เปิดช่องแชท","start.first-five#2#li1":"พิมพ์สิ่งที่ต้องการจริง ๆ ลองเช่น \"อธิบายว่าโปรเจกต์นี้ทำอะไร\" หรือ \"เพิ่มปุ่มล้างฟอร์ม\"","start.first-five#2#li2":"Ava แสดงสิ่งที่เธอจะทำ — แล้วรอ","start.first-five#2#li3":"พอใจไหม? บอกใช่ ดูเธอทำ","start.first-five#3#p":"นั่นคือจังหวะทั้งหมด: คุณถาม เธอแสดงแผนให้คุณดู คุณอนุมัติ เธอทำ เธอไม่เปลี่ยนอะไรโดยไม่แสดงให้คุณดูก่อน — ดังนั้นคุณจึงไม่สามารถทำลายอะไรได้ด้วยการลอง","start.first-five#4#h":"บางสิ่งน่าขอ","start.glossary#1#td7.1":"หน่วยที่ง่ายขึ้นของ Ava สำหรับบอกต้นทุนของแต่ละการกระทำ ทำให้คุณไม่ต้องปวดหัวกับการคำนวณโทเค็น แผนต่างๆ มาพร้อมแพ็กเกจรายเดือน","start.glossary#1#td8.0":"คีย์ API","start.glossary#1#td8.1":"รหัสผ่านส่วนตัวที่ทำให้ซอฟต์แวร์สามารถใช้บริการแบบชำระเงิน (เช่น โมเดล AI) ในบัญชีของคุณ คุณจำเป็นต้องมีเฉพาะเมื่อต้องการนำคีย์ของตัวเองมาใช้","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"นำคีย์ของคุณเอง.\" ใช้คีย์ API ของคุณเองแทนการเข้าถึงที่จัดการโดย Ava เป็นทางเลือก — สำหรับผู้ที่จ่ายกับผู้ให้บริการโดยตรงอยู่แล้ว","start.glossary#1#td10.0":"เน้นท้องถิ่น","start.glossary#1#td10.1":"ข้อมูลของคุณจะอยู่ที่คอมพิวเตอร์ของคุณเป็นค่าเริ่มต้น ไม่มีการอัปโหลดอะไรเลย เว้นแต่คุณจะเปิดการซิงค์ไว้ \"ข้อมูลในเครื่องคือสิ่งที่ศักดิ์สิทธิ์\"","start.glossary#1#td11.0":"โหมดการอนุญาต","start.glossary#1#td11.1":"ระดับความระมัดระวังของ Ava ก่อนทำสิ่งใดสิ่งหนึ่ง — ถามทุกครั้ง, ถามเฉพาะเรื่องเสี่ยง, หรือแค่ทำไปเลย คุณเป็นคนกำหนดระดับเอง","start.glossary#1#td12.0":"หน้าต่างบริบท","start.glossary#1#td12.1":"ปริมาณข้อความที่โมเดลจดจำไว้ในใจได้ทีละครั้ง — ความจำระยะสั้นของโมเดล \"1M บริบท\" หมายถึงประมาณหนึ่งล้านคำ ยิ่งมาก = ยิ่งอ่านได้เยอะก่อนจะลืม","start.glossary#1#td13.0":"ส่วนต่าง","start.glossary#1#td13.1":"การแสดงเปรียบเทียบแบบคู่ขนานว่าไฟล์จะเปลี่ยนแปลงตรงไหนบ้าง — เก่าอยู่ฝั่งหนึ่ง ใหม่อยู่อีกฝั่ง — แสดงให้เห็นก่อนที่ Ava จะแก้ไขอะไรใดๆ เพื่อให้คุณสามารถอนุมัติได้","start.glossary#1#td14.0":"ที่เก็บงาน (repo)","start.glossary#1#td14.1":"โฟลเดอร์โปรเจกต์ที่ถูกติดตามการเปลี่ยนแปลง โดยปกติจะใช้ Git ถ้ายังไม่คุ้นเคยกับคำนี้ ก็แค่ \"โฟลเดอร์ที่โปรเจกต์ของฉันอาศัยอยู่\"","start.glossary#1#td15.0":"คำสั่ง","start.glossary#1#td15.1":"สิ่งที่พิมพ์ส่งไปยัง AI — คำถามหรือคำสั่งของคุณ","start.glossary#2#c":"ยังติดขัดกับคำไหนอยู่ไหม? ถาม Ava ในโหมดแชท — \"X หมายถึงอะไร?\" — แล้วเธอจะอธิบายตามระดับของคุณ","models.routing#title":"การเลือกเส้นทาง — วิธีที่ Ava เลือกโมเดล","models.routing#0#p":"นี่คือสรุปสั้นๆ: คุณไม่ต้องเลือกเองว่าใช้โมเดล AI ตัวไหน Ava ทำแทนคุณ เลือกเครื่องมือที่ดีที่สุดสำหรับแต่ละส่วนของงาน — เหมือนผู้จัดการที่ดีมอบงานที่เหมาะสมให้คนที่เหมาะสม","models.routing#1#p":"คุณเลือกสไตล์หนึ่งในสาม — Maestro, Supernova, หรือ Aurora — และ Ava จะส่งงานแต่ละชิ้นไปยังโมเดลที่จัดการได้ดีที่สุด Maestro เป็นค่าเริ่มต้น ทำงานบนทุกแผน และเป็นตัวเลือกที่ดีสำหรับเกือบทุกคน","models.routing#2#h":"ทำไมต้องเลือกเส้นทาง?","models.routing#3#p":"การใช้โมเดลที่เหมาะสมในแต่ละขั้นตอนมีค่าใช้จ่ายน้อยกว่าการรันทุกอย่างบนโมเดลใหญ่ราคาแพงเพียงตัวเดียว — และให้ผลลัพธ์ที่ดีกว่า เพราะแต่ละโมเดลทำในสิ่งที่มันถนัดที่สุด คุณจะได้ต้นทุนที่คงที่และคุณภาพสูงโดยไม่ต้องรู้เลยว่าโมเดลไหนคือโมเดลไหน","models.routing#4#c":"สไตล์ทั้งสามใช้งานได้ทั้งบนเครดิตของแพลตฟอร์มและคีย์ของคุณเอง หากคุณใช้คีย์ของคุณเอง คุณสามารถข้ามการเลือกเส้นทางและใช้โมเดลเดี่ยวโดยตรงได้ รายละเอียดครบถ้วนของกองเรืออยู่ใต้ \"แสดงรายละเอียดให้ฉันดู\"","models.routing#deeper#0#c":"ตัวเลข \"B\" ด้านล่างหมายถึงพันล้านพารามิเตอร์ — ประมาณขนาดสมองของโมเดล; ยิ่งใหญ่ขึ้นมักหมายถึงฉลาดขึ้นแต่ช้าลงและแพงขึ้น นี่คือรายละเอียดเบื้องหลัง; คุณไม่จำเป็นต้องรู้เพื่อใช้ Ava","models.routing#deeper#1#h":"เปรียบเทียบแบบเคียงข้างกัน","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"ผู้ประสานงาน","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B พารามิเตอร์ที่ใช้งาน, 1M บริบท)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B พารามิเตอร์ที่ใช้งาน, 262K บริบท)","models.routing#deeper#2#td1.0":"ผู้สร้าง","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (ใช้ผู้ประสานงานซ้ำ)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B แบบหนาแน่น, 256K บริบท)","models.routing#deeper#2#td2.0":"ผู้เชี่ยวชาญระดับกลาง","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (ผู้ตรวจสอบโค้ด, ผู้ตรวจสอบข้อเท็จจริง, รวบรวมข้อมูล, สแกน, ยืนยันความปลอดภัย, ฯลฯ)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (สถาปนิก, ผู้ตรวจสอบ, ผู้จัดลำดับ, ผู้สอน, ผู้รายงาน, ฯลฯ)","models.routing#deeper#2#td3.0":"ระดับเบา / ตัวกรองเจตนา","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (ผู้ลาดตระเวน, ผู้ตรวจสอบ, ผู้จัดลำดับ, ผู้ท้าทาย, ผู้บูรณาการ)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"ผู้เชี่ยวชาญระดับสูง","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (นักวิจัย, ผู้ท้าทาย, นักวิจัย CVE, ผู้ริเริ่มไอเดีย, ผู้ตรวจสอบข้อเท็จจริง)","models.routing#deeper#2#td5.0":"แชท","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"การจัดการสร้างภาพ","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"การมองเห็น","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (ตัวเข้ารหัสภาพที่ฝึกฝนจากศูนย์)","models.routing#deeper#2#td8.0":"การเขียนเนื้อหาแบบยาว","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"ที่ตั้งข้อมูล","models.routing#deeper#2#td9.1":"ผสมผสาน (Alibaba Cloud)","models.routing#deeper#2#td9.2":"ผสมผสาน (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"เฉพาะ EU · โมเดลน้ำหนักเปิด","models.routing#deeper#2#td10.0":"สถานะ","models.routing#deeper#2#td10.1":"ใช้งานได้แล้ว · ทุกแพ็กเกจ","models.routing#deeper#2#td10.2":"เร็วๆ นี้","models.routing#deeper#2#td10.3":"เร็วๆ นี้","models.routing#deeper#2#td11.0":"เหมาะสำหรับ","models.routing#deeper#2#td11.1":"งานประจำวัน ค่าใช้จ่ายที่คาดการณ์ได้","models.routing#deeper#2#td11.2":"งานหนักหลายขั้นตอน มีตัวประสานงานระดับแนวหน้าในทุกแพ็กเกจ","models.routing#deeper#2#td11.3":"GDPR-strict, ภาคสาธารณะ, โครงสร้างพื้นฐานแบบอธิปไตยของ EU","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"การกระจายงาน Qwen ตามระดับชั้น พื้นที่ใช้สอยต่ำ Qwen 3.6 Plus ดูแลบทบาทตัวประสานงาน ผู้สร้าง (Builder) การวางแผน ความปลอดภัย การระดมสมอง และงานบริบทยาว — ซึ่งเป็นจุดที่ความสามารถรองรับบริบทยาว 1 ล้านโทเค็นด้วย Hybrid Linear Attention ของมันทำได้ดีที่สุด Qwen 3.5 Flash จัดการแชท การสั่งการสร้างภาพ และประตูเจตนาต้นน้ำ ซึ่งราคา $0.07/$0.26 และเวลาตอบกลับเร็ว (TTFT) ชนะใจปริมาณโทเค็นส่วนใหญ่ที่มีความลึกต่ำ Qwen 3.5 Omni Plus ดูแลอินพุตภาพ (Qwen 3.6 Plus ไม่มีระบบภาพในตัว) Qwen 3.5 Plus ดูแลงานเขียนยาวที่เน้นต้นทุน หากตัวประสานงานหลักไม่ว่าง ระบบจะลองใช้ลำดับถัดไป: Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"กลุ่มโมเดลพหุภาษา DeepSeek V4 Pro ประสานงานและส่งมอบงานย่อยให้แต่ละผู้เชี่ยวชาญเฉพาะทาง: Qwen 3.6 Plus ทำงานทุก Spawn ของ Builder, V4 Flash จัดการแชท รวมถึงบุคลิกภาพตรวจสอบ/สอบทานระดับกลาง, Qwen 3.5 Flash รับงานจำแนกประเภทระดับเบา, Qwen 3.5 Omni Plus ดูแลอินพุตภาพ, Qwen 3.5 Omni Flash สั่งการคำสั่งเครื่องมือสร้างภาพ, Qwen 3.5 Plus ดูแลบุคลิกภาพผู้เขียนเนื้อหาที่เน้นต้นทุน เหตุผลขั้นสูงเฉพาะจุดที่สำคัญ ส่วนเศรษฐศาสตร์ระดับ Flash สำหรับปริมาณโทเค็นส่วนใหญ่","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"โครงสร้างพื้นฐาน AI แห่งยุโรป — ออกแบบให้เป็นอธิปไตย การกระจายงานใช้เฉพาะ Mistral ในสามระดับ: Mistral Large 3 (675B/41B-active sparse MoE) ดูแลบทบาทตัวประสานงานและผู้เชี่ยวชาญหนักที่ต้องการความลึก — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — และงาน grunt บริบทยาวที่ประสิทธิภาพ sparse-MoE ของมันชนะใจ Mistral Medium 3.5 — ฟลากรวมที่เปิดตัวเมษายน 2026, 128B dense, 256K context, vision encoder ฝึกใหม่ทั้งหมด, MIT open weights, 77.6% SWE-Bench Verified — ทำงานในระดับปฏิบัติการจริง: Builder spawns, ผู้เชี่ยวชาญระดับกลาง (Architect, Verifier, Sequencer, Tutor, Reporter), อินพุตภาพ, และการเขียนยาว Mistral Small 4 ขยายจากบทบาทเดียวที่ intent gate มาจัดการแชทและการสั่งการสร้างภาพ — ราคา $0.15/$0.60 และความสามารถปรับแต่งเหตุผล ทำให้คุ้มค่าบนเส้นทางปริมาณสูงแต่ความลึกต่ำ Open weights ตั้งแต่ต้นจนจบ ไม่ออกจากโครงสร้างพื้นฐานของ EU เลยเลย Aurora ตั้งใจไม่เปลี่ยนเส้นทางไปยังโมเดลอื่นนอกเหนือจาก Mistral โดยอัตโนมัติเมื่อมีโมเดลไม่พร้อมใช้งาน; ตัวจัดเส้นทางจะแสดงข้อผิดพลาดแทน — นั่นคือสิ่งที่ทำให้มันคือ \"Aurora\" แทนที่จะเป็น Maestro รสชาติ Mistral","credits.overview#title":"เครดิต Ava — วิธีการคิดเงิน","credits.overview#0#p":"เครดิตคือวิธีที่ Ava นับการใช้งานของคุณ — เหมือนนาทีในแผนโทรศัพท์ ทุกแพ็กเกจ รวมถึงฟรี ก็มาพร้อมกับพูลเครดิต และทุกสิ่งที่ Ava ทำ (ตอบคำถาม สร้างภาพ) มีค่าใช้จ่ายเล็กน้อยจากเครดิตเหล่านั้น นั่นคือแนวคิดหลัก รายละเอียดด้านล่างมีไว้เมื่อคุณต้องการทราบค่าใช้จ่ายที่แน่นอน","credits.overview#1#p":"Ava คิดเงินเป็นเครดิต ไม่ใช่จำนวนโทเค็นดิบ (\"token\" คือชิ้นข้อความเล็กๆ — ประมาณไม่กี่ตัวอักษร — ที่โมเดล AI อ่านและเขียน; บริการส่วนใหญ่คิดเงินคุณตามโทเค็น ซึ่งคาดเดายาก) หนึ่งเครดิตครอบคลุมหนึ่งหน่วยงาน — การสนทนาหนึ่งรอบ, การเรียก Persona (ผู้ช่วยหนึ่งคนทำงานส่วนหนึ่งของงาน), หรือการสร้างภาพ การแยกจากระบบวัดผลตามโทเค็นหมายความว่า คุณไม่ต้องรู้ว่าโมเดลใดกำลังทำงานอยู่เพื่อรู้ว่าการกระทำนั้นจะมีค่าใช้จ่ายเท่าไร การสนทนาหนึ่งรอบมีค่าใช้จ่ายเท่ากัน ไม่ว่า Maestro จะส่งไปที่ Qwen 3.6 Plus หรือ Supernova ส่งไปที่ V4 Pro","credits.overview#2#h":"แพ็กเกจ","credits.overview#3#p":"ทุกแพ็กเกจเข้าถึงฟีเจอร์ได้ทุกอย่าง — เข้าถึงโมเดล, Creative Studio, โหมดทั้งเจ็ด, และการประสานงาน Persona เต็มรูปแบบ แพ็กเกจที่สูงขึ้นซื้อเครดิตเพิ่มและขีดจำกัดอัตราที่สูงขึ้น ไม่ใช่ฟีเจอร์ที่ถูกปลดล็อก","credits.overview#4#li0":"ฟรี — $0/เดือน. 300 เครดิต. อัตราจำกัด 20 คำขอ/นาที. ไม่ต้องใช้บัตร","credits.overview#4#li1":"Pro — $19/เดือน. 5,000 เครดิต. 60 คำขอ/นาที","credits.overview#4#li2":"Ultra — $39/เดือน. 10,000 เครดิต. 120 คำขอ/นาที","credits.overview#4#li3":"Enterprise — $79/เดือน. 20,000 เครดิต. 200 คำขอ/นาที","credits.overview#5#c":"เครดิตที่ไม่ได้ใช้จะถูกโอนต่อไปในขณะที่การสมัครสมาชิกยังคงใช้งานได้ — ไม่มีนโยบายยึดคืนบังคับ การเติมเครดิตจะซ้อนทับกับพูลการสมัครสมาชิก: 750 เครดิตสำหรับ $3, 2,000 สำหรับ $8, 4,000 สำหรับ $15","credits.overview#6#h":"รายการค่าใช้จ่าย","credits.overview#7#p":"ตารางค่าใช้จ่ายต่อการทำงาน — สิ่งที่ถูกหักออกจากพูลเครดิตของคุณเมื่อแต่ละการกระทำเกิดขึ้น (\"cache hit\" คือเมื่อ Ava นำงานที่เคยทำไปแล้วกลับมาใช้ใหม่แทนการทำซ้ำ; เมื่อเกิดสิ่งนี้คุณจ่ายน้อยลง — ค่าใช้จ่ายลดลง 70%, หรือ 50% สำหรับโมเดลที่ใช้เอาต์พุตหนักๆ เช่น DeepSeek V4 Pro)","credits.overview#8#li0":"การสนทนาหนึ่งรอบ — 2 เครดิต. การโต้ตอบครั้งเดียวในโหมดใดๆ","credits.overview#8#li1":"การเรียกเบา — 1 เครดิต. ประตูเจตนา, การจัดหมวดหมู่, การอ่านครั้งเดียว","credits.overview#8#li2":"Persona หนัก — 3 เครดิต. Architect, Researcher, CVE Researcher, Ideator (ความลึก ≥ 4)","credits.overview#8#li3":"Persona เบา — 1 เครดิต. Scout, Verifier, Sequencer, Challenger (ความลึก ≤ 2)","credits.overview#8#li4":"การประสานงาน — 10 เครดิต. เริ่มกระบวนการสร้างบุคลิกภาพเต็มรูปแบบ (Conductor + งานหลายบุคลิก)","credits.overview#8#li5":"การสร้างรูปภาพ — 12 เครดิต. Hailuo image-01 ผ่าน Creative Studio.","credits.overview#8#li6":"การสร้างวิดีโอ — 150 เครดิต. Hailuo 02 Pro 1080p คลิปความยาว 6 วินาที","credits.overview#8#li7":"การสร้างเสียงพูด — 10 เครดิต. Speech 2.8 HD synthesis.","credits.overview#8#li8":"การสร้างดนตรี — 50 เครดิต. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"การลบพื้นหลัง — 2 เครดิต.","credits.overview#9#h":"ตัวคูณตามแต่ละโมเดล","credits.overview#10#p":"ส่วนนี้ไว้สำหรับคนที่อยากรู้ลึกซึ้งนิดหน่อย — คุณไม่จำเป็นต้องเข้าใจมันเพื่อใช้งาน Ava ได้ปกติ ตัวคูณทำหน้าที่ปรับต้นทุนเครดิตขึ้นหรือลง ตามความแพงของโมเดลที่ใช้ทำภารกิจนั้นๆ โมเดลหนักๆ ก็อาจมีราคาสูงกว่าเล็กน้อย (\"กำไรสุทธิ\" คือส่วนที่โปรเจกต์เก็บไว้หลังจากหักค่าใช้จ่ายแล้ว — เราตั้งเป้าต่ำ เพื่อให้มูลค่าไหลกลับมาหาคุณ)","credits.overview#11#p":"โมเดลที่มีน้ำหนักมากกว่าจะคูณต้นทุนของการทำงาน เพื่อให้เครดิตสะท้อนการใช้จ่ายจริง แทนที่จะเป็นอัตราคงที่ ปรับเทียบให้เหลือกำไรสุทธิประมาณ 55%","credits.overview#12#li0":"0.6× — Mistral Small 4 (ตำแหน่งผู้เชี่ยวชาญของ Aurora). ต่ำกว่า 1× เนื่องจาก Mistral Small 4 มีราคาถูกกว่าตัวอ้างอิง Qwen 3.6 Plus","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. อัตราพื้นฐาน","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (ผู้ประสานงานของ Aurora). ประมาณเท่าตัวอ้างอิง Qwen 3.6 Plus","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (ผู้ประสานงานระดับมาสเตอร์).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (ผู้ประสานงานของ Supernova + ผู้เชี่ยวชาญหนัก) ปรับเทียบใหม่จาก 5.0× เพื่อคืนสมดุลกำไรที่อัตรา V4 Pro ที่ประกาศ","credits.overview#13#c":"โมเดลของ Anthropic (Claude Opus / Sonnet / Haiku) ไม่ต้องใช้เครดิตเลย — เป็นแบบ BYOK เท่านั้น และคุณจ่ายให้ Anthropic โดยตรง เช่นเดียวกันกับผู้ให้บริการ BYOK อื่นๆ เมื่อใช้คีย์ของคุณเอง","credits.overview#14#h":"BYOK และเครดิต","credits.overview#15#p":"BYOK (\"Bring Your Own Key\") — คุณนำบัญชีและคีย์ของตัวเองจากผู้ให้บริการ AI มาใช้ ซึ่งคีย์คือรหัสผ่านส่วนตัวที่อนุญาตให้ซอฟต์แวร์ใช้บัญชีที่ชำระเงินนั้นได้ สำหรับผู้ที่จ่ายให้ผู้ให้บริการ AI โดยตรงอยู่แล้ว หากคุณไม่ใช่กลุ่มนี้ คุณสามารถข้ามส่วนนี้ไปได้เลย","credits.overview#16#p":"คำขอ Bring-your-own-key จะข้ามโครงสร้างพื้นฐานของแพลตฟอร์มไปเลย — การเชื่อมต่อจะตรงจาก Ava ไปยังผู้ให้บริการ คุณจ่ายให้ผู้ให้บริการโดยตรง ไม่มีการตัดเครดิต เว้นแต่กรณีเดียวคือเมื่อเซสชัน BYOK สร้างบุคลิกภาพแบบจัดการ (managed-tier persona) สำหรับงานย่อย — การหักเครดิทยังคงเกิดขึ้นเพราะมีการใช้พื้นผิวการประสานงานของ Ava","credits.overview#17#h":"ตรวจสอบยอดคงเหลือได้ที่ไหน","credits.overview#18#li0":"ส่วนขยาย — การตั้งค่า → บัญชี, หรือปุ่มแสดงเครดิตในหัวข้อความแชท","credits.overview#18#li1":"IDE — หน้าจอรวมบัญชี (Account dashboard tile) แสดงยอดคงเหลือปัจจุบันและอัตราการใช้จ่าย","credits.overview#18#li2":"เว็บ — ava-supernova.com/dashboard แสดงยอดคงเหลือ ประวัติ และการต่ออายุ","credits.overview#19#c":"Local-first: Ava ทำงานได้โดยไม่ต้องมีบัญชีบนการ์ด Custom Model (Ollama, LM Studio, vLLM, หรือจุดเชื่อมต่อที่เข้ากันได้กับ OpenAI ใดๆ) ไม่มีเครดิต ไม่มีโทเคนของแพลตฟอร์ม — โมเดลของคุณ เครื่องของคุณ บิลเป็นศูนย์","concepts.modes#title":"โหมด — สภาวะการทำงานของ Ava","concepts.modes#0#p":"โหมดคือสถานะความคิดของ Ava — เหมือนเพื่อนร่วมงานที่เปลี่ยนหมวก คนเดิม ความทรงจำเกี่ยวกับคุณก็เหมือนเดิม แต่คนสร้างงานคิดต่างจากครู คุณเลือกโหมด แล้วมันจะเปลี่ยนวิธีที่เธอทำงานและทีมผู้ช่วยที่เธอเรียกมา สลับได้ตลอดเวลาด้วยตัวเลือกระบบโหมด หรือพิมพ์ชอร์ตคัตสองตัวอักษร","concepts.modes#2#h":"คุณต้องการแบบไหน?","concepts.modes#3#p":"เริ่มจากสิ่งที่กำลังจะทำ — โหมดจะตามมาจากนั้น:","concepts.modes#4#li0":"ฉันต้องการสร้างหรือแก้ไขอะไรบางอย่าง → โค้ด (>>). คุณอธิบาย เธอสร้างให้ โดยแสดงการเปลี่ยนแปลงให้คุณเห็นก่อน ทีมผู้ช่วยครบชุดจะทำงานเมื่อมีงานใหญ่","concepts.modes#4#li1":"ฉันต้องการแผนก่อนเริ่มทำอะไร → แผน (::). เธอคิดวางแผนแล้วส่งมาให้คุณอนุมัติหรือแก้ไข เธอจะไม่แตะต้องไฟล์ของคุณในโหมดนี้","concepts.modes#4#li2":"ฉันแค่อยากคุยหรือถามคำถาม → แชท (..). พาร์ทเนอร์คิดวิเคราะห์ที่มีหน่วยความจำ ข่าว และสภาพอากาศ ไม่มีการเปลี่ยนไฟล์ ไม่มีโค้ด — แค่บทสนทนา","concepts.modes#4#li3":"ฉันอยากเรียนรู้สิ่งใหม่ → สอน (??). หลักสูตรจริงที่สร้างสำหรับคุณ: บทเรียน แบบทดสอบ ครบถ้วน ฟรีทุกแพ็กเกจตลอดไป เหมาะมากถ้าคุณเพิ่งเริ่มต้น","concepts.modes#4#li4":"ฉันต้องการตรวจสอบช่องโหว่ด้านความปลอดภัยของโปรเจกต์ → ความปลอดภัย (!!). ทีมงานจะตรวจสอบรายการมาตรฐานของช่องโหว่เว็บทั่วไป (หมวดหมู่ \\\"OWASP\\\") และข้อบกพร่องที่รายงานไว้ (เรียกว่า \\\"CVEs\\\") แล้วส่งรายงานให้คุณเรียงตามความรุนแรงของปัญหา โหมดนี้เหมาะสำหรับนักพัฒนา — ถ้าไม่ใช่ก็ข้ามไปได้","concepts.modes#4#li5":"ฉันต้องการไอเดีย → ระดมสมอง (**). เธอสร้างตัวเลือกโดยอิงจากสถานการณ์จริงของคุณ เจาะจุดอ่อน และปรับปรุงส่วนที่เหลือให้เป็นขั้นตอนต่อไป","concepts.modes#4#li6":"ฉันต้องการเขียนเอกสาร → เขียน (<<). รายงาน ข้อเสนอจดหมาย บทความ — เธอร่างเป็น Markdown และส่งออกเอกสาร Word หรือ PDF ที่มีแบรนด์ ปรับแต่งทีละส่วน ไม่มีโค้ด มีแต่การเขียน","concepts.modes#5#c":"\"ทีมผู้ช่วย\" (บุคลิก) ทำงานเบื้องหลังทั้งหมด — คุณไม่ได้คุยกับพวกเขาโดยตรง คุณแค่ได้รับคำตอบที่ละเอียดขึ้น ไม่ต้องรู้ชื่อของพวกเขา","concepts.modes#6#c":"คุณสามารถสลับโหมดระหว่างสนทนาได้ ความทรงจำของคุณจะถูกเก็บไว้ ผู้เชี่ยวชาญจะรีเซ็ตให้เหมาะกับโหมดใหม่","concepts.tasks-journal#title":"งานและบันทึกประจำวัน","concepts.tasks-journal#0#p":"Ava เก็บโน้ตสามประเภทให้คุณ ซึ่งง่ายที่จะสับสน วิธีจำง่ายๆ: หน่วยความจำคือสิ่งที่เธอรู้เกี่ยวกับคุณ งานคือสิ่งที่คุณยังต้องทำ และบันทึกประจำวันคือไดอารี่ว่าเรื่องต่างๆ เป็นอย่างไร นี่คือเวลาที่ใช้แต่ละอย่าง","concepts.tasks-journal#1#li0":"หน่วยความจำ — ข้อเท็จจริงที่คงอยู่ ความชอบ การตัดสินใจ รูปแบบ ถามซ้ำๆ มักไม่ค่อยสร้างด้วยตนเอง","concepts.tasks-journal#1#li1":"งาน — สิ่งที่ต้องทำ รายการปฏิบัติการพร้อมกำหนดวันและสถานะ คุณติ๊กถูกเมื่อเสร็จ","concepts.tasks-journal#1#li2":"บันทึกประจำวัน — การสะท้อนคิด บันทึกประจำวัน คู่บันทึก (ของคุณและ Ava สังเกตการณ์เกี่ยวกับเซสชัน) มีประโยชน์สำหรับการติดตามอารมณ์ ทบทวนเซสชัน บริบทสำหรับวันพรุ่งนี้","concepts.tasks-journal#2#p":"Ava เขียนลงในทั้งสามอย่างเมื่อเหมาะสม คุณสามารถเขียนไปยังใดก็ได้โดยตรงจากแดชบอร์ด ไม่มีอะไรถูกจำกัดอยู่ที่เดียวที่คุณใช้ Ava — งานที่คุณสร้างในที่หนึ่ง (เช่น เครื่องมือบรรทัดคำสั่ง) จะปรากฏในทุกที่อื่น (เช่น แอปเดสก์ท็อป) อัตโนมัติ","concepts.permissions#title":"สิทธิ์อนุญาต — ปุ่มควบคุมความปลอดภัยของคุณ","concepts.permissions#0#p":"สิทธิ์อนุญาตคือปุ่มควบคุมความปลอดภัยของคุณ มันตัดสินว่าเมื่อไหร่ Ava จะขอความยินยอมก่อนทำบางสิ่งบนคอมพิวเตอร์ของคุณ แทนที่จะทำเลย คุณสามารถตั้งค่าให้เธอถามทุกอย่าง ถามเฉพาะเรื่องเสี่ยง หรือไว้วางใจให้เธอทำ — และคุณสามารถเปลี่ยนได้ตลอดเวลา ถ้าคุณไม่แน่ใจ ให้ทิ้งไว้ที่ค่าเริ่มต้นแล้วคุณจะปลอดภัย","concepts.permissions#1#p":"Ava มีเครื่องมือ 60 อย่าง (\"เครื่องมือ\" คือการกระทำที่เธอทำได้ — อ่านไฟล์ ค้นหาเว็บ ฯลฯ) ทุกเครื่องมืออยู่ในหมวดหมู่ (การดำเนินการไฟล์, shell, git, เว็บ, สื่อ, ฐานข้อมูล, ระบบ, เอกสาร, หน่วยความจำ, การเรียนรู้) ทุกคำสั่งเครื่องมือจะผ่านประตูสิทธิ์ (จุดตรวจสอบที่ตัดสินว่าจะถามคุณก่อนหรือไม่) ก่อนรัน คุณควบคุมว่าอะไรได้รับการอนุมัติอัตโนมัติ อะไรถามครั้งเดียว และอะไรถามเสมอ","concepts.permissions#3#p":"สมดุลเป็นค่าเริ่มต้น เข้มงวดเมื่อคุณกำลังตรวจสอบพฤติกรรมของเธอ (ดูใกล้ๆ เพื่อตรวจสอบแต่ละขั้นตอน) อัตโนมัติเมื่อคุณอยากให้เธอทำไปเลย","concepts.permissions#4#c":"อัตโนมัติไม่ได้หมายความว่าไม่มีตรวจสอบ แผน คำถามชี้แจง และคำขอผู้ใช้ชัดเจนยังคงหยุดรอการป้อนข้อมูลของคุณ การดำเนินการที่ไม่สามารถย้อนกลับได้ (git force-push, database drops) ยืนยันเสมอไม่ว่าจะเป็นโหมดไหน","concepts.interjection#title":"การนำทางและการหยุด Ava","concepts.interjection#0#p":"คุณเป็นผู้รับผิดชอบเสมอ ในขณะที่ Ava กำลังทำงาน คุณสามารถปรับทิศทางเบาๆ ใหม่โดยไม่ขัดจังหวะ หรือหยุดเธอทันที สองปุ่ม สองผลลัพธ์ — นั่นคือทั้งหมดของหน้านี้","concepts.interjection#1#p":"Ava จะทำงานต่อจนกว่าแผนจะสำเร็จ หรือจนกว่าคุณจะสั่งหยุด คุณสามารถแทรกแซงได้สองวิธีระหว่างที่เธอกำลังทำงานอยู่ (คำว่า \"intervene\" ในที่นี้หมายถึงการแทรกแซง)","concepts.interjection#2#h":"Interject — นำทางโดยไม่ยกเลิก","concepts.interjection#3#p":"พิมพ์ข้อความใหม่ขณะที่ Ava กำลังทำงาน เธอจะทำงานคำสั่งปัจจุบันให้เสร็จสิ้น อ่านข้อความของคุณ แล้วปรับแผนให้เหมาะสม ไม่สูญเสียบริบทใดๆ ไปเลย ใช้วิธีนี้เมื่อต้องการเปลี่ยนทิศทาง เพิ่มข้อมูล หรือปรับลำดับความสำคัญระหว่างที่กำลังดำเนินการ","concepts.interjection#4#h":"Hard-stop — ยกเลิกและล้างผล","concepts.interjection#5#p":"กดปุ่ม Escape (CLI), คลิก Stop (extension, IDE), หรือพิมพ์คำสั่งหยุด การรันปัจจุบันจะถูกยกเลิก คำสั่งเครื่องมือที่ยังค้างอยู่จะถูกตัดทิ้ง และบทสนทนาพร้อมสำหรับการเริ่มรอบใหม่","concepts.interjection#6#c":"ลอง Interject ก่อน ส่วน Hard-stop ใช้เมื่อเกิดปัญหาจริงๆ การ Interject ช่วยรักษาความต่อเนื่องของบทสนทนาไว้","concepts.desktop-personas#title":"บทบาทบนเดสก์ท็อป","concepts.desktop-personas#0#p":"หน้านี้เหมาะสำหรับผู้ที่อยากรู้อยากเห็นและผู้ใช้ขั้นสูง \"Desktop automation\" (หรือบางครั้งเรียกว่า \"computer use\") หมายถึง Ava สามารถคลิกบนหน้าจอและใช้แอปพลิเคชันแทนคุณได้จริง ๆ — เปิด Gmail กรอกแบบฟอร์ม ส่งข้อความ — เหมือนคนนั่งอยู่ที่คีย์บอร์ด เพื่อให้ปลอดภัย เธอจึงแบ่งงานออกเป็นผู้ช่วยเล็กๆ 5 คน แต่ละคนมีบทบาทเฉพาะเจาะจงเพียงอย่างเดียว คุณไม่ต้องจัดการกับพวกเขาโดยตรง หน้านี้แค่แสดงให้คุณเห็นว่าใครทำอะไรบ้าง","concepts.desktop-personas#1#p":"ทุกขั้นตอนในเส้นทางบนเดสก์ท็อป (หนึ่งรอบการทำงานของ Ava ที่ขับเคลื่อนหน้าจอของคุณไปสู่เป้าหมาย) จะมีการเรียกใช้คลื่นบทบาททั้งห้า แต่ละบทบาทมีงานเดียวเท่านั้น การแยกหน้าที่ช่วยให้คำสั่งกระชับ ผลลัพธ์เป็นโครงสร้าง และการคิดวิเคราะห์มีความระมัดระวังตามการออกแบบ","concepts.desktop-personas#2#h":"Scout","concepts.desktop-personas#3#p":"รายงานสิ่งที่ปรากฏบนหน้าจอในปัจจุบัน ไม่สร้างองค์ประกอบขึ้นมาเอง ไม่วางแผน คืนค่า ScreenState JSON พร้อม ID ขององค์ประกอบ ชื่อ bboxes ความมั่นใจ และแหล่งที่มาของการยืนยัน (UIA, Playwright DOM, หรือ OmniParser vision)","concepts.desktop-personas#4#h":"Planner","concepts.desktop-personas#5#p":"ตัดสินใจการกระทำถัดไปเพียงครั้งเดียว ทำทีละขั้นตอน — ไม่ทำรวมกัน ชอบเส้นทางที่สามารถย้อนกลับได้ จำแนกความเสี่ยงตาม safety ontology เอาต์พุตเป็น ProposedAction JSON พร้อม kind, target, params, riskClass, reasoning และการทำนาย expectedPostState","concepts.desktop-personas#6#h":"Actor","concepts.desktop-personas#7#p":"ดำเนินการตามที่ Planner เสนอมาอย่างแม่นยำ — หลังจากผ่านประตูอนุมัติแล้ว ไม่มีการแก้ไขเอง ไม่มีการลองซ้ำ รายงานความล้มเหลวอย่างตรงไปตรงมา และ Verifier จะจัดการการเคลื่อนไหวถัดไป","concepts.desktop-personas#8#h":"Verifier","concepts.desktop-personas#9#p":"ตรวจสอบว่าการกระทำนั้นสำเร็จหรือไม่ เปรียบเทียบ ScreenState ใหม่กับการทำนายของ Planner คืนค่า verified, deviated, หรือ rollback_needed นอกจากนี้ยังตรวจสอบการวนซ้ำ — การทำซ้ำการกระทำที่เคยสำเร็จแล้วถือเป็นความเบี่ยงเบน ไม่ใช่การยืนยัน","concepts.desktop-personas#10#h":"Narrator","concepts.desktop-personas#11#p":"เป็นเสียงเดียวที่ผู้ใช้ได้ยินระหว่างการทำงานแต่ละขั้นตอน ประโยคอดีตหนึ่งประโยคต่อขั้นตอน (\"Opened Gmail.\", \"Clicked Compose.\") เขียนบันทึกการตรวจสอบแบบมีโครงสร้าง บอกเมื่อมีปัญหาเกิดขึ้น — ไม่เคยปิดบังปัญหา","concepts.desktop-safety#title":"ระบบความปลอดภัยบนเดสก์ท็อป","concepts.desktop-safety#0#p":"สั้นๆ คือ: ก่อนที่ Ava จะคลิกอะไรบนหน้าจอ เธอจะจัดหมวดหมู่การกระทำตามระดับความเสี่ยง การอ่านหน้าจอ? ไม่เป็นอันตราย การโอนเงินหรือลบไฟล์? เธอจะหยุดและถามคุณก่อนเสมอ — ทุกครั้ง ไม่มีข้อยกเว้น ฉลากทั้งห้าด้านล่างคือบันไดขั้นบันไดความเสี่ยง นี่คือรายละเอียดสำหรับผู้ใช้ขั้นสูง แต่ใจความสำคัญคือ: สิ่งที่เป็นอันตรายต้องได้รับอนุญาตจากคุณเสมอ","concepts.desktop-safety#1#p":"การกระทำที่ถูกเสนอจะถูกจัดอยู่ในหนึ่งในห้าชั้นความเสี่ยง การจำแนกประเภทผสมผสานสามสัญญาณ — เป้าหมายบนหน้าจอคืออะไร คำอธิบายภาษาธรรมดา (\"semantic caption\" — คำพูดของ Ava เกี่ยวกับสิ่งที่เธอกำลังมองอยู่) และการตั้งค่าของการกระทำ — และยกระดับขึ้น (ถือว่าเสี่ยงมากขึ้น) เมื่อสิ่งเหล่านี้ขัดแย้งกัน False positive (ถามทั้งที่ไม่จำเป็นต้องถาม) ก็แค่รำคาญเล็กน้อย False negative (ไม่ถามทั้งที่ควรถาม) คือเหตุการณ์ร้ายแรงที่อาจทำให้ผลิตภัณฑ์ต้องหยุดให้บริการ","concepts.desktop-safety#2#h":"ห้าชั้นความเสี่ยง","concepts.desktop-safety#3#li0":"Observational — อ่านต้นไม้ UIA, ภาพหน้าจอ, ลอยเมาส์ อนุญาตอัตโนมัติเสมอ","concepts.desktop-safety#3#li1":"Navigational — เลื่อน, ย้ายโฟกัส, เปิดเมนู อนุญาตอัตโนมัติในโหมด Drive","concepts.desktop-safety#3#li2":"การกระทำที่เปลี่ยนแปลงได้และสามารถย้อนกลับได้ — พิมพ์ลงในช่อง วางข้อความ เปิดแอป หรือนำทางไปยัง URL ยืนยันในโหมด Ask; ทำงานอัตโนมัติใน Drive ภายในรายการอนุญาต","concepts.desktop-safety#3#li3":"การกระทำที่เปลี่ยนแปลงได้แต่ไม่สามารถย้อนกลับได้ — ส่ง ส่งคำขอ จ่าย ลบ ยืนยัน เผยแพร่ ยืนยันเสมอ ไม่ว่าระดับสิทธิ์จะเป็นอย่างไร การอนุมัติจะไม่ถูกบันทึกแคช","concepts.desktop-safety#3#li4":"สิทธิ์พิเศษ — การยกระดับ UAC, sudo, แก้ไข registry, หน้าต่างขอข้อมูลรับรอง ห้ามใช้โดยค่าเริ่มต้น ต้องเลือกใช้งานครั้งเดียวต่อเซสชัน","concepts.desktop-safety#4#h":"การอนุมัติที่ไม่ถูกบันทึกแคช","concepts.desktop-safety#5#p":"คู่แข่งทุกรายมักบันทึกการอนุมัติ (จำคำตอบ \"yes\" ของคุณเพื่อนำไปใช้ซ้ำครั้งหน้า) นี่คือช่องทางหลักของการโจมตีแบบ Prompt Injection — การโจมตีที่เว็บเพจที่มีกับดักแอบแฝงคำสั่งลับเข้าไปใน AI ให้มันทำงานขัดแย้งกับคุณ หากมีการบันทึกการอนุมัติ เว็บที่ถูกบุกรุกก็สามารถอาศัย \"yes\" ที่คุณเคยตอบไว้ได้ Ava ไม่เคยบันทึกแคช ทุกการกระทำที่เปลี่ยนแปลงแล้วไม่อาจย้อนกลับได้จะถามยืนยันใหม่เสมอ","concepts.desktop-safety#6#h":"การจัดการรหัสลับ","concepts.desktop-safety#7#p":"รหัสผ่าน, คีย์ API และรหัส 2FA (รหัสครั้งเดียวที่แอปอื่นหรือข้อความส่งมาให้ตอนล็อกอิน) จะถูกจัดการผ่านตัวระบุแบบปิดบัง — ตัวแทนชั่วคราวที่แทนค่าจริง Ava จะเห็นแค่ \"{secret}\" ไม่ใช่รหัสผ่านจริง ค่าจริงไม่เคยเข้าหน่วยความจำ บันทึกกิจกรรม หรือสิ่งที่เธอ \"อ่าน\" — มีชั้นการทำงานระดับต่ำแยกต่างหากที่จะพิมพ์ค่านี้ในวินาทีสุดท้าย เมื่อกดแป้นพิมพ์ ดังนั้นส่วน AI จึงไม่เคยสัมผัสข้อมูลนั้น","reference.cli#title":"คำสั่ง CLI","reference.cli#0#p":"หน้านี้มีไว้สำหรับ CLI — เวอร์ชันของ Ava ที่คุณพิมพ์สั่งงานในหน้าต่างเทอร์มินัล แทนการใช้คลิกปุ่ม หากคุณใช้ส่วนขยายหรือแอปบนเดสก์ท็อป คุณสามารถข้ามหน้านี้ไปได้เลย ส่วนนี้มีไว้สำหรับผู้ที่ชอบใช้คีย์บอร์ด","reference.cli#1#p":"CLI คือระบบ REPL — หน้าจอคำสั่งที่รอให้คุณพิมพ์ รันสิ่งที่พิมพ์ แล้วรอรับคำสั่งใหม่ คำสั่งแบบสแลช (คำสั่งที่ขึ้นต้นด้วย \"/\") สามารถใช้งานได้จากหน้าจอคำสั่งนี้","reference.cli#2#li0":"/help — แสดงรายการคำสั่งและโหมดปัจจุบัน","reference.cli#2#li1":"/mode <name> — สลับโหมด (งาน เขียน แผน แชท สอน ความปลอดภัย ระดมสมอง)","reference.cli#2#li2":"/model <id> — สลับโมเดลโดยไม่ต้องออกจากเซสชัน","reference.cli#2#li3":"/clear — ล้างบทสนทนาปัจจุบัน หน่วยความจำไม่ถูกลบ","reference.cli#2#li4":"/history — แสดงประวัติบทสนทนาในโปรเจกต์นี้","reference.cli#2#li5":"/memory — เปิดเบราว์เซอร์หน่วยความจำ","reference.cli#2#li6":"/tasks — แสดงและจัดการงาน","reference.cli#2#li7":"/journal — เปิดบันทึกประจำวันวันนี้","reference.cli#2#li8":"/settings — เปิดเมนูตั้งค่า","reference.cli#2#li9":"/exit — ออกจาก REPL","reference.cli#3#h":"ตัวเลือกการเปิดโปรแกรม","reference.cli#4#p":"แฟล็กเป็นตัวเลือกเสริมที่คุณเพิ่มตอนเริ่มใช้งาน Ava แต่ละตัวจะขึ้นต้นด้วย \"--\" เพื่อตั้งค่าวิธีการเปิดโปรแกรม","reference.cli#5#li0":"--mode <name> — เริ่มในโหมดที่กำหนด","reference.cli#5#li1":"--model <id> — เริ่มด้วยโมเดลที่กำหนด","reference.cli#5#li2":"--permission <mode> — เข้มงวด / สมดุล / อัตโนมัติ","reference.cli#5#li3":"--project <path> — กำหนดรากโปรเจกต์อย่างชัดเจน","reference.desktop-budget#title":"ขีดจำกัดงบประมาณบนเดสก์ท็อป","reference.desktop-budget#0#p":"เมื่อ Ava ควบคุมเดสก์ท็อปของคุณแทนคุณ ไม่ว่าจะเป็นการคลิก พิมพ์ หรือเปิดแอป แต่ละครั้งที่เราเรียกการทำงานนี้ว่า \"trajectory\" หน้าหน้านี้จะอธิบายขอบเขตความปลอดภัยที่กำหนดไว้ เพื่อไม่ให้การรันใดๆ ยาวนานเกินไปหรือเสียค่าใช้จ่ายมากเกินไป สรุปสั้นๆ คือ เธอจะหยุดและทบทวนก่อนทำเกินกำหนด ตัวเลขรายละเอียดมีอยู่ตรงนี้หากคุณต้องการทราบ","reference.desktop-budget#1#p":"ทุก trajectory จะทำงานภายใต้ขีดจำกัดสูงสุดสามแบบพร้อมกัน (hard limits) ขีดจำกัดใดถูกแตะก่อนจะเป็นตัวตัดสิน trajectory จะไม่ดำเนินการต่อเงียบๆ เมื่อมีการละเมิด — Narrator (ผู้ช่วยที่คอยบอกเล่าสิ่งที่กำลังเกิดขึ้น) จะหยุดและถามว่าคุณต้องการทำอะไรต่อ","reference.desktop-budget#2#h":"ขีดจำกัดสูงสุดสามแบบ (ค่าเริ่มต้น)","reference.desktop-budget#3#li0":"จำนวนขั้นตอน — 30 ขั้นตอน","reference.desktop-budget#3#li1":"งบประมาณโทเค็น — 500,000 โทเค็น","reference.desktop-budget#3#li2":"เวลาจริง — 5 นาที","reference.desktop-budget#4#h":"ระดับค่าใช้จ่ายของงาน","reference.desktop-budget#5#li0":"ง่าย (ค้นหาเอกสาร เปิดหน้าเว็บ) — 5–10 ขั้นตอน, ~70–135K โทเค็น, ~$0.04–0.08","reference.desktop-budget#5#li1":"ปานกลาง (ล็อกอิน ตรวจสอบบันทึก ดาวน์โหลดผลลัพธ์) — 15–25 ขั้นตอน, ~205–340K โทเค็น, ~$0.12–0.21","reference.desktop-budget#5#li2":"ซับซ้อน (จัดการ GitHub issues สามรายการ) — 25–30 ขั้นตอน, ~340–410K โทเค็น, ~$0.21–0.25","reference.desktop-budget#6#p":"ตัวเลขโทเค็นด้านบนเป็นขีดจำกัดทางเทคนิคต่อการรันแต่ละครั้ง ไม่ใช่โควตาประจำเดือนของคุณ — ซึ่งนับรวมในเครดิต และแพ็กเกจฟรีที่มี 300 ต่อเดือนก็ครอบคลุมการใช้งานแชท เขียนโค้ด และการออโตเมชันได้สบายๆ","reference.desktop-budget#7#c":"คุณสามารถปรับขีดจำกัดสำหรับแต่ละงานได้ที่จุดเริ่มต้น แต่หากมีการเกินขีดจำกัด จะแสดงจุดตัดสินใจเสมอ งบประมาณจะไม่ถูกใช้ไปโดยไม่รู้ตัว","reference.desktop-whitelist#title":"รายการอนุญาตสำหรับเซสชันบนเดสก์ท็อป","reference.desktop-whitelist#0#p":"\"Whitelist\" คือรายการแอปและเว็บไซต์ที่คุณบอกว่า Ava สามารถเข้าถึงได้ขณะควบคุมเดสก์ท็อปของเธอ หน้าหน้านี้จะอธิบายวิธีให้สิทธิ์นั้นและทำไมมันจึงรีเซ็ตทุกครั้ง เวอร์ชันสั้นๆ คือ เธอสามารถทำได้เฉพาะที่คุณอนุญาต และเธอจะถามก่อนเข้าที่ใหม่","reference.desktop-whitelist#1#p":"ตอนเริ่มเซสชันบนเดสก์ท็อป Ava จะถามว่าเธอสามารถทำงานที่ไหนได้บ้าง ใช้ภาษาธรรมดาได้ เช่น \"Gmail, Cursor, the Azure portal.\" เธอจะอ่านข้อความนั้นและยืนยันกลับกับคุณว่าตรงกัน (\"Gmail เว็บ, Cursor แอป, portal.azure.com\")","reference.desktop-whitelist#2#h":"วิธีการบังคับใช้","reference.desktop-whitelist#3#p":"การกระทำแบบดูอย่างเดียว — ถ่ายภาพหน้าจอ อ่านรายการปุ่มและฟิลด์บนหน้าจอ (\"UIA tree\", แผนที่ของ Windows ว่ามีอะไรอยู่ในหน้าต่าง) — อนุญาตได้ทุกที่ เพราะคุณจำเป็นต้องเห็นสิ่งที่มีบนหน้าจอเพื่อตัดสินใจว่าจะเพิ่มแอปลงในรายการอนุญาตหรือไม่ ทุกอย่างที่มีการเปลี่ยนแปลงจะถูกบล็อกนอกจากรายชื่อ; Ava จะหยุดและถามว่าจะเพิ่มหรือไม่","reference.desktop-whitelist#4#h":"จำกัดเฉพาะเซสชัน โดยตั้งใจ","reference.desktop-whitelist#5#p":"รายการอนุญาตไม่ได้คงอยู่ข้ามเซสชัน ไม่มีตัวเลือก \"จำแอปนี้ไว้\" trajectory ใหม่ทุกอันจะเริ่มด้วยขอบเขตใหม่ ออกแบบมาให้ต้องยืนยันใหม่ — การลืมที่จะอนุญาตซ้ำถือเป็นฟีเจอร์ ไม่ใช่บั๊ก","reference.desktop-whitelist#6#h":"การเพิ่มระหว่าง trajectory","reference.desktop-whitelist#7#p":"ระหว่าง trajectory คุณสามารถเพิ่มแอปจากแถบหัวเรื่อง: \"+ Allow app\" จะเปิดช่องกรอกข้อมูลเล็กๆ กด Add แล้วแอปใหม่จะมีผลตลอดช่วงที่เหลือของเซสชัน","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"อยากสร้างรูปภาพ วิดีโอสั้น เพลง หรือเสียงพากย์? แค่บรรยายมา Ava จะทำให้คุณ — ไม่ต้องใช้ซอฟต์แวร์ออกแบบหรือเสียงเลย","features.creative-studio#1#p":"สร้างรูปภาพ วิดีโอ เพลง และเสียง — รวมอยู่ในเวิร์กโฟลว์เดียวกับโค้ดของคุณ สร้างไอคอน ภาพจำลองผลิตภัณฑ์ วิดีโอสาธิต หรือพากย์เสียงสำหรับบทเรียน ขับเคลื่อนด้วย MiniMax.","features.creative-studio#2#h":"สิ่งที่คุณสร้างได้","features.creative-studio#3#li0":"รูปภาพ — จากข้อความเป็น PNG/JPG ลบพื้นหลังทำได้แค่คำสั่งเดียว","features.creative-studio#3#li1":"วิดีโอ — คลิปสั้น AI จากข้อความ (MiniMax Hailuo)","features.creative-studio#3#li2":"เพลง — ดนตรีบรรเลงหรือร้องพร้อมเนื้อเพลง","features.creative-studio#3#li3":"เสียง — แปลงข้อความเป็นเสียงพูด เลือกเสียงได้","features.creative-studio#4#p":"ค่าใช้จ่ายของ Creative Studio ใช้จากแหล่งเครดิตเดียวกันกับทุกอย่างอื่น — แหล่งเดียว ตัวเลขเดียว BYOK คีย์ MiniMax ของคุณเอง แล้วใช้ได้ฟรีตามแพ็กเกจของคุณ","features.creative-studio#5#c":"Creative Studio เข้าถึงได้ฟรีในแพ็กเกจเริ่มต้น ไม่ใช่ส่วนเสริมที่ต้องจ่ายเงินเพิ่ม","features.desktop-automation#title":"การทำงานอัตโนมัติบนเดสก์ท็อป","features.desktop-automation#0#p":"พูดง่ายๆ คือ Ava สามารถควบคุมเมาส์และคีย์บอร์ดของคุณเพื่อทำงานแทนคุณได้ — เปิดแอป คลิกปุ่ม กรอกแบบฟอร์ม — ในขณะที่คุณดูและอนุมัติสิ่งสำคัญต่างๆ","features.desktop-automation#1#p":"โหมดใหม่สำหรับ Ava ขึ้นต้นด้วย @@ เธอจะสังเกตหน้าจอเดสก์ท็อป ตัดสินใจทำอะไร และขับเคลื่อนการทำงานอัตโนมัติบน UI (ควบคุมแอปบนหน้าจอให้คุณ) ให้สำเร็จ รันบนเครื่องจริงของคุณด้วยข้อมูลรับรองจริงของคุณ — ไม่ใช่เบราว์เซอร์บนคลาวด์ จะเปิดให้ทุกแพ็กเกจเมื่อเปิดตัว","features.desktop-automation#2#h":"ทำไมต้องมีอีกตัว?","features.desktop-automation#3#p":"ผลิตภัณฑ์ทำอัตโนมัติบนเดสก์ท็อปอื่นๆ มักเริ่มใช้งานตอนคุณนั่งที่โต๊ะ แต่ Ava ยังคงอยู่เมื่อตัวติดตามข้อผิดพลาดแจ้งเตือนตอนตีสอง — IDE ยังทำงานต่อ โทรศัพท์เชื่อมต่อกันผ่านช่องทางปลอดภัย คุณอนุมัติสิ่งที่แก้ไขไม่ได้ด้วยการแตะเพียงครั้งเดียว","features.desktop-automation#4#p":"เธอยังจำวิธีนำทางแอปของคุณข้ามเซสชันได้ ตัวเอเจนต์อื่นๆ ต้องเรียนรู้ใหม่ทุกครั้ง ความแตกต่างเรื่องความทรงจำนี้จะยิ่งมีค่ามากขึ้นเรื่อยๆ เมื่อใช้งาน","features.desktop-automation#5#h":"ทำงานอย่างไร","features.desktop-automation#6#p":"แต่ละขั้นตอนจะเรียกใช้คลื่นบทบาท 5 แบบ: Scout สังเกตการณ์, Planner เลือกการกระทำถัดไป, Actor ดำเนินการ, Verifier ตรวจสอบ, Narrator บอกเล่าสิ่งที่เกิดขึ้น sidecar จะเลือกวิธีการรองรับที่คุ้มค่าและน่าเชื่อถือที่สุด — UIA สำหรับแอปเนทีฟ, Playwright สำหรับเบราว์เซอร์, OmniParser vision เมื่อไม่มีอะไรอื่นที่มีโครงสร้างต้นไม้ที่เป็นประโยชน์","features.desktop-automation#7#p":"ดูหน้าแนวคิดเพื่อดูหลักความปลอดภัย ลำดับชั้นการยึดโยง สวิตช์ตัดการทำงาน และโมเดลรายการอนุญาตของเซสชัน","start.first-model#deeper#0#h":"แต่ละสไตล์มีอะไรบ้าง","start.first-model#deeper#1#p":"Maestro — ผู้ควบคุมวงหนึ่งคน (Qwen 3.6 Plus) ดูแลทุกขั้นตอน ปรับแต่งมาเพื่อใช้งานจริง เชื่อถือได้ และต้นทุนคาดการณ์ได้","start.first-model#deeper#2#p":"Supernova — ผู้ประสานงานแถวหน้า (DeepSeek V4 Pro, พารามิเตอร์ 1.6T / ใช้งานจริง 49B, บริบท 1M) มอบงานย่อยให้ผู้เชี่ยวชาญเฉพาะด้าน: V4 Flash สำหรับงานสร้างปริมาณมาก, Qwen 3.6 Plus เป็นตัวสำรอง, Qwen Omni สำหรับงานภาพ","start.first-model#deeper#3#p":"Aurora — ใช้เฉพาะ Mistral ในสามระดับ: Mistral Large 3 (ผู้ประสานงาน + ผู้เชี่ยวชาญหนัก), Mistral Medium 3.5 (128B แบบหนาแน่น, บริบท 256K, งานภาพเนทีฟ, น้ำหนักโมเดลเปิดแบบดัดแปลง MIT, ยืนยัน SWE-Bench 77.6%) สำหรับผู้สร้าง + ระดับกลาง + งานภาพ + เนื้อหายาว, และ Mistral Small 4 ที่จุดกรองเจตนา น้ำหนักโมเดลเปิดตลอดกระบวนการ ไม่ออกนอกโครงสร้างพื้นฐานในสหภาพยุโรป","start.first-model#deeper#4#h":"ใช้โมเดลของคุณเอง (BYOK)","start.first-model#deeper#5#p":"ชอบใช้บัญชี AI ของคุณเองไหม? วางคีย์ผู้ให้บริการของคุณในการตั้งค่า แล้วคุณจะได้ทั้งสองอย่าง — สไตล์การกำหนดเส้นทางทั้งสาม พร้อมตัวเลือกเลือกโมเดลเดียวและข้ามการกำหนดเส้นทางไปเลย มีประโยชน์สำหรับความชอบที่ชัดเจน งบประมาณที่จำกัด หรือทดสอบโมเดลเฉพาะ รายการผู้ให้บริการเต็มรูปแบบอยู่ในส่วนอ้างอิง","start.glossary#title":"คำศัพท์ภาษาธรรมดา","start.glossary#0#p":"ทุกคำที่คุณอาจเจอเกี่ยวกับ Ava อธิบายไว้โดยไม่ต้องมีความรู้เดิมมาก่อน คุณไม่ต้องจำทั้งหมดนี้หรอก — เปิดกลับมาดูเมื่อไหร่ก็ได้ที่เจอคำศัพท์ยากๆ","start.glossary#1#th0":"คำ","start.glossary#1#th1":"ความหมายที่แท้จริง","start.glossary#1#td0.0":"เอเจนต์","start.glossary#1#td0.1":"AI ที่สามารถดำเนินการแทนคุณได้ — อ่านไฟล์ รันคำสั่ง ค้นหาเว็บ — ไม่ใช่แค่แชท Ava เป็นเอเจนต์: เธอทำสิ่งต่างๆ ด้วยอนุญาตจากคุณ","start.glossary#1#td1.0":"โมเดล","start.glossary#1#td1.1":"สมอง AI จริงๆ ที่กำลังคิด (Qwen, DeepSeek, Mistral และอื่นๆ) โมเดลต่างกันมีจุดแข็งต่างกัน ปกติคุณไม่ต้องเลือกเอง — Ava ทำให้","start.glossary#1#td2.0":"โหมด","start.glossary#1#td2.1":"ความคิดของ Ava ในขณะนั้น เหมือนเพื่อนร่วมงานเปลี่ยนหมวก: ผู้สร้าง, นักเขียน, ครู, ผู้วางแผน, เพื่อน คุณเลือกโหมด; มันเปลี่ยนวิธีที่เธอปฏิบัติ มีเจ็ดโหมด","start.glossary#1#td3.0":"บุคลิกภาพ / ผู้เชี่ยวชาญ","start.glossary#1#td3.1":"บทบาทผู้ช่วยที่ Ava ทำงานเบื้องหลังสำหรับงานยาก — นักสำรวจ, ผู้วางแผน, ผู้ตรวจสอบข้อเท็จจริง คิดเป็นทีมผู้เชี่ยวชาญเล็กๆ คุณไม่เคยคุยกับพวกเขาโดยตรง; Ava เป็นผู้ประสานงาน","start.glossary#1#td4.0":"การกำหนดเส้นทาง","start.glossary#1#td4.1":"Ava ตัดสินใจว่าจะใช้โมเดลใดในแต่ละขั้นตอน เพื่อให้คุณได้คำตอบที่ดีโดยไม่เสียเงินเกินจำเป็น เกิดขึ้นอัตโนมัติ — \"โหมดการกำหนดเส้นทาง\" เลือกกลยุทธ์โดยรวม","start.glossary#1#td5.0":"เครื่องมือ","start.glossary#1#td5.1":"การกระทำเฉพาะที่ Ava สามารถทำได้ — อ่านไฟล์ ค้นหา ส่งอีเมล การ \"เรียกใช้เครื่องมือ\" คือการใช้หนึ่งในนั้น เธอขอความยินยอมก่อนทุกอย่างที่มีความเสี่ยง","start.glossary#1#td6.0":"โทเค็น","start.glossary#1#td6.1":"วิธีที่ AI วัดข้อความ — ประมาณ ¾ ของคำ โมเดลคิดราคาต่อล้านโทเค็น ส่วนใหญ่เป็นสิ่งที่คุณสามารถเพิกเฉยได้","start.glossary#1#td7.0":"เครดิต"},"tr":{"start.for-non-coders#title":"Hiç kod yazmadınız mı? Buradan başlayın","start.for-non-coders#0#p":"Daha önce hiç kod satırı yazmadıysanız, tam da Ava'nın hedef kitlesi sizsiniz. Başlamak için herhangi bir jargon öğrenmenize gerek yok — bilge bir arkadaşınıza sorduğunuz gibi sade bir dille konuşursunuz. Bu sayfa sizin tüm giriş kapınız.","start.for-non-coders#1#h":"Deneyiminiz olmadan bugün neler yapabilirsiniz","start.for-non-coders#2#li0":"Normal kelimelerle her şeyi sorun — \"bu dosya ne işe yarar?\", \"sayfam neden boş?\", \"veritabanı nedir zaten?\" Normal dilde cevaplar ve konuşmayı hatırlar.","start.for-non-coders#2#li1":"Sıfırdan bir şeyler öğrenin — \"sıfırdan bana Python öğret\" deyin ve size derslerle ve sınavlarla doğru bir kurs hazırlasın. Bu her zaman ücretsizdir.","start.for-non-coders#2#li2":"Bir şey yaptırın — ne istediğinizi tarif edin (\"notlarımı indiren bir düğme\") ve her değişimi gerçekleşmeden önce göstererek yazsın.","start.for-non-coders#3#h":"Her şeyi anlamanıza gerek yok","start.for-non-coders#4#p":"Ava'nın motorun altında çok fazla mekanizma var — modlar, modeller, uzmanlar, yönlendirme. Uygulamada ve bu dokümantasyonda bu kelimeleri göreceksiniz. İşte sır: bunların neredeyse tamamını görmezden gelebilirsiniz. Ava sizin için doğru araçları ve yardımcıları otomatik seçer. Teknik sayfalar merak ettiğinizde oradadır, başlaması için değil.","start.for-non-coders#5#h":"Nazik bir ilk yol","start.for-non-coders#6#li0":"Ava'yı yükleyin (sonraki sayfa) ve sohbeti açın.","start.for-non-coders#6#li1":"Gerçekten aklınızda olan bir soru yazın. Herhangi bir şey. Nasıl cevap verdiğine bakın.","start.for-non-coders#6#li2":"Öğrenme modunu deneyin: \"teach me\" ve bir konu yazın. Peşinden gelin.","start.for-non-coders#6#li3":"Bir şeyi gerçekten yapmasını veya değiştirmesini istediğinizde sadece söyleyin; o da ne yapacağını size her zaman gösterir ve \"evet\" demenizi bekler.","start.for-non-coders#7#c":"Tanımadığınız bir kelimeye mi takıldınız? Bu bölümün biraz aşağısındaki Basit Anlam Sözlüğü, herhangi bir ön bilgi varsaymadan her terimi açıklar.","start.install#title":"Kurulum","start.install#0#p":"Nasıl çalıştığınıza uyan arayüzü seçin. Birden fazlasını kullanabilirsiniz; Ava, giriş yaptığınızda hafızasını tüm bunlar arasında senkronize eder.","start.install#1#h":"VS Code eklentisi","start.install#2#li0":"VS Code'da Eklentiler panelini açın (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"\"Ava Supernova\" için arama yapın ve Yükle'ye tıklayın.","start.install#2#li2":"Sohbet panelini açmak için Ctrl+Shift+A tuşlarına basın (macOS'te Cmd+Shift+A).","start.install#2#li3":"Kurulum sihirbazını takip edin; bir model seçin, izin modunuzu belirleyin ve bitirin.","start.install#3#h":"Masaüstü IDE","start.install#4#li0":"Platformunuz için yükleyiciyi sürümler sayfasından indirin.","start.install#4#li1":"Çalıştırın. IDE ilk açılışta sizi karşılama akışıyla gelir.","start.install#4#li2":"Ücretsiz platform jetonları için giriş yapın ya da tamamen yerel çalıştırmak için kendi API anahtarınızı yapıştırın.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli (veya pnpm / yarn — tercihiniz).","start.install#6#li1":"Herhangi bir proje dizininde ava komutunu çalıştırın.","start.install#6#li2":"İlk çalıştırmada sizden bir sağlayıcı ve bir model ister. Seçin ve başlayın.","start.install#7#c":"Hesabınız olmasa da sorun değil. Kendi API anahtarınızla (BYOK) hiç giriş yapmanıza gerek kalmaz. Ücretsiz paket, platform tarafından yönetilen modeller içindir.","concepts.memory#title":"Hafıza — Ava sizi nasıl hatırlıyor","concepts.memory#0#p":"Düz haliyle: Ava sizi hatırlar. Ona bir kez bir şey söyleyin — neyi sevdiğinizi, verdiğiniz bir kararı — ve onu saklar, böylece bir sonraki sohbetinizde veya haftada kendinizi tekrarlamak zorunda kalmazsınız. İşte ana fikir. Aşağıdaki katmanlar sadece onun bu hafızayı zamanla nasıl temiz tuttuğunu açıklar.","concepts.memory#1#p":"Ava'nın kalıcı bir hafızası var (\"kalıcı\" — uygulamanızı kapattıktan sonra yanında kalması anlamına gelir) ve senkronizasyonu açarsanız konuşmalar arasında, projeler arasında ve cihazlar arasında hayatta kalır (senkronizasyon hafızanızı cihazlarınız arasında kopyalar). Bu bir sohbet kaydı değil. Sizin kim olduğunuz, neyi sevdiğiniz ve neye karar verdiğiniz hakkında yapılandırılmış, aranabilir bir anlayıştır.","concepts.memory#2#h":"Beş katman","concepts.memory#3#li0":"Çıkar — Her mesajdan anlık olarak yakalanan temel gerçekler.","concepts.memory#3#li1":"Yansıt — Anlamlı oturumların sonunda daha derin analizler çalışır. Desenler, temalar, çelişkiler.","concepts.memory#3#li2":"Biriktir — Düzeltmeler ve tercihler haftalar ve aylar içinde birikir.","concepts.memory#3#li3":"Analiz Et — Grafik motoru ilgili hafızaları bağlar ve yeni bilgi eskiyle çakıştığında çelişkileri işaretler.","concepts.memory#3#li4":"Birleştir — Benzer hafızalar birleşir; eski olanlar temizlenir. Hafıza zamanla daha keskin olur, gürültülü değil.","concepts.memory#4#c":"Yukarıdaki beş katman kendi başına çalışır — bunları yönetmek zorunda değilsiniz. Buradalar ki hafızanın zamanla gerçekten geliştiğini görebilesiniz, bir dağınıklık yığınına dönüşmesin.","concepts.memory#5#h":"Hatırlama","concepts.memory#6#p":"Bir soru sorduğunuzda Ava, hafızayı anlam üzerinden arar (\"semantik arama\" — ne demek istediğinizi anlar, bu yüzden farklı ifade etseniz bile doğru hafızayı bulur), sadece tam kelimeleri eşleştirmek yerine. Mod-bazlı filtreler birlikte çalışır — Sohbet modu kişisel bağlamı çeker, Çalışma modu proje kararlarını ve kod desenlerini çeker.","concepts.memory#7#c":"Hafıza kullanıcı ve proje bazlıdır (hafızanız size aittir, kişi ve proje bazında ayrı tutulur). Gizli bilgiler ve kimlik doğrulama bilgileri (parolalar, anahtarlar) kaydetme sınırında engellenir — asla hafızaya düşemezler.","concepts.desktop-grounding#title":"Masaüstü Bağlama Hiyerarşisi (Ön İzleme)","concepts.desktop-grounding#0#c":"Ön İzleme — Scout'un her adımda hangi bağlama kaynağını kullanacağını nasıl belirlediği.","concepts.desktop-grounding#1#p":"Ava bir düğmeye tıklamadan önce, gerçekten neyin nerede olduğunu anlaması gerekir — bu 'bağlama'dır (ekrandaki her şeyin ne olduğunu ve tam konumunu bulmak). Bunu yapmanın üç yolu vardır ve bulunduğunuz uygulama için en güvenilir olanı seçer. Bu derin bir kullanıcı detayıdır; asıl nokta sadece onun resimden tahmin etmek yerine sağlam, doğru yöntemleri tercih etmesidir.","concepts.desktop-grounding#2#p":"Üç seviye vardır, sırasıyla değerlendirilir. En uygun maliyetli ve güvenilir kaynak tercih edilir.","concepts.desktop-grounding#3#h":"1. Tarayıcı Penceresi → Playwright DOM","concepts.desktop-grounding#4#p":"Aktif pencere bir web tarayıcısıysa, Ava sayfayı resimden tahmin etmek yerine kendi yapısını ('DOM' — sayfadaki öğelerin altında yatan listesi) okur. Yapıyı okumak, pikselleri gözlemlemekten yaklaşık 10 kat daha güvenlidir — her düğmenin tam olarak nerede olduğunu ve sayfanın yüklenip yüklenmediğini bilir. Bu, web'deki her şey için ana yoldur, bir yedek değil.","concepts.desktop-grounding#5#h":"2. UIA Destekli Yerel Uygulama → Windows UI Otomasyonu","concepts.desktop-grounding#6#p":"Windows'taki sıradan masaüstü uygulamaları için Ava, yerleşik bir erişilebilirlik haritasını okur ('UIA', pencereleri tanımlamak için ekran okuyucuların kullandığı aynı veri) — her denetimi, adını ve nerede olduğunu listeler. Bu harita en az beş kullanılabilir, adlandırılmış öğe döndürürse, ona güvenir ve kullanır.","concepts.desktop-grounding#7#h":"3. UIA Boşsa veya İşe Yaramazsa → OmniParser Görüntüsü","concepts.desktop-grounding#8#p":"Bu harita yoksa veya işe yaramazsa (bazı uygulamalar, oyunlar ve uzaktan ekranlar bir tane sağlamaz), Ava doğrudan ekran görüntüsüne bakmaya döner. Bir görüntü aracı (OmniParser) tıklanabilir bölgeleri tespit eder ve her birinin ne olduğunu etiketler, resmi işlenebilecek bir listeye dönüştürür — erişilebilirlik haritasının verdiği küçük bilgilerle birlikte.","concepts.desktop-grounding#9#c":"OmniParser, Ava ilk kez ihtiyaç duyduğunda açık bir gizlilik uyarısıyla isteğe bağlıdır. BYOK kullanıcıları kendi yerel OmniParser dağıtımlarını gösterebilir.","concepts.desktop-kill-switches#title":"Masaüstü Acil Durdurma Anahtarları (Ön İzleme)","concepts.desktop-kill-switches#0#c":"Ön İzleme — çalışan bir işlemi iptal etmenin üç bağımsız yolu. Bunlardan herhangi biri yeterlidir.","concepts.desktop-kill-switches#1#p":"'Acil durdurma anahtarı' tam olarak seslendirdiği gibidir — Ava ekranınızı kontrol ederken onu anında durdurmanın acil bir yoludur. Rahatlatıcı kısım: üçün var, her biri ayrı inşa edilmiştir, yani biri başarısız olursa diğeri yine de çalışır. Üçünü de öğrenmenize gerek yok. Sadece bir şeyler yanlış görünürse her zaman durdurabileceğinizi bilin ve en güçlü durdurma (aşağıdaki panik durdurma), Ava'nın işbirliğine dayanmaz.","concepts.desktop-kill-switches#2#p":"Kamuoyuna açıklanan tüm otonomi olaylarını inceledikten sonra (AI ajanlarının durdurma komutlarını görmezden geldiği, e-posta arşivlerini sildiği veya diski temizlediği gerçek durumlar), üç farklı katmanda üç acil durdurma anahtarı geliştirdik. Hiçbiri AI modeline bağlı değildir — Ava takılı kalırsa veya tepkisiz olursa bile onu durdurabilirsiniz.","concepts.desktop-kill-switches#3#h":"Duraklat — Boşluk tuşu veya Duraklat düğmesi","reference.config#title":"Yapılandırma","reference.config#0#p":"Bu sayfa, Ava'nın bilgisayarınızdaki ayarlarını ve dosyalarını nerede sakladığını gösterir. Bunların hiçbirine elinizle dokunmanız neredeyse hiç gerekmez — uygulama bunu sizin için yönetir. Kendi başınıza görmek, yedeklemek veya paylaşmak istediğinizde buradadır.","reference.config#1#p":"Ava yapılandırmayı (kaydedilmiş ayarlarını) iki kapsamdan okur. Küresel ayarlar — yani her yerde geçerli olanlar — ~/.ava/ adında bir klasörde bulunur (\"~\" kısaltması ana klasörünüz anlamına gelir). Proje bazlı ayarlar ise projenin içindeki .ava/ klasöründe yer alır.","reference.config#2#h":"Küresel — ~/.ava/","reference.config#3#li0":"settings.json — model tercihleri, izin modu, kişilik, dil.","reference.config#3#li1":"memory/ — küresel hafızalarınız (her yerde geçerli tercihler ve kararlar).","reference.config#3#li2":"tasks.json — proje genelinde görev listesi.","reference.config#3#li3":"journal/ — günlük girişler, tarih sırasına göre düzenlenmiş.","reference.config#4#h":"Proje — .ava/","reference.config#5#li0":"instructions.md — Ava'nın her zaman yüklediği proje özel talimatlar. Kalıcı bağlam (\"pnpm kullanıyoruz, npm değil\", \"API anahtarları 1Password'da saklanır\").","reference.config#5#li1":"context.md — isteğe bağlı serbest form proje notları.","reference.config#5#li2":"memory/ — bu projeye özel hafızalar.","reference.config#5#li3":"datasets/config.json — seçmeli veri seti yakalama yapılandırması.","reference.config#6#c":".ava/ klasörünü .gitignore'a ekleyin (Git'in paylaşılan projeden çıkarılması söylenen dosya listesi), eğer hafızalarınızı ekibinizle paylaşmak istemiyorsanız. instructions.md dosyasını depoda (paylaşılan proje klasörü) tutun — işte Ava'nın proje kurallarını öğrenme şekli budur.","reference.shortcuts#title":"Klavye kısayolları","reference.shortcuts#0#p":"Klavye kısayolları isteğe bağlı hızlandırmalardır — hepsi aynı zamanda tıklayabileceğiniz bir düğmedir. Sadece klavyeden Ava'yı daha hızlı kullanmak isterseniz buraya bakın.","reference.shortcuts#1#p":"Arayüzlere göre kısayollar (Ava'nın çalıştığı üç ortam: VS Code eklentisi, masaüstü uygulaması ve terminal). Her arayüzün ayarlarından özelleştirebilirsiniz. Aşağıdaki listeyi ezberlemenize gerek yok.","concepts.desktop-kill-switches#4#p":"Bir sonraki adım sınırında durur. Devam ettirilebilir. Trajektoriyi kaybetmeden müdahale etmek istediğinizde bunu kullanın.","concepts.desktop-kill-switches#5#h":"Durdur — Escape veya Durdur düğmesi","concepts.desktop-kill-switches#6#p":"Temel iptal. Anlatıcı, şimdiye kadar ne yapıldığını özetler. Devam ettirilemez. Denetim günlüğü kaydedilir.","concepts.desktop-kill-switches#7#h":"Panik öldürme — üç kez Escape veya Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"En kesin durdurma budur. Ekranınızı yöneten Ava'nın parçasını zorla kapatan küçük, ayrı bir izleme programıdır. Yapay zekanın yanıt vermesini beklemez, uygulama penceresinin çalışmasına gerek duymaz ve durumun ne olduğuna bakmaz — sadece kapatır. Gerçekten bir şeyler ters gittiğinde kullanılması gereken budur.","concepts.desktop-kill-switches#9#p":"Üçü de yardımcı uygulamadan da çalışır. Herhangi bir sürücü sonlandırabilir.","reference.tools#title":"Araç referansı","reference.tools#0#p":"Bu, Ava'nın sahip olduğu tüm araçların tam listesidir — bir \"araç\", dosya okumak veya arama yapmak gibi yapabileceği belirli bir eylemdir. Bu sayfayı okumanıza gerek yok. Ava her seferinde doğru aracı kendisi seçer. Tam olarak ne yapabildiğini merak ettiğinizde buradadır.","reference.tools#1#p":"Tam yerleşik araç kutusu. Buradaki her araç, temel çalışma zamanına (üç yüzeyin altındaki motor) kaydedilmiştir ve mod ile izin modu izin verdiğinde Ava'ya açıktır. Kategori veya risk açısından filtreleyin.","reference.tools#2#p":"Bunları ezberlemenize gerek yok — aşağıdaki tablo sadece bir referans kartıdır.","reference.tools#4#h":"Risk seviyeleri","reference.tools#5#li0":"Güvenli — hiçbir şeyi değiştirmeden okur. file_read, glob (dosyaları ad deseniyle bulur), grep (dosyaların içinde metin için arama yapar), git_status (Git, projenizdeki değişiklikleri takip eden sistemdir).","reference.tools#5#li1":"Yaz — dosyaları değiştirir, işinizin bir kontrol noktasını kaydeder (bir \"commit\"), veya yeni bir şey üretir. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Tehlikeli — bilgisayarınızda komutlar çalıştırır (\"shell\"), masaüstünü kontrol eder, internete çıkar veya veritabanlarını sorgular. bash, browser, desktop_*.","reference.tools#6#c":"Kişi uzmanlarının kendi araç izin listeleri vardır. Scout okuyabilir ama yazamaz. Builder tam erişime sahiptir. Challenger hiç araç sahibi değildir — görevi planı sorgulamaktır.","reference.models#title":"Modeller","reference.models#0#p":"Bir \"model\", düşünmeyi yapan yapay zeka beynidir — Qwen, DeepSeek, Mistral ve diğerleri. Bu sayfa, Ava'nın kullanabileceği her modeli listeler. Kısa versiyon: birini seçmek zorunda değilsiniz. Ava her adım için doğru modeli kendisi seçer. Bunu anlamak veya geçersiz kılmak istiyorsanız devam edin.","reference.models#1#p":"Ava'nın yönlendirebileceği her model, artı üç koordinasyon stratejisi — bir işin hangi kısmının hangi model tarafından ele alınacağını belirleyen kurallar. Bir yönlendirme modu seçin ve Ava'nın dağıtmasına izin verin, veya tek bir model seçin ve yönlendirmeyi tamamen atlayın.","reference.models#2#h":"Yönlendirme modları","reference.models#3#p":"Üç koordine strateji. Aynı uzman akışı (Ava'nın arka planda çalıştırdığı küçük uzman ekibi) hepsinde çalışır; değişen şey alttaki model grubudur. Model seçicisinde bir mod seçin ve Ava gerisini halleder. Aşağıdaki her kart, yöneticinin yönlendirdiği uzmanları gösterir.","reference.models#4#p":"Aşağıdaki kartları ezberlemenize gerek yok — bunlar burada, her stratejinin neyle yapıldığını görebilmeniz içindir.","reference.models#6#c":"Aurora kasıtlı olarak yalnızca Mistral kullanır. Bir Mistral modeli bulunamazsa, yönlendirici çapraz yönlendirme yapmak yerine hata döndürür — bu AB yığını garantisidir. Kademeli azalma için Maestro veya Supernova'yı seçin.","reference.models#7#c":"Üç mod da evrensel olarak kullanılabilir — platform kredilerinde ve kendi anahtarlarınızda. BYOK, koordinasyonu atlayıp doğrudan tek bir modeli sürme seçeneğini ekler.","reference.models#8#h":"Platform yönetimli modeller","reference.models#9#p":"Her plana, ücretsiz katmana dahil olmak üzere mevcuttur. Tokenlar (yapay zekanın metin ölçümünde kullandığı birimler — her biri yaklaşık dörtte üç kelime) plan kotanızdan düşülür. Anahtarlar (her ücretli modeli kilitleyen özel şifreler) platform tarafından periyodik olarak değiştirilir ve izlenir — ayar yapmanız gereken bir şey yok.","reference.models#11#h":"Kendi Anahtarını Getir","reference.models#12#p":"\"API anahtarı\", yazılımın kendi hesabınız üzerinden ücretli bir hizmet kullanmasını sağlayan özel bir şifredir. \"BYOK\" sadece \"kendi anahtarınızı getirmek\" anlamına gelir — bizimkinden ziyade kendi anahtarınızı kullanmak. API anahtarınızı ayarlara yapıştırın. BYOK istekleri Ava'dan doğrudan sağlayıcıya (modeli işleten şirkete) gider — altyapımızdan geçmez ve platform jetonlarını tüketmez. Sağlayıcıya siz ödersiniz; biz trafiği görmüyoruz.","reference.models#14#c":"Benchmark skorları, yetenek etiketleri ve yan yana filtreleme için ava-supernova.com/models adresindeki tam Modeller sayfasına bakın. Yukarıda gösterilen fiyatlandırma, yayınlandığı anda her sağlayıcının fiyat kartı hakkında en iyi okumamızdır — bir iş yüküne başlamadan önce her zaman sağlayıcının web sitesini kontrol edin.","reference.personas#title":"Persona Koordinasyonu","reference.personas#0#p":"Bir \"persona\", Ava'nın zorlu işler için arka planda oynadığı yardımcı rolüdür — bir kaşif, bir planlayıcı, bir doğrulayıcı. Onlarla doğrudan konuşmazsınız ve Ava'yı kullanmak için bu sayfayı anlamanıza gerek yoktur. Büyük bir işi küçük uzman bir ekibe nasıl böldüğünü merak ettiğinizde buradadır.","reference.personas#1#p":"5 mod takımında 24 uzman. İdareci (diğerlerini koordine eden yardımcı), hangi takımın çalışacağını, sırayı ve hangi bağlamla kullanılacağını belirler. Sohbet modunda persona yoktur — bu Ava'nın kendisidir.","reference.personas#2#h":"Koordinasyon Nasıl Çalışır","reference.personas#3#li0":"Planlama, Öğretme, Güvenlik veya Beyin Fırtınası modunda bir mesaj gönderirsiniz (veya karmaşık bir İş isteği).","reference.personas#3#li1":"İdareci isteği okur, mod takımını seçer ve bir yürütme planı oluşturur — bazı personalar sırayla, bazıları paralel dalgalar halinde çalışır.","reference.personas#3#li2":"Her personanın kendi sistem istemi, kısıtlı araç onay listesi ve önceki personaların bulduklarından oluşan paylaşılan bir bağlam havuzu vardır.","reference.personas#3#li3":"Son persona, moda bağlı olarak bir özet, bir plan veya bir rapor üretir.","reference.personas#3#li4":"Ava sonucu size sunar. Onaylarsınız, düzeltirsiniz veya yönlendirirsiniz.","reference.personas#4#p":"Aşağıdaki tam kadro sadece referans içindir — kimin ne yaptığını ezberlemenize gerek yok. Ava sizin için doğru ekibi toplar.","reference.personas#6#c":"İş modu sadece karmaşık görevler için tam ekibi çağırır. Basit düzenlemeler Ava'yı doğrudan çalıştırır — hiçbir koordinasyon yükü yoktur.","features.unified-panel#title":"Birleştirilmiş panel","features.unified-panel#0#p":"Basitçe anlatmak gerekirse: Ava'nın yaptığı her şey tek bir pencerede yaşar, böylece bulmak için sekme arasında gezinmek zorunda kalmazsınız.","features.unified-panel#1#p":"Sohbet, panel, hafıza, görevler ve günlük için tek bir panel. Pencereler arasında bağlam değiştirme yok. Kenar çubuğu neye baktığınızı seçer; ana alan buna uyacak şekilde değişir.","features.unified-panel#2#p":"Konuşma durumu yanına gittiğinizde de kalır — hafızayı açın, bir görevi kontrol edin, sonra geri dönün. Sohbet hala orada, Ava çalışıyorsa akış halindedir.","features.unified-panel#3#c":"Birleştirilmiş panel bir uzantı ve IDE kavramıdır. Web yüzeyi tarayıcı sekmelerini kullanır.","features.knowledge-packs#title":"Bilgi paketleri","features.knowledge-packs#0#p":"Basitçe anlatmak gerekirse: Ava'ya kendi belgelerinizin olduğu bir klasör verin, o da sorularınızı yanıtlamak için onlardan okuyabilir. Bir \"bilgi paketi\", yalnızca o dosya demeti — başvurmasına izin verilen referans materyalinizdir.","features.knowledge-packs#1#p":"Referans materyal dizininizi (özellikler, RFCs, toplantı notları, API dokümantasyonu) bir bilgi paketine bırakın. Sohbet konuya değindiğinde Ava ilgili parçaları bağlama çekebilir.","features.knowledge-packs#2#p":"Paketler yerel olarak indekslenir. Arama anlamsaldır — Ava doğru belgeyi dosya adı yerine anlam üzerinden bulur. (\"Anlamsal\", bir belgenin hakkında ne olduğunu eşleştirdiği anlamına gelir, böylece tam kelimeleri veya dosya adını hatırlamanıza gerek yoktur.) Paketler bir ekip ile paylaşılabilir veya gizli tutulabilir.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Bir rapor, e-posta veya belge mi yazmanız gerekiyor? Ava taslağını hazırlayıp size gerçek bir Word, Excel veya PDF dosyası verir; diğer dosyalar gibi açıp düzenleyebilirsiniz.","features.office-suite#1#p":"Raporlar, e-postalar ve belgeler — taslak hali, biçimlendirilmiş ve yerel formatlara aktarılmış (.docx Word, .xlsx Excel, .pdf PDF dosyasıdır).","features.office-suite#2#li0":"report_generate — görevlerden, günlükten, hafızadan ve proje durumundan veri çeken yapılandırılmış bir .docx.","features.office-suite#2#li1":"email_draft — ton kontrolü olan e-posta, .docx dosyası olarak.","features.office-suite#2#li2":"document_manage — Word, Excel, PDF, CSV, Markdown üzerinde oluştur, oku, düzenle, dışa aktar.","features.office-suite#3#p":"Ava sizin adınıza yazarken kullanışlıdır — durum raporları, başlangıç sunumları, müşteri güncellemeleri. .docx dosyası projenize gelir, burada onu son dokunuşlarla güzelleştirebilirsiniz.","features.dashboard-library#title":"Gösterge paneli kütüphanesi","features.dashboard-library#0#p":"Basitçe anlatmak gerekirse: Sizin ve Ava'nın yaptığınız ve konuştuğunuz her şeyi tutan tek bir raf, böylece hiçbir şey kaybolmaz.","features.dashboard-library#1#p":"Ava'nın sizinle ürettiği her şeyin gezilebilir görünümü — oluşturulan görseller, videolar, sesler, belgeler — sohbetleriniz, hafızanız ve görevlerinizin yanında. Geçen hafta yaptığınız bir şeyi bulmak için tek bir yer.","features.document-preview#title":"Belge önizleme","features.document-preview#0#p":"Basitçe anlatmak gerekirse: Okumak için ayrı bir program açmadan, tam bulunduğunuz yerde bir belgenin içine göz atın.","features.document-preview#1#p":"Projenizdeki bir Word belgesi, Excel tablosu, PDF, CSV, HTML veya Markdown dosyasına sağ tıklayın — editörden çıkmadan satır içinde önizleyin. Ava'nın oluşturduğu referans materyallerini okumak veya bir işbirlikçinin eklediği dosyalara bakmak için kullanışlıdır.","features.daily-briefing#title":"Günlük özet","features.daily-briefing#0#p":"Basitçe anlatmak gerekirse: Her sabah kısa bir \"nerede kaldığınızı hatırlatan\" not, böylece her şeyi yeniden okumadan devam edebilirsiniz.","features.daily-briefing#1#p":"Sabah özeti: dünki günlük, açık görevler, proje durumu ve Ava'nın belirlediği herhangi bir hatırlatma. İsteğe bağlı — ayarlardan açabilirsiniz.","features.daily-briefing#2#p":"Özet, ilgili bağlamı ortaya çıkarmak için hafızayı kullanır (\"son kez kimlik doğrulama akışı üzerinde çalışırken, yenileme jetonu stratejisini tekrar gözden geçirmek istediğinizi not etmiştiniz\"). Haber akışı değil — odaklanmış bir toparlanma.","reference.project-context#title":"Proje bağlamı","reference.project-context#0#p":"Bu, Ava'nın başlamadan önce projeniz hakkında bilgi edinme şeklini açıklar — çalıştığınız şeyi anlamak için baktığı dosyalar. Bunlardan hiçbirini kurmanıza gerek yok; o kendi başına halleder. O her zaman görsün diye bir not nereye koyabileceğinizi bilmek istiyorsanız okuyun.","reference.project-context#1#p":"Bir proje açtığınızda Ava, zihninde tuttuğu arka plan bilgilerini (bağlamı) birkaç katmanda yükler. Bilgileri doğru yere yerleştirmenize yardımcı olmak için bu katmanları anlamanız gerekir.","reference.project-context#2#h":"Otomatik olarak yüklenenler","reference.project-context#3#li0":".ava/instructions.md — kalıcı, yüksek öncelikli rehberlik olarak kabul edilir. Her zaman bağlamdadır.","reference.project-context#3#li1":".ava/context.md — serbest notlar. Yüklenir, ancak önceliği daha düşüktür.","reference.project-context#3#li2":"README.md — proje özeti için ilk çalıştırmada taranır.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — proje kurulumunu listeleyen küçük dosyalar; dili, çerçeveyi ve test komutunu algılamak için okunur.","reference.project-context#3#li4":".gitignore — sürüm kontrolüne dahil edilmemesi gereken dosyaların listesi; tüm dosya araçları (glob, grep, project_index) tarafından saygı duyulur.","reference.project-context#4#h":"İsteğe bağlı yüklenenler","reference.project-context#5#p":"\"İsteğe bağlı\", Ava'nın bunları ön yükleme yerine görev gerçekten ihtiyaç duyduğunda alması demektir.","reference.project-context#6#li0":"Proje indeksi — dosyalarınızın ve içindeki adlandırılmış parçaların (fonksiyonlar, sınıflar — \"semboller\") ve nasıl bağlandıklarının (\"importlar\") yapısal bir haritası. Sadece Ava'ya gerektiğinde inşa edilir.","reference.project-context#6#li1":"Git geçmişi — geçmiş değişikliklerin kaydı; git_status, git_diff veya git_create_pr çağrıldığında çekilir (git, projeye yapılan her değişikliği takip eden araçtır; \"PR\" bir çekme isteğidir, önerilen bir değişiklik paketidir).","reference.project-context#6#li2":"Hafıza — girdiler anlam bazlı (\"anlamsal\") eşleştirilir ve hepsi birden değil, tek seferde enjekte edilir.","reference.project-context#7#c":"Kuralları instructions.md'ye, notları context.md'ye yazın. Geri kalanını hafızanın kendi yakalamasına izin verin.","features.workflows#title":"İş Akışları","features.workflows#0#p":"Basitçe anlatmak gerekirse: Ava'nın sürekli tekrarladığı bir rutin öğretin, ona bir isim verin ve o da istediğiniz zaman tümünü tekrar çalıştırabilir. Bir 'iş akışı' sadece kaydedilmiş rutindir — Ava'nın sizin için tekrarladığı adımlar kümesidir.","features.workflows#1#p":"Tekrar ettiğini fark ettiğiniz adım dizilerini kaydedin — PR gözden geçir → testleri çalıştır → sürüm notlarını yaz → e-postayı taslağını hazırla. Bir iş akışı, farklı girdilerle yeniden oynatılabilecek kullanılabilir bir plandır.","features.workflows#2#p":"İş akışları proje başına .ava/workflows/ klasörü içinde projenizin içine saklanır. Takımınızla paylaşmak için dizini commit edin (paylaşılan projeye kaydeder, böylece takım arkadaşlarınız da alır).","features.events#title":"Etkinlikler ve Bildirimler","features.events#0#p":"Basitçe anlatmak gerekirse: Ava çalışırken yaptıkları hakkında düzenli bir adım adım liste alırsınız ve uzun bir işlem bittiğinde size haber verir, böylece uzaklaşabilirsiniz.","features.events#1#p":"Ava çalışırken karşınıza çıkan karmaşık bir metin yığını yerine düzenli güncellemeler görürsünüz. Her araç kullanımı, her rol devri, her veri akışı arayüzde ayrı bir olay olarak yer alır — detay görmek için açabilir, genel görünüm için kapatabilirsiniz.","features.events#2#p":"Arka plan çalışmaları tamamlandığında işletim sistemi düzeyinde bildirim gönderir. Uzun bir derleme işlemi sırasında masanızdan ayrılabilirsiniz; Ava bitince size haber verecektir.","features.personality#title":"Kişilik Tasarımcısı","features.personality#0#p":"Basitçe anlatmak gerekirse: Ava'nın sizinle nasıl konuştuğunu ayarlayın — sohbetse mi kısa mı, resmi mi samimi mi, daha çok şaka mı az mı — böylece sevdiğiniz gibi ses çıkarır.","features.personality#1#p":"Ava'nın sizinle konuşma şeklini şekillendirin. Ton, enerji, sözcük sayısı (ne kadar konuştuğu), resmiyet, mizah. Kaydırıcılar ve hazır ayarlar — kısa kesmeli mühendis, sıcak mentor, soğuk meslektaş veya kendi karışımınız.","features.personality#2#p":"Kişilik ifade biçimini etkiler, yeteneği değil. Yine de aynı araçları çalıştırır ve aynı izin kurallarını izler. İsmi Ava olarak sabittir — bu tartışılmaz.","features.release-notes#title":"Sürüm Notları","features.release-notes#0#p":"Basitçe anlatmak gerekirse: Her güncellemede neyin yeni olduğunu ve neyin düzeltildiğini gösteren devam eden bir liste, böylece nelerin değiştiğini görebilirsiniz.","features.release-notes#1#p":"Uygulama içi değişiklik günlüğü (bir değişiklik günlüğü değişikliklerin tarihidir). Her gönderilen sürümün öne çıkan özellikleri, hata düzeltmeleri ve kırıcı değişiklikler (kullanım şeklinizi değiştirmenizi gerektirebilecek değişiklikler). Web arayüzü, ava-supernova.com/releases adresinde halka açık sürümü korur.","troubleshooting.common-errors#title":"Yaygın Hatalar","troubleshooting.common-errors#0#p":"Çoğu hatanın kısa ve özel bir nedeni vardır. İşte yaygın olanlar ve nasıl düzeltilecekleri. Yazımın teknik gelmesinden endişelenmeyin — aşağıdakilerin her biri gördüğünüz şeyi ve tam olarak ne yapmanız gerektiğini anlatır.","troubleshooting.common-errors#1#h":"Model Yanıt Vermiyor","troubleshooting.common-errors#2#p":"Gördüğünüz Şey: Ava sessizleşir ve yanıt vermez.","troubleshooting.common-errors#3#p":"Sohbet başlığındaki durum göstergesini kontrol edin. Eğer \"bağlanıyor\" yazıyorsa, sağlayıcınız (Ava'nın konuştuğu AI hizmeti) erişilebilir ama yavaş — otuz saniye bekleyin. Eğer \"erişilemiyor\" yazıyorsa, Ava zincirdeki sonraki modele otomatik olarak geri döndü (yedek modele otomatik olarak geçti). Hiçbiri değilse, Ayarlar'da API anahtarınızı doğrulayın ve bağlantıyı test edin. (Bir API anahtarı, Ava'nın ücretli bir AI hizmetini kullanmasına izin veren özel şifredir.)","troubleshooting.common-errors#4#h":"Araç Çağrısı Başarısız Oldu","troubleshooting.common-errors#5#p":"Gördüğünüz Şey: Ava'nın adımlarından biri (bir \"araç çağrısı\" — bir dosya okuma, komut çalıştırma vb.) bitmek yerine kırmızı bir hata gösteriyor.","troubleshooting.common-errors#6#p":"Başarısız araç çağrısına tıklayarak hatayı görün. Yaygın nedenler: Proje klasörünüzün dışındaki bir dosyaya dokunmaya çalıştı (bu güvenlik için kasıtlı olarak engellenmiştir; bu kalkan \"yol geçiş\" koruması olarak adlandırılır — sizi çalıştığınız klasörün dışına çıkmasını engeller); farklı bir klasörde çalışması gereken bir komut; veya Ava son kez baktığından beri taşınmış bir dosya. Ne olduğunu ona söyleyin — düzeltmelerle yeniden deneyecektir.","troubleshooting.common-errors#7#h":"Hafıza Hatırlamıyor","troubleshooting.common-errors#8#p":"Gördüğünüz Şey: Ava, kesinlikle hatırlaması gereken bir şeyi bulamıyor.","troubleshooting.common-errors#9#p":"Hafıza, tam kelimeler yerine anlamla çalışır (bu \"anlamsal\" dediğimiz şeydir). Yani \"Auth hakkında ne karar vermiştik?\" ifadesi, \"auth kararımı bul\"dan daha iyi çalışır. Hafıza kesinlikle orada ama görünmüyorsa, hafıza tarayıcısını açın ve arama yapın — eğer yoksa, ilk başta hiç kaydedilmemiştir.","troubleshooting.common-errors#10#h":"Giriş Döngüleri","troubleshooting.common-errors#11#p":"Gördüğünüz Şey: Giriş yaparsınız, ancak Ava tekrar giriş yapmanızı ister — sizi içeri sokmayan bir döngü.","troubleshooting.common-errors#12#p":"Çözüm, kaydedilmiş giriş bilgilerini temizlemek ve sıfırdan başlamaktır: uzantıda komut paletinden \"Ava: Çıkış Yap\"ı çalıştırın, IDE'de Ayarlar → Hesap → Çıkış Yap'ı kullanın, CLI'de ~/.ava/auth.json dosyasını silin (ev dizininizdeki .ava adında bir klasördeki küçük bir giriş dosyası). Sonra tekrar giriş yapın.","troubleshooting.common-errors#13#h":"Token Tükenmiş","troubleshooting.common-errors#14#p":"Gördüğünüz Şey: Bu ay ücretsiz kullanım hakkınızın dolduğunu belirten bir mesaj. (\"Tokenlar\", AI kullanımının ölçüldüğü yoldur — \"tükenmiş\" demek sadece bu ayın ücretsiz tahsisatını kullandığınız anlamına gelir.)","troubleshooting.common-errors#15#p":"Ücretsiz katman aylık bütçesi her ayın 1'inde sıfırlanır. Buna kadar, çalışmaya devam etmek için bir BYOK sağlayıcısına geçin (kendi API anahtarınızı kullanın). Hesabınız aktif kalır — yalnızca ücretsiz platform yönetilen istekler durdurulur.","troubleshooting.logs#title":"Günlük Dosyaları Nerede Bulunur","troubleshooting.logs#0#p":"Bir \"günlük\", bilgisayarınızın ne olduğunu kaydettiği bir defter gibidir — bir şey bozulduğunda ve siz (veya destek) detayları görmeniz gerektiğinde yararlıdır.","troubleshooting.logs#1#p":"Ham görüntüyü istediğinizde — hangi aracın çağrıldığı, hangi bilgiyi aldığı, AI servisinin ne döndürdüğü — günlükler bilgisayarınızda ~/.ava/logs/ konumundaki bir klasördeki düz metin dosyalarıdır (ev dizininizde .ava adında bir klasör, içinde de logs klasörü var).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — oturum başına transkriptler, araç çağrıları, akış yanıtları ve hataları içerir.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — VS Code uzantı ana makinesi günlüğü. Etkinleştirme hataları, panel hataları.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — masaüstü IDE günlüğü. Sidecar işlem mesajları, Rust çöküşleri.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — CLI REPL günlüğü.","troubleshooting.logs#3#p":"Uzantıda, komut paletindeki \"Ava: Günlükleri Göster\" ilgili logu bir düzenleyici sekmesinde açar. IDE'de Ayarlar → Tanılama'da \"Günlükleri Aç\" butonu bulunur. CLI, kendi günlüklerini ava logs --follow ile takip edebilir.","troubleshooting.logs#4#c":"Günlükler, oturum sırasında Ava'nın okuduğu proje dosyalarından küçük parçalar içerebilir. Paylaşmadan önce gözden geçirin.","troubleshooting.support-request#title":"Destek Talebi Oluşturma","troubleshooting.support-request#0#p":"Kısaca özetlemek gerekirse: Bir sorun varsa ve yukarıdaki çözümler işe yaramadıysa, bize haber verin. En kolayı, bunu Ava'dan yapmasını istemek.","troubleshooting.support-request#1#p":"Yaygın hatalar arasında yer almayan bir sorunla karşılaşırsanız, bir destek talebi oluşturun (destek ekibine yardım isteyin). Bunu Ava içinde (doldurmanız gereken bir form olmadan) ya da web sitesinde yapabilirsiniz.","troubleshooting.support-request#2#h":"Ava İçinden","troubleshooting.support-request#3#p":"Onu bunu yapması için rica edin. \"Ava, bunun hakkında bir destek talebi oluşturabilir misin?\" Destek talebi fonksiyonunu devreye alır, ilgili oturum bağlamını (kimlik bilgileri gizlenmiş) ekler ve gönderir. En hızlı yol.","troubleshooting.support-request#4#h":"Web Üzerinden","troubleshooting.support-request#5#p":"ava-supernova.com/support adresini ziyaret edin. Bir kategori seçin (hata, özellik, hesap, güvenlik, genel) ve yaşananları anlatın. Yanıt bir iş günü içinde alınır.","troubleshooting.support-request#6#h":"Neleri Dahil Etmelisiniz","troubleshooting.support-request#7#li0":"Ne yapmaya çalıştığınız.","troubleshooting.support-request#7#li1":"Gerçekte ne olduğu.","troubleshooting.support-request#7#li2":"Hangi ortam (eklenti, IDE, CLI, yan uygulama) ve hangi sürüm.","troubleshooting.support-request#7#li3":"Herhangi bir hata mesajı veya günlük alıntısı. Önce kimlik bilgilerini gizleyin.","troubleshooting.security-disclosure#title":"Güvenlik Sorunlarını Bildirme","troubleshooting.security-disclosure#0#p":"Kısaca özetlemek gerekirse: Ava'nın bir şekilde kırılabileceğini veya kötüye kullanılabileceğini fark ettinizse (bir \"zafiyet\" — güvenlik açıklığı), lütfen önce bize özel olarak bildirin ki herkes yararlanmadan önce düzeltebilelim. İşte bu sayfa nasıl yapılacağını anlatıyor.","troubleshooting.security-disclosure#1#p":"Bir zafiyet mi buldunuz? Teşekkür ederiz. Her bildirimi ciddiye alır ve sorunu herkese açık olarak duyurmadan önce (kamuoyuna açıklanmadan) sizinle birlikte düzeltme üzerinde çalışırız.","troubleshooting.security-disclosure#2#h":"Nasıl Bildirilir","troubleshooting.security-disclosure#3#li0":"security@ava-supernova.com adresine bir açıklama, sorunu tekrar etme adımları ve tercihiniz olan açıklama zamanlamasıyla e-posta gönderin.","troubleshooting.security-disclosure#3#li1":"Ya da \"güvenlik\" kategorili bir destek talebi oluşturun — aynı sınıflandırma kuyruğuna gider.","troubleshooting.security-disclosure#3#li2":"24 saat içinde geri dönüş yapıyoruz.","troubleshooting.security-disclosure#4#h":"Taahhütlerimiz","troubleshooting.security-disclosure#5#li0":"Koordineli açıklama — hiçbir şey kamuya açıklanmadan önce sizinle bir zaman çizelgesi üzerinde anlaşırız. Varsayılan süre 90 gündür.","troubleshooting.security-disclosure#5#li1":"Teşekkür — düzeltme notlarında adınız anılır, anonim kalmayı tercih etmediğiniz sürece.","troubleshooting.security-disclosure#5#li2":"Yasal yaptırım yok — iyi niyetli araştırmaya değer veriyoruz. Sizin peşinize avukat göndermeyeceğiz.","troubleshooting.security-disclosure#6#c":"ava-supernova.com/security adresindeki güvenlik sayfası tüm detayları sunar — mimari garantiler, gizleme araçları ve yetki kapıları.","start.what#title":"Ava Nedir?","start.what#0#p":"Ava, sadece konuşan değil, iş yapan bir yapay zeka. Sizin için bir uygulama geliştirir, bir belge yazar, baştan sona bir şey öğretir, bir logo tasarlar ya da sürekli ertelediğiniz idari işleri halleder. Sizi de hatırlar: ne üzerinde çalıştığınızı, neleri nasıl tercih ettiğinizi, geçen hafta ne sorduğunuzu.","start.what#1#p":"Tek bir Ava var ve nerede çalışıyorsanız orada yanınızda — kod editörünüzde, masaüstü uygulamasında, telefonunuzda veya terminalde. Her yerde aynı hafıza, aynı kişilik.","start.what#2#h":"Onu Farklı Kılan Ne?","start.what#3#li0":"Varsayılan olarak size ait. İşleriniz kendi cihazınızda kalır. Asla takip yok, asla telemetri yok.","start.what#3#li1":"Herkesin görebileceği şekilde açık. Ava'nın her satırı kamuya açıktır. Güvenmek zorunda olduğunuz hiçbir şey yok.","start.what#3#li2":"Başlangıç ücretsiz. Her ay 300 kredi, kart gerekmez, gizli ücret yok — ya da kendi yapay zeka anahtarlarınızı ekleyip bize hiç ödeme yapmazsınız.","start.what#3#li3":"Öğretmek sonsuza kadar ücretsiz. Öğrenmenin bir bedeli olmamalı.","start.what#4#p":"Hiç kod yazmadınız mı? Bir sonraki sayfa tam size göre yazıldı. Teknik bilginiz varsa? Öteye geçin — o sizi yakalar.","start.what#deeper#0#h":"Where Ava lives","start.what#deeper#1#li0":"VS Code extension — Ava next to your editor: a chat panel, a dashboard, and changes shown inline before they happen.","start.what#deeper#1#li1":"Desktop IDE — a standalone app with the whole thing in one window. Adds desktop control (opening apps, clicking, typing for you).","start.what#deeper#1#li2":"Companion — a mobile app for when you're away from your desk: tasks, journal, memory, quick chats.","start.what#deeper#1#li3":"CLI — Ava in your terminal, for people who live there.","start.what#deeper#2#h":"How she works, in brief","start.what#deeper#3#p":"Ava switches mindsets (called modes) to match the job, quietly runs a small team of specialist helpers on harder work, and picks the best AI model for each step automatically. You never manage any of it. The Core concepts section has the full tour whenever you're curious.","start.first-five#title":"Ava ile İlk İşiniz","start.first-five#0#p":"Ava'yı kullanmaya başlamanın en hızlı yolu, ona somut bir şey istemek ve yaparken izlemektir. Okunacak bir kurulum yok, önceden öğrenecek bir şey yok — sadece ne istediğinizi sade kelimelerle söyleyin.","start.first-five#1#h":"Şimdi Bunu Deneyin","start.first-five#2#li0":"Sohbeti açın.","start.first-five#2#li1":"Gerçekten yapmak istediğiniz bir şey yazın. \"Bu proje ne işe yarıyor\" veya \"formu temizleyen bir buton ekle\" gibi örnekler deneyin.","start.first-five#2#li2":"Ava yapmayı planladığını size gösterir — ve onayınızı bekler.","start.first-five#2#li3":"Beğendiniz mi? Onaylayın. Yaparken izleyin.","start.first-five#3#p":"Ritim bu kadar basit: siz sorarsınız, o planı gösterir, siz onaylarsınız, o yapar. Size göstermeden hiçbir şeyi değiştirmez — böylece deneme sırasında hiçbir şeyi bozamazsınız.","start.first-five#4#h":"Sormaya Değer Birkaç Şey","start.first-model#deeper#0#h":"Her stilde tam olarak neler var?","start.first-model#deeper#1#p":"Maestro — tek bir şef (Qwen 3.6 Plus) her adımı yönetir. Üretim odaklı, kanıtlanmış, maliyeti öngörülebilir.","start.first-model#deeper#2#p":"Supernova — sınır koordinatörü (DeepSeek V4 Pro, 1.6T parametre / 49B aktif, 1M bağlam) her alt görevi bir uzmana devreder: V4 Flash yüksek hacimli derlemeler için, Qwen 3.6 Plus yedek olarak, Qwen Omni görüntü için.","start.first-model#deeper#3#p":"Aurora — sadece Mistral, üç seviyede: Mistral Large 3 (koordinatör + ağır uzmanlar), Mistral Medium 3.5 (128B yoğun, 256K bağlam, yerel görüntü, değiştirilmiş-MIT açık ağırlıklar, %77.6 SWE-Bench Doğrulanmış) Yapıcı + orta seviye + görüntü + uzun form için ve Mistral Small 4 niyet kapısında. Açık ağırlıklar uçtan uca, asla AB altyapısından çıkmaz.","start.first-model#deeper#4#h":"Kendi modelinizi getirin (BYOK)","start.first-model#deeper#5#p":"Kendi AI hesabınızı kullanmak mı istersiniz? Ayarlarda sağlayıcı anahtarınızı yapıştırın ve ikisini de elde edersiniz — üç yönlendirme stili, ayrıca tek bir model seçip yönlendirmeyi tamamen atlamak için seçenek. Güçlü bir tercihiniz varsa, katı bir bütçeniz varsa veya belirli bir modeli test ediyorsanız çok faydalıdır. Tam sağlayıcı listesi Başvuru bölümünde yer alıyor.","start.glossary#title":"Basit Anlatım Sözlüğü","start.glossary#0#p":"Ava ile ilgili karşılaşabileceğiniz her kelime, herhangi bir ön bilgi gerektirmeden açıklanıyor. Bunların hiçbirini ezberlemenize gerek yok — bir terim takıldığında geri dönüp bakabilirsiniz.","start.glossary#1#th0":"Kelime","start.glossary#1#th1":"Aslında ne anlama geliyor","start.glossary#1#td0.0":"Ajan","start.glossary#1#td0.1":"Sizin için eylemlerde bulunabilen bir Yapay Zeka — bir dosya okumak, komut çalıştırmak, web'de arama yapmak — sadece sohbet etmek değil. Ava bir ajandır: sizin izninizle işler yapar.","start.glossary#1#td1.0":"Model","start.glossary#1#td1.1":"Düşünmeyi yapan gerçek AI beyni (Qwen, DeepSeek, Mistral ve diğerleri). Farklı modellerin farklı güçlü yönleri vardır. Normalde birini siz seçmezsiniz — Ava seçer.","start.glossary#1#td2.0":"Mod","start.glossary#1#td2.1":"Ava'nın içinde bulunduğu zihniyet. Bir meslektaşın şapkaları değiştirmesi gibi: yapımcı, yazar, öğretmen, planlayıcı, arkadaş. Modu siz seçersiniz; bu onun nasıl davrandığını değiştirir. Yedi tane var.","start.glossary#1#td3.0":"Kişilik / Uzman","start.glossary#1#td3.1":"Zor işler için arka planda çalışan yardımcı roller — bir keşifçi, bir planlayıcı, bir doğrulayıcı. Küçük bir uzman ekibi gibi düşünün. Onlarla doğrudan konuşmazsınız; Ava onları koordine eder.","start.glossary#1#td4.0":"Yönlendirme","start.glossary#1#td4.1":"Ava'nın iyi yanıtlar almanızı sağlarken aşırı ödeme yapmamanız için her adım için hangi modeli kullanacağına karar vermesi. Otomatik olarak gerçekleşir — 'yönlendirme modu' sadece genel stratejiyi seçer.","start.glossary#1#td5.0":"Araç","start.glossary#1#td5.1":"Ava'nın yapabileceği belirli bir eylem — bir dosya okumak, arama yapmak, e-posta göndermek. Bir 'araç çağrısı', onun birini kullanmasıdır. Herhangi bir riskli şeyden önce izin ister.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"AI'nin metni ölçme birimi — yaklaşık bir kelimenin ¾'ü. Modeller milyon token başına fiyatlandırılır. Çoğunlukla göz ardı edebileceğiniz bir şeydir.","start.glossary#1#td7.0":"Kredi","start.first-five#5#li0":"Bir soru — \"sayfam neden boş?\", \"bu dosya ne işe yarar?\"","start.first-five#5#li1":"Bir şeyler inşa etmek — \"bana basit bir yapılacaklar listesi sayfası yap\".","start.first-five#5#li2":"Bir şeyler öğrenmek — \"sıfırdan bana Python öğret\". (Her zaman ücretsiz.)","start.first-five#5#li3":"Bir belge — \"bana tek sayfalık bir proje önerisi yaz\". Size bir Word dosyası veya PDF sunar.","start.first-five#6#c":"Ne yazacağınızdan emin değil misiniz? Bilgili bir arkadaşınla konuşuyormuşsun gibi konuşun. Basit kelimeler tam olarak doğru — başlamak için teknik terimlere ihtiyacınız yok.","start.first-five#deeper#0#p":"O basit döngü, perde arkasında oldukça fazla şey yapıyor. Bunu kullanmak için bunların hiçbirine ihtiyacınız yok — ama merak ederseniz aslında neler oluyor burada.","start.first-five#deeper#1#h":"Araçlar ve onay","start.first-five#deeper#2#p":"Ava bir dosya okuduğunda, bir komut çalıştırdığında veya kod düzenlediğinde, bunların her biri bir \"araç çağrısı\"dır. Dosyalarınıza veya sisteminize dokunan herhangi bir şeyden önce sorar — ne sıklıkta sorduğu izin modunuz tarafından belirlenir (her seferinde sor, sadece riskli olanlarda sor, ya da direkt devam et).","start.first-five#deeper#3#h":"Modlar — onun çalışma halleri","start.first-five#deeper#4#p":"Ava modlarda çalışır: iş için uygun bir zihniyet ve araç takımı. Seçiciden istediğiniz zaman geçiş yapabilir veya mesajınızın başına bir önek yazabilirsiniz. Yedi tane var.","start.first-five#deeper#6#h":"Uzmanlar ve yönlendirme","start.first-five#deeper#7#p":"Zor işlerde Ava, perde arkasında küçük bir uzman yardımcı ekibi çalıştırır (bir planlayıcı, bir denetleyici, bir oluşturucu) ve her adımı en iyi olduğu modele yönlendirir. Bunlardan hiçbiriyle ilgilenmezsiniz — o sizin için koordinasyonunu sağlar.","start.local-vs-cloud#title":"Yerel mi bulut mu, tek paragrafta","start.local-vs-cloud#0#p":"Ava'nın yaptığı her şey açıkça izin vermedikçe yereldir. Hafıza, görevler, günlük, kişilik, ayarlar — hepsi makinenizde ~/.ava/ ve .ava/ (projeye özel) klasörlerinde saklanır. İsteğinizi çalıştırmak için model sağlayıcılarıyla HTTPS üzerinden konuşur, sonra eve döner. Verilerini dışarıya göndermez. Kullanım verisi toplamaz. Kodunuzu eğitmek için kullanmaz.","start.local-vs-cloud#1#p":"Giriş yaparsanız, platform yönetimli modellerde (Qwen, MiniMax) aylık 300 ücretsiz kredi kazanırsınız ve cihazlar arasında hafıza ve ayarlar için isteğe bağlı bulut senkronizasyonu olur. Senkronizasyon özellik bazındadır, her zaman iptal edilebilir. Kendi API anahtarınızı getirin ve Ava hesab olmadan tamamen çalışır.","start.local-vs-cloud#2#c":"Kural: Yerel kutsaldır. Bulut ise eklemelidir.","start.first-model#title":"Bir yapay zeka seçmem gerekiyor mu?","start.first-model#0#p":"Rahatlayın: Yapay zekayı siz seçmezsiniz. Ava her adım için doğru olanı otomatik olarak seçer, böylece düşünmenize gerek kalmadan iyi sonuçlar alırsınız.","start.first-model#1#p":"Seçebileceğiniz tek şey bir yönlendirme stilidir — ve varsayılan neredeyse herkes için uygundur. Diğerlerine sadece belirli bir neden için ihtiyacınız vardır.","start.first-model#2#h":"Üç stil","start.first-model#3#li0":"Maestro — varsayılan. Dengeli, güvenilir, öngörülebilir. Emin değilseniz? Bu doğru seçim.","start.first-model#3#li1":"Supernova — ağır, çok adımlı işler için, işin her parçasına farklı bir uzman koymaya değer olduğunda.","start.first-model#3#li2":"Aurora — verilerinizin AB içinde kalması gerektiğinde (kamu sektörü, sağlık, katı gizlilik). Tamamen Avrupa menşeli, açık ağırlıklı yapay zeka üzerinde çalışır.","start.first-model#4#p":"Sohbetin üstündeki model seçiciden istediğiniz zaman geçiş yapın. Hiçbir şey sabitlenmiş değil.","start.first-model#5#c":"Belirli bir modeli kendiniz mi yönetmek istersiniz? Evet — \"Detayları göster\"i açın.","models.routing#deeper#1#h":"Yan Yana","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Koordinatör","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B aktif, 1M bağlam)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B aktif, 262K bağlam)","models.routing#deeper#2#td1.0":"Oluşturucu","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (koordinatörü yeniden kullanır)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B yoğun, 256K bağlam)","models.routing#deeper#2#td2.0":"Orta Seviye Uzmanlar","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (kod inceleyici, gerçek kontrolörü, keşif, tarama aracı, güvenlik doğrulayıcısı vb.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Mimar, Doğrulayıcı, Sıralayıcı, Eğitmen, Raporlayıcı vb.)","models.routing#deeper#2#td3.0":"Hafif Seviye / Niyet Filtresi","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Keşifçi, Doğrulayıcı, Sıralayıcı, Sorgulayıcı, Birleştirici)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Yoğun Uzmanlar","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Araştırmacı, Sorgulayıcı, CVE Araştırmacısı, Fikir Üretici, Gerçek Kontrolörü)","start.glossary#1#td7.1":"Ava'nın bir eylemin maliyetini ölçmek için daha basit birimi; böylece token hesaplarıyla uğraşmazsınız. Planlar aylık bir paketle birlikte gelir.","start.glossary#1#td8.0":"API anahtarı","start.glossary#1#td8.1":"Hesabınız üzerinde ücretli bir hizmeti (örneğin bir yapay zeka modelini) kullanabilen yazılımlar için özel bir şifredir. Kendi anahtarınızı getirmek istiyorsanız sadece buna ihtiyacınız var.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Kendi Anahtarını Getir.\" Ava'nın yönettiği erişim yerine kendi API anahtarınızı kullanmak. İsteğe bağlı — zaten bir sağlayıcıya doğrudan ödeme yapanlar için.","start.glossary#1#td10.0":"Yerel Odaklı","start.glossary#1#td10.1":"Verileriniz varsayılan olarak kendi bilgisayarınızda bulunur. Senkronizasyonu açana kadar hiçbir şey yüklenmez. \"Yerel olan kutsaldır.\"","start.glossary#1#td11.0":"İzin Modu","start.glossary#1#td11.1":"İşler yapmadan önce Ava'nın ne kadar temkinli olacağı — her seferinde sormak, sadece riskli işlerde sormak ya da direkt devam etmek. Seviyeyi siz belirlersiniz.","start.glossary#1#td12.0":"Bağlam Penceresi","start.glossary#1#td12.1":"Bir modelin aynı anda zihninde tutabileceği metin miktarı — yani kısa süreli hafızası. \"1M bağlam\" yaklaşık bir milyon kelime anlamına gelir. Daha büyük = unutmadan daha fazlasını okuyabilir.","start.glossary#1#td13.0":"Dosya Değişikliği","start.glossary#1#td13.1":"Bir dosyada tam olarak neyin değişeceğini yan yana gösteren görünüm — eskisi bir tarafta, yenisi diğer tarafta. Ava herhangi bir değişiklik yapmadan önce bunu görürsünüz ve onaylarsınız.","start.glossary#1#td14.0":"Depo (Repo)","start.glossary#1#td14.1":"Değişiklikleri takip eden bir proje klasörüdür, genellikle Git ile kullanılır. Eğer bu sizin için henüz anlamsız geliyorsa, sadece \"projenizin bulunduğu klasör\" demektir.","start.glossary#1#td15.0":"İstem","start.glossary#1#td15.1":"Yapay zekaya yazdığınız şeydir — sorunuz veya talimatınız.","start.glossary#2#c":"Bir kelimeyi hala mı çözemiyorsunuz? Sohbet modunda Ava'ya sorun — \"X ne anlama geliyor?\" — ve seviyenize göre açıklayacaktır.","models.routing#title":"Yönlendirme — Ava modelleri nasıl seçiyor","models.routing#0#p":"Kısacası: Hangi yapay zeka modelini kullanacağınızı seçmenize gerek yok. Ava bunu sizin için yapar, işin her aşaması için en iyi aracı seçer — tıpkı iyi bir yöneticinin doğru görevi doğru kişiye vermesi gibi.","models.routing#1#p":"Üç tarzdandan birini seçersiniz — Maestro, Supernova veya Aurora — ve Ava her iş parçasını onu en iyi yöneten modele gönderir. Varsayılan Maestro'dur, her planda aktiftir ve neredeyse herkes için iyi bir seçimdir.","models.routing#2#h":"Neden yönlendirme yapmalı?","models.routing#3#p":"Her adıma doğru modeli yerleştirmek, her şeyi tek büyük ve pahalı bir modelde çalıştırmaktan daha az maliyetlidir — ve daha iyi sonuç verir, çünkü her model en iyi olduğu alanda çalışır. Hangi modelin hangisi olduğunu bilmenize gerek kalmadan sabit maliyet ve yüksek kalite elde edersiniz.","models.routing#4#c":"Üç tarz da platform kredileri ve kendi anahtarlarınızla çalışır. Kendi anahtarınızla yönlendirmeyi atlayıp tek bir modeli doğrudan kullanabilirsiniz. Tüm model listesi \"Detayları Göster\" bölümündedir.","models.routing#deeper#0#c":"Aşağıdaki \"B\" sayıları milyarlarca parametreyi temsil eder — kabaca bir modelin 'beyninin' boyutu budur; daha büyük genellikle daha akıllı ama daha yavaş ve pahalı demektir. Bu teknik bir detaydır; Ava'yı kullanmak için buna ihtiyacınız yoktur.","models.routing#deeper#2#td5.0":"Sohbet","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Görsel Üretim Yönetimi","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Görsel Yetenek","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (görüntü kodlayıcı sıfırdan eğitildi)","models.routing#deeper#2#td8.0":"Uzun Metin Yazımı","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Veri Konumu","models.routing#deeper#2#td9.1":"Karışık (Alibaba Bulut)","models.routing#deeper#2#td9.2":"Karışık (DeepSeek + Alibaba Bulut)","models.routing#deeper#2#td9.3":"Yalnızca AB · Açık Ağırlıklar","models.routing#deeper#2#td10.0":"Durum","models.routing#deeper#2#td10.1":"Aktif · Tüm Planlar","models.routing#deeper#2#td10.2":"Çok Yakında","models.routing#deeper#2#td10.3":"Çok Yakında","models.routing#deeper#2#td11.0":"En Uygun Kullanım","credits.overview#8#li4":"Koordinasyon — 10 kredi. Tam kişilik iş akışının başlatılması (Koordinatör + çoklu kişilik görevi).","credits.overview#8#li5":"Görüntü oluşturma — 12 kredi. Creative Studio üzerinden Hailuo image-01.","credits.overview#8#li6":"Video oluşturma — 150 kredi. Hailuo 02 Pro 1080p 6 saniyelik klip.","credits.overview#8#li7":"Ses oluşturma — 10 kredi. Speech 2.8 HD sentezleme.","credits.overview#8#li8":"Müzik oluşturma — 50 kredi. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Arka plan kaldırma — 2 kredi.","credits.overview#9#h":"Model bazlı çarpanlar","credits.overview#10#p":"Bu kısım merak edenler içindir — Ava'yı kullanmak için ihtiyacınız yok. Bir çarpan, bir eylemin arkasındaki modelin maliyetine göre kredi ücretini yukarı veya aşağı ölçeklendirir; yani daha ağır modeller biraz daha pahalıya gelir. (\"Net kâr marjı\", projenin kendi masraflarını ödedikten sonra elinde tuttuğu paydır — değerin size dönmesi için bunu düşük tutmayı hedefliyoruz.)","credits.overview#11#p":"Daha ağır modeller işlem maliyetini çarparak kredilerin düz bir aralık yerine gerçek harcamayı takip etmesini sağlar. Yaklaşık %55 net kâr marjına göre ayarlanmıştır.","credits.overview#12#li0":"0.6× — Mistral Small 4 (Aurora'nın uzman koltuğu). 1'in altında çünkü Mistral Small 4, Qwen 3.6 Plus referansından daha ucuzdur.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Temel oran.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (Aurora koordinatörü). Qwen 3.6 Plus referansı ile yaklaşık eşdeğer.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (Maestro koordinatörü).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (Supernova koordinatörü + ağır uzmanlar). Yayınlanan V4 Pro oranında marj dengesini sağlamak için 5.0×'ten yeniden ayarlandı.","credits.overview#13#c":"Anthropic modelleri (Claude Opus / Sonnet / Haiku) kredi faturalandırmasını tamamen atlar — bunlar yalnızca BYOK'dur ve doğrudan Anthropic'e ödeme yaparsınız. Kendi anahtarınızla kullanılan diğer herhangi bir BYOK sağlayıcı için de aynı durum geçerlidir.","credits.overview#14#h":"BYOK ve krediler","credits.overview#15#p":"BYOK (\"kendi anahtarını getir\" — bir AI sağlayıcısı için kendi hesabınızı ve o ödenmiş hesabı yazılımın kullanmasına izin veren özel bir şifre olan anahtarı sağlarsınız) zaten doğrudan bir AI sağlayıcısına ödeme yapan insanlar içindir. Eğer siz değilseniz, bu bölümü tamamen görmezden gelebilirsiniz.","credits.overview#16#p":"Kendi anahtarını getir istekleri platform altyapısını tamamen atlar — çağrı doğrudan Ava'dan sağlayıcıya gider, siz sağlayıcıya ödeme yaparsınız, kredi tüketilmez. Tek istisna, bir BYOK oturumu alt bir görev için yönetilen katman kişiliği başlattığında; Ava'nın koordinasyon yüzeyi kullanıldığı için kredi düşümü yine de uygulanır.","credits.overview#17#h":"Bakiyenizi nerede kontrol edebilirsiniz","credits.overview#18#li0":"Uzantı — Ayarlar → Hesap, veya sohbet başlığındaki kredi etiketi.","credits.overview#18#li1":"IDE — Hesap panosu karesi mevcut bakiyeyi ve harcama hızını gösterir.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard bakiyeyi, geçmişi ve yenileme tarihini gösterir.","credits.overview#19#c":"Yerel odaklı: Ava, Özel Model kartında hesap olmadan çalışır (Ollama, LM Studio, vLLM veya herhangi bir OpenAI uyumlu uç nokta). Kredi yok, platform jetonu yok — modeliniz, makineniz, faturanız sıfır.","concepts.modes#title":"Modlar — Ava'nın zihin halleri","concepts.modes#0#p":"Bir mod, Ava'nın bulunduğu zihniyet halidir — tıpkı bir meslektaşının şapka değiştirmesi gibi. Aynı kişi, aynı hafızası var ama bir yapımcı bir öğretmenden farklı düşünür. Modu siz seçersiniz ve bu onun nasıl davrandığını ve hangi yardımcıları getireceğini değiştirir. İstediğiniz zaman mod seçicisiyle veya iki karakterlik bir kısayol yazarak geçiş yapabilirsiniz.","concepts.modes#2#h":"Hangisini istersiniz?","concepts.modes#3#p":"Ne yapmak istediğinizden başlayın — mod buna göre şekillenir:","concepts.modes#4#li0":"İnşa edilmesini veya değiştirilmesini istiyorum → Kod (>>). Siz tarif edersiniz, o inşa eder, her değişikliği önce size gösterir. Büyük işler için tam yardımcı ekibi devreye girer.","concepts.modes#4#li1":"Herhangi bir değişiklikten önce bir plan istiyorum → Plan (::). Önce düşünür ve onaylamanız veya düzenlemeniz için bir plan sunar. Bu modda dosyalarınıza dokunmaz.","concepts.modes#4#li2":"Sadece konuşmak veya sormak istiyorum → Sohbet (..). Hafızası, haberleri ve hava durumu olan bir düşünce ortağı. Dosya değişikliği yok, kod yok — sadece sohbet.","concepts.modes#4#li3":"Bir şey öğrenmek istiyorum → Öğret (??). Sizin için özel hazırlanmış gerçek bir kurs: dersler, sınavlar, hepsi. Her planda sonsuza kadar ücretsiz. Yeniyseniz mükemmeldir.","concepts.modes#4#li4":"Projemin güvenlik açıklarını kontrol etmemi istiyorum → Güvenlik (!!). Bir ekip, standart web açıkları listesini (\"OWASP\" kategorileri) ve bilinen raporlanan kusurları (\"CVE\" olarak adlandırılan) tarar, ardından her sorunun ciddiyetine göre sıralanmış bir rapor sunar. Bu geliştiriciler içindir — eğer siz değilseniz atlayın.","concepts.modes#4#li5":"Fikirler istiyorum → Beyin Fırtınası (**). Gerçek durumunuza dayalı seçenekler üretir, zayıf olanların açığını bulur ve kalanları sonraki adımlara dönüştürerek rafine eder.","concepts.modes#4#li6":"Bir belge yazmak istiyorum → Yaz (<<). Raporlar, teklifler, mektuplar, makaleler — Markdown'da taslak yazar ve bölüm bölüm rafine ederek markalı bir Word belgesi veya PDF dışa aktarır. Kod yok, sadece yazma.","concepts.modes#5#c":"\"Yardımcı ekibi\" (kişilikler) tamamen arka planda çalışır — onlarla doğrudan konuşmazsınız. Daha kapsamlı bir yanıt alırsınız. İsimlerini bilmenize gerek yoktur.","concepts.modes#6#c":"Sohbet sırasında modları değiştirebilirsiniz. Hafızanız taşınır; uzmanlar yeni moda uygun şekilde sıfırlanır.","concepts.tasks-journal#title":"Görevler ve günlük","concepts.tasks-journal#0#p":"Ava sizin için üç tür not tutar ve bunları karıştırmak kolaydır. Hatırlamanın hızlı yolu: hafıza hakkında bildikleridir, görevler henüz yapmanız gerekenlerdir, günlük ise işlerin nasıl gittiğine dair bir gündüzdür. Hangisini ne zaman kullanacağınız burada.","concepts.tasks-journal#1#li0":"Hafıza — kalıcı gerçekler. Tercihler, kararlar, kalıplar. Tekrar tekrar sorulduğunda, nadiren manuel olarak oluşturulur.","concepts.tasks-journal#1#li1":"Görevler — yapılacaklar. Son tarih ve durumlu aksiyon öğeleri. Bitince işaretlersiniz.","concepts.tasks-journal#1#li2":"Günlük — düşünce. Günlük kayıt, çift giriş (sizin ve Ava'nın oturum hakkındaki gözlemleri). Ruh hali takibi, oturum incelemeleri, yarın için bağlam için yararlı.","concepts.tasks-journal#2#p":"Ava mantıklı olduğunda hepsine yazar. Bunlardan herhangi birine doğrudan panelden yazabilirsiniz. Kullandığınız yer tek bir yere kilitlenmiş hiçbir şey yok — bir yerde (örneğin komut satırı aracında) oluşturduğunuz bir görev, her yerde (masaüstü uygulama gibi) otomatik olarak görünür.","concepts.permissions#title":"İzinler — güvenliğiniz için ayar","concepts.permissions#0#p":"İzinler, güvenliğiniz için bir ayardır. Ava'nın bilgisayarınızda bir şey yapmadan önce onayınızı isteyip istemeyeceğine, yoksa devam edip etmeyeceğine karar verir. Her şey hakkında sormasını, sadece riskli şeyler hakkında sormasını veya ona güvenip çalıştırmasını ayarlayabilirsiniz ve bunu istediğiniz zaman değiştirebilirsiniz. Emin değilseniz varsayılan bırakın, sorun olmaz.","concepts.permissions#1#p":"Ava'nın 60 aracı vardır (\"araçlar\" yapabileceği eylemlerdir — dosya okuma, web arama vb.). Her araç bir kategoriye aittir (dosya işlemleri, terminal, Git, web, medya, veritabanı, sistem, belgeler, hafıza, öğrenme). Her araç çağrısı çalışmadan önce izin kapısından (önce sizi sorup sormayacağına karar veren bir kontrol noktasından) geçer. Ne otomatik onaylanacak, ne bir kez soracak ve ne de her zaman soracak kontrolü sizde.","concepts.permissions#3#p":"Dengeli varsayılandır. Davranışlarını denetlediğinizde (her adımı yakından izlemek için) Sıkı. Sadece gitmesini istediğinizde Otonom.","concepts.permissions#4#c":"Otonom denetimsiz değildir. Planlar, netleştirme soruları ve açık kullanıcı sorgusu hâlâ girdinizi bekler. Geri döndürülemez işlemler (Git force-push, veritabanı silmeleri) moddan bağımsız olarak her zaman onay ister.","concepts.interjection#title":"Ava'yı yönlendirme ve durdurma","concepts.interjection#0#p":"Siz her zaman yönetici konumundasınız. Ava çalışırken ya onu akışını bozmadan yeni bir yöne sevk edebilir ya da anında durdurabilirsiniz. İki düğme, iki sonuç — bu sayfanın tamamı bununla ilgili.","concepts.desktop-safety#3#li2":"Değiştirilebilir ve geri alınabilir — bir metin alanına yazı yazmak, yapıştırmak, bir uygulama açmak veya bir web adresine gitmek gibi eylemler. 'Soru' Modu'nda onay ister; Beyaz Liste içindeki 'Sürücü' modunda ise otomatik gerçekleşir.","concepts.desktop-safety#3#li3":"Değiştirilebilir ve geri alınamaz — mesaj göndermek, form doldurup göndermek, ödeme yapmak, silmek, onaylamak veya yayınlamak gibi eylemler. İzin seviyesi ne olursa olsun her zaman onay ister. Onaylar hiçbir zaman hafızada tutulmaz.","concepts.desktop-safety#3#li4":"Özel Yetkiler — UAC yükseltme, sudo komutları, kayıt defteri değişiklikleri veya kimlik bilgisi istekleri. Varsayılan olarak yasaktır. Her oturumda tek seferlik açık rıza (opt-in) gerektirir.","concepts.desktop-safety#4#h":"Asla Önbelleğe Alınmayan Onaylar","concepts.desktop-safety#5#p":"Rakiplerin hepsi onayları hafızada tutar (\"evet\" dediğinizi hatırlar ve bir dahaki sefere tekrar kullanır). Bu, \"prompt enjeksiyonu\" adı verilen saldırılar için en büyük kapı aralığıdır; yani tuzaklanmış bir web sayfasının yapay zekaya gizli talimatlar sızdırıp sizi aleyhinize harekete geçirmesidir. Eğer onaylar saklanırsa, zarar görmüş bir sayfa daha önce verdiğiniz \"evet\"e binerek ilerleyebilir. Ava asla saklamaz. Her değiştirilebilir ve geri alınamaz işlem için yeniden sorar.","concepts.desktop-safety#6#h":"Gizli Bilgilerin Yönetimi","concepts.desktop-safety#7#p":"Şifreler, API anahtarları ve 2FA kodları (giriş yaparken size ikinci bir uygulamadan veya mesajdan gelen tek kullanımlık kodlar), gerçek değeri temsil eden yer tutucular olan opak işlemler aracılığıyla yönetilir. Ava \"{secret}\" görür, gerçek şifreyi değil. Gerçek değer asla onun hafızasına, etkinlik kayıtlarına veya \"okuduklarına\" girmez. Ayrı bir alt katman bunu son anda, tuşa basıldığı anda girer; böylece Yapay Zeka parçası buna hiç temas etmez.","reference.cli#title":"CLI Komutları","reference.cli#0#p":"Bu sayfa CLI içindir — yani butonlara tıklamak yerine terminal penceresinde yazarak etkileşime girdiğiniz Ava sürümü. Uzantıyı veya masaüstü uygulamasını kullanıyorsanız bu sayfayı tamamen atlayabilirsiniz. Burası klavye kullanımını tercih edenler içindir.","reference.cli#1#p":"CLI bir REPL'dir — sizin yazmanızı bekleyen, yazdıklarınızı çalıştıran ve ardından tekrar bekleyen bir istemdir. Bu eğik çizgi komutları ('/' ile başlayan talimatlar) istem üzerinden çalışır.","reference.cli#2#li0":"/help — komutları ve mevcut modu listeler.","reference.cli#2#li1":"/mode <isim> — modu değiştirir (çalışma, yazma, planlama, sohbet, öğretme, güvenlik, beyin fırtınası).","reference.cli#2#li2":"/model <kimlik> — oturumdan çıkmadan modeli değiştirir.","reference.cli#2#li3":"/clear — mevcut sohbeti temizler. Hafıza dokunulmaz kalır.","reference.cli#2#li4":"/history — bu projedeki geçmiş sohbetleri listeler.","reference.cli#2#li5":"/memory — hafıza tarayıcısını açar.","reference.cli#2#li6":"/tasks — görevleri listeler ve yönetir.","reference.cli#2#li7":"/journal — bugünün günlük girişini açar.","reference.cli#2#li8":"/settings — ayarlar menüsünü açar.","reference.cli#2#li9":"/exit — REPL'den çıkar.","reference.cli#3#h":"Başlatma Bayrakları","reference.cli#4#p":"Bayraklar, Ava'yı başlatırken eklediğiniz ekstra seçeneklerdir; her biri '--' ile başlar ve nasıl açılacağını belirlemenizi sağlar.","reference.cli#5#li0":"--mode <isim> — belirli bir modda başlatır.","reference.cli#5#li1":"--model <kimlik> — belirli bir model ile başlatır.","reference.cli#5#li2":"--permission <mod> — sıkı / dengeli / otonom.","concepts.interjection#1#p":"Ava, planını tamamlayana kadar veya siz durdurana kadar çalışmaya devam eder. Çalışırken araya girmenin (buna \"müdahale\" denir) iki yolu bulunur.","concepts.interjection#2#h":"Müdahale Edin — İptal Etmeyin, Yönlendirin","concepts.interjection#3#p":"Ava çalışırken yeni bir mesaj yazabilirsiniz. Mevcut görevini tamamlar, mesajınızı okur ve planını buna göre günceller. Hiçbir bağlam kaybolmaz. Akış sırasında yön değiştirmek, bilgi eklemek veya öncelikleri değiştirmek istediğinizde bunu kullanın.","concepts.interjection#4#h":"Kesin Durdurma — İptal Edin ve Temizleyin","concepts.interjection#5#p":"Escape tuşuna basın (CLI), Durdur düğmesine tıklayın (uzantı, IDE) veya bir durdurma komutu girin. O anki işlem iptal edilir, bekleyen araç çağrıları sonlandırılır ve sohbet yeni bir başlangıç için hazır olur.","concepts.interjection#6#c":"Önce müdahale edin. Kesin durdurma sadece gerçek bir sorun olduğunda kullanılmalıdır. Müdahale ederek süreci canlı tutarsınız.","concepts.desktop-personas#title":"Masaüstü Kişilikler","concepts.desktop-personas#0#p":"Bu sayfa merak edenler ve ileri düzey kullanıcılar içindir. \"Masaüstü otomasyonu\" (bazen \"bilgisayar kullanımı\" olarak da geçer) Ava'nın ekranınızda gerçekten gezinebileceği ve sizin adınıza uygulamaları kullanabileceği anlamına gelir — Gmail'i açmak, form doldurmak, mesaj göndermek gibi — sanki klavyede oturan bir insanmış gibi. Bunu güvenli yapmak için işi beş küçük yardımcı arasında bölüştürür; her birinin tek bir dar rolü vardır. Bunlarla doğrudan uğraşmazsınız; bu bölüm sadece kimin ne işe yaradığını gösterir.","concepts.desktop-personas#1#p":"Bir masaüstü görevinde (Ava'nın ekranınızı bir hedefe doğru yönettiği tek bir çalışma döngüsü) her adım, beş kişilik bir diziyle ilerler. Her kişiliğin tek bir görevi vardır ve sadece o görevi yapar. Bu ayrım, talimatların net olmasını, çıktıların düzenli kalmasını ve tasarım gereği eleştirel düşünülmesini sağlar.","concepts.desktop-personas#2#h":"Keşifçi","concepts.desktop-personas#3#p":"Ekranda şu an görünenleri rapor eder. Asla var olmayan öğeler uydurmaz. Planlama yapmaz. Element kimliklerini, isimlerini, sınırlayıcı kutuları (bboxes), güven skorlarını ve dayanak kaynağını (UIA, Playwright DOM veya OmniParser görüntü işleme) içeren bir ScreenState JSON döndürür.","concepts.desktop-personas#4#h":"Planlayıcı","concepts.desktop-personas#5#p":"Sıradaki tek eylemi belirler. Her adımda sadece bir eylem yapar — asla toplu işlem yapmaz. Geri alınabilir yolları tercih eder. Riski güvenlik sınıflandırmasına göre derecelendirir. Türü, hedefi, parametreleri, risk sınıfı, gerekçesi ve beklenen sonraki durum tahmini içeren bir ProposedAction JSON çıktısı üretir.","concepts.desktop-personas#6#h":"Eylemci","concepts.desktop-personas#7#p":"Planlayıcının önerdiği şeyi tam olarak uygular — onay aşaması geçtiğinde. Hiçbir uydurma yapmaz. Yeniden denemez. Başarısızlık dürüstçe raporlanır ve sonraki hamleyi Doğrulayıcı yönetir.","concepts.desktop-personas#8#h":"Doğrulayıcı","concepts.desktop-personas#9#p":"Eylemin gerçekleşip gerçekleşmediğini kontrol eder. Yeni gelen ScreenState'i Planlayıcının tahminiyle karşılaştırır. Sonuç olarak \"doğrulandı\", \"sapma oldu\" veya \"geri alma gerekli\" döner. Ayrıca döngü algılama yapar — zaten başarılı olan bir eylemi tekrarlamak bir sapmadır, doğrulama değildir.","concepts.desktop-personas#10#h":"Anlatıcı","concepts.desktop-personas#11#p":"Görev süresince kullanıcının duyduğu tek sestir. Her adımda tek bir geçmiş zaman cümlesi (\"Gmail açıldı.\", \"Oluştur'a tıklandı.\") yazar. Ayrıca yapılandırılmış denetim günlüğünü oluşturur. Bir şeyler ters gittiğinde bunu belirtir — asla sorunu gizlemez.","concepts.desktop-safety#title":"Masaüstü Güvenlik Sınıflandırması","concepts.desktop-safety#0#p":"Kısa özet: Ava ekranınızda herhangi bir şeye tıklamadan önce, eylemi risk seviyesine göre sınıflandırır. Ekranı okumak mı? Zararsız. Para göndermek veya bir şey silmek mi? Her zaman durur ve önce sizden izin alır — her seferinde, istisnasız. Aşağıdaki beş etiket, o risk merdiveninin basamaklarıdır. Bu biraz ileri düzey detay olsa da asıl mesaj basit: Tehlikeli işler her zaman sizin onayınızı gerektirir.","concepts.desktop-safety#1#p":"Her önerilen eylem, beş risk sınıfından birine atanır. Sınıflandırma üç unsuru birleştirir: ekrandaki hedefin ne olduğu, bunun sade bir dille açıklaması (\"semantik başlık\" — Ava'nın baktığı şeyi kendi kelimeleriyle tanımlaması) ve eylemin ayarları. Bunlar çeliştiğinde risk seviyesi yükseltilir (daha riskli kabul edilir). Yanlış pozitif (gereksiz yere sormak) sadece bir rahatsızlıktır. Ancak yanlış negatif (sorması gerekirken sormamak) ise ciddi bir hatadır.","concepts.desktop-safety#2#h":"Beş Sınıf","concepts.desktop-safety#3#li0":"Gözlemsel — UIA ağacını oku, ekran görüntüsüne bak, üzerine gel. Her zaman otomatik olarak izinlidir.","concepts.desktop-safety#3#li1":"Navigasyonel — kaydır, odak noktasını değiştir, menü aç. Drive modunda otomatik olarak izinlidir.","models.routing#deeper#2#td11.1":"Günlük işler, öngörülebilir maliyet","models.routing#deeper#2#td11.2":"Ağır çok adımlı işler için, her planda ileri düzey koordinatör","models.routing#deeper#2#td11.3":"GDPR'a sıkı uyumlu, kamu sektörü, egemen AB altyapıları","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Farklı katmanlarda Qwen yönlendirmesi, hafif kullanım. Qwen 3.6 Plus, koordinatör, Yapımcı, planlama, güvenlik, fikir üretimi ve uzun bağlam işlerini yönetir — özellikle 1 milyon kelime bağlamında hibrit doğrusal dikkat mekanizmasının işe yaradığı yerler burası. Qwen 3.5 Flash sohbet, görsel oluşturma yönetimi ve yukarı akış niyet kapısını ele alır; düşük derinlikli token hacminin çoğunda $0.07/$0.26 fiyatlandırma ve daha hızlı ilk token yanıt süresi ile kazanır. Qwen 3.5 Omni Plus görüntü girdisini üstlenir (Qwen 3.6 Plus'ın yerleşik görüntü yeteneği yok). Qwen 3.5 Plus, maliyet odaklı uzun içerik işlerini üstlenir. Birincil koordinatör bulunamazsa, öncelik sırası Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash şeklinde ilerler.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Çoklu uzman topluluğu. DeepSeek V4 Pro her alt görevi en uygun uzmana koordine eder ve dağıtır: Qwen 3.6 Plus tüm Yapımcı başlatmalarını çalıştırır, V4 Flash sohbet ve orta seviye gözden geçirme/denetim rollerini ele alır, Qwen 3.5 Flash hafif seviye sınıflandırma işini yapar, Qwen 3.5 Omni Plus görüntü girdisini üstlenir, Qwen 3.5 Omni Flash görsel oluşturma araç çağrılarını yönetir, Qwen 3.5 Plus maliyet duyarlı uzun form İçerik Yazarı rolünü taşır. Önemli yerlerde ileri düzey düşünme, token hacminin çoğunda ekonomik hız.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Avrupa yapay zeka altyapısı — tasarım gereği egemen. Üç katmanda sadece Mistral yönlendirme: Mistral Large 3 (675B/41B aktif seyrek karma uzman), koordinatör rolünü ve derinliğe ihtiyaç duyan ağır uzmanları — Araştırmacı, Meydan Okuyucu, CVE Araştırmacısı, Fikir Üretici, Gerçek Kontrolcüsü, Güvenlik Doğrulayıcısı — ve seyrek karma uzman verimliliğinin kazandığı uzun bağlam işini üstlenir. Mistral Medium 3.5 — Nisan 2026'da birleştirilmiş amiral gemisi, 128B yoğun, 256K bağlam, sıfırdan eğitilmiş görüntü kodlayıcısı, değiştirilmiş-MIT açık ağırlıklar, %77.6 SWE-Bench Doğrulanmış — asıl çalışma katmanını yürütür: Yapımcı başlatmaları, orta seviye uzmanlar (Mimar, Doğrulayıcı, Sıralayıcı, Öğretmen, Raporlayıcı), görüntü girdisi ve uzun form yazım. Mistral Small 4, niyet kapısında tek bir rolden sohbet ve görsel oluşturma yönetimine de genişledi — $0.15/$0.60 fiyatlandırması ve yapılandırılabilir düşünme yeteneği yüksek hacimli düşük derinlikli rotalarda haklarını kazanır. Açık ağırlıklar uçtan uca, hiç AB altyapısından çıkmaz. Aurora, bir model kullanılamaz olduğunda sessizce Mistral olmayan bir modele yönlendirmez; yönlendirici bunun yerine bir hata gösterir — bu onu \"Aurora\" yapan şeydir, sadece Mistral benzeri bir Maestro değil.","credits.overview#title":"Ava Kredileri — faturalandırma nasıl çalışır","credits.overview#0#p":"Krediler, Ava'nın ne kadar kullandığınızı saymanın basit yoludur — tıpkı telefon paketindeki dakikalar gibi. Her plan, ücretsiz olan dahil olmak üzere bir kredi havuzuyla gelir ve Ava'nın yaptığı her şey (size cevap verme, resim oluşturma) birkaç krediyi harcar. İşte temel mantık bu. Aşağıdaki detay, tam olarak neyin ne kadar tuttuğunu bilmek istediğiniz zaman içindir.","credits.overview#1#p":"Ava, faturayı ham tokenlara göre değil, kredilere göre keser. (Bir \"token\", yapay zeka modellerinin okuyup yazdığı küçük metin parçasıdır — yaklaşık birkaç harf — çoğu hizmet size token başına ücret yükler, bu da tahmin etmeyi zorlaştırır.) Bir kredi, bir iş birimini kapsar — bir sohbet turu, bir kişi başlatma (görevin bir parçasını yapan bir yardımcı), bir görsel oluşturma. Modelin hangisi çalıştığına bakmadan bir eylemin ne kadar tutacağını bilebilirsiniz. Aynı sohbet turu, Maestro onu Qwen 3.6 Plus'a yönlendirse de Supernova onu V4 Pro'ya yönlendirse de aynı maliyete sahiptir.","credits.overview#2#h":"Planlar","credits.overview#3#p":"Her plan, tüm özelliklere erişime sahiptir — model erişimi, Creative Studio, tüm yedi mod, tam kişilik senaryosu. Daha yüksek katmanlar daha fazla kredi ve daha yüksek hız sınırı tavanı satın alır, kilitli özellikler değil.","credits.overview#4#li0":"Ücretsiz — ayda $0. 300 kredi. Dakikada 20 istek hız sınırı. Kart gerekmez.","credits.overview#4#li1":"Pro — ayda $19. 5.000 kredi. Dakikada 60 istek.","credits.overview#4#li2":"Ultra — ayda $39. 10.000 kredi. Dakikada 120 istek.","credits.overview#4#li3":"Kurumsal — ayda $79. 20.000 kredi. Dakikada 200 istek.","credits.overview#5#c":"Aboneliğiniz aktifken kullanılmayan krediler sonraki aya geçer — zorunlu iade yoktur. Yüklemeler abonelik havuzuna eklenir: 750 kredi için $3, 2.000 için $8, 4.000 için $15.","credits.overview#6#h":"Şeylerin Maliyeti","credits.overview#7#p":"Eylem başına maliyet tablosu — her eylem çalıştığında kredi havuzunuzdan ne düşülür. (Bir \"önbellek eşleşmesi\", Ava'nın zaten yaptığı işi tekrar yapmak yerine yeniden kullandığı durumdur; bu olduğunda daha az ödersiniz — ücret %70 düşer veya DeepSeek V4 Pro gibi çıktı ağırlıklı modellerde %50 olur.)","credits.overview#8#li0":"Sohbet turu — 2 kredi. Herhangi bir modda tek bir geri dönüşlü konuşma.","credits.overview#8#li1":"Hafif çağrı — 1 kredi. Niyet kapısı, sınıflandırma, tek atış okuma.","credits.overview#8#li2":"Ağır kişilik — 3 kredi. Mimar, Araştırmacı, CVE Araştırmacısı, Fikir Üretici (derinlik ≥ 4).","credits.overview#8#li3":"Hafif kişilik — 1 kredi. Keşifçi, Doğrulayıcı, Sıralayıcı, Meydan Okuyucu (derinlik ≤ 2).","reference.cli#5#li3":"--project <path> — proje kök dizinini açıkça belirler.","reference.desktop-budget#title":"Masaüstü bütçe sınırları","reference.desktop-budget#0#p":"Ava senin adına masaüstünü yönetirken — tıklama, yazma, uygulama açma gibi — her çalıştırma işlemine bir \"yörünge\" denir. Bu sayfa, herhangi bir çalıştırmanın çok uzun sürmesini veya çok maliyetli olmasını engelleyen güvenlik sınırlarını açıklıyor. Özetle: aşırıya kaçmadan önce her zaman durur ve kontrol eder. Detayları istersen sayısal değerler burada yer alıyor.","reference.desktop-budget#1#p":"Her yörünge, üç eşzamanlı kısıtlama (katı sınır) altında çalışır. İlk vurulan kazanır. Yörünge, bir ihlal durumunda sessizce devam etmez — Anlatıcı (olup biteni sana anlatan yardımcı) duraksar ve ne yapacağını sorar.","reference.desktop-budget#2#h":"Üç katı sınır (varsayılan)","reference.desktop-budget#3#li0":"Adım sayısı — 30 adım","reference.desktop-budget#3#li1":"Token bütçesi — 500.000 token","reference.desktop-budget#3#li2":"Gerçek zaman — 5 dakika","reference.desktop-budget#4#h":"Görev maliyet aralıkları","reference.desktop-budget#5#li0":"Basit (belge ara, bir sayfa aç) — 5–10 adım, ~70–135K token, ~$0,04–0,08","reference.desktop-budget#5#li1":"Orta (giriş yap, logları kontrol et, çıktı indir) — 15–25 adım, ~205–340K token, ~$0,12–0,21","reference.desktop-budget#5#li2":"Karmaşık (üç GitHub sorununu önceliklendir) — 25–30 adım, ~340–410K token, ~$0,21–0,25","reference.desktop-budget#6#p":"Yukarıdaki token rakamları, yörünge başına teknik sınırlardır; aylık tahsisatınız değil — bu kredilerde hesaplanır ve ücretsiz katmanın ayda 300'ü sohbet, kod ve birkaç otomasyon karışımı için rahatlıkla yeterlidir.","reference.desktop-budget#7#c":"Başlangıçta görev başına sınırları geçersiz kılabilirsiniz, ancak ihlaller her zaman bir karar noktası ortaya çıkarır. Bütçe asla sessizce harcanmaz.","reference.desktop-whitelist#title":"Masaüstü oturum beyaz listesi","reference.desktop-whitelist#0#p":"\"Beyaz liste\", Ava'nın masaüstünü yönetirken dokunmasına izin verdiğiniz uygulamalar ve web siteleri listesidir. Bu sayfa, bu izni nasıl verdiğinizi ve neden her seferinde sıfırlandığını açıklıyor. Kısa versiyon: Sadece izin verdiğin yerde hareket edebilir ve yeni bir yere gitmeden önce sorar.","reference.desktop-whitelist#1#p":"Bir masaüstü oturumunun başında Ava nerede hareket edebileceğini sorar. Basit Türkçe iş görür: \"Gmail, Cursor, Azure portalı.\" Bunu okur ve eşleşmeyi size onaylar (\"Gmail web, Cursor uygulaması, portal.azure.com\").","reference.desktop-whitelist#2#h":"Nasıl uygulanır","reference.desktop-whitelist#3#p":"Sadece görüntüleme eylemleri — ekran görüntüsü almak, ekrandaki düğme ve alanların listesini okumak (\"UIA ağacı\", Windows'un kendi haritası) — her yerde izinlidir, çünkü bir uygulamayı beyaz listeye ekleyip eklememe kararı vermek için ekranda ne olduğunu görmeniz gerekir. Bir şeyi değiştiren her şey listeden dışarıda engellenir; Ava duraksar ve bunu ekleyip eklememeyi sorar.","reference.desktop-whitelist#4#h":"Oturum odaklı, kasıtlı olarak","reference.desktop-whitelist#5#p":"Beyaz liste oturumlar arasında kalıcı değildir. \"Bu uygulamayı hatırla\" seçeneği yoktur. Her yeni yörünge, temiz bir kapsamla başlar. Tasarım gereği rahatsız edici — yeniden yetkilendirmeyi unutmak bir özellik, hata değil.","reference.desktop-whitelist#6#h":"Yörünge içinde eklemeler","reference.desktop-whitelist#7#p":"Bir yörünge sırasında üst menüden uygulamalar ekleyebilirsiniz: \"+ Uygulama İzin Ver\" küçük bir giriş açar. Ekle'ye dokunun ve yeni uygulama oturumun geri kalanı için aktif olur.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Bir resim, kısa bir video, şarkı veya seslendirme mi yapmak istiyorsunuz? Sadece tarif edin, Ava sizin için hazırlasın — tasarım veya ses yazılımına gerek yok.","features.creative-studio#1#p":"Görsel, video, müzik ve ses üretimi — kodunuzun iş akışının içine yerleştirilmiş durumda. Bir ikon, ürün taslağı, tanıtım videosu veya bir eğitim için seslendirme oluşturun. MiniMax tarafından desteklenir.","features.creative-studio#2#h":"Neler üretebilirsiniz","features.creative-studio#3#li0":"Görseller — komutdan PNG/JPG'ye. Arka plan silme tek bir çağrıyla mümkün.","features.creative-studio#3#li1":"Video — metin komutundan kısa AI videoları (MiniMax Hailuo).","features.creative-studio#3#li2":"Müzik — sözli enstrümantal veya vokal parçalar.","features.creative-studio#3#li3":"Ses — seçilebilir seslerle metinden sese çeviri.","features.creative-studio#4#p":"Creative Studio maliyetleri diğer her şeyle aynı kredi havuzundan düşer — tek havuz, tek rakam. Kendi MiniMax anahtarınızı BYOK yapın ve planınız için ücretsiz olur.","features.creative-studio#5#c":"Creative Studio ücretsiz katman için uygundur. Ücretli bir eklenti değildir.","features.desktop-automation#title":"Masaüstü Otomasyonu","features.desktop-automation#0#p":"Basitçe söylemek gerekirse: Ava fare ve klavyenizi devralarak sizin için görevler yapabilir — bir uygulama açmak, düğmelere tıklamak, bir formu doldurmak gibi — siz izlerken ve önemli olanları onaylarken.","features.desktop-automation#1#p":"Ava için yeni bir mod, ön ek @@. Masaüstünü gözlemler, ne yapılacağına karar verir ve bunu tamamlamak için UI otomasyonunu yönetir (ekranınızdaki uygulamaları sizin için kontrol eder). Gerçek makinenizde ve gerçek kimlik bilgilerinizle çalışır — bulut tarayıcı değil. Her seviyede sunulduğunda kullanılabilir olacak.","features.desktop-automation#2#h":"Neden biri daha?","features.desktop-automation#3#p":"Diğer tüm masaüstü otomasyonu ürünleri masanızda olduğunuzda başlattığınız şeylerdir. Ava ise hata takipçiniz gece 2'de çaldığında hala orada olandır — IDE çalışmaya devam eder, telefonunuz güvenli bir kanal üzerinden eşleşir, geri dönüşü olmayanları tek bir dokunuşla onaylarsınız.","features.desktop-automation#4#p":"Ayrıca oturumlar boyunca uygulamalarınızı nasıl gezeceğinizi de hatırlar. Diğer her ajan her seferinde bunları yeniden öğrenir. Hafıza farkı kullanıldıkça artar.","features.desktop-automation#5#h":"Nasıl Çalışır","features.desktop-automation#6#p":"Her adım beş kişilik bir dalga çalıştırır: Keşifçi gözlemler, Planlayıcı sonraki eylemi seçer, Oyuncu yürütür, Doğrulayıcı kontrol eder, Anlatıcı size ne olduğunu söyler. Yan servis en uygun maliyetli güvenilir referansı seçer — yerel uygulamalar için UIA, tarayıcılar için Playwright, başka bir yararlı ağaç yoksa OmniParser görseli.","features.desktop-automation#7#p":"Güvenlik ontolojisi, temel hiyerarşisi, acil durdurma anahtarları ve oturum beyaz liste modeli için kavram sayfalarına bakın."},"it":{"start.for-non-coders#6#li3":"Quando vuoi che lei faccia o modifichi qualcosa, chiedi pure — ti mostrerà sempre cosa sta per fare e attenderà il tuo \"sì\".","start.for-non-coders#7#c":"Ti imbatti in una parola che non conosci? Il glossario in lingua semplice (più avanti in questa sezione) spiega ogni termine senza dare nulla per scontato.","start.install#title":"Installa","start.install#0#p":"Scegli l'interfaccia che si adatta al tuo modo di lavorare. Puoi usarne più di una — Ava sincronizza la sua memoria tra tutte quando accedi.","start.install#1#h":"Estensione VS Code","start.install#2#li0":"Apri il pannello Estensioni in VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Cerca \"Ava Supernova\" e clicca su Installa.","start.install#2#li2":"Premi Ctrl+Shift+A (Cmd+Shift+A su macOS) per aprire il pannello della chat.","start.install#2#li3":"Segui la procedura guidata — scegli un modello, imposta la tua modalità di autorizzazione, fatto.","start.install#3#h":"IDE Desktop","start.install#4#li0":"Scarica l'installer per la tua piattaforma dalla pagina delle release.","start.install#4#li1":"Esegui il file. L'IDE si avvia con un flusso di benvenuto la prima volta.","start.install#4#li2":"Accedi per ottenere i token gratuiti della piattaforma, oppure incolla la tua chiave API per eseguire tutto in locale.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (o pnpm / yarn — scegli tu).","start.install#6#li1":"Esegui  ava  in qualsiasi directory del progetto.","start.install#6#li2":"Al primo avvio ti chiede un provider e un modello. Scegli e vai.","start.install#7#c":"Nessun account, nessun problema. Con la tua chiave API personale (BYOK) non devi mai accedere. Il piano gratuito è per i modelli gestiti dalla piattaforma.","start.for-non-coders#title":"Non hai mai scritto codice? Inizia qui","start.for-non-coders#0#p":"Se non hai mai scritto una riga di codice, sei esattamente la persona per cui Ava è stata creata. Non devi imparare gergo tecnico per iniziare: parli con lei in italiano semplice, come faresti con un amico esperto. Questa pagina è tutto ciò di cui hai bisogno per iniziare.","start.for-non-coders#1#h":"Cosa puoi fare oggi, senza esperienza","start.for-non-coders#2#li0":"Chiedile qualsiasi cosa, con parole normali — \"cosa fa questo file?\", \"perché la mia pagina è vuota?\", \"cos'è anche solo un database?\" Risponde in linguaggio semplice e ricorda la conversazione.","start.for-non-coders#2#li1":"Impara qualcosa da zero — dì \"insegnami Python da zero\" e costruirà per te un corso vero con lezioni e quiz. Questo è sempre gratis.","start.for-non-coders#2#li2":"Ottieni qualcosa di fatto — descrivi cosa vuoi (\"un pulsante che scarica le mie note\") e lei lo scrive, mostrandoti ogni modifica prima che accada.","start.for-non-coders#3#h":"Non devi capire tutto","start.for-non-coders#4#p":"Ava ha molta meccanica sotto il cofano — modalità, modelli, specialisti, routing. Vedrai queste parole nell'app e in queste guide. Ecco il segreto: puoi ignorare quasi tutto. Ava sceglie gli strumenti giusti e gli aiutanti giusti per te automaticamente. Le pagine tecniche ci sono quando diventi curioso, non perché ti servono per iniziare.","start.for-non-coders#5#h":"Un primo approccio semplice","start.for-non-coders#6#li0":"Installa Ava (pagina successiva) e apri la chat.","start.for-non-coders#6#li1":"Scrivi una domanda reale che hai. Qualsiasi cosa. Vedi come risponde.","start.for-non-coders#6#li2":"Prova la modalità apprendimento: scrivi \"insegnami\" e un argomento. Seguila.","concepts.memory#title":"Memoria — come Ava ricorda te","concepts.memory#0#p":"In parole semplici: Ava ricorda te. Dille qualcosa una volta — cosa ti piace, una decisione che hai preso — e lei la conserva, così non devi ripeterlo nella prossima chat o la settimana prossima. Questa è la notizia principale. Gli strati qui sotto spiegano solo come mantiene quella memoria ordinata nel tempo.","concepts.memory#1#p":"Ava ha una memoria persistente (\"persistente\" significa che rimane attiva anche dopo aver chiuso l'app) che sopravvive tra conversazioni, tra progetti e tra macchine se abiliti la sincronizzazione (la sincronizzazione copia la tua memoria tra i tuoi dispositivi). Non è un registro di chat. È una comprensione strutturata e ricercabile di chi sei, di cosa ti piace e di quello che hai deciso.","concepts.memory#2#h":"Cinque livelli","concepts.memory#3#li0":"Estrai — fatti chiave catturati da ogni messaggio in tempo reale.","concepts.memory#3#li1":"Rifletti — analisi più approfondite alla fine delle sessioni significative. Pattern, temi, contraddizioni.","concepts.memory#3#li2":"Accumula — correzioni e preferenze si accumulano nel corso di settimane e mesi.","concepts.memory#3#li3":"Analizza — il motore a grafo collega memorie correlate e segnala contraddizioni quando nuove informazioni confliggono con quelle vecchie.","concepts.memory#3#li4":"Consolida — memorie simili si fondono; quelle obsolete vengono eliminate. La memoria diventa più nitida col tempo, non più rumorosa.","concepts.memory#4#c":"I cinque livelli sopra funzionano da soli — non devi mai gestirli. Sono qui per mostrarti che la memoria migliora davvero col tempo invece di diventare un mucchio di disordine.","concepts.memory#5#h":"Richiamo","concepts.memory#6#p":"Quando fai una domanda, Ava cerca nella memoria per significato (\"ricerca semantica\" — capisce cosa intendi, così trova la memoria giusta anche se la esprimi diversamente), non solo per corrispondenza esatta di parole. Filtri specifici per modalità si applicano insieme — Modalità Chat richiama contesto personale, Modalità Lavoro richiama decisioni di progetto e pattern di codice.","concepts.memory#7#c":"La memoria è limitata per utente e per progetto (le tue memorie sono tue, tenute separate per persona e per progetto). Segreti e credenziali (password, chiavi) sono bloccati al confine di salvataggio — non possono mai finire nella memoria.","reference.models#11#h":"Porta la tua chiave","reference.models#12#p":"Una \"chiave API\" è una password privata che permette al software di utilizzare un servizio a pagamento sul tuo account. \"BYOK\" significa semplicemente \"porta la tua chiave\" — usare la tua invece della nostra. Incolla la tua chiave API nelle impostazioni. Le richieste BYOK vanno direttamente da Ava al provider (l'azienda che gestisce il modello) — non passano attraverso la nostra infrastruttura e non consumano token della piattaforma. Paghi il provider; noi non vediamo il traffico.","reference.models#14#c":"Per i punteggi dei benchmark, i tag delle funzionalità e il confronto diretto, consulta la pagina completa Modelli su ava-supernova.com/models. I prezzi mostrati sopra sono la nostra migliore interpretazione delle tariffe di ciascun provider al momento della pubblicazione — controlla sempre il sito web del provider prima di impegnarti in un carico di lavoro.","reference.personas#title":"Orchestrazione dei ruoli","reference.personas#0#p":"Un \"ruolo\" è un incarico di supporto che Ava svolge dietro le quinte per compiti più difficili — un esploratore, un pianificatore, un verificatore di fatti. Non parli mai direttamente con loro e non hai bisogno di capire questa pagina per usare Ava. È qui quando sei curioso di sapere come lei scompone un grande compito in un piccolo team di esperti.","reference.personas#1#p":"24 specialisti distribuiti su 5 team di modalità. Il Coordinatore (l'assistente che coordina gli altri) decide quale team eseguire, in che ordine e con quale contesto. La modalità Chat non ha ruoli — è la stessa Ava.","reference.personas#2#h":"Come funziona l'orchestrazione","reference.personas#3#li0":"Invii un messaggio in modalità Piano, Insegna, Sicurezza o Brainstorm (o una richiesta di Lavoro complessa).","reference.personas#3#li1":"Il Coordinatore legge la richiesta, sceglie il team della modalità e costruisce un piano di esecuzione — alcuni ruoli vengono eseguiti in sequenza, altri in onde parallele.","reference.personas#3#li2":"Ogni ruolo ha il proprio prompt di sistema, un elenco consentito di strumenti limitato e un pool di contesto condiviso su ciò che hanno trovato i ruoli precedenti.","reference.personas#3#li3":"L'ultimo ruolo produce un riepilogo, un piano o un report, a seconda della modalità.","reference.personas#3#li4":"Ava ti presenta il risultato. Approvi, modifichi o reindirizzi.","reference.personas#4#p":"L'elenco completo qui sotto è solo a scopo di riferimento — non c'è bisogno di memorizzare chi fa cosa. Ava assembla il team giusto per te.","reference.personas#6#c":"La modalità Lavoro invoca il team completo solo per compiti complessi. Le modifiche semplici vengono eseguite direttamente da Ava — nessun sovraccarico di orchestrazione.","reference.config#title":"Configurazione","reference.config#0#p":"Questa pagina mostra dove Ava conserva le sue impostazioni e i file sul tuo computer. Quasi mai dovrai toccarli manualmente: è l'app a gestirli per te. È qui se vuoi vedere, fare il backup o condividere quei file tu stesso.","reference.config#1#p":"Ava legge la configurazione (le sue impostazioni salvate) da due ambiti. Le impostazioni globali — quelle valide ovunque — risiedono in una cartella chiamata ~/.ava/ (il \"~\" è un'abbreviazione per la tua cartella home). Le impostazioni specifiche del progetto risiedono in una cartella .ava/ all'interno del progetto stesso.","reference.config#2#h":"Globale — ~/.ava/","reference.config#3#li0":"settings.json — preferenze del modello, modalità di permesso, personalità, lingua.","reference.config#3#li1":"memory/ — i tuoi ricordi globali (preferenze, decisioni che valgono ovunque).","reference.config#3#li2":"tasks.json — elenco dei compiti tra progetti.","reference.config#3#li3":"journal/ — voci del diario quotidiano, organizzate per data.","reference.config#4#h":"Progetto — .ava/","reference.config#5#li0":"instructions.md — istruzioni specifiche del progetto che Ava carica sempre. Contesto durevole (\"usiamo pnpm, non npm\", \"le chiavi API vivono in 1Password\").","reference.config#5#li1":"context.md — appunti sul progetto liberi opzionali.","reference.config#5#li2":"memory/ — ricordi limitati a questo progetto.","reference.config#5#li3":"datasets/config.json — configurazione per la cattura dei dataset, su base volontaria.","reference.config#6#c":"Aggiungi .ava/ al tuo .gitignore (un elenco di file che Git viene istruito a escludere dal progetto condiviso) se non vuoi condividere i ricordi con il tuo team. Mantieni instructions.md nel repository (la cartella del progetto condivisa): è così che Ava impara le convenzioni del progetto.","reference.shortcuts#title":"Scorciatoie da tastiera","reference.shortcuts#0#p":"Le scorciatoie da tastiera sono accelerazioni opzionali — ognuna di esse è anche un pulsante che puoi cliccare. Consulta questa sezione solo se vuoi interagire con Ava più velocemente usando la tastiera.","reference.shortcuts#1#p":"Scorciatoie per ambiente (ciascuno dei tre spazi in cui Ava opera: l'estensione VS Code, l'app desktop e il terminale). Personalizzali nelle impostazioni di ciascun ambiente. Non c'è bisogno di memorizzare l'elenco qui sotto.","concepts.desktop-grounding#title":"Gerarchia di ancoraggio desktop (Anteprima)","concepts.desktop-grounding#0#c":"Anteprima — come Scout decide quale fonte di ancoraggio usare ad ogni passo.","concepts.desktop-grounding#1#p":"Prima che Ava possa cliccare un pulsante, deve capire davvero cosa c'è sul tuo schermo e dove si trovano le cose — questo è l'\"ancoraggio\" (capire cos'è ogni elemento sullo schermo e la sua posizione esatta). Ha tre modi per farlo e sceglie quello più affidabile che funziona per l'app che stai usando. Questo è un dettaglio tecnico avanzato; il punto è semplicemente che preferisce metodi solidi e precisi rispetto a indovinare da un'immagine.","concepts.desktop-grounding#2#p":"Tre livelli, valutati in ordine. Vince la fonte affidabile più economica.","concepts.desktop-grounding#3#h":"1. Finestra browser → Playwright DOM","concepts.desktop-grounding#4#p":"Se la finestra attiva è un browser web, Ava legge la struttura stessa della pagina (il \"DOM\" — la lista sottostante di ciò che c'è su una pagina) invece di indovinare dall'immagine. Leggere la struttura è circa 10× più affidabile che guardare i pixel a occhio nudo — sa esattamente dove si trova ogni pulsante e quando la pagina ha finito di caricarsi. Questa è la strada principale per tutto ciò che è sul web, non un piano di riserva.","concepts.desktop-grounding#5#h":"2. App nativa con UIA → Automazione interfaccia utente Windows","concepts.desktop-grounding#6#p":"Per le normali app desktop su Windows, Ava legge una mappa di accessibilità integrata (\"UIA\", gli stessi dati usati dai lettori vocali per descrivere una finestra) — elenca ogni controllo, il suo nome e dove si trova. Se quella mappa restituisce almeno cinque elementi utilizzabili e nominati, si fida e li usa.","concepts.desktop-grounding#7#h":"3. UIA vuota o inutilizzabile → Visione OmniParser","concepts.desktop-grounding#8#p":"Quando quella mappa manca o è inutile (alcune app, giochi e schermi remoti non ne forniscono una), Ava ricade sull'effettivo sguardo allo screenshot. Uno strumento di visione (OmniParser) individua le aree cliccabili e etichetta cosa rappresenta ciascuna, trasformando l'immagine di nuovo in una lista su cui può agire — combinata con qualsiasi piccolo contributo che la mappa di accessibilità abbia fornito.","concepts.desktop-grounding#9#c":"OmniParser richiede un consenso esplicito la prima volta che Ava ne ha bisogno, con un chiaro avviso sulla privacy. Gli utenti BYOK possono indicare la propria implementazione locale di OmniParser.","concepts.desktop-kill-switches#title":"Interruttori di emergenza desktop (Anteprima)","concepts.desktop-kill-switches#0#c":"Anteprima — tre modi indipendenti per interrompere una traiettoria in corso. Basta uno solo per funzionare.","concepts.desktop-kill-switches#1#p":"Un \"interruttore di emergenza\" è esattamente quello che dice la parola — un modo d'emergenza per fermare Ava istantaneamente mentre controlla il tuo schermo. La parte rassicurante: ce ne sono tre, costruiti separatamente, quindi se uno fallisce un altro funziona comunque. Non devi imparare tutti e tre. Sappi solo che quando qualcosa sembra sbagliato, puoi sempre fermarla, e la fermata più forte (l'interruttore di panico qui sotto) non dipende dalla collaborazione di Ava.","concepts.desktop-kill-switches#2#p":"Dopo aver letto ogni incidente pubblico di autonomia (casi reali in cui agenti AI hanno ignorato comandi di arresto, eliminato archivi email, cancellato dischi), abbiamo costruito tre interruttori di emergenza su tre livelli diversi. Nessuno di essi dipende dal modello AI stesso — se Ava è bloccata o non risponde, puoi ancora fermarla.","concepts.desktop-kill-switches#3#h":"Pausa — barra spaziatrice o il pulsante Pausa","concepts.desktop-kill-switches#4#p":"Si ferma al prossimo passo. Riprendibile. Usalo quando vuoi intervenire senza perdere il filo.","concepts.desktop-kill-switches#5#h":"Stop — Esc o il pulsante Stop","concepts.desktop-kill-switches#6#p":"Aborto pulito. Il narratore riassume cosa è stato fatto finora. Non riprendibile. Il registro di audit viene aggiornato.","concepts.desktop-kill-switches#7#h":"Terminazione di emergenza — triplo-Esc o Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"È la fermata più drastica in assoluto. Un piccolo programma watchdog separato chiude forzatamente la parte di Ava che controlla il tuo schermo. Non aspetta che l'IA risponda, non ha bisogno che la finestra dell'app sia attiva, e non gli importa in che stato siano le cose — si limita a spegnerla. È questa da usare quando qualcosa va davvero storto.","concepts.desktop-kill-switches#9#p":"Tutti e tre funzionano anche dall'app compagna. Qualsiasi dei due motori può interromperlo.","reference.tools#title":"Riferimento agli strumenti","reference.tools#0#p":"Questo è l'elenco completo di tutti gli strumenti di Ava — uno \"strumento\" è solo un'azione specifica che può compiere, come leggere un file o eseguire una ricerca. Non hai bisogno di leggere questa pagina. Ava sceglie lo strumento giusto lei stessa ogni volta. È qui quando sei curioso di sapere esattamente cosa può fare.","reference.tools#1#p":"La cassetta degli attrezzi integrata completa. Ogni strumento qui è registrato nel runtime principale (il motore alla base di tutte e tre le interfacce) ed è disponibile per Ava quando la modalità e la modalità di autorizzazione lo permettono. Filtra per categoria o rischio.","reference.tools#2#p":"Non c'è bisogno di memorizzare nulla — la tabella qui sotto è solo una scheda di riferimento.","reference.tools#4#h":"Livelli di rischio","reference.tools#5#li0":"Sicuro — legge le cose senza modificare nulla. file_read, glob (trova file per modello di nome), grep (cerca testo all'interno dei file), git_status (Git è il sistema che tiene traccia delle modifiche al tuo progetto).","reference.tools#5#li1":"Scrivere — modifica file, salva un punto di controllo del tuo lavoro (un \"commit\"), o produce qualcosa di nuovo. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Pericoloso — esegue comandi sul tuo computer (il \"terminale\"), controlla il desktop, accede a internet, o interroga database. bash, browser, desktop_*.","reference.tools#6#c":"Gli specialisti persona hanno le proprie liste di strumenti consentiti. Scout può leggere ma non scrivere. Builder ha accesso completo. Challenger non ha strumenti affatto — il suo compito è mettere in dubbio il piano.","reference.models#title":"Modelli","reference.models#0#p":"Un \"modello\" è il cervello IA che pensa — Qwen, DeepSeek, Mistral e altri. Questa pagina elenca tutti i modelli che Ava può utilizzare. In sintesi: non devi sceglierne uno. Ava sceglie il modello giusto per ogni passaggio lei stessa. Procedi con la lettura solo se vuoi capire o sovrascrivere questa scelta.","reference.models#1#p":"Tutti i modelli a cui Ava può indirizzare, più le tre strategie di orchestrazione — le regole che decidono quale modello gestisce ogni parte di un compito. Scegli una modalità di instradamento e lascia che Ava assegni, oppure scegli un singolo modello e salta l'instradamento del tutto.","reference.models#2#h":"Modalità di instradamento","reference.models#3#p":"Tre strategie orchestrate. La stessa pipeline dei ruoli (il piccolo team di assistenti specializzati che Ava attiva dietro le quinte) funziona su tutti e tre; ciò che cambia è la flotta sottostante di modelli. Scegli una modalità nel selettore modelli e Ava gestisce il resto. Ogni scheda qui sotto mostra gli specialisti costituenti a cui il direttore instrada.","reference.models#4#p":"Non hai bisogno di memorizzare le schede qui sotto — sono qui perché puoi vedere di cosa è composta ciascuna strategia.","reference.models#6#c":"Aurora è volutamente solo Mistral. Se un modello Mistral non è disponibile, il router restituisce un errore invece di instradare altrove — questa è la garanzia dello stack UE. Scegli Maestro o Supernova per un funzionamento degradato.","reference.models#7#c":"Tutte e tre le modalità sono universalmente disponibili — sui crediti della piattaforma e sulle tue chiavi. BYOK aggiunge l'opzione di bypassare l'orchestrazione e controllare un singolo modello direttamente.","reference.models#8#h":"Modelli gestiti dalla piattaforma","reference.models#9#p":"Disponibile su ogni piano, incluso quello gratuito. I token (le unità di testo in cui l'IA è misurata — circa tre quarti di parola ciascuno) vengono scalati dal tuo piano. Le chiavi (le password private che sbloccano ogni modello a pagamento) sono ruotate e monitorate dalla piattaforma — nulla da configurare per te.","reference.project-context#title":"Contesto del progetto","reference.project-context#0#p":"Questo spiega come Ava si documenta sul tuo progetto prima di iniziare — i file che consulta per capire su cosa stai lavorando. Non devi configurare nulla; lo fa da sola. Leggilo se vuoi sapere dove inserire una nota affinché la veda sempre.","reference.project-context#1#p":"Quando apri un progetto, Ava carica diversi livelli di contesto (informazioni di sfondo che tiene a mente). Capire questi livelli ti aiuta a inserire le informazioni nel posto giusto.","reference.project-context#2#h":"Caricati automaticamente","reference.project-context#3#li0":".ava/instructions.md — considerata come guida duratura e prioritaria. Sempre presente nel contesto.","reference.project-context#3#li1":".ava/context.md — appunti liberi. Caricati, con priorità inferiore.","reference.project-context#3#li2":"README.md — analizzato al primo avvio per il riepilogo del progetto.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — i piccoli file che elencano l'impostazione del progetto; letti per rilevare il linguaggio, il framework e il comando di test.","reference.project-context#3#li4":".gitignore — l'elenco dei file da escludere dal controllo versione; rispettato da tutti gli strumenti sui file (glob, grep, project_index).","reference.project-context#4#h":"Caricati su richiesta","reference.project-context#5#p":"\"Su richiesta\" significa che Ava recupera questi elementi solo quando un compito ne ha effettivamente bisogno, invece di caricarli subito.","reference.project-context#6#li0":"Indice del progetto — una mappa strutturata dei tuoi file e delle parti nominate al loro interno (funzioni, classi — \"simboli\") e di come si collegano (\"importazioni\"). Costruito solo quando serve.","reference.project-context#6#li1":"Cronologia Git — il registro delle modifiche passate; recuperata quando vengono eseguiti git_status, git_diff o git_create_pr (Git è lo strumento che traccia ogni modifica al progetto; \"PR\" è una pull request, una proposta di gruppo di modifiche).","reference.project-context#6#li2":"Memoria — le voci vengono abbinate per significato (\"semanticamente\") e inserite una alla volta, non tutte insieme.","reference.project-context#7#c":"Metti le convenzioni in instructions.md. Inserisci gli appunti in context.md. Lascia che la memoria gestisca il resto da sola.","features.unified-panel#title":"Pannello unificato","features.unified-panel#0#p":"In parole povere: tutto quello che fa Ava vive in una sola finestra, così non devi cercare tra le schede per trovarla.","features.unified-panel#1#p":"Un unico pannello per chat, dashboard, memoria, attività e diario. Nessun cambio di contesto tra finestre. La barra laterale seleziona cosa stai guardando; l'area principale cambia per adattarsi.","features.unified-panel#2#p":"Lo stato della conversazione persiste quando ti sposti — apri la memoria, controlla un'attività, poi torna indietro. La chat è ancora lì, ancora in streaming se Ava sta ancora lavorando.","features.unified-panel#3#c":"Il pannello unificato è un concetto di estensione e IDE. La superficie web usa le schede del browser.","features.knowledge-packs#title":"Pacchetti di conoscenza","features.knowledge-packs#0#p":"In parole povere: dai ad Ava una cartella con i tuoi documenti, e lei può leggerli per rispondere alle tue domande. Un \"pacchetto di conoscenza\" è proprio questo insieme di file — il materiale di riferimento che può consultare.","features.knowledge-packs#1#p":"Trascina una cartella di materiale di riferimento (specifiche, RFC, appunti di riunione, documentazione API) in un pacchetto di conoscenza. Ava può estrarre i pezzi rilevanti nel contesto quando una conversazione tocca l'argomento.","features.knowledge-packs#2#p":"I pacchetti sono indicizzati localmente. Il recupero è semantico — Ava trova il documento giusto per significato, non per nome file. (\"Semantico\" significa che abbina in base a di cosa parla un documento, quindi non devi ricordare le parole esatte o il nome del file.) I pacchetti possono essere condivisi con un team o tenuti privati.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Ti serve un report, una mail o un documento scritto? Ava può abbozzarlo e consegnarti un vero file Word, Excel o PDF che puoi aprire e modificare come qualsiasi altro.","features.office-suite#1#p":"Report, email e documenti — abbozzati, formattati ed esportati in formati nativi (.docx è Word, .xlsx è Excel, .pdf è un PDF).","features.office-suite#2#li0":"report_generate — un .docx strutturato che attinge da task, diario, memoria e stato del progetto.","features.office-suite#2#li1":"email_draft — email con tono controllato salvata come file .docx.","features.office-suite#2#li2":"document_manage — crea, leggi, modifica ed esporta tra Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Utile quando Ava scrive per te — report di stato, presentazioni di avvio, aggiornamenti ai clienti. Il .docx finisce nel tuo progetto dove puoi rifinirlo.","features.dashboard-library#title":"Libreria delle dashboard","features.dashboard-library#0#p":"In parole semplici: uno scaffale che contiene tutto ciò che tu e Ava avete creato e discusso, così nulla va perso.","features.dashboard-library#1#p":"Una vista navigabile di tutto ciò che Ava ha prodotto con te — immagini generate, video, audio, documenti — insieme alle tue conversazioni, memorie e task. Un unico posto per trovare qualcosa che hai fatto la scorsa settimana.","features.document-preview#title":"Anteprima del documento","features.document-preview#0#p":"In parole semplici: dai un'occhiata dentro un documento proprio dove sei, senza dover aprire un programma separato per leggerlo.","features.document-preview#1#p":"Clicca col tasto destro su un file Word, foglio Excel, PDF, CSV, HTML o Markdown nel tuo progetto — anteprimalo in linea senza uscire dall'editor. Utile per leggere materiale di riferimento generato da Ava o file lasciati da un collaboratore.","features.daily-briefing#title":"Briefing giornaliero","features.daily-briefing#0#p":"In parole semplici: una breve nota ogni mattina (\"ecco dove eri arrivato\") così puoi riprendere senza rileggere tutto.","features.daily-briefing#1#p":"Riassunto mattutino: diario di ieri, task aperti, stato del progetto e eventuali promemoria impostati da Ava. Opzionale — attivalo nelle impostazioni.","features.daily-briefing#2#p":"Il briefing usa la memoria per mostrare contesto rilevante (\"l'ultima volta che hai lavorato sul flusso di autenticazione, hai notato che volevi rivedere la strategia dei token di aggiornamento\"). Non è un feed di notizie — è un aggiornamento mirato.","troubleshooting.logs#4#c":"I log potrebbero contenere estratti dei file del progetto che Ava ha letto durante una sessione. Controllali prima di condividerli.","troubleshooting.support-request#title":"Invio di una richiesta di supporto","troubleshooting.support-request#0#p":"In parole semplici: se qualcosa non funziona e le soluzioni indicate sopra non hanno risolto, facci sapere. Il modo più semplice è chiedere ad Ava di farlo per te.","troubleshooting.support-request#1#p":"Se il problema non rientra negli errori comuni, apri un ticket di assistenza (invia una richiesta di aiuto al nostro team). Puoi farlo direttamente in Ava (senza moduli da compilare) oppure dal sito web.","troubleshooting.support-request#2#h":"Dall'interno di Ava","troubleshooting.support-request#3#p":"Chiedile di farlo. \"Ava, puoi aprire un ticket di supporto su questo?\" Lei esegue la funzione support_request, allega il contesto della sessione pertinente (con le credenziali oscurate) e lo invia. È la via più rapida.","troubleshooting.support-request#4#h":"Dal sito web","troubleshooting.support-request#5#p":"Vai su ava-supernova.com/support. Scegli una categoria (bug, feature, account, security, general) e descrivi cosa è accaduto. Risponderemo entro un giorno lavorativo.","troubleshooting.support-request#6#h":"Cosa includere","troubleshooting.support-request#7#li0":"Cosa stavi cercando di fare.","troubleshooting.support-request#7#li1":"Cosa è successo effettivamente.","troubleshooting.support-request#7#li2":"Quale piattaforma (estensione, IDE, CLI, app companion) e quale versione.","troubleshooting.support-request#7#li3":"Qualsiasi messaggio di errore o estratto dai log. Rimuovi le credenziali prima.","troubleshooting.security-disclosure#title":"Segnalazione di problemi di sicurezza","troubleshooting.security-disclosure#0#p":"In parole semplici: se hai individuato un modo in cui Ava potrebbe essere violata o usata impropriamente (una \"vulnerabilità\" — una debolezza di sicurezza), per favore comunicacelo privatamente prima, così possiamo risolverla prima che qualcuno ne approfitti. Questa pagina ti spiega come.","troubleshooting.security-disclosure#1#p":"Hai trovato una vulnerabilità? Grazie. Prendiamo ogni segnalazione sul serio e lavoriamo insieme alla soluzione prima di qualsiasi diffusione pubblica (prima che il problema venga annunciato ufficialmente).","troubleshooting.security-disclosure#2#h":"Come segnalare","troubleshooting.security-disclosure#3#li0":"Invia un'email a security@ava-supernova.com con una descrizione, i passaggi per riprodurre l'errore e il periodo di divulgazione preferito.","troubleshooting.security-disclosure#3#li1":"Oppure apri un ticket di supporto con categoria \"security\" — entra nella stessa coda di valutazione.","troubleshooting.security-disclosure#3#li2":"Riceverai conferma entro 24 ore.","troubleshooting.security-disclosure#4#h":"I nostri impegni","troubleshooting.security-disclosure#5#li0":"Divulgazione coordinata — concordiamo una tempistica con te prima che tutto diventi pubblico. Il termine predefinito è di 90 giorni.","troubleshooting.security-disclosure#5#li1":"Riconoscimento — riceverai credito nelle note di correzione, a meno che tu non preferisca rimanere anonimo.","troubleshooting.security-disclosure#5#li2":"Nessuna ritorsione legale — la ricerca condotta in buona fede è benvenuta. Non intraprenderemo azioni legali nei tuoi confronti.","troubleshooting.security-disclosure#6#c":"La pagina sulla sicurezza all'indirizzo ava-supernova.com/security illustra il nostro approccio completo — garanzie architetturali, strumenti di oscuramento e controlli di accesso.","features.workflows#title":"Workflow","features.workflows#0#p":"In parole semplici: insegna ad Ava una routine che fai ripetutamente, dai le un nome e lei può eseguirla tutta di nuovo su richiesta. Un \"workflow\" è proprio quella routine salvata — un insieme di passaggi che Ava ripete per te.","features.workflows#1#p":"Salva una sequenza di passaggi che trovi di ripetere — rivedi PR → esegui test → scrivi note di rilascio → bozza l'email. Un workflow è un piano riutilizzabile che Ava può riprodurre con input diversi.","features.workflows#2#p":"I workflow sono archiviati per progetto in una cartella chiamata `.ava/workflows/` all'interno del tuo progetto. Condividili con il tuo team facendo il commit della directory (salvandola nel tuo progetto condiviso così anche i colleghi la ricevono).","features.events#title":"Eventi e notifiche","features.events#0#p":"In parole semplici: mentre Ava lavori ricevi un elenco ordinato passo dopo passo di ciò che sta facendo, e un avviso quando un lavoro lungo finisce così puoi allontanarti.","features.events#1#p":"Mentre Ava è in esecuzione vedi aggiornamenti strutturati, non un muro di testo. Ogni chiamata strumento, ogni passaggio tra ruoli, ogni delta in streaming è un evento discreto nell'interfaccia — espandibile per i dettagli, comprimibile per la panoramica.","features.events#2#p":"Le esecuzioni in background emettono notifiche di sistema quando completano. Puoi allontanarti da una build lunga e Ava ti dirà quando è finita.","features.personality#title":"Progettista della personalità","features.personality#0#p":"In parole semplici: regola come Ava ti parla — chiacchierona o breve, formale o informale, più battute o meno — così suoni come preferisci.","features.personality#1#p":"Modula come Ava ti parla. Tono, energia, verbosità (quanto dice), formalità, umorismo. Cursori e preset — ingegnere conciso, mentor accogliente, collega asciutto, o la tua miscela personale.","features.personality#2#p":"La personalità influisce sul modo di esprimersi, non sulla competenza. Esegue comunque gli stessi strumenti e segue le stesse regole di autorizzazione. Il suo nome è bloccato su Ava — questo è non negoziabile.","features.release-notes#title":"Note di rilascio","features.release-notes#0#p":"In parole semplici: un elenco aggiornato di cosa è nuovo e cosa è stato corretto in ogni aggiornamento, così puoi vedere cosa è cambiato.","features.release-notes#1#p":"Registro delle modifiche nell'app (un changelog è la cronologia delle modifiche). Ogni versione rilasciata con i suoi punti salienti, correzioni di bug e cambiamenti significativi (modifiche che potrebbero richiedere di aggiustare come usi qualcosa). La pagina web mantiene la versione pubblica su ava-supernova.com/releases.","troubleshooting.common-errors#title":"Errori comuni","troubleshooting.common-errors#0#p":"Quasi tutti gli errori hanno una causa breve e precisa. Qui trovi quelli più frequenti e come risolverli. Non preoccuparti se le parole sembrano tecniche — ogni punto qui sotto ti spiega cosa stai vedendo e cosa devi fare esattamente.","troubleshooting.common-errors#1#h":"Il modello non risponde","troubleshooting.common-errors#2#p":"Cosa vedi: Ava si zittisce e non risponde.","troubleshooting.common-errors#3#p":"Controlla l'indicatore di stato nell'intestazione della chat. Se vedi \"in collegamento\", il tuo fornitore (il servizio AI con cui Ava sta parlando) è raggiungibile ma lento — aspetta trenta secondi. Se leggi \"non disponibile\", Ava è tornata automaticamente al modello successivo nella catena (ha cambiato su un modello di riserva). Se non appare nulla, controlla la tua chiave API nelle Impostazioni e prova la connessione. (La chiave API è la password privata che permette ad Ava di utilizzare un servizio AI a pagamento.)","troubleshooting.common-errors#4#h":"Chiamata strumento fallita","troubleshooting.common-errors#5#p":"Cosa vedi: uno dei passaggi di Ava (una \"chiamata strumento\" — mentre legge un file, esegue un comando, ecc.) mostra un errore rosso invece di completarsi.","troubleshooting.common-errors#6#p":"Clicca sulla chiamata strumento fallita per vedere l'errore. Cause comuni: ha provato ad accedere a un file fuori dalla cartella del progetto, bloccato appositamente per la tua sicurezza (questo controllo si chiama protezione \"path traversal\" — evita che esca dalla cartella in cui stai lavorando); un comando che richiede un'altra cartella; oppure un file spostato dall'ultima volta che Ava lo ha controllato. Spiegale cosa è successo — riproverà correggendo.","troubleshooting.common-errors#7#h":"Memoria non ricorda","troubleshooting.common-errors#8#p":"Cosa vedi: Ava non trova qualcosa di cui sei sicuro dovrebbe ricordare.","troubleshooting.common-errors#9#p":"La memoria funziona per significato, non per parole esatte (questo è il senso di \"semantic\"). Quindi \"Cosa ho deciso sull'autenticazione?\" funziona meglio di \"trova la mia decisione sull'autenticazione\". Se la memoria è sicuramente presente ma non appare, apri il browser della memoria e cerca — se non c'è, non è mai stata salvata.","troubleshooting.common-errors#10#h":"Loop di accesso","troubleshooting.common-errors#11#p":"Cosa vedi: accedi, ma Ava continua a chiederti di accedere di nuovo — un loop che non ti fa passare.","troubleshooting.common-errors#12#p":"La soluzione è cancellare i dati di accesso salvati e ricominciare da zero: nell'estensione esegui \"Ava: Esci\" dal pannello comandi, nell'IDE vai su Impostazioni → Account → Esci, nel CLI elimina il file in ~/.ava/auth.json (un piccolo file di accesso in una cartella chiamata .ava nella tua home). Poi accedi di nuovo.","troubleshooting.common-errors#13#h":"Token esauriti","troubleshooting.common-errors#14#p":"Cosa vedi: un messaggio che indica che hai finito l'utilizzo gratuito del mese. (I \"token\" sono l'unità di misura dell'uso AI — \"esauriti\" significa semplicemente che hai consumato tutto il tuo credito gratuito mensile.)","troubleshooting.common-errors#15#p":"Il budget mensile gratuito si azzera il 1° di ogni mese. Fino ad allora, passa a un provider BYOK (usa la tua chiave API) per continuare a lavorare. Il tuo account resta attivo — solo le richieste gratuite gestite dalla piattaforma sono sospese.","troubleshooting.logs#title":"Dove trovare i log","troubleshooting.logs#0#p":"Un \"log\" è semplicemente un diario che il tuo computer tiene di quanto accaduto — utile quando qualcosa si blocca e tu (o l'assistenza) dovete vedere i dettagli.","troubleshooting.logs#1#p":"Quando hai bisogno del quadro completo — quale strumento è stato chiamato, quali informazioni ha ricevuto, cosa ha restituito il servizio AI — i log sono file di testo semplice in una cartella sul tuo computer alla posizione ~/.ava/logs/ (una cartella chiamata .ava nella tua home, contenente una cartella logs).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — trascrizioni per sessione incluse chiamate strumento, risposte in streaming ed errori.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — log dell'host delle estensioni VS Code. Errori di attivazione, errori del pannello.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — log dell'IDE desktop. Messaggi del processo sidecar, panic di Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — log REPL del CLI.","troubleshooting.logs#3#p":"Nell'estensione, \"Ava: Mostra Log\" nel pannello comandi apre il log pertinente in una scheda dell'editor. Nell'IDE, Impostazioni → Diagnostica ha un pulsante \"Apri Log\". Il CLI può monitorare il proprio log con ava logs --follow.","start.what#title":"Cos'è Ava?","start.what#0#p":"Ava è un'intelligenza artificiale che fa davvero le cose — non solo parla. Ti costruirà un'app, scriverà un documento, ti insegnerà qualcosa da zero, progetterà un logo o si occuperà di quella burocrazia che rimandi sempre. E lei ti ricorda: su cosa stai lavorando, come preferisci le cose, cosa hai chiesto la settimana scorsa.","start.what#1#p":"C'è una sola Ava, e lavora dove lavori tu — nel tuo editor di codice, come app desktop, sul telefono o nel terminale. Stessa memoria, stessa personalità, ovunque.","start.what#2#h":"Cosa la rende diversa","start.what#3#li0":"Di base è tua. Il tuo lavoro rimane sul tuo dispositivo. Nessun tracciamento, nessuna telemetria — mai.","start.what#3#li1":"Aperta a tutti. Ogni riga di Ava è pubblica. Niente da prendere per fede.","start.what#3#li2":"Gratuita per iniziare. 300 crediti ogni mese, senza carta, senza inghippi — oppure inserisci le tue chiavi AI e non ci paghi nulla affatto.","start.what#3#li3":"Insegnare è gratis, per sempre. Imparare non dovrebbe costare.","start.what#4#p":"Non hai mai scritto codice? La pagina successiva è scritta proprio per te. Sei già esperto? Vai avanti — lei ti terrà il passo.","start.what#deeper#0#h":"Where Ava lives","start.what#deeper#1#li0":"VS Code extension — Ava next to your editor: a chat panel, a dashboard, and changes shown inline before they happen.","start.what#deeper#1#li1":"Desktop IDE — a standalone app with the whole thing in one window. Adds desktop control (opening apps, clicking, typing for you).","start.what#deeper#1#li2":"Companion — a mobile app for when you're away from your desk: tasks, journal, memory, quick chats.","start.what#deeper#1#li3":"CLI — Ava in your terminal, for people who live there.","start.what#deeper#2#h":"How she works, in brief","start.what#deeper#3#p":"Ava switches mindsets (called modes) to match the job, quietly runs a small team of specialist helpers on harder work, and picks the best AI model for each step automatically. You never manage any of it. The Core concepts section has the full tour whenever you're curious.","start.first-five#title":"La tua prima cosa con Ava","start.first-five#0#p":"Il modo più veloce per ottenere Ava è chiederle qualcosa di reale e guardarla fare. Nessuna configurazione da leggere, niente da imparare prima — basta dirle cosa vuoi, in parole semplici.","start.first-five#1#h":"Prova questo ora","start.first-five#2#li0":"Apri la chat.","start.first-five#2#li1":"Scrivi qualcosa che vuoi davvero. Prova \"spiega cosa fa questo progetto\", o \"aggiungi un pulsante che svuota il modulo\".","start.first-five#2#li2":"Ava ti mostra cosa sta per fare — e aspetta.","start.first-five#2#li3":"Sei soddisfatto? Di sì. Guardala fare.","start.first-five#3#p":"È tutto il ritmo: chiedi, ti mostra il piano, approvi, lo fa. Non cambia mai nulla senza mostrartelo prima — così non puoi rompere nulla provando.","start.first-five#4#h":"Alcune cose che vale la pena chiedere","models.routing#deeper#2#td5.0":"Chat","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Gestione creazione immagini","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Visione","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (encoder visivo addestrato da zero)","models.routing#deeper#2#td8.0":"Scrittura di testi lunghi","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Residenza dei dati","models.routing#deeper#2#td9.1":"Misto (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Misto (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Solo UE · pesi aperti","models.routing#deeper#2#td10.0":"Stato","models.routing#deeper#2#td10.1":"Attivo · tutti i piani","models.routing#deeper#2#td10.2":"Prossimamente","models.routing#deeper#2#td10.3":"Prossimamente","models.routing#deeper#2#td11.0":"Ideale per","models.routing#deeper#1#h":"Affiancati","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Coordinatore","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B attive, 1M contesto)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B attive, 262K contesto)","models.routing#deeper#2#td1.0":"Costruttore","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (riutilizza il coordinatore)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B denso, 256K contesto)","models.routing#deeper#2#td2.0":"Specialisti di fascia media","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (revisione codice, verifica fatti, ricognizione, scanner, verificatore sicurezza, ecc.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Architetto, Verificatore, Sequenziatore, Tutor, Relatore, ecc.)","models.routing#deeper#2#td3.0":"Fascia leggera / controllo intento","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Esploratore, Verificatore, Sequenziatore, Sfidante, Integratore)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Specialisti di fascia pesante","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Ricercatore, Sfidante, Ricercatore CVE, Ideatore, Verificatore dei fatti)","start.glossary#1#td7.1":"L'unità più semplice di Ava per il costo di un'azione, così non devi fare calcoli sui token. I piani includono un pacchetto mensile.","start.glossary#1#td8.0":"Chiave API","start.glossary#1#td8.1":"Una password privata che permette al software di usare un servizio a pagamento (come un modello AI) sul tuo account. Ne hai bisogno solo se vuoi portare la tua chiave.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Porta la tua chiave.\" Usare la propria chiave API invece dell'accesso gestito da Ava. Opzionale — per chi paga già direttamente un fornitore.","start.glossary#1#td10.0":"Locale-first","start.glossary#1#td10.1":"I tuoi dati risiedono sul tuo computer di default. Niente viene caricato a meno che tu non attivi la sincronizzazione. \"Il locale è sacro.\"","start.glossary#1#td11.0":"Modalità autorizzazioni","start.glossary#1#td11.1":"Quanto è cauta Ava prima di agire — chiedere ogni volta, chiedere solo per le cose rischiose, o semplicemente procedere. Decidi tu il livello.","start.glossary#1#td12.0":"Finestra di contesto","start.glossary#1#td12.1":"Quanto testo un modello può tenere a mente contemporaneamente — la sua memoria a breve termine. \"Contesto 1M\" significa circa un milione di parole. Più grande = può leggere di più prima di dimenticare.","start.glossary#1#td13.0":"Differenza","start.glossary#1#td13.1":"Una vista affiancata di esattamente cosa cambierà in un file — vecchio da una parte, nuovo dall'altra — mostrata prima che Ava modifichi qualcosa così puoi approvarlo.","start.glossary#1#td14.0":"Repository (repo)","start.glossary#1#td14.1":"Una cartella di progetto tracciata per le modifiche, solitamente con Git. Se questo non ti dice ancora nulla, è semplicemente \"la cartella dove vive il mio progetto.\"","start.glossary#1#td15.0":"Prompt","start.glossary#1#td15.1":"Quello che scrivi all'AI — la tua domanda o istruzione.","start.glossary#2#c":"Bloccato su una parola? Chiedi ad Ava in modalità Chat — \"cosa significa X?\" — e te lo spiegherà al tuo livello.","models.routing#title":"Routing — come Ava sceglie i modelli","models.routing#0#p":"Ecco la versione breve: non devi mai scegliere quale modello AI usare. Ci pensa Ava per te, scegliendo lo strumento migliore per ogni parte del lavoro — come un buon capo assegna il compito giusto alla persona giusta.","models.routing#1#p":"Scegli uno dei tre stili — Maestro, Supernova, o Aurora — e Ava invia ogni pezzo di lavoro al modello che lo gestisce meglio. Maestro è il default, è attivo su tutti i piani ed è una buona scelta per quasi tutti.","models.routing#2#h":"Perché preoccuparsi del routing?","models.routing#3#p":"Mettere il modello giusto su ogni passaggio costa meno che eseguire tutto su un unico modello grande e costoso — e dà risultati migliori, perché ogni modello fa ciò in cui eccelle. Ottieni costi stabili e alta qualità senza dover mai sapere quale modello è quale.","models.routing#4#c":"Tutti e tre gli stili funzionano con i crediti della piattaforma e con le tue chiavi. Con la tua chiave puoi anche saltare il routing e guidare un singolo modello direttamente. La panoramica completa della flotta si trova sotto \"Mostrami i dettagli\".","models.routing#deeper#0#c":"I numeri \"B\" qui sotto sono miliardi di parametri — grossomodo quanto è grande il cervello di un modello; più grande significa solitamente più intelligente ma più lento e costoso. Questo è un dettaglio tecnico sottostante; non ne hai mai bisogno per usare Ava.","start.first-model#deeper#0#h":"Cosa c'è davvero in ogni stile","start.first-model#deeper#1#p":"Maestro — un solo direttore (Qwen 3.6 Plus) gestisce ogni passaggio. Ottimizzato per la produzione, collaudato e con costi prevedibili.","start.first-model#deeper#2#p":"Supernova — un coordinatore all'avanguardia (DeepSeek V4 Pro, 1.6T parametri / 49B attivi, contesto da 1M) affida ogni sotto-compito a uno specialista: V4 Flash per build ad alto volume, Qwen 3.6 Plus come alternativa, Qwen Omni per la visione.","start.first-model#deeper#3#p":"Aurora — solo Mistral, su tre livelli: Mistral Large 3 (coordinatore + specialisti pesanti), Mistral Medium 3.5 (128B denso, contesto 256K, visione nativa, pesi aperti MIT modificato, 77.6% SWE-Bench Verified) per Costruttore + fascia media + visione + testi lunghi, e Mistral Small 4 alla soglia dell'intento. Pesi aperti dall'inizio alla fine, non esce mai dall'infrastruttura UE.","start.first-model#deeper#4#h":"Porta il tuo modello (BYOK)","start.first-model#deeper#5#p":"Preferisci usare il tuo account AI? Incolla la chiave del fornitore nelle impostazioni e ottieni entrambe le cose — i tre stili di instradamento, più l'opzione di scegliere un singolo modello ed evitare completamente l'instradamento. Utile se hai una preferenza forte, un budget rigido o vuoi testare un modello specifico. L'elenco completo dei fornitori è nella sezione Riferimento.","start.glossary#title":"Glossario in linguaggio semplice","start.glossary#0#p":"Ogni parola che potresti incontrare intorno ad Ava, spiegata senza presupporre conoscenze pregresse. Non devi memorizzare nulla di tutto questo: torna indietro ogni volta che un termine ti crea difficoltà.","start.glossary#1#th0":"Parola","start.glossary#1#th1":"Cosa significa davvero","start.glossary#1#td0.0":"Agente","start.glossary#1#td0.1":"Un'IA che può compiere azioni per te — leggere un file, eseguire un comando, cercare sul web — non solo chattare. Ava è un agente: fa cose, con il tuo permesso.","start.glossary#1#td1.0":"Modello","start.glossary#1#td1.1":"Il vero cervello dell'IA che pensa (Qwen, DeepSeek, Mistral e altri). Modelli diversi hanno punti di forza diversi. Di solito non ne scegli uno tu — lo fa Ava.","start.glossary#1#td2.0":"Modalità","start.glossary#1#td2.1":"Lo stato mentale di Ava. Come un collega che cambia cappello: costruttore, scrittore, insegnante, pianificatore, amico. Scegli tu la modalità; cambia il modo in cui si comporta. Ce ne sono sette.","start.glossary#1#td3.0":"Persona / specialista","start.glossary#1#td3.1":"Ruoli di supporto che Ava attiva dietro le quinte per compiti difficili — un esploratore, un pianificatore, un controllore dei fatti. Immagina una piccola squadra di esperti. Non parli direttamente con loro; Ava li coordina.","start.glossary#1#td4.0":"Instradamento","start.glossary#1#td4.1":"Ava decide quale modello usare per ogni passaggio così ottieni buone risposte senza pagare troppo. Succede automaticamente — \"routing mode\" sceglie solo la strategia complessiva.","start.glossary#1#td5.0":"Strumento","start.glossary#1#td5.1":"Un'azione specifica che Ava può fare — leggere un file, fare una ricerca, inviare un'email. Una \"tool call\" è quando ne usa uno. Chiede il permesso prima di qualsiasi cosa rischiosa.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Come l'IA misura il testo — circa ¾ di una parola. I modelli sono tariffati per milione di token. Per lo più qualcosa che puoi ignorare.","start.glossary#1#td7.0":"Credito","models.routing#deeper#2#td11.1":"Lavoro quotidiano, costo prevedibile","models.routing#deeper#2#td11.2":"Lavoro complesso multi-step, coordinatore all'avanguardia su ogni piano","models.routing#deeper#2#td11.3":"GDPR rigoroso, settore pubblico, stack sovrani UE","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Routing Qwen differenziato per livello, impronta leggera. Qwen 3.6 Plus gestisce il coordinatore, Builder, pianificazione, sicurezza, brainstorming e lavoro con contesto lungo — gli slot in cui il suo attention lineare ibrido da 1M contesti conviene davvero. Qwen 3.5 Flash si occupa della chat, dell'orchestrazione della generazione immagini e del gate dell'intento a monte, dove il suo prezzo $0.07/$0.26 e il TTFT più veloce vincono sulla maggior parte del volume di token a bassa profondità. Qwen 3.5 Omni Plus possiede l'input visivo (Qwen 3.6 Plus non ha visione nativa). Qwen 3.5 Plus gestisce il lavoro lungo sensibile al costo. Scende nella scala delle priorità Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash se il coordinatore primario non è disponibile.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Insieme poliglotta. DeepSeek V4 Pro coordina e invia ogni sotto-compito allo specialista più adatto: Qwen 3.6 Plus avvia ogni Spawn Builder, V4 Flash gestisce la chat più i ruoli di revisione/audit di fascia media, Qwen 3.5 Flash assorbe il lavoro di classificazione di fascia leggera, Qwen 3.5 Omni Plus possiede l'input visivo, Qwen 3.5 Omni Flash orchestra le chiamate degli strumenti di generazione immagini, Qwen 3.5 Plus porta il ruolo di Scrittore di contenuti sensibile al costo. Ragionamento all'avanguardia dove serve, economia di livello flash sul grosso del volume di token.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Stack AI europeo — sovrano per progettazione. Routing solo Mistral in tre livelli: Mistral Large 3 (675B/41B-sparse MoE attivo) gestisce il ruolo di coordinatore più gli specialisti pesanti che hanno bisogno di profondità — Ricercatore, Sfidante, Ricercatore CVE, Ideatore, Controllore dei fatti, Verificatore di sicurezza — e il lavoro pesante a contesto lungo dove la sua efficienza sparse-MoE vince. Mistral Medium 3.5 — il modello principale fuso rilasciato ad aprile 2026, 128B denso, 256K contesto, encoder visivo addestrato da zero, pesi aperti MIT modificati, 77.6% SWE-Bench Verified — gestisce il vero livello operativo: avvio di Builder, specialisti di fascia media (Architetto, Verificatore, Sequencer, Tutor, Relatore), input visivo e scrittura lunga. Mistral Small 4 espanso da un singolo ruolo al gate dell'intento per gestire anche la chat e l'orchestrazione della generazione immagini — il suo prezzo $0.15/$0.60 e il ragionamento configurabile valgono il loro spazio sui percorsi ad alto volume e bassa profondità. Pesi aperti dall'inizio alla fine, non esce mai dalle infrastrutture UE. Aurora deliberatamente non reindirizza silenziosamente a un modello non Mistral quando uno non è disponibile; il router mostra un errore invece — è questo che fa sì che sia \"Aurora\" piuttosto che un Maestro con sapore Mistral.","credits.overview#title":"Crediti Ava — come funziona la fatturazione","credits.overview#0#p":"I crediti sono semplicemente il modo in cui Ava tiene traccia di ciò che usi — come i minuti di un piano telefonico. Ogni piano, incluso quello gratuito, viene fornito con un pool di crediti, e ogni cosa che Ava fa (risponderti, creare un'immagine) costa un piccolo numero di essi. È tutto qui il concetto. I dettagli qui sotto servono se vuoi sapere esattamente quanto costa ciascuna cosa.","credits.overview#1#p":"Ava fattura in crediti, non in token grezzi. (Un \"token\" è la piccola porzione di testo — circa alcune lettere — che i modelli AI leggono e scrivono; la maggior parte dei servizi ti fa pagare per token, il che è difficile da prevedere.) Un credito copre un'unità di lavoro — un turno di chat, un avvio di persona (un aiuto che svolge una parte del compito), una generazione di immagini. Il disaccoppiamento dalla misurazione a livello di token significa che non devi sapere quale modello è attivo per capire quanto costa un'azione. Lo stesso turno di chat costa lo stesso, sia che Maestro lo instradi a Qwen 3.6 Plus o che Supernova lo indirizzi a V4 Pro.","credits.overview#2#h":"Piani","credits.overview#3#p":"Ogni piano ha accesso a tutte le funzionalità — accesso ai modelli, Creative Studio, tutte e sette le modalità, la piena orchestrazione delle persone. I livelli superiori acquistano più crediti e un tetto del limite di richieste più alto, non funzionalità sbloccate.","credits.overview#4#li0":"Gratuito — $0/mese. 300 crediti. Limite di richieste 20/minuto. Nessuna carta richiesta.","credits.overview#4#li1":"Pro — $19/mese. 5.000 crediti. 60 richieste/minuto.","credits.overview#4#li2":"Ultra — $39/mese. 10.000 crediti. 120 richieste/minuto.","credits.overview#4#li3":"Enterprise — $79/mese. 20.000 crediti. 200 richieste/minuto.","credits.overview#5#c":"I crediti non utilizzati si accumulano mentre il tuo abbonamento è attivo — non c'è recupero forzato. Le ricariche si sommano al pool dell'abbonamento: 750 crediti per $3, 2.000 per $8, 4.000 per $15.","credits.overview#6#h":"Quanto costano le cose","credits.overview#7#p":"Tabella dei costi per azione — cosa viene detratto dal tuo pool di crediti quando viene eseguita ogni azione. (Un \"colpo di cache\" è quando Ava riutilizza un lavoro che ha già fatto invece di rifarlo; quando succede paghi meno — la tariffa scende del 70%, o del 50% sui modelli pesanti sull'output come DeepSeek V4 Pro.)","credits.overview#8#li0":"Turno di chat — 2 crediti. Un singolo scambio in qualsiasi modalità.","credits.overview#8#li1":"Chiamata leggera — 1 credito. Gate dell'intento, classificazione, lettura singola.","credits.overview#8#li2":"Persona pesante — 3 crediti. Architetto, Ricercatore, Ricercatore CVE, Ideatore (profondità ≥ 4).","credits.overview#8#li3":"Persona leggera — 1 credito. Esploratore, Verificatore, Sequencer, Sfidante (profondità ≤ 2).","credits.overview#8#li4":"Orchestrazione — 10 crediti. Avvio completo della pipeline delle identità (Conductor + compito multi-identità).","credits.overview#8#li5":"Generazione immagini — 12 crediti. Hailuo image-01 tramite Creative Studio.","credits.overview#8#li6":"Generazione video — 150 crediti. Clip video Hailuo 02 Pro 1080p da 6 secondi.","credits.overview#8#li7":"Generazione voce — 10 crediti. Sintesi vocale Speech 2.8 HD.","credits.overview#8#li8":"Generazione musica — 50 crediti. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Rimozione sfondo — 2 crediti.","credits.overview#9#h":"Moltiplicatori per modello","credits.overview#10#p":"Questa parte è per i curiosi — non ti serve per usare Ava. Un moltiplicatore scala semplicemente il costo dei crediti su o giù a seconda di quanto costa il modello dietro un'azione, quindi i modelli più pesanti costano un po' di più. (\"Margine netto\" è la fetta che il progetto trattiene dopo aver pagato le proprie spese — puntiamo basso affinché il valore torni a te.)","credits.overview#11#p":"I modelli più pesanti moltiplicano il costo dell'azione così i crediti tracciano la spesa reale invece di una tariffa fissa. Calibrato per un margine netto di circa il 55%.","credits.overview#12#li0":"0.6× — Mistral Small 4 (il ruolo dello specialista di Aurora). Sotto 1× perché Mistral Small 4 costa meno del riferimento Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Tariffa base.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (coordinatore di Aurora). Circa pari al riferimento Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (coordinatore Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (coordinatore Supernova + specialisti pesanti). Ricalibrato da 5.0× per ripristinare la parità di margine alla tariffa pubblicata V4 Pro.","credits.overview#13#c":"I modelli Anthropic (Claude Opus / Sonnet / Haiku) saltano completamente la fatturazione dei crediti — sono solo BYOK e paghi Anthropic direttamente. Lo stesso vale per qualsiasi altro fornitore BYOK usato con la tua chiave.","credits.overview#14#h":"BYOK e crediti","credits.overview#15#p":"BYOK (\"porta la tua chiave\" — fornisci tu stesso il tuo account presso un fornitore di IA e una chiave, che è una password privata che permette al software di utilizzare quell'account a pagamento) è per chi paga già direttamente un fornitore di IA. Se non sei tu, puoi ignorare questa sezione interamente.","credits.overview#16#p":"Le richieste \"porta la tua chiave\" aggirano completamente l'infrastruttura della piattaforma — la chiamata va diretta da Ava al fornitore, paghi il fornitore, nessun credito viene consumato. L'unica eccezione è quando una sessione BYOK avvia un'identità di livello gestito per un sotto-compito; la deduzione del credito si applica comunque perché viene utilizzata la superficie di orchestrazione di Ava.","credits.overview#17#h":"Dove controllare il saldo","credits.overview#18#li0":"Estensione — Impostazioni → Account, o la pillola dei crediti nell'intestazione della chat.","credits.overview#18#li1":"IDE — La scheda del cruscotto dell'account mostra il saldo corrente e il tasso di consumo.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard mostra saldo, cronologia e data di rinnovo.","credits.overview#19#c":"Local-first: Ava funziona senza account sulla scheda Modello Personalizzato (Ollama, LM Studio, vLLM o qualsiasi endpoint compatibile OpenAI). Nessun credito, nessun token della piattaforma — il tuo modello, la tua macchina, la tua fattura a zero.","concepts.modes#title":"Modalità — Stati d'animo di Ava","start.first-five#5#li0":"Una domanda — «perché la mia pagina è vuota?», «a cosa serve questo file?»","start.first-five#5#li1":"Qualcosa da costruire — «creami una pagina semplice per le cose da fare».","start.first-five#5#li2":"Per imparare qualcosa — «insegnami Python da zero». (Sempre gratis.)","start.first-five#5#li3":"Un documento — «scrivimi una proposta di progetto di una pagina». Ti consegnerà un file Word o PDF.","start.first-five#6#c":"Non sai cosa scrivere? Parla con lei come faresti con un amico esperto. Le parole semplici sono perfette — non ti servono mai i termini tecnici per iniziare.","start.first-five#deeper#0#p":"Questo semplice ciclo fa molto dietro le quinte. Non ti serve nessuna di queste cose per usare Ava — ma ecco cosa succede realmente se sei curioso.","start.first-five#deeper#1#h":"Strumenti e approvazione","start.first-five#deeper#2#p":"Quando Ava legge un file, esegue un comando o modifica codice, ciascuno di questi è una «chiamata strumento». Chiede prima di qualsiasi cosa che tocchi i tuoi file o il sistema — quanto spesso chiede è impostato dalla tua modalità di autorizzazione (chiedere ogni volta, chiedere solo per le cose rischiose, o semplicemente procedere).","start.first-five#deeper#3#h":"Modalità — i suoi stati d'animo","start.first-five#deeper#4#p":"Ava lavora in modalità: un approccio mentale più gli strumenti giusti per il lavoro. Cambia quando vuoi dal selettore, oppure digita un prefisso all'inizio del tuo messaggio. Sono sette.","start.first-five#deeper#6#h":"Specialisti e instradamento","start.first-five#deeper#7#p":"Nei lavori più difficili, Ava fa lavorare un piccolo team di aiutanti specializzati dietro le quinte (un pianificatore, un controllore, un costruttore) e instrada ogni passaggio al modello migliore per quello. Non devi gestire nulla di tutto questo — lei coordina tutto per te.","start.local-vs-cloud#title":"Locale vs cloud, in un paragrafo","start.local-vs-cloud#0#p":"Tutto ciò che fa Ava è locale a meno che tu non lo autorizzi esplicitamente. Memoria, compiti, diario, personalità, impostazioni — tutto salvato sulla tua macchina in ~/.ava/ e .ava/ (per progetto). Parla con i provider di modelli via HTTPS per eseguire la tua richiesta, poi torna a casa. Non richiama a casa. Non raccoglie telemetria. Non si addestra sul tuo codice.","start.local-vs-cloud#1#p":"Se accedi, ricevi 300 crediti gratuiti al mese sui modelli gestiti dalla piattaforma (Qwen, MiniMax) e la sincronizzazione cloud opzionale per memoria e impostazioni tra macchine. La sincronizzazione è per funzionalità, revocabile in qualsiasi momento. Porta la tua chiave API e Ava funziona completamente senza account.","start.local-vs-cloud#2#c":"La regola: il locale è sacro. Il cloud è aggiuntivo.","start.first-model#title":"Devo scegliere un'IA?","start.first-model#0#p":"Ecco una consolazione: non scegli tu l'IA. Ava sceglie quella giusta per ogni passaggio automaticamente, così ottieni buoni risultati senza doverci pensare.","start.first-model#1#p":"L'unica cosa che puoi scegliere è uno stile di instradamento — e quello predefinito va bene per quasi tutti. Ti servono gli altri solo per motivi specifici.","start.first-model#2#h":"I tre stili","start.first-model#3#li0":"Maestro — il predefinito. Solido, affidabile, prevedibile. Non sei sicuro? È questo.","start.first-model#3#li1":"Supernova — per lavori complessi in più passaggi, dove conviene mettere uno specialista diverso per ogni parte del compito.","start.first-model#3#li2":"Aurora — quando i tuoi dati devono rimanere nell'UE (settore pubblico, sanità, privacy rigorosa). Esegue interamente su IA europea a peso aperto.","start.first-model#4#p":"Cambia quando vuoi dal selettore dei modelli in alto nella chat. Nulla è bloccato.","start.first-model#5#c":"Vuoi guidare tu stesso un modello specifico? Puoi farlo — apri «Mostrami i dettagli».","concepts.desktop-safety#3#li2":"Mutativo reversibile — digita in un campo, incolla, apri un'app, naviga su un URL. Conferma in modalità Chiedi; automatico in Drive se nella lista autorizzata.","concepts.desktop-safety#3#li3":"Mutativo irreversibile — invia, invia modulo, paga, cancella, conferma, pubblica. Conferma sempre, indipendentemente dal livello di permesso. L'approvazione non viene mai memorizzata.","concepts.desktop-safety#3#li4":"Privilegiati — elevazione UAC, sudo, modifiche al registro, richieste di credenziali. Vietati di default. Richiede un consenso esplicito singolo per ogni sessione.","concepts.desktop-safety#4#h":"Approvazioni mai memorizzate","concepts.desktop-safety#5#p":"Ogni concorrente memorizza le approvazioni (ricorda il tuo \"sì\" e lo usa la prossima volta). Questo è il punto di ingresso più grande per l'iniezione di prompt — un attacco in cui una pagina web insidiosa inserisce istruzioni nascoste nell'AI per farla agire contro di te. Se le approvazioni vengono memorizzate, una pagina compromessa può approfittare di un \"sì\" che hai dato in precedenza. Ava non memorizza mai. Ogni azione mutativa irreversibile richiede una nuova conferma.","concepts.desktop-safety#6#h":"Gestione dei segreti","concepts.desktop-safety#7#p":"Password, chiavi API e codici 2FA (i codici monouso che un'altra app o un SMS ti danno quando accedi) sono gestiti tramite riferimenti opachi — segnaposto che sostituiscono il valore reale. Ava vede \"{secret}\", non la password vera. Il valore reale non entra mai nella sua memoria, nel suo registro delle attività o in ciò che \"legge\" — uno strato separato a basso livello lo digita nell'ultimo istante, premendo i tasti, così la parte AI non lo tocca mai.","reference.cli#title":"Comandi CLI","reference.cli#0#p":"Questa pagina è dedicata alla CLI — la versione di Ava con cui interagisci digitando in una finestra del terminale, invece di cliccare sui pulsanti. Se usi l'estensione o l'app desktop, puoi ignorarla del tutto. È presente per chi preferisce usare la tastiera.","reference.cli#1#p":"La CLI è un REPL — un prompt che attende che tu digiti, esegue quanto scritto, poi attende di nuovo. Questi comandi slash (istruzioni che iniziano con \"/\") funzionano direttamente dal prompt.","reference.cli#2#li0":"/help — elenca i comandi e la modalità corrente.","reference.cli#2#li1":"/mode <nome> — cambia modalità (lavoro, scrittura, pianificazione, chat, insegnamento, sicurezza, brainstorming).","reference.cli#2#li2":"/model <id> — cambia modello senza uscire dalla sessione.","reference.cli#2#li3":"/clear — cancella la conversazione corrente. La memoria resta intatta.","reference.cli#2#li4":"/history — elenca le conversazioni passate in questo progetto.","reference.cli#2#li5":"/memory — apri il browser della memoria.","reference.cli#2#li6":"/tasks — elenca e gestisci i compiti.","reference.cli#2#li7":"/journal — apri l'entrata del diario di oggi.","reference.cli#2#li8":"/settings — apri il menu delle impostazioni.","reference.cli#2#li9":"/exit — esci dal REPL.","reference.cli#3#h":"Flag di avvio","reference.cli#4#p":"I flag sono opzioni aggiuntive da aggiungere quando avvii Ava, ognuna inizia con \"--\", per impostare come viene avviata.","reference.cli#5#li0":"--mode <nome> — avvia in una modalità specifica.","reference.cli#5#li1":"--model <id> — avvia con un modello specifico.","reference.cli#5#li2":"--permission <modalità> — rigoroso / bilanciato / autonomo.","concepts.modes#0#p":"Una modalità è il modo di pensare di Ava — come un collega che cambia cappello. Stessa persona, stesso ricordo di te, ma un costruttore pensa diversamente da un insegnante. Scegli la modalità e cambierà il suo comportamento e gli assistenti che porta con sé. Cambia quando vuoi usando il selettore di modalità o digitando una scorciatoia di due caratteri.","concepts.modes#2#h":"Quale preferisci?","concepts.modes#3#p":"Parti da ciò che vuoi fare — la modalità ne consegue:","concepts.modes#4#li0":"Voglio costruire o modificare qualcosa → Codice (>>). Tu lo descrivi, lei lo costruisce mostrandoti ogni modifica prima. L'intero team di assistenza interviene per i lavori più grandi.","concepts.modes#4#li1":"Voglio un piano prima di qualsiasi modifica → Piano (::). Ci riflette sopra e ti consegna un piano da approvare o modificare. In questa modalità non toccherà i tuoi file.","concepts.modes#4#li2":"Voglio solo parlare o chiedere → Chat (..). Un partner pensante con memoria, notizie e meteo. Nessuna modifica ai file, nessun codice — solo conversazione.","concepts.modes#4#li3":"Voglio imparare qualcosa → Insegna (??). Un corso vero e proprio creato per te: lezioni, quiz, tutto quanto. Gratuito su tutti i piani, per sempre. Perfetto se sei nuovo.","concepts.modes#4#li4":"Voglio controllare il progetto alla ricerca di falle di sicurezza → Sicurezza (!!). Un team esamina l'elenco standard delle vulnerabilità web comuni (le categorie \"OWASP\") e le difetti noti segnalati (chiamati \"CVE\"), poi ti consegna un rapporto ordinato in base alla gravità di ciascun problema. Questo è rivolto agli sviluppatori — saltalo se non lo sei.","concepts.modes#4#li5":"Voglio idee → Brainstorm (**). Genera opzioni basate sulla tua situazione reale, smonta quelle deboli e affina le altre in prossimi passi.","concepts.modes#4#li6":"Voglio scrivere un documento → Scrivi (<<). Report, proposte, lettere, articoli — bozza in Markdown ed esporta un documento Word o PDF con marchio, affinando sezione per sezione. Nessun codice, solo scrittura.","concepts.modes#5#c":"Il \"team di assistenza\" (ruoli) lavora interamente dietro le quinte — non parli mai direttamente con loro. Ricevi semplicemente una risposta più completa. Non devi conoscere i loro nomi.","concepts.modes#6#c":"Puoi cambiare modalità durante la conversazione. La tua memoria viene mantenuta; gli specialisti si resettano per adattarsi alla nuova modalità.","concepts.tasks-journal#title":"Compiti e diario","concepts.tasks-journal#0#p":"Ava tiene tre tipi di note per te, ed è facile confonderle. Il modo veloce per ricordarle: la memoria è ciò che sa di te, i compiti sono ciò che devi ancora fare, e il diario è un resoconto di come sono andate le cose. Ecco quando usare quale.","concepts.tasks-journal#1#li0":"Memoria — fatti persistenti. Preferenze, decisioni, schemi. Chiesti ripetutamente, raramente creati manualmente.","concepts.tasks-journal#1#li1":"Compiti — cose da fare. Azioni con scadenze e stato. Le spunti quando sono finite.","concepts.tasks-journal#1#li2":"Diario — riflessione. Registro giornaliero, voci doppie (tue e osservazioni di Ava sulla sessione). Utile per tracciare l'umore, revisioni della sessione, contesto per domani.","concepts.tasks-journal#2#p":"Ava scrive in tutte e tre quando ha senso. Puoi scrivere in ognuna direttamente dalla dashboard. Nulla è bloccato in un unico posto dove usi Ava — un compito che crei in uno (diciamo lo strumento a riga di comando) appare ovunque altrove (come l'app desktop), automaticamente.","concepts.permissions#title":"Permessi — la manopola della tua sicurezza","concepts.permissions#0#p":"I permessi sono la manopola della tua sicurezza. Decidono quando Ava chiede il tuo ok prima di fare qualcosa sul tuo computer, invece di procedere subito. Puoi impostarla per chiedere di tutto, chiedere solo sulle cose rischiose, o fidarti che giri — e puoi cambiarlo in qualsiasi momento. Se non sei sicuro, lascialo su predefinito e starai bene.","concepts.permissions#1#p":"Ava ha 60 strumenti (gli \"strumenti\" sono le azioni che può compiere — leggere un file, cercare sul web, ecc.). Ogni strumento appartiene a una categoria (operazioni sui file, shell, Git, web, multimedia, database, sistema, documenti, memoria, apprendimento). Ogni chiamata allo strumento passa attraverso il cancello dei permessi (un punto di controllo che decide se chiederti prima) prima di essere eseguita. Controlli cosa viene approvato automaticamente, cosa chiede una volta e cosa chiede sempre.","concepts.permissions#3#p":"Bilanciato è il predefinito. Rigido quando stai verificando il suo comportamento (guardando da vicino per controllare ogni passo). Autonomo quando vuoi che proceda da sola.","concepts.permissions#4#c":"Autonomo non significa senza controllo. Piani, domande chiarificatrici e richieste esplicite all'utente si fermano comunque per il tuo input. Operazioni irreversibili (Git force-push, eliminazioni del database) confermano sempre indipendentemente dalla modalità.","concepts.interjection#title":"Guidare e fermare Ava","concepts.interjection#0#p":"Sei sempre tu il responsabile. Mentre Ava è impegnata a lavorare, puoi sia indirizzarla verso una nuova direzione senza interrompere il flusso, sia fermarla immediatamente. Due pulsanti, due risultati — ecco tutto quello di cui parla questa pagina.","features.creative-studio#1#p":"Generazione di immagini, video, musica e voce — integrata nello stesso flusso di lavoro del tuo codice. Crea un'icona, una bozza di prodotto, un video dimostrativo, una voce narrante per un tutorial. Alimentato da MiniMax.","features.creative-studio#2#h":"Cosa puoi creare","features.creative-studio#3#li0":"Immagini — da prompt a PNG/JPG. Rimozione dello sfondo a un clic di distanza.","features.creative-studio#3#li1":"Video — brevi video AI generati da un prompt testuale (MiniMax Hailuo).","features.creative-studio#3#li2":"Musica — brani strumentali o vocali con testi.","features.creative-studio#3#li3":"Voce — sintesi vocale con voci selezionabili.","features.creative-studio#4#p":"I costi di Creative Studio provengono dallo stesso pool di crediti di tutto il resto — un unico pool, un unico numero. Utilizza la tua chiave MiniMax (BYOK) e diventa gratuito per il tuo piano.","features.creative-studio#5#c":"Creative Studio è eleggibile per il piano gratuito. Non è un'aggiunta a pagamento.","features.desktop-automation#title":"Automazione Desktop","features.desktop-automation#0#p":"In parole semplici: Ava può prendere il controllo del tuo mouse e della tastiera per eseguire compiti per te — aprire un'app, fare clic sui pulsanti, compilare un modulo — mentre tu guardi e approvi qualsiasi cosa importante.","features.desktop-automation#1#p":"Una nuova modalità per Ava, prefisso @@. Osserva il desktop, decide cosa fare e guida l'automazione dell'interfaccia utente (controllando le app sul tuo schermo per te) per completare il compito. Esegue sulla tua macchina reale con le tue credenziali reali — non un browser cloud. Disponibile su ogni livello una volta rilasciata.","features.desktop-automation#2#h":"Perché un'altra soluzione","features.desktop-automation#3#p":"Ogni altro prodotto di automazione desktop è qualcosa che attivi quando sei alla tua scrivania. Ava è quella che c'è ancora quando il tuo tracciatore di errori scatta alle 2 di notte — l'IDE continua a funzionare, il tuo telefono si accoppia tramite un canale sicuro, approvi le azioni irreversibili con un tocco.","features.desktop-automation#4#p":"Lei ricorda anche come navigare nelle tue app tra le sessioni. Ogni altro agente deve reimpararle ogni volta. La differenza data dalla memoria si accumula con l'uso.","features.desktop-automation#5#h":"Come funziona","features.desktop-automation#6#p":"Ogni passaggio attiva un'onda a cinque ruoli: Esploratore osserva, Pianificatore sceglie l'azione successiva, Esecutore esegue, Verificatore controlla, Narratore ti spiega cosa è successo. Il sidecar sceglie il metodo di ancoraggio più economico e affidabile — UIA per le app native, Playwright per i browser, visione OmniParser quando nessun altro offre un albero utile.","features.desktop-automation#7#p":"Consulta le pagine dei concetti per la ontologia di sicurezza, la gerarchia di ancoraggio, gli interruttori di sicurezza e il modello di lista bianca delle sessioni.","reference.cli#5#li3":"--project <path> — imposta esplicitamente la radice del progetto.","reference.desktop-budget#title":"Limiti di budget per il desktop","reference.desktop-budget#0#p":"Quando Ava controlla il tuo desktop per tuo conto — cliccando, digitando, aprendo app — ogni esecuzione è chiamata \"traiettoria\". Questa pagina spiega i limiti di sicurezza che impediscono a una singola esecuzione di durare troppo a lungo o costare troppo. Il concetto chiave: lei si ferma sempre e fa un controllo prima di superare i limiti. I numeri sono qui se vuoi i dettagli.","reference.desktop-budget#1#p":"Ogni traiettoria opera sotto tre limiti simultanei (limiti rigidi). Vince quello raggiunto per primo. La traiettoria non prosegue mai silenziosamente oltre una violazione: il Narratore (l'assistente che ti accompagna spiegando cosa sta succedendo) si ferma e chiede cosa fare.","reference.desktop-budget#2#h":"Tre limiti rigidi (predefiniti)","reference.desktop-budget#3#li0":"Conteggio passaggi — 30 passaggi","reference.desktop-budget#3#li1":"Budget token — 500,000 token","reference.desktop-budget#3#li2":"Tempo reale — 5 minuti","reference.desktop-budget#4#h":"Fasce di costo per compito","reference.desktop-budget#5#li0":"Semplice (cerca documenti, apri una pagina) — 5–10 passaggi, ~70–135K token, ~$0.04–0.08","reference.desktop-budget#5#li1":"Medio (accedi, controlla i log, scarica l'output) — 15–25 passaggi, ~205–340K token, ~$0.12–0.21","reference.desktop-budget#5#li2":"Complesso (gestisci tre GitHub issue) — 25–30 passaggi, ~340–410K token, ~$0.21–0.25","reference.desktop-budget#6#p":"Le cifre sui token sopra sono i limiti tecnici per traiettoria, non il tuo mensile — questo viene conteggiato in crediti, e i 300 al mese del piano gratuito coprono comodamente una miscela di chat, codice e alcune automazioni.","reference.desktop-budget#7#c":"Puoi sovrascrivere i limiti per compito all'inizio, ma le violazioni mostrano sempre un punto di decisione. Il budget non viene mai consumato silenziosamente.","reference.desktop-whitelist#title":"Lista autorizzata per sessione desktop","reference.desktop-whitelist#0#p":"Una \"lista autorizzata\" è semplicemente l'elenco delle app e dei siti web che hai detto ad Ava essere autorizzati a toccare mentre controlla il tuo desktop. Questa pagina spiega come concedere tale permesso e perché si resetta ogni volta. In breve: può agire solo dove le permetti e chiede prima di andare da qualche parte di nuovo.","reference.desktop-whitelist#1#p":"All'inizio di una sessione desktop Ava chiede dove è autorizzata ad agire. L'italiano semplice va bene: \"Gmail, Cursor, il portale Azure.\" Lo legge e conferma la corrispondenza con te (\"Gmail web, l'app Cursor, portal.azure.com\").","reference.desktop-whitelist#2#h":"Come viene applicato","reference.desktop-whitelist#3#p":"Azioni solo visualizzazione — scattare uno screenshot, leggere l'elenco di pulsanti e campi sullo schermo (l'\"albero UIA\", la mappa propria di Windows di ciò che c'è in una finestra) — sono consentite ovunque, perché devi vedere cosa c'è sullo schermo per decidere se aggiungere un'app alla lista autorizzata. Tutto ciò che modifica qualcosa è bloccato fuori dall'elenco; Ava si ferma e chiede se aggiungerlo.","reference.desktop-whitelist#4#h":"Confinato alla sessione, deliberatamente","reference.desktop-whitelist#5#p":"La lista autorizzata NON persiste tra le sessioni. Non esiste l'opzione \"ricorda questa app\". Ogni nuova traiettoria inizia con un ambito nuovo. Scomodo per scelta progettuale — dimenticare di ri-autorizzare è una funzionalità, non un bug.","reference.desktop-whitelist#6#h":"Aggiunte durante la traiettoria","reference.desktop-whitelist#7#p":"Durante una traiettoria puoi aggiungere app dall'intestazione: \"+ Consenti app\" apre un piccolo campo di inserimento. Tocca Aggiungi e la nuova app è attiva per il resto della sessione.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Vuoi creare un'immagine, un video breve, una canzone o una voce narrata? Descrivilo e Ava lo crea per te — non serve alcun software di design o audio.","concepts.interjection#1#p":"Ava continua finché il suo piano non è completato o finché non la fermi. Hai due modi per intervenire (il termine per questo è \"intervenire\") mentre sta lavorando.","concepts.interjection#2#h":"Intervieni — guida senza annullare","concepts.interjection#3#p":"Digita un nuovo messaggio mentre Ava lavora. Termina la chiamata dello strumento corrente, legge il tuo messaggio e aggiusta il suo piano. Nessun contesto viene perso. Usalo quando vuoi reindirizzare, aggiungere informazioni o cambiare priorità durante l'esecuzione.","concepts.interjection#4#h":"Arresto immediato — annulla e pulisci","concepts.interjection#5#p":"Premi Esc (CLI), clicca su Stop (estensione, IDE), o digita un comando di arresto. L'esecuzione corrente viene annullata, le chiamate degli strumenti in sospeso vengono eliminate e la conversazione è pronta per un nuovo turno.","concepts.interjection#6#c":"Intervieni prima. L'arresto immediato serve quando c'è davvero un problema. Intervenire mantiene viva la conversazione.","concepts.desktop-personas#title":"Profili Desktop","concepts.desktop-personas#0#p":"Questa pagina è per i curiosi e per gli utenti esperti. L'\"automazione desktop\" (a volte chiamata \"uso del computer\") significa che Ava può effettivamente cliccare sullo schermo e usare le app per te — aprire Gmail, compilare un modulo, inviare un messaggio — come una persona alla tastiera. Per farlo in sicurezza, divide il lavoro tra cinque piccoli aiutanti, ognuno con un ruolo specifico. Non interagisci mai direttamente con loro; questa pagina ti mostra solo chi fa cosa.","concepts.desktop-personas#1#p":"Ogni passo in una traiettoria desktop (un'esecuzione di Ava che guida il tuo schermo verso un obiettivo) attiva un'onda di cinque ruoli. Ogni ruolo ha un compito e solo un compito. La separazione mantiene i prompt concisi, gli output strutturati e il ragionamento scettico per progettazione.","concepts.desktop-personas#2#h":"Esploratore","concepts.desktop-personas#3#p":"Riporta ciò che è visibile sullo schermo in questo momento. Non inventa elementi. Non pianifica. Restituisce un JSON ScreenState con ID elemento, nomi, bboxes, confidenza e una fonte di ancoraggio (UIA, Playwright DOM, o visione OmniParser).","concepts.desktop-personas#4#h":"Pianificatore","concepts.desktop-personas#5#p":"Decide l'unica azione successiva. Un'azione per passo — mai in batch. Preferisce percorsi reversibili. Classifica il rischio secondo l'ontologia di sicurezza. Produce un JSON ProposedAction con tipo, target, parametri, riskClass, ragionamento e una previsione expectedPostState.","concepts.desktop-personas#6#h":"Esecutore","concepts.desktop-personas#7#p":"Esegue esattamente quanto proposto dal Pianificatore — dopo che il cancello di approvazione è stato superato. Nessuna improvvisazione. Nessun tentativo di ripetizione. Il fallimento viene riportato fedelmente e il Verificatore gestisce il prossimo movimento.","concepts.desktop-personas#8#h":"Verificatore","concepts.desktop-personas#9#p":"Controlla se l'azione è andata a buon fine. Confronta il nuovo ScreenState con la previsione del Pianificatore. Restituisce verified, deviated, o rollback_needed. Esegue anche il rilevamento di loop — ripetere un'azione già riuscita è una deviazione, non una verifica.","concepts.desktop-personas#10#h":"Narratore","concepts.desktop-personas#11#p":"L'unica voce che l'utente sente durante una traiettoria. Una frase al passato per passo (\"Aperto Gmail.\", \"Cliccato Componi.\"). Scrive anche il registro di audit strutturato. Dice quando qualcosa va storto — non nasconde mai un problema.","concepts.desktop-safety#title":"Ontologia di sicurezza desktop","concepts.desktop-safety#0#p":"In breve: prima che Ava clicchi qualsiasi cosa sul tuo schermo, classifica l'azione in base al rischio. Leggere lo schermo? Inoffensivo. Inviare denaro o eliminare qualcosa? Si ferma sempre e ti chiede prima — ogni singola volta, senza eccezioni. Le cinque etichette qui sotto sono solo i gradini di quella scala dei rischi. Questo è un dettaglio per utenti esperti, ma il concetto è semplice: le cose pericolose richiedono sempre il tuo sì.","concepts.desktop-safety#1#p":"Ogni azione proposta è classificata in una delle cinque classi di rischio. La classificazione combina tre segnali — qual è il bersaglio sullo schermo, una descrizione in linguaggio semplice (\"didascalia semantica\" — le parole di Ava su ciò che sta guardando), e le impostazioni dell'azione — ed eleva il livello (tratta come più rischioso) quando non concordano. Un falso positivo (chiedere quando non era necessario) è solo un fastidio. Un falso negativo (non chiedere quando avrebbe dovuto) è un incidente grave.","concepts.desktop-safety#2#h":"Le cinque classi","concepts.desktop-safety#3#li0":"Osservazionale — leggi albero UIA, screenshot, hover. Sempre consentito automaticamente.","concepts.desktop-safety#3#li1":"Navigazionale — scorri, sposta il focus, apri un menu. Consentito automaticamente in modalità Drive."},"pl":{"start.for-non-coders#6#li3":"Kiedy chcesz, żeby coś faktycznie stworzyła lub zmieniła, po prostu zapytaj – ona zawsze pokaże ci, co zamierza zrobić i zaczeka na twoje „tak\".","start.for-non-coders#7#c":"Napotkasz słowo, którego nie rozpoznajesz? Prosty glosariusz (niżej w tej sekcji) wyjaśnia każdy termin bez zakładania wiedzy wstępnej.","start.install#title":"Instalacja","start.install#0#p":"Wybierz środowisko, które najlepiej pasuje do Twojej pracy. Możesz użyć więcej niż jednego – Ava synchronizuje swoją pamięć między nimi, gdy się zalogujesz.","start.install#1#h":"Rozszerzenie VS Code","start.install#2#li0":"Otwórz panel Rozszerzenia w VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Wyszukaj „Ava Supernova\" i kliknij Zainstaluj.","start.install#2#li2":"Naciśnij Ctrl+Shift+A (Cmd+Shift+A na macOS), aby otworzyć panel czatu.","start.install#2#li3":"Postępuj zgodnie z kreatorem konfiguracji – wybierz model, ustaw tryb uprawnień i gotowe.","start.install#3#h":"Środowisko IDE na pulpit","start.install#4#li0":"Pobierz instalator dla swojej platformy ze strony z wersjami.","start.install#4#li1":"Uruchom go. IDE uruchomi się z ekranem powitalnym przy pierwszym starcie.","start.install#4#li2":"Zaloguj się, aby uzyskać darmowe tokeny platformy, lub wklej swój własny klucz API, aby działać w pełni lokalnie.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (lub pnpm / yarn — Twój wybór).","start.install#6#li1":"Uruchom  ava  w dowolnym katalogu projektu.","start.install#6#li2":"Przy pierwszym uruchomieniu zostaniesz poproszony o podanie dostawcy i modelu. Wybierz i ruszaj.","start.install#7#c":"Brak konta? To żaden problem. Posiadając własny klucz API (BYOK), nigdy nie musisz się logować. Darmowy plan dotyczy modeli zarządzanych przez platformę.","start.for-non-coders#title":"Nigdy nie pisałeś kodu? Zacznij tutaj","start.for-non-coders#0#p":"Jeśli nigdy nie napisałeś linii kodu, jesteś dokładnie tym, dla kogo stworzona jest Ava. Nie musisz znać żadnego żargonu, aby zacząć — rozmawiasz z nią zwykłym językiem, tak jak pytasz wiedzącego przyjaciela. Ta strona to cała Twoja droga startowa.","start.for-non-coders#1#h":"Co możesz zrobić dzisiaj, bez doświadczenia","start.for-non-coders#2#li0":"Zapytaj ją o cokolwiek, normalnymi słowami — \"co robi ten plik?\", \"dlaczego moja strona jest pusta?\", \"co właściwie jest bazą danych?\" Odpowiada prostym językiem i zapamiętuje rozmowę.","start.for-non-coders#2#li1":"Naucz się czegoś od podstaw — powiedz \"naucz mnie Pythona od zera\", a ona stworzy Ci odpowiedni kurs z lekcjami i quizami. To zawsze darmowe.","start.for-non-coders#2#li2":"Zbuduj coś — opisz, czego chcesz (\"przycisk pobierający moje notatki\"), a ona napisze to, pokazując Ci każdą zmianę przed jej wprowadzeniem.","start.for-non-coders#3#h":"Nie musisz rozumieć wszystkiego","start.for-non-coders#4#p":"Ava ma dużo mechanizmów pod maską — tryby, modele, specjaliści, routing. Zobaczysz te słowa wokół aplikacji i w tej dokumentacji. Oto sekret: możesz zignorować prawie wszystko. Ava dobiera odpowiednie narzędzia i pomocników automatycznie. Strony techniczne są tam, gdy poczujesz ciekawość, nie dlatego, że musisz je znać, żeby zacząć.","start.for-non-coders#5#h":"Delikatna ścieżka na start","start.for-non-coders#6#li0":"Zainstaluj Avę (następna strona) i otwórz czat.","start.for-non-coders#6#li1":"Wpisz prawdziwe pytanie, które masz. Cokolwiek. Zobacz, jak odpowiada.","start.for-non-coders#6#li2":"Spróbuj trybu nauki: wpisz \"naucz mnie\" i temat. Podążaj za nią.","concepts.memory#title":"Pamięć — jak Ava Cię zapamiętuje","concepts.memory#0#p":"Prostymi słowami: Ava Cię zapamiętuje. Powiedz jej coś raz — co lubisz, jaką decyzję podjąłeś — i ona to przechowuje, więc nie musisz powtarzać tego w następnej rozmowie czy za tydzień. To jest główna informacja. Warstwy poniżej wyjaśniają tylko, jak utrzymuje tę pamięć w porządku z czasem.","concepts.memory#1#p":"Ava ma trwałą pamięć (\"trwała\" oznacza, że pozostaje po zamknięciu aplikacji), która przetrwa między rozmowami, między projektami i między urządzeniami, jeśli włączysz synchronizację (synchronizacja kopiuje Twoją pamięć między urządzeniami). To nie jest dziennik czatu. To ustrukturyzowane, wyszukiwalne zrozumienie tego, kim jesteś, co lubisz i co zdecydowałeś.","concepts.memory#2#h":"Pięć warstw","concepts.memory#3#li0":"Wyodrębnianie — kluczowe fakty przechwytywane z każdej wiadomości w czasie rzeczywistym.","concepts.memory#3#li1":"Refleksja — głębsza analiza uruchamiana na końcu wartościowych sesji. Wzorce, tematy, sprzeczności.","concepts.memory#3#li2":"Kumulowanie — poprawki i preferencje kumulują się przez tygodnie i miesiące.","concepts.memory#3#li3":"Analiza — silnik grafowy łączy powiązane wspomnienia i sygnalizuje sprzeczności, gdy nowe informacje kolidują ze starymi.","concepts.memory#3#li4":"Utrwalanie — podobne wspomnienia łączą się; przestarzałe są usuwane. Pamięć staje się z czasem ostrzejsza, a nie bardziej szumna.","concepts.memory#4#c":"Pięć powyższych warstw działa samoistnie — nigdy nie musisz nimi zarządzać. Są tutaj, abyś widział, że pamięć naprawdę się poprawia z czasem, zamiast zamieniać się w stos bałaganu.","concepts.memory#5#h":"Przywoływanie","concepts.memory#6#p":"Gdy zadajesz pytanie, Ava przeszukuje pamięć według znaczenia (\"wyszukiwanie semantyczne\" — rozumie, co masz na myśli, więc znajduje właściwą pamięć nawet jeśli sformułujesz to inaczej), a nie tylko poprzez dopasowanie słów. Filtry zależne od trybu działają obok — Tryb Czat pobiera kontekst osobisty, Tryb Praca decyzje projektowe i wzorce kodu.","concepts.memory#7#c":"Pamięć jest ograniczona do użytkownika i projektu (Twoje wspomnienia należą do Ciebie, oddzielone osobno i według projektu). Sekrety i dane uwierzytelniające (hasła, klucze) są blokowane na granicy zapisu — nigdy nie mogą trafić do pamięci.","reference.models#11#h":"Własny klucz","reference.models#12#p":"An \"API key\" is a private password that lets software use a paid service on your own account. \"BYOK\" just means \"bring your own key\" — using yours instead of ours. Paste your API key in settings. BYOK requests go direct from Ava to the provider (the company that runs the model) — they do not pass through our infrastructure and do not consume platform tokens. You pay the provider; we do not see the traffic.","reference.models#14#c":"Do wyników testów, znaczników możliwości i porównań obok siebie zobacz pełną stronę Modeli na ava-supernova.com/models. Ceny pokazane powyżej to nasze najlepsze odczyty cenników każdego dostawcy w momencie publikacji — zawsze sprawdzaj stronę dostawcy przed podjęciem pracy.","reference.personas#title":"Orkiestracja ról","reference.personas#0#p":"\"Rola\" to pomocnicza rola, którą Ava odgrywa w tle przy trudniejszych zadaniach — badaczka, planistka, weryfikatorka faktów. Nigdy nie rozmawiasz z nimi bezpośrednio i nie musisz rozumieć tej strony, aby używać Avy. Jest tu dla Ciebie, gdy jesteś ciekawa, jak ona dzieli duże zadanie na mały zespół ekspertów.","reference.personas#1#p":"24 specjalistów z 5 zespołów trybów. Dyrygent (pomocnik koordynujący resztę) decyduje, który zespół działa, w jakiej kolejności i z jakim kontekstem. Tryb czatu nie ma ról — to sama Ava.","reference.personas#2#h":"Jak działa orkiestracja","reference.personas#3#li0":"Wysyłasz wiadomość w trybie Planowanie, Nauka, Bezpieczeństwo lub Burza mózgów (lub złożone żądanie Praca).","reference.personas#3#li1":"Dyrygent czyta żądanie, wybiera zespół trybu i buduje plan wykonania — niektóre role działają sekwencyjnie, niektóre falami równoległymi.","reference.personas#3#li2":"Każda rola ma swoją własną podpowiedź systemową, ograniczoną listę zatwierdzonych narzędzi i wspólną pulę kontekstu tego, co znalazły poprzednie role.","reference.personas#3#li3":"Ostateczna rola tworzy podsumowanie, plan lub raport, w zależności od trybu.","reference.personas#3#li4":"Ava przedstawia Ci wynik. Ty zatwierdzasz, poprawiasz lub przekierowujesz.","reference.personas#4#p":"Pełna lista poniżej jest tylko informacyjna — nie musisz pamiętać, kto co robi. Ava dobiera odpowiedni zespół dla Ciebie.","reference.personas#6#c":"Tryb Praca wywołuje pełny zespół tylko dla złożonych zadań. Proste edycje uruchamiają Avę bezpośrednio — bez nakładu operacji orkiestracji.","reference.config#title":"Konfiguracja","reference.config#0#p":"Ta strona pokazuje, gdzie Ava przechowuje swoje ustawienia i pliki na Twoim komputerze. Zazwyczaj nie musisz ich dotykać ręcznie — aplikacja zarządza nimi za Ciebie. Przydaje się, gdy chcesz zobaczyć, zrobić kopię zapasową lub udostępnić te pliki samodzielnie.","reference.config#1#p":"Ava odczytuje konfigurację (swoje zapisane ustawienia) z dwóch zakresów. Ustawienia globalne — obowiązywane wszędzie — znajdują się w folderze ~/.ava/ (symbol \"~\" oznacza Twój folder domowy). Ustawienia dla konkretnego projektu mieszczą się w folderze .ava/ wewnątrz samego projektu.","reference.config#2#h":"Globalne — ~/.ava/","reference.config#3#li0":"settings.json — preferencje modelu, tryb uprawnień, osobowość, język.","reference.config#3#li1":"memory/ — Twoje globalne wspomnienia (preferencje, decyzje obowiązywane wszędzie).","reference.config#3#li2":"tasks.json — lista zadań między projektami.","reference.config#3#li3":"journal/ — codzienne wpisy dziennika, pogrupowane według daty.","reference.config#4#h":"Projekt — .ava/","reference.config#5#li0":"instructions.md — instrukcje specyficzne dla projektu, które Ava zawsze ładuje. Trwały kontekst (np. \"używamy pnpm, nie npm\", \"klucze API są w 1Password\").","reference.config#5#li1":"context.md — opcjonalne notatki projektowe w dowolnej formie.","reference.config#5#li2":"memory/ — wspomnienia ograniczone do tego projektu.","reference.config#5#li3":"datasets/config.json — konfiguracja rejestracji zbiorów danych (opcjonalna).","reference.config#6#c":"Dodaj .ava/ do swojego pliku .gitignore (lista plików, które Git ma ignorować w projekcie współdzielonym), jeśli nie chcesz udostępniać wspomnień zespołowi. Zachowaj instructions.md w repozytorium (folderze projektu współdzielonego) — dzięki temu Ava poznaje konwencje projektu.","reference.shortcuts#title":"Skróty klawiszowe","reference.shortcuts#0#p":"Skróty klawiszowe to opcjonalne przyspieszacze — każdy z nich jest też przyciskiem, który możesz kliknąć. Zajrzyj tutaj tylko, jeśli chcesz sterować Avą szybciej z klawiatury.","reference.shortcuts#1#p":"Skróty podzielone na środowiska (trzy miejsca, gdzie działa Ava: rozszerzenie VS Code, aplikacja desktopowa i terminal). Dostosuj je w ustawieniach każdego środowiska. Nie musisz zapamiętywać poniższej listy.","reference.project-context#title":"Kontekst projektu","reference.project-context#0#p":"To wyjaśnia, jak Ava zapoznaje się z Twoim projektem przed rozpoczęciem pracy — pliki, które sprawdza, aby zrozumieć, nad czym pracujesz. Nie musisz niczego z tego konfigurować; ona robi to sama. Przeczytaj to, jeśli chcesz wiedzieć, gdzie umieścić notatkę, aby zawsze ją widziała.","reference.project-context#1#p":"Ava ładuje kilka warstw kontekstu (informacji tła, które ma w pamięci), gdy otwierasz projekt. Zrozumienie warstw pomaga Ci umieścić informacje we właściwym miejscu.","reference.project-context#2#h":"Ładowane automatycznie","reference.project-context#3#li0":".ava/instructions.md — traktowane jako trwałe, priorytetowe wytyczne. Zawsze dostępne w kontekście.","reference.project-context#3#li1":".ava/context.md — notatki swobodne. Ładowane, niższy priorytet.","reference.project-context#3#li2":"README.md — skanowany przy pierwszym uruchomieniu pod kątem podsumowania projektu.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — małe pliki zawierające konfigurację projektu; czytane, aby wykryć język, framework i polecenie testowe.","reference.project-context#3#li4":".gitignore — lista plików pomijanych w systemie kontroli wersji; respektowana przez wszystkie narzędzia do plików (glob, grep, project_index).","reference.project-context#4#h":"Ładowane na żądanie","reference.project-context#5#p":"\"Na żądanie\" oznacza, że Ava pobiera je tylko wtedy, gdy zadanie faktycznie ich potrzebuje, a nie z góry.","reference.project-context#6#li0":"Indeks projektu — strukturalna mapa Twoich plików i nazwanych elementów w nich zawartych (funkcje, klasy — \\\"symbole\\\") oraz jak są połączone (\\\"importy\\\"). Tworzona leniwie, czyli tylko wtedy, gdy Ava jej potrzebuje.","reference.project-context#6#li1":"Historia Git — zapis poprzednich zmian; pobierana, gdy wywołane zostaną git_status, git_diff lub git_create_pr (Git to narzędzie śledzące każdą zmianę w projekcie; \\\"PR\\\" to pull request, proponowana partia zmian).","reference.project-context#6#li2":"Pamięć — wpisy dopasowywane są według znaczenia (\\\"semantycznie\\\") i wstrzykiwane po jednym kroku, a nie wszystkie naraz.","reference.project-context#7#c":"Zasady umieszczaj w instructions.md. Notatki w context.md. Pozostałe niech przechwyci pamięć sama.","features.unified-panel#title":"Połączony panel","features.unified-panel#0#p":"Prostymi słowy: wszystko, co robi Ava, mieści się w jednym oknie, więc nigdy nie musisz szukać w kartach, żeby to znaleźć.","features.unified-panel#1#p":"Jeden panel dla czatu, panelu głównego, pamięci, zadań i dziennika. Brak konieczności przełączania między oknami. Pasek boczny wybiera, czego szukasz; główny obszar dostosowuje się do tego.","features.unified-panel#2#p":"Stan rozmowy zachowuje się, gdy przejdziesz dalej — otwórz pamięć, sprawdź zadanie, potem wróć. Czat nadal tam jest, nadal się aktualizuje, jeśli Ava nadal działa.","features.unified-panel#3#c":"Połączony panel to koncepcja rozszerzenia i IDE. Interfejs sieciowy używa kart przeglądarki.","features.knowledge-packs#title":"Pakiety wiedzy","features.knowledge-packs#0#p":"Prostymi słowy: podaj Avie folder ze swoimi dokumentami, a ona może ich używać, aby odpowiadać na Twoje pytania. \"Pakiet wiedzy\" to po prostu ten zestaw plików — materiały pomocnicze, z których może korzystać.","features.knowledge-packs#1#p":"Wrzuć katalog materiałów pomocniczych (specyfikacje, RFC, notatki ze spotkań, dokumentacja API) do pakietu wiedzy. Ava może wyciągać odpowiednie fragmenty do kontekstu, gdy rozmowa porusza dany temat.","features.knowledge-packs#2#p":"Pakiety są indeksowane lokalnie. Wyszukiwanie jest semantyczne — Ava znajduje odpowiedni dokument według znaczenia, a nie nazwy pliku. (\"Semantyczne\" oznacza, że dopasowuje treść dokumentu, więc nie musisz pamiętać dokładnych słów ani nazwy pliku.) Pakiety można udostępniać zespołowi lub zachować prywatnie.","concepts.desktop-grounding#title":"Hierarchia zakorzenienia pulpitu (Podgląd)","concepts.desktop-grounding#0#c":"Podgląd — jak Scout decyduje, którego źródła zakorzenienia użyć w każdym kroku.","concepts.desktop-grounding#1#p":"Zanim Ava kliknie przycisk, musi naprawdę zrozumieć, co jest na twoim ekranie i gdzie znajdują się rzeczy — to jest „zakorzenienie” (ustalanie, czym jest każdy element na ekranie i jego dokładne położenie). Ma trzy sposoby na to i wybiera ten najbardziej niezawodny, który działa w aplikacji, której używasz. To szczegół dla zaawansowanych użytkowników; chodzi tylko o to, że preferuje solidne, dokładne metody niż zgadywanie na podstawie obrazka.","concepts.desktop-grounding#2#p":"Trzy poziomy, oceniane po kolei. Wygrywa najtańsze niezawodne źródło.","concepts.desktop-grounding#3#h":"1. Okno przeglądarki → Playwright DOM","concepts.desktop-grounding#4#p":"Jeśli aktywne okno to przeglądarka internetowa, Ava czyta strukturę strony („DOM” — podstawową listę tego, co jest na stronie) zamiast zgadywać na podstawie obrazka. Czytanie struktury jest około 10× bardziej niezawodne niż oglądanie pikseli — ona dokładnie wie, gdzie znajduje się każdy przycisk i kiedy strona zakończyła ładowanie. To główna ścieżka dla wszystkiego w sieci, a nie opcja zapasowa.","concepts.desktop-grounding#5#h":"2. Aplikacja natywna z UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Dla zwykłych aplikacji pulpitu na Windows, Ava czyta wbudowaną mapę dostępności („UIA”, te same dane, których używają czytniki ekranu do opisu okna) — wymienia każdy element sterujący, jego nazwę i gdzie się znajduje. Jeśli ta mapa zwraca co najmniej pięć używalnych, nazwanych elementów, ufa jej i jej używa.","concepts.desktop-grounding#7#h":"3. UIA puste lub bezwartościowe → Wizja OmniParser","concepts.desktop-grounding#8#p":"Gdy ta mapa brakuje lub jest bezużyteczna (niektóre aplikacje, gry i zdalne ekrany jej nie dostarczają), Ava wraca do faktycznego patrzenia na zrzut ekranu. Narzędzie wizyjne (OmniParser) wykrywa obszary klikania i opisuje, czym jest każdy z nich, zamieniając obrazek z powrotem na listę, na której może działać — w połączeniu z tym wszystkim, co mapa dostępności dała.","concepts.desktop-grounding#9#c":"OmniParser jest opcjonalny przy pierwszym użyciu, gdy Ava go potrzebuje, z jasnym monitem dotyczącym prywatności. Użytkownicy BYOK mogą wskazać własną lokalną instalację OmniParser.","concepts.desktop-kill-switches#title":"Wyłączniki awaryjne pulpitu (Podgląd)","concepts.desktop-kill-switches#0#c":"Podgląd — trzy niezależne sposoby przerwania biegnącej trajektorii. Wystarczy jeden z nich.","concepts.desktop-kill-switches#1#p":"„Wyłącznik awaryjny” to dosłownie to, co sugeruje nazwa — sposób awaryjny natychmiastowego zatrzymania Avy, gdy kontroluje twój ekran. Uspokajająca część: są ich trzy, każdy zbudowany oddzielnie, więc jeśli jeden zawiedzie, inny nadal działa. Nie musisz uczyć się wszystkich trzech. Po prostu wiedź, że gdy coś wygląda źle, zawsze możesz to zatrzymać, a najsilniejsze zatrzymanie (panikowy wyłącznik poniżej) nie polega na współpracy Avy.","concepts.desktop-kill-switches#2#p":"Po przeczytaniu każdego publicznego incydentu autonomii (rzeczywistych przypadków, w których agenci AI ignorowali polecenia zatrzymania, usuwali archiwa e-mail, czyszcząc dyski), zbudowaliśmy trzy wyłączniki awaryjne w trzech różnych warstwach. Żaden z nich nie zależy od samego modelu AI — jeśli Ava utknęła lub nie odpowiada, nadal możesz ją zatrzymać.","concepts.desktop-kill-switches#3#h":"Pauza — spacja lub przycisk Pauza","features.workflows#title":"Przepływy pracy","features.workflows#0#p":"Mówiąc prosto: naucz Avę rutyny, którą wykonujesz wielokrotnie, nadaj jej nazwę, a ona może uruchomić całość na żądanie. „Przepływ” to po prostu zapisana rutyna — zestaw kroków, które Ava powtarza dla Ciebie.","features.workflows#1#p":"Zapisz sekwencję kroków, które masz tendencję powtarzać — przegląd PR → uruchom testy → napisz notatki wydania → przygotuj e-mail. Przepływ to ponownie używalny plan, który Ava może odtworzyć z różnymi danymi wejściowymi.","features.workflows#2#p":"Przepływy są przechowywane dla każdego projektu w folderze o nazwie `.ava/workflows/` wewnątrz Twojego projektu. Udostępnij je zespołowi, komitując ten katalog (zapisując go we wspólnym projekcie, aby koledzy z zespołu też mieli dostęp).","features.events#title":"Wydarzenia i powiadomienia","features.events#0#p":"Mówiąc prosto: podczas pracy Avy widzisz uporządkowaną listę krok po kroku tego, co robi, oraz sygnał, gdy długi proces się skończy, dzięki czemu możesz odejść.","features.events#1#p":"Podczas działania Avy widzisz ustrukturyzowane aktualizacje, a nie ścianę tekstu. Każde wywołanie narzędzia, każde przekazanie między osobowościami, każdy strumieniowany fragment to oddzielne zdarzenie w interfejsie — można rozwinąć dla szczegółów lub zwinąć dla przeglądu.","features.events#2#p":"Uruchomienia w tle wysyłają powiadomienia systemowe po zakończeniu. Możesz odejść od długiego procesu budowania, a Ava poinformuje Cię, kiedy będzie gotowe.","features.personality#title":"Projektant osobowości","features.personality#0#p":"Mówiąc prosto: ustaw sposób, w jaki Ava do Ciebie mówi — rozmowna czy zwięzła, oficjalna czy luźna, więcej żartów czy mniej — tak, aby brzmiała tak, jak lubisz.","features.personality#1#p":"Ukształtuj sposób, w jaki Ava do Ciebie mówi. Ton, energia, ilość słów (ile mówi), formalność, humor. Suwaki i gotowe ustawienia — zwięzły inżynier, ciepły mentor, suchy kolega lub Twoje własne połączenie.","features.personality#2#p":"Osobowość wpływa na dobór słów, nie na kompetencje. Nadal uruchamia te same narzędzia i przestrzega tych samych zasad uprawnień. Jej nazwa jest przypisana do Avy — to nie podlega dyskusji.","features.release-notes#title":"Notatki wydania","features.release-notes#0#p":"Mówiąc prosto: bieżąca lista tego, co nowego i co naprawiono w każdej aktualizacji, abyś widział, co się zmieniło.","features.release-notes#1#p":"Dziennik zmian w aplikacji (dziennik zmian to historia zmian). Każda wysłana wersja ze swoimi wyróżnieniami, poprawkami błędów i zmianami łamiącymi (zmiany, które mogą wymagać dostosowania sposobu korzystania z czegoś). Strona internetowa utrzymuje publiczną wersję pod adresem ava-supernova.com/releases.","troubleshooting.common-errors#title":"Typowe błędy","troubleshooting.common-errors#0#p":"Większość błędów ma krótką, konkretną przyczynę. Oto najczęstsze z nich i sposób ich naprawy. Nie przejmuj się, jeśli język brzmi technicznie — każdy opis poniżej wyjaśnia, co dokładnie widzisz i co dokładnie należy zrobić.","troubleshooting.common-errors#1#h":"Model nie odpowiada","troubleshooting.common-errors#2#p":"Co widzisz: Ava milczy i nie odpowiada.","troubleshooting.common-errors#3#p":"Sprawdź wskaźnik statusu w nagłówku czatu. Jeśli widnieje tam \\\"connecting\\\", Twój dostawca (usługa AI, z którą rozmawia Ava) jest dostępny, ale wolny — poczekaj trzydzieści sekund. Jeśli widnieje \\\"unavailable\\\", Ava automatycznie przełączyła się na kolejny model w łańcuchu (wybrała model zapasowy). Jeśli nic się nie dzieje, sprawdź swój klucz API w Ustawieniach i przetestuj połączenie. (Klucz API to prywatne hasło, które pozwala Avie korzystać z płatnej usługi AI.)","troubleshooting.common-errors#4#h":"Wywołanie narzędzia nie powiodło się","troubleshooting.common-errors#5#p":"Co widzisz: jeden z kroków Avy (wywołanie \\\"narzędzia\\\" — czytanie pliku, uruchamianie polecenia itd.) wyświetla czerwony błąd zamiast zakończenia.","troubleshooting.common-errors#6#p":"Kliknij nieudane wywołanie narzędzia, aby zobaczyć szczegóły błędu. Najczęstsze przyczyny: próbowała uzyskać dostęp do pliku poza folderem projektu (zablokowano to celowo dla Twojego bezpieczeństwa — ta ochrona nazywa się zabezpieczeniem przed \\\"przejściem ścieżki\\\" i zapobiega wychodzeniu poza folder, w którym pracujesz); polecenie wymagające uruchomienia w innym folderze; albo plik, który został przeniesiony od momentu ostatniego sprawdzenia przez Avę. Powiedz jej, co poszło nie tak — ona spróbuje ponownie z korektami.","troubleshooting.common-errors#7#h":"Pamięć nie przypomina","troubleshooting.common-errors#8#p":"Co widzisz: Ava nie może znaleźć czegoś, o czym jesteś pewien, że powinna pamiętać.","troubleshooting.common-errors#9#p":"Pamięć działa na podstawie znaczenia, a nie dokładnych słów (o tym właśnie mówi termin \\\"semantyczny\\\"). Dlatego pytanie \\\"Co zdecydowałem o uwierzytelnianiu?\\\" zadziała lepiej niż \\\"znajdź moją decyzję dotyczącą uwierzytelniania\\\". Jeśli pamięć na pewno istnieje, ale nie pojawia się, otwórz przeglądarkę pamięci i wyszukaj — jeśli jej tam nie ma, oznacza to, że nigdy nie została zapisana.","troubleshooting.common-errors#10#h":"Zapętlenie logowania","troubleshooting.common-errors#11#p":"Co widzisz: logujesz się, ale Ava ciągle prosi o ponowne zalogowanie — pętla, która nigdy Cię nie przepuszcza.","troubleshooting.common-errors#12#p":"Rozwiązaniem jest usunięcie zapisanych danych logowania i rozpoczęcie od nowa: w rozszerzeniu uruchom komendę \\\"Ava: Sign Out\\\" z palety poleceń, w IDE wybierz Ustawienia → Konto → Wyloguj, w CLI usuń plik znajdujący się w ~/.ava/auth.json (mały plik logowania w folderze .ava w katalogu domowym). Następnie zaloguj się ponownie.","troubleshooting.common-errors#13#h":"Wyczerpanie tokenów","troubleshooting.common-errors#14#p":"Co widzisz: komunikat informujący, że wyczerpałeś limit darmowego użytku w tym miesiącu. (\\\"Tokeny\\\" to jednostka miary zużycia AI — \\\"wyczerpane\\\" oznacza po prostu, że wykorzystałeś przydzielony na ten miesiąc darmowy limit.)","troubleshooting.common-errors#15#p":"Miesięczny budżet wersji darmowej resetuje się pierwszego dnia każdego miesiąca. Do tego czasu przełącz się na dostawcę BYOK (korzystając ze swojego własnego klucza API), aby kontynuować pracę. Twoje konto pozostaje aktywne — wstrzymane są jedynie darmowe żądania obsługiwane przez platformę.","troubleshooting.logs#title":"Gdzie znajdują się logi","troubleshooting.logs#0#p":"\\\"Log\\\" to po prostu dziennik, jaki Twój komputer prowadzi z tego, co się wydarzyło — przydatny, gdy coś się zepsuje i Ty (lub wsparcie) potrzebujecie zobaczyć szczegóły.","troubleshooting.logs#1#p":"Gdy potrzebujesz pełnego obrazu — jakie narzędzie zostało wywołane, jakie informacje otrzymało, co zwróciła usługa AI — logi to zwykłe pliki tekstowe w folderze na Twoim komputerze pod ścieżką ~/.ava/logs/ (folder .ava w katalogu domowym zawierający folder logs).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — transkrypcje sesji, w tym wywołania narzędzi, odpowiedzi strumieniowe i błędy.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — log hosta rozszerzeń VS Code. Niepowodzenia aktywacji, błędy panelu.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — log biurowego IDE. Komunikaty procesu sidecar, awarie Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — log REPL CLI.","troubleshooting.logs#3#p":"W rozszerzeniu komenda \\\"Ava: Show Logs\\\" z palety poleceń otwiera odpowiedni log w zakładce edytora. W IDE w sekcji Ustawienia → Diagnostyka znajduje się przycisk \\\"Open Logs\\\". CLI może wyświetlać swój log na bieżąco za pomocą komendy ava logs --follow.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Potrzebujesz raportu, e-maila lub dokumentu? Ava może go napisać i przekazać Ci rzeczywisty plik Word, Excel lub PDF, który otworzysz i edytujesz tak jak każdy inny.","features.office-suite#1#p":"Raporty, e-maile i dokumenty — napisane, sformatowane i wyeksportowane do natywnych formatów (.docx to Word, .xlsx to Excel, .pdf to PDF).","features.office-suite#2#li0":"report_generate — strukturalny plik .docx pobierający dane z zadań, dziennika, pamięci i stanu projektu.","features.office-suite#2#li1":"email_draft — e-mail sterowany tonem do pliku .docx.","features.office-suite#2#li2":"document_manage — tworzenie, czytanie, edycja, eksport w zakresie Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Przydatne, gdy Ava pisze w Twoim imieniu — raporty statusowe, prezentacje startowe, aktualizacje dla klientów. Plik .docx trafia do Twojego projektu, gdzie możesz go dopracować.","features.dashboard-library#title":"Biblioteka panelu","features.dashboard-library#0#p":"Mówiąc prosto: jedna półka przechowująca wszystko, co Ty i Ava stworzyliście i omówiliście, więc nic nie ginie.","features.dashboard-library#1#p":"Przejrzysty widok wszystkich rzeczy, które Ava wyprodukowała wraz z Tobą — wygenerowane obrazy, wideo, audio, dokumenty — obok rozmów, pamięci i zadań. Jedno miejsce, aby znaleźć to, co zrobiłeś w zeszłym tygodniu.","features.document-preview#title":"Podgląd dokumentu","features.document-preview#0#p":"Mówiąc prosto: zajrzyj do środka dokumentu tam, gdzie jesteś, bez otwierania osobnego programu do jego czytania.","features.document-preview#1#p":"Kliknij prawym przyciskiem myszy plik Word, arkusz Excel, PDF, CSV, HTML lub Markdown w projekcie — podglądaj go w miejscu bez wychodzenia z edytora. Przydatne do czytania materiałów referencyjnych wygenerowanych przez Avę lub plików wrzuconych przez współpracownika.","features.daily-briefing#title":"Codzienne podsumowanie","features.daily-briefing#0#p":"Mówiąc prosto: krótka notatka \\\"tu jest, gdzie skończyłeś\\\" każdego ranka, żebyś mógł kontynuować bez czytania wszystkiego od nowa.","features.daily-briefing#1#p":"Poranne podsumowanie: wczorajszy dziennik, otwarte zadania, stan projektu oraz wszelkie przypomnienia ustawione przez Avę. Opcjonalne — włącz to w ustawieniach.","features.daily-briefing#2#p":"Briefing wykorzystuje pamięć, aby wyświetlić istotny kontekst (\\\"za ostatnim razem, gdy pracowałeś nad przepływem autoryzacji, zauważyłeś, że chcesz wrócić do strategii tokenów odświeżających\\\"). To nie jest kanał wiadomości — skupione podsumowanie postępów.","troubleshooting.logs#4#c":"Logs may contain snippets of the project files Ava read during a session. Review before sharing.","troubleshooting.support-request#title":"Filing a support request","troubleshooting.support-request#0#p":"In plain terms: if something is wrong and the fixes above did not help, send us a message about it. The easiest way is to just ask Ava to do it for you.","troubleshooting.support-request#1#p":"If a problem is not covered by common errors, file a support ticket (send the support team a request for help). You can do it inside Ava (no form to fill out) or on the web.","troubleshooting.support-request#2#h":"From inside Ava","troubleshooting.support-request#3#p":"Ask her to file it. \"Ava, can you file a support ticket about this?\" She calls support_request, attaches the relevant session context (with credentials redacted), and sends it. Fastest path.","troubleshooting.support-request#4#h":"From the web","troubleshooting.support-request#5#p":"Visit ava-supernova.com/support. Pick a category (bug, feature, account, security, general) and describe what happened. Response within one working day.","troubleshooting.support-request#6#h":"What to include","troubleshooting.support-request#7#li0":"What you were trying to do.","troubleshooting.support-request#7#li1":"What actually happened.","troubleshooting.support-request#7#li2":"Which surface (extension, IDE, CLI, companion) and which version.","troubleshooting.support-request#7#li3":"Any error message or log excerpt. Redact credentials first.","troubleshooting.security-disclosure#title":"Reporting security issues","troubleshooting.security-disclosure#0#p":"In plain terms: if you have spotted a way Ava could be broken into or misused (a \"vulnerability\" — a security weakness), please tell us privately first so we can fix it before anyone can take advantage. This page is how.","troubleshooting.security-disclosure#1#p":"Found a vulnerability? Thank you. We take every report seriously and work with you on the fix before any public disclosure (before the problem is announced publicly).","troubleshooting.security-disclosure#2#h":"How to report","troubleshooting.security-disclosure#3#li0":"Email security@ava-supernova.com with a description, reproduction steps, and your preferred disclosure window.","troubleshooting.security-disclosure#3#li1":"Or file a support ticket with category \"security\" — same triage queue.","troubleshooting.security-disclosure#3#li2":"We acknowledge within 24 hours.","troubleshooting.security-disclosure#4#h":"Our commitments","troubleshooting.security-disclosure#5#li0":"Coordinated disclosure — we agree a timeline with you before anything is public. Default is 90 days.","troubleshooting.security-disclosure#5#li1":"Credit — you are credited in the fix notes unless you prefer anonymity.","troubleshooting.security-disclosure#5#li2":"No legal retaliation — good-faith research is welcome. We will not send lawyers after you.","troubleshooting.security-disclosure#6#c":"The security page at ava-supernova.com/security has the full posture — architecture guarantees, redactor, permission gates.","concepts.desktop-kill-switches#4#p":"Freezes on the next step boundary. Resumable. Use this when you want to intervene without losing the trajectory.","concepts.desktop-kill-switches#5#h":"Stop — Escape or the Stop button","concepts.desktop-kill-switches#6#p":"Clean abort. Narrator summarises what was done so far. Not resumable. Audit log commits.","concepts.desktop-kill-switches#7#h":"Panic kill — triple-Escape or Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"The hardest stop there is. A small, separate watchdog program force-quits the part of Ava that is driving your screen. It does not wait for the AI to respond, does not need the app window to be working, and does not care what state things are in — it just kills it. This is the one for when something is genuinely wrong.","concepts.desktop-kill-switches#9#p":"All three work from the companion app too. Either driver can end it.","reference.tools#title":"Tool reference","reference.tools#0#p":"This is the full lookup of every tool Ava has — a \"tool\" just being a specific action she can take, like reading a file or running a search. You do not need to read this page. Ava picks the right tool herself every time. It is here for when you are curious about exactly what she can do.","reference.tools#1#p":"The full built-in toolbox. Every tool here is registered in the core runtime (the engine underneath all three surfaces) and available to Ava when the mode and permission mode allow it. Filter by category or risk.","reference.tools#2#p":"No need to memorise any of this — the table below is just a reference card.","reference.tools#4#h":"Risk levels","reference.tools#5#li0":"Safe — reads things without changing anything. file_read, glob (find files by name pattern), grep (search inside files for text), git_status (Git is the system that tracks changes to your project).","reference.tools#5#li1":"Write — changes files, saves a checkpoint of your work (a \"commit\"), or produces something new. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Dangerous — runs commands on your computer (the \"shell\"), controls the desktop, goes out to the internet, or queries databases. bash, browser, desktop_*.","reference.tools#6#c":"Persona specialists have their own tool allowlists. Scout can read but not write. Builder has full access. Challenger has no tools at all — its job is to question the plan.","reference.models#title":"Models","reference.models#0#p":"A \"model\" is the AI brain doing the thinking — Qwen, DeepSeek, Mistral and others. This page lists every model Ava can use. The short version: you do not have to choose one. Ava picks the right model for each step herself. Read on only if you want to understand or override that.","reference.models#1#p":"Every model Ava can route to, plus the three orchestration strategies — the rules that decide which model handles each part of a job. Pick a routing mode and let Ava dispatch, or pick a single model and skip routing entirely.","reference.models#2#h":"Routing modes","reference.models#3#p":"Three orchestrated strategies. The same persona pipeline (the small team of specialist helpers Ava runs behind the scenes) runs on all three; what changes is the underlying fleet of models. Pick a mode in the model selector and Ava handles the rest. Each card below shows the constituent specialists the conductor routes to.","reference.models#4#p":"You do not need to memorise the cards below — they are here so you can see what each strategy is made of.","reference.models#6#c":"Aurora is deliberately Mistral-only. If a Mistral model is unavailable the router returns an error rather than cross-routing — that is the EU-stack guarantee. Pick Maestro or Supernova for graceful degradation.","reference.models#7#c":"All three modes are universally available — on platform credits and on your own keys. BYOK adds the option to bypass orchestration and drive a single model directly.","reference.models#8#h":"Platform-managed models","reference.models#9#p":"Available on every plan, including the free tier. Tokens (the units of text AI is measured in — roughly three-quarters of a word each) count against your plan allowance. The keys (the private passwords that unlock each paid model) are rotated and monitored by the platform — nothing for you to configure.","start.what#title":"Czym jest Ava?","start.what#0#p":"Ava to sztuczna inteligencja, która faktycznie coś robi – nie tylko rozmawia. Zbuduje dla ciebie aplikację, napisze dokument, nauczy cię czegoś od podstaw, zaprojektuje logo albo zajmie się administracją, którą ciągle odkładasz. I pamięta o tobie: nad czym pracujesz, jak lubisz rzeczy, o co prosiłaś w zeszłym tygodniu.","start.what#1#p":"Jest jedna Ava i działa tam, gdzie ty – w edytorze kodu, jako aplikacja desktopowa, na telefonie albo w terminalu. Ta sama pamięć, ta sama osobowość, wszędzie.","start.what#2#h":"Co ją wyróżnia","start.what#3#li0":"Domyślnie należy do ciebie. Twoja praca zostaje na twoim urządzeniu. Żadnego śledzenia, żadnej telemetrii – nigdy.","start.what#3#li1":"Otwarta dla każdego do obejrzenia. Każdy wiersz Avy jest publiczny. Nic nie musisz brać na słowo.","start.what#3#li2":"Start za darmo. 300 kredytów co miesiąc, bez karty, bez haczyka – albo podłącz swoje własne klucze AI i zapłać nam zero.","start.what#3#li3":"Nauczanie jest darmowe, na zawsze. Nauka nie powinna mieć ceny.","start.what#4#p":"Nigdy nie pisałeś kodu? Następna strona jest pisana specjalnie dla ciebie. Jesteś już techniczny? Przeskocz dalej – ona nadąży.","start.what#deeper#0#h":"Gdzie mieszka Ava","start.what#deeper#1#li0":"Rozszerzenie VS Code — Ava obok edytora: panel czatu, pulpit i zmiany pokazane bezpośrednio przed ich wprowadzeniem.","start.what#deeper#1#li1":"Stacjonarne IDE — samodzielna aplikacja z całym zestawem w jednym oknie. Dodaje kontrolę nad pulpitem (otwieranie aplikacji, klikanie, wpisywanie za ciebie).","start.what#deeper#1#li2":"Kompanion — aplikacja mobilna, gdy jesteś poza biurkiem: zadania, dziennik, pamięć, szybkie rozmowy.","start.what#deeper#1#li3":"CLI — Ava w twoim terminalu, dla osób, które tam mieszkają.","start.what#deeper#2#h":"Jak działa, w skrócie","start.what#deeper#3#p":"Ava zmienia nastawienia (zwane trybami), aby dopasować się do zadania, cicho uruchamia mały zespół specjalistycznych pomocników przy trudniejszych pracach i wybiera najlepszy model AI dla każdego kroku automatycznie. Ty nigdy tego nie zarządzasz. Sekcja Podstawowe pojęcia zawiera pełny przewodnik, gdy będziesz ciekawy.","start.first-five#title":"Twoje pierwsze zadanie z Avą","start.first-five#0#p":"Najszybszy sposób na skorzystanie z Avy to poprosić ją o coś konkretnego i zobaczyć, jak to zrobi. Nie ma konfiguracji do przeczytania, niczego nie trzeba się uczyć najpierw – po prostu powiedz jej, czego chcesz, zwykłymi słowami.","start.first-five#1#h":"Spróbuj teraz","start.first-five#2#li0":"Otwórz czat.","start.first-five#2#li1":"Wpisz coś, na czym naprawdę ci zależy. Spróbuj \"wyjaśnij, co robi ten projekt\", lub \"dodaj przycisk, który czyści formularz\".","start.first-five#2#li2":"Ava pokazuje ci, co zamierza zrobić – i czeka.","start.first-five#2#li3":"Zadowolony? Powiedz tak. Zobacz, jak to zrobi.","start.first-five#3#p":"To cały rytm: pytasz, ona pokazuje plan, zatwierdzasz, ona wykonuje. Nigdy nic nie zmienia bez pokazania ci najpierw – więc nie możesz nic zepsuć przez próbę.","start.first-five#4#h":"Kilka rzeczy wartych poproszenia","models.routing#deeper#2#td5.0":"Rozmowa","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Koordynacja generowania obrazów","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Widzenie","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (model wizyjny trenowany od podstaw)","models.routing#deeper#2#td8.0":"Pisanie długich treści","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Lokalizacja danych","models.routing#deeper#2#td9.1":"Mieszane (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Mieszane (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Tylko UE · otwarte wagi","models.routing#deeper#2#td10.0":"Status","models.routing#deeper#2#td10.1":"Dostępne · wszystkie plany","models.routing#deeper#2#td10.2":"Wkrótce","models.routing#deeper#2#td10.3":"Wkrótce","models.routing#deeper#2#td11.0":"Najlepsze do","models.routing#deeper#1#h":"Obok siebie","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Koordynator","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B aktywne, 1M kontekstu)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B aktywne, 262K kontekstu)","models.routing#deeper#2#td1.0":"Twórca","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (korzysta z koordynatora)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B gęsty, 256K kontekstu)","models.routing#deeper#2#td2.0":"Specjaliści średniego poziomu","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (recenzent kodu, weryfikator faktów, rozpoznanie, skaner, weryfikator bezpieczeństwa itp.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Architekt, Weryfikator, Planista, Mentor, Raportant itp.)","models.routing#deeper#2#td3.0":"Poziom lekki / brama intencji","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Zwiadowca, Weryfikator, Planista, Krytyk, Integrator)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Zaawansowani specjaliści","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Badacz, Krytyk, Badacz CVE, Pomysłodawca, Weryfikator faktów)","models.routing#deeper#2#td11.1":"Codzienna praca, przewidywalny koszt","models.routing#deeper#2#td11.2":"Ciężka wieloetapowa praca, koordynator klasy frontowej w każdym planie","models.routing#deeper#2#td11.3":"Ścisłe zgodne z RODO, sektor publiczny, suwerenne stosy UE","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Warstwowe trasowanie Qwen, lekki ślad. Qwen 3.6 Plus przejmuje rolę koordynatora, Buildera, planowania, bezpieczeństwa, burzy mózgów i pracy o długim kontekście — tu najlepiej sprawdza się jego hybrydowa uwaga liniowa z kontekstem 1M. Qwen 3.5 Flash zajmuje się czatem, koordynacją generowania obrazów i bramą zamiarów na wlocie, gdzie jego ceny $0.07/$0.26 i szybsze TTFT wygrywają na większości niskogłębokościowego ruchu. Qwen 3.5 Omni Plus przejmuje wejście wizyjne (Qwen 3.6 Plus nie ma natywnej obsługi wizji). Qwen 3.5 Plus przejmuje pracę długich tekstów wrażliwą na koszty. Jeśli główny koordynator jest niedostępny, system schodzi po drabinie priorytetów: Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Zespół wielojęzyczny. DeepSeek V4 Pro koordynuje i kieruje każde zadanie do najlepiej dopasowanego specjalisty: Qwen 3.6 Plus uruchamia każdą instancję Buildera, V4 Flash obsługuje czat oraz role przeglądania i audytu średniego poziomu, Qwen 3.5 Flash przejmuje pracę klasyfikatora niskiego poziomu, Qwen 3.5 Omni Plus przejmuje wejście wizyjne, Qwen 3.5 Omni Flash koordynuje wywołania narzędzi do generowania obrazów, Qwen 3.5 Plus przejmuje rolę pisarstwa treści wrażliwą na koszty. Myślenie klasy frontowej tam, gdzie to istotne, a ekonomiczne modele flash na większości wolumenu tokenów.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Europejski stos AI — zaprojektowany jako suwerenny. Tylko trasowanie Mistral w trzech warstwach: Mistral Large 3 (675B/41B-active sparse MoE) przejmuje rolę koordynatora oraz ciężkich specjalistów wymagających głębi — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — i podstawową pracę długiego kontekstu, gdzie wydajność architektury MoE wygrywa. Mistral Medium 3.5 — nowy flagowiec wydany w kwietniu 2026, 128B dense, 256K kontekst, encoder wizyjny trenowany od zera, zmodyfikowane otwarte wagi MIT, 77.6% SWE-Bench Verified — prowadzi właściwy poziom pracy: uruchomienia Buildera, specjaliści średniego poziomu (Architect, Verifier, Sequencer, Tutor, Reporter), wejście wizyjne i pisanie długich tekstów. Mistral Small 4 rozszerzył się z jednej roli na bramie zamiarów do obsługi czatu i koordynacji generowania obrazów — jego ceny $0.15/$0.60 i konfigurowalne rozumienie są uzasadnione na trasach o wysokim wolumenie i niskiej głębokości. Otwarte wagi od początku do końca, nigdy nie opuszcza infrastruktury UE. Aurora celowo nie przekierowuje cicho do modelu spoza Mistral, gdy ten jest niedostępny; router wyświetla błąd zamiast tego — to właśnie czyni ją \"Aurorą\", a nie Maestrem w stylu Mistral.","credits.overview#title":"Kredyty Ava — jak działa rozliczanie","credits.overview#0#p":"Kredyty to po prostu sposób, w jaki Ava liczy zużycie — tak jak minuty w abonamencie telefonicznym. Każdy plan, włączając darmowy, otrzymuje pulę kredytów, a każda rzecz, którą Ava robi (odpowiedź dla Ciebie, stworzenie obrazu), kosztuje ich niewielką ilość. To cała idea. Szczegóły poniżej są dla tych, którzy chcą wiedzieć dokładnie, co ile kosztuje.","credits.overview#1#p":"Ava rozlicza się w kredytach, nie surowych tokenach. (Token to malutki kawałek tekstu — około kilku liter — który modele AI czytają i zapisują; większość usług nalicza opłaty za token, co trudno przewidzieć.) Jeden kredyt pokrywa jedną jednostkę pracy — zwrot czatu, uruchomienie persony (jeden pomocnik wykonujący część zadania), generowanie obrazu. Odłączenie od pomiaru na poziomie tokenów oznacza, że nie musisz znać modelu, aby wiedzieć, ile będzie kosztować akcja. Ten sam zwrot czatu kosztuje tyle samo, czy Maestro przekaże go do Qwen 3.6 Plus, czy Supernova do V4 Pro.","credits.overview#2#h":"Plany","credits.overview#3#p":"Każdy plan daje dostęp do każdej funkcji — dostępu do modeli, Creative Studio, wszystkich siedmiu trybów, pełnej orkiestracji person. Wyższe poziomy kupują więcej kredytów i wyższy limit szybkości, a nie odblokowane funkcje.","credits.overview#4#li0":"Darmowy — $0/miesiąc. 300 kredytów. Limit 20 żądań/minutę. Nie wymaga karty.","credits.overview#4#li1":"Pro — $19/miesiąc. 5,000 kredytów. 60 żądań/minutę.","credits.overview#4#li2":"Ultra — $39/miesiąc. 10,000 kredytów. 120 żądań/minutę.","credits.overview#4#li3":"Enterprise — $79/miesiąc. 20,000 kredytów. 200 żądań/minutę.","credits.overview#5#c":"Nieużywane kredyty przenoszą się, dopóki subskrypcja jest aktywna — nie ma wymuszonego cofnięcia. Doładowania sumują się do puli subskrypcji: 750 kredytów za $3, 2,000 za $8, 4,000 za $15.","credits.overview#6#h":"Co ile kosztuje","credits.overview#7#p":"Tabela kosztów na akcję — co jest odejmowane z Twojej puli kredytów przy uruchomieniu każdej akcji. (Hit pamięci podręcznej to moment, gdy Ava ponownie wykorzystuje pracę, którą już wykonała, zamiast jej powtarzać; wtedy płacisz mniej — opada o 70%, lub 50% w przypadku modeli obciążonych wyjściem jak DeepSeek V4 Pro.)","credits.overview#8#li0":"Zwrot czatu — 2 kredyty. Pojedyncza wymiana zdań w dowolnym trybie.","credits.overview#8#li1":"Lekkie połączenie — 1 kredyt. Brama zamiarów, klasyfikacja, odczyt jednorazowy.","credits.overview#8#li2":"Ciężka persona — 3 kredyty. Architect, Researcher, CVE Researcher, Ideator (głębokość ≥ 4).","credits.overview#8#li3":"Lekka persona — 1 kredyt. Scout, Verifier, Sequencer, Challenger (głębokość ≤ 2).","start.first-five#5#li0":"Pytanie — \"dlaczego moja strona jest pusta?\", \"co robi ten plik?\"","start.first-five#5#li1":"Coś zbudowane — \"zrób mi prostą stronę z listą zadań\".","start.first-five#5#li2":"Żeby się czegoś nauczyć — \"naucz mnie Pythona od podstaw\". (Zawsze za darmo.)","start.first-five#5#li3":"Dokument — \"napisz mi jednostronicową propozycję projektu\". Odda Ci plik Word lub PDF.","start.first-five#6#c":"Nie wiesz, co wpisać? Rozmawiaj z nią jak z mądrą przyjaciółką. Zwykłe słowa są idealne — nie potrzebujesz terminów technicznych, żeby zacząć.","start.first-five#deeper#0#p":"Ta prosta pętla robi sporo w tle. Nie musisz znać tego wszystkiego, żeby używać Avy — ale oto, co tak naprawdę dzieje się, jeśli jesteś ciekawy.","start.first-five#deeper#1#h":"Narzędzia i zgoda","start.first-five#deeper#2#p":"Kiedy Ava czyta plik, uruchamia polecenie albo edytuje kod, każde z tych działań to \"wywołanie narzędzia\". Pyta przed wszystkim, co dotyka Twoich plików lub systemu — jak często pyta zależy od trybu uprawnień (pytaj za każdym razem, pytaj tylko o ryzykowne rzeczy, albo po prostu działaj).","start.first-five#deeper#3#h":"Tryby — jej stany umysłu","start.first-five#deeper#4#p":"Ava pracuje w trybach: nastawienie plus odpowiednie narzędzia do zadania. Przełączaj kiedy chcesz z listy lub wpisz prefiks na początku wiadomości. Jest ich siedem.","start.first-five#deeper#6#h":"Specjaliści i kierowanie","start.first-five#deeper#7#p":"Przy trudniejszych zadaniach Ava uruchamia mały zespół specjalistycznych pomocników w tle (planista, kontroler, budowniczy) i kieruje każdy krok do modelu, który najlepiej sobie z nim radzi. Ty nigdy tym nie zarządzasz — ona koordynuje to za Ciebie.","start.local-vs-cloud#title":"Lokalnie vs chmura, w jednym akapicie","start.local-vs-cloud#0#p":"Wszystko, co robi Ava, jest lokalne, chyba że wyraźnie wyrazisz zgodę. Pamięć, zadania, dziennik, osobowość, ustawienia — wszystko przechowywane na Twoim komputerze w ~/.ava/ i .ava/ (na projekt). Rozmawia z dostawcami modeli przez HTTPS, aby uruchomić Twoje żądanie, potem wraca do domu. Nie dzwoni do domu. Nie zbiera telemetrii. Nie trenuje na Twoim kodzie.","start.local-vs-cloud#1#p":"Jeśli się zalogujesz, otrzymasz 300 darmowych kredytów miesięcznie dla modeli zarządzanych przez platformę (Qwen, MiniMax) oraz opcjonalną synchronizację chmurową pamięci i ustawień między urządzeniami. Synchronizacja dotyczy funkcji, można ją cofnąć w każdej chwili. Przynieś własny klucz API i Ava działa w pełni bez konta.","start.local-vs-cloud#2#c":"Zasada: lokalne jest święte. Chmura jest dodatkiem.","start.first-model#title":"Czy muszę wybrać AI?","start.first-model#0#p":"Oto ulga: nie wybierasz AI. Ava wybiera odpowiednią dla każdego kroku automatycznie, więc uzyskujesz dobre wyniki bez konieczności zastanawiania się nad tym.","start.first-model#1#p":"Jedyną rzeczą, którą możesz wybrać, jest styl kierowania — a domyślny pasuje prawie każdemu. Innych potrzebujesz tylko z konkretnego powodu.","start.first-model#2#h":"Trzy style","start.first-model#3#li0":"Maestro — domyślny. Stabilny, niezawodny, przewidywalny. Nie jesteś pewien? To jest ten.","start.first-model#3#li1":"Supernova — do ciężkiej, wieloetapowej pracy, gdzie opłaca się powierzyć każdą część zadania innemu specjaliście.","start.first-model#3#li2":"Aurora — gdy Twoje dane muszą pozostać w UE (sektor publiczny, ochrona zdrowia, ścisła prywatność). Działa w całości na europejskim, otwartym AI.","start.first-model#4#p":"Przełączaj kiedy chcesz z wyboru modelu na górze czatu. Nic nie jest ustalone na stałe.","start.first-model#5#c":"Chcesz sterować konkretnym modelem samodzielnie? Możesz — otwórz \"Pokaż mi szczegóły\".","concepts.modes#0#p":"Tryb to sposób myślenia, w którym znajduje się Ava — jak kolega zmieniający czapkę. Ta sama osoba, ta sama pamięć o Tobie, ale twórca myśli inaczej niż nauczyciel. Wybierasz tryb i to zmienia jej zachowanie oraz pomocników, które przywołuje. Przełączaj w dowolnej chwili za pomocą selektora trybu lub wpisz dwuznakowy skrót.","concepts.modes#2#h":"Który z nich wybierasz?","concepts.modes#3#p":"Zacznij od tego, co chcesz zrobić — tryb wynika z tego:","concepts.modes#4#li0":"Chcę coś zbudować lub zmienić → Kod (>>). Opisujesz, ona buduje, pokazując Ci każdą zmianę najpierw. Pełny zespół pomocników włącza się do większych zadań.","concepts.modes#4#li1":"Chcę plan przed czymkolwiek się zmieni → Plan (::). Przemyśli to wszystko i poda Ci plan do zatwierdzenia lub edycji. Nie będzie dotykać Twoich plików w tym trybie.","concepts.modes#4#li2":"Chcę tylko pogadać lub zapytać → Czat (..). Partner do myślenia z pamięcią, wiadomościami i pogodą. Żadnych zmian plików, żadnego kodu — tylko rozmowa.","concepts.modes#4#li3":"Chcę się czegoś nauczyć → Nauka (??). Prawdziwy kurs dla Ciebie: lekcje, quizy, wszystko. Dostępne za darmo w każdym planie, na zawsze. Idealne, jeśli jesteś nowy.","concepts.modes#4#li4":"Chcę sprawdzić projekt pod kątem dziur bezpieczeństwa → Bezpieczeństwo (!!). Zespół sprawdza standardową listę typowych luk w zabezpieczeniach sieciowych (kategorie „OWASP”) i znanych zgłoszonych błędów (zwanych „CVE”), a potem przekazuje raport posortowany według powagi każdego problemu. Ten tryb jest skierowany do programistów — pomiń go, jeśli nie jesteś.","concepts.modes#4#li5":"Chcę pomysły → Burza mózgów (**). Generuje opcje osadzone w Twojej rzeczywistej sytuacji, szuka słabych punktów w tych słabszych i dopracowuje resztę w kolejne kroki.","concepts.modes#4#li6":"Chcę napisać dokument → Pisanie (<<). Raporty, propozycje, listy, artykuły — szkicuje w Markdown i eksportuje sformatowany dokument Word lub PDF, dopracowując sekcję po sekcji. Żadnego kodu, tylko pisanie.","concepts.modes#5#c":"Zespół pomocników (osobowości) działa całkowicie w tle — nigdy nie rozmawiasz z nimi bezpośrednio. Po prostu otrzymujesz bardziej szczegółową odpowiedź. Nie musisz znać ich nazw.","concepts.modes#6#c":"Możesz przełączać tryby w trakcie rozmowy. Twoja pamięć przechodzi dalej; specjaliści resetują się, aby dopasować do nowego trybu.","concepts.tasks-journal#title":"Zadania i dziennik","concepts.tasks-journal#0#p":"Ava prowadzi trzy rodzaje notatek dla Ciebie i łatwo je pomieszać. Szybki sposób na zapamiętanie: pamięć to to, co ona wie o Tobie, zadania to to, co jeszcze musisz zrobić, a dziennik to dziennik tego, jak sprawy szły. Oto kiedy używać którego.","concepts.tasks-journal#1#li0":"Pamięć — trwałe fakty. Preferencje, decyzje, wzorce. Pytane wielokrotnie, rzadko tworzone ręcznie.","concepts.tasks-journal#1#li1":"Zadania — rzeczy do zrobienia. Elementy akcji z datami i statusem. Odznaczasz je, gdy są gotowe.","concepts.tasks-journal#1#li2":"Dziennik — refleksja. Codzienny log, podwójne wpisy (Twoje i obserwacje Avy dotyczące sesji). Przydatne do śledzenia nastroju, przeglądów sesji, kontekstu na jutro.","concepts.tasks-journal#2#p":"Ava zapisuje we wszystkich trzech, gdy ma to sens. Możesz pisać do każdej z nich bezpośrednio z panelu. Nic nie jest zamknięte w jednym miejscu, gdzie używasz Avy — zadanie utworzone w jednym (np. narzędziu CLI) pojawi się wszędzie indziej (jak aplikacja desktopowa), automatycznie.","concepts.permissions#title":"Uprawnienia — Twój suwak bezpieczeństwa","concepts.permissions#0#p":"Uprawnienia to Twój suwak bezpieczeństwa. Decydują, kiedy Ava prosi o Twoją zgodę przed wykonaniem czegoś na komputerze, zamiast po prostu brać się do roboty. Możesz ustawić ją tak, by pytała o wszystko, pytała tylko o ryzykowne rzeczy, albo ufala jej, żeby działała — i możesz to zmienić w każdej chwili. Jeśli nie jesteś pewien, zostaw domyślne ustawienie i będzie dobrze.","concepts.permissions#1#p":"Ava ma 60 narzędzi („narzędzia” to działania, które może wykonać — czytanie pliku, wyszukiwanie w sieci i tak dalej). Każde narzędzie należy do kategorii (operacje na plikach, powłoka, Git, sieć, multimedia, baza danych, system, dokumenty, pamięć, nauka). Każde wywołanie narzędzia przechodzi przez bramę uprawnień (punkt kontrolny decydujący, czy najpierw zapytać Cię), zanim zostanie uruchomione. Kontrolujesz, co jest automatycznie zatwierdzane, co pyta raz, a co zawsze pyta.","concepts.permissions#3#p":"Zrównoważone to domyślne. Ścisłe, gdy audytujesz jej zachowanie (pilnie sprawdzając każdy krok). Autonomiczne, gdy chcesz, żeby po prostu działała.","concepts.permissions#4#c":"Autonomiczne nie oznacza bez nadzoru. Plany, pytania wyjaśniające i wyraźne prośby o użytkownika nadal czekają na Twój wpis. Nieodwracalne operacje (wymuszony push w Git, kasowanie baz danych) zawsze potwierdzają niezależnie od trybu.","concepts.interjection#title":"Sterowanie i zatrzymywanie Avy","concepts.interjection#0#p":"Ty zawsze masz władzę. Podczas gdy Ava pracuje, możesz albo delikatnie skierować ją w nowym kierunku bez przerwania tempa, albo zatrzymać ją natychmiast. Dwa przyciski, dwa wyniki — o tym jest ta strona.","concepts.interjection#1#p":"Ava działa, dopóki nie dokończy swojego planu lub jej nie zatrzymasz. Masz dwa sposoby, by się wtrącić (nazywa się to „interwencją”), gdy już pracuje.","concepts.interjection#2#h":"Interwencja — steruj bez anulowania","concepts.interjection#3#p":"Wpisz nową wiadomość, gdy Ava pracuje. Dokończy aktualne polecenie, przeczyta Twoją wiadomość i dostosuje plan. Nic nie ginie z kontekstu. Użyj tego, gdy chcesz zmienić kierunek, dodać informacje lub zmienić priorytety w trakcie działania.","concepts.interjection#4#h":"Całkowite zatrzymanie — anuluj i wyczyść","concepts.interjection#5#p":"Naciśnij Esc (CLI), kliknij Stop (rozszerzenie, IDE) lub wpisz komendę zatrzymania. Aktualna sesja zostaje anulowana, oczekujące polecenia są odrzucane, a rozmowa jest gotowa na nowy krok.","concepts.interjection#6#c":"Najpierw interwencja. Całkowite zatrzymanie stosuj tylko, gdy coś jest naprawdę nie tak. Interwencja pozwala kontynuować wątek.","concepts.desktop-personas#title":"Osobowości pulpitu","concepts.desktop-personas#0#p":"Ta strona jest dla ciekawskich i zaawansowanych użytkowników. „Automatyzacja pulpitu” (czasem zwana „korzystaniem z komputera”) oznacza, że Ava faktycznie klika po ekranie i używa aplikacji za Ciebie — otwiera Gmaila, wypełnia formularze, wysyła wiadomości — jak osoba przy klawiaturze. Aby robić to bezpiecznie, dzieli zadanie na pięciu małych pomocników, z których każdy ma jedną, wąską rolę. Nie masz z nimi bezpośredniego kontaktu; ta sekcja pokazuje tylko, kto co robi.","concepts.desktop-personas#1#p":"Każdy krok w ścieżce pracy na pulpicie (jedna sesja, w której Ava prowadzi Twój ekran ku celowi) uruchamia falę pięciu osobowości. Każda ma jedno zadanie i tylko jedno. Rozdzielenie sprawia, że polecenia są zwięzłe, wyjścia ustrukturyzowane, a rozumowanie krytyczne z założenia.","concepts.desktop-personas#2#h":"Zwiadowca","concepts.desktop-personas#3#p":"Raportuje to, co widoczne jest teraz na ekranie. Nigdy nie wymyśla elementów. Nigdy nie planuje. Zwraca stan ekranu w formacie ScreenState JSON z ID elementów, nazwami, ramkami, poziomem pewności i źródłem danych (UIA, Playwright DOM lub wizja OmniParser).","concepts.desktop-personas#4#h":"Planista","concepts.desktop-personas#5#p":"Decyduje o jednym następnym kroku. Jedno działanie na krok — nigdy grupuje. Preferuje ścieżki odwracalne. Klasyfikuje ryzyko zgodnie z ontologią bezpieczeństwa. Zwraca proponowaną akcję w formacie ProposedAction JSON z rodzajem, celem, parametrami, klasą ryzyka, uzasadnieniem i przewidywanym stanem po wykonaniu.","concepts.desktop-personas#6#h":"Wykonawca","concepts.desktop-personas#7#p":"Wykonuje dokładnie to, co zaproponował Planista — po przejściu przez bramkę zatwierdzenia. Żadnych improwizacji. Żadnych ponowień. Niepowodzenie jest wiernie raportowane, a Weryfikator podejmuje kolejny ruch.","concepts.desktop-personas#8#h":"Weryfikator","concepts.desktop-personas#9#p":"Sprawdza, czy akcja się powiodła. Porównuje świeży stan ekranu z przewidywaniem Planisty. Zwraca potwierdzono, odchylenie lub potrzebny cofnięcie. Wykrywa też pętle — powtarzanie akcji, która już się udała, to odchylenie, a nie weryfikacja.","concepts.desktop-personas#10#h":"Opowiadacz","concepts.desktop-personas#11#p":"To jedyny głos, który użytkownik słyszy podczas trwania procesu. Jedno zdanie w czasie przeszłym na krok („Otwarto Gmaila.”, „Kliknięto Składanie.”). Pisze też ustrukturyzowany dziennik audytu. Mówi, gdy coś poszło nie tak — nigdy nie ukrywa problemu.","concepts.desktop-safety#title":"Ontologia bezpieczeństwa pulpitu","concepts.desktop-safety#0#p":"Krótko mówiąc: zanim Ava kliknie cokolwiek na Twoim ekranie, sortuje akcję według jej ryzyka. Przeglądanie ekranu? Bezpieczne. Wysyłanie pieniędzy lub usuwanie czegoś? Zawsze się zatrzymuje i pyta Cię najpierw — za każdym razem, bez wyjątków. Pięć poniższych etykiet to tylko szczeble tej drabiny ryzyka. To szczegół dla zaawansowanych użytkowników, ale wniosek jest prosty: niebezpieczne rzeczy zawsze wymagają Twojego „tak”.","concepts.desktop-safety#1#p":"Każda proponowana akcja jest klasyfikowana do jednej z pięciu klas ryzyka. Klasyfikacja łączy trzy sygnały — czym jest cel na ekranie, jego opis prostym językiem („opis semantyczny” — własne słowa Avy na to, na co patrzy) oraz ustawienia akcji — i eskaluje (traktuje jako bardziej ryzykowne), gdy się nie zgadzają. Fałszywy alarm (pytanie, gdy nie trzeba) to tylko irytacja. Błąd pominięcia (niepytanie, gdy trzeba) to incydent kończący produkt.","concepts.desktop-safety#2#h":"Pięć klas","concepts.desktop-safety#3#li0":"Obserwacyjne — odczytaj drzewo UIA, zrzut ekranu, najedź myszką. Zawsze automatycznie dozwolone.","concepts.desktop-safety#3#li1":"Nawigacyjne — przewijaj, zmieniaj fokus, otwieraj menu. Automatycznie dozwolone w trybie prowadzenia.","features.creative-studio#1#p":"Generowanie obrazów, wideo, muzyki i głosu — wbudowane w ten sam proces pracy co Twój kod. Stwórz ikonę, makietę produktu, film demonstracyjny lub lektor do poradnika. Napędzane przez MiniMax.","features.creative-studio#2#h":"Co możesz stworzyć","features.creative-studio#3#li0":"Obrazy — z opisu do formatu PNG/JPG. Usunięcie tła dostępne jednym kliknięciem.","features.creative-studio#3#li1":"Wideo — krótkie filmy AI z tekstu (MiniMax Hailuo).","features.creative-studio#3#li2":"Muzyka — utwory instrumentalne lub wokalne z tekstem piosenki.","features.creative-studio#3#li3":"Głos — zamiana tekstu na mowę z wyborem głosów.","features.creative-studio#4#p":"Koszty Creative Studio pochodzą z tej samej puli kredytów co wszystko inne — jedna pula, jeden numer. Podłącz własny klucz MiniMax (BYOK) i korzystaj za darmo w ramach swojego planu.","features.creative-studio#5#c":"Creative Studio kwalifikuje się do darmowego poziomu. To nie jest płatny dodatek.","features.desktop-automation#title":"Automatyzacja pulpitu","features.desktop-automation#0#p":"Mówiąc prosto: Ava może przejąć kontrolę nad myszką i klawiaturą, aby wykonywać zadania za Ciebie — otworzyć aplikację, kliknąć przyciski, wypełnić formularz — podczas gdy Ty obserwujesz i zatwierdzasz wszystko ważne.","features.desktop-automation#1#p":"Nowy tryb dla Avy, prefiks @@. Obserwuje ona pulpit, decyduje, co zrobić, i steruje automatyzacją interfejsu (kontrolując aplikacje na Twoim ekranie za Ciebie), aby to zakończyć. Działa na Twoim komputerze z Twoimi prawdziwymi danymi logowania — nie przeglądarka w chmurze. Dostępna na każdym planie po udostępnieniu.","features.desktop-automation#2#h":"Dlaczego kolejna?","features.desktop-automation#3#p":"Każdy inny produkt do automatyzacji pulpitu to coś, co uruchamiasz, gdy siedzisz przy biurku. Ava to ta, która nadal tam jest, gdy Twój system śledzenia błędów alarmuje o 2 w nocy — IDE wciąż działa, telefon paruje przez bezpieczne połączenie, zatwierdzasz nieodwracalne akcje jednym dotknięciem.","features.desktop-automation#4#p":"Ona również pamięta, jak nawigować w Twoich aplikacjach między sesjami. Każdy inny agent musi uczyć się ich od nowa za każdym razem. Korzyść z pamięci rośnie wraz z użytkowaniem.","features.desktop-automation#5#h":"Jak to działa","features.desktop-automation#6#p":"Każdy krok uruchamia falę pięciu ról: Szpieg obserwuje, Planista wybiera kolejne działanie, Aktor wykonuje, Weryfikator sprawdza, Opowiadacz informuje Cię, co się stało. Moduł pomocniczy wybiera najtańsze niezawodne oparcie — UIA dla natywnych aplikacji, Playwright dla przeglądarek, wizja OmniParser, gdy nic innego nie ma użytecznego drzewa.","features.desktop-automation#7#p":"Zobacz strony koncepcyjne dotyczące ontologii bezpieczeństwa, hierarchii oparcia, wyłączników awaryjnych i modelu białej listy sesji.","credits.overview#8#li4":"Orkiestracja — 10 kredytów. Pełne uruchomienie potoku persony (Dyrektor + zadanie z wieloma osobami).","credits.overview#8#li5":"Generowanie obrazów — 12 kredytów. Hailuo image-01 przez Creative Studio.","credits.overview#8#li6":"Generowanie wideo — 150 kredytów. Klip Hailuo 02 Pro 1080p o długości 6 sekund.","credits.overview#8#li7":"Generowanie głosu — 10 kredytów. Synteza mowy Speech 2.8 HD.","credits.overview#8#li8":"Generowanie muzyki — 50 kredytów. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Usuwanie tła — 2 kredyty.","credits.overview#9#h":"Mnożniki dla każdego modelu","credits.overview#10#p":"Ten fragment jest dla ciekawskich — nie musisz go znać, żeby korzystać z Avy. Mnożnik po prostu skaluje koszt kredytów w górę lub w dół w zależności od tego, jak drogi jest model stojący za daną akcją, więc cięższe modele kosztują nieco bardziej. („Marża netto\" to część, którą projekt zatrzymuje po opłaceniu własnych rachunków — celujemy nisko, żeby wartość wracała do Ciebie.)","credits.overview#11#p":"Cięższe modele mnożą koszt akcji, dzięki czemu kredyty śledzą rzeczywiste wydatki zamiast płaskiej stawki. Skalibrowane pod kątem ~55% marży netto.","credits.overview#12#li0":"0.6× — Mistral Small 4 (specjalistyczna pozycja Aurory). Poniżej 1×, ponieważ Mistral Small 4 jest tańszy niż wartość odniesienia Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Stawka bazowa.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (koordynator Aurory). Podobnie jak wartość odniesienia Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (koordynator Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (koordynator Supernova + ciężcy specjaliści). Ponownie skalibrowane z 5.0×, aby przywrócić równowagę marży przy opublikowanej stawce V4 Pro.","credits.overview#13#c":"Modele Anthropic (Claude Opus / Sonnet / Haiku) całkowicie pomijają rozliczenia kredytowe — są dostępne tylko w trybie BYOK i płacisz bezpośrednio Anthropic. To samo dotyczy każdego innego dostawcy BYOK używanego z Twoim własnym kluczem.","credits.overview#14#h":"BYOK i kredyty","credits.overview#15#p":"BYOK („przynieś swój klucz\" — dostarczasz własne konto u dostawcy AI i klucz, który jest prywatnym hasłem pozwalającym oprogramowaniu używać tego płatnego konta) jest dla osób, które już płacą bezpośrednio dostawcy AI. Jeśli to nie Ty, możesz całkowicie zignorować ten dział.","credits.overview#16#p":"Żądania „przynieś swój klucz\" omijają infrastrukturę platformy całkowicie — połączenie idzie bezpośrednio z Avy do dostawcy, Ty płacisz dostawcy, żadne kredyty nie są zużywane. Jedyny wyjątek występuje, gdy sesja BYOK uruchamia zarządzaną osobę na potrzeby podzadania; potrącenie kredytu nadal obowiązuje, ponieważ używana jest powierzchnia orkiestracji Avy.","credits.overview#17#h":"Gdzie sprawdzić saldo","credits.overview#18#li0":"Rozszerzenie — Ustawienia → Konto, lub odznaka kredytowa w nagłówku czatu.","credits.overview#18#li1":"IDE — kafelki panelu konta pokazują aktualne saldo i tempo zużycia.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard pokazuje saldo, historię i datę odnowienia.","credits.overview#19#c":"Lokalnie: Ava działa bez konta na karcie Własny model (Ollama, LM Studio, vLLM lub dowolny punkt końcowy zgodny z OpenAI). Brak kredytów, brak tokenów platformy — Twój model, Twoja maszyna, Twoje rachunki wynoszą zero.","concepts.modes#title":"Tryby — stany umysłu Avy","start.first-model#deeper#0#h":"Co właściwie kryje każdy ze stylów","start.first-model#deeper#1#p":"Maestro — jeden dyrygent (Qwen 3.6 Plus) prowadzi każdy krok. Dostosowany do produkcji, sprawdzony, przewidywalny koszt.","start.first-model#deeper#2#p":"Supernova — koordynator na froncie (DeepSeek V4 Pro, 1.6T parametrów / 49B aktywnych, kontekst 1M) przekazuje każde podzadanie specjalistom: V4 Flash do budowania dużych pakietów, Qwen 3.6 Plus jako zapas, Qwen Omni do wizji.","start.first-model#deeper#3#p":"Aurora — tylko Mistral, w trzech warstwach: Mistral Large 3 (koordynator + ciężcy specjaliści), Mistral Medium 3.5 (128B gęsty, kontekst 256K, natywna wizja, otwarte wagi modyfikowane MIT, 77.6% SWE-Bench Verified) dla Budowniczego + średnia półka + wizja + długie teksty, oraz Mistral Small 4 przy bramce intencji. Otwarte wagi od początku do końca, nigdy nie opuszcza infrastruktury UE.","start.first-model#deeper#4#h":"Własny model (BYOK)","start.first-model#deeper#5#p":"Wolisz używać swojego konta AI? Wklej klucz dostawcy w ustawieniach i otrzymujesz obie opcje — trzy style trasowania, plus możliwość wybrania jednego modelu i pominięcia trasowania całkowicie. Przydatne przy silnej preferencji, ścisłym budżecie lub testowaniu konkretnego modelu. Pełna lista dostawców jest w sekcji Referencyjnej.","start.glossary#title":"Słowniczek prostym językiem","start.glossary#0#p":"Każde słowo, z którym możesz się spotkać wokół Avy, wyjaśnione bez zakładania żadnej wiedzy. Nie musisz tego niczego zapamiętywać — wracaj tutaj, gdy jakiś termin cię zaskoczy.","start.glossary#1#th0":"Słowo","start.glossary#1#th1":"Co to tak naprawdę oznacza","start.glossary#1#td0.0":"Agent","start.glossary#1#td0.1":"AI, który może wykonywać działania za ciebie — czytać pliki, uruchamiać polecenia, szukać w sieci — nie tylko czatać. Ava jest agentem: ona wykonuje rzeczy, za twoją zgodą.","start.glossary#1#td1.0":"Model","start.glossary#1#td1.1":"Prawdziwy mózg AI zajmujący się myśleniem (Qwen, DeepSeek, Mistral i inni). Różne modele mają różne mocne strony. Zazwyczaj nigdy nie wybierasz jednego — robi to Ava.","start.glossary#1#td2.0":"Tryb","start.glossary#1#td2.1":"Nastrój, w jakim znajduje się Ava. Jak kolega przełączający kapelusze: budowniczy, pisarz, nauczyciel, planista, przyjaciel. Ty wybierasz tryb; to zmienia sposób jej zachowania. Jest ich siedem.","start.glossary#1#td3.0":"Osobowość / specjalista","start.glossary#1#td3.1":"Role pomocnicze, które Ava obsługuje w tle przy trudniejszych zadaniach — odkrywca, planista, fakt-checker. Pomyśl o małym zespole ekspertów. Nigdy nie rozmawiasz z nimi bezpośrednio; Ava je koordynuje.","start.glossary#1#td4.0":"Trasowanie","start.glossary#1#td4.1":"Decyzja Avy, którego modelu użyć na każdym kroku, abyś dostał dobre odpowiedzi bez przepłacania. Dzieje się to automatycznie — \"tryb trasowania\" wybiera ogólną strategię.","start.glossary#1#td5.0":"Narzędzie","start.glossary#1#td5.1":"Konkretne działanie, jakie Ava może podjąć — przeczytać plik, wyszukać coś, wysłać e-mail. \"Wezwanie narzędzia\" to jej użycie jednego z nich. Pyta o zgodę przed czymkolwiek ryzykownym.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Jak AI mierzy tekst — około ¾ słowa. Modele są wyceniane za milion tokenów. Zazwyczaj coś, co możesz zignorować.","start.glossary#1#td7.0":"Credit","reference.cli#5#li3":"--project <path> — ustaw jawnie główny katalog projektu.","reference.desktop-budget#title":"Limity budżetu na pulpicie","reference.desktop-budget#0#p":"Kiedy Ava steruje Twoim pulpitem za Ciebie — klikając, pisząc, otwierając aplikacje — każde uruchomienie nazywamy \"trajektorią\". Ta strona wyjaśnia limity bezpieczeństwa, które zapobiegają temu, by jedno uruchomienie trwało zbyt długo lub kosztowało zbyt dużo. Wniosek: Ona zawsze się zatrzymuje i sprawdza, zanim przekroczy limit. Liczby są tutaj, jeśli chcesz znać szczegóły.","reference.desktop-budget#1#p":"Każda trajektoria działa pod trzema równoczesnymi limitami (twardymi ograniczeniami). Ten, który zostanie pierwszy osiągnięty, wygrywa. Trajektoria nigdy nie kontynuuje cicho po przekroczeniu — Narrator (pomocnik, który tłumaczy Ci, co się dzieje) pauzuje i pyta, co robić.","reference.desktop-budget#2#h":"Trzy twarde limity (domyślne)","reference.desktop-budget#3#li0":"Liczba kroków — 30 kroków","reference.desktop-budget#3#li1":"Budżet tokenów — 500,000 tokenów","reference.desktop-budget#3#li2":"Czas rzeczywisty — 5 minut","reference.desktop-budget#4#h":"Zakresy kosztów zadań","reference.desktop-budget#5#li0":"Proste (szukanie w dokumentach, otwarcie strony) — 5–10 kroków, ~70–135K tokenów, ~$0.04–0.08","reference.desktop-budget#5#li1":"Średnie (logowanie, sprawdzanie logów, pobieranie wyników) — 15–25 kroków, ~205–340K tokenów, ~$0.12–0.21","reference.desktop-budget#5#li2":"Złożone (priorytetyzowanie trzech problemów GitHub) — 25–30 kroków, ~340–410K tokenów, ~$0.21–0.25","reference.desktop-budget#6#p":"Powyższe liczby tokenów to techniczne limity na jedną trajektorię, a nie Twój miesięczny limit — to liczone w kredytach, a darmowy pakiet z 300 miesięcznie wygodnie pokrywa mieszankę czatu, kodu i kilku automatyzacji.","reference.desktop-budget#7#c":"Możesz nadpisać limity dla każdego zadania na starcie, ale przekroczenia zawsze ujawniają punkt decyzyjny. Budżet nigdy nie jest spalany w ciszy.","reference.desktop-whitelist#title":"Biała lista sesji pulpitu","reference.desktop-whitelist#0#p":"\"Biała lista\" to po prostu lista aplikacji i stron internetowych, które pozwoliłaś Avie dotykać, gdy steruje Twoim pulpitem. Ta strona wyjaśnia, jak przyznajesz tę zgodę i dlaczego resetuje się ona za każdym razem. W skrócie: może działać tylko tam, gdzie jej pozwolisz, i pyta przed wejściem w nowe miejsce.","reference.desktop-whitelist#1#p":"Na początku sesji pulpitu Ava pyta, gdzie ma prawo działać. Zwykły język działa: \"Gmail, Cursor, portal Azure.\" Czyta to i potwierdza dopasowanie do Ciebie (\"strona Gmail, aplikacja Cursor, portal.azure.com\").","reference.desktop-whitelist#2#h":"Jak to działa","reference.desktop-whitelist#3#p":"Działania tylko do odczytu — robienie zrzutu ekranu, czytanie listy przycisków i pól na ekranie (\"drzewo UIA\", własna mapa Windows tego, co jest w oknie) — są dozwolone wszędzie, bo musisz widzieć, co jest na ekranie, by zdecydować, czy dodać aplikację do białej listy. Wszystko, co coś zmienia, jest blokowane poza listą; Ava pauzuje i pyta, czy dodać ją.","reference.desktop-whitelist#4#h":"Ograniczone do sesji, celowo","reference.desktop-whitelist#5#p":"Biała lista NIE zachowuje się między sesjami. Nie ma opcji \"zapamiętaj tę aplikację\". Każda nowa trajektoria zaczyna się od świeżego zakresu. Niewygodne z założenia — zapomnienie ponownego autoryzowania to funkcja, nie błąd.","reference.desktop-whitelist#6#h":"Dodania w trakcie trajektorii","reference.desktop-whitelist#7#p":"W trakcie trajektorii możesz dodać aplikacje z nagłówka: \"+ Zezwól na aplikację\" otwiera małe pole wprowadzania. Dotknij Dodaj i nowa aplikacja jest aktywna przez resztę sesji.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Chcesz stworzyć obraz, krótki film, piosenkę lub lektor głosowy? Po prostu opisz to, a Ava zrobi to dla Ciebie — nie potrzebujesz oprogramowania do grafiki ani dźwięku.","start.glossary#1#td7.1":"Prostsza jednostka Avy określająca koszt działania, więc nie musisz liczyć tokenów. W cenie planu masz miesięczny pakiet.","start.glossary#1#td8.0":"Klucz API","start.glossary#1#td8.1":"Prywatne hasło, które pozwala oprogramowaniu korzystać z płatnej usługi (np. modelu AI) na Twoim koncie. Potrzebujesz go tylko, jeśli chcesz użyć własnego.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Przynieś swój klucz\". Używanie własnego klucza API zamiast zarządzanego dostępu Avy. Opcjonalne – dla osób, które już płacą dostawcy bezpośrednio.","start.glossary#1#td10.0":"Local-first","start.glossary#1#td10.1":"Twoje dane domyślnie znajdują się na Twoim komputerze. Nic nie jest wysyłane, dopóki nie włączysz synchronizacji. \"Lokalność jest święta.\"","start.glossary#1#td11.0":"Tryb uprawnień","start.glossary#1#td11.1":"Określa, jak ostrożna jest Ava przed wykonaniem czynności – pytać za każdym razem, tylko przy ryzykownych zadaniach, albo działać od razu. To Ty decydujesz o poziomie.","start.glossary#1#td12.0":"Okno kontekstowe","start.glossary#1#td12.1":"Ile tekstu model może mieć jednocześnie w pamięci – jego pamięć krótkotrwała. \"Kontekst 1M\" oznacza około miliona słów. Im większy, tym więcej przeczyta zanim zapomni.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"Widok obok siebie pokazujący dokładnie, co się zmieni w pliku – stare po jednej stronie, nowe po drugiej – wyświetlany przed tym, jak Ava cokolwiek zmieni, abyś mógł to zatwierdzić.","start.glossary#1#td14.0":"Repozytorium (repo)","start.glossary#1#td14.1":"Folder projektu śledzony pod kątem zmian, zazwyczaj z użyciem Git. Jeśli to jeszcze nic Ci nie mówi, to po prostu \"folder, w którym znajduje się mój projekt.\"","start.glossary#1#td15.0":"Zapytanie","start.glossary#1#td15.1":"To, co wpisujesz do AI – Twoje pytanie lub instrukcja.","start.glossary#2#c":"Nadal utknąłeś na jakimś słowie? Zapytaj Avę w trybie czatu – \"co oznacza X?\" – i ona wyjaśni to na Twoim poziomie.","models.routing#title":"Routing — jak Ava wybiera modele","models.routing#0#p":"Oto wersja skrócona: nigdy nie musisz wybierać, którego modelu AI użyć. Ava robi to za Ciebie, wybierając najlepsze narzędzie do każdej części zadania – tak jak dobry menedżer przekazuje właściwe zadanie odpowiedniej osobie.","models.routing#1#p":"Wybierasz jeden z trzech stylów — Maestro, Supernova lub Aurora — i Ava kieruje każdą część pracy do modelu, który radzi sobie z nią najlepiej. Maestro jest domyślny, działa we wszystkich planach i jest dobrym wyborem dla prawie każdego.","models.routing#2#h":"Dlaczego warto stosować routing?","models.routing#3#p":"Przekazanie odpowiedniego modelu do każdego kroku kosztuje mniej niż uruchamianie wszystkiego na jednym dużym, drogim modelu – i daje lepsze wyniki, bo każdy model robi to, w czym jest najlepszy. Masz stały koszt i wysoką jakość, nie musząc wiedzieć, który model jest którym.","models.routing#4#c":"Wszystkie trzy style działają na kredytach platformy i na Twoich własnych kluczach. Posiadając własny klucz, możesz też pominąć routing i sterować pojedynczym modelem bezpośrednio. Pełny rozkład floty znajdziesz pod \"Pokaż mi szczegóły\".","models.routing#deeper#0#c":"Liczby \"B\" poniżej oznaczają miliardy parametrów – mniej więcej wielkość mózgu modelu; większa zazwyczaj oznacza mądrzejszy, ale wolniejszy i droższy. To szczegół techniczny \"pod maską\"; nigdy nie będziesz go potrzebować, aby korzystać z Avy.","concepts.desktop-safety#3#li2":"Mutative-reversible — type into a field, paste, open an app, navigate a URL. Confirms in Ask mode; auto in Drive within the whitelist.","concepts.desktop-safety#3#li3":"Mutative-irreversible — send, submit, pay, delete, confirm, publish. Always confirms, regardless of permission level. Approval never caches.","concepts.desktop-safety#3#li4":"Privileged — UAC elevation, sudo, registry edits, credential prompts. Forbidden by default. Single-use opt-in required per session.","concepts.desktop-safety#4#h":"Never-cached approvals","concepts.desktop-safety#5#p":"Every competitor caches approvals (remembers your \"yes\" and reuses it next time). That is the largest foothold for prompt injection — an attack where a booby-trapped web page sneaks hidden instructions to the AI to make it act against you. If approvals are cached, a compromised page can ride on a \"yes\" you gave earlier. Ava never caches. Each mutative-irreversible action asks fresh.","concepts.desktop-safety#6#h":"Secrets handling","concepts.desktop-safety#7#p":"Passwords, API keys, and 2FA codes (the one-time codes a second app or text gives you when you log in) are handled via opaque handles — placeholders that stand in for the real value. Ava sees \"{secret}\", not the actual password. The real value never enters her memory, her activity log, or what she \"reads\" — a separate low-level layer types it in at the last moment, at the keypress, so the AI part never touches it.","reference.cli#title":"CLI commands","reference.cli#0#p":"This page is for the CLI — the version of Ava you type to in a terminal window, rather than clicking buttons. If you use the extension or the desktop app, you can skip it entirely. It is here for people who prefer the keyboard.","reference.cli#1#p":"The CLI is a REPL — a prompt that waits for you to type, runs what you typed, then waits again. These slash commands (instructions that start with \"/\") work from the prompt.","reference.cli#2#li0":"/help — list commands and current mode.","reference.cli#2#li1":"/mode <name> — switch mode (work, write, plan, chat, teach, security, brainstorm).","reference.cli#2#li2":"/model <id> — switch model without leaving the session.","reference.cli#2#li3":"/clear — clear the current conversation. Memory is untouched.","reference.cli#2#li4":"/history — list past conversations in this project.","reference.cli#2#li5":"/memory — open the memory browser.","reference.cli#2#li6":"/tasks — list and manage tasks.","reference.cli#2#li7":"/journal — open today journal entry.","reference.cli#2#li8":"/settings — open the settings menu.","reference.cli#2#li9":"/exit — quit the REPL.","reference.cli#3#h":"Launch flags","reference.cli#4#p":"Flags are extra options you add when you start Ava, each beginning with \"--\", to set how she opens.","reference.cli#5#li0":"--mode <name> — start in a specific mode.","reference.cli#5#li1":"--model <id> — start with a specific model.","reference.cli#5#li2":"--permission <mode> — strict / balanced / autonomous."},"uk":{"start.for-non-coders#title":"Ніколи не писали код? Почніть звідси","start.for-non-coders#0#p":"Якщо ви ніколи не писали жодного рядка коду, ви саме той, для кого створена Ava. Вам не потрібно вивчати жаргон, щоб почати — ви спілкуєтеся з нею простою мовою, як запитали б у знайомого друга. Ця сторінка — ваш повний шлях до старту.","start.for-non-coders#1#h":"Що ви можете зробити сьогодні без досвіду","start.for-non-coders#2#li0":"Запитайте її про будь-що простими словами — «що робить цей файл?», «чому моя сторінка порожня?», «що взагалі таке база даних?» Вона відповідає простою мовою і пам'ятає розмову.","start.for-non-coders#2#li1":"Дізнайтеся щось з нуля — скажіть «навчи мене Python з нуля» і вона створить вам курс із уроками та тестами. Це завжди безкоштовно.","start.for-non-coders#2#li2":"Отримайте готовий продукт — опишіть, що ви хочете («кнопка, яка завантажує мої нотатки»), і вона напише його, показуючи кожну зміну перед тим, як вона станеться.","start.for-non-coders#3#h":"Вам не потрібно розуміти все","start.for-non-coders#4#p":"У Ava багато механізму під капотом — режими, моделі, спеціалісти, маршрутизація. Ви побачите ці слова навколо додатка та в цих документах. Ось секрет: ви можете ігнорувати майже все. Ava сама обирає правильні інструменти та помічників для вас. Технічні сторінки існують, коли ви захочете дізнатися більше, а не тому, що вони потрібні для старту.","start.for-non-coders#5#h":"М'який перший крок","start.for-non-coders#6#li0":"Встановіть Ava (наступна сторінка) і відкрийте чат.","start.for-non-coders#6#li1":"Введіть реальне запитання, яке у вас є. Будь-яке. Подивіться, як вона відповідає.","start.for-non-coders#6#li2":"Спробуйте режим навчання: введіть «навчи мене» і тему. Слідуйте за нею.","start.for-non-coders#6#li3":"Коли ви хочете, щоб вона щось створила або змінила, просто запитайте — Ava завжди покаже вам, що планує зробити, і зачекає на ваше «так».","start.for-non-coders#7#c":"Сталася незрозуміла фраза? Словник простими словами (дещо нижче в цьому розділі) пояснить кожен термін без жодних припущень про ваші знання.","start.install#title":"Встановлення","start.install#0#p":"Оберіть інструмент, який найкраще пасує до вашого стилю роботи. Можна використовувати кілька — Ava синхронізує свою пам'ять між ними, коли ви входите в систему.","start.install#1#h":"Розширення для VS Code","start.install#2#li0":"Відкрийте панель розширень у VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Знайдіть \"Ava Supernova\" і натисніть Встановити.","start.install#2#li2":"Натисніть Ctrl+Shift+A (Cmd+Shift+A на macOS), щоб відкрити панель чату.","start.install#2#li3":"Дотримуйтесь майстра налаштувань — оберіть модель, встановіть режим дозволів, і все готово.","start.install#3#h":"Настільний IDE","start.install#4#li0":"Завантажте інсталятор для вашої платформи зі сторінки релізів.","start.install#4#li1":"Запустіть його. При першому запуску IDE відкриється з вітальною процедурою.","start.install#4#li2":"Увійдіть, щоб отримати безкоштовні токени платформи, або вставте свій власний ключ API для повного локального запуску.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (або pnpm / yarn — на ваш вибір).","start.install#6#li1":"Запустіть  ava  у будь-якій директорії проекту.","start.install#6#li2":"При першому запуску система запитає про постачальника та модель. Обирайте і працюйте.","start.install#7#c":"Немає акаунту — не біда. Маючи свій власний ключ API (BYOK), вам ніколи не потрібно входити в систему. Безкоштовний тариф призначений для моделей, керованих платформою.","concepts.memory#title":"Пам'ять — як Ava запам'ятовує вас","concepts.memory#0#p":"Простими словами: Ava пам'ятає вас. Розкажіть їй щось один раз — що вам подобається, рішення, яке ви прийняли — і вона збереже це, тому вам не доведеться повторюватися в наступному чаті чи наступного тижня. Це головне. Нижче пояснюється лише те, як вона тримає цю пам'ять у порядку з часом.","concepts.desktop-grounding#title":"Ієрархія розуміння робочого столу (Прев'ю)","concepts.desktop-grounding#0#c":"Прев'ю — як Scout вирішує, яке джерело орієнтування використовувати на кожному кроці.","concepts.desktop-grounding#1#p":"Перш ніж Ava зможе натиснути кнопку, вона має реально зрозуміти, що на вашому екрані і де знаходяться речі — це й є \\\"розуміння контексту\\\" (визначення того, що саме є на екрані і його точне місце). Вона має три способи зробити це і обирає найнадійніший, який працює для програми, яку ви використовуєте. Це деталь для просунутого користувача; головне те, що вона надає перевагу надійним, точним методам, а не вгадуванню за картинкою.","concepts.desktop-grounding#2#p":"Три рівні, оцінюються послідовно. Перемагає найдешевший надійний джерело.","concepts.desktop-grounding#3#h":"1. Вікно браузера → Playwright DOM","concepts.desktop-grounding#4#p":"Якщо активне вікно — це веббраузер, Ava читає власну структуру сторінки (те, що називають \\\"DOM\\\" — внутрішній список того, що є на сторінці), замість того щоб вгадувати за картинкою. Читання структури приблизно в 10 разів надійніше, ніж погляд на пікселі — вона точно знає, де кожна кнопка і коли сторінка завантажилося. Це основний шлях для всього в мережі, а не резервний.","concepts.desktop-grounding#5#h":"2. Нативна програма з UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Для звичайних програм на Windows Ava читає вбудовану карту доступності (\\\"UIA\\\", ті самі дані, які використовують програми читання екрана для опису вікна) — вона перелічує кожну кнопку, її ім'я і де вона знаходиться. Якщо ця карта повертає хоча б п'ять придатних, іменованих елементів, вона їй довіряє і використовує її.","concepts.desktop-grounding#7#h":"3. UIA порожня або непридатна → OmniParser vision","concepts.desktop-grounding#8#p":"Коли цієї карти немає або вона безглузда (деякі програми, ігри та віддалені екрани її не надають), Ava переходить до фактичного перегляду скріншота. Інструмент зору (OmniParser) знаходить клікабельні області і підписує, що кожна з них собою являє, перетворюючи картинку назад у список, з яким можна діяти — разом із тим малим, що дала карта доступності.","concepts.desktop-grounding#9#c":"OmniParser підключається добровільно вперше, коли Ava йому потрібен, з чітким повідомленням про конфіденційність. Користувачі BYOK можуть вказати на свій власний локальний деплоймент OmniParser.","concepts.desktop-kill-switches#title":"Аварійні вимикачі на робочому столі (Прев'ю)","concepts.desktop-kill-switches#0#c":"Прев'ю — три незалежні способи скасувати поточний процес. Будь-який з них спрацює.","concepts.desktop-kill-switches#1#p":"«Аварійний вимикач» — це саме те, що звучить — спосіб терміново зупинити Ava миттєво, коли вона керує вашим екраном. Що заспокоює: їх три, кожен побудований окремо, тому якщо один не спрацює, інший все одно працюватиме. Вам не потрібно вчити всі три. Просто знайте, що коли щось виглядає неправильно, ви завжди можете зупинити це, і найсильніша зупинка (панічний аварійний вимикач нижче) не покладається на співпрацю Ava.","concepts.desktop-kill-switches#2#p":"Після прочитання всіх публічних інцидентів автономності (реальні випадки, коли агенти ШІ ігнорували команди зупинки, видаляли архіви електронної пошти, очищали диски), ми створили три аварійні вимикачі в трьох різних шарах. Жоден з них не залежить від самої моделі ШІ — якщо Ava зависла або не реагує, ви все одно можете її зупинити.","concepts.desktop-kill-switches#3#h":"Пауза — пробіл або кнопка Пауза","concepts.desktop-kill-switches#4#p":"Зупиняється на наступній межі кроку. Можна відновити. Використовуйте це, коли хочете втрутитися, не втрачаючи траєкторії.","concepts.desktop-kill-switches#5#h":"Стоп — клавіша Escape або кнопка «Стоп»","concepts.desktop-kill-switches#6#p":"Чисте скасування. Асистент підсумовує, що вже виконано. Відновити неможливо. Журнал аудиту записує коміти.","concepts.desktop-kill-switches#7#h":"Термінове вимкнення — тричі Escape або Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"Це найжорсткіша зупинка. Мала окрема програма-сторож примусово завершує ту частину Ava, яка керує вашим екраном. Вона не чекає відповіді ШІ, не потребує, щоб вікно програми працювало, і їй байдуже, у якому стані все знаходиться — вона просто вимикає це. Це варіант для випадків, коли щось дійсно пішло не так.","concepts.desktop-kill-switches#9#p":"Усі три діють і через додаток-компаньйон. Будь-який драйвер може це завершити.","reference.tools#title":"Довідник інструментів","reference.tools#0#p":"Це повний перелік усіх інструментів Ava — «інструмент» означає конкретну дію, яку вона може виконати, наприклад, прочитати файл або запустити пошук. Вам не потрібно читати цю сторінку. Ava сама обирає правильний інструмент кожного разу. Вона тут для тих, хто цікавиться, чим саме вона може займатися.","reference.tools#1#p":"Повний вбудований набір інструментів. Кожен інструмент тут зареєстрований у ядрі (движку під усіма трьома поверхнями) і доступний Ava, коли режим та режим дозволів дозволяють. Фільтруйте за категорією або ризиком.","reference.tools#2#p":"Не треба нічого запам'ятовувати — таблиця нижче є лише довідковою карткою.","reference.tools#4#h":"Рівні ризику","reference.tools#5#li0":"Безпечний — читає інформацію без змін. file_read, glob (знайти файли за шаблоном імені), grep (пошук тексту всередині файлів), git_status (Git — це система, що відстежує зміни вашого проекту).","reference.tools#5#li1":"Запис — змінює файли, зберігає точку контролю роботи («коміт») або створює щось нове. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Небезпечний — запускає команди на вашому комп'ютері («оболонка»), керує робочим столом, виходить в інтернет або запитує бази даних. bash, browser, desktop_*.","reference.tools#6#c":"Спеціалісти-персони мають свої власні списки дозволених інструментів. Scout може читати, але не писати. Builder має повний доступ. Challenger не має жодних інструментів — його завдання ставити план під сумнів.","reference.models#title":"Моделі","reference.models#0#p":"«Модель» — це мозок ШІ, який думає — Qwen, DeepSeek, Mistral та інші. Ця сторінка перелічує всі моделі, які може використовувати Ava. Коротко: вам не потрібно обирати одну. Ava сама обирає правильну модель для кожного кроку. Читайте далі тільки якщо хочете зрозуміти або змінити це.","reference.models#1#p":"Усі моделі, куди Ava може спрямовувати завдання, плюс три стратегії оркестрації — правила, що вирішують, яка модель обробляє кожну частину роботи. Оберіть режим маршрутизації і дозвольте Ava розподілити, або оберіть одну модель і пропустіть маршрутизацію взагалі.","reference.models#2#h":"Режими маршрутизації","reference.models#3#p":"Три оркестровані стратегії. Одна й та сама конвеєрна лінія персонажів (невеличка команда спеціалізованих помічників, яких запускає Ava у фоновому режимі) працює на всіх трьох; змінюється лише базовий парк моделей. Оберіть режим у виборі моделей, і Ava зробить решту. Кожна картка нижче показує спеціалістів, до яких диригент направлятиме завдання.","reference.models#4#p":"Вам не треба запам'ятовувати картки нижче — вони тут, щоб ви бачили, з чого складається кожна стратегія.","reference.models#6#c":"Aurora навмисно використовує лише Mistral. Якщо модель Mistral недоступна, роутер повертає помилку, а не перемикається на іншу — це гарантія стеку ЄС. Оберіть Maestro або Supernova для плавного зниження функціоналу.","reference.models#7#c":"Усі три режими доступні скрізь — на кредити платформи та на ваших ключах. BYOK додає можливість обійти оркестрацію і керувати однією моделлю напряму.","reference.models#8#h":"Моделі, що керуються платформою","reference.models#9#p":"Доступні на кожному тарифі, включаючи безкоштовний рівень. Токени (одиниці тексту, за якими вимірюється ШІ — приблизно три чверті слова кожен) враховуються у вашому ліміті тарифу. Ключі (приватні паролі, що розблоковують кожну платну модель) обмінюються та моніторяться платформою — нічого налаштовувати вам не потрібно.","reference.models#11#h":"Внесіть свій ключ","reference.models#12#p":"An \"API key\" is a private password that lets software use a paid service on your own account. \"BYOK\" just means \"bring your own key\" — using yours instead of ours. Paste your API key in settings. BYOK requests go direct from Ava to the provider (the company that runs the model) — they do not pass through our infrastructure and do not consume platform tokens. You pay the provider; we do not see the traffic.","reference.models#14#c":"Для результатів бенчмарків, тегів можливостей та порівняння див. повну сторінку Models на ava-supernova.com/models. Ціни вище — це наше найкраще читання тарифної картки кожного провайдера на момент публікації — завжди перевіряйте сайт провайдера перед початком роботи.","reference.personas#title":"Оркестрація ролей","reference.personas#0#p":"«Персона» — це допоміжна роль, яку Ava виконує за лаштунками для складних завдань — дослідник, планувальник, фактчекер. Ви ніколи не спілкуєтеся з ними напряму і вам не потрібно розуміти цю сторінку, щоб користуватися Ava. Вона тут для тих, хто цікавиться, як вона розбиває велике завдання на команду експертів.","reference.personas#1#p":"24 спеціалісти в 5 командах режимів. Диригент (допоміжник, що координує решту) вирішує, яка команда запускається, в якому порядку і з яким контекстом. У режимі чату немає ролей — це сама Ava.","reference.personas#2#h":"Як працює оркестрація","reference.personas#3#li0":"Ви надсилаєте повідомлення в режимах План, Виклад, Безпека або Мозковий штурм (або складне завдання Робота).","reference.personas#3#li1":"Диригент читає запит, обирає команду режиму та будує план виконання — деякі персонажі запускаються послідовно, деякі хвилями паралельно.","reference.personas#3#li2":"Кожна персона має свій системний запит, обмежений дозволений список інструментів та спільний пул контексту того, що знайшли попередні персонажі.","reference.personas#3#li3":"Остаточна персона створює зведення, план або звіт залежно від режиму.","reference.personas#3#li4":"Ava показує вам результат. Ви затверджуєте, виправляєте або спрямовуєте далі.","reference.personas#4#p":"Повний список нижче є лише довідковим — не треба запам'ятовувати, хто що робить. Ava збирає правильну команду для вас.","reference.personas#6#c":"Режим Робота залучає повну команду лише для складних завдань. Прості редагування запускає Ava напряму — без навантаження від оркестрації.","reference.config#title":"Конфігурація","reference.config#0#p":"Ця сторінка показує, де Ava зберігає свої налаштування та файли на вашому комп'ютері. Вам майже ніколи не потрібно чіпати їх вручну — програма керує цим за вас. Це потрібно лише тоді, коли ви хочете переглянути, зробити резервну копію або поділитися цими файлами самостійно.","reference.config#1#p":"Ava читає конфігурацію (свої збережені налаштування) з двох рівнів. Глобальні налаштування — ті, що діють скрізь — знаходяться в папці ~/.ava/ (знак \"~\" означає вашу домашню папку). Налаштування для конкретного проекту знаходяться в папці .ava/ всередині самого проекту.","reference.config#2#h":"Глобальні — ~/.ava/","reference.config#3#li0":"settings.json — уподобання моделей, режим дозволів, особистість, мова.","reference.config#3#li1":"memory/ — ваші глобальні спогади (уподобання, рішення, що стосуються всього).","reference.config#3#li2":"tasks.json — список завдань між проектами.","reference.config#3#li3":"journal/ — щоденникові записи, організовані за датою.","reference.config#4#h":"Проект — .ava/","reference.config#5#li0":"instructions.md — інструкції для цього проекту, які Ava завжди завантажує. Постійний контекст («ми використовуємо pnpm, а не npm», «ключі API зберігаються в 1Password»).","reference.config#5#li1":"context.md — необов'язкові довільні нотатки про проект.","reference.config#5#li2":"memory/ — спогади, прив'язані до цього проекту.","reference.config#5#li3":"datasets/config.json — налаштування захоплення наборів даних (за бажанням).","reference.config#6#c":"Додайте .ava/ до свого .gitignore (список файлів, які Git повинен ігнорувати у спільному проекті), якщо ви не хочете ділитися спогадами зі своєю командою. Залиште instructions.md у репозиторії (спільній папці проекту) — так Ava вивчає конвенції проекту.","reference.shortcuts#title":"Клавіатурні скорочення","reference.shortcuts#0#p":"Клавіатурні скорочення — це додаткові швидкі способи роботи — кожне з них також є кнопкою, яку можна натиснути. Заглядайте сюди лише тоді, коли хочете керувати Ava швидше з клавіатури.","reference.shortcuts#1#p":"Скорочення за місцями роботи (кожне з трьох місць, де працює Ava: розширення VS Code, десктопна програма та термінал). Налаштуйте їх у налаштуваннях кожного місця. Не потрібно запам'ятовувати список нижче.","reference.project-context#title":"Контекст проекту","reference.project-context#0#p":"Тут пояснюється, як Ава ознайомлюється з вашим проектом перед початком роботи — які файли вона переглядає, щоб зрозуміти, над чим ви працюєте. Вам не потрібно нічого налаштовувати: вона робить це сама. Читайте, якщо хочете знати, куди додати нотатку, щоб вона завжди її бачила.","reference.project-context#1#p":"Ава завантажує кілька шарів контексту (фонову інформацію, яку вона тримає в пам'яті), коли ви відкриваєте проект. Розуміння цих шарів допоможе вам розмістити інформацію у правильному місці.","reference.project-context#2#h":"Завантажується автоматично","reference.project-context#3#li0":".ava/instructions.md — розглядається як важливі, пріоритетні інструкції. Завжди в контексті.","reference.project-context#3#li1":".ava/context.md — довільні нотатки. Завантажуються, нижчий пріоритет.","reference.project-context#3#li2":"README.md — сканується при першому запуску для отримання загального опису проекту.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — невеликі файли зі списком налаштувань проекту; читаються для визначення мови, фреймворку та команди тестування.","reference.project-context#3#li4":".gitignore — список файлів, які слід виключити з системи контролю версій; поважається всіма інструментами роботи з файлами (glob, grep, project_index).","reference.project-context#4#h":"Завантажується за запитом","reference.project-context#5#p":"«За запитом» означає, що Ава отримує їх лише тоді, коли завдання дійсно потребує цього, а не заздалегідь.","reference.project-context#6#li0":"Індекс проекту — структурна карта ваших файлів іменованих частин всередині них (функції, класи — «символи») і як вони пов'язані («імпорт»). Створюється ліниво, тобто лише коли Ава це потрібно.","reference.project-context#6#li1":"Історія Git — запис минулих змін; завантажується при виклику git_status, git_diff або git_create_pr (Git — це інструмент, який відстежує кожну зміну в проекті; «PR» — це запит на вилучення, запропонована партія змін).","reference.project-context#6#li2":"Пам'ять — записи співвідносяться за значенням («семантично») і вводяться по одному кроці, а не всі одразу.","reference.project-context#7#c":"Правила розміщуйте в instructions.md. Нотатки — в context.md. Дозвольте пам'яті самостійно захопити решту.","features.unified-panel#title":"Єдина панель","features.unified-panel#0#p":"Простими словами: все, що робить Ava, живе в одному вікні, тому вам ніколи не доведеться шукати її через вкладки.","features.unified-panel#1#p":"Одна панель для чату, панелі приладів, пам'яті, завдань і журналу. Жодного перемикання контексту між вікнами. Бічна панель обирає те, на що ви дивитесь; основна область змінюється відповідно.","features.unified-panel#2#p":"Стан розмови зберігається, коли ви переходите далі — відкрийте пам'ять, перевірте завдання, потім поверніться. Чат все ще там, все ще транслюється, якщо Ava все ще працює.","features.unified-panel#3#c":"Єдина панель — це концепція розширення та IDE. Веб-поверхня використовує вкладки браузера.","features.knowledge-packs#title":"Пакети знань","features.knowledge-packs#0#p":"Простими словами: дайте Ava папку зі своїми документами, і вона зможе читати їх, щоб відповісти на ваші запитання. «Пакет знань» — це просто набір файлів — ваші довідкові матеріали, з яких вона має право черпати.","features.knowledge-packs#1#p":"Перетягніть директорію з довідковими матеріалами (специфікації, RFC, нотатки зустрічей, документи API) у пакет знань. Ava може витягувати відповідні частини в контекст, коли розмова торкається теми.","features.knowledge-packs#2#p":"Пакети індексуються локально. Пошук є семантичним — Ava знаходить правильний документ за змістом, а не за назвою файлу. («Семантичний» означає, що вона співвідносить те, про що документ, тому вам не потрібно пам'ятати точні слова або назву файлу.) Пакети можна ділитися з командою або залишати приватними.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Потрібен звіт, лист чи документ? Ava може написати його і надати вам справжній файл Word, Excel або PDF, який ви зможете відкрити та редагувати як будь-який інший.","features.office-suite#1#p":"Звіти, листи та документи — складені, відформатовані та експортовані у рідні формати (.docx це Word, .xlsx це Excel, .pdf це PDF).","features.office-suite#2#li0":"report_generate — структурований .docx, що бере дані з завдань, щоденника, пам'яті та стану проекту.","features.office-suite#2#li1":"email_draft — електронний лист із контролем тону у файл .docx.","features.office-suite#2#li2":"document_manage — створення, читання, редагування, експорт у Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Корисно, коли Ava пише від вашого імені — звіти про статус, презентації для старту, оновлення для клієнтів. Файл .docx потрапляє у ваш проект, де ви зможете його доопрацювати.","features.dashboard-library#title":"Бібліотека дашбордів","features.dashboard-library#0#p":"Простими словами: одна полиця, де зберігається все, що ви і Ava створили та обговорили, щоб нічого не загубилося.","features.dashboard-library#1#p":"Переглядаваний огляд всього, що Ava створила разом із вами — згенеровані зображення, відео, аудіо, документи — поряд із вашими розмовами, спогадами та завданнями. Одне місце, щоб знайти те, що ви зробили минулого тижня.","features.document-preview#title":"Попередній перегляд документа","features.document-preview#0#p":"Простими словами: подивитися всередину документа прямо там, де ви є, не відкриваючи окрему програму для читання.","features.document-preview#1#p":"Натисніть правою кнопкою миші на файл Word, Excel, PDF, CSV, HTML або Markdown у своєму проекті — перегляньте його вбудовано, не залишаючи редактора. Корисно для читання матеріалів, які згенерувала Ava, або файлів, які додав співпрацівник.","features.daily-briefing#title":"Щоденний брифінг","features.daily-briefing#0#p":"Простими словами: короткий запис «ось де ви зупинилися» кожного ранку, щоб ви могли продовжити, не перечитуючи все заново.","features.daily-briefing#1#p":"Ранковий підсумок: щоденник за вчора, відкриті завдання, стан проекту та будь-які нагадування, які встановила Ava. Опціонально — увімкніть у налаштуваннях.","features.daily-briefing#2#p":"Брифінг використовує пам'ять, щоб показати релевантний контекст (\"востаннє, коли ви працювали над потоком автентифікації, ви зазначили, що хотіли б повернутися до стратегії refresh token\"). Це не стрічка новин — а сфокусований збір інформації.","troubleshooting.logs#4#c":"Логи можуть містити уривки файлів проекту, які Ava прочитала під час сесії. Перегляньте перед тим, як ділитися.","troubleshooting.support-request#title":"Оформлення запиту до служби підтримки","troubleshooting.support-request#0#p":"Простими словами: якщо щось не так і наведені вище виправлення не допомогли, надішліть нам повідомлення про це. Найпростіший спосіб — просто попросити Ava зробити це за вас.","troubleshooting.support-request#1#p":"Якщо проблема не описана серед поширених помилок, створіть тикет підтримки (надішліть команді підтримки запит про допомогу). Ви можете зробити це всередині Ava (не потрібно заповнювати форми) або на сайті.","troubleshooting.support-request#2#h":"Зсередини Ava","troubleshooting.support-request#3#p":"Попросіть її оформити його. «Ava, ти можеш оформити тикет підтримки щодо цього?» Вона викликає support_request, прикріплює відповідний контекст сесії (з прихованими обліковими даними) та надсилає його. Найшвидший шлях.","troubleshooting.support-request#4#h":"Через веб-сайт","troubleshooting.support-request#5#p":"Відвідайте ava-supernova.com/support. Оберіть категорію (помилка, функція, акаунт, безпека, загальна) та опишіть, що сталося. Відповідь протягом одного робочого дня.","troubleshooting.support-request#6#h":"Що включити","troubleshooting.support-request#7#li0":"Що ви намагалися зробити.","troubleshooting.support-request#7#li1":"Що сталося насправді.","troubleshooting.support-request#7#li2":"Який інструмент (розширення, IDE, CLI, додаток-компаньйон) та яка версія.","troubleshooting.support-request#7#li3":"Будь-яке повідомлення про помилку або уривок логу. Спочатку приховуйте облікові дані.","troubleshooting.security-disclosure#title":"Повідомлення про проблеми безпеки","troubleshooting.security-disclosure#0#p":"Простими словами: якщо ви помітили спосіб, яким Ava можна зламати або використати не за призначенням («вразливість» — слабкість у безпеці), будь ласка, сповістіть нас приватно спочатку, щоб ми могли виправити це, перш ніж хтось зможе скористатися цим. Ця сторінка пояснює, як це зробити.","troubleshooting.security-disclosure#1#p":"Знайшли вразливість? Дякуємо. Ми ставимося до кожного звіту серйозно і працюємо з вами над виправленням до будь-якого публічного розголошення (до того, як проблему оголосять публічно).","troubleshooting.security-disclosure#2#h":"Як повідомити","troubleshooting.security-disclosure#3#li0":"Надішліть електронний лист на security@ava-supernova.com із описом, кроками відтворення та вашим бажаним вікном розголошення.","troubleshooting.security-disclosure#3#li1":"Або створіть тикет підтримки з категорією «безпека» — той самий черговий пул.","troubleshooting.security-disclosure#3#li2":"Ми підтверджуємо отримання протягом 24 годин.","troubleshooting.security-disclosure#4#h":"Наші зобов'язання","troubleshooting.security-disclosure#5#li0":"Координоване розголошення — ми домовляємося про терміни з вами перед чим-небудь публічним. За замовчуванням — 90 днів.","troubleshooting.security-disclosure#5#li1":"Подяка — ви отримуєте подяку в примітках до виправлення, якщо не надаєте перевагу анонімності.","troubleshooting.security-disclosure#5#li2":"Жодних судових заходів — дослідження добросовісно вітаються. Ми не залучатимемо юристів проти вас.","troubleshooting.security-disclosure#6#c":"Сторінка безпеки за адресою ava-supernova.com/security має повну інформацію — гарантії архітектури, редактор, контроль доступу.","troubleshooting.common-errors#title":"Поширені помилки","troubleshooting.common-errors#0#p":"Більшість помилок мають коротку, конкретну причину. Ось найпоширеніші та як їх виправити. Не хвилюйтеся, якщо терміни здаються технічними — кожен пункт нижче пояснює, що саме ви бачите і що робити.","troubleshooting.common-errors#1#h":"Модель не відповідає","troubleshooting.common-errors#2#p":"Що ви бачите: Ava мовчить і не відповідає.","troubleshooting.common-errors#3#p":"Перевірте індикатор статусу в заголовку чату. Якщо там написано «підключення», ваш провайдер (сервіс ШІ, з яким спілкується Ava) доступний, але повільний — дайте йому тридцять секунд. Якщо написано «недоступно», Ava автоматично перемкнулася на наступну модель у ланцюжку (вона перейшла на резервну модель). Якщо взагалі нічого немає, перевірте свій API ключ у налаштуваннях і протестуйте з'єднання. (API ключ — це приватний пароль, який дозволяє Ava використовувати платний сервіс ШІ.)","troubleshooting.common-errors#4#h":"Виклик інструменту не вдався","troubleshooting.common-errors#5#p":"Що ви бачите: один із кроків Ava («виклик інструменту» — читання файлу, запуск команди тощо) показує червону помилку замість того, щоб завершитися.","troubleshooting.common-errors#6#p":"Натисніть на невдалий виклик інструменту, щоб побачити помилку. Поширені причини: вона спробувала торкнутися файлу поза межами вашої проектної папки, що навмисно заблоковано для вашої безпеки (цей захист називається «захистом від перехоплення шляху» — він не дає їй блукати за межами папки, в якій ви працюєте); команда, яка має запуститися в іншій папці; або файл, який перемістили після того, як Ava його переглянула. Поясніть їй, що сталося — вона спробує знову з виправленнями.","troubleshooting.common-errors#7#h":"Пам'ять не згадує","troubleshooting.common-errors#8#p":"Що ви бачите: Ava не може знайти те, що, на вашу думку, вона повинна пам'ятати.","troubleshooting.common-errors#9#p":"Пам'ять працює за змістом, а не за точними словами (саме так означає «семантичне»). Тому «Про що ми домовилися щодо авторизації?» спрацює краще, ніж «знайди моє рішення щодо auth». Якщо пам'ять точно є, але не знаходить її, відкрийте браузер пам'яті і пошукайте — якщо її там немає, значить, вона ніколи не була збережена.","troubleshooting.common-errors#10#h":"Зациклення входу","troubleshooting.common-errors#11#p":"Що ви бачите: ви входите в систему, але Ava постійно просить вас увійти знову — цикл, який ніколи не пропускає вас далі.","troubleshooting.common-errors#12#p":"Рішення — очистити збережені дані для входу і почати заново: у розширенні виконайте «Ava: Sign Out» з палітри команд, в IDE перейдіть до Налаштування → Обліковий запис → Вийти, у CLI видаліть файл за адресою ~/.ava/auth.json (невеликий файл входу в папці .ava у вашій домашній директорії). Потім увійдіть знову.","troubleshooting.common-errors#13#h":"Токени вичерпано","troubleshooting.common-errors#14#p":"Що ви бачите: повідомлення про те, що ви вичерпали безкоштовне використання за місяць. («Токени» — це одиниця виміру використання ШІ — «вичерпано» просто означає, що ви використали цей місячний безкоштовний ліміт.)","troubleshooting.common-errors#15#p":"Безкоштовний місячний бюджет скидається 1-го числа кожного місяця. До цього часу переключіться на провайдера BYOK (використовуйте свій власний API ключ), щоб продовжити роботу. Ваш обліковий запис залишається активним — призупиняються лише безкоштовні запити, керувані платформою.","troubleshooting.logs#title":"Де знаходяться логи","troubleshooting.logs#0#p":"«Лог» — це просто щоденник, який ваш комп'ютер веде про те, що відбувається — корисно, коли щось ламається і вам (або підтримці) потрібно побачити деталі.","troubleshooting.logs#1#p":"Коли вам потрібна сира картина — який інструмент було викликано, яку інформацію він отримав, що повернув сервіс ШІ — логи є текстовими файлами в папці на вашому комп'ютері за адресою ~/.ava/logs/ (папка .ava у вашій домашній директорії, всередині якої є папка logs).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — транскрипти кожної сесії, включаючи виклики інструментів, потокові відповіді та помилки.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — лог хоста розширення VS Code. Збої активації, помилки панелі.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — лог настільної IDE. Повідомлення процесу Sidecar, збої Rust.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — лог CLI REPL.","troubleshooting.logs#3#p":"У розширенні «Ava: Show Logs» у палітрі команд відкриває відповідний лог у вкладці редактора. В IDE в Налаштуваннях → Діагностика є кнопка «Відкрити логи». CLI може слідкувати за своїм логом через ava logs --follow.","features.workflows#title":"Робочі процеси","features.workflows#0#p":"Простими словами: навчите Ava рутинну дію, яку ви повторюєте постійно, дайте їй назву, і вона зможе запустити все це знову за вашим запитом. «Робочий процес» — це просто збережена рутина — набір кроків, які Ava виконує для вас.","features.workflows#1#p":"Збережіть послідовність кроків, яку ви самі собі повторюєте — перевірка PR → запуск тестів → написання нотаток до випуску → чернетка листа. Робочий процес — це багаторазовий план, який Ava може відтворити з різними вхідними даними.","features.workflows#2#p":"Робочі процеси зберігаються для кожного проекту в папці .ava/workflows/ всередині вашого проекту. Поділіться ними зі своєю командою, закомітивши каталог (зберігши його у спільному проекті, щоб колеги теж отримали доступ).","features.events#title":"Події та сповіщення","features.events#0#p":"Простими словами: поки Ava працює, ви отримуєте чіткий покроковий список того, що вона робить, і сигнал, коли довга задача завершується, щоб ви могли відійти.","features.events#1#p":"Поки Ava виконує задачу, ви бачите структуровані оновлення, а не стіну тексту. Кожен виклик інструменту, кожна передача між ролями, кожне оновлення в режимі реального часу — це окрема подія в інтерфейсі — можна розгорнути для деталей або згорнути для огляду.","features.events#2#p":"Фонові запуски надсилають сповіщення рівня операційної системи після завершення. Ви можете відійти від тривалої збірки, і Ava повідомить вас, коли вона буде готова.","features.personality#title":"Налаштування особистості","features.personality#0#p":"Простими словами: налаштуйте, як Ava спілкується з вами — щоська чи стисла, офіційна чи невимушена, більше жартів чи менше — щоб вона звучала так, як вам подобається.","features.personality#1#p":"Визначте стиль спілкування Ava. Тон, енергія, обсяг мовлення, формальність, гумор. Повзунки та готові налаштування — стислий інженер, теплий наставник, сухий колега або ваша власна суміш.","features.personality#2#p":"Особистість впливає на формулювання, а не на компетентність. Вона все одно використовує ті самі інструменти та дотримується тих самих правил доступу. Її ім'я закріплено за Ava — це необговорювано.","features.release-notes#title":"Нотатки до випуску","features.release-notes#0#p":"Простими словами: поточний список того, що нове і що було виправлено в кожному оновленні, щоб ви бачили, що змінилося.","features.release-notes#1#p":"Список змін у додатку (історія змін). Кожна випущена версія з її головними моментами, виправленнями помилок та змінами, що вимагають коригування (зміни, які можуть потребувати налаштування способу використання чогось). Веб-сторінка підтримує публічну версію на ava-supernova.com/releases.","concepts.memory#1#p":"Ava має стійку пам'ять (`\"persistent\"` означає, що вона зберігається після закриття додатка), яка зберігається між розмовами, між проектами та між пристроями, якщо увімкнути синхронізацію (синхронізація копіює вашу пам'ять між пристроями). Це не журнал чату. Це структуроване, пошукове розуміння того, хто ви, що вам подобається і що ви вирішили.","concepts.memory#2#h":"П'ять шарів","concepts.memory#3#li0":"Витяг — ключові факти, захоплені з кожного повідомлення в режимі реального часу.","concepts.memory#3#li1":"Рефлексія — глибший аналіз запускається в кінці важливих сесій. Патерни, теми, суперечності.","concepts.memory#3#li2":"Накопичення — виправлення та вподобання накопичуються протягом тижнів і місяців.","concepts.memory#3#li3":"Аналіз — графове ядро зв'язує пов'язані спогади та позначає суперечності, коли нова інформація конфліктує зі старою.","concepts.memory#3#li4":"Консолідація — схожі спогади об'єднуються; застарілі видаляються. Пам'ять стає чіткішою з часом, а не шумнішою.","concepts.memory#4#c":"П'ять шарів вище працюють самостійно — вам ніколи не потрібно ними керувати. Вони тут, щоб ви бачили, як пам'ять справді покращується з часом, а не перетворюється на купу сміття.","concepts.memory#5#h":"Згадування","concepts.memory#6#p":"Коли ви запитуєте щось, Ava шукає в пам'яті за змістом (`\"semantic search\"` — вона розуміє, що ви маєте на увазі, тому знаходить потрібний спогад, навіть якщо ви сформулювали це інакше), а не просто за точним збігом слів. Фільтри залежно від режиму працюють поруч — Режим Чату тягне особистий контекст, Режим Роботи — проектні рішення та патерни коду.","concepts.memory#7#c":"Пам'ять обмежена користувачем і проектом (ваші спогади ваші, збережені окремо за людиною та за проектом). Секрети та облікові дані (паролі, ключі) блокуються на етапі збереження — вони ніколи не потраплять у пам'ять.","start.what#title":"Що таке Ava?","start.what#0#p":"Ava — це ШІ, який дійсно щось робить, а не просто говорить. Вона створить для вас додаток, напише документ, навчить чогось з нуля, розробить логотип або візьме на себе ту адміністративну роботу, яку ви постійно відкладаєте. І вона пам'ятає вас: над чим ви працюєте, як вам подобається робити речі, що ви просили минулого тижня.","start.what#1#p":"Є одна Ava, і вона працює там, де й ви — у вашому редакторі коду, як десктопний додаток, на телефоні чи в терміналі. Однакова пам'ять, однаковий характер скрізь.","start.what#2#h":"Чим вона відрізняється","start.what#3#li0":"За замовчуванням ваша. Ваша робота залишається на вашій машині. Жодного відстеження, жодної телеметрії — ніколи.","start.what#3#li1":"Відкрита для всіх. Кожен рядок Ava публічний. Нічого не потрібно приймати на довіру.","start.what#3#li2":"Безкоштовно для старту. 300 кредитів щомісяця, без картки, без підводних каменів — або підключіть свої власні ключі ШІ і не платьте нам взагалі нічого.","start.what#3#li3":"Навчання безкоштовне назавжди. Навчатися не повинно бути платним.","start.what#4#p":"Ніколи не писали код? Наступна сторінка написана спеціально для вас. Вже технічно підковані? Пропустіть вперед — вона впорається.","start.what#deeper#0#h":"Де живе Ava","start.what#deeper#1#li0":"Розширення VS Code — Ava поруч із вашим редактором: панель чату, панель керування та зміни показуються вбудовано ще до того, як вони стануться.","start.what#deeper#1#li1":"Десктопний IDE — окремий додаток, де все одразу в одному вікні. Додає керування комп'ютером (відкриття програм, кліки, введення тексту за вас).","start.what#deeper#1#li2":"Супутник — мобільний додаток, коли ви далеко від столу: завдання, щоденник, пам'ять, швидкі чати.","start.what#deeper#1#li3":"CLI — Ava у вашому терміналі, для тих, хто там живе.","start.what#deeper#2#h":"Як вона працює, коротко","start.what#deeper#3#p":"Ava перемикає режими мислення (звані режимами), щоб відповідати завданню, непомітно запускає невелику команду спеціалізованих помічників для складнішої роботи та автоматично обирає найкращу модель ШІ для кожного кроку. Ви ніколи не керуєте цим. У розділі «Основні концепції» є повний огляд, якщо вам цікаво.","start.first-five#title":"Ваше перше завдання з Ava","start.first-five#0#p":"Найшвидший спосіб отримати Ava — попросити її про щось реальне і подивитися, як вона це зробить. Не треба читати налаштування, нічого вчити спочатку — просто скажіть їй, що ви хочете, простими словами.","start.first-five#1#h":"Спробуйте зараз","start.first-five#2#li0":"Відкрийте чат.","start.first-five#2#li1":"Напишіть те, що ви справді хочете. Спробуйте «поясніть, що робить цей проект», або «додайте кнопку, яка очищає форму».","start.first-five#2#li2":"Ava показує вам, що вона збирається зробити — і чекає.","start.first-five#2#li3":"Вам подобається? Скажіть так. Подивіться, як вона це робить.","start.first-five#3#p":"Це весь ритм: ви запитуєте, вона показує план, ви погоджуєтесь, вона робить. Вона ніколи нічого не змінює, не показавши вам спочатку — тому ви не зламаєте нічого, пробуючи.","start.first-five#4#h":"Кілька речей, які варто попросити","start.first-five#5#li0":"Питання — \\\"чому мій екран порожній?\\\", \\\"що робить цей файл?\\\"","start.first-five#5#li1":"Щось створено — \\\"зроби мені просту сторінку зі списком справ\\\".","start.first-five#5#li2":"Щоб чогось навчитись — \\\"навчи мене Python з нуля\\\". (Завжди безкоштовно.)","start.first-five#5#li3":"Документ — \\\"напиши мені односторінкову пропозицію проекту\\\". Вона передасть вам файл Word або PDF.","start.first-five#6#c":"Не впевнені, що писати? Розмовляйте з нею як із знавцем-другом. Звичайні слова — саме те, що треба — вам ніколи не доведеться використовувати технічні терміни, щоб почати.","start.first-five#deeper#0#p":"Цей простий цикл виконує чимало роботи за лаштунками. Вам не потрібно знати цього, щоб користуватися Ava — але ось що насправді відбувається, якщо вам цікаво.","start.first-five#deeper#1#h":"Інструменти та погодження","start.first-five#deeper#2#p":"Коли Ava читає файл, запускає команду або редагує код, кожна така дія називається \\\"викликом інструмента\\\". Вона запитує перед тим, як щось торкнеться ваших файлів чи системи — як часто вона питає, залежить від вашого режиму дозволів (питати кожного разу, питати лише для ризикованих дій або просто йти далі).","start.first-five#deeper#3#h":"Режими — її стан душі","start.first-five#deeper#4#p":"Ava працює в режимах: спосіб мислення плюс правильний набір інструментів для завдання. Можна змінити будь-коли через вибірник або ввести префікс на початку повідомлення. Їх сім.","start.first-five#deeper#6#h":"Спеціалісти та маршрутизація","start.first-five#deeper#7#p":"При складних завданнях Ava запускає за лаштунками маленьку команду спеціалістів-помічників (планувальника, перевіряльника, будівельника) і спрямовує кожен крок до моделі, яка найкраще з цим впорається. Ви ніколи не керуєте цим — вона координує все за вас.","start.local-vs-cloud#title":"Локально проти хмари, одним абзацом","start.local-vs-cloud#0#p":"Усе, що робить Ava, локальне, якщо ви явно не погодилися інакше. Пам'ять, завдання, журнал, особистість, налаштування — усе зберігається на вашому комп'ютері в ~/.ava/ та .ava/ (для кожного проекту). Вона спілкується з постачальниками моделей через HTTPS, щоб виконати ваш запит, а потім повертається додому. Вона не телефонує додому. Вона не збирає телеметрію. Вона не тренується на вашому коді.","start.local-vs-cloud#1#p":"Якщо ви увійдете в систему, ви отримаєте 300 безкоштовних кредитів на місяць для моделей, керованих платформою (Qwen, MiniMax), та опціональний хмарний синхронізацію пам'яті та налаштувань між пристроями. Синхронізація за функцією, можна скасувати будь-коли. Використовуйте свій власний API key, і Ava повністю працює без облікового запису.","start.local-vs-cloud#2#c":"Правило: локальне — священне. Хмара — додаткова.","start.first-model#title":"Чи потрібно обирати ШІ?","start.first-model#0#p":"Ось полегшення: ви не обираєте ШІ. Ava сама обирає потрібну для кожного кроку автоматично, тому ви отримуєте хороші результати, не думаючи про це.","start.first-model#1#p":"Єдина річ, яку ви можете обрати — це стиль маршрутизації — і стандартний підходить майже всім. Інші потрібні лише для конкретної причини.","start.first-model#2#h":"Три стилі","start.first-model#3#li0":"Maestro — стандартний. Стабільний, надійний, передбачуваний. Не впевнені? Це той самий.","start.first-model#3#li1":"Supernova — для важкої, багатокрокової роботи, де вигідно поставити різного спеціаліста на кожну частину завдання.","start.first-model#3#li2":"Aurora — коли ваші дані мають залишатися в ЄС (держсектор, охорона здоров'я, суворі приватність). Працює повністю на європейському ШІ з відкритими параметрами.","start.first-model#4#p":"Змінити можна будь-коли через вибірник моделей угорі чату. Нічого не заблоковано.","start.first-model#5#c":"Хочете керувати однією конкретною моделлю самі? Можете — відкрийте \\\"Покажіть мені деталі\\\".","start.first-model#deeper#0#h":"Що насправді в кожному стилі","start.first-model#deeper#1#p":"Maestro — один диригент (Qwen 3.6 Plus) обробляє кожен крок. Налаштовано для виробництва, перевірено, передбачувана вартість.","start.first-model#deeper#2#p":"Supernova — координатор нового рівня (DeepSeek V4 Pro, 1.6 трлн параметрів / 49 млрд активних, контекст 1 млн) передає кожну підзадачу спеціалісту: V4 Flash для великих обсягів збірки, Qwen 3.6 Plus як резервний варіант, Qwen Omni для роботи з візуальним контентом.","start.first-model#deeper#3#p":"Aurora — тільки Mistral, у трьох рівнях: Mistral Large 3 (координатор + важкі спеціалісти), Mistral Medium 3.5 (128 млрд щільна, контекст 256 тис., нативне бачення, модифікований MIT відкриті ваги, 77.6% SWE-Bench Verified) для будівника + середнього рівня + бачення + довгих текстів, і Mistral Small 4 на вході наміру. Відкриті ваги від початку до кінця, ніколи не залишає інфраструктуру ЄС.","start.first-model#deeper#4#h":"Використовуйте свою модель (BYOK)","start.first-model#deeper#5#p":"Хочете використовувати свій акаунт ШІ? Вставте ключ провайдера в налаштування, і ви отримаєте все — три стилі маршрутизації, плюс можливість обрати одну модель і взагалі пропустити маршрутизацію. Корисно при сильній перевазі, суворому бюджеті або тестуванні конкретної моделі. Повний список провайдерів є в розділі «Довідка».","start.glossary#title":"Глосарій простою мовою","start.glossary#0#p":"Кожне слово, з яким ви зіткнетеся в роботі з Ava, пояснено просто. Вам не треба цього вчити — заглядайте сюди, якщо якийсь термін здасться незрозумілим.","start.glossary#1#th0":"Слово","start.glossary#1#th1":"Що це означає насправді","start.glossary#1#td0.0":"Агент","start.glossary#1#td0.1":"ШІ, який може виконувати дії за вас — читати файл, запускати команду, шукати в мережі — не лише чатити. Ava — це агент: вона робить справи, але тільки за вашим дозволу.","start.glossary#1#td1.0":"Модель","start.glossary#1#td1.1":"Справжній мозок ШІ, що думає (Qwen, DeepSeek, Mistral та інші). Різні моделі мають різні сильні сторони. Зазвичай ви ніколи не обираєте одну — це робить Ava.","start.glossary#1#td2.0":"Режим","start.glossary#1#td2.1":"Настрій, у якому перебуває Ava. Як колега, що змінює капелюхи: будівник, письменник, вчитель, планувальник, друг. Ви обираєте режим; це змінює її поведінку. Їх сім.","start.glossary#1#td3.0":"Персона / спеціаліст","start.glossary#1#td3.1":"Допоміжні ролі, які запускає Ava за лаштунками для складніших завдань — дослідник, планувальник, фактчекер. Уявіть маленьку команду експертів. Ви ніколи не спілкуєтесь із ними напряму; Ava координує їх.","start.glossary#1#td4.0":"Маршрутизація","start.glossary#1#td4.1":"Рішення Ava, яку модель використати на кожному кроці, щоб ви отримували гарні відповіді, не переплачуючи. Це відбувається автоматично — «режим маршрутизації» просто обирає загальну стратегію.","start.glossary#1#td5.0":"Інструмент","start.glossary#1#td5.1":"Конкретна дія, яку може виконати Ava — прочитати файл, зробити пошук, надіслати електронного листа. «Виклик інструменту» — це коли вона ним користується. Вона просить дозвіл перед будь-чим ризикованим.","start.glossary#1#td6.0":"Токен","start.glossary#1#td6.1":"Як ШІ вимірює текст — приблизно ¾ слова. Моделі коштують за мільйон токенів. Загалом, це те, що можна ігнорувати.","start.glossary#1#td7.0":"Кредит","models.routing#deeper#1#h":"Поруч","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Координатор","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B активних, 1M контекст)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B активних, 262K контекст)","models.routing#deeper#2#td1.0":"Конструктор","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (використовує координатора)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B щільна, 256K контекст)","models.routing#deeper#2#td2.0":"Спеціалісти середнього рівня","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (перевірник коду, фактчекер, розвідка, сканер, перевірка безпеки тощо)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Архітектор, Перевіряючий, Планувальник, Наставник, Звітувальник тощо)","models.routing#deeper#2#td3.0":"Легкий рівень / фільтр намірів","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Розвідник, Перевіряючий, Планувальник, Опонент, Інтегратор)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Експертні спеціалісти","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Дослідник, Опонент, Дослідник CVE, Генератор ідей, Фактчекер)","start.glossary#1#td7.1":"Простіша одиниця для вартості дій від Ava, щоб вам не доводилося рахувати токени. У планах вже є щомісячний пакет.","start.glossary#1#td8.0":"Ключ API","start.glossary#1#td8.1":"Приватний пароль, який дає програмі доступ до платної послуги (наприклад, моделі ШІ) у вашому обліковому записі. Він потрібен лише якщо ви хочете підключити свій власний.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Bring Your Own Key.\" Використання свого власного ключа API замість керованого доступу Ava. Необов'язково — для тих, хто вже платить постачальнику напряму.","start.glossary#1#td10.0":"Local-first","start.glossary#1#td10.1":"Ваші дані живуть на вашому комп'ютері за замовчуванням. Ніщо не завантажується, доки ви не увімкнете синхронізацію. «Локальне — священне.»","start.glossary#1#td11.0":"Режим дозволів","start.glossary#1#td11.1":"Наскільки обережною є Ava перед діями — запитувати завжди, тільки для ризикованих, або просто виконувати. Ви самі обираєте рівень.","start.glossary#1#td12.0":"Контекстне вікно","start.glossary#1#td12.1":"Скільки тексту модель може тримати в голові одночасно — її короткочасна пам'ять. «1M контекст» означає приблизно мільйон слів. Чим більше, то більше вона може прочитати, перш ніж забути.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"Вигляд поруч того, що саме зміниться у файлі — старе з одного боку, нове з іншого — показується перед тим, як Ava щось змінить, щоб ви могли це схвалити.","start.glossary#1#td14.0":"Репозиторій (репо)","start.glossary#1#td14.1":"Тека проекту, за якою відстежуються зміни, зазвичай через Git. Якщо це ще нічого не говорить, це просто \"тека, де живе мій проект\".","start.glossary#1#td15.0":"Промпт","start.glossary#1#td15.1":"Те, що ви пишете ШІ — ваше запитання чи інструкція.","start.glossary#2#c":"Все ще застрягли на слові? Запитайте Ava в режимі чату — «що означає X?» — і вона пояснить це для вашого рівня.","models.routing#title":"Маршрутизація — як Ava обирає моделі","models.routing#0#p":"Ось коротко: вам ніколи не потрібно обирати, яку модель ШІ використовувати. Ava робить це за вас, обираючи найкращий інструмент для кожної частини завдання — так, як хороший менеджер доручає правильну задачу правильній людині.","models.routing#1#p":"Ви обираєте один із трьох стилів — Maestro, Supernova або Aurora — і Ava надсилає кожну частину роботи тій моделі, яка справляється з нею найкраще. Maestro є стандартом, він доступний на кожному плані, і це гарний вибір майже для всіх.","models.routing#2#h":"Навіщо взагалі маршрутизація?","models.routing#3#p":"Розміщення правильної моделі на кожному кроці коштує менше, ніж запуск усього на одній великій дорогій моделі — і дає кращі результати, бо кожна модель робить те, в чому вона найкраща. Ви отримуєте стабільну ціну та високу якість, не доведеться знати, яка модель яка.","models.routing#4#c":"Усі три стилі працюють на кредити платформи та на ваших власних ключах. З вашим власним ключем ви також можете пропустити маршрутизацію і керувати однією моделлю напряму. Повний перелік моделей знаходиться під «Покажіть мені деталі».","models.routing#deeper#0#c":"Числа «B» нижче — це мільярди параметрів — приблизно розмір «мозку» моделі; більше зазвичай означає розумніше, але повільніше і дорожче. Це технічна деталь «під капотом»; вам ніколи не потрібно знати це, щоб користуватися Ava.","models.routing#deeper#2#td5.0":"Чат","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Управління генерацією зображень","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Розуміння зображень","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (кодер зображень, навчений з нуля)","models.routing#deeper#2#td8.0":"Написання довгих текстів","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Де зберігаються дані","models.routing#deeper#2#td9.1":"Комбіновано (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Комбіновано (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Лише ЄС · відкриті параметри","models.routing#deeper#2#td10.0":"Статус","models.routing#deeper#2#td10.1":"Доступно · усі тарифи","models.routing#deeper#2#td10.2":"Незабаром","models.routing#deeper#2#td10.3":"Незабаром","models.routing#deeper#2#td11.0":"Для чого найкраще","models.routing#deeper#2#td11.1":"Щоденна робота, передбачувана вартість","models.routing#deeper#2#td11.2":"Важка багатоетапна робота, передовий координатор у кожному тарифі","models.routing#deeper#2#td11.3":"Суворе дотримання GDPR, державний сектор, суверенні європейські стеки","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Розподіл за рівнями Qwen з легким навантаженням. Qwen 3.6 Plus бере на себе роль координатора, а також завдання планування, безпеки, мозкового штурму та роботи з великим контекстом — саме тут його гібридна лінійна увага на 1 млн токенів показує себе найкраще. Qwen 3.5 Flash обслуговує чат, оркестрацію генерації зображень та верхівковий фільтр намірів, де ціни $0.07/$0.26 і швидший час до першого токена (TTFT) дають перевагу при великому обсязі простих запитів. Qwen 3.5 Omni Plus відповідає за візуальний вхід (у Qwen 3.6 Plus немає рідної підтримки візуалу). Qwen 3.5 Plus бере на себе довгі тексти з урахуванням вартості. Якщо основний координатор недоступний, система переходить по сходах пріоритетів: Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Поліглотський ансамбль. DeepSeek V4 Pro координує та розподіляє кожну підзадачу найкращому спеціалісту: Qwen 3.6 Plus виконує всі запуски Builder, V4 Flash обслуговує чат плюс середньорівневі ролі огляду/аудиту, Qwen 3.5 Flash поглинає роботу класифікатора легкого рівня, Qwen 3.5 Omni Plus відповідає за візуальний вхід, Qwen 3.5 Omni Flash оркеструє виклики інструментів генерації зображень, Qwen 3.5 Plus веде роль Content Writer для довгих текстів з урахуванням вартості. Передові обчислення там, де це важливо, економія рівня flash на основному обсязі токенів.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Європейський стек ШІ — суверенний за замовчуванням. Маршрутизація тільки Mistral у трьох рівнях: Mistral Large 3 (675B/41B-active sparse MoE) виконує роль координатора та важких спеціалістів, яким потрібна глибина — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — а також «чорнову» роботу з великим контекстом, де ефективність sparse-MoE перемагає. Mistral Medium 3.5 — об'єднаний флагман, випущений квітнем 2026 року, 128B щільний, 256K контекст, візуальний енкодер навчений з нуля, модифікований MIT open weights, 77.6% SWE-Bench Verified — виконує реальний робочий рівень: запуски Builder, середньорівневі спеціалісти (Architect, Verifier, Sequencer, Tutor, Reporter), візуальний вхід та написання довгих текстів. Mistral Small 4 розширився від однієї ролі на ворітках наміру до також обслуговування чату та оркестрації генерації зображень — його ціни $0.15/$0.60 та конфігуровані міркування окупаються на високообсягових низькоглибинних маршрутах. Відкриті ваги від початку до кінця, ніколи не покидає інфраструктуру ЄС. Aurora свідомо не перехоплює автоматично маршрут до моделі не Mistral, коли одна недоступна; роутер виводить помилку — саме це робить його \"Aurora\", а не Maestro зі смаком Mistral.","credits.overview#title":"Кредити Ava — як працює оплата","credits.overview#0#p":"Кредити — це просто спосіб, яким Ava рахує ваше використання — як хвилини у телефонному тарифі. Кожен план, навіть безкоштовний, має пул кредитів, і кожна дія Ava (відповідь вам, створення зображення) коштує невеликої кількості з них. Це вся суть. Нижче деталі, якщо ви хочете знати точно, що скільки коштує.","credits.overview#1#p":"Ava рахує у кредитах, а не за кількістю токенів. (Токен — це крихітна частинка тексту — приблизно кілька літер, які моделі ШІ читають і пишуть; більшість сервісів стягують плату за токен, що важко передбачити.) Один кредит покриває одну одиницю роботи — хід чату, створення персонажа (один помічник, який робить частину завдання), генерацію зображення. Відокремлення від лічби за токени означає, що вам не потрібно знати, яка модель працює, щоб розуміти вартість дії. Той самий хід чату коштуватиме однаково, чи то Maestro направить його до Qwen 3.6 Plus, чи то Supernova направляє до V4 Pro.","credits.overview#2#h":"Тарифи","credits.overview#3#p":"Кожен план має доступ до всіх функцій — доступ до моделей, Creative Studio, усі сім режимів, повна оркестрація персонажів. Вищі тарифи купують більше кредитів та вищий ліміт запитів, а не розблоковані функції.","credits.overview#4#li0":"Безкоштовний — $0/міс. 300 кредитів. Ліміт 20 запитів/хв. Картка не потрібна.","credits.overview#4#li1":"Pro — $19/міс. 5 000 кредитів. 60 запитів/хв.","credits.overview#4#li2":"Ultra — $39/міс. 10 000 кредитів. 120 запитів/хв.","credits.overview#4#li3":"Enterprise — $79/міс. 20 000 кредитів. 200 запитів/хв.","credits.overview#5#c":"Невикористані кредити переносяться, поки ваша підписка активна — примусового списання немає. Доповнення накопичуються з пулом підписки: 750 кредитів за $3, 2 000 за $8, 4 000 за $15.","credits.overview#6#h":"Скільки коштує","credits.overview#7#p":"Таблиця вартості за дію — що списується з вашого пулу кредитів при запуску кожної дії. («Збіг кешу» — це коли Ava повторно використовує роботу, яку вона вже виконала, замість того, щоб робити її знову; у такому разі ви платите менше — сума знижується на 70%, або 50% на моделях, орієнтованих на вивід, як DeepSeek V4 Pro.)","credits.overview#8#li0":"Хід чату — 2 кредити. Одиночний обмін репліками в будь-якому режимі.","credits.overview#8#li1":"Легкий запит — 1 кредит. Ворітка наміру, класифікація, одноразове читання.","credits.overview#8#li2":"Важкий персонаж — 3 кредити. Архітектор, Дослідник, CVE Дослідник, Ідейник (глибина ≥ 4).","credits.overview#8#li3":"Легкий персонаж — 1 кредит. Розвідник, Перевірювач, Сіквенсер, Викликатель (глибина ≤ 2).","credits.overview#8#li4":"Оркестрація — 10 кредитів. Повний запуск потоку роботи персон (Кондуктор + завдання з кількома персонами).","credits.overview#8#li5":"Генерація зображень — 12 кредитів. Hailuo image-01 через Creative Studio.","credits.overview#8#li6":"Генерація відео — 150 кредитів. Hailuo 02 Pro 1080p 6s кліп.","credits.overview#8#li7":"Генерація голосу — 10 кредитів. Синтез мовлення 2.8 HD.","credits.overview#8#li8":"Генерація музики — 50 кредитів. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Видалення фону — 2 кредити.","credits.overview#9#h":"Множники на основі моделі","credits.overview#10#p":"Цей розділ для допитливих — він не потрібен для використання Ava. Множник просто змінює вартість кредитів у більшу чи меншу сторону залежно від того, наскільки дорога модель стоїть за дією, тому важчі моделі коштують трохи більше. («Чиста маржа» — це частина прибутку, яку проект залишає собі після сплати власних витрат — ми тримаємо її низькою, щоб вигода поверталася до вас.)","credits.overview#11#p":"Важчі моделі множать вартість дії, щоб кредити відображали реальні витрати, а не фіксований тариф. Калібровано під ~55% чистої маржі.","credits.overview#12#li0":"0.6× — Mistral Small 4 (спеціаліст Aurora). Менше ніж 1×, оскільки Mistral Small 4 дешевший за якір Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Базова ставка.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (координатор Aurora). Приблизно на рівні якіря Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (координатор Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (координатор Supernova + важкі спеціалісти). Перераховано з 5.0× для відновлення паритету маржі за опублікованою ставкою V4 Pro.","credits.overview#13#c":"Моделі Anthropic (Claude Opus / Sonnet / Haiku) повністю обходять кредитування — вони доступні лише за схемою BYOK, і ви платите Anthropic напряму. Те саме стосується будь-якого іншого провайдера BYOK при використанні вашого ключа.","credits.overview#14#h":"BYOK та кредити","credits.overview#15#p":"BYOK («принеси свій ключ» — ви надаєте свій власний акаунт у провайдера ШІ та ключ, який є приватним паролем, що дозволяє програмному забезпеченню використовувати цей оплачений акаунт) призначено для тих, хто вже платить провайдеру ШІ напряму. Якщо це не про вас, можете ігнорувати цей розділ цілком.","credits.overview#16#p":"Запити «принеси свій ключ» повністю обходять інфраструктуру платформи — запит йде напряму від Ava до провайдера, ви платите провайдеру, кредити не витрачаються. Єдиний виняток — коли сесія BYOK запускає керовану персону для підзавдання; списання кредитів все одно застосовується, бо використовується система оркестрації Ava.","credits.overview#17#h":"Де перевірити баланс","credits.overview#18#li0":"Розширення — Налаштування → Акаунт, або чип кредитів у шапці чату.","credits.overview#18#li1":"IDE — Плитка панелі керування акаунтом показує поточний баланс та швидкість витрачання.","credits.overview#18#li2":"Веб — ava-supernova.com/dashboard показує баланс, історію та дату поповнення.","credits.overview#19#c":"Локальний режим: Ava працює без акаунту на картці «Власна модель» (Ollama, LM Studio, vLLM або будь-який сумісний з OpenAI ендпоінт). Без кредитів, без платформних токенів — ваша модель, ваша машина, нульовий рахунок.","concepts.modes#title":"Режими — стани свідомості Ava","concepts.desktop-safety#3#li2":"Зворотні дії — введіть текст у поле, вставте, відкрийте програму або перейдіть за посиланням. У режимі «Запит» завжди запитує підтвердження; у Drive всередині білого списку — працює автоматично.","concepts.desktop-safety#3#li3":"Незворотні дії — надіслати, відправити форму, оплатити, видалити, підтвердити, опублікувати. Завжди запитує підтвердження, незалежно від рівня дозволів. Попереднє погодження ніколи не зберігається.","concepts.desktop-safety#3#li4":"Привілейовані — підвищення прав (UAC), sudo, редагування реєстру, запити паролів. Заборонено за замовчуванням. Потрібен одноразовий дозвіл для кожної сесії.","concepts.desktop-safety#4#h":"Ніколи не кешуються погодження","concepts.desktop-safety#5#p":"Усі конкуренти кешують погодження (запам'ятовують ваше «так» і використовують його наступного разу). Це найсильніша точка для ін'єкції промптів — атаки, коли вебсторінка-пастка краде приховані команди до ШІ, щоб змусити його діяти проти вас. Якщо погодження зберігаються, зламана сторінка може скористатися вашим попереднім «так». Ava ніколи не кешує. Кожна незворотна дія запитує підтвердження заново.","concepts.desktop-safety#6#h":"Обробка секретів","concepts.desktop-safety#7#p":"Паролі, ключі API та коди 2FA (одночасові коди, які дає друга програма чи SMS при вході) обробляються через непрозорі маркери — умовні позначки замість справжніх значень. Ava бачить \"{secret}\", а не сам пароль. Справжнє значення ніколи не потрапляє в її пам'ять, лог активності або те, що вона «читає» — окремий низькорівневий шар вводиться в останній момент, під час натискання клавіші, тому частина ШІ ніколи з цим не взаємодіє.","reference.cli#title":"Команди CLI","reference.cli#0#p":"Ця сторінка для CLI — версії Ava, з якою ви спілкуєтеся, набираючи текст у вікні терміналу, а не клікаючи кнопки. Якщо ви користуєтеся розширенням або десктопною програмою, можете пропустити це. Вона тут для тих, хто воліє клавіатуру.","reference.cli#1#p":"CLI — це REPL — інтерфейс, який чекає, поки ви щось наберете, виконує це, а потім знову чекає. Ці слеш-команди (інструкції, що починаються з \"/\") працюють прямо з цього рядка.","reference.cli#2#li0":"/help — перелік команд і поточний режим.","reference.cli#2#li1":"/mode <name> — змінити режим (робота, написання, планування, чат, навчання, безпека, мозковий штурм).","reference.cli#2#li2":"/model <id> — змінити модель, не виходячи з сесії.","reference.cli#2#li3":"/clear — очистити поточну розмову. Пам'ять залишається незмінною.","reference.cli#2#li4":"/history — перелік минулих розмов у цьому проекті.","reference.cli#2#li5":"/memory — відкрити браузер пам'яті.","reference.cli#2#li6":"/tasks — перелік та керування завданнями.","reference.cli#2#li7":"/journal — відкрити сьогоднішній запис у щоденнику.","reference.cli#2#li8":"/settings — меню налаштувань.","reference.cli#2#li9":"/exit — вихід із REPL.","reference.cli#3#h":"Параметри запуску","reference.cli#4#p":"Параметри — це додаткові опції, які ви додаєте при запуску Ava, кожна починається з \"--\", щоб налаштувати спосіб її запуску.","reference.cli#5#li0":"--mode <name> — запустити в певному режимі.","reference.cli#5#li1":"--model <id> — запустити з певною моделлю.","reference.cli#5#li2":"--permission <mode> — суворий / збалансований / автономний.","concepts.modes#0#p":"Режим — це стан, у якому перебуває Ava — як колега, що змінює шапку. Та сама людина, та сама пам'ять про вас, але будівник думає інакше від вчителя. Ви обираєте режим, і це змінює те, як вона поводиться та яких помічників підключає. Змінюйте будь-коли через селектор режиму або введіть двосимвольне скорочення.","concepts.modes#2#h":"Який вам потрібен?","concepts.modes#3#p":"Виходьте з того, що ви хочете зробити — режим випливає з цього:","concepts.modes#4#li0":"Хочу щось побудувати чи змінити → Код (>>). Опишіть це, вона побудує, спочатку показуючи кожну зміну. Повна команда помічників підключається для великих завдань.","concepts.modes#4#li1":"Хочу план перед будь-якими змінами → План (::). Вона продумує все і передає вам план для затвердження чи редагування. Вона не торкатиметься ваших файлів у цьому режимі.","concepts.modes#4#li2":"Просто хочу поговорити чи запитати → Чат (..). Партнер для роздумів із пам'яттю, новинами та погодою. Без змін файлів, без коду — лише розмова.","concepts.modes#4#li3":"Хочу чогось навчитися → Навчання (??). Реальний курс, створений для вас: уроки, тести, усе необхідне. Безкоштовно на кожному тарифі, назавжди. Ідеально, якщо ви новачок.","concepts.modes#4#li4":"Хочу перевірити свій проект на вразливості безпеки → Безпека (!!). Команда проходить стандартний список поширених веб-вразливостей (категорії \"OWASP\") та відомих повідомлених помилок (так званих \"CVE\"), потім передає звіт, відсортований за серйозністю кожного питання. Це для розробників — пропускайте, якщо це не про вас.","concepts.modes#4#li5":"Хочу ідеї → Мозковий штурм (**). Вона генерує варіанти, ґрунтуючись на вашій реальній ситуації, знаходить слабкі місця в них і перетворює решту на наступні кроки.","concepts.modes#4#li6":"Хочу написати документ → Написання (<<). Звіти, пропозиції, листи, статті — вона складає чернетки в Markdown і експортує брендований документ Word або PDF, вдосконалюючи розділ за розділом. Без коду, лише текст.","concepts.modes#5#c":"Команда помічників (персони) працює повністю у фоновому режимі — ви ніколи не спілкуєтесь з ними напряму. Ви просто отримуєте більш детальну відповідь. Вам не потрібно знати їхні імена.","concepts.modes#6#c":"Ви можете змінювати режими під час розмови. Ваша пам'ять зберігається; спеціалісти скидаються під новий режим.","concepts.tasks-journal#title":"Завдання та щоденник","concepts.tasks-journal#0#p":"Ava веде три види нотаток для вас, і їх легко переплутати. Швидкий спосіб запам'ятати: пам'ять — це те, що вона знає про вас, завдання — це те, що вам ще треба зробити, а щоденник — це щоденник перебігу подій. Ось коли використовувати який.","concepts.tasks-journal#1#li0":"Пам'ять — постійні факти. Переваги, рішення, закономірності. Запитуються часто, рідко створюються вручну.","concepts.tasks-journal#1#li1":"Завдання — що робити. Елементи дій з термінами та статусом. Ви викреслюєте їх, коли готово.","concepts.tasks-journal#1#li2":"Щоденник — роздуми. Щоденний журнал, подвійні записи (ваші та спостереження Ava про сесію). Корисно для відстеження настрою, перегляду сесій, контексту на завтра.","concepts.tasks-journal#2#p":"Ava пише до всіх трьох, коли це має сенс. Ви можете писати до будь-якої з них напряму з панелі керування. Ніщо не заблоковане в одному місці, де ви використовуєте Ava — завдання, створене в одному (наприклад, інструмент командного рядка), з'явиться скрізь іншому (наприклад, у десктопному застосунку), автоматично.","concepts.permissions#title":"Дозволи — ваш регулятор безпеки","concepts.permissions#0#p":"Дозволи — це ваш регулятор безпеки. Вони вирішують, коли Ava просить вашого дозволу перед тим, як щось зробити на вашому комп'ютері, проти того, щоб просто взятися за справу. Ви можете налаштувати її так, щоб вона питала про все, питала лише про ризиковане, або довіряла їй бігати — і ви можете змінити це будь-коли. Якщо сумніваєтеся, залиште на значенні за замовчуванням, і все буде гаразд.","concepts.permissions#1#p":"У Ava 60 інструментів (інструменти — це дії, які вона може виконувати — читання файлу, пошук у мережі тощо). Кожен інструмент належить до категорії (операції з файлами, термінал, Git, веб, медіа, база даних, система, документи, пам'ять, навчання). Кожний виклик інструменту проходить через шлюз дозволів (контрольну точку, яка вирішує, чи питати вас спочатку), перш ніж він запуститься. Ви контролюєте, що автоматично схвалюється, що питає один раз, а що завжди питає.","concepts.permissions#3#p":"Збалансований — це за замовчуванням. Суворий, коли ви аудитуєте її поведінку (дивитеся уважно, щоб перевірити кожен крок). Автономний, коли хочете, щоб вона просто діяла.","concepts.permissions#4#c":"Автономний не означає неконтрольований. Плани, уточнюючі запитання та явні запити користувачеві все одно зупиняються для вашого введення. Необоротні операції (Git force-push, видалення баз даних) завжди підтверджуються незалежно від режиму.","concepts.interjection#title":"Керування та зупинка Ava","concepts.interjection#0#p":"Ви завжди керуєте процесом. Поки Ava зайнята роботою, ви можете або підштовхнути її в новому напрямку, не ламаючи ходу, або зупинити її миттєво. Дві кнопки, два результати — ось і все, про що ця сторінка.","concepts.interjection#1#p":"Ava працює, доки не завершить свій план або ви її не зупините. Є два способи втрутитися (це називається «інтервенція»), поки вона працює.","concepts.interjection#2#h":"Втрутитися — керувати без скасування","concepts.interjection#3#p":"Надішліть нове повідомлення, поки Ava працює. Вона завершить поточний виклик інструменту, прочитає ваше повідомлення та коригує план. Жоден контекст не буде втрачено. Використовуйте це, якщо хочете перенаправити дії, додати інформацію або змінити пріоритети під час виконання.","concepts.interjection#4#h":"Різке припинення — скасувати і очистити","concepts.interjection#5#p":"Натисніть Escape (CLI), клацніть «Зупинка» (розширення, IDE) або введіть команду зупинки. Поточне виконання скасовується, чергові виклики інструментів відхиляються, а розмова готова до нового ходу.","concepts.interjection#6#c":"Спочатку спробуйте втрутитися. Різке припинення — для випадків, коли щось дійсно не так. Втручання зберігає нить розмови живою.","concepts.desktop-personas#title":"Персонажі робочого столу","concepts.desktop-personas#0#p":"Ця сторінка для допитливих та просунутих користувачів. «Автоматизація робочого столу» (іноді «використання комп'ютера») означає, що Ava може реально клікати по екрані та використовувати програми за вас — відкривати Gmail, заповнювати форми, надсилати повідомлення — як людина за клавіатурою. Щоб робити це безпечно, вона розподіляє завдання між п'ятьма маленькими помічниками, кожен з яких має одну вузьку роль. Ви ніколи не працюєте з ними напряму; це просто показує, хто що робить.","concepts.desktop-personas#1#p":"Кожен крок у траєкторії робочого столу (один запуск, де Ava веде ваш екран до мети) включає роботу п'яти персонажів. Кожен персонаж виконує лише одне завдання. Такий поділ забезпечує чіткі запити, структуровані результати та обережне мислення.","concepts.desktop-personas#2#h":"Розвідник","concepts.desktop-personas#3#p":"Повідомляє, що зараз видно на екрані. Ніколи не вигаджує елементи й не планує. Повертає стан екрана у форматі ScreenState JSON із ID елементів, назвами, координатами, рівнем впевненості та джерелом (UIA, Playwright DOM або OmniParser).","concepts.desktop-personas#4#h":"Планувальник","concepts.desktop-personas#5#p":"Вирішує єдину наступну дію. Одна дія на крок — ніколи не групами. Віддає перевагу оборотним шляхам. Класифікує ризики згідно з онтологією безпеки. Виводить ProposedAction JSON із типом, ціллю, параметрами, класом ризику, поясненням та прогнозом майбутнього стану.","concepts.desktop-personas#6#h":"Виконавець","concepts.desktop-personas#7#p":"Виконує рівно те, що запропонував Планувальник — після того, як пройдено перевірку схвалення. Без імпровізації. Без повторних спроб. Про невдачу повідомляється чесно, а Перевіряючий вирішує наступний хід.","concepts.desktop-personas#8#h":"Перевіряючий","concepts.desktop-personas#9#p":"Перевіряє, чи дія спрацювала. Порівнює свіжий стан екрана з прогнозом Планувальника. Повертає: підтверджено, відхилено або потрібен відкат. Також виявляє цикли — повторення дії, яка вже успішна, це відхилення, а не перевірка.","concepts.desktop-personas#10#h":"Оповідач","concepts.desktop-personas#11#p":"Єдиний голос, який чує користувач під час роботи. Одне речення в минулому часі на крок («Відкрито Gmail.», «Натиснуто «Написати».»). Також пише структурований журнал аудиту. Говорить, коли щось пішло не так — ніколи не ховає проблем.","concepts.desktop-safety#title":"Онтологія безпеки робочого столу","concepts.desktop-safety#0#p":"Коротко: перед тим як натиснути будь-що на екрані, Ava сортує дію за рівнем ризику. Читання екрана? Безпечно. Переказ грошей або видалення чогось? Вона завжди зупиняється і питає вас спочатку — кожного разу, без винятків. П'ять міток нижче — це сходинки цієї драбини ризиків. Це деталі для просунутих користувачів, але головне просте: небезпечне завжди потребує вашого «так».","concepts.desktop-safety#1#p":"Кожна запропонована дія класифікується в один із п'яти класів ризику. Класифікація поєднує три сигнали — що є ціллю на екрані, опис звичайною мовою («семантичний підпис» — власні слова Ava про те, на що вона дивиться) та налаштування дії — і підвищує рівень ризику, коли вони суперечать одне одному. Помилковий позитив (запит, коли не треба) — це просто турбота. Помилковий негатив (не запитувати, коли треба) — це інцидент, що загрожує існуванню продукту.","concepts.desktop-safety#2#h":"П'ять класів","concepts.desktop-safety#3#li0":"Спостереження — читати дерево UIA, скріншот, наведення курсора. Завжди автоматично дозволено.","concepts.desktop-safety#3#li1":"Навігація — прокрутка, зміна фокусу, відкриття меню. Автоматично дозволено в режимі Drive.","reference.cli#5#li3":"--project <path> — явно вказати корінь проекту.","reference.desktop-budget#title":"Обмеження бюджету на робочому столі","reference.desktop-budget#0#p":"Коли Ava контролює ваш робочий стіл від вашого імені — клацає, друкує, відкриває програми — кожен запуск називається «траєкторією». Ця сторінка пояснює межі безпеки, які не дають одному запуску тривати занадто довго або коштувати занадто дорого. Головне: вона завжди зупиняється і звітується перед тим, як перевищити ліміт. Числа тут, якщо вам потрібні деталі.","reference.desktop-budget#1#p":"Кожна траєкторія працює під трьома одночасними обмеженнями (жорсткими лімітами). Перше досягнуте обмеження є вирішальним. Траєкторія ніколи не продовжується мовчки після порушення — Оповідач (допоміжник, який пояснює, що відбувається) паузує і питає, що робити далі.","reference.desktop-budget#2#h":"Три жорсткі обмеження (за замовчуванням)","reference.desktop-budget#3#li0":"Кількість кроків — 30 кроків","reference.desktop-budget#3#li1":"Бюджет токенів — 500 000 токенів","reference.desktop-budget#3#li2":"Час у реальному масштабі — 5 хвилин","reference.desktop-budget#4#h":"Діапазони вартості завдань","reference.desktop-budget#5#li0":"Просте (пошук документації, відкриття сторінки) — 5–10 кроків, ~70–135K токенів, ~$0.04–0.08","reference.desktop-budget#5#li1":"Середнє (вхід у систему, перевірка журналів, завантаження результату) — 15–25 кроків, ~205–340K токенів, ~$0.12–0.21","reference.desktop-budget#5#li2":"Складне (сортування трьох проблем GitHub) — 25–30 кроків, ~340–410K токенів, ~$0.21–0.25","reference.desktop-budget#6#p":"Вказані вище цифри токенів — це технічні ліміти на одну траєкторію, а не ваш щомісячний дозвіл — він рахується в кредитах, і безкоштовний тариф із 300 на місяць комфортно покриває суміш чату, коду та кількох автоматизацій.","reference.desktop-budget#7#c":"Ви можете змінити обмеження для кожного завдання на початку, але порушення завжди виводять точку прийняття рішення. Бюджет ніколи не витрачається мовчки.","reference.desktop-whitelist#title":"Білий список сесій робочого столу","reference.desktop-whitelist#0#p":"«Білий список» — це просто перелік програм і вебсайтів, з якими Ava дозволено взаємодіяти, поки вона керує вашим робочим столом. Ця сторінка пояснює, як надати цей дозвіл і чому він скидається щоразу. Коротко: вона може діяти лише там, де ви їй дозволяєте, і запитує перед тим, як піти кудись нове.","reference.desktop-whitelist#1#p":"На початку сесії робочого столу Ava запитує, де вона має право діяти. Звичайна розмова: «Gmail, Cursor, портал Azure». Вона читає це і підтверджує відповідність вам («веб-версія Gmail, додаток Cursor, portal.azure.com»).","reference.desktop-whitelist#2#h":"Як це забезпечується","reference.desktop-whitelist#3#p":"Дії тільки для перегляду — знімок екрана, читання списку кнопок і полів на екрані (так званий «дерево UIA», власна карта Windows того, що знаходиться у вікні») — дозволені всюди, тому що вам потрібно бачити, що на екрані, щоб вирішити, чи додати програму до білого списку. Усе, що щось змінює, блокується поза списком; Ava паузує і питає, чи додати її.","reference.desktop-whitelist#4#h":"Обмежено сесією, навмисно","reference.desktop-whitelist#5#p":"Білий список НЕ зберігається між сесіями. Немає опції «запам'ятати цю програму». Кожен новий запуск починається з чистого поля. Незручно за задумом — забути повторно авторизувати — це функція, а не помилка.","reference.desktop-whitelist#6#h":"Додавання під час траєкторії","reference.desktop-whitelist#7#p":"Під час траєкторії ви можете додати програми з заголовка: «+ Дозволити програму» відкриває невелике поле вводу. Натисніть «Додати», і нова програма стане доступною до кінця сесії.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Хочете створити зображення, коротке відео, пісню або озвучений голос? Просто опишіть це, і Ava зробить це для вас — без необхідності використовувати програмне забезпечення для дизайну чи аудіо.","features.creative-studio#1#p":"Генерація зображень, відео, музики та голосу — усе вбудовано в один робочий процес разом із вашим кодом. Створюйте іконки, макети продуктів, демо-відео чи озвучення для навчальних матеріалів. Завдяки MiniMax.","features.creative-studio#2#h":"Що ви можете створити","features.creative-studio#3#li0":"Зображення — від запиту до PNG/JPG. Видалення фону в один клік.","features.creative-studio#3#li1":"Відео — короткі відео зі ШІ за текстовим запитом (MiniMax Hailuo).","features.creative-studio#3#li2":"Музика — інструментальні або вокальні треки з текстом пісні.","features.creative-studio#3#li3":"Голос — перетворення тексту на мовлення з можливістю вибору голосу.","features.creative-studio#4#p":"Вартість Creative Studio враховується з того самого пулу кредитів, що й решта сервісів — один пул, одна цифра. Підключіть свій ключ MiniMax через BYOK, і це буде безкоштовно для вашого тарифу.","features.creative-studio#5#c":"Creative Studio доступний у безкоштовному тарифі. Це не платна надстройка.","features.desktop-automation#title":"Автоматизація робочого столу","features.desktop-automation#0#p":"Простими словами: Ava може взяти під контроль мишу та клавіатуру, щоб виконувати завдання за вас — відкривати програми, натискати кнопки, заповнювати форми — поки ви стежите та схвалюєте важливе.","features.desktop-automation#1#p":"Новий режим для Ava, префікс @@. Вона спостерігає за робочим столом, вирішує, що робити, і керує автоматизацією інтерфейсу (контролює програми на вашому екрані замість вас), щоб завершити справу. Працює на вашій реальній машині з вашими реальними обліковими даними — не хмарний браузер. Доступно на всіх тарифах після релізу.","features.desktop-automation#2#h":"Чому ще один?","features.desktop-automation#3#p":"Кожен інший продукт для автоматизації робочого столу — це те, що ви запускаєте, коли сидите за столом. Ava — це та, яка залишається поруч, коли ваш трекер помилок спрацьовує о 2-й ночі — IDE продовжує працювати, телефон підключається через захищений канал, ви схвалюєте незворотні дії одним натисканням.","features.desktop-automation#4#p":"Вона також пам'ятає, як орієнтуватися у ваших програмах між сесіями. Кожен інший агент вчиться цьому заново щоразу. Перевага пам'яті зростає з використанням.","features.desktop-automation#5#h":"Як це працює","features.desktop-automation#6#p":"Кожен крок запускає хвилю з п'яти ролей: Розвідник спостерігає, Планувальник обирає наступну дію, Виконавець виконує, Перевірка перевіряє, Оповідач розповідає, що сталося. Sidecar обирає найдешевший надійний метод прив'язки — UIA для нативних програм, Playwright для браузерів, OmniParser для зору, коли нічого іншого не має корисного дерева.","features.desktop-automation#7#p":"Дивіться сторінки з концепціями щодо онтології безпеки, ієрархії прив'язки, аварійних перемикачів та моделі білого списку сесій."},"nl":{"start.for-non-coders#6#li3":"Als je wilt dat ze echt iets maakt of aanpast, vraag het haar gewoon. Ze laat je altijd zien wat ze van plan is te doen en wacht op jouw \"ja\".","start.for-non-coders#7#c":"Een woord tegenkomen dat je niet herkent? De woordenlijst in begrijpelijke taal (verderop in deze sectie) legt elke term uit, zonder dat er voorkennis vereist is.","start.install#title":"Installeren","start.install#0#p":"Kies de werkplek die bij je past. Je kunt er meerdere gebruiken — Ava synchroniseert haar geheugen overal waar je inlogt.","start.install#1#h":"VS Code-extensie","start.install#2#li0":"Open het Extensies-paneel in VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Zoek naar \"Ava Supernova\" en klik op Installeren.","start.install#2#li2":"Druk op Ctrl+Shift+A (Cmd+Shift+A op macOS) om het chatvenster te openen.","start.install#2#li3":"Volg de installatiewizard — kies een model, stel je toestemmingsmodus in, klaar.","start.install#3#h":"Desktop-IDE","start.install#4#li0":"Download de installatiebestanden voor je platform op de pagina met releases.","start.install#4#li1":"Start het programma. De IDE start de eerste keer op met een welkomstflow.","start.install#4#li2":"Log in voor gratis platform-tokens, of plak je eigen API-sleutel om volledig lokaal te draaien.","start.install#5#h":"CLI","start.install#6#li0":"`npm install -g @ava/cli` (of pnpm / yarn — jouw keuze).","start.install#6#li1":"Voer `ava` uit in elke projectmap.","start.install#6#li2":"Bij de eerste keer wordt je gevraagd om een provider en een model te kiezen. Kies en ga aan de slag.","start.install#7#c":"Geen account, geen probleem. Met je eigen API-sleutel (BYOK) hoef je nooit in te loggen. Het gratis niveau is voor de door het platform beheerde modellen.","start.for-non-coders#title":"Nooit code geschreven? Begin hier","start.for-non-coders#0#p":"Als je nog nooit een regel code hebt geschreven, ben jij precies de persoon waarvoor Ava bedoeld is. Je hoeft geen vaktermen te leren om te beginnen — je praat met haar in gewone taal, zoals je een vriend zou vragen. Deze pagina is je volledige opstap.","start.for-non-coders#1#h":"Wat je vandaag kunt doen, zonder ervaring","start.for-non-coders#2#li0":"Vraag haar alles, in normale woorden — \"wat doet dit bestand?\", \"waarom is mijn pagina leeg?\", \"wat is eigenlijk een database?\". Ze antwoordt in begrijpelijke taal en onthoudt het gesprek.","start.for-non-coders#2#li1":"Leer iets helemaal van voren af aan — zeg \"leer me Python van nul\" en ze maakt een echte cursus voor je met lessen en oefeningen. Dit is altijd gratis.","start.for-non-coders#2#li2":"Laat iets maken — beschrijf wat je wilt (\"een knop die mijn notities downloadt\") en ze schrijft het, waarbij ze elke wijziging aan je toont voordat deze plaatsvindt.","start.for-non-coders#3#h":"Je hoeft niet alles te begrijpen","start.for-non-coders#4#p":"Ava heeft veel techniek onder de motorkap — modi, modellen, specialisten, routing. Je zult die woorden tegenkomen in de app en in deze documentatie. Hier is het geheim: je kunt bijna alles negeren. Ava kiest automatisch de juiste tools en helpers voor je. De technische pagina's zijn er voor als je nieuwsgierig wordt, niet omdat je ze nodig hebt om te beginnen.","start.for-non-coders#5#h":"Een vriendelijk begin","start.for-non-coders#6#li0":"Installeer Ava (volgende pagina) en open de chat.","start.for-non-coders#6#li1":"Typ een echte vraag die je hebt. Alles. Kijk hoe ze antwoordt.","start.for-non-coders#6#li2":"Probeer leermodus: typ \"leer me\" en een onderwerp. Volg mee.","concepts.memory#title":"Geheugen — hoe Ava je onthoudt","concepts.memory#0#p":"In gewone taal: Ava onthoudt jou. Vertel haar iets één keer — wat je leuk vindt, een beslissing die je hebt genomen — en ze onthoudt het, zodat je het niet hoeft te herhalen in de volgende chat of volgende week. Dat is het hoofdpunt. De lagen hieronder leggen alleen uit hoe ze dat geheugen netjes houdt in de loop van de tijd.","concepts.desktop-grounding#title":"Desktop-grondingshiërarchie (Voorproefje)","concepts.desktop-grounding#0#c":"Voorproefje — hoe Scout beslist welke grondingsbron elke stap te gebruiken.","concepts.desktop-grounding#1#p":"Voordat Ava op een knop kan klikken, moet ze echt begrijpen wat er op je scherm staat en waar dingen zijn — dat is \"gronding\" (uitvogelen wat elk ding op het scherm is en de exacte plek). Ze heeft drie manieren om dit te doen en kiest de meest betrouwbare die werkt voor de app waarin je zit. Dit is gedetailleerde info voor gevorderden; het punt is gewoon dat ze liever stevige, nauwkeurige methoden gebruikt dan raden uit een foto.","concepts.desktop-grounding#2#p":"Drie niveaus, geëvalueerd in volgorde. De meest efficiënte betrouwbare bron wint.","concepts.desktop-grounding#3#h":"1. Browservenster → Playwright DOM","concepts.desktop-grounding#4#p":"Als het actieve venster een webbrowser is, leest Ava de structuur van de pagina zelf (de \"DOM\" — de onderliggende lijst van wat er op een pagina staat) in plaats van raden uit de foto. Het lezen van de structuur is ongeveer 10× betrouwbaarder dan pixels bekijken — ze weet precies waar elke knop is en wanneer de pagina klaar is met laden. Dit is het hoofdpad voor alles op het web, geen back-up.","concepts.desktop-grounding#5#h":"2. Native app met UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Voor gewone desktop-apps op Windows leest Ava een ingebouwde toegankelijkheidskaart (\"UIA\", dezelfde data die schermlezers gebruiken om een venster te beschrijven) — deze lijst bevat elke besturing, de naam en waar deze zich bevindt. Als die kaart ten minste vijf bruikbare, benoemde items teruggeeft, vertrouwt ze erop en gebruikt ze.","concepts.desktop-grounding#7#h":"3. UIA leeg of waardeloos → OmniParser visie","concepts.desktop-grounding#8#p":"Wanneer die kaart ontbreekt of nutteloos is (sommige apps, spellen en externe schermen bieden er geen), valt Ava terug op het daadwerkelijk kijken naar een schermfoto. Een visietool (OmniParser) signaleert de klikbare gebieden en labelt wat elk ervan is, waardoor de foto weer een lijst wordt waarop ze kan handelen — gecombineerd met wat weinig de toegankelijkheidskaart wel gaf.","concepts.desktop-grounding#9#c":"OmniParser is opt-in de eerste keer dat Ava het nodig heeft, met een duidelijk privacy-prompt. BYOK-gebruikers kunnen wijzen naar hun eigen lokale OmniParser-implementatie.","concepts.desktop-kill-switches#title":"Desktop-noodstops (Voorproefje)","concepts.desktop-kill-switches#0#c":"Voorproefje — drie onafhankelijke manieren om een lopende traject te annuleren. Elk daarvan wint.","concepts.desktop-kill-switches#1#p":"Een \"noodstop\" is precies wat het geluid doet — een noodweg om Ava direct te stoppen wanneer ze je scherm bestuurt. Het geruststellende deel: er zijn er drie, elk apart gebouwd, dus als één faalt werkt een andere nog steeds. Je hoeft niet alle drie te leren. Weet gewoon dat als iets verkeerd lijkt, je het altijd kunt stoppen, en de sterkste stop (de panieknoodstop hieronder) vertrouwt niet op samenwerking van Ava.","concepts.desktop-kill-switches#2#p":"Na het lezen van elk publiek autonomie-incident (echte gevallen waarin AI-agenten stopcommando's negeerden, e-mailarchieven verwijderden, schijven wisden), hebben we drie noodstops in drie verschillende lagen gebouwd. Geen van hen hangt af van het AI-model zelf — als Ava vastzit of niet reageert, kun je haar toch stoppen.","concepts.desktop-kill-switches#3#h":"Pauze — spatiebalk of de Pauze-knop","concepts.desktop-kill-switches#4#p":"Vorst vast op de grens van de volgende stap. Hervatbaar. Gebruik dit als je wilt ingrijpen zonder de richting te verliezen.","concepts.desktop-kill-switches#5#h":"Stop — Escape-toets of de Stop-knop","concepts.desktop-kill-switches#6#p":"Netjes stoppen. De verteller vat samen wat er tot nu toe is gedaan. Niet hervatbaar. Het auditlogboek wordt vastgelegd.","concepts.desktop-kill-switches#7#h":"Paniekstop — drie keer Escape of Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"De allerhardste stop die er bestaat. Een klein, apart wachthondprogramma sluit het deel van Ava dat je scherm bestuurt, geforceerd af. Het wacht niet op reactie van de AI, heeft geen werkend app-venster nodig en maakt zich niet druk om de staat van zaken — het schakelt het gewoon uit. Dit is de optie wanneer er echt iets mis is.","concepts.desktop-kill-switches#9#p":"Alle drie werken ook vanuit de bijbehorende app. Elke driver kan het beëindigen.","reference.tools#title":"Toolsreferentie","reference.tools#0#p":"Dit is het volledige naslagwerk van elke tool die Ava heeft — een 'tool' is simpelweg een specifieke actie die ze kan uitvoeren, zoals een bestand lezen of zoeken. Je hoeft deze pagina niet te lezen. Ava kiest zelf elke keer de juiste tool. Deze pagina is er voor als je nieuwsgierig bent naar precies wat ze kan doen.","reference.tools#1#p":"De volledige ingebouwde toolbox. Elke tool hier is geregistreerd in de kernruntime (de motor onder alle drie de oppervlakken) en beschikbaar voor Ava als de modus en machtigingsmodus het toestaan. Filter op categorie of risico.","reference.tools#2#p":"Je hoeft dit alles niet te onthouden — de tabel hieronder is slechts een naslagkaart.","reference.tools#4#h":"Risiconiveaus","reference.tools#5#li0":"Veilig — leest dingen zonder iets te wijzigen. file_read, glob (bestanden vinden op naam), grep (zoeken naar tekst in bestanden), git_status (Git is het systeem dat wijzigingen in je project bijhoudt).","reference.tools#5#li1":"Schrijven — wijzigt bestanden, slaat een controlepunt van je werk op (een \"commit\"), of produceert iets nieuws. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Gevaarlijk — voert opdrachten uit op je computer (de commandoregel), bestuurt het bureaublad, gaat naar internet, of vraagt databases op. bash, browser, desktop_*.","reference.tools#6#c":"Persona-specialisten hebben hun eigen lijst met toegestane tools. Scout kan lezen maar niet schrijven. Builder heeft volledige toegang. Challenger heeft helemaal geen tools — zijn taak is het plan ter discussie stellen.","reference.models#title":"Modellen","reference.models#0#p":"Een 'model' is de AI-hersenen die nadenkt — Qwen, DeepSeek, Mistral en anderen. Deze pagina somt alle modellen op die Ava kan gebruiken. De korte versie: je hoeft er geen te kiezen. Ava kiest zelf het juiste model voor elke stap. Lees verder alleen als je wilt begrijpen of dat kunt overschrijven.","reference.models#1#p":"Elk model waarnaar Ava kan route, plus de drie orkestreerstrategieën — de regels die beslissen welk model welk deel van een taak behandelt. Kies een routemodus en laat Ava het afhandelen, of kies een enkel model en sla routing volledig over.","reference.models#2#h":"Routeringsmodi","reference.models#3#p":"Drie georkestreerde strategieën. Dezelfde persona-pijplijn (het kleine team van hulpspecialisten dat Ava achter de schermen draait) draait op alle drie; wat verandert is de onderliggende vloot van modellen. Kies een modus in de modelselector en Ava regelt de rest. Elke kaart hieronder toont welke specialisten de dirigent aanstuurt.","reference.models#4#p":"Je hoeft de kaarten hieronder niet te onthouden — ze zijn er zodat je kunt zien waar elke strategie uit bestaat.","reference.models#6#c":"Aurora is bewust alleen Mistral. Als een Mistral-model niet beschikbaar is, geeft de router een foutmelding terug in plaats van door te sturen naar andere modellen — dat is de garantie van de EU-stack. Kies Maestro of Supernova voor een veilige fallback.","reference.models#7#c":"Alle drie de modi zijn overal beschikbaar — op platformtegoeden en op je eigen sleutels. BYOK voegt de optie toe om orkestreering te omzeilen en één model rechtstreeks te bedienen.","reference.models#8#h":"Door het platform beheerde modellen","reference.models#9#p":"Beschikbaar op elk abonnement, inclusief de gratis versie. Tokens (de eenheden waarin tekst wordt gemeten waar AI op gebaseerd is — ongeveer drie kwart van een woord per stuk) tellen mee tegen je abonnementslimiet. De sleutels (de privéwachtwoorden die elk betaald model ontgrendelen) worden door het platform gewisseld en bewaakt — je hoeft hier niets te configureren.","reference.config#title":"Configuratie","reference.config#0#p":"Deze pagina laat zien waar Ava haar instellingen en bestanden op je computer bewaart. Je hoeft bijna nooit iets met de hand aan te raken — de app regelt dit voor je. Het staat hier als je deze bestanden zelf wilt bekijken, back-uppen of delen.","reference.config#1#p":"Ava leest configuratie (haar opgeslagen instellingen) uit twee niveaus. Globale instellingen — die overal gelden — zitten in een map genaamd ~/.ava/ (de \"~\" is een afkorting voor je thuismap). Instellingen per project zitten in een .ava/ map binnenin het project zelf.","reference.config#2#h":"Globaal — ~/.ava/","reference.config#3#li0":"settings.json — modelvoorkeuren, toestemmingsmodus, persoonlijkheid, taal.","reference.config#3#li1":"memory/ — je globale geheugen (voorkeuren, beslissingen die overal gelden).","reference.config#3#li2":"tasks.json — projectoverstijgende takenlijst.","reference.config#3#li3":"journal/ — dagboekentries, datum-georganiseerd.","reference.config#4#h":"Project — .ava/","reference.config#5#li0":"instructions.md — projectspecifieke instructies die Ava altijd laadt. Blijvende context (\"we gebruiken pnpm, niet npm\", \"API-sleutels zitten in 1Password\").","reference.config#5#li1":"context.md — optionele vrije projectnotities.","reference.config#5#li2":"memory/ — geheugen dat beperkt is tot dit project.","reference.config#5#li3":"datasets/config.json — configuratie voor het opt-in vastleggen van datasets.","reference.config#6#c":"Voeg .ava/ toe aan je .gitignore (een lijst met bestanden die Git buiten het gedeelde project houdt) als je geen geheugen met je team wilt delen. Houd instructions.md in de repo (de gedeelde projectmap) — zo leert Ava de projectconventies.","reference.shortcuts#title":"Toetsenbord sneltoetsen","reference.shortcuts#0#p":"Sneltoetsen zijn optionele versnellingen — elke is ook een knop die je kunt klikken. Kijk alleen hier als je Ava sneller vanaf het toetsenbord wilt besturen.","reference.shortcuts#1#p":"Sneltoetsen per omgeving (elk van de drie plekken waar Ava draait: de VS Code-extensie, de desktop-app en de terminal). Pas ze aan in de instellingen van elke omgeving. Geen behoefte om de onderstaande lijst te onthouden.","reference.models#11#h":"Je eigen sleutel gebruiken","reference.models#12#p":"Een \"API-sleutel\" is een privé-wachtwoord dat software toelaat een betaalde dienst op je eigen account te gebruiken. \"BYOK\" betekent simpelweg \"je eigen sleutel meenemen\" — je gebruikt die in plaats van de onze. Plak je API-sleutel in de instellingen. BYOK-verzoeken gaan direct van Ava naar de provider (het bedrijf dat het model runt) — ze passeren niet onze infrastructuur en verbruiken geen platform-tokens. Je betaalt de provider; wij zien het verkeer niet.","reference.models#14#c":"Voor benchmarkscores, capaciteitsetiketten en filteren naast elkaar zie je de volledige Modellenpagina op ava-supernova.com/models. De hierboven getoonde prijzen zijn onze beste inschatting van het prijskaartje van elke aanbieder bij publicatie — controleer altijd de website van de aanbieder voordat je een taak start.","reference.personas#title":"Orkestratie van persona's","reference.personas#0#p":"Een \"persona\" is een hulprool die Ava achter de schermen speelt voor moeilijkere taken — een onderzoeker, een planner, een feitenchecker. Je praat nooit rechtstreeks met hen en je hoeft deze pagina niet te begrijpen om Ava te gebruiken. Het staat hier als je benieuwd bent hoe ze een grote taak opsplits in een klein team van experts.","reference.personas#1#p":"24 specialisten verdeeld over 5 modeteams. De Dirigent (de hulp die de rest coördineert) beslist welk team aan de slag gaat, in welke volgorde, en met welke context. Chat-modus heeft geen persona's — het is Ava zelf.","reference.personas#2#h":"Hoe orkestratie werkt","reference.personas#3#li0":"Je stuurt een bericht in Plan-, Teach-, Security- of Brainstormmodus (of een complexe werkaanvraag).","reference.personas#3#li1":"De Dirigent leest het verzoek, kiest het modeteam en maakt een uitvoeringsplan — sommige persona's draaien sequentieel, anderen in parallelle golven.","reference.personas#3#li2":"Elke persona heeft zijn eigen systeemprompt, een beperkte lijst van toegestane tools, en een gedeeld contextpool van wat eerdere persona's hebben gevonden.","reference.personas#3#li3":"De laatste persona maakt een samenvatting, een plan of een rapport, afhankelijk van de modus.","reference.personas#3#li4":"Ava presenteert het resultaat aan jou. Jij keurt goed, past aan of stuurt om.","reference.personas#4#p":"Het volledige overzicht hieronder is alleen ter referentie — geen behoefte om te onthouden wie wat doet. Ava stelt het juiste team voor je samen.","reference.personas#6#c":"Work-modus roept alleen het volledige team op voor complexe taken. Simpele bewerkingen draait Ava direct — geen orkestratie-overhead.","reference.project-context#title":"Projectcontext","reference.project-context#0#p":"Hier leg ik uit hoe Ava zich eerst verdiept in je project voordat ze begint — de bestanden die ze bekijkt om te begrijpen waar je mee bezig bent. Je hoeft hier niets voor in te stellen; ze doet het zelf. Lees dit als je wilt weten waar je een notitie kunt plaatsen zodat ze deze altijd ziet.","reference.project-context#1#p":"Wanneer je een project opent, laadt Ava verschillende lagen context (achtergrondinformatie die ze bij zich houdt). Begrijpen wat deze lagen zijn, helpt je om informatie op de juiste plek te zetten.","reference.project-context#2#h":"Automatisch geladen","reference.project-context#3#li0":".ava/instructions.md — wordt behandeld als duurzame, hoogprioritaire instructies. Altijd in de context.","reference.project-context#3#li1":".ava/context.md — vrije notities. Wordt geladen, lagere prioriteit.","reference.project-context#3#li2":"README.md — wordt bij de eerste keer gescand voor een samenvatting van het project.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — de kleine bestanden die een projectopzet beschrijven; worden gelezen om de taal, het framework en de testopdracht te detecteren.","reference.project-context#3#li4":".gitignore — de lijst met bestanden die niet in versiebeheer moeten komen; wordt door alle bestandsprogramma’s gerespecteerd (glob, grep, project_index).","reference.project-context#4#h":"Op verzoek geladen","reference.project-context#5#p":"“Op verzoek” betekent dat Ava deze alleen ophaalt wanneer een taak ze echt nodig heeft, en niet van tevoren.","reference.project-context#6#li0":"Project index — een gestructureerde kaart van je bestanden en de benoemde onderdelen erin (functies, klassen — “symbolen”) en hoe ze met elkaar verbonden zijn (“imports”). Wordt pas gebouwd wanneer Ava het nodig heeft.","reference.project-context#6#li1":"Git geschiedenis — het overzicht van eerdere wijzigingen; wordt opgehaald wanneer git_status, git_diff of git_create_pr worden aangeroepen (Git is het hulpmiddel dat elke wijziging aan een project bijhoudt; “PR” is een samenvoegverzoek, een voorgestelde bundel wijzigingen).","reference.project-context#6#li2":"Geheugen — items worden op betekenis afgestemd (“semantisch”) en één voor één toegevoegd, niet in één keer.","reference.project-context#7#c":"Zet conventies in instructions.md. Zet notities in context.md. Laat het geheugen de rest maar vastleggen.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Een rapport, e-mail of document nodig? Ava kan het concept opstellen en je een echt Word-, Excel- of PDF-bestand geven dat je kunt openen en bewerken zoals elk ander bestand.","features.office-suite#1#p":"Rapporten, e-mails en documenten — opgesteld, opgemaakt en geëxporteerd naar native formaten (.docx is Word, .xlsx is Excel, .pdf is een PDF).","features.office-suite#2#li0":"report_generate — een gestructureerd .docx dat ophaalt uit taken, dagboek, geheugen en projectstatus.","features.office-suite#2#li1":"email_draft — e-mail met tooncontrole naar een .docx-bestand.","features.office-suite#2#li2":"document_manage — maken, lezen, bewerken, exporteren over Word, Excel, PDF, CSV, Markdown heen.","features.office-suite#3#p":"Handig wanneer Ava namens jou schrijft — statusrapporten, kickoff-presentaties, klantupdates. De .docx belandt in je project waar je het kunt polijsten.","features.dashboard-library#title":"Dashboardbibliotheek","features.dashboard-library#0#p":"In gewone taal: één plank waarop alles staat wat jij en Ava hebben gemaakt en besproken, zodat niets verloren gaat.","features.dashboard-library#1#p":"Een bladerweergave van alles wat Ava samen met jou heeft geproduceerd — gegenereerde afbeeldingen, video's, audio, documenten — naast je gesprekken, herinneringen en taken. Één plek om iets te vinden wat je vorige week hebt gemaakt.","features.document-preview#title":"Documentvoorbeeld","features.document-preview#0#p":"In gewone taal: even kijken in een document precies daar waar je bent, zonder een apart programma te openen om het te lezen.","features.document-preview#1#p":"Klik met de rechtermuisknop op een Word-doc, Excel-sheet, PDF, CSV, HTML- of Markdown-bestand in je project — bekijk het direct in het venster zonder de editor te verlaten. Handig voor het lezen van referentiemateriaal dat Ava heeft gegenereerd of bestanden die een collega erin heeft geplaatst.","features.daily-briefing#title":"Dagelijkse briefing","features.daily-briefing#0#p":"In gewone taal: een kort \"hier ben je gestopt\"-notitie elke ochtend, zodat je kunt doorgaan zonder alles opnieuw te lezen.","features.daily-briefing#1#p":"Ochtendsamenvatting: gisteren dagboek, open taken, projectstatus en alle herinneringen die Ava heeft ingesteld. Optioneel — zet dit aan in de instellingen.","features.daily-briefing#2#p":"De briefing gebruikt geheugen om relevante context te tonen (\"de laatste keer dat je werkte aan de auth-flow, merkte je op dat je de refresh-token-strategie wilde herzien\"). Geen nieuwsfeed — een gefocuste update.","features.unified-panel#title":"Geïntegreerd paneel","features.unified-panel#0#p":"In gewone taal: alles wat Ava doet, leeft in één venster, dus je hoeft nooit door tabbladen te zoeken om het te vinden.","features.unified-panel#1#p":"Eén paneel voor chat, dashboard, geheugen, taken en dagboek. Geen wisselen van context tussen vensters. De zijbalk kiest wat je bekijkt; het hoofdgebied wisselt mee.","features.unified-panel#2#p":"De status van het gesprek blijft bewaard als je weg navigeert — open geheugen, controleer een taak, en kom dan terug. De chat is er nog steeds, blijft streamen als Ava nog draait.","features.unified-panel#3#c":"Geïntegreerd paneel is een extensie- en IDE-concept. Het weboppervlak gebruikt browsertabbladen.","features.knowledge-packs#title":"Kennispakketten","features.knowledge-packs#0#p":"In gewone taal: geef Ava een map met je eigen documenten, en ze kan eruit lezen om je vragen te beantwoorden. Een \"kennispakket\" is gewoon die bundel bestanden — je naslagmateriaal waar ze op mag terugvallen.","features.knowledge-packs#1#p":"Sleep een map met naslagmateriaal (specificaties, RFC's, vergadernotities, API-documentatie) naar een kennispakket. Ava kan de relevante stukken meenemen in de context wanneer een gesprek het onderwerp raakt.","features.knowledge-packs#2#p":"Pakketten worden lokaal geïndexeerd. Opzoeken is semantisch — Ava vindt het juiste document op basis van betekenis, niet bestandsnaam. (\"Semantisch\" betekent dat ze matcht op waar een document over gaat, zodat je de exacte woorden of bestandsnaam niet hoeft te onthouden.) Pakketten kunnen met een team worden gedeeld of privé blijven.","features.workflows#title":"Werkstromen","features.workflows#0#p":"In gewone taal: leer Ava een routine aan die je steeds herhaalt, geef het een naam, en ze kan het hele proces opnieuw uitvoeren op verzoek. Een 'workflow' is gewoon die opgeslagen routine — een reeks stappen die Ava voor jou herhaalt.","features.workflows#1#p":"Sla een reeks stappen op die je vaak herhaalt — pull request review → testen uitvoeren → release-notes schrijven → e-mail opstellen. Een workflow is een herbruikbaar plan dat Ava met verschillende invoer kan afspelen.","features.workflows#2#p":"Werkstromen worden per project opgeslagen in een map genaamd .ava/workflows/ binnen je project. Deel ze met je team door de map te committen (opslaan in je gedeelde project zodat collega's deze ook krijgen).","features.events#title":"Gebeurtenissen en meldingen","features.events#0#p":"In gewone taal: terwijl Ava werkt krijg je een overzichtelijke stap-voor-stap lijst van wat ze doet, en een seintje als een lange taak klaar is zodat je even weg kunt.","features.events#1#p":"Terwijl Ava draait zie je gestructureerde updates, geen muur van tekst. Elke toolaanroep, elke overdracht tussen persona's, elke gestreamde delta is een discrete gebeurtenis in de interface — uitklapbaar voor details, inklapbaar voor overzicht.","features.events#2#p":"Achtergrondtaken sturen meldingen op systeemniveau wanneer ze voltooid zijn. Je kunt weglopen bij een lange build en Ava vertelt je wanneer het klaar is.","features.personality#title":"Persoonlijkheidsontwerper","features.personality#0#p":"In gewone taal: stel in hoe Ava tegen je praat — gezellig of beknopt, formeel of informeel, meer of minder grappen — zodat ze klinkt zoals jij wilt.","features.personality#1#p":"Bepaal hoe Ava tegen je praat. Toon, energie, woordkeuze (hoeveel ze zegt), formaliteit, humor. Schuifregelaars en voorinstellingen — bondige ingenieur, warme mentor, droge collega, of je eigen mix.","features.personality#2#p":"Persoonlijkheid beïnvloedt de formulering, niet de vaardigheid. Ze gebruikt nog steeds dezelfde tools en volgt dezelfde toegangsregels. Haar naam is vergrendeld op Ava — dat is niet onderhandelbaar.","features.release-notes#title":"Release-notes","features.release-notes#0#p":"In gewone taal: een lopende lijst van wat er nieuw is en wat er is gerepareerd in elke update, zodat je ziet wat er veranderd is.","features.release-notes#1#p":"Changelog in de app (een changelog is de geschiedenis van wijzigingen). Elke uitgebrachte versie met hoogtepunten, bugfixes en brekende wijzigingen (wijzigingen die kunnen vereisen dat je aanpast hoe je iets gebruikt). Het weboppervlak onderhoudt de publieke versie op ava-supernova.com/releases.","troubleshooting.logs#4#c":"Logs kunnen fragmenten van de projectbestanden bevatten die Ava heeft gelezen tijdens een sessie. Controleer dit voordat je ze deelt.","troubleshooting.support-request#title":"Een ondersteuningsverzoek indienen","troubleshooting.support-request#0#p":"In gewone taal: als er iets mis is en de bovenstaande oplossingen niet hebben geholpen, stuur ons dan een bericht. De makkelijkste manier is om gewoon Ava te vragen dit voor je te doen.","troubleshooting.support-request#1#p":"Als een probleem niet wordt gedekt door veelvoorkomende fouten, dien dan een ondersteuningsticket in (stuur het supportteam een verzoek om hulp). Je kunt dit doen binnen Ava (geen formulier om in te vullen) of op het web.","troubleshooting.support-request#2#h":"Vanuit Ava","troubleshooting.support-request#3#p":"Vraag haar om dit te doen. \"Ava, kun jij hierover een ondersteuningsticket indienen?\" Ze roept support_request aan, hecht de relevante sessiecontext (met verwijderde inloggegevens) en stuurt het. Snelste weg.","troubleshooting.support-request#4#h":"Via het web","troubleshooting.support-request#5#p":"Bezoek ava-supernova.com/support. Kies een categorie (bug, feature, account, security, general) en beschrijf wat er gebeurd is. Antwoord binnen één werkdag.","troubleshooting.support-request#6#h":"Wat u moet opnemen","troubleshooting.support-request#7#li0":"Wat u probeerde te doen.","troubleshooting.support-request#7#li1":"Wat er daadwerkelijk gebeurde.","troubleshooting.support-request#7#li2":"Welke omgeving (extensie, IDE, CLI, begeleidend programma) en welke versie.","troubleshooting.support-request#7#li3":"Eventuele foutmeldingen of logfragmenten. Verwijder eerst inloggegevens.","troubleshooting.security-disclosure#title":"Veiligheidsproblemen melden","troubleshooting.security-disclosure#0#p":"In gewone taal: als je hebt ontdekt hoe Ava gehackt of misbruikt kan worden (een \"kwetsbaarheid\" — een beveiligingszwakke plek), vertel ons dit dan eerst privé zodat we het kunnen oplossen voordat iemand er misbruik van maakt. Dit is hoe.","troubleshooting.security-disclosure#1#p":"Kwetsbaarheid gevonden? Bedankt. We nemen elk rapport serieus en werken met je samen aan de oplossing voordat er openbaarmaking plaatsvindt (voordat het probleem publiek bekend wordt gemaakt).","troubleshooting.security-disclosure#2#h":"Hoe te melden","troubleshooting.security-disclosure#3#li0":"Stuur een e-mail naar security@ava-supernova.com met een beschrijving, stappen om het na te bootsen, en uw voorkeur voor openbaarmaking.","troubleshooting.security-disclosure#3#li1":"Of dien een ondersteuningsticket in met categorie \"security\" — dezelfde wachtrij.","troubleshooting.security-disclosure#3#li2":"Wij bevestigen binnen 24 uur.","troubleshooting.security-disclosure#4#h":"Onze toezeggingen","troubleshooting.security-disclosure#5#li0":"Gecoördineerde openbaarmaking — we stemmen een tijdslijn met u af voordat iets publiek wordt. Standaard is 90 dagen.","troubleshooting.security-disclosure#5#li1":"Naamvermelding — u krijgt credit in de opmerkingen bij de oplossing, tenzij u anonimiteit prefereert.","troubleshooting.security-disclosure#5#li2":"Geen juridische represailles — onderzoek in goede trouw is welkom. Wij zullen geen advocaten achter je aan sturen.","troubleshooting.security-disclosure#6#c":"De beveiligingspagina op ava-supernova.com/security bevat de volledige beveiligingspositie — architectuurgaranties, redactor, toegangshekken.","troubleshooting.common-errors#title":"Veelvoorkomende fouten","troubleshooting.common-errors#0#p":"De meeste fouten hebben een korte, specifieke oorzaak. Hier zijn de meest voorkomende en hoe je ze oplost. Maak je geen zorgen als de tekst technisch klinkt — elk punt hieronder vertelt je wat je precies ziet en wat je moet doen.","troubleshooting.common-errors#1#h":"Model reageert niet","troubleshooting.common-errors#2#p":"Wat je ziet: Ava wordt stil en reageert niet.","troubleshooting.common-errors#3#p":"Controleer de statusindicator in de chatkop. Als er \"connecting\" staat, is je provider (de AI-service waar Ava mee praat) bereikbaar maar traag — geef het dertig seconden. Als er \"unavailable\" staat, is Ava automatisch teruggevallen op het volgende model in de keten (ze heeft automatisch geschakeld naar een back-upmodel). Staat er helemaal niets? Controleer dan je API-sleutel in Instellingen en test de verbinding. (Een API-sleutel is het privé-wachtwoord waarmee Ava een betaalde AI-service kan gebruiken.)","troubleshooting.common-errors#4#h":"Toolaanroep mislukt","troubleshooting.common-errors#5#p":"Wat je ziet: één van Ava's stappen (een \"toolaanroep\" — zoals het lezen van een bestand, het uitvoeren van een opdracht, enzovoort) geeft een rode fout weer in plaats van afgerond te worden.","troubleshooting.common-errors#6#p":"Klik op de mislukte toolaanroep om de fout te zien. Veelvoorkomende oorzaken: ze probeerde een bestand buiten je projectmap aan te raken, wat expres geblokkeerd is voor je veiligheid (deze beveiliging heet \"path traversal\"-bescherming — het voorkomt dat ze dwalend buiten de map komt waarin je werkt); een opdracht die in een andere map moet draaien; of een bestand dat verplaatst is sinds Ava er voor het laatst naar keek. Vertel haar wat er misging — ze zal het opnieuw proberen met correcties.","troubleshooting.common-errors#7#h":"Geheugen onthoudt niet","troubleshooting.common-errors#8#p":"Wat je ziet: Ava kan iets niet vinden waarvan je zeker weet dat ze het zou moeten onthouden.","troubleshooting.common-errors#9#p":"Geheugen werkt op basis van betekenis, niet op exacte woorden (dit is wat \"semantic\" betekent). Dus \"Wat heb ik besloten over auth?\" werkt beter dan \"vind mijn auth-besluit\". Als het geheugen er zeker wel is, maar niet tevoorschijn komt, open je de geheugenbrowser en zoek je — als het er niet staat, is het nooit opgeslagen.","troubleshooting.common-errors#10#h":"Inlog-lussen","troubleshooting.common-errors#11#p":"Wat je ziet: je logt in, maar Ava blijft vragen om opnieuw in te loggen — een lus die je nooit doorlaat.","troubleshooting.common-errors#12#p":"De oplossing is de opgeslagen inloggegevens wissen en opnieuw beginnen: in de extensie voer je \"Ava: Sign Out\" uit via het commandopalet, in de IDE ga je naar Instellingen → Account → Sign Out, in de CLI verwijder je het bestand op ~/.ava/auth.json (een klein inlogbestand in een map genaamd .ava in je thuisdirectory). Log daarna opnieuw in.","troubleshooting.common-errors#13#h":"Tokens uitgeput","troubleshooting.common-errors#14#p":"Wat je ziet: een bericht dat je de gratis gebruikslimiet voor deze maand hebt overschreden. (\"Tokens\" zijn de maatstaf voor AI-gebruik — \"uitgeput\" betekent gewoon dat je je gratis tegoed voor deze maand hebt opgebruikt.)","troubleshooting.common-errors#15#p":"Het maandbudget voor de gratis versie reset elke 1e van de maand. Tot die tijd schakel je over naar een BYOK-provider (gebruik je eigen API-sleutel) om door te kunnen werken. Je account blijft actief — alleen de gratis, door het platform beheerde aanvragen zijn gepauzeerd.","troubleshooting.logs#title":"Waar logs staan","troubleshooting.logs#0#p":"Een \"log\" is simpelweg een dagboek dat je computer bijhoudt van wat er gebeurd is — handig als er iets kapotgaat en jij (of ondersteuning) de details nodig hebt.","troubleshooting.logs#1#p":"Als je het ruwe plaatje nodig hebt — welke toolaanroep werd uitgevoerd, welke informatie hij kreeg, wat de AI-service terugstuurde — dan zijn de logs platte tekstbestanden in een map op je computer op ~/.ava/logs/ (een map genaamd .ava in je thuisdirectory, met daarin een logs-map).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — transcripten per sessie inclusief toolaanroepen, gestreamde antwoorden en fouten.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — logboek van de VS Code-extensiehost. Activeringsfouten, paneelfouten.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — desktop IDE-logboek. Berichten van het Sidecar-proces, Rust panics.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — CLI REPL-logboek.","troubleshooting.logs#3#p":"In de extensie opent \"Ava: Show Logs\" in het commandopalet de relevante log in een bewerkingsvenster. In de IDE heeft Instellingen → Diagnose een knop \"Open Logs\". De CLI kan zijn eigen log volgen met ava logs --follow.","concepts.memory#1#p":"Ava heeft een persistent geheugen (\"persistent\" betekent dat het blijft hangen nadat je de app sluit) dat overleeft tussen gesprekken, projecten en machines als je synchronisatie inschakelt (synchronisatie kopieert je geheugen tussen je apparaten). Het is geen chatlog. Het is een gestructureerd, doorzoekbaar begrip van wie je bent, wat je leuk vindt en wat je hebt besloten.","concepts.memory#2#h":"Vijf lagen","concepts.memory#3#li0":"Extraheren — belangrijke feiten die in realtime uit elke bericht worden vastgelegd.","concepts.memory#3#li1":"Reflecteren — diepere analyse wordt uitgevoerd aan het einde van betekenisvolle sessies. Patronen, thema's, tegenstrijdigheden.","concepts.memory#3#li2":"Accumuleren — correcties en voorkeuren stapelen zich op over weken en maanden.","concepts.memory#3#li3":"Analyseren — de kennisgraaf koppelt gerelateerde herinneringen en markeert tegenstrijdigheden wanneer nieuwe informatie botst met oude.","concepts.memory#3#li4":"Samenvoegen — gelijke herinneringen samengevoegd; verouderde verwijderd. Geheugen wordt scherper na verloop van tijd, niet rommeliger.","concepts.memory#4#c":"De vijf lagen hierboven draaien op zichzelf — je hoeft ze nooit te beheren. Ze zijn er zodat je kunt zien dat het geheugen echt verbetert in de loop van de tijd, in plaats van dat het verandert in een hoop rommel.","concepts.memory#5#h":"Opvragen","concepts.memory#6#p":"Wanneer je een vraag stelt, zoekt Ava in het geheugen op betekenis (\"semantisch zoeken\" — het begrijpt wat je bedoelt, dus het vindt de juiste herinnering zelfs als je het anders formuleert), niet alleen door exacte woorden te matchen. Modus-specifieke filters lopen mee — Chat-modus haalt persoonlijke context op, Werk-modus haalt projectbeslissingen en codepatronen op.","concepts.memory#7#c":"Geheugen is beperkt tot gebruiker en project (je herinneringen zijn van jou, gescheiden per persoon en project). Geheimen en inloggegevens (wachtwoorden, sleutels) worden geblokkeerd bij het opslaan — ze kunnen nooit in het geheugen terechtkomen.","start.first-five#5#li0":"Een vraag — \"waarom is mijn pagina leeg?\", \"wat doet dit bestand?\"","start.first-five#5#li1":"Iets gebouwd — \"maak voor mij een simpele takenlijst-pagina\".","start.first-five#5#li2":"Om iets te leren — \"leer me Python vanaf nul\". (Altijd gratis.)","start.first-five#5#li3":"Een document — \"schrijf voor mij een projectvoorstel van één pagina\". Ze geeft je dan een Word-bestand of PDF.","start.first-five#6#c":"Twijfel je wat je moet typen? Praat met haar alsof het een vriendin is die veel weet. Gewone woorden zijn precies goed — je hebt nooit technische termen nodig om te beginnen.","start.first-five#deeper#0#p":"Die simpele lus regelt er achter de schermen aardig wat. Je hebt dit niet nodig om Ava te gebruiken — maar hier is wat er eigenlijk gebeurt als je nieuwsgierig bent.","start.first-five#deeper#1#h":"Hulpmiddelen en goedkeuring","start.first-five#deeper#2#p":"Wanneer Ava een bestand leest, een opdracht uitvoert of code bewerkt, is elk daarvan een \"gereedschapsaanroep\". Ze vraagt toestemming voordat ze iets aanraakt dat je bestanden of systeem betreft — hoe vaak ze vraagt hangt af van je toestemmingsmodus (vragen bij elke keer, alleen bij risicovolle acties, of gewoon gaan).","start.first-five#deeper#3#h":"Modussen — haar denkstanden","start.first-five#deeper#4#p":"Ava werkt in modussen: een instelling plus de juiste gereedschapskist voor de klus. Wissel op elk moment via de kiezer, of typ een voorvoegsel aan het begin van je bericht. Er zijn er zeven.","start.first-five#deeper#6#h":"Specialisten en routebeheer","start.first-five#deeper#7#p":"Bij lastiger taken zet Ava een klein team van gespecialiseerde helpers achter de schermen in (een planner, een controleur, een bouwer) en stuurt ze elke stap naar het model dat daar het beste in is. Je hoeft dit nooit zelf te regelen — zij coördineert het voor je.","start.local-vs-cloud#title":"Lokaal versus cloud, in één alinea","start.local-vs-cloud#0#p":"Alles wat Ava doet, is lokaal tenzij je dit expliciet inschakelt. Geheugen, taken, dagboek, persoonlijkheid, instellingen — allemaal opgeslagen op je computer in ~/.ava/ en .ava/ (per project). Ze praat met modelaanbieders via HTTPS om je verzoek uit te voeren, en keert daarna terug. Ze belt niet naar buiten. Ze verzamelt geen gegevens. Ze traint niet op je code.","start.local-vs-cloud#1#p":"Als je inlogt, krijg je 300 gratis kredietpunten per maand voor modellen beheerd door het platform (Qwen, MiniMax) en optionele cloudsynchronisatie voor geheugen en instellingen over apparaten heen. Synchronisatie is per functie, altijd herroepbaar. Gebruik je eigen API-sleutel en Ava werkt volledig zonder account.","start.local-vs-cloud#2#c":"De regel: lokaal is heilig. Cloud is aanvullend.","start.first-model#title":"Moet ik een AI kiezen?","start.first-model#0#p":"Wat een opluchting: jij kiest de AI niet. Ava kiest automatisch de juiste voor elke stap, zodat je goede resultaten krijgt zonder erover na te hoeven denken.","start.first-model#1#p":"Het enige wat je kunt kiezen, is een routestijl — en de standaard past bijna iedereen. Je hebt de anderen alleen nodig om een specifieke reden.","start.first-model#2#h":"De drie stijlen","start.first-model#3#li0":"Maestro — de standaard. Stabiel, betrouwbaar, voorspelbaar. Twijfel je? Dit is de juiste.","start.first-model#3#li1":"Supernova — voor zware, meerstaps-werkzaamheden, waar het loont om een andere specialist op elk deel van de taak te zetten.","start.first-model#3#li2":"Aurora — wanneer je gegevens in de EU moeten blijven (publieke sector, zorg, strikte privacy). Draait volledig op Europese AI met open gewichten.","start.first-model#4#p":"Wissel op elk moment via de modelkiezer bovenaan de chat. Niets is vastgelegd.","start.first-model#5#c":"Wil je zelf een specifiek model aansturen? Dat kan — open \"Laat me de details zien\".","start.what#title":"Wat is Ava?","start.what#0#p":"Ava is een AI die echt dingen doet – niet alleen maar praat. Ze bouwt voor je een app, schrijft een document, leert je iets van nul af aan, ontwerpt een logo, of zorgt voor de administratie die je steeds uitstelt. En ze onthoudt jou: waar je mee bezig bent, hoe je dingen wilt, wat je vorige week vroeg.","start.what#1#p":"Er is één Ava, en ze werkt waar jij ook werkt – in je code-editor, als desktop-app, op je telefoon, of in een terminal. Dezelfde geheugen, dezelfde persoonlijkheid, overal.","start.what#2#h":"Wat maakt haar anders","start.what#3#li0":"Standaard van jou. Jouw werk blijft op jouw eigen machine. Geen tracking, geen telemetrie – nooit.","start.what#3#li1":"Open voor iedereen om te zien. Elke regel van Ava is publiek. Niets om blindelings te vertrouwen.","start.what#3#li2":"Gratis om mee te beginnen. 300 credits elke maand, geen kaart, geen addertje onder het gras – of sluit je eigen AI-sleutels aan en betaal ons helemaal niets.","start.what#3#li3":"Leren is gratis, voor altijd. Leren zou geen prijskaartje moeten hebben.","start.what#4#p":"Nooit code geschreven? De volgende pagina is speciaal voor jou geschreven. Al technisch? Sla gerust over – ze kan meekomen.","start.what#deeper#0#h":"Where Ava lives","start.what#deeper#1#li0":"VS Code extension — Ava next to your editor: a chat panel, a dashboard, and changes shown inline before they happen.","start.what#deeper#1#li1":"Desktop IDE — a standalone app with the whole thing in one window. Adds desktop control (opening apps, clicking, typing for you).","start.what#deeper#1#li2":"Companion — a mobile app for when you're away from your desk: tasks, journal, memory, quick chats.","start.what#deeper#1#li3":"CLI — Ava in your terminal, for people who live there.","start.what#deeper#2#h":"How she works, in brief","start.what#deeper#3#p":"Ava switches mindsets (called modes) to match the job, quietly runs a small team of specialist helpers on harder work, and picks the best AI model for each step automatically. You never manage any of it. The Core concepts section has the full tour whenever you're curious.","start.first-five#title":"Je eerste keer met Ava","start.first-five#0#p":"De snelste manier om Ava aan het werk te zetten is haar om iets concreets vragen en kijken hoe ze het doet. Geen handleiding lezen, niets eerst leren – vertel haar gewoon wat je wilt, in gewone woorden.","start.first-five#1#h":"Probeer dit nu","start.first-five#2#li0":"Open de chat.","start.first-five#2#li1":"Typ iets dat je echt wilt. Probeer \"leg uit wat dit project doet\", of \"voeg een knop toe die het formulier leegt\".","start.first-five#2#li2":"Ava laat je zien wat ze gaat doen – en wacht.","start.first-five#2#li3":"Blij met het plan? Zeg ja. Kijk hoe ze het doet.","start.first-five#3#p":"Dat is het hele ritme: jij vraagt, zij toont het plan, jij keurt goed, zij doet het. Ze verandert nooit iets zonder het eerst te tonen – dus je kunt niets kapotmaken door het te proberen.","start.first-five#4#h":"Een paar dingen die het waard zijn om te vragen","models.routing#deeper#1#h":"Naast elkaar","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Coördinator","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B actief, 1M context)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B actief, 262K context)","models.routing#deeper#2#td1.0":"Bouwer","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (maakt gebruik van coördinator)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B volledig, 256K context)","models.routing#deeper#2#td2.0":"Specialisten op middenniveau","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (code-reviewer, feitenchecker, verkenner, scanner, beveiligingsverificator, enz.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Architect, Verificator, Volgordebepaler, Gids, Verslaggever, enz.)","models.routing#deeper#2#td3.0":"Licht niveau / intentiepoort","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Verkenner, Verificator, Volgordebepaler, Uitdager, Integreerder)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Expert-specialisten","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Onderzoeker, Uitdager, CVE-onderzoeker, Bedenker, Feitenchecker)","start.first-model#deeper#0#h":"Wat zit er precies in elke stijl?","start.first-model#deeper#1#p":"Maestro — één dirigent (Qwen 3.6 Plus) regelt elke stap. Productie-geoptimaliseerd, bewezen, voorspelbare kosten.","start.first-model#deeper#2#p":"Supernova — een grensverleggende coördinator (DeepSeek V4 Pro, 1,6T parameters / 49B actief, 1M context) geeft elke deeltaak aan een specialist: V4 Flash voor grote volumes, Qwen 3.6 Plus als back-up, Qwen Omni voor visie.","start.first-model#deeper#3#p":"Aurora — alleen Mistral, in drie niveaus: Mistral Large 3 (coördinator + zware specialisten), Mistral Medium 3.5 (128B dicht, 256K context, ingebouwde visie, aangepaste-MIT open gewichten, 77,6% SWE-Bench Geverifieerd) voor Builder + middenklasse + visie + lange teksten, en Mistral Small 4 bij de intentiegrens. Open gewichten van begin tot eind, verlaat nooit EU-infrastructuur.","start.first-model#deeper#4#h":"Breng je eigen model (BYOK)","start.first-model#deeper#5#p":"Geef je de voorkeur aan je eigen AI-account? Plak je providersleutel in de instellingen en krijg je beide — de drie routeringsstijlen, plus de optie om één enkel model te kiezen en routering volledig over te slaan. Handig bij een sterke voorkeur, een strikt budget, of het testen van een specifiek model. De volledige lijst met providers staat in de Referentie-sectie.","start.glossary#title":"Glossarium in begrijpelijke taal","start.glossary#0#p":"Elk woord dat je rondom Ava tegenkomt, uitgelegd zonder voorkennis. Je hoeft dit niet uit je hoofd te leren — sla terug wanneer een term je dwarszit.","start.glossary#1#th0":"Woord","start.glossary#1#th1":"Wat het eigenlijk betekent","start.glossary#1#td0.0":"Agent","start.glossary#1#td0.1":"Een AI die acties voor je kan uitvoeren — een bestand lezen, een opdracht uitvoeren, het web doorzoeken — niet alleen chatten. Ava is een agent: ze doet dingen, met jouw toestemming.","start.glossary#1#td1.0":"Model","start.glossary#1#td1.1":"De daadwerkelijke AI-brain die denkt (Qwen, DeepSeek, Mistral, en anderen). Verschillende modellen hebben verschillende sterktes. Je kiest normaal gesproken nooit zelf één — Ava doet dat.","start.glossary#1#td2.0":"Modus","start.glossary#1#td2.1":"De mentaliteit waarin Ava zit. Als een collega die van pet wisselt: bouwer, schrijver, leraar, planner, vriend. Jij kiest de modus; dit verandert hoe ze zich gedraagt. Er zijn er zeven.","start.glossary#1#td3.0":"Persoonlijkheid / specialist","start.glossary#1#td3.1":"Hulprollen die Ava achter de schermen draait voor lastige taken — een verkenner, een planner, een feitencheck. Denk aan een klein expertteam. Je praat nooit direct met hen; Ava coördineert ze.","start.glossary#1#td4.0":"Routering","start.glossary#1#td4.1":"Ava beslist welk model voor elke stap gebruikt wordt zodat je goede antwoorden krijgt zonder te veel te betalen. Dit gebeurt automatisch — \"routeringsmodus\" kiest alleen de algemene strategie.","start.glossary#1#td5.0":"Hulpmiddel","start.glossary#1#td5.1":"Een specifieke actie die Ava kan ondernemen — een bestand lezen, zoeken uitvoeren, een e-mail sturen. Een \"tool call\" is haar gebruik van zo'n hulpmiddel. Ze vraagt toestemming voordat iets risicovol is.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Hoe AI tekst meet — ongeveer ¾ van een woord. Modellen worden geprijsd per miljoen tokens. Meestal iets wat je kunt negeren.","start.glossary#1#td7.0":"Krediet","models.routing#deeper#2#td5.0":"Chat","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Orkestratie van beeldgeneratie","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Beeldherkenning","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (visie-encoder vanaf nul getraind)","models.routing#deeper#2#td8.0":"Schrijven van lange teksten","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Gegevenslocatie","models.routing#deeper#2#td9.1":"Gemengd (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Gemengd (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Alleen EU · open gewichten","models.routing#deeper#2#td10.0":"Status","models.routing#deeper#2#td10.1":"Nu beschikbaar · voor alle abonnementen","models.routing#deeper#2#td10.2":"Binnenkort beschikbaar","models.routing#deeper#2#td10.3":"Binnenkort beschikbaar","models.routing#deeper#2#td11.0":"Ideaal voor","start.glossary#1#td7.1":"Ava's simpelere eenheid voor wat een actie kost, zodat je niet met tokens hoeft te rekenen. De abonnementen komen met een maandelijkse pakket.","start.glossary#1#td8.0":"API-sleutel","start.glossary#1#td8.1":"Een privé-wachtwoord waarmee software een betaalde dienst (zoals een AI-model) op je account kan gebruiken. Je hebt er maar één nodig als je je eigen wilt meebrengen.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Breng je eigen sleutel mee.\" Je eigen API-sleutel gebruiken in plaats van Ava's beheerde toegang. Optioneel — voor mensen die al direct bij een provider betalen.","start.glossary#1#td10.0":"Lokaal eerst","start.glossary#1#td10.1":"Je data staat standaard op je eigen computer. Er wordt niets geüpload tenzij je synchronisatie aanzet. \"Lokaal is heilig.\"","start.glossary#1#td11.0":"Toestemmingsmodus","start.glossary#1#td11.1":"Hoe voorzichtig Ava is voordat ze dingen doet — elke keer vragen, alleen bij riskante dingen vragen, of gewoon doorgaan. Jij bepaalt het niveau.","start.glossary#1#td12.0":"Contextvenster","start.glossary#1#td12.1":"Hoeveel tekst een model tegelijkertijd in gedachten kan houden — zijn kortetermijngeheugen. \"1M context\" betekent ongeveer een miljoen woorden. Groter = het kan meer lezen voordat het vergeet.","start.glossary#1#td13.0":"Verschilweergave","start.glossary#1#td13.1":"Een zij-aan-zij overzicht van precies wat er in een bestand verandert — oud aan de ene kant, nieuw aan de andere — getoond voordat Ava iets wijzigt, zodat je het kunt goedkeuren.","start.glossary#1#td14.0":"Opslagplaats (repo)","start.glossary#1#td14.1":"Een projectmap die bijgehouden wordt op wijzigingen, meestal met Git. Als dat nog niets voor je betekent, is het gewoon \"de map waar mijn project in zit.\"","start.glossary#1#td15.0":"Instructie","start.glossary#1#td15.1":"Wat je typt naar de AI — je vraag of instructie.","start.glossary#2#c":"Nog vastgelopen op een woord? Vraag Ava in Chat-modus — \"wat betekent X?\" — en zij legt het uit op jouw niveau.","models.routing#title":"Routing — hoe Ava modellen kiest","models.routing#0#p":"Hier is de korte versie: je hoeft nooit zelf te kiezen welk AI-model je gebruikt. Ava doet het voor je, en kiest de beste tool voor elk onderdeel van een taak — zoals een goede manager de juiste taak aan de juiste persoon geeft.","models.routing#1#p":"Je kiest een van drie stijlen — Maestro, Supernova, of Aurora — en Ava stuurt elk werkstuk naar het model dat het het beste aan kan. Maestro is de standaard, het werkt op elk abonnement, en het is een goede keuze voor bijna iedereen.","models.routing#2#h":"Waarom routing inzetten?","models.routing#3#p":"Het juiste model per stap inzetten kost minder dan alles op één groot duur model draaien — en geeft betere resultaten, omdat elk model doet waar het goed in is. Je krijgt stabiele kosten en hoge kwaliteit zonder ooit te hoeven weten welk model welke is.","models.routing#4#c":"Alle drie de stijlen werken met platformcredits en je eigen sleutels. Met je eigen sleutel kun je ook routing overslaan en rechtstreeks één model aansturen. De volledige opsomming vind je onder \"Toon mij de details\".","models.routing#deeper#0#c":"De \"B\"-getallen hieronder staan voor miljarden parameters — ruwweg hoe groot het brein van een model is; groter betekent meestal slimmer maar langzamer en duurder. Dit is een technisch detail; je hebt dit nooit nodig om Ava te gebruiken.","models.routing#deeper#2#td11.1":"Dagelijks werk, voorspelbare kosten","models.routing#deeper#2#td11.2":"Zwaar meervoudig stappenwerk, coördinator van topniveau in elk plan","models.routing#deeper#2#td11.3":"GDPR-streng, overheidssectoren, soevereine EU-systemen","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Op niveau afgestemde Qwen-routing, lichtgewicht. Qwen 3.6 Plus neemt de coördinatorrol, Builder, planning, beveiliging, brainstormen en langere teksten — daar waar zijn hybride lineaire aandacht met 1M-context het beste tot zijn recht komt. Qwen 3.5 Flash regelt chatten, beeldgeneratie-coördinatie en de initiële intentie-controle, waar zijn prijs van $0.07/$0.26 en snellere TTFT het verschil maken bij het merendeel van de lage diepte-tokens. Qwen 3.5 Omni Plus verzorgt visuele invoer (Qwen 3.6 Plus heeft geen ingebouwde visie). Qwen 3.5 Plus draagt kostengevoelige lange teksten. Valt terug op de prioriteitsladder Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash als de primaire coördinator niet beschikbaar is.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Meertalige samenstelling. DeepSeek V4 Pro coördineert en stuurt elke subtak naar de meest geschikte specialist: Qwen 3.6 Plus draait elke Builder-start, V4 Flash regelt chatten plus de middensegment review/audit-persona's, Qwen 3.5 Flash absorbeert de lichtsegment classifiër-werk, Qwen 3.5 Omni Plus verzorgt visuele invoer, Qwen 3.5 Omni Flash coördineert beeldgenereer-toolaanroepen, Qwen 3.5 Plus draagt de kostengevoelige lange-vorm Content Writer-persoonlijkheid. Geavanceerd redeneren waar het er toe doet, economische flash-niveaus op het merendeel van het tokenvolume.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Europese AI-stack — soeverein van ontwerp. Alleen Mistral routing in drie niveaus: Mistral Large 3 (675B/41B-actief spaarzaam MoE) neemt de coördinatorrol en de zware specialisten die diepte nodig hebben — Researcher, Challenger, CVE Researcher, Ideator, Fact Checker, Security Verifier — en het zware werk met lange context waar zijn spaarzaam-MoE-efficiëntie wint. Mistral Medium 3.5 — de samengevoegde vlaggenschip versie uitgebracht april 2026, 128B dicht, 256K context, visuele encoder vanaf nul getraind, gewijzigde-MIT open gewichten, 77.6% SWE-Bench Geverifieerd — draait de daadwerkelijke werkniveau: Builder starts, middensegment specialisten (Architect, Verifier, Sequencer, Tutor, Reporter), visuele invoer, en lange-vorm schrijven. Mistral Small 4 uitgebreid van een enkele rol aan de intentie-poort om ook chatten en beeldgenereer-coördinatie te doen — zijn prijs van $0.15/$0.60 en configureerbare redenering verdienen hun kost op de hoge-volume lage-diepte routes. Open gewichten van begin tot eind, verlaat nooit EU-infrastructuur. Aurora kruist bewust niet stilletjes naar een niet-Mistral-model wanneer één niet beschikbaar is; de router geeft een foutmelding in plaats daarvan — dat is wat het \"Aurora\" maakt in plaats van een Maestro met Mistral-smaak.","credits.overview#title":"Ava Credits — hoe facturatie werkt","credits.overview#0#p":"Credits zijn simpelweg hoe Ava telt wat je gebruikt — zoals minuten op een telefoonabonnement. Elk abonnement, inclusief het gratis, komt met een pot credits, en elke actie die Ava doet (jou beantwoorden, een afbeelding maken) kost een klein aantal ervan. Dat is het hele idee. De details hieronder zijn voor als je precies wilt weten wat wat kost.","credits.overview#1#p":"Ava factureert in credits, niet in ruwe tokens. (Een \"token\" is het kleine stukje tekst — ongeveer een paar letters — dat AI-modellen lezen en schrijven; de meeste diensten rekenen je per token af, wat lastig te voorspellen is.) Eén credit dekt één eenheid werk — een chatbeurt, een persona-activering (één helper die een stukje van de taak doet), een beeldgeneratie. Loskoppeling van token-niveau meting betekent dat je niet hoeft te weten welk model draait om te weten wat een actie kost. Dezelfde chatbeurt kost hetzelfde, of Maestro het nu naar Qwen 3.6 Plus stuurt of Supernova het naar V4 Pro.","credits.overview#2#h":"Abonnementen","credits.overview#3#p":"Elk abonnement heeft toegang tot alle functies — modeltoegang, Creative Studio, alle zeven modi, de volledige persona-orkestratie. Hogere niveaus kopen meer credits en een hogere limiet voor aanvragen, geen ontgrendelde functies.","credits.overview#4#li0":"Gratis — $0/maand. 300 credits. Limiet van 20 aanvragen/minuut. Geen kaart vereist.","credits.overview#4#li1":"Pro — $19/maand. 5,000 credits. 60 aanvragen/minuut.","credits.overview#4#li2":"Ultra — $39/maand. 10,000 credits. 120 aanvragen/minuut.","credits.overview#4#li3":"Enterprise — $79/maand. 20,000 credits. 200 aanvragen/minuut.","credits.overview#5#c":"Niet-gebruikte credits rollen door zolang je abonnement actief is — er is geen gedwongen terugname. Opwaarderingen stapelen zich op het abonnementspot: 750 credits voor $3, 2,000 voor $8, 4,000 voor $15.","credits.overview#6#h":"Wat dingen kosten","credits.overview#7#p":"Tabel met kosten per actie — wat er van je creditpool wordt afgetrokken wanneer elke actie draait. (Een \"cache hit\" is wanneer Ava werk hergebruikt dat het al gedaan heeft in plaats van het opnieuw te doen; als dat gebeurt betaal je minder — de kosten dalen met 70%, of 50% bij uitvoer-zware modellen zoals DeepSeek V4 Pro.)","credits.overview#8#li0":"Chatbeurt — 2 credits. Een enkele uitwisseling in elke modus.","credits.overview#8#li1":"Lichte oproep — 1 credit. Intentie-poort, classificatie, eenmalige lezing.","credits.overview#8#li2":"Zware persona — 3 credits. Architect, Researcher, CVE Researcher, Ideator (diepte ≥ 4).","credits.overview#8#li3":"Lichte persona — 1 credit. Scout, Verifier, Sequencer, Challenger (diepte ≤ 2).","credits.overview#8#li4":"Orkestratie — 10 credits. Volledig persona-proces opzetten (Conductor + multi-persona taak).","credits.overview#8#li5":"Afbeeldingen genereren — 12 credits. Hailuo image-01 via Creative Studio.","credits.overview#8#li6":"Video's genereren — 150 credits. Hailuo 02 Pro 1080p 6s clip.","credits.overview#8#li7":"Stemmen genereren — 10 credits. Speech 2.8 HD synthese.","credits.overview#8#li8":"Muziek maken — 50 credits. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Achtergrond verwijderen — 2 credits.","credits.overview#9#h":"Vermenigvuldigingsfactoren per model","credits.overview#10#p":"Dit stukje is voor de nieuwsgierigen — je hebt het niet nodig om Ava te gebruiken. Een vermenigvuldigingsfactor past de kredietkosten gewoon aan, omhoog of omlaag, afhankelijk van hoe duur het model achter een actie is. Zwaardere modellen kosten daardoor iets meer. (\\\"Netto marge\\\" is het aandeel dat het project overhoudt na het betalen van de kosten — we houden dit laag, zodat de waarde bij jou terechtkomt.)","credits.overview#11#p":"Zwaardere modellen vermenigvuldigen de actiekosten, zodat credits de werkelijke kosten volgen in plaats van een vast tarief. Gecalibreerd voor ~55% netto marge.","credits.overview#12#li0":"0.6× — Mistral Small 4 (de specialistenrol van Aurora). Onder 1× omdat Mistral Small 4 goedkoper is dan het Qwen 3.6 Plus referentiepunt.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Basistarief.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (Aurora coördinator). Ongeveer gelijkwaardig aan het Qwen 3.6 Plus referentiepunt.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (Maestro coördinator).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (Supernova coördinator + zware specialisten). Opnieuw gecalibreerd van 5.0× om het marge-evenwicht te herstellen bij het gepubliceerde V4 Pro-tarief.","credits.overview#13#c":"Anthropic-modellen (Claude Opus / Sonnet / Haiku) worden niet gefactureerd via credits — ze werken alleen via BYOK en je betaalt Anthropic direct. Dit geldt ook voor elke andere BYOK-provider die wordt gebruikt met je eigen sleutel.","credits.overview#14#h":"BYOK en credits","credits.overview#15#p":"BYOK (\\\"breng je eigen sleutel\\\" — jij levert je eigen account bij een AI-provider en een sleutel, een privé wachtwoord waarmee software dat betaalde account kan gebruiken) is voor mensen die al direct een AI-provider betalen. Als dat niet voor jou geldt, kun je dit gedeelte volledig negeren.","credits.overview#16#p":"Aanvragen met een eigen sleutel omzeilen de platforminfrastructuur volledig — de aanroep gaat direct van Ava naar de provider, jij betaalt de provider, er worden geen credits verbruikt. De enige uitzondering is wanneer een BYOK-sessie een beheerde persona start voor een subtaak; de creditaftrek geldt dan nog steeds, omdat er gebruik wordt gemaakt van Ava's orkestratielaag.","credits.overview#17#h":"Waar je je saldo kunt controleren","credits.overview#18#li0":"Extensie — Instellingen → Account, of het credit-balkje in de chat-kop.","credits.overview#18#li1":"IDE — De dashboard-tegel van het account toont het huidige saldo en verbruik.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard toont saldo, geschiedenis en verlengingsdatum.","credits.overview#19#c":"Local-first: Ava werkt zonder account op de kaart voor Aangepast Model (Ollama, LM Studio, vLLM, of elk OpenAI-compatibel eindpunt). Geen credits, geen platformtokens — jouw model, jouw machine, je factuur is nul.","concepts.modes#title":"Modi — Ava's denkstanden","features.creative-studio#1#p":"Afbeeldingen, video’s, muziek en spraak — allemaal ingebouwd in dezelfde workflow als je code. Maak een icoon, een productmockup, een demovideo of een voiceover voor een handleiding. Mogelijk gemaakt door MiniMax.","features.creative-studio#2#h":"Wat je kunt creëren","features.creative-studio#3#li0":"Afbeeldingen — van tekst naar PNG/JPG. Achtergrond verwijderen is één stap verwijderd.","features.creative-studio#3#li1":"Video — korte AI-video’s uit een tekstprompt (MiniMax Hailuo).","features.creative-studio#3#li2":"Muziek — instrumentale of zangtracks met teksten.","features.creative-studio#3#li3":"Spraak — tekst-naar-spraak met keuze uit verschillende stemmen.","features.creative-studio#4#p":"Kosten voor Creative Studio worden afgetrokken van hetzelfde kredietenpakket als alles anders — één pakket, één saldo. Gebruik je eigen MiniMax-sleutel (BYOK) en het is gratis bij je abonnement.","features.creative-studio#5#c":"Creative Studio is geschikt voor de gratis versie. Het is geen betaalde toevoeging.","features.desktop-automation#title":"Desktopautomatisering","features.desktop-automation#0#p":"Simpel gezegd: Ava kan je muis en toetsenbord overnemen om taken voor je uit te voeren — een app openen, knoppen aanklikken, formulieren invullen — terwijl jij meekijkt en belangrijke dingen goedkeurt.","features.desktop-automation#1#p":"Een nieuwe modus voor Ava, begin met @@. Zij observeert je bureaublad, beslist wat er moet gebeuren, en stuurt de UI-automatisering aan (ze bestuurt de apps op je scherm voor jou) om het klaar te krijgen. Dit draait op jouw eigen computer met jouw eigen inloggegevens — geen cloudbrowser. Beschikbaar op elk niveau zodra het beschikbaar is.","features.desktop-automation#2#h":"Waarom dit nog eens?","features.desktop-automation#3#p":"Elk ander product voor desktopautomatisering gebruik je pas als je aan je bureau zit. Ava is er altijd als je foutmeldingssysteem om 2 uur 's nachts alarm slaat — de IDE blijft draaien, je telefoon koppelt via een beveiligde verbinding, jij keurt onomkeerbare acties goed met één tik.","features.desktop-automation#4#p":"Zij onthoudt ook hoe je door je apps navigeert tussen sessies door. Elke andere agent moet ze elke keer opnieuw leren. Het geheugen voordeel wordt groter naarmate je het gebruikt.","features.desktop-automation#5#h":"Hoe het werkt","features.desktop-automation#6#p":"Bij elke stap schakelt Ava een team van vijf rollen in: Scout observeert, Planner kiest de volgende actie, Actor voert uit, Verifier controleert, Narrator vertelt je wat er gebeurde. De sidecar kiest de goedkoopste betrouwbare basis — UIA voor native apps, Playwright voor browsers, OmniParser vision als niets anders een bruikbare structuur biedt.","features.desktop-automation#7#p":"Bekijk de conceptpagina's voor veiligheidsonologie, hiërarchie van de grondslag, noodstopschakelaars en het sessie-witlijstmodel.","concepts.desktop-safety#3#li2":"Mutatief-omkeerbaar — typ in een veld, plak tekst, open een app, ga naar een URL. Bevestigt in Vraag-modus; automatisch in Drive binnen de witte lijst.","concepts.desktop-safety#3#li3":"Mutatief-onomkeerbaar — versturen, indienen, betalen, verwijderen, bevestigen, publiceren. Bevestigt altijd, ongeacht je toestemmingsniveau. Goedkeuring wordt nooit onthouden.","concepts.desktop-safety#3#li4":"Bevoegd — UAC-verhoging, sudo, registerbewerkingen, wachtwoordverzoeken. Standaard verboden. Vereist eenmalige toestemming per sessie.","concepts.desktop-safety#4#h":"Goedkeuringen worden nooit onthouden","concepts.desktop-safety#5#p":"Elke concurrent slaat goedkeuringen op (onthoudt je \"ja\" en gebruikt het de volgende keer). Dat is de grootste insteek voor prompt injection — een aanval waarbij een geladen webpagina verborgen instructies aan de AI sluist om tegen jou te handelen. Als goedkeuringen worden onthouden, kan een gehackte pagina misbruikmaken van een \"ja\" dat je eerder hebt gegeven. Ava slaat nooit op. Elke mutatief-onomkeerbare actie vraagt opnieuw.","concepts.desktop-safety#6#h":"Omgaan met geheimen","concepts.desktop-safety#7#p":"Wachtwoorden, API-sleutels en 2FA-codes (de eenmalige codes die een tweede app of sms je geeft bij het inloggen) worden behandeld via ondeugdelijke verwijzingen — plaatsaanduidingen die de echte waarde vervangen. Ava ziet \"{secret}\", niet het echte wachtwoord. De echte waarde komt nooit in haar geheugen, haar activiteitenlogboek of wat ze \"leest\" — een aparte laag typt dit op het allerlaatste moment in, bij de toetsaanslag, zodat het AI-gedeelte er nooit mee in aanraking komt.","reference.cli#title":"CLI-commando's","reference.cli#0#p":"Deze pagina is voor de CLI — de versie van Ava waarmee je typt in een terminalvenster, in plaats van op knoppen te klikken. Als je de extensie of de desktop-app gebruikt, kun je deze pagina volledig overslaan. Hij is er voor mensen die liever het toetsenbord gebruiken.","reference.cli#1#p":"De CLI is een interactieve shell — een prompt die wacht tot je typt, uitvoert wat je typte, en dan weer wacht. Deze slash-commando's (instructies die beginnen met \"/\") werken vanaf de prompt.","reference.cli#2#li0":"/help — lijst met commando's en huidige modus.","reference.cli#2#li1":"/mode <naam> — wissel modus (werken, schrijven, plannen, chatten, leren, beveiliging, brainstormen).","reference.cli#2#li2":"/model <id> — wissel model zonder de sessie te verlaten.","reference.cli#2#li3":"/clear — wis de huidige conversatie. Geheugen blijft intact.","reference.cli#2#li4":"/history — lijst met eerdere conversaties in dit project.","reference.cli#2#li5":"/memory — open het geheugenoverzicht.","reference.cli#2#li6":"/tasks — lijst en beheer taken.","reference.cli#2#li7":"/journal — open dagboekvermelding van vandaag.","reference.cli#2#li8":"/settings — open het instellingenmenu.","reference.cli#2#li9":"/exit — sluit de interactieve shell af.","reference.cli#3#h":"Startopties","reference.cli#4#p":"Opties zijn extra instellingen die je toevoegt wanneer je Ava start, elk beginnend met \"--\", om te bepalen hoe ze opent.","reference.cli#5#li0":"--mode <naam> — start in een specifieke modus.","reference.cli#5#li1":"--model <id> — start met een specifiek model.","reference.cli#5#li2":"--permission <modus> — strikt / gebalanceerd / autonoom.","concepts.modes#0#p":"Een modus is de denkstand waarin Ava zit — alsof een collega van pet wisselt. Dezelfde persoon, dezelfde herinnering aan jou, maar een bouwer denkt anders dan een leraar. Jij kiest de modus en dat bepaalt hoe ze zich gedraagt en welke helpers ze erbij haalt. Wissel elke keer met de modus-selector, of typ een twee-karakter sneltoets.","concepts.modes#2#h":"Welke kies je?","concepts.modes#3#p":"Begin bij wat je wilt bereiken — de modus volgt daaruit:","concepts.modes#4#li0":"Ik wil iets bouwen of wijzigen → Code (>>). Jij beschrijft het, zij bouwt het en laat eerst elke wijziging zien. Voor grotere taken schakelt het volledige helper-team in.","concepts.modes#4#li1":"Ik wil eerst een plan voordat er iets verandert → Plan (::). Ze denkt alles door en legt jou een plan voor om goed te keuren of aan te passen. In deze modus raakt ze je bestanden niet aan.","concepts.modes#4#li2":"Ik wil gewoon praten of iets vragen → Chat (..). Een denkpartner met geheugen, nieuws en weerinformatie. Geen bestandswijzigingen, geen code — alleen een gesprek.","concepts.modes#4#li3":"Ik wil iets leren → Teach (??). Een echte cursus op maat: lessen, quizzen, alles erop en eraan. Gratis op elk abonnement, voor altijd. Ideaal als je net begint.","concepts.modes#4#li4":"Ik wil mijn project laten controleren op veiligheidslekken → Security (!!). Een team loopt de standaardlijst van veelvoorkomende webkwetsbaarheden (de \"OWASP\" categorieën) en bekende gemelde fouten (genoemd \"CVEs\") na, en geeft je daarna een rapport gesorteerd op hoe ernstig elk probleem is. Dit is bedoeld voor ontwikkelaars — sla dit over als dat niet voor jou is.","concepts.modes#4#li5":"Ik wil ideeën → Brainstorm (**). Ze bedenkt opties die aansluiten bij jouw situatie, test de zwakke plekken af, en verfijnt de rest tot concrete vervolgstappen.","concepts.modes#4#li6":"Ik wil een document schrijven → Write (<<). Rapporten, voorstellen, brieven, artikelen — ze maakt concepten in Markdown en exporteert een document met je huisstijl als Word-doc of PDF, sectie per sectie verfijnend. Geen code, alleen schrijven.","concepts.modes#5#c":"Het \"helper team\" (persona's) werkt volledig achter de schermen — je spreekt hen nooit rechtstreeks aan. Je krijgt gewoon een grondiger antwoord. Je hoeft hun namen niet te kennen.","concepts.modes#6#c":"Je kunt van modus wisselen tijdens een gesprek. Jouw geheugen blijft behouden; de specialisten resetten zich passend bij de nieuwe modus.","concepts.tasks-journal#title":"Taken en dagboek","concepts.tasks-journal#0#p":"Ava bewaart drie soorten notities voor je, en het is makkelijk om ze door elkaar te halen. De snelle manier om te onthouden: geheugen is wat ze over jou weet, taken zijn wat je nog moet doen, en het dagboek is een logboek van hoe dingen verliepen. Hier zie je wanneer je welke gebruikt.","concepts.tasks-journal#1#li0":"Geheugen — blijvende feiten. Voorkeuren, beslissingen, patronen. Wordt vaak gevraagd, zelden handmatig aangemaakt.","concepts.tasks-journal#1#li1":"Taken — dingen om te doen. Actiepunten met termijnen en status. Je vinkt ze af als ze geklaard zijn.","concepts.tasks-journal#1#li2":"Dagboek — reflectie. Dagelijks logboek, dubbele invoer (jouw en Ava's observaties over de sessie). Handig voor stemming volgen, sessie-evaluaties, context voor morgen.","concepts.tasks-journal#2#p":"Ava schrijft naar alle drie als het zinvol is. Je kunt rechtstreeks vanuit het dashboard naar elk van hen schrijven. Niets is vastgezet op één plek waar je Ava gebruikt — een taak die je in één maakt (bijvoorbeeld de command-line tool) verschijnt automatisch ook overal elders (zoals de desktop-app).","concepts.permissions#title":"Machtigingen — je veiligheidsschakelaar","concepts.permissions#0#p":"Machtigingen zijn je veiligheidsschakelaar. Ze bepalen wanneer Ava je toestemming vraagt voordat ze iets op je computer doet, in plaats van gewoon doorgaan. Je kunt haar instellen om over alles te vragen, alleen over risico's, of haar vertrouwen om zelfstandig te werken — en je kunt dit elke keer wijzigen. Twijfel je? Laat het op de standaard staan en je zit goed.","concepts.permissions#1#p":"Ava heeft 60 tools (\"tools\" zijn de acties die ze kan uitvoeren — een bestand lezen, het web doorzoeken, enzovoort). Elke tool valt onder een categorie (bestandsbewerkingen, shell, Git, web, media, database, systeem, documenten, geheugen, leren). Elke tool-aanroep gaat langs de machtigingspoort (een controlepunt dat beslist of ze eerst jou moet vragen) voordat het draait. Jij bepaalt wat automatisch wordt goedgekeurd, wat één keer vraagt, en wat altijd vraagt.","concepts.permissions#3#p":"Gebalanceerd is de standaard. Strikt als je haar gedrag auditeert (nauwlettend controleren van elke stap). Autonoom als je wilt dat ze gewoon aan de slag gaat.","concepts.permissions#4#c":"Autonoom betekent niet ongecontroleerd. Plannen, verhelderende vragen, en expliciete prompts om input te vragen, pauzeren nog steeds voor jouw input. Onomkeerbare bewerkingen (Git force-push, database-drops) vragen altijd bevestiging, ongeacht de modus.","concepts.interjection#title":"Sturen en stoppen van Ava","concepts.interjection#0#p":"Jij bent altijd aan het roer. Terwijl Ava druk bezig is, kun je haar in een nieuwe richting sturen zonder haar ritme te verbreken, of haar direct stoppen. Twee knoppen, twee uitkomsten — daar draait deze pagina om.","reference.cli#5#li3":"--project <path> — stel de projectroot expliciet in.","reference.desktop-budget#title":"Desktop-begrotingslimieten","reference.desktop-budget#0#p":"Wanneer Ava namens jou je desktop bestuurt — klikken, typen, apps openen — wordt elke run een \"traject\" genoemd. Deze pagina legt de veiligheidslimieten uit die voorkomen dat één run te lang duurt of te veel kost. De boodschap: ze stopt altijd en meldt zich voordat ze te ver gaat. De cijfers staan hier als je details wilt.","reference.desktop-budget#1#p":"Elk traject draait onder drie gelijktijdige limieten (harde grenzen). De eerste die bereikt wordt, wint. Het traject gaat nooit stil verder na een overtreding — de Narrator (de helper die je uitlegt wat er gebeurt) pauzeert en vraagt wat je wilt doen.","reference.desktop-budget#2#h":"Drie harde limieten (standaard)","reference.desktop-budget#3#li0":"Staptelling — 30 stappen","reference.desktop-budget#3#li1":"Tokenbudget — 500.000 tokens","reference.desktop-budget#3#li2":"Werkelijke tijd — 5 minuten","reference.desktop-budget#4#h":"Taakkostenbanden","reference.desktop-budget#5#li0":"Eenvoudig (documenten zoeken, een pagina openen) — 5–10 stappen, ~70–135K tokens, ~$0,04–0,08","reference.desktop-budget#5#li1":"Gemiddeld (inloggen, logs controleren, uitvoer downloaden) — 15–25 stappen, ~205–340K tokens, ~$0,12–0,21","reference.desktop-budget#5#li2":"Complex (drie GitHub-issues triagen) — 25–30 stappen, ~340–410K tokens, ~$0,21–0,25","reference.desktop-budget#6#p":"De bovenstaande tokencijfers zijn de technische limieten per traject, niet je maandelijkse tegoed — dat wordt geteld in credits, en het gratis niveau met 300 per maand dekt comfortabel een mix van chat, code en een paar automatiseringen.","reference.desktop-budget#7#c":"Je kunt limieten per taak aan het begin overschrijven, maar bij overtredingen komt er altijd een beslispunt. Budget wordt nooit stilletjes verbrand.","reference.desktop-whitelist#title":"Desktopsessie-witlijst","reference.desktop-whitelist#0#p":"Een \"witlijst\" is simpelweg de lijst van apps en websites waar je hebt gezegd dat Ava mag naar kijken terwijl ze je desktop bestuurt. Deze pagina legt uit hoe je die toestemming geeft en waarom deze telkens reset. De korte versie: ze kan alleen handelen waar je haar laat, en ze vraagt voordat ze ergens anders naartoe gaat.","reference.desktop-whitelist#1#p":"Bij het starten van een desktopsessie vraagt Ava waar ze mag handelen. Gewone taal werkt: \"Gmail, Cursor, het Azure-portaal.\" Ze leest dit en bevestigt de overeenkomst terug aan jou (\"Gmail web, Cursor de app, portal.azure.com\").","reference.desktop-whitelist#2#h":"Hoe het wordt afgedwongen","reference.desktop-whitelist#3#p":"Alleen-kijken acties — een screenshot maken, de lijst van knoppen en velden op het scherm lezen (de \"UIA tree\", Windows eigen kaart van wat er in een venster zit) — zijn overal toegestaan, omdat je moet zien wat er op het scherm staat om te beslissen of je een app aan de witlijst toevoegt. Alles wat iets wijzigt, wordt buiten de lijst geblokkeerd; Ava pauzeert en vraagt of je het wilt toevoegen.","reference.desktop-whitelist#4#h":"Sessie-gebonden, opzettelijk","reference.desktop-whitelist#5#p":"De witlijst blijft NIET behouden tussen sessies. Er is geen optie \"deze app onthouden\". Elk nieuw traject begint met een nieuwe scope. Onhandig door ontwerp — vergeten opnieuw te autoriseren is een functie, geen fout.","reference.desktop-whitelist#6#h":"Toevoegingen halverwege het traject","reference.desktop-whitelist#7#p":"Tijdens een traject kun je apps toevoegen via de koptekst: \"+ Allow app\" opent een klein invoerveld. Tik op Toevoegen en de nieuwe app is actief voor de rest van de sessie.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Wil je een afbeelding, een korte video, een liedje of een gesproken voiceover maken? Beschrijf het gewoon en Ava maakt het voor je — geen ontwerpsoftware of audioprogramma nodig.","concepts.interjection#1#p":"Ava werkt tot haar plan voltooid is of jij haar stopt. Je hebt twee manieren om in te grijpen (het woord hiervoor is \"intervenen\") terwijl ze draait.","concepts.interjection#2#h":"Intervenen — sturen zonder annuleren","concepts.interjection#3#p":"Typ een nieuw bericht terwijl Ava werkt. Ze maakt de huidige taak af, leest je bericht en past haar plan aan. Geen context gaat verloren. Gebruik dit als je wilt bijsturen, informatie toevoegen of prioriteiten wijzigen tijdens het proces.","concepts.interjection#4#h":"Harde stop — annuleren en wissen","concepts.interjection#5#p":"Druk op Escape (CLI), klik op Stop (extensie, IDE), of typ een stopcommando. De huidige run wordt geannuleerd, openstaande taken vallen weg en het gesprek is klaar voor een nieuwe ronde.","concepts.interjection#6#c":"Begin met intervenen. Een harde stop is voor als er echt iets mis is. Intervenen houdt de draad vast.","concepts.desktop-personas#title":"Desktop-persona's","concepts.desktop-personas#0#p":"Deze pagina is voor de nieuwsgierigen en de power users. \"Desktop automatisering\" (soms \"computergebruik\" genoemd) betekent dat Ava daadwerkelijk op je scherm kan klikken en apps voor je kan gebruiken — Gmail openen, formulieren invullen, berichten versturen — net als een persoon achter het toetsenbord. Om dit veilig te doen, verdeelt ze de taak over vijf kleine helpers, elk met één smalle rol. Je hebt er nooit direct mee te maken; dit laat alleen zien wie wat doet.","concepts.desktop-personas#1#p":"Elke stap in een desktop-traject (één keer dat Ava je scherm bestuurt naar een doel) activeert een groep van vijf persona's. Elke persona heeft één taak en niets anders. Deze scheiding zorgt ervoor dat instructies strak blijven, de uitvoer gestructureerd is en de redenering kritisch is door ontwerp.","concepts.desktop-personas#2#h":"Verkenner","concepts.desktop-personas#3#p":"Rapportage van wat er nu zichtbaar is op het scherm. Vindt nooit elementen uit. Plant nooit. Retourneert een ScreenState JSON met element-ID's, namen, bboxes, betrouwbaarheid en een grondingsbron (UIA, Playwright DOM, of OmniParser visie).","concepts.desktop-personas#4#h":"Planmaker","concepts.desktop-personas#5#p":"Beslist over de volgende enkele actie. Één actie per stap — nooit bundels. Voorkeur voor omkeerbare paden. Classificeert risico volgens de veiligheidsontologie. Output een ProposedAction JSON met type, doel, parameters, riskClass, redenering en een expectedPostState voorspelling.","concepts.desktop-personas#6#h":"Uitvoerder","concepts.desktop-personas#7#p":"Voert precies uit wat Planmaker voorgesteld heeft — nadat de goedkeuringspoort vrij is. Geen improvisatie. Geen herhaling. Fouten worden eerlijk gerapporteerd en Controleur regelt de volgende zet.","concepts.desktop-personas#8#h":"Controleur","concepts.desktop-personas#9#p":"Checkt of de actie geland is. Vergelijkt de nieuwe ScreenState met Planmakers voorspelling. Retourneert geverifieerd, afgeweken, of terugdraaien_nodig. Voert ook lusdetectie uit — een actie herhalen die al geslaagd is, is een afwijking, geen verificatie.","concepts.desktop-personas#10#h":"Verteller","concepts.desktop-personas#11#p":"De enige stem die de gebruiker hoort tijdens een traject. Eén zin in verleden tijd per stap (\"Gmail geopend.\", \"Op Schrijven geklikt.\"). Schrijft ook de gestructureerde controlelogboek. Zegt wanneer er iets misging — verbergt nooit een probleem.","concepts.desktop-safety#title":"Veiligheidsontologie voor desktop","concepts.desktop-safety#0#p":"Kortom: voordat Ava iets op je scherm aanklikt, sorteert ze de actie op hoe risicovol het is. Scherm lezen? Onschuldig. Geld sturen of iets verwijderen? Ze stopt altijd en vraagt het eerst — elke keer, zonder uitzondering. De vijf labels hieronder zijn gewoon de sporten van die risicoladder. Dit is detail voor power users, maar de boodschap is simpel: gevaarlijke dingen hebben altijd jouw ja nodig.","concepts.desktop-safety#1#p":"Elke voorgestelde actie wordt ingedeeld in één van vijf risicoklassen. De classificatie combineert drie signalen — wat het doel op het scherm is, een beschrijving in gewone taal (\"semantische bijschrift\" — Avas eigen woorden voor wat ze ziet), en de instellingen van de actie — en schakelt hoger (behandelt het als risicovoller) als ze niet overeenkomen. Een vals positief (vragen wanneer het niet nodig was) is gewoon irritant. Een vals negatief (niet vragen waar het wel had moeten) is een incident dat het einde van het gebruik betekent.","concepts.desktop-safety#2#h":"De vijf klassen","concepts.desktop-safety#3#li0":"Observatief — lees UIA-boom, schermafbeelding, hover. Altijd automatisch toegestaan.","concepts.desktop-safety#3#li1":"Navigatief — scrollen, focus verplaatsen, menu openen. Automatisch toegestaan in Drive-modus."},"id":{"start.for-non-coders#title":"Belum Pernah Menulis Kode? Mulai dari Sini","start.for-non-coders#0#p":"Jika Anda belum pernah menulis kode sedikitpun, Anda adalah target utama Ava. Anda tidak perlu belajar istilah teknis untuk mulai — Anda cukup bicara padanya dalam bahasa Inggris yang sederhana, seperti bertanya pada teman yang paham. Halaman ini adalah panduan lengkap Anda.","start.for-non-coders#1#h":"Apa yang Bisa Anda Lakukan Hari Ini, Tanpa Pengalaman","start.for-non-coders#2#li0":"Tanyakan apa saja dengan kata-kata biasa — \"what does this file do?\", \"why is my page blank?\", \"what even is a database?\" Dia menjawab dengan bahasa santai dan mengingat percakapan Anda.","start.for-non-coders#2#li1":"Belajar dari dasar — ucapkan \"teach me Python from zero\" dan dia buatkan kursus lengkap dengan materi dan kuis. Ini selalu gratis.","start.for-non-coders#2#li2":"Buat sesuatu — deskripsikan keinginan Anda (\"a button that downloads my notes\") dan dia menuliskannya, memperlihatkan setiap perubahan sebelum diterapkan.","start.for-non-coders#3#h":"Anda Tidak Perlu Memahami Semuanya","start.for-non-coders#4#p":"Di balik layar, Ava punya banyak mekanisme — mode, model, spesialis, dan penyaluran. Anda mungkin melihat kata-kata ini di aplikasi atau dokumen ini. Rahasianya: Anda bisa abaikan hampir semuanya. Ava otomatis memilih alat dan bantuan yang tepat untuk Anda. Halaman teknis disediakan saat Anda penasaran, bukan syarat untuk memulai.","start.for-non-coders#5#h":"Langkah Pertama yang Ramah","start.for-non-coders#6#li0":"Instal Ava (halaman berikutnya) dan buka obrolan.","start.for-non-coders#6#li1":"Ketik pertanyaan nyata yang Anda miliki. Apa saja. Lihat bagaimana dia menjawab.","start.for-non-coders#6#li2":"Coba mode belajar: ketik \"teach me\" dan topik. Ikuti langkahnya.","start.for-non-coders#6#li3":"Saat Anda ingin dia benar-benar membuat atau mengubah sesuatu, cukup minta saja — dia akan selalu menunjukkan apa yang akan dilakukannya dan menunggu persetujuan \"ya\" dari Anda.","start.for-non-coders#7#c":"Ketemu kata yang tidak Anda kenal? Glosarium Bahasa Sederhana (ada di bagian bawah ini) menjelaskan setiap istilah tanpa perlu latar belakang khusus.","start.install#title":"Instalasi","start.install#0#p":"Pilih antarmuka yang sesuai dengan cara kerja Anda. Anda bisa menggunakan lebih dari satu — Ava menyinkronkan ingatannya di semua tempat saat Anda masuk.","start.install#1#h":"Ekstensi VS Code","start.install#2#li0":"Buka panel Ekstensi di VS Code (Ctrl+Shift+X / Cmd+Shift+X).","start.install#2#li1":"Cari \"Ava Supernova\" dan klik Instal.","start.install#2#li2":"Tekan Ctrl+Shift+A (Cmd+Shift+A pada macOS) untuk membuka panel obrolan.","start.install#2#li3":"Ikuti wizard pengaturan — pilih model, atur mode izin, selesai.","start.install#3#h":"IDE Desktop","start.install#4#li0":"Unduh installer untuk platform Anda dari halaman rilis.","start.install#4#li1":"Jalankan. IDE akan dimulai dengan alur sambutan pertama kali.","start.install#4#li2":"Masuk untuk mendapatkan token platform gratis, atau tempel kunci API sendiri agar berjalan sepenuhnya lokal.","start.install#5#h":"CLI","start.install#6#li0":"npm install -g @ava/cli  (atau pnpm / yarn — pilihan Anda).","start.install#6#li1":"Jalankan ava di direktori proyek apa pun.","start.install#6#li2":"Pada pemutaran pertama, Anda diminta memilih penyedia dan model. Pilih dan mulai.","start.install#7#c":"Tidak punya akun, tidak masalah. Dengan kunci API sendiri (BYOK), Anda tidak perlu masuk. Paket gratis adalah untuk model yang dikelola platform.","concepts.memory#title":"Memori — bagaimana Ava mengingat Anda","concepts.memory#0#p":"Secara sederhana: Ava mengingat Anda. Ceritakan sesuatu sekali — apa yang Anda sukai, keputusan yang Anda buat — dan dia menyimpannya, jadi Anda tidak harus mengulanginya di obrolan berikutnya atau minggu depan. Itulah intinya. Lapisan di bawahnya hanya menjelaskan bagaimana dia menjaga memori itu rapi seiring waktu.","concepts.memory#1#p":"Ava memiliki memori persisten (\"persisten\" artinya tetap ada setelah Anda menutup aplikasi) yang bertahan melintasi percakapan, proyek, dan perangkat jika sinkronisasi diaktifkan (sinkronisasi menyalin memori Anda antar perangkat). Ini bukan log obrolan. Ini adalah pemahaman terstruktur, dapat dicari tentang siapa Anda, apa yang Anda sukai, dan apa yang telah Anda putuskan.","concepts.memory#2#h":"Lima Lapisan","concepts.memory#3#li0":"Ekstrak — fakta penting diambil dari setiap pesan secara langsung.","concepts.memory#3#li1":"Refleksi — analisis mendalam berjalan di akhir sesi yang bermakna. Pola, tema, kontradiksi.","concepts.memory#3#li2":"Akumulasi — koreksi dan preferensi terkumpul seiring minggu dan bulan.","concepts.memory#3#li3":"Analisis — mesin grafik menghubungkan ingatan terkait dan memberi tanda kontradiksi ketika informasi baru bertentangan dengan yang lama.","concepts.memory#3#li4":"Konsolidasi — ingatan serupa bergabung; yang usang dipangkas. Memori menjadi lebih tajam seiring waktu, bukan semakin bising.","concepts.memory#4#c":"Lima lapisan di atas berjalan sendiri — Anda tidak perlu mengelolanya. Mereka ada agar Anda bisa melihat ingatan benar-benar membaik seiring waktu, bukan berubah menjadi tumpukan sampah.","concepts.memory#5#h":"Pemanggilan","concepts.memory#6#p":"Ketika Anda bertanya, Ava mencari dalam memori berdasarkan makna (\"pencarian semantik\" — ia memahami maksud Anda, sehingga menemukan ingatan yang tepat meskipun Anda mengungkapkannya berbeda), bukan hanya mencocokkan kata persis. Filter khusus mode berjalan bersamaan — Mode Obrolan menarik konteks pribadi, Mode Kerja menarik keputusan proyek dan pola kode.","concepts.memory#7#c":"Memori dibatasi per-pengguna dan per-proyek (memori Anda milik Anda, disimpan terpisah per orang dan per proyek). Rahasia dan kredensial (kata sandi, kunci) diblokir pada batas penyimpanan — mereka tidak akan pernah masuk ke memori.","concepts.desktop-grounding#title":"Hierarki penjangkaran desktop (Pratinjau)","concepts.desktop-grounding#0#c":"Pratinjau — cara Scout memutuskan sumber penjangkaran mana yang digunakan pada setiap langkah.","concepts.desktop-grounding#1#p":"Sebelum Ava bisa mengklik tombol, dia harus benar-benar memahami apa yang ada di layar Anda dan di mana letak semuanya — itulah yang disebut \"penjangkaran\" (menentukan apa fungsi setiap elemen di layar dan posisinya persis). Ada tiga cara untuk melakukannya, dan dia memilih yang paling andal sesuai dengan aplikasi yang sedang Anda gunakan. Ini adalah detail teknis mendalam; poin utamanya adalah dia lebih memilih metode yang pasti dan akurat daripada menebak-nebak dari gambar.","concepts.desktop-grounding#2#p":"Tiga tingkatan, dievaluasi secara berurutan. Sumber andal yang paling efisien menang.","concepts.desktop-grounding#3#h":"1. Jendela browser → Playwright DOM","concepts.desktop-grounding#4#p":"Jika jendela aktif adalah browser web, Ava membaca struktur halaman itu sendiri (\"DOM\" — daftar dasar isi halaman) daripada menebak dari gambar. Membaca strukturnya sekitar 10× lebih andal daripada sekadar melihat piksel — dia tahu persis di mana setiap tombol berada dan kapan halaman selesai dimuat. Ini adalah jalur utama untuk segala sesuatu di web, bukan sekadar cadangan.","concepts.desktop-grounding#5#h":"2. Aplikasi native dengan UIA → Windows UI Automation","concepts.desktop-grounding#6#p":"Untuk aplikasi desktop biasa di Windows, Ava membaca peta aksesibilitas bawaan (\"UIA\", data yang sama yang digunakan pembaca layar untuk menjelaskan jendela) — ini mencantumkan setiap kontrol, namanya, dan lokasinya. Jika peta tersebut memberikan setidaknya lima item yang dapat digunakan dan memiliki nama, dia mempercayainya dan menggunakannya.","concepts.desktop-grounding#7#h":"3. UIA kosong atau tidak berguna → OmniParser vision","concepts.desktop-grounding#8#p":"Ketika peta tersebut hilang atau tidak berguna (beberapa aplikasi, game, dan layar jarak jauh tidak menyediakannya), Ava beralih ke cara melihat langsung tangkapan layar. Alat visi (OmniParser) mendeteksi area yang bisa diklik dan memberi label pada masing-masing, mengubah gambar kembali menjadi daftar yang bisa ditindaklanjuti — dikombinasikan dengan informasi kecil yang mungkin diberikan peta aksesibilitas tadi.","concepts.desktop-grounding#9#c":"OmniParser memerlukan persetujuan (opt-in) pertama kali Ava memerlukannya, dengan pemberitahuan privasi yang jelas. Pengguna BYOK dapat mengarahkan ke instalasi OmniParser lokal mereka sendiri.","concepts.desktop-kill-switches#title":"Tombol darurat desktop (Pratinjau)","concepts.desktop-kill-switches#0#c":"Pratinjau — tiga cara independen untuk menghentikan proses yang sedang berjalan. Cukup salah satu saja yang berhasil.","concepts.desktop-kill-switches#1#p":"\"Tombol darurat\" memang terdengar seperti itu — cara darurat untuk menghentikan Ava secara instan saat dia mengendalikan layar Anda. Yang menenangkan: ada tiga tombol, masing-masing dibangun terpisah, jadi jika satu gagal, yang lain tetap berfungsi. Anda tidak perlu mempelajari ketiganya. Cukup tahu bahwa ketika ada sesuatu yang tampak salah, Anda selalu bisa menghentikannya, dan penghentian terkuat (tombol panik di bawah) tidak bergantung pada kerja sama Ava.","concepts.desktop-kill-switches#2#p":"Setelah mempelajari setiap insiden otonomi publik (kasus nyata di mana agen AI mengabaikan perintah berhenti, menghapus arsip email, atau menghapus drive), kami membuat tiga tombol darurat di tiga lapisan berbeda. Tidak satu pun bergantung pada model AI itu sendiri — jika Ava macet atau tidak merespons, Anda tetap bisa menghentikannya.","concepts.desktop-kill-switches#3#h":"Jeda — spasi atau tombol Jeda","concepts.desktop-kill-switches#4#p":"Membeku di batas langkah berikutnya. Bisa dilanjutkan. Gunakan ini jika ingin ikut campur tanpa kehilangan arah kerja.","concepts.desktop-kill-switches#5#h":"Berhenti — Tekan Escape atau tombol Stop","concepts.desktop-kill-switches#6#p":"Abort bersih. Narator merangkum apa saja yang sudah dikerjakan. Tidak bisa dilanjutkan. Log audit disimpan.","concepts.desktop-kill-switches#7#h":"Kill panik — tekan Escape tiga kali atau Ctrl+Shift+K","concepts.desktop-kill-switches#8#p":"Ini cara berhenti paling keras. Ada program pengawas kecil yang terpisah, memaksa mematikan bagian Ava yang menggerakkan layar Anda. Ia tidak menunggu AI menjawab, tidak perlu jendela aplikasi berjalan, dan tidak peduli kondisi apa pun — ia langsung mematikannya. Gunakan ini jika benar-benar ada sesuatu yang salah.","concepts.desktop-kill-switches#9#p":"Ketiga cara ini juga bekerja lewat aplikasi pendamping. Penggerak mana pun bisa mengakhirinya.","reference.tools#title":"Daftar Alat","reference.tools#0#p":"Ini daftar lengkap semua alat yang dimiliki Ava — \"alat\" hanyalah tindakan spesifik yang bisa dia lakukan, seperti membaca file atau mencari sesuatu. Anda tidak perlu membaca halaman ini. Ava memilih alat yang tepat sendiri setiap waktu. Halaman ini ada agar Anda tahu persis apa saja kemampuannya.","reference.tools#1#p":"Kotak alat bawaan lengkap. Semua alat di sini terdaftar di mesin inti (di balik tiga antarmuka) dan tersedia untuk Ava selama mode dan izin mengizinkan. Anda bisa filter berdasarkan kategori atau tingkat risiko.","reference.tools#2#p":"Tidak perlu menghafal semuanya — tabel di bawah ini hanya sebagai kartu acuan.","reference.tools#4#h":"Tingkat Risiko","reference.tools#5#li0":"Aman — hanya membaca tanpa mengubah apa pun. file_read, glob (mencari file berdasarkan pola nama), grep (mencari teks di dalam file), git_status (Git adalah sistem yang melacak perubahan proyek Anda).","reference.tools#5#li1":"Menulis — mengubah file, menyimpan titik penyimpanan pekerjaan Anda (sebuah \"commit\"), atau menghasilkan sesuatu yang baru. file_edit, git_commit, generate_image.","reference.tools#5#li2":"Berbahaya — menjalankan perintah di komputer Anda (\"shell\"), mengendalikan desktop, mengakses internet, atau bertanya ke database. bash, browser, desktop_*.","reference.tools#6#c":"Spesialis persona memiliki daftar izin alat masing-masing. Scout bisa membaca tetapi tidak menulis. Builder memiliki akses penuh. Challenger tidak memiliki alat sama sekali — tugasnya adalah mempertanyakan rencana.","reference.models#title":"Model AI","reference.models#0#p":"\"Model\" adalah otak AI yang melakukan pemikiran — Qwen, DeepSeek, Mistral, dan lainnya. Halaman ini mencantumkan semua model yang bisa digunakan Ava. Singkatnya: Anda tidak perlu memilih salah satu. Ava memilih model yang tepat untuk setiap langkah sendiri. Lanjutkan membaca hanya jika Anda ingin memahami atau mengubah hal tersebut.","reference.models#1#p":"Semua model yang bisa dialihkan ke Ava, ditambah tiga strategi pengaturan terkoordinasi — aturan yang menentukan model mana menangani setiap bagian pekerjaan. Pilih mode penyaluran dan biarkan Ava mengatur, atau pilih satu model saja dan lewati penyaluran sepenuhnya.","reference.models#2#h":"Mode Penyaluran","reference.models#3#p":"Tiga strategi yang diatur secara terpadu. Alur kerja persona yang sama (tim kecil spesialis pembantu yang dijalankan Ava di belakang layar) berjalan di ketiganya; yang berubah adalah kumpulan model dasarnya. Pilih mode di pemilih model dan Ava akan menangani sisanya. Setiap kartu di bawah menunjukkan spesialis penyusun yang dituju oleh konduktor.","reference.models#4#p":"Anda tidak perlu menghafal kartu di bawah ini — mereka ada agar Anda bisa melihat apa saja yang menyusun setiap strategi.","reference.models#6#c":"Aurora sengaja hanya menggunakan Mistral. Jika model Mistral tidak tersedia, router mengembalikan error daripada mengalihkan lintas — itulah jaminan stack UE. Pilih Maestro atau Supernova untuk penurunan kinerja yang wajar.","reference.models#7#c":"Ketiga mode tersedia secara universal — baik menggunakan kredit platform maupun kunci Anda sendiri. BYOK menambahkan opsi untuk melewati pengaturan terkoordinasi dan mengendalikan satu model secara langsung.","reference.models#8#h":"Model Kelola Platform","reference.models#9#p":"Tersedia di setiap paket, termasuk tier gratis. Token (satuan teks tempat AI diukur — kira-kira tiga perempat kata per token) dihitung terhadap kuota paket Anda. Kunci (kata sandi pribadi yang membuka setiap model berbayar) diputar dan dimonitor oleh platform — tidak perlu Anda konfigurasi apa pun.","reference.models#11#h":"Bawa kunci Anda sendiri","reference.models#12#p":"Sebuah \"kunci API\" adalah kata sandi pribadi yang memungkinkan perangkat lunak menggunakan layanan berbayar pada akun Anda sendiri. \"BYOK\" hanya berarti \"bawa kunci Anda sendiri\" — menggunakan milik Anda alih-alih milik kami. Tempelkan kunci API Anda di pengaturan. Permintaan BYOK berjalan langsung dari Ava ke penyedia (perusahaan yang menjalankan model) — mereka tidak melewati infrastruktur kami dan tidak mengonsumsi token platform. Anda membayar penyedia; kami tidak melihat lalu lintasnya.","reference.models#14#c":"Untuk skor benchmark, tag kemampuan, dan pembandingan berdampingan, lihat halaman Model lengkap di ava-supernova.com/models. Harga yang ditampilkan di atas adalah estimasi terbaik kami terhadap tarif setiap penyedia saat publikasi — selalu periksa situs web penyedia sebelum memulai pekerjaan tersebut.","reference.personas#title":"Orkestrasi persona","reference.personas#0#p":"Sebuah \"persona\" adalah peran pembantu yang dimainkan Ava di belakang layar untuk pekerjaan yang lebih sulit — seorang penjelajah, perencana, atau pemeriksa fakta. Anda tidak pernah berbicara langsung dengan mereka dan Anda tidak perlu memahami halaman ini untuk menggunakan Ava. Ini ada di sini ketika Anda penasaran bagaimana dia memecah pekerjaan besar menjadi tim ahli kecil.","reference.personas#1#p":"24 spesialis di 5 tim mode. Konduktor (pembantu yang mengoordinasikan sisanya) memutuskan tim mana yang berjalan, dalam urutan apa, dan dengan konteks apa. Mode Chat tidak memiliki persona — itu adalah Ava sendiri.","reference.personas#2#h":"Bagaimana orkestrasi berjalan","reference.personas#3#li0":"Anda mengirim pesan dalam mode Plan, Teach, Security, atau Brainstorm (atau permintaan Work yang kompleks).","reference.personas#3#li1":"Konduktor membaca permintaan, memilih tim mode, dan membangun rencana eksekusi — beberapa persona berjalan secara berurutan, beberapa dalam gelombang paralel.","reference.personas#3#li2":"Setiap persona memiliki prompt sistem sendiri, daftar izin alat yang dibatasi, dan kolam konteks bersama mengenai apa yang ditemukan persona sebelumnya.","reference.personas#3#li3":"Persona terakhir menghasilkan ringkasan, rencana, atau laporan, tergantung mode.","reference.personas#3#li4":"Ava menyajikan hasil kepada Anda. Anda menyetujui, mengubah, atau mengarahkan ulang.","reference.personas#4#p":"Daftar penuh di bawah ini hanya referensi — tidak perlu menghafal siapa melakukan apa. Ava merakit tim yang tepat untuk Anda.","reference.personas#6#c":"Mode Work hanya memanggil tim penuh untuk tugas kompleks. Edit sederhana dijalankan Ava langsung — tanpa beban orkestrasi tambahan.","reference.config#title":"Konfigurasi","reference.config#0#p":"Halaman ini menunjukkan tempat Ava menyimpan pengaturan dan file di komputer Anda. Anda hampir tidak pernah perlu mengubahnya secara manual — aplikasi yang mengelolanya untuk Anda. Halaman ini tersedia jika Anda ingin melihat, mencadangkan, atau berbagi file tersebut sendiri.","reference.config#1#p":"Ava membaca konfigurasi (pengaturan tersimpannya) dari dua cakupan. Pengaturan global — yang berlaku di mana saja — disimpan dalam folder bernama ~/.ava/ (\"~\" adalah singkatan untuk folder rumah Anda). Pengaturan per-proyek disimpan dalam folder .ava/ di dalam proyek itu sendiri.","reference.config#2#h":"Global — ~/.ava/","reference.config#3#li0":"settings.json — preferensi model, mode izin, kepribadian, bahasa.","reference.config#3#li1":"memory/ — memori global Anda (preferensi, keputusan yang berlaku di mana saja).","reference.config#3#li2":"tasks.json — daftar tugas lintas proyek.","reference.config#3#li3":"journal/ — entri jurnal harian, terorganisir berdasarkan tanggal.","reference.config#4#h":"Proyek — .ava/","reference.config#5#li0":"instructions.md — instruksi spesifik proyek yang selalu dimuat Ava. Konteks yang tetap (\"kami menggunakan pnpm, bukan npm\", \"kunci API ada di 1Password\").","reference.config#5#li1":"context.md — catatan proyek bebas opsional.","reference.config#5#li2":"memory/ — memori yang dibatasi untuk proyek ini.","reference.config#5#li3":"datasets/config.json — konfigurasi penangkapan dataset pilihan.","reference.config#6#c":"Tambahkan .ava/ ke .gitignore Anda (daftar file yang diberitahu Git untuk tidak disertakan dalam proyek bersama) jika Anda tidak ingin membagikan memori dengan tim Anda. Simpan instructions.md di repositori (folder proyek bersama) — begitulah cara Ava mempelajari konvensi proyek.","reference.shortcuts#title":"Pintasan keyboard","reference.shortcuts#0#p":"Pintasan keyboard adalah percepatan opsional — semuanya juga merupakan tombol yang bisa Anda klik. Kunjungi halaman ini hanya jika Anda ingin menggunakan Ava lebih cepat lewat keyboard.","reference.shortcuts#1#p":"Pintasan berdasarkan antarmuka (setiap dari tiga tempat Ava berjalan: ekstensi VS Code, aplikasi desktop, dan terminal). Sesuaikan di pengaturan setiap antarmuka. Tidak perlu menghafal daftar di bawah ini.","reference.project-context#title":"Konteks Proyek","reference.project-context#0#p":"Ini menjelaskan bagaimana Ava mempelajari proyek Anda sebelum memulai — file apa saja yang dia lihat untuk memahami apa yang sedang Anda kerjakan. Anda tidak perlu mengatur ini; dia melakukannya sendiri. Baca jika ingin tahu di mana menaruh catatan agar dia selalu melihatnya.","reference.project-context#1#p":"Ava memuat beberapa lapisan konteks (informasi latar belakang yang dia ingat) saat Anda membuka proyek. Memahami lapisannya membantu Anda menempatkan informasi di tempat yang tepat.","reference.project-context#2#h":"Dimuat secara otomatis","reference.project-context#3#li0":".ava/instructions.md — dianggap sebagai panduan tahan lama dan prioritas tinggi. Selalu ada dalam konteks.","reference.project-context#3#li1":".ava/context.md — catatan bebas. Dimuat, prioritas lebih rendah.","reference.project-context#3#li2":"README.md — dipindai pada jalankan pertama untuk ringkasan proyek.","reference.project-context#3#li3":"package.json / pyproject.toml / Cargo.toml — file kecil yang mendaftar pengaturan proyek; dibaca untuk mendeteksi bahasa, framework, dan perintah tes.","reference.project-context#3#li4":".gitignore — daftar file yang harus ditinggalkan dari kontrol versi; dihormati oleh semua alat file (glob, grep, project_index).","reference.project-context#4#h":"Dimuat sesuai permintaan","reference.project-context#5#p":"\"Sesuai permintaan\" berarti Ava hanya mengambil ini ketika tugas benar-benar membutuhkannya, bukan di awal.","reference.project-context#6#li0":"Indeks proyek — peta terstruktur dari file Anda dan bagian bernama di dalamnya (fungsi, kelas — \"simbol\") dan bagaimana mereka terhubung (\"impor\"). Dibangun saat dibutuhkan, artinya hanya saat Ava memerlukannya.","reference.project-context#6#li1":"Riwayat Git — catatan perubahan masa lalu; diambil ketika git_status, git_diff, atau git_create_pr dipanggil (Git adalah alat yang melacak setiap perubahan ke proyek; \"PR\" adalah permintaan tarik, usulan batch perubahan).","reference.project-context#6#li2":"Memori — entri cocok berdasarkan makna (\"semantik\") dan dimasukkan satu giliran demi satu giliran, bukan sekaligus.","reference.project-context#7#c":"Letakkan konvensi di instructions.md. Letakkan catatan di context.md. Biarkan memori menangkap sisanya secara mandiri.","features.unified-panel#title":"Panel terpadu","features.unified-panel#0#p":"Secara sederhana: semua yang dilakukan Ava tinggal di satu jendela, jadi Anda tidak perlu mencari-cari melalui tab untuk menemukannya.","features.unified-panel#1#p":"Satu panel untuk obrolan, dasbor, memori, tugas, dan jurnal. Tidak ada pergantian konteks antar jendela. Sidebar memilih apa yang Anda lihat; area utama berganti untuk mencocokkan.","features.unified-panel#2#p":"Status percakapan tetap ada saat Anda berpindah — buka memori, periksa tugas, lalu kembali. Obrolan masih ada, masih mengalir jika Ava masih berjalan.","features.unified-panel#3#c":"Panel terpadu adalah konsep ekstensi dan IDE. Permukaan web menggunakan tab browser.","features.knowledge-packs#title":"Paket pengetahuan","features.knowledge-packs#0#p":"Secara sederhana: berikan Ava folder dokumen Anda sendiri, dan dia bisa membacanya untuk menjawab pertanyaan Anda. \"Paket pengetahuan\" hanyalah bundel file itu — materi referensi yang diizinkan dia gunakan.","features.knowledge-packs#1#p":"Seret direktori materi referensi (spesifikasi, RFCs, catatan rapat, dokumentasi API) ke dalam paket pengetahuan. Ava dapat menarik bagian yang relevan ke dalam konteks saat percakapan menyentuh topik tersebut.","features.knowledge-packs#2#p":"Paket diindeks secara lokal. Pengambilan bersifat semantik — Ava menemukan dokumen yang tepat berdasarkan makna, bukan nama file. (\"Semantik\" berarti dia mencocokkan apa yang dibahas dokumen, jadi Anda tidak perlu mengingat kata-kata persis atau nama file.) Paket dapat dibagikan dengan tim atau disimpan pribadi.","features.workflows#title":"Alur Kerja","features.workflows#0#p":"Secara sederhana: ajarkan Ava rutinitas yang Anda lakukan berulang kali, beri nama, dan dia bisa menjalankannya lagi kapan saja. \"Alur kerja\" hanyalah rutinitas tersimpan — serangkaian langkah yang diulang Ava untuk Anda.","features.workflows#1#p":"Simpan urutan langkah yang sering Anda ulangi — tinjau PR → jalankan tes → tulis catatan rilis → draf email. Alur kerja adalah rencana yang dapat digunakan ulang yang bisa diputar ulang oleh Ava dengan input berbeda.","features.workflows#2#p":"Alur kerja disimpan per proyek dalam folder bernama .ava/workflows/ di dalam proyek Anda. Bagikan dengan tim Anda dengan menyimpan direktori tersebut (menyimpannya ke dalam proyek bersama agar rekan tim juga mendapatkannya).","features.events#title":"Event dan notifikasi","features.events#0#p":"Secara sederhana: saat Ava bekerja, Anda mendapatkan daftar langkah demi langkah yang rapi tentang apa yang sedang dilakukannya, serta notifikasi ketika pekerjaan lama selesai sehingga Anda bisa istirahat sejenak.","features.events#1#p":"Saat Ava berjalan, Anda melihat pembaruan terstruktur, bukan tumpukan teks. Setiap panggilan alat, setiap perpindahan persona, setiap update kecil yang mengalir adalah event diskrit di antarmuka — dapat diperluas untuk detail, dikolaps untuk ringkasan.","features.events#2#p":"Jalankan di latar belakang mengirimkan notifikasi tingkat sistem operasi saat selesai. Anda bisa meninggalkan proses build yang lama dan Ava akan memberitahu Anda ketika sudah selesai.","features.personality#title":"Desainer Kepribadian","features.personality#0#p":"Secara sederhana: sesuaikan cara Ava berbicara dengan Anda — banyak bicara atau singkat, formal atau santai, lebih banyak lelucon atau sedikit — agar terdengar seperti yang Anda suka.","features.personality#1#p":"Bentuk cara Ava berbicara dengan Anda. Nada, energi, kerincian (seberapa banyak yang ia katakan), formalitas, humor. Slider dan preset — insinyur singkat, mentor hangat, rekan kerja kering, atau campuran Anda sendiri.","features.personality#2#p":"Kepribadian mempengaruhi pengungkapan kata, bukan kompetensi. Dia masih menjalankan alat yang sama dan mengikuti aturan izin yang sama. Namanya terkunci pada Ava — itu tidak bisa ditawar.","features.release-notes#title":"Catatan Rilis","features.release-notes#0#p":"Secara sederhana: daftar terus-menerus tentang apa yang baru dan apa yang diperbaiki dalam setiap pembaruan, sehingga Anda dapat melihat apa yang berubah.","features.release-notes#1#p":"Catatan perubahan dalam aplikasi (changelog adalah riwayat perubahan). Setiap versi yang dikirimkan dengan sorotan, perbaikan bug, dan perubahan besar (perubahan yang mungkin mengharuskan Anda menyesuaikan cara menggunakan sesuatu). Antarmuka web mempertahankan versi publik di ava-supernova.com/releases.","troubleshooting.common-errors#title":"Kesalahan Umum","troubleshooting.common-errors#0#p":"Sebagian besar kesalahan memiliki penyebab singkat dan spesifik. Berikut adalah yang umum terjadi dan cara memperbaikinya. Jangan khawatir jika bahasanya terdengar teknis — setiap poin di bawah ini menjelaskan apa yang sebenarnya Anda lihat dan persis apa yang harus dilakukan.","troubleshooting.common-errors#1#h":"Model tidak merespons","troubleshooting.common-errors#2#p":"Yang Anda lihat: Ava diam dan tidak membalas.","troubleshooting.common-errors#3#p":"Periksa indikator status di header obrolan. Jika tertulis \"connecting\", penyedia Anda (layanan AI tempat Ava berbicara) dapat dijangkau tetapi lambat — beri waktu tiga puluh detik. Jika tertulis \"unavailable\", Ava otomatis beralih ke model berikutnya dalam rantai (dia secara otomatis mengganti ke model cadangan). Jika sama sekali tidak ada, periksa kunci API Anda di Pengaturan dan uji koneksi. (Kunci API adalah kata sandi pribadi yang memungkinkan Ava menggunakan layanan AI berbayar.)","troubleshooting.common-errors#4#h":"Panggilan alat gagal","troubleshooting.common-errors#5#p":"Yang Anda lihat: salah satu langkah Ava (\"panggilan alat\" — dia membaca file, menjalankan perintah, dan sebagainya) menampilkan error merah alih-alih selesai.","troubleshooting.common-errors#6#p":"Klik panggilan alat yang gagal untuk melihat errornya. Penyebab umum: dia mencoba menyentuh file di luar folder proyek Anda, yang diblokir sengaja demi keamanan Anda (pengaman ini disebut perlindungan \"path traversal\" — mencegah dia berkeliaran keluar dari folder tempat Anda bekerja); perintah yang perlu dijalankan di folder berbeda; atau file yang telah dipindahkan sejak Ava terakhir kali memeriksanya. Beritahu dia apa yang salah — dia akan mencoba lagi dengan perbaikan.","troubleshooting.common-errors#7#h":"Memori tidak mengingat","troubleshooting.common-errors#8#p":"Yang Anda lihat: Ava tidak menemukan sesuatu yang Anda yakin dia harus ingat.","troubleshooting.common-errors#9#p":"Memori bekerja berdasarkan makna, bukan kata-kata tepat (ini maksudnya \"semantik\"). Jadi \"Apa yang saya putuskan tentang auth?\" lebih baik daripada \"cari keputusan auth saya\". Jika memori pasti ada tetapi tidak muncul, buka browser memori dan cari — jika tidak ada, itu tidak pernah disimpan sejak awal.","troubleshooting.common-errors#10#h":"Masuk berulang (loop)","troubleshooting.common-errors#11#p":"Yang Anda lihat: Anda masuk, tetapi Ava terus meminta Anda masuk lagi — sebuah loop yang tidak pernah mengizinkan Anda melanjutkan.","troubleshooting.common-errors#12#p":"Solusinya adalah menghapus detail masuk tersimpan dan mulai ulang: di ekstensi jalankan \"Ava: Sign Out\" dari palet perintah, di IDE gunakan Pengaturan → Akun → Keluar, di CLI hapus file di ~/.ava/auth.json (file masuk kecil di folder bernama .ava di direktori rumah Anda). Kemudian masuk lagi.","troubleshooting.common-errors#13#h":"Token habis","troubleshooting.common-errors#14#p":"Yang Anda lihat: pesan bahwa Anda kehabisan penggunaan gratis untuk bulan ini. (\"Token\" adalah cara penggunaan AI diukur — \"habis\" hanya berarti Anda telah menghabiskan kuota gratis bulan ini.)","troubleshooting.common-errors#15#p":"Anggaran bulanan paket gratis direset pada tanggal 1 setiap bulan. Sampai saat itu, beralih ke penyedia BYOK (gunakan kunci API Anda sendiri) untuk tetap bekerja. Akun Anda tetap aktif — hanya permintaan yang dikelola platform gratis yang dihentikan.","troubleshooting.logs#title":"Di mana log berada","troubleshooting.logs#0#p":"\"Log\" hanyalah buku harian yang komputer Anda simpan tentang apa yang terjadi — berguna ketika sesuatu rusak dan Anda (atau dukungan) perlu melihat detailnya.","troubleshooting.logs#1#p":"Ketika Anda butuh gambaran mentah — alat apa yang dipanggil, informasi apa yang didapat, apa yang dikembalikan layanan AI — log adalah file teks biasa di folder pada komputer Anda di ~/.ava/logs/ (folder bernama .ava di direktori rumah Anda, dengan folder logs di dalamnya).","troubleshooting.logs#2#li0":"~/.ava/logs/session-<date>.log — transkrip per sesi termasuk panggilan alat, respons streaming, dan error.","troubleshooting.logs#2#li1":"~/.ava/logs/extension.log — log host ekstensi VS Code. Kegagalan aktivasi, error panel.","troubleshooting.logs#2#li2":"~/.ava/logs/ide.log — log IDE desktop. Pesan proses sidecar, Rust panics.","troubleshooting.logs#2#li3":"~/.ava/logs/cli.log — log REPL CLI.","troubleshooting.logs#3#p":"Di ekstensi, \"Ava: Show Logs\" di palet perintah membuka log terkait di tab editor. Di IDE, Pengaturan → Diagnostik memiliki tombol \"Open Logs\". CLI dapat mengikuti lognya sendiri dengan ava logs --follow.","troubleshooting.logs#4#c":"Log mungkin memuat potongan file proyek yang dibaca Ava selama sesi. Periksa dulu sebelum dibagikan.","troubleshooting.support-request#title":"Mengajukan Permintaan Dukungan","troubleshooting.support-request#0#p":"Secara sederhana: jika ada sesuatu yang bermasalah dan perbaikan di atas belum berhasil, beri tahu kami. Cara termudah cukup minta Ava yang melakukannya untuk Anda.","troubleshooting.support-request#1#p":"Jika masalah tidak tercakup oleh kesalahan umum, buat tiket dukungan (kirim permintaan bantuan ke tim kami). Anda bisa melakukannya di dalam Ava (tanpa perlu mengisi formulir) atau melalui web.","troubleshooting.support-request#2#h":"Dari dalam Ava","troubleshooting.support-request#3#p":"Minta Ava yang membuatnya. \"Ava, bisakah kamu membuat tiket dukungan tentang ini?\" Dia akan memanggil support_request, melampirkan konteks sesi yang relevan (dengan kredensial disensor), lalu mengirimkannya. Jalur paling cepat.","troubleshooting.support-request#4#h":"Dari web","troubleshooting.support-request#5#p":"Kunjungi ava-supernova.com/support. Pilih kategori (bug, fitur, akun, keamanan, umum) dan jelaskan apa yang terjadi. Kami akan merespons dalam satu hari kerja.","troubleshooting.support-request#6#h":"Apa yang Harus Disertakan","troubleshooting.support-request#7#li0":"Apa yang sedang Anda coba lakukan.","troubleshooting.support-request#7#li1":"Apa yang sebenarnya terjadi.","troubleshooting.support-request#7#li2":"Platform mana (ekstensi, IDE, CLI, aplikasi pendamping) dan versinya.","troubleshooting.support-request#7#li3":"Pesan error atau cuplikan log apa pun. Sembunyikan kredensial terlebih dahulu.","troubleshooting.security-disclosure#title":"Melaporkan Masalah Keamanan","troubleshooting.security-disclosure#0#p":"Secara sederhana: jika Anda menemukan celah agar Ava bisa diretas atau disalahgunakan (sebuah \"kerentanan\" — kelemahan keamanan), beri tahu kami secara pribadi dulu agar kami bisa memperbaikinya sebelum dimanfaatkan orang lain. Halaman ini adalah caranya.","troubleshooting.security-disclosure#1#p":"Menemukan kerentanan? Terima kasih. Kami menangani setiap laporan dengan serius dan bekerja sama dengan Anda untuk memperbaikinya sebelum pengungkapan publik (sebelum masalah diumumkan secara terbuka).","troubleshooting.security-disclosure#2#h":"Cara Melaporkan","troubleshooting.security-disclosure#3#li0":"Kirim email ke security@ava-supernova.com dengan deskripsi, langkah reproduksi, dan periode pengungkapan yang Anda inginkan.","troubleshooting.security-disclosure#3#li1":"Atau buat tiket dukungan dengan kategori \"keamanan\" — masuk antrian penapisan yang sama.","troubleshooting.security-disclosure#3#li2":"Kami akan memberikan konfirmasi dalam 24 jam.","troubleshooting.security-disclosure#4#h":"Komitmen Kami","troubleshooting.security-disclosure#5#li0":"Pengungkapan terkoordinasi — kami sepakat jadwal dengan Anda sebelum apa pun dipublikasikan. Standar adalah 90 hari.","troubleshooting.security-disclosure#5#li1":"Penghargaan — nama Anda dicantumkan dalam catatan perbaikan kecuali Anda memilih anonimitas.","troubleshooting.security-disclosure#5#li2":"Tidak ada tindakan hukum — riset dengan niat baik sangat dihargai. Kami tidak akan mengirimkan pengacara untuk mengejar Anda.","troubleshooting.security-disclosure#6#c":"Halaman keamanan di ava-supernova.com/security memiliki rincian lengkap — jaminan arsitektur, alat penyensor, gerbang izin.","features.office-suite#title":"Office Suite","features.office-suite#0#p":"Butuh laporan, email, atau dokumen yang ditulis? Ava bisa menyusunnya dan memberikan file Word, Excel, atau PDF asli yang bisa Anda buka dan edit seperti biasa.","features.office-suite#1#p":"Laporan, email, dan dokumen — disusun, diformat, dan diekspor ke format asli (.docx adalah Word, .xlsx adalah Excel, .pdf adalah PDF).","features.office-suite#2#li0":"report_generate — .docx terstruktur yang mengambil dari tugas, jurnal, memori, dan status proyek.","features.office-suite#2#li1":"email_draft — email terkendali nada ke file .docx.","features.office-suite#2#li2":"document_manage — buat, baca, edit, ekspor untuk Word, Excel, PDF, CSV, Markdown.","features.office-suite#3#p":"Berguna saat Ava menulis atas nama Anda — laporan status, presentasi awal, pembaruan klien. File .docx akan masuk ke proyek Anda tempat Anda bisa merapikannya.","features.dashboard-library#title":"Pustaka Dashboard","features.dashboard-library#0#p":"Secara sederhana: satu rak yang menyimpan semua yang Anda dan Ava buat dan bicarakan, agar tidak ada yang hilang.","features.dashboard-library#1#p":"Tampilan yang bisa dijelajahi dari semua yang telah Ava hasilkan bersama Anda — gambar, video, audio, dokumen yang dihasilkan — bersama percakapan, kenangan, dan tugas Anda. Satu tempat untuk menemukan sesuatu yang Anda buat minggu lalu.","features.document-preview#title":"Pratinjau Dokumen","features.document-preview#0#p":"Secara sederhana: lihat isi dokumen tepat di tempat Anda berada, tanpa membuka program terpisah untuk membacanya.","features.document-preview#1#p":"Klik kanan pada file Word doc, Excel sheet, PDF, CSV, HTML, atau Markdown di proyek Anda — pratinjau langsung tanpa meninggalkan editor. Berguna untuk membaca materi referensi yang dihasilkan Ava atau file yang ditinggalkan kolaborator.","features.daily-briefing#title":"Briefing Harian","features.daily-briefing#0#p":"Secara sederhana: catatan singkat \"ini posisi terakhir Anda\" setiap pagi, agar Anda bisa melanjutkan tanpa membaca ulang semuanya.","features.daily-briefing#1#p":"Ringkasan pagi: jurnal kemarin, tugas terbuka, status proyek, dan pengingat apa pun yang telah Ava atur. Opsional — nyalakan di pengaturan.","features.daily-briefing#2#p":"Briefing ini menggunakan memori untuk menampilkan konteks relevan (\"terakhir kali Anda bekerja pada alur autentikasi, Anda mencatat ingin meninjau kembali strategi token refresh\"). Bukan feed berita — update fokus.","start.what#title":"Apa itu Ava?","start.what#0#p":"Ava adalah AI yang benar-benar melakukan hal-hal — bukan sekadar bicara. Dia akan membuatkanmu aplikasi, menulis dokumen untukmu, mengajarimu sesuatu dari awal, mendesain logomu, atau mengurus administrasi yang terus kamu tunda. Dan dia mengingatmu: apa yang sedang kamu kerjakan, bagaimana kamu menyukai hal-hal, apa yang kamu minta minggu lalu.","start.what#1#p":"Ada satu Ava, dan dia bekerja di mana pun kamu bekerja — di editor kodemu, sebagai aplikasi desktop, di ponselmu, atau di terminal. Memori sama, kepribadian sama, di mana saja.","start.what#2#h":"Apa yang membuatnya berbeda","start.what#3#li0":"Milikmu secara default. Karyamu tetap di komputermu sendiri. Tidak ada pelacakan, tidak ada telemetri — selamanya.","start.what#3#li1":"Terbuka untuk siapa saja melihat. Setiap baris Ava bersifat publik. Tidak perlu percaya begitu saja.","start.what#3#li2":"Gratis untuk memulai. 300 kredit setiap bulan, tanpa kartu, tanpa jebakan — atau pasang kunci AI-mu sendiri dan tidak perlu membayar kami sedikit pun.","start.what#3#li3":"Mengajar gratis, selamanya. Belajar seharusnya tidak memiliki harga.","start.what#4#p":"Pernah menulis kode? Halaman berikutnya ditulis khusus untukmu. Sudah teknis? Lompat ke depan — dia akan mengikutimu.","start.what#deeper#0#h":"Di mana Ava tinggal","start.what#deeper#1#li0":"Ekstensi VS Code — Ava di samping editormu: panel obrolan, dashboard, dan perubahan ditampilkan langsung sebelum terjadi.","start.what#deeper#1#li1":"IDE Desktop — aplikasi mandiri dengan semua fitur dalam satu jendela. Menambahkan kontrol desktop (membuka aplikasi, mengklik, mengetik untukmu).","start.what#deeper#1#li2":"Pendamping — aplikasi mobile saat kamu jauh dari meja: tugas, jurnal, memori, obrolan cepat.","start.what#deeper#1#li3":"CLI — Ava di terminalmu, untuk orang-orang yang hidup di sana.","start.what#deeper#2#h":"Bagaimana cara kerjanya, singkatnya","start.what#deeper#3#p":"Ava beralih mindset (disebut mode) untuk menyesuaikan pekerjaan, tanpa kamu sadari menjalankan tim kecil spesialis pembantu pada pekerjaan sulit, dan memilih model AI terbaik untuk setiap langkah secara otomatis. Kamu tidak pernah mengelola apapun itu. Bagian Konsep Inti memiliki tur lengkap kapanpun kamu penasaran.","start.first-five#title":"Hal pertama yang kamu lakukan dengan Ava","start.first-five#0#p":"Cara tercepat mendapatkan Ava adalah meminta sesuatu yang nyata dan melihatnya melakukannya. Tidak ada panduan pengaturan yang harus dibaca, tidak ada yang dipelajari dulu — cukup beri tahu dia apa yang kamu inginkan, dengan kata-kata biasa.","start.first-five#1#h":"Coba ini sekarang","start.first-five#2#li0":"Buka obrolan.","start.first-five#2#li1":"Ketik sesuatu yang benar-benar kamu inginkan. Coba \"jelaskan apa yang dilakukan proyek ini\", atau \"tambahkan tombol yang menghapus formulir\".","start.first-five#2#li2":"Ava menunjukkan apa yang akan dia lakukan — dan menunggu.","start.first-five#2#li3":"Puas dengan itu? Katakan ya. Lihat dia melakukannya.","start.first-five#3#p":"Itulah irama utuhnya: kamu bertanya, dia menunjukkan rencana, kamu menyetujui, dia melakukannya. Dia tidak pernah mengubah apa pun tanpa menunjukkannya kepadamu dulu — jadi kamu tidak bisa merusak apa pun hanya dengan mencoba.","start.first-five#4#h":"Beberapa hal yang layak diminta","start.first-five#5#li0":"Sebuah pertanyaan — \"kenapa halaman saya kosong?\", \"file ini fungsinya apa?\"","start.first-five#5#li1":"Sesuatu yang dibuat — \"buatkan saya halaman daftar tugas sederhana\".","start.first-five#5#li2":"Untuk belajar sesuatu — \"ajar saya Python dari nol\". (Selalu gratis.)","start.first-five#5#li3":"Sebuah dokumen — \"tuliskan proposal proyek satu halaman untuk saya\". Dia akan memberikan Anda file Word atau PDF.","start.first-five#6#c":"Tidak yakin harus mengetik apa? Bicaralah padanya seperti teman yang paham. Kata-kata biasa sudah tepat — Anda tidak perlu istilah teknis untuk memulai.","start.first-five#deeper#0#p":"Loop sederhana itu sebenarnya bekerja cukup banyak di belakang layar. Anda tidak butuh ini semua untuk menggunakan Ava — tapi beginilah yang sebenarnya terjadi jika Anda penasaran.","start.first-five#deeper#1#h":"Alat dan persetujuan","start.first-five#deeper#2#p":"Saat Ava membaca file, menjalankan perintah, atau mengedit kode, masing-masing itu adalah \"panggilan alat\". Dia bertanya sebelum melakukan apa pun yang menyentuh file atau sistem Anda — seberapa sering dia bertanya diatur oleh mode izin Anda (tanya setiap kali, tanya hanya untuk hal berisiko, atau langsung saja).","start.first-five#deeper#3#h":"Mode — kondisi pikirannya","start.first-five#deeper#4#p":"Ava bekerja dalam mode: pola pikir ditambah toolkit yang tepat untuk pekerjaan. Ganti kapan saja dari pemilih, atau ketik awalan di awal pesan Anda. Ada tujuh.","start.first-five#deeper#6#h":"Spesialis dan perutean","start.first-five#deeper#7#p":"Pada pekerjaan yang lebih sulit, Ava menjalankan tim kecil spesialis pembantu di belakang layar (perencana, pemeriksa, pembangun) dan mengarahkan setiap langkah ke model yang paling ahli di situ. Anda tidak pernah mengelola ini — dia yang mengoordinasikannya untuk Anda.","start.local-vs-cloud#title":"Lokal vs cloud, dalam satu paragraf","start.local-vs-cloud#0#p":"Semua yang dilakukan Ava bersifat lokal kecuali Anda secara eksplisit memilih ikut. Memori, tugas, jurnal, kepribadian, pengaturan — semuanya disimpan di mesin Anda di ~/.ava/ dan .ava/ (per proyek). Dia berkomunikasi dengan penyedia model lewat HTTPS untuk menjalankan permintaan Anda, lalu kembali ke perangkat Anda. Dia tidak menghubungi server. Dia tidak mengumpulkan telemetri. Dia tidak melatih pada kode Anda.","start.local-vs-cloud#1#p":"Jika Anda masuk, Anda mendapat 300 kredit gratis sebulan untuk model yang dikelola platform (Qwen, MiniMax) dan sinkronisasi cloud opsional untuk memori dan pengaturan di berbagai mesin. Sinkronisasi per-fitur, bisa dicabut kapan saja. Bawa kunci API sendiri dan Ava bekerja penuh tanpa akun.","start.local-vs-cloud#2#c":"Aturannya: lokal itu prioritas utama. Cloud bersifat tambahan.","start.first-model#title":"Apakah saya perlu memilih AI?","start.first-model#0#p":"Ini kabar baik: Anda tidak memilih AI-nya. Ava memilih yang tepat untuk setiap langkah secara otomatis, jadi Anda dapat hasil bagus tanpa harus memikirkannya.","start.first-model#1#p":"Satu-satunya hal yang bisa Anda pilih adalah gaya perutean — dan yang default cocok untuk hampir semua orang. Anda hanya butuh yang lain untuk alasan khusus.","start.first-model#2#h":"Tiga gaya","start.first-model#3#li0":"Maestro — yang default. Tenang, terpercaya, terprediksi. Bingung? Ini yang dipilih.","start.first-model#3#li1":"Supernova — untuk kerja berat, multi-langkah, di mana lebih baik menempatkan spesialis berbeda untuk setiap bagian pekerjaan.","start.first-model#3#li2":"Aurora — untuk saat data Anda harus tetap di UE (sektor publik, kesehatan, privasi ketat). Berjalan sepenuhnya pada AI bobot terbuka Eropa.","start.first-model#4#p":"Ganti kapan saja dari pemilih model di atas obrolan. Tidak ada yang terkunci.","start.first-model#5#c":"Ingin mengendalikan satu model spesifik sendiri? Bisa — buka \"Tampilkan detail\".","models.routing#deeper#1#h":"Bersebelahan","models.routing#deeper#2#th0":"","models.routing#deeper#2#th1":"Maestro","models.routing#deeper#2#th2":"Supernova","models.routing#deeper#2#th3":"Aurora","models.routing#deeper#2#td0.0":"Koordinator","models.routing#deeper#2#td0.1":"Qwen 3.6 Plus","models.routing#deeper#2#td0.2":"DeepSeek V4 Pro (1.6T / 49B aktif, 1M konteks)","models.routing#deeper#2#td0.3":"Mistral Large 3 (675B / 41B aktif, 262K konteks)","models.routing#deeper#2#td1.0":"Pembangun","models.routing#deeper#2#td1.1":"Qwen 3.6 Plus (menggunakan ulang koordinator)","models.routing#deeper#2#td1.2":"Qwen 3.6 Plus","models.routing#deeper#2#td1.3":"Mistral Medium 3.5 (128B padat, 256K konteks)","models.routing#deeper#2#td2.0":"Spesialis tingkat menengah","models.routing#deeper#2#td2.1":"—","models.routing#deeper#2#td2.2":"DeepSeek V4 Flash (peninjau kode, pengecek fakta, pengumpulan data, pemindai, pemeriksa keamanan, dll.)","models.routing#deeper#2#td2.3":"Mistral Medium 3.5 (Arsitek, Pengecek, Pengurut, Guru, Pelapor, dll.)","models.routing#deeper#2#td3.0":"Tingkat ringan / Gerbang Niat","models.routing#deeper#2#td3.1":"Qwen 3.5 Flash","models.routing#deeper#2#td3.2":"Qwen 3.5 Flash (Penjelajah, Pengecek, Pengurut, Penantang, Pengintegrasi)","models.routing#deeper#2#td3.3":"Mistral Small 4","models.routing#deeper#2#td4.0":"Spesialis berat","models.routing#deeper#2#td4.1":"—","models.routing#deeper#2#td4.2":"—","models.routing#deeper#2#td4.3":"Mistral Large 3 (Peneliti, Penantang, Peneliti CVE, Pencetus Ide, Pengecek Fakta)","start.glossary#1#td7.1":"Unit sederhana Ava untuk biaya per aksi, jadi Anda tidak perlu hitung-hitungan token. Paket langganan sudah termasuk bundel bulanan.","start.glossary#1#td8.0":"Kunci API","start.glossary#1#td8.1":"Kata sandi pribadi yang memungkinkan perangkat lunak menggunakan layanan berbayar (seperti model AI) di akun Anda. Anda hanya butuh satu jika ingin membawa sendiri.","start.glossary#1#td9.0":"BYOK","start.glossary#1#td9.1":"\"Bawa Kunci Sendiri.\" Menggunakan kunci API Anda sendiri alih-alih akses terkelola Ava. Opsional — untuk orang yang sudah membayar penyedia secara langsung.","start.glossary#1#td10.0":"Local-first","start.glossary#1#td10.1":"Data Anda hidup di komputer Anda sendiri secara default. Tidak ada yang diunggah kecuali Anda mengaktifkan sinkronisasi. \"Lokal itu suci.\"","start.glossary#1#td11.0":"Mode izin","start.glossary#1#td11.1":"Seberapa hati-hati Ava sebelum melakukan sesuatu — tanya setiap kali, tanya hanya untuk hal berisiko, atau langsung jalan. Anda yang mengatur tingkatannya.","start.glossary#1#td12.0":"Jendela konteks","start.glossary#1#td12.1":"Berapa banyak teks yang bisa diingat model sekaligus — memori jangka pendeknya. \"Konteks 1M\" berarti sekitar sejuta kata. Lebih besar = bisa membaca lebih banyak sebelum lupa.","start.glossary#1#td13.0":"Diff","start.glossary#1#td13.1":"Tampilan perbedaan sisi-berdampingan dari apa yang akan berubah dalam sebuah file — lama di satu sisi, baru di sisi lain — ditampilkan sebelum Ava mengubah apa pun agar Anda bisa menyetujuinya.","start.glossary#1#td14.0":"Repositori (repo)","start.glossary#1#td14.1":"Folder proyek yang dilacak perubahannya, biasanya dengan Git. Jika itu belum berarti apa-apa bagi Anda, itu hanyalah \"folder tempat proyek saya berada.\"","start.glossary#1#td15.0":"Perintah (Prompt)","start.glossary#1#td15.1":"Apa yang Anda ketik ke AI — pertanyaan atau instruksi Anda.","start.glossary#2#c":"Masih bingung dengan kata tertentu? Tanya Ava di mode Chat — \"apa artinya X?\" — dan dia akan menjelaskannya sesuai level Anda.","models.routing#title":"Routing — bagaimana Ava memilih model","models.routing#0#p":"Ini versi singkatnya: Anda tidak pernah harus memilih model AI mana yang digunakan. Ava yang melakukannya untuk Anda, memilih alat terbaik untuk setiap bagian pekerjaan — seperti manajer baik yang menyerahkan tugas yang tepat kepada orang yang tepat.","models.routing#1#p":"Anda pilih salah satu dari tiga gaya — Maestro, Supernova, atau Aurora — dan Ava mengirim setiap bagian pekerjaan ke model yang menanganinya paling baik. Maestro adalah default, aktif di semua paket, dan pilihan bagus untuk hampir semua orang.","models.routing#2#h":"Mengapa repot-repot melakukan routing?","models.routing#3#p":"Menempatkan model yang tepat pada setiap langkah lebih murah daripada menjalankan semuanya pada satu model besar mahal — dan memberikan hasil lebih baik, karena setiap model melakukan apa yang paling ia kuasai. Anda mendapatkan biaya stabil dan kualitas tinggi tanpa perlu tahu model mana yang mana.","models.routing#4#c":"Ketiga gaya bekerja pada kredit platform dan kunci Anda sendiri. Dengan kunci Anda sendiri, Anda juga bisa melewati routing dan mengendalikan satu model langsung. Rincian armada lengkap ada di bawah \"Tunjukkan detailnya\".","models.routing#deeper#0#c":"Angka \"B\" di bawah ini adalah miliaran parameter — kira-kira seberapa besar otak model; lebih besar biasanya berarti lebih pintar tapi lebih lambat dan lebih mahal. Ini detail teknis di balik layar; Anda tidak pernah memerlukannya untuk menggunakan Ava.","start.first-model#deeper#0#h":"Apa yang sebenarnya ada di setiap gaya","start.first-model#deeper#1#p":"Maestro — satu konduktor (Qwen 3.6 Plus) menangani setiap langkah. Disesuaikan untuk produksi, terbukti, dan biaya yang bisa diprediksi.","start.first-model#deeper#2#p":"Supernova — koordinator terdepan (DeepSeek V4 Pro, 1.6T parameter / 49B aktif, konteks 1M) menyerahkan setiap tugas kecil ke spesialis: V4 Flash untuk pembuatan volume tinggi, Qwen 3.6 Plus sebagai cadangan, Qwen Omni untuk visi.","start.first-model#deeper#3#p":"Aurora — hanya Mistral, dalam tiga tingkatan: Mistral Large 3 (koordinator + spesialis berat), Mistral Medium 3.5 (128B padat, konteks 256K, visi bawaan, bobot terbuka modifikasi-MIT, 77.6% SWE-Bench Verified) untuk pembangun + tingkat menengah + visi + konten panjang, dan Mistral Small 4 di gerbang niat. Bobot terbuka dari awal hingga akhir, tidak pernah keluar dari infrastruktur UE.","start.first-model#deeper#4#h":"Bawa model Anda sendiri (BYOK)","start.first-model#deeper#5#p":"Lebih suka menggunakan akun AI Anda sendiri? Tempelkan kunci penyedia Anda di pengaturan dan Anda mendapatkan keduanya — ketiga gaya pengalihan, plus opsi memilih satu model dan melewatkan pengalihan sepenuhnya. Berguna untuk preferensi kuat, anggaran ketat, atau menguji model tertentu. Daftar lengkap penyedia ada di bagian Referensi.","start.glossary#title":"Glosarium bahasa sederhana","start.glossary#0#p":"Setiap kata yang mungkin Anda temui seputar Ava, dijelaskan tanpa pengetahuan sebelumnya. Anda tidak perlu menghafal ini semua — kembali kapan pun istilah membuat Anda bingung.","start.glossary#1#th0":"Kata","start.glossary#1#th1":"Apa artinya sebenarnya","start.glossary#1#td0.0":"Agen","start.glossary#1#td0.1":"AI yang bisa melakukan tindakan untuk Anda — membaca file, menjalankan perintah, mencari web — bukan sekadar chatting. Ava adalah agen: dia melakukan hal-hal, dengan persetujuan Anda.","start.glossary#1#td1.0":"Model","start.glossary#1#td1.1":"Otak AI sungguhan yang berpikir (Qwen, DeepSeek, Mistral, dan lainnya). Model berbeda memiliki kekuatan berbeda. Biasanya Anda tidak memilih satu pun — Ava yang melakukannya.","start.glossary#1#td2.0":"Mode","start.glossary#1#td2.1":"Pola pikir Ava saat itu. Seperti rekan kerja yang berganti topi: pembangun, penulis, guru, perencana, teman. Anda pilih mode-nya; itu mengubah cara ia bertindak. Ada tujuh.","start.glossary#1#td3.0":"Persona / spesialis","start.glossary#1#td3.1":"Peran bantuan yang dijalankan Ava di balik layar untuk pekerjaan sulit — penjelajah, perencana, pemeriksa fakta. Bayangkan tim ahli kecil. Anda tidak pernah berbicara langsung dengan mereka; Ava yang mengoordinasikannya.","start.glossary#1#td4.0":"Pengalihan","start.glossary#1#td4.1":"Ava memutuskan model mana yang dipakai untuk setiap langkah agar Anda dapat jawaban bagus tanpa membayar berlebihan. Ini terjadi otomatis — \"mode pengalihan\" hanya memilih strategi secara keseluruhan.","start.glossary#1#td5.0":"Alat","start.glossary#1#td5.1":"Tindakan spesifik yang bisa diambil Ava — membaca file, menjalankan pencarian, mengirim email. \"Pemanggilan alat\" adalah saat ia menggunakannya. Ia meminta izin sebelum apa pun yang berisiko.","start.glossary#1#td6.0":"Token","start.glossary#1#td6.1":"Cara AI mengukur teks — kira-kira ¾ dari satu kata. Model dihargai per juta token. Sebagian besar sesuatu yang bisa Anda abaikan.","start.glossary#1#td7.0":"Kredit","models.routing#deeper#2#td5.0":"Obrolan","models.routing#deeper#2#td5.1":"Qwen 3.5 Flash","models.routing#deeper#2#td5.2":"DeepSeek V4 Flash","models.routing#deeper#2#td5.3":"Mistral Small 4","models.routing#deeper#2#td6.0":"Pengaturan pembuatan gambar","models.routing#deeper#2#td6.1":"Qwen 3.5 Flash","models.routing#deeper#2#td6.2":"Qwen 3.5 Omni Flash","models.routing#deeper#2#td6.3":"Mistral Small 4","models.routing#deeper#2#td7.0":"Visual","models.routing#deeper#2#td7.1":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.2":"Qwen 3.5 Omni Plus","models.routing#deeper#2#td7.3":"Mistral Medium 3.5 (pengkode visual yang dilatih dari awal)","models.routing#deeper#2#td8.0":"Penulisan konten panjang","models.routing#deeper#2#td8.1":"Qwen 3.5 Plus","models.routing#deeper#2#td8.2":"Qwen 3.5 Plus","models.routing#deeper#2#td8.3":"Mistral Medium 3.5","models.routing#deeper#2#td9.0":"Lokasi penyimpanan data","models.routing#deeper#2#td9.1":"Campuran (Alibaba Cloud)","models.routing#deeper#2#td9.2":"Campuran (DeepSeek + Alibaba Cloud)","models.routing#deeper#2#td9.3":"Hanya Eropa · bobot terbuka","models.routing#deeper#2#td10.0":"Status","models.routing#deeper#2#td10.1":"Aktif · semua paket","models.routing#deeper#2#td10.2":"Segera hadir","models.routing#deeper#2#td10.3":"Segera hadir","models.routing#deeper#2#td11.0":"Cocok untuk","credits.overview#8#li4":"Orkestrasi — 10 kredit. Memulai alur kerja persona lengkap (Konduktor + tugas multi-persona).","credits.overview#8#li5":"Pembuatan gambar — 12 kredit. Hailuo image-01 melalui Creative Studio.","credits.overview#8#li6":"Pembuatan video — 150 kredit. Klip Hailuo 02 Pro 1080p 6 detik.","credits.overview#8#li7":"Pembuatan suara — 10 kredit. Sintesis Suara 2.8 HD.","credits.overview#8#li8":"Pembuatan musik — 50 kredit. MiniMax Music 2.5/2.6.","credits.overview#8#li9":"Penghapusan latar belakang — 2 kredit.","credits.overview#9#h":"Pengali per model","credits.overview#10#p":"Bagian ini khusus untuk yang penasaran — Anda tidak perlu memahaminya untuk menggunakan Ava. Pengali hanya menyesuaikan biaya kredit naik atau turun tergantung seberapa mahal model di balik suatu tindakan, sehingga model yang lebih berat biayanya sedikit lebih tinggi. (\\\"Margin bersih\\\" adalah bagian yang disimpan proyek setelah membayar tagihan sendiri — kami menargetkannya rendah agar nilai kembali kepada Anda.)","credits.overview#11#p":"Model yang lebih berat mengalikan biaya tindakan agar kredit mencerminkan pengeluaran nyata, bukan sekadar kategori tetap. Dikalibrasi untuk margin bersih sekitar 55%.","credits.overview#12#li0":"0.6× — Mistral Small 4 (kursi spesialis Aurora). Di bawah 1× karena Mistral Small 4 lebih murah daripada patokan Qwen 3.6 Plus.","credits.overview#12#li1":"1.0× — Qwen 3.5 Flash, Qwen Omni Flash, DeepSeek V4 Flash, MiniMax. Tarif dasar.","credits.overview#12#li2":"1.2× — Qwen 3.5 Plus, Qwen 3.5 Omni Plus.","credits.overview#12#li3":"1.4× — Mistral Large 3 (koordinator Aurora). Sekitar setara dengan patokan Qwen 3.6 Plus.","credits.overview#12#li4":"1.5× — Qwen 3.6 Plus (koordinator Maestro).","credits.overview#12#li5":"6.0× — DeepSeek V4 Pro (koordinator Supernova + spesialis berat). Dikalkibrasi ulang dari 5.0× untuk mengembalikan kesetaraan margin pada tarif V4 Pro yang diterbitkan.","credits.overview#13#c":"Model Anthropic (Claude Opus / Sonnet / Haiku) sepenuhnya dilewati penagihan kredit — mereka hanya tersedia via BYOK dan Anda membayar Anthropic langsung. Sama berlaku untuk penyedia BYOK lainnya saat digunakan dengan kunci Anda sendiri.","credits.overview#14#h":"BYOK dan kredit","credits.overview#15#p":"BYOK (\\\"bawa kunci Anda sendiri\\\" — Anda menyediakan akun Anda sendiri ke penyedia AI dan sebuah kunci, yaitu kata sandi pribadi yang memungkinkan perangkat lunak menggunakan akun berbayar tersebut) ditujukan bagi orang yang sudah membayar penyedia AI secara langsung. Jika itu bukan Anda, Anda dapat mengabaikan bagian ini sepenuhnya.","credits.overview#16#p":"Permintaan bawa-kunci-sendiri melewati infrastruktur platform sepenuhnya — panggilan langsung dari Ava ke penyedia, Anda membayar penyedia, tanpa kredit yang terpakai. Satu-satunya pengecualian adalah ketika sesi BYOK memicu persona tingkat terkelola untuk tugas bawahan; pengurangan kredit tetap berlaku karena layanan orkestrasi Ava sedang digunakan.","credits.overview#17#h":"Tempat memeriksa saldo Anda","credits.overview#18#li0":"Ekstensi — Pengaturan → Akun, atau pil kredit di header obrolan.","credits.overview#18#li1":"IDE — Kartu dasbor Akun menampilkan saldo saat ini dan laju pemakaian.","credits.overview#18#li2":"Web — ava-supernova.com/dashboard menampilkan saldo, riwayat, dan tanggal perpanjangan.","credits.overview#19#c":"Lokal-pertama: Ava bekerja tanpa akun pada kartu Model Kustom (Ollama, LM Studio, vLLM, atau endpoint kompatibel OpenAI apa pun). Tanpa kredit, tanpa token platform — model Anda, mesin Anda, tagihan Anda menjadi nol.","concepts.modes#title":"Mode — keadaan pikiran Ava","concepts.desktop-safety#3#li2":"Perubahan yang dapat dibatalkan — ketik di kolom, tempel, buka aplikasi, buka tautan. Meminta konfirmasi dalam mode Tanya; otomatis di Drive jika ada dalam daftar izin.","concepts.desktop-safety#3#li3":"Perubahan yang tidak dapat dibatalkan — kirim, ajukan, bayar, hapus, konfirmasi, terbitkan. Selalu meminta konfirmasi, terlepas dari tingkat izin. Persetujuan tidak pernah disimpan sementara.","concepts.desktop-safety#3#li4":"Izin Khusus — kenaikan hak akses UAC, sudo, edit registri, permintaan kredensial. Dilarang secara bawaan. Perlu persetujuan sekali pakai untuk setiap sesi.","concepts.desktop-safety#4#h":"Persetujuan yang Tidak Pernah Disimpan Sementara","concepts.desktop-safety#5#p":"Setiap kompetitor menyimpan persetujuan (mengingat jawaban \"ya\" Anda dan menggunakannya lagi lain kali). Ini adalah celah terbesar untuk injeksi prompt — serangan di mana halaman web berjebakan menyelipkan instruksi tersembunyi ke AI agar bertindak melawan Anda. Jika persetujuan disimpan, halaman yang sudah diretas bisa menumpang pada \"ya\" yang Anda berikan sebelumnya. Ava tidak pernah menyimpan. Setiap perubahan yang tidak dapat dibatalkan akan bertanya ulang.","concepts.desktop-safety#6#h":"Penanganan Data Rahasia","concepts.desktop-safety#7#p":"Kata sandi, kunci API, dan kode 2FA (kode satu kali yang diberikan aplikasi lain atau pesan teks saat Anda masuk) ditangani melalui penanda aman — tempat penampung yang mewakili nilai asli. Ava hanya melihat \"{secret}\", bukan kata sandi sebenarnya. Nilai asli tidak pernah masuk ke memorinya, log aktivitasnya, atau apa yang dia \"baca\". Lapisan dasar terpisah mengetikkannya di detik terakhir, tepat saat tombol ditekan, sehingga bagian AI tidak pernah menyentuhnya langsung.","reference.cli#title":"Perintah CLI","reference.cli#0#p":"Halaman ini untuk CLI — versi Ava yang Anda gunakan dengan mengetik di jendela terminal, alih-alih mengklik tombol. Jika Anda menggunakan ekstensi atau aplikasi desktop, Anda bisa melewatinya sepenuhnya. Halaman ini tersedia bagi mereka yang lebih menyukai keyboard.","reference.cli#1#p":"CLI adalah REPL — antarmuka yang menunggu Anda mengetik, menjalankan apa yang diketik, lalu menunggu lagi. Perintah garis miring ini (instruksi yang dimulai dengan \"/\") berfungsi dari antarmuka tersebut.","reference.cli#2#li0":"/help — daftar perintah dan mode saat ini.","reference.cli#2#li1":"/mode <nama> — ganti mode (kerja, tulis, rencana, obrolan, ajar, keamanan, curah pendapat).","reference.cli#2#li2":"/model <id> — ganti model tanpa meninggalkan sesi.","reference.cli#2#li3":"/clear — bersihkan percakapan saat ini. Memori tetap utuh.","reference.cli#2#li4":"/history — daftar percakapan masa lalu dalam proyek ini.","reference.cli#2#li5":"/memory — buka penjelajah memori.","reference.cli#2#li6":"/tasks — daftar dan kelola tugas.","reference.cli#2#li7":"/journal — buka entri jurnal hari ini.","reference.cli#2#li8":"/settings — buka menu pengaturan.","reference.cli#2#li9":"/exit — keluar dari REPL.","reference.cli#3#h":"Opsi peluncuran","reference.cli#4#p":"Opsi adalah pilihan tambahan yang Anda tambahkan saat memulai Ava, masing-masing dimulai dengan \"--\", untuk mengatur cara Ava dijalankan.","reference.cli#5#li0":"--mode <nama> — mulai dalam mode tertentu.","reference.cli#5#li1":"--model <id> — mulai dengan model tertentu.","reference.cli#5#li2":"--permission <mode> — ketat / seimbang / otonom.","reference.cli#5#li3":"--project <path> — tetapkan akar proyek secara eksplisit.","reference.desktop-budget#title":"Batas anggaran Desktop","reference.desktop-budget#0#p":"Saat Ava mengendalikan desktop Anda — mengklik, mengetik, membuka aplikasi — setiap eksekusi disebut sebagai \"jalur\". Halaman ini menjelaskan batas keamanan yang mencegah satu jalur berjalan terlalu lama atau menghabiskan biaya terlalu banyak. Poin utamanya: dia selalu berhenti dan memeriksa kembali sebelum melebihi batas. Angka-angkanya ada di sini jika Anda ingin detailnya.","reference.desktop-budget#1#p":"Setiap jalur berjalan di bawah tiga batas sekaligus (batas keras). Yang pertama tercapai akan menang. Jalur tidak pernah diam-diam melanjutkan setelah pelanggaran — Narator (asisten yang menjelaskan apa yang terjadi kepada Anda) akan menjeda dan bertanya apa yang harus dilakukan.","reference.desktop-budget#2#h":"Tiga batas keras (bawaan)","reference.desktop-budget#3#li0":"Jumlah langkah — 30 langkah","reference.desktop-budget#3#li1":"Anggaran token — 500.000 token","reference.desktop-budget#3#li2":"Waktu nyata — 5 menit","reference.desktop-budget#4#h":"Rentang biaya tugas","reference.desktop-budget#5#li0":"Sederhana (cari dokumen, buka halaman) — 5–10 langkah, ~70–135K token, ~$0,04–0,08","reference.desktop-budget#5#li1":"Sedang (masuk, periksa log, unduh hasil) — 15–25 langkah, ~205–340K token, ~$0,12–0,21","reference.desktop-budget#5#li2":"Kompleks (triase tiga masalah GitHub) — 25–30 langkah, ~340–410K token, ~$0,21–0,25","reference.desktop-budget#6#p":"Angka token di atas adalah batas teknis per-jalur, bukan jatah bulanan Anda — itu dihitung dalam kredit, dan versi gratis dengan 300 per bulan cukup nyaman untuk campuran obrolan, kode, dan beberapa otomatisasi.","reference.desktop-budget#7#c":"Anda dapat menimpa batas per-tugas saat memulai, tetapi pelanggaran selalu muncul sebagai titik keputusan. Anggaran tidak pernah habis tanpa pemberitahuan.","reference.desktop-whitelist#title":"Daftar putih sesi Desktop","reference.desktop-whitelist#0#p":"\"Daftar putih\" hanyalah daftar aplikasi dan situs web yang telah Anda katakan Ava boleh sentuh saat mengendalikan desktop Anda. Halaman ini menjelaskan bagaimana Anda memberikan izin itu dan mengapa itu reset setiap kali. Versi singkatnya: dia hanya bisa bertindak di tempat yang Anda izinkan, dan dia bertanya sebelum pergi ke mana pun yang baru.","reference.desktop-whitelist#1#p":"Di awal sesi desktop, Ava bertanya di mana dia diizinkan bertindak. Bahasa sederhana sudah cukup: \"Gmail, Cursor, portal Azure.\" Dia membacanya dan mengonfirmasi kecocokannya kembali kepada Anda (\"Gmail web, Cursor aplikasi, portal.azure.com\").","reference.desktop-whitelist#2#h":"Cara penegakannya","reference.desktop-whitelist#3#p":"Tindakan hanya melihat — mengambil tangkapan layar, membaca daftar tombol dan bidang di layar (\"pohon UIA\", peta bawaan Windows tentang apa yang ada di jendela) — diizinkan di mana saja, karena Anda perlu melihat apa yang ada di layar untuk memutuskan apakah akan menambahkan aplikasi ke daftar putih. Apa pun yang mengubah sesuatu diblokir di luar daftar; Ava menjeda dan bertanya apakah akan menambahkannya.","reference.desktop-whitelist#4#h":"Dibatasi sesi, disengaja","reference.desktop-whitelist#5#p":"Daftar putih TIDAK bertahan melintasi sesi. Tidak ada opsi \"ingat aplikasi ini\". Setiap jalur baru dimulai dengan cakupan segar. Tidak nyaman oleh desain — lupa mengotorisasi ulang adalah fitur, bukan bug.","reference.desktop-whitelist#6#h":"Penambahan di tengah jalur","reference.desktop-whitelist#7#p":"Selama sebuah jalur, Anda dapat menambahkan aplikasi dari bagian header: \"+ Izinkan aplikasi\" membuka input kecil. Ketuk Tambahkan dan aplikasi baru langsung aktif untuk sisa sesi.","features.creative-studio#title":"Creative Studio","features.creative-studio#0#p":"Ingin membuat gambar, video pendek, lagu, atau suara narasi? Cukup deskripsikan dan Ava membuatnya untuk Anda — tidak perlu perangkat lunak desain atau audio.","models.routing#deeper#2#td11.1":"Pekerjaan harian, biaya yang dapat diprediksi","models.routing#deeper#2#td11.2":"Pekerjaan berat multi-langkah, koordinator terdepan di setiap paket","models.routing#deeper#2#td11.3":"Patuh ketat GDPR, sektor publik, tumpukan berdaulat UE","models.routing#deeper#3#h":"Maestro","models.routing#deeper#4#p":"Routing Qwen terdiferensiasi tier dengan jejak ringan. Qwen 3.6 Plus memegang peran koordinator, Pembangun, perencanaan, keamanan, curah ide, dan kerja konteks panjang — tempat di mana perhatian linear hibrida 1M-konteksnya memberikan hasil. Qwen 3.5 Flash menangani obrolan, orkestrasi generasi gambar, dan gerbang niat hulu, di mana harga $0.07/$0.26 dan waktu hingga respons pertama yang lebih cepat menang pada sebagian besar volume token kedalaman rendah. Qwen 3.5 Omni Plus memegang masukan visi (Qwen 3.6 Plus tidak memiliki visi asli). Qwen 3.5 Plus menangani kerja bentuk panjang yang sensitif biaya. Sistem turun ke tangga prioritas Qwen 3.6 Plus → 3.5 Plus → 3.5 Flash jika koordinator utama tidak tersedia.","models.routing#deeper#5#h":"Supernova","models.routing#deeper#6#p":"Ensemble poliglot. DeepSeek V4 Pro mengoordinasikan dan menugaskan setiap sub-tugas ke spesialis terbaik: Qwen 3.6 Plus menjalankan setiap munculan Pembangun, V4 Flash menangani obrolan plus persona tinjauan/audit tingkat menengah, Qwen 3.5 Flash menyerap kerja klasifikasi tingkat ringan, Qwen 3.5 Omni Plus memegang masukan visi, Qwen 3.5 Omni Flash mengorkestrasi panggilan alat generasi gambar, Qwen 3.5 Plus menangani persona Penulis Konten yang sensitif biaya. Penalaran terdepan di tempat yang penting, ekonomi tier Flash pada sebagian besar volume token.","models.routing#deeper#7#h":"Aurora","models.routing#deeper#8#p":"Tumpukan AI Eropa — berdaulat sejak desain. Routing hanya Mistral dalam tiga tier: Mistral Large 3 (675B/41B aktif MoE sparse) menangani peran koordinator plus spesialis berat yang butuh kedalaman — Peneliti, Penantang, Peneliti CVE, Pemikir, Pemeriksa Fakta, Pengecek Keamanan — dan pekerjaan dasar konteks panjang di mana efisiensi MoE sparse menang. Mistral Medium 3.5 — produk unggulan gabungan dirilis April 2026, 128B padat, konteks 256K, encoder visi dilatih dari awal, bobot terbuka MIT yang dimodifikasi, 77.6% SWE-Bench Verified — menjalankan tier kerja aktual: munculan Pembangun, spesialis tingkat menengah (Arsitek, Pengecek, Pengurut, Tutor, Pelapor), masukan visi, dan tulisan bentuk panjang. Mistral Small 4 diperluas dari satu peran di gerbang niat juga menangani obrolan dan orkestrasi generasi gambar — harga $0.15/$0.60 dan penalaran yang dapat dikonfigurasi mempertahankan posisinya pada rute volume tinggi kedalaman rendah. Bobot terbuka ujung ke ujung, tidak pernah meninggalkan infrastruktur UE. Aurora sengaja tidak melakukan rute silang diam-diam ke model non-Mistral saat salah satu tidak tersedia; router menampilkan kesalahan — itulah yang membuatnya \"Aurora\" daripada Maestro rasa Mistral.","credits.overview#title":"Kredit Ava — cara penagihan bekerja","credits.overview#0#p":"Kredit hanyalah cara Ava menghitung apa yang Anda gunakan — seperti menit pada paket telepon. Setiap paket, termasuk yang gratis, datang dengan kolam kredit, dan setiap hal yang Ava lakukan (menjawab Anda, membuat gambar) memakan sejumlah kecil kredit. Itu saja idenya. Detail di bawah ini untuk ketika Anda ingin tahu persis apa yang dikenakan biaya.","credits.overview#1#p":"Ava menagih dalam kredit, bukan token mentah. (\"Token\" adalah potongan kecil teks — sekitar beberapa huruf — yang dibaca dan ditulis oleh model AI; kebanyakan layanan mengenakan biaya per token, yang sulit diprediksi.) Satu kredit mencakup satu unit pekerjaan — putaran obrolan, munculan persona (satu pembantu mengerjakan bagian tugas), generasi gambar. Memisahkan dari pengukuran berbasis token berarti Anda tidak perlu tahu model mana yang berjalan untuk mengetahui biaya suatu tindakan. Putaran obrolan yang sama biayanya sama apakah Maestro mengarahkannya ke Qwen 3.6 Plus atau Supernova mengarahkannya ke V4 Pro.","credits.overview#2#h":"Paket","credits.overview#3#p":"Setiap paket memiliki akses ke setiap fitur — akses model, Creative Studio, semua tujuh mode, orkestrasi persona penuh. Tier yang lebih tinggi membeli lebih banyak kredit dan batas atas laju permintaan yang lebih tinggi, bukan fitur yang dibuka.","credits.overview#4#li0":"Gratis — $0/bulan. 300 kredit. Batas 20 permintaan/menit. Tidak memerlukan kartu.","credits.overview#4#li1":"Pro — $19/bulan. 5,000 kredit. 60 permintaan/menit.","credits.overview#4#li2":"Ultra — $39/bulan. 10,000 kredit. 120 permintaan/menit.","credits.overview#4#li3":"Enterprise — $79/bulan. 20,000 kredit. 200 permintaan/menit.","credits.overview#5#c":"Kredit yang tidak terpakai digulirkan selama berlangganan aktif — tidak ada pengambilan paksa. Tambahan ditumpuk pada kolam langganan: 750 kredit untuk $3, 2,000 untuk $8, 4,000 untuk $15.","credits.overview#6#h":"Biaya berbagai hal","credits.overview#7#p":"Tabel biaya per tindakan — apa yang dikurangi dari kolam kredit Anda saat setiap tindakan berjalan. (\"Cache hit\" adalah ketika Ava menggunakan kembali pekerjaan yang sudah dilakukan alih-alih mengulanginya; saat itu terjadi Anda bayar lebih sedikit — biaya turun 70%, atau 50% pada model yang banyak output seperti DeepSeek V4 Pro.)","credits.overview#8#li0":"Putaran obrolan — 2 kredit. Satu bolak-balik dalam mode apa pun.","credits.overview#8#li1":"Panggilan ringan — 1 kredit. Gerbang niat, klasifikasi, bacaan tunggal.","credits.overview#8#li2":"Persona berat — 3 kredit. Arsitek, Peneliti, Peneliti CVE, Pemikir (kedalaman ≥ 4).","credits.overview#8#li3":"Persona ringan — 1 kredit. Pengintai, Pengecek, Pengurut, Penantang (kedalaman ≤ 2).","concepts.modes#0#p":"Mode adalah cara berpikir yang dipakai Ava — seperti rekan kerja yang berganti topi. Orang yang sama, memori tentang Anda tetap sama, tapi seorang pembangun berpikir berbeda dari seorang guru. Anda pilih modenya dan itu mengubah cara dia berperilaku serta asisten mana yang dia bawa. Ganti kapan saja dengan pemilih mode, atau ketik pintasan dua karakter.","concepts.modes#2#h":"Mana yang Anda inginkan?","concepts.modes#3#p":"Mulailah dari apa yang ingin Anda lakukan — mode mengikuti hal tersebut:","concepts.modes#4#li0":"Saya ingin sesuatu dibangun atau diubah → Kode (>>). Anda jelaskan, dia bangun, menunjukkan setiap perubahan dulu. Tim bantuan lengkap aktif untuk pekerjaan besar.","concepts.modes#4#li1":"Saya ingin rencana sebelum ada perubahan → Rencana (::). Dia pikirkan matang-matang dan berikan Anda rencana untuk disetujui atau diedit. Dia tidak akan menyentuh file Anda dalam mode ini.","concepts.modes#4#li2":"Saya hanya ingin bicara atau bertanya → Obrolan (..). Mitra berpikir dengan memori, berita, dan cuaca. Tidak ada perubahan file, tidak ada kode — hanya percakapan.","concepts.modes#4#li3":"Saya ingin belajar sesuatu → Ajarkan (??). Kursus nyata yang dibuat untuk Anda: pelajaran, kuis, semuanya. Gratis di semua paket, selamanya. Sempurna jika Anda baru.","concepts.modes#4#li4":"Saya ingin proyek saya dicek celah keamanan → Keamanan (!!). Tim bekerja melalui daftar standar kerentanan web umum (kategori \"OWASP\") dan cacat yang dilaporkan (disebut \"CVEs\"), lalu berikan laporan yang diurutkan berdasarkan tingkat seriusnya masalah. Ini ditujukan untuk pengembang — lewatkan jika Anda bukan pengembang.","concepts.modes#4#li5":"Saya ingin ide → Curah Pikir (**). Dia usulkan opsi berdasarkan situasi Anda, kritik yang lemah, dan perbaiki sisanya jadi langkah selanjutnya.","concepts.modes#4#li6":"Saya ingin menulis dokumen → Tulis (<<). Laporan, proposal, surat, artikel — dia buat draf dalam Markdown dan ekspor dokumen Word atau PDF bermerek, menyempurnakan bagian demi bagian. Tidak ada kode, hanya menulis.","concepts.modes#5#c":"Tim \"bantuan\" (persona) berjalan sepenuhnya di belakang layar — Anda tidak pernah berbicara langsung dengan mereka. Anda hanya mendapatkan jawaban yang lebih menyeluruh. Anda tidak perlu tahu nama mereka.","concepts.modes#6#c":"Anda bisa ganti mode tengah percakapan. Memori Anda terbawa; spesialisnya direset agar sesuai mode baru.","concepts.tasks-journal#title":"Tugas dan jurnal","concepts.tasks-journal#0#p":"Ava menyimpan tiga jenis catatan untuk Anda, dan mudah tercampur. Cara cepat mengingat: memori adalah apa yang dia tahu tentang Anda, tugas adalah apa yang masih harus Anda lakukan, dan jurnal adalah buku harian bagaimana jalannya hal-hal. Berikut kapan menggunakannya.","concepts.tasks-journal#1#li0":"Memori — fakta permanen. Preferensi, keputusan, pola. Ditanyakan berulang kali, jarang dibuat manual.","concepts.tasks-journal#1#li1":"Tugas — hal yang harus dilakukan. Item aksi dengan tanggal jatuh tempo dan status. Anda centang saat selesai.","concepts.tasks-journal#1#li2":"Jurnal — refleksi. Log harian, entri ganda (milik Anda dan observasi Ava tentang sesi). Berguna untuk pelacakan suasana hati, tinjauan sesi, konteks untuk besok.","concepts.tasks-journal#2#p":"Ava menulis ke ketiga tempat saat masuk akal. Anda bisa menulis ke salah satunya langsung dari dasbor. Tidak ada yang terkunci di satu tempat Anda pakai Ava — tugas yang Anda buat di satu tempat (misalnya alat baris perintah) muncul di tempat lain (seperti aplikasi desktop), secara otomatis.","concepts.permissions#title":"Izin — kenop keselamatan Anda","concepts.permissions#0#p":"Izin adalah kenop keselamatan Anda. Mereka memutuskan kapan Ava meminta izin Anda sebelum melakukan sesuatu di komputer Anda, versus langsung melakukannya. Anda bisa atur dia untuk tanya segalanya, tanya hal berisiko saja, atau percayai dia menjalankan — dan Anda bisa ubah kapan saja. Jika ragu, biarkan di pengaturan bawaan dan Anda aman.","concepts.permissions#1#p":"Ava punya 60 alat (\"alat\" adalah tindakan yang bisa dia ambil — membaca file, mencari web, dan seterusnya). Setiap alat milik kategori (operasi file, shell, Git, web, media, database, sistem, dokumen, memori, pembelajaran). Setiap panggilan alat melewati gerbang izin (titik pemeriksaan yang memutuskan apakah minta Anda dulu) sebelum jalan. Anda kontrol apa yang disetujui otomatis, apa yang tanya sekali, dan apa yang selalu tanya.","concepts.permissions#3#p":"Seimbang adalah pilihan bawaan. Ketat saat Anda mengaudit perilakunya (mengamati ketat cek setiap langkah). Otonom saat Anda ingin dia langsung bekerja.","concepts.permissions#4#c":"Otonom tidak berarti tanpa pengawasan. Rencana, pertanyaan klarifikasi, dan permintaan eksplisit minta pengguna masih jeda untuk input Anda. Operasi tak dapat dibatalkan (Git force-push, penghapusan database) selalu konfirmasi terlepas dari mode.","concepts.interjection#title":"Mengarahkan dan menghentikan Ava","concepts.interjection#0#p":"Anda selalu memegang kendali. Saat Ava sibuk bekerja, Anda bisa dorong dia ke arah baru tanpa merusak langkahnya, atau hentikan seketika. Dua tombol, dua hasil — itu saja halaman ini bahas.","concepts.interjection#1#p":"Ava akan terus bekerja hingga rencana selesainya atau Anda menghentikannya. Ada dua cara untuk masuk campur (kata untuk ini adalah \"intervensi\") saat dia sedang berjalan.","concepts.interjection#2#h":"Intervensi — kendalikan tanpa membatalkan","concepts.interjection#3#p":"Ketik pesan baru saat Ava sedang bekerja. Dia menyelesaikan panggilan alat saat ini, membaca pesan Anda, dan menyesuaikan rencananya. Tidak ada konteks yang hilang. Gunakan ini saat Anda ingin mengalihkan arah, menambah informasi, atau mengubah prioritas di tengah jalan.","concepts.interjection#4#h":"Hentikan Paksa — batalkan dan bersihkan","concepts.interjection#5#p":"Tekan Escape (CLI), klik Stop (ekstensi, IDE), atau ketik perintah berhenti. Proses berjalan saat ini dibatalkan, panggilan alat yang menunggu dilepas, dan percakapan siap untuk langkah baru.","concepts.interjection#6#c":"Intervensi dulu. Hentikan Paksa hanya jika memang ada kesalahan serius. Intervensi menjaga percakapan tetap hidup.","concepts.desktop-personas#title":"Persona Desktop","concepts.desktop-personas#0#p":"Halaman ini untuk yang penasaran dan pengguna tingkat lanjut. \"Otomasi Desktop\" (kadang disebut \"penggunaan komputer\") berarti Ava benar-benar bisa mengklik layar Anda dan menggunakan aplikasi untuk Anda — buka Gmail, isi formulir, kirim pesan — seperti orang di depan keyboard. Untuk melakukannya dengan aman, dia membagi pekerjaan ke lima pembantu kecil, masing-masing dengan satu peran sempit. Anda tidak pernah berurusan langsung dengan mereka; ini hanya menunjukkan siapa mengerjakan apa.","concepts.desktop-personas#1#p":"Setiap langkah dalam lintasan desktop (satu kali Ava menggerakkan layar Anda menuju tujuan) melibatkan gelombang lima persona. Setiap persona memiliki satu tugas saja. Pemisahan ini menjaga instruksi tetap fokus, output terstruktur, dan penalaran kritis sesuai rancangan.","concepts.desktop-personas#2#h":"Pengintai","concepts.desktop-personas#3#p":"Melaporkan apa yang terlihat di layar saat ini. Tidak pernah mengarang elemen. Tidak pernah merencanakan. Mengembalikan ScreenState JSON berisi ID elemen, nama, bboxes, tingkat kepercayaan, dan sumber referensi (UIA, Playwright DOM, atau visi OmniParser).","concepts.desktop-personas#4#h":"Perencana","concepts.desktop-personas#5#p":"Memutuskan satu tindakan selanjutnya. Satu tindakan per langkah — tidak pernah digabung. Lebih memilih jalur yang bisa dibatalkan. Mengklasifikasikan risiko sesuai ontologi keamanan. Menghasilkan ProposedAction JSON berisi jenis, target, parameter, riskClass, alasan, dan prediksi expectedPostState.","concepts.desktop-personas#6#h":"Pelaksana","concepts.desktop-personas#7#p":"Menjalankan persis apa yang diusulkan Perencana — setelah gerbang persetujuan terbuka. Tidak ada improvisasi. Tidak ada coba ulang. Kegagalan dilaporkan dengan setia dan Verifier menangani langkah selanjutnya.","concepts.desktop-personas#8#h":"Pengecek","concepts.desktop-personas#9#p":"Memeriksa apakah tindakan berhasil. Membandingkan ScreenState baru dengan prediksi Perencana. Mengembalikan verified, deviated, atau rollback_needed. Juga menjalankan deteksi loop — mengulang tindakan yang sudah berhasil adalah penyimpangan, bukan verifikasi.","concepts.desktop-personas#10#h":"Narator","concepts.desktop-personas#11#p":"Satu-satunya suara yang didengar pengguna selama lintasan. Satu kalimat lampau per langkah (\"Membuka Gmail.\", \"Mengklik Compose.\"). Juga menulis log audit terstruktur. Berkata ketika ada masalah — tidak pernah menyembunyikan masalah.","concepts.desktop-safety#title":"Ontologi Keamanan Desktop","concepts.desktop-safety#0#p":"Singkatnya: sebelum Ava mengklik apa pun di layar Anda, dia mengurutkan tindakan berdasarkan risikonya. Membaca layar? Tidak berbahaya. Mengirim uang atau menghapus sesuatu? Dia selalu berhenti dan bertanya pada Anda terlebih dahulu — setiap saat, tanpa pengecualian. Lima label di bawah ini hanyalah anak tangga pada tangga risiko itu. Ini detail pengguna tingkat lanjut, tetapi intinya sederhana: hal berbahaya selalu butuh izin Anda.","concepts.desktop-safety#1#p":"Setiap tindakan yang diusulkan diklasifikasikan ke salah satu dari lima kelas risiko. Klasifikasi menggabungkan tiga sinyal — apa target di layar, deskripsi bahasa sederhana (\"caption semantik\" — kata-kata Ava sendiri tentang apa yang dilihatnya), dan pengaturan tindakan — serta ditingkatkan (diperlakukan lebih berisiko) jika terjadi ketidaksesuaian. Positif palsu (bertanya padahal tidak perlu) hanya sekadar mengganggu. Negatif palsu (tidak bertanya padahal seharusnya) adalah insiden fatal bagi produk.","concepts.desktop-safety#2#h":"Lima kelas","concepts.desktop-safety#3#li0":"Observasional — baca pohon UIA, tangkapan layar, hover. Selalu otomatis diizinkan.","concepts.desktop-safety#3#li1":"Navigasional — gulir, pindahkan fokus, buka menu. Otomatis diizinkan dalam Mode Drive.","features.creative-studio#1#p":"Pembuatan gambar, video, musik, dan suara — terintegrasi langsung dalam alur kerja kode Anda. Buat ikon, mockup produk, video demo, atau narasi untuk tutorial. Ditenagai oleh MiniMax.","features.creative-studio#2#h":"Apa yang bisa Anda buat","features.creative-studio#3#li0":"Gambar — dari prompt ke PNG/JPG. Penghapusan latar belakang hanya satu perintah.","features.creative-studio#3#li1":"Video — video AI pendek dari prompt teks (MiniMax Hailuo).","features.creative-studio#3#li2":"Musik — trek instrumental atau vokal dengan lirik.","features.creative-studio#3#li3":"Suara — teks-ke-suara dengan pilihan pengisi suara.","features.creative-studio#4#p":"Biaya Creative Studio diambil dari kolam kredit yang sama dengan lainnya — satu kolam, satu angka. Gunakan kunci MiniMax Anda sendiri (BYOK) dan biaya ini gratis untuk paket Anda.","features.creative-studio#5#c":"Creative Studio memenuhi syarat untuk paket gratis. Bukan tambahan berbayar.","features.desktop-automation#title":"Otomasi Desktop","features.desktop-automation#0#p":"Secara sederhana: Ava dapat mengambil alih mouse dan keyboard Anda untuk melakukan tugas — membuka aplikasi, mengklik tombol, mengisi formulir — sementara Anda menonton dan menyetujui hal-hal penting.","features.desktop-automation#1#p":"Mode baru untuk Ava, awalan @@. Dia mengamati desktop, memutuskan apa yang harus dilakukan, dan menjalankan otomasi UI (mengendalikan aplikasi di layar Anda) hingga selesai. Berjalan di mesin asli Anda dengan kredensial asli Anda — bukan browser cloud. Tersedia di setiap paket setelah dirilis.","features.desktop-automation#2#h":"Mengapa lagi satu?","features.desktop-automation#3#p":"Setiap produk otomasi desktop lain adalah sesuatu yang Anda mulai saat berada di meja kerja. Ava adalah yang tetap ada ketika pelacak error Anda berbunyi jam 2 pagi — IDE terus berjalan, ponsel Anda terhubung melalui saluran aman, Anda menyetujui tindakan yang tidak bisa dibatalkan dengan satu ketukan.","features.desktop-automation#4#p":"Dia juga mengingat cara menavigasi aplikasi Anda antar sesi. Agen lain harus belajar ulang setiap kali. Pembeda memori ini semakin kuat seiring penggunaan.","features.desktop-automation#5#h":"Cara kerjanya","features.desktop-automation#6#p":"Setiap langkah menjalankan gelombang lima persona: Scout mengamati, Planner memilih tindakan berikutnya, Actor mengeksekusi, Verifier memeriksa, Narrator memberi tahu Anda apa yang terjadi. Sidecar memilih landasan paling murah dan andal — UIA untuk aplikasi native, Playwright untuk browser, visi OmniParser ketika tidak ada yang memiliki pohon berguna.","features.desktop-automation#7#p":"Lihat halaman konsep untuk ontologi keamanan, hierarki landasan, sakelar darurat, dan model daftar putih sesi."}};
